INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onarım', 'onarim-funda-soylemez-apv57', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanı yırtıp gittin

Devam eden zaman sensiz akıyor

Yırtıktan geçip peşine düşerim sanmıştın ya,

Haberin olsun diye söylüyorum

Arkandan yırtığı diktim

İzi bile belli olmuyor

Yani benim zamanıma

İstesen de giremezsin bir daha

(Mayıs 2005)', 'Zamanı yırtıp gittin Devam eden zaman sensiz akıyor Yırtıktan geçip peşine düşerim sanmıştın ya, Haberin olsun diye söylüyorum Arkandan yırt...', ARRAY['Türk Edebiyatı','Şiir','Funda Söylemez']::text[], 8.5, '{"poet":"Funda Söylemez","poet_slug":"funda-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/onarim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deneme', 'deneme-songul-ucar-8rh94', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'B azen zaman durur,

U mursamaz hiçbir şeyi.

B azense su misali,

İ nsafsızca akıp gider...

R ücu etmez ölüm gibi.

D ünya an-da bir mekan.

E n güzel nimetler hep onda! 

N asıl olsa geçer zaman,

E bedi ne var hayatta? 

M adem ölüm kapıda,

E cel en yakın yoldaşın,

D urma eğlen sızlanmadan,

İ ste ne varsa aklında! 

R am etme sakın almadan.

 :)', 'B azen zaman durur, U mursamaz hiçbir şeyi. B azense su misali, İ nsafsızca akıp gider... R ücu etmez ölüm gibi. D ünya an-da bir mekan. E n...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/deneme-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Paylaş Benimle', 'paylas-benimle-nurten-altinok-n8a8l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En büyük fırtınalar hortumudur sessizliğin

Kulakpatlatan

İnme gibi iner sorular düğümgecelerimize arapsaçı

Çöz, çözebilirsen formülünü aşkın

Çöz

Çözülebiliyor musun

Çözülebiliyorsan 

Düş sesime yangınkıranım

Yeniden alev alsın muştumavi yüreğimin gönderinde

Varsın

Böylesine vurdumduymaz olsun yaramız

Varsın 

Böylesine pembe olsun yalanımız

Yapabilirsen 

Yap

Yapabiliyor musun

Yapabiliyorsan 

Çık gözkamaştıran güneşin ardından 

Saklandığın duygu denizinin poyrazlarından

Buğulu bir mehtapmavisidir sana sunacağım 

Bakışlarımdaki yosunyeşilinden armağan

Ya da adına ne dersen de 

Mutluluk rengi gibi bir şey olur işte

Bilebilirsen 

Bil 

Bilebiliyor musun

Biliyorsan

En büyük sessizliğin fırtına çığlığını

Paylaş benimle sesini 

Paylaş benimle nefesini

Paylaşabilirsen 

Paylaşabiliyor musun! ..', 'En büyük fırtınalar hortumudur sessizliğin Kulakpatlatan İnme gibi iner sorular düğümgecelerimize arapsaçı Çöz, çözebilirsen formülünü aşkın...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/paylas-benimle-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Hatırlanmaz Hatırlatır', 'dost-hatirlanmaz-hatirlatir-adulera-ayza-b3w7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer benim dostum isen hatırlanma hatırlat

Bana kim olduğumu değil ne olduğumu anlat

Ben zaten biliyorum kim olduğumu 

Önemli olan arada bir de olsa senin yanındaki değerimi anımsat

Dost altın kadar değerli zümrüt kadar bulunmaz olmalı

Dostum dediğim insan iyi günümde değil zor günümde yanımda kalmalı

Sana dostum diyorsan eğer

Sana bunu demeye değer

Bunu bana lütfen bana dedirtme

Senide dost sanmışım meğer', 'Eğer benim dostum isen hatırlanma hatırlat Bana kim olduğumu değil ne olduğumu anlat Ben zaten biliyorum kim olduğumu  Önemli olan arada bir...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dost-hatirlanmaz-hatirlatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsaf Nerdesin', 'i-nsaf-nerdesin-kadir-kaya-w1kz1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalpdeki sevgiyi büyüten şefkat,

Çilemi görüyor, insaf nerdesin.

Hakkın kapısında vefaya dikkat,

Şükürsüz duruyor, insaf nerdesin.

Dokuz ay taşıdı, doğurdu bizi,

Vücudu yorgandı, yastıktı dizi,

Sütüyle besledi, ninniydi sözü,

Anayı kırıyor, insaf nerdesin.

Yoksulun olmalı sıcak bir aşı,

Yetimin dinmeli gözünün yaşı,

Yaşasın baharı, görmesin kışı,

Umudum soruyor, insaf nerdesin.

Çalışanın gelir durumu harap,

Az kazancı ile çeker ızdırap,

Gelecek yardımı bekliyor Yarab,

Yokluğa varıyor, insaf nerdesin.

Yaşadığın hayat emanet sende,

Yarına hazırlan sayılı günde,

Can kuşu misafir, ağırla tende,

Kalemler kuruyor, insaf nerdesin.

Edep,erkan bizi giyimden tanır,

Bunca açıklığa nerede sınır,

Sevgiyi, saygıyı gözetmek onur,

Düşüncem eriyor, insaf nerdesin.

Çeçenler yıllardır yaşıyor zulüm,

Gazneli   haykırır, kalmadı halim,

Doğu Türkistanda konuşmaz dilim,

Kadirim,  arıyor, insaf nerdesin', 'Kalpdeki sevgiyi büyüten şefkat, Çilemi görüyor, insaf nerdesin. Hakkın kapısında vefaya dikkat, Şükürsüz duruyor, insaf nerdesin. Dokuz ay ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/insaf-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeditepeden', 'yeditepeden-mahmut-ozkan-qdc8w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir başkasın istanbul Gözlerimde bu akşam 

Kelimeler yetmiyor  Seni nasıl anlatsam

Asırlardır vatansın  Çeşitli milletlere

Şimdi benim canımsın Asla vermem ellere

Adaları gözlerim Sanki zümrüt taşları

Biraz uzak kalsa da Cıvıl cıvıl yazları

Kız kulesi arada Öksüz kalmış birisi

Üsküdar''dan bakınca Göz kırpıyor kulesi

Yalılar ve saraylar İnci gibi dizilmiş

Boğazında gemiler Üzülerek gidermiş

Kıtaları bağlıyor Üstündeki köprüler

Üsküdar''da ezanla Şenlenir minareler

Yerebatan gülhane Görsen sultanahmeti 

Ayasofya Topkapı  Beyazıt  piyerloti

Sahilde  kumkapıda Cek  balık ziyafeti

Bulamazsın bir yerde  Buradaki lezzeti

Süleymaniye camii Dünyanın harikası

Herkesi imrendirir Selimiye kışlası

Eyüpte sabahleyin Yer bulamam kaygısı

Nostaljiyi yaşatır Bize mısır çarşısı

İkitane şahit var tarihe tanık olan

Beyazıt ve galata kulesiyle tanınan

Geceleri yalnızca İstanbul''u gözlüyor

Kimbilir üzerinde nice sırlar saklıyor

Beylerbeyi eskiden Saltanatın kalesi

Vaniköy sahilinde  Askeriye lisesi

Hidiv kasrı yüksekte boğazı seyrediyor

Emirganla sarıyer çay içmeye bekliyor

Sesleniyor uzaktan Birbirine bakarak

Anadolu hisarı Rumeli hisarına

Bakın neler söylüyor İçi kan ağlayarak

Bir şey yaptık diyemem Fatihin anısına..', 'Bir başkasın istanbul Gözlerimde bu akşam  Kelimeler yetmiyor  Seni nasıl anlatsam Asırlardır vatansın  Çeşitli milletlere Şimdi benim canım...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Özkan']::text[], 8.5, '{"poet":"Mahmut Özkan","poet_slug":"mahmut-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yeditepeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alev Alev', 'alev-alev-yusuf-ter-mgbkw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimiz kilitlendi Şafağa

Canlar uyanmıyor durduk sabaha 

Yandı göz önünde nice bedenler

Ateşe verildi canlar Sivas’ta 

Şu üzgün yüreğim içten yanıyor

Kanlar ılgıt ılgıt yara kanıyor

Faşistler kuşatmış hep saldırıyor 

Zulme insanımız inler Maraş ta

Dersim dereleri kızıl boyandı

Ölümler içinde ölüm beğendi

Munzur yandı Harran uyandı

Acıydı figandı dünler Çorum da

Emekçiler bildi meydanlar dolu

Haykırdılar o gün tuttular yolu

Şimdi de uyansın şu insan seli

Ne yaralar açtı günler derimde

28.04.05

Saat 02:21 İsviçre

http://www.yusufter.tr.cx', 'Gözlerimiz kilitlendi Şafağa Canlar uyanmıyor durduk sabaha  Yandı göz önünde nice bedenler Ateşe verildi canlar Sivas’ta  Şu üzgün yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/alev-alev-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mirasım Şerefim.', 'mirasim-serefim-i-shak-ozlu-sko88', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çalıştım oğul,hainlik bilmedim,

Ülkemin Doğusu Batısı demedim.

Helal olmayan Ekmeği yemedim.

Mirasım Şerefim,taşı alnında oğul.

Yetim hakkı araziler çevirmedim,

Yüreksiz hırsızlara rüşvet yedirmedim.

Yürüdüm Adaletin çizdiği yolda,

Övüncüm alınterim,bil değerini oğul.

Yakın çevreme çıkar sağlamadım,

Birilerine talep için ağlamadım.

Vicdanın gören gözünü bağlamadım,

Gururum yüreğim,dinle sesini oğul.

Karanlık köşke paralı varılmaz,

Adettir,Kefensiz Mezarda yatılmaz.

Açılır sayfalar eksik fazla katılmaz,

Gerçek Ödül orda,unutma oğul.', 'Çalıştım oğul,hainlik bilmedim, Ülkemin Doğusu Batısı demedim. Helal olmayan Ekmeği yemedim. Mirasım Şerefim,taşı alnında oğul. Yetim hakkı ...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mirasim-serefim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evladım', 'evladim-veli-dalbudak-6mirj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana ömrümün çocukluğunu sakladım,

Her gününde mutlu olasın diye,

Sana ömrümün gençliğini sakladım,

Her mevsimde yeşil kalasın diye.

Sana ömrümün ihtiyarlığını sakladım,

Dertlerine olgun olasın diye,

Sana ömrümü harcadım,

Harcanmayasın diye.

.....hay evladım..

haberin bile yok.

(Stockholm 1986)', 'Sana ömrümün çocukluğunu sakladım, Her gününde mutlu olasın diye, Sana ömrümün gençliğini sakladım, Her mevsimde yeşil kalasın diye. Sana öm...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/evladim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankaram', 'ankaram-kadir-kaya-wj5iw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nice uygarlıklar görmüştür başın,

Anlatayım,herkes duysun Ankaram.

Bugün özgürdür toprağın, taşın,

Kimse aç kalmasın doysun Ankaram.

Sırayla yaşanmış tarih izleri,

Malazgirt'' den aktı, doldu özleri,

Başkent oldu.mutlu etti bizleri,

Şehirler içinde beysin Ankaram.

Atamı bağrına basmıştı Dikmen,

Düşmanı yok etti, hücuma kalkman,

Kurtuluş aşkını kalplere ekmen,

Karanlık gecemde aysın Ankaram.

Cumhuriyetimiz sende kuruldu,

İşgale gelenden hesap soruldu,

Savaşlardan sonra meydan duruldu,

Hasmına gerilmiş yaysın Ankaram.

Seymenler oynar misket oyunu,

Çubuk, Kurtboğazı verir suyunu,

Merada otlatır, keçi,koyunu,

Dönere yoğurdu koysun Ankaram.

Metrosunda türkü söyler rayları,

Gelmiş, mesken tutmuş Türkün boyları,

Hacı Bayram Veli gibi huyları,

Hüseyin Gazi''yi saysın Ankaram.

Görün gençlik,Güven,Kuğulu Parkı,

Çiçekler rengarenk doğanın farkı,

Buradan hızlanır devletin çarkı,

Haklının yanında oysun Ankaram.

Nehirler takın, barajlar küpen,

Nöbette ordumuz olmasın şüphen,

Nur içinde mabet, bak,  Anıttepen,

Zorda sığındığım koysun Ankaram.

Otagara bakarsan boyunda gerdan,

Elmadağı kışın geçilmez kardan,

Kaplıcada şifa beklenir terden,

Kızakla kaymayan kaysın Ankaram.

Yuvanın kavunu, Güdülde kiraz,

Akşam Gölbaşında mehtap eder naz,

Aydos yaylasında doyumsuzdur haz,

Namını dünyaya yaysın Ankaram.

Uruş, Beypazarı halis balımsın,

Çeşit çeşit meyva dolu dalımsın,

Moganla içiçe köşküm, yalımsın,

İçimi ısıtan çaysın Ankaram.

Tiyatro, opera, seyret baleyi,

Müzelerden sonra gezin kaleyi,

Sakın unutmayın Ata Kuleyi,

Hipodrumda nazlı taysın Ankaram.

Bayrağım göklerde dinlerim ezan,

Rabbime duamdır Odurki yazan,

Kadir,  Ankara''ma gelmesin hazan,

İsterse canıma kıysın Ankaram.', 'Nice uygarlıklar görmüştür başın, Anlatayım,herkes duysun Ankaram. Bugün özgürdür toprağın, taşın, Kimse aç kalmasın doysun Ankaram. Sırayla...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ankaram-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümün nuru', 'gozumun-nuru-meryem-i-sler-m2siu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerine yağmur düşmüş

Yanağında güller solmuş

Yüreğin hüzünlere boğulmuş

Canımın canı seni kimler üzmüş

Tanrımın bana hediyesi meleğimsin

Sen benim canımsın ciğerimsin

Gönül senden başkasını neylesin

Dilerim güneş yüzüne gölge  hiç düşmesin

Okyanuslar kadar sevgi dolu kalbin

 karıncayı bile incitmezsin

Bir gülüşüne neler neler vermezdim

Ceheneme bile seve seve giderdim

Ay seni görünce kıskanır doğmazdı

Yıldızlar utancından bulutlara saklanırdı

Işığından her birinin gözleri kamaşırdı

Kim üzdü  kim kırdi kalbini kim kararttı yüreğini

Canım çok acıyor seni hüzünlü görünce

Kalbim kan ağlıyor eriyorum içten içe

Gül ğözümün nuru dönelim mutlu günlere

Yoksa öleceğim seni böyle gördükçe', 'Gözlerine yağmur düşmüş Yanağında güller solmuş Yüreğin hüzünlere boğulmuş Canımın canı seni kimler üzmüş Tanrımın bana hediyesi meleğimsin ...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozumun-nuru-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ait Değilim', 'ait-degilim-sair-can38ist-b9p89', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aynı mahallede karşı komşumuz,

Ayşe hanım, Mehmet Bey, Nuran Teyze

Olmadı hiç.

Bakkalımız hep Ahmet Bey,

Kasabımız Musa efendi olmadı.

Çocukluğum aynı mahallede geçmedi,

Cem’le Fatmayla, Samiyle,

Uzun yıllar aynı okula gidip,

Aynı okuldan mezun olmadım

Mahallenin ebesi Nur Hanımın elinde doğup

Gözünün önünde büyümedim.

Kah bir şehirde doğdum,

Kah küçük bir kasabada okula gittim,

Ayşe,Meral,Serdar,Murat,Orhan,

Ve niceleri oldu sınıf arkadaşım,

Dün küçük bir kasabada Ahmet bakkaldan alışveriş yaptım,

Bugün büyük şehirde Süpermarkette.

Yaşadığım her kentte, kasabada,

Küçük, büyük sevgilerim oldu, 

Gözyaşlarım oldu,

Ne bir yere,

Ne bir kişiye ait oldum.

İzler kaldı beynimde, kalbimde,

Hüzün kapladı bazen,

Güldüm kendi kendime aklıma geldikçe.

Geçen bunca zamanda

Ait olmak istemedimmi? 

Bir mahalleye, bir kahveye...

Geri döndüğümde kahvede oturup,

Konuşmak Veli dedeyle,çaycı Mehmetle

Karşı komşumuzun oğlu Oğuzla

Yürürken mahallede pencereden..

Semra hanım ile selamlaşmayı...

İstemedimmi sanıyorsun? 

İlk aşkımı tekrar görüp,

Kalbimin kıpırdamasını istemedimmi? 

Beceremedim bunları,

Bir yere ait olmayı.

Hep kendimleydim, sadece ben.

İşte BEN,

Bana sahip olmayı düşünme,

Kaçırırsın o kocaman kalbi,

Serseri ruhu.

Hiçbiryere ait değil O.

Bırak yaşasın başka kalplerde,

Beyinlerde, duygularda,

Rüzgar savursun onu.

Kah senin kalbinde bedeninde,

Kah Ayşe teyzenin sevgisinde.

Kah kahveci Mehmet beyin çayında.

HİÇBİRYERE AİT OLMADAN......', 'Aynı mahallede karşı komşumuz, Ayşe hanım, Mehmet Bey, Nuran Teyze Olmadı hiç. Bakkalımız hep Ahmet Bey, Kasabımız Musa efendi olmadı. Çocuk...', ARRAY['Türk Edebiyatı','Şiir','Şair Can38ist']::text[], 8.5, '{"poet":"Şair Can38ist","poet_slug":"sair-can38ist","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/ait-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
