INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın Yok Diyecekler', 'yarin-yok-diyecekler-sair-can38ist-n8t99', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece yaşanmaya hazır,

Beklemekte seni,

Gün bitmiş, yaşanmaya hazır bir gece

Telaşla gelmişsin eve,

Bir an önce hazırlanıp çıkmak için can atıyorsun.,

Gözün saatte, gecikmemek için çabalıyorsun,

Son kez aynaya bakıp, 

Kendine gülümsüyorsun ve....

Atıyorsun kendini evden dışarı.

Güzel bir manzara var yanı başında,

Deniz dingin, martılar üstünde şarkı söylemekte,

Arkadaşların, dostların yanında, karşında,

Bir yandan çalan müzik, 

Diğer yanda martıların ve vapurların nağmeleri.

Ne güzel bir senfoni, gözlerini kapatıyorsun.......

Sohbetler, kahkahalar,gece yaşanıyor,

İçin daralıyor

 Boğazın düğümleniyor  bir an,

Anlam veremiyorsun,

Kuruyan boğazını ıslatmak için,

Bir yudum almak istiyorsun,

Kadehteki şarabından.

Anlamsızlığı anlamlandırmak için kadehine bakarken,

Elinden kayıp gidiyor kadeh,

Kırılıyor,  kırdığın kalpler gibi.

Yitip gitmiş gençliğin gibi.

Sabah olmuş, aynı telaş.....

İşe geç kalmamak için başlayan koşuşma,

İşte yine aynı şeyler başlıyor, 

Yaşadığın günü tekrar yaşamak...

İşe başlamadan yaptığın şeyi yapıyorsun yine

Bir kahve içimlik sürede gazeteye göz atıyorsun,

İkinci yudumda düğümleniyor boğazın,

Gazetede gördüğün bir küçük bir haber,

Küçük bir ölüm ilanı,

Sıradan, her gün yazılanlardan,

Düğüm her saniye büyüyor boğazında,

Gözlerinde oluşan küçük damlalar,

Ve onları tutmak için mücadele etmeden,

Tekrar bakıyorsun küçük ilana

O Artık yok diyorsun,

Gelen bir telefon,

“ O artık yok “ diyor sana

Gözden geçirmenin zamanımı şimdi? 

Boğazındaki düğümler çözecekmi? 

Takvime bakıyorsun gözünü kırpmadan,

Yarın olmuş bunu anlıyorsun

Telefondaki ses 

“ O Artık Yok “ diyor', 'Bir gece yaşanmaya hazır, Beklemekte seni, Gün bitmiş, yaşanmaya hazır bir gece Telaşla gelmişsin eve, Bir an önce hazırlanıp çıkmak için ca...', ARRAY['Türk Edebiyatı','Şiir','Şair Can38ist']::text[], 8.5, '{"poet":"Şair Can38ist","poet_slug":"sair-can38ist","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/yarin-yok-diyecekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin İçindeki Ben', 'gecenin-i-cindeki-ben-sair-can38ist-88hnt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gündüz örtmüş sevgiyi, duyguyu,

Gündüz karartmış mutluluğu,

Karartmışız aşkımızı,

Bilmeden, duymadan.

Gece, ne güzelsin sen,

Yalnızlığımı paylaşan, beni saran

Hüznümü alan, mutluluğumu veren,

Geceleri severim yaşamayı,

İnsanları severim gecelerde,

Maskelerini çıkarmış,

Çırılçıplak insanları.

Nefretler, kinler, mutsuzluklar,

Dönüşür sevgiye mutluluğa,dostluğa,

Sonsuz sakinliğinde gecenin.

Aşklar ilan edilir,

Kaçamak bakışlar kenetlenir,

Eller buluşur, nefesler birleşir,

Bir can olur; 

İki ruh, iki beden.

Korkusuzca, sevgiyle, umutla.

Dedim ya, geceleri severim yaşamayı,

Gece severim ölmeyi,

Sessiz, sakin habersizce gitmeyi.

Farkına vararak mutluluğun, dostluğun, sevginin.

Gece ölmek isterim; 

Sessiz huzur içinde sakin bir gecenin.

Gece gelin mezarıma,

İnsanlar görmesin ağladığınızı,

Yanımda ağlayın, mutluluktan, sevgiden...

Dostlarım! Geceleri hatırlayın beni..

Sevdiğim kadınlar geceleri hatırlayın beni,

Geceleri aldatın beni umursamadan.

Sen oğlum; geceleri bak resmime,

Gecelerde geleceğim yanına,

Kollarımla saracağım seni,

İçime alacağım geceleri,

Ve seni daima seveceğim GECELERİ', 'Gündüz örtmüş sevgiyi, duyguyu, Gündüz karartmış mutluluğu, Karartmışız aşkımızı, Bilmeden, duymadan. Gece, ne güzelsin sen, Yalnızlığımı pa...', ARRAY['Türk Edebiyatı','Şiir','Şair Can38ist']::text[], 8.5, '{"poet":"Şair Can38ist","poet_slug":"sair-can38ist","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gecenin-icindeki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsim', 'dort-mevsim-sair-can38ist-3t8lq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben dört mevsim gibiyim,

Gözlerime bakıp üşüyüp kışı hissederken,

Tenime dokunup kavurucu yazı hissedersin.

Kelimelerimde ilkbaharın tatlı esintisini yaşarken,

Kalbimde sonbahar hüznünü görürsün.

Ben deniz gibiyim,

Öfkem patlamış tayfuna benzer,yıkar geçer,

Sakinliğimde kıyıma oturup sessizce dinlersin beni', 'Ben dört mevsim gibiyim, Gözlerime bakıp üşüyüp kışı hissederken, Tenime dokunup kavurucu yazı hissedersin. Kelimelerimde ilkbaharın tatlı e...', ARRAY['Türk Edebiyatı','Şiir','Şair Can38ist']::text[], 8.5, '{"poet":"Şair Can38ist","poet_slug":"sair-can38ist","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dort-mevsim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (74) ''Gönül Yare Seslenir...''', 'maniler-74-gonul-yare-seslenir-abdullah-atay-qkw0q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül yare seslenir 

Yar gelirse uslanır 

Yari güzel olanlar 

Bal dudakla beslenir... 

Su akar derin derin 

Gönlümdedir yar yerin 

Dünya malı neyleyim 

Bana yarimi verin... 

Baharımı kış eyleme 

Gözlerimi yaş eyleme 

Beni gurbet elde koyup 

Yüreğimi taş eyleme... 

O yare ben kul oldum 

Çiçeğine dal oldum 

Gonca gülüm solunca 

Susuz kalmış çöl oldum... 

Gözlerinde yaş olsam 

Aksam bağlara bağlara 

Gönlündeki kuş olsam 

Uçsam dağlara dağlara.... 

Kurt kuşu besler dağlar 

Eteğini süsler dağlar 

Sevdalanmış başını 

Buluta yaslar dağlar... 

Evinin önü fırın 

Yari görecem yarın 

İpek peştamal aldım 

Sarın sevdiğim sarın... 

Yare kavuşmuş gönlüm 

Yeni açmış gül gibi 

Yarsız geçen her günüm 

Suya hasret çöl gibi...', 'Gönül yare seslenir  Yar gelirse uslanır  Yari güzel olanlar  Bal dudakla beslenir...  Su akar derin derin  Gönlümdedir yar yerin  Dünya mal...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/maniler-74-gonul-yare-seslenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiyem', 'turkiyem-kadir-kaya-lmt21', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nereye bakarsan, sanırsın Cennet,

Sevincim içimde kordur Türkiyem.

Özlerim, doyamam duyarım minnet,

Yuvadır, anadır, yardir  Türkiyem.

En kutsal emanet bizde vatandır,

Atam üç kıtada şehit yatandır,

Beklerim nöbeti evim kıtamdır,

Askerim sınırda surdur Türkiyem.

Hunlar, Göktürk, Uygur Turan boyumdur,

Selçuklu, Osmanlı özüm, soyumdur,

Yüz ondokuz birlik, devlet sayımdır,

Senin aslın, kökün gürdür Türkiyem.

Ulusum tarihi gücüyle yazar,

Sevgimiz yürekten sızdıkça sızar,

Dualar sanadır, değmesin nazar,

Varlığın islamda kardır Türkiyem.

Bağrında yiğitler saklar toprağın,

Türkiyem Türkündür olmaz ortağın,

Renk  renk desen  desen yaprağın,

Senden uzak kalmak zordur  Türkiyem.

Halkımız barışta güller derendir,

Savaşta cepheye koşup girendir,

Bayrağım uğruna canlar verendir,

Sönmeyen aşkımız sırdır Türkiyem.

Misafir ilgiyle sürer sefayı,

Tatlı dil ,güler yüz bulur vefayı,

Sabır yüküm, sine çeker  cefayı,

Bitmez hoşgörüyü sürdür Türkiyem.

Dededen toruna gizemli bağlar,

Babalar çalışır geleçek sağlar,

Yaylayı, ovaya özletir dağlar,

Candan, hürmet, saygım vardır Türkiyem.

Malım, mülküm hepsi sana fedadır,

Can tenimden çıkar ,borcum edadır,

Okunan ezanlar Haktan sedadır,

Bize mutluluğu erdir Türkiyem.

Kadirim, son damla kanı dökmeden,

Yerler delinmeden,  gökler çökmeden,

Türk yaşayacaktır, boyun bükmeden,

Dünyamız durdukça hürdür Türkiyem.', 'Nereye bakarsan, sanırsın Cennet, Sevincim içimde kordur Türkiyem. Özlerim, doyamam duyarım minnet, Yuvadır, anadır, yardir  Türkiyem. En ku...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/turkiyem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tohum', 'tohum-yucel-gursac-f96v8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Martı

gagasında bir tohum

uçar gökyüzünde

derinler boyunca günlerce.

bir gün düşer ağzından,

martının yemi sahillere.

bir rüzgar eser, karıştırır tohumu kumsallara

bir dalga vurur, suyun verir

ardından güneş

tohum yeşerir, çiçek verir

çiçek bakar senelerce

rüzgarın serinlettiği

denizle göğün birleştiği yere.

ve birgün

bir martı gelir, ayırır özünü çiçeğin

bir rüzgar eser, eğdirir boynunu

bir dalga vurur sahillere

kırar belini çiçeğin

ve güneş ardından bir tanem

çiçek kurur

döner başladığı yere...', 'Martı gagasında bir tohum uçar gökyüzünde derinler boyunca günlerce. bir gün düşer ağzından, martının yemi sahillere. bir rüzgar eser, karış...', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tohum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı-1', 'sarki-1-guzin-eye-dundar-2azz3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözgöze konuştuk 

belki son defa

anladımki sevgimiz

tükendi bitti

bu şarkı bendendir

senin  adına

gönlün mutluluğa 

koşsun isterim

göğsümde  hıçkıran

İnleyen kalbin

dert tasa görmesin

tapsın sevdaya

bu şarkı bendendir

armağan sana

mutluluk baş tacın olsun isterim', 'gözgöze konuştuk  belki son defa anladımki sevgimiz tükendi bitti bu şarkı bendendir senin  adına gönlün mutluluğa  koşsun isterim göğsümde ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sarki-1-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sila...', 'sila-zulfikar-yapar-kaleli-zjkc2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanık bir türküdür ah, garibin dudağında

Sevdalar yankılanır, muhabbet onu izler

Bülbülün gözü kalmış, şu gülün budağında

Düşünce düşlerine, çekilmez olur nazlar

Ne bir ezân okunur, ne evde duman tüter

Çeşmesinde suyu yok, bağında geven biter

Bekçi, muhtar mezarda, garipliğe bu yeter

Baykuşlara yurt olmuş, insanın içi sızlar

Yıkıntılar üstünde mutlu ağarmıyor tan

Ah şu sıla dediğim, koskoca bir kabristan

Gönüller ağıt söyler, ne mâni, var ne destan

Ne de bacalarında horon tepiyor kızlar

Bir hasret ki bağrımda, yakar da beni nara

Devası yok hasretin, sıla gönlümde yara

Bu özlem işkencesi, benle gider mezara

Baharların adı güz, beni ısıtmaz yazlar

Yoluna düş sılanın, karalı git, aklı gel

Gözler sürme, kaş kalem, kirpikleri oklu gel

Çeşmin yolda, iç buruk, düğüm- düğüm saklı gel

Gönlüne özlem düşer, buruktur sılasızlar', 'Yanık bir türküdür ah, garibin dudağında Sevdalar yankılanır, muhabbet onu izler Bülbülün gözü kalmış, şu gülün budağında Düşünce düşlerine,...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sila-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köylerin Hali...', 'koylerin-hali-zulfikar-yapar-kaleli-18ok3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Görmedim bir tane mağdur olmamış,

Yolları perişan köylerin şimdi.

Dağlarında kuşu bile kalmamış,

Halleri perişan köylerin şimdi.

Göçmen kuşlar artık köyden geçmiyor,

Kuşu bırak, sinek bile uçmuyor,

Kuşburnu da bile çiçek açmıyor,

Gülleri perişan köylerin şimdi.

Kimisi şehirde refah aradı,

Malum ya kiminin “höt” oldu adı,

Bu göç işi mezarcıya yaradı,

Elleri perişan köylerin şimdi.

Kimi köyde kaldı çare olmadı,

Kalan da, göçen de huzur bulmadı,

Hiç bir şeyin eski tadı kalmadı,

Belleri perişan köylerin şimdi.

Doğunun insanı batıya dolmuş,

Kaleli ne töre ne adet kalmış,

Arı nezle olmuş petek bozulmuş,

Balları perişan köylerin şimdi.', 'Görmedim bir tane mağdur olmamış, Yolları perişan köylerin şimdi. Dağlarında kuşu bile kalmamış, Halleri perişan köylerin şimdi. Göçmen kuşl...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/koylerin-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrasi Ürünü.! ! !', 'demokrasi-urunu-zulfikar-yapar-kaleli-w4cko', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soyundan habersiz dolu her yanı

Yetmedi mi kaçırmayın kaçağı

Soygun, vurgun,talan ile vatanın

Kemiğine dayamışlar bıçağı

Zincire vurulsun kapansın yırtık

Fakat namussuzluk kalmasın örtük

Gafil olmak ayıp görmeli artık

Millete kurulan bunca tuzağı

Ehliyetsiz olan işini bulmuş

İhtisası olan kenarda kalmış

Başımıza amir diye oturmuş

Devrin en azılı kösnük bunağı.

Soyguncu, vurguncu ülkeye dolmuş

Üstelikte kanun, ceza o olmuş

Yalanın, talanın tadını almış

Bulmuşken şu başsız baş avanağı.

Hep git dedik, kovduk kovduk gitmedi

Çaldı, yedi haramı hiç itmedi

Sattı savdı, yedi içti bitmedi

Hâlâ gözü beklemekte bu bağı

Bunlar hiç olur mu Allah’a yakın

Sakın ha! ! Bunlardan kendini sakın

Fırsat kaçırmazlar görün de bakın

Çünkü bunlar şeytanların ortağı

                                           1990', 'Soyundan habersiz dolu her yanı Yetmedi mi kaçırmayın kaçağı Soygun, vurgun,talan ile vatanın Kemiğine dayamışlar bıçağı Zincire vurulsun ka...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/demokrasi-urunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümserim.!', 'gulumserim-zulfikar-yapar-kaleli-uy4vl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Gülümserim; sanmayın mutluluktandır, hayır! 

Hüznümün göz yaşıyla, sulanır bunca çayır...', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Gülümserim; sanmayın mutluluktandır, hayır!  Hüznümün göz yaşıyla, sulanır bunca çayır......', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gulumserim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Ortasındayım...', 'sokak-ortasindayim-zulfikar-yapar-kaleli-8kb1g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Bir yaz öğlesinin karanlığında

Sarılmışım, sokak ortasındayım

Omzum sorumluluk ağırlığında

Yarılmışım, sokak ortasındayım.

Gecikmiş muştunun karanlık ardı

Güneş bizim ufkumuzdan doğardı

Yağmurlar ki göğümüzden yağardı

Durulmuşum, sokak ortasındayım.

Diriliş âhdinin müjdesi ölüm

Yüreğim yeşerir, kurusa dilim

Şimdi vakti değil ölümün gülüm

Yorulmuşum, sokak ortasındayım.

Umudun ufkuna asılı gözler

Güneşin şavkısı gölgemi izler

Sular bir özlemle denizi özler

Burulmuşum, sokak ortasındayım.

Buharın buluta hasreti yaman

Gecikti emeller eridi zaman

Korkunun pençesi peşimde her an

Sorulmuşum, sokak ortasındayım.

Yüreğin yükünü taşımaz tenim

Düşlerim tavafta, Mekke’ye yönüm

Dünyanın en yalnız insanı benim 

Darılmışım, sokak ortasındayım.

Dilimin kilidi bağrımda yara 

Çöller suya hasret, gönül bahara

Yeşeren yüreği göklerde ara

Kırılmışım, sokak ortasındayım.

Şu başıma yağan sevda karını 

Eritemem, sevdam günün sorunu

Yaşardım bugünden dünü, yarını

Vurulmuşum, sokak ortasındayım.

                 					20 haziran 1997', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Bir yaz öğlesinin karanlığında Sarılmışım, sokak ortasındayım Omzum sorumluluk ağırlığınd...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sokak-ortasindayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Rüyana Gireceğim! ...*', 'ruyana-girecegim-askin-egeli-9q392', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir rüya mı olmalıydım

Tutunabilmek için sana

Rüyan olup orada mı kalmalıydım? ...

Seni sewip senle kalabilmek için... 

Aşkın olabilmek için sana,

 daha nereye kadar gitmeliyim! ? 

Aşık olabilmen için bana, 

daha ne kadar delirmeliyim? ! ...

Rüyalar hep güzelse...

Sen hep rüyalara aşıksan yalnız...

Rüyan olmaya razıyım senin! ...,

Gerçeğin olamayacaksam...

Ben de rüyana girerim! 

Rüyan olur, 

Gerçeği bırakır,

Sadece SANA gelirim! ...', 'Bir rüya mı olmalıydım Tutunabilmek için sana Rüyan olup orada mı kalmalıydım? ... Seni sewip senle kalabilmek için...  Aşkın olabilmek için...', ARRAY['Türk Edebiyatı','Şiir','Askın Egeli']::text[], 8.5, '{"poet":"Askın Egeli","poet_slug":"askin-egeli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruyana-girecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İman Merkezinde Kal', 'i-man-merkezinde-kal-necmi-unsal-2up77', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya sana mülk olacak sanma.

Gitmeden önce tedbirini al.

Hevesler fâni, sakın ha kanma! 

Götürür seni düşlerinle sal.

Zehre şifadır diyerek banma! 

Sevgi balına hep iştahla dal.

Ateşe döner günahın, yanma! 

Dâima iman merkezinde kal.



9 Haziran 2004 Çarşamba, Danimarka-Køge 19.43

5+5', 'Dünya sana mülk olacak sanma. Gitmeden önce tedbirini al. Hevesler fâni, sakın ha kanma!  Götürür seni düşlerinle sal. Zehre şifadır diyerek...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iman-merkezinde-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arap saçına döndü', 'arap-sacina-dondu-mikdat-bal-n5iey', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep sırt üstü yatıldı

Dama neler atıldı

Neler bize katıldı

Arap saçına döndü

Vaatler kaldı lafta

Ukalalar hilafta

Çözülme var her safta

Arap saçına döndü

Düğüm üstüne düğüm

Sade benim gördüğüm

Neyi baksan, kör düğüm

Arap saçına döndü

Para etmiyor hasat

Ortadan kalktı vasat

İmefeli iktisat

Arap saçına döndü

İşsizler iş bulamaz

Fakirler aş bulamaz

İşçi maaş alamaz

Arap saçına döndü

Sıkıldı kemerimiz

Para etmez terimiz

Beynelmilel yerimiz

Arap saçına döndü

Başıboş bir piyasa

Çoğu gitti iflasa

Bütün işler hülasa

Arap saçına döndü

Po-li-ti-ka dört hece

Demokrasi bilmece

Ekonomi gün, gece

Arap saçına döndü', 'Hep sırt üstü yatıldı Dama neler atıldı Neler bize katıldı Arap saçına döndü Vaatler kaldı lafta Ukalalar hilafta Çözülme var her safta Arap...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/arap-sacina-dondu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlar...', 'aglar-sila-nur-koken-vvv74', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşklar oldu ağladığım

Yoklara karışan

Ve

Kördüğüm ağlar

Öyleymiş

Düşgücümün gücüymüş hepsi

Düşlemişim

İstemişim

İçim acımış sadece

Sevmişim de bu acıyı 

Acıyan içime acıyarak

Ve

Ağlayarak

Yeni düşler kurup

Yeni ağlar örerek

Giderek

Daha da

Azalır görünürken

Çoğalarak

Aşk olarak

Gidiyorum...

Giderek

Aşklaşıyorum...”

(28 Ağustos 2004)', 'Aşklar oldu ağladığım Yoklara karışan Ve Kördüğüm ağlar Öyleymiş Düşgücümün gücüymüş hepsi Düşlemişim İstemişim İçim acımış sadece Sevmişim ...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aglar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atisma', 'atisma-ayda-yildiz-uz64s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim yuregime kim dokunur

Eyer egilmezsem

Benim sirtima kim vurur

Eyer kollarimi acip ona sarilmazsam

Ben nasil gulumserim

Eyer seni okumazsam

Egil bir yol yureginden opeyim

Saril bir yol sirtina vurayim

Gul bana bir yol, seni opeyim

Misra, misra dokup, gondereyim', 'Benim yuregime kim dokunur Eyer egilmezsem Benim sirtima kim vurur Eyer kollarimi acip ona sarilmazsam Ben nasil gulumserim Eyer seni okumaz...', ARRAY['Türk Edebiyatı','Şiir','Ayda Yıldız']::text[], 8.5, '{"poet":"Ayda Yıldız","poet_slug":"ayda-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/atisma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altıncı Gün', 'altinci-gun-huseyin-dogan-f9q6m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir geceyi daha kavuşturdum sabahına

Ölüme gebe yüreğim

Doğuracak sonunda çığlık çığlığa

Taze bir mezar benim mezarım

Beşinci gece bekleyişi

Altıncı gün nefes almaktayım hala.

Ölümün Annesi olmak ne zormuş

Şimdi anlıyorum kadınları.....

Ben ölürken ölüm doğacak

Haber salacaklar dostlarıma

Muştumuzu isteriz

Hee oğlan oğlan doğdu ölüm

Kadife ceketini giyip bir adam

Kayıp gidecek bu dünyadan

Mahzun kalacak ahu besteleri sevdanın

Eziyetimi ağırlaştıranda

Mum misali fitilimde ateş var

Yüreğim hala sıcak

Ama akmış kalmamış bembeyaz tenim

Ne kadar direneceğim

Daha ne kadar gece kavuşacak sabahına...

......................

Şehirden mektupların geldi

Okumadım hiç birini

Yanlız açıldı zarflardan biri

Kaydı içinden yeni fotografın

Değişmişsin kısa kestirmişsin saçlarını

Fransız markizi olmuşsun bu maskeli balonun

Sana muhabbetim erkeklik ihtiyacı

Nefretimse kadınlık ihtiyacın değildi elbette

Aşk bozgununu bilirim ben

O lise talebesi değilim

Sivilcelerinin içinde sevda taşıyan.

Vurup sırtıma semeri hep taşıdım sevdanın yükünü

Ben indirmeden  kederleri gideceğim.

Semerde sevdada benim.

Bunu böyle bileceğim.

.........................

Ne kadar tenha oluyor sonlar

Ölüme beş kala beydahlanmış mayası nefes almanın.', 'Bir geceyi daha kavuşturdum sabahına Ölüme gebe yüreğim Doğuracak sonunda çığlık çığlığa Taze bir mezar benim mezarım Beşinci gece bekleyişi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Doğan']::text[], 8.5, '{"poet":"Hüseyin Doğan","poet_slug":"huseyin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/altinci-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bir Beddua Değil (Gerçekler)', 'bu-bir-beddua-degil-gercekler-umit-engin-ancyd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varlığımda hüküm sür yıllar boyu, hiç kimseye söylemeyeceğim adını. Bir ok gibi parçala yüreğimi, unutmayacağım seni. Her zerrem yok olana kadar  bu dünyada, tin olup göcünce manevi dünyaya, yine seninle, senin olacak varlığım. Aşk diye, sevgi diye bakıp kandığın, seni yarı yolda  bırakan  herkesten hesap soracağım senin için. “ inan bana, bu zavallı dünyada seni sevdiğini sandığın herkesin üzerinde gözüm. Sana yapılan her sahte sevginin bedelini yavaş yavaş açılar içinde ödeyecekler…”                                                                        

 

26.03.2005  / 16:35  / ümit engin', 'Varlığımda hüküm sür yıllar boyu, hiç kimseye söylemeyeceğim adını. Bir ok gibi parçala yüreğimi, unutmayacağım seni. Her zerrem yok olana k...', ARRAY['Türk Edebiyatı','Şiir','Ümit Engin']::text[], 8.5, '{"poet":"Ümit Engin","poet_slug":"umit-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bu-bir-beddua-degil-gercekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz Kesti Heryanım', 'buz-kesti-heryanim-umit-engin-nnlmx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimsesizleri oynuyorum martılarla sen bu limandan gideli. Uçsuz bucaksız bir okyanus gibi oldu yanlızlığım. Sanki seni görüyormuş gibi hasret çığlıkları haykırıyorum etrafa. Poyraz rüzgarları dövüyor bedenimi, fırtınalar kopuyor gözlerimde. Ben ise ne bir acı duyuyorum, nede bir alabora oluyor içimde. Buz kesti her yanım, seni düşünüyorum sadece…

 

04.04.2005 / 09:50 / ümit engin', 'Kimsesizleri oynuyorum martılarla sen bu limandan gideli. Uçsuz bucaksız bir okyanus gibi oldu yanlızlığım. Sanki seni görüyormuş gibi hasre...', ARRAY['Türk Edebiyatı','Şiir','Ümit Engin']::text[], 8.5, '{"poet":"Ümit Engin","poet_slug":"umit-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/buz-kesti-heryanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Bilen Arıyorum', 'aski-bilen-ariyorum-sahin-erturk-wbxly', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Trakyada,İstanbul da

Sakaryada,Ankara da

Sosyetede arıyorum

Aşkı bilen arıyorum

Eskişehir,Kütahya da

Denizlide,Antalya da

Yakınlarda arıyorum

Aşkı bilen arıyorum

Sevda dolu şiirleri

Unutulmaz şarkıları

Yazanlarla arıyorum

Aşkı bilen arıyorum

İşin ehli olanlarla

Yalnızlığı çekenlerle

Gözyaşını dökenlerle

Aşkı bilen arıyorum

Köye gittim,dağa çıktım

Varoşları,kenti gezdim

Taşralarda arıyorum

Aşkı bilen arıyorum

Kimileri tipin dedi

Kimileri sesin dedi

Kimileri cebin dedi

Çıkmadıki aşkı bilen

Sora,sora düşe kalka

Oralarda,buralarda

Arıyorum,arıyorum

Aşkı bilen arıyorum

Yaşa,başa aldırmayan

Yalan sözle kandırmayan

Televole yaşamayan

Aşkı bilen arıyorum

Leyla,Zühre çıkar diye

Mutluluğum olur diye

Otuz yıldır arıyorum

Aşkı bilen arıyorum

(20.05.2005) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Trakyada,İstanbul da Sakaryada,Ankara da Sosyetede arıyorum Aşkı bilen arıyorum Eskişehir,Kütahya da Denizlide,Antalya da Yakınlarda arıyoru...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/aski-bilen-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Ateştir', 'yuregimde-atestir-kadir-soyturk-qoc8x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ödeyin beyler, ödeyin; çalışmayana  ödeyin

Çalışanlar aç kalsın; ''paramız yokki '' deyin! 

Bu millet evladının ağzı varya dili yok

Simit olsun almaya, imkanı, torpili yok! 

Ahmetler, Haticeler zaten bilmez yemeyi

Açlıktan ölse bile, ''Hakkım nerde? '' demeyi! 

Evde oğlan – kız açken, danyel – manyeller doysun; 

Otursun baş köşeye, bizi sokağa koysun! 

İnsan bakıp duruma, ''Sahipsiz miyiz? '' diyor 

Gidişimiz nereye,  kim kazanıp kim yiyor? 

Soru sormak kolay ya, cevap vermek zor gibi....

Bana acı veriyor, yürekte ki kor  gibi! 

Yiyin – yutun,  harcayın, boş yerlere ödeyin

Bir gün soran olursa, ''yanlışlık olmuş '' deyin!', 'Ödeyin beyler, ödeyin; çalışmayana  ödeyin Çalışanlar aç kalsın; ''paramız yokki '' deyin!  Bu millet evladının ağzı varya dili yok Simit olsu...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yuregimde-atestir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmuşum Kızma Be Gülüm!', 'unutmusum-kizma-be-gulum-sahin-yilmaz-u7j86', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ancak ölüm unutturur, demişim

Seni unutmuşum, kızma be gülüm! 

Demek ki laf olsun diye sevmişim

Seni unutmuşum, kızma be gülüm! 

Hatırlayamadım, nasıldı yüzün? 

İsmini duydukça almıyor hüzün

Gözümün önüne gelmiyor gözün

Seni unutmuşum, kızma be gülüm! 

Sahi soyadın ne, adresin neydi? 

El ele gezmemiz nasıl bir şeydi? 

Yaşlandım mı, yoksa nazar mı değdi

Seni unutmuşum, kızma be gülüm! 

Saçın siyah mıydı, yoksa sarı mı? 

Tenin buğday mıydı, dağın karı mı? 

Deme sakın unutmanın yeri mi? 

Seni unutmuşum, kızma be gülüm! 

Karşıma geçip de durma boşuna

Geçmişi önüme serme boşuna

Bazı ipuçları verme boşuna

Seni unutmuşum, kızma be gülüm! 

Ne hayalin kaldı, ne cismin kaldı

Ne mektubun kaldı, ne resmin kaldı

Sana olan sevgim biranda öldü

Seni unutmuşum, kızma be gülüm! 

Senden kalanları ateşte yaktım

Mazinin üstüne bir çizgi çektim

Gönül dayanmadı, nazından bıktım

Seni unutmuşum, kızma be gülüm! 

Şahin uçamıyor, yoruldu artık

Hatırlaması zor, kırıldı artık

Aramıza perde gerildi artık

Seni unutmuşum, kızma be gülüm!', 'Ancak ölüm unutturur, demişim Seni unutmuşum, kızma be gülüm!  Demek ki laf olsun diye sevmişim Seni unutmuşum, kızma be gülüm!  Hatırlayama...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/unutmusum-kizma-be-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın Beyler Günaydın', 'gunaydin-beyler-gunaydin-mustafa-kemal-bal-mx4d2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görev sizde ey idare

Hortumları kesin diye

Gerek kalmasın vergiye

Günaydın beyler günaydın

Suçlular her kim ise

Adaletle yüzleşirse

Haksızlık giderilirse

Günaydın beyler günaydın

Gemi karaya vurmadan

Yurttaş aradan çıkmadan

Ellere avuç açmadan

Günaydın beyler günaydın

Ne ar kaldı nede hayâ

Namus düştü işportaya

Hatırlat ana babaya

Günaydın beyler günaydın

Dürüstlük düştü ayağa

İnsanlıksa beş paraya? 

Kurtuluş kaldı duaya

Günaydın beyler günaydın

Derman vardır her yaraya

Son verelim kanamaya

Gerek var mı ağlamaya? 

Günaydın beyler günaydın

Çözüm lafla değil bilin

Çareyse neşter indirin

Sancıları hep dindirin

Günaydın beyler günaydın', 'Görev sizde ey idare Hortumları kesin diye Gerek kalmasın vergiye Günaydın beyler günaydın Suçlular her kim ise Adaletle yüzleşirse Haksızlı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kemal Bal']::text[], 8.5, '{"poet":"Mustafa Kemal Bal","poet_slug":"mustafa-kemal-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gunaydin-beyler-gunaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardır', 'vardir-huseyin-sigirtmac-a38je', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damla damla süzülürüz ezelden

Altına öz olan pulumuz vardır.

Bize ne, çürümüş, kuru gazelden.

Yeşile erdiren Ulumuz vardır.

Riya ile dosta verilmez ikrar.

Yar olanlar yarsa, duygusuyla yar.

İnsanla şenlenir yaşanan diyar.

Hakka doğru giden yolumuz vardır.

Gerçekten ayrılmaz gerçek olanlar.

Zirveye erer mi alçak olanlar? 

Tonları da taşır ölçek olanlar.

Boşlara da gıda dolumuz vardır.

Sığırtmaç aklaşıp sildik pasımız.

Bülbülün nağmesi nefes, sesimiz.

Zulüm bitmedikçe geçmez yasımız.

Mazlumun üstünde kolumuz vardır.', 'Damla damla süzülürüz ezelden Altına öz olan pulumuz vardır. Bize ne, çürümüş, kuru gazelden. Yeşile erdiren Ulumuz vardır. Riya ile dosta v...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vardir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin Sen Dostum?', 'kimsin-sen-dostum-mustafa-kemal-bal-fgd2y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kolayca kandın

Oyuna daldın

Ölçünü aldın

Kimsin sen dostum? 

Yele takılmış

Sele kapılmış

Ele sarılmış

Kimsin sen dostum? 

Vatana asi

Mevlaya asi

Tam yüz karası

Kimsin sen dostum? 

Sahnede başta

Kıvrakça dansta

Aklın oynaşta

Kimsin sen dostum? 

İçimizdesin 

Bizden değilsin

Yeniçerisin 

Kimsin sen dostum? 

Kendine karşı

Halkına karşı

Lanet olası

Kimsin sen dostum? 

Ne varsa gitti

Güvenim bitti

Canıma yetti

Kimsin sen dostum? 

Süt mü istersin? 

Bal mı istersin? 

Atalım! gitsin

Kimsin sen dostum?', 'Kolayca kandın Oyuna daldın Ölçünü aldın Kimsin sen dostum?  Yele takılmış Sele kapılmış Ele sarılmış Kimsin sen dostum?  Vatana asi Mevlaya...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kemal Bal']::text[], 8.5, '{"poet":"Mustafa Kemal Bal","poet_slug":"mustafa-kemal-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kimsin-sen-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşim ve Annem', 'esim-ve-annem-kadir-kaya-lku32', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbim iki uçtan onlara bağlı,

Duygum yoğunlaşır,hislerim coşar,

Ağız tadım ballı, ekmeğim yağlı,

Gönül sarayımda ikisi yaşar.

Biraz durgun görsem, yanıyor içim,

Paylaşmayı bilsek, olacak geçim,

Aralarında hiç olurmu seçim,

Birinde yoğrulur,birinde pişer.

Analar evladı büyümez sanır,

Sevenler sevgiyi    severek tanır,

Canlar cananını elbet kıskanır,

Hasretler, özlemler çoğalır taşar.

Zorlukları aşıp gelecek çizer,

Yolumu bekleyip derdimi çözer,

Bakışıyla okşar, arzumu sezer,

Bitmeyen vefayla yanıma koşar.

Acısı, tatlısı yaşanan gerçek,

Eşimde büyüttü üç tane çiçek,

Kadir mutlu güzel  günler gelecek,

Hüzünü, kederi mutluluk aşar.', 'Kalbim iki uçtan onlara bağlı, Duygum yoğunlaşır,hislerim coşar, Ağız tadım ballı, ekmeğim yağlı, Gönül sarayımda ikisi yaşar. Biraz durgun ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/esim-ve-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ona Buna Dağıtılmış Öpüşler', 'ona-buna-dagitilmis-opusler-derin-oger-2xkdo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir gün senin de ihtişamın yıldızlarla kayarken bulur kendini

tedirgin edici acı bir gülüş yerleşir dudaklarının kıvrımlarına

şarkılarımızı suçlu bir özgürlüğün ağzından dinledikçe 

utanır sızan yaştan gözbebeğin,eğilir umutlarım gibi kirpiğin

anlarsın ki ne izi var ne hatırası ona buna dağıtılmış öpüşlerin......', 'bir gün senin de ihtişamın yıldızlarla kayarken bulur kendini tedirgin edici acı bir gülüş yerleşir dudaklarının kıvrımlarına şarkılarımızı ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ona-buna-dagitilmis-opusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Yalnızsın ki', 'oyle-yalnizsin-ki-ertugrul-sakar-557wo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle yalnızsın ki

Yalnızlığım yanında hiç kaldı

Yastığın ağlıyor

Hani neşe dolu cıvıl cıvıldın

Nerde günışığı gülücüklerin

Bu mu hayat

İş

Aş', 'Öyle yalnızsın ki Yalnızlığım yanında hiç kaldı Yastığın ağlıyor Hani neşe dolu cıvıl cıvıldın Nerde günışığı gülücüklerin Bu mu hayat İş Aş...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oyle-yalnizsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalıntı Hayatlar * 2*', 'calinti-hayatlar-2-tulay-sustam-3u1tm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saçlarıma bir bir aklar düşünce

Her yıl bir yaş daha gençleşiyorum

Dilek tuttuğum yıldız kaymayınca

Gülüşlerimi Ay''a saklıyorum', 'Saçlarıma bir bir aklar düşünce Her yıl bir yaş daha gençleşiyorum Dilek tuttuğum yıldız kaymayınca Gülüşlerimi Ay''a saklıyorum...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/calinti-hayatlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalıntı Hayatlar * 3*', 'calinti-hayatlar-3-tulay-sustam-727ne', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni çıkardım yirmilik dişimi

Kırkı çıkanlarla bir olmuyorum

Yarıda da bıraksam mektebimi

Bir çocuğu yaşıtım görmüyorum', 'Yeni çıkardım yirmilik dişimi Kırkı çıkanlarla bir olmuyorum Yarıda da bıraksam mektebimi Bir çocuğu yaşıtım görmüyorum...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/calinti-hayatlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ülkücü Kız Sevdim', 'bir-ulkucu-kiz-sevdim-sahin-buber-pa5xc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir  ülkücü kız sevdim

vuruldum gözlerinin karasına

dağılan saçlaranın teline vuruldum

gözlerinin hapsinde buldum aşkı

araladım gönül kapısını

içimdeki yangına su serpsin diye

bir  ülkücü kız sevdim

yiğit mi yiğit

bu asırda zor bulunan

yani delikanlı yürekli

mangal yürekli

türkiyem gibi bir kız sevdim

ülkücü bir kız sevdim

ben divane bozkurt

o deli asena

dayansın artık dağlar

yıkamazlar sevdamı

ipe götürselerde

kurşuna dizselerde

vazgeçmem asla ondan

yalnız tek feryadım var

o da ayrılıktan

bir ülkücü kız sevdim

ela gözlerinde üç hilal

yüreğinde masum bir heyecan

gönül kabemdir o

baharda açan gurbet gülümdür o

peteğimdir balımdır o

bir ülkücü kız sevdim

sesini kattım soluğuma

ılık ılık nefesini hissettim

o ne sesti ama

yağmur gibi berrak

toprak kadar sadık bir sesti

yarabbim can vermeden evvel

onu bir kez görmeyi nasip et

bir ülkücü kız sevdim

moskof diyarlarında yaşayan

ama türkü ve türklüğünü unutmayan

türkiyem gibi saf ve temiz olan

bir ülkücü kız sevdim', 'bir  ülkücü kız sevdim vuruldum gözlerinin karasına dağılan saçlaranın teline vuruldum gözlerinin hapsinde buldum aşkı araladım gönül kapısı...', ARRAY['Türk Edebiyatı','Şiir','Şahin Büber']::text[], 8.5, '{"poet":"Şahin Büber","poet_slug":"sahin-buber","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-ulkucu-kiz-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte İrtica Budur', 'i-ste-i-rtica-budur-kadir-soyturk-i6df4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adım başına çirkef, kokudan geçilmiyor

Kim günahkar, kim masum bir türlü seçilmiyor! 

Şair sen yazmana bak, ne çok ağla, ne de gül

Beyler baş örtüsüyle irtica ile meşgul! 

Bilmezler ki irtica, ışıkların sönmesi

İnsan oğlunun küfre, cehalete dönmesi...

Nice ebu cehilin, başlara taç olması; 

Hastaların doktorsuz ve bi ilaç olması! 

Doğruya adım atmaz, bir kez olsun ayağı; 

Dinime irtica der, irticanın uşağı!', 'Adım başına çirkef, kokudan geçilmiyor Kim günahkar, kim masum bir türlü seçilmiyor!  Şair sen yazmana bak, ne çok ağla, ne de gül Beyler ba...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iste-irtica-budur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Değil Bize..!', 'dost-degil-bize-muharrem-cetinkaya-449o5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak dostum; 

        bu'' tek dişi kalmış canavar''

        dost değil bize,

                   hatta kendine bile...! 

Kırdığımız esaret zincirini,

Altın kelepçe ile takmak ister elimize,

Sahtedir inan O''nun

                                altını bile

Amacı sömürmektir

                  dün olduğu gibi,

                                           bile bile.

Kanımızı emer, 

                       vatanımızı böler,

                                           dün yapamadığını

çağdaş maskesiyle.........bile bile.

     

Kanmayalım beyaz düşlere

Kimde var bizdeki.....yürek

Düşmeyelim birbirimize

Düşmeyelim düşmanın hilesine

Bu vatan bizim

      bizim bu dağlar taşlar

Birlik olalım

          bölünmeden

 Bu bayrak hepimizin

         Yürüyelim arkadaşlar!', 'Bak dostum;          bu'' tek dişi kalmış canavar''         dost değil bize,                    hatta kendine bile...!  Kırdığımız esaret zinc...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dost-degil-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler Sarhoş Olmuş', 'kelimeler-sarhos-olmus-ozan-ozel-vro5f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kelimeler sarhoş olmuş

salınarak geziyorlar aşk dizelerinde

devrilip devrilip kalkıyorlar

düştükleri mısralardan

yürüyorlar hece hece

kafiyesi olmayan gecede

harf olup sızıp kalıyorlar

şiirin koynunda...', 'kelimeler sarhoş olmuş salınarak geziyorlar aşk dizelerinde devrilip devrilip kalkıyorlar düştükleri mısralardan yürüyorlar hece hece kafiye...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kelimeler-sarhos-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henüz Vakit Var...', 'henuz-vakit-var-ahmet-ferit-cosan-snivg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yoğurtlu spagetti

ve 

erkence gelen

intihar haberi.

kıymetli ağabeyim,

otuz üç yaşıma

bir şey kalmadı şurada

misafir kabul eder misin

hiç tanımadığın beni,

kaktüslerle bezeli

tabuttan cumbana? 

o kutlu anında,

o en yalnızlığında,

bilemem

''hangi vasıflardaki vasıta 

birincil tercihindi? 

lakin,

hep 

daha bir asil

daha bir soylucadır bizce

hap...

uykuda huzurla,

..........gözlerin patlamadan,

..............................kıvranmadan acıdan, 

seyrü-sefer dost karanlıklara.

dar gelmeye başladı

kıy(a) metli ağabeyim

şiirimin mısraları. 

tek okuyanı değil,

daha yenice yazanı dahi

boğmakta satırlarım.

sıkıyor sözcükler,

dimağa çarpıp çarpıp

geri zıplayan,

olanca hatıranın

uğultulu basıncından...

dışarıda bayram,

şen gönüller

oradalar hep...

loş derinlerimde isyan,

jiletler ve gözyaşlarım...

iki ayrı(k)  yüzü,

bir gümüşi plakanın...

titrek titrek

bakmaktalar aynaya,

biribirine küskün

ve fakat 

bir o kadar birbirince 

yoldaş gözlerim.

yar bellediğim

uzağıma düşmüş,

uzak alemlerinde

şuh kahkahaları ile

bezemekte sırtlanları...

oysa ben,

tam da bu alemde,

alemin tam da bu cografyasında,

coğrafyanın tam da bu anında,

ölebilsem diyorum,

ölebilsem hapsız, 

ölebilsem metalsiz,

belki bir iple,

niçin olmasın? 

bir ülkü uğruna

dökmek kanını,

yerine kan dökmenin...

yavaş yavaş

sallansam, 

tereddütsüz savrulan

bir tekmenin çiğ sesiyle... 

asude karışsa 

gölgem,

toprak tenhalığına

kızıl avlunun.

için için,

gıcırdasa 

ahşap sehpaha,

yaşanmamışlıkların

pişmanlık dolu 

tonlarca ağırlığıyla...

ip,

metal,

namlu ki

uzunlu inceli bir yol, 

küskün gözleri

dilim dilim doğrayan.

ufak gözenekleriyle

kahpe bir rende şiir,

çekip çekip mutlulukları

küçük küçük parçalayan...

''kendini prens sanan kurbagaya...''

ötelerde anlayışla karşılanman dileği ile Sabri Kaliç', 'yoğurtlu spagetti ve  erkence gelen intihar haberi. kıymetli ağabeyim, otuz üç yaşıma bir şey kalmadı şurada misafir kabul eder misin hiç ta...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/henuz-vakit-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuzlar...!', 'uykusuzlar-muharrem-cetinkaya-z0fzl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nöbeteyim,sınır boyunda

Siz sımsıcak yatağınızda,

            mışıl,mışıl..............

Bilir misiniz tan yeri ağarırken,

Günün doğuşunu,ne güzeldir; 

            ne zamandan beri görmediniz...? 

Yoldayım,şoförüm

Siz sımsıcak.............................

                  ..............................

Dağlar,tepeler aşarım

             karanlıkları deler,

Uyandığınızda yanınızda olur,

                          sevdikleriniz.

İş_teyim,''serseri*'' vardiyası,

siz...........................................

...............................................! 

Makinalar,dişliler,çarklar,

Üretirim......

Uyandığınızda masanızda olur

Kahvaltınız................................

Gece de yaşam devam eder,

Siz........................................

             .................................! 

Sabah kalkarsınız

               deniz mavi,gökyüzü mavi

                doğa yemyeşil  boyalı

  sanırsınız ki kendi oluyor böyle; 

  her şeyi hazır bulursunuz,

  kendi mi olur sanırsınız? 

Kim boyar; denizi,gökyüzünü,doğayı

                   kime güvenir uyursunuz,

hatırlar mısınız hiç; 

                          Sabahlayan uykusuzlar var...!', 'Nöbeteyim,sınır boyunda Siz sımsıcak yatağınızda,             mışıl,mışıl.............. Bilir misiniz tan yeri ağarırken, Günün doğuşunu,ne ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/uykusuzlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem ki Desem mi', 'bilmem-ki-desem-mi-murat-demir-ax5fd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne yapsam ne etsem kimlere desem

Derdimi gidipte kime bildirsem

Bilmem ki yazılı ilan mı versem

Canımı alıyor günden güne o

İçime dert döküp sevda küpüyle

İkiye bölerek hasret tüpüyle

Bilmem ki desem mi azap çöpüyle

Kalbimi deliyor günden güne o

Değirmen misali suyumu tutup

Darı ymışım gibi  ezip öğütüp

Bilmem ki desem mi beni uyutup

Unumu eliyor günden güne o

Bitirip ömrümün murekkebini

Kırıp içimde ki can kalemini

Bilmem ki desem mi dost alemini

Recmime salıyor günden güne o', 'Ne yapsam ne etsem kimlere desem Derdimi gidipte kime bildirsem Bilmem ki yazılı ilan mı versem Canımı alıyor günden güne o İçime dert döküp...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmem-ki-desem-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlün Doysun!', 'gonlun-doysun-muharrem-cetinkaya-qrgfx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Afiyet Olsun! 

         Yarasın

Yarasın da; 

                 helal mi yediğin.....

Aman ha sakın

                 hakkını yeme kimsenin...

Acından ölen var mı; ha kebap yemişsin

                                   ha bulgur...

                                   ha soğan-ekmek.

Yine acıkacaksın unutma akşama,

              ne yediğinin ne önemi var,

              nereye gider baksana! 

Az ye temiz ye,

       doyur gözünü-gönlünü,

        yoksa doymazsın; 

                     yesen Dünya''yı....

                          Mihalıççık Mayıs 2005', 'Afiyet Olsun!           Yarasın Yarasın da;                   helal mi yediğin..... Aman ha sakın                  hakkını yeme kimsenin... ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonlun-doysun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-suha-ardahan-zjp16', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen sevda böler adami 

bin parçaya ayirir çocuk. 

Sevmek istesen de sevemezsin 

                 engelse sadece kendinsin. 

Bazen ask denilen illet 

öyle bir yapisir ki yakana 

çocuk sussan bile gevezelik edersin. 

Tek engel bilesin ki sensin. 

Bazen bazenler öyle hapsederki köseye seni 

                 kendi kendini engellersin. 

Aklina gelir zihnini çeler 

yine de kendini çelmelersin. 

Hata edersin çocuk! 

Özgürlükten dem vururken 

yüreginde pranga pare pare gezersin. 

Çocuk git uyu 

sen bu ask denen illeti çözemezsin...', 'Bazen sevda böler adami  bin parçaya ayirir çocuk.  Sevmek istesen de sevemezsin                   engelse sadece kendinsin.  Bazen ask deni...', ARRAY['Türk Edebiyatı','Şiir','Suha Ardahan']::text[], 8.5, '{"poet":"Suha Ardahan","poet_slug":"suha-ardahan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bazen-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbula kuşbakışı bakmayı özledim...', 'i-stanbula-kusbakisi-bakmayi-ozledim-suha-ardahan-ug6c1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'istanbula kuşbakışı bakmayı özledim... 

alabildigince narsist 

alabildigince bencil 

ve bir o kadar yalniz... 

istanbul beni özledimi fikrim yok...', 'istanbula kuşbakışı bakmayı özledim...  alabildigince narsist  alabildigince bencil  ve bir o kadar yalniz...  istanbul beni özledimi fikrim...', ARRAY['Türk Edebiyatı','Şiir','Suha Ardahan']::text[], 8.5, '{"poet":"Suha Ardahan","poet_slug":"suha-ardahan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/istanbula-kusbakisi-bakmayi-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ençok', 'encok-suha-ardahan-m76oj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ençok gözlerindeki hareleri sevdim.

Dalgaların tırnaklarında ki ojeler gibi beyaz halkaları.

en cok bana eşim diyemeyişine dertleniyorum.

bi isyan değil bu 

      ki söz verdim sana. 

en çok melegim olmanı seviyorum.

hatalarımla senin olmayı. 

en cok seni seviyorum demeni 

beni benden alıp senle birlikte 

                                tanrı olmayı', 'Ençok gözlerindeki hareleri sevdim. Dalgaların tırnaklarında ki ojeler gibi beyaz halkaları. en cok bana eşim diyemeyişine dertleniyorum. bi...', ARRAY['Türk Edebiyatı','Şiir','Suha Ardahan']::text[], 8.5, '{"poet":"Suha Ardahan","poet_slug":"suha-ardahan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/encok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçarcasına bir sevda', 'kacarcasina-bir-sevda-suha-ardahan-qy7ik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaçarcasına bir sevdaydı,

ayaküstü aşklar da yaşandı İstanbulun göbeginde.

İstanbulda bir guzel vardı. 

İstanbul da kıskandı. 

Sonra cekip gitti doyamadan. 

Ortaköyde biraya bulanmak da yetmedi 

                       yorgun yüreğime. 

Doyamadan gitti işte. 

SONRASI yok..!', 'Kaçarcasına bir sevdaydı, ayaküstü aşklar da yaşandı İstanbulun göbeginde. İstanbulda bir guzel vardı.  İstanbul da kıskandı.  Sonra cekip g...', ARRAY['Türk Edebiyatı','Şiir','Suha Ardahan']::text[], 8.5, '{"poet":"Suha Ardahan","poet_slug":"suha-ardahan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kacarcasina-bir-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbula dair...', 'i-stanbula-dair-suha-ardahan-ar0w7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbula dair düşlerim vardı. 

Düş olarak kaldı onlar. 

İstanbulda bir düşlediğim vardı. 

Usumdan düştü ötelerde kaldı. 

O yine ötelerde umutlar yine bana kaldı. 

Sana dair düşlerim vardı. 

Onlar yapıştı, yürekde kaldı.', 'İstanbula dair düşlerim vardı.  Düş olarak kaldı onlar.  İstanbulda bir düşlediğim vardı.  Usumdan düştü ötelerde kaldı.  O yine ötelerde um...', ARRAY['Türk Edebiyatı','Şiir','Suha Ardahan']::text[], 8.5, '{"poet":"Suha Ardahan","poet_slug":"suha-ardahan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/istanbula-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün gelecek', 'gun-gelecek-suha-ardahan-2ebly', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün gelecek

gün güzele dönecek

gün olacak, güzel gözlerimde ölecek..

gün bitecek 

dün düzene uyacak

yarın diye bildiğin gün

bugünün kendisi olacak

değişecek,dirilecek, düzelecek

düne dair tasalar...

güne dair sevdalar yarına miras kalacak...

gün biter yarın da bitecek

tıpkı yaşadığın dünler gibi..

öğüdüm tüketme umutları

hayat dediğin değil mi ki yaşamak

doğumla ölüm arasındaki

hataları', 'Gün gelecek gün güzele dönecek gün olacak, güzel gözlerimde ölecek.. gün bitecek  dün düzene uyacak yarın diye bildiğin gün bugünün kendisi ...', ARRAY['Türk Edebiyatı','Şiir','Suha Ardahan']::text[], 8.5, '{"poet":"Suha Ardahan","poet_slug":"suha-ardahan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-gelecek-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç kimse?', 'hic-kimse-suha-ardahan-mvlw3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni hiçkimse SENiN kadar SEVMEDi Ki,

Sana dair düşlerimi hiçkimseyle üleşmedim ki,

Hiç kimse; 

Penceremin önündeki gün ışığı,

Hiçkimse ruhumdaki şen aşığı,

Hiçkimse görmedi ki,

Hiçkimse bana EŞ olmadı ki,

Beni hiçkimse senin kadar SEVMEDi Ki...', 'Beni hiçkimse SENiN kadar SEVMEDi Ki, Sana dair düşlerimi hiçkimseyle üleşmedim ki, Hiç kimse;  Penceremin önündeki gün ışığı, Hiçkimse ruhu...', ARRAY['Türk Edebiyatı','Şiir','Suha Ardahan']::text[], 8.5, '{"poet":"Suha Ardahan","poet_slug":"suha-ardahan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hic-kimse-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telli Kavak, Duvaklı Kavak', 'telli-kavak-duvakli-kavak-i-smet-barlioglu-f5uxv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden benzetiyorum bu kavağı sana? 

Senin gibi narin ve zarif olduğu için mi? 

Yaprakları parladığı için mi saçın gibi,

Bedeni dal gibi, zirvesi hilal gibi olduğu için mi? 

Senin gibi salındığı,

Benden kaçmadığı,

Okşamama izin-ruhsat verdiği için mi? 

Neden benzetiyorum güneşte hışırdayan kavağı sana? 

Anlasana anam-babam,

Anlasana.

Deniz bir tablo gibi körpe kavağımın arkasında,

Kavağımda tatlı hışırtılar,

Yıldızlar misali göz kırpan pırıltılar,

Güneşler geziniyor kavağımın körpe yapraklarında,

Geziniyor, geziniyor, geziniyor,

Sonra yerine sen gelip salınıyorsun,

O gidiyor.

Sen sen olmasan; ötüşür mü dallarında

Körpecik serçeler binbir sevinçle? 

Musikiyle mi bezenir hiç, her biri dalın, yaprağın? 

Bir melodi anıtı gibisin

Üstünde toprağın.

Yavaş yavaş anlıyorum sana neden benzettiğimi

Bir körpecik telli kavağı; 

Yaprakların masallardaki duvak,

Dalların bir gelinliğin tellerince,

Ben hep seni anıp duruyorum günler boyu

Ne zaman bir kavağa rastlasam; 

Yeterince.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 25-26/100)', 'Neden benzetiyorum bu kavağı sana?  Senin gibi narin ve zarif olduğu için mi?  Yaprakları parladığı için mi saçın gibi, Bedeni dal gibi, zir...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/telli-kavak-duvakli-kavak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Doldurdum Odama', 'seni-doldurdum-odama-i-smet-barlioglu-atybb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açıverdim bu gece pencerelerimi ardına kadar,

Seninle tıka basa doldurdum ıssız odamı,

Sana buyur ettim kapılarımdan,

Sana açtım köşemi-bucağımı,

Senin için kilimler serdim döşemelere,

Yolluklar uzattım kapıdan divanlara,

Masalar donattım, Tanrı ne verdiyse.

Zira; senin tenezzül edip bana konuk olman

Hadise.

Seni doldurdum odama, anam-babam,

Döşemeden tavana, duvardan duvara, pencereden pencereye,

Çiçek yerine seni koydum vazolara,

Resminin yerine seni astım duvarlara,

Seni her yana yağdırdım gül yaprakları misali,

Rengarenk şeritler gibi tutturdum köşelerden köşelere,

Seni serptim altından pullar misali

Her yere.

Kollarımı açtım sana açabildiğimce,

Seni kucakladım, sana sarıldım,

Seni öptüm, seni kokladım,

Geceleyin sabaha kadar yüzdüm mutluluklar içinde.

Yatamadım.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 27-28/100)', 'Açıverdim bu gece pencerelerimi ardına kadar, Seninle tıka basa doldurdum ıssız odamı, Sana buyur ettim kapılarımdan, Sana açtım köşemi-buca...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-doldurdum-odama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün Yeter Bana', 'gulusun-yeter-bana-aysel-al-x5igj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitsen de gelmesen de,

Aşkımı bilmesen de,

Gözyaşımı si lmesende

Gülüşün yeter bana! ...

İstemem dünya malı,

Uğrunda oldum deli,

Öyle candan neşeli,

Gülüşün yeter bana! ...

Bir şey istemem senden,

Kurtulamazsın benden,

Yıllardır resimlerden,

Gülüşün yeter bana! ...

Aysel''in sele düştü

Aşkınla yandı pişti,

İmdadıma yetişti

Gülüşün yeter bana! ...', 'Gitsen de gelmesen de, Aşkımı bilmesen de, Gözyaşımı si lmesende Gülüşün yeter bana! ... İstemem dünya malı, Uğrunda oldum deli, Öyle candan...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulusun-yeter-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşa Kurmuşum İskeleleri', 'bosa-kurmusum-i-skeleleri-i-smet-barlioglu-078xq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çilelerindeyim yıllar yılı,

Azaplarındayım,

Özlemlerinde, ayrılıklarındayım,

Kalmışım bir başıma gaiplerden imdat dilenip

Ve bir gün kurtulacağıma güvenip.

Neye uğradığını bilmeyen garipler gibiyim; 

Düşmüşüm ne idiğü belirsiz bir toprağa,

Yakınımdan geçip gitmiş cümle gemiler

Varlığımı bile beraber alamayıp.

Ölü gözündeki yaşa bağlamışım umutlarımı

Ağlayıp.

Alışamadım gitti kalabalıklar içinde sensiz yaşamaya,

Çığlıklara çevirdim kendimi, belki duyarsın diye,

Ömrümü yaktım yıllar yılı, imdat ateşi olarak,

Neye niyet, neye kısmet; 

Kendi ateşimde kendim yandım, anam-babam,

Sabah,

Akşam.

Boşa kurmuşum iskeleleri bir hayırsız denizde,

Boşa dikilmişim kıyılara ömür boyu,

Boşa bekçi etmişim gözlerimi,

Boşa bırakmışım işimi-gücümü.

Gün-akşam etmemişim,

Aylar, yıllar dememişim.

Boşuna…

Ne zaman geleceğini söylese de,

Ne zaman dineceğini söyler mi

Fırtına? 

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 29-30/100)', 'Çilelerindeyim yıllar yılı, Azaplarındayım, Özlemlerinde, ayrılıklarındayım, Kalmışım bir başıma gaiplerden imdat dilenip Ve bir gün kurtula...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bosa-kurmusum-iskeleleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorsun', 'biliyorsun-aysel-al-fdtrn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yanıyorum aman, aman! 

Bu hasretlik ne de yaman,

Anılara zaman zaman

Daldığımı biliyorsun...

Duy! Duy artık niyazımı! 

Kar kapladı son yazımı,

Dertlidertli aşk sazımı

Çaldığımı biliyorsun...

Yüreğim dolu yara,

Dargınım sensiz yıllara,

Şu başımı belâlara

Saldığımı biliyorsun...', 'Yanıyorum aman, aman!  Bu hasretlik ne de yaman, Anılara zaman zaman Daldığımı biliyorsun... Duy! Duy artık niyazımı!  Kar kapladı son yazım...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biliyorsun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat Gibi...', 'saat-gibi-i-brahim-ethem-bingul-bjrx7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayranıyım ahengine

Tıkır tıkır çalışır

Yirmi dört saat

Kesintisiz...

İhmali sevmez

Yorulmayı bilmez

Durduğu görülmez

Sebebsiz...

Ters düşmez zamana

Çalışmayla yarışır

Zamanda at koşturur

Duranlarla boğuşur

Bir kahramandır

İsimsiz...

Gece, gündüz

Tatil, bayram fark etmez

Her şehirde, her ülkede

Hep ilerler, çark etmez

Hedefi hep ileriye

Geri kalanlar onun gözünde

Sevimsiz...

Yürümek

Her gün, her saat nakarat

Bir kırpıntı her saniye

Geçmiş de kendinden

Derunî  tefekkürde, zikirde

Duyduğu haz 

Tarifsiz...

Ufku ne kadar berrak

Serüveni sesinde

Tik- tak... Tik-tak...

Çalışmayı iş edinmiş

Terk etmez

Saatten ibret almayan

Zannımca hissiz...

www.iebingul.com', 'Hayranıyım ahengine Tıkır tıkır çalışır Yirmi dört saat Kesintisiz... İhmali sevmez Yorulmayı bilmez Durduğu görülmez Sebebsiz... Ters düşme...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/saat-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Şeherindeki Kadına', 'hayal-seherindeki-kadina-koksal-akar-u7mr0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hicrândı yokluğunu ruhumda saklı kılan,

sevdayı gözlerinde bana yasaklı  kılan.

mahşer ki, yükseliyor arşa zerresi âh’ın

her nefes bir kıvılcım, yandıkça körüklenen

bir ah ki çırpınıyor yüreğinde sabahın

mecnun’dan bilirim ki gelmeyecek beklenen

anladım bir hiçliğin peşine düştü adın

ey gözleri sevdaya hep gülümseyen kadın

her gece yalnızlığı arzulasa da ruhun

göklerinden merhamet düşer aşkın bahtına

visâlin gecesine gem vursa da  gürûhun,

baykuş konabilir mi bülbüllerin tahtına

silemezsin, bahtına gizlenen bunca kiri

ruhunda fettan yazan fikrimin muhariri! 

bilseydim gece-gündüz ardından ağlar mıydım

sever miydim bilseydim gözlerini bir hiçin

hep durgun bir nehirken coşup da çağlar mıydım

şimdi hücrelerimde çırpınıyor bir niçin

bir leyla gerek olsa bile istemem seni

dermanımdır bilsem de hülyamdaki bûseni

istemem sende kalsın yalnızlığın her rengi

gözlerinden gerçeğe çıkan yol bana yeter

istemem bu şarkıyı şarkıdaki ahengi

bir acı düşlüyorum, hicrândan daha beter', 'hicrândı yokluğunu ruhumda saklı kılan, sevdayı gözlerinde bana yasaklı  kılan. mahşer ki, yükseliyor arşa zerresi âh’ın her nefes bir kıvıl...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayal-seherindeki-kadina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğret bana öğretmenim...!', 'ogret-bana-ogretmenim-muharrem-cetinkaya-yjheq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öğret bana öğretmenim

           okumayı-güzel yazmayı

           düşünmeyi,hesap yapmayı.

Ögret bana öğretmenim,

            tarihimi,geleceğimi

            geleneğimi,göreneğimi

Bana öğret öğretmenim,

            vatanımın,bayrağımın,değerlerimin

            kıymetini,değerini.

Öğret bana; 

             öğrenmeyi,öğretmeyi

             bilimi,teknolojiyi

Öğret........................................

             vatanıma göz diken

             düşmanla mücadeleyi

Ben senin eserin; 

              iyiyi,doğruyu güzeli

              aklı,fikiri,ilimi,irfanı,

Öğret beni öğretmenim,

              beni öğrenmenin esiri

              çalışmanın tutsağı yap...!', 'Öğret bana öğretmenim            okumayı-güzel yazmayı            düşünmeyi,hesap yapmayı. Ögret bana öğretmenim,             tarihimi,gelec...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ogret-bana-ogretmenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-abdurrahim-karakoc-6u80b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Rahmetli babam Ümmet Karakoç''a aittir...)

Deli gönül kalktı yoldaş arıyor

Uyan gelsin Muhammed''in aşkına

Masivadan üryan edip sinesin

Soyan gelsin Muhammed''in aşkına

Bu yolda gidenler dertli olmasın

Yükü arkasında katlı olmasın

Ağa-paşa gibi atlı olmasın

Yayan gelsin Muhammed''in aşkına

Aldanmayıp şu dünyanın barına

Göz dikmeye şöhretine-şanına

Mansur gibi dar üstünde canına

Kıyan gelsin Muhammed''in aşkına

Bir gün deriliriz mahşer divana

Hepimiz muhtacız kâmil imana

Dört mezhebi bilip Oniki İmam''a

Uyan gelsin Muhammed''in aşkına

Oniki İmam''dan alsın dersini

Gözetmesin bu dünyanın hırsını

Dalıp Bahr''ummana gönül pasını

Yuyan gelsin Muhammed''in aşkına

Merdaneler bu yollarda yürüye

Yüreğinde yağ kalmayıp eriye

Ehl-i evlâdını atıp geriye

Koyan gelsin Muhammed''in aşkına

Bu yola gideni gelmez diyorlar

Eyi hayat icra olmaz diyorlar

Hak''tan gayrisini görmez diyorlar

Duyan gelsin Muhammed''in aşkına

Dünya senin olsa bir top bez hakkın

Kime vefa kıldı bu cihan bakın

Hazreti İsmail gibi ben hakım

Diyen gelsin Muhammed''in aşkına

Dünya benim diye dava edersin

Bir gün olur hepsin koyup gidersin

Bir top bez de bulunmazsa ne dersin

Üryan gelsin Muhammed''in aşkına

Kul Ümmet''im der de bir bade içip

Ve cümle mahlukat kendinden geçip

Azrail gelmeden kefenin biçip

Giyen gelsin Muhammed''in aşkına.

Ümmet Karakoç', '(Rahmetli babam Ümmet Karakoç''a aittir...) Deli gönül kalktı yoldaş arıyor Uyan gelsin Muhammed''in aşkına Masivadan üryan edip sinesin Soyan...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/davet-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmak uçlarımda...sessizce....', 'parmak-uclarimda-sessizce-sila-nur-koken-e0rsd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar sürdü yokluğunuz

sonunda gittim ben

şimdi kim duymak isteyecek 

söylenmeyen sözlerinizi

kim bakacak 

olmayan gözlerinize

kim isteyecek 

hüzünlü ellerinizi

kim omuzlayacak

vermediğiniz dertlerinizi

gittim ben

şimdi kim ağlayacak

duvarlarınıza bakıp bakıp...

kim bekleyecek

elinde anahtar

karşıda kilit

uzanmadan

bekleyip

gittim ben

şimdi kim kalacak

dur dediğiniz 

bekle demediğiniz yerde

sabır örerek

ilmik ilmik

göz göz

yürek 

gittim ben

siz hepiniz kaldınız geride

bir başınıza..

siz

suskunluğunuz

yokluğunuz

duvarlarınız

belki de

umut ederek

oradadır diye

Ama bilmem duydunuz mu

gittim ben

parmak uçlarıma basarak

ve gülümseyerek

sessizce...

(16 Mayıs 2005)', 'Yıllar sürdü yokluğunuz sonunda gittim ben şimdi kim duymak isteyecek  söylenmeyen sözlerinizi kim bakacak  olmayan gözlerinize kim isteyece...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/parmak-uclarimda-sessizce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunun Esiriyim', 'yoklugunun-esiriyim-muharrem-cetinkaya-sv2sr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sabah güneşin doğuşuyla,

        salar yeryüzüne

        akşama kadar güderim

                                               hüzünlerimi.

Doyurur, sularım gün boyu

                     akşam olunca

sayım yaparım,doldurur gönlüme,

uyuturum sonra da

                              ninni söylerim

                                                      hepsine ayrı ayrı.

Bir senin yokluğun

                                isyankâr,

       gün boyu firar

       zamansız girer gönlüme

                         olmadık yerde

                         olmadık zamanda.

Bir tek senin yokluğunu güdemem,

                       Aykırı senin...............

Ne uyku bilir,

                    ne de ninniden anlar.

Prangaya vursam,zaptedemem

Benim elim kolum bağlı

             O''nun varlığı,senin yokluğun

Anlamadım; 

Ben mi O''nun tutsağı_

                     O''mu benim esirim!', 'Her sabah güneşin doğuşuyla,         salar yeryüzüne         akşama kadar güderim                                                hüzünlerimi...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yoklugunun-esiriyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamalıydın', 'anlamaliydin-dilek-eliagir-49gyv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlamalıydın…

Haykırışlarımdan….

Biliyor olmalıydın…

Seni  nasıl sevdiğimi…

Olmadı …

Olmadı…

Yanlış nerde başladı nerde bitti

Bilinmez….

Sana yanlışsın diyemem…

Kıyamam sana…

Yanlış olan ben olayım

Sen kal öyle…

Olduğun gibi…

Benzeme hiç kimselere

Bırak ben..

Hayalinle avunayım…', 'Anlamalıydın… Haykırışlarımdan…. Biliyor olmalıydın… Seni  nasıl sevdiğimi… Olmadı … Olmadı… Yanlış nerde başladı nerde bitti Bilinmez…. San...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eliağır']::text[], 8.5, '{"poet":"Dilek Eliağır","poet_slug":"dilek-eliagir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlamaliydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul''u Almada Gayret Et!', 'istanbul-u-almada-gayret-et-huseyin-avdic-vbfm0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Allah ilham ediyor ki:

Istanbul''u almada, haydi Mehmed gayret et.

Ne olursa olsun, bir hayali hakikat et.

Berlin,  20 Mayis 2005.

(Fetihe 09 kala)', 'Allah ilham ediyor ki: Istanbul''u almada, haydi Mehmed gayret et. Ne olursa olsun, bir hayali hakikat et. Berlin,  20 Mayis 2005. (Fetihe 09...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/istanbul-u-almada-gayret-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir garip hazan', 'bir-garip-hazan-dilek-eliagir-bidv8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir garib hazandır vakit…

Gel desem …

Gelmessin yar….

Git desem…

Çıkmıyorsun ki aklımdan …

Ne seninle..

Ne de sensiz…..

Geçmiyor…yar…

Geçmiyor işte….

Sensiz tadı yok…

Bu Ankara”nın…

Sensiz adı yok…

Günlerin.…

Sensiz…

Anlamı yok…

Düşlerin…

Seni…düşünüyorum…..

Düşünmemem lazım…..

Ama sözüm geçmiyor…

Geçmiyor işte….', 'Bir garib hazandır vakit… Gel desem … Gelmessin yar…. Git desem… Çıkmıyorsun ki aklımdan … Ne seninle.. Ne de sensiz….. Geçmiyor…yar… Geçmiy...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eliağır']::text[], 8.5, '{"poet":"Dilek Eliağır","poet_slug":"dilek-eliagir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-garip-hazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-tuba-celik-dicfh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hadi bir kurşun da sen sık bana! 

Zararı yok, alıştım.

Nereye gitsem bir gölge gibi,

Önümde yürür kadınlığım.

Zor şeydir bilemezsin... 

Ne ezerim, ne de yakalarım.

Yaptıklarımı gizler boyuna, bana inat.

Ben çalışır yorulurum,

O yan gelir yatar, 

Yine de kadın! ...', 'Hadi bir kurşun da sen sık bana!  Zararı yok, alıştım. Nereye gitsem bir gölge gibi, Önümde yürür kadınlığım. Zor şeydir bilemezsin...  Ne e...', ARRAY['Türk Edebiyatı','Şiir','Tuba Çelik']::text[], 8.5, '{"poet":"Tuba Çelik","poet_slug":"tuba-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kadin-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen giderken', 'sen-giderken-dilek-eliagir-xm1uc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen giderken….

Şiirler okuyordum ben…

Adı sanı belli olmayan…

Sen giderken..

Hayaller kuruyordum…

Hemde en olmayacaklardan….

Sen giderken …

Şarkılar söylüyordum…

En güzel namelerden…

Sen giderken…

Düşler görüyordum…

En hayırlılarından….

Sen giderken…

Sigaramdan derin bi nefes

Çekiyordum en acısından….

Sen giderken…

Masallar anlatıyordum kendime…

Hatta bazen ben bile gerçek

Sanıp inananasım geliyordu…

Sen giderken ….

Dualar ediyordum Rabbime…

“Seni korusun” diye….

Velhasıl…

Sen benden giderken….

Ben bende değildim aslında…', 'Sen giderken…. Şiirler okuyordum ben… Adı sanı belli olmayan… Sen giderken.. Hayaller kuruyordum… Hemde en olmayacaklardan…. Sen giderken … ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eliağır']::text[], 8.5, '{"poet":"Dilek Eliağır","poet_slug":"dilek-eliagir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-giderken-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Sen Koy', 'adini-sen-koy-umit-engin-qmezl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Belirsiz korkuların oluyorsa zamansız, içini bir ürperiti sarıyorsa ve cevabını bilmediğin sorular çıkıyorsa karşına hiç durmadan, sebebi bir tek benim.  Olmuyor! Ne kadar denesemde, istesemde kendimi senden alamıyorum. Çoğu zaman arzularımın, isteklerimin önüne geçemiyorum. Tüm bunların yanında çaresizliğin,  çaresizliğine karşı bastıramadığım duygularım, incitiyor bizi. Doğrular? Yanlışlar?  İstekler? Arzular? Sen? Ben? Bazen neler oluyor bize mi diyorsun? Herşey bukadar güzelken içindeki burukluğumu sorguluyorsun? O buruk  benim.  Anlam veremediğin, içinde kaybolduğun herşeyim ben…

 

16.05.2005 / 10:50 / ümit engin', 'Belirsiz korkuların oluyorsa zamansız, içini bir ürperiti sarıyorsa ve cevabını bilmediğin sorular çıkıyorsa karşına hiç durmadan, sebebi bi...', ARRAY['Türk Edebiyatı','Şiir','Ümit Engin']::text[], 8.5, '{"poet":"Ümit Engin","poet_slug":"umit-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/adini-sen-koy-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Traş,,,,,,,*', 'tras-muharrem-cetinkaya-4hlsh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '--tanıdık biri-

Sereserpe uzanıp,

                   yatıverdin,

    elalem ne der sonra bize,

                                             yapma! 

Çağdaşlık mı,

                       modern görüş mü,

                                                    ben

anlayamadım...! 

                      .........................açıkta! 

Belki ben geri kafalıyım,

          ya da kafam geride,

Ama senin kafan nerede? 

               --tanımadık  biri- 

Etek_se

              dizde olur,

                    hadi  biraz daha yukarı....

Ama senin ki taa baldırda; 

          yoldan geçenler traş olsun(!) : 

             ......biraz daha kaldırda...! 

                             Not (beni alakadar etmez,kimin ne giydiği)', '--tanıdık biri- Sereserpe uzanıp,                    yatıverdin,     elalem ne der sonra bize,                                              ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tras-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'isimsiz bir siir; (Özo''ma)', 'isimsiz-bir-siir-ozo-ma-diyar-serdar-yildiz-yfz4k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deli bir cocuk sevinciydi, 

Ve bir annenin 

ilk yavruya olan özleminde 

Bir bebegin ilk anne,baba derken 

verdigi tarifi imkansiz duyguda gizliydi...

Ve aldirmaz bir kosusturmaydi 

Daracik sokaklarinda, cocuklugumun

Bitmeyen bir türküydü dilden dile söylenen

Bir isyan di KAWA hakliliginda

Örse inen cekicin sicakliginda

Bir direnisti Dersim boylarinda.

Seyit Riza''yla vucut bulan bir haykiris, 

Agucan diyarinda dilenen bir adak.

Icilen bir tas suydu gözelerinde Munzur''un,

Ve o kutsal topraklarin kutsanmisligiydi

Ve sendin sevgili; bir anlami

Yüreginin carpintisi

Gözlerinin isiltisiydi 

O saclarinin rüzgarda savrulusu,

Bir kamci misali carpmasiydi 

Suratina halden bilmezin.

Böyledi bilesin ey gülbenizli,

Dersim gözlü,Munzur yüzlü yar

Yasam di; nam-i diger sende vucut bulan

Ve ben sana vurgunum ey yar...', 'Deli bir cocuk sevinciydi,  Ve bir annenin  ilk yavruya olan özleminde  Bir bebegin ilk anne,baba derken  verdigi tarifi imkansiz duyguda gi...', ARRAY['Türk Edebiyatı','Şiir','Diyar Serdar Yıldız']::text[], 8.5, '{"poet":"Diyar Serdar Yıldız","poet_slug":"diyar-serdar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/isimsiz-bir-siir-ozo-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Sütü', 'kus-sutu-muharrem-cetinkaya-gsgk2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün akşam ki alemde

                 her şey vardı,

                 ve de herkes,

yedik,içtik,eğlendik

          gün doğana dek.

Bir kuş sütü eksikti masamızdan,

bir de sen.

Yoksa sen,

       kuş sütü müsün...!', 'Dün akşam ki alemde                  her şey vardı,                  ve de herkes, yedik,içtik,eğlendik           gün doğana dek. Bir kuş sü...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kus-sutu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teğet.. (Bir Düzüne Deneysel Mısra)', 'teget-bir-duzune-deneysel-misra-i-brahim-ozcan-v9zgb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir

ge ce

se nin le

se vi şir ken

a yı dü şür  dük 

kaç  pen ce re miz den

yıl dız lar da  gül müş tü

za man ön ce si bir yer den

mil yar  ı şık  yı lı  ev  vel den

u nu tu lur mu  bu   ey sev gi li

hüz nü müz  te ğet  geç se de  sa hil den

son suz luk  vur ur ken  böğ rü ne de niz den

19 Mayıs 2005

 Kocahasanlı', 'bir ge ce se nin le se vi şir ken a yı dü şür  dük  kaç  pen ce re miz den yıl dız lar da  gül müş tü za man ön ce si bir yer den mil yar  ı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/teget-bir-duzune-deneysel-misra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın Ya...!', 'anlarsin-ya-muharrem-cetinkaya-im0i8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yokluğunu boyadım,

 Her renge,

        rengarenk...

Uymadı,

            istediğim gibi olmadı.

Sonra geçip karşına oturdum,

            düşündüm ne renk olsun diye,

karar verdim; 

          buldum; 

.............................rengi

Anlarsın ya...!', 'Yokluğunu boyadım,  Her renge,         rengarenk... Uymadı,             istediğim gibi olmadı. Sonra geçip karşına oturdum,             düşü...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anlarsin-ya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Sevgiliden Dertli!', 'herkes-sevgiliden-dertli-muharrem-cetinkaya-tmpuy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biraz sana benziyor herkes,

          baksana kime sorsam

                                    dertli! 

Kime acacak olsam derdimi

           herkes benden gamlı-kasevetli! 

Kim icat eder bu dertleri........! 

                 kim bulur getirir. 

Biraz sana benziyor herkes,

   __________baksana 

                 herkes sevgiliden dertli!', 'Biraz sana benziyor herkes,           baksana kime sorsam                                     dertli!  Kime acacak olsam derdimi            ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/herkes-sevgiliden-dertli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatoş.', 'fatos-seref-karakulah-cwhpd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kez sen değil

Yokluğun var gözlerimde

Sigara dumanımı onları yaşartan

Yoksa özlemin meyvelerimi.

Ne olur tersine dönse dünya

Geleceğe umutla baksa insanlar

Mutluluk saçılsa gökyüzünden

Bu gece ''Bu'' dese dudaklar.

Simsiyah hayallerim pembeye dönüşse

Tanrım saadette varmış yeryüzünde.

Neden renklerden siyahı

Çiçeklerden gülü seviyorum

Ve  neden alkol dolaşıyor damarlarımda.

.................................................... ! 

Çünkü seni seviyorum  Fatoş.

(1974 Ankara) .', 'Bu kez sen değil Yokluğun var gözlerimde Sigara dumanımı onları yaşartan Yoksa özlemin meyvelerimi. Ne olur tersine dönse dünya Geleceğe umu...', ARRAY['Türk Edebiyatı','Şiir','Şeref Karakülah']::text[], 8.5, '{"poet":"Şeref Karakülah","poet_slug":"seref-karakulah","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fatos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hasan’ a Mektup / 8 (Serzenişlerim)', 'hasan-a-mektup-8-serzenislerim-ahmet-turan-altunsu-pmnii', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '/ karındaşım uzaklarda / gözden ırak, sözden ırak / Bitlis, Bingöl, Muş son durak / aklım fikrim tuzaklarda...

/ ne arayan var, ne soran  / kahroluyor Ahmet Turan / Hasan karındaşsız yaren  / dil, gönül lal; yasaklarda...

uzak aralar da yazamaz olduk artık...

selâm sabah hak getire! ..

hani, o çok kızdığın zamanlar 

yiğitçe haykırışlar nire,

gözlerinden püsküren ateşler nire? ..

ya o öfkeyi yazdığın zamanlar? ..

selâm sabah hak getire! ..

okuduk; eşkıyalar parsellemiş dağlarını...

yeter ki düşman biline; 

bulursun çaresini, bilirim! ..

ne var ki çok zamandır Hasan,

omuzlarımdaki yükün altında ezilirim! ..

bir delişmen poyrazın

yüreğime buz gibi çarpmasına üzülürüm! 

üşürüm de karındaşım,

iki büklüm büzülürüm! ..

kolay değil karındaşım, dertlerle boğuşuyorsun...

dağda eşkıya, göl kıyısında bir çingene...

- ah be Hasan; dün seni sordu gene! .. -

bir de benimle uğraşma, bırak dursun...

- desem de inanma sakın -

dursun durmasına ya biliyorum, hissediyorsun

- çalmalı davul dengi dengine -

 duyar gibi oluyorum: ‘delisin sen’, diyorsun! ..

dinle beni be Hasan, söylemek zorundayım! 

bir yanar ki içim; pir yanar! ..

tam kıvamında yüreğim; sevda pazarındayım,

devasa yaralarım her gün yeniden kanar...

say ki, adı uçmak olan bir sonun huzurundayım...

sende şaşkın bir çingene, bir delişmen sevda bende; 

ben, o delişmen sevdanın doyulmaz nazarındayım

bir de maruzatım var; 

dolaşır bugünlerde ortalıkta bir çapar...

şikâyetçiyim sivri dilli dost(!)        larımızdan! ..

terk ettiler mahfilimizi apar topar...

şüpheleri mi varmış da şiarımızdan; 

bir kaşık su içinde bunca kasırga kopar? ...

tez dönesin karındaşım, Ankara’ nın ahvali bu,

ardı sıra dizilmiş günahların vebali bu...

“...dön gel ağam, dön gel; dayanamirem,

-uyku, gaflet basmış; uyanamirem...”

-20.05.2005 / Ankara

-Ahmet Turan Altunsu', '/ karındaşım uzaklarda / gözden ırak, sözden ırak / Bitlis, Bingöl, Muş son durak / aklım fikrim tuzaklarda... / ne arayan var, ne soran  / ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/hasan-a-mektup-8-serzenislerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gool(KK)', 'gool-kk-muharrem-cetinkaya-8ldck', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizim forma vardı sırtında

                      siyah-beyaz

                         9 numara,

pas attın,

pas verdik,

çalım,çalım,çalım

attıkların ya taç

               ya aut! 

Ne bu canım! 

Faullerine aldımadık,

                               her yerimiz yara-bere! 

kaptan bile yaptık,sonunda

             gücün bize yetti! 

Hiç ummazdık senden,ey sevgili

                            bizim pasımızla; 

-35 metreden sert şut; - 

                                  gol attın,

bizim kaleye!', 'Bizim forma vardı sırtında                       siyah-beyaz                          9 numara, pas attın, pas verdik, çalım,çalım,çalım att...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gool-kk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanım', 'vatanim-lokman-ali-yavuz-q4uja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana kavuşana dek’ti

Yüreğimdeki VATANIM,

Gördüm ki,

Sen değildin yüreğimde yatanım.', 'Sana kavuşana dek’ti Yüreğimdeki VATANIM, Gördüm ki, Sen değildin yüreğimde yatanım....', ARRAY['Türk Edebiyatı','Şiir','Lokman Ali Yavuz']::text[], 8.5, '{"poet":"Lokman Ali Yavuz","poet_slug":"lokman-ali-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vatanim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saatler Vardır', 'saatler-vardir-tahsin-ozmen-cwcpx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duvarlarda asılı yorgun zamanlar vardır.

Renkleri solmuş fotoğraflar gibi,

yüzlerini suskunluğa dönmüşlerdir.

Bir bakışın içinde saklı kalmış vedalar,

bir gülüşün ucunda kırılmış hatıralar vardır.

.

Duvarlarda asılı yaşlanmış hatıralar vardır.

Yüzlerini geçmişe dönmüşler ve dilsiz bir ağıtı fısıldamaya başlamışlardır.

Işıltılarını kaybetmişler ve soğuk bir sessizliği kuşanmaya başlamışlardır.

.

Aynalarda kulaklarına hatıra takan yorgun kadınlar vardır.

Odalarında saçlarını tarayan kederli kadınlar vardır.

Sırlı camlarda ansızın beliren çizgilerden kurtulmayı bekleyen gençlikler vardır.

.

Bir el uzanır.

Zarif, parmak uçlarında gümüş tozları, anneanne kokulu dualar ile.

Aynalarda kırılmalarından korktuğum yüzler vardır.

O ellerden kayıp yere saçılmalarından korktuğum.

.

Aynalar vardır.

Suretler vardır.

Kırıklar vardır.

Fakat,

saatler vardır.

İçinde bir kalbin değil,

bir ömrün attığı.

(Ne çok yakışır bir genç kızın nabzının attığı narin bileklere.)

.

Zamana direnişin adıdır saat.

Unutuşa karşı mücadelenin.

Mimarıdır ilk randevunun. Düzenin…

.

Önceleri metal kayışları vardı.

Sonra plastik oldular.

Rengarenk oldular. sarı oldular, kırmızı, yeşil, pembe…

Sesli oldular. Işıklı oldular.

Önceleri kurmalı saatler vardı.

Sonra pilli oldular.

Dijital oldular. (Duygu fukarası rakamları soğuk, ışıkları donuk…)

.

Çocukların serveti

Çocukların ilk hediyesi

Çocukların babalık oyunu idiler.

Erkeklerin tek süsü, gençlerin randevu telaşı oldular. Annelerin bakışında endişe oldular. Yastık altlarında tiktaklarıyla uykuları bölen bekleyişler oldular. Bekleyişlerin en sadık tanığıydılar…

.

Saatler vardır.

Tozlu raflardan indirilmiş kutuların arasında bir kadife içinde,

unutuluşun eşiğinde bir ömrü

ana iliştiren.

Bileklerdeki ince damarların üzerinde...

Yorgun adamların ellerinde.

Ne zaman bir yelkovan görsem kovalayan akrebi,

Nefesinin kesilip duracağından korkarım.

Ne zaman bir eski saat görsem bir masada duran,

Aklıma gidişin gelir.

Ne zaman zamanı durdurmaya çalışan

Bir telaş görsem bir adamın gözlerinde

Umutları ıslanmış olur.

Bir vazgeçtiği oluverir.

Ne zaman bir saati kolundan çıkarıp fırlatan

Bir öfke görsem bir kadın elinde

Islanmış olur gözleri yol gözlemekten.

Randevusuna gelmeyen,

Bir beklediği oluverir.

Bir de kadranların üzerinde yapayalnız kalmış akrepler vardır.

Hiç gelmeyecek olan yolcuları beklerler.

Bir de tozlu çekmecelere atılmış, büyük bir sabırla takılmayı bekleyen cep telefonu mağduru 

Yorgun ve kırgın saatler vardır. Umutsuzca…

Kalbim kırılıyor desem

Kapıma gelir misiniz?

Kaybolmaktan kurtarmak için bir adamı....?

Yeleğinizde, 

eski, yorgun, inatla çalışan köstekli bir saat olsun ama...

.

Vakit daralıyor desem

Yola düşer misiniz,

Geç kalmaktan kurtarmak için bir adamı....?

Bileğinizde, 

kurmalı gümüş bir saat olsun ama...

2009

*Düşünmek Yaşamın Pasını Silmektir, Karina Yayınevi, Ank, 2018', 'Duvarlarda asılı yorgun zamanlar vardır. Renkleri solmuş fotoğraflar gibi, yüzlerini suskunluğa dönmüşlerdir. Bir bakışın içinde saklı kalmı...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Özmen']::text[], 8.5, '{"poet":"Tahsin Özmen","poet_slug":"tahsin-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/bilmece-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irakta''ki Çocuklar', 'irakta-ki-cocuklar-lokman-ali-yavuz-sls0h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Irak’taki çocuklar 

Çikolata yemiyormus(basindan)  

Bilmedikleri seyi neden yesin ki

Irak''taki çocuklar

Irak’taki çocuklar.

Gülmüyorlar.

Çizme altinda bilemezler ki

Nasil gülsünler.

Irak’ta ki çocuklar. 

Ellerinde silahlar

Birileri gül yerine insanliklarini vermis.

Nereden bilsinler ki? 

Irak''taki çocuklar...

Ümitvarim,

Yüreginizin tebessüm ettigi, bir gün gelecek.

O gün kanatlariniz olacak,

Irakta''ki çocuklarla uçmak için', 'Irak’taki çocuklar  Çikolata yemiyormus(basindan)   Bilmedikleri seyi neden yesin ki Irak''taki çocuklar Irak’taki çocuklar. Gülmüyorlar. Çiz...', ARRAY['Türk Edebiyatı','Şiir','Lokman Ali Yavuz']::text[], 8.5, '{"poet":"Lokman Ali Yavuz","poet_slug":"lokman-ali-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/irakta-ki-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simitçi', 'simitci-muharrem-cetinkaya-b1tla', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkesten erken kalkar,

                   düşer yollara.

Susamlı döner

                    der ona

                                yiyenler.

Simitçinin derdi

                   bitirmek bir an önce

                                        simitleri.

Üçyüz kişiye,binbeşyüz kelime

                     taze  sıcak simit,

                              afiyet olsun! 

Üçyüz simite 

                    bir ayakkabı

                                      küçük kızına! 

Ötekiler de bekler..........................

Onların ki

                 yarına................................', 'Herkesten erken kalkar,                    düşer yollara. Susamlı döner                     der ona                                 yiyenler...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/simitci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür dediğin...', 'omur-dedigin-kenan-ciftci-e8f6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman akıyor, sel gibi...

bir gün denecek,dur hele...

Ömür dediğin,gül gibi...

bir gün solacak dur hele...

Çocukken,bolca oynardın...

gençken,aldanır,kanardın...

yaşlılık gelmez sanırdın...

Belin bükülsün dur hele...

Ölüm aklına gelmez ki...

kendisine,düşünmez ki...

kaç nefes kaldı bilmez ki..

Sona erecek,dur hele...

Kapı çalınır,duyamaz...

hastadır kalkıp açamaz...

Azrail gelmiş,kaçamaz...

Tamam diyecek dur hele...', 'Zaman akıyor, sel gibi... bir gün denecek,dur hele... Ömür dediğin,gül gibi... bir gün solacak dur hele... Çocukken,bolca oynardın... gençke...', ARRAY['Türk Edebiyatı','Şiir','Kenan Çiftçi']::text[], 8.5, '{"poet":"Kenan Çiftçi","poet_slug":"kenan-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omur-dedigin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Sen Onlara', 'bakma-sen-onlara-lokman-ali-yavuz-gauiv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakma

Bakma sen onların 

Horoz gibi yürüdüğüne

Ben onları el etek öperken gördüm

Onların etek öptüğü yerde 

Ben başımı gökte gördüm', 'Bakma Bakma sen onların  Horoz gibi yürüdüğüne Ben onları el etek öperken gördüm Onların etek öptüğü yerde  Ben başımı gökte gördüm...', ARRAY['Türk Edebiyatı','Şiir','Lokman Ali Yavuz']::text[], 8.5, '{"poet":"Lokman Ali Yavuz","poet_slug":"lokman-ali-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bakma-sen-onlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Öylesine Sevdim-Gizli Sevda', 'ben-seni-oylesine-sevdim-gizli-sevda-muharrem-cetinkaya-ux4lu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elin elime değmedi,

        gözüm gözüne

Saçının bir tek teline bile dokunmadım,

                              sesini, hiç duymadım,

kimsin,

nesin,

nasıl birisin,

nerde oturursun,

ne yersin,ne içersin bilmem! 

Ama her gün,

          benimlesin,

                          haberin bile yok! 

Bir resimde gördüm 

                                 hayalini

tanıdık geldi.

Ben seni öyle

                 _________öylesine sevdim!', 'Elin elime değmedi,         gözüm gözüne Saçının bir tek teline bile dokunmadım,                               sesini, hiç duymadım, kimsin,...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-seni-oylesine-sevdim-gizli-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Seninle', 'sadece-seninle-volkan-yoruc-wdt95', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzanmışım yere ve aklım yine sende

Elimde bir kırmızı kalem

Beyaz sayfalara seni yazıyorum sessizce

Önce gülüşün yerleşiyor hayalime

Sonra seninle geçen dakikalar yeşeriyor zihnimde

Nede güzelmiş diye dönmek istercesine o vakte

Bir dilek ekiyorum dizelerime

Oysa 24 saat öncesinde

Ben seninleydim halimize gülercesine

Sanki asırlık çınarlar kadar eski geliyor şimdi gönlüme

Ve geri dönüpte yine yaşamak istiyorum o çınarların gölgesinde

Bir sen ve bir ben, sadece seninle, gülümsercesine

(20/05/2005)    Saat:00.20

  Perşembe', 'Uzanmışım yere ve aklım yine sende Elimde bir kırmızı kalem Beyaz sayfalara seni yazıyorum sessizce Önce gülüşün yerleşiyor hayalime Sonra s...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sadece-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ser-giran Eyler Yar Beni', 'ser-giran-eyler-yar-beni-zeki-akcali-i1ytt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hançer-i müjgan saplanırken kalbime,

Ser-i dara asar yar beni.

Gisu-yi yar okşarken gönlümü,

Ser-giran eyler yar beni.

Lahn-i inkisar çalarken sazında,

Ser-i dara asar yar beni.

Gamze-i cadu ile sararken ruhumu,

Ser-giran eyler yar beni.

(20/05/2005, Cuma, B.Çekmece) 

hançer-i müjgan...: hançere benzeyen kirpikler

gisu-yi yar...........: sevgilinin saçı   

lahn-i inkisar........: kırgınlık namesi

gamze-i cadu.......: büyüleyen gamze (süzgün bakış) 

ser-i dar...............: darağacının tepesi

ser-giran..............: çok sarhoş etmek', 'Hançer-i müjgan saplanırken kalbime, Ser-i dara asar yar beni. Gisu-yi yar okşarken gönlümü, Ser-giran eyler yar beni. Lahn-i inkisar çalark...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ser-giran-eyler-yar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Karınca', 'kirmizi-karinca-lokman-ali-yavuz-1tl85', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neyi değiştirir ki

Varlığın, varsızlığın

Yalnızsın işte

Karıncalar çokluğu 

Tanışıklar olsa ne yazar

Karıncalar içinde 

Sen  “kırmızı karınca” olduktan sonra

Saat üç olmuş, beş olmuş onbeş olmuş

Neyi değiştirir 

Neyi değiştirir 

Lalelerin dik duruşu 

Festival tadındaki   

Doğa izlenceleri

Neyi değiştirir

Kemanın yankısı

Bağlamanın kilim rengi

Kemençenin  oynaşlığı

Çocuk cıvıltıları haricindekiler

Neyi değiştir ki 

Boş işte.', 'Neyi değiştirir ki Varlığın, varsızlığın Yalnızsın işte Karıncalar çokluğu  Tanışıklar olsa ne yazar Karıncalar içinde  Sen  “kırmızı karınc...', ARRAY['Türk Edebiyatı','Şiir','Lokman Ali Yavuz']::text[], 8.5, '{"poet":"Lokman Ali Yavuz","poet_slug":"lokman-ali-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirmizi-karinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksul', 'yoksul-muharrem-cetinkaya-9j3oa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne evim var,ne-barkım

      ne arabam,ne katım,ne yatım

toto oynarım tutmaz

      iddaa da tek maçla kaybederim.

Ne gül''üm var,ne gülistanım

 sabah kalkar,

 düşerim yollara,

 ekmek parası...! 

Dün ayakkabım delikti

        bugün çorabım da.......! 

Bu yoksulluk,yürek yarası.

Fabrikalarım iflas,

                           dükkânlarım kepenkli

bütün varlığım bitik

sıfır elde var sıfır

  ikiyi çarparım ikiyle

o da çıkar hep...........

             akşam yatarım

sabah kalkarım

            akşam...................', 'Ne evim var,ne-barkım       ne arabam,ne katım,ne yatım toto oynarım tutmaz       iddaa da tek maçla kaybederim. Ne gül''üm var,ne gülistanım...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yoksul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-guzin-eye-dundar-9h8hl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittin... soğudu bu ten

kıpır kıpır can

henüz  yaşarken

gittin... uzaklar ses vermiyor

bir kere seslen

sevdiğim sana dair ne varsa

aşk oldu bende 

gözlerime hapsettim gözlerini

ışıklarını  ödünç ver

gittin anlamı kalmadı  hiçbirşeyin

bozuldu düzen.

zamansızlık özlemi sardı evrenimi

uzaklar yakın oldu

soğudu bu ten

gittin  ölümüne bitti  özlenen

seninle başlayıp seninle biten...', 'Gittin... soğudu bu ten kıpır kıpır can henüz  yaşarken gittin... uzaklar ses vermiyor bir kere seslen sevdiğim sana dair ne varsa aşk oldu ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gittin-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak', 'toprak-ali-kilic-26dsl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Diken dolu olsada bu topraklar

kuş uçmaz kervan geçmez densede

atalarımın teri değmiştir 

nasırlı ellerinden kan, alnından ter akmıştır

koşu sürmüş, saban ardında 

bazen kuraklıktan bir damla suya hasret

bazen testiden kana kana su içip

yakasındaki mendile terini silermiş', 'Diken dolu olsada bu topraklar kuş uçmaz kervan geçmez densede atalarımın teri değmiştir  nasırlı ellerinden kan, alnından ter akmıştır koşu...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç']::text[], 8.5, '{"poet":"Ali Kılıç","poet_slug":"ali-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/toprak-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-ali-kilic-bc77w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'oğulsun sen kovandan giden arı gibi

iseterim yolun göküzü gibi açık

yüzün güleç nasibin bol olsun

ne gecelerim kaldı ne ben

artık herşeyim sen 

ne çabuk geçer zaman 

oldu yirmi üç ay

en dolu geçen zananım işte bu zaman 

hastayken sen ağlarken 

ağrılardan çaresizce bana sarılışın

benim dünyanın altında kaldığım an o an

acların acılarım olmadı acıdan beter 

çaresizlikten yüreğimi sökmek geldi içimden

nasipse eğer ben yanlızlığı tatım sen tatma 

baba deyip açtığında kollarını nasip olsun 

kollarım o an boynuda 

canım serilsin senin uğruna 

sen oğulsun canın canı 

kanımın kanısın oğul', 'oğulsun sen kovandan giden arı gibi iseterim yolun göküzü gibi açık yüzün güleç nasibin bol olsun ne gecelerim kaldı ne ben artık herşeyim s...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç']::text[], 8.5, '{"poet":"Ali Kılıç","poet_slug":"ali-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ogul-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümü Özledim!', 'koyumu-ozledim-muharrem-cetinkaya-8zjp7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özledim,kekik kokulu akşamları,

Özledim köyümü,

                             köyümün; 

   oyun oynadığım sokaklarını.

Dedemin üzüm bağını

        salkım salkım kara üzümleri.

        ninemin inek sağdığını

        bakraç bakraç süt,kaymak,yoğurt

Hasan Dayı''mın çayırlıktaki bahçesini

                  bahçenin kara kara eriklerini.

Halamın oğluyla kılıç yapar

                dövüşürdük kavak dallarından.

Dedem düdük yapardı

                                     söğütten,

 en iyi benim ki öterdi.

Polis-kaçak oynardık akşamları,

          gece salatalık çalardık

          ''Sarı Mevlüt''dayının bahçesinden

 ne tatlıydı o kavunlar,

        ...............................................! 

Öküz arabasıyla tarlaya gider,

              eşekle geri dönerdik,

dayımın atlarıyla harman sürer,

     deredeki çeşmenin oluğunda yüzerdik,

Köyde herkes çalışırdı; 

     derede çamaşır yıkanır,serilirdi ağaçlara

      çocuklar kuzu güderdi çayırlarda

Musa Emmi''nin kalın kavaklarına

adımızı yazardık; 

             kazırdık baş harflerimizi.

Her şeyimiz doğaldı,

       pazardan hiç bi-şey alınmazdı.

Her şeyin tadı o kadar doğal

                         o kadar güzel

        o kadar doyumsuzdu ki; 

Şimdi O günleri,

               hatıraları

                             andıkça

Burnuma kekik kokulu,

                sacda pişen bazlamaların kokusu gelir,

yemeden doyarım...!', 'Özledim,kekik kokulu akşamları, Özledim köyümü,                              köyümün;     oyun oynadığım sokaklarını. Dedemin üzüm bağını   ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/koyumu-ozledim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-umit-engin-ophqc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir veda öpücüğü, bir sevgi sözcüğü ile ayrıldık. Yüzün, gözün, dudakların o gün olduğu gibi hala aklımda sen gittekten sonra girdim ara sokaklar gibi parçalandı kalbim. Seninle geçtiğimiz sokakları yürüdüm, oturduğumuz yerlere oturdum, uzandğımız yatağa uzandım. Herşey hala öyle buran buram sen kokuyor ki, her yanımda görüyorum suretini. Kelimeler anlamsız nu gece, bursa bir yabancı geldi bana. Seninle anlam kazanan bu kenti terk ettiğin gün başladı gündüzün karanlığı. 

20.05.2005 / 17:30 / ümit engin', 'Bir veda öpücüğü, bir sevgi sözcüğü ile ayrıldık. Yüzün, gözün, dudakların o gün olduğu gibi hala aklımda sen gittekten sonra girdim ara sok...', ARRAY['Türk Edebiyatı','Şiir','Ümit Engin']::text[], 8.5, '{"poet":"Ümit Engin","poet_slug":"umit-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ayrilik-250-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalansınız', 'yalansiniz-asli-yildiran-f348a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalansınız sizde, diğerleri gibi, yaz yağmuru gibi geçici

Gökkuşağı gibi yanıltıcısınız, yalansınız işte

Dünya kadar yalansınız sizde.

Yalan yanımda oluşlarınız, elleriniz sıkıca tutan yada tuttuğuna inanılan

Gözleriniz ve bakışlarınız sevgi dolu olan, yalan 

Yalansınız işte dünya kadar yalan...

“Var mısın” diyen dillerinizden dökülen sevda sözleriniz yalan

Renkleriniz mavi,yeşil,beyaz hepsi yalan 

Siyah giymiş gölgelersiniz, gölgelerden bile yalan

Dönüşleriniz yalan, gidişleriniz, zaten hiç gelmemiştiniz.

Gecelerin karasında camlara vuran dalların canavarlığı kadar yalansınız

Yalansınız sizde, dünya kadar...', 'Yalansınız sizde, diğerleri gibi, yaz yağmuru gibi geçici Gökkuşağı gibi yanıltıcısınız, yalansınız işte Dünya kadar yalansınız sizde. Yalan...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalansiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Meçhulün Ardından', 'bir-mechulun-ardindan-eyup-tosun-3zs6q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömre bedel iki damla aktı gözlerimden

Denizin soğuk nemiydi inen hislerimden

Hissettim,yere doğru süzüldü dizlerimden

Ardısıra ufuktan geçen gemiler başka...

Gün hicran dolu,gönlüm bir meçhulün yasında

Dağların ardında,karanlığın bağrında

Bir huzur arıyorum dalgaların bağrında,

Nafile diyorum,kurduğum hayaller başka...

Yıldızlarla konuştum dün gece,vuslat uzak

Martılar söyledi kaderden bana bir tuzak

Karlar üstüne bahtımı yazıyor şu kızak

Oysa bilmiyorlar,içimdeki dertler başka...

Beyhude geçiyor gençliğim,anladım sürgün

Meçhulümden,karıncama herkes bana küskün

İçimde çalkantılar batıyorum günbegün

Gezdiğim adalar,vurduğum kıyılar başka...

Demir atmak zor duvardaki körpe zamana

Onsuz daralıyorum,sığmıyorum mekana

Takvime yetişmek,ayak diremek cihana

İçimde halen aynıyım,yansımalar başka...

Sorularla bıraktın beni cevapsız,sessiz

Bir başıma buralarda ne yaparım sensiz

Bir akıntıya kapıl,koyma beni kimsesiz

Koşuyorum sana her gece,rüyalar başka.', 'Ömre bedel iki damla aktı gözlerimden Denizin soğuk nemiydi inen hislerimden Hissettim,yere doğru süzüldü dizlerimden Ardısıra ufuktan geçen...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Tosun']::text[], 8.5, '{"poet":"Eyüp Tosun","poet_slug":"eyup-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-mechulun-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bahar', 'yeni-bahar-zeki-akcali-55mo7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu bahar,

Artık yeni bir bahar...

Yaseminler açtı gönlümde.

(20/5/2005, Cuma, B.Çekmece) 

(2. dönem)', 'Bu bahar, Artık yeni bir bahar... Yaseminler açtı gönlümde. (20/5/2005, Cuma, B.Çekmece)  (2. dönem)...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yeni-bahar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-yahya-akbulut-9wjo9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar bedenimde izlerini

Zaman yılların özlemini

Gözlerinde gizlemiş. 

Bitmeyen ilkbahar geceleri

Beyaz giymiş gelin gibi.

Sırlarını özlemiş. 

Dökülen sonbahar yaprakları,

Yüzünde ıslak gözyaşlarının

izlerini gizlemiş. 

Mevsimler gözlerimde seni

Yıllar yorgun bedenimi

Sevdaları özlemiş.', 'Yıllar bedenimde izlerini Zaman yılların özlemini Gözlerinde gizlemiş.  Bitmeyen ilkbahar geceleri Beyaz giymiş gelin gibi. Sırlarını özlemi...', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sir-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıp Değil Ya Annem', 'ayip-degil-ya-annem-emin-eren-ensa3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçüçük el kadardık

Ninnilerle yatardık

Özünden sütün ile

Kahvaltılar yapardık

Konuşamazken bile

Belkide iç güdüyle

Suyumu ilacımı

Verdin melek elinle

İlk adımda benimle

Yine sen vardın anne

Daha düşmeden yere

Doğruldum desteğinle

Bazen kızardın bana

Hatta küserdin ama

En uzun dargınlığın

Sürmezdi beş dakika

Sonunda adam oldum

Tüccar,işçi,memurum

Yaşım olsada kırkbeş

Ayıp değilya annem

Kokunu özlüyorum', 'Küçüçük el kadardık Ninnilerle yatardık Özünden sütün ile Kahvaltılar yapardık Konuşamazken bile Belkide iç güdüyle Suyumu ilacımı Verdin me...', ARRAY['Türk Edebiyatı','Şiir','Emin Eren']::text[], 8.5, '{"poet":"Emin Eren","poet_slug":"emin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayip-degil-ya-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Şansın', 'senin-sansin-cenk-aksal-5ko8j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir yıldız daha kaydı,

iyi bir dilek tut içinden..

ben yalnız,garip balıkçın,

her gece alargadayım,

bu yıldız senin şansın:

iyi bir dilek tut içinden,

yakomozlar benim,

yıldızlar senin şansın,

çobanyıldızı,kuyruğunda

bizim hikayemiz var,

iyi bir dilek tut içinden.

bu yıldız senin şansın...

        ''kanatlarında aşk,yıldızımın''

        ''bu yıldız senin şansın/canım''', 'bir yıldız daha kaydı, iyi bir dilek tut içinden.. ben yalnız,garip balıkçın, her gece alargadayım, bu yıldız senin şansın: iyi bir dilek tu...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/senin-sansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Donuyorum', 'donuyorum-sahin-erturk-0il41', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanki kuzey kutbundayım

Üşüyorum,titriyorum

Sensizlikten,yalnızlıktan

Buz kesiyor,donuyorum

Sensizlikle yıllar bitti

Yalnızlıkla ömrüm geçti

Kanım,canım senle gitti

Buz kesiyor,donuyorum

Biliyorum gelmez artık

Umudumu kestim artık

Ağustos a çıkmam artık

Buz kesiyor,donuyorum

Alsan beni kollarına

Sıksan kırsan kemiğimi

İşte şimdi hapı yuttum

Şuursuzum,saçmaladım

Buz kesiyor,donuyorum

(20.05.2005-Yeni)', 'Sanki kuzey kutbundayım Üşüyorum,titriyorum Sensizlikten,yalnızlıktan Buz kesiyor,donuyorum Sensizlikle yıllar bitti Yalnızlıkla ömrüm geçti...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/donuyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşklı sözler(ufuk)', 'askli-sozler-ufuk-evren-demirdelen-sldo9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ufuk çizgisine doğru yolculuğa çıkmaya benzer

                   gerçek aşkı aramak..

           sürekli yaklaştığını hissedersin 

               ancak asla varamazsın..

ne zaman ki karaya çıkarsın...işte o zaman da

                         arkanda kalmıştır! !', 'ufuk çizgisine doğru yolculuğa çıkmaya benzer                    gerçek aşkı aramak..            sürekli yaklaştığını hissedersin           ...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/askli-sozler-ufuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorumsuz..', 'yorumsuz-evren-demirdelen-33558', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sözün gözünde gizli

sevda özünde..

neden sorarlar ki beni sana? 

neden ararım seni başka yerde?', 'sözün gözünde gizli sevda özünde.. neden sorarlar ki beni sana?  neden ararım seni başka yerde?...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yorumsuz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gülüşün...', 'bu-gulusun-halil-kesken-o7w8r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gülüşün öylesine güzel ki,

Edalı, nazlı bir kelebeğe benziyor

Yanaklarında takılıp kalmamalı

Dolaşmalı kırları, bayırları

Ağaçlara, çiçeklere, kayalara konmalı

Bu gülüşün öylesine güzel ki,

Sevgi dolu, umut dolu bir öpücüğe benziyor

Dudaklarında takılıp kalmamalı

Bir yoksulun, bir evsizin yanaklarına konmalı

Ya da bir mutsuzun (yani benim :-))  yanağıma konmalı

Bu gülüşün öylesine güzel ki,

Cıvıl cıvıl bir kanaryaya benziyor

Havada dolaşıp durmamalı

Uçup bir hastanın penceresine konmalı

Gidip geceye konmalı, güneşi doğdurmalı

Bu gülüşün öylesine güzel ki,

Rengarenk bir gökkuşağına benziyor

Gidip savaş alanının üzerine doğmalı

Çocukların kara gözlüklerini tozpembeye boyamalı

Tetiği sıkan yüreği yumuşatmalı

Bu gülüşün öylesine güzel ki,', 'Bu gülüşün öylesine güzel ki, Edalı, nazlı bir kelebeğe benziyor Yanaklarında takılıp kalmamalı Dolaşmalı kırları, bayırları Ağaçlara, çiçek...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-gulusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biten..', 'biten-evren-demirdelen-gmy82', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yabancı geleir buralar bana

gitmek isterim..

avutmaz puslu gözlerin! 

aynı boş sokaklardan

geldiğim gibi...

elimde bavul sahibine küs

giderm bir ayaz çıkar

yağmur yağar,gözlerimi silerim..

aldırmam artık olmayışına

elmastan bir ölümdür kaderim

içim başka zamanların öfkesinde

sahipsizim yok gidecek yerim

yine de ben..

böyle şiirlerde kendimi söylerim! 

yok kimseyle düşmanlığım

istenmesem de sevilmesem de

severim..

artık unutulmuş şarkılar söylerim

gülen arkadaştır ağlayan dost

susmayı erdem bilirim

bilirim ölmenin değerini

bir gün bırakır dünyalık ne varsa

geldiğim gibi..

elimde bavul; gözlerin..

yürekte rüzgar; sözlerin

atarım başka ne varsa..

giderim..', 'yabancı geleir buralar bana gitmek isterim.. avutmaz puslu gözlerin!  aynı boş sokaklardan geldiğim gibi... elimde bavul sahibine küs giderm...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/biten-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka bir dalga..', 'baska-bir-dalga-evren-demirdelen-c9e3p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'baktım ve geçtim

öylesine..

hayatmış adı; 

neylersin! ! 

ismini koyamadım yaşananların

bilirsiniz işte

öylesine..

baktım ve geçtim!', 'baktım ve geçtim öylesine.. hayatmış adı;  neylersin! !  ismini koyamadım yaşananların bilirsiniz işte öylesine.. baktım ve geçtim!...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/baska-bir-dalga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 8:yoksun', 'saat-8-yoksun-evren-demirdelen-gjupu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'saat sekiz derler günün bitimine bilirsin

ve ölüm derler hayatın bitimine

yine de herkes razıdır

bu kelime yitimine..

günün ve hayatın devamı vardır

yoktur anlamı karanlığın..

kimsenin de bir şeyi yoktur

yerine konulacak bu masalın..!', 'saat sekiz derler günün bitimine bilirsin ve ölüm derler hayatın bitimine yine de herkes razıdır bu kelime yitimine.. günün ve hayatın devam...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saat-8-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mümkünse..', 'mumkunse-evren-demirdelen-ipmcs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mümkünse sevmeyin..

görüyorum ki anlamım yok! 

tek tutanağım

bilmemeniz..

belki bakıyorsunuz ama

yokum oralarda..

mümkünse öldürün..! 

ulaşamayacağınız yerlere gömün.

fazla şey istedim sanırım

unutun yeter..

yaşarken ölmek bana da koyar! 

sizin gördükleriniz

bende yok..

afedersiniz! 

ama şunu bilin ki

ne yaparsanız yapın

aynısınız içimde

ne iyi ne kötü

yalnızca her hangi...

eminim ben de size öyleyim! 

o zaman 

zaman zaman

mümkünse dinleyin

ve anlamı kendinizde aramayın her zaman

mümkünse..', 'mümkünse sevmeyin.. görüyorum ki anlamım yok!  tek tutanağım bilmemeniz.. belki bakıyorsunuz ama yokum oralarda.. mümkünse öldürün..!  ulaşa...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mumkunse-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vahinzel-2', 'vahinzel-2-evren-demirdelen-1v99b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'neyse ki suskunduk kapalı yaralarımıza

belki de sessizliği sensizliğin getirisi sandım

bundandır açıklanamazlığı 

yutkunmasız hıçkırıkların..

görmüştün sevdanın alacakaranlığını

tuzluydu aşk salatası

ya da acısı az''dı sözlerimin..

görmüştün gözlerini

görgülü bir görünmezliğin..

alacakaranlığıydı ayrılık zifiri bir nefretin..

yavaş yavaş belirginleşen

eski yıldızlardan biriydin oysa

binyılları deviren ama ışığı

bir ayrılığa yetmeyen

tutsaklığa ömürler tüketen ancak..

gözlerinden ölümsüz aşkın korkusu gitmeyen

bu şiir bir melodidir ki 

ne sende ne de bende bitmeyen...', 'neyse ki suskunduk kapalı yaralarımıza belki de sessizliği sensizliğin getirisi sandım bundandır açıklanamazlığı  yutkunmasız hıçkırıkların....', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/vahinzel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzer mi', 'uzer-mi-abdulrizak-kilic-ebo6r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gece gündüzünü

ölüm ölümsüzlüğünü

zaman zamansızlığını

insan sevdiğini üzer mi hiç

terk eder mi aşkını

bir anlık öfke mayınına basıp

inat sınırında kaçak dolaşır mı hiç

aşkımsın her şeyimsin demekle aşk olur mu hiç

ormanda esintisiz bir kırık dal

sonsuzluğumda yönsüz bir kasırgasın sen

anlaşılmaz 

dertsiz 

vurdum duymaz birisin sen

gündüz gecesini

ölümsüzlük ölümünü

zamansızlık zamanını

insan sevdiğini üzer mi hiç

danışmayıp karar verensin sen

seveni sevdiğini hiçe sayansın

kendinin farkında değilsin sen

dost ile düşman arasında

bir sınırsız sınırsın sen

uykularda kabus

içimde tek mahpus

derdime bin dertsin sen

insan insana kıyar mı hiç', 'gece gündüzünü ölüm ölümsüzlüğünü zaman zamansızlığını insan sevdiğini üzer mi hiç terk eder mi aşkını bir anlık öfke mayınına basıp inat sı...', ARRAY['Türk Edebiyatı','Şiir','Abdulrızak Kılıç']::text[], 8.5, '{"poet":"Abdulrızak Kılıç","poet_slug":"abdulrizak-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/uzer-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler Anneler Melek Anneler', 'anneler-anneler-melek-anneler-umut-gungor-qellv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kol kanat gererler büyüsün diye,

Vatan millet için yürüsün diye,

Okutur cahillik çürüsün diye,

Anneler anneler melek anneler.

Uykusuz geçirir aylar günleri,

Bal olur akar şirin dilleri,

Şevkatle sarar sıcak elleri,

Anneler, anneler melek anneler.', 'Kol kanat gererler büyüsün diye, Vatan millet için yürüsün diye, Okutur cahillik çürüsün diye, Anneler anneler melek anneler. Uykusuz geçiri...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anneler-anneler-melek-anneler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serdengeçtim 1', 'serdengectim-1-umut-gungor-gnkry', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Serdengeçtim vakit artık doluyor,

Altaylarda kardelenim soluyor,

Sinirinden yaprağını yoluyor,

Aral nehrim kurumaya yüz tuttu.

Türkistan da kardeşlerim zulümde,

Nükleer deneyde fenni ölümde,

Gonca açmaz oldu gayrı gülümde,

Tuna Nehrim buzlanmaya yüz tuttu.

Serdengeçtim ok yayından çıkıyor,

Hava pusa durdu şimşek çakıyor,

Bazısına TÜRKÜN adı batıyor,

Kürsülere çıkacağın gün bugün.

Serdengeçtim kır belini zilletin,

Köküne zehir saç her bir illetin,

Kahraman soyludur senin milletin,

Meydanlarda coşacağın gün bugün.

Serdengeçtim vakit geldi koşmaya,

Karadeniz dalgasıyla taşmaya,

Ulubatlı gibi sancak asmaya,

Bayrağınla koşacağın gün bugün.', 'Serdengeçtim vakit artık doluyor, Altaylarda kardelenim soluyor, Sinirinden yaprağını yoluyor, Aral nehrim kurumaya yüz tuttu. Türkistan da ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/serdengectim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin Ertesi', 'sensizligin-ertesi-baran-baransel-d867y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sabah,

Yokluğun bir yıldırım gibi düştü bu kente,

Çığlık çığlığa akıp giden hayat,

Birden bir salyangoz gibi

Çekilip kendi kabuğuna,

Kapattı bütün perdelerini

Güneşin yüzüne...

Ne mevsim bahardır şimdi,

Ne gönlüm çocuklar gibi şendir.

Ne nergis nergis gibi kokar,

Ne kırlangıçlar mavilere yoldaş...

Acımam bu şehre

Dilimde bedduanın bini bi para,

Beter ol derim yüzlerce kez içimden

Onulmaz dertlerden kurtulama bir daha

Sensizliğin ayıbını

Seninle temizlemeden...', 'Bu sabah, Yokluğun bir yıldırım gibi düştü bu kente, Çığlık çığlığa akıp giden hayat, Birden bir salyangoz gibi Çekilip kendi kabuğuna, Kapa...', ARRAY['Türk Edebiyatı','Şiir','Baran Baransel']::text[], 8.5, '{"poet":"Baran Baransel","poet_slug":"baran-baransel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensizligin-ertesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün Sensizliğin İlk Günü...', 'bu-gun-sensizligin-i-lk-gunu-cigdem-simsek-h5dyp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gün sensizliğin ilk günü... 

Başka bir gökyüzünde ilk gecen olacak... 

Tek bildiğim her bir yıldıza baktığında,

Beni düşündüğünü biliyor olacağım…

Şafak saymaya başladın yarınlar için

Sabahın alaca karanlığında her gün açtığın

Gözlerin seni bana getirecek…

Biliyor musun? sen gidince şehir öksüz kaldı, 

Boş bıraktığın ellerim gibi...

Kapat gözlerini ve ….

Söylemek isteyip de söylemediklerimi bir düşün…

İçimdeki sessiz çığlıkları dinle…

Belki isyan, belki kabulleniş

Hayır! ! ! Bu çaresizlik…

Çok uzakta olsan da, özlendiğini bil...', 'Bu gün sensizliğin ilk günü...  Başka bir gökyüzünde ilk gecen olacak...  Tek bildiğim her bir yıldıza baktığında, Beni düşündüğünü biliyor ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-gun-sensizligin-ilk-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düz şiir?', 'duz-siir-mikdat-bal-8230g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düz şiir diyorlar notası var mı? 

Kuralı, ölcüsü, rotası var mı? 

Ahenkli mısrası, kıtası var mı? 

Bilmiyorum, bilen, varsa söylesin 

Neresi nereye, bağlanır burda? , 

Müzikle irtibat, sağlanır burda? . 

Hangi bölümünde, ağlanır burda? 

Bilmiyorum, bilen varsa söylesin 

Bu şiir türünün çoktur hastası 

Hala anlamadım nedir kıstası? 

Türkiye çapında kimdir ustası? 

Bilmiyorum, bilen varsa söylesin 

Okurum anlamam, bilmece gibi 

Zaten okunmuyor, bir hece gibi 

Hikayeye benzer, düzmece gibi 

Bilmiyorum, bilen varsa söylesin 

Maksatım öğrenmek, yermek değildir 

Sizin dünyanıza girmek değildir 

Sizi üzgün, kızgın, görmek değildir 

Bilmiyorum, bilen varsa, söylesin 

Mikdat’ım ben hece, yazar okurum 

Mısra, mısra ipek gibi dokurum 

Bazen durgun, bazen fokur fokurum 

Bilmiyorum bilen varsa, söylesin', 'Düz şiir diyorlar notası var mı?  Kuralı, ölcüsü, rotası var mı?  Ahenkli mısrası, kıtası var mı?  Bilmiyorum, bilen, varsa söylesin  Neresi...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/duz-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gönlüm', 'bu-gonlum-ali-kilic-kakiz-8z8mz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan oğlu tuvaf,övünür durur,

Hep rüyalarım kurtlu  koyunludur.

Gitti kötüye mi dolandı  bu gönlüm.

Bacı soğandan acı,küllemişler sacı. 

Sen sen ol çevirme kapından muhtacı. 

Gitti kötüye mi dolandı  bu gönlüm.

Ne yapsam ne söylesem hep hafife alır.

İnsan dediğin biraz olsun,arlanır uslanır.

Gitti kötüye mi dolandı  bu gönlüm.

Söz dinletemedim, takatım kalmadı.

Korkular beni ürpertti anam ağladı.

Gitti kötüye mi dolandı  bu gönlüm.

Koyunda kene,atta eğer oldum.

Hayatımın baharında sarardım soldum.

Gitti kötüye mi dolandı  bu gönlüm.

İstanbul / 1999', 'İnsan oğlu tuvaf,övünür durur, Hep rüyalarım kurtlu  koyunludur. Gitti kötüye mi dolandı  bu gönlüm. Bacı soğandan acı,küllemişler sacı.  Se...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-gonlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş Ve Barış', 'savas-ve-baris-omer-ergoren-4vo40', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatta bildiğimiz yalnız iki kelime:

Dolanır dilden dile savaş ve barış.

İyi günde kötü günde her birimize,

Sahiplenmiş durmakta,savaş ve barış.

Kimi malım dedi kimisi canım...

Merhem sürse yaraya olmakta kanım.

Bazen iyi gitse de şanstadır bahtım.

Sebeb fazla aranmaz,savaş ve barış! 

Parayla satılır saadet bize.

Sırtına kırbaçtır gelmezsen dize.

Yoktur hakkın söyleyecek iki kelime! 

Mahkeme kurulmuştur savaş ve barış! 

Bir bakarsın yıldızlar yağıyor üstümüze.

Gözyaşı kan olmuş çocuktan da kime ne? 

Dönüp bakmak ölümdür,yerde yatan anneye.

Alnına yazılmıştır savaş ve barış.

Günler artık geçmeli kansız ve yaşsız.

Hayat bahçe olsa,çiçek olamaz mıyız? 

Bir maddeden daha çok insan durmalıyız.

Yeter çekil aradan; savaş ve barış! ! !', 'Hayatta bildiğimiz yalnız iki kelime: Dolanır dilden dile savaş ve barış. İyi günde kötü günde her birimize, Sahiplenmiş durmakta,savaş ve b...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ergören']::text[], 8.5, '{"poet":"Ömer Ergören","poet_slug":"omer-ergoren","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/savas-ve-baris-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İronik Teşbih XV', 'i-ronik-tesbih-xv-ahmet-aksoy-jo92z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kürtaj ücretleri kadar düşük bedelleri', 'kürtaj ücretleri kadar düşük bedelleri...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ironik-tesbih-xv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Yüreğimsin', 'can-yuregimsin-gonul-ozdemir-tdxi3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Can Yüreğimsin

Sen kalbimde açan ilk çiçeğimsin

Sen en kötü günlerimde meleğimsin

Sevgi dünyama doğuşuyla aydınlatan

Güneşim ilk ve son aşkım

Sen yüreğim sen kan yüreğim

Can yüreğimsin...

9.2.2005  Gönül Özdemir-SAMSUN', 'Can Yüreğimsin Sen kalbimde açan ilk çiçeğimsin Sen en kötü günlerimde meleğimsin Sevgi dünyama doğuşuyla aydınlatan Güneşim ilk ve son aşkı...', ARRAY['Türk Edebiyatı','Şiir','Gönül Özdemir']::text[], 8.5, '{"poet":"Gönül Özdemir","poet_slug":"gonul-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/can-yuregimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkum', 'mahkum-yilmaz-korkankorkmaz-k8scn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dolaşırken damarlarımda lanetli bir yaşam

dilimde lal dualar

aralıksız adımlar peşinde

aydınlık bir yarın serüvencisiyim

kırılmış bir sazın

titrek ses akorduyla

tarihin içinde

çıldırmış bir gelecek yansısı gibi

bin savaş öfke sunuyorum nasırlı avuçlarımla

anlık bir mahkumum ben 

niyesi bilinmeyen göçlerden arta kalan 

ve sokaklarında sadece sessizliğin dolaştığı 

bir kente sevdalı

acemi 

ürkek 

yalınayak 

dil ucunda bir çocuk gibi

............anlık bir mahkumum ben 

....................boynumda ecel kayganlığı', 'dolaşırken damarlarımda lanetli bir yaşam dilimde lal dualar aralıksız adımlar peşinde aydınlık bir yarın serüvencisiyim kırılmış bir sazın ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Korkankorkmaz']::text[], 8.5, '{"poet":"Yılmaz Korkankorkmaz","poet_slug":"yilmaz-korkankorkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mahkum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudumsun', 'umudumsun-yilmaz-korkankorkmaz-qskqi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güvercin kanadına gizlenmiş umudumsun 

pencereden dışarıyı izlerken 

gözümü kamaştıran kar tanesi 

her gece boğulduğum 

gözlerin kadar masmavi bir deniz 

her gece boğulduğum 

gözlerin kadar ışıldayan yarınımsın

avuçlayarak içtiğim su kadar 

mecburumsun', 'güvercin kanadına gizlenmiş umudumsun  pencereden dışarıyı izlerken  gözümü kamaştıran kar tanesi  her gece boğulduğum  gözlerin kadar masma...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Korkankorkmaz']::text[], 8.5, '{"poet":"Yılmaz Korkankorkmaz","poet_slug":"yilmaz-korkankorkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umudumsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı', 'sizi-suskun-resital-3vnmr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duman tüter isi kalır 

Yara geçer izi kalır 

Sever seversin O da gider 

Sana bir tek sızı kalır....', 'Duman tüter isi kalır  Yara geçer izi kalır  Sever seversin O da gider  Sana bir tek sızı kalır.......', ARRAY['Türk Edebiyatı','Şiir','Suskun Resital']::text[], 8.5, '{"poet":"Suskun Resital","poet_slug":"suskun-resital","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sizi-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıratlar Üstünde', 'siratlar-ustunde-i-smet-barlioglu-6psbq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıldan ince, kılıçtan keskin Sırat ‘lar üstündeyim,

Çekilip alınmış elimden bilcümle düzlükler,

Canımın bedenimden çekilip çıkarılması gibi bir şey,

Dört bir yanım uçurum, altım cehennem,

Koparıp atma derinlerdeyim yaşamla aramdaki bağı,

Yapışmışım ellerimle bir karasevdanın eteklerine,

Beni kurtarırsa o kurtarır

Diye.

Belli ki; derelerden toplamışım bu ömrümü,

Ömrüne böylesine kıydığı görülmüş mü insanın? 

Sebil edip dağıtmışım yıllarımı bir karasevda uğruna,

Su edip akıtmışım, kuş edip uçurmuşum,

Bırakmışım aklımı başımdan alıp biryerlere,

Unutmuşum.

Sevenler bunca mı çeker bir sevda uğruna, bilemiyorum,

Ne hesaba geliyor çektiklerim, ne kitaba,

Ne tartmaya geliyor, ne ölçmeye.

Yokluyorum; yürek yaralı,

Yokluyorum; ciğerler yanık.

İşte bir hayattır yaşadığımı sanıyorum; 

Allahlık.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 33-34/100)', 'Kıldan ince, kılıçtan keskin Sırat ‘lar üstündeyim, Çekilip alınmış elimden bilcümle düzlükler, Canımın bedenimden çekilip çıkarılması gibi ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/siratlar-ustunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülerdim', 'gulerdim-i-smet-barlioglu-m6aq0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aynalarda seni görüyorum kendimi göreceğime,

Saçların benim kendi saçlarım,

Kaşların, gözlerin, benim kaşlarım, benim gözlerim,

Yanakların benim yanaklarım,

Dudakların benim dudaklarım,

Kirpiklerin benim kirpiklerim.

Ben; benim yerime seni koymuş olan

Ben ‘im.

Sızı sızı işleyip durmuşsun kemiklerime,

Kan olup damarlarıma işlemişsin ılgıt ılgıt,

Hançereme düğümlenen hıçkırık olmuşsun,

Kuruyan dudaklarıma feryat,

Yaralı yüreğime sonu gelmez inilti.

Varlığın varlığımdan çıkıp karşıma dikilen

Görüntü.

Yalan; benim gülüp senin aradığın,

Yalan; benden ayrı biryerlerde yaşadığın,

Yalan; gittiğin,

Yalan; uzaklaştığın,

Benden ayrı soluklar alabildiğin yalan,

Ben seni benimle gülen yaptım, benimle ağlayan yaptım,

İçimde seni yaşattım bir günahsız çocuk gibi,

Canımdan can verdim hayallerine,

Kanımdan kan verdim,

Çarmıhlara çekseler beni senin uğrunda; 

Gülerdim.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 35-36/100)', 'Aynalarda seni görüyorum kendimi göreceğime, Saçların benim kendi saçlarım, Kaşların, gözlerin, benim kaşlarım, benim gözlerim, Yanakların b...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gulerdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana kalmak', 'sana-kalmak-yucel-gursac-yytqp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnanır mısın

ölümü düşlüyorum bazen kıyısından

bir ucundan tutunca içimin

öbür ucundan çıkası geliyor hayallerim

çocuk gibi coşuyorum bazen kendi başıma

yalın ayak uydurmalarda

biliyorum vardıkça eksiliyorum yüreğimden

eksildikçe taşıyorum ümitlerimden

varsın eksilsin, taştıkça taşsın

kaldıkça kalıyorum ya sana

unutuveriyorum ya kendimi ansızın...', 'İnanır mısın ölümü düşlüyorum bazen kıyısından bir ucundan tutunca içimin öbür ucundan çıkası geliyor hayallerim çocuk gibi coşuyorum bazen ...', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sana-kalmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramak', 'aramak-gurbuz-kaya-i3fbd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umutsuzum dostum, gözlerim biçare bakıyor 

Yorgunum dostum, ayaklarım titriyor

Durgunum dostum, beynim  üşüyor

Yılgınım dostum, puslu düşünceler sardı her yanımı 

Nereye gitsem, nereye dönsem huzursuzum dostum

ben O''nu arıyorum...

Gönlümü, ruhumu rahatlatan 

Beni yoktan yaratan 

herşeyimi planlayan 

İlahi kudret sahibi tek taptığım

O yukarıdaki; 

düşüncelerimin sonsuzluktaki önünü gören 

herşeyin başı ve sonu 

O ilahi tek güç, hakim olan 

Allahımı arıyorum...

Kısacası dostum ; 

sanırım onu daha da çok hissediyorum 

bucaksız düşünceler kervanımda. 

Ve herşeyinde farkındayım eskisinden da daha çok.

Anıyorum O''nu 

Nasip olan ömrümün nefes alacağım kısmında.

Soruyorum dostum? 

Onsuz olur muyum? batıl hayatta...', 'Umutsuzum dostum, gözlerim biçare bakıyor  Yorgunum dostum, ayaklarım titriyor Durgunum dostum, beynim  üşüyor Yılgınım dostum, puslu düşünc...', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Kaya']::text[], 8.5, '{"poet":"Gürbüz Kaya","poet_slug":"gurbuz-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aramak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Ölmek', 'adam-olmek-yucel-gursac-k3ohf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adam doğmuş yıllar önce

daha adam değilmiş o zamanlar

bebek derlermiş ona

anlarmış da gülücük atmazmış etrafına 

yıllar bir ana olmuş bizim adamcağıza

büyütmüş, adam etmeye çalışmış

bizimki göğsünü gere gere söylenirmiş

''ben adamım artık, ben adamım''

ama bilmezmiş hala adam olmadığını

çocuk demeye başlamışlar ona

inat edermiş o da, ''ben adamım'' diye

delikanlı olmuş zamanla

ama o hala ''adamım'' dermiş

bir sürü kız sevmiş gençliğinde

aralarından birini seçene kadar

adam oldum diye evlenmiş onunla

kocam derken karısı,

damat dermiş kaynanası

terslemiş onları da ''hayır ben adamım'' diye

çocukları olmuş zamanı gelince

bir derken iki, iki derken üç

baba demiş hepsi ona teker teker

sevmemiş hiçbirini adam demiyorlar diye

torunları olmuş kızlı, erkekli

bakmamış hiçbirine dede dediler diye

adam deseler ya bir kere

dışarı çıkamazmış gündüzleri

neymiş, bir haylaz moruk demiş

ölmüş bizimki, zavallı demiş herkes

ama ermiş muradına toprakta

neden mi? 

mezar taşına koskocaman bir

''BURADA BÜYÜK BİR ADAM YATIYOR''

yazmışlar da.', 'Adam doğmuş yıllar önce daha adam değilmiş o zamanlar bebek derlermiş ona anlarmış da gülücük atmazmış etrafına  yıllar bir ana olmuş bizim ...', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/adam-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ben Birde Köyüm Can', 'bir-ben-birde-koyum-can-nilgun-yuce-eseqp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gelişim bir coşku,

Her dönüşüm; Hep hüsran.

Bağım bahçem olmuş,harman, duman.

Özlemine tutuştuğum orman..

Çocukluğum''da gençliğim''de

Yokluğun cenderesin''de

Kağıt kalem yoktu ben''de,

Okul diye her gidiş''de

Anam, babam, serzeniş''de..

Umutlarımı gömdüm,yüreğime.! 

Kelepçe vurdum gençliğime.! 

Tuttuğum dallar bile çürükce,

Anamın vasiyeti''de bende,

Olsun diye adina bir akar çeşme...

Alıp başımı gitsem''de

Arada bir gelsem''de

Dağlardaki otlak evime,

Yörük olan köyüme,

Hasret siner icime,

Adını bilmediğim kuşlar türkü''de

Suların''da kurbağalar cilve''de.,

Ana,baba,kardeş hepsi ahiret''de,

Öksüz kalan bir ben var; Benim içim''de

O''da,mahsur gurbet''de....

Her gelişim bir coşku,

Her dönüşüm; Hep hüsran.

Kızsam''da zaman zaman

Anamın ceşmesin''de; Hayat bulan,

Bir ben; Birde,Köyüm,köylüm,kaldı; Can

2.05.2005', 'Her gelişim bir coşku, Her dönüşüm; Hep hüsran. Bağım bahçem olmuş,harman, duman. Özlemine tutuştuğum orman.. Çocukluğum''da gençliğim''de Yok...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Yüce']::text[], 8.5, '{"poet":"Nilgün Yüce","poet_slug":"nilgun-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-ben-birde-koyum-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçmalı kendinden', 'kacmali-kendinden-yucel-gursac-uap7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir teknem olsa limanımda

yalnızlığa kucak açsam tek başıma

çeksem kürekleri korkularıma, hülyalarıma

adı bilinmeyen adalara, çok uzaklara

duygularım kabarır iki dalga boyu

bir dalga boyu ben, bir dalga boyu sen

acım iner iki kulaç derinlere

bir kulaç ben, bir kulaç içimdeki

korkutur beni arzular, erişilemesi mutluluktan

bir gün yitesi gelir, bir gün gidesi bakışların

korkutan beni kendimden

biliyorum bir buruşuk yatak değil...', 'Bir teknem olsa limanımda yalnızlığa kucak açsam tek başıma çeksem kürekleri korkularıma, hülyalarıma adı bilinmeyen adalara, çok uzaklara d...', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kacmali-kendinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istırabın Çağrısı...', 'istirabin-cagrisi-zulfikar-yapar-kaleli-wsywq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu aşkın ağında olmuşum tutsak,

Bir düş kelebeği sineme iner! 

Ruhumdaki seher rüzgarı ak ak,

Esince karanlık şafağa döner.

Sensiz bu şafaklar bu yükü çekmez

Bu yüzden eksilmez gözümün yaşı.

Gündüzler geceye zehrini dökmez

Bitmez içimdeki duygu savaşı.

Istıraplı, fakat acıdan bıkmaz

Sonbaharda bağlar dökse de gazel

İstemem dertlerim şifa bulsun az

Bu sızıyı dindirecek o güzel

Bir deryadan iki damla alınca

Ne derya eksilir, ne alan duyar

Sevda işi hal bilmeze kalınca

Tutar muhabbetin gözünü oyar

Gönle düşen çise çiçeğin teri

Yudum yudum yudumlarım kederi,

Her beterin mutlaka var beteri

Aşkınsa gönlümün koçağı eri', 'Bu aşkın ağında olmuşum tutsak, Bir düş kelebeği sineme iner!  Ruhumdaki seher rüzgarı ak ak, Esince karanlık şafağa döner. Sensiz bu şafakl...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istirabin-cagrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanlar Sultanı Yardan Arınmış', 'sultanlar-sultani-yardan-arinmis-zulfikar-yapar-kaleli-eleto', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bahar kokusunu alınca dağlar

Kardelen boy atmış kardan arınmış.

Ana ah ettikçe ırmaklar çağlar

Kemale özenmiş sırdan arınmış.

Desinler delisi, dünya tapulu

İki yüz gönüllü, üç yüz kapılı 

Keçi özentili, inek yapılı

Edepten, hayadan, ardan arınmış.

Yaban gülü gibi çöplükte bitmiş

Çarşıda, pazarda, meydanda yitmiş

Ve sonsuz kazancı eliyle itmiş 

Sultanlar sultanı yardan arınmış.

Bedelsiz beldenin, çölün çocuğu

Aslı velet, başı kelin çocuğu

Onun, şunun- bunun, elin çocuğu

Yalınayak meczup kârdan arınmış.

Ağzında marlbora, yanda flörtü,

Beyninde gezinir bin türlü dürtü

Altta kot pantolon, üste baş örtü

Örtünme bu mudur nurdan arınmış.', 'Bahar kokusunu alınca dağlar Kardelen boy atmış kardan arınmış. Ana ah ettikçe ırmaklar çağlar Kemale özenmiş sırdan arınmış. Desinler delis...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sultanlar-sultani-yardan-arinmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine gelirim', 'yine-gelirim-yahya-akbulut-z4i8u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğer bir gün... 

Güneş batmadan

yorgun ufkun pençesinde,

nefesi tükenmiş, ışıklar sönük

Ansızın kader kapımı çalarsa,

huzurluyum, bilirsin! 

Hiç arkama bakmadan, 

aşarım karanlığın yollarını.

Yağmurla birlikte

Gözlerden uzak...

Fırtına sonrası

Yine gelirim.', 'Eğer bir gün...  Güneş batmadan yorgun ufkun pençesinde, nefesi tükenmiş, ışıklar sönük Ansızın kader kapımı çalarsa, huzurluyum, bilirsin! ...', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-gelirim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye', 'hikaye-selman-faris-karakose-iqpeu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu bir hikayedir bakarsın, hikayelerde başka bir şehre gider,

Bir yaz günü başlamıştır sevda masalı ve en güzel yerinde yarimde gider.

Yolcudur, yoluna gider... Hancıdır, hanına gider... Aşıktır, aşkına gider...

Gider aşkına ama bir şeylerde gider, anlamazsın...

Anlatmak istersin, duyulmazsın...

Sonunda garip bir hikâye olursun, okunmazsın... 

Köşe bucak bekler seni bazen, en muhtaç anında tokat atarsın,

Ölmeye hasret kalırsın, belki zaman aleyhine işler,

Bomboş bir tual gibi anlamsız olursun,

İşte o zaman, sevdam kalır ama yarim gider.

Güneştir, batmaya gider... Mektuptur, vuslata gider... Nehirdir, deryalara gider...

Gider deryalara, yolu bellidir, menzili bellidir,

Bir çağrıdır... o seni bekler,

Sonunda varırsın sevdiğine ve acılarda gider... 

Sonra bir hasrettir ki, tam bir zulümdür ve en feryatlı döneminde hasrette gider.

Yine yolcudur bütün karanlıklar,

Yine başlar kokmaya tüm karanfiller,

Geceler uykusuz geçer, gündüzler ardınca sıraya girer.

Unut denilen bütün kötülerde gider.

Şiirlerinde seni anlatır,

Yıldızlarda yüzünü çizer,

Bütün parçalar birleşir bir an, hiçbir şeyi gözün görmez,

Haylaz çocuk içinde canlanır birden,

Ve en çok ben seviyorum der.

Beyaz bütün bulutlar senin için,

Bütün kuşlar, bütün ağaçlar senin için,

Bunları görmen için ömründen bir ömür daha gider.

Ömürdür, durağı belirsiz bir tren gibi,

Mutluluktur, sonsuz sanılan gülücüklerden bir demet,

Ama gün gelir ihanet boy boy serilir önüne

Ve o haylaz, uslanmaz çocukta gider.

Bir bakarsın her şey daha güzel olmuştur ve en umulmadık zaman güzelliklerde gider.

Sahnelenir bütün ayrılık oyunları,

Bin bir bahane uydurulur kırılmamak için,

Umutlu bir ses tonu ama sadece yalan,

Bir yalanın kollarında umutlarımda gider.

Şarkılar küser hayata, 

En güzel olanı acıyı anlatandır senin için,

Solmuş bir karanfil yaprağıdır her şey,

Umudun yarını yok ve sevdiğinle birlikte yarınlarında gider...

Biliyor musun neler çıkar kaşına şimdi? 

Aynaya bakınca nasıl bir soru soracak sana? 

Ve sen nasıl cevap vereceksin sorulara? 

Aşktır bu, hiçbir şeye benzemez,

Sonra o aynaya baktığın yüzde gider.

Ben bakamaz oldum resmine şimdi,

Ben yazamaz oldum şiirleri şimdi,

Mutluluklara peşkeş çekilmiş bir yalan oldum şimdi,

Ve gün gelir o yüzündeki mutluluklarda gider.

O zaman, o delikanlı dersin, seviyordu dersin,

Seni seven kişileri bir bir kaybedersin,

Deli divane gibi aranırsın sahte olmayan bir tebessüm,

Bir tek gün bile uyku girmez gözüne,

Neden böyle diye sorarsın kendine,

Biraz hatıraların içinde kaybolursun,

Leş gibi kokan bir bataklığın içinde,

Bembeyaz bir el uzanır, o hatıralardan sana,

Senin için oradadır belli ki,

Ama çabuk olmazsan o elde gider...

Her şey senin içinken,

Bütün kaçışlar, bütün aldanışlar,

Okuduğun bu şiir, bir köşedeki gülen resmim,

Seni seviyorum diyen bütün her şey,

Yüreğime kazıya kazıya yazdığım adın

Ve sana doğru attığım her adım,

Ama dikkat et sevdiğim gün gelir,

Bir hiç olursun ve saha doğru attığım adımlarda gider.

Her şeye rağmen unutma, umudumu adadığım güzel kız...

Samimiyetimden şüphe duyma ki,

Sen gidersin aşkın kalır,

Şu yüreğimdeki yara gider ama mührü kalır..

Selman Faris KARAKÖSE

(12.08.2002 - İzmir)', 'Bu bir hikayedir bakarsın, hikayelerde başka bir şehre gider, Bir yaz günü başlamıştır sevda masalı ve en güzel yerinde yarimde gider. Yolcu...', ARRAY['Türk Edebiyatı','Şiir','Selman Faris Karaköse']::text[], 8.5, '{"poet":"Selman Faris Karaköse","poet_slug":"selman-faris-karakose","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/hikaye-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Kalan Yalnızca Umutsuzluğum', 'bana-kalan-yalnizca-umutsuzlugum-selman-faris-karakose-0pz4n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Burada sevdiğim yok... mavi bulutlarda gitmiş...

Yazın en mutlu sıcağında terk etmişler beni.

Yapayalnız kalmışım bir başıma. Yaralı gibi sere serpe...

Bu şehir beni bitiremez demiştim bir zaman önce, yanılmışım.

Sevdiğimden uzağım şimdi. Burada yalan sevgiler içinde bunalmışım.

Nerede şimdi bilmem ki, gözlerimi daha da bir canlı açtığım günler? 

Yıkılmam asla dediğim kelimelerin ahtı tuttu belli ki! ...

Bozuk para gibi harcadım ömrümü şu çıplak şehirde...

Burada sevdiğim yok... mavi bulutlarda gitmiş...

Burada dostlarım yok... hayallerimde gitmiş...

Denize düşmüşüm, sarılacak yılan arıyorum.

Bir dost sesine muhtacım şimdi. Burada her şey çok anlamsız.    

Bir kahvede kağıt oynamayı, rengi atmış çayı içip birde onun hesabını ödemeyi özledim.

Sabahlara kadar sohbet edecek bir yüzden ırak ortamlarda tükettim kendimi.

Düştüğüm zaman kaldıracak kişiler nerede acaba? Biliyorum... onlar çok uzakta.

Şimdi haykırıyorum ve sesimi duyarlar umarım...

Burada dostlarım yok... hayallerimde giymiş.

Burada ailem yok... tesellilerimde gitmiş...

Akşam vakti gidecek, sıcak, mutlu bir evimin olması ne güzelmiş meğer...

Sıcak bir çorba içmek bir ayrıntı değil... anladım.

Babamın her an sitemkâr bakışları ve annemin ümit dolu sözcüklerini kaybettim.

Ufak tefek de olsa yediğim fırçaların hatırı kalmış anlaşılan.

Olsun be... o kadar da olsun.

Büyük hayallerimi sığdırdığım o ufacık odama hasret düştüm.

Kimseye görünmeden gecenin bir vakti balkona çıkıp sigara içmek,

Ve sonra hülyalara dalıp uyumak ne güzel şey...

Burada ailem yok... tesellilerimde gitmiş...

Burada çocukluğum yok... misketlerimde gitmiş...

Sokağımın aşınmış yokuşunda top koşturduğum günler çok uzakta.

Tadına varamadan geçen yıllarımın ardından baka kaldım şimdi.

Ayva ağaçlarına dadandığımız, saklambaç oynadığımız, 

Okula giderken unuttuğum yakalığım, Ali Amcanın küfür ederek kovalaması,

Kırdığımız gece kondu kiremitleri, Yavuz, Eyüp, İbrahim...

Hepsi yıllar önce gitmişti. Sadece arkalarından el sallamaktı bana düşen...

Ama şimdi daha da özlettirdiler kendilerini. 

Kim bilir, hangi sokağın parke taşlarında, dert çekiyorlardır şu an.

Sokağın bakkalından zar zor denkleştirdiğimiz parayla aldığımız leblebi tozu,

Bahçede oynadığımız misketlerimiz, hatta bahçemiz bile...

Hepsi gittiler.

Vardiyeli bir hayatın gündüz kısmını da alıp götürdüler yanlarında,

Bana yalnızca geceyi yaşamak kaldı...

Burada çocukluğum yok... misketlerimde gitmiş...

Burada şafak yok... gündüzlerde gitmiş...

Bir ben kalmışım ortada yalın ve sessiz, giden onca şeyin ardından. 

Ümitlerim başka bir şehirde kaldı. 

Bir ben kaldım ortada, yalnızlığın çığlığı gibi manasız olmuş her şeyim.

Yaşanan her şey, karanlıklar ardında bir sır misali meçhule karışıyor,

Yitiriyorum damarlarımdaki kanı, yardım edin diyen feryatlarım yankılanıyor.

Bunalmışım, arlanmışım, utanmışım, yıkılmışım, kovulmuşum.

Yeter artık...

Bütün güneşler benden öteye kaçmış. Ne yaptım da, cezası bu oldu? 

Hata nerede? ...

Kimler çaldı benim mavi bulutlarımı, nerede unuttum hayallerimi acaba,

Hangi rüzgarın önüne katılmış tesellilerim, ne zaman kayboldu misketlerim,

Ve gündüzlerim, gündüzlerimde yalan söyledi bana...

Burada şafak yok... gündüzlerde gitmiş...

Selman Faris KARAKÖSE

(05.09.2002 - İzmir)', 'Burada sevdiğim yok... mavi bulutlarda gitmiş... Yazın en mutlu sıcağında terk etmişler beni. Yapayalnız kalmışım bir başıma. Yaralı gibi se...', ARRAY['Türk Edebiyatı','Şiir','Selman Faris Karaköse']::text[], 8.5, '{"poet":"Selman Faris Karaköse","poet_slug":"selman-faris-karakose","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/bana-kalan-yalnizca-umutsuzlugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildiğim Yer', 'bildigim-yer-selman-faris-karakose-6r0hy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün başımı alıp gideceğim buralardan. 

Herkes kadar eski, herkes kadar yeni bir yerlerlere. 

Hiç kimsenin konuşmadığı, sadece gönülleriyle muhabbet ettikleri bir yerlere, 

Güneşin sadece bir kez doğduğu ve sadece bir kez batacağı, 

Hiç kimsenin olmadığı ama aslında 

Çevrende herkesin olduğu bir yerlere. 

Açan her çiçeğin göz yaşı yere düşmeden kurumadığı 

Yani hiç göz yaşı olmayan, 

Aradığın herşeye inat hiçbirşey bulacağını bildiğin bir yer! 

Bir gün başımı alıp gideceğim buralardan. 

Yanımda herşey değerinde hiç birşey, 

Hiç birşey değerinde herşeyi götüreceğim... 

Aldığım yükün ağırlığı kadar hafif hüzün 

Ve belki son cümleyi dahi söylemeden, 

Hiç kimse görmeden, hiç kimse duymadan, 

Belkide ben bile uyanmadan usulca. 

Sessizliğin çığlık olmadığı, yağmurun yağmadığı, 

Kırılmayacağım, dökülmeyeceğim, tükenmeyeceğim 

Desdursuz bir yerlere. 

Yolu hiçde karışık olmayan ama geri dönme ihtimali sıfır olan, 

Sıcağın terletmediği, soğuğun üşütmediği.

Kimsenin gitmek istemeyeceği kadar ürpertici 

Ama mecbur….. olabilen, 

Belkide her kesin benim kadar gitmek isteyeceği 

Cennetvari bir yerlere. 

Anlam kargaşasından uzak, 

Kavram kargaşalarına meydan vermeyecek kadar sakin! 

Bir gün başımı alıp gideceğim buralardan...

Dedimya yanımda hiç birşey kadar herşey, 

Herşey kadar hiç bir şey götüreceğim. 

Yani tek başıma, tek tabanca, yalnız bir kardelen çiçeği gibi 

Ve gün olmayacak, belki gün dönecek 

Bir daha hiç gitmeyecek kadar yakın biryerlere. 

Ne bir adrese, ne bir klavuza ihtiyacım var...

Ben bu yeri biliyorum..... 

HER HARİTADA BİR KABRİSTAN VARDIR.... 

Selman Faris KARAKÖSE         

(06.01.2004 - İstanbul)', 'Bir gün başımı alıp gideceğim buralardan.  Herkes kadar eski, herkes kadar yeni bir yerlerlere.  Hiç kimsenin konuşmadığı, sadece gönülleriy...', ARRAY['Türk Edebiyatı','Şiir','Selman Faris Karaköse']::text[], 8.5, '{"poet":"Selman Faris Karaköse","poet_slug":"selman-faris-karakose","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bildigim-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Dostum', 'merhaba-dostum-adulera-ayza-jeiml', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle az yürümedik bu sosyalist kaldırım taşlarında

Kolay değil bir ömür verdik bu inanç dolu davamıza

İnandığımız inanç uğruna boşladık anamızı da avradımızı da

Kimimiz öldü bazılarımız da oyun sandı yazdığımız duvarlara

Çekiç oraklı isyan yazılarımızı da

Denizi Yusuf u İbrahim i aldık örnek

Onlar gibi savaştık onlar gibi gençtik yaşlandık ama onlar gibi ölmedik ölemedik

Şimdi senle kelaynak kuşları gibiyiz tükendi neslimiz

Bakıyorum şimdi ki gençliğe ya uyuşturucu ya da bağımlısı olmuşlar bir maddenin

Hal bu ki ciğerimiz parçalanırdı yaralı ise kanadı yoldaki gördüğümüz bir serçenin

İki dakika sohbet etsen hocam bunlar eskiden di diyorlar geçelim

En güzel yaptıkları iş uyuşturucudan sonra hatırlamadan sabahlara kadar sevişelim

Bizler değişmezdik onlarca volta atmayı evlerinin önünden geçerken sevdiğimizin 

Gizlice verdiğimiz alelacele yazılmış şiirli yarısı yanık mektuplu resimlerin

Şimdi ise gençler bulmuş kolayı gir bir internete çetleşelim 

Ne bir haz ne bir duyarlılık sadece sanal ortamda çırılçıplak sevişelim

Hiçbir zaman görüşmeden alem yansın biz bu alemde elele gezelim

Kemikleri sızlıyor bu ülke için yağlı urganları boynuna geçirenlerin

Sohbet sırasında soruyorsun bilir misin börtiçene yi can yücel i nazım ı 

Diyorlar ki az bekle amca daha alamadım hızımı 

İçimden gülüyorum tabi ki dostum böyle giderlerse öperler bunların bacısını

Zaten bir oniki eylül var ki kimse unutamaz Erdal ı n cuntanın acısını

Alem gümlemiş biz eskidik be dostum cebimizden çıkarırız bunların en akıllısını

Anımsar mısın bilmem bir eylemde  yakalamıştı zabitler köyün en iyi hacısını

Her zaman kulağıma küpe senin bir sözün var onu bilirim onu söylerim

Bu ülkede “sağcıların bu  günkü konumu onlara korkak solcuların lütfudur “

Tüm dünyadaki mücadeleci inançlı  solculara son sözüm bumudur budur

Kendimi bildiğimden beri tehlikeli şiir okur ve yazarım

Bu Ülkede Ya Tarafsınız Yada Tararftarsınız.', 'Seninle az yürümedik bu sosyalist kaldırım taşlarında Kolay değil bir ömür verdik bu inanç dolu davamıza İnandığımız inanç uğruna boşladık a...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/merhaba-dostum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabrettim İşte', 'sabrettim-i-ste-selman-faris-karakose-2jfge', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İsmini yazıyorum ismimle birlikte

Ve ismini süslüyorum çiçeklerle güllerle

Bir resmin bile yok elimde,

Yok işte gözlerim gözlerinde,

Ne de sözlerim sözlerinde.

2 yıl geçmiş aradan,

Kolay mı sence? 

Sabrettim işte! 

Belki kavuşurum diye,  belki tutarım ellerinden,

Belki bakarım gözlerine yine.

Hiç bırakmayacakmışçasına, bağlansam gözlerine yine.

Bağlandım ya özlemine, ağladım ya hasretine,

Kahroldum ya sensizliğe,

Bittim, tükendim işte.

En son iki yıl önce, doya doya baktım sana

Ve bir daha asla girmedim rüyalarıma,

Hiç uğramadın umutlarıma, merhem olmadın yaralarıma.

Aynaya her baktığımda yıkıldım daha fazla.

Uğramıyorsun rüyalarıma.

Gözden ıraksın tamam ama, gel gir rüyalarıma...

Yürü yol olayım yollarına,

Koş rüzgar olayım saçlarına

Sabrettim işte! 

Bir resmin bile yok elimde.

Bir ismin var sadece yüreğimde.

Bir de kabuk bağlamış bir yara.

Adını her duyuşumda

Ve seni her hatırlayışımda kanayan

Kanadıkça büyüyen, 

Büyüdükçe kapanmayan bir yara.

Ben bir keşim...

Özlemeye, kahrolmaya, yıkılmaya,

En çok da senin aşkına sevda keşim.

Hiç hatırlamıyorum en son ne zamandı

Gözlerimin önünden geçişin,

Geçip gidişin

Sabrettim işte

Günler geçti umarsızca,

Hesapsız ve insafsızca,

Hiç arkama bakmadım, acı çekmemek için

O günleri hatırladıkça

Dermansız kalmamak için 

Ama bir kez daha görsem seni.

Kader gülmez ki bana,

Ama birde gülerde ellerinden tutarsam

O zaman beklerim yeniden seni  senelerce

Tamam ağlarım belki, tamam sızlanırım belki

Yine kanar yaram, sonra kabuk bağlar belki

Ama olsun yinede beklerim, yinede severim

Yinede sabrederim

Sabrettim işte! 

Sabretmek alnıma yazılmış benim.

Bir de sevmek yazılmış alnıma.

Hiç bakmadım ardıma

Yalan yok ağladım, uyuyamadım aylarca.

Geride onlarca kaybettiğim şey

Ama tek önemli bir şey, mutluluğu kaybettim,

Gülmeyi kaybettim...

Hayatın her anı bir tümsek önümde.

Aşabilirsem dedim,

Eğer aşabilirsem kavuşurum sevdiğime.

Aştım işte, geldim işte,

Karşında dimdik ayaktayım işte. 

Sabrettim işte! 

Gözlerin gözümün önünde artık, 

Sözlerin özlemin önünde artık.

Sabrederim gayrı, ama bir dokunsaydım ellerine.

Buz tutmuş ellerim,

Hava soğuk değil ki niye? 

İki kelimeydi boğazımda düğümlenen

Artık söylüyorum

SENİ SEVİYORUM.

Selman Faris KARAKÖSE

(12.03.2001 - İstanbul)', 'İsmini yazıyorum ismimle birlikte Ve ismini süslüyorum çiçeklerle güllerle Bir resmin bile yok elimde, Yok işte gözlerim gözlerinde, Ne de s...', ARRAY['Türk Edebiyatı','Şiir','Selman Faris Karaköse']::text[], 8.5, '{"poet":"Selman Faris Karaköse","poet_slug":"selman-faris-karakose","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/sabrettim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildiğim misin(!)', 'bildigim-misin-sule-aydemir-55vsa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-ah be 

ah be sarı gelin

portakal çiçeğine mi 

aşkın

-ah be portakal çiçeği

gelinciği 

bilir misin ki

yaslandın

ah ha

ha parçalandı

ha parçalanacak

daha öncesi

nasıl parçalandı 

bilir misin

-yok be gülüm

yarımsın

nasıl yarımdır

yanıldığı

yanıldığımsın

hissedebilir misin

ağlardım

ağlar

ağlardı

bir gelin-cik

yine bil 

cahilim

uçuyor

görmüyor musun

sarı bir güvercincik

____________acıtıyor bildiğim

___________________bilir misin? ...', '-ah be  ah be sarı gelin portakal çiçeğine mi  aşkın -ah be portakal çiçeği gelinciği  bilir misin ki yaslandın ah ha ha parçalandı ha parça...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bildigim-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bebeğim', 'ah-bebegim-yavuz-agir-ofcta', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deryaları göl; 

Ovaları çölmü sanırsın.

Dereleri pınar; 

Şarıl şarıl akan suları; 

Düşlerinde  yokmu sanırsın...

Abenim güzel bebeğim; 

Sen beni ne sanırsın..

Kime benzetir,kime satarsın

Değerimi nasıl biçersin.

Sen beni ne sanırsın; ne sanırsın.....', 'Deryaları göl;  Ovaları çölmü sanırsın. Dereleri pınar;  Şarıl şarıl akan suları;  Düşlerinde  yokmu sanırsın... Abenim güzel bebeğim;  Sen ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ah-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak dur', 'uzak-dur-yucel-gursac-7iain', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerin soğudu son günlerde

gözlerin kilometrelerce bakıyor bana

dudakların büküldü iki büklüm

biliyorum

artık sevmiyorsun beni

belli ki artık uğramayacaksın geceleri

olsun

gelme

istemem

yakmıyacaksa nefesin tenimi

sarhoşluğunla rezil etme kendini

yıllanma benimle, derdimle, dertlerimle

ama saçlarını da savurma öyle yüzüme

çıldırtma bedenimi

değdirme ellerini ellerime

üfleme nefesini tenime

uzak dur benden

ne olur ağlatma beni

bilirsin

ağlamak yakışmaz bana...', 'Ellerin soğudu son günlerde gözlerin kilometrelerce bakıyor bana dudakların büküldü iki büklüm biliyorum artık sevmiyorsun beni belli ki art...', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzak-dur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüm ecele...', 'kustum-ecele-yucel-gursac-o98eo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gençtim

babam evden kovmuştu

bir pazar günü tekme tokat

sevgilim terk etmişti

bakmaya doyamadığım dudaklarını

öpmedim diye

canımdan bezdim sonunda

dostlarım da beni terk edince

dayımın bir silahı vardı

çaldım onu evinden

tetiği yokmuş

sıkamadım kurşunu beynime

bir evin dördüncü katından atladım

sol ayağım kırıldı

bir ay sonra taburcu oldum hastaneden

asayım dedim kendimi

tavan çöktü

üç gün sonra çıkardılar enkazdan

tam açlıktan ölmek üzereyken

dayanamadım küfrettim ölüme

gelmişine, geleceğine

küsüs ecelle o günden beri

yılardır ne ben onu ararım

ne de o

sorar beni...', 'Gençtim babam evden kovmuştu bir pazar günü tekme tokat sevgilim terk etmişti bakmaya doyamadığım dudaklarını öpmedim diye canımdan bezdim s...', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kustum-ecele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışın Yeter Bana', 'bakisin-yeter-bana-nesrin-gocmen-9j90p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aklında gül, sümbül, nilüfer olsa da

Şefkatli kolları boynuma bir dola

Bin özlemle kokla, öp ardı ardına

İster unut sonra istersen anımsa

. 

Bir günlük de olsa çare ol derdime 

Nergisden, laleden, sümbülden bana ne? 

Bakışın kalsın yeter giderken o yerde

İster konuş sonra istersen arama

.

21/05/2005', 'Aklında gül, sümbül, nilüfer olsa da Şefkatli kolları boynuma bir dola Bin özlemle kokla, öp ardı ardına İster unut sonra istersen anımsa . ...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bakisin-yeter-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş', 'tas-ayhan-yavuz-acikgoz-3979i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Avucumda sıkınca,

                   kanatır, acıtır ve ağlatır...

Canını yakar en sevdiklerimin,

                   fırlatınca öfke ile...

Ayağımı alıkoyan ve salıveren bedenimi toprağa,

                                                                    parçalarcasına...

Hamallığımın en ağır yükü, ardından

                                             ölesiye yorgun,

                                             ölesiye bıkkın bir ben...

Öyle sert ve keskin,

Öyle soğuk,

Öyle duygusuz,

Öyle ağır ve zahmetli...

Ömrümün en kötü izlerinin sanatkârı...

Hep üzen,

Hep ağlatan,

Küfrü en çok hakettiğini zannettiğim,

Yegâne nesne...

Taş...

Şimdi en yakın dostum, bağrıma yaslanmış...

Yosun tutmuş üzerinde,

                        ark olan gözyaşımın istikameti...

Belki tek tesellim...

Ta ki dönene kadar sen...

(istanbul-20.05.2005)', 'Avucumda sıkınca,                    kanatır, acıtır ve ağlatır... Canını yakar en sevdiklerimin,                    fırlatınca öfke ile... ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tas-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryad Tanımaz Vekûd', 'feryad-tanimaz-vek-d-ayhan-yavuz-acikgoz-gf43v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dünya aşık saklar, kalbimde her bir hudûd

Yürekten damlayanın, kıymetin bilmez vücûd

Eğer aşkın bedeli ölmek ise o yolda

Ölürüm her sâniye, sevdiğim olsun Vedûd

Kalkmasın seccâdeden, nasır bağlasın alnım

Bedel bin saltânata, eylenen bir tek sücûd

Aşktır benim özlemim, bilmem nedir han hamam

Evlâ bir karış cennet, tüm arz edilse mev''ûd

Ger dönersem sırtımı, gün gelir hakîkate

Kana kesilmiş gözler, olur katlime şuhûd

Bilirim ki her nefis, tadıcıdır ölümü

Verse de tüm servetin, arzda değildir ku''ûd

Ey Ayhan''ım meyletme, dünyanın ziynetine

O da yanar seninle, ''feryâd tanımaz vekûd''

(istanbul-20.05.2005)', 'Bir dünya aşık saklar, kalbimde her bir hudûd Yürekten damlayanın, kıymetin bilmez vücûd Eğer aşkın bedeli ölmek ise o yolda Ölürüm her sâni...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/feryad-tanimaz-vekud-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Bana Eyvallah', 'haydi-bana-eyvallah-suheyl-turkoglu-7q19a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidiyorum dostlar,

Kızmayın bana,

İsteğim değil,

Sürgündeyim,

Mecburum,

Haydi bana eyvallah.

Aşkı tanıyamadım,

Başım döndü,

Bocaladım,

Bazen doldum,

Bazen de,

Özlemini yaşadım.

Sevgi sofrasında,

Adam gibi doyamadım,

Delice yuttum,

Çiğnemeden lokmaları,

Yalanlarla gerçeği,

Ayıramadım.

Tıka basa yedim,

Karnım aç kalktım.

Çok sevdim güzelliği,

Duvar ördüm etrafına,

Bütün gücümle,

İçine gömüp,

Yok etmeye çalıştım,

Çirkinlikleri,

Beceremedim.

Teslim oldum,

Dostluğa,

Lanet olası,

Çıkar virüsleri,

Dostlarımı,

Tanıyamadım.

Sadakat kavramını,

Yerle bir etti,

Zalim menfaat,

Beynim allak bullak,

Çok düşündüm,

İçinden çıkamadım.

Işık aradım,

Karanlıktayım,

İçimi kemiriyor,

Gelecek kaygısı,

Çocuklarıma düşündüğüm,

Dünyayı sunamadım.

Gidiyorum dostlar,

Küstüm sanmayın,

Benimkisi sürgün,

Sakın ha,

Arkamdan ağlamayın,

Yazık etmeyin gözyaşınıza,

Sizlere kalan,

Değerlere ağlayın.

Haydi bana eyvallah.', 'Gidiyorum dostlar, Kızmayın bana, İsteğim değil, Sürgündeyim, Mecburum, Haydi bana eyvallah. Aşkı tanıyamadım, Başım döndü, Bocaladım, Bazen...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/haydi-bana-eyvallah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 1', 'rubai-1-ayda-yildiz-r8tym', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ictigin suyun ustune su ekleyip icmedimmi

  Sacimdan tutam kesip sana vermedimmi

  Arkandan kosup, tozu topraga karistirmadimmi

  Neden, sana yazdiklarimi tutmadin, inanmadinmi?', 'Ictigin suyun ustune su ekleyip icmedimmi   Sacimdan tutam kesip sana vermedimmi   Arkandan kosup, tozu topraga karistirmadimmi   Neden, san...', ARRAY['Türk Edebiyatı','Şiir','Ayda Yıldız']::text[], 8.5, '{"poet":"Ayda Yıldız","poet_slug":"ayda-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-1-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Yavruyla Yaşadığım', 'kucuk-bir-yavruyla-yasadigim-zeynep-nilgun-gokceoz-03wqw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün sokak çocuklarıyla ilgili bir yazı okurken eski bir anım canlandı gözlerimin önünde. Unuttuğumu sandığım bir duygu yüreğimden kopup geldi ansızın. Yavaşça, bir köşeye gizlediğim bu anımın üstündeki örtüyü aralayıp sizlerle paylaşmayı düşündüm.

Belki çok uzun değil ama yine de yıllar önceydi. Küçük bir ilde yaşıyordum ve insanların sorunlarını daha çabuk görme şansına sahiptim. Her sene kendi imkanlarımızla topladığımız paralarla kıyafet, oyuncak ve kırtasiye gibi ihtiyaçları alarak Çocuk Esirgeme Kurumu’na giderdik. Onlara küçük bir parti düzenleyerek, müzik eşliğinde hediyelerini verip türlü oyunlar oynardık. Genelde bu tür partiler hüzünle başlar hüzünle biterdi. Çoğumuz ayrılma vaktinde oradan ağlayarak ayrılırdık. Yaş grubu genelde 3 – 12 arasındaydı. Öyle meraklı ve sevecen bakarlardı ki bizlere sevgiye olan susuzluklarını hemen hissederdik. Götürdüğümüz pastaları, çörekleri yedikten sonra onlarla oyunlar oynar dans ederdik. Bazılarının ağlayarak sümüklerini çekmeleri bizi derinden yaralardı. O manzarayı sevgiye ve açlığa tok insanların görmelerini çok isterdim. Yanlarına gidip başlarını okşadığımız zaman ellerimize öyle yapışırlardı ki yüreklerimizi tuttuklarını sanırdık. Küçücük elleriyle, kaybettikleri sevgileri tutmak istemelerinin heyecanını onlarla birlikte yaşardık. 

İçlerinden bir tanesi dikkatimi çekmişti. Sanıyorum üç yaşlarındaydı. Bir kenarda oturmuş elindeki kırık oyuncağa bakarak sessizce ağlıyordu. Onu öyle görünce içimin parçalandığını hissetim. Kendi çocuklarım aklıma geldi. Nasıl da bir gül gibi koklayarak, kollayarak büyütüyorduk. Acaba nefes alıyorlar mı diye gecede sayısız kereler kalkıp nefeslerini dinliyorduk. Bu düşüncelerle yanına gittim ve “ ne oldu bebeğim” diye sordum. Başka bir oyuncağı görmüştü ve onu istiyordu. Ne yazık ki o oyuncakta başka bir yavrunun elinde ona mutluluk veriyordu. Almamın imkansız olduğunu anlamıştım. Ne söylesem dinlemedi, gittikçe daha yüksek seste ağlamaya devam etti. Kucağıma aldım ve ikimiz yere oturduk. Saçını okşayarak “seni seviyorum” diye fısıltıyla kulağına vazgeçmeden söyledim. Önce aynı tempoda ağlamaya devam etti fakat bir müddet sonra ağlamasının azaldığını fark ettim. Saçlarını okşayarak çocuklarıma söylediğim anne ile ilgili bir ninniyi severek, sevgiyle söyledim. Artık sakinleşmişti. Başka oyuncaklarla bir çok oyun oynadık. Gideceğimi anlar gibi yanımdan hiç ayrılmadı, elimi hiç bırakmadı. Bir müddet daha oyalandıktan sonra gitme vakti gelmişti. Sanki yüreğimi bir şeyler sıkıyor, boğazıma düğümler sıralanıyordu. Yavaş yavaş belli etmeden yanından uzaklaşmaya başladım. Tam oldu derken arkamdan koşan bir sesle olduğum yerde öylece kaldım. Ağlayarak “anne gitme” diyordu. Koşarak geldi ve bacaklarıma sarılarak ağlamaya devam etti. Durmadan tekrarladı “anne gitme, anne gitme”. İşte o an kendimi tutmanın imkansızlığını anladım. Ona sarılıp onunla birlikte bende çaresizce ağladım, ağladım. Yapabileceğim hiçbir şey yoktu. Ben bunu çok iyi biliyordum fakat o bilmiyordu. İşte bu yaşamında yaşadığı belki ilk acımasızlıklardan biriydi. Onu tatlı yalanlarla kandırıp arkama bakamadan kaçarcasına uzaklaştım oradan. 

Eve gidince saatlerce düşündüm ne yapabilirim diye. Çözüm bulamadım. Küçük olmalarına rağmen çocuklarımı karşıma alıp ne kadar şanslı olduklarını anlattım. Binlerce annesiz, babasız, sevgiye muhtaç çocukların var olduğu düşüncesi beni kahretti. Bugün hala bu duygularla yaşamaya devam ediyorum. Bazen düşünmemeyi, görmemeyi denesem de vicdanımın isyanını yüreğimin derinliklerinde duyuyorum. 

Şimdi ne zaman ağlayarak “anne gitme” diyen bir çocuk sesi duysam göz yaşlarımın firar ettiğini hissederim. Hep anne, baba sevgisi görmeden büyüyen çocuklar için yüreğim sessizce yas tutar. Onların yüzüne bakmaya korkarım, yıllar önceki o çaresiz kaçışımı görmesinler diye. Ama onlar için verecek kocaman bir yüreğim, sonsuz sevgilerim ve onları terk etmeyen dualarım olduğunu hissedeceklerine bütün kalbimle inanıyorum..', 'Bugün sokak çocuklarıyla ilgili bir yazı okurken eski bir anım canlandı gözlerimin önünde. Unuttuğumu sandığım bir duygu yüreğimden kopup ge...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kucuk-bir-yavruyla-yasadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Bilinçler', 'ac-bilincler-turk-oger-koc-yaene', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha çocukken başlar

her kıpırtıya aç bilinçler

büyümek ne fayda

çocuk kaldıkça yürekler 

sevgi dolu, afacanlık dolu

bilgiye aç bakan gözler

eskitmesin zaman seni güzelim

yüreğindeki ışıltılar

zaman, zaman yaksa da beni', 'Daha çocukken başlar her kıpırtıya aç bilinçler büyümek ne fayda çocuk kaldıkça yürekler  sevgi dolu, afacanlık dolu bilgiye aç bakan gözler...', ARRAY['Türk Edebiyatı','Şiir','Türk Öğer Koç']::text[], 8.5, '{"poet":"Türk Öğer Koç","poet_slug":"turk-oger-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ac-bilincler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yol Bulamadım', 'bir-yol-bulamadim-enver-bahcekapili-5erv9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalem elimde,

Kağıt önümde,

Hayata bakıyorum,

Geçmiş, ozan,yazar, ressam, müzisyenleri,

Topyekün ustaları hayalliyorum...

Nazım gibi düşünüyor, yazamıyorum.

Bicasso gibi görüyor, çizemiyorum.

Bethoven''den daha içten, daha derin

Hayatı mırıldanıyor, anlatamıyorum.

Ben, ben olmak istiyorum,

Aşk, umut, barış, yaşam dolu fikirlerimi

İfade edecek yol bulamıyorum! 

Öyle bir çıkmazdayım ki

Tarifi yok,

Patlıyorum...

16.01.1981', 'Kalem elimde, Kağıt önümde, Hayata bakıyorum, Geçmiş, ozan,yazar, ressam, müzisyenleri, Topyekün ustaları hayalliyorum... Nazım gibi düşünüy...', ARRAY['Türk Edebiyatı','Şiir','Enver Bahçekapılı']::text[], 8.5, '{"poet":"Enver Bahçekapılı","poet_slug":"enver-bahcekapili","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-yol-bulamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ferdi''ye...', 'ferdi-ye-emirhan-bala-kehan', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Farz etki sana aşığım,

Elim sana mahkum,

Raks etse de seninle ruhum,

Dünya benim ne umurum,

İlham perim sen olduktan sonra…', 'Farz etki sana aşığım, Elim sana mahkum, Raks etse de seninle ruhum, Dünya benim ne umurum, İlham perim sen olduktan sonra…...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ferdi-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenigün sokakta', 'yenigun-sokakta-soner-polat-zy4zx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yenigün sokakta

bir sokak var

adı güzel bahar

nasıl söylesem

gül kokuları

yüreğinizi okşar', 'yenigün sokakta bir sokak var adı güzel bahar nasıl söylesem gül kokuları yüreğinizi okşar...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yenigun-sokakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-turgut-onal-jiv9z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günaydın kuşlar, horozlar

Günaydın çocuklarım

Günaydın evimin güneşi

Sevgili karım

Günaydın bacası tüten fabrikalar

Günaydın işçi kardeşlerim

Günaydın okula giden çocuklar

Sınırda nöbet tutan askerim

Günaydın mavi deniz, akarsu

Günaydın cömert, bereketli toprağım

Günaydın bir uçtan bir uca

Uzayıp giden yollar

Vatanım, halkım, Anadolu'' lum......', 'Günaydın kuşlar, horozlar Günaydın çocuklarım Günaydın evimin güneşi Sevgili karım Günaydın bacası tüten fabrikalar Günaydın işçi kardeşleri...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunaydin-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninni', 'ninni-soner-polat-agxt8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'uyusam

uyusan

uyansan

uyansam

sen olsan

ben olsam

yanımda

sen olsan

gözlerin

gözlerim

hep seni

özlerim

daha dün

yanımday-ken

şimdi nerdesin', 'uyusam uyusan uyansan uyansam sen olsan ben olsam yanımda sen olsan gözlerin gözlerim hep seni özlerim daha dün yanımday-ken şimdi nerdesin...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ninni-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürahi', 'surahi-sule-aydemir-f7ujj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-kendini fazla özletme 

demiştim giderken

ıslatmıştı

en sevdiğim sürahi

çiğnediğin kaldırımları

şimdi

bir cenaze kalkar orta yerden

yeri midir neden

kim der ki daha erken

bilirsin

hep çok ge(n) çtir 

ağlarız 

ıslat(a) madığımız

orta yerden

boynu bükük 

sürahim

bir de ben



______üzülme ilahi sürahi

________yar(ın) a ve yarınlara sözleşme yok', '-kendini fazla özletme  demiştim giderken ıslatmıştı en sevdiğim sürahi çiğnediğin kaldırımları şimdi bir cenaze kalkar orta yerden yeri mid...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/surahi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sence', 'sence-tulay-yilmaz-q4rfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaderin kölesiyim,kadere tutsak.

Keşke bin umutla yeniden doğsak.

Sevinç denizlerinde boğulsak.

Değerini bilir miydik,sevinçlerin? 

Ne yazı vardır ne de kışı,

Ne kara günü der ne de akı,

Hiç bilemezsin,nedir alnındaki yazı.

Bilseydik kalır mıydı,hayatın anlamı? 

Ömür de gelir geçer,böyle işte.

Gönlün hala genç ister,eğlence.

Aynadaki yaşlılığa yok çare,

Olsaydı,değişir miydi sence?', 'Kaderin kölesiyim,kadere tutsak. Keşke bin umutla yeniden doğsak. Sevinç denizlerinde boğulsak. Değerini bilir miydik,sevinçlerin?  Ne yazı ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Yılmaz']::text[], 8.5, '{"poet":"Tülay Yılmaz","poet_slug":"tulay-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sence-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar VII', 'hatiralar-vii-erdogan-ergin-s4mkt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zamandır, rüyalarım bitmeden, kesiliyor

İrkiliyorum

Zamana borcum varmış sanki,

Esiriyim bilmediğim bir hayatın

Diyorum, düşlerim bana kalsın

Kıyafeti olmasın.Hep tek tip dolaşmayayım

Uçsuz bucaksız ilkbaharın çiçekleri içinde

Kuşlar, yeşilim diye konmasın

Böcekler kamufle olmasın

Arılar, dokunsun ellerime

Zehirli iğnelerini soksunlar bedenime

Acıtmasın, şişmesin göz bebeklerim

Ağlamaktan...

Kesilmesin artık,

Rüyalarım olsun,

Onlardan bana kalsın', 'Ne zamandır, rüyalarım bitmeden, kesiliyor İrkiliyorum Zamana borcum varmış sanki, Esiriyim bilmediğim bir hayatın Diyorum, düşlerim bana ka...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatiralar-vii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar VIII', 'hatiralar-viii-erdogan-ergin-bhcj8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şehri yakıyorum,

Her gün içimde

Neron hayret ediyor

Alevlerin, kendi adına yakıştığına

Ürkmüyorum,

Neden gülmüyorum diye

Ama hayret ediyorum

Hüznün, bana yakıştığına

Öne taranmış bir sürü beyaz saçım içinde

Biraz hüzün

Eskidendi,

Saçlarım geriye taralı

Kadir İnanır bakışlı

Gülmenin yakıştığı

Günler...

Sormuyorum kendime

Bu kadar güzel şey içinde

Niçin asıyorum suratımı

Güzümün altında ki kırışıklık cevabı

Tek başıma kutluyorum otuz yaşımı', 'Bir şehri yakıyorum, Her gün içimde Neron hayret ediyor Alevlerin, kendi adına yakıştığına Ürkmüyorum, Neden gülmüyorum diye Ama hayret ediy...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hatiralar-viii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal Yapraklarda', 'kal-yapraklarda-mehmet-akdogan-rsygs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kal yapraklarda,

Son baharın rüzgarı

Ölümün dansını sergilesede

Yinede! Sen kal yapraklarda

Çünkü mevsin yapraklarındır

Ölüm öncesi, yada ölüm sonrası

Mevsim yapraklarındır.

Sıyrıl ölüm anından

Uzan yapraklara....

Yaşamın örmesi, örümcek ağı

Hayat sarması, aşk yapraklarda...

Ak sayfaları, selpak kirletmesi

imge artıklarım değersiz gelsede

sen kal yapraklarda....', 'Kal yapraklarda, Son baharın rüzgarı Ölümün dansını sergilesede Yinede! Sen kal yapraklarda Çünkü mevsin yapraklarındır Ölüm öncesi, yada öl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akdoğan']::text[], 8.5, '{"poet":"Mehmet Akdoğan","poet_slug":"mehmet-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kal-yapraklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-mehmet-akdogan-wbr8d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kanıma düşen alazlara

olsun sözüm

son nefesime bile 

nefel ekeceğim.....

belki bir gün 

dönüp bakarsın

yada gün olur

bir bakışta bile olsa

bil gülücük olarak 

dönersin.....

inan o zaman 

yaşamak için 

geri gelecek gülüşüm....', 'kanıma düşen alazlara olsun sözüm son nefesime bile  nefel ekeceğim..... belki bir gün  dönüp bakarsın yada gün olur bir bakışta bile olsa b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akdoğan']::text[], 8.5, '{"poet":"Mehmet Akdoğan","poet_slug":"mehmet-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-mehmet-akdogan-95pc0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zaman; 

ayaklarımın altında

kayan topraktır....

ölüm ise; 

pusuda bir sendeleme...

ve ben....

zamanda yolcu

ölüm cenginde

bir yaşam sevdası

güneş ekseninde 

kendimi arıyorum....', 'zaman;  ayaklarımın altında kayan topraktır.... ölüm ise;  pusuda bir sendeleme... ve ben.... zamanda yolcu ölüm cenginde bir yaşam sevdası ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akdoğan']::text[], 8.5, '{"poet":"Mehmet Akdoğan","poet_slug":"mehmet-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zaman-200-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıklar İçinde', 'karanliklar-i-cinde-i-smet-barlioglu-7cdfy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşlerimi çalıp tıkmışlar zindanlara,

Hücrelere kapatmışlar aylarımı, yıldızlarımı,

her birinin bileklerinde paslı paslı zincirler,

Paslı paslı gülleler her birinin ayaklarında,

Bedenim kanlı çarmıhlara gerilip gitmiş

Uğrunda.

Umurunda bile değil acılarım yüreğimin,

Gözlerimin yaşı umurunda bile değil,

Aklımı çoktan terk edip gitti o yürek

Bir ağır angaryadan kurtulurcasına.

Gözü ne senden öncesini görür, ne senden sonrasını,

Olanca çilesinin bedenime bıraktı

Faturasını.

Uzanırım, tek bir umuda rastlamaz ellerim,

Yürürüm, gidecek yerim yok,

Yaşarım, yaşadığım pul etmez, para etmez,

Başıma bir büyük karasevda tebelleş olmuş

Yıllar yılı

Terketmez.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 37-38/100)', 'Güneşlerimi çalıp tıkmışlar zindanlara, Hücrelere kapatmışlar aylarımı, yıldızlarımı, her birinin bileklerinde paslı paslı zincirler, Paslı ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karanliklar-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tartılacak Günah', 'tartilacak-gunah-i-smet-barlioglu-i0rfa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çöllere vurdu yine kervanlarım,

Kaldım yine uçsuz-bucaksız kum deryasında,

Sardı yine vahasız acımasızlıklar dört bir yanımı,

Ha bir damla suya muhtacım, ha sana muhtaç,

Hangi yağmayacak yağmurlara el-avuç açayım? 

Hangi kızgın güneşleri kovayım başımdan sinek gibi? 

Her yol ölüme yolcu, sana çıkan yoldan öte,

Ne kalmış ki; şunun şurasında

Ahrete? 

Bu kadar mı zor olurmuş yaşaması insanın? 

Elest bezminde başlamış beklemeye beni karasevda,

Yıllardır keser durur yollarımı uğrular gibi,

Kandökücüler gibi,

Canalıcılar gibi,

Nafakasını ölüme bağlamış akbabalar gibi.

Pençeleri altında yüzüm-gözüm yarık-yırtık,

Alacaklarsa; alsınlar canımı

Artık.

Menzile ulaşamayacak tek kervan benim kervanım,

Develerim yorgundan yorgun, acdan ac, susuzdan susuz,

Yüklerim ağırdan ağır,

Nerede biteceği falcılara kalmış yollarımın,

Çöl sonsuz, kumlar yakıcı, ben yayan-yapıldak,

Sanki günahım varmışda bu karasevdada,

Tartılacak.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 39-40/100)', 'Çöllere vurdu yine kervanlarım, Kaldım yine uçsuz-bucaksız kum deryasında, Sardı yine vahasız acımasızlıklar dört bir yanımı, Ha bir damla s...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tartilacak-gunah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tecavüz', 'tecavuz-mehmet-akdogan-yhce5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bakireliğimde; 

çiğnendi zaman

yarınların gülüşünde

inleme rüzgarı 

ve bir çocuk ölüyor 

çığlığımda acı 

namus kurşununda....

namus vuruldu....! ! ! ! 

otuz erkeğin gölgesi

otuz kurşun bedenime saplandı

herbiri kendi yüzyılının

pasıdır tenimde

ve üç bin yılın hikayesidir tecavüz...', 'bakireliğimde;  çiğnendi zaman yarınların gülüşünde inleme rüzgarı  ve bir çocuk ölüyor  çığlığımda acı  namus kurşununda.... namus vuruldu....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akdoğan']::text[], 8.5, '{"poet":"Mehmet Akdoğan","poet_slug":"mehmet-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tecavuz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı Kurtara', 'tanri-kurtara-i-smet-barlioglu-mqz7o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bulsam kaderimi, oturtacağım karşıma,

Sigaya çekeceğim Münkir ‘le Nekir gibi,

Ne istediğini soracağım bencileyin garipten,

Beni neden kahrettiğini soracağım

Ve ellerimi koyacağım yanan şakaklarıma,

Dinleyeceğim ta ahır zamana kadar,

Varsın soyunsun diye kışlık giysilerinden

Yalanlar.

Öğreneceğim bana neden yazıldığını bu karayazının,

Neden başıma tebelleş edildiğini bu karasevdanın,

Bana neden nasip edildiğini bu boynu büküklüğün,

Bu yüreği yanmışlığın,

Bu gözü yaşlılığın.

Öğreneceğim gözlerimi gezdire gezdire

Kaderimin asık yüzüne,

O gülüşlere hasret dudaklarına,

Bana biraz merhamet etsin diye

Kapanıp durmayacağım

Ayaklarına.

Bakacağım, başkalarına da yazılmış mı böyle bir sevda,

Başkalarının da sokulmuş mu iki ayağı bir pabuca,

Yalnızlıklara mahkum edilmiş mi başkaları da,

Atılmış mı başkaları da kara gecelerde iğneli fıçılara,

Çekilmiş mi gövdeleri bencileyin çarmıhlara? 

Böylesi bir karasevdaya

Bir ben mahkum edilmişim ki; 

Daha artık

Tanrı Kurtara.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 41-42/100)', 'Bir bulsam kaderimi, oturtacağım karşıma, Sigaya çekeceğim Münkir ‘le Nekir gibi, Ne istediğini soracağım bencileyin garipten, Beni neden ka...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tanri-kurtara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Kabrinden Toprak Rahmine', 'ana-kabrinden-toprak-rahmine-orkun-isik-o3uok', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu gece yalnızlığımı asıyorum 

sokak lambalarının üşümüşlüğüne.

rengi olamayan ve hep kanayan

gölgelerimin ayak seslerini bırakarak

terk ediyorum rengi azap şehrini

bu gece ey sevgili bu gece.

toprağın rahmine düşeceğim

bilmediğim yerlere öleceğim

uzat hayallerini, gel ört beni…

hüzünlen tırmala tırmala! yokluğumu

toprağın rahmine, bir gözyaşın damlasın 

kalp gözünün kirpiğinden

ama ne olursun özden…

bilmeliydin

iki kabir arasıydı tüm muhabbetlerimiz

bilinçli ya da bilinçsiz...

hep bu iki nokta arasıydı güzelliklerimiz

ne garip değil mi! bir türlü anlayamadık! 

bizi nereye götürecekti bu gel-gitlerimiz

çoğaldıkça çoğaldı belkilerimiz 

hem de toprak kadar, mavilik kadar

ah kim bilir nerededir

yürek-den-izimdeki med ve cezirlerimiz…

bir bilsen ki ben sıfırım

hoşgörü kâbesinin yamaçlarında.

ey küçük dünya! 

bir bilseydin eğer,

ateşlere nefeslendiğimi

ateş soluyup mavi/ye d/erdiğimi

tek nefeste, kalp g_özün de y_anardı.

ve hayata  ''bence'' bakardın 

işte o zaman anlardın

yalın düşlerimde seni çizdiğimi

dokunmasız saf, duru ve kültsüz…

zaman mevhumunu eşeliyorum

zamansızlığın debdebesinde

ana kabrinden düşüyorum toprağın rahmine

dokunma bana yanarsın ey sevgili.

dokunma!', 'bu gece yalnızlığımı asıyorum  sokak lambalarının üşümüşlüğüne. rengi olamayan ve hep kanayan gölgelerimin ayak seslerini bırakarak terk edi...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ana-kabrinden-toprak-rahmine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ağlama! Solmaz Gül…', 'aglama-solmaz-gul-naime-erlacin-nhy1v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'var olmak

ölümüne bir yarış

nahif güllerden geçer aynanın sırrı

yerde mi 

gökte miyiz

hangi zaman diliminden kopup geldik

umursamayız hiç

yaradır yıkıntısına kanayan 

bir de sevda karası hüzün

turkuvaza sığınılır böyle

sonsuzu arayan 

o camdan bu cama 

müzmin bir ağrıdan arta kalan 

izleğin peşindeyiz

mavileşen yıldıza sor 

hayra yorulur mu duyguezer kabus

tüle ağlayan acının geçitlerinde

sınanmadık mı yeterince? 

mücerret bir hikâyenin sandık odasına

mezuniyetimiz bırakılır bir gün

giz dolu

yarından alacaklı 

kendinden menkul biraz 

hesaplaşmadı halen özgeçmişiyle

biraz meşru hatta 

güne dünden borçlu

 birinci doğru:

-bilinmezden sonuç çıkaran yanılır en çok! 

o ki; 

güneşi dinledi kâhinden

yok saymadı yaşam ve karmaşayı

huşûyla giydirdi geceyi kalbinin külüne

ikinci doğru:

-sır’ını dökmez soylu aynalar biliriz! 

ve

''b u   d a   g e ç e r'' 

dedi kâhin 

''a ğ la m a   s o l m a z   g ü l'' 

rengini gizlemez ayna

sözün hükmüne çünkü

can suyu gibi sinmiştir kederiniz

üçüncü doğru:

-yaratır acı hiç durmaz! 

(21 Mayıs 2005)', 'var olmak ölümüne bir yarış nahif güllerden geçer aynanın sırrı yerde mi  gökte miyiz hangi zaman diliminden kopup geldik umursamayız hiç ya...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/aglama-solmaz-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hudutlar Var', 'hudutlar-var-baris-bicici-ivrzc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hudutlar var

dünümüzü, bugünümüzü, yarınımızı

karartacak kadar.

Hudutlar var

ak güvercinlerin  zeytin dalına duvar

rüyalara sınır çeken.

Hudutlar var

birliktelikleri engelleyen

özgürlükleri zincirleyen

gemileri döndüren rotasından.

Hudutlar var

aşkım karşısında çaresiz

sevdamın önünde saygıyla duran

ve sevgime selam veren...', 'Hudutlar var dünümüzü, bugünümüzü, yarınımızı karartacak kadar. Hudutlar var ak güvercinlerin  zeytin dalına duvar rüyalara sınır çeken. Hud...', ARRAY['Türk Edebiyatı','Şiir','Barış Biçici']::text[], 8.5, '{"poet":"Barış Biçici","poet_slug":"baris-bicici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hudutlar-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ohaaaaaaa! ...Dedi Birisi! *....', 'ohaaaaaaa-dedi-birisi-naime-erlacin-4bsnz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'beni anlamak

çok ister sizden

bu denli varsıl mısınız? 

borçlu dediler insanlık için

inanmadım

meğer BDDK’ya geçmiş çoktan

ne gaflet! 

kimi 

bir çay bedeline mutlu

kimi bilmez mutluluğu

gönül kaynağını kurutanı bulmadı daha

ne bu! 

bozuk para mı

ayak altında dolaşsın? 

hem vurdun mu ayağını duyguya

su çıkmalı yerden

su çıkmalı 

ağacının köklerinden

bu günlerde bir “ohaa” modası…

“oha”nızı alıp gidiniz 

gidiniz 

müflis ve kapalı tahtalardan

ölüsü dirisinden heybetlidir sevginin

(*)      Bu dizeler ilhamını senden aldı Sevgili Çağıl (Ener) . Sen bilirsin :))))))   

(21 Mayıs 2005)', 'beni anlamak çok ister sizden bu denli varsıl mısınız?  borçlu dediler insanlık için inanmadım meğer BDDK’ya geçmiş çoktan ne gaflet!  kimi ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ohaaaaaaa-dedi-birisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-turgut-onal-plc3d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum 

Gideceksin

Gitme demeyeceğim

Özlemle yollarını

İnan bekleyeceğim.

Yıldızlar kayar gider

Gün gelir umut biter

Haykırıp bir gün; 

Yeter! ...

Diye bekleyeceğim.

Özlemlere gem vurup

Ufukta kızıl gurup

Her saat

Her gün durup

Sana gel diyeceğim.

Seni bekleyeceğim.', 'Biliyorum  Gideceksin Gitme demeyeceğim Özlemle yollarını İnan bekleyeceğim. Yıldızlar kayar gider Gün gelir umut biter Haykırıp bir gün;  Y...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekleyecegim-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlarımız', 'kadinlarimiz-kadir-kaya-gsnd0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gerçeği gör, sende kalma yalnız,

Dur ,boşuna inadın sürme yaldız,

İnsanlar içinde kadınlar yıldız,

Genç kızlara örnektir baldız.

Kadınsız olmaz her şeyi de  bilsen,

Hoş olurum ne zaman yanıma gelsen,

Hayatın tuzu, biberi o kadar elzem,

Eniştem ne yapardı olmasa teyzem.

Sizleri Yaradan''a kurban olayım,

Şükran duygusuyla selam durayım,

Sizleri anlamayanın haline yanayım,

Koşup annemin yanına varayım.

Mutlu günler için kişiye eş lazım,

Sevgi yoksa okunmaz bu yazım,

Hasta olunca başlar ağrım ,sızım,

Hemen yanımdadır sevgili kızım.

Annelere takardım olsa tacım,

Zor günler geçirdim kalmadı saçım,

Başım sıkışsa, olursa acım,

Nerede olsam karşımda bacım.

Yılları ,ayları tek tek biçin,

Kadirim, yoktan   zor oluyor geçim,

Kadınlar içinde yapılsa seçim,

Emsali bulunmaz bir tane eşim.', 'Gerçeği gör, sende kalma yalnız, Dur ,boşuna inadın sürme yaldız, İnsanlar içinde kadınlar yıldız, Genç kızlara örnektir baldız. Kadınsız ol...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kadinlarimiz-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-baris-bicici-wc2n6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al leçeği boynuna sarmış geliyor

Sallana sallana bakın bir güzel

Kınalı saçlara rüzgar değiyor

Kokusu gülden, laleden güzel

Sordum adını söylemem dedi bana

Azıcık dudaktan edayla güldü bana

Bir bakış attı yürekten vurdu bana

Köyümden, yurdumdan, canımdan güzel

Ellerinde toprağın demi vardı 

Gözlerinde sevdanın bakışı vardı

Dillerinde türkünün anlamı vardı

Sazımdan, sözümden, telinden güzel

Eğildim çeşmeden bir tas su verdim

Yoluna koyuldu Müjganım dedi bana

İsmine duyunca kendimden geçtim

Barıştan, umuttan, sevgiden güzel', 'Al leçeği boynuna sarmış geliyor Sallana sallana bakın bir güzel Kınalı saçlara rüzgar değiyor Kokusu gülden, laleden güzel Sordum adını söy...', ARRAY['Türk Edebiyatı','Şiir','Barış Biçici']::text[], 8.5, '{"poet":"Barış Biçici","poet_slug":"baris-bicici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzel-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk!', 'ey-ask-i-brahim-yamac-o3uym', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aşk! ey aşk! 

üstüme üstüme yürü, bana sataş

düzenimi boz, tersyüz et beni

özenle ördüğüm duvarları yık

ve bul altındaki adamı kurtar

ben çer çöple oyalanırken

sen ki bana kendini bildirdin

kendi sarayımdan kaçmak için

kan ter içinde tüneller kazdırdın

şimdi içimde kal, yüreğime geril

tokat bekleyen çocuklar gibi

nefesimi tuttum, hazırım

beni iğnenin deliğinden geçir', 'aşk! ey aşk!  üstüme üstüme yürü, bana sataş düzenimi boz, tersyüz et beni özenle ördüğüm duvarları yık ve bul altındaki adamı kurtar ben çe...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yamaç']::text[], 8.5, '{"poet":"İbrahim Yamaç","poet_slug":"i-brahim-yamac","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ey-ask-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Demiş Sevenler Kavuşmaz Diye', 'kim-demis-sevenler-kavusmaz-diye-i-brahim-bayraktar-1qc1y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kim demiş sevenler kavuşmaz diye? 

Sevmeye kim engel olur güzelim? 

Sevgi, insanlığa büyük hediye,

Sevgisiz yürekler ölür güzelim.

Sevgiler, hayatın bir evresinde; 

Kanında, canında her zerresinde; 

Şu kısacık yaşama süresinde; 

Kalbin köşesinde durur güzelim.

Tarihe bir bak! Ne aşklar yaşandı,

Nice gönüller bağından boşandı,

Bu sevdalar kalpten kalbe taşındı,

O, bir gün seni de bulur güzelim.', 'Kim demiş sevenler kavuşmaz diye?  Sevmeye kim engel olur güzelim?  Sevgi, insanlığa büyük hediye, Sevgisiz yürekler ölür güzelim. Sevgiler,...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kim-demis-sevenler-kavusmaz-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaa...', 'yaa-turgut-onal-q9c3u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Babam o kadar zengindi ki...

Kapıda bekleyen trenimiz, 

Banyoda koskoca yelkenlimiz vardı

Yaa...

Bir odadan öbürüne atla giderdik

Bahçemizi Mercedes'' le gezerdik

İnsanlar açız dedikçe gülerdik

Yaa...

Aşçılarımız, işçilerimiz, dadılarımız vardı

Yataklarımız sanki gemi kadardı

Herkes bize imrenerek bakardı

Yaa...

Oyuncaklarım çeşit çeşitti

İnsanlar doğuştan eşitti

Bazıları fakiriz diyor... inanırmıyım

Yaa...', 'Babam o kadar zengindi ki... Kapıda bekleyen trenimiz,  Banyoda koskoca yelkenlimiz vardı Yaa... Bir odadan öbürüne atla giderdik Bahçemizi ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgini Beklerken', 'sevgini-beklerken-ozan-kiratli-he7o4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni hep mutlu görmek isterdim

Nedenini hiç bilemezdim...

Sesin kulaklarımda yankılanırdı bazen 

Eğlenen kahkahalarıyla

Mutlu olurdum...

Susmayı hiç tercih etme diye

Dua ederdim inandığıma

Gülücüklerin süslerdi kalbini

En karanlık günlerinde bile

Sevgin o kadar büyüktü ki

Tutamazdın elinde

Ve güneş bile sönük kalırdı yanında

Bir şeyi hiç anlamadım kendimde

O şey senden bir parçaydı bende

Ve kıpırdardı her sevdan dediğimde

Bir şeyi bilmediğinde

Susmakmış en iyisi derler

Susmayı tercih ettim ben de 

Yine de

O kokuya susamıştım delice', 'Seni hep mutlu görmek isterdim Nedenini hiç bilemezdim... Sesin kulaklarımda yankılanırdı bazen  Eğlenen kahkahalarıyla Mutlu olurdum... Sus...', ARRAY['Türk Edebiyatı','Şiir','Ozan Kıratlı']::text[], 8.5, '{"poet":"Ozan Kıratlı","poet_slug":"ozan-kiratli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgini-beklerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımsız Kadın', 'tanimsiz-kadin-abdulrizak-kilic-r1cul', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'rengârenk 

ne tavus kuşu 

ne kelebek 

ne bahar bahçe çiçek 

ne dikensiz hayat 

ne uçsuz bucaksız kâinat 

ne cennet 

ne cehennem 

senin kadar ne güzel ne özel 

tüm güzel yanları toplansın kadınların 

bir zerren bile değil senin 

sen ne tarif edilebilen 

ne tanımlanabilen 

ne harf harf yazılabilen 

ne çizgi çizgi çizilebilen 

ne nakış nakış işlenebilensin 

sen senden öte bir masal 

bir Kafdağı’sın 

saraylar hanlar tahtlar içinde 

sen bir ben içinde 

bır varmış bir yokmuşsun

  ...  ...   ...

suskun sevda', 'rengârenk  ne tavus kuşu  ne kelebek  ne bahar bahçe çiçek  ne dikensiz hayat  ne uçsuz bucaksız kâinat  ne cennet  ne cehennem  senin kadar...', ARRAY['Türk Edebiyatı','Şiir','Abdulrızak Kılıç']::text[], 8.5, '{"poet":"Abdulrızak Kılıç","poet_slug":"abdulrizak-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tanimsiz-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar IX', 'hatiralar-ix-erdogan-ergin-qqa3l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaldır başını, bak gökyüzüne

Kuşlar ne kadar özgür

Kelebekler bir gün de olsa, yaşıyor doyasıya

Ağaçlar, nasıl da kaldırmışlar, ellerini gökyüzüne

Yapraklar nasıl uçuyor umarsızca,

Ve güller dalından yırtılıyor yeni sevdalara

Şimdi eğ başını,

Görebiliyor musun kendini

Karıncalar gibi sıraya girmiş

Dizi dizi iş yaparken

Ve bir kedi gibi ekmek beklerken, bir çöpün kenarında

Düşünmüyor değilim; 

Kanatları olan bir karınca olsam keşke

Hem özgürce çalışsam, hem uçsam gökyüzüne', 'Kaldır başını, bak gökyüzüne Kuşlar ne kadar özgür Kelebekler bir gün de olsa, yaşıyor doyasıya Ağaçlar, nasıl da kaldırmışlar, ellerini gök...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hatiralar-ix-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heder Oldum', 'heder-oldum-yavuz-agir-or03k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömrümün baharına; 

Karlar yağdı otağıma.

Gönlümün daracık sokağına,

Ateş düştü,heder oldum...

Taşlar feryadımda eridi

Dağlar sesime inledi

Bütün alem dinledi 

Ateş düştü, heder oldum....

Ömrüm pınar oldu çağladı

Deli gönül,için için ağladı.

Beni bir vefasıza bağladı

Ateş düştü  yandım,heder oldum....', 'Ömrümün baharına;  Karlar yağdı otağıma. Gönlümün daracık sokağına, Ateş düştü,heder oldum... Taşlar feryadımda eridi Dağlar sesime inledi B...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/heder-oldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Kelimeyle Başladı Her Şey', 'i-lk-kelimeyle-basladi-her-sey-melih-coskun-6an3b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk kelimeyle başladı her şey 

İlk dizesi gibi acemi bir şairin.

İlk öpücükte saklıydı aşkın büyüsü,

İlk adımındaydı sevinç 

Yeni yürümeye başlayan çocuğun.

İlk ayrılışındaydı hüzün delikanlının sevdiğinden.

                       

Her şey ilklerde saklıydı 

Hiç aklıma gelmezdi sonu da gelebileceği güzelliklerin 

Tükenebileceği sonunda bütün mutluluklarımızın.

Ben yine de ilk şiirim gibi 

Heyecanla okuyacağım sana yazdığım şiirlerimi

Ve her seferinde 

İlk defa tutuyormuş gibi yine yüzüm kızararak 

Tutacağım ellerini.

Onlarca yıl geçse de üzerinden 

Ben sende hep ilklerimizi hatırlayacağım

Sonuna gelmiş olsakta yaralı ömrümüzün. 

Yani sevdiğim 

Her şey başladığı gibi bitecek bende 

Sana söylediğim ilk söz olacak 

Son sözüm...', 'İlk kelimeyle başladı her şey  İlk dizesi gibi acemi bir şairin. İlk öpücükte saklıydı aşkın büyüsü, İlk adımındaydı sevinç  Yeni yürümeye b...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ilk-kelimeyle-basladi-her-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemileri Karadan Yürütmek!', 'gemileri-karadan-yurutmek-huseyin-avdic-zykds', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I$te dâvâ, i$te gercek, o da bir tek:

Dâvâ, gemileri karadan yürütmek! 

Bati Berlin, 1980-85.

(Fetihe 08 kala)', 'I$te dâvâ, i$te gercek, o da bir tek: Dâvâ, gemileri karadan yürütmek!  Bati Berlin, 1980-85. (Fetihe 08 kala)...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gemileri-karadan-yurutmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul Yaniyor!', 'istanbul-yaniyor-huseyin-avdic-ttkkv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendini fethetmi$ asker kalk, boru caliyor.

Gönüllerin Istanbul''u tutu$mu$ yaniyor! 

Bati Berlin, 1980-85.

(Fetihe 08 kala)', 'Kendini fethetmi$ asker kalk, boru caliyor. Gönüllerin Istanbul''u tutu$mu$ yaniyor!  Bati Berlin, 1980-85. (Fetihe 08 kala)...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/istanbul-yaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız sen', 'yalniz-sen-yahya-akbulut-2y0vf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çiçekler göndermek istedim

İlahlar kadar güzel, sıcak 

Yağmurdan ıslak, binlerce güller. 

Dikensiz, rengarenk...

Yapamadım!                        

Bir şeyler sanki eksik içimde                             

Kalbimde saplı kanlı bıçak 

Yüreğimde yerin olsa bile

İzlerin hep mazide kalacak.

Her şeyden beter bu gönül sızısı 

Arzular eksik, tutkular ölü.                    

Bazıları doğuştan kaybeder                       

Ben de onlardan birisi.                        

Ayak seslerine nokta koydum

Sevdalara mezar kazdım

Kendim düştüm içine

Üzüldüm, küçüldüm.

Elimde kaldı gül yaprakları

Cansız, sensiz...Solmuş.

Hayalimde yalnız sen!', 'Çiçekler göndermek istedim İlahlar kadar güzel, sıcak  Yağmurdan ıslak, binlerce güller.  Dikensiz, rengarenk... Yapamadım!                 ...', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalniz-sen-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş dili', 'kus-dili-ali-riza-unal-l4oar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulut buhara sarılmış, terine su içmeğe.

Şeytan yolun şaşırmış,alime hal biçmeğe.

Şakir açar keseyi, sultana cevher dökmeğe.

Fakire darı sayar,seneye ekip biçmeğe.

Karga talim eder bülbül olup ötmeye.

Aşık olmuş ördeğe yolun gözler öpmeye.

Hindi hased olmuş, süslü tavus kuşuna.

Yemin etmiş sülüne,tüyün tek,tek sökmeye.

Bu sözlerler yalansız şakiye deynek gibi.

Konarım her meclisi arifana,leykek gibi.

Bu sırra hal olana, ankayız ref,ref gibi.

Her dem sır dilde nakş eder,gergef gibi.

   Kuş dili Yunus dli.....', 'Bulut buhara sarılmış, terine su içmeğe. Şeytan yolun şaşırmış,alime hal biçmeğe. Şakir açar keseyi, sultana cevher dökmeğe. Fakire darı say...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kus-dili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğle birisi', 'ogle-birisi-halil-colak-na7j2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canların   canı  olan öğle birisi

Gönülden seveni anlamaz öğle birisi

Yakar durur yürekleri öğle birisi

Laftan anlamaz öğle birisi

Ceylana benzeyen öğle birisi

Bakışları ile öldürür öğle birisi

Leyla dan daha özge öğle birisi

Kalbe sultan olacak öğle birisi

Sözle,sazla anlatılmaz öğle birisi

Boyu selvi,dudak kiraz öğle birisi

Gözler ela,yanak elma öğle birisi

Derde derman olacak öğle birisi

Horasan ereni anlatamaz öğle birisi 

Dikenler içinde gül olan öğle birisi

Aslı’ danda güzel hoş öğle birisi

Kırlarda ender olan çiçek öğle birisi 

Halil Çolak', 'Canların   canı  olan öğle birisi Gönülden seveni anlamaz öğle birisi Yakar durur yürekleri öğle birisi Laftan anlamaz öğle birisi Ceylana b...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ogle-birisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Ey Resul', 'gel-ey-resul-nesibe-gulsen-tqjhm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey Resul,

Gel de bir gör ümmetinin halini...

Çöller hiç böyle suya hasret kalmadı

Böyle yanmadı yanardağlarda ateş

Üstümüze böyle sağanak yangınlar yağmadı

Ey Resul, gel

Bir mucize de bize göster; 

Öyle çaresiziz ellerimiz bağlanmış, 

Öyle yanmış içimiz, gözlerimiz dağlanmış,

Öyle ki umudumuz nuruna bağlanmış.

Ey Resul gel de çıkar bizi Asr-ı Saadet’e

Ey Resul gel de kurtar varmadan kıyamete.

Yokuşlarda susayıp çatlamış dudağımız,

Çatlamış her yanından, çatlamış vicdanımız.

Ey Resul Sen ki ateşte açan gülsün,

Elbette ki alemlere gönderilen ödülsün,

Gel, son bir kez dünyanın yüzü gülsün

Gel ey Resul

Bir mucize de bize göster.

Öyle çaresiziz ellerimiz bağlanmış,

Öyle yanmış içimiz gözlerimiz dağlanmış,

Öyle ki umudumuz nuruna bağlanmış.

Ey Resul gel de çıkar bizi Asr-ı Saadete

Ey Resul gel de kurtar varmadan kıyamete.

Rabb’imin rızasına ulaşmamız için gel,

Mahşerden önce son defa kavuşmamız için gel,

Nurunu görüp hayırda yarışmamız için gel...

Ey Resul gel de bir sor topraklar neden ağlar

Ey Resul,Mekke’de neden durmaz çığlıklar,

Neden durmaz gözyaşı, gökten neden kan damlar

Neden delinmiş sema, neden çatlak bulutlar

Ey Resul gel de bir sor camiler niye ağlar

Neden susmuş yürekler, nerde kalmış dualar...

Ey Resul bekliyoruz son duamız için gel

Gerçekte gelmesen de gel, rüyamız için gel

Gök kubbede çınlayan feryadımız için gel

Her Kadir Gecesinde Kur’an’ımız için gel 

Elden gitmekte olan imanımız için gel

İçimizde her dem kopan figanımız için gel

Ey Resul sen gideli putlarımız çoğaldı

Gel, yeniden Allah’a yönelmemiz için gel

		

Ey Resul gel. Bir mucize de bize göster

Öyle çaresiziz ellerimiz bağlanmış

Öyle yanmış içimiz, gözlerimiz dağlanmış

Öyle ki umudumuz nuruna bağlanmış

Ey Resul gel de çıkar bizi Asr-ı Saadete 

Ey Resul gel de kurtar varmadan kıyamete...

					

                                           (İstanbul/2002)', 'Ey Resul, Gel de bir gör ümmetinin halini... Çöller hiç böyle suya hasret kalmadı Böyle yanmadı yanardağlarda ateş Üstümüze böyle sağanak ya...', ARRAY['Türk Edebiyatı','Şiir','Nesibe Gülşen']::text[], 8.5, '{"poet":"Nesibe Gülşen","poet_slug":"nesibe-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gel-ey-resul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahrum', 'mahrum-hatice-ozdes-r6k3x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni görmekten mahrum ettin

Senle konuşmayı haram ettin

Bu ceza reva mı bana

Seni aramak bile ürkütür oldu

Sevmek bir gün, 

Kahrolmak her gün

Kader dalga geçiyor

Yalnızlığa zincirliyor

Seni benden mahrum ediyor.

Sesin bana uzak geliyor

Tesadüfen görürüm diyorum

Seher vakti  yoksun sen

Sevmek bir gün, 

Kahrolmak her gün

Kader dalga geçiyor

Yalnızlığa zincirliyor

Yine seni benden mahrum ediyor.', 'Seni görmekten mahrum ettin Senle konuşmayı haram ettin Bu ceza reva mı bana Seni aramak bile ürkütür oldu Sevmek bir gün,  Kahrolmak her gü...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mahrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşalım Bahara', 'kavusalim-bahara-i-lknur-cekici-0pb30', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşığım sevdiğim yok

Çölde kaldım suyum yok

Yaralandı yüreğim

Derdime dermanım yok

Kerem yandı aslıya

Mecnun koştu leylaya

Bir ışık yak sende bana

Senden başka kimsem yok

Ne geceler geçirdim

Gün doğmadı bahtıma

Ruhumun gıdasısın

Sensiz olmam unutma

Daha ne kadar dayanır

Yüreğim bu hayata

Karar ver artık yeter

Kavuşalım bahara', 'Aşığım sevdiğim yok Çölde kaldım suyum yok Yaralandı yüreğim Derdime dermanım yok Kerem yandı aslıya Mecnun koştu leylaya Bir ışık yak sende...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kavusalim-bahara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemiyorum', 'diyemiyorum-hatice-ozdes-g5283', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde dolunay

Gönlümde aşk var

Seni seviyorum diyemiyorum

Haykırışlar bende

Hayal kırıklığı sende

Umutlar gönlümüzde

Seni seviyorum diyemiyorum

Içiyorum her gece

Kadehler kırılıyor ellerimde

Yine de seni seviyorum

Diyemiyorum

Gönlümün içinde sen					 	 

İçimde iyileşmeyen yaramsın sen

Haykırıyorum her gece

Ama yoksun sen

Seni seviyorum 

Diyemiyorum........', 'Gökyüzünde dolunay Gönlümde aşk var Seni seviyorum diyemiyorum Haykırışlar bende Hayal kırıklığı sende Umutlar gönlümüzde Seni seviyorum diy...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/diyemiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çukurlar açılır, işaret iz yok', 'cukurlar-acilir-isaret-iz-yok-mikdat-bal-pyx95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çukurlar açılır, işaret iz yok 

Hala konuşurlar, bunlarda yüz yok 

Dünyada bunlardan alâ keriz yok 

Çukura düşene, ceza var gardaş

Bu kadar ucuz mu, insanlar canlar 

Çukurun halinden düşenler anlar 

Çukur problemini, çözemez bunlar 

Çukurun başında niza var gardaş

Beş liralık şerit, problemi çözer 

Bunlar işi bilmez, akıl ne gezer 

Çukurlar sadece, düşeni üzer 

Genelde bu işe rıza var gardaş

Alçak ötesine, çukur diyorlar 

İnsanlar levhayı okur diyorlar 

Bu gün ölümüz yok, şükür diyorlar 

Sadece ufak bir kaza var gardaş

Mikdat der kardeşim, bu kadar yeter 

Akıllı insanlar, programla gider 

Bir işe başlanır, aynı gün biter 

Böyle işte düzen, hiza var gardaş', 'Çukurlar açılır, işaret iz yok  Hala konuşurlar, bunlarda yüz yok  Dünyada bunlardan alâ keriz yok  Çukura düşene, ceza var gardaş Bu kadar ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cukurlar-acilir-isaret-iz-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Kalışım', 'tek-kalisim-hatice-ozdes-o0ag1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Suskunluğun bana ceza

Serseri aşklar olsada

Saman alevi olsamda

Gönlümü çelen bakışın

Beni sarmalayışın

Tek beden olmayışım

Sensiz tek kalışım

Yasaklar yok olacak 

Sonunda sana kavuşacak					

Gönül yarası kaybolacak

Bu yürek sensiz olmayacak

Gönlümü çelen bakışın

Beni sarmalayışın

Tek beden olmayışım

Sensiz tek kalışım', 'Suskunluğun bana ceza Serseri aşklar olsada Saman alevi olsamda Gönlümü çelen bakışın Beni sarmalayışın Tek beden olmayışım Sensiz tek kalış...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tek-kalisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir olalım', 'bir-olalim-halil-colak-pxo5i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel kardeşim bir olalım

Bu peygamber buyruğudur

Tek vücut Çınar olalım

Bu peygamber buyruğudur

Gaflet ikilikte kalan

Vatanda olur talan

Bu gidişin sonu viran

Bu peygamber buyruğudur

Ben bildiğim dava haktır

Türk’ün korkusu yoktur

Fesatlıkta kalan çoktur

Bu peygamber buyruğudur

Birdir Allah canların canı

Birdir ahır ve evveli

Pirimiz Horasan erenleri

Bu peygamber buyruğudur

Horasan erenidir sözüm

Bu yola adadım canım

Kurtuluşa tekbir çözüm

Bu peygamber buyruğudur

Halil Çolak', 'Gel kardeşim bir olalım Bu peygamber buyruğudur Tek vücut Çınar olalım Bu peygamber buyruğudur Gaflet ikilikte kalan Vatanda olur talan Bu g...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-olalim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çan Çiçeğim', 'can-cicegim-zafer-mutlu-6owhd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kara gözlüm

                esmerim...

                sen

                hiç dert etme

                girdabında  beynim...

                senden ayrı,

                tarla sınırındaki tek ağaç,

                gibiyim

                rüzgar nereden eserse o yana

                dönerim...

                 bak yine haykırışlarını duyar 

                 gibiyim..

                 inan ki... yaramaz

                 değilim...', 'kara gözlüm                 esmerim...                 sen                 hiç dert etme                 girdabında  beynim...              ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/can-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cıvıl Cıvıl', 'civil-civil-hatice-ozdes-sct40', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkım cıvıl cıvıl

Gönlüm kıpır kıpır

Yaşamak senle fıkır fıkır

Bu yürek seni ister 

Başkasını değil seni ister

Sen yüz verince

Canından can ister 

İçimi bağlayan sen

Kalbime çağlayan sen

Beni alıp götüren sen

Beni baştan çıkaran sen

aşkım çıvıl,gönüm kıpır

yaşamak senle fıkır fıkır', 'Aşkım cıvıl cıvıl Gönlüm kıpır kıpır Yaşamak senle fıkır fıkır Bu yürek seni ister  Başkasını değil seni ister Sen yüz verince Canından can ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/civil-civil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Sevda', 'yalanci-sevda-hatice-ozdes-jttxi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bitmez dediğim sevdamdın sen

Hayatıma giren kavgamdın sen

Bir yastığa baş koyan aşkım

Beni yargısız sevendin sen

Aşkımız hiç tükenmeyecek

Bin yıl geçsede hiç bitmeyecek

Başka sevdaya yelken açtın

Beni kör kuyulara attın

Hayatımı aldın,aşkımı sattın

Beni paçavra yaptın

Yalancı sevdamıydı bizim aşkımız

Yıpranmış fotoğraflarda kaldı aşkımız', 'Bitmez dediğim sevdamdın sen Hayatıma giren kavgamdın sen Bir yastığa baş koyan aşkım Beni yargısız sevendin sen Aşkımız hiç tükenmeyecek Bi...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalanci-sevda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümidim - Sevdam Ol', 'umidim-sevdam-ol-hatice-ozdes-uba09', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzansam tutabilirmiyim ellerini

Teselli olurmusun kıvranan yüreğime 

Aciz ruhuma merhem olurmusun

Ümidim ol, sevdam ol

Sen hayatıma ışık ol

Anılarım yok olmayacak

Küllenen aşklarım son bulmayacak

Anlamsız bitmiş sevdalar 

Sayende bir son bulacak

Ümidim ol, sevdam ol

Sen hayatıma ışık ol', 'Uzansam tutabilirmiyim ellerini Teselli olurmusun kıvranan yüreğime  Aciz ruhuma merhem olurmusun Ümidim ol, sevdam ol Sen hayatıma ışık ol ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umidim-sevdam-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hain', 'hain-hatice-ozdes-ei3dl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutmak isteyipte unutamadığım

Gitme deyipte durduramadığım

Sayende bu cana sığdıramadığım

Tükenmez deyipte tüketemediğim

Sen hayatımdaki hain

Yüreğimi dağlayan kara sevdam

Unutmak istesemde unutamadığım

Bir kalemde silipte atamadığım

Yarınsız sevdalara kucak açtığım

Beni çıkmaz girdaplara attığın

Sen hayatımdaki hain

Yüreğimi dağlayan kara sevdam', 'Unutmak isteyipte unutamadığım Gitme deyipte durduramadığım Sayende bu cana sığdıramadığım Tükenmez deyipte tüketemediğim Sen hayatımdaki ha...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hain-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Kahve', 'aci-kahve-hatice-ozdes-nov12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir acı kahvemi içmeyemi geldin 

Gönlünü gönlüme vermeyemi geldin 

Görmeyi haram etmiştin bana 

Sevmemem için reddettin beni 

Hayatın  acı tecrübesiydi 

Sevipte sevmeyeni oynamam

Görünce ellerim titremedi mi 

Nefesim kesildi hissetmedin mi 

Bir acı kahvemi içmeye mi geldin 

Gönlünü gönlüme vermeye mi geldin 

Arada bir kalbimi yakmaya mı geldin', 'Bir acı kahvemi içmeyemi geldin  Gönlünü gönlüme vermeyemi geldin  Görmeyi haram etmiştin bana  Sevmemem için reddettin beni  Hayatın  acı t...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aci-kahve-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Kirletmeyin', 'aski-kirletmeyin-sahin-erturk-pvyxs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanatcıyım,Şarkıcıyım

Mankenim diyen sizler

Size sesleniyorum size

Sayenizde aşk bitti

Bugün CANAN la

Yarın MERAL le

Bugün MEHMET ALİ

Yarın AHMET ALİ

Bunun neresi AŞK

Bir kazanıyorsunuz

Bin harcıyorsunuz

Bu değirmenin suyu

Nereden geliyor...? 

Ben söyleyeyim mi? 

Aşkı satıyorsunuz...

Bir koca yetmiyor

İKİ,ÜÇ,DÖRT,BEŞ

Oda yetmiyor

Ekranlarda

Pişmiş kelle gibi

Sırıtıyorsunuz

Aşığım,aşık diyorsunuz

Aşkla dalga geçiyorsunuz

KADINI da aynı

ERKEĞİ de aynı

Sanatcıyım,Şarkıcıyım

Mankenim diyen sizler

Size sesleniyorum size

Sayenizde aşk bitti

Aşkı almayın ağzınıza

AŞK LA,İHTİRASI

AŞK LA,REKLAMI

AŞK LA,çıkar ilişkilerinizi

Karıştırmayın ne olur...? 

AŞK KİM

SİZLER KİM

Siyahla,beyaz gibi

Uzaksınız,zıtsınız birbirinize...? 

Yakışmıyor ağzınıza AŞK

Yeter,yeter artık

KİRLETMEYİN AŞKI

Kirletmeyin,kirletmeyin

(21.05.2005-Yeni)', 'Sanatcıyım,Şarkıcıyım Mankenim diyen sizler Size sesleniyorum size Sayenizde aşk bitti Bugün CANAN la Yarın MERAL le Bugün MEHMET ALİ Yarın ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/aski-kirletmeyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla İşte', 'anla-i-ste-ayhan-yavuz-acikgoz-xr1ju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben...

Zekâ oyunlarının bir numaralı ismi...

Dört haneli rakamları çarparım kafadan...

Yoktur dengim ezberde...

Binlerce şiir, binlerce türkü...

Binlerce söz, binlerce nasihat...

Binlerce ninni, binlerce çîrok...

Binlerce isim, adres ve telefon...

Her maçın sonucunu doğru tahmin eder,

Ve gülerdim bilgi yarışmalarındaki sorulara...

Fakat...

Ne zaman sen gelsen aklıma...

Karışıyor...

...

Hani bu tavlanın şahı veziri,

İki kere iki beştir elbette,

Orhan Veli Abasıyanık ne güzel yazıyor,

Bir elin sesi iki elin kesesi var demiş atalarımız,

Kuzu kurdu yemiş hikâye bitmiş, haydi yataklara,

Türkiyenin kodu seksen miydi abi,

Bu maçı kesin beşyüz-sıfır kazanırız, ne maç yok mu,

Fasın başkenti Suudi Arabistan''dır, bildim mi...

Bilemedim mi? 

...

Anla işte...

(istanbul-2005)', 'Ben... Zekâ oyunlarının bir numaralı ismi... Dört haneli rakamları çarparım kafadan... Yoktur dengim ezberde... Binlerce şiir, binlerce türk...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anla-iste-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastane Odaları', 'hastane-odalari-ahmet-agdere-4c27l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çekilmez dakikaların ardına saklı

Ayrılık kokulu hastane odaları

Dar ümitlerden geçirsen de cananımı

Bin yürek ona uzattık kollarımızı

Sen, bin bir kötülüğe pençe vuran dilber

Bu odalar sana olamaz kara çember

Nice diller senin için dualar söyler

Ey, bin bir kötülüğe pençe vuran dilber', 'Çekilmez dakikaların ardına saklı Ayrılık kokulu hastane odaları Dar ümitlerden geçirsen de cananımı Bin yürek ona uzattık kollarımızı Sen, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hastane-odalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Beni', 'al-beni-hatice-ozdes-ncoad', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağınıklığı yaşattınız bana 

Riyakarlığı tattırdınız bana 

Sırtından vurulmasının acısını 

Aynı gün hissettirdiniz bana 

Al canımı kurtar beni 

Hayattan,bu bedenden al beni 

Fırtınalarımı dindir 

Yanına al beni 

Düşünceler içinde alt üst oldum 

Kendimi tutamaz oldum 

Bir çığlık çözer mi bilinmez 

İçime ata ata cansız bir beden oldum 

Al canımı kurtar beni 

Hayattan,bu bedenden al beni 

Fırtınalarımı dindir 

Yanına al beni', 'Dağınıklığı yaşattınız bana  Riyakarlığı tattırdınız bana  Sırtından vurulmasının acısını  Aynı gün hissettirdiniz bana  Al canımı kurtar be...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/al-beni-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Numara', 'numara-serhat-ayan-am2wt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

.

bıraktığın korkuların ışığında büyüyen 

yeni yetme yalnızlıklarım var 

toplam ağırlığımın 

üç katı kadar

sen gittiğinden beri 

yeni şeyler öğreniyorum 

yemek yapmak, 

deme su katmak gibi mesela 

yeni yeni öğreniyorum 

Türkçe''yi 

olumlu cümlelere 

olumsuzluk eklemeyi 

karartmayı 

soğutmayı 

cılkını çıkarmayı 

senli arzularımın 

bak, 

nasıl da istemiyor 

numaraları yapıyorum 

gel-me 

gel-me 

gel 

. 

. 

. 

me', '. . bıraktığın korkuların ışığında büyüyen  yeni yetme yalnızlıklarım var  toplam ağırlığımın  üç katı kadar sen gittiğinden beri  yeni şeyl...', ARRAY['Türk Edebiyatı','Şiir','Serhat Ayan']::text[], 8.5, '{"poet":"Serhat Ayan","poet_slug":"serhat-ayan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/numara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlanmayan Bayramlar', 'kutlanmayan-bayramlar-omer-golge-pm43c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim bayramlarım hiç olmadı

Ne rengarenk pamuk şekerleri,

Ne atlı karıncalar.

Girdiler düşlerime arefe geceleri

Acı ve öfke doldurdu her yeni gün,

Bayram medilleri kadar,

Tertemiz yüreğimi.

Benim şehirlerim,hep hüzün kokardı

Kan ve barutla karışık......

Ve göz bebeklerinde çocukların,

Oyunlar,ölümlerle barışık............

Kaf dağının ardını hiç düşleyemedim ben....

Ebabillerdi benim Zümrüd-ü Anka larım.

Yap-boz oyuncaklara benzerdi sokaklarım,

Yeniden inşaa edildiğinde

Her bombardıman sonrası.......

Masal dünyasında yaşamazdı kahramanlarım,

Yedi başlı ejderlerle savaşan.............

Bakkal Ali...kasap Ahmet ti köşe başında

Ellerinde sapan taşı,

Otomatik tüfeklere karşı,

Çocuk gözlerimde devleşen........

İlk kez 12 yaşımda gördüm,

Bulutların üstümüze ölüm yağdırdığını.....

Neden sonra anladım............

Gazze li çocukların.........

Bayram kutlamadığını', 'Benim bayramlarım hiç olmadı Ne rengarenk pamuk şekerleri, Ne atlı karıncalar. Girdiler düşlerime arefe geceleri Acı ve öfke doldurdu her ye...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kutlanmayan-bayramlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal bu hal', 'hal-bu-hal-ali-riza-unal-7lqk3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayayız ahrazı hale, kelâmı yuttuk.

Mihmanız şehri Mustafaya mekânı tuttuk.

O marifet ilinden haberim çok, cahilem.

Ne akıllı ne deli,ben sen ile mahvilem.', 'Hayayız ahrazı hale, kelâmı yuttuk. Mihmanız şehri Mustafaya mekânı tuttuk. O marifet ilinden haberim çok, cahilem. Ne akıllı ne deli,ben se...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hal-bu-hal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a Dair', 'ask-a-dair-omer-golge-rtzkw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşık her neye mecnun ise aslında,

O aşkın ta kendisidir

Hangi vuslatın hasreti,

Fırtınalar estirse gönülde,

Bilki hedef tektir

Bu serabın ötesinde..............

Varsın Yusuf............

Bin Züleyha ile halvette bulunsun

Yansın da Mecnun,

Leyla''sı için bi-akl olsun

Tarih-i köhne............

Nice kıssa-i aşk kayde de dursun

Henüz...............

Kayda değer bir söz düşmedi,

Vak''a-i Nivüs aşk üzerine.

Kimi bir çift ceylan göze,

Yandı,tutuldu

Kimi bir dilber-i ahu''ya

Tığ-ı Rüstem le vuruldu.

Her kim ne dedi ise iş bu barede,

Nihayetsiz bir ummanın kıyısında bulundu.

Aşık her neye mecnun ise aslında,

O aşkın ta kendisidir.

Ebediyyet verilmişken insana,

Bezm-i Elestte

Neden hala fani olana,

Hezeran beste.

Sen gel birde aşkı ariften dinle

Bir mısra ol mesneviden,

Süzülüp,

Kamışlıktan koparılmış bir neyde inle.

Hasret ummanadır vuslat faslında

Pençe-i ezelin açtığı aşk yarasında

Laleler filizlenmekte her lahza,

 Hayvan-ı natıkın ruh aynasında

Aşık her neye mecnun ise aslında,

O aşkın ta kendisidir

Gönül içre saltanat kurmuşken

Gönül verdiğin............

Bidar ol! 

''O''

Hem ezeldir hem ebeddir.', 'Aşık her neye mecnun ise aslında, O aşkın ta kendisidir Hangi vuslatın hasreti, Fırtınalar estirse gönülde, Bilki hedef tektir Bu serabın öt...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ask-a-dair-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözün Anlamı Yok', 'sozun-anlami-yok-yasar-pullu-9fygn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçurumlar konuşalım 

Dilinden anlamaz kimse

Yüreğin nereye sürgünse

Kanıyor bir çıban seliyle

Sözün anlamı yok 

susalım 

çünkü 

kuş kanatlarını kırmış gökyüzüne.

Koynumuzda harladığımız ateş

Sönerken bir itin gölgesinde

Deli taylar doğuyordu senden

Biz gene şiir okuyorduk

Habur kapısından  girerken ülkemize

Biz yarayı kanadıkça

Ağrıyı acıdıkça seviyorduk

Kanadık sıçradık gökyüzüne

Kan kesti mavi

O günden beri

hasreti sevdik

Ölenler gömüldü

Yitirdik sevdiklerimizi', 'Uçurumlar konuşalım  Dilinden anlamaz kimse Yüreğin nereye sürgünse Kanıyor bir çıban seliyle Sözün anlamı yok  susalım  çünkü  kuş kanatlar...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sozun-anlami-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Başa', 'bas-basa-turgut-onal-xa5x2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karlı dağlar aşılmaz ki; 

Aşayım

Yorgun insan koşamaz ki; 

Koşayım

Ancak...

Sana özgü yerlerde

Seninle

Başbaşayım.', 'Karlı dağlar aşılmaz ki;  Aşayım Yorgun insan koşamaz ki;  Koşayım Ancak... Sana özgü yerlerde Seninle Başbaşayım....', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bas-basa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lodos', 'lodos-ali-furkan-oguz-kafu5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bakislardaki mavi

ruzgara

ardindan kalan bir tutam ozgurluge sevdalanmaktan gecse yuregimiz

yok 

yanilir yine

ne lodos var

ne ofke

ellerim bile kan icinde

ustum basim camur...', 'bakislardaki mavi ruzgara ardindan kalan bir tutam ozgurluge sevdalanmaktan gecse yuregimiz yok  yanilir yine ne lodos var ne ofke ellerim b...', ARRAY['Türk Edebiyatı','Şiir','Ali Furkan Oğuz']::text[], 8.5, '{"poet":"Ali Furkan Oğuz","poet_slug":"ali-furkan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/lodos-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katık', 'katik-turgut-onal-l0u99', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Onca yıl çalıştım

Harcadım ömrümü

Değer vermediler

Emeğime.

Önüme gözyaşımı koydular

Katık ettim

Ekmeğime.', 'Onca yıl çalıştım Harcadım ömrümü Değer vermediler Emeğime. Önüme gözyaşımı koydular Katık ettim Ekmeğime....', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/katik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Öyle Kolay Değildir Gitmeler**', 'oyle-kolay-degildir-gitmeler-kubra-gulbahar-2h9vb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidecektim…

Gittikçe silinecektim…

Bir daha dönmemek adınaydı tüm yeminlerim! 

Bu eziyetlere bir son vermek uğrunaydı revan oluşlarım..! 

Yeni bir şehrin suyuyla yıkayacaktım kendimi

Tüm günahlarım birer birer dökülecekti üzerimden..! 

Yeni yapraklar verecektim sarıdan uzak…

Yüksek sesle konuşacaktım, içimdeki çığlıklara inat…

Doğruyu bulmak adına böyle deli uğraşlar vermeyecektim! 

Yaptığım yanlışların korkularında yaşamayacaktım

Böyle insafsızca yargılanmayacaktım! 

Gidecektim işte..! Gittikçe silinecektim..! 

Olmadı… yapamadım… gidemedim… silinemedim..! 

Yeniden başlamak için çevireceğim temiz bir sayfam yoktu

Zamana yayamadan tüketmişim her şeyi

Nesnelerin kopukluğunda yaşamışım

Duyguların kırılganlığında…! 

Ömür gitmiş ben öylece durmuşum

Ruhumu sensizlikle dolduralı

Hayata sığmaz olmuşum! ! !', 'Gidecektim… Gittikçe silinecektim… Bir daha dönmemek adınaydı tüm yeminlerim!  Bu eziyetlere bir son vermek uğrunaydı revan oluşlarım..!  Ye...', ARRAY['Türk Edebiyatı','Şiir','Kübra Gülbahar']::text[], 8.5, '{"poet":"Kübra Gülbahar","poet_slug":"kubra-gulbahar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oyle-kolay-degildir-gitmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-turgut-onal-u2n3l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne rüzgâra karşı tükürürüm

Ne uçurumdan aşağı yürürüm

Uçurtmalar uçururum gökyüzünde

Balıklar tutarım denizinde

Mevsim mevsim yaşarım yılları

Avuç kadar ömür

Avuç kadar dünya

Avuç kadar sevgi

Yeter mi insanoğluna? 

Uçsuz bucaksız kâinatta

Yaşam ve ölüm arasında

Avuç kadar yol yok', 'Ne rüzgâra karşı tükürürüm Ne uçurumdan aşağı yürürüm Uçurtmalar uçururum gökyüzünde Balıklar tutarım denizinde Mevsim mevsim yaşarım yıllar...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yol-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döner durur', 'doner-durur-ali-riza-unal-fqjdn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AŞIK VEYSEL sorar durur

Sazını yürekle kırar durur

İçimdeki MEVLANA

Senin ile döner durur.

              Saniye Altun', 'AŞIK VEYSEL sorar durur Sazını yürekle kırar durur İçimdeki MEVLANA Senin ile döner durur.               Saniye Altun...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/doner-durur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş', 'sarhos-turgut-onal-8kkgy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine içmiş zehir zıkkımı

Fitil gibi sarhoş.

Dudağının kenarında sigarası,

Cebinde bir ufak rakısı,

Umurunda değil

Evdeki karısı

Sabah evden çıkmış

Dönüyor geceyarısı.

Zanneder kendini

Kovboy filmindeki şerif

Boyun bosun devrilsin

Emi herif.', 'Yine içmiş zehir zıkkımı Fitil gibi sarhoş. Dudağının kenarında sigarası, Cebinde bir ufak rakısı, Umurunda değil Evdeki karısı Sabah evden ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarhos-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cısss', 'cisss-turgut-onal-3mrls', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbim senin aşkından 

Kor gibi yanıyor kız

Dudağını arala

Gözlerini biraz kıs

Şimdi gelip öpecem

Deme sakın bana

Cısss.', 'Kalbim senin aşkından  Kor gibi yanıyor kız Dudağını arala Gözlerini biraz kıs Şimdi gelip öpecem Deme sakın bana Cısss....', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cisss-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekçi Kız', 'cicekci-kiz-turgut-onal-xj43m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyordu gece vakti

Eski bir şarkı gibi

Vuruyordu camlara

İmbikten geçmiş katıksız bir hüznün

Hikâyesini anlatıyordu sanki akşamlara

Çıplak ayaklı çiçekçi kız

Yine köprü başında bu kez sırılsıklam

Yüzünde aynı tebessüm sımsıcak

Gözleri ışıl ışıl

Saklanma endişesi duymadan

Islanmaktan korkmadan

Çiçek satıyordu

Kendini ilk görüşte sevecek prensini

Hep burada bekliyordu

Son gördüğümde solgundu yüzü

Kesik kesik öksürüyordu

Kime sorduysam bir iç çekerek

İnce hastalıkmış diyordu

Onu bir daha görmedim yazık ki

Aradan yıllar geçti

Ne zaman yağmur yağsa gece vakti

Eski bir şarkı gibi vururken cama

İmbikten geçmiş katıksız bir hüznün

Hikâyesini anlatırken akşamlara

Ben onu düşünürüm

Gözlerimde iki damla yaş

Masamda bir çiçek

Sanki kapıyı usulca açıp

İçeri girecek

Ben buradayım diyecek

Ben buradayım...

Ben...', 'Yağmur yağıyordu gece vakti Eski bir şarkı gibi Vuruyordu camlara İmbikten geçmiş katıksız bir hüznün Hikâyesini anlatıyordu sanki akşamlara...', ARRAY['Türk Edebiyatı','Şiir','Turgut Önal']::text[], 8.5, '{"poet":"Turgut Önal","poet_slug":"turgut-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cicekci-kiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Sen Adı Hayat', 'adi-sen-adi-hayat-mehmet-haluk-hisli-cdkrg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...

sabah düşünce güne 

uyanmamış duygular üşüşürler 

yüreğimize 

hüzünlü beden uyuyuşunun 

güzel uyanışıdır 

senin sevgine

sensizliği hatırlatan ne varsa

yok ederim 

düşerim yollarına 

bir ufka kanat açarcasına

sanki yeni bir göç yolunu 

bulmanın heyecanında 

atılırım kollarına

aralanır duygular

buluşur dudaklarınla 

başlarım yeni bir hayata

bir yağmur yağar

bir vaha doğar

uyanır binlerce yıllık 

kurumuş topraklar

uyanır duygular

adı sen

adı hayat

yeni bir gün başlar

...

Serap Büyük -*- Mehmet Haluk Hisli', '... sabah düşünce güne  uyanmamış duygular üşüşürler  yüreğimize  hüzünlü beden uyuyuşunun  güzel uyanışıdır  senin sevgine sensizliği hatır...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/adi-sen-adi-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıldırın Anısına', 'cildirin-anisina-tuncay-akdeniz-2p6tl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çıldır kazasında övündü köyün

Köyünden göç etmiş çoğu çıldırın 

Baba ocağıdır İsrafil  beyin

Şenlikler yaşamış çağı çıldırın

Dağların yamacı çiçekli güldür

Derelerin içi meyveli daldır

Silkele dalını sepetin doldur

Meyveli bahçedir bağı çıldırın

Karşıdan görünür kel dağın başı

Yolları patika çakıldır taşı

Böreği katmeri ayranlı aşı

Ala balık dolu ağı çıldırın

Gelini kızları giymiş alları

Çiçek açar meyve verir dalları

Arılar kovanda yapar balları

Koyunlu kuzulu dağı çıldırın

Övündü köyünün ilaçtır balı

Elmalı armutlu cevizli dalı

İlmik,ilmik elde dokurlar halı

Nakış,nakış süsler tığı çıldırın

Düğünde oynanır yöre oyunu

Çoban yaylasında yayar koyunu

İner derelerden içer suyunu

Bol olur peyniri yağı çıldırın

*****Vefa borcu*****

Yaptığın çeşmeler ebedi kalsın

Suyundan içine afiyet olsun

Bu eseri gören bir ibret alsın

Çağlamış akıyor suyu çıldırın

O nurlu makamda elinin izi

Duanızdan hacı unutman bizi

Eşinde bin başak köyünün kızı

İkramda içilir çayı çıldırın

Nasıl tarif etsem deseler bana

Canım gibi sevdim söyleyin ona

Hacı İsrafil de yakındır cana

Asıl zadelerin soyu çıldırın

Tuncayım eledim inceden süzdüm

Çok ekmeğin yedim helal et yazdım

Af et hacı baba belki de üzdüm

Kadirşinas insan beyi çıldırın

					07.12.1996', 'Çıldır kazasında övündü köyün Köyünden göç etmiş çoğu çıldırın  Baba ocağıdır İsrafil  beyin Şenlikler yaşamış çağı çıldırın Dağların yamacı...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/cildirin-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşklı sözler ''''su''''', 'askli-sozler-su-evren-demirdelen-i6963', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'soğuk bir duştur doğrusu aşk..

yalnızlığımızdan arındığımız! ! 

tek fark hiçbir havlu eski damlaları yok edecek kadar

kuraklayamaz adamı...', 'soğuk bir duştur doğrusu aşk.. yalnızlığımızdan arındığımız! !  tek fark hiçbir havlu eski damlaları yok edecek kadar kuraklayamaz adamı......', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/askli-sozler-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umulan..', 'umulan-evren-demirdelen-menrj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaşanan hatasızdır..

önce düşün sonra öl..

soğukkanlı sancılar

yavaştan gelir hatırla..

hayal et sonumuzu ki 

acıtmasın! ..

göğün gözüyle bakalım gel

dinleyelim yalnızlığımızı

suskunluğumuzu resmedelim denizlere

o zaman gör

gelip aklımızın yağışlı iklimine

bulacaktır bizi hakikat..', 'yaşanan hatasızdır.. önce düşün sonra öl.. soğukkanlı sancılar yavaştan gelir hatırla.. hayal et sonumuzu ki  acıtmasın! .. göğün gözüyle ba...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umulan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz aşk reçetesi..', 'olumsuz-ask-recetesi-evren-demirdelen-yfewg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yarına kalmazmış hiç bir sevda

kavuşmak imkansız olmadıkça..

ve imkansız olmazmış hiç bir sevda

kadın aşka doymadıkça! !', 'yarına kalmazmış hiç bir sevda kavuşmak imkansız olmadıkça.. ve imkansız olmazmış hiç bir sevda kadın aşka doymadıkça! !...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olumsuz-ask-recetesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Farkediş-', 'farkedis-evren-demirdelen-veyfo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'geçmişimden uzaklaştıkça

yaklaşıyorum gerçeğe

ve tanıdıkça insanları

anlıyorum oyunun büyüklüğünü..

hayatımı gömsede oraya

sessizlik getirecek farklıyı

uzlaşmayı düşünmesem de 

hemfikir olacağız yakınlarda

sabretmek zaman kaybı..

başlamak yakınsa

son da yakındır..', 'geçmişimden uzaklaştıkça yaklaşıyorum gerçeğe ve tanıdıkça insanları anlıyorum oyunun büyüklüğünü.. hayatımı gömsede oraya sessizlik getirec...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/farkedis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevme Beni', 'sevme-beni-aysel-al-7vipf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreciğin kırılacak,

Yaram verdır sarılacak...

Bakma bana, çevrene bak,

Sevme beni ne olusun

Küçücüktüm bahtım kara

Yenik düştüm hem yıllara

Sen kendine bir gül ara

Sevme beni ne olursun

Tatlı sözler söylemeden

Beni aşktan eğlemeden,

Git, haydi git, beklemeden

Sevme beni ne olursun!', 'Yüreciğin kırılacak, Yaram verdır sarılacak... Bakma bana, çevrene bak, Sevme beni ne olusun Küçücüktüm bahtım kara Yenik düştüm hem yıllara...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevme-beni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Hiç Bakma', 'gozlerime-hic-bakma-aysel-al-3b52q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git istediğin yere

Anılar kalsınbende

Sevdam tutsak eder seni

Başkasını sevemezsin!', 'Git istediğin yere Anılar kalsınbende Sevdam tutsak eder seni Başkasını sevemezsin!...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozlerime-hic-bakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin benimle', 'gozlerin-benimle-yucel-gursac-om1wo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bulut yükselir beynimde

üflesem sarı fırtına

saçların beynimde gezer o an

saçların nerede bilemem

okşasam bir avuç alevi

yanar vücudum diri diri

sıksam avuçlarımı yeşil yeşil

iki damla düşer ellerimden

gözlerin benimle gezer

gözlerin

ellerimde bu gece...', 'Bir bulut yükselir beynimde üflesem sarı fırtına saçların beynimde gezer o an saçların nerede bilemem okşasam bir avuç alevi yanar vücudum d...', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gozlerin-benimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinç! !', 'sevinc-evren-demirdelen-7s1zh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yüzümü döndüm

bir sabah vakti güneşe

rüzgarı hissettim yüzümde

kuş cıvıltıları eşliğinde

ilk kez mi bakıyorum

daha mı mavi yoksa bugün gökyüzü? 

bulutlar beyaz gömlekli

yaşamak diyorum..bu sanırım! 

atıp dertlerini bir yana

koşmak yalınayak sokaklarda

selam vermek yeni uyananlara

dağınık saçlarım

deli diyorlar sanırım..

ne yalan söyleyim

seviyorum hala yaşıyor olmayı

yeni açan çiçeklere gülümseyip

hayatın içine dolmayı..', 'yüzümü döndüm bir sabah vakti güneşe rüzgarı hissettim yüzümde kuş cıvıltıları eşliğinde ilk kez mi bakıyorum daha mı mavi yoksa bugün gökyü...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevinc-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil suskun', 'dil-suskun-tuncay-akdeniz-7e5we', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiirler yazmıştım senin adına

Sensiz okunmuyor dil suskun canım

Bal koydum tabağa baktım tadına

Sensiz tadılmıyor bal suskun canım

Mecnun gibi medet umdum çölünden

Çok çileler çektim kader elinden

Bülbül gibi ayrılamam gülümden

Viran oldu bağım dal suskun canım

Yeni girmiş idim aşkın çağına

Dolu yağdırdılar gönül dağıma

Güller dikmiş idim sevgi bağına

Sensiz sevilmiyor gül suskun canım

Tuncayım  yoluna koydum canımı

Ben sensiz neyleyim dünya malını

Yazamadım sana arzu halımı

Yazmıyor kalemim el suskun canım', 'Şiirler yazmıştım senin adına Sensiz okunmuyor dil suskun canım Bal koydum tabağa baktım tadına Sensiz tadılmıyor bal suskun canım Mecnun gi...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dil-suskun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmek İstiyorum', 'gelmek-i-stiyorum-aysel-al-fx0po', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sesin huzur veriyor

Gönlümdeki karanlığı siliyor...

yüz güneş sığıyor avuçlarıma

Göğü saran nefesimle...

Sımsıcak kucağımda ölmek

Sana gelmek istiyorum...

Rüzg^rında savrulankâğıt, gibiyim,

Kor dudakların ısıtıyor içimi

Dağ gibi teninle benimsin,

Zamanı gülüşünle bölmek,

Dünanın en güzel gelinliğini  giyerek

Sana gelmek istiyorum...

Sınırları,kilometreleri,dağları

Gönlümün adımlarıyla bir bir geçmek,

Avuçlarına kır çiçeği misali yerleşmek istiyorum...

Kısaca,

Çağır beni artık, çağır! 

Sana gelmek,

Seninle evlenmek

Seni sevmek istiyorum', 'Sesin huzur veriyor Gönlümdeki karanlığı siliyor... yüz güneş sığıyor avuçlarıma Göğü saran nefesimle... Sımsıcak kucağımda ölmek Sana gelme...', ARRAY['Türk Edebiyatı','Şiir','Aysel Al']::text[], 8.5, '{"poet":"Aysel Al","poet_slug":"aysel-al","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelmek-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi...', 'sevgi-evren-demirdelen-bfr2o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dünyada sevilme gereksinimi olmayan tek şey sevgidir...

onu da sevmeyen yoktur zaten..!', 'dünyada sevilme gereksinimi olmayan tek şey sevgidir... onu da sevmeyen yoktur zaten..!...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sevgi-180-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne desen boş aşk üstüne..', 'ne-desen-bos-ask-ustune-evren-demirdelen-11j7w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaşanmamış bir hayatın 

öcünü alıyorum hatalarımdan

yaptırımı olmayan aşklarımı

rehin veriyorum umutlara

sahibini aradığım..

sevgi sözleri satıyorum şiirlerimde

şiirler ki anlamı

satır arkası..

tek bir özlem bile yok şimdi

hepsi kaçtılar

çıkış yolu yapılmamış 

kalp çıkmazındalar

sağa dönseler yokuş

solda sonsuz bir yanıt

arkalarında..

yükü kendinden ağır bir karınca..

aşk! !', 'yaşanmamış bir hayatın  öcünü alıyorum hatalarımdan yaptırımı olmayan aşklarımı rehin veriyorum umutlara sahibini aradığım.. sevgi sözleri s...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-desen-bos-ask-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç konuşmadın ki! !', 'hic-konusmadin-ki-evren-demirdelen-03v4p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sordun mu hiç ne kadar sevdiğimi? 

belki gözlerine kaç kez gidip geldiğimi? 

ya da senin sevmediğini bildiğimi? 

hiç konuşmadın ki! !', 'sordun mu hiç ne kadar sevdiğimi?  belki gözlerine kaç kez gidip geldiğimi?  ya da senin sevmediğini bildiğimi?  hiç konuşmadın ki! !...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hic-konusmadin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl elmaya', 'kizil-elmaya-hayri-arikan-serdaroglu-4vuno', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TÜRK yolun çetin 

Alplerin metin 

Sür koşşun atın 

Kızıl elmaya 

Düşmanın çoktur 

Korkunsa yoktur 

Hedefin tektir 

Kızıl elmaya 

Engeller erir 

Dağlar yol verir 

Bozkurtlar yürür 

Kızıl elmaya 

Sanmaki hayal 

Bizdeki buhal 

KURAN ve hilal 

Kızıl elmaya 

Serdaroğlu koş 

Ülkü ile çoş 

Yaren ve yoldaş 

Kızıl elmaya 

HAYRİ ARIKAN (SERDAROĞLU)  1974

 Hayri Arıkan (Serdaroğlu)', 'TÜRK yolun çetin  Alplerin metin  Sür koşşun atın  Kızıl elmaya  Düşmanın çoktur  Korkunsa yoktur  Hedefin tektir  Kızıl elmaya  Engeller er...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kizil-elmaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 2', 'rubai-2-ayda-yildiz-n8vxe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bende o denizin icinde bir mahluk

Sasirmis yolunu kacirmis bir alik

Nedir bu tepemde yuzen salinik, salinik

Fisildadi deli ses, takip et bulacaksin bir aciklik', 'Bende o denizin icinde bir mahluk Sasirmis yolunu kacirmis bir alik Nedir bu tepemde yuzen salinik, salinik Fisildadi deli ses, takip et bul...', ARRAY['Türk Edebiyatı','Şiir','Ayda Yıldız']::text[], 8.5, '{"poet":"Ayda Yıldız","poet_slug":"ayda-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-2-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenk Yamaç'' a', 'cenk-yamac-a-yucel-gursac-bzu1l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen geliverdin dunyaya

günler geçmeyecek derken

daha dün anneni tekmelerken...

ellerindir diye tuttuğum

ayaklarındır diye öptüğüm bedende

yanak yanağa geldiğimizi kimse bilmezken...

evren yankılanacak çığlığınla diye beklerken

usulca sokuldun yamacımıza...

titreyen dudakların, sıkılan yumrukların

koyuverince ilk mamayla kendini,

bir kucak daha açıldı beklentili yüreklerimize...

doldurduğunda ikicik avucumu bedenin

telaşı kesiliverdi ellerimin,

yarı ara gözlerinin parıltısı

alıverdi yüreğimin ürpertisini...

ten teneydik üç kat elbisenin altında

sarılsan sıkılamayacak kadar narin

gömsen içine sığamayacak kadar engin

tutsan uçursan havalara

ya terkedilirse ellerin...

asalet gözlerinde başladı,

dudakların fethetti yürekleri

ayakların, minicik parmakların bana saklı

iki avucaydın, düşün ayaklarını...

cesaretimiz uykuna sığındı o gece

mışıl bir nefes

mışıl bir dinleti oldu yorgunluğumuza,

can koktun burnumuza

birimiz oldun,

bir dikildik karşına...

(15.05.2000)', 'Sen geliverdin dunyaya günler geçmeyecek derken daha dün anneni tekmelerken... ellerindir diye tuttuğum ayaklarındır diye öptüğüm bedende ya...', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cenk-yamac-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz', 'caresiz-huseyin-rahmi-levent-uqqwz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hafakanlı geceler oldu yoldaşım

Dertliyim yoktur derdimi paylaşanım

Sılada mecnundum gurbette derbeder

Bir zalimi sevdim sevdadan bihaber

Acı verir bana aşkının ateşi

Isıtmaz içimi sevdanın güneşi

Ümitsizim yardan kafidir artık gam

Mezarım olsun bu loş virane odam', 'Hafakanlı geceler oldu yoldaşım Dertliyim yoktur derdimi paylaşanım Sılada mecnundum gurbette derbeder Bir zalimi sevdim sevdadan bihaber Ac...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Rahmi Levent']::text[], 8.5, '{"poet":"Hüseyin Rahmi Levent","poet_slug":"huseyin-rahmi-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/caresiz-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama İnancım', 'yasama-i-nancim-mehmet-dag-80pgc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana beni soruyor sorgucular

Oda, dar, kafamı duvardan, duvara vuruyorlar.

Taşlarını ben örmüştüm O duvarların 

Hepside beni tanıyorlar

Sendeleyip elimi uzattığım da, oldu 

Taşlar sorguculardan daha insaflı

Hemen parmaklarımdan yakalıyorlar

Çünkü üzerlerinde alın terlerim, emeklerim var

Maaşları artsın diye çırpındığım O gaddar sorgucular

Yaşama inancım olmasa beni öldürecekler.

Onları da tanıyorum en az duvarlar kadar

Biliyorum dinlenip dinlenip dövecekler

Salyalarını silip ve de küfredecekler

Onlar korkak, onlar  ürkek, onlar  ödlekler

Bu zavallılar döneklerle karıştırıyorlar beni

Bilmiyorlar ki karşılarında  kıp kızıl güneş gibi yürek var.

20-5-2005 AVCILAR-İST', 'Bana beni soruyor sorgucular Oda, dar, kafamı duvardan, duvara vuruyorlar. Taşlarını ben örmüştüm O duvarların  Hepside beni tanıyorlar Send...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasama-inancim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar', 'hatiralar-yavuz-bayram-caliskan-sm5v1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yapraklarında sarılı çileklere düşen çiğ damlaları,

Yumuşak mavi bulutlar gezegeni,

Aşk dereleri, akar akşamlara.

Ah kızıl bahçeli çilekler,

Ah dayanılmaz çılgınlıklar,

Kayalıklardaki denizkızları,

Uçuk pembeliğin çekiciliği,

Garip ve yabancı dudaklarda,

Yaşanmışlığın kokusu sinmişti,

Dumanlı alevlerle,

Anıları içimde kıvrandıran,

Ah o hatıralar.

Usul rüzgârlar eser şehrimde

Masal gibi karşımda,

Tutkuya sarılı geçen günlerim.

Rıhtımdaki gemiler yerlerini gözyaşlarıma bırakıyor,

Kışkırtıcı çağrışımlar son demlerini yudumluyor

Durma kader zıpkını daha derine sapla,

Yılgınlık kuş sürüsü gibi.

Silinir gelgitlerle götürülür hatıralar

Yükselen alevler, kaynar nehirler,

İniltiler, ağıtlar,

Kasırgamın dindiği minik çiçekli düşler

Ne biriktiyse silikleşmiş,

Özlemlerin, hasretlerin saldırısında gibiler.

Müthiş hazlar masallardaki şelalenin altında.

Dünümüzün renkli çiçekleri,

Ve yosunlanmış kayın ormanları,

Sihirli zevk yolculuğunun son durakları.

Yağmurlar hiç bitmez, yeni çiçekler için.

Yaralayıcı olan var oluştan yoksulluğum,

Göz kırpıyor hasretle gurbetin gururuna.

Yaramaz günlerin kahkahaları meyhanelerden,

Merak tutsağı gözler,

Dalıyor ufkun engin derinlerine,

Gün huysuzlaşıyor yaklaşan akşamlara,

Gergin öfkeleri kucaklıyor son ışıklar

Beyaz öfkenin köpükleri gözükmüyor,

Çağlayanların gürültüsü yaralıyor,

Girdaplar çekiyor beni derin hatıralara.

Bahar sabahlarına düşen kırağı,

Kızgın çölleri arayan sevdalar

Neşeli çarpıntılarla atan yürekler

Kuşkanadında mutluluğu taşıyan günler,

Saklı duran günahlar çekiliyor,

Trenlerle gizli dünyalara.

Büyülü aynalardaki gözler,

Ödünç bakışların ucuzluğuna yanıyor

Ürkek adımlar hangi dönemece gider? 

Seferinden dönen gemilerin barınağı mı bu liman? 

Güneşsiz günler boynunu eğen ay çiçekleri,

Aya mı sevdalı, güneşe mi? 

Yıllar kalın örtüyor, ses vermiyor hatıralar,

Küller yabancı ve uzak değil,

Hatıralar elden gidiyor.

Ayaklarımın tiryakisi olduğu hatıralar,

Yangına gidiyor yana yana.', 'Yapraklarında sarılı çileklere düşen çiğ damlaları, Yumuşak mavi bulutlar gezegeni, Aşk dereleri, akar akşamlara. Ah kızıl bahçeli çilekler,...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/hatiralar-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-adnan-gordum-o85t4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölüm aniden gelmeli ve

Hiç korkmamalısın..

Zamanı önemli değil,akşam,sabah

Veya geceyarısı,

Belkide sabaha karşı..

Ama aniden gelmeli ölüm.

Hiç kimseyi üzmeden ve

Sessizce terk etmelisin dünyayı

Ve sen bunca yıllık yaşamını

Gözlerinin önünden bile geçiremeden

Göçmelisin dünyadan.

Ölüm böyle olmalı..

(26.08.2002)', 'Ölüm aniden gelmeli ve Hiç korkmamalısın.. Zamanı önemli değil,akşam,sabah Veya geceyarısı, Belkide sabaha karşı.. Ama aniden gelmeli ölüm. ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gördüm']::text[], 8.5, '{"poet":"Adnan Gördüm","poet_slug":"adnan-gordum","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-176-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradığım', 'aradigim-adnan-gordum-9h3mt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeni farkettim,

Ben şarkıları yalnız senin için dinliyormuşum meğer; 

Ve yalnız seni düşünerek okuyormuşum

Bunca şiiri..

Aradığım senmişsin hep

Romanların sayfalarında.

Ve anladımki..

Bütün hikayeler seninle başlayıp

Seninle bitiyormuş güzel yüzlüm..

(30.03.2004)', 'Yeni farkettim, Ben şarkıları yalnız senin için dinliyormuşum meğer;  Ve yalnız seni düşünerek okuyormuşum Bunca şiiri.. Aradığım senmişsin ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gördüm']::text[], 8.5, '{"poet":"Adnan Gördüm","poet_slug":"adnan-gordum","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aradigim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-adnan-gordum-9c0yi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşeyden daha önemli

senin gözlerin,ümitle bakarken dünyaya..

Ve herşeyden daha önemli

Gamzelerindeki çukurlar gülerken.

İhtimal sende önemsersin kendini; 

Çirkin çıkar tarlasının ortasında,

Pırıl pırıl ışıldarken yüzün..

(29.04.2005)', 'Herşeyden daha önemli senin gözlerin,ümitle bakarken dünyaya.. Ve herşeyden daha önemli Gamzelerindeki çukurlar gülerken. İhtimal sende önem...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gördüm']::text[], 8.5, '{"poet":"Adnan Gördüm","poet_slug":"adnan-gordum","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-559-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yola Çıktı Muallâ', 'yola-cikti-muall-ali-aydogdu-k93f9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bence sende oyna muallâ

kaldırım taşlarıyla

unutma

bir sağa koyacaksın, bir sola

bunun neresi muamma

bir sağa diyorum, birde; 

sen bildiğini yaşa

yarına sakla dolgun bacaklarını 

kaldır kaşlarını muallâ

kaşlarıma yasla

anlasana

gözlerin kapalı daha güzelsin dünden

oysa; 

ben seni gözü açık severim

insancıl keyifler uğruna

neyin varsa ortada

uzak olmayalım muallâ

yolu tam ortala! ! !', 'bence sende oyna muallâ kaldırım taşlarıyla unutma bir sağa koyacaksın, bir sola bunun neresi muamma bir sağa diyorum, birde;  sen bildiğini...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydoğdu']::text[], 8.5, '{"poet":"Ali Aydoğdu","poet_slug":"ali-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yola-cikti-mualla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş', 'tas-mehmet-halil-1drtx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz kenarında yaşamak varken,

Asitli böbreğimde yatarsın.

Güveler yemiş gibi, delik deşik gövden,

Sen altın mı olacaksın, ben kıvranırken? 

Allahım ne kadar da aptalsın.', 'Deniz kenarında yaşamak varken, Asitli böbreğimde yatarsın. Güveler yemiş gibi, delik deşik gövden, Sen altın mı olacaksın, ben kıvranırken?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tas-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şişko Adam', 'sisko-adam-yusuf-ziyaeddin-sivaslioglu-rnzuj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şişko adam

Kadıköy meydanında

Sallıyor koca göbeğini

Taşıyor sanki karnında

Sekiz aylık bebeğini

Şişko adam

Gözler kaybolmuş yüzünde

Kafa omuza birleşmiş

Görünmüyor boyun

Şişko bedende

Şişko adam

Elleri somun ekmeği

Ayaklar taşımıyor bedeni

Tonton desen, o da değil

O biliyor çektiği eziyeti

Şişko adam

Eğilemiyor, kalkamıyor istediği gibi

Otursa sandalyeye dert

Kalksa bedene eziyet

Duyardı her gün bin nasihat

Şişko adam

Ültra yüksek

Kollestrol, trigliserit

Nefes darlığı var

Şekerden de muzdarip

Şişko adam

Ağladı, baktı şöyle

Ekmeğe, çaya, şekere

Bin kere tövbe etti

Uymak için diyete

Şişko adam

Yürüdü sokaklarda, parklarda

El uzatmadı tatlılara

İçti suyunu

Gönlündeki kederiyle uyudu

Şişko adam

Hergün söyledi dostlarına

Can boğazdan geçer

Dediklerine bakma

Can boğazdan gider

(istanbul, 6 Mayıs 2005)', 'Şişko adam Kadıköy meydanında Sallıyor koca göbeğini Taşıyor sanki karnında Sekiz aylık bebeğini Şişko adam Gözler kaybolmuş yüzünde Kafa om...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sisko-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görerek geldik', 'gorerek-geldik-i-lhami-arslantas-miea2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne pembe düş gördük ne pembe hayat 

Mazlumun göz yaşın silerek geldik 

Ne şeytan taşladık ne beyan verdik 

Doğruyu yanlışı görerek geldik 

Hiçbir zaman halk huzurun bozmadık 

Bilimle beslendik yalan yazmadık 

Haddimiz aşarak asla azmadık 

Doğruyu yanlışı bilerek geldik 

Gaflete düşmedik hiçbir zamanda 

Medet beklemedik dinde imanda 

Kimi fetva arar iken kuranda 

Doğruyu vicdana sorarak geldik 

Zalim insafından medet ummadık 

Medet et demedik kurtar demedik 

Çareyi muskada cinde görmedik 

Doğruyu bilimde bularak geldik 

Der ilhami gocunmadık sözünden 

Gafile uymadık cahil yüzünden 

İrfan bulmuş kamillerin izinden 

Kement ilmiğini çözerek geldik', 'Ne pembe düş gördük ne pembe hayat  Mazlumun göz yaşın silerek geldik  Ne şeytan taşladık ne beyan verdik  Doğruyu yanlışı görerek geldik  H...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gorerek-geldik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
