INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyen benim', 'usuyen-benim-gokhan-sahin-4599x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'göz yaşlarıyla

ıslatıp

kaldırımları

hüzünleri 

mısralara

döken

benim

ve

bir ankara akşamında

soğuk

bir çocuk parkının

ortasında

üşüyen

benim

ağlayan 

benim

boynundaki pranganın yanlızlığını 

hissederek boynumda

kalbiminin üzerine inen kanın

sıcaklığıyla

kalbi yanan

boş ellerini 

göz yaşlarıyla dolduran

benim…

10.04.2004

21:56', 'göz yaşlarıyla ıslatıp kaldırımları hüzünleri  mısralara döken benim ve bir ankara akşamında soğuk bir çocuk parkının ortasında üşüyen benim...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Şahin']::text[], 8.5, '{"poet":"Gökhan Şahin","poet_slug":"gokhan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/usuyen-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne zaman', 'ne-zaman-gokhan-sahin-0x1tx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne zaman

