INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cop başına', 'cop-basina-i-lhami-arslantas-71i9q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlanacak halimize zoraki 

Gülüyoruz cop başına efendim 

Cop dediğin lezzetli bir şıra ki 

Yalıyoruz cop başına efendim 

Söylüyorsak rahat rahat gıyabı 

Beş cop demek bir hayırın cevabı 

Alıyorlar hem maaş hem sevabı 

Biliyoruz cop başına efendim 

Kırılsa da iki bacak bir kolun 

Yaptım demek kestirmesi bu yolun 

Diploması coptan imiş okulun 

Alıyoruz cop başına efendim 

Der İlhami falakada ayağın 

Vergilerin teşekkürü dayağın 

Yağlısıdır madalyası kıyağın 

Doluyoruz cop başına efendim', 'Ağlanacak halimize zoraki  Gülüyoruz cop başına efendim  Cop dediğin lezzetli bir şıra ki  Yalıyoruz cop başına efendim  Söylüyorsak rahat r...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cop-basina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıncı Ayrılık', 'kacinci-ayrilik-gokhan-sahin-8wvfw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu

kaçıncı ayrılık

kör bir bıçak gibi

saplanan

yüreğime

indikçe

derinlere

daha da acıtan

büyüten

martı beyazlığındaki

sevgimi 

2002', 'bu kaçıncı ayrılık kör bir bıçak gibi saplanan yüreğime indikçe derinlere daha da acıtan büyüten martı beyazlığındaki sevgimi  2002...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Şahin']::text[], 8.5, '{"poet":"Gökhan Şahin","poet_slug":"gokhan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kacinci-ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamoz', 'yakamoz-serif-erginbay-u9wnb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tozlu yollardan geçiyorduk:

Eski güzlere saplanan dikenlerin acısı..

Kırçiçekleriyle taçlanan gün:

Her an bir umut izleği..

Sevgilimin ışıklandırdığı patika yakamoza çıkardı bizi:

Avunmak yok -yaşamın kalbine dalıyoruz- 

soluk soluğa ve soluksuz! 

Balıkçı kasabası:

Bin yıllık gözyaşı ve aşkolmuş denizi,

bin yıllık uğultu,

her aşka batırılmış bir sandalın masalı...

Tozlu yollardan

yakamozun kalbine; 

-Nisan yağmuruyduk sevgilim! -

kasabanın geniş sofrasında şarap...

Tozlu yollarda yıkandık:

Eski güzlere saplanan dikenlerin anısı..

Taçınla aydınlanıyor bütün sular:

Kâlbim bir umut izleği..', 'Tozlu yollardan geçiyorduk: Eski güzlere saplanan dikenlerin acısı.. Kırçiçekleriyle taçlanan gün: Her an bir umut izleği.. Sevgilimin ışıkl...', ARRAY['Türk Edebiyatı','Şiir','Şerif Erginbay']::text[], 8.5, '{"poet":"Şerif Erginbay","poet_slug":"serif-erginbay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yakamoz-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkarım', 'korkarim-gokhan-ebren-o0vl9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'korkarım

her insan gibi

korkulması gereken 

         her şeyden...

sevdadan,

kurttan

geceden de...

senden değil amma

korkarım 

sevdiğim 

en çok

kadınlığını

kullandığın 

    yerden! ..', 'korkarım her insan gibi korkulması gereken           her şeyden... sevdadan, kurttan geceden de... senden değil amma korkarım  sevdiğim  en ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Ebren']::text[], 8.5, '{"poet":"Gökhan Ebren","poet_slug":"gokhan-ebren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/korkarim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-gokhan-sahin-claof', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yalnızlık

o kadar büyük ki

