INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fal', 'fal-metin-yalti-aevez', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğru zamanda,doğru kişi

Çıkacak karşına inan

Ama  üç vakit var daha

üç vaktin birisi

bitecekse de bu gece

en uzunu geriye kalan

Sabırlıysan eğer

hele yüreğinde

birazda aşk varsa eğer

nasıl geçtiğini bilmeyeceksin

sonrakini vakitten sayma

o bazen bir göz süzüş

çokça bir gülümseme kadar uzundur.

Bazen se

           kim bilir

                      belki de

.................

uzunca bir uykudur.

20,3,2000', 'Doğru zamanda,doğru kişi Çıkacak karşına inan Ama  üç vakit var daha üç vaktin birisi bitecekse de bu gece en uzunu geriye kalan Sabırlıysan...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/fal-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cankurtaran', 'cankurtaran-zeki-akcali-l20cy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapat şu sirenleri şoför efendi! ..

Yavaşlat arabayı.

Mümkünse emniyet şeridinden git.

Yetişmek istemiyorum hastaneye.

Tutkularımla yolunda,

Ölmek istiyorum sevdiğimin.

(22/05/2005, Pazar, B.Çekmece)', 'Kapat şu sirenleri şoför efendi! .. Yavaşlat arabayı. Mümkünse emniyet şeridinden git. Yetişmek istemiyorum hastaneye. Tutkularımla yolunda,...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cankurtaran-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Diyeyim Birtanem', 'ne-diyeyim-birtanem-muhsin-altintas-dknwn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üzülmeni, ağlamanı asla istemem inan

Senin gibi bir insana hiç söylenirmi yalan

Mutluluğun en güzeli, en büyüğü her zaman

Senin olsun yalnız senin ne diyeyim BİRTANEM.

Yalnız sensin Dünyada bana veren her şeyi,

Yaşama sevincini, mutluluğu, neşeyi,

Bende dilek diliyorum, tüm hayalin gerçeği

Seni bulsun yalnız seni ne diyeyim BİRTANEM.

Seni üzen mutluluğa ermesin, herdem ağlasın,

Garip garip düşünmekten karaları bağlasın,

Sense huzur dolu, güzellikler hayalinde canlansın,

Sende kalsın yalnız sende ne diyeyim BİRTANEM.

Öyle bir kulki bütün derdi sen olsun

Birtek senle ağlayıp, birtek seninle gülsün

Bir mecnun misali yansın kül olsun

Seni sevsin yalnız seni ne diyeyim BİRTANEM.', 'Üzülmeni, ağlamanı asla istemem inan Senin gibi bir insana hiç söylenirmi yalan Mutluluğun en güzeli, en büyüğü her zaman Senin olsun yalnız...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Altıntaş']::text[], 8.5, '{"poet":"Muhsin Altıntaş","poet_slug":"muhsin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-diyeyim-birtanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heryerde sen..ama yoksun', 'heryerde-sen-ama-yoksun-evren-demirdelen-hhc7f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir kış günü..

otobüs camının soğukluğunda hissettim

yokluğunu..

geceydi..

kar yağıyordu üstelik..

savruldun rüzgarla çarptın cama..

üşüdüm ama..

yokluğuna sarılamadım!', 'bir kış günü.. otobüs camının soğukluğunda hissettim yokluğunu.. geceydi.. kar yağıyordu üstelik.. savruldun rüzgarla çarptın cama.. üşüdüm ...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/heryerde-sen-ama-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah', 'ah-zeki-akcali-ldsc5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elinize batsın,

