INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerinizdeydi yüreğim! ...', 'ellerinizdeydi-yuregim-cemal-nalci-kucmv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o gece,

	ellerinizdeydi yüreğim! ...

otogarda

	bir sokak lambasının altında…

saat 22:00 suları

hava bir başka karanlık

gökyüzü bir başka küskün 

yüreğinde yağmur bulutları

bulutlar sabaha saklı…

o gece,

ellerinizdeydi yüreğim

ve gecenin sessiz karanlığında

bir hayalin kalmıştı pencerede

	bir de ellerin 

		dokunuyordu yüreğime…

o gece,

ellerinizdeydi yüreğim

otogarda

	bir sokak lambasının altında…

uzaklaşırken gecenin buzul çıplaklığında

bilemezsin bedenimin nasıl titrediğini

bir ben vardım geceleri

		bir de hayalin,

örtü beni...

ellerinizdeydi yüreğim

0406122353ct

