INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaddaş', 'yaddas-sair-nadirezheri-hfv2s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önceden ellerimi gönderirem

Qapin çalinir...

Ve görürşen:

Bölüm bölüm toplaniram

Tekce dodağlarimdir yolda qalan...

Şimdi

Neqeder susqundur evin...

(...Ve yaddaşinda yaradirsan meni...)

Erdebil-2000', 'Önceden ellerimi gönderirem Qapin çalinir... Ve görürşen: Bölüm bölüm toplaniram Tekce dodağlarimdir yolda qalan... Şimdi Neqeder susqundur ...', ARRAY['Türk Edebiyatı','Şiir','Şair Nadirezheri']::text[], 8.5, '{"poet":"Şair Nadirezheri","poet_slug":"sair-nadirezheri","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yaddas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hoş Geldin Öfkem', 'hos-geldin-ofkem-ahmet-turan-altunsu-to0gh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugün öfkeme izin verdim. 

giyindirdim, kuşandırdım; sokağa salıverdim, 

bardağın dolu tarafındayım artık... 

sormayın kaç damla su var diye, 

belki biraz bulanık... 

-oysa biz ne bulanık sular gördük- 

başlasak mı diyorum yeni bir mesaiye...

Ayşe ninemin 

-mütebessim yüzü gelir 

-gözlerimin önüne... 

bir çift mavi boncuk, gözlerimi kamaştırır. 

almış testere ağızlı bıçağını eline, 

kaptırmış kendisini içli bir sevda türküsüne; 

bir yandan çayır biçer, 

bir yandan bostanına suyu kavuşturur.. 

sever yaşamayı benim Ayşe ninem, 

Ayşe ninem bidenem...

Mehmet dedem sakin, muzur mu muzur. 

aldanmayın sert görünüşüne... 

oturmuş duldasına yaşlı dut ağacının, 

tüttürürken cigarasını fosur fosur, 

bilir ki her bir telinde simsiyah saçının, 

okunur ninemin; 

-dedemin ruhunda yarattığı huzur... 

sever yaşamayı benim Mehmet dedem, 

Mehmet dedem bidenem...

Ayşe ninem çalışır, kalır kan ter içinde,

Mehmet dedemin sevdası atının terkisinde! ..

bardak neden bu kadar boş? ...

su neden bulanık bu kadar? ...

nerede kaldın öfkem; 

duymadı mı sokaklar? ..

öfkem yetiş! .. öfkem koş! ..

bırakma beni başıboş! ..

............

hoş geldin öfkem! 

-26.05.2005 / Ankara

-Ahmet Turan Altunsu', 'bugün öfkeme izin verdim.  giyindirdim, kuşandırdım; sokağa salıverdim,  bardağın dolu tarafındayım artık...  sormayın kaç damla su var diye...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hos-geldin-ofkem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurur', 'gurur-esma-ozdemir-oxznn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar aşılır; yıllar tükenir 

Sevgi aşınır; yürek tükenir 

Dostlar yaralanır; vefa tükenir 

Tükenen her sonun bir ilki vardır; 

Bütün ilkler gururla başlar 

Gururla tükenir... 

Biten her güzelliğin sonunda 

Yalnızlık ölüm gibidir.

Yalnızlık içinde inan 

Gurur can simididir. 

Ölüm, Hak''tan; ve 

Mutlak boynumuzun borcu...

Lakin insan

Ne, yalnızlık içinde boğulmalı 

Ne de ömrünce 

Boynunda can simidi taşımalıdır. 

Sevebildiğince 

Gül güzeli Arkadaşım-

sevmeli...sevmeli...sevmelidir!', 'Yollar aşılır; yıllar tükenir  Sevgi aşınır; yürek tükenir  Dostlar yaralanır; vefa tükenir  Tükenen her sonun bir ilki vardır;  Bütün ilkle...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gurur-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar yeşili gözlerin...', 'sonbahar-yesili-gozlerin-cemal-nalci-bo0lz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'babamdan

oğluma...

sonbahar yeşili gözlerinde öyküler

kimi; 

aç kalmış sokakların mavisi,

tan yerinde gizlenmiş aşk öyküleri 

						ya da...

dağ fulyası yüklü yüreğini

			seyrederim,

			iz be iz bedeninde...

sonbahar yeşili gözlerin 

			dalar…

			derinliklerden

			sessizce haykırışın yankılanır...

gururla saklarsın gözyaşlarını

tutamazsın

		öyküler saçılır 

			her damla da

				          	düşer,

			toprak ananın kucağına

						      filizlenir...

ben,

yağmur sonrası hüznü yaşarım

			baktıkça sana...

		

sonbahar yeşili gözlerin

0311031603pt

cemalnalcı', 'babamdan oğluma... sonbahar yeşili gözlerinde öyküler kimi;  aç kalmış sokakların mavisi, tan yerinde gizlenmiş aşk öyküleri  						ya da......', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sonbahar-yesili-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgem Düştü', 'golgem-dustu-sule-aydemir-43pqb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yine 

gözüm 

önüme

düştü

üzgün 

perişan

CanCemre’m

fahr

doğuştan

bu

beşikten 

geçer 

diyorlar

beşiğe

gözüm 

ellerimle

düştü 

bu kez 

önüme

ne zor

beklemek

bilinmeyeni

ölüme

halka halka

geçirmek 

KanÇiçeklerini

üç

kardeş

benzemez

üçü

daha 

dün 

gülmüştük de

demişti

öğretmen 

teyze

-sandıktan

çıkar 

yazma

oynarım

gölgemle

gözüm 

ellerim

yaşamla 

düştü 

önüme

çakıl taşlarını

tekmeler gibi

sektirip 

gidiyoruz

beşikten 

beşiğe

bilinmeyene

gölgem

düştü

önüme', 'yine  gözüm  önüme düştü üzgün  perişan CanCemre’m fahr doğuştan bu beşikten  geçer  diyorlar beşiğe gözüm  ellerimle düştü  bu kez  önüme n...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/golgem-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüyorum...', 'dusuyorum-emine-deniz-hs6ft', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni hergün bu saatlerde 

Terk ediyorum, 

her akşam güneş batmadan önce, 

Sen yorgun eve dönerken 

Ben üşüyorum... 

Sensizliğime inat 

sevgisizliğine inat 

Denizin gözlerine düşüyorum 

Sonra 

Islak bir kedi yavrusu gibi sokulup koynuna,

Rüzgarla deliler gibi sevişiyorum...', 'Seni hergün bu saatlerde  Terk ediyorum,  her akşam güneş batmadan önce,  Sen yorgun eve dönerken  Ben üşüyorum...  Sensizliğime inat  sevgi...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dusuyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-serhat-sumer-vydd8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1

Belki de bulutlar

Bizden yanadır

Elma şekerlerimizi elimizden düşürdüğümüzde 

Tavşana benzettiğimiz bulutlar...

Yani

Yüzü güldüğünde çocukluğumuzun 

Bembeyaz papatyalar gibi

Önümüze serilirler 

Bize bir gülüşlük sonsuzluk verirler 

Hani el ele tutuştuğumuzda 

Ağlayan bulutlar 

Sırılsıklam bir sessizlikte 

İçi boşalır bir anda kalbimizin 

Şimşekler çakar kızdıklarında 

Sustuklarında 

Okyanus olurlar...

2

Ve güneşte bizdendir 

Tam da katranlaşmaya başlarken karanlık 

Her şey bitti derken 

Sürgülerken umudun nizamiye kapısını 

Tarihten gelen bir kahraman gibi

Doğuverir acının üstüne 

Her şey gülücük saçar 

Aralarız gözlerimizi 

Birde bakarız ki 

Silinip gitmiş gölgeler 

Belki farkına bile varmayız 

Oysa ne kadar kolaymış deriz 

Yenmek kederi

Ve güneşe bir selam göndeririz 

Martılarla...

3

Çiçeklerde bizdendir 

Ağaçlar ve kuşlar 

Bir gülüşümüz için serilirler ayaklarımıza 

Buradayız derler, sizin için 

Duymayız 

Kolaydır gözyaşına teslim olmak 

Sırtımızı döneriz umut saçan ne varsa 

Işıklarına aldanırız gecenin 

Öpüp koklaşırken kainat 

Biz yaşlanırız yaşamın yokuşlarında 

Bir döşeğe sarılırız 

İçimizde gam 

Ölüm bizdendir...', '1 Belki de bulutlar Bizden yanadır Elma şekerlerimizi elimizden düşürdüğümüzde  Tavşana benzettiğimiz bulutlar... Yani Yüzü güldüğünde çocuk...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/umut-178-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız mı? ..', 'zamansiz-mi-cemal-nalci-pil3y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen; 

geldiğin an,

güleç bir mavilik başlar

gözlerinde 

ulaşamam…

gök mavi... 

deniz mavi...

boğulurum! .. 

		derinliklerinde

			denizinin…

apansızca çıka geldin ya…

beklenmedik,yani…

bazen de…

ne denizin parıltısı 

		yetiyor gözlerine…

ne de ay

		benziyor yüzüne...

sen; 

zamansız bir güneş misin? ...doğan

yoksa,

bir bahar mısın? ..zamansız açan! ..

zamansız mı? ..

0205271647pt

cemalnalcı', 'sen;  geldiğin an, güleç bir mavilik başlar gözlerinde  ulaşamam… gök mavi...  deniz mavi... boğulurum! ..  		derinliklerinde 			denizinin… ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zamansiz-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldatılan', 'aldatilan-serhat-sumer-trisk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimden yaşlar düşerken 

Işıkla dans ediyor gölgeler 

Susuyorsun 

Ben bilmem hangi iklimin kıvamında 

Sana çarpılıyorum şimşeklerle 

Sızılar içinde...

Gün batıp gidiyor 

Karşı tepenin arkasından 

Pencerede kanlar içinde bir akşam 

Bulutlar gözlerin oluyor 

Ağlıyorsun 

Belki küçük bir çocuk oluyorsun 

Gözlerimin içinde 

Elinden oyuncağı çalınmış...

Bir fotoğraf ellerimden düşüyor 

Kırılıyorsun

Bir şarkının ortasına yumruğumu vuruyorum

Kurtar beni 

Ölüyorum

Dudağının ucunda çarpıyor kalbim

Bir kere söylesen yetecek diyorum

Söylemiyorsun...', 'Gözlerimden yaşlar düşerken  Işıkla dans ediyor gölgeler  Susuyorsun  Ben bilmem hangi iklimin kıvamında  Sana çarpılıyorum şimşeklerle  Sız...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aldatilan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesela', 'mesela-cemil-aygen-d2pw4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat gizlenmiş bir yerlere

Çekip çıkartalım mı...Mesela

Gizemleriyle hep bizimle yaşamışta

Arkadaş olmuş tam yanlışlarla 

Sevgiyi ona doğru anlattılarmı...Mesela

Mazi derin bir yara kaldı içimde 

Gizli kalmış saklanmış

Neyimiz varsa bir bir ortaya çıkartıp

Hepsini sizlere anlattim mi...Mesela

Bir kız vardı hani sevdiğim 

Sarı saçları mavi gözleri vardı

Bana çok mu bakıyordu 

Beni çok mu seviyordu...Siz anladınız mı Mesela 

Hani onun da benim de titreyen ellerimiz vardı 

Heyecanla çok sarılırdık birbirimize de

Ama o kadar istediğim halde..O..

Daha öpüşmesini bilmiyordu...Mesela

Bu kadar ömür geçirdik...Saçlara aklar düştü

Bir kıyı köşe oturmuş anı yazıyorum 

Eski zamanın gençliği çok geride kaldı 

Sahi o gençlik yıllarımızda biz neler neler 

Yapıyorduk da Hatırlamıyorum Mesela....', 'Hayat gizlenmiş bir yerlere Çekip çıkartalım mı...Mesela Gizemleriyle hep bizimle yaşamışta Arkadaş olmuş tam yanlışlarla  Sevgiyi ona doğru...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mesela-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalga ve şişe! ..', 'dalga-ve-sise-cemal-nalci-2dwhw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben; 

yağmurlu bir gecenin

	örtüsü sanırdım

			hüznü...

oysa sen,

	bu terkedilmişliği,

	bu yalnızlığı

	deniz kenarında

	dalgalarda sallanan

bir şişenin

derinliklerine sığdırmışsın...

bazen; 

ahengine bırakıyordun ya...kendini

dalgalar yaklaştıkça

	dudaklarında bir tebessüm...

	durulur bazen yüzün

		derinliklere süzülürsün...

dalgalar sıklaşır

		nefesinde...

kaşların çatılır

	yutkunursun...

sessizliğin haykırır gözlerinden

	dalgalara yüreğini bırakan

			şişenin ardından...

tekrar sallanırsın,

	farkında olmadan...

gözlerini yaslarken dağlara

	akşamın yükü çöker kucağına...

bir giden var! 

	besbelli...

sen misin? ..

	sallanan şişe mi? ..

		dalgaların kucağında...

ben; 

yağmurlu bir gecenin

	örtüsü sanırdım

			hüznü...

sen; 

ardından bakakaldığın 

	bir şişeye mahkum ettin

			kendini...

sallanan şişe 

0205241334c

cemal nalcı', 'ben;  yağmurlu bir gecenin 	örtüsü sanırdım 			hüznü... oysa sen, 	bu terkedilmişliği, 	bu yalnızlığı 	deniz kenarında 	dalgalarda sallanan ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dalga-ve-sise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni düşünüyorum...', 'seni-dusunuyorum-cemal-nalci-zcrod', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni düşünüyorum,

bir odun parçasının yanmama uğraşı verdiği

sobanın başında 

	üşümemeye çalışarak…

küçük ve darmadağın odamın içinde

sigaram elimde 

	dumanıyla dört duvarın en ücra köşelerini

	ağır ağır gezerek

	bir hacım,

		bin düşünce içinde! ..

ayaklarım kıvır kıpır bir şekilde

		düşünüyorum, seni…

gecenin karanlığında

	karanlığın ötesini

		daha ötesini

		görmeye çalışıyorum

					seni…

seni düşünüyorum,

	gecenin bir’i

	bir çoğu uykuda

			ve tabii sen…

fakat vakit benim için çok erken

kim bilir! ..

	belki de son dem

		sonbaharım da…

ve seni düşünüyorum

	kış günlerinde

	dışarıda kar,

		koşar adım ıslık eşliğinde

					…karlar

				kapıyı tırmalıyorlar…

	soğuk acımasız kış günlerinde

	bir atlatabilsem

		belki de,

			tekrar karşımda bahar….

seni düşünüyorum

8811130110pz

cemalnalcı', 'seni düşünüyorum, bir odun parçasının yanmama uğraşı verdiği sobanın başında  	üşümemeye çalışarak… küçük ve darmadağın odamın içinde sigara...', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/seni-dusunuyorum-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayacaksın! ..', 'anlayacaksin-cemal-nalci-17fq9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'anlayacaksın; 

soğuk bir gecede

	çıplak ve yapayalnız

	umutlara sarılarak beklemenin

			ne demek olduğunu…

anlayacaksın; 

yağmur altında ıslanmanın

	ve özlenen bir bardak suyun

		ne demek olduğunu…

anlayacaksın; 

baharda kuşların öttüğünü

	kelebeklerin dans ettiğini

	yemyeşil kırlarda güzelliği

	anlamayı

		anlatmayı…

	sana verilen değeri

				özlemi…

	ve suskunluğumu,

			anlayacaksın…

anlayacaksın; 

üzülerek,sevinerek,

	baktığın halde göremeyerek…

	yıkılarak,kalkarak,

			düşe kalka…

ve belki de…

	yittiğin an anlayacaksın…

anlayacaksın

8811102220pb

cemalnalcı', 'anlayacaksın;  soğuk bir gecede 	çıplak ve yapayalnız 	umutlara sarılarak beklemenin 			ne demek olduğunu… anlayacaksın;  yağmur altında ısl...', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/anlayacaksin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katar Gizliden', 'katar-gizliden-huseyin-sigirtmac-pjsfq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir fırtına kopar, eser bağrıma.

Duyguma sevdayı katar gizliden.

Ayrılık ve hasret gider ağrıma.

Gurbet yollarına katar gizliden.

Yar hayali gitmez oldu gözümden.

Keder eksilmedi bir gün yüzümden.

Ateşlere düşüp yandım özümden.

O yar alevini katar gizliden.

Ne gözlerim görür, ne el ulaşır.

Bir hayale daldım aklım dolaşır.

Mecnun’un sevdası bana bulaşır.

Sığırtmaç’ı çöle katar  gizliden.', 'Bir fırtına kopar, eser bağrıma. Duyguma sevdayı katar gizliden. Ayrılık ve hasret gider ağrıma. Gurbet yollarına katar gizliden. Yar hayali...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/katar-gizliden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık', 'pismanlik-ayhan-yavuz-acikgoz-efjl0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözümden düşen damlalar

Yüreğime inmez oldu

Aklımda duran cümleler

Dillerimde dönmez oldu

Şükretmedim kazanırken

İpeklere bezenirken

Ben ateşe özenirken

Yandı yürek, sönmez oldu

Bu ne özlem, bu ne çile

Terkedildim takbih ile

Üç yaşında kızım bile

Omuzuma binmez oldu

Mümkün mü bu kalbi sökmek

Ve gözlerden neş''e dökmek

Bir lokma yediğim ekmek

İçerime sinmez oldu

Ayhan''ım dön, bir bak geri

Şimdi serde, veren seri

Yirmi iki yıldan beri

Yaralarım dinmez oldu

(istanbul-26.05.2005)', 'Gözümden düşen damlalar Yüreğime inmez oldu Aklımda duran cümleler Dillerimde dönmez oldu Şükretmedim kazanırken İpeklere bezenirken Ben ate...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/pismanlik-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsim', 'dort-mevsim-cenk-aksal-27xee', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hüzün bulutları çökerde

düşünüpte seni..

kar olup yağarım...

dağlarına.

kardelenler açar,

dört bir yanda...

bir fırtına çıkar da:

sevdan karışır rüzgarlarıma..

hatıralar sarar heryanını:

ağlarsın/ayrılığa..

mevsim bahar olur da

kuşanır sevdayı yüreğim,

ulaşırım sıcak ellerine,

titrer yüreğin/ağlarsın,

mevsim olur sonbahar:

dökülen her yaprakta,

gözyaşlarımı ararsın..

bir canız seninle,

dört mevsim beni

yaşarsın/sevgiyle

  ''uzanır ellerin sevdama''

   ''sıcağımda yanarsın''', 'hüzün bulutları çökerde düşünüpte seni.. kar olup yağarım... dağlarına. kardelenler açar, dört bir yanda... bir fırtına çıkar da: sevdan kar...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dort-mevsim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru (1)', 'soru-1-hatem-kardesler-tqerz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her hüzünlü şarkı bana seni mi hatırlatsın? 

Seni beklemekle mi geçsin ömrüm…

Şarkının her nağmesi yüreğimi mi kanatsın? 

Hergün başka bir acıyı mı seçsin ömrüm…

Ayrılık,ayrılık diye mi geçsin günlerim,

Cevapsız kalmasın artık niçinlerim,nedenlerim,

Ben tertemiz aşkım için inlerim,

Artık ayrılık şerbetini mi içsin ömrüm…

Söyle bir yol göster bana…

İçinde bulunduğum durumu anlasana…

Baksana hiç dur denilmiyor zamana,

Bu acı hasretle mi göçsün ömrüm…

	

		         (Hasret İçimde Bir Dağ Kitabından)', 'Her hüzünlü şarkı bana seni mi hatırlatsın?  Seni beklemekle mi geçsin ömrüm… Şarkının her nağmesi yüreğimi mi kanatsın?  Hergün başka bir a...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/soru-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin ham maddesi', 'sairin-ham-maddesi-mikdat-bal-r8u8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi, aşk, hürmet, saygı,

Üzüntü, keder, kaygı,

İlham, sezgi, his, duygu

Şairin ham maddesi, şiir de ifadesi

Yaprak, çiçek, böcek, kuş,

Hayal, gerçek, rüya, düş,

Hem ağlayış, hem gülüş

Şairin ham maddesi, şiir de ifadesi

Zerre, küre, kuru, yaş,

Hayat, gurbet, iş ve aş,

Can, canan, dost, arkadaş

Şairin ham maddesi, şiir de ifadesi

Ülfet, rahmet, vicdan, din,

Haset, gıpta, nefret, kin,

Melek, şeytan, insan, cin

Şairin ham maddesi, şiir de ifadesi

Eğlence, neşe, sefa,

Sıkıntı, güçlük, cefa,

Dostluk, dürüstlük, vefa

Şairin ham maddesi, şiir de ifadesi

Mikdat der kalem, lisan

Sen bu işi kolay san

Tabiat, çevre, insan

Şairin ham maddesi, şiir de ifadesi', 'Sevgi, aşk, hürmet, saygı, Üzüntü, keder, kaygı, İlham, sezgi, his, duygu Şairin ham maddesi, şiir de ifadesi Yaprak, çiçek, böcek, kuş, Hay...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sairin-ham-maddesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru (2)', 'soru-2-hatem-kardesler-15kps', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neye,nereden,nasıl başlasam? ...

En güzel günleri mi yazsam gelecekteki? ...

Senin yanında zamanı cendereye mi geçirsem? ...

Bir demet mi sunsam leylaklardan yoksa…

Aşkımı nasıl anlatsam ki! ...

Tutsaklığını gönlümün,

Upuzun cümlelerle mi dile getirsem…

Rüyalarımı nasıl açsam sana? ...

Hangi kelimelerle anlatsam güzelliğini? ...

Akıl almaz sorulara nasıl cevap versem? ...

Nasıl? ...Nasıl? ...Nasıl? ...  

	

		         (Hasret İçimde Bir Dağ Kitabından)', 'Neye,nereden,nasıl başlasam? ... En güzel günleri mi yazsam gelecekteki? ... Senin yanında zamanı cendereye mi geçirsem? ... Bir demet mi su...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soru-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnış Zaman/Sevda', 'yalnis-zaman-sevda-cenk-aksal-z0v2h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dün akşam söyledin,

gidiyorum:

bitti dedin/sendin

şok oldum titredim,

delice seven/ben/sendin,

nasıl kıydın yıllara,

bilemedim...

ölüm ayırır diyen/sen/bendim

bir hiç uğruna/aşkımızı

tükettin...

boynuma sarılıp ağlayan:

yalvaran/bitmesin isteyen,

sen/bendim

ateş sarmışken bacayı,

kitlenmişken sevdaya,

herşeyi tükettin...

sana yalvarmam bilesin:

gizli gizli ağlarım,

kimseler  görmesin...

son satırlar/bu yazdıklarım

vakit geçiyor bak:

sakın af dilemeyesin...

ölümüne seven/sen/bendim...

    ''yıllar geçecek,bu günün ardından''

    ''yüreklerde yaşanacak bu sevda''

    ''vuslat vakti kavuşacak/sen/bendim''', 'dün akşam söyledin, gidiyorum: bitti dedin/sendin şok oldum titredim, delice seven/ben/sendin, nasıl kıydın yıllara, bilemedim... ölüm ayırı...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalnis-zaman-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru (3)', 'soru-3-hatem-kardesler-62nts', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen sevmek nedir bilir misin? ...

Sabahlara kadar sevdiğini düşündüğün oldu mu hiç? :..

Gözlerin tavanın bir köşesine takılıp kaldı mı? ...

Dudaklarında bir hasret şarkısı,

Kulaklarında kemanın tatlı nağmesi,

Ve elinde sigarayla sabahladığın oldu mu hiç? ...

Kalp atışını duydun mu derinden derine? 

Bir sarhoş narasında bir şeyler sezebildin mi? ...

Kısacası ömrünün baharında,

Sevebildin mi? ... Sevebildin mi? ... sevebildin mi) ? ...

		         (Hasret İçimde Bir Dağ Kitabından)', 'Sen sevmek nedir bilir misin? ... Sabahlara kadar sevdiğini düşündüğün oldu mu hiç? :.. Gözlerin tavanın bir köşesine takılıp kaldı mı? ... ...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soru-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cözemedim', 'cozemedim-serpil-maglicoglu-13aa6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni hatirladigim icin mi üzgünüm,.

yoksa üzülebilmek icin mi hatirlar insan? 

Sana özlemim, seni özledigimden midir,

yoksa özleyebilmek midir asil özlem? 

Seni var oldugun icin mi düsünürüm,

yoksa düsündügüm icin mi varsin sen? 

Benim derdim gercekten sen misin,

yoksa sorun aramak midir  asil dert? 

Cözemedim', 'Seni hatirladigim icin mi üzgünüm,. yoksa üzülebilmek icin mi hatirlar insan?  Sana özlemim, seni özledigimden midir, yoksa özleyebilmek mid...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cozemedim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-hatem-kardesler-k0ko0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani dağ başlarında beraber olacaktık? ...

Hani mor çiçekler mutluluğumuzun sembolüydü? ... 

Hani ağaç gövdelerinden ismimiz silinmeyecekti? ...

Hani kuşlar yalnız bizim için ötecekti? ...

Hani tamburlar bir daha hüzzam çalmayacaktı? ...

Hani Palandöken daha heybetli,

Kar aşkımızca beyaz olacaktı? ...

Hani ellerimiz isteksiz,gözlerimiz yorgun olmayacaktı? ...

Hani sen yıllar yılı “Liselim” kalacaktın? ...

Hani hüzün katarı kara trenlerden,

Yolumu bekleyecektin? ...

Ve……………………………………………….

Hani birgün karşıma çıkıper olacaktık? ...

“Ben geldim” diyecektin……………...

		         (Hasret İçimde Bir Dağ Kitabından)', 'Hani dağ başlarında beraber olacaktık? ... Hani mor çiçekler mutluluğumuzun sembolüydü? ...  Hani ağaç gövdelerinden ismimiz silinmeyecekti?...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hani-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-hatem-kardesler-sxzwy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Palandöken Dağlarında

Bir sisli hava gezinmekte şimdi…

Karın güzelliğine eş duygularımda,

Bir şüphe sezilmekte şimdi…

Gezinmekteyim şimdi ıssız sokaklarda,

Karın güzelliğine eş duygularım,

Beni sensiz bırakır sessiz sokaklarda,

Ben aşkımı karın beyazlığında ararım…

		         (Hasret İçimde Bir Dağ Kitabından)', 'Palandöken Dağlarında Bir sisli hava gezinmekte şimdi… Karın güzelliğine eş duygularımda, Bir şüphe sezilmekte şimdi… Gezinmekteyim şimdi ıs...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kar-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır..', 'sir-osman-kilic-2pfco', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yapma güzel

Bakma bana öyle

Birşeyler var gözlerinde

Bana doğru

Biliyorum

Görüyorum

Beyinkürenin ardı o kasabın piçinde

Sol-ön lobu bende

Anlıyorum seni

Ve seni seveceğim diyemeden

Seni seviyorum diyemeden

Seni sevdim diyemeden

Seni sevmiştim de diyemeden

Zaman nasıl akıvermişti hemen 

Öğrendim ki kaçar gibi taşınmıştın mahalleden

Dedikodu aldı yürüdü bilmem kaç ay boyunca

Taş olsan-ki öyle idin

Kuma dönerdin

O lafları duyunca...

Anlamıştım seni o zaman bile

İki çocuğun anan-baban

El toprağında bir kocan 

Bolca sevgilin vardı

Ahh o memleket orospusu yüreğine

Beni de alsan ne vardı? ...', 'Yapma güzel Bakma bana öyle Birşeyler var gözlerinde Bana doğru Biliyorum Görüyorum Beyinkürenin ardı o kasabın piçinde Sol-ön lobu bende An...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sir-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namus İki Bacak Arasında Olur (!)', 'namus-i-ki-bacak-arasinda-olur-muharrem-cetinkaya-dia4y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İliklerimizi emdiler,yediler bitirdiler,

Siz çalışın,kazanın,sabredin dediler.

Kandırdılar,satmaya alıp götürdüler,

Namus iki bacak arasında olur dediler.

Garibin hakkını yiyip,milleti sömürdüler,

Her şeyi...........için yaptık  dediler.

Biz aç yatarken,karşımızda genirdiler,

Namus iki bacak arasında  olur dediler.

Yanlış tarttı,yanlış biçti,yanlış ölçtüler,

Biz doğruyuz,biz haklıyız,güçlüyüz dediler.

Etimizi,.......,bacağımızdaki don_u söktüler,

Namus iki bacak arasında  olur dediler.

Biz de ne namus kaldı ne ar,yere düşürdüler,

Olabilir,yoksulun namusu mu olur dediler.

Biz de inandık,sandık,bizi düşündüler,

Namus iki bacak arasında  olur dediler.

Düştükçe,leş kargası gibi başımıza üşüştüler,

Boşver diyerek,çiğ etimizi bile yediler.

Namus insanın özündedir,Onlar bi-hiçtiler,

Namussuzlar yıllarca kanımızı içtiler,

Namus iki bacak arasında olur dediler.

                 -bizde hep inandık-', 'İliklerimizi emdiler,yediler bitirdiler, Siz çalışın,kazanın,sabredin dediler. Kandırdılar,satmaya alıp götürdüler, Namus iki bacak arasında...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/namus-iki-bacak-arasinda-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Anlarda', 'sensiz-anlarda-cenk-aksal-alzg7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''nereye baksam 

sen varsın,

cindy bebeklerin ağlıyor,

kelebeklerinin rengi soldu..

piyerlotide çekildiğimiz resim

ellerimde şimdi,

saçlarını okşuyorum,

dalıpta melül gözlerine,

damla damla gözyaşı 

akıtıyorum yanaklarıma,

gittiğin gün giydiğin,tişörtün

hala mis gibi sen kokuyor,

keyf kahvesi içtiğin fincanın:

ayrılık falı içinde duruyor..

öksüz kaldı her yanım,

içim alev alev yanıyor...

ağlamaklı piskopat balığım,

akvuryumum gözyaşıyla taşıyor,

hani birgün darıldığımızda,

barışmak için aldığım,

kırmızı kalpli yastık varya,

her eve girişimde gözlerime batıyor,

seni seviyorum/çok seviyorum,

yaprak yaprak dökülüyor zaman,

yüreğim kanıyor ağlıyorum...

gözlerim her dakika kapıda,

gelecekmişsin gibi bir his var içimde,

sen yoksun ama/senle yüreğim,

dön artık geri hayat çekilmiyor....

  ''ağlamadım gidişinin ardından''

   ''biliyorum döneceksin/birgün''', '''nereye baksam  sen varsın, cindy bebeklerin ağlıyor, kelebeklerinin rengi soldu.. piyerlotide çekildiğimiz resim ellerimde şimdi, saçlarını...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sensiz-anlarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Dön.! !', 'kendine-don-siya-yok-jga9c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baykuşlar türemiş, enseden süzen 

Çakallar konmuş peşin süre gezen 

Memnun değilse düzülen ve düzen 

Titreyip kendine dönmek iste sen 

Duygular bencil, isteniyor hep ben 

Doğrular bulunmaz gören göz körken 

Yüreğin suskun, düşmüyorsa gölgen 

Titreyip kendine dönmek iste sen 

Boşuna vermiyor kuruşu veren 

Neden bilmiyor kurşunu güveren 

Benliğinin dışına taşar öfken 

Titreyip kendine dönmek iste sen', 'Baykuşlar türemiş, enseden süzen  Çakallar konmuş peşin süre gezen  Memnun değilse düzülen ve düzen  Titreyip kendine dönmek iste sen  Duygu...', ARRAY['Türk Edebiyatı','Şiir','Siya Yok']::text[], 8.5, '{"poet":"Siya Yok","poet_slug":"siya-yok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kendine-don-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani düşler vardır ya', 'hani-dusler-vardir-ya-ziya-nizam-i4iku', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani düşler vardır ya

Aşk dolu,

Loş bir ortamda mum ışıklarında.

Dünyalar vardır ya bizde.

Umutlar vardır sana ve bana ait,

Nasıl yapsak ta kopmasak diye.

Hani sevgiler vardır ya

Aklımızdan çıkmayan

Neden sevdim deriz hep

Ama bağlanıveririz birden bire

Nedenini anlamadan

	O büyük sevgiliye.

			27.03.1999-Cumartesi

			01:15 Radyo Mavideniz Rize', 'Hani düşler vardır ya Aşk dolu, Loş bir ortamda mum ışıklarında. Dünyalar vardır ya bizde. Umutlar vardır sana ve bana ait, Nasıl yapsak ta ...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hani-dusler-vardir-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemim Sana', 'ozlemim-sana-onder-yagci-j9chl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu gün yine özlemim sana

buram buram tüten sevda

hani her gecenin nihayetinde

karanlıgın üstüne günes doğarya

ben oyum sevgılım 

her sabah pencerenden girecegim

sana doya doya sarılıp

her gece ayla geleceğim

sen karanlıktan korkarsınya 

her karanlıkta kaldgında

ışıgın olacagım senın 

hem gündüzün tüm rüyalarında', 'bu gün yine özlemim sana buram buram tüten sevda hani her gecenin nihayetinde karanlıgın üstüne günes doğarya ben oyum sevgılım  her sabah p...', ARRAY['Türk Edebiyatı','Şiir','Önder Yağcı']::text[], 8.5, '{"poet":"Önder Yağcı","poet_slug":"onder-yagci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlemim-sana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birdir Bir', 'birdir-bir-yavuz-selim-tastekne-ms852', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'birdir bir 

Bir Ne? 

BİR BİR

Bir Kaç? 

BİR TEK

Tek Ne? 

SANDAL

Nasıl San? 

NİSAN

Bahar Mı? 

DAHA VAR

Ne Kaldı? 

SON BAHAR

Başka? 

DON DA VAR

Kar da mı? 

YUKARDA

Ne Kadar? 

O ooo

''O''Harf Ne

MESAFE

Nereden? 

MAZİDEN

Nereye? 

GÜNÜMÜZE

Niçin? 

İLM İÇİN

Çin''den mi? 

YOK DİN DEN

Ne Din''den

HAK DİN''DEN

Din Nedir? 

NASİHAT

Sana mı? 

HERKESE

Ya Bana? 

YOK SANA

Kim Verir? 

BEN BİLMEM

Kim Bilir? 

''O'' BİLİR

''O'' Kimdir

RABBİ''DİR

Kimin? 

A L E M L E R İ N', 'birdir bir  Bir Ne?  BİR BİR Bir Kaç?  BİR TEK Tek Ne?  SANDAL Nasıl San?  NİSAN Bahar Mı?  DAHA VAR Ne Kaldı?  SON BAHAR Başka?  DON DA VAR...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Selim Taştekne']::text[], 8.5, '{"poet":"Yavuz Selim Taştekne","poet_slug":"yavuz-selim-tastekne","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/birdir-bir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saksı', 'saksi-ali-kilic-ugsst', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir saksıda üç gül var 

bir kımızı, bir beyaz,birde pembe 

seç sen gönlüne göre 

gerisi kalır sonsuza kadar bende 

ucu bucağı yoktu gönül behçemde 

sen gidince kaldı geriye 

bir saksılık yer               

kaldı üç çiçeklik yer

biri kırık kalbim  diğeri umutlarımız

en son çiçek benim gibi

senden sonra solup gidecek

ona toprak bulunmaz artık 

bedenim sensi susuz güzelim', 'Bir saksıda üç gül var  bir kımızı, bir beyaz,birde pembe  seç sen gönlüne göre  gerisi kalır sonsuza kadar bende  ucu bucağı yoktu gönül be...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç']::text[], 8.5, '{"poet":"Ali Kılıç","poet_slug":"ali-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/saksi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sazın isyanı', 'sazin-isyani-i-lhami-arslantas-jn6eo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haykırır

   karanlığı yırtarak 

   tellerinde 

   Sıkar 

   Namerdin alnına

Kurşun gibi… 

   Sarhoş isyanlarını

haykırır

Mazlumun feryadını

Utanç

duvarlarına

vurur kahpeliğin suratına

bir bir

lanetleyerek ihaneti

çalar başlarına kirli namuslarını

,Ondandır uluması itlerin

   sazın isyan sesine 

kulak verip dinleyin

sazımın öfkesine', 'Haykırır    karanlığı yırtarak     tellerinde     Sıkar     Namerdin alnına Kurşun gibi…     Sarhoş isyanlarını haykırır Mazlumun feryadını ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sazin-isyani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzatmalar', 'uzatmalar-funda-soylemez-3nfwl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Maç çoktan bitmeliydi aslında

Ben hala uzatmaları oynuyorum

Kendi kendimle yaptığım bir maçtı

Ve oyuncularım yorgun düştü

Sahayı terk etmek istiyorlar artık

Trafiğe karışmak ve yollarda dans etmek yeniden...

Hey hakem! Düdüğünü çal artık! 

Ne olursun! ! ! 

(Mayıs 2005)', 'Maç çoktan bitmeliydi aslında Ben hala uzatmaları oynuyorum Kendi kendimle yaptığım bir maçtı Ve oyuncularım yorgun düştü Sahayı terk etmek ...', ARRAY['Türk Edebiyatı','Şiir','Funda Söylemez']::text[], 8.5, '{"poet":"Funda Söylemez","poet_slug":"funda-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uzatmalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım şiir', 'yarim-siir-tevfik-karinca-mqatz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bensiz kalacaksın 

günaydınsız geçecek o ilk sabah

seni seviyorum diyen ses olmayacak

burnunun direği sızlayacak

hep bana verdiğin söz kulağında çınlayacak

'' senden sonra başkası olmayacak''

     özleyeceksin 

     içinden gelecek ağlamak

     tek tesellin seni seven bu adamın

     son sözünün ismini sayıklaması olacak', 'bensiz kalacaksın  günaydınsız geçecek o ilk sabah seni seviyorum diyen ses olmayacak burnunun direği sızlayacak hep bana verdiğin söz kulağ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yarim-siir-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceleri sönmeyen lanbalar', 'geceleri-sonmeyen-lanbalar-muhammet-faruk-koca-hyu2n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana sordular mı gökyüzünde asılı olan lambaları, 

Nereden söndüğünü hiç sordular mı, 

Evlerin bacalarından çıkan kara dumanlarla yükselmek, 

Mümkün olur muydu gökyüzüne, 

Gökyüzündeki yıldızlara ulaşmak kolay olur muydu söylesene, 

Hep tebessümle çıplak vücudumuzla izlerdik lambaları, 

Duygularımızı yansıtırdık onlara, 

Erişe bilir miyiz merdivenler diksek yeryüzünden gökyüzüne, 

Erişmek kolay olur muydu lambalar sönünce yaka bilmek, 

Erişe bilir miyiz kaybettiğimiz duygulara, 

Alıp o duyguları, 

Lambaların altında yine sevişe bilir miydik söylesene, 

Yeryüzünde sensizlik içinde çığlıklar içinde, 

Yine seni düşünmek lambaların altında, 

Sanki bana el sallıyormuşsun gibi, 

Onun için bu gökyüzüne ulaşa bilmek. 

(01.03.2000)', 'Sana sordular mı gökyüzünde asılı olan lambaları,  Nereden söndüğünü hiç sordular mı,  Evlerin bacalarından çıkan kara dumanlarla yükselmek,...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geceleri-sonmeyen-lanbalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-tuncay-akdeniz-5vnqk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin için ben bu, aşkı bitirdim,

Hoyrat bahçemize,daldı bu sene.

Deli oldum ben,aklımı yitirdim,

Açılan gülümüz,soldu bu sene.

Aşkımız düşmüştü,alem diline,

Beni sürgün ettin,macnun çölüne

Yaktın ocağında,kattın külüne,

Sevdamız yarıda,kaldı bu sene.

Aklıma düşende,yemez içmezdim,

İhanet olmasa,senden geçmezdim.

Yoksa ayrılığa,kefen biçmezdim,

Ayrılık vadesi,doldu bu sene.

Silmedin içinden,hırçın hırsını

İhanetin kimden aldın dersini.

Ben doğruyu yaptım,sende tersini,

Başımı dertlere,saldı bu sene.

Tuncayım düşürdün,vefasız aşka,

Sevdamın yarası,yürekte  başka.

Kerem gibi yanıp,bitseydim keşke

Acı dertler beni,buldu bu sene.', 'Senin için ben bu, aşkı bitirdim, Hoyrat bahçemize,daldı bu sene. Deli oldum ben,aklımı yitirdim, Açılan gülümüz,soldu bu sene. Aşkımız düşm...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vefasiz-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Yeşili Yapraktır Gülüm', 'gulun-yesili-yapraktir-gulum-hasan-ejderha-kx1c3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Memduh  ATALAY’a

Ninemin yüzü gibi bakar göklere

Yerlerin sultanı topraktır gülüm

Miskler suvarır dostun yüzü

Gülün yeşili yapraktır gülüm

Yerlerin sultanı topraktır gülüm.

Dosta amadedir, uçar göklerde

Atların soylusu buraktır gülüm

Taylar kanatlanır bozkırlarda

Akmıyor ırmaklar kuraktır gülüm

Atların soylusu buraktır gülüm.

Yuyup serilince güne

İpek mendil celalin yüzü

Dane dane bayraktır gülüm

Celali duydun da yanmadın mı

Yanmayan gönüller çoraktır gülüm

İpek mendil bayraktır gülüm.

Hilm sahibi yolcular revan yollara

Açınca göklere, dudakları kıpır kıpır

Elleri parlar anamın, ap-aktır gülüm

Mısralar haykırmıyorsa bir beldede

O beldenin şairleri korkaktır gülüm

Elleri parlar anamın ap-aktır gülüm.

Yürümek er işi, ateş gerektir

Yanmayınca yollar ıraktır gülüm

“Uzaktır yakındır, yakındır uzaktır”

demiş ya dost. Başka ne gerektir gülüm.', 'Memduh  ATALAY’a Ninemin yüzü gibi bakar göklere Yerlerin sultanı topraktır gülüm Miskler suvarır dostun yüzü Gülün yeşili yapraktır gülüm Y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gulun-yesili-yapraktir-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci', 'dilenci-muhammet-faruk-koca-tr74v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün garip bir duyguya kapıldı gönlüm, 

Gün ağarmıştı vakit tam dolmuş, 

Bir rüzgar esiyordu uvultuyarak, 

Ve garip bir insan, 

Çıkıyor aniden önüme, 

Elinde garip bir kutu, 

Değişik bir müzik’e eşlik eder gibi kutuyu sallıyordu, 

Gözleri gözüme aşinayla bakıyordu, 

Elimi cebimden usulca çekip, 

Ne kadar bozukluk varsa, 

Eşlik ettim onun duygularınca, 

Yırtık partısosu kır pas içinde elleri, 

Ve onun duygularının bana yansıyışı, 

Bir garip hisse kaptırdı gönlümü, 

Kulağımda garip bir fısıltı, 

Kalsana kalsana diye bir yalvarış, 

Ve istemeye istemeye o sokaktan uzanıp gidişim, 

Ve o adamın bakışlarında ki tebessüm, 

Dünyaları veriyordu sanki bana, 

Ve gece ne kadar sessiz olsuda, 

Hayat orada daha karmaşık daha başka, 

O dilencinin hayattan umduğu garip duygularca hissettiriyordu bütün insanlara, 

Onlar bu dilenciyi umursamasa da. 

(01.03.2000)', 'Bu gün garip bir duyguya kapıldı gönlüm,  Gün ağarmıştı vakit tam dolmuş,  Bir rüzgar esiyordu uvultuyarak,  Ve garip bir insan,  Çıkıyor an...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dilenci-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dal vermez bana', 'dal-vermez-bana-tuncay-akdeniz-9zj9x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fidan oldum toprağına dikildim

Kurumuş kökleri dal vermez bana

Söküldüm de bağdan bağa ekildim

Tomurcuk dalından gül vermez bana

Boşuna gezmişim ömür boyunca

Hayat bana atmış çelik bir kanca

Hiç dostum kalmadı var olmayınca

Kesmiş kısmetimi mal vermez bana

Otuz  yıldır terk etmişim köyümü

Mesken tuttum ben gurbetin elini

Gezdim sahrasını susuz çölünü

Kesilmiş mayası döl vermez bana

Tuncay bu gurbeti gezdi boşuna

Bu garip başımı koydum taşına

Yaptığın  gider mi insan hoşuna

Geri gönder dedim yol vermez bana', 'Fidan oldum toprağına dikildim Kurumuş kökleri dal vermez bana Söküldüm de bağdan bağa ekildim Tomurcuk dalından gül vermez bana Boşuna gezm...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dal-vermez-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aras nehri durmayıp, çağlayıp akar', 'aras-nehri-durmayip-caglayip-akar-halil-colak-qp9bx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aras nehri durmayıp, çağlayıp  akar

Palandökeninde şimdi yeşile doyar

Kır çiçekleri ile bezenmiş olan diyar

Erzurum’um aşığım aşığım sana

Karasu kaynağı dumlu dağından

Bereket fışkırır dört bir yanından

Derde şifa vardır her bir otundan

Erzurum’um aşığım aşığım sana

Horasan ereni Erzurum’u özledin yine

Kendi kendini dadaş dinledin yine

Yayla rüzgarın gönlünde esiyor yine

Erzurum’um aşığım aşığım sana

Halil Çolak', 'Aras nehri durmayıp, çağlayıp  akar Palandökeninde şimdi yeşile doyar Kır çiçekleri ile bezenmiş olan diyar Erzurum’um aşığım aşığım sana Ka...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aras-nehri-durmayip-caglayip-akar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gıramafon', 'giramafon-muhammet-faruk-koca-bkb72', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fatihte bir gramofon inliyor, 

Sahibinin kendi sesinden, 

Yürümek istiyorum sokaklarda, 

Yine basamıyorum ayağımı, 

Kapılacak yine gözlerim, 

Bu mekânın uğultusuyla, 

Şair sunuyor bestelerini bir bir, 

Gözlerimin önünde, 

Derin çizgiler çizilmiş sanki ellerine, 

Uhdeler düğümlenir aniden boğazıma, 

Söylemiyor şairden başkası bu şiiri, 

Ellerimden tutmuş bir kere kara kış zamanında, 

Şiirle büyüyorum bir çocuk gibi, 

Fatihteki o gramofon sesiyle. 

(06.01.2000)', 'Fatihte bir gramofon inliyor,  Sahibinin kendi sesinden,  Yürümek istiyorum sokaklarda,  Yine basamıyorum ayağımı,  Kapılacak yine gözlerim,...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/giramafon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar', 'yillar-suleyman-yavuz-1rylv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgun ve kırgınım size

Hem de çok 

Nasılda geçip gittiniz

Beni benden ettiniz

Sevgi ile bakarken gözlerim

Şimdi giden bu gençliğim 

Eski beni özlerim

Aldattınız siz de beni

Karşımda bir ayna

Söyle bana ey ayna

Her şey yalan mıydı? 

Yoksa rüyamı

Bak nasılda bitirdi 

Aldatıp ta gitti beni yıllar', 'Yorgun ve kırgınım size Hem de çok  Nasılda geçip gittiniz Beni benden ettiniz Sevgi ile bakarken gözlerim Şimdi giden bu gençliğim  Eski be...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yillar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık kalp', 'kirik-kalp-muhammet-faruk-koca-5n4u0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırdın kalbimi bir hiç uğruna, 

Kolay değil artık seni unutmak, 

Baktığım gördüğüm sevdiğim sensin, 

Her tarafta senden bir hatıra var şimdi bana. 

(19.10.1999)', 'Kırdın kalbimi bir hiç uğruna,  Kolay değil artık seni unutmak,  Baktığım gördüğüm sevdiğim sensin,  Her tarafta senden bir hatıra var şimdi...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kirik-kalp-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ağlarken', 'sen-aglarken-yunus-guzel-nv58j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'direnç duvarlarım yerle bir,

sen ağlarken…

adını gül koymuştum,

gül hüznü tanımaz

bırak,

nasır tutmuş gözlerim ağlasın

acı patlıcanı kırağı çalmaz

sevdiğin yalan söylemişti anlaşılan

yalan sığmaz ki çuvala 

aydınlatmaz karanlıkları yalan 

yalan hayatları yazmaz kitaplar

ve iz bırakmaz yalan aşklar...

“ben, doğruyu öğretmiştim yalnızca,

yalanı gerçekten ayırmak sana düşer”

desem de,

duyan olmaz sesimi

içimde kırılan bir şeylerin sesi

gözyaşlarının seline karışır…', 'direnç duvarlarım yerle bir, sen ağlarken… adını gül koymuştum, gül hüznü tanımaz bırak, nasır tutmuş gözlerim ağlasın acı patlıcanı kırağı ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-aglarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Öleceğiz', 'biz-olecegiz-nihal-gungor-nadxb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düştü karnıma iki damla sevgi,

bir yerde birleşerek.

Düştü yüreğime merakla telaş,

sevinerek.

Biliyorum,önce ne olduğunu anlamayacağız,

herşey eskisi gibi devam edecek.

Sonra midem kabul etmeyecek,

eski tadları,uğraşları.

Ama o haydut alacak günlük hasılatını.

Varlığını ele güne ispat edecek,

her geçen gün inat ederek.

Belkide bu yoldan vazgeçecek.

O zaman biz öleceğiz.

Vazgeçmezse eğer,

büyüyeceğiz onunla beraber.

Büyüdükçe hayat değişecek.

Sonra yeniden doğacağız.

O zaman biz sevinçten öleceğiz.

                         26.05.2005', 'Düştü karnıma iki damla sevgi, bir yerde birleşerek. Düştü yüreğime merakla telaş, sevinerek. Biliyorum,önce ne olduğunu anlamayacağız, herş...', ARRAY['Türk Edebiyatı','Şiir','Nihal Güngör']::text[], 8.5, '{"poet":"Nihal Güngör","poet_slug":"nihal-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/biz-olecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S u', 's-u-halil-colak-sl7ik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buhar olur çıkar göklere

Rahmet yükletir bulutlara

İlham kaynağıdır gönüllere

Her derde dermandır su.

İnsan bedenin her hücresinde

Meyvenin can veren usaresinde

Her çeşmenin kitabesinde

Kurumuş dudaklara hayat veren su

Ezelden ebede gelen çağlardan

Susuzluktan yanan çöllerden

Hakka susamış gönüllerden

Yanık yürekleri söndüren su.

Horasan ereni aslın balçıktan

Toprak su ile yoğrulmuş hamurdan

Adem babamızı yaratmış ondan.

Beş vakit namaza hazırlayan su,

HALİL ÇOLAK6.4.2005', 'Buhar olur çıkar göklere Rahmet yükletir bulutlara İlham kaynağıdır gönüllere Her derde dermandır su. İnsan bedenin her hücresinde Meyvenin ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/s-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldı', 'kaldi-halil-colak-v1m4s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Döktüğüm  yaşları mendile silmem

            Seni sevmekle yılgınlık bilmem

            İçimde kanayan hasretim bilmem

            Kalbime vurmadığın  yaramı kaldı

           Başlıyor kalbim yine feryada

           Mutlu günlerim gelince akla

          Aşk-ı muhabbet varsa darı dünyada

          Başımdan geçmedik haller mi kaldı. 

         Horasan ereniyim derdindir derdim

         Acıyla kederle yolunda erdim

        Bir yer bulsam bende giderdim.

         Gurbetten öte yerim mi kaldı.

         Halil Çolak.2005-04-08', 'Döktüğüm  yaşları mendile silmem             Seni sevmekle yılgınlık bilmem             İçimde kanayan hasretim bilmem             Kalbime v...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kaldi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Mani', 'mavi-mani-nurten-altinok-mytcx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir telaş

Aşka hüsran düşecek

Biliyorum başkası

Bana hırsız diyecek

Ne adında, sandayım

Vurgun yemiş limanım

Her şey unutulur da

Neden mavi hep kanım

Gitme desem kal desem

Bilmedin ki kalasın

Bir ömür seni sevsem 

Sen bir başka aşktasın

Yüreğimde bir telaş

Acemi çocuk gibi

Günah sayılmaz şair

Bu gönülde bu sevgi…', 'Yüreğimde bir telaş Aşka hüsran düşecek Biliyorum başkası Bana hırsız diyecek Ne adında, sandayım Vurgun yemiş limanım Her şey unutulur da N...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mavi-mani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giresun''a Doymayın', 'giresun-a-doymayin-mehmet-yilmaz-bulancakli-rfziw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Giresun''a gel Giresun''a,					

Çıkalım şu yaylalara,					

Hasretim soğuk sularına,					

Şenlikler gelir bu aylara.					

					

Enerjimiz hamsi,fındık,					

Bakın burada gaydalara,					

Yar İstanbul''dan usandık,					

Haydi çıkalım yaylalara.					

					

Giresun''da güzel havalar,					

Bakın şenlik üstüne şenlik,					

Yar öldürür beni bu havalar,					

Giresun''u candan özledik.					

					

Yaylanın kırında eğlence,					

Oynayın kızlar oynayın,					

Çalıyor bağlama,kemençe,					

Giresun''da eğlenmeye doymayın.					

								

14.02.2005-Bulancak-GİRESUN', 'Giresun''a gel Giresun''a,					 Çıkalım şu yaylalara,					 Hasretim soğuk sularına,					 Şenlikler gelir bu aylara.					 					 Enerjimiz hamsi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/giresun-a-doymayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-i-lknur-cekici-1ev01', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruhumdaki gelgitler

Hüzünle dolu

Boş gözler

Güvensiz incinen

Bu yürek

Senin eserin

Hiç çıkarsız yalansı

................................Sevdim

Karşılığın da mutsuzluğa

..............................................İtildim

Artık aşka tövbe 

.......................................................Ettim', 'Ruhumdaki gelgitler Hüzünle dolu Boş gözler Güvensiz incinen Bu yürek Senin eserin Hiç çıkarsız yalansı ................................Sevd...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdim-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-ozgur-kokturk-nno36', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutmak şimdi haykırışları

Unutmak boş bakışları

Sevdaya çağıran gizlerin

Derinliğini unutmak

Kızıllığında yanarken gözlerim şafakların

Sevgisizlik sel olur akar

Sevdasız günlerin yarınlarında

Hayaller ufuklara bakar

Zaman delirmiş, kuduruyor köpükleri

Sinsice gelir ayrılık vaktinde

Dumura uğramış hayat bezerken

Kıvrım kıvrım süzüldüğünde

Neyi arar bu yürek

Neyi kaybeder umarsızca

Kim gelir çalar kapısını

Kim gider çarparak umursuzca

Kime göre bu gitmeler, gelmeler

Sevmeler, nefretler kimin

Yudum yudum acı şerbetler

İçenler, içirenler hangi ellerin

Şiir tutsak, çıkmaz olmuş kalemden

Dizeler küskün kâğıtlara

Anlatamadım kendimi kendimden kaçarken

Anlamayanlar kayboldular sırlara…', 'Unutmak şimdi haykırışları Unutmak boş bakışları Sevdaya çağıran gizlerin Derinliğini unutmak Kızıllığında yanarken gözlerim şafakların Sevg...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unutmak-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlığınla Bayramdır', 'varliginla-bayramdir-mehmet-yilmaz-bulancakli-u6l1k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen neymişsin fındık,					

Ocağımızda aş imişsin,					

Yokluğundan yandık,					

Başımızda taç imişsin.					

					

Herkes seni ister,					

Yokluğunda ağladık,					

Varlığını artık göster,					

Umudu sana bağladık.					

					

Sen neymişsin fındık,					

Giresun’da boş uşaklar,					

İşsizlikten bunaldık,					

Perişan gelen kuşaklar.					

					

Sanayi henüz gelmemiş,					

Burada acı ondandır,					

Köylü,şehirli gülmemiş,					

Gurbete göç ondandır.					

					

Sen neymişsin fındık,					

Sana dünya hayrandır,					

Yokluğundan usandık,					

Varlığınla düğün bayramdır.					

								

14.02.2005-Bulancak-GİRESUN', 'Sen neymişsin fındık,					 Ocağımızda aş imişsin,					 Yokluğundan yandık,					 Başımızda taç imişsin.					 					 Herkes seni ister,					 Yo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/varliginla-bayramdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler', 'anneler-sair-ahrazi-94r4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anladım…anne imiş rûhumun İstanbul’u,

Anladım,gözleriymiş duyguların ilk yolu.

Sâde mîmârı değil,çehresidir kalbimin,

En muazzâm eserî sevgidir annelerin.

Görmedim böylesi nûrun böyle bir rengini,

Bir ışık huzmesidir sanki,beyaz elleri.

Annelik,kendine mahrum bir ibâdet midir? 

Ya Rab! bizden biri sandık fakat,âyet midir? 

Her gün akşam,düşünürken bu ilâhî gücü,

Sahte vicdânı taşır benliğimin hörgücü; 

Onca yıl,onca bahâneyle buluşmak için,

Nîçin ister o büyük kalbini anneliğin? 

Anladım…anne imiş terk-edilen sığınak; 

Bir demir pencereden seslenir,ağlayarak; 

Kim bilir? hangi rüyâ,hangi hayâl belli mi? 

Bekliyor,boynunu bükmüş de kim bilir,kimi! 

Ömrün en son günü evlâdını görmüş ise,

İstemez ayrılıktan,ömrüne birkaç sene.

Lâkin,insanlığı çok kere yıkan bizlerin,

Daha bir çok izi vardır,hayâsız ve derin.

Kırdık ancak,sığınırken annelik affına,

Affet! affetmeyi öğretmiştin etrâfına.

Belki bir akşamı çok gördük,hatırlanmadın,

Belki isyân için andık seni kutsî kadın.

En nihâyet,o kadim yolcu sen olmaya gör,

İlk defâ irkilmeye başlar gönül adlı nankör; 

Annesin çünki,bu nihâyetle bakmazdı o,

Hâyır,ayrılsa da hiç bir gün bırakmazdı o.

Elvedâ mıydı,selam mıydı,rüyâ mıydı? Âh! 

Hiç denir miydi,gidip gelmeyecek bir sabah.

Sen değilsin,Sana benzer biridir terk-eden! 

Ve derken annesidir,bilir,ebediyyen giden! 

* * *', 'Anladım…anne imiş rûhumun İstanbul’u, Anladım,gözleriymiş duyguların ilk yolu. Sâde mîmârı değil,çehresidir kalbimin, En muazzâm eserî sevgi...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/anneler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve sen gidiyorsun', 've-sen-gidiyorsun-ercan-eyvaz-jbzgd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve sen gidiyorsun

Alıyorum sanıyorsun her şeyini

Söküp hatıraları senden kalma izleri

Söküp atıyorum sanıp gidiyorsun

Ertelendi sürekli bu hayatta bu sevgi

Erkendi belki ama seni çok sevdi 

Ve sen gidiyorsun…

Arkana bile bakmadan

Elveda demeden  üstelik

Gidiyorsun işte bırak hadi

Gözlerimle birleştirip gözlerini

Son kez suskun suskun bakıp gidiyorsun 

Her sevgide son buluyormuş demek

Ben sevgiyide bulmuşumda sende 

Sevgin senin hep böylemi

Alıştırıp yanlız ortada koyup gtmek mi

Çekip gitmek ansızın  kolay sanıyorsun besbelli

Ve gidiyorsun işte

Garip aşk bestesi gibi yaşanılan sevgi

Adını daha koyamadığım 

Sadece ansızın diyebildiğim 

Masum sıcak gerçek tek taraflı belki

Ve gidiyorsun  işte

Bakma ardına aldırma bir şey olmamış gibi

Kalbi taş bedenin buz 

Anlamak seni öyle zormuş ki 

Seni düşünüp geçen zaman

Seni özleyip de alınan nefes

Hıçkırıklarda senin beni düşündüğünü düşünmek

Adını söylemek güle güle

Seviyorum demek seni

Acı veren inan bunlar kalbime

Sürekli hemde sürekli

Gidiyorsun işte

Gitmek istiyorsun demek git o zaman

Unutmaksa sebebin unut şimdiden

Ve sen gidiyorsun işte…', 'Ve sen gidiyorsun Alıyorum sanıyorsun her şeyini Söküp hatıraları senden kalma izleri Söküp atıyorum sanıp gidiyorsun Ertelendi sürekli bu h...', ARRAY['Türk Edebiyatı','Şiir','Ercan Eyvaz']::text[], 8.5, '{"poet":"Ercan Eyvaz","poet_slug":"ercan-eyvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ve-sen-gidiyorsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
