INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair''in Sırrı', 'sair-in-sirri-turgut-baki-dgeda', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şair 

bu gece ölür diyerek 

beklediler sabaha kadar

şair ölmedi

şair bir vasiyet bırakır mı diye düşündüler

şair gülümsedi

ne çok aşklar yaşamıştı şair

şiirlerinde hep methiyeler düzmüştü sevgiliye

kimdi bu ateşin sahibi

şairi yakan aşk kimindi

ve neden hep bir bilinmezlik denklemiydi

şiirlerdeki sevgili

gizlenen neydi

söylenen ne

sırrı neydi şairin

neden söz sevgiliye gelince 

susuyordu böyle

gün ışımış

şair hala ölmemişti

kenetlenmiş ellerinde kalem

gizemli bir tebessümle

uzaklara bakarak yatıyordu öylece

şairi yaşatan aşktır diye düşündüler

dayanamayarak merak denen iblisin 

fitnesine

aşk bohçasını açtılar şairin alelacele

kim bilir neler bırakmıştır diyerek geriye

boştu

öyleyse şair hiç mi aşk yaşamamıştı

kime niye yazmıştı bunca şiiri

diye düşünürlerken

şairle buluşuverdi '' O '' büyük sevgili..! 

(şairin dizelerinde görememişlerdi

artık göremezlerdi...)', 'şair  bu gece ölür diyerek  beklediler sabaha kadar şair ölmedi şair bir vasiyet bırakır mı diye düşündüler şair gülümsedi ne çok aşklar yaş...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sair-in-sirri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çift Hüzün Gözlerinden Miras Bana', 'bir-cift-huzun-gozlerinden-miras-bana-mehmet-lutfu-aydin-f1ewu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi uzaklardasın

Bir çift hüzün gözlerinden miras bana

İstemem, dönme sakın

Seni ben içime gömdüm, ikimizi toprağa

Unuturum sanmıştım

Düşlemekten kan çanağı gözlerim

Süzülürken göz yaşlarım kahırla 

Sırılsıklam hayallerim

Sen unutabildin mi sanki? 

Seni bana, beni sana 

Akortlamış yüce Mevlâ 

Tik tak atan kalplerimiz

Bak, çalıyor aynı telden

…

Umudum yok

Haykırışım beyhude

İçimdeki yangını söndüremez denizler

Boğuluşum girdabında hazan yüklü sellerin

Vefasızlık yüzünden

Göç etmeden dünyasına faili meçhullerin

Bu sana son seslenişim

İsterim değsin parmakların

Okşasın saçlarımı tabutumun üstünden 

Fısıldarken son defa titreyen dudakların

“Bir hoş sadâ” kalsın, senden bana hatıra

…

Karışırken topraklara bedenim

Suskun volkanlara inat

Patlatacak kabrimi aşkımın magmaları 

Gökyüzünde uçuşurken salkım saçak maytaplar

Yas tutacak yıldızlar

Ay sinecek bulutların ardına

Ve uyurken sen kollarında ihanetin 

Bir yaldızlı kelebek konacak yüreğine usulca

Ve çırpacak kanadını sessizce

Zamanın ötesinden 

İki sözcük düşecek, benden sana hatıra 

İsterim ki duy

İsterim ki unutma 

Se ni  se v i yo rum', 'Şimdi uzaklardasın Bir çift hüzün gözlerinden miras bana İstemem, dönme sakın Seni ben içime gömdüm, ikimizi toprağa Unuturum sanmıştım Düşl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-cift-huzun-gozlerinden-miras-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metal Para', 'metal-para-mehmet-lutfu-aydin-08z5d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkımız metal para

Bir yüzünde sen

Bir yüzünde ben

Ben yazıyım

Sen tura

Kim demiş sonsuz diye

Dönmüş iken sırt sırta

Bu aşk çıkmaz bahara', 'Aşkımız metal para Bir yüzünde sen Bir yüzünde ben Ben yazıyım Sen tura Kim demiş sonsuz diye Dönmüş iken sırt sırta Bu aşk çıkmaz bahara...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/metal-para-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ben Değilim', 'ben-ben-degilim-mehmet-lutfu-aydin-7t1ka', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben ben değilim

Bakmayın siz güldüğüme

Gülüşlerim sahte benim

Gülerken ben sizin için, içim ağlar kendim için 

Göz yaşlarım sahte benim

Dökülürken yanağımdan kızıl şerbet damlalar

Yankılanır arsızca içimde kahkahalar 

Ben ben değilim işte

Siz beni bilmezsiniz

İki ben var bir bende:

Bir ben varım görünen 

Bir de içimdeki ben

Dışımdaki kocamış 

Masum bir çocuk hâlâ, içimdeki gerçek ben 

Koştu aşkın peşinden

Aradı bir dert ortağı, paylaşacak gönülden

Sevdi, sevilmedi dışımdaki sanal ben

Ne kendine ne bir dosta diyebildi merhaba

İçimdeki saklı ben, tırmalıyor beynimi 

Bazen çocukça bir sevgi, bazen sevgiye hasret bir çocuk

Haykırıyor canhıraş: “Çık gel artık, nerdesin? ” 

Dedim ya, ben ben değilim; iki ben saklı bende

Kaçıyorum kendimden bulmak için kendimi 

Bir kaçak aranıyor; içinde iki ben saklı

Biri melek, biri şeytan

Ben beni ihbar ettim

Çifte ödül kazandım', 'Ben ben değilim Bakmayın siz güldüğüme Gülüşlerim sahte benim Gülerken ben sizin için, içim ağlar kendim için  Göz yaşlarım sahte benim Dökü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ben-ben-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-mehmet-lutfu-aydin-kldpt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ecel kapıyı çaldı, çıkar mısın sabaha? 

Veda et dostlarına, kapanıyor dükkânın

Az mı çileler çektin? Yalvar, yakar Allah’a

Açılsın kapıları, Cennet olsun mekânın', 'Ecel kapıyı çaldı, çıkar mısın sabaha?  Veda et dostlarına, kapanıyor dükkânın Az mı çileler çektin? Yalvar, yakar Allah’a Açılsın kapıları,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/veda-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınar', 'cinar-mehmet-lutfu-aydin-hayfy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yolumun üstünde bir ulu çınar

Bakar yükseklerden gülümseyerek

Çıkarır dallarda bir dolu çıngar

Kargalar çınarı küçümseyerek', 'Yolumun üstünde bir ulu çınar Bakar yükseklerden gülümseyerek Çıkarır dallarda bir dolu çıngar Kargalar çınarı küçümseyerek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cinar-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Korkusu', 'olum-korkusu-mehmet-lutfu-aydin-m9xaa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölümden korkulmaz, beden ölünce

Ölünce ölümü bilemezsin ki…

Ölümden kaçış yok, vaden gelince

Alnında yazanı silemezsin ki…

Eğlen, gez, hiç durma, yaşa keyfince

Ölümü dert etme, gülemezsin ki…

Azrail dost olur, güzel sevince 

Sarılır dostuna, ölemezsin ki…', 'Ölümden korkulmaz, beden ölünce Ölünce ölümü bilemezsin ki… Ölümden kaçış yok, vaden gelince Alnında yazanı silemezsin ki… Eğlen, gez, hiç d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olum-korkusu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinledim..', 'dinledim-sila-nur-koken-fusjg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözümün içine

baka baka

yalan söylediler benim

Onlar bu yalanları

söylerken mutluydular

iyiydiler...

Dinledim.

İnanmadan...

(8 Temmuz 2004)', 'Gözümün içine baka baka yalan söylediler benim Onlar bu yalanları söylerken mutluydular iyiydiler... Dinledim. İnanmadan... (8 Temmuz 2004)...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dinledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoktun..', 'sen-yoktun-sila-nur-koken-llnq0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne çok sevinçlerim

ne çok kederlerim

oldu sen yokken

içimi taşıran

anlatılası

dilimin ucuna kadar geldiler 

Ama yüreğimde tutuklu kaldı

kelimeler

sen yoktun

dinleyecek yoktu

Sustum..

(18 mayıs 2005)', 'Ne çok sevinçlerim ne çok kederlerim oldu sen yokken içimi taşıran anlatılası dilimin ucuna kadar geldiler  Ama yüreğimde tutuklu kaldı keli...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-yoktun-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-birsen-ates-3z3iy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir iz var

hala yüreğimde

sana dair

atamadığım

şiir olup düşüyorsun

ya geceme

gecelerimde

manolya kokusu

a ş k

a ş k ı m

sensizlik 

ah sensizlik

büyüyor içimde

yine gecemdesin

sessiz çığlıklarım

duyuyor musun 

geleceksen gel artık

bak yoksa 

yoksa

unutacak artık

bu yürek seni', 'bir iz var hala yüreğimde sana dair atamadığım şiir olup düşüyorsun ya geceme gecelerimde manolya kokusu a ş k a ş k ı m sensizlik  ah sensi...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aska-dair-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderme..', 'gonderme-sila-nur-koken-enzfr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç kere dedim sana

martıları takma peşime

yoksa onları da 

götürürüm

yokluğuma

martısız kalır

şehir

Takma martıları peşime

bensizliğe gelirler

yalnız kalır

deniz

ağlar dalgalarca

dayanamaz

düşer yollara

o da gelir peşimizden

bu kez

denizsiz kalır

şehir

Kıyamam

ne şehre ne denize

gönderme martıları

peşimden

gönderme...

(27 Mayıs 2005)', 'Kaç kere dedim sana martıları takma peşime yoksa onları da  götürürüm yokluğuma martısız kalır şehir Takma martıları peşime bensizliğe gelir...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonderme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aştım...', 'astim-sila-nur-koken-a09b1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine birdenbire

kızıl kayalar yuvarlandı

dün gece üzerime üzerime

ayaklarımın dibine düşüp

kızıl kum tanecikleri oldular

Kayalar geldikçe

tanecikler yükseldikçe

boğazıma dayandıkça

soluğum kesildikçe

gayret ettim

savundum kendimi

tuttum gözyaşlarımı 

içime gömdüm

yavaş yavaş

an be an

dönüştüm

bir kaktüs çiçeğine

Aştım kendimi

kumlara yar oldum..

(2005)', 'Yine birdenbire kızıl kayalar yuvarlandı dün gece üzerime üzerime ayaklarımın dibine düşüp kızıl kum tanecikleri oldular Kayalar geldikçe ta...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/astim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz..', 'giz-sila-nur-koken-w8j7x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öleceğimi bile bile

herkesten saklıyorum

içimde bir giz bu

paylaşmadığım

Henüz kimse bilmiyor

ama

belki veda bile edemeden

belki ben bile anlayamadan

gidivereceğim

Kim bilir

belki de aylar sürecek vedalaşmam

göz göre göre 

hep bir umutla bekleyerek

bir sonraki sabahı

belki yeni bir baharı

belki de sonbaharı...

Ama 

öleceğim bir gün

biliyorum

kimseye

söylemiyorum..

(10 Mayıs 2005)', 'Öleceğimi bile bile herkesten saklıyorum içimde bir giz bu paylaşmadığım Henüz kimse bilmiyor ama belki veda bile edemeden belki ben bile an...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/giz-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen hiç ırmakların dilinden ağladın mı Almira?', 'sen-hic-irmaklarin-dilinden-agladin-mi-almira-nuri-can-6amfd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen hiç ırmakların dilinden ağladın mı? 

Almira

menekşe gözlü kız

çizdin mi sevdasını bulutlara rüzgarın

hayatın isyanına dokunup titredi mi yüreğin...

 yedirdin mi yaban kuşlarına gözlerini çaresiz? 

kalbinden hiç nefret ettin mi? 

laanet  okudun mu gözlerine gördükleri karşısında? 

Gelincikler

hep boynu bükük mü bu şehirde

hep böyle is mi kokar perdeler? 

salkım söğütler hep ağlar mı nazlı nazlı

hep böyle küskün mü baharlar? 

Sözcükler yeter mi? 

bir sevdayı anlamaya, anlatmaya

İnsanın dili sevgice değilse

nasıl anlatılır

nasıl anlaşılır

donmuş duygularla sevda

“Anlat! ” diyorsun

Nasıl anlatırım Almira

sözcükler yeter mi

bir sevdayı

anlamaya

anlatmaya

dil yeter mi? 

Sen sevdalandın mı hiç? 

gökteki kuşa

yerdeki suya

annesiz bir çocuğun gözlerindeki acıya

oğlunu yitirmiş bir babanın yüzüne

bakıp ağladın mı Almira? 

bakışlarını bağışladın mı bir amanın gözlerine? 

Ormanlarda kuşlarla

denizlerde balıklarla

gökyüzünde bulutlarla

konuştun mu hiç? 

umudun en şefkatli kucağında

verdin mi umudunu umutsuz kalmışlara? 

Bilir misin? 

akşam evine ekmek götüremeyen

işsiz bir babanın ezikliğini

hapishanede tütünü bitmiş bir mahkumun hüznünü

ırzına geçilmiş bir kadının çaresizliğini

duydun mu hiç yüreğinde? 

Sen kelebeklerin,

sen çiçeklerin,

özğürlüğün dilince konuştun mu hiç? 

kinden, nefretten,düşmanlıktan uzak

dostluk ve kardeşlik dilince

konuştun mu Almira? 

ırmakların dilinden ağladın mı hiç? 

Yaşam

bir oyundur Almira

bir filmde bir rol

maskeli bir balonun

önceden hazırlanmış

tekstleridir elimizde okuruz

aptalca, sahtekarca ve derinliksiz

Sevda

kardeşlikle bütünleşmemişse

beslenmemişse dostlukla

tüm kaygılardan uzak

savaş ve düşmanlıklardan uzak

özgürlük ve dostluk üzerine kurulmamışsa

sevda, sevda değildir Almira

Sevda, sevda demekse

ve

sevdan sevdama denkse

işte o zaman

işte o zaman

işte o zaman

sevdan, sevdamdır Almira

kaygısız, yalansız ve içten

Nuri Can

www.nurican.com', 'Sen hiç ırmakların dilinden ağladın mı?  Almira menekşe gözlü kız çizdin mi sevdasını bulutlara rüzgarın hayatın isyanına dokunup titredi mi...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/sen-hic-irmaklarin-dilinden-agladin-mi-almira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Almira', 'almira-nuri-can-xq3tb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelincikler 

hep boynu bükük müdür bu şehirde? 

hep ağlar mı salkım söğütler? 

sözcükler yeter mi

bir sevdayı anlamaya, anlatmaya? 

gök gözlü kız

İnsanın konuştuğu dil

sevdaca değilse

nasıl anlatılır

nasıl anlaşılır

donmuş duygularla sevda

“anlat! ” diyorsun

benim konuştuğum dil

sevdacadır

sevda ise kalp dilidir

nasıl anlatırım mariaaa

sözcükler yeter mi 

bir sevdayı

anlamaya

anlatmaya

dil yeter mi? 

sevda dili sevdacadır 

sevda çekenler bilir ancak

mariaaa

sen hiç sevdalandın mı

gökteki kuşa 

yerdeki suya

annesiz bir çocuğun 

gözlerindeki acıya

oğlunu yitirmiş bir anneye 

bakıp ağladın mı hiç? 

ormanlarda kuşlarla

denizlerde balıklarla

gökyüzünde bulutlarla

konuştun mu hiç? 

bilir misin? 

akşam evine ekmek götüremeyen 

işsiz bir babanın ezikliğini

tütünü bitmiş bir mahkumu hapishanede

ırzına geçilmiş bir kadının acısını

duydun mu hiç yüreğinde? 

ben seninle ancak 

sevda dilince konuşurum 

konuşursam mariaaa

kelebeklerin dilince 

çiçeklerin dilince

özğürlüğün dilince 

kinden düşmanlıktan uzak

dostluk ve kardeşlik dilince

sen ırmakların dilinden 

ağladın mı hiç mariaaa? 

yaşam

bir oyundur mariaaa

bir filmde bir rol

maskeli bir balonun

önceden hazırlanmış

tekstleridir elimizde

okuruz

aptalca, sahtekarca ve derinliksiz

sevda 

kardeşlikle bütünleşmemişse

dostlukla bütünleşmemişse 

tüm kaygılardan uzak

savaş ve düşmanlıklardan uzak

özgürlük ve dostluk üzerine kurulmamışsa

sevda değildir 

sevda, sevda demekse

ve 

sevdan sevdaya denkse

işte o zaman

sevda, sevdadır mariaaa 

kaygısız, yalansız ve içten', 'Gelincikler  hep boynu bükük müdür bu şehirde?  hep ağlar mı salkım söğütler?  sözcükler yeter mi bir sevdayı anlamaya, anlatmaya?  gök gözl...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/kalp-dili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terimler Sözlüğü....?', 'terimler-sozlugu-musfik-saltik-prpfc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vefa: İstanbul ilinde bozasıyla meşhur  bir semt.

Dost: Nesli tükenmiş bir insan türü.

Dürüst: Çalıştığı her ortamda herkesin  başına iş açan zararlı insan türü. 

Çalışkan: Aynı bedel karşılığında iki kat iş yapan bir aptal türü.

Tembel: Tanrının lütfettiği  bedene eziyet etmeyen insan.

Namuslu: Ömür boyu sürünmeye mahkum, nesli tükenmekte olan bir insan 

                  türü.

Sadık: Aynı insanla bir ömür geçirmeyi ilke edinmiş, pasif insan türü.

Vatansever: Globalleşme karşıtı geri kalmış insan türü.

Şeref: Fenerbahçeli eski bir futbolcu 

Hırsız: Serbest girişimci.

Dolandırıcı:  Zekâsıyla başarıya ulaşan girişimci.

Katil: Nüfus plânlama görevlisi.

Dönek: Değişime süratli uyum gösterebilen insan.

Nankör: Son kullanma sürelerine önem veren bilinçli  tüketici.

Gurursuz: Gereksiz duygulardan arınmış insan.

Duyarsız: Tanrının takdirine karışmayan  insan.

Saygısız: İnsanların eşitliğine inanan insan.

İnsafsız: Duygularına hakim olabilen güçlü insan.

                                                                Mayıs 2005', 'Vefa: İstanbul ilinde bozasıyla meşhur  bir semt. Dost: Nesli tükenmiş bir insan türü. Dürüst: Çalıştığı her ortamda herkesin  başına iş aça...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/terimler-sozlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'FaRk EtMeZ', 'fark-etmez-kerime-kaya-ms9q0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum demek, yetmez

  Yabancı gibi duruyorsan, yanımda

  Gözlerin, gözlerimde değilse

  Değilse, ellerim ellerinde

  Seni seviyorum de istersen.

  fark etmez.

Seni seviyorum demek de yetmez

  Gözlerin, bakışların demeli bunu

  Titrek dudakların demeli.

....

Bir ateş varsa başında

  Bir bulut gibi kabarıyorsa,

  y ü r e ğ i n.

Seni seviyorum de istersen.

  fark etmez.', 'Seni seviyorum demek, yetmez   Yabancı gibi duruyorsan, yanımda   Gözlerin, gözlerimde değilse   Değilse, ellerim ellerinde   Seni seviyorum...', ARRAY['Türk Edebiyatı','Şiir','Kerime Kaya']::text[], 8.5, '{"poet":"Kerime Kaya","poet_slug":"kerime-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/fark-etmez-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrep', 'akrep-arif-emrah-toyoglu-s71n3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'en çok ta sendin yatsıyı toprağa düşüren

dilindeki gecekondu tarzı bir bıçaklama ile

ve belkide seni en iyi yapan

olur olmadık yerde

geceleri

hikayenin açık saçık tarihini

gürültülü bir şekilde yatsımandı...

nem değil bazen

kuraklık acıtıyor susmam gerektiğini

sana anlatcak en fazla şeyi olan

benim zaten

ve senin neden

yelkovana duyduğun kıskançlığı

zamana bıraktığını anlamış değilim..

sadece susamıyorum..

belkide

çoğunun yaptığıda 

anlaşılmamıştı diyeceksin,

ama benim sana anlatmam gereken

senin ıslaklığın değil

sadece basmakalıp sözlerde

kıyasıya birikmen..

oysaki ne bir mitozdu yaptığımız

nede bir birleşmek..

biz basbaya soluğumuzu öpüyorduk...

tadına varmak demiyeceğim bukez ama

adına saymak sonsuzluğu

belkide bitiren şey olacaktı..

aklıma geleni sabaha kadar sevişmem

ben hep gecedesin diyorum..

ve belkide bir gün

kafama takacağım sessizliği

akşamdan sonraya

hep seninle kalacağım...', 'en çok ta sendin yatsıyı toprağa düşüren dilindeki gecekondu tarzı bir bıçaklama ile ve belkide seni en iyi yapan olur olmadık yerde geceler...', ARRAY['Türk Edebiyatı','Şiir','Arif Emrah Toyoğlu']::text[], 8.5, '{"poet":"Arif Emrah Toyoğlu","poet_slug":"arif-emrah-toyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/akrep-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-uşağum 103.', 'a-usagum-103-mikdat-bal-277mn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uşağum 103.

Şerre sabır şerre rıza demektir

Titre, kükre, kendine gel, uşağum!

Bilinçlenmek, cihat, gaza demektir

Titre, kükre, kendine dön, uşağum!

Türk’ün, Türk’ten başka dostu olamaz

Domuz gönü, namaz postu olamaz

Bu cenk çetin, ayak üstü olamaz

Titre, kükre, kendine dön uşağum!

Kanma sakın, asla hiç bir yalana

Hele, hele, düşmanla bir olana

Fırsat verme bu milleti yolana

Titre, kükre, kendine dön, uşağum!

Üç beş sülük, üç beş tane asalak

Bir kaç gafil, birkaç satılmış salak

Dünya gelse bizi edemez helak

Titre, kükre, kendine dön, uşağum!

Vatan bizim, toprak bizim, şan bizim

Şehit bizim, gazi bizim, kan bizim

Uyanacak, dirilecek an bizim

Titre, kükre, kendine dön, uşağum!

Alnın açık, kafan dimdik, ilerle

Hadi durma ileri çık, ilerle

Şu gaflet otelini yık, ilerle

Titre, kükre, kendine dön, uşağum!

Sen varsın ya, isterse dünya gelsin

Eğer Türk’sen sen dünya ya bedelsin

Mikdadi der gafiller böyle bilsin

Titre, kükre, kendine dön, uşağum!

Şair Mikdat Bal', 'Uşağum 103. Şerre sabır şerre rıza demektir Titre, kükre, kendine gel, uşağum! Bilinçlenmek, cihat, gaza demektir Titre, kükre, kendine dön,...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dursun-elmas-in-sabir-mi-kaldi-siirine-nazire-ileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik Bebeğime.', 'minik-bebegime-musfik-saltik-11ivl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geleceğini öğrenince dünyalar benim olmuştu.

Bilsen beklemek ne zor geliyordu.

Yavaş yavaş büyüdüğünü görmek

Varlığını hissedip sana el sürememek

Ne zoruma giderdi bir bilsen Sadoş bebek.

Hiç aklıma gelmezdi o güne dek

Bana bu kadar keyif vereceği 

Annenin karnına kulağımı yaslayıp

Kalp atışlarını dinlemek.

Nasıl mutlu eder bilir misin insanı

Doğmamış çocuğundan 

Yüzüne tekme yemek.

Doğduğun gün dün gibi aklımda.

İşten izin alıp hastaneye koşuşum

Onca bekleyişin ardından 

Sana kavuşuşum. 

Kızın oldu dediğinde annem

Sevinçten havalara uçuşum.

Sonra o kâbus gibi geçen bir hafta

Ellerimden kayıp gidişin 

Sonra geri gelişin.

Eve döndüğümüzde 

Sabahlara kadar başında

Korkulu bekleyişim.

İlk ağlayışını duymanın  verdiği huzur.

İlk gülüşünün yüreğime doldurduğu  mutluluk.

Göğsüme yatırıp saçını koklayışım

Annenle birlikte seni ilk yıkayışım. 

Sarı tulumunu giyip

Melek gibi uyuyuşun

Hep gülerek uyanışın

İlk emekleyişin

İlk ayağa kalkışın

İlk kaşık tutup

Mama yiyişin

Bardaktan ilk su içişin 

Yıllar ne çabuk geçti be kızım.

Artık   güzel bir genç kızsın

Bu da yetmezmiş  gibi 

Fena halde  aşıksın.

Çırpınışım boşuna

Yuvadan uçacaksın

Doğal olan bu ama

Gel de anlat babana

Artık yatarken sarı tulumunu giymiyorsun

Ama olsun  halâ bebek gibi uyuyorsun.

İkna edemez beni hiç kimse büyüdüğüne

Boyunun boyuma eriştiğine

Kim ne derse desin 

Sen halâ benim

O minik bebeğimsin

                                   26 Mayıs 2005 

                                     Saat 04.18', 'Geleceğini öğrenince dünyalar benim olmuştu. Bilsen beklemek ne zor geliyordu. Yavaş yavaş büyüdüğünü görmek Varlığını hissedip sana el süre...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/minik-bebegime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
