INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güvercin Olayım Pencerende', 'bir-guvercin-olayim-pencerende-huseyin-erdogan-4z2a1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'iyi ki sevmişim seni

yüreğim sıcacık şimdi

ne iyi etmişim de

aylarca peşinde gezmişim

inan yorgunluğum gitti

ben sevgisiz yaşayamazdım ki

sevdam benim herşeyimdi

gözlerim her bakışımda

çiçekler açar geçtiğin yollarda

senden yana 

yüzümü her dönüşümde

bahar renklenir bahçelerde

ellerinle bir bir dokun güllere

bazılarına benim adımı ver

onları sev benim yerime

kuşlar hiç gelir mi pencerene? 

onun birini iyice belle

her gelişinde ben diye

ona sevgiyle gülümse

ömrümce

çiçekler olayım bahçende

bir güvercin olayım pencerende

inan mutluluğu buldum sende

ne olur bana hiç yüz çevirme

                         27.05.2005', 'iyi ki sevmişim seni yüreğim sıcacık şimdi ne iyi etmişim de aylarca peşinde gezmişim inan yorgunluğum gitti ben sevgisiz yaşayamazdım ki se...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-guvercin-olayim-pencerende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Diye', 'canim-diye-ziya-nizam-fnu91', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canım diye

Sarılmak istedim boynuna.

Eksikliğimi doldurmanı istedim

Üstün kararlılığınla.

Sen bilirsin

En doğrusunu, en güzelini.

O yüzden yanımda olmanı istedim.

Canım diye

Sarılmak istedim boynuna

Canımdan bir parça ol istedim.

			27.01.1998-Salı

			15:54 Çerkezköy', 'Canım diye Sarılmak istedim boynuna. Eksikliğimi doldurmanı istedim Üstün kararlılığınla. Sen bilirsin En doğrusunu, en güzelini. O yüzden y...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/canim-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesine', 'sesine-ziya-nizam-4r1ch', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok sesler duydum

Kimi; soğuk, buzlar misali

En neşeli anımda

Tüm dünyamı karartabilecek gibi

Öyle karamsar, öyle yıkık.

Çok sesler duydum

Kimi; ateşten bir parça sanki.

Alevli bir ok gibi

Kalbe saplanıp

Hiç çıkmayan sesler duydum.

Çok sesler duydum

Hep bir çocukluk taşıyan.

Masum alabildiğine

Onlara güvenmemek,inanmamak

Elinde değil insanın.

Çok sesler duydum

Her haykırışında dünyalar vaat eden.

Gel diye çağıran

Varı yoğu önüne sererim diyen

Öyle güçlü sesler duydum.

Sonra birden sesini duydum.

Öyle neşeli, öyle candandı ki

Benzemiyordu hiçbir sese.

Sanki benim sesimdi o.

İçten kabullenebildiğim bir sesti.

Hep bir huzur

Hep bir mutluluk yayıyor etrafına.

Seni almaya geldim

Koş kollarıma diyor.

Öyle yüce bir seksi bu.

Kapılmamak elde değil ona

Ömürler boyu dinlenesi bir ses

O senin sesin.

			27.01.1998-Salı

			16:16 Çerkezköy', 'Çok sesler duydum Kimi; soğuk, buzlar misali En neşeli anımda Tüm dünyamı karartabilecek gibi Öyle karamsar, öyle yıkık. Çok sesler duydum K...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersem Bir Gün Bildiğin Diyarlardan', 'gidersem-bir-gun-bildigin-diyarlardan-ziya-nizam-m5nfw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidersem bir gün bildiğin diyarlardan

Bil ki özlemlerim sana hasret kalır.

Kalırsam sensiz yalnızlıklarda

İçime attığım haykırışlarım kalır.

Yokluğun doldurur kalbimi.

Ellerimde hayalin kalır.

Sana bir türlü anlatamadığım ilgim

Büyür de gönlümde

Aşarsa benliğimi

Anla ki o anda

Senin yerine sensizliğe sarılıyorum.

Baharın habercisi gözlerin

Uzak kalırsa benden

Bil ki küsmüşüm tüm baharlara...

O zaman beklemem artık,

Doğan güneşin yakınlığını.

Kurumuş bir toprağın suya hasreti gibi

Hasretim bende sana.

Ne olur

Sana açılan kollarımı 

Kimsesiz bırakma.

			17.01.1998-Cumartesi

			20:17 Flamingo Cafe Çerkezköy', 'Gidersem bir gün bildiğin diyarlardan Bil ki özlemlerim sana hasret kalır. Kalırsam sensiz yalnızlıklarda İçime attığım haykırışlarım kalır....', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gidersem-bir-gun-bildigin-diyarlardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu Cennettir', 'anadolu-cennettir-bekir-gedikoglu-j3qpj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Müzikle hastalığı gideren bir Milletiz

Azıcık düşünürsek bak nelere kadiriz

Beşerin dertlerini ancak biz gideririz

Tarihi okumakla gerçeği öğreniriz

Ruhu hasta olanlar hiçbir yola gidemez

Büyük problemlerde bir çözüm üretemez

Tüm toplum böyle ise düşman dahi gerekmez

Düşmana da gerek yok bu toplum üreyemez

Aman dileyenlere hiç kılıç çekmemişiz

Bir şey istendiğinde hiç ikiletmemmişiz

Bu er meydanlarında rakibi hep sermişiz 

Kalleş olan insanı toplumu sevmemişiz

Anadolu cennettir biz meleği oluruz

Kirletecek var ise Allah için koruruz

Yediden yetmişine hepimiz onurluyuz

Yurduma yan bakanın biz canını okuruz

Ankara 26 Mayıs 2005', 'Müzikle hastalığı gideren bir Milletiz Azıcık düşünürsek bak nelere kadiriz Beşerin dertlerini ancak biz gideririz Tarihi okumakla gerçeği ö...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anadolu-cennettir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-! - Gittin Ben de Öldüm', 'gittin-ben-de-oldum-tulay-sustam-1ipis', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gittin! ...

kimliği belirsiz bir yalnızlığa bıraktın beni

yokluğunda anladım kim olduğumu

aşk tarlasına; 

seni ektim, kendimi biçtim.

aşk denizinde; 

bir başıma yüzmeyi öğrendim.

öğrendim

öğrenmesine de...

ne gariptir ki! ...

gözyaşımda boğuldum

gittiğinde her şeyin biteceğini sandın

ben aşka; sen gidince susadım...

./.

gittin! ...

gözyaşları döktüm

yüreğimdeki bir avuç toprağa

İstanbul''un mavi gözleri kapandı senden sonra

gece üç-beş nöbetlerimde

yağmurlar yağdı

el ele dolaştığımız sokaklara

hangi yana baksam

hayalin doluyordu gözbebeklerime

hangi taşı kaldırsam 

altından sen çıkıyordun

gittiğin gün! ...

geceyi; gözlerinin rengine boyadım

senden sonra,

gündüzün yüzünü hiç görmedim

ve gündüzü seni özlediğim kadar özlemedim

./..

gittin! ...

et, tırnaktan ayrıldı

kanım çekildi damarlarımdan

ömrün yarısına ramak kala

birden bire durdu

-aşka çalan- yürek saatim

ne 

zaman geçti senden sonra

ne de

adam gibi bir aşk uğradı yüreğime

gittiğin de! ...

götürdün bendeki her şeyi de...

ben -aşk- yaşımı seninle doldurdum

şimdi -hayattan- gün alıyorum

./...

gittin! ...

dizlerime kadar battım hayatın içine...

yüreğim buz kesti

ellerim ısınmadı senden sonra

gittiğin gün özledim buselerini

ellerin saçlarımı toplardı 

bir buse, bir buse daha kondururdun

boynumda ki ben''e...

buz gibi nefesin

ateş topu olurdu boynumdayken

rüzgâr; 

nefesinin yerini almak isterdi de...

ellerimle kapatırdım boynumda ki ben''i...

senden başkası buse kondurmasın diye! ...

anlasana! ...

tenin değildi tenimden ayrılan

önce serçe parmağın ayrıldı saç tellerimden

o günden beri ellerim gitmedi saçlarıma

./....

gittin! ...

hiç düşünmedin

senden sonra ne olacağımı

bir kez olsun aklına getirmedin beni

ne yer, ne içerdim sensiz...

söyle! ...

söner miydi yüreğimde ki ateş

-nisan yağmurlarıyla-

sensiz,

bir lokma geçer miydi boğazımdan? 

çayım azalır mıydı? 

bardağıma dudağın değmeyince...

sigaram biter miydi? 

sen bir nefes çekmeyince...

yaz çocuğu! ...

bıraktın beni mayıs''ın ortasında çırılçıplak

bir kez olsun düşünmedin

seni canından çok seven bu kış çocuğunu...

senden miras kaldı bana / dizelerim

ben senin şairin oldum, sende benim şiirlerim...

./.....

gittin! ...

bu şehrin altını üstüne getirdim

demir atmadığım iskele

geçmediğim sokak kalmadı

ne pahasına olursa olsun,

bulacaktım seni...

nefes nefese kaldım,

el ayak çekilince...

dermanım kalmamıştı

güneş batıp, perdeler kapanınca...

yıldızlardan fallar açtım

''mutlaka onu bulacağım'' diye...

her gün bu umutla yaşadım

her güneş doğduğunda 

bende senin aşkını doğurdum

-yeni bir güne-

baktığım hiçbir yerde bulamadım seni

sanki yer yarıldı da sen içine girmiştin

kime sorsam; 

görmemişlerdi seni benden sonra

bilse bilse bir martılar bilirdi

gizlendiğin yeri...

el ettim, avuçlarıma kondular

bir yüreğimin sesini dinlediler

bir de yanağımdan süzülen yaşlara baktılar

sustular, sustular...

sonra konuştular

o günden sonra

hiç gitmedi çığlıkları kulaklarımdan

kış çocuğu; 

senin ''yaz çoçuğu kara-toprak oldu'' dediler...

usulca avuçlarımdan uçup gittiler

sustum, sustum, sustum...

ne tuhaf değil mi? 

o gün anladım beni ne kadar çok sevdiğini...

kara - tenim

toprak - gözlerim

yâr, ah yâr sen benden gidip bana gelmişsin...

yoksun! ...

yokluğuna lânet olsun...

sensiz; anıların gölgesinde güneşleniyorum

tenimde esmer gecelerin gölgesi...

./......

gittin! ...

sen; bendeki maviyi öldürdün...

mavi kaldı, sen öldün...

senden sonra ben öldüm...', 'gittin! ... kimliği belirsiz bir yalnızlığa bıraktın beni yokluğunda anladım kim olduğumu aşk tarlasına;  seni ektim, kendimi biçtim. aşk de...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":133,"source_url":"https://www.antoloji.com/gittin-ben-de-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Sonram', 'bir-gun-sonram-ali-gencay-qdoo8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir kez daha aştı güneş tepemden

biraz daha yaşlandım, derinden

göz kapaklarıma çizdiğim şafak

atmak üzere gün dönmeden

kırık bacağıyla bir sandalye

çıkardığım urbaları kaldıramaz halde

şimdi yine yalnızlığa soyunacağım

yine üşüyeceğim yokluğunla

ezbere bildiğim tüm şarkıları

dolayacağım dilime

bak yine hüzün buldu beni

oysa ne kadar yakışırdı 

gülünce dudakların, açan karanfille

yırtıyorum sayfayı orta yerinden

kırıyorum kalemimi belinden

oysa acı çekiyorum kime ne

yıldızları saydım onlarda bitti

şimdi saçlarında sıra yastığıma dökülen 

sen geldiğinde aynı yerde

gittiğinden beri silkelemedim bile

üşüyorum sevgilim

bacaklarımda sıtmadan beter titreme

en son paramla aldığım güzüne

yakacak pabucum kalmadı

sığındım kedi gibi yanmasa da ta dibine

uyuyacağım gözlerimde ağır gece

uyanacağım güneş tenime değince

üşüyorum sevgilim

yüreğimde hayaller sensizce

yıkılıyor hayat yerle bir, zelzele', 'bir kez daha aştı güneş tepemden biraz daha yaşlandım, derinden göz kapaklarıma çizdiğim şafak atmak üzere gün dönmeden kırık bacağıyla bir ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-gun-sonram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgündeyim Şimdi', 'surgundeyim-simdi-turhan-toy-q5ngu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'talan, aklımın en ücra köşelerinde

acziyetim, kitabelere düşmüş

silinen, can haritamdı tufanlarda 

kovulmuştum yürek cennetlerinden

ruhum çırılçıplak kabuğu kırılmış

arzın dışına ötelenmekte

firkat kelepçesi ayaklarıma vurulmuş

sürgündeyim şimdi.

rüzgârların kanadına astım

hazan kuşunun feryadını

güneşe hasret iklimleri

yük katarlarıyla aştım

nafileydi son nefes çırpınışları

tufan tortularının altında

canlarım bir bir damarlarımdan çekilirken

telsiz anonsları koro halinde

adım yasaklılar listesinde

yüreğim sınırlar ötesinde

sürgündeyim şimdi.

bu kaçıncı kovuluşun cenneti saymadığımızda

bu kaçıncı katlin Habil''i saymadığımızda

bu kaçıncı tufanın Nuh''u saymadığımızda

bu kaçıncı teslimiyetin İbrahim''i saymadığımızda

bu kaçıncı hicretin Medine''yi saymadığımızda

bu kaçıncı firkatin Leyla''yı saymadığımızda

ey yüreğim 

sulansın gülistan gözyaşlarınla

kapanan kapıların ardında

sürgündeyim şimdi.

kaç kıta kaç ülke dolaştım

tüm evreni sabrımla aştım

bulutlarda yıkandım 

göçmen kuşlara yoldaş oldum

sürgün sayılmadı da

bir yüreğe 

bir göze 

zehirlerle kutsanmış bir söze

mahkûm olup 

sınır dışı edilerek

sürgündeyim şimdi.

dikenli yollarda yürümek

sevda güllerine basmamak içindir

acısı en kuytu köşelerini yaksa da

yürekten yüreğe aksa da

aşk tek kişiliktir 

ey sevgili

hiç bir karşılık beklemeden

sevdamı yüreğime koyuyorum

ceylanların göz yaşıyla suladığı

nergisleri topluyorum

ayın doğduğu yerde

sürgündeyim şimdi.

şiirlerim ve diğer edebi metinlerime turhantoy.com dan ulaşabilirsiniz', 'talan, aklımın en ücra köşelerinde acziyetim, kitabelere düşmüş silinen, can haritamdı tufanlarda  kovulmuştum yürek cennetlerinden ruhum çı...', ARRAY['Türk Edebiyatı','Şiir','Turhan Toy']::text[], 8.5, '{"poet":"Turhan Toy","poet_slug":"turhan-toy","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/surgundeyim-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Yavrucuğum', 'sevgili-yavrucugum-rifki-kaymaz-fv02q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlümde altın taçsın, 

	Sen gül ki güller açsın, 

	Gül yüzün güller saçsın, 

	Sevgili yavrucuğum.', 'Gönlümde altın taçsın,  	Sen gül ki güller açsın,  	Gül yüzün güller saçsın,  	Sevgili yavrucuğum....', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgili-yavrucugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostiş-1', 'akrostis-1-hatem-kardesler-vwf6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elveda sevgiye,

Lambanın titrek ışığında,

Var olan şiire elveda…

Elveda bana tutulan ışığa,

Durmadan O’nu arayan ve

Arzulayan gönüle elveda…', 'Elveda sevgiye, Lambanın titrek ışığında, Var olan şiire elveda… Elveda bana tutulan ışığa, Durmadan O’nu arayan ve Arzulayan gönüle elveda…...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/akrostis-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhların tarifi yapılır mı?', 'ruhlarin-tarifi-yapilir-mi-caglar-asik-bz8si', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şöyle bir düşünün de cevap verin banada.

Tanıdığınız insanların ruhlarını tarif edebilir misiniz? 

Ruh nasıl bir şeydir? Tarifi nedir sizce? 

Elle tutulup, gözle görünmeyen, tadı ve kokusu olmayan bir şey.

Ama aynı zamanda karşınızdaki kişinin bedeninde gizli.

Bence, O cevher çıkardığı ürünlerle tanınıp anlaşılır.

Verdiğiniz kararlar, yaptığınız işlerdir ruhunuza şekil veren.

Bunlardır sizi karşınızdakine etki ettiren, özünüzü belirleyen.

Gül dikensiz olamaz ise, ruhta sevgisiz duramaz.

Zorlu dikenleri aşıp gülü koklayabilmektir asıl olay. 

Ruhunun derininde O vardır herkesin özünde.

Kaldır bu perdeleri, aş bütün dikenleri, doyasıya izle sende Sevdiğini.

Güç gelirse bunlar sana, asla Ruhuna ulaşamazsın.

Sen zaten sende değil, gerçekte hep oradasın.

Kaybolup yitmek istemiyorsan, sende bul içindeki özü.

Coşsun ruhun bulunca içindeki O yüceliği.

(İstanbul – 12.04.2005)', 'Şöyle bir düşünün de cevap verin banada. Tanıdığınız insanların ruhlarını tarif edebilir misiniz?  Ruh nasıl bir şeydir? Tarifi nedir sizce?...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ruhlarin-tarifi-yapilir-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninni', 'ninni-rifki-kaymaz-m35e4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara gözlerine uykular insin,

	Göklerden en güzel duygular insin

	Korkular dağılsın, ağrılar dinsin,

		Benim  tatlı yavrum, güzelim uyu! 

		Sevgiyle, ninniyle, uyu da büyü! 

	Gülücükler, gül gül olup açılsın,

	Yanağına yaprak  yaprak saçılsın.

	Kafdağı’na gökten bir yol açılsın,

		Benim tatlı  yavrum, güzelim uyu! 

		Sevgiyle, ninniyle, uyu da büyü! 

	Sensin, rüyalara süzülüp akan,

	Sevginin  tacını gönlüme takan.

	Nefesinden, beşiğinden gül kokan,

		Benim tatlı yavrum, güzelim uyu! 

 		Sevgiyle, ninniyle, uyu da büyü!', 'Kara gözlerine uykular insin, 	Göklerden en güzel duygular insin 	Korkular dağılsın, ağrılar dinsin, 		Benim  tatlı yavrum, güzelim uyu!  		...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ninni-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dilek Zinciri', 'bir-dilek-zinciri-caglar-asik-khkue', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seven, için ağlar özüm. 

Coşar coşar çağlar gönlüm.

Ne yanlız senin için ne bir başkası için.

Gönülden Sevdiğim içindir bu sözüm.

Gel etme, eyleme diyemem.

O’na nasıl söz vermişim meğer.

Bu söz O’nun katında aşikar. 

Gizleyesim yoktur benim.

Gizlesemde bende durmaz.

Bu derde düşen iflah olmaz.

Sevdiğine ulaşan gönül.

Hiçbir derde düçar olunmaz.

Asıl derdine sarılasın.

Derdinle gönlünü avutasın.

Sakın boşvermeyesin.

İbadetsiz doğru yol bulunmaz.

Koş namaza vaktince.

Tut orucu haddince.

Helal kıl malını, ver zekatı usulünce.

Gücün yeterse Hacca, temizlenip gir ihrama.

Selam ver Kabe’deki tüm Dost’lara.

Sakın gafil olma es geçme hiç birini.

Hem şimdiye kadar gelen,

Hemde gelecek tüm Dost’ları.

Dostlar sadece insan mıdır? 

Hor görme sakın Cinleri ve Melekleri.

Onlara da bir selam ver.

Titrer işitince pür nur’dan yürekleri.

Daha da kaldı ise bilmediklerin.

Yaradana sığınıp Onlar içinde bir selam.

Kainatta Razı olunan her ne varsa,

Hepsine ayrı ayrı, tüm dostlara selam.

Çağlar Aşık dostu dost bil, düşmanı düşman.

İşte budur, tüm kainatta asıl olan.

Bilemem ben bildirilmeyeni dersen.

Yolunu şaşırıp yanlışa gidiverirsin.

(İstanbul – 12.04.2005)', 'Seven, için ağlar özüm.  Coşar coşar çağlar gönlüm. Ne yanlız senin için ne bir başkası için. Gönülden Sevdiğim içindir bu sözüm. Gel etme, ...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-dilek-zinciri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Titreyen Ruha', 'titreyen-ruha-caglar-asik-oj602', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kur’an-ı Kerim’dir şüphesiz kitapların en yücesi.

Ama inanmalısın insanlar bozmadan önce; 

Tevrat, Zebur, İncil de İlahi ve orjinal idi.

Rab katından söz var, O Kur’an-ı korumayı diledi. 

Kitapları yetmedi, seçilmiş yüce insanları da birlikte gönderdi.

En yücesi Sevgilinin Seviligisi Hz. Muhammed Mustafa idi.

O kalblere dolan Nur’dur, sakınmalı kaybetmekten O Nur’lu yolu.

Unutmamalı diğer peygamber, şehit ve erenleri de; kurtuluşa erdirdiler kimleri.

O son Güneş’ti ruhlara doğan, başka gelecek olan yok.

Bu hak din Onda tamam oldu, Hak katında artık O’ndan razı oldu.

Adını andırdı Arş’u ala’da kendi adıyla yan yana.

Bilinmez sırlara ve makamlara ulaştı Burak’la çıktığı miraç’ta.

Aldı hediyesini geldi tekrar Dünya’ya.

Kurtuluşuna razı olamadı yanlız başına.

Kavmine Şefaatlik duasını verdi Yaradan yanlızca O’na.

Mahşerde şefaatçi Nebi’de yok, o hak sadece Resul’de.

Sevenin sevdiğine vereceği sadece bu kadar değil.

Yüce Yaradan katında verilebilecekler biter mi? 

İbadet ederken gördü Melekleri, kimisi Kıyam’da, 

Kimisi Kıraat’da, bir kısmı Rüku’da, diğer bir kısmıda Sücut’da

Hemen diledi Namazı ibadet olarak Allah’tan.

Önce elli vakit verildi, sonra beşte karar kıldı Yaratan.

İnceden inceye öğretildi tüm detaylar hakkıyla.

Tüm inanmış temiz ruhları kurtuluşa erdirebilmek içindi, aslında bu olay.

Kader’den kaçılamaz mutlaka olacak olan olur.

Bütün Dost gönüller bu yolda huzur bulur.

Niyetlerdir amelleri tetikleyip işleten. 

Din günüdür; Sonun başlangıç günüdür, tüm ruhları titreten.

(İstanbul – 12.04.2005)', 'Kur’an-ı Kerim’dir şüphesiz kitapların en yücesi. Ama inanmalısın insanlar bozmadan önce;  Tevrat, Zebur, İncil de İlahi ve orjinal idi. Rab...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/titreyen-ruha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocuğu', 'sokak-cocugu-ozan-ozel-t97np', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'silik bakışları okunmuyor

belki korku

belki öfke

...

yanıyor dünya, içinde

çocuk büyüyor

sokakta

romantik aşk şarkısı okuyor kedi

miyav makamında

dansediyor çocuk

yalnızlığın kollarında

tiner sarhoşluğunda

yitiyor...', 'silik bakışları okunmuyor belki korku belki öfke ... yanıyor dünya, içinde çocuk büyüyor sokakta romantik aşk şarkısı okuyor kedi miyav maka...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sokak-cocugu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostiş-2', 'akrostis-2-hatem-kardesler-wlido', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu halime bak,,

İkide bir seninle karşılaşıyorum…

İnan sevdiğimden çok,

Rüyalarımda mısralarınla savaşıyorum.

		         (Hasret İçimde Bir Dağ Kitabından)', 'Şu halime bak,, İkide bir seninle karşılaşıyorum… İnan sevdiğimden çok, Rüyalarımda mısralarınla savaşıyorum. 		         (Hasret İçimde Bir ...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/akrostis-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-caglar-asik-ocysl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüzgar ile yağmur ile ansan.

En derin deryalara dalsan.

Gözyaşın sel olup boğulasın.

Kurtuluşa eremeyince.

Varlık katındasın, bu yokluk neden? 

Kimdir Hak’tan geleni vermiyen? 

Bu bedendeki tatlı canı.

Kor olup yakmayasın.

Gel ey aşık koy gönlünü.

Yaksın kabını kacağını.

Yanmayan kalb içinde.

Pişer, olur mu diyeceğin? 

Pişen söz, söylenince.

Ruhun lezzete erişince.

Bu ahı vah ile olmaz.

Gönül gözün görmeyince.

Çağrı yapan Doğruya uy.

Ezan-ı duy, namazını kıl.

Sağlıklıyken orucunu tut.

Geçen zaman geri gelmez! 

Haktan gelen malını,

Ver gönülden zekatını.

Hiç gocunma azalmaz.

Helal olur, daha artar.

Vakitin geldi ise,

Durumunda var ise,

Hiç durma koş Resule.

Git Hacca, Mekke ve Medine’ye.

Temiz kalmak için,

Sık sık temizlenmelisin.

Bolca zikret Allah’ı.

Tövbe et ettiklerine.

Girme sakın kabir-e,

Ruhunu temizlemeden.

Temiz olan huzur bulur.

Çünkü artık bu gerçek sondur.

Hesapçılar gelir sual ederler.

Ruhunu sınav edip, gerçekleri belli ederler.

Sınav kağıdın zaten ömrünce yazılmıştır.

Münker ve Nekir ne etsin, bu sınav yanlızca sanadır.

Kopya çekmekte yok, bu son dakikada.

Hak katından gelen bir sözdü, bu sınav her cana.

Geçmek istiyorsan bu sınavı, iyi kullan zamanını.

Ameller niyete göre olur, sende bul artık doğru safı.

(İstanbul – 12.04.2005)', 'Rüzgar ile yağmur ile ansan. En derin deryalara dalsan. Gözyaşın sel olup boğulasın. Kurtuluşa eremeyince. Varlık katındasın, bu yokluk nede...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/cagri-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla, Gül!', 'agla-gul-caglar-asik-r4efj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelin dostlar hep birlikte gezelim.

Günü gün, yarını bugün gibi düşleyelim.

Hiç boş yere konuşup durmak olmaz.

Bu Nuru birlikte seyir gerek.

Göklerde O yerlerde O.

Hiçbir yere sığmayan O.

Sadece sığacağı bir yer var.

Onun yerini arayıp bulan var mı? 

Ne büyük murad O’nu görmek.

Hep yanında olduğunu bilmek.

Seven sevdiğinden ayrılır mı? 

Sevgiliye seven gerek.

Hiç muhtaç değil mutlaka.

O, sevgiye ve sevgiliye.

Fakat biz kuluz aciz ve fakir.

Bunu da anlamayan var mı? 

Seven sevdiğini arar.

Bulunca hep ardında gider.

Coşan gönüldeki aşkın.

Sonsuzluğa erişesi gerek.

Gözlerdeki hüzün niye? 

Sözlerdeki acı niye? 

Seven sevdiğini iyi ister.

Bu kadar ümitsizlik niye? 

Affedenlerin en affedicisi.

Sevenlerin en seveni.

Tüm gönüllerin tek sahibi.

Rızasına erişmek gerek.

Coşar, coşar çağlar isen,

Hak yolunda ağlar isen.

Akıtasın yürek yaşın.

Hiç damlasın gören var mı? 

Derde düşen derman arar.

Bu derde düşen pek az.

Arayı arayı sende bulasın.

Sakın durma acele gerek.

Çağlar Aşık hep içinde.

Kimi zamanda dilinde.

Bazı sözler ta özünde.

Gürül gürül duyulası gerek.

(İstanbul – 13.04.2005)', 'Gelin dostlar hep birlikte gezelim. Günü gün, yarını bugün gibi düşleyelim. Hiç boş yere konuşup durmak olmaz. Bu Nuru birlikte seyir gerek....', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/agla-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır!', 'sir-caglar-asik-xsecr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kor ateşi gönlümü yakar.

Sevda dumanı içimde tüter.

Bu dert en büyük hazine imiş.

Kaybetmekten korkmak gerek.

Yandıkça yanmak istersin.

Bu derde bağlanmak istersin.

Kopmaz bir bağın var mı? 

Aşık gönüle bolca ateş gerek.

Tüter dumanın, görünmez yüzün.

Kim bilesi halin, cismin? 

Sözlerin özünü bilen var mı? 

Manasına varmak gerek.

Çağlar Aşık’ın sözleri değil.

Rab katının sözleri için bu söz.

Hak’tan inen sözler Kur-an’da.

Gerçek sırrı aramak gerek.

(İstanbul – 13.04.2005)', 'Kor ateşi gönlümü yakar. Sevda dumanı içimde tüter. Bu dert en büyük hazine imiş. Kaybetmekten korkmak gerek. Yandıkça yanmak istersin. Bu d...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sir-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer-5', 'rubailer-5-hatem-kardesler-iiqvc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göz mü aradı,gönül mü sevdi seni? :..

Yoksa bahçedeki gül mü sevdi seni? ...

O biricik sevdiğim dediğin kız,

Yoksa Ayşegül mü sevdi seni? ...

		         (Hasret İçimde Bir Dağ Kitabından)', 'Göz mü aradı,gönül mü sevdi seni? :.. Yoksa bahçedeki gül mü sevdi seni? ... O biricik sevdiğim dediğin kız, Yoksa Ayşegül mü sevdi seni? .....', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubailer-5-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer-6', 'rubailer-6-hatem-kardesler-d9umi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu dünyada sevsek ne çıkar,sevmesek ne çıkar? ...

Temiz aşkları sel basar,deprem yıkar…

O kadar saçma ki bu sevgi lafı,

Birgün sevilen de bıkar,seven de bıkar…

		         (Hasret İçimde Bir Dağ Kitabından)', 'Bu dünyada sevsek ne çıkar,sevmesek ne çıkar? ... Temiz aşkları sel basar,deprem yıkar… O kadar saçma ki bu sevgi lafı, Birgün sevilen de bı...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubailer-6-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer-7', 'rubailer-7-hatem-kardesler-kd05p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbim sana hasret mi gidecek ne? ...

Ömrüm aşk acısıyla mı bitecek ne? ...

Kalbimin içindeki bu sönmez ateşi,

Yoksa bir sel gelipte mi söndürecek ne? ...

		         (Hasret İçimde Bir Dağ Kitabından)', 'Kalbim sana hasret mi gidecek ne? ... Ömrüm aşk acısıyla mı bitecek ne? ... Kalbimin içindeki bu sönmez ateşi, Yoksa bir sel gelipte mi sönd...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubailer-7-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözüm Yok', 'sozum-yok-hatem-kardesler-j3gzc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana sözüm yok bir tanem,

Sana sözüm yok…

Hıncım dağlara,

Kinim dağ doruklarına,

Neden acımasızca girdiler aramıza,

Neden seni benden aldılar? ...

Sana sözüm yok bir tanem,

Sana sözüm yok…

Hıncım yollara,

Kinim yol kıvrımlarına,

Neden geçit verdiler sana,

Neden ayırdılar bizi? ...

Sana sözüm yok bir tanem,

Sana sözüm yok…

Hıncım mektuplara,

Kinim postacıya,

Neden kapımı çalmıyor,

Neden bir haber getirmiyor hala? ...

Sana sözüm yok bir tanem,

Sana sözüm yok…

Hıncım gurbete,

Kinim hasrete,

Neden bitmedi bu ayrılık,

Neden kavuşmadık hala? ...

Sana sözüm yok bir tanem,

Sana sözüm yok…

Hıncım sensizliğe,

Kinim aşka,

Neden sonu hep hüsran dolu,

Neden sevenler mutsuz hala? ...

Sana sözüm yok bir tanem,

Sana sözüm yok…

Hıncım besteler,

Kinim şarkılara,

Neden hep seninle başlayıp seninle bitiyor,

Neden kulaklarımda çınlıyorsun hala? ...

Sana sözüm yok bir tanem,

Sana sözüm yok…

Hıncım bulutlara,

Kinim yağmurlara,

Neden hep seni hatırlatıyor,

Neden sana ağlıyorum hala? ...

Sana sözüm yok bir tanem,

Sana sözüm yok…

Hıncım meyhanelere,

Kinim boş kadehlere,

Neden unutturamıyorlar seni,

Neden içimdesin hala? ...

Sana sözüm yok bir tanem,

Sana sözüm yok…

Hıncım kadere,

Kinim ecele,

Neden almıyorlar canımı,

Neden yaşıyorum hala? ...

		         (Hasret İçimde Bir Dağ Kitabından)', 'Sana sözüm yok bir tanem, Sana sözüm yok… Hıncım dağlara, Kinim dağ doruklarına, Neden acımasızca girdiler aramıza, Neden seni benden aldıla...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/sozum-yok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük-1', 'dortluk-1-hatem-kardesler-orbaz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkı.sevdayı,neş’eyi arayan heves,

Artıyor,çoğalıyor günbegün…

O sinsi rüzgar,o fısıltılı ses,

Bir aşkın itirafıydı dün…

		         (Hasret İçimde Bir Dağ Kitabından)', 'Aşkı.sevdayı,neş’eyi arayan heves, Artıyor,çoğalıyor günbegün… O sinsi rüzgar,o fısıltılı ses, Bir aşkın itirafıydı dün… 		         (Hasret ...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-1-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendiliğinden', 'kendiliginden-hamdi-hos-xbcga', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün içimde anlamsız bir sıkıntı, bir üşüme var.

Sanırım, ellerine ihtiyacım var.

Öyle ben ısıttığım için değil,

Kendiliğinden sıcak.

Öyle ben sıktığım için değil,

 Kendiliğinden  sıkacak.

Bugün ellerine ihtiyacım var.

Tuttu muydu beni; 

Sıkıntılar bana doğru değil,

Damardaki kan gibi sana doğru akacak.

Bugün ellerine ihtiyacım var.

Öyle “birazdan”, “bakarız sonra” değil,

Hemen, şimdi......', 'Bugün içimde anlamsız bir sıkıntı, bir üşüme var. Sanırım, ellerine ihtiyacım var. Öyle ben ısıttığım için değil, Kendiliğinden sıcak. Öyle ...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Hoş']::text[], 8.5, '{"poet":"Hamdi Hoş","poet_slug":"hamdi-hos","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kendiliginden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük-2', 'dortluk-2-hatem-kardesler-sks9i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günleri iple çekiyorum inan,

Seni görmek arzu ve hevesiyle…

Her gece rüyalarıma uzanan,

Bir yüz siliniyor,bir hayat zelzelesiyle…

		         (Hasret İçimde Bir Dağ Kitabından)', 'Günleri iple çekiyorum inan, Seni görmek arzu ve hevesiyle… Her gece rüyalarıma uzanan, Bir yüz siliniyor,bir hayat zelzelesiyle… 		        ...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-2-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük-3', 'dortluk-3-hatem-kardesler-2qntu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çeken bilir sevdanın çilesini,

Zor olur ayrılık sevenler için…

Yok edelim dağlar silsilesini,

Siz sevenler buradan geçin…



		         (Hasret İçimde Bir Dağ Kitabından)', 'Çeken bilir sevdanın çilesini, Zor olur ayrılık sevenler için… Yok edelim dağlar silsilesini, Siz sevenler buradan geçin… 		         (Hasret...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-3-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar Dinliyorum Hergün', 'sarkilar-dinliyorum-hergun-sumru-karabas-vgk2a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şarkılar dinliyorum her gün

Türküler var dilimden düşmeyen

Dillendiremediğim duygularımı

Dile getiren, 

Ben onlarla gülüp, onlarla ağlıyorum...

Ve hala hayaller kuruyorum...

Yapamadıklarım var 

Listelerce uzayıp giden

Erteleyip durduğum

Yarınlarıma yakamoz gibi düşen...

Tellerde arpeji bulan parmaklara

Hala hayran oluyorum

Bir tınıda, bir akorda 

Gerçeklerden kaçıyor

Kendimde kayboluyorum

Ben hayatı böyle seviyorum ama

Galiba yaşlanıyorum...

Direndikçe yüzümdeki çizgilere

Daha çok bakar oldum tozlu resimlere

İnanmıyorum papatya çaylarına

Gülüyorum gençlik iksirlerine

Hala olmazların peşinde

Yaşamı sürüklüyorum...

Ve hala hayaller kuruyorum...

Yolculuklarım var

Yollarca uzayıp giden

Görmediğim diyarlar

Yollarıma toprak olup dökülen...

Ve yine, sevdiğim

Her dizeye

Yeniden vuruluyorum...

Şiirlerle  yaşayıp

Sözlerde sevdalanıyorum

Avuçlarıma tecrübe diye sıkıştırılan

Acılar biriktiriyorum

Söylediğim şarkıların

Kuvözlerinde

Hüzünler büyütüyorum

Beneklendi mi diye

Sık sık ellerimin üstüne bakıyorum

Belki öyle de severim, sevilirim ama

Çok korkuyorum

Galiba yaşlanıyorum...', 'Şarkılar dinliyorum her gün Türküler var dilimden düşmeyen Dillendiremediğim duygularımı Dile getiren,  Ben onlarla gülüp, onlarla ağlıyorum...', ARRAY['Türk Edebiyatı','Şiir','Sumru Karabaş']::text[], 8.5, '{"poet":"Sumru Karabaş","poet_slug":"sumru-karabas","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sarkilar-dinliyorum-hergun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilsem Ve Dirilsem De Yürüsem', 'bilsem-ve-dirilsem-de-yurusem-hasan-ejderha-q6x9s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hocam Mustafa KÖK’e 

Belki soğuk, zaman şiire doymadan toynaklar baki

Sanki ruha haber var, kılıçlar anlık efendiler, sonra bahar

Karar günü her dem tuğra ve dert çığlıkta akşam

Yaşasam ve yaşamasam ne ki doğrulur umut, gelir kırlangıçlar

Su akacak bir gün duyulur çağrılar ve durulur köpük.

Ben oradaydım bilmeden vurulur turnalara gem

Her em şifa değildir her dem  gizliden akar bengisu.

Bilsem ve dirilsem de yürüsem güneş işte şurada an yakın

Kalkın ceylanlar göç var tarlalar  ve ağaçlar, yoruldu gelecek

Kurnaz tilkiler karanlığında kaldı kunduzların

Yıldızların varına denk ne varsa gerçek, ben inanıyorum hayata.

Daha toprak kuru bebekler uyanacak ancak

Anlayacak ne varsa, bilip de taşımak kadar yoruldum ey yar.

Kök sağlam dağlar kadar anlasam yağmuru kolay berekete durmak

Uyumak sonra aldırmadan, kan üzre çizgiler kadar devlet

Evet haykırmaya, lakin çığlık evrensel olsa güzel

Ezel-ebet tarla mezarlıklar, bire bin veren harman ne yaman bir ders.

Dervişin yüzü düşer ebrulara ve tekne sıcak

Alınacak ne kadar öç varsa alınacak sürülünce sayfaları kitabın.

Denilse ki kral çıplak kahkahalar yükselecek göğe 

Dağlara ağan bulutlar şaşıracak tavşanlardan önce.

Gülünce çiçekleri kıskandıracak bebekler, denklemler iflas edecek

Gidecek gelmemek üzre kötü örtü kalkacak aydınlanacak gökyüzü.

Özü ve sözü ile yürüdü erler ki gelirler 

Ayak sesleri değil mi ağıtlar, türküler, şiirler ve cümle evrensel bilgiler.', 'Hocam Mustafa KÖK’e  Belki soğuk, zaman şiire doymadan toynaklar baki Sanki ruha haber var, kılıçlar anlık efendiler, sonra bahar Karar günü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bilsem-ve-dirilsem-de-yurusem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzakların Kızı', 'uzaklarin-kizi-gurcan-gunay-fmfl4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ey uzak iklimlerin kızı

Sen bir ömre bedel hasret

Sen içimde dinmeyen sızı

Çıka gel bir gün insaf et

Ayaklarında uzakların tozu

İster vakit çok geç olsun

Gün solmuş olsun gönülde

Gel bir akşam üstü davetsiz

Çayımın şekeri ol çorbamın tuzu

Sen uzak dağların esintisi

Sen dinmeyen yürek çarpıntısı

Yol yol uzayıp bir akşam

Uğra yine bana kalp hırsızı

Sen yüreğimin dinmez ateşi

Sen içimin batmayan güneşi

Bir umut sun uzaklar ötesinden 

Çözülsün kalplerimizin buzu

Sen ah o gönül yangını

Ruhumun tükenmeyen hazı

Nisan sabahının yıldızı

Ekim güneşinin mağrur kızı

Çıka gel o gelinmeyenlerden

Ayaklarında yılların tozu...', 'Sen ey uzak iklimlerin kızı Sen bir ömre bedel hasret Sen içimde dinmeyen sızı Çıka gel bir gün insaf et Ayaklarında uzakların tozu İster va...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/uzaklarin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kitabın Önsözüne Son Söz', 'bir-kitabin-onsozune-son-soz-hasan-sun-ie2sg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(vazgeçemediklerimizdi mutsuzluklarımız) 

ankam ölüm mahzenlerinde

cennete açılmak istiyor 

cehennem kapılarından

bitti, bitsin

bu yalan da

bir birimizin hiçbir şeyiydik

her şeyi olamadık

sadece buzulsun şimdi 

rehin denizlerde

bitecekse bir masal

en gerçekçi şekliyle bitmeli

en mutsuz şekliyle

süslü hayaller yok artık

aldanmadık birbirimize hiç

sadece hayata…

hayata…

üç nokta koydum sana da

ikisini saymayarak

seni suçlamıyorum

sakin bir şiir

duru bir su gibi

baktım, geçtim

migren duruldu

bir öpücük kondurarak

saf bir çiçeğe tutuşturdum eline

elin, elim çiçekte

elim elimde

gözlerin beynimde

öperek göz bebeklerinden

geçtik

gençtik….! 

gösterdik yaralarımızı

çatmadan kaşlarımızı

narin bir dokunuş gibi

ürpertici

soğukkanlı bir cinayet gibi 

olağan

ben resmederken sevdayı

s/ilgini ustaca kull/andın

alışkanlık diyordun…

bırakarak bir yarımızı

yarım kalacak bir sevdayı

çeyrek çeyrek bozdurduk

sıkıntılısın 

durgunum

sebep arıyorsun

kaçıyorsun

sığıntım kadar

sıkıntın azar

ne istediğini bilmeyenim

küçük ütopyam

üvey bir aşk

öz bir ayrılık gerektirir

bilesin….

kapı eşiğine gelişimiz

içeri giremeyişimiz

neydi buraya getiren bizi

gidelim buradan

yitelim… yitelim…

sancı sancı kanayan

saran, sarmalayan

ey sızılı hayat

kanayan

ve hep kanayan

bekle bizi

bitti,

bit-

sin

bu yalan da

çünkü üvey bir aşk

öz bir ayrılık gerektirir', '(vazgeçemediklerimizdi mutsuzluklarımız)  ankam ölüm mahzenlerinde cennete açılmak istiyor  cehennem kapılarından bitti, bitsin bu yalan da ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sun']::text[], 8.5, '{"poet":"Hasan Sun","poet_slug":"hasan-sun","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/bir-kitabin-onsozune-son-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'goturun', 'goturun-rifki-kaymaz-zigdr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıldızlar kaldırın götürün beni, 

Orada saadet, sevinç, huzur var. 

Işık ışık salkım salkım dökülen, 

Ruhları yıkayan, sönmeyen nur var. 

Oranın hasreti beni yakarken, 

Geceler yarama saplanır kalır. 

Acılar, acılar durmaz akarken, 

Gündüzler dost olur, beni uyarır. 

Ey hasreti yüreğimde toplanan, 

Ey gelişi bize bayram olan yâr, 

Karanlık elinden kurtarıp beni, 

Götürün, götürün beni yıldızlar.', 'Yıldızlar kaldırın götürün beni,  Orada saadet, sevinç, huzur var.  Işık ışık salkım salkım dökülen,  Ruhları yıkayan, sönmeyen nur var.  Or...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goturun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımda', 'aklimda-hikmet-kavas-wuy4o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kadının adını unuttum 

çeşmede suya tuttuğu avucu aklımda 

sömürüye diken diken tüyleri aklımda 

gözleri ki sözlerinden hep önde 

yediveren gözleri aklımda 

kalemi tomruk kavrar gibi kavrayışı aklımda 

baharı saçlarından serpişi aklımda 

eyleme koşarken unutuşu aklımda 

hayat kaldıracı kolunun kırıklığını 

saksılara süzerdi kirpiklerini 

göğü geren türkülerin ortasında 

çocuk gibi değil nenem gibi ağlayışı aklımda 

-ahh nenem 

küfrünü gözyaşıyla çelikleyip çelikleyip 

bir gürlemesi vardı çardaktan- 

nenemin küfürlerindeki çelik gibi 

sıkı sımsıkı yumrukları aklımda 

kadının adını unuttum 

arada bir aklıma vurunca 

çeşmede avuçlarına koyuyorum yüreğimi 

suyun serinliğini unutuyorum 

ellerinin sıcaklığı aklımda', 'kadının adını unuttum  çeşmede suya tuttuğu avucu aklımda  sömürüye diken diken tüyleri aklımda  gözleri ki sözlerinden hep önde  yediveren ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Kavas']::text[], 8.5, '{"poet":"Hikmet Kavas","poet_slug":"hikmet-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aklimda-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimin Hafızası...', 'duslerimin-hafizasi-tulay-eker-8m949', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En güzel ben yanarım

Ateş korkar açar gözlerini

Kaçmak ister yakarım tenini

Ne bir yağmur damlası

Ne de kar yağdırır sevdamın üzeri

Teninde sevdanda tut beni

Hani kaçarsın ya gözlerinin dalışından her baktığın yer sevgilinin gülüşüdür,

sıcacık bakışıdır.Ellerin terler  yarin eli dokunursun sevi akar akarken 

bir acı saplanır soluna dokunamazsın kaçmak istersin dere tepeye vurmak kendini 

oysa nafiledir aldığın nefes bile yarinindir.Herşeyde yarin vardır ama serap gibi

 vahaya düşmüşcesine dizlerin çöker çöl ıslanır daha bir kavrularak  içinde dere akar,

ırmak..okyanus... çağıl çağıl ne sesini duyan olur ne de çığlığını hisseden.Senindir bu

 acı bıçaktan keskin donar her noktan.

 Hani gündüz güneşle sevişirken katılmak istersin aralarına rüzgar şarkı söyler salarsın 

kendini uğultusuna ılık ılık yaprak misali sürüklesin beni dersin umarsızca sadece duymak

 istemezsin özlemeyi kaçarsın özlemden oysa özlemin ta kendisidir yarin,gülüşündür,

görüşündür,içine katıp onunla dolaşmandır.Dudaklarından çıkan her harften üç hece

 dökülür iç çekersin,biriktirirsin..Gece çöker sesler kesilir kaybolursun yarin sokaklarında işte dem vakti dersin her 

içine vuran sancıda debelenirsin,sökülüyormuşcasına..Tıkanır nefes alışın ölsem dersin

 ne garip şey ölmekle eşleştirmek ölümden acı gelir işte.

En güzel ben ağlarım

Kıvrılıp kenarına sessizce

Yamaçlarından aşağı salarım düşlerimi

Ne bir kol tutar

Ne de bir el dokunur tenime

Kenarında, kıvrımlarında tut beni 

Hani duyumsamaz olur ya insan yaşamadan anlayamaz,anlayabiliyor musun ki insanın aklının

 kahve tadına varmasını hatta hatta durmasını yok, yok! beynim,aklım, tek hissettiğim 

yüreğim yüreğimdeyse, ayak izlerin kanar üstünde yırtılırcasına,gülüşlerin..

sevişlerin..varım ya deyişlerin,bak oradayım demelerin.Eşleştirirsin sonra önceleri 

sonralarla yarin yerine koyarsın kendini daha beter vurur işte zaman insana fena koyar

 yok tarifi yok bu acının yaktığın her sigarada bile yari çekersin ciğerlerine her yer yar yar 

yarrr..duydun mu...Gece susmuyor,yağmur dinmiyor...dinmiyorr 

Beni düşün yar

Al koynuna sar

Gözlerin dokunsun 

Gözlerinden bakan olayım

Susta yemişcesine

Beni düşün yar...

İlkbahar sabahı serinliğinde

Teninde çiğ damlaları olayım

Süzülüp kokunda

Yele değmişcesine

Beni düşün yar...

Dudaklarında name olsun adım

Titresin dört yanım

Göğe vursun başım

Güneş yakmışcasına

Beni düşün yar...

Beni düşün

Beni

Yar! 

^^özlem kokar salınır nazlı yar bir bakış atar gülüm-ser...ömre bedel..özledim..özlendin..özlemim^^', 'En güzel ben yanarım Ateş korkar açar gözlerini Kaçmak ister yakarım tenini Ne bir yağmur damlası Ne de kar yağdırır sevdamın üzeri Teninde ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/duslerimin-hafizasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkın Testileri', 'hakkin-testileri-gurbuz-kaya-4abdm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüce dağlar arasında bayırlar

İnsanlar birbirini kayırırlar

Akılsızlar yol gösterirse

Ölüme kazılır çukurlar

Yollarda doludur dizilmiş testiler 

Kurulmuştur düzen tabi olmak için sınava

Bakarlar da görmezler aceleden 

Oysa doludur hakka çağıran mesajlar...

Bilmezler düşmeden kör kuyuya

Batıl olup, yutacağını karanlıkla

Meraklılılar ya! Akılsızlar inerler de kör kuyuya

Açarlar o demde yakarış için ellerini 

Başlarlar Allahım Allahım bağışla bizi

Ulaşır da  yankılanır sesleri iman dolu yüreklerde 

Merhametlidir hası  Müslümanın 

Arar da bulur kardeşini 

Amacı tektir anlamayan kardeşi için 

Kurtarmaktır gayesi, hedefi

Bu  yüzdendir anlatması HAKKI…

Anlayınca onlar; 

Dinlediği dalkavukların yanlış yollarını.

O’da başlar çağırmaya, toplar yoldakileri 

Mücahit oluverir inandıkları için 

Zaman olur bayırlarda 

Dolanırlar etrafında 

Kavuştururlar hakkın fidelerini

Yaratıldıkları toprakla.

Oluverir gitmeden, gideceği yer gibi mekanı

Uyanırlar da almaya çalışırlar rızasını 

Bırakırlar da unuturlar eskileri 

Nasıl olsa yalanmış diye...', 'Yüce dağlar arasında bayırlar İnsanlar birbirini kayırırlar Akılsızlar yol gösterirse Ölüme kazılır çukurlar Yollarda doludur dizilmiş testi...', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Kaya']::text[], 8.5, '{"poet":"Gürbüz Kaya","poet_slug":"gurbuz-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hakkin-testileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demem Eyvallah', 'demem-eyvallah-hadi-onal-w6xcl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözenin başında susuz aşıma

Zehir katılsa  da demem eyvallah

Yüklerim sebebi kader kuşuna

Yine de soysuza demem eyvallah

Gölgelese bulut kararsa mah’ım

İçimden zamanı durdursa ahım

Bilsem ki dinecek bütün eyvahım

Yine de sütsüze demem eyvallah

Gazel dallarımda baykuş  ötse de

Kalmasa umudum vahım gitse de

Türlü işkenceler cana yetse de

Yine de kansıza demem eyvallah

Nedamet suçlunun, yakarış  Bir’e

Boyun eğmek mi? Yok,yakışmaz ere

Dedirtirim ben kendime kefere

Yine de sütsüze demem eyvallah

İsyanım dorukta  yare gitsem de

Divane alemde hara gitsem de

Beş arşın boyunda dara gitsem de

Yine de soysuza demem eyvallah

Sebepler sır olsa kesilse yolum

Tütmese ocağım kırılsa kolum

Deseler kapıda  acılı ölüm

Yine de kansıza demem eyvallah', 'Gözenin başında susuz aşıma Zehir katılsa  da demem eyvallah Yüklerim sebebi kader kuşuna Yine de soysuza demem eyvallah Gölgelese bulut kar...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/demem-eyvallah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul''un Fethine 2 Kala', 'istanbul-un-fethine-2-kala-huseyin-avdic-vdctf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mehdi''nin sava$cilari olmak isteyenler katilsin, Istanbul''un kurtulu$ harbine.

Kalemleriniz kilinc, kitaplariniz kalkan olsun, saldirin Bizans''in kalelerine! 

Berlin, 27 Mayis 2005.

(Fetihe 02 kala)', 'Mehdi''nin sava$cilari olmak isteyenler katilsin, Istanbul''un kurtulu$ harbine. Kalemleriniz kilinc, kitaplariniz kalkan olsun, saldirin Biza...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/istanbul-un-fethine-2-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul''u Istiyorum!', 'istanbul-u-istiyorum-huseyin-avdic-z206u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey yigitlerim! Iki gün icinde Istanbul''u sizden istiyorum.

Beni mahcup ve yalanci etmeyeceginizi iyi biliyorum...

Berlin, 27 Mayis 2005

(Fetihe 02 kala)', 'Ey yigitlerim! Iki gün icinde Istanbul''u sizden istiyorum. Beni mahcup ve yalanci etmeyeceginizi iyi biliyorum... Berlin, 27 Mayis 2005 (Fet...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/istanbul-u-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılaşma', 'karsilasma-omer-faruk-hatipoglu-evvzd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir yerde biliyorsun seninle karşılaştık

ben bir daldan kabuk gibi kuruyorken toprağa

sen bir dala yaprak gibi yürüyordun topraktan

özsuyunda kar suyu,yolun bahar, zaman pul

bana altın,güz makasın ağzındayken kefen çul

ya ben anlatsam yeşil,ya sarıyı anlasan

kayan bir yıldızım ki ne versem akşamüstü

ne versen ışık etmez,günler ki zaten küstü

bu yüzden açma korkum bağrına krateri

yalnız söz''üm kaldı gençliğim gibi duran

duygudan yırttığıma,düşten mürekkep katıp  

şiir günlerden yazdığım yıllardır süren mektup

bir yerde biliyorsun seninle karşılaştık

sen bir dala yaprak gibi yürüyorken topraktan

ben bir daldan kabuk gibi kuruyordum toprağa', 'bir yerde biliyorsun seninle karşılaştık ben bir daldan kabuk gibi kuruyorken toprağa sen bir dala yaprak gibi yürüyordun topraktan özsuyund...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karsilasma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırılmış Yorumlar', 'kaldirilmis-yorumlar-ertugrul-sakar-zkfdb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yorum yok

Seslerin içerisinde susmaya ihtiyacım var

Kaldırılmış yorumlar

Çiğ ıslanmışlığı çiçeğin üzerindeki

Mutluyum içimdeki kemiren kurtla

Bahar umutları hep çiçek açar

Bilmemelisin değişimi

Aynı kaldığına inanarak

Kaldırılmışsa yorumlar

Yorum yok', 'Yorum yok Seslerin içerisinde susmaya ihtiyacım var Kaldırılmış yorumlar Çiğ ıslanmışlığı çiçeğin üzerindeki Mutluyum içimdeki kemiren kurtl...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kaldirilmis-yorumlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterik Hayat', 'i-sterik-hayat-zafer-mutlu-h05w0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'içimde bir sıkıntı var dostlar

dilimide ısırdım..

üstüne üstlük tahtaya da vurdum

nafile, nafile...

hangi anı yaşıyorum ki şu anda...

serseri bir kurşunmu canımı alacak? 

yoksa; bir otobüs içinde,

yoldan çok  iç dikiz aynasını yoklayan densizmi 

ulaştıracak son durağa...

bilemiyorum hala hangi andayım..

belki de; kapanan bir fabrikada,

hakkımı arayan bir işçiyim..

kolluk kuvvetleri karşımda..

of, offff...

kimbilir, zevki alem sonucu olan

bir bebek olacağım sonrada

terkedilen cami avlusuna...

roller belli..

hudutlarda...

yazılmışı oynar dururuz,

kapalı gişeli...

hani, yakan toptaki gibi

yanlış yerde,yanlış zaman

işte

o anda yandın bitti...

sen, koca deniz misin, köpürerek

sınırlarınını zorlayacak...

of  offf...', 'içimde bir sıkıntı var dostlar dilimide ısırdım.. üstüne üstlük tahtaya da vurdum nafile, nafile... hangi anı yaşıyorum ki şu anda... serser...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/isterik-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim...', 'ogretmenim-cemal-nalci-qiqvm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'öğretmenlere…

sana; 

bir takvim yaprağına mecbur kalmadan

gelmek isterim...

derste, 

yolda,

ev de...

dilediğim an yani,

çat kapı.

ana gibi okşamalısın saçlarımı

belki de yar olmalısın gönlüme

ya da bir baba gibi

siper etmelisin göğsünü cehalete.

bense,

seni yazarım beynime,

gözlerindeki ışık cesaretlendirir...

dokunmak isterim yüreğine.

ve...

öğretilerini ateşlerim meşalemde

yansıtırım yüzünü...

karanlıklar aydınlanır

yarınlar doğar seninle...

oysa bu tarih 

bir ok gibi saplanır ya böğrüme

sana ulaşmak

ya da

bana gelmen için

bir neden

gerekmiyor öğretmenim...

öğretmenim...

0111271130s

cemalnalcı', 'öğretmenlere… sana;  bir takvim yaprağına mecbur kalmadan gelmek isterim... derste,  yolda, ev de... dilediğim an yani, çat kapı. ana gibi o...', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ogretmenim-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz bir yolcu! ..', 'i-simsiz-bir-yolcu-cemal-nalci-r5kic', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sökeceğim; 

bandıraları gemilerimin

bütün motorları susturacağım! ..

bırakacağım kürekleri 

birer birer

yelkenimle örteceğim...

ne bekliyorsun ki? ..

durma! ..

bırak kendini sulara...

varsın,

çekeni olmasın kürekleri

kirletmesin dumanlar

mavi gömleğimi

istemem yelkenimde rüzgarlar

rüzgarları tutmak istemem...

dalgalar...

dalgalar götürsün

öylesine rotasız...

ve ben uzanırken mavi yatağıma... 

sere serpe 

yemyeşil odamda 

örter bir mavi beni

beyaz puanlı...

ılınırım ışığında...

üşümem.

kapanır gözlerim

dalgalar eşliğinde...

dalgalar söyler

dalgalar götürür

dalgalar beni

özgür dalgalar...

kucağında,

isimsiz bir gemi...

isimsiz bir zamanda...

bir yer ki isimsiz 

ve...

isimsiz bir ben...

...

sökeceğim; 

bandıraları gemilerimin,

susturacağım bütün motorları

tek tek bırakacağım kürekleri

mavinin koynuna! ..

...ve yelkenimle örteceğim...

yol alacağım

dalgalarla

isimsiz bir gemiyle

isimsiz bir zamana...

bir yer ki isimsiz...

ve...

adı konulmamış bir ben

isimsiz bir yolcu! ..

0206281500c

cemalnalcı', 'sökeceğim;  bandıraları gemilerimin bütün motorları susturacağım! .. bırakacağım kürekleri  birer birer yelkenimle örteceğim... ne bekliyors...', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/isimsiz-bir-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz Aşk', 'olumsuz-ask-i-lknur-cekici-mld13', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiirlerime bakıp da

Çaresiz,mutsuz sanmayın

Gönlümden bir saniyede

Bin türlü duygu geçer

Kimi sevgi, aşk adına

Kimi hüsran, dert adına

Hissettiğim negatifler

Bir saniyede gelir geçer

Hissettiğim ölümsüz aşk

Yıllardır sürer gider

Yazıyorsam bitti her şey

Sevgiye tövbe ettim

Düşünürüm ben tersini

Yaşarım aşkın ölmezini

Aşka tövbe etmem için

Kefeni giymem gerek

Hayatımdaki büyük aşkı

Maziye gömmem gerek', 'Şiirlerime bakıp da Çaresiz,mutsuz sanmayın Gönlümden bir saniyede Bin türlü duygu geçer Kimi sevgi, aşk adına Kimi hüsran, dert adına Hisse...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olumsuz-ask-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yasak Aşk 3*', 'yasak-ask-3-kubilay-enginol-ph0q7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu bedende kavuşmaz artık,bu ruhlar

Başka bedene kaldı mutluluklar

Bu beden bedenden geçti

Hep seni özledi beden inanki

Gözlerinin ışığı ısıttı uzakta olsa

Hep hasret,hep hasret mutluluğa

Beden geçsin.hayat sayfası dolsun

Bu ruh daima senin olsun

Özlem boynunda halka senin esirin

Hep sordu bu beden,neredeydin? 

Gözyaşı bile değil artık fayda

Bu yaşam değil,belki başka yaşama', 'Bu bedende kavuşmaz artık,bu ruhlar Başka bedene kaldı mutluluklar Bu beden bedenden geçti Hep seni özledi beden inanki Gözlerinin ışığı ısı...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasak-ask-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok mu Güzel?', 'cok-mu-guzel-i-smet-barlioglu-9pl8v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duyuyor musun yüreğimin sesini? 

Kemiklerimdeki sızılarımın sesini duyuyor musun? 

Acılarımın sesini,

Çilelerimin sesini,

Yolunu-yordamını şaşıran aklımın sesini,

Zavallı bedenimin sesini duyuyor musun? 

Karasevda oyun-moyun değildir, anam-babam,

Oynuyor musun? 

Bir ömür boyudur

Ellerini çalkalayıp durdun kanımda,

Sildin, kuruladın, kenara çıktın,

Yaptığından sen sorumlu değilmişsin gibilerden.

Ortada bir damlacık kan varsa; 

Bir de sorumlu vardır

Sevgililerden.

Neden böyle sırtsırtayız düşman kardeşler misali

Ve neden yüzyüze değiliz yıllar yılı? 

Çok mu güzel

Her soluk alıp verişte uzaklaşmak birbirimizden? 

Çok mu güzel düşmanlaşmak? 

Çok mu güzel, yakınlaşmak dururken

Yakınlaşmamak? 

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 77-78/100)', 'Duyuyor musun yüreğimin sesini?  Kemiklerimdeki sızılarımın sesini duyuyor musun?  Acılarımın sesini, Çilelerimin sesini, Yolunu-yordamını ş...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cok-mu-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karakterim Değildir', 'karakterim-degildir-i-smet-barlioglu-g19fp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim karakterim değildir sensiz olmak; 

Gururum kırılır gururlar içinde,

İki elim böğürlerimde kalır

Ve iki ayağım bir pabuçta.

Ben ben olmaktan çıkar giderim

Sonuçta.

Parmaklar olmazsa; el, el olmazsa; kol neye yarar? 

Kanatsız-kuyruksuz kuşlar misali,

Yüzgeçsiz, solungaçsız balıklar misali,

Yaprağı olmayan çiçekler misali? 

Sen olmazsan; neye yararım dört duvar arasında,

Bir mavi gökle, bir kara toprak ortasında,

Örselenmiş bir yürekle,

Yanıp yıkılmış bir ciğerle? 

Bir büyük okyanusta sandal mı karaya ulaşabilir

Kürekle? 

Benim karakterim değildir sensizlik,

Benim karakterim değildir boynubüküklük,

Karanlık yağmurlar altında

Kuzey rüzgarlarına göğsünü

Ve yıldızsız göklere ellerini açmak.

Benim karakterim değildir

Kahrından

Kaçmak.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 79-80/100)', 'Benim karakterim değildir sensiz olmak;  Gururum kırılır gururlar içinde, İki elim böğürlerimde kalır Ve iki ayağım bir pabuçta. Ben ben olm...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/karakterim-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar Gibi', 'mektuplar-gibi-i-smet-barlioglu-9rppe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Serilmek istiyorum

Ayaklarının altına güneş ışıklarınca

Sabahın karanlıkları zorladığı saatlerde.

İki avucumda bir yaralı yüreğim,

Önümde, sana çift kanatlı bir kapı gibi açılmış gönlüm,

Umutlarımda seninle dopdolu bir yaşam

Ve azaplarımda

Ölüm.

Enginlerden kaçıp kurtulmuş denizler misali

Usulca sığınmak istiyorum kumlarına

Ayın göklerde gümüş tepsiye döndüğü gecelerde,

Körpecik dalları ılık rüzgarlar okşarken

Ve yağmurlar, taramamı bekleyen saçlarına

Yağarken.

Günü gününe yola çıkmış bir mektup gibi

Ulaşmak istiyorum sana,

Üstünde pul yerine sevdalarla,

Ağzı öpüle öpüle yapıştırılmış mektuplar misali,

Selamdan, sevgiden öte söz etmeyen,

Küstürmeyen,

İncitmeyen,

Desturlar-ruhsatlar veren mektuplar misali, insana,

Anında, zamanında ulaşmak istiyorum

Sana.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

SON GÜNEŞ isimli Serbest Şiirler ''inden > 81-82/100)', 'Serilmek istiyorum Ayaklarının altına güneş ışıklarınca Sabahın karanlıkları zorladığı saatlerde. İki avucumda bir yaralı yüreğim, Önümde, s...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mektuplar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yazmadım O Şiiri', 'ben-yazmadim-o-siiri-melih-coskun-p2nex', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben yazmadım o şiiri

Ellerim, beynim, yüreğim değil 

Uzak yolların elleri değdi sayfalarıma, 

Tren yolunun gecenin beyazlığını 

Bir bıçak gibi kesen o parlak demiri 

Ben yazmadım o şiiri 

Siz yazdınız aslında 

Umutsuz aşkların sözsüz fermanı 

Ve Mayıs şafağında 

Kurulan darağacı

Kıpkırmızı mürekkep 

Ölüme ve sevdaya dökülen gözyaşındaki saflık 

Oyuncağı elinden alınan bir çocuğun haykırışı değil bu 

Ya da sahte dünyaların sahte gülümseyişleri

Göğüste açılan meşruiyet kazanmış 

Bir kurşun yarasıdır artık, 

Çizildi acının o sararmış resmi 

Ben yazmadım o şiiri

Siz yazdınız aslında...

28 Mayıs 2003

00:57', 'Ben yazmadım o şiiri Ellerim, beynim, yüreğim değil  Uzak yolların elleri değdi sayfalarıma,  Tren yolunun gecenin beyazlığını  Bir bıçak gi...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-yazmadim-o-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Tinerci*(akrostiş)', 'tinerci-akrostis-seyhmus-sevilmez-589kc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(T) ek başına kalmış, düşmüş yatağa

…Hep sahipsiz kalan, tinerci çocuk

…Üvey baba kovmuş, dalmış batağa

…Ele poşet alan, tinerci çocuk

…Yaşı daha ne ki, belki on buçuk

(İ) nce ceketine, poşeti gizler

…Koklayarak çeker, alemi izler

…Göz bebeği kayar, yürümez dizler

…Hayallere dalan, tinerci çocuk

…Kötüyü bilemez daha çok küçük

(N) erde el tutanı, tedavi etse

…Yattığı gazteyi, okuya bilse

…Kitap defter ile okula gitse

…Kalbe umut dolan, tinerci çocuk

…Mavi hayallerle, gözleri boncuk

(E) lbet Başı boşsa, hırsız olacak

…Kapkaççılık yapıp,  halkı soyacak

…Sahipsiz kalınca, nefret dolacak

…Midesi aç olan tinerci çocuk

…Düşlerinde yerdi, omlet ve sucuk

(R) üyalara dalar, yastığı taştan

…Yuva özler belli, gözdeki yaştan

…Kağıttan yorganla, korunur kıştan

…Sahipsizlik bulan tinerci çocuk

…Olsaydı  sırtında, sıcak bir gocuk 

(C) amiden yükselir, bir ezan sesi

…Kundakta ağlayan, kimin bebesi

…Bu nasıl bir vicdan, neyin dengesi

…Mazisini solan, tinerci çocuk

…Dudağında kanar, ani bir uçuk

“(İ) mdat devlet baba, tut ellerimi

…Bana sahip çıkıp, gör sen halimi

…Bir iş imkanıyla, düzelt belimi”

…Diye feryat kılan, tinerci çocuk

…Umutları örter, kirli bir balçık…

(Not:Bu şiir; Sokaklardaki  kimsesiz  çocuklarımızı,  kendi emelleri için, bazı maddelere bağımlı yapıp, kirli işlerinde piyon olarak  kullanan karanlık güçlere bir sitem; Devletin, şefkatli ve sıcak elini bu kötü güçlerden önce bu çocuklara uzatması için bir yakarış olarak kaleme alınmıştır…)', '(T) ek başına kalmış, düşmüş yatağa …Hep sahipsiz kalan, tinerci çocuk …Üvey baba kovmuş, dalmış batağa …Ele poşet alan, tinerci çocuk …Yaşı...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tinerci-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-türkiye’m içimde', 'a-turkiye-m-icimde-mikdat-bal-aq54e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vatandan uzakta sanmayın beni 

Türkiye’m içimde, ben içindeyim 

Gurbetçi diyerek, anmayın beni 

Türkiye’m içimde, ben içindeyim

Zannetmeyin onun haricindeyim

Ay-yıldız göğsümde, şanım, gururum 

İmanım kalbimde, parlayan nur’um 

Vatanım ben sana kurban olurum 

Türkiye’m içimde, ben içindeyim

Onun hasretiyle har içindeyim

Her karış toprağı, yoğrulmuş kanla 

Devletim, kurulmuş şerefle şanla 

Vatan sevgisini, bildim imanla 

Türkiye’m içimde, ben içindeyim

Firakı çekilmez nar içindeyim

Atamın, babamın, anamın yeri 

Ruhumdur, nur’umdur, gözümün feri 

Et kemik misali, daha ileri 

Türkiye’m içimde, ben içindeyim

Diyarı ağyarda kor içindeyim

Mikdadî der yoktur başka vatanım 

Onun hasretiyle, matem tutanım 

Türkiye’m bendendir, ben de ondanım 

Türkiye’m içimde, ben içindeyim

Senelerdir ahu zar içindeyim 

Ozan Mikdadi', 'Vatandan uzakta sanmayın beni  Türkiye’m içimde, ben içindeyim  Gurbetçi diyerek, anmayın beni  Türkiye’m içimde, ben içindeyim Zannetmeyin ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/turkiye-m-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hâlâ Gelmedin - Asrın Hissiyatı Kitabından', 'h-l-gelmedin-asrin-hissiyati-kitabindan-omer-ekinci-micingirt-ocvz4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutamadığım ismin andığım

Mor çiçekler açtı hâlâ gelmedin

Nerelerdesin sen yârim sandığım

Kasırgalar geçti hâlâ gelmedin

Kimseler duymasın gözlerime bak

Ben sende kavruldum güneşte toprak

Gel firar bahçemde uç yaprak yaprak

Zaman zehri içti hâlâ gelmedin

İffet reçinesi tenha geceler

Zihnim muallâkta nasıl niceler

Yuvayı besleyen derin heceler

Vakitlerim kaçtı hâlâ gelmedin

Uzun hava çaldı bam telimde dün

İçimde fışkıran köpüğü yosun

Sensiz çığlığımı duyuyor musun

Ömre ömür biçti hâlâ gelmedin

İçli uçurumlar koş adım adım

Bir yığın sözüm var birkaç saatim

Yüreğim yanıyor anlatamadım

Öldüm gece üçte hâlâ gelmedin', 'Unutamadığım ismin andığım Mor çiçekler açtı hâlâ gelmedin Nerelerdesin sen yârim sandığım Kasırgalar geçti hâlâ gelmedin Kimseler duymasın ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hala-gelmedin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Akşamlarım', 'benim-aksamlarim-hadi-onal-kj1rz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim akşamlarım sancılı başlar

Oturmaz yerine bir türlü taşlar

Değişir iklimler, sert olur kışlar

Donar gönül kuşum dalında kalır

Benim akşamıma ay perde çeker

Hangi yöne dönsem uzar gölgeler

Bırakmaz yakamı bir türlü keder

Dolar yudum yudum hıçkırık olur

Benim akşamıma uğramaz dostlar

Dert ortağım olur bana duvarlar

Odamda her eşya benimle ağlar

Mendilin yerini yastığım alır

Benim akşamlarım uzar sabaha

Gecelerim döner  uzun bir aha

Düşe kalka en son bulduğum vaha

Koşarım serap ah! O, uzaklaşır

Benim akşamımda gözüm tavanda

Ararım kendimi bütün zamanda

Çizgiler bir şekil çizdiği anda

Bir başka akşamım sabaha varır.', 'Benim akşamlarım sancılı başlar Oturmaz yerine bir türlü taşlar Değişir iklimler, sert olur kışlar Donar gönül kuşum dalında kalır Benim akş...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benim-aksamlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Pencere-', 'pencere-evren-demirdelen-r0iiq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlamak için daha çok sebebim

Daha az gücüm olduğu zamanlardı.

İlk kez farkına vardığım bir geçmişin

Silik gerçekliğiyle yüzleşirken bedenim,

Ruhum hiç varolmamış şehrin

Karanlığında arıyordu sonunu..

Duruldum sonra istemeden

Yankılanıp dişlerime çarpan şarkılar

Yalnızca birşeylerin cevabı olduğunu bildiğim gece..

Maviden bahsetmediğim şiirler..

Ve görebileceğim kadar beyaz nefesimin

Pencereden başka çözümü yoktu! ! 

Evet pencere! Açık kalmış biryerlerde

Uyuyan şehrin tek bir sıcak yatağa benzemesi gibi

Tutsağıydım nefesime rengini

şiirime soğuğunu verişinin...

İçimde biryerlerde....

Kimin eli yetiştiyse o kadar derinlere

Açık...Bekliyor...

Gülmek için daha çok gidenim

Daha az acım olacak zamanları..

       Yarın uyanınca gece

       Silinince sayfanın sebebi

       Değişmeyecek biliyorum..

       Ama sonunda

       Birşeyler değişecek..

       Ve bu yüzden sessiz

       Saf bu yüzden...', 'Ağlamak için daha çok sebebim Daha az gücüm olduğu zamanlardı. İlk kez farkına vardığım bir geçmişin Silik gerçekliğiyle yüzleşirken bedenim...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/pencere-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semender', 'semender-dua-ekseni-qaibx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SEMENDER

Bilirmisiniz,

Semender’i? 

En kavurucu ateşte

Hiçbir canlının yaşayamaz,

Uçamaz,kaçamaz,

Nefes alamaz

Bakanların gözünü alan,

Yaklaşanın yüzünü yakan,

İçinde ne var, ne yoksa

Her şeyi yakıp kavuran

Cehennemi alevlerde

Yandıkça var olan

Var oldukça

Yakan kavuran ateşinde

Yaşam sebebi olan

Aşkının peşinde

Savrulup duran

Semender’i! ..

..

Ey can! ..

Bilirmisin tutuşturduğun

Ateşin; 

Dünyayı yakıp kavurmaya

Yeteceğini..

Gönlümün; 

Bir semender misali

Hava gibi,su gibi

Aşk ateşiyle beslendiğini.

Hasretinle üşüyüp

Kızgın alevler ortasında

Tir,tir titrediğini.

Duymayacağını bile bile

Her nefeste sana seslendiğini.

..

Bilmezsin! ..

Bunca ateşin aydınlatmaya,

Kör karanlıktan çıkmaya

Yetmediğini..

Eksenindesin nurun,

Nurundan nur

Beklediğini..

..

Şunu da bil ki! ..

Cam en yüksek ısıda

Eriyip,

İstenen şekli alır.

Kadeh olup,mey sunar,

İçene hayat verir.

Sırça kadeh yolunda

Ateşi senin elindendir

Kadeh,kadeh iç gönlüm

Aşk şerbetini

Öğren artık bu yolun

Sabırla biteceğini..

..

Bilesin ki Can! 

Gönlümdeki ateşin

Sebebi sen olsan da,

Yakanın sen olmadığını

Fark ettiğimi..

Dönsen de,dönmesen de

Fark etmez

Anladım ki bu semender gönlümün

Seni O’nda eritip

Bitireceğini! ...

(duaekseni) 

(Semender; çok uzun süreli ve çok yüksek ısıda

yanan ateşin içinde oluşup,yaşamaya başlayan bir canlı türü)', 'SEMENDER Bilirmisiniz, Semender’i?  En kavurucu ateşte Hiçbir canlının yaşayamaz, Uçamaz,kaçamaz, Nefes alamaz Bakanların gözünü alan, Yakla...', ARRAY['Türk Edebiyatı','Şiir','Dua Ekseni']::text[], 8.5, '{"poet":"Dua Ekseni","poet_slug":"dua-ekseni","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/semender-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz''e', 'deniz-e-dilek-kesgin-z3h7k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kıskandın değil mi? 

O yüzden bugün bu kadar hırçınsın,

Bizi bile içine gömebilecek kadar hırçın! 

Oysa dün sabah sen beni kıskandırıyordun,

Martılarla oynaşıyordun, gözlerimle gördüm.

Bense, seni seyredip dalıp uzaklara

“Neden yanımda değil, özledim” diyordum,

Haykırırcasına...

Hoş bir sürpriz yüzünden kıskanma böyle

Ne olmuş, dün sarmaş dolaş,

İçimizde bir telaş

Öylece bindiysek vapura,

Seyrettiysek seni..

Kıskandın değil mi? 

(Nisan,2001)', 'Kıskandın değil mi?  O yüzden bugün bu kadar hırçınsın, Bizi bile içine gömebilecek kadar hırçın!  Oysa dün sabah sen beni kıskandırıyordun,...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kesgin']::text[], 8.5, '{"poet":"Dilek Kesgin","poet_slug":"dilek-kesgin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/deniz-e-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir Benim Olamaz...', 'bu-sehir-benim-olamaz-dursun-elmas-on77f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kent herşeyiyle bana yabancı 

Dostluğu,sevgisi ve de vefası. 

Çiçeği,meyvesi...gülümsemesi 

Hepsi sanal,bütünüyle yalancı... 

Üst kattaki aile, 

Alttakini tanımaz. 

Böyle yığın içinde 

Elbet sevgi barınamaz... 

Bu kentin insanları,olmuş birer hayalet 

Bir ''merhaba'' demeyi beceremezler 

Dirhem dirhem feragat 

Yığın yığın ihanet.... 

Parçalanmış aileler 

Açlık sefalet yüzünden. 

Garip kalmış yetimler 

Kan akar gözlerinden! .. 

Kimsenin kimseye,güveni hiç kalmamış; 

Kadının kocasına, 

Kızının babasına, 

Ne de ananın balasına. 

İtimat uğramamış 

Buranın piyasasına... 

Sokak ortasında adam yabancı 

Zengin sofrasında madam yabancı. 

Divanda çalınan sazlar yabancı 

Dudaktan gönüle sözler yabancı... 

Hayır...hayır! ... 

Bu kent benim olamaz. 

Benim olan insanım,sevmeyi unutamaz. 

Hak haklının olmalı,hep güçlünün olamaz 

Bu şehirde hak,hukuk her ne varsa YABANCI! ..', 'Bu kent herşeyiyle bana yabancı  Dostluğu,sevgisi ve de vefası.  Çiçeği,meyvesi...gülümsemesi  Hepsi sanal,bütünüyle yalancı...  Üst kattaki...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bu-sehir-benim-olamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kur’anı kelâm', 'kur-ani-kel-m-ali-riza-unal-3jghk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölülüleri dirilten Hakkın kelamı kur’an

Hayvandan öte ölen, mezar bekçisimi kur’an

Hudutsuz alemi cihana, tefsiri meâldir kur’an

Neylesin alfabe hafızı, ahmakı avama kur’an

Aklı selim basire, feyyazı membaadır, kur’an

Üfürene savurana,ahiri mühlettir kur’an', 'Ölülüleri dirilten Hakkın kelamı kur’an Hayvandan öte ölen, mezar bekçisimi kur’an Hudutsuz alemi cihana, tefsiri meâldir kur’an Neylesin al...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kur-ani-kelam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güven Olmuyor Diyorsun', 'guven-olmuyor-diyorsun-bora-alagoz-tvsbs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''güven olmuyor'' diyorsun,

''hiç kimseye güvenilmiyor'' diyorsun...

doğrudur güzelim, doğrudur

canımız dahi terk edip gidiyor

ihanet ediyor yaşadığı bedene? ! ...', '''güven olmuyor'' diyorsun, ''hiç kimseye güvenilmiyor'' diyorsun... doğrudur güzelim, doğrudur canımız dahi terk edip gidiyor ihanet ediyor yaş...', ARRAY['Türk Edebiyatı','Şiir','Bora Alagöz']::text[], 8.5, '{"poet":"Bora Alagöz","poet_slug":"bora-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guven-olmuyor-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Gideli..', 'gittin-gideli-dilek-kesgin-y6vwo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gittin gideli suları çekildi burada denizlerin

Balıklar ağlar oldu,

Yüzüm gülmez..

Gittin gideli yakamoz vermez oldu ay suya

Belli ki o bile acıyor bize

Yakamozu birlikte seyredemiyoruz diye..

Gittin gideli sıradanlaştı hayatım

Evden işe, işten eve..

Sensiz zevki çıkmıyor yaşamın

Eski tadı kalmadı buraların.

Gittin gideli yağmur daha şiddetli yağıyor

Sensizliğimin üstüne

Hasretimin şiddetini artırıyor damlalar

Yüreğim isyanda..

Gittin gideli karanlıklardayım

Tenhalaştı sokaklar,

Yanmaz oldu lambalar

Umudumun mumunu yaktım senli günlere

Avunuyorum onunla, gittin gideli..

Gittin gideli dudaklarım buz gibi,

İhtiyacı var sıcaklığına teninin

Elinin ve nefesinin..

Gittin gideli viran oldu bu şehir

Yüreğim bir harabe

Zaman bile ilaç değil yaralarıma

Gittin gideli..

Gittin gideli sevmiyorum hayatı

Kalmadı ki anlamı..

Seyrederken bu koca şehri ayaklarımın altında

Kamçılıyor bir deli özlem bedenimi

Sığınıyorum yüreğime,

Yüreğim sıcak,

Yüreğim deli dolu,

Yüreğim sakin

Beni ancak o anlar böyle durumlarda

Gittin gideli..

Gittin gideli hayranım yalnızlığa

Yalnız yaşayanlara..

Hayranım, şu dünyanın kahrına katlanışlarına

Tek başına..

O hayranlığı yaşıyorum şimdi ben

Gittin gideli..

Katlanmaya çalışıyorum dünyaya ve kahrına

Sensiz, çaresiz,

Tek başıma..

Gittin gideli martılar suya hasret,

Ben sana..

Aynalar bir yüze,

Ben yine sana..

Kuşlar gökyüzüne,

Ben hala sana hasretim, gittin gideli..

Rüzgar nasıl körüklerse yangını

Sensizlik de öyle körüklüyor yalnızlığımı

Bir bıçak yarası gibi içimde hasretin

Bitmek bilmiyor, gittin gideli..

Gittin gideli sele döndü gözyaşım,

Daha çok ağrıyor başım

Gittin gideli hala bekliyorum,

Hala,

Seni çok seviyorum

Gittin gideli..

(İzmir,2001)', 'Gittin gideli suları çekildi burada denizlerin Balıklar ağlar oldu, Yüzüm gülmez.. Gittin gideli yakamoz vermez oldu ay suya Belli ki o bile...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kesgin']::text[], 8.5, '{"poet":"Dilek Kesgin","poet_slug":"dilek-kesgin","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/gittin-gideli-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memur', 'memur-i-brahim-kilinc-dl6fw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoksulluk, sefalet memurun eşi

Hiç tamam olmadı sofrada aşı

Bir iner, bir çıkar emekli yaşı

Seslense sesini duyan var mı ki

Doğduğu gün sille yemiş felekten

Sağılır hep farkı yoktur inekten

Ağalara giden pasta börekten

Ver bir parça dese duyan var mı ki

Gıdım gıdım alır ancak besini

Her gelen iktidar kısar sesini

Kendinden başkası tutmaz yasını

Bir lokma aş dese duyan var mı ki

Sahipsiz değildir, ona çok bakan

Benim memurum der kürsüye çıkan

Gül koklatıp önce ardından diken

Batırır, uy dese duyan var mı ki

Enfilasyon nedir, memura kazık

Zengin torbasından eksilmez azık

Size verdiğimiz oylara yazık

Ver geriye dese duyan var mı ki

Yüzde onu geçmez verilen zamlar

Sözde yüzde yüz denilen zamlar

Hayalde, rüyada görülen zamlar

Ver dese sesini duyan var mı ki

Halkçıyım ben diye yola çıkanlar

Liberal avlakta ava çıkanlar

Çok güvenilip te hava çıkanlar

Bunların şunlardan farkı var mı ki

Sendika kur, grev hakkı yok sana

Çok isteme maaş farkı yok sana

Maval, türkü, şarkı, ninni çok sana

Ülkede memurun hakkı var mı ki

Her iktidar aynı sazı çalıyor

Yarım bize, on kendine alıyor

Eti yiyor, kemiği de yalıyor

Bizim kapımızı çalan var mı ki

Görevin seçimde oyunu vermek

Siyaset işinden uzakta durmak

Sana yakışır mı hiç vekil olmak

Meclis kapısında sıran var mı ki

Böyle gelmiş böyle gitmez bu hava

Çalınmaz bu zurna böyle bedava

Gün gelir divanda görülür dava

Buna hiç ihtimal veren var mı ki

İbrahim karanlık bulur sabahı

Kimsede kalmaz bak kimsenin ahı

Kul görmezse o nu görür Allah ı

Buna  hiç kafayı yoran var mı ki', 'Yoksulluk, sefalet memurun eşi Hiç tamam olmadı sofrada aşı Bir iner, bir çıkar emekli yaşı Seslense sesini duyan var mı ki Doğduğu gün sill...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/memur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-dilek-kesgin-upqmq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hıdrellezlerde yakılan ateşlerin

Savrulan kıvılcımları gibiydik seninle,

Hep savrulduk,

Hep hasret çekmeye mecburduk! 

(İzmir,05.05.2002)', 'Hıdrellezlerde yakılan ateşlerin Savrulan kıvılcımları gibiydik seninle, Hep savrulduk, Hep hasret çekmeye mecburduk!  (İzmir,05.05.2002)...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kesgin']::text[], 8.5, '{"poet":"Dilek Kesgin","poet_slug":"dilek-kesgin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hasret-251-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARAR (SIZ) lık....! ! !', 'karar-siz-lik-mehmet-emin-yesilmen-x0pvg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belkide hayatta vereceğim en zor karardır.

Nedeni olmayan soru işaretidir beynimde.

Olmasımı gerekiyor,

Yoksa olmamasımı...

Bu anlamsızlık

Çok sonrasınıda düşünmekten mi geliyor.

Ya da acabalardan mı..? 

Neye karar varemiyorum.

Olur ve anti olur.

İki yürek arasındayım

Bazende koskoca iki şehir...

Halbuki ince bir iptir

Beni sende tutan.

Belkide sahipsiz gülüşün.

Şimdi bana düşen ise

Çözümsüz bir kararsızlık...', 'Belkide hayatta vereceğim en zor karardır. Nedeni olmayan soru işaretidir beynimde. Olmasımı gerekiyor, Yoksa olmamasımı... Bu anlamsızlık Ç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karar-siz-lik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya Yürüyüş', 'sevdaya-yuruyus-dilek-kesgin-fmft0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece ağır büyür gözlerimde,

Ufukları göremez olur yüreğim.

Karanlık, kara su misali iner bacaklarıma,

Yürüyemez olur gövdem sevda serinliğinde..

Hayallerim sürüklenir dalgalarda,

Ümitlerim çığlık çığlığa, çarpacak bir deniz kenarı aramaya koyulur

Rüyalar, dipsiz çukurlarda son bulur.

Sevdam yakalar beni çıkarır gökyüzüne,

Yıldızlarla dostluğum başlar böylece..

Gece yavaşlar, ufuklarım yakın olur alabildiğince.

Sevdamın serinliği sarar bacaklarımı

Yürürüm binlerce yıllık hasretle..

Yürürüm sevdamın gölgesinde,

Senin serinliğinde

Gözlerinin derinliğinde

Yürürüm! ..

(İzmir,15.02.2002)', 'Gece ağır büyür gözlerimde, Ufukları göremez olur yüreğim. Karanlık, kara su misali iner bacaklarıma, Yürüyemez olur gövdem sevda serinliğin...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kesgin']::text[], 8.5, '{"poet":"Dilek Kesgin","poet_slug":"dilek-kesgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdaya-yuruyus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost denilir mi', 'dost-denilir-mi-i-brahim-kilinc-ankcf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizleri hor görüp eğleniyorsa

Böyle dosta dostlar, dost denilir mi

Yanlışa, hataya söyleniyorsa

Böyle dosta dostlar, dost denilir mi

İyi günde ışık, neşe saçarsa

Kötü günde bizden uzak kaçarsa

Hemen sevip, hemen gönlü geçerse

Böyle dosta dostlar, dost denilir mi

Halimizi sorup öğrenmiyorsa

Hep bizden bekleyip hiç vermiyorsa

Ziyaret etsek te o gelmiyorsa

Böyle dosta dostlar, dost denilir mi

Pintileşip esirgerse bir çayı

Bizden uzak geçiyorsa her ayı

Neyleyim var imiş tahtı, sarayı

Böyle dosta dostlar, dost denilir mi

Hep anlatıp sesimizi duymazsa

Geleneği töremize uymazsa

Dostu sevip hatırını sormazsa

Böyle dosta dostlar, dost denilir mi

Sözde sevip özde ciddî olmazsa

Dar gününde arayıp ta sormazsa

Hiç değilse üç beş ayda gelmezse

Böyle dosta dostlar, dost denilir mi

Üzüntü derdini dosta açmazsa

Coşku neşesini hiç paylaşmazsa 

Dosta giden yola hiç yaklaşmazsa

Böyle dosta dostlar, dost denilir mi

İbrahim kimedir bu hücum, akın

Sanki dostlarına sen oldun yakın

Var mı dostlarından senin bir farkın

Böyle dosta dostlar, dost denilir mi', 'Bizleri hor görüp eğleniyorsa Böyle dosta dostlar, dost denilir mi Yanlışa, hataya söyleniyorsa Böyle dosta dostlar, dost denilir mi İyi gün...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dost-denilir-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Yıl Sonraya Vasiyetimdir', 'kirk-yil-sonraya-vasiyetimdir-tunahan-ermihan-z126p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçer bu üzerine ölü toprağı serpilmiş

Karanlık zamanlar da sevdiğim

Sen yüreğini ferah tut

Yollar çıkar önümüze

Gidenler olur kalanlar olur

Dönmesi beklenen ama dönmeyenler olur hayatımız da

Hatta zaman, zaman olur

Hayattan beklediğin kıvırcık saçlı bebeklerin olur

Gözlerinde yuva kurmasına izin verme acıların

Mevsimdir namı koynunda yatırdığının

Ömrüne ömür mevsimleri sarma sevdiğim

Sevdalarımızı sar umutlarımızı sar

Sar ki gidip de gelmeyenin

Veya ardından bakanların yaslarıyla

Tükenmesin ömrüme ömür diye sardığım ömrün

Kıvırcık saçları rüzgar da uçuşan bebeklerinin

Şen kahkahalarıyla anımsarsın namımı

Bir sonbahar akşamı

Yasım yerine huzura boğarsın

Geçmek de olan yaşını', 'Geçer bu üzerine ölü toprağı serpilmiş Karanlık zamanlar da sevdiğim Sen yüreğini ferah tut Yollar çıkar önümüze Gidenler olur kalanlar olur...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirk-yil-sonraya-vasiyetimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Kızın Giysisi', 'bahar-kizin-giysisi-omer-faruk-hatipoglu-7a1bi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'örteceğine üstündeki basma gömlek

civir civir çıkartmış memelerini

ankara''nın orta yerine rengârenk

ayaklarını öpsün diye saldığın etek

çiçek çiçek açmış seni bahar kız

söylemesi ayıp kalçalarına dek

niye ezersin ayakkaplarını çıplak-

ayak dolaşırken gözlerimde boşuna

yalnızca yeşiline baktığımı bilerek', 'örteceğine üstündeki basma gömlek civir civir çıkartmış memelerini ankara''nın orta yerine rengârenk ayaklarını öpsün diye saldığın etek çiçe...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bahar-kizin-giysisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umarım', 'umarim-mehmet-emin-yesilmen-5v3lj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umarım beni Seviyorsun...

Umarım beni Seviyordur...

Umarım beni Seviyor...

Umarım....

.........

Umarım Umarsızlık Ummam...

....Umarsızlık ölümdür....', 'Umarım beni Seviyorsun... Umarım beni Seviyordur... Umarım beni Seviyor... Umarım.... ......... Umarım Umarsızlık Ummam... ....Umarsızlık öl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/umarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilindik Bir Şey', 'bilindik-bir-sey-omer-faruk-hatipoglu-403g8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'rû ta’ya

şimdi bir yüz ulandı yüzüme

topunu açsam gölyazı’dan

alpler’e kadar gökyüzü

sınırsız

rengini biliyorsunuz

şimdi  bir çift göz eklendi gözüme

elimi siper etsem leman gölü’nden

halikân çölü’ne kadar deniz

fırtınasız

sığlığını biliyorsunuz

şimdi bir el kenetlendi elime

kaç insan varsa iki katı el eleyiz

dünyayı sarmalamışız

kopuksuz

sıklığını biliyorsunuz

şimdi bir de yürek katıldı yüreğime

tık yok

durmayacak biliyorsunuz', 'rû ta’ya şimdi bir yüz ulandı yüzüme topunu açsam gölyazı’dan alpler’e kadar gökyüzü sınırsız rengini biliyorsunuz şimdi  bir çift göz eklen...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bilindik-bir-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabanıl', 'yabanil-omer-faruk-hatipoglu-odvmx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'rüzgârı soyundu karı soyundu bir dağ

	 çiçeği ormanı açıyordu

giyin diyorum, hava tenine göre değil

incir yaprağı bile üstüme ağır diyorsun

ayaklarını bağladıkça bileklerine

bir çitanın gövdesinde bacakların

sana bir kenti sunuyorum çarşı sokak

yalnızca ağaçlarını alıp gidiyorsun

al aç diyorum saçını şu fildişi tarakla

fillerin su içtiği gölde taranıyorsun                            

giyin diyorum,hava, o eski hava değil

sen ademin eğe kemiğini aranıyorsun 

...

boynunda diş izi bir erkek aslanın                                   

kanayan koynundaki dağdan ayrılık', 'rüzgârı soyundu karı soyundu bir dağ 	 çiçeği ormanı açıyordu giyin diyorum, hava tenine göre değil incir yaprağı bile üstüme ağır diyorsun ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yabanil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğrafın', 'fotografin-omer-faruk-hatipoglu-ggjpp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'fotoğrafını senmiş gibi ağırladım

gözlerim zarf oldu ağzı açık

göğsüme yolladım bir anne alsın diye

kimsesi yoktu fotoğrafının

kimsem yoktu fotoğrafını yollayacak

bütün fotoğraflarımı serdim önüne

hiç biri benzemiyordu

fotoğrafınla çekindiğime

hiç kapanmıyordu yeşil gözlerin

ormanı kokluyordum kirpiklerinden

uzayıp gidiyordu incecik parmakların

çıkıp resmin karesinden

çıkıp resmin karesinden 

savruluyordu kıvır kıvır saçların

baktıkça ermiş buğday tarlası bütün çöllerim

bir hal olduğu belliydi bana

göğüs cebimden çırılçıplak çıkıyordun

yüreğim yünlü sesini giyindikçe

üstümdekiler çıkıyordu kendiliğinden

neler anlattım fotoğrafına biliyor musun', 'fotoğrafını senmiş gibi ağırladım gözlerim zarf oldu ağzı açık göğsüme yolladım bir anne alsın diye kimsesi yoktu fotoğrafının kimsem yoktu ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/fotografin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultani aşk', 'sultani-ask-ali-riza-unal-2x9zu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayranım sureti nigârına.

Sireti vechine kurban olayım.

Mecnunu ram olmuşum revânına.

Bir deyil bin fedâyım seyranına.

Rahm eyle, settârı ismin hürmetine.

Azaptır valsına firak, üryânın olayım.', 'Hayranım sureti nigârına. Sireti vechine kurban olayım. Mecnunu ram olmuşum revânına. Bir deyil bin fedâyım seyranına. Rahm eyle, settârı is...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sultani-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöküş', 'cokus-omer-faruk-hatipoglu-mseby', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ilikte deprem bu,kemik yalıtır,ten sarsılmaz 

ruhundan çekilir nehir,ruhunu basar deniz

yüzüne bir çizgidir yıkılan,saçına beyaz

yürek saatli bomba,göğüs duvarında dilsiz

diz boyunca kardasın toprak neden kupkuru 

yağmayan yağmurdan mı çamur beline kadar 

hadi yürü duvarlar koşarken göğsüne doğru

ayaklarında unutuluşla örülen ağlar

göğün göç yolundayken,uzakta uçuşur kuşlar

seçer yağmur seni,saçına değmeden yağmıştır

gecenin her salisesi durur zihne ur işler

gün, gökten yorgana düşen saati bozuk taştır

artık masanın üstü tenha,sandalyeler bomboş

yel bile kapına dargın,zil ölüden de dalgın

adını ünleyen yok,sözcükler cümleden düşmüş

çöktükçe ağırlaşırsın koltuğun senden yorgun

ne sen içindesin ne gün farkında senin

aynanın alnacındayken,aynadaki yüz kimin

ah o kerpiç batındaki cila yalayan cenin 

senden mi kurudu, balkonda asılı adam kim

ne güzeldi her akşam tüm lambalar yanıyordu 

güneş yatıda gibi yanında uyanıyordu

merhabalar çiserdi, koruk yüz şarabolurdu

çölde bir ıslık çalsan,arkanda nehirler ordu

ah şimdi akmıyorsun nehrin iniş yatağında

önünü çöl kesmiş,yol kum fırtınasında yitik

hakkını yiyorsun ömrün, hayatın yutağında

sus! duyulmaz bu kolonsuz çöküşten gelen çığlık', 'ilikte deprem bu,kemik yalıtır,ten sarsılmaz  ruhundan çekilir nehir,ruhunu basar deniz yüzüne bir çizgidir yıkılan,saçına beyaz yürek saatl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cokus-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Sazak Bey!', 'gun-sazak-bey-muharrem-cetinkaya-fxn0n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '27 Mayıs 1980 Günü Kahpece şehit edilen Eşsiz İnsan Gün Sazak''ın anısına....

Mihalıççık''tan can hemşehrimizdir,

Örnek insan Gün Beyi''imiz.

Babası Gazi''nin dava arkadaşıdır,

Örnek insan Gün Beyi''imiz.

27 mayıs 1980 şehitlerin yoldaşıdır,

Örnek insan Gün Beyi''imiz.

Kahpece vuruldu,akan milletin gözyaşıdır,

Örnek insan Gün Beyi''imiz.

Kutlu davada ülkücülerin gardaşıdır,

Örnek insan Gün Beyi''imiz.

Seni unutmadık,yerin gönüldedir,yaştadır,

Örnek insan Gün Beyi''imiz.', '27 Mayıs 1980 Günü Kahpece şehit edilen Eşsiz İnsan Gün Sazak''ın anısına.... Mihalıççık''tan can hemşehrimizdir, Örnek insan Gün Beyi''imiz. B...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gun-sazak-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanma', 'utanma-murat-demir-qwbqb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne yapsanda sormam niçin

Yaksan bile biçim biçim

Neyin varsa almak için

Çal kapımı çal utanma

Yıktın o’ki temelimden

Ölsem demem tut elimden

Ben razıyım buna dünden

Al canımı al utanma

Bak anlımda kalmamış ak

Benzim sanki sarı toprak

Madem döktün yaprak yaprak

Kır dalımı kır utanma

Sende ki aşk vermiş söküm

Anla artık yapma kem küm

Sen cellatsın bende mahküm

Çek ipimi çek utanma

Alıştırdın hasretine

Hep dert verdin ben yetime

Ne çıkarsa kısmetime

Yak başımı yak utanma

Gün olur da nazarıma

Girer isen pazarıma

Damla damla mezarıma 

Dök yaşını dök utanma!', 'Ne yapsanda sormam niçin Yaksan bile biçim biçim Neyin varsa almak için Çal kapımı çal utanma Yıktın o’ki temelimden Ölsem demem tut elimden...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/utanma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Secerem', 'secerem-guven-tahtakiran-vrn4q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Altmışdört yılının nisan ayında

Doğmuşum babama civan demişler

Yozgat-Akdağ-Yeniyapan Köyünde

Büyükler adıma Güven demişler

Anam gidivermiş bir evliyaya

Niyaz etmiş el açarak hüdaya

Ben olunca dua katmış duaya

Sen arı bu dünya kovan demişler

Altıya dek havaleler görmüşüm

Türlü türlü nevaleler görmüşüm

Yedisinde aklı başa dermişim

Artık mektep senin yuvan damişler

Yavaş yavaş engelleri aşmışım

Sınıfları pekiyiyle geçmişim

İyi nedir kötü nedir seçmişim

Onikide yola revan demişler

Şöyle böyle ortaokul yılları

Gurbet-sıla adımladım yolları

Dermeden tanıdım gonca gülleri

Hocalar derslerde yavan demişler

Onbeşinde kalem çektim ezele

Merak saldım muammaya gazele

Gönül koydum şiir yazdım güzele

Yanık Kerem gibi havan demişler

Fakültede hamlığımı pişirdim

Aruzla heceyle aşkı devşirdim

Güreş mi şiir mi bazen şaşırdım

Duyduk bize bir pehlivan demişler

Yirmisinde askerlikten haz duydum

Bana lazım nasihatli söz duydum

Bazısın tam bazısını az duydum

Sabrile çok bela savan demişler

Yirmidörtte öğretmenlik başladı

Mürüvvetim kütüğüme işledi

Otuzüçte balalarım üçledi

Şükreyle kabulmüş duan demişler

Gördüğüm dikende gülü aradım

Sevgiye ulaşan yolu aradım

Şefkatle açılan eli aradım

Muallim kutsalmış davan demişler', 'Altmışdört yılının nisan ayında Doğmuşum babama civan demişler Yozgat-Akdağ-Yeniyapan Köyünde Büyükler adıma Güven demişler Anam gidivermiş ...', ARRAY['Türk Edebiyatı','Şiir','Güven Tahtakıran']::text[], 8.5, '{"poet":"Güven Tahtakıran","poet_slug":"guven-tahtakiran","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/secerem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küfür', 'kufur-osman-velioglu-9vocx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vay anam vay! 

Sen,

Bir zamanlar selamettin...

dalga dalga 

saçlarına

doladığın ömrünü,

Her seher yele verdin,

Bende dil yoktu

sende din,

Burun kırdın,

Yüz ekşittin,

Çektin gittin...

N''ettin gülüm, n''ettin

Sende yoksun,

bende bittin,

...

ben de yokum

sen de yoksun

Var, gül,oyna şimdi...', 'Vay anam vay!  Sen, Bir zamanlar selamettin... dalga dalga  saçlarına doladığın ömrünü, Her seher yele verdin, Bende dil yoktu sende din, Bu...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kufur-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepimiz Fatih''iz', 'hepimiz-fatih-iz-muharrem-cetinkaya-8hocx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '............fetih marşı na atfen; 

Yelkenleri biçeceğiz,yelkenleri dikeceğiz,

Dağlardan çektiriler,kalyonları çekeceğiz; 

Kerpedenlerle..........dişlerini sökeceğiz.

Yürüyoruz artık hainlerle savaştayız,

Fatih''in İstambul''u fethettiği yaştayız.

Biz de geçeriz yardan,anadan,serden...

Bizim de destanımız okunsun ezberden...

Farkındayız artık taşıdığımız değerden...

Elde benim,dilde benim,gönüldeyim,baştayım...

Fatih''in İstanbul''u fethettiği yaştayım.! 

Yüzüne çarpıyorum zamanenin fendini...

Göstereceğim:Kabaran sular nasıl yıkar bendini? 

Küçük görmüyorum,hor görmüyorum kendimi.

Kırılan abideleri yükseltecek taştayım; 

Fatih''in İstanbul''u fethettiği yaştayım.! 

Önderlerim Fatih''tir,Selim''dir,Süleyman''dır,

Sahibiyim ezanların,çünkü bu minare Sinan''dır,

Hadi gardaş uyuyan destanı uyandır..! 

Artık gündelik işlerde niye telaştasın,

Bacım,sen de Fatih''ler doğuracak yaştasın..! 

Arkadaşlar,işaret aldık Gazi Atam''dan

Yürüyelim,bak, millet yürüyecek arkamızdan,

Aldık selamı Ulubatlı Hasandan...! 

Biz ki; burçlara bayrak olacak kumaştayız; 

Fatih''in İstanbul''u fethettiği yaştayız.! 

Artık bozuk saatler yalan yanlış işlemesin! 

...................çekilip haremlerde kışlamasın! 

Yürüyelim,...............hazırlığı başlasın...

Yürüyelim,halâ kendimizle savaştayız? 

Fatih''in İstanbul''u fethettiği yaştayız.!', '............fetih marşı na atfen;  Yelkenleri biçeceğiz,yelkenleri dikeceğiz, Dağlardan çektiriler,kalyonları çekeceğiz;  Kerpedenlerle........', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hepimiz-fatih-iz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan-ı Kamil', 'i-nsan-i-kamil-guven-tahtakiran-5brn6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne bahilem ne şakiyem ne leim

Bir şahiyem isterem olam kerim

Sofram gönlüm alnım açık her daim

Kara toprak son durağım son yerim', 'Ne bahilem ne şakiyem ne leim Bir şahiyem isterem olam kerim Sofram gönlüm alnım açık her daim Kara toprak son durağım son yerim...', ARRAY['Türk Edebiyatı','Şiir','Güven Tahtakıran']::text[], 8.5, '{"poet":"Güven Tahtakıran","poet_slug":"guven-tahtakiran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/insan-i-kamil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son uç', 'son-uc-gulseren-onay-92avu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her şiirimde bir ayrılık var

Her mısramda bir yitirilmişlik,

Her hecem hüznü vurguluyor

Sen ve ben diye başliyorum,

Ama 

Her şey benle bitiyor.......

GÜLSEREN ONAY', 'Her şiirimde bir ayrılık var Her mısramda bir yitirilmişlik, Her hecem hüznü vurguluyor Sen ve ben diye başliyorum, Ama  Her şey benle bitiy...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-uc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir Kadına', 'baska-bir-kadina-sule-aydemir-os2jq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'farkında değilsin -hiç

çiçek kokulu 

yollarda yürüyorsun

ömürün boyunu

sonunda öylesine bir 

çarşaf kucaklıyor tenini

farkında değilsin –hiç bilmiyorsun

yumuşacık 

mis kokulu

bir kadın gibi geliyor

fevt

sonrası yoktur 

lügatinde bir hayır

çiçek

topraktandır

kokusu ondan

mis kokulu kadının

eteklerini havalandıran deli rüzgara

biliyorsun  da ondan gidiyorsun', 'farkında değilsin -hiç çiçek kokulu  yollarda yürüyorsun ömürün boyunu sonunda öylesine bir  çarşaf kucaklıyor tenini farkında değilsin –hiç...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/baska-bir-kadina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivasa', 'sivasa-guven-tahtakiran-td3k7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'B’re Sivas havan soğuk,

Yaylaların ovan soğuk,			

İnsanların sıcak kanlı,

Sanılmasın doğan soğuk,

				Aşıkların atışırlar,

				Celallenir yatışırlar,

				Muhabbete tutuşurlar,

				Sohbet sıcak divan soğuk.

								Kaynar gençlerinin kanı,

								Civan, cihan pehlivanı,

								Sılada koyup cananı,

								Gurbet gurbet savan soğuk,

Güzellerin dokur halı,

Motif olur gülün dalı,

Meşhurdur Zara’nın balı,

Petek sırlı kovan soğuk.

				Şifaiye nakış nakış,

				Gez gör mazi ile bakış,

				Gelse bahar geçse de kış,

				Mekan serin tavan soğuk.

								Yıldız, Tecer tipi boran,,

								Yolculardan hesap soran,,

								Yaraş beli Yağdonduran,,

								Dağın taşın yuvan soğuk..

				Balkan’dan Diyar-ı Rum’dan,,

				Öz vatanı Erzurum’dan,,

				Gelip otağ kurduğundan,,

				Seni candan seven soğuk..

									SİVAS / 23.01.2002', 'B’re Sivas havan soğuk, Yaylaların ovan soğuk,			 İnsanların sıcak kanlı, Sanılmasın doğan soğuk, 				Aşıkların atışırlar, 				Celallenir ya...', ARRAY['Türk Edebiyatı','Şiir','Güven Tahtakıran']::text[], 8.5, '{"poet":"Güven Tahtakıran","poet_slug":"guven-tahtakiran","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sivasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar Geçiyor Sürülerle', 'kuslar-geciyor-surulerle-oguzkan-bolukbasi-lmtq0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkes öldü. 

Bir ben kaldım. 

Yaralı.

 Bir gün karışacağımız toprak üzerinde öylece. 

Dönmek bir yana mümkün değil

Adına aşk dedim bebeğim. 

Kan akmıyor yüreğimde…….. Vuruldum vurulalı

Gözlerimde yağmurlar geziniyor…

 O yağmurlar ki en güzeli çisil çisil

Bahar, mevsimlerin kışkırtanı.. 

Deli olan ne varsa ortaya çıkıyor. 

Aralarına karışıyorum

Ellerin yaralarımı sarsa şimdi, öpücüklerin içimi kanatsa.

 Acıya alışıyorum.

Yolumu de yitirdim dersem., hangi basamağına bir sıfır daha koyarlar notumun

Sorular kolay, ben tembel ve deli ve yaralı, yine de sınıfı geçmeye çalışıyorum

Çabucak bir renk söyle…

Kuşlar geçiyor sürülerle. 

Dileğim renginle hayat bulsun.

Bir dileğim daha var. 

Söyleyeceğin renk mavi ve mavide biraz kırmızı olsun.

Sen tek kişi sanma kendini. 

Sen hayatımdaki tek çoğulsun.

 Odur yedi renk yapan beyazı.

Ne yaparsam yapayım, boş geziniyor düşüncelerim ortalıkta.

 Seni mi bulmaktır maksadım.

Bazı sözleri, bazı anıları, bazı fotoğrafları, bir gün söylerim, anlatırım, gösteririm diye sakladım.

Gözlerinin değdiği çiçeği soldurmadan bekletemedim bunca yıl. 

Adı neydi…..

Zambaktı evet zambaktı, bu mayıs akşamında, o günü ve adını hatırladım. Zambaktı

Evinin pencerelerinden içeriye giren güneş, saçlarından yansıdığında akşam yaklaşıyor olurdu

Şarkı söylemeyen sesin, bilinmez notalarda nağmeleşirdi, ve gemiler limana sokulurdu

Özlem bitti. 

Yaz geliyor. 

Seni yeniden göreceğim.. 

Kısacık saçlarını karıştırıp yüzünü öpeceğim.

Yaralarım kabuk bağladı…

Gül şeklinde kıvrım, kıvrım. 

Unuttum acısını yalnızlığın.

Bana sarıldığın yerde anıtım dikildi, o gündür, donup kaldığım.

Ne olursa olsun aşkının kalanı, ben iyi ederim yaramı, budur aşktan anladığım.', 'Herkes öldü.  Bir ben kaldım.  Yaralı.  Bir gün karışacağımız toprak üzerinde öylece.  Dönmek bir yana mümkün değil Adına aşk dedim bebeğim....', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kuslar-geciyor-surulerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepimizin Anası Anadolu', 'hepimizin-anasi-anadolu-muharrem-cetinkaya-bhz65', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aynı ağacın dallarıyız,beraber açar,beraber solarız,

Bozmayalım dilimizi,dinimizi,bayrağı,kuralı...

Uyanalım,bizi bize vurdurup,kırıyorlar dalları,budakları; 

Hepimizin anası Anadolu,ataları buralı...

Hainlerin oyunları,hilelerine,allarına gelmeyelim,

Bozmayalım dilimizi,dinimizi,bayrağı,kuralı...

Düşmek niye birbirimize,vurmak,vuruşmak....

Hepimizin anası Anadolu,ataları buralı...

Alevi,sünni,kürt,türk,çerkez...etle-tırnak gibiyiz,

Bozmayalım dilimizi,dinimizi,bayrağı,kuralı...

Ayrılık niye,bölünmek,parçalanmak,

Hepimizin anası Anadolu,ataları buralı...

Gelin birlik olalım,bölücülerin sözüne uymayalım; 

Bozmayalım dilimizi,dinimizi,bayrağı,kuralı...

Asırlardır va bu oyun,bozalım,bu vatan bizim; 

Hepimizin anası Anadolu,ataları buralı...

           27 Mayıs 2005 Mihalıççık', 'Aynı ağacın dallarıyız,beraber açar,beraber solarız, Bozmayalım dilimizi,dinimizi,bayrağı,kuralı... Uyanalım,bizi bize vurdurup,kırıyorlar d...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hepimizin-anasi-anadolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardına Bakma..', 'ardina-bakma-veysel-alkan-f1gls', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dokun, son kez ellerime ve yüreğime,

Aldırma sen, sesimin titrediğine,

Beni düşünme sakın,kafana takma! 

Giderken, dönüp de ardına bakma...

Ne verdiysen,al götür, gittiğin yere.

Bilmek de hiç istemem orası nere.

Bana, bir tek hatıra bile bırakma! 

Giderken, dönüp de ardına bakma...

Nasıl bir gidiştir bu,neden kaçışın? 

Yokluğuna gözlerim; siz de alışın.

Verdiğim son gülü, yakana takma! 

Giderken, dönüp de ardına bakma...

Bir bakarsan,yakarak şu gözlerime,

Can vermiş olmaz mısın son közlerime? 

Sönmüşken ateşim, yeniden yakma! 

Giderken, dönüp de ardına bakma... 

Uveys der ki; pişmanım çok sevdiğime,

Değdi mi bu aşk için didindiğime? 

Bundan böyle karşıma,sakın ha çıkma! 

Giderken, dönüp de ardına bakma...', 'Dokun, son kez ellerime ve yüreğime, Aldırma sen, sesimin titrediğine, Beni düşünme sakın,kafana takma!  Giderken, dönüp de ardına bakma... ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ardina-bakma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leb’i şarap', 'leb-i-sarap-ali-riza-unal-mw6mu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana uzaklardan, şevk veren leyli.

Dilinden dökülen,dürmü canânım.

O revânı ihtişamın,ne civandır ne selvi.

Ellere hicap ol,bana meramın sırmı canânım.

Şu garip aşığın,sendedir meyli.

Dide’i nigârdan, buse yokmu canânım.

Gelki sine’i vasla,meşk edem leyli.

Bu üryâna,leb’i şarap çokmu canânım.

Yeni güfte ve beste   t.s.m.

    Udi şair bestekâr Ali Rıza Ünal', 'Bana uzaklardan, şevk veren leyli. Dilinden dökülen,dürmü canânım. O revânı ihtişamın,ne civandır ne selvi. Ellere hicap ol,bana meramın sır...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/leb-i-sarap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Çocukları Öldürmeli,Yetim Kalmasınlar Diye', 'butun-cocuklari-oldurmeli-yetim-kalmasinlar-diye-ozhan-hakan-dez23', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '________________________________________________Babama__

parçalanmış günlerdir yetim çocuklar,

kimseler bilmez parçalarını onlar kadar

kaçmaksa ölüm körler zindanından; 

körlere zindan ne yazar? 

sahi kaçmaya daha kaç var? 

içimde hasretinden utanan

bir eşkıya kederi,

ve

parçalanmış bir ömre dair ne varsa kirlettiğim

kara bir leke gibi düşüyorum

günlerin nakışına

ve yetim bir çocuğun kederli bakışına

kirleniyor,kara bir gergefe gerilmiş günler.

sarılıp o üşüyen günlere

notaları kurşunlanmış türkülerle

sazlarla...ayazlarla...

çalıntı masallarla çağrılan 

umutlara yürüsem; yalnızlığa,

üşüsem; lanetlenmiş bir mayısa çıkar

içimin bütün yolları...

yan diyorum ömrüme.yan! 

yan ki; kederin bile tutuşsun âhından...

ya parçalanmadan günleri ölmeli çocuklar

ya da paramparça olsun ölüm onlar kadar

ölüm! 

seni de kör kurşunlarla öldürmeli

günde milyon kere

seni de ölümlere göndermeli.

sönmeyen bir ateştir ömrüm,külleri sancıma karışır

and olsun ki yokluğundan gayrı bu yürek her şeye alışır....

*21 Mayıs 05

babamın ölümünün 16.yılı anısına', '________________________________________________Babama__ parçalanmış günlerdir yetim çocuklar, kimseler bilmez parçalarını onlar kadar kaçma...', ARRAY['Türk Edebiyatı','Şiir','Özhan Hakan']::text[], 8.5, '{"poet":"Özhan Hakan","poet_slug":"ozhan-hakan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/butun-cocuklari-oldurmeli-yetim-kalmasinlar-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasağım', 'yasagim-aydin-yuzgulec-qdiss', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yasağımsın sen benim

Çiğnesem idam

Çiğnemesem intahar.....

Gözler konuşurken nasıl anlatabilirim sana

Yüreğimde şimşekler çaktığını

Nasıl aydınlanır içinde kaybolduğum karanlık

Ve öyle bir acı ki nasıl dindirebilirim ızdırabını

Şimdi sen oyunlar oynarken efsunlu gözlerinle yüreğime

Ben adını bile koyamadığım duygularla avunurum

Ve bütün benliğimle ellerindeyim 

Nereye savursan beni, oraya savrulurum

Dedimya; kurallarla dolu bu hayatın içinde

Katı bir hükümle hükmeden

Yasğımsın sen benim 

Çiğnesem idam eder gözlerin 

çiğnemesem intahar......

şiir:Ersun Ay', 'Yasağımsın sen benim Çiğnesem idam Çiğnemesem intahar..... Gözler konuşurken nasıl anlatabilirim sana Yüreğimde şimşekler çaktığını Nasıl ay...', ARRAY['Türk Edebiyatı','Şiir','Aydın Yüzgüleç']::text[], 8.5, '{"poet":"Aydın Yüzgüleç","poet_slug":"aydin-yuzgulec","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasagim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Nedir', 'siir-nedir-dursun-elmas-296z2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir vardır; 

-Yığınla söz cümbüşü

Şiir vardır; 

-Yıldızın göz kırpışı.

Şiir vardır; 

-Fırtınalar koparır

Şiir vardır; 

-Karanlığı parlatır.

Şiir vardır; 

-Ruhlara ışık saçar

Şiir vardır; 

-Düşe pencere açar.

Şiir vardır; 

-Erkekçe bir haykırış

Şiir vardır; 

-Yüce Rabbe yakarış.

Şiir vardır; 

-Yüreği dağlamaklı

Şiir vardır; 

-Usulca ağlamaklı.

Şiir vardır; 

-Sular gibi dupduru

Şiir vardır; 

-Kelimeler kupkuru.

Şiir vardır; 

-Mısralar sevda yüklü

Şiir vardır; 

-Nota gibi ahenkli.

Şiirde kelimeler; nağme gibi akmalı,

Yanık türküler gibi,yüreğe köz atmalı.

Şiir; gönüllerin duygu selidir,

Şiir; düşüncenin nazlı dilidir...', 'Şiir vardır;  -Yığınla söz cümbüşü Şiir vardır;  -Yıldızın göz kırpışı. Şiir vardır;  -Fırtınalar koparır Şiir vardır;  -Karanlığı parlatır....', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/siir-nedir-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sevdada Yalnızım', 'bu-sevdada-yalnizim-adnan-ozkan-7xp9c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı sinemde yerini bulan oklar

Bu kaçıncı fırtına, kaçıncı yıkılışım

Hayatımdan silinmiş, kaybolmuş mutluluklar

Dertlerimle kaynaşmış tek başıma yalnızım

Terk etmiş birer birer dost bildiğim insanlar

Susmuş zaman, susmuş yer, taş kesilmiş vicdanlar

Canan diye sevdiğim hani nerde, o canlar

Şu koskoca dünyada bir başıma yalnızım

Beni benden sormayın, adım mazlum, adım hür

Bundan beni sevmezler, tanımazlar mümkündür

Bana göre dünya mı, dünya sağır, dünya kör

Dünya zalime mekan, mazlum nerde, yalnızım

Anlamzken halimi benle geçen yıllarım

Geçen onca mevsimler, ne kışın ne baharın

Öyle büyük ki sevdam, onu bir ben anlarım

Söylemeye ne hacet, bu sevdada yalnızım', 'Bu kaçıncı sinemde yerini bulan oklar Bu kaçıncı fırtına, kaçıncı yıkılışım Hayatımdan silinmiş, kaybolmuş mutluluklar Dertlerimle kaynaşmış...', ARRAY['Türk Edebiyatı','Şiir','Adnan Özkan']::text[], 8.5, '{"poet":"Adnan Özkan","poet_slug":"adnan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-sevdada-yalnizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve İhanet', 'ask-ve-i-hanet-humeyra-yilmaz-mi6nd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Demek bu kadar basitti bir aşkın adını ihanet koyup gitmek

Hem de deliler gibi susarak

Titrek avuçlarıma çaresizlik dikenleri batıyorken

En avaz yanıma sakladım yüreğimin terk edilmişliğini 

Sessiz bir gemiyi uğurlarken son yolculuğuna 

Korkusuz olmaktan ilk defa o gün korktum

Yoksun ya şimdi herkesin sana benzediği bu şehirde

Yalnızlık yine yıldızlardan payıma düşen

Ben buna da alışırım 

Sadece yaşanmamış şeylerin sancısı ağır gelen

Artık geceler de saklamıyor karanlıklarımı 

Güne değmez oldu düşlerimin gölgesi

Mevsimler son seferlerini tamamlıyorken içimde

Ben ayaza koşuyorum son sürat

Belki de haklı isyanımın haksız gerekçesidir bu 

Zaten yargısız bir infazda kalayca ölüyorsa 

Varsın adı ihanet olsun  bu aşkın', 'Demek bu kadar basitti bir aşkın adını ihanet koyup gitmek Hem de deliler gibi susarak Titrek avuçlarıma çaresizlik dikenleri batıyorken En ...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-ve-ihanet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp', 'kayip-salih-gozek-a9vqf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İkindi sonrası onyedi sularında

ırmağın üzerine düştüğünde gölgen

sessiz istasyondan tren geçerdi

ahşap pencerelerine değerdi güneş

ve gözlerinden yansırdı hüzün

şakağından vurulmuş bir şahan gibi

sevdam dolanırken üstünde

güneşin ardına dönerdi yüzün

Gurbeti yaralı sevdalıyım ben

derin bir fay kırığı gibi

               göçe durdum  gözlerinden

hasretinden kurudu nehir yatakları

taş avlular,  eskimiş trabzanlar gibi

yangınlardan kalan külüm

coşkulu bir sabır seni özlemek

nice uykusuz gecelerden sonra

yüzüme çöken acı

saçlarının çizdiği çentiktir gülüm!', 'İkindi sonrası onyedi sularında ırmağın üzerine düştüğünde gölgen sessiz istasyondan tren geçerdi ahşap pencerelerine değerdi güneş ve gözle...', ARRAY['Türk Edebiyatı','Şiir','Salih Gözek']::text[], 8.5, '{"poet":"Salih Gözek","poet_slug":"salih-gozek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kayip-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Beklerken', 'olumu-beklerken-murat-senel-aulwh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Penceremden dışarı bakıyorum yine

Koşuşturan insanlara bakıyorum.

Sonra sen geliyorsun aklıma

Sen, o güzel günler ve ben.

Ben ki ölümün sessizliğine düşmüş

Kafesteki kuş gibiyim,

Önüme koyulan bir aş ve bir su

İşte hayatım işte hepsi bu.

Ölümü bekliyorum sonra,

Belki ağlarken, belki uyurken

Ve belkide seni düşünürken 

Beni yaklayacak ölümü.', 'Penceremden dışarı bakıyorum yine Koşuşturan insanlara bakıyorum. Sonra sen geliyorsun aklıma Sen, o güzel günler ve ben. Ben ki ölümün sess...', ARRAY['Türk Edebiyatı','Şiir','Murat Şenel']::text[], 8.5, '{"poet":"Murat Şenel","poet_slug":"murat-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olumu-beklerken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevgilerim....', 'benim-sevgilerim-murat-oz2-azon8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derme çatmadır benim sevgilerim 

Tuğlalar çarpık,kiremitler rastgele 

Demirden çalınmıştır direkler 

Kumu deniz kumudur... 

Üstüme yıkılır viranedir gönül 

Derme çatmadır benim sevgilerim 

Yanlızlık kah bir uyku sersemliğinde 

Kah bir yudum şarapta. 

İçtikçe içesi gelir insanın 

Bir an dertsiz dünyalar senin 

İçten bir nara ile 

Hayalin yansır solgun ayşığına 

Ve 

Don gömlek kalakalır 

Öylesine sezsizce', 'Derme çatmadır benim sevgilerim  Tuğlalar çarpık,kiremitler rastgele  Demirden çalınmıştır direkler  Kumu deniz kumudur...  Üstüme yıkılır v...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz2']::text[], 8.5, '{"poet":"Murat Öz2","poet_slug":"murat-oz2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benim-sevgilerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılkı Sevda', 'yilki-sevda-salih-gozek-bo4nz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Durgun bir boşluktayım kımıltısız

bilinmez,

          göç rengi ayrılıklardayım

suskun ve  dalgakıran direncinde umutlar

yılkılanmış saçlarında hüzün sunaklarım

Kural dışı sevdalardayım

yüzün  içimde  kar çiçeği

önsüz ve sonsuz coşkularla damıttım sevgimi

gizemli tutkuların burgacında

              bilinmez kuşkulardayım

Ay dizimde uyudu dün gece

ellerinin büyüsüne odakladım düşlerimi

ödünsüz erdemlerimi erteledim gözlerin için

yazgısını  sildim geleceğimin

and olsun

boyun eğmem yokluğunun depremine

içimdeki varlığını hiçleyemem

buyurgan gözaltılar yıldıramaz sevdalarımı

Sen bilmesen de tanığımdır

                          dizimde uyuyan ay

yıldızlar biliyor ki; 

                        seni seviyorum

seninle kuşatma altında duygularım

yine de karabasan yakarmalarla bakmam yüzüne

sanık değilim,

           bilincim hükümlü gözlerine

benliğimde

           aydınlık utkularımdır  egemenliğin.!', 'Durgun bir boşluktayım kımıltısız bilinmez,           göç rengi ayrılıklardayım suskun ve  dalgakıran direncinde umutlar yılkılanmış saçları...', ARRAY['Türk Edebiyatı','Şiir','Salih Gözek']::text[], 8.5, '{"poet":"Salih Gözek","poet_slug":"salih-gozek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yilki-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemem', 'bilemem-halil-colak-fjz7t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilemem

Açık yeşil sevdaların baharı

Koyu yeşil deryalara aşına

Aşk ki yakar yanardağın sıcağı

Böyle çekilirmi  çekilmezmi bilemem 

Halil Çolak', 'Bilemem Açık yeşil sevdaların baharı Koyu yeşil deryalara aşına Aşk ki yakar yanardağın sıcağı Böyle çekilirmi  çekilmezmi bilemem  Halil Ço...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilemem-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Git(!)', 'hadi-git-sule-aydemir-dyob1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tam yeni oturmuştum yüreğim ağzımda; 

–Hadi git…(!)

diyordu hınzır. Yüreğimi bu sözlerinin acıtacağını sanıyordu…neler görmüştük oysa neler..

Bir de ağlasa tastamam olacaktı tablo… Biliyordum, ki yaşamıştım evvelden. Yalnızın rolünü yalnızken yapmak acıdır, acıtır daha çok. Çoğu da bunu bilirde bilmezden gelir. Gidip yanına dizlerimin üzerinde çömeldim, yumruk yaptığı ellerini öptüm, öptüm arka arkaya. Başımı yavaşça kaldırıp gözbebeğine gözlerimi kilitledim. Yanaklarımızdan eş zamanlı ılık ıslak yollar açıldı, sonra çağladılar ama sessizce. Sonunda  tamamlanmıştı tablo.

Nasıl güzellikti bu ey Allah’ ım…(!)  Sıkıca sarıldım acısını kendiminkiyle çiftleştirdim…Aynıydı genlerimiz. Kim bilebilirdi bizi bizden daha iyi! 

Hastaydı babam. Çözümsüzdü. Ve kör bir bulmaca gibi çözülemeyecektik biz de.

Saçlarımı okşadı pamuk yumuk elleriyle, kulağıma fısıldadı; 

-Güzel günler geliyor, sabırla bekle, Yaratıcına güven… Git desem de gitme… Hadi şimdi git… Sımsıkı sarıldık, güvenle sıcacık…

Biliyordum, aynıydı O’ da,  inandım…

O tek torunuydu babamın…', 'Tam yeni oturmuştum yüreğim ağzımda;  –Hadi git…(!) diyordu hınzır. Yüreğimi bu sözlerinin acıtacağını sanıyordu…neler görmüştük oysa neler....', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hadi-git-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek gerek', 'bilmek-gerek-tuncay-akdeniz-5zccf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlığın iyiliğin

Sırasını bilmek gerek

Çiçek ile karanfilin

Sarısını bilmek gerek

Bilinmez ki sırdır alem

Aracıdır dile kalem

Hakkın emri yüce kelâm

Şurasını bilmek gerek

Bulut ağlar döker yaşı

Sabırdır her ilmin başı

Hak yaratmış arzı arşı

Arasını bilmek gerek

Ölümde hak dirilmekte

Her canlı bunu bilmekte

İş libası giyinmekte

Orasını bilmek gerek

Mekan kılmış dağı taşı

Yuvasız koymamış kuşu

Hayat denen uzun koşu

Turasını bilmek gerek

Önündeki derin kuyu

Çalışmasan çıkmaz suyu

Tabiatın budur huyu

Burasını bilmek gerek

Tuncayım hep kardeş olsak

Yol bilenle yoldaş olsak

Dertlilere sırdaş olsak

Yarasını bilmek gerek

Not.bu şiirim zamana göre içimden gelen bir duygudur.Gönül dostları ile paylaşmak istedim hiç bir amaca yönelik değildir.', 'İnsanlığın iyiliğin Sırasını bilmek gerek Çiçek ile karanfilin Sarısını bilmek gerek Bilinmez ki sırdır alem Aracıdır dile kalem Hakkın emri...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bilmek-gerek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Senin aşkın', 'o-senin-askin-halil-colak-he3e4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düştüm senin aşkınla bak ahu zara 

Gönlümde yaralar bin pare pare 

Acep bu sevdaya olur mu çare 

Derdime çare olacak o senin aşkın 

Halil Çolak 27.5.2005', 'Düştüm senin aşkınla bak ahu zara  Gönlümde yaralar bin pare pare  Acep bu sevdaya olur mu çare  Derdime çare olacak o senin aşkın  Halil Ço...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/o-senin-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lafla Olmuyor..', 'lafla-olmuyor-emin-eren-fhcgx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yudum sevgi için

Canımızı veririz

Bir güler yüz için

Dağları deviririz

Biz yaparız arkadaş

Sözümüz senet deriz 

Lafla   olmuyor gardaş

Ne yaptık ne bekleriz

Kolay dille suclamak

Ah felek kader deriz

Diller aklanır ançak

Sucludur kalplerimiz

İmkansız bir dakkalık

Coşunca çatal diller

Yapınca bir güzellik 

Karşılık bekler eller

Bir doğruyu lakırdar

Dört yanlışı hak beller

Hep delikanlı onlar

Alemeyse puşt derler', 'Bir yudum sevgi için Canımızı veririz Bir güler yüz için Dağları deviririz Biz yaparız arkadaş Sözümüz senet deriz  Lafla   olmuyor gardaş N...', ARRAY['Türk Edebiyatı','Şiir','Emin Eren']::text[], 8.5, '{"poet":"Emin Eren","poet_slug":"emin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/lafla-olmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştüm senin aşkınla bak ahu zara', 'dustum-senin-askinla-bak-ahu-zara-halil-colak-8uy0u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düştüm senin aşkınla bak ahu zara

Gönlümde yaralar bin pare pare

Acep bu sevdaya olurmu çare

Günden güne artar feryadım

Çekeyim bu sevda kaderim olsun

Aşkta senden bana hatıra olsun

Yanar Halil aşkından haberin olsun

Sardı ateş yüreği,hediyem olsun

Halil Çolak 27.5.2005', 'Düştüm senin aşkınla bak ahu zara Gönlümde yaralar bin pare pare Acep bu sevdaya olurmu çare Günden güne artar feryadım Çekeyim bu sevda kad...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dustum-senin-askinla-bak-ahu-zara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostiş - Mutlu Olmak', 'akrostis-mutlu-olmak-zafer-yazici-i8elg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zira demiş adamın biri

Ahkam kesmenin bir anlamı yok,

Feri kesilinceye kadar gözlerinin, yapacağın çok şey var hayatta! 

Ekmek kavgasından başka ne kavgasıdır bu ömrünü tükettiğin

Rahat olacaksın, ne kıracak, ne de sıkılacaksın hayattan, hep seveceksin…

Mutlu olmanın tek yolu

Mutlu etmekten geçer…

Zafer kazanmanın yolu

Gönül fethetmekten geçer…', 'Zira demiş adamın biri Ahkam kesmenin bir anlamı yok, Feri kesilinceye kadar gözlerinin, yapacağın çok şey var hayatta!  Ekmek kavgasından b...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/akrostis-mutlu-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sensiz yaşıyorum', 'seni-sensiz-yasiyorum-hicabi-ceylan-e052w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O kadar yalnızım ki

Tek arkadaşım, sigaram

Bir yanımda karlı dağlar

Bir yanımda! 

beni hiç yalnız bırakmayan 

İçimde! Yüreğimde! Kanayan yaram var

Sensizlik yetti artık canıma

Karlı dağlar gibi kar yağdı saçlarıma

Kör talih barikat  kurdu

Sana gelen yollarıma

Bir yanımda kahpe felek

Bir yanımda! 

İçimde! Yüreğimde! Yaşayan deli sevdam var

Kor ateşlere düştü gönlüm

Seni beklemekle geçti kısacık ömrüm

Mum misali eriyip söndüm

Bir yanımda uzayan yollar

Bir yanımda! 

İçimde! Yüreğimde! Hissettiğim hasretin var

Unutamadım atamadım içimden seni

Dağlara, taşlara haykırdım! 

Seni ne çok sevdiğimi

Onlar bildi de bir sen bilemedim

Bir yanımda bitmeyen umutlarım

Bir yanımda! 

İçimde! Yüreğimde! Yaşayan sensizlik var

Seni sensiz seviyorum', 'O kadar yalnızım ki Tek arkadaşım, sigaram Bir yanımda karlı dağlar Bir yanımda!  beni hiç yalnız bırakmayan  İçimde! Yüreğimde! Kanayan yar...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seni-sensiz-yasiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bir Şey Aynı Değil..', 'hic-bir-sey-ayni-degil-sair-salma-g6n9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O  yaşadığımız  aşk  masalına  ne  olmuş.....

Neler  değişmiş.....

Neler  unutulmuş...

Hiç  bir  şey  değişmedi....

Diyorsun  diyorsunda.....

Buna  sende  inanmıyorsun.....

AŞKIM  deyişin  bile...

Yetmiyor.....yetemiyor....

Bize  ne  oldu.. 

Ne  yapdılar....ne  istediler...

Bozulan  hangi  tılsım  

Hangi  büyüydü.....

Anlat  bana  anlat  bana  canımm.... 

Sevmek  bu  kadar  kolaymıydı...

Kolaymıydı  ki  unutmak  kolay  olsun....

Ferhat  ile  şirin  diyordun

Leylayla  ile   mecnunu  düşün  diyordun.....

Bunlar  hep  o  yaşadığımız...

AŞK  masalında  kaldı.......

Olmayınca   olmuyor...

Sevdamız   yerine  dolmuyor......

Ne  çare  elimizden  birşey  gelmiyor......

.', 'O  yaşadığımız  aşk  masalına  ne  olmuş..... Neler  değişmiş..... Neler  unutulmuş... Hiç  bir  şey  değişmedi.... Diyorsun  diyorsunda.......', ARRAY['Türk Edebiyatı','Şiir','Şair Salma']::text[], 8.5, '{"poet":"Şair Salma","poet_slug":"sair-salma","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hic-bir-sey-ayni-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
