INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tütün', 'tutun-sair-morris-yjbw4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pervanenin ateşle uzun ve keyifli dansı

Ateşin ona kısa ve acı cevabı

Bu sefer yok leyla ile mecnun’un aşkı

Mesnevim sadece ortaköy cuması

Mavi kenarında sigaraların ucunda ateş

Aptal pervane ise keş', 'Pervanenin ateşle uzun ve keyifli dansı Ateşin ona kısa ve acı cevabı Bu sefer yok leyla ile mecnun’un aşkı Mesnevim sadece ortaköy cuması M...', ARRAY['Türk Edebiyatı','Şiir','Şair Morris']::text[], 8.5, '{"poet":"Şair Morris","poet_slug":"sair-morris","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tutun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma', 'sorma-halil-colak-45o5m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk nedir diye sorma

Boşa sakın kafa sorma

Bak halime aşığım

Niçin bu haldesin diye sorma

Çünkü ilk gördüğüm an

Yitirmiştim benliğimi

Aldı benden her şeyimi

Mecnun gibi içi yanarak

Dolaşıyorum avanak avanak

İşte aşk koydu bu hale arkadaş

Gör halimi sonra sev

Aşığım ona,aşık kalacağım

her şeyim olan Sema’ya

Başka artık bir şey sorma 

Halil Çolak 31.03.2005', 'Aşk nedir diye sorma Boşa sakın kafa sorma Bak halime aşığım Niçin bu haldesin diye sorma Çünkü ilk gördüğüm an Yitirmiştim benliğimi Aldı b...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sorma-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deyin Bana', 'deyin-bana-hadi-onal-acmoe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ana gardaş deyin bana, 

Çıra gibi yanayım mı? 

Dalımıza kondu baykuş,

Sözlerine kanayım mı? 

Sevdamı veremem yele.

Gülümü koklatmam ele.

Dert çektiren zalim söyle,

Seni de dost  sanayım mı? 

Elim ermez yüzüm tutmaz

Usandırdı bu kadar naz

Diyorsun ki çektiğin az

Tahammülde ana’yım mı

Murad alan var mı handan.

Ne istersiz garip candan.

Rüzgar esi dört bir yandan.

Ben soğuktan donayım mı? 

Kaldım işte bir başıma

Felek acımaz yaşıma

Zehir olan şu aşıma 

Ekmeğimi banayım mı? 

Ana gardaş deyin bana, 

Çıra gibi yanayım mı? 

Dalımıza kondu baykuş,

Sözlerine kanayım mı?', 'Ana gardaş deyin bana,  Çıra gibi yanayım mı?  Dalımıza kondu baykuş, Sözlerine kanayım mı?  Sevdamı veremem yele. Gülümü koklatmam ele. Der...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deyin-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler ve Diriler Onlar Bilirler', 'oluler-ve-diriler-onlar-bilirler-sule-altundag-qrrxk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerimle konuşsam yeter

Bu eller çok ölü gömdü

Onlar bilirler

Ya gözler

Kıyametleri gördüğümde çok diri yandı

Mahşer burada

Ölüler ve diriler...

Onlar bilirler

(2005)', 'Ellerimle konuşsam yeter Bu eller çok ölü gömdü Onlar bilirler Ya gözler Kıyametleri gördüğümde çok diri yandı Mahşer burada Ölüler ve diril...', ARRAY['Türk Edebiyatı','Şiir','Şule Altundağ']::text[], 8.5, '{"poet":"Şule Altundağ","poet_slug":"sule-altundag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oluler-ve-diriler-onlar-bilirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emekli', 'emekli-tuncay-akdeniz-hvvpa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soran yok derdini eridin  bittin

Hep çileli günün yılın emekli

Otuz yıl çalıştın çok fidan diktin 

Giden gelen kesti dalın emekli

Hizmet edip emek vatana katmış

Kimisi şehitler acısı tatmış

İnsan hakkı diyen seni unutmuş

Onlar bilmez senin halın emekli

Dertlerin bitmiyor kanıyor yaran

Fatura kiraya yetmiyor paran

Sabahtan akşama gelmiyor sıran

Bağlamışlar elin kolun emekli

Emekli Tuncay in hiç yüzü gülmez

Tok aç halinden anlamaz bilmez

Makamlar geçici şahlara kalmaz

Bilmem doğrulur mu belin emekli', 'Soran yok derdini eridin  bittin Hep çileli günün yılın emekli Otuz yıl çalıştın çok fidan diktin  Giden gelen kesti dalın emekli Hizmet edi...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emekli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toyunu görelim', 'toyunu-gorelim-tuncay-akdeniz-42q99', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'El sözünün güzel kızı

Seç de toyunu görelim

Baldan tatlı el pekmezi

İç de toyunu görelim

	Güzel uslumudur huyu

	Kimlerdendir aslı soyu

	Senin  gibi var mı boyu

	Ölç de toyunu görelim

Elin dili söyler boşa

Aldanma hayale düşe

Kargada benziyor kuşa

Uç da toyunu görelim

	İki dağın arasına

	Köprü kurmuş deresine

	Sular akıyor tersine

	Geç de toyunu görelim

Silinmez yazılan yazı

Biliyor mu çoğu azı

Beş vakittir hak namazı

Beş de toyunu görelim

	Bilmiyorlar neyin nesi

	Kursak ta kalır hevesi

	Gizli kapalı neresi

	Aç ta toyunu görelim

Tuncay güvenme varına	

Kimseler gelmez darına

Birde cahilin toruna

Düş''te toyunu görelim.

Not.Görücü gözüyle evlenen bir gence uyarı.....! ! !', 'El sözünün güzel kızı Seç de toyunu görelim Baldan tatlı el pekmezi İç de toyunu görelim 	Güzel uslumudur huyu 	Kimlerdendir aslı soyu 	Seni...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/toyunu-gorelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Sesi', 'askin-sesi-yavuz-agir-aef5j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kır çiçekleri gibidir yüzüm

Sevmesini bilirsen.

Çok güzeldir kalbim

Aşkı vermesini bilirsen...

Sevgi öyle bir şeydir.

Ömür boyu kalır içimde.

Yeterki sevmesini bil,

Aşkı vermesini bilirsen...

Bu sevgiler derindedir

Yapmacık değil  içtendir.

İçin için alevlenir

Aşkı vermesini bilirsen...

      Serap Ağır', 'Kır çiçekleri gibidir yüzüm Sevmesini bilirsen. Çok güzeldir kalbim Aşkı vermesini bilirsen... Sevgi öyle bir şeydir. Ömür boyu kalır içimde...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askin-sesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter bu kadar zillet', 'yeter-bu-kadar-zillet-mikdat-bal-5u4gf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeter bu kadar zillet

Kanım donuyor kanım

Kalmadı hiç fazilet

Keşke çıksaydı canım

Aval aval bakıyor

Diyenler, müslümanım

Böyle mi olmalıydı

Memleketim vatanım

Çinsiyeti şüpheli

Yarı bey, yarı hanım

Ondan ağa mı olur

Affınızı umanım

Bağdaşır mı töre’nle? 

Nasıl yaptın başkanım? 

Karşılarsın törenle

Sızlar yerde yatanım

Haberleri izlerken

Zannettim ki Alman’ım

Seyrederken kahroldum

Doğduğuma pişmanım

Elimden birşey gelmez 

Kalemdir tecümanım

Hür’üm yazarım işte

Dertlerden el amanım

Bir gün piliniz biter

Buna tamdır imanım

Tek başına da kalsam

Çıkar tozum dumanım

Mücadeleye devam

Elverdikçe dermanım

Mikdat der düşer isem

Var elimden tutanım

Ben samanlıkta bir çöp

Milyonla var harmanım', 'Yeter bu kadar zillet Kanım donuyor kanım Kalmadı hiç fazilet Keşke çıksaydı canım Aval aval bakıyor Diyenler, müslümanım Böyle mi olmalıydı...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yeter-bu-kadar-zillet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafam', 'mustafam-veli-dalbudak-k4quy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(komşumuzun ağıdını dile getirmeye çalıştım) 

Mustafamı vurdular, beylik gününde,

Böyle acı görmedim anam ömrümde,

Yatıyor dağ gibi, eşik önünde, 

Bana sensiz gülmek haram Mustafam.

Dizlerime yatırıp saçını taradım,

Vurdular Mustafamı,bende ağladım,

Boynuna sarılıp murad almadım,

Bana sensiz gülmek haram Mustafam.

Kurumaz artık gözümün yaşı,

Böylemi bitecekti ikimizin aşkı,

Kader degil mustafam,kötuler yakti,

Bana sensiz gulmek haram Mustafam.

(gerçek bir olaydan esinlenmiştir,

ve o, bir daha hiç gülmedi) 

(Stockholm 2000)', '(komşumuzun ağıdını dile getirmeye çalıştım)  Mustafamı vurdular, beylik gününde, Böyle acı görmedim anam ömrümde, Yatıyor dağ gibi, eşik ön...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mustafam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-veli-dalbudak-swf9i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...Ey Yavrum...

...Sana Öğüdüm...

Karnın tok iken, Açları unutma

İşini bulunca işsizleri unutma

Karnını doyurmak için emek döküp,

karnını doyuramayanları Unutma.

Unutma! , dünyalar kadar emek versede,

bir kaşık çorbaya gülenleri,

bir tas suya gülenleri,

bir tebessüme kul olanları Unutma. 

Zenginliği parayla ölçüp,

Gönül zenginliğini hiçe sayma,

Bu dünyanın altı üstünden daha geniş 

Sakın Unutma

Unutma! nerden geldiğini bilmezisen,

nereye gittiğini bilemezsin

Başkalarının çaresizliği senin çaren olmasın.

Mecbur kalmışları fırsat bilme.

Adaleti kovalayıp,

haksızlıktan kaçtığın kadar

hiç bir şeyi kovalayıp,

hiç bir şeyden kaçma.

Unutma! 

''Aynı değer var her bedende''

Unutma! 

insanı ayakta tutan şey

ayaktakilerin ayağına sarılmak değil,

yerdekilerin elinden tutmaktır.

Unutma! 

Ayağın ne kadar yere basarsa, sen 

o kadar yücelirsin.

Senin için göğsünü siper,elini kılıç eden

...Şehitleri, şehit yavrularını unutma.

Unutma! 

Bildiğin ve bilmediğin, bilemediğin

Gördügün ve görmediğin,göremediğin

Düşündüğün ve düşünmediğin,düşünemediğin

Her şeyi bilen bir ALLAH

Sakın unutma 

Ve ona hep şükret.

(Stockholm 1993)', '...Ey Yavrum... ...Sana Öğüdüm... Karnın tok iken, Açları unutma İşini bulunca işsizleri unutma Karnını doyurmak için emek döküp, karnını do...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ogut-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem uykunda düşlensin', 'ozlem-uykunda-duslensin-yuksel-ozbek-s0onq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Orman örgüsünü yeşillerken

Yüksek patikadan 

Dut ağaçlarının 

Çekici bakışlarında 

Sensizliğinde  seni izledim

Bulutlara çizilmiş kızıllıkta.......

İçi boşaltılmış bağ evinde

Yaşanmış yasak aşkın 

Geçmiş gölgesinde

Hiç tanımadan seni

Çoğalabilmek yaban çileği

Kokusunda yurtluğunda

Çocukluğumun  ninnisinde

Prangalansın gözlerim gözlerine

Işığının büyüsüne 

sevdalansın kelebekler

özlem uykunda düşlensin

bahar doğsun gülüşüne

yaşamına uzat öpüşlerini

yanık sevdalara

yenik sevdalara...', 'Orman örgüsünü yeşillerken Yüksek patikadan  Dut ağaçlarının  Çekici bakışlarında  Sensizliğinde  seni izledim Bulutlara çizilmiş kızıllıkta...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Özbek']::text[], 8.5, '{"poet":"Yüksel Özbek","poet_slug":"yuksel-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozlem-uykunda-duslensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-gulseren-onay-tyj83', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne siluetin kaldı hayalimde,

Ne kulaklarımda nağmelerin,

Nede  buradaki insanları,

Senin insanlarına benzetirim...

Bir özlemin kalmış içimde,

Ne sana gel diyebilirim,

Bağlanmış kalmışım burda

Nede ben sana gelebilirim.....

GÜLSEREN ONAY', 'Ne siluetin kaldı hayalimde, Ne kulaklarımda nağmelerin, Nede  buradaki insanları, Senin insanlarına benzetirim... Bir özlemin kalmış içimde...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozlem-226-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotograf Karesi', 'fotograf-karesi-sair-shimalwest-p2w43', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'fotograf karesi

gerçeğin gölgesi

anıların yaşadığı

bir kağıt parçası

hayat orada tek boyutlu

çoğunlukla mutlu

herşey tersine döndü

şimdi baş ucumun süsü

güneş battıkça her geçen günle

usulca sarardı o kare

fotograf karesi

geçmişin gölgesi

yaşanmışın izi

08.05.2005', 'fotograf karesi gerçeğin gölgesi anıların yaşadığı bir kağıt parçası hayat orada tek boyutlu çoğunlukla mutlu herşey tersine döndü şimdi baş...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/fotograf-karesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme sonbaharda', 'gitme-sonbaharda-sair-shimalwest-ro0y8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gitme...

gitme sonbaharda yaprakların döküldüğü mevsimde

ayazın insanın içine işlediği yerde

ben...

boynu bükük bir elim cebimde

sigaram diğerinde

dumanı göğsümde

gitme...

bak mevsim dönüyor işte bahara

yeşermeye başladı yapraklar dallarında

kuşlar haykırmaya başladı haykırışla

dur...

gitme...

hayat sensiz anlamsız

ben sensiz anlamsız

herşey anlamsız

gitme...

ya da...

gidelim gittiğin yere

03.03.2005', 'gitme... gitme sonbaharda yaprakların döküldüğü mevsimde ayazın insanın içine işlediği yerde ben... boynu bükük bir elim cebimde sigaram diğ...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gitme-sonbaharda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tutam rüya', 'bir-tutam-ruya-sair-shimalwest-fov43', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hayalimde yarattım onu ben

öylece sevdim..

öylece paylaştım..

öylece kızdım..

öylece terk ettim..

karşı çıkmadı hiç bana

dayandı her şekilde sevdama

hayallerim yıkıldığında

buruk kimse bırakmadım arkamda

hayalimde yaşadım onu ben

öylece durgun..

öylece ateşli..

tek taraflı sevda benimki

varolmayanı yaşamanın zevki

gidişi olmayan

dönüşü hiç olmayan

ama...

hayalimde bile tutamadım seni

böylesi tutkulu sevgiyi

hayalimde öldürdüm onu ben

incitmeden..

üzmeden..

üzülmeden..

gerçeklerle yüz yüzeyim artık ben

kaçmadım ki hiç gerçeklerden

sadece bir tutam rüya

çok görme onu da bana

06.03.2005', 'hayalimde yarattım onu ben öylece sevdim.. öylece paylaştım.. öylece kızdım.. öylece terk ettim.. karşı çıkmadı hiç bana dayandı her şekilde...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-tutam-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlensin kelimeler', 'dinlensin-kelimeler-sair-shimalwest-09qwk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sözler kırmaya başlayınca 

düşüncelere izin vermek lazım 

kelimeler dinlensin diye 

yüzler yeniden gülsün diye

09.03.2005', 'sözler kırmaya başlayınca  düşüncelere izin vermek lazım  kelimeler dinlensin diye  yüzler yeniden gülsün diye 09.03.2005...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dinlensin-kelimeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lolipop', 'lolipop-sair-shimalwest-7ghux', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şekeri alınmış çocuk

dudaklar titrek

gözler kısılmış

damlalar düştü düşecek

amca dedi...

ver benim şekerimi

alma çok sevdiğimi

yıkma hayallerimi

adam çattı kaşlarını...

gözleri dik..

sesi net..

bırak artık şekeri

artık büyümek vakti

yaşa hayallerini......

10.03.2005', 'şekeri alınmış çocuk dudaklar titrek gözler kısılmış damlalar düştü düşecek amca dedi... ver benim şekerimi alma çok sevdiğimi yıkma hayalle...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/lolipop-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sunu', 'sunu-guzin-eye-dundar-b36ze', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eğer bu dünyada

nasibim varsa

verdiğim her sözü 

tutmak  isterim

gözümün nuru 

can bedenimi

armağan eylemek 

sunmak  isterim

isterse olmasın 

kabrim durağım

isterse küllensin 

bedenim canım

yüce sevgilerim 

onurlu adım

göklerin koynun da yatmak  isterim...', 'eğer bu dünyada nasibim varsa verdiğim her sözü  tutmak  isterim gözümün nuru  can bedenimi armağan eylemek  sunmak  isterim isterse olmasın...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sunu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçit', 'gecit-guzin-eye-dundar-48yn2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç ömür gömülse tenine

kaç ülkede hüküm sürse

ölümdür tek giysisi

çıplaktır insan...

beyaz saçlarında 

bükülür gider

dağılan hayatın

son zerreleri

ne bir sitem eder 

ne acı  çeker

özgürlüğe çağrılıdır gözleri

öyle bir geçiş ki 

çaresiz seçer

bağlamaz gönlünü 

dünya zevkleri

hayatın sırrını  çözer de gider

belki de duyulmaz son sözcükleri', 'Kaç ömür gömülse tenine kaç ülkede hüküm sürse ölümdür tek giysisi çıplaktır insan... beyaz saçlarında  bükülür gider dağılan hayatın son ze...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gecit-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimdim ben?', 'kimdim-ben-cengiz-emre-karatekin-3saio', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yıldırm düştü yandı can evim

Oniki yıl sürdü, bende bir mevsim

Bütün sevgileri öldürdü sevgim...

Kimdim ben,kimdim ben Yarabbim kimdim? 

Yeryüzü ters döndü,ayakta başım

Gurbetten ihtiyar,ihtiyar yaşım

Kızıl bir çiçektir; mezarda taşım

Kimdim ben,kimdim ben Yarabbim kimdim? 

Yalnız dert şarkısı duydum hayattan

Rüyalarım çiktı,artık umuttan...

Farkım yok zamanı içen saaten

Kimdim ben,kimdim ben Yarabbim kimdim? 

Bir varım,bir yoğum aklımda neden? 

Gözleri gündüzden,ruhum geceden

Sanki bir alemi çıkardın benden

Kimdim ben,kimdim ben Yarabbim kimdim?', 'Bir yıldırm düştü yandı can evim Oniki yıl sürdü, bende bir mevsim Bütün sevgileri öldürdü sevgim... Kimdim ben,kimdim ben Yarabbim kimdim? ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Emre Karatekin']::text[], 8.5, '{"poet":"Cengiz Emre Karatekin","poet_slug":"cengiz-emre-karatekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimdim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al da git beni', 'al-da-git-beni-cengiz-emre-karatekin-dux66', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kızıl sabahta,bir kızıl yağmur

Sevda durağına al da git beni.

Gölgemi kuşatan nur kanatlı nur! 

Ümit rüzgarına al da git beni...

Yalan gece,gündüz yalan bu saat

Yalan sokaklarda gördüğüm hayat,

Esrara bürünmüş,meçhul hakikat

Zamanın yârına al da git beni...

Ruhumu sarınca dertler mahşeri,

Unuttum bulutta müthiş haberi

Günahkar cenneti,sevgi çemberi

O gül diyarına al da git beni...

''İlkbaharda yağan bir kar gibiydim''

Usandım fikirden,hayalden dedim...

Bir yudum su için kapına geldim,

Aşkın pınarına al da git beni...', 'Bir kızıl sabahta,bir kızıl yağmur Sevda durağına al da git beni. Gölgemi kuşatan nur kanatlı nur!  Ümit rüzgarına al da git beni... Yalan g...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Emre Karatekin']::text[], 8.5, '{"poet":"Cengiz Emre Karatekin","poet_slug":"cengiz-emre-karatekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/al-da-git-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-gidişat bozuk!', 'a-gidisat-bozuk-mikdat-bal-sben8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidişat bozuk!

Yaşanacak devir, değil bu devir

Yönümüz yön değil gidişat bozuk!

Soytarılar muhbir, medya müzevir

Günümüz gün değil gidişat bozuk!

İp kimin elinde, diyemem açık

Ahmet zannedersin, çıkar Fatmacık

Her “söylemi” hata, her “eylem” gıcık

Anımız an değil gidişat bozuk!

Dilimizi, dilim, dilim ettiler

Her sözü istihza, filim ettiler

Sinsi, sinsi, milim, milim gittiler

Sonumuz son değil gidişat bozuk!

Bütün değerleri hiçe saydılar

Eloğlunu taklit edip uydular

Arşın, arşın, karış, karış kaydılar

Önümüz ön değil gidişat bozuk!

Adaletin, ismi kaldı cismi yok

Bakar ses etmeyiz, bizde his mi yok?

İslâm’ın bir kısmı kaldı resmi yok

Dinimiz din değil gidişat bozuk!

Düdük yanlış öter, oyun huzursuz

Keçi çok olunca, koyun huzursuz

Ecdadın horlandı, soyun huzursuz

Şanımız şan değil gidişat bozuk!

Mikdatî. İstikbal bundan da acı

Hep böyle uyursan ey aymaz hacı

Neler daha var ki bunlar birkaçı

Tonumuz ton değil gidişat bozuk!

Şair Mikdat Bal', 'Gidişat bozuk! Yaşanacak devir, değil bu devir Yönümüz yön değil gidişat bozuk! Soytarılar muhbir, medya müzevir Günümüz gün değil gidişat b...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/allah-sonumuzu-hayir-eylesin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay gölgesinde', 'ay-golgesinde-cengiz-emre-karatekin-rrq50', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam uyandı mı kapımı çalar,

Esrarlı gözlerin ay gölgesinde.

İçimi ürperten bir korku salar,

Can alan sözlerin ay gölgesinde.

İsmin erişince ufkun ardına

Yıldızlar dökülür ayaklarına...

Senden tipi eser,benden fırtına

Kış düğünü olur,ay gölgesinde.

Bir mecnun ümidi,beni çıldırtan

Kalbimde kan gibi saklı hatıran

Dilimde çığlığa döndüğü zaman,

İpe çekilirim,ay gölgesinde.

Bahtımı sürgüne salacak gibi,

Gül tüten hayalin bir kaçak gibi,

Ölüme susamış bir bıçak gibi,

Bütün özlemlerin,ay gölgesinde', 'Akşam uyandı mı kapımı çalar, Esrarlı gözlerin ay gölgesinde. İçimi ürperten bir korku salar, Can alan sözlerin ay gölgesinde. İsmin erişinc...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Emre Karatekin']::text[], 8.5, '{"poet":"Cengiz Emre Karatekin","poet_slug":"cengiz-emre-karatekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ay-golgesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ', 'dag-guzin-eye-dundar-eo5na', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yeşil başlı

hüzünlü  dağ

gün ışıklarıyla çiçeklen

yağmuru karşıla 

güler yüzünle

kaçan renklerine 

tutun güneşin

rüzgarla  seslen

gecenin ışıklarını getir

yıldızlar eski dost gibidir

seninle güzeldir  uzaklar

baharı şenlendir.', 'Sen yeşil başlı hüzünlü  dağ gün ışıklarıyla çiçeklen yağmuru karşıla  güler yüzünle kaçan renklerine  tutun güneşin rüzgarla  seslen geceni...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dag-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Git Deli Çocuk', 'cek-git-deli-cocuk-sair-akcabey-zs7oh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çek git deli çocuk diyorum kendime

Vur kendini yola ve bir daha hiç ağlama

Hazırlıyorum valizimi ve

Düşkırıklıklarımı dolduruyorum içine

Ezilmişliklerimi,başarısızlıklarımı,alkışlarımı...

Bir tek seni koymuyorum valize

Çıkıyorum yola

Ray sesleri beynimde bir bir infilak

Her takta takıntılarım geliyor aklıma

Her şangırda kırdığın kalbim

Ürpertiyor içimi karla karısık yağmurun titreten nefesi

Ve akabindeki tipinin vahameti

Dönüyorum

Dönüyorum

Aynı yere geliyorum

Anlıyorum sonunda

Vazgeçilmezmiş bu şehirden

Şehir benim içimdeymiş içim adressiz şehirlerde

Hiç bir harita göstermiyor bu adressiz şehri

Ve hiç bir postacı bilmiyor adresimi

Şehir benim içmde içim isimsiz şehirlerde

Dönüyorum

Dönüyorum

Aynı yere geliyorum', 'Çek git deli çocuk diyorum kendime Vur kendini yola ve bir daha hiç ağlama Hazırlıyorum valizimi ve Düşkırıklıklarımı dolduruyorum içine Ezi...', ARRAY['Türk Edebiyatı','Şiir','Şair Akçabey']::text[], 8.5, '{"poet":"Şair Akçabey","poet_slug":"sair-akcabey","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cek-git-deli-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklarda Bir Yerde...', 'uzaklarda-bir-yerde-mehmet-yilmaz-1k7a2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dokunamiyorum sana, kokun benden cok uzaklarda

Beni görebiliyor musun? 

Nasil kipirdadigimi? 

Nasil agladigimi? 

Nasil yürek vurgununla dibe cöküsümü...

Bilmiyorum beni hatirliyor musun? 

Nasil kivrandigimi yüregimdeki yarayla,

Sende aci cekiyor musun ben gibi? 

Agliyor musun yagmura inatlasir gibi? 

Kelimeler kifayetsiz kaliyor hasretimi anlatmaya

Ne yapmaliyim bilmiyorum,

Caresizlik bedenimi sarmaya basladi bile,

Kurtulamazsam diye korkuyorum,

Beni birakip gideceginden korkuyorum,

Birakmazsin degil mi beni? 

Benim sevgilerim derinlerde erişilmeyecek yerlerde yasamaya mahkum

Simdi o en derinde senin yüregine sürgün

Mahkum ol bana cikma icimden

Nedeni yok sevgimin,

Seni bulamadim hala icimde o kadar gizlisin ki,

Gözlerin, kokun, ellerin neydi? 

Neydi benim sevgim cözemedim,

Gözle görünenden cok öte bir seydi,

Bir dünyaydi hayatti benim sevgim,

Hadi sinirlarini genislet bende,

Bagimsizligini ilan et topraklarimda,

yasa öyle yasa ki, bir nefes kadar yakin olayim daima sana,

Soru sorma bana

Nedeni yok sevgimin

nedensiz o dinlemeye doyamadigim sesin.

Zamanin en gerisinde kalmis sevgim,

Simdi sende atti adimini tekrar,

Artik yürümüyor kosuyor,

Sakladi geride kalmis ne varsa,

Tekrar büyüttü icindekileri,

Korkma benden,adimini at sende,

Kapat geride kalanlari, bak yeni bir sayfa uzatti eline,

Hadi yaz sende benimle askin siirini,

Virgül olalim nokta olalim,

Satir aralarinda bulalim sevgimizi...

Dokunabileyim artik sana bir cümlede olsa

Sesin uzaklarda olsa bile yazayim her daim seni,

Beni bulabilecegin tek yer,

Sevgimin bulustugu tek anlamli yer,

Iste karsinda sevgili...

Sevgi karsiliksiz bende,

Sevgi hayat bende,

Sevgi umut bende,

Sende hic ayrilik olmayacak,

Simdi ben sevgimin aynasini buldum sende

Simdi sana bakmaliyim,

Simsicak bir tende seni buldum ben,

Artik kollarinda erimek istiyorum,

Ne Korkum var ne de kücük bir Umudum

Sadece rüzgarin bende...', 'Dokunamiyorum sana, kokun benden cok uzaklarda Beni görebiliyor musun?  Nasil kipirdadigimi?  Nasil agladigimi?  Nasil yürek vurgununla dibe...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/uzaklarda-bir-yerde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemim...', 'kalemim-mehmet-yilmaz-7d9ch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalemim titrek ve bugün hic olmadigi kadar heyacanli

Gene her zaman ki gibi yüreginden bir seyler aktaracak

Gene kanayacak yüregi, gene aglayacak bu gece...

Sessiz gecen gündüzün ardindan,

Gece gene caglayan gibi akti beyaz sayfalarima,

Biliyorum bir cizgi daha cekecekti yalnizligin taa ortasina,

Aglamasi gerekliydi ve aglayacakti,

Kalemim özleme bile hasret kalmisti,

Onu bile yazamaz oldu,

Yalnizlikti onun tek bildigi

Sessizlikti, karanlikti beyaz sayfasiyla paylasbildigi,

Biliyorum o bu gece satir aralarina birakacakti gözyaslarini,

Kalemim umutsuz bir sekilde dökecekti damlalarini.

Soru sormuyordu artik hayata,

Cevab o kadar kaciyordu ki ondan,

Artik anlamsizdi belkide savasmak,

Beyaz sayfasiyla acisini paylasmak,

Hersey anlamini yitirmisti onda...

Sevmek tek cözüm degildi,

Sevmeyi anlatmak onun tek avuntusuydu sadece

Artik o da farkindaydi,

O da farkindaydi uzakta bitkin duran insanin caresizce bakislarinin ne anlama geldiginin,

Mesafeler örtüyordu kücücük sevdasini,

Bilmiyordu nerde oldugunu,

Bilmiyordu kime gönlünü acacagini,

Caresizlikti onun yazabildigi.

Umutsuz oldugunu biliyordu.

O bu gece aglayacakti, belkide ucu bitecekti,

Titriyordu, yazamayacak diye korkuyordu canim kalemim,

Silgi en büyük kabusuydu onun,

Ondan korkuyordu onun bu sevgisini silmesinden korkuyordu,

Tek gercegiydi sevgi, tek yazabildigi cümleydi sevgi,

Gelmesin satir aralarima dokunmasin kelimelerime diye amansizca bagiracakti,

Ve o Bu gece Hic olmadigi kadar dökecekti gözyaslarini,

Beyaz sayfasina güzel seyler tattiramadigi icin aglayacakti.', 'Kalemim titrek ve bugün hic olmadigi kadar heyacanli Gene her zaman ki gibi yüreginden bir seyler aktaracak Gene kanayacak yüregi, gene agla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kalemim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Seninle', 'adim-seninle-necmi-unsal-hn0bg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adını haykırırım ben  bütün secdelerde.

Ezelde Levh’e yazdığın ilk adım seninle.

Bu yolda tam sadakatle sürülen izlerde,

Rahına aşkla attığım ilk adım seninle.

Bir kere tattım, aramam artık gerilerde.

Biberim, tuzum; ağzımda hoş tadım seninle.

Saadet asrından  beri bütün gecelerde,

Hecede, cümlede; özde hep yadım seninle.

Geçmişte, halde; anlarda gelecek demlerde,

Aşkınla başlayan sonsuz miâdım seninle.

Bülbüller efganda, kuşlar öter  seherlerde,

Açılan ellerim, kırık kanadım seninle.

Sen varsın şu alçak nefse tüm direnişlerde,

Rızan baş tacım, şeytana inadım seninle.

Ömrümde tüm çıkıslarda bütün inişlerde,

Düşsem de kalksam da özde maksadım seninle.

5 Mayıs 2004 Çarsamba, Danimarka-Køge 23.45

3+5+6', 'Adını haykırırım ben  bütün secdelerde. Ezelde Levh’e yazdığın ilk adım seninle. Bu yolda tam sadakatle sürülen izlerde, Rahına aşkla attığı...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/adim-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zy16) Feth-i Mübin! -Mensuriye-', 'zy16-feth-i-mubin-mensuriye-zulfikar-yapar-kaleli-lqkbn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sultan İkinci Mehmet, 

bir cihangir, 

devrinin fikir aleminde 

büyüklüğünü kabul ettirmiş 

essiz bir kıymet olmasına rağmen, 

elini öpeceği bir üstadı, 

nazlanıp sesini yükselttiği zaman 

“hizaya gel” diyerek karşı koyabilen 

bir hocası vardı.

İskender, Sezar ve Napolyon da 

birer cihangirdiler. 

Fakat bütün kabiliyetlerine rağmen, 

birer malzeme olmaktan kurtulamadılar. 

Fatih kendine karşı hesap vermeye mecbur edilmiş, 

manevi terbiyesinde nefsini 

kontrol etmesi şart koşulmuş birdir. 

Bu yüzden aralarında daima 

mesafeler olmuştur.

................Bizans surları önünde 

53 günlük çetin ve meşakkatli 

kuşatmanın içinde 

Sultanı destekleyen,

bunaldığı anlarda onu ümitsizlikten 

geri çeken 

“fetih mutlaka müyesser olacak” diyen 

bir  Akşemseddin var. 

Fatih bu savaş dramının hem yazarı, 

hem yöneteni, 

hem de aktörü durumundadır. 

Bunalınca imdada yetişen 

arkadaki suflörün sesi:

”korkma İstanbul’u alacaksın”.

................Fatih, 

...............Bizans’ı almaya teşebbüs eden 

...............sayısız hükümdarlar arasında, 

...............gayesinin bilincine varmış biriydi. 

stanbul’un fethi tarihin en çetin 

savaşlarından biri olmuştur. 

Hatta 70 parça donanmayı 

bir gecede dağlardan aşırıp, 

ordusunu en yeni silahlarla donatan, 

kuşatma planlarını kendi çizen, 

onu denetleyerek tatbik ettiren, 

çok kısa zamanlarda kuleler kuran, 

büyük toplar döktüren bu yaman kumandan, 

kalenin düşmediğine sinirlendiği 

bir zaman atını denize sürüyor. 

Yanındakiler “Sultanım at denizi geçemez ki” 

deyince İşaret parmağını kaleye doğru uzatıyor

ve haykırıyor. 

“Ya İstanbul beni alır, ya ben İstanbul’u”.

...................İşte bu sıkıntıların içinde 

zafer dileği ile Ahmet Paşayı: 

“Paşa velinimetim hocama git 

fethin gününü, 

saatini söylesin” diyerek 

Akşemseddin’e gönderiyor. 

Ak Şeyh fethin 29 Mayıs Salı günü 

müyesser olacağı haberini yollayıp 

metin olmasını istiyor. 

Söylenen zaman yaklaştığı halde 

kalenin düşmemiş olmasından endişelenen 

Akşemseddin’in oğlu telaş 

ve üzüntülü bir şekilde 

babasını çadırında ziyaret etmek istiyor. 

Lakin kapıda duran nöbetçi: 

...........“Bana, içeri kimseyi 

............koymayasın diye söylendi, 

...........seni içeri koyamam” 

..........diye yasaklayınca, 

..........çadırın eteğini kaldırıp 

..........babasını gözlemeye başlıyor. 

Gördüklerini şöyle anlatıyor. 

“Baktım babamın başı açık, 

cübbesi bir yanda, 

seccadesi bir yanda, 

gözyaşları toprağı çamurlaştırmış, 

yüzü çamurlu, elleri semada 

“Allah’ım beni mahcup etme, 

beni utandırma, fethi müyesser kıl” 

diye sesli niyazda, 

kendinden geçmiş. 

..........Bu niyaz hali ne kadar 

.........devam etti bilemem. 

.........Babamın ayağa kalktığını ve

.......... “elhamdülillah kale feth olundu.

...........” dediğini duydum, 

.............başımı kaldırıp uzaklara baktım. 

.............Haftalardır Bizans’ın geri ittiği 

.............ordunun  kaleye girdiklerini gördüm.”

Nihayet Fatih zafer alayı 

ile şehre giriyor. 

Büyük serdarın  sağ yanında 

hocaları Molla Gürani ile 

Molla Hüsrev, 

sol yanında 

Ak Şeyh ile 

Akbıyık Sultan var. 

Padişaha çiçek vermek için 

yollara düşen Bizanslı kızlar, 

Sultanın bir delikanlı olduğunu ne bilsinler. 

Ellerindeki çiçek demetlerini 

ak ve seyrek sakallı ihtiyara uzatıyorlar. 

O da “padişah ben değilim” 

diyerek yanındaki genç serdarı gösteriyor. 

Fatih: “Verin verin, 

ben padişahım ama, 

o benim hocamdır” diyerek 

tebessüm ediyor.

O İstanbul’u alınca bunu 

beşeri ihtiraslarını tatmin etmek, 

davayı kendisine mal etmek 

sevdasına kapılmamıştır. 

Öyle ki şehre girerken:

 “Sultanım mutlusunuz değil mi? 

”sorusuna, 

“En büyük mutluluğum velinimetim, 

hocamın yanılmamış olmasıdır” 

diye cevaplıyor. 

O böyle mutlu bir düğümü 

kendi eli çözdüğü için ancak şükretmiştir. 

Nitekim ilk Cuma namazını 

Ayasofya’da kılmak için zaptettiği 

şehrin dışında üç gün bekledikten sonra

şehrin kapısından girip 

mabedin önüne geldiği zamanı 

ilk işi secdeye kapanıp şükretmek olmuştur.

...............Ayasofya Camiinde 

...............ilk cuma namazı kılınacak 

...............Sultan imam, tekbir alıyor, 

...............el bağlıyor, ellerini çözüyor 

.................tekrar  tekbir alıyor. 

...............Bu hal üç defa tekrar ediyor. 

...............Cemaat şaşırıyor. 

...............Namazdan sonra sebebi Sultana soruluyor. 

..............Fatih: “Niyet ettim, tekbir aldım. 

..............Her zaman namaz kılarken 

.............karşıma dikilen Kâbe’yi göremedim. 

.............Allah’ım bana Kâbe’yi göster 

.............diyerek tekrar tekbir aldım. 

...............Kâbe hayal meyal göründü. 

..............Allah’ım İstanbul mülkünü 

..............Kâbe ile aramıza sokma, 

.............ben senin rızandan başka 

...............hiçbir şey istemedim, 

...............ne yaptımsa senin rızan için yaptım 

...............diyerek tekbir aldım. 

...............Şükürler olsun Kâbe karşımdaydı. 

................Bu şekilde namazı kıldık.” 

Padişah yoksul ve harap şehrin 

içinden geçerken iliklerine 

işlemiş bir hüzün içindedir. 

Devlet erkanıyla konuştuğu bir gün 

“Dünya devleti müebbet olmaz 

ve cihan-ı fanide kimse baki  kalmaz” 

diyerek hayat felsefesini açıklamış, 

bin yıllık Roma İmparatorluğunu 

yıkarak da milletini

cihangirler sınıfının başına geçirmiştir.', 'Sultan İkinci Mehmet,  bir cihangir,  devrinin fikir aleminde  büyüklüğünü kabul ettirmiş  essiz bir kıymet olmasına rağmen,  elini öpeceği ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":159,"source_url":"https://www.antoloji.com/zy16-feth-i-mubin-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadriye', 'kadriye-muzaffer-erdogan-291xg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'K albimi verdim sana incitmeden bakasın diye

A vare gönlüme sensizlik kaldı hediye

D arılmadım sana darılamam bitanem

R üyalarımda bile eksilmiyor gözlerimde nem

İ   stenmediğm yerde bir saniye olsun duramam

Y oklugun hançer gibi batsada sineme,sensizliğin hayalini bile kuramam

E lveda vefasız sevgili elveda,her şeye ramen bu can sana feda...!', 'K albimi verdim sana incitmeden bakasın diye A vare gönlüme sensizlik kaldı hediye D arılmadım sana darılamam bitanem R üyalarımda bile eksi...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kadriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik bulunursa emek zay olmaz', 'yitik-bulunursa-emek-zay-olmaz-i-lhami-arslantas-8mhxt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fikir vermek ile akıl pay olmaz 

Kendini bul dostum erdemin olsun 

Yitik bulunursa emek zay olmaz 

Erdemi bul dostum her dem’in olsun 

Okumak ve bilmek sabır işidir 

Aklı dengeleyen mihenk taşıdır 

Kitap her insana can yoldaşıdır 

Erdemi bul dostum her dem’in olsun 

Arz eyle halini bildir her zaman 

Dedim ya nefsini öldür her zaman 

Seni sevenleri güldür her zaman 

Erdemi bul dostum her dem’in olsun 

Sahteliğe muazzez olma sakın 

Ne ondan ol nede olasın yakın 

İnsana bir insan gözüyle bakın 

Erdemi bul dostum her dem’in olsun 

Mutluluk yanlıştan dönmektir bazen 

Sevmek sevilmektir, anmaktır bazen 

Nefse hakim olup yenmektir bazen 

Erdemi bul dostum her dem’in olsun 

Der İlhami her şey insana ibret 

Bilenlerden öğren,bildiğin öğret 

Mezarda yaramaz aldığın şöhret 

Erdemi bul dostum her dem’in olsun', 'Fikir vermek ile akıl pay olmaz  Kendini bul dostum erdemin olsun  Yitik bulunursa emek zay olmaz  Erdemi bul dostum her dem’in olsun  Okuma...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yitik-bulunursa-emek-zay-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölükle belendik', 'olukle-belendik-i-lhami-arslantas-x5t4k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölükle belendik 

Yürek bağı sargılı 

………yürümeyi, 

tahta yürüteçle öğrendik 

o anam ki, 

şefkati dünyaya değer 

hon başına, 

toprağa gömerdi bizi 

göbeğimize kadar 

………ekin biçerken 

emzirirdi memelerinden. 

………Ölükle belendik 

yürek bağı sargılı 

………yürümeyi, 

tahta yürüteçle öğrendik 

şefkâte gülüp, 

memeye ağlayarak 

yalın taban, 

ve baldırı çıplak büyüdük 

ayağımıza, 

her diken batışında 

nedeni sorgulayarak 

biz acılarımızla 

acılarımız, 

bizimle büyüdü 

her geçen yıl, 

bir acı bıraktı ardında. 

…….Ölükle belendik 

Yürek bağı sargılı 

………yürümeyi 

tahta yürüteçle öğrendik 

yalın taban, 

ve baldırı çıplak büyüdük 

hayatı çıplak gözle görmeyi 

böyle öğrendik, 

böyle öğrettik bebelerimize…', 'Ölükle belendik  Yürek bağı sargılı  ………yürümeyi,  tahta yürüteçle öğrendik  o anam ki,  şefkati dünyaya değer  hon başına,  toprağa gömerdi...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/olukle-belendik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat bitti sana yanmakla', 'hayat-bitti-sana-yanmakla-mehmet-yilmaz-bulancakli-4gky3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceler hep karanlık,					

Yalnızım sokakta,					

Dertler benim artık,					

Hayatım benden çok uzakta.					

					

Her derde kurban ömrüm,					

Yıllar geçti seni anmakla,					

Çile çektim.neler gördüm,					

Hayatım bitti sana yanmakla.					

					

Geceler hep karanlık,					

Yalnızım şu sokakta,					

Kederliyim ben artık,					

Hayatım bitti sana yanmakla.					

								

Bulancak-GİRESUN-1979-Turkuaz					

2004-Temmuz', 'Geceler hep karanlık,					 Yalnızım sokakta,					 Dertler benim artık,					 Hayatım benden çok uzakta.					 					 Her derde kurban ömrüm,			...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayat-bitti-sana-yanmakla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarım', 'dostlarim-mehmet-yilmaz-bulancakli-1i7jd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geldi Bektaş zamanı,					

Kalkın gidelim dostlar,					

Şimdi şenlik zamanı,					

Toz duman olsun yollar.					

					

Özledim suyunu,etini,					

Canını sevdiğim memleketini,					

Boşuna çekermiyim zahmetini,					

Kalkın gidelim dostlar.					

					

Hava orda,su orda,					

Mis gibi doğayla başbaşa,					

Başın kalmaz hiç darda,					

Kalkın gidelim dostlar.					

								

Bulancak-GİRESUN					

Aydın-15.07.2002', 'Geldi Bektaş zamanı,					 Kalkın gidelim dostlar,					 Şimdi şenlik zamanı,					 Toz duman olsun yollar.					 					 Özledim suyunu,etini,			...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dostlarim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginle sarhoş et dil ile öldür', 'sevginle-sarhos-et-dil-ile-oldur-i-lhami-arslantas-p3gkh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim avucunda canını sunan 

İçimde mor alev yar diye yanan 

Gönlüme yarensen billahi inan 

Sevginle sarhoş et dil ile öldür 

Sevdanla yanıyor susuzum susuz 

Baş yastıkta gözüm sana uykusuz 

Yaşasa ne olur bu ser duygusuz 

Gönder  sahralara yarim çöl ile öldür 

Önce bağrına bas ne diyor yürek 

Giderim ölüme on kez gülerek 

İstersen al getir bir kazma kürek 

son kez sual edip bel ile öldür 

Onca yıldır bana can ortağımsın 

Kanımız karıştı kan ortağımsın 

Bu günlük burada gün ortağımsın 

As bir gül dalına tel ile öldür

 Onca yıldır bana can ortağımsın 

Kanımız karıştı kan ortağımsın 

Bu günlük burada gün ortağımsın 

As bir gül dalına tel ile öldür 

Der İlhami etme istersen niyaz 

Ben gidince açıl kızıl,mor,beyaz 

Gel akşam üzeri düşünce ayaz 

Saçın dan bir belik kıl ile öldür', 'Benim avucunda canını sunan  İçimde mor alev yar diye yanan  Gönlüme yarensen billahi inan  Sevginle sarhoş et dil ile öldür  Sevdanla yanıy...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevginle-sarhos-et-dil-ile-oldur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke demeyeceksin! ..', 'keske-demeyeceksin-cemal-nalci-ipxu5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'süeda’ya

keşke demeyeceksin! .. 		

belki gözlerinle konuşacaksın

ama,

     göz yaşların sende kalacak…

ümitlerin hayallerin olacak

niye,

kime olduğunu bileceksin

varılmaktan korkulan hedeflere

kırmaktan,

kırılmaktan da korkmayacaksın...

belki anılar kalacak seninle

sakladığın göz yaşlarınla 

paylaşacaksın! ..belki de…

yaşlı gözlerinle

		dönüp baktığında

		masanın üzerinde bir tepsi

		tepsinin içinde bir pirinç tanesi 						göremiyorsan...

“keşke” demeyeceksin! ..

belki de bir balık olacaksın

		yakamozların arasında

		dalgalarla dans edeceksin

				mehtaba karşı...

ancak biraz ötende

		bir olta,

		bir ağ,

		tirol ya da

		yaşamınla kol kola…

ya da kumsal olacaksın

yağmuru,

	güneşi göreceksin...

ıslak,

	yalın ayaklarının her dokunuşunda 

	başka bedenlere kum olacaksın

ve dönüp baktığında 

“ölü balıklar kumlanmıyorlarsa seninle! ”

“keşke” demeyeceksin...

...

ve yapraklar dökülecek

	sarardıkça 

		tek tek...

baktıkça...

	baş başa olacaksın çizdiklerinle...

ya da,

	tahterevalli olacaksın

	birer çocuk uçlarında

	birinin adı sevi

	yürek olacak diğeri

		senden birer parça...

	birer birer havalandıracaksın

	uçuracaksın güvercinlerle

	yıldızlara salacaksın

		ulaşılmaza belki...

yine dönüp baktığında; 

	yaşanmamışın acı pişmanlığı

	bir bedel olacak göz yaşlarında…

keşke

9712222020

cemalnalcı', 'süeda’ya keşke demeyeceksin! .. 		 belki gözlerinle konuşacaksın ama,      göz yaşların sende kalacak… ümitlerin hayallerin olacak niye, kim...', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/keske-demeyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni kendimi sevememenin acısıyla sevdim! ..', 'ben-seni-kendimi-sevememenin-acisiyla-sevdim-cemal-nalci-o4xov', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ay parçasına...

ben seni,

	kendimi sevememenin

		acısıyla sevdim...

gece maviliklerini verdim gündüzlerine

ay pencerende,

	güneş gözlerinde saklı

sen,

	bende taşıdığım bir yürek...

ben seni,

	kendimi sevememenin 

			acısıyla sevdim...

bu gün; 

	şimdi,

	sahillerime gelen bu dalgalara

	atıyorum anılarımı

	al götür diye

	dalgalara...

	uzaklara...

	...ta uzaklara...

bu an,

	her an; 

	ne zaman bir maviyi düşlesem...

	ne zaman yumsam gözlerimi

			gecenin karanlığına

ya da,

	bir bedene dokunsam

	şehrin tüm ışıkları sönüverir

	kentin ortası ve ben

	kentin ortasında 

		sen gelirsin aklıma...

ben seni,

kendimi sevememenin 

acısıyla sevdim...

pervasız,

	kural tanımaz,

			uslu...

kaybetmenin direngenliğinde

				kararlı...

...

gecelerden bir gece

		sahillerimizde

yakamozları  seyrederken

	ay gitmek istemedi	...

bu defa,

	dalgalara apansızca gidiverdi

					damlacık

	dalgaların kucağına

	özgürce süzüldüler...

	...ve şıpladılar

	dalgaların  kucağına 

			damlacıklar...

dalgalar,

	yaklaştıkça büyüdü

	büyüdü damlacıklarla

	kayaları aştı

		bir bütün

sahillerime ulaştılar

	sahil ve ben

		ıslak

		...ve yapayalnız...

...

sonra,

	duruldu dalgalar

	damlacıklar duruldu

sahil 

	süt liman

ve ben,

	geçmişi 

		geleceğe bütünledim

		yaşanmamışı ekledim

					sevilerime...

ben seni,

	kendimi sevememenin

			acısıyla sevdim.

ben seni kendimi sevememenin 

acısıyla sevdim

9808211747c

cemalnalcı', 'ay parçasına... ben seni, 	kendimi sevememenin 		acısıyla sevdim... gece maviliklerini verdim gündüzlerine ay pencerende, 	güneş gözlerinde ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/ben-seni-kendimi-sevememenin-acisiyla-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
