INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma.', 'korkma-i-shak-ozlu-qra3p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Suya sabuna dokunma demiş,

Demişte acep iyimi etmiş.

Gözümüze baka baka çalıyorlar,

Sanırım bu sözün ömrü bitmiş.

Bu deyimin üzerini çizmeli.

Deyimler üzerinde bir gezmeli.

Suyada dokun,sabuna da.Korkma,

Korkmadığını korkak gayri sezmeli.', 'Suya sabuna dokunma demiş, Demişte acep iyimi etmiş. Gözümüze baka baka çalıyorlar, Sanırım bu sözün ömrü bitmiş. Bu deyimin üzerini çizmeli...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korkma-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yurdun Mu?', 'senin-yurdun-mu-zulfikar-yapar-kaleli-n0tb6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seyir makamından doğrul bak Fatih

Allah''a inanan kul karalanır! 

Bu ruhla mı gerçekleşti o fetih? 

Yalan, dolan,  fitne,  şer sıralanır! 

Hakanlar hakanı dinle ne olmuş

Yobazlar her şeye bir kılıf bulmuş

Senin fikirlerin zindana dolmuş

Ne açılır kapı,  ne aralanır! 

Bir kez n''olur, bir kez doğrul mezardan

Bak eser kalmış mı namustan, ardan? 

Yeninin aşığı,  koca kumandan

Sizlere sevdalı yol paralanır! 

Hep arzu edilen ''Avrupa tipi''

Kimse dinlemiyor artık hatibi

Sokaklar hep mezat,  mezbaha gibi

Utanmaz, arlanmaz hal yaralanır

Kaleliyim sızılıyor her yanım

Türk demekten korkar olduk hakanım

“Fetih ruhu” çoktan öldü  sultanım

Millet oyalanır,  yurt oyalanır 

                                               1 mayıs 1990', 'Seyir makamından doğrul bak Fatih Allah''a inanan kul karalanır!  Bu ruhla mı gerçekleşti o fetih?  Yalan, dolan,  fitne,  şer sıralanır!  Ha...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senin-yurdun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldirimlar', 'kaldirimlar-halime-vatansever-wie77', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaldirima usul usul 

Dusuyordu kar taneleri

Yolu gormedim 

Kaldirimlardi gozumun onundekiler

Bulusmak icin sozlestigimiz kaldirimlar...

Biri gecti kaldirimdan

Uzun aba mantosu vardi

Kipkirmiziydi yuzu

Soguktan

Isinacak bir yer ariyordu

Kaldirima piril piril 

Geliyordu gunes isinlari

Yolu gormedim

Kaldirimlardi 

Gozumun onundekiler

Biri gecti kaldirimdan

Uzun sari saclari vardi

Kipkirmiziydi yuzu

Sicaktan

Golgelik bir yer ariyordu

Ardindan  bir golge gecti

Bu kaldirimdan

Sanssizdi kaybetmisti sahibini

Kendine sahip olmayanin 

Golgesi nasil olsun ki

Yoksullar aclar aciklar kurk mantolu kadinlar

Gecti bu kaldirimdan

Mevsimler golgeler golgesizler gecti

Bir sen gecmedin 

Dort gozle bekledigim', 'Kaldirima usul usul  Dusuyordu kar taneleri Yolu gormedim  Kaldirimlardi gozumun onundekiler Bulusmak icin sozlestigimiz kaldirimlar... Biri...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kaldirimlar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir', 'bir-halime-vatansever-unpsu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni severken 

Her yerde seni gordum

Sigaramin dumaninda

Yemek yerken catalimin ucunda 

Su icerken

Dudagimin bardaga degen kisminda

Aynaya bakarken 

Kendi gozlerimin icinde bile seni gorurdum

Denize baktigimda en siddetli dalga

Sen olurdun benim icin

En hareketli marti sen olurdun

Havaya baktigimda 

En belirgin bulut sen...

Senin anlayacagin

Istanbul''a baktigimda

Bogazlar olurdun

Isparta''ya baktigimda gul olurdun 

Gulum

Sense o kadar yakininda olmama ragmen

Basini cevirip yuzume bile bakmazdin

Beni bende bile gormezdin

Bir esyaya baktiginda 

Sanki neye baktigini

Bilmezmis gibi umursamaz bakardin

Sonra senin askindan ben 

Her seyi bos gorur oldum 

Yani

Bir zamanlar her sey sendi benim icin

Sonra ben sen oldum', 'Seni severken  Her yerde seni gordum Sigaramin dumaninda Yemek yerken catalimin ucunda  Su icerken Dudagimin bardaga degen kisminda Aynaya b...', ARRAY['Türk Edebiyatı','Şiir','Halime Vatansever']::text[], 8.5, '{"poet":"Halime Vatansever","poet_slug":"halime-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız', 'anlamsiz-sadik-dursun-6pyah', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeniden,

Bir karanlık sokağa doğru,

Yürüyorum, anlamsız.

Çaresizliğimde,

Kaçarken senden,

Ağlıyorum, anlamsız.

Bak! hayalim yine,

Seninle başladı.

Aldırmadan terkedilmişliğime,

Yapayalnız,

Bir rüya gibi seni,

Görüyorum, anlamsız.

Bu gözyaşı, göremediğin,

Bu haykırış,

Duyamadığın ben.

Ben sana uzak, sana ıssız; 

Sende yitirdiğim aşkı,

Arıyorum, anlamsız.

22 Mayıs 2005 TURHAL', 'Yeniden, Bir karanlık sokağa doğru, Yürüyorum, anlamsız. Çaresizliğimde, Kaçarken senden, Ağlıyorum, anlamsız. Bak! hayalim yine, Seninle ba...', ARRAY['Türk Edebiyatı','Şiir','Sadık Dursun']::text[], 8.5, '{"poet":"Sadık Dursun","poet_slug":"sadik-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anlamsiz-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
