INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi İğneli Fıçım', 'kendi-i-gneli-ficim-sair-morris-rczje', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum, hiç bir zaman yapamadığım kadar,

Kendimi anlıyorum, hep istediğim gibi,

Yazıyorum, gerçek şairlere inat,

Yorumluyorum anlamsız hayatımı,

Yoruluyorum, yorumsuz daha güzel.

Kuşları duyuyorum, dikkat dağıtıyorlar,

Baharı farkediyorum, mutlu etmekten aciz,

İnsanlar, kuşlar gibi bahar gibiler.

Bana baharı anlatmak için bir insan yaklaşıyor,

Savıyorum başımdan,

Bir gün bir kuş yaklaşsa,

Hayatta samimi bir şey gördüğüme sevinirim,

 Ama hiçbiri anlatmıyor,

Ben kendime işkence ediyorum,

Kendi iğneli fıçımda

Kan kaybından ölüyorum.', 'Düşünüyorum, hiç bir zaman yapamadığım kadar, Kendimi anlıyorum, hep istediğim gibi, Yazıyorum, gerçek şairlere inat, Yorumluyorum anlamsız ...', ARRAY['Türk Edebiyatı','Şiir','Şair Morris']::text[], 8.5, '{"poet":"Şair Morris","poet_slug":"sair-morris","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kendi-igneli-ficim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardayım', 'uzaklardayim-muzaffer-erdogan-jesdb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birgün özlemle beni andığında

Kalbindeki  acının ben oldugunu sandığında

Çagırma sevdiğim hasretimle yandığında

Gelemem  ben çok çok uzaklardayım

Hasretin beni yaksa kavursada

Çölde esen rüzgar gibi  savursada

Üzülüp aglama  birtanem

Gelemem ben çok çok uzaklardayım

Bensizlik ruhuna hasretle dolsada

Gelişim esaretten kurtuluşun olsada

Bağlarında acan  güllerin solsada

Gelemem birtanem ben çok uzaklardayım

Aşkımız sığmazdı bizim dağlara taşlara

Yazık etme sevdiğim gözünden akan yaşlara

Nice vurulanlar olur sendeki kalem kaşlara

Gelemem birtanem  ben çok çokuzaklardayım

Benden sana hatıra olarak kalsın mazide yaşanan

Beni daima mutlu hatıralarımızla  an

Dönecegim sana birgün göçmeden bu dünyadan

İstesemde gelemem  ben çok çok uzaklardayım...!', 'Birgün özlemle beni andığında Kalbindeki  acının ben oldugunu sandığında Çagırma sevdiğim hasretimle yandığında Gelemem  ben çok çok uzaklar...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzaklardayim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüktün Nokta Gibi Bende,Şimdi Bir Nokta Gibisin İçimde', 'buyuktun-nokta-gibi-bende-simdi-bir-nokta-gibisin-i-cimde-cansin-unver-ihyz8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BÜYÜKTÜN NOKTA GİBİ BENDE, 

ŞİMDİ BİR NOKTA GİBİSİN İÇİMDE. 

Beynimin her noktası, 

Yüreğimin nokta nokta atışı. 

Noktaydın ''Seni seviyorum''un sonunda 

Yakamoz ışıltısında sesimin 

Göremezken senden başka bir şey 

Noktaydı gözlerimde her şey. 

Sevdamı açıklar, duygularımı tanımlarken 

İki noktam. 

Seni seviyorum: 

Bir çocuk gibi, 

Bir dost gibi, 

Sana yar gibi. 

İçim ürperir heyecandan 

Soluğum yetmez, 

Cümlelerim bitmez 

Üç noktam... 

Söze ne gerek sevdiğim; 

''Sen sus gözlerin konuşsun...'' 

Söylenmeden geçen sözlerimiz, duygularımız 

Sıra noktam.............. 

Ve şimdi 

Gidiyorsun. 

Çok şey demek istiyorum 

Ama 

Söylenmeden geçen cümlelerimin sonundasın 

Sıra nokta................. 

Ve şimdi 

Gidiyorsun 

Boğazıma düğümlenen, 

Tamamlayamadığım cümlelerimin sonundasın 

Üç nokta... 

Gitme: 

Seni seven çocuk ölür, 

Dost ölür, 

Sana yar ölür 

Açıklamalarımın sonundasın 

İki nokta. 

Gittin 

Nokta. 

Her şey yalan, görmek istediğimiz gibi mi yoksa 

Sevgiler, aşklar 

Nokta. 

İki nokta: 

Üç nokta... 

Sıra nokta........ 

Ayrılışlar, acılar 

Sıra nokta........ 

Üç nokta... 

İki nokta: 

Nokta.', 'BÜYÜKTÜN NOKTA GİBİ BENDE,  ŞİMDİ BİR NOKTA GİBİSİN İÇİMDE.  Beynimin her noktası,  Yüreğimin nokta nokta atışı.  Noktaydın ''Seni seviyorum''...', ARRAY['Türk Edebiyatı','Şiir','Cansın Ünver']::text[], 8.5, '{"poet":"Cansın Ünver","poet_slug":"cansin-unver","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/buyuktun-nokta-gibi-bende-simdi-bir-nokta-gibisin-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Veda...', 'bir-garip-veda-emine-deniz-a10hd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '__Kanımı akıtmak için geldin kapıma...Biliyorum....Hep kıskandığım aşklara  inat,son bir gayretle sarıldım sana.Kelimelerini düşürdün omuzlarıma.O kadar ağırdı ki satır araların kelimelerini taşıyamazken seni nasıl taşırdım söylesene...Bana gitmek düştü sevgili.Şiirlerim kadar cesur değilmişim affet beni..

...

Sustuğumuz yerde başlar ayrılık

Gönül çukurundan dört yol ağzına

Bakmaz parmaklardan kan aktığına

Kokar yalvarışlar ayak altında

Giden gitmiştir oysa...

Ah

Sen bilmezsin nasıl yıkılır duvarlar insanın üstüne

Perdeler nasıl kapanır utancın yüzsüzlüğüne

Sen 

Bileklerinde parlayan gözyaşlarını silmeye çalışan çocuk

Ağlama 

Biz bu hikayeyi defalarca okuduk...

Ah 

Sen bilmezsin

Ne büyük rezilliktir kirletmek kendini

İhanet sokaklarında dilenmek kirletir en çok sevgiyi

Zehir kokar sabahlar

Ne kadar yıkarsan yıka çıkmaz lekesi karanlığın

Tutma çocuk

Sen de kirletme ellerini

Ah 

Nabzımda atan,kanımda parlayan 

Dudaklarımda patlayan mavzer

Vefa kaç dolar bugün

Aşk kaç euro ediyor

Serseri akşamlarda,asalet eziliyor...', '__Kanımı akıtmak için geldin kapıma...Biliyorum....Hep kıskandığım aşklara  inat,son bir gayretle sarıldım sana.Kelimelerini düşürdün omuzla...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-garip-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'U m u t', 'u-m-u-t-muhammet-faruk-koca-3b2vm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitmeyen hayallerimin ardınca ağladım bulunması güçtün sen, 

Geceler boyu kapanmışçasına secdeye, 

Allah’ım isyanım sana değil kendime, 

İlk gözlerim kavuştu sonraysa ellerim, 

Ardınca geliverdi boşaldı her şey, 

Sora kalbim, 

Gam vuruldu bir ilkbahar akşamında, 

Yokluktan çıka gelen bir adam, 

Bir tohum bıraktı avuçlarıma, 

Dizilen kelimeler boğazıma, 

Oğul sevgidir bu tohumun adı, 

Büyüyüp bir fidan olacak elbet, 

Sorarsa bir çınar, 

Yüreğini vereceksin ona, 

Su gibi sevgi besleyeceksin ona, 

Dedi bana ihtiyar adam sonra kayboldu, 

Göz gözü görünmeyen o sisli havada, 

Tohum büyüdü bir çınar oldu, 

Sonra dalları kurudu, 

Anlam veremedim, 

On beş yıl geçti aradan 

Ve yine o adam, 

Çıkmıştı ağacın kavuğundan, 

Oğul dedi can dedi sevdiğin dedi, 

Bu ağaçta gizlidir dedi, 

O gün anlamıştım her şeyi, 

Koştum koştum koştum kaybolmuştum, 

Uyandım bir garip diyardayım, 

Saçımı okşayan bir el, 

Gözlerimi açtım, 

Sevgiliye kavuşmuştum. 

(08.11.1999)', 'Bitmeyen hayallerimin ardınca ağladım bulunması güçtün sen,  Geceler boyu kapanmışçasına secdeye,  Allah’ım isyanım sana değil kendime,  İlk...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/u-m-u-t-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece kararınca', 'gece-kararinca-evren-dalgic-kdx6y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece kararınca yüreğinde

Yazıklar olunca o yetim hayallere

Bir parça geleyim aklına.

Bir parça; 

Beni düşün düşüncelerin arasında

Karmaşık değil aslında

Sade düşün

Beyaz ve narin düşün düşlerimi

Yanıkça düşün her değdiğinde

Ellerinle yüreğimi.

Gece kararınca bir nebze gözlerine

Ve oltaya düşünce o safça hayaller

Bir türkü gibi sızlasın azabım içimde

Yalnızca kal

Hoşça kal düşlerimin yangını

İçimde 

İçimde bir hayal öldü.

İçimde bir tane daha ben öldü bugün.

Laleler gibi solduğum şu anda

Odamda senin dışında sadece üzgün bir hüzün

Yorgun benim artık

Sazımda inceden bir kırgın düş

Olsa da olur bir benliğim gayrı

Aşka aşk demeyen bir yürek,

Solmuş gözlerimin o ahenkli ışığı.', 'Gece kararınca yüreğinde Yazıklar olunca o yetim hayallere Bir parça geleyim aklına. Bir parça;  Beni düşün düşüncelerin arasında Karmaşık d...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gece-kararinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Dünya', 'yalan-dunya-muhammet-faruk-koca-jlnvw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlıklara çıkmasın yolun, 

İçimde ki korkuları alda git, 

Bir sevdadır bu bende kalan, 

Ne bir anı ne bir hatıra, 

Bırakmadan git gide bilirsen, 

Bana söylenmedik bir söz, 

Bir hicranlı hançeri bağrıma vur da git, 

Git gide bilirsen, 

Yalnızlıklara çıkar yolum, har gidişinle, 

İçimden bir şeyleri koparıp götürürsün, 

Meçhule giden bir tiren gibi, 

Bilemesin bende olan kaderi, 

Tulupta kaldır beni, 

Gör o zaman sensiz kalan çaresizliği, 

Derdimi anlatırım boş duvarlara, 

Ekipte sigaramı derin derin, 

Bir duman alırım içime, 

Kendimi öldürürcesine, 

Kendimi kaybeder gibi öylece başı boş, 

Kumsallara çıkar yolum hep, 

Seni anlatırım kumsallara, 

Çizerim kendi aklımca seni denizlere, 

Gel yaralım kara gözlüm, 

Ayrı düştük yaralıyım, 

Biz bu derde nasıl dayanalım, 

Her gece düşümde seni aradım, 

Sayıkladım adımı ecel gel ipte alsın diye, 

Vurgun düştüm güne, 

Uyandım sensiz bir sabaha, 

Sensiz ser hoş bir suçlu gibi, 

Uzatıp ellimi gök yüzüne, 

Dilendim seni senden, 

Yazımızı yazan kalem, 

Har şey yalan yalan, 

Şu yaşama hevesimi, 

İnsanlığın sahte yüzünü görgümde anladım ki, 

Hepsi yalan sen yalan dünya yalanmış yalan. 

(05.11.2003)', 'Karanlıklara çıkmasın yolun,  İçimde ki korkuları alda git,  Bir sevdadır bu bende kalan,  Ne bir anı ne bir hatıra,  Bırakmadan git gide bi...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yalan-dunya-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AŞK ın tarifleri; ;', 'ask-in-tarifleri-hamiye-alkis-qr0o0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ateşe benzetiyorum aşkı; 

Alev alev yakamozlarla yanan,

Yaklaşınca ılgıt ılgıt ısıtan,

Değdiğinde acı acı sızlatan.

Bulutlara benzetiyorum; 

Ufuklarda narin narin dolaşan,

Gölge gölge serinleten,

Çarpışınca fırtınalar koparan.

Mermere benzetiyorum; 

İşlenince biblö olan, süs olan,

Fırlatınca kaya olan, taş olan.

Mermiye benzetiyorum; 

Ergiyince metal olan, has olan,

Silahlarsan acımadan can alan.', 'Ateşe benzetiyorum aşkı;  Alev alev yakamozlarla yanan, Yaklaşınca ılgıt ılgıt ısıtan, Değdiğinde acı acı sızlatan. Bulutlara benzetiyorum; ...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-in-tarifleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyma felek kıyma unufağım ben,', 'kiyma-felek-kiyma-unufagim-ben-hamiye-alkis-llk1i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yapma felek yapma, varamıyorum

Anlamsız dünyada, yaşamıyorum.

Kuşlar bile yuvada susmuş

Derlenip toplanıp gelemiyorum.

 

Ümit bahçem vardı, ekini solmuş.

Bu güzel dünyada daha nem kalmış.

Kıyma felek kıyma unufağım ben,

Derlenip toplanıp gelemiyorum.', 'Yapma felek yapma, varamıyorum Anlamsız dünyada, yaşamıyorum. Kuşlar bile yuvada susmuş Derlenip toplanıp gelemiyorum.   Ümit bahçem vardı, ...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kiyma-felek-kiyma-unufagim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaklım Benim', 'yasaklim-benim-nedim-saatcioglu-w2v6g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bahara ulaştım senin yanında

Güneş görmüş kar misali eridim

Mutluluk deminin son zamanında

Hoş geldin gönlüme yasaklım benim

Kısanın uzunda hakkı yok artık

Siyahın beyazdan farkı yok artık

Acının ruhumda şavkı yok artık

Hoş geldin gönlüme yasaklım benim

Tanrı’dan kalbime verilen maruf

Yazgımdan ömrüme sunulan matuf

Alın yazımdaki en büyük lütuf

Hoş geldin gönlüme yasaklım benim', 'Bahara ulaştım senin yanında Güneş görmüş kar misali eridim Mutluluk deminin son zamanında Hoş geldin gönlüme yasaklım benim Kısanın uzunda ...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasaklim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyuyan Güzel', 'uyuyan-guzel-kemal-cakir-3r3cj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak bahçede güller,

Ağaçlarda kuşlar,

Gökte bulut, yerde ona hasret var.

Ama sen hala uykudasın.

Umut katmer- katmer toprakta,

Sevgi yumak -yumak gönlümde.

Dışarıda yağmur yağmakta 

Ama sen hala uykudasın.

Yemyeşil  vadi, masmavi göl,

Gölde alabalık,

Mangalda köz hazır.

Çiçek, kuş, sevgi, umut, 

yağmur, balık! 

Ama sen hala uykudasın.

			Temmuz 1988', 'Bak bahçede güller, Ağaçlarda kuşlar, Gökte bulut, yerde ona hasret var. Ama sen hala uykudasın. Umut katmer- katmer toprakta, Sevgi yumak -...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uyuyan-guzel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-murat-senel-of45w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ahınmı tuttu sevgilim? 

Sokaklar çıkmaz oldu, 

Sesler duyulmaz, 

Umutlar yeşermez, 

Güller açmaz oldu. 

Benmi dedimki sana beni unut diye 

Bu sensizlik bu ayrılık niye 

senden uzak şimdi 

Bu günler geçermi 

Geceler acımasızca çöküyor üstüme 

Bilmemki yüreğin affedermi. 

Desemki gel bırakma 

Yaram sızlıyor açma kanatma, 

Bu yalnızkta boğuluyorum beni unutma 

Gül dudakların evet dermi. 

Sönük ateşi küllendirmek zor 

Ölü aşk diriltilmez  biliyorum 

Hani sihirli aşkımız vardı 

Yüreklerimizi çoşturan sevgimiz 

Olur ya umut ediyorum. 

Ne desem sanırım nafile, 

Duyuyorum sesini olmaz diye: 

Ne sevgi ne aşk ne bir şiir 

Diriltemez bu harabeyi 

Ne de bir tek kelime 

Sesziyorum ben gibi 

Bu sözleri söylerken 

Seninde yüreğin incir.', 'Ahınmı tuttu sevgilim?  Sokaklar çıkmaz oldu,  Sesler duyulmaz,  Umutlar yeşermez,  Güller açmaz oldu.  Benmi dedimki sana beni unut diye  B...', ARRAY['Türk Edebiyatı','Şiir','Murat Şenel']::text[], 8.5, '{"poet":"Murat Şenel","poet_slug":"murat-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/neden-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu meydan boş değildir', 'bu-meydan-bos-degildir-mikdat-bal-2ee60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu meydan boş değildir, biz varız çiğnetmeyiz

Bir kaç tane kargaya hele hiç pes etmeyiz

Vakti geldiği zaman, olur olmaz ötmeyiz

Onların suratına tükürmek bir zahmettir

Hoşlarına da gider, onlar için rahmettir

Göz göre Kıbrıs gitti, sıra soykırımında

Ecdadım yargılandı, bir sanık durumunda

Ben böyle fikirlerin, böylesi yorumunda

İçine tükürüşüm, benim için zahmettir

Onlar bundan hoşlanır, onlar için rahmettir

Memleket adım adım, kayıyor kaymaktadır

Misyonerler sinsice dinini yaymaktadır

Bir taraftan rantçılar, ülkeyi soymaktadır

Tükür,bir daha tükür, ancak boşa zahmettir

Onlar bundan hoşlanır, onlar için rahmettir

Ne oldu böyle bize, uysal olduk bir anda

Aydınlar ki sustular, gizli bir sır var bunda

Dış mihraklar durmuyor, iç düşmanlar bir yanda

Bunların suratına, tükürmek bir zahmettir

Onlar bunu istiyor, onlar için rahmettir

Sövene misli ile sövmek caiz o kadar

Eşek inat ederse, dövmek caiz o kadar

Bu yolda caht edeni övmek caiz o kadar

Tükürmek bizim için, hem ayıp hem zahmettir

Çünkü faydası olmaz, onlar için rahmettir', 'Bu meydan boş değildir, biz varız çiğnetmeyiz Bir kaç tane kargaya hele hiç pes etmeyiz Vakti geldiği zaman, olur olmaz ötmeyiz Onların sura...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-meydan-bos-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-murat-senel-3oqod', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yorgun bir yağmur altında 

Ayrılığın sesini çıkarırken ayaklarım 

Hıçkırırksız ağlayan göğün gözyaşlarına 

Karıştı iki damla yaşım. 

Adını sayıklıyor şimdi dudaklarım 

Bulutlar hasreti olduğum yüzünün şeklini almış sanırım, 

Yürüdüğüm yollar sana çıkar diye 

Kanayan yüreğimi aldatırım. 

Bilsem ki ölüme koşmak günah değil, 

Hazır, kurgulanmış beynimde intiharım. 

Yılgın bedenim dayanamaz sonuna değin, 

Yaşadıklarımızın yalan olmasından korkarım.', 'Yorgun bir yağmur altında  Ayrılığın sesini çıkarırken ayaklarım  Hıçkırırksız ağlayan göğün gözyaşlarına  Karıştı iki damla yaşım.  Adını s...', ARRAY['Türk Edebiyatı','Şiir','Murat Şenel']::text[], 8.5, '{"poet":"Murat Şenel","poet_slug":"murat-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmur-185-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tütünname', 'tutunname-abdullah-oztemiz-gos5o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tütünname

Sık sık tüter bir an gelir

Can ülkesinden can gelir

Tiryakiler tüttürmese

Tüm bir cihan zindan gelir

Farz et ki borç altındasın

Derdin tasan ondan gelir

Efkar basar birden bire 

Tellendirirsin yan gelir

Osman gelip! (yak)  der sunar

! (Yak)  der sunar Orhan gelir

Turgut gelip! (yak)  der sunar

Yak der sunar Turhan gelir

Bir Bafra derken bir Hisar

Samsun gelir,Harman gelir

Farz et tütün en baş ürün

Farz et ki yurdundan gelir

Sanmam ki gelsin bir yarar

İçtikçe burnundan gelir.

Abdullah Öztemiz Hacıtahiroğlu

  Yeni İstiklal gazetesinde 1967 de yayınlanmıştır.', 'Tütünname Sık sık tüter bir an gelir Can ülkesinden can gelir Tiryakiler tüttürmese Tüm bir cihan zindan gelir Farz et ki borç altındasın De...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztemiz']::text[], 8.5, '{"poet":"Abdullah Öztemiz","poet_slug":"abdullah-oztemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tutunname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısık Lamba', 'kisik-lamba-abdullah-oztemiz-svnst', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KISIK LAMBA

                                Beğenir sever sıradan sözü

                                Dışa aldanan özü kavramaz

                                Kim alışsa beylik ucuz söze

                                Alışılmamış sözü kavramaz

Kısılınca lamba sönük gibi

Üşüşür karaltı sülük gibi

Dayanıklı söz katı olsa da 

Yumuşak olur öpücük gibi

Yanaşır mı ölçüye her kişi

Biner ölçü sırtına yük gibi

Bileğimde bir bilezik aruz

Hece parmağımda yüzük gibi

Ateşim su verdi çeliklere

Demir işledim Karabük gibi

Bana şi’r olur suyu toprağı

Gezerim bu yurdu yörük gibi

Kalemim kabuk değil öz sunar

Sözüm oldu şi’re tüzük gibi

Ölü duydu bir gece şi’rimi

Soluk aldı verdi körük gibi

Kavalım yanık havalar çalar

Doludur havayla köpük gibi.

Abdullah Öztemiz Hacıtahiroğlu.

   Kardelen dergisinde 1988 yılında yayınlandı.', 'KISIK LAMBA                                 Beğenir sever sıradan sözü                                 Dışa aldanan özü kavramaz            ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztemiz']::text[], 8.5, '{"poet":"Abdullah Öztemiz","poet_slug":"abdullah-oztemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kisik-lamba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşı Karşıya', 'karsi-karsiya-abdullah-oztemiz-qhgvi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KARŞI KARŞIYA

Mavnalar sandala karşı

İncelik hantala karşı

Ak köpük şarkısı söyler

Dalgalar kumsala karşı

Yüreğim bir sıcak eldir

Isınır mangala karşı

Verelim el ele artık

 Dal uzansın dala karşı

Gece göz kırpar uzaktan

Adalar, Kartal’a karşı

Geçtiğin yolda gözüm hep

Pencerem var yola karşı

  Abdullah Öztemiz Hacıtahiroğlu

   2001 İslami edebiyat dergisi.', 'KARŞI KARŞIYA Mavnalar sandala karşı İncelik hantala karşı Ak köpük şarkısı söyler Dalgalar kumsala karşı Yüreğim bir sıcak eldir Isınır man...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztemiz']::text[], 8.5, '{"poet":"Abdullah Öztemiz","poet_slug":"abdullah-oztemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karsi-karsiya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Sarılması', 'sair-sarilmasi-kemal-cakir-k0z8o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok uzaklardan gülüyorsun bana

Belki bulutlardasın belki de ayda

Sanki şair sarılmış sana

Renk-renk çiçekler var kucağında.', 'Çok uzaklardan gülüyorsun bana Belki bulutlardasın belki de ayda Sanki şair sarılmış sana Renk-renk çiçekler var kucağında....', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sair-sarilmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Odam', 'sensiz-odam-murat-senel-tkifl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir oda ki; sensizliğin sessizliğin kolgezdiği zindan,

Bir oda ki; soyumu soysuzların arasında idrak ettiğim mekan

Ve bir oda ki; aşk yasak, hayal yasak ve ağlamak yasak kesin ferman.

İşte şimdi o odanın bir köşesindeyim,

Senden vazgeçip geçmemenin muhakemesindeyim.

Ama karar vermak zor, 

Hele senden vazgeçmek en zor,

Zor ki; zorluklara anahtar 

İçimi kemiriyor ateşten bir kor.

Yine de sen boşver aldırma

Bu gemi elbet liman bulur,

Aldırıp kalbimi ateşe daldırma,

Gemiyi batırıpta beni limansız bırakma

Ne olur!', 'Bir oda ki; sensizliğin sessizliğin kolgezdiği zindan, Bir oda ki; soyumu soysuzların arasında idrak ettiğim mekan Ve bir oda ki; aşk yasak,...', ARRAY['Türk Edebiyatı','Şiir','Murat Şenel']::text[], 8.5, '{"poet":"Murat Şenel","poet_slug":"murat-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensiz-odam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu Yolunda Gerek', 'yolcu-yolunda-gerek-aysun-erat-gn9jl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düş önüme ey zaman! 

Kovalayacağız seninle,

Yarım kalan düşleri, öpüşleri, gülüşleri…

Yar elinden mey içmeden ölmek yok bana.

Aşktan yana ne varsa birlikte arayacağız

Ve yine,

İhtimal o ki, bulup bulup kaçacağız aşktan.

Pusulaya gerek yok

Gökte Kutup Yıldızı yeter bize

Gümüş ışıkları ay’ın, aydınlatacak önümüzü

Karanlıklarda kaybolmayalım,

Düşüp düşüp kanamayalım diye,

Çocuklar gibi.

Düş önüme ey zaman! 

Beni eğleme işimden gücümden.

Tez vakitte vurmalıyız kendimizi yola,

Varmak için büyük aşka.

Ömür bitip tükenmeden gitmeli,

Yolcu yolunda gerek, eğleme beni.

05/2005', 'Düş önüme ey zaman!  Kovalayacağız seninle, Yarım kalan düşleri, öpüşleri, gülüşleri… Yar elinden mey içmeden ölmek yok bana. Aşktan yana ne...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yolcu-yolunda-gerek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süslü Gazel', 'suslu-gazel-abdullah-oztemiz-6o8v3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Süslü Gazel

Yaz çekti gitti, güz değişik bir bahar açar

Yel kükredikçe dalga denizden tomar açar

Çoktan solup sarardı bağın benzi durmadan

Artık solan benizleri kan yüklü nar açar

Güz, puslu gözgüsünde silik yansıtır göğü

Toprak, solan çiçeklere her gün mezar açar

Salkım söğüt çömelmiş arar yerde bir yitik

Yaprak sanıp boş avcunu dal dal çınar açar

Hırçın yel, uslu dal kapışırlar yalınkılıç

Rüstem bitirse bir savaş, İsfendiyar açar

Güz her dönemde gündeme gelmiş bir öyküdür

Dün Şişli gündem açtı, bu gün Üsküdar açar

Antalya tınmaz, Eskişehir yadsımaz güzü

Çivril kapatsa pencere, Sultanhisar açar

Her telli çalgı tel tel açar sanmayın gönül

Dün bir ud açtı gönlü, bugün bir gitar açar

Her düş, giz ülkesinden açar bir demir kapı

Şâir kapatsa bir kapı, bir bestekâr açar

Dövdükçe tavlanan demir er geç kılıçlaşır

Her kın filizlenip, Ali''den Zülfikar açar

Görkemli şiirimin suyu bol güçlü kaynağı

Her çağda, her dönemde coşan bir pınar açar

Dr. Abdullah Öztemiz

2003 Yağmur Dergisinde yayınlandı.', 'Süslü Gazel Yaz çekti gitti, güz değişik bir bahar açar Yel kükredikçe dalga denizden tomar açar Çoktan solup sarardı bağın benzi durmadan A...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztemiz']::text[], 8.5, '{"poet":"Abdullah Öztemiz","poet_slug":"abdullah-oztemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/suslu-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopyalanmış Hayat', 'kopyalanmis-hayat-atilla-guler-nm2cy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yersiz bir fırtınada yelken açan geminin acemi kaptanı

alabora hayatımda hikayelerden alıntı bir keşmekeş

kes/yapıştır

her iç çekişte bir kırılış…bıkkınlığa bir serzeniş daha

susması gereken sözlere

çığlıklarım anlamsız…sessizse sesler

vurduğun her yerde gül bitmiyor

ve her gül biten yere vurmuyor hayat

ılıman bir iklim değişikliğinde bitişi bir şeylerin

numarası yok aldığım cevapsız çağrıların

kumsala iz bırakmış hatalarımdan ders de çıkmıyor

arayan her zamanki gibi yalnızlık

riyakar gün

güneşi sakladı bir yerlerde yine…zil çalıyor

ay da sensiz doğmuyor

…gün tükenmekte', 'yersiz bir fırtınada yelken açan geminin acemi kaptanı alabora hayatımda hikayelerden alıntı bir keşmekeş kes/yapıştır her iç çekişte bir kı...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kopyalanmis-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lahit', 'lahit-kemal-cakir-o5y4o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle donuk ki bakışları

Sanki gözleri bir heykele ait

Ömrü boyunca bütün sırları

Saklamış içinde olmuş lahit.', 'Öyle donuk ki bakışları Sanki gözleri bir heykele ait Ömrü boyunca bütün sırları Saklamış içinde olmuş lahit....', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/lahit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle!', 'soyle-murat-senel-lkyh5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorum:

Uzakta bir yerlerde solunmaktasın,

O yeşil gözlerinle bakınmaktasın,

Titrek ellerine sarılmış şimdi

Sözleşip yüreğinle beni unutmaktasın.

Duyuyorum:

Hasretin yüklü rüzgarlar kulağıma fısıldıyor ismini,

Nefes diye içime akıtyor zehrini.

Seni unutmayı unutmuşken böyle, şimdi

Söyle nasıl unuturum ben seni.', 'Biliyorum: Uzakta bir yerlerde solunmaktasın, O yeşil gözlerinle bakınmaktasın, Titrek ellerine sarılmış şimdi Sözleşip yüreğinle beni unutm...', ARRAY['Türk Edebiyatı','Şiir','Murat Şenel']::text[], 8.5, '{"poet":"Murat Şenel","poet_slug":"murat-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/soyle-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa Çare', 'yalnizliga-care-kemal-cakir-jr55g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yalnızlık halinde doğmuşsa hisleniş

Son verir bu yalnızlığa Allah’a yöneliş', 'Bir yalnızlık halinde doğmuşsa hisleniş Son verir bu yalnızlığa Allah’a yöneliş...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yalnizliga-care-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Yazıcı', 'kader-yazici-kemal-cakir-qdzzd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her insan kendi kaderini kendisi yazar

Kader yazan birisi yok inan ortada

Dünyalarca var olsa,tükenir azar- azar

Yokla baş başa kalır insan sonunda.

		27.07.2002  didim', 'Her insan kendi kaderini kendisi yazar Kader yazan birisi yok inan ortada Dünyalarca var olsa,tükenir azar- azar Yokla baş başa kalır insan ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kader-yazici-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Assai Zifir(i) Sade(ce)', 'assai-zifir-i-sade-ce-sule-aydemir-5tr81', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '_________________________Kardeşime

zifiri karanlıktı

beyaz tenli

küçük kadın

ışığı yakmadı

uykulu başka küçük

bir fısıltı

aniden bağırdı

-her şeyim sana batmaya 

başladı

beyaz tenli

küçük kadın

bakışlarını kadırdı 

- geç oldu

sana gelirken

anladım

senden giderken de

erken

uykulu başka küçük

bir fısıltı 

büyüdü uyuşuklukla

aldı umursamaz başını

yeni yaktığı sigara ile

uykuya gitti

zifiri karanlıktı

beyaz tenli

küçük kadın

ışığı yakmadı 

yine ağlıyordu 

zifir* gece

sessizce onun yerine

sıvazladı sırtını

gece rüzgarını takıp peşine

diğer geçen geceler gibi

tahammül için

ağladı

sabırla

sade(ce) 

* zifir; çöp, çerçöp, çapak,kir.', '_________________________Kardeşime zifiri karanlıktı beyaz tenli küçük kadın ışığı yakmadı uykulu başka küçük bir fısıltı aniden bağırdı -he...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/assai-zifir-i-sade-ce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kez', 'son-kez-atilla-guler-cvr71', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'son kez 

mutluluk esintisi girmedi daha

evimden içeri

hantal günlerin puslu güneşi

açalyaların açtığı salonumda

hazır bekliyor

tavşan kanı çayımın yanında yalnızlık

yürek yangınlarının közü

bir daha alevlenir mi

bilemem

adını yazdığım defterin sayfaları

arasında kuruyan papatya

yine açar mı

titrer mi yüreğim yine

ellerini tuttuğumda

…bahar yelinde çıkagelsen

bozuk bir plağın takıldığı söz gibi

iltica etti yüreğim

…sana…bir sana

rumuzum yok/sen bilirsin

…ben…benim

- ormanların koyu karanlığında

yakaladım yeşilini sevdanın

rastığını çekmiş ceylan gözlerin derininde

kayboldu hüznüm

otur biraz yanıma sana neler anlatacağım -

sus…dinle… sadece…dinle 

sen bilmezsin ıssız akşamların kuru soğuğunu 

hiç…bilemezsin

unutmak kolay olmadı

dinle…gitmeden…dinle

bak son kez gözlerime

hiç bakmadığınca daha önce

melekler kanatlarını takmış

gelmeden benden yana

son kez…öp

ya da gitme

gidişler öylesi kolay ki

süzülen gözyaşlarının yoğunluğunda kaybolur

aşk

göremezsin', 'son kez  mutluluk esintisi girmedi daha evimden içeri hantal günlerin puslu güneşi açalyaların açtığı salonumda hazır bekliyor tavşan kanı ç...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/son-kez-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak İsterken', 'unutmak-i-sterken-murat-senel-fw8vv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kokuşmuş çamaşırlarım, dağınık odam,

Umarsızca dumanı tüten sigaram

Hepsi şahit, aşikar sevdam

Yanık tütsü gibi kokuyor buram buram.

Başımda yelleri sevdamın,

Üstümde kırışmış yorganım, 

Elimde bitmeye amade kalemim

San veda şiirleri yazarım.

Yorgun başım düşer bir yana,

Ağlıyor gözlerim kana kana,

Uğultusu midemin açlıktan yana

Böyle hazırlanır seni unutmaya.

Aklımda sensiz geleceğin hayali vardır,

Her zaman bir umut vardır,

Bir kapıyı kapayanın başka kapısı vardır

Tek sığındığım Rabbim, tıpkı yıllardır.

Lakin yok ayağa kalkmaya mecalim,

Adını söylemek isterim çıkmaz sesim,

Senden geriye ne bir ses, ne bir resim

Yarım mektup, sensiz şiirlerim.', 'Kokuşmuş çamaşırlarım, dağınık odam, Umarsızca dumanı tüten sigaram Hepsi şahit, aşikar sevdam Yanık tütsü gibi kokuyor buram buram. Başımda...', ARRAY['Türk Edebiyatı','Şiir','Murat Şenel']::text[], 8.5, '{"poet":"Murat Şenel","poet_slug":"murat-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutmak-isterken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül diye yazmış', 'gul-diye-yazmis-tuncay-akdeniz-rh61v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün bana yardan bir name gelmiş 

Mektubun içine gel diye yazmış

Dökmüş yaşlarını kağıt ıslanmış

Gözünün yaşını sel diye yazmış

Yar sensiz neyleyim boş viran bağı

Bülbül gibi olmuş gülün aşığı

Gül yerine koymuş kuru yaprağı

Okusun koklasın gül diye yazmış

Çıkmıyor içimden hasret acısı

Ayrılığın kime olmuş faydası

Yalnız çekilmiyor yarsız sılası

Ayrılık adını yol diye yazmış

Bu Tuncay in senden uzak arası

Senden ayrı koydu beni burası

Senin kalbindeki sevgi yarası

Seviyorum seni bil diye yazmış', 'Bu gün bana yardan bir name gelmiş  Mektubun içine gel diye yazmış Dökmüş yaşlarını kağıt ıslanmış Gözünün yaşını sel diye yazmış Yar sensiz...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-diye-yazmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seli gibi', 'seli-gibi-tuncay-akdeniz-0ypqv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül çağlamış akıyor

Kar suları seli gibi

Aşk ateşi can yakıyor

Mecnunların çölü gibi

Yoramadım rüyasını

Kim yaşamış dünyasını

Aşk yakarsa lambasını

Alev uzar dili gibi

Yandırır ateşe köze

İnandırır tatlı söze

Engel çıkar önümüze

Sarp geçidin yolu gibi

Haktan ara kısmetini

Ferhat sevmişti şirini

Aslı yaktı keremini

Savrulursun külü gibi

Tuncay in var inandığı

Açılmaz gönül sandığı

Olursan dalın konuğu

Sevilirsin gülü gibi', 'Gönül çağlamış akıyor Kar suları seli gibi Aşk ateşi can yakıyor Mecnunların çölü gibi Yoramadım rüyasını Kim yaşamış dünyasını Aşk yakarsa ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seli-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seven bilir', 'seven-bilir-tuncay-akdeniz-milsk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O sevdiğin çiçeklerin

Kokusunu deren bilir

Beşik deki bebeklerin

Sevgisine eren bilir

Dağlardaki kır çiçeği

Kelebek uğur böceği

İbret alın örümceği

İncesini ören bilir

Kanat vermiş uçan kuşa

Gücün yetmez büyük taşa

Kimseyi çıkarmaz başa

Devranını süren bilir

Tuncayım böyle söylerim

Bu dünyayı ben neylerim

Boşuna gönül eylerim

Viranını gören bilir', 'O sevdiğin çiçeklerin Kokusunu deren bilir Beşik deki bebeklerin Sevgisine eren bilir Dağlardaki kır çiçeği Kelebek uğur böceği İbret alın ö...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seven-bilir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader ile yarışamadım', 'kader-ile-yarisamadim-tuncay-akdeniz-jenv3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eller ortak oldu benim derdime

Kader senin ile barışamadım 

Arkadaş bilirdim seni kendime

Ben kendimi sana danışamadım

Akıl erdiremem senin işine

Zorladım şansımı boşu boşuna

Örümcek gibi ağ ördün başıma

Seninle derdimi bölüşemedim

Bana reva gördün derdi kederi

Bana düşman oldun öteden beri

Hangi yola gitsem çevirdin geri

Yendin meydanında yarışamadım

Tuncay-ı inceltin tele çevirdin

İplik gibi iğnelerden geçirdin

Kadehine zehir koydun içirdin

Ben senin huyuna alışamadım', 'Eller ortak oldu benim derdime Kader senin ile barışamadım  Arkadaş bilirdim seni kendime Ben kendimi sana danışamadım Akıl erdiremem senin ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kader-ile-yarisamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşar insan oğlu şaşar', 'sasar-insan-oglu-sasar-tuncay-akdeniz-mkect', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her zorluğa sabır eder

Aşar insan oğlu aşar

Yanılır bilmeze gider

Şaşar insan oğlu şaşar

Akıllıdır gönlü zengin

Gururlanmaz olur engin

Yollar uzun ayak üzgün

Koşar insan oğlu koşar

Dertleri var çeşit,çeşit

Yüklesen götürmez taşıt

Bir dokunsan bin ah işit

Coşar insan oğlu coşar

Beşikten mezara kadar

Örse,örse bitmez duvar

Dağlar kadar yığsa da var 

Düşer insan oğlu düşer

Tuncay kuldur olur muhtaç

Dünya malıdır ihtiyaç

Karnı doysa gözleri aç

Beşer insan oğlu beşer', 'Her zorluğa sabır eder Aşar insan oğlu aşar Yanılır bilmeze gider Şaşar insan oğlu şaşar Akıllıdır gönlü zengin Gururlanmaz olur engin Yolla...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sasar-insan-oglu-sasar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teklif', 'teklif-funda-soylemez-za258', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akıp gidelim yamaçlardan

Geçelim hayatın cilvelerinden beraber

El sallayalım tek tek bıraktıklarımıza

Bir sandalın içinde; 

Bir sen, bir ben

Bir de neşemiz olsun sadece

Şarkılar tüttürelim ard arda

Efkar basarsa yol boyunda

Sen beni sıvazlarsın ben seni

Konuşuruz bol bol; 

Havadan sudan ve gönlümüze dolanlardan.

Sen gülersin hep, ben de izlerim doya doya

Akıp gidelim yamaçlardan

Hava bazen soğuk bazen sıcak

Bazen de yağmurlu

Ne fark eder ki

Islanmak da güzel üşümek de,

Yanımda sen olduktan sonra..

Yolumuz uzun olur

Ve yol boyunca ne sen terk edersin sandalı

Ne de ben

Balık çıkmadığında beraber aç kalırız

Bereketi ikiye böldüğümüz gibi

Belki yolda küçük yeni dostlar bulur bizi

Mesela kızımız olur biri

Yolların bitmesine doğru,

Kızımızı başka bir sandala uğurlamışken,

Sular sığlaşıp, yamaçlar düzlüğe kavuşurken,

Ve artık aşınmışken sandalın boyaları,

Gıcırdarken tahtalar ve ufak ufak su alırken içeri,

Kürek çekmekten yorulmuş kollarımızı sararız birbirimize

Beraber bitiririz bu keyifli yolculuğu,

Türküler bize eşlik ederken

Ne dersin? 

Akıp gidelim mi beraber yamaçlardan? 

(Mayıs 2005)', 'Akıp gidelim yamaçlardan Geçelim hayatın cilvelerinden beraber El sallayalım tek tek bıraktıklarımıza Bir sandalın içinde;  Bir sen, bir ben...', ARRAY['Türk Edebiyatı','Şiir','Funda Söylemez']::text[], 8.5, '{"poet":"Funda Söylemez","poet_slug":"funda-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/teklif-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün Vezirin Neşideleri / I', 'surgun-vezirin-nesideleri-i-bahaettin-karakoc-3brdp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-------------------Ferman Padişah''ın ve mülk de O''nun

* İTİRAF *

Başıma ne geldiyse beyaz sevdamdan geldi

Belki de salt budur sürgünlüğümün gerekçesi

Uyum en gizemli bir ahenktir hayat çalgısında

Ötelerin ötelerine alazlanır

Has sözün çarpıcı dibâcesi

Aşk, amaca götüren en kısa yoldur önümüzde

Bu yolda ne öğrendimse inanınca öğrendim

Zevklendim şu dağ senin, bu dağ benim gezmekten

Uçtan-kıyıdan-kenardan değil

Özümden yanınca öğrendim

Gördüklerimden çoktur göreceklerim

Öğrendiklerimden daha çoktur öğreneceklerim

  * ANLADIM *

(ARANÂĞME) 

Aşkın hem ateş, hem yağmur olduğunu

Kemiklerime kadar ıslanınca anladım

Adildir Padişahım, yan tutmaz, emek yemez

İnanıp erkine yaslanınca anladım

Sınırları karıştırdım deliliğin met çağında

Gerçeği, som gerçeği uslanınca anladım

Fiziğini aşan yanık sesin yeni ufuklara

Nasıl pençe vurduğunu, seslenince anladım

Aşkın fotoğrafı gözlerimde fer/kanat

Yürek sürekli zikir ile beslenince anladım

Yaş dorukta, gönül hâlâ çıktığı yolun başında

Başım dağlar gibi sislenince anladım

 			Bahaeddin KARAKOÇ (Dolunay Yay. 2004)', '-------------------Ferman Padişah''ın ve mülk de O''nun * İTİRAF * Başıma ne geldiyse beyaz sevdamdan geldi Belki de salt budur sürgünlüğümün ...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/surgun-vezirin-nesideleri-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Diye Diye', 'sen-diye-diye-adulera-ayza-j6qfq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başladı yine ayin her zaman ki muhteşemliği ile

Gecenin bir yarısı herkesin kendi dertleri ile

Gecenin en döngüsü ve en zevkleriyle

Geceden ince saz öyle bir yerdeyim ki 

Dostum dostum güzel dostum diye devam eden 

Sevenleri bir kez daha sevmeye mecbur eden duygu ne

Devam eden dizeler de eziyet eder mi seven sevene

Gecenin en zulüm hali dedim ya başladı ayin yine

Çıplağım her zaman ki gibi sendeyim en saf halimle

Kaç kere el açtım yalvardım beni bul diye

Bulmadın hiçbir zaman bulsan

Benim bu yalvarışlarım el açışlarım ne diye

Ölüyorum be aşkım

Sen diye diye', 'Başladı yine ayin her zaman ki muhteşemliği ile Gecenin bir yarısı herkesin kendi dertleri ile Gecenin en döngüsü ve en zevkleriyle Geceden ...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-diye-diye-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eli Hamurlu Şiir', 'eli-hamurlu-siir-bir-mim-kemal-ertugrul-bbko4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duyamıyorum 

Karıcığım 

Anlamıyorum... 

Ne mi yapıyorum? 

Herzamanki işimi elbet..! 

Şairlik ince iş...

Kabuklarını soyuyorum 

Birbir sözcüklerin 

Tıpkı 

Soyduğun gibi 

Ağlayarak soğanı senin... 

Nasıl mı? 

Kusura kalma

Sen anlamazsın karıcığım 

Nasıl ben; 

Hiç anlamıyorsam 

Mutfak işlerinden....', 'Duyamıyorum  Karıcığım  Anlamıyorum...  Ne mi yapıyorum?  Herzamanki işimi elbet..!  Şairlik ince iş... Kabuklarını soyuyorum  Birbir sözcük...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eli-hamurlu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızım için', 'kizim-icin-huseyin-i-rfan-kibrislioglu-dws25', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canım kızım

kıvır, kıvır saçlı

Kara üzüm gözlü

minnacık zarif kelebeğim benim.

Sen benim 

açlıktan kırılan  kara Afrika’da, 

İşgal altındaki Irak’ta, Filistin’de

Ya da dünyanın en uzak yerlerindeki

tüm çocuklar kadar güzel kızım.

Seni en az onlar kadar çok seviyorum.

Ve tüm o çocukların üzerine 

senin kadar eğilemediğim için

kendime çok kızıyorum.

Baba olmak böyleymiş demek ki

ayıp biliyorum ama

bunca güzel çocuk varken

utansam da kendimden

galiba en çok seni seviyorum.', 'Canım kızım kıvır, kıvır saçlı Kara üzüm gözlü minnacık zarif kelebeğim benim. Sen benim  açlıktan kırılan  kara Afrika’da,  İşgal altındaki...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin İrfan Kıbrıslıoğlu']::text[], 8.5, '{"poet":"Hüseyin İrfan Kıbrıslıoğlu","poet_slug":"huseyin-i-rfan-kibrislioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kizim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul olmak! (3x4''lük)', 'i-stanbul-olmak-3x4-luk-atakan-kartaltepe-xz9rf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul olmak!   (3x4''lük)     '' Bir deli/Muammer Çelik Beyefendinin  adlı şiirime  şekindeki teveccühleri sebebiyle kabûl buyurması dileğiyle kendisine ithafen bir İstanbul şiiri

Senin koynunda doğmak da güzel...sende yaşayıp bilmek de...

Sende açıp solmak da güzel...sende ağlayıp gülmek de...

Sana aşk ile yanmak da güzel...seni uzaktan anmak da...

Seni bir İnci sanmak da güzel...seni birinci saymak da...

Sana hasretle varmak da güzel...seni diline sarmak da...

Seni bilmeyip sormak da güzel...seni dileyip ermek de...

Sende seviyor olmak da güzel...sende sevilen olmak da...

Sende ayrılık çekmek de güzel...sende kavuşmuş olmak da...

Sende gezip de tozmak da güzel...seni anlatıp yazmak da...

Sende durulup azmak da güzel...sana gücenip kızmak da...

Sana koşup da gelmek de güzel...sende soluyup ölmek de...

Sende yatıyor olmak da güzel...senle İstanbul olmak da...

                                 30.05.2005/09.45', 'İstanbul olmak!   (3x4''lük)     '' Bir deli/Muammer Çelik Beyefendinin  adlı şiirime  şekindeki teveccühleri sebebiyle kabûl buyurması dileği...', ARRAY['Türk Edebiyatı','Şiir','Atakan Kartaltepe']::text[], 8.5, '{"poet":"Atakan Kartaltepe","poet_slug":"atakan-kartaltepe","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istanbul-olmak-3x4-luk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Bende Saklım', 'adi-bende-saklim-salih-ozalasan-buhpr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Edalım, baldan tatlım, bal dudaklım

Denizim deryam,umman gözlerinde saklım

Ay yüzlüm kaşı sürmelim, en kıymatlım

Lale sümbül nergis, kokusu hepsinden farklım

Işığıyla aydınlandığım, kalbinde sevgisi, salkım saçaklım

Melek huylum, ruhu nurdan kanatlım

Edasına kurban olduğum, yüreğinde sevdam saklım

Doğan Güneş’le bir tuttuğum, geceme mah cemalım

Adın bende saklı, sorana diyorum senin için edalım

Mahşerde kavuşurum dediğim, bedeni bana yasaklım

30-05-05

Salih Özalaşan', 'Edalım, baldan tatlım, bal dudaklım Denizim deryam,umman gözlerinde saklım Ay yüzlüm kaşı sürmelim, en kıymatlım Lale sümbül nergis, kokusu ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adi-bende-saklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazırım Gitmeye', 'hazirim-gitmeye-sabit-i-nce-57ztp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Epeydir hazırım gitmeye

korkum yok gitmek için..

Ben beni bırakamıyorum

Bendeki ben hiç bırakmıyor ki peşimi, gideyim..

gideceğim yeri bilmesem de

görmesem de, yaşamasam da

şiirimsi kelimeler, şiirimsi cümleler peşimde hep

Bırakmıyorlar ki gideyim.

Ben onları mı onlar beni mi bırakmıyor 

bilemiyorum...

Ama birgün mutlaka gideceğim buralardan

mutlaka, ha bu gün ha yarın..

farketmez..

Bir iz, bir güzellik bir emare bırakmak istiyorum.

Bekliyorsam sadece bunun için..

Yoksa neyi bekleyeyim, 

neden bekleyeyim buraları.

Hep aynı şeyleri yapmak, yemek, içmek,

gezmek hep aynı...

Farklı şeyler yok ki

Olmuyarsa niye bu bekleyiş? 

Onun için gideceğim buralardan

gideceğim bir meçhule doğru...

O meçhul çekiyor beni,

O meçhulü merak ediyorum,

O heyecan veriyor bana.

epey zamandır hazırım gitmeye,

Yitmeye...

Epeydir hazırım..

Sabit İnce Kayseri

29.6.2003', 'Epeydir hazırım gitmeye korkum yok gitmek için.. Ben beni bırakamıyorum Bendeki ben hiç bırakmıyor ki peşimi, gideyim.. gideceğim yeri bilme...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hazirim-gitmeye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran', 'haziran-gulseren-onay-mtk7n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağ oldu büyüdü

Yankısı 

İlk çığlıkların,

Anılarımla bu Haziranda yine..

Suskun haykırışlarla

Gözlerimde

Yaşadım geçmişi

İsyan ettim....

Yalnızlığımı yıllara böldüm

Ekledim mutsuzluğu

Yaşım çıktı ortaya

Sabaha 

Güneşle doğdum

Ondandır ruhumun sıcaklığı

Ve yine 

Bir başka Haziranda 

Öleceğim,

Gün doğumuyla

Soğumayacak bedenim..

GÜLSEREN ONAY

31/05/2005/ANTALYA', 'Dağ oldu büyüdü Yankısı  İlk çığlıkların, Anılarımla bu Haziranda yine.. Suskun haykırışlarla Gözlerimde Yaşadım geçmişi İsyan ettim.... Yal...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/haziran-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-guzin-eye-dundar-b9i4p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen ve ben

birden başka değiliz

ince sınır çizgisi ikilemin

ölümle

hayat gibi içiçe

ilkle son arası bir yerde

sen  ben

ben sen oldukça

büyüdü evren

bütünlendi ten', 'sen ve ben birden başka değiliz ince sınır çizgisi ikilemin ölümle hayat gibi içiçe ilkle son arası bir yerde sen  ben ben sen oldukça büyüd...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ve-ben-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-rütbe-i  tenzil', 'a-rutbe-i-tenzil-mikdat-bal-401sq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rütbe-i  tenzil

Milletin dertleri o kadar çok ki!

Fark etmedik yoldan kayana kadar

Arasan bulunmaz insanlık yok ki!

Rütbe-i  tenzili çıyana kadar!

Değişti insanlar, hayalet olmuş

Bunun müsebbibi cehalet olmuş

Sonradan görmeler bir lanet olmuş

Böyle değillerdi doyana bakar

Selamun aleyküm dedim birine

Keşke “hello” desem onun yerine

Başka bir dünyada dalmış derine

Üç kez tekrarladım duyana kadar

Ayağa dikildi, karşımda durdu

Belli tanımadı, yabancı gördü

Selamı almadı, sen kimsin sordu

Ben ona ceddini sayana kadar

Dedim ben tanırım, hep akrabanı

Eşek oğlu eşek, tanı babanı

Affetmemek lazım, böyle yapanı

Ta ki bu tavırdan, cayana kadar

Der Mikdadi millet, ne hale düştü

Değerlerden koptu, büsbütün şaştı

Sevgi sandı şehvet ile öpüştü

Bay bay ile bayan bayana kadar

Şair Mikdat Bal', 'Rütbe-i  tenzil Milletin dertleri o kadar çok ki! Fark etmedik yoldan kayana kadar Arasan bulunmaz insanlık yok ki! Rütbe-i  tenzili çıyana ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/degisti-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işığa Hapis Gölgem', 'isiga-hapis-golgem-cetin-hacifettahoglu-wvo4j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar Nasılda Geçmiş Meğer...

Hatırlanmış Gibi Davranılan Hatıralar,

Ne Gülümseyişlere Yenik Düşmüş

Sil Baştan Reset Çeksem Şu Beynime

Gülümseyişlere Anlamsızlaşırım

Ağaçların Kuru Gövdelerinde, 

Taze Bir Resim Olur Hatıralar

Gökyüzü,Şahit Tutar Yağmurlarını

Ben Islak Bir Yalan Olurum

Güneşin Her Doğuşunda

Kuruyan Yanlarıma Doğrulurum

Ne Kaldırımlar Yürüdüm 

Hızla Geçen Köpekler Yol Boyunda

Kimi Çabukluğunun Kurbanı,

Kimi Açlığın Talihlisi

Ve,Ne Yazıkki Hiç Ezberimde Kalmayan

Sokak Köpeklerine Tazelerim Hatıralarımı

O Yerde Bir Başkası Var Şimdi

Biraz Sen Biraz Yabancı 

Ve Hiç Olmadığı Kadar Orda Olan Gülümseyişlerin

Yaklaştıkça Depreşen Köşe Başı Sendromlarım

Ardında Koca Bir Boş Sokak

Hatıralar,Kaldırımlar Olur Yeniden

Ben Bu Sokaktan Hep Geçerim

Uzaklaşan Hatıralarımı Tazelerim

Ne Sen Olursun Bazen Ne De Ben

Ben Sokak Lambasına Yaslı Bir Yabancı

Sen İse Önümde Işığa Hapis Gölgem', 'Yıllar Nasılda Geçmiş Meğer... Hatırlanmış Gibi Davranılan Hatıralar, Ne Gülümseyişlere Yenik Düşmüş Sil Baştan Reset Çeksem Şu Beynime Gülü...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/isiga-hapis-golgem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şematik', 'sematik-hayri-arikan-serdaroglu-dbbtk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Girince.        acı               bahar         can               geldi       cana        canan   

 Acı               bakışın        gönül          hanemde    çerağ       oldu     yanan       

Bahar         gönül            mülkümü    umarsız       eyledi       eyvah     can        Can             hanemde     umarsız      yaşar           tahtsız      bahtsız    han      Geldi          çerağ            Eyledi        tahtsız          şafak        atmada    tan    

Cana          oldu              eyvah         bahtsız           atmada    nabızda   kan    

Canan        yanan           can             han               tan            kan            şan

 Hayri Arıkan (Serdaroğlu)', 'Girince.        acı               bahar         can               geldi       cana        canan     Acı               bakışın        gönül  ...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sematik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşeli yaz, güldür bizi diyorlar', 'neseli-yaz-guldur-bizi-diyorlar-mikdat-bal-52f7y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazdıklarım acı, ama gerçektir

Neşeli yaz, güldür bizi diyorlar

Gönlüm ayna, kalemim de mercektir

Neşeli yaz dizi dizi diyorlar

Ne yazayım,ağaç, çiçek, kuş, böcek

Saki, sarhoş, davul, zurna, ya köçek

Bundan yazsam, problemler mi gidecek! 

Her gün acı her gün sızı diyorlar

Bir yanda yangın var, bir yanda yağma

Kıdemli hırsızlar,anadan doğma

Okurlar diyor ki, bir de sen boğma

Az neşeyle doldur bizi diyorlar

Gülemeyen insan, nasıl güldürür

Kalplere neşeyi nasıl doldurur

Bu kahır bu merak, bizi öldürür

Neşeli yaz öldür bizi diyorlar

Uğraştım olmadı her seferinde

Umarım yazarım günün birinde

Bizden olmayanlar gittiklerinde.

Yaz bize neşeli sözü diyorlar', 'Yazdıklarım acı, ama gerçektir Neşeli yaz, güldür bizi diyorlar Gönlüm ayna, kalemim de mercektir Neşeli yaz dizi dizi diyorlar Ne yazayım,a...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neseli-yaz-guldur-bizi-diyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal Tercümesi!', 'hal-tercumesi-zulfikar-yapar-kaleli-qowkc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baktım gelinmezin düşkün halı var

Bilinmezi gelinmeze yolladım.

Görüp bilmediğim alem geldi dar

Sonsuzluğa hançerimi salladım.

Gölgem bıçaklandı, yarıldı ama

Gönlümün kuşunu eyleyemedi.

Beynimde engeller darıldı ama

Gönlümce bir türkü söyleyemedi.

Düşman aşkımıza fitne ekmekte

Gaflet uykusunda uyumaktayız.

Kökümüze kibrit suyu dökmekte

Tavlı demir gibi soğumaktayız.

Bana göre bir eğlence bulmuşum

Hayal sahnesinde gafil oynarım

Derinliğin gözlerine dalmışım

Harda donar, suya batar yanarım

Gözümden işittim, kulaktan baktım

Kapısında yağız atlar göründü

Gönlümün gözüne güneşi soktum

Dünyam zifir karanlığa büründü.', 'Baktım gelinmezin düşkün halı var Bilinmezi gelinmeze yolladım. Görüp bilmediğim alem geldi dar Sonsuzluğa hançerimi salladım. Gölgem bıçakl...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hal-tercumesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güven...', 'guven-zulfikar-yapar-kaleli-vlgv5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Yolun ortasında bırakıp beni,

Gidenlere güvenemem, bilesin.

Kürkçü dükkanıdır sonu, encamı,

Güdenlere güvenemem, bilesin.

Çileyi, cefayı sayarsan mübah,

Sevende mi, sevilende mi günah? 

Gam yükü sırtımda yoruldum, eyvah! 

Didenlere güvenemem, bilesin.

Günlerim, aylarım, yıllarım nerde? 

Densiz aramıza gerilen perde,

Haktan uzak olan her türlü ferde,

Bedenlere güvenemem, bilesin.

Didik didik oldu ocağım, yerim,

Doğrandı kollarım, didildi derim,

Ne istersen düşün, vallahi derim,

Cedenlere güvenemem, bilesin.

Kaleli’yim diyeceğim bitmedi,

Anlatmaya kağıt, kalem yetmedi,

Yaptığımız hiçbir hesap tutmadı,

Nedenlere güvenemem, bilesin,', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Yolun ortasında bırakıp beni, Gidenlere güvenemem, bilesin. Kürkçü dükkanıdır sonu, encam...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guven-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet! !', 'emanet-zulfikar-yapar-kaleli-fh9e0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Emanet illerde zulm doruktadır

Ayaklar sürünür başlar sevinir

Kaç yıl oldu yavru ana ayrıdır

Martlar gazel döker kışlar sevinir

Bu vahşete susar Garbın inadı

Düpedüz soykırım ve zulüm adı                                        

Yıkılmış yuvası kırık kanadı

Bahar muştusuna kuşlar sevinir

Dilde nağme adın aşk bestelenir

Gökler ağlayınca yer hastalanır

Nasihat hovarda kin destelenir

Sevda kucaklanır yaşlar sevinir

Bitmiyor bir türlü ağrı sancısı

Her gün kan ağlıyor ana bacısı

Ölüm işkencesi kardeş acısı

Bulutlar yaş döker  taşlar sevinir', 'Emanet illerde zulm doruktadır Ayaklar sürünür başlar sevinir Kaç yıl oldu yavru ana ayrıdır Martlar gazel döker kışlar sevinir Bu vahşete s...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emanet-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makber Taşıma', 'makber-tasima-mehmet-fatin-baki-zqril', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şükür ettim yüce Allâhıma ben tek başıma.

Seneler koydu beyaz saçları yorgun başıma.

Bana tattırdı bu yetmiş sekizin yaş tadını

Beni sıhhatlı yetiştirdi bu olgun yaşıma.

Bana ihsâmı yeter târihe bâkî kalacak

Gazelim zevkle yazılsın kara makber taşıma.

Feilâtün     feilâtün     feilâtün     feilün 

.  .   /   /    .  .   /   /   .  .   /   /   .  .   /', 'Şükür ettim yüce Allâhıma ben tek başıma. Seneler koydu beyaz saçları yorgun başıma. Bana tattırdı bu yetmiş sekizin yaş tadını Beni sıhhatl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/makber-tasima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Taze Gelin...', 'dunya-taze-gelin-zulfikar-yapar-kaleli-wesot', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzü okyanus, arşa dayalı

Çile denizinde kesilir gider.

Dünya taze gelin, yeşil boyalı

Günün gölgesinde kısılır gider.

Nesneler kavgalı, değil barışık

Her şey bir bilmece, her şey karışık

Mevla’dan hidayet, nurdan bir ışık

Sızmazsa, veliye küsülür gider.

Göklerin başında tacı aradı

Acının içinde acı aradı

Bazen kardeş bazen bacı aradı

Bazen bir yıldıza asılır gider.

Toprakları bomboş, şu aç diyarda

Irmakları susuz, kıraç diyarda

En ücra köşede, en uç diyarda

Çöllerde Leyla’ya esilir gider. 

Hayal sonsuz deniz daldı bir anlık

Geceler uykusuz, gündüz karanlık

Yerin karnı geniş ve içi ılık

Sırta tahta duvar basılır gider.', 'Gökyüzü okyanus, arşa dayalı Çile denizinde kesilir gider. Dünya taze gelin, yeşil boyalı Günün gölgesinde kısılır gider. Nesneler kavgalı, ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dunya-taze-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dengin Kadar', 'dengin-kadar-mehmet-fatin-baki-sie6o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pek şikâyet etme kim senden de dûn bin kişi var.

Çok böbürlenmek te boştur. Kimse vermez  i’tibar.

İç güzellik dış güzellikten de evlâdır,  Fatin

Mûteberdir gösterirsen kendini dengin kadar.

Dûn = aşağı

Fâilâtün    fâilâtün    fâilâtün    fâilün

/  .   /   /   /  .   /   /   /  .   /   /   /  .   /', 'Pek şikâyet etme kim senden de dûn bin kişi var. Çok böbürlenmek te boştur. Kimse vermez  i’tibar. İç güzellik dış güzellikten de evlâdır,  ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dengin-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mürsillerine', 'mursillerine-mehmet-fatin-baki-2r3ki', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendim gibi ahret  suçu fâillerine

Sır köprü çıkar geçmeğe mevt illerine. 

Göçtükte bu ten postacı bey lutfederek

Gönder geri mektupları mürsillerine.

Fâiller = yapanlar

Mevt = ölüm

Mürsiller = gönderenler

Mefûlü    mefâîlü     mefâîlü    feül

/   /  .    .   /   /  .   .   /   /  .   .   /', 'Kendim gibi ahret  suçu fâillerine Sır köprü çıkar geçmeğe mevt illerine.  Göçtükte bu ten postacı bey lutfederek Gönder geri mektupları mür...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mursillerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanırsın', 'sanirsin-mehmet-fatin-baki-zdxg5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarışırken beni görsen deli divâne sanırsın

Ama halvette iken bendeni mestâne sanırsın.

Sen eğer Türkçeyi sâf kalb ile hatm edemezsen

Bu beyitlerde geçen sözleri efsâne  sanırsın.

Gece eğlencede hamr içmeyi dostlarla  yaparken

Şeb ü rûz  şi’r  okunan yerleri meyhâne  sanırsın.

Yazılan lafların anlamlarını bir bilebilsen

Gelişen bilgini girdap gibi pervâne  sanırsın.

Atik Osmanlıcanın vardığı yerden bakılırsa

Edebî Mehmet’i sen kültüre bîgâne  sanırsın.



Halvet = yalınız tenhada kalma

Mestâne = Sarhoş, kendinden geçmiş 

Hamr = şarap, içki

Şeb ü ruz = gece gündüz

Atik = eski

Edebî = edebiyatla ilgili 

Bîgâne = ilgisiz, kayıtsız

Feilâtün   feilâtün    feilâtün    feilâtün 

.  .   /   /  .  .   /   /  .  .   /   /   .  .   /   /', 'Yarışırken beni görsen deli divâne sanırsın Ama halvette iken bendeni mestâne sanırsın. Sen eğer Türkçeyi sâf kalb ile hatm edemezsen Bu bey...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sanirsin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fürkânsız Olur', 'furk-nsiz-olur-mehmet-fatin-baki-pnb1p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mesken kirası vermeyen iskânsız olur

Mümkün bile bir tembele imkânsız olur. 

Tenhâya gidip kırk seneden fazla kalan

Gurbetçi,  cefâ-keş gibi furkânsız olur. 

Tenhâ = uzak ıssız yerler

Cefâ-keş  =  cefa çeken

Furkânsız  = iyi kötü, doğru yanlış arasındaki farkı

görmeyen kimse

Mefûlü   mefâîlü    mefâilü    feül

/   /  .   .   /   /  .   .   /   /  .   .   /', 'Mesken kirası vermeyen iskânsız olur Mümkün bile bir tembele imkânsız olur.  Tenhâya gidip kırk seneden fazla kalan Gurbetçi,  cefâ-keş gibi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/furkansiz-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen Cemil Beye', 'ogretmen-cemil-beye-mehmet-fatin-baki-5rmk6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mektepte eleştirme Cemil bendeni sen

Ceddim dili Osmanlıca dil olduğunu. 

Bir sözlüğe bak hüsn’ü, güzel gör seni sen

İsmin de güzel-yahşi-cemil olduğunu.

Ceddim = ecdâdım, dedelerim

Hüsn = güzel

Yahşi = güzel 

Cemil = güzel

Mefûlü   mefâîlü    mefâîlü    feül

/   /  .    .   /   /  .   .   /   /  .   .   /', 'Mektepte eleştirme Cemil bendeni sen Ceddim dili Osmanlıca dil olduğunu.  Bir sözlüğe bak hüsn’ü, güzel gör seni sen İsmin de güzel-yahşi-ce...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ogretmen-cemil-beye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özrün Nedir?', 'ozrun-nedir-caglar-asik-h7w7h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Besmele ile çıkalım yola.

Selam verelim sağa sola.

Bu yol ne güzel bir yolmuş.

Geçenlere selam olsun.

Bu sendeki yükün.

Acep nedir tartısı? 

Gönlünde taşıdığın nedir? 

Cevherine ulaşabilen var mı? 

Kim ölçebilse gerek.

Tartacak olana ölçü gerek.

Tartmak istemez isen.

Neylesin seni O yürek.

Yürek bir büzülüp, bir açılırsın.

Acep niye koşturup durursun? 

İçinde kıymetlini mi korursun? 

Niçin hep titrereyip durursun? 

Böcekler bile karanlıktan ışığa koşar.

Yürekler karanlıktan ışığa koşmaz mı? 

Sen niçin bekler durusun! 

Boşa geçirilecek zamanın var mı? 

Durma anlat içten geleni.

Söyletme hiç kötüleri.

İyilikten hiç zarar gelmez.

Dinle artık sende iyileri.

Tanımazsın kendini bile.

Nasılda emin davranırsın.

Şu kısacık zaman içinde.

Ne işlerle uğraşırsın? 

Boş işlerden kaçasın.

Faydasızdan korunasın.

Ecel herkesin hakkı.

Bu hakkı sende tadacacaksın.

Çağlar Aşık nedir özrün? 

Ağrır durur bir yerlerin.

Bu Dünya’daki küçük derdine yanma.

Asıl bak gerçek olan, büyük Dünyana.

(İstanbul – 18.04.2005)', 'Besmele ile çıkalım yola. Selam verelim sağa sola. Bu yol ne güzel bir yolmuş. Geçenlere selam olsun. Bu sendeki yükün. Acep nedir tartısı? ...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ozrun-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru Yunus Emre’ye', 'dogru-yunus-emre-ye-caglar-asik-lve0w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nice gönüller yaratmış yaratan.

Sevgisini özünden duyup taşıran.

Boğulup gider yüzmesini bilmeyen.

Var mı Yunusça sevgisini söyleyebilen? 

Yunus’un sözleri çok güçlü ve derince.

Varıpta inceden hissedip, düşünesin iyice.

Vakit ayırıp sende biraz ilgileniversen.

Ruhlara şifa olan sözleri, dinleyiversen.

O bunca özlü sözü kendi için mi sarfetti sanırsın? 

Dertli, dermanı kendince mi arayıp buldu sanırsın! 

Gönlünde bir dert var ise, o sözlerde manayı bulursun.

Sen niçin dermanını almazda, uzaklara kaçıp durursun? 

Yunus gelmiş söylemiş yürekten, özden nice sözlerini.

Yakışmaz sana karar vermek, dinlemezsen erenlerini.

Hak yoluna çıkmak için, gönlünü hazır mı sanırsın? 

Bu işi kolaylıkla olur, herkesçe başarılır mı sanırsın? 

Yunus’un çalalım kapısını, alsa bizleri de içeri! 

Bir içeri giriversek, kim çıkar ki bir daha geri? 

Çağlar Aşık coşar, yürekten, özden; hissedenler alır lezzetini.

Haydi durmayıp koşalım, gidip alalım, Yunus’un şifalı dediklerini. 

(İstanbul – 18.04.2005)', 'Nice gönüller yaratmış yaratan. Sevgisini özünden duyup taşıran. Boğulup gider yüzmesini bilmeyen. Var mı Yunusça sevgisini söyleyebilen?  Y...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dogru-yunus-emre-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Doğum Günü', 'kutlu-dogum-gunu-caglar-asik-12626', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geldi Sevgilinin Sevgilisi.

Kainat’ın hep beklediği.

Dertli gönüllerin dermanı.

Sonsuzluğun baş tacı.

Yaradan Ondan hoşnut olmuş.

Mekanını Cennet’te hazır kılmış.

Alemler Onda Muradını bulmuş. 

O daima doğruluk üzerine olmuş.

Niceleri ışığıyla, Hak yolu bulmuş.

Aşıklar dermanını O yolda bulmuş.

Melekler bile hayran olup, adını anmış.

Hak adını, arşu ala’ya beraber yazdırmış.

Burak gidememiş Onun gittiği yere.

Bilemeyiz gizlenen hikmetleri elbette.

Yaradan bilir ancak gerçekteki  hikmeti.

Dünya’nın dili olsa kimbilir neler diyecekti. 

Doğdu 571’de susayan Dünya üzerine.

Öyle bir gürlediki, tüm bozuk düzen üzerine.

Dayanamayıp yıkılıp gitti, bu gürleyişine.

Dikti en büyük eserini, Hak olan İslam Dinini.

(İstanbul – 18.04.2005)', 'Geldi Sevgilinin Sevgilisi. Kainat’ın hep beklediği. Dertli gönüllerin dermanı. Sonsuzluğun baş tacı. Yaradan Ondan hoşnut olmuş. Mekanını C...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kutlu-dogum-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nevin Ana Cansın Canımsın Benim', 'nevin-ana-cansin-canimsin-benim-doner-ozeke-9jjgj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi gözlü beyaz tenli gül yüzlü

Sen bir harikasın çerkez güzeli 

Senle mutluluklar dünyaya bedel 

Nevin ana cansın canımsın benim 

Durup durup bir kelime edersin ya sen 

Özün sözün doğru seviyorum ben 

Kötüleri sözlerinle daima yen sen 

Nevin ana cansın canımsın benim 

Abi kardeş bir yuvada ne kadar da hoş 

Tek dileğim ömrün boyu neşenlen ve çoş 

Nerede fakir fukara var imdadına koş 

Nevin ana cansın canımsın benim 

Seninle saatler saniye olur 

Üzüntümde olsa mutluluk bulur 

Seninle yaşayan bahtiyar olur 

Nevin ana cansın canımsın benim 

Dragos dağları seni bana anlatır 

Senin o melek kalbini bana dinletir 

Dertli isen sazım neler söyletir 

Nevin ana cansın canımsın benim 

Kafana tokadan başka hiç bir şey takma 

Geçmişi unut gitsin arkana bakma 

Sürümden kazanalım yerinden kalkda 

Nevin ana cansın canımsın benim 

Döner''im doğruları dile getirdim 

Her gidişimde seni cana götürdüm 

Söyleyecek çok söz var ama artık bitirdim 

Nevin ana cansın canımsın benim 

                       

                       DÖNER ÖZEKE

                          01.06.2005', 'Mavi gözlü beyaz tenli gül yüzlü Sen bir harikasın çerkez güzeli  Senle mutluluklar dünyaya bedel  Nevin ana cansın canımsın benim  Durup du...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/nevin-ana-cansin-canimsin-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya da Öl de Bari', 'ya-da-ol-de-bari-huseyin-erdogan-uv482', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'böyle susup susup da

beni hasretinle yakma

beni sensiz bırakıp da

düşürme derde

gün bile zindandır bana

senin olmadığın yerde

inan ki sen benim

kalbimde teksin

yalan söyleyen

ömrünce çile çeksin

bil ki sen yer yüzünde

en çok sevilen meleksin

ben de seni delice sevenim

rüya bile görmek istemem

düşlerimde sen yoksan eğer

vallahi sen istemedikçe 

ellerine bile değmem

sevdiğini bir kez olsa da 

söylesen de bana yeter

zaten,yokluğunda 

ne sabah oluyor 

dünyama

ne de gün doğuyor 

zifiri karanlıklarıma? 

geleceksen gel artık 

perişan etme beni

ne olur bir umut ver 

ya da öl de bari

hiç olmazsa

mahşerde beklerim seni

hem de umutla

bir gün nasıl olsa

sen de geleceksin oraya

                          01.06.2005', 'böyle susup susup da beni hasretinle yakma beni sensiz bırakıp da düşürme derde gün bile zindandır bana senin olmadığın yerde inan ki sen be...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ya-da-ol-de-bari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-nurol-banabak-v0hrv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şaire güvenmek yürek ister

Hiç beklemediğin an

Değişir seni şiirle

Anlayacağın

Yaşadı mı şiir gibi yaşar

Yaşayamayınca şiir yazar şair

(bir yolculuk eşiğinden 01.06.2005', 'Bir şaire güvenmek yürek ister Hiç beklemediğin an Değişir seni şiirle Anlayacağın Yaşadı mı şiir gibi yaşar Yaşayamayınca şiir yazar şair (...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/itiraf-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Aslında..', 'benim-aslinda-dilek-kesgin-hk564', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çığlık duyarsan kulağında,

Bir damla gözyaşı varsa yanağında,

Bir tebessüm belirirse dudağında,

Bil ki, bu tebessüm, benim aslında..

Kapattığın kapının altındaki boşluktan

İçeri sızarsa hafiften bir rüzgar,

Havalandırırsa dipsiz duygularını

Bil ki, bu rüzgar, benim aslında..

Ağlamak isteyip de ağlayamazsan,

Sığınırsan ürkekçe anılarına

Ve nihayet karar vermişken ağlamaya

Bir ses doldurursa beynini o an

Bil ki, bu ses, benim aslında..

Umutsuzca kapandığında kalbine

Fısıldayarak girerse bir çığlık odana

Seni sevdiğini fısıldarsa üstelik,

Bil ki, bu çığlık, sensizliğim aslında! 

(İzmir, 22.10.2001)', 'Bir çığlık duyarsan kulağında, Bir damla gözyaşı varsa yanağında, Bir tebessüm belirirse dudağında, Bil ki, bu tebessüm, benim aslında.. Kap...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kesgin']::text[], 8.5, '{"poet":"Dilek Kesgin","poet_slug":"dilek-kesgin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benim-aslinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç gelirmiydi', 'hic-gelirmiydi-ramazan-kurt-2-bg486', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırmızı kazağımın küçüleceği; 

Makarnayı sevmeyeceyim.,

Rakı içeceğim,

Bir başkasının, sevgilimin dudaklarından öpeceği

Hiç gelirmiydi aklıma!', 'Kırmızı kazağımın küçüleceği;  Makarnayı sevmeyeceyim., Rakı içeceğim, Bir başkasının, sevgilimin dudaklarından öpeceği Hiç gelirmiydi aklım...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kurt 2']::text[], 8.5, '{"poet":"Ramazan Kurt 2","poet_slug":"ramazan-kurt-2","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hic-gelirmiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-murat-demir-dgnxq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar kartal iken  kuş oldum 

Yaş kemale erdi artık boş oldum 

Zevk eylence bitti sanki taş oldum 

Hayatın son demi fenaymış oğul 

Evin odaları sanki bir zindan 

Hayal çok, haber yok bayırdan kırdan 

Hiç eser kalmadı sohbetten sırdan 

Hayatın son demi yamanmış oğul 

Can çeker diz tutmaz sokak yabancı 

Gitsen kabul etmez ne han, ne hancı 

Kadın erkek olduk kardeş ve bacı 

Hayatın son demi boş imiş oğul 

Şikayetler arttı beden paslandı 

Yürek bocaladı beyin hırslandı 

Çoğu zaman yorgan döşek ıslandı 

Hayatın son demi yaş imiş oğul 

Çatal, kaşık ele ağır geliyor 

Çaresizlik her an bağır deliyor 

Kulak iflas etmiş sağır deniyor 

Hayatın son demi betermiş oğul 

Gözler solmuş görüneni görmüyor 

El titriyor yırtığını örmüyor 

Can istiyor ecel öte koymuyor 

Hayatın son demi kahırmış oğul 

Stres, sinir çocuklara eziyet 

Sıhhat bozuk çok dağınık vaziyet 

Düşündükçe ağlatıyor bu illet 

Hayatın son demi zehirmiş oğul 

Hayal eder geçmişime bakarım 

Bir pireye yorgan döşek yakarım 

Anlıyorum çocuklaştım sakarım 

Hayatın son demi hüsranmış oğul 

Dişler bitmiş içe düşmüş yanağım 

Dil dönmüyor kelam etmiyor ağzım 

Sıcak soğuk hep yanıyor boğazım 

Hayatın son demi zulümmuş oğul 

Ten sarardı kan damardan çekildi 

Deva diye ne şuruplar içildi 

Yolun sonu rampalardan geçildi 

Hayatın son demi hazanmış oğul 

Dalga bitti su duruldu, don geldi 

Can bedenden ayrıldığı an geldi 

Kalp titriyor anlıyorum son geldi 

Hayatın son demi vedaymış oğul 

Murat der aleme helallık verin 

Elem, acı, keder, derdim çok derin 

Anlaşıldı artık toprak son yerim 

Hayatın son demi ölümmüş oğul.', 'Bir zamanlar kartal iken  kuş oldum  Yaş kemale erdi artık boş oldum  Zevk eylence bitti sanki taş oldum  Hayatın son demi fenaymış oğul  Ev...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ogul-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-mesut-akinci-8uyno', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittin, sormadan, söylemeden, terkettin neden? 

Vurdun beni aldın benden gittin neden

Sorsaydın söylerdim derdimi sana

Gittin, sormadan, söylemeden, terkettin neden? 

Ben sensizim mutluyum  sanma 

Kim ne derse desin sakın inanma

Ben de seni unutur giderdim amma

Sen gibi olamadım acaba neden

Git artık sende git herkes gibi 

Bırak sen de beni aynen  el gibi

İstesende olamazsın artık eskisi

Bırak git sende beni sorma neden

Ben de artık bir yol tuttum sevgilim 

Sensizliğe alıştım artık unuttum

Bir süre bana da zor geldi ama

Nedense çabucak seni unuttum 

Neden deme bana unuttun neden

Senin gibi oldum bende fenamı? neden? 

Hani hep derdinya bana bilmeden

Unutursun beni, beni bilmeden

Unuttum ben seni seni bilmeden 

Neden deme bana biemem neden...

Nedenim yok neden diyemem neden

Sende unut beni hiç yokken neden 

Ne olur unut beni sorma bir neden...', 'Gittin, sormadan, söylemeden, terkettin neden?  Vurdun beni aldın benden gittin neden Sorsaydın söylerdim derdimi sana Gittin, sormadan, söy...', ARRAY['Türk Edebiyatı','Şiir','Mesut Akıncı']::text[], 8.5, '{"poet":"Mesut Akıncı","poet_slug":"mesut-akinci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/neden-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlılara', 'yaslilara-omer-faruk-hatipoglu-4oa5m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'artık bir akşamüstüsün

ak sevinç ve sarı hüzün

kızıl yorgun renk alırlar

kaynar çevren''de gözüm

içinde bir boy çukursun

inip inip çıkıyorsun

eğilip tutsam elinden

bahara dönüşür güzün

varsa göreceğim yıllar

aradığım yitik yollar

bana seni yolladılar

oğluma çıkıyor izin

kaşına asılı ömür

bir koca çığ güllesidir

çıt kopar göz kapanır

üstüne sonsuz bir gizin', 'artık bir akşamüstüsün ak sevinç ve sarı hüzün kızıl yorgun renk alırlar kaynar çevren''de gözüm içinde bir boy çukursun inip inip çıkıyorsun...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaslilara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırs', 'hirs-omer-faruk-hatipoglu-ukk29', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hırs 

iki başlı bir kurda benzer

                 insan içinde

bir ağzın dizlere tükürdüğü derman

                 gençlik iksiri

öbür ağzın yürekten kemirdiğidir', 'hırs  iki başlı bir kurda benzer                  insan içinde bir ağzın dizlere tükürdüğü derman                  gençlik iksiri öbür ağzın...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hirs-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Serçeyim Aslında', 'ben-bir-serceyim-aslinda-omer-faruk-hatipoglu-fremp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uçmadığıma bakmayın

ben bir serçeyim aslında

gökyüzü kanatlarımın değil

ama ayaklarımın altında

ben bir serçeyim aslında

bilirim yaşam ne denli kısa

bu yüzden bu başımdaki telaş

bu yüzden adımlarım sıkıysa

ben bir serçeyim aslında

bakmayın benzim eylül sarısı

bahar üstderimin altındadır

nisan akar kanarsa', 'uçmadığıma bakmayın ben bir serçeyim aslında gökyüzü kanatlarımın değil ama ayaklarımın altında ben bir serçeyim aslında bilirim yaşam ne de...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-bir-serceyim-aslinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Çocuk Yanımla', 'sevdim-cocuk-yanimla-omer-faruk-hatipoglu-4dkmg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu çocuğu bir abinin

çatık kaşıyla sevdim

ablamın derdime düşen 

uykusuz başıyla

      çocuktu, beyaz güvercinler

      gözündeki saçaklardan

      küren küren kalkıyordu

sonra bir annenin 

yüzünde çizgiyle sevdim

babamın dışkapıda direk

oyuksuz gözüyle

      çocuktu kitap sayfalarından

      uçuşan harflerin kanadında

      tümce  tümce özgürlüğe

sonra bir dostun

kucaklar tokasıyla sevdim

yoldaşımın yitik yolda

şaşmaz pusulasıyla

      çocuktu darasız terazisiz

      dünyayı çıplak gözüyle

      gram gram tartıyordu

ve sonra bir sevgili gibi sevdim

benliğimi salıverdim göğüne

terzi bildim acemi aşkını

ustaca parçalanmış yüreğime

sevdim en çocuk yanımla

bir çocuk bir çocuğu

nasıl severse öyle', 'bu çocuğu bir abinin çatık kaşıyla sevdim ablamın derdime düşen  uykusuz başıyla       çocuktu, beyaz güvercinler       gözündeki saçaklarda...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevdim-cocuk-yanimla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudakların Özetindir', 'dudaklarin-ozetindir-omer-faruk-hatipoglu-34v2v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dudakların kızıl bir özeti aşkın

sen ki

uzun anlatıldın

ne sancılar çekti zaman

seni karnına düşürdüğünden beri

sular seni fısıldadı

fırtına çamurlar seni

dipsiz zamanın karanlık yerlerinde

yeşil yosundan mavi göze

karanlıktan aydınlığa söylendin

ne sancılar çektin

ağrıların sevgi bulundu dindi

sen sen oldun yeryüzü sayfalarla

kan sayfalar çevrildi dudaklarına kadar

sevda sayfalar

uzun anlatıldın

sular bengisular kıyısında

kutsanmış kızıl düşçiçeği dudakların

aşkın heyecanlı bir özeti 

bir düş gibi yaşamak tadında

imgenin bal dese,cennet dese yetemediği

ama ben ayrıntını merak ederim hep

dudaklarındaki önsöz yetmiyor

dudaklarındaki o kızıl özeti aşkın

ayrıntılarını okumak istiyorum

ağzından', 'dudakların kızıl bir özeti aşkın sen ki uzun anlatıldın ne sancılar çekti zaman seni karnına düşürdüğünden beri sular seni fısıldadı fırtına...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dudaklarin-ozetindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkında mısın?', 'farkinda-misin-mesut-akinci-cz878', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk tanıştığımız yerdeydim dün

Tanışalı yıllar olmuş farkında mısın? 

Sanki dün gibiydi hatırlıyorum

Sen unuttuğunun farkında mısın? 

Ne oldu sana böyle

Sertleştiğinin hiç farkında mısın? 

Son zamanlar tanınmaz oldun 

Değiştiğinin hiç farkında mısın? 

Neden hep ben hatırlıyorum 

Böyle güzellikleri

Her güzelliği unuttuğunun

Farkında mısın? 

Seni ne kadar sevdiğimi 

Bilmezmiş gibi 

Şüpheciliğinin hiç farkında mısın? 

Artık hiç birşey eskisi gibi değil 

Ne sen artık eski sen nede ben eski ben oldum

Birbirimizden kopukluğumuzun hiç

Farkında mısın? 

Gelmez artık o günler boşa bekleme 

Gitti giden geriye dönmez bekleme

Zaten derdin çoktur yarim derdine

Yeni yeni dertler sakın ekleme

Artık ne sen bekle beni nede ben gelem 

Gelmem artık geriye kırgınım sana

İstesem de sana geri dönemem 

Beni fena kırdın farkında mısın?', 'İlk tanıştığımız yerdeydim dün Tanışalı yıllar olmuş farkında mısın?  Sanki dün gibiydi hatırlıyorum Sen unuttuğunun farkında mısın?  Ne old...', ARRAY['Türk Edebiyatı','Şiir','Mesut Akıncı']::text[], 8.5, '{"poet":"Mesut Akıncı","poet_slug":"mesut-akinci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/farkinda-misin-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Raylar Üzerinde Demir Bacaklı Çocuklar Gördüm...', 'raylar-uzerinde-demir-bacakli-cocuklar-gordum-tulay-sustam-w5yqr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '____ Yeğenim Selda''ya ve tekerlekli sandalyede ki her bir çocuğa...

anlatsam; 

anlamayacaksınız beni...

anlatsam; 

inanmayacaksınız bana...

raylar üzerinde yürüyen

elele tutuşmuş 

tekerlekli sandalyelerini bir kenara atmış

karanlık dünyalarında 

gördükleri küçük bir ışığa doğru adım atan

demir bacaklı çocuklar gördüm

siz onların adını ''''kara tren'''' koydunuz...

oysa onların bacaklarında ki platinler

ve dikiş izleri ''''tren yolunu'''' andırıyordu

hepsi bu kadar...

rayların üzerinde yürüyen

demir bacaklı çocuklar gördüm diyorum size

umut vardı gözbebeklerinde her birinin

her biri omuz omuza vermişlerdi

yeniden yürüyüp, yeniden koşacaklardı

sizler onların adını ''''vagon-lar'''' koydunuz

oysa onların hepsi birer çocuktu

aynı yolda yürüyorlardı hepsi bu kadar...

rayların üzerinde yürüyen

demir bacaklı çocuklar gördüm diyorum size

neden inanmıyorsunuz? 

onların gözbeklerinde ki ışığı gördüm

gün be gün ''''güneşi'''' andıran umutlarını

ne olur o ışıkları söndürmeyin

çekin ellerinizi umudum(uz)  dan...

rayların üzerinde yürüyen

elele tutuşmuş çocuklar gördüm

demir bacaklı çocuklar

gördüm diyorum neden inanmıyorsunuz? 



*bugün ayağa kalkacaksın değil mi ufaklık:(((', '____ Yeğenim Selda''ya ve tekerlekli sandalyede ki her bir çocuğa... anlatsam;  anlamayacaksınız beni... anlatsam;  inanmayacaksınız bana... ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/raylar-uzerinde-demir-bacakli-cocuklar-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tersine', 'tersine-omer-faruk-hatipoglu-ogluf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'canımda ne kadar çoksan

o kadar azsın tenimde

düşümde ne kadar varsan

gerçekte o kadar yoksun

yüzümde ne kadar gizliysen

özümde o kadar açık açığa

ne kadar özlem olup taşıyorsan

o kadar uzaklarda akıyorsun

geceme ne kadar ışıksan

o kadar gündüzüme kısık

ne kadar ağrımda çığlıksan

ilacımda o kadar susuk

herkesle ne kadar yalnızsam

seninle o kadar kalabalık

ne kadar bende var oluyorsan

o kadar yok oluyorum sende', 'canımda ne kadar çoksan o kadar azsın tenimde düşümde ne kadar varsan gerçekte o kadar yoksun yüzümde ne kadar gizliysen özümde o kadar açık...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tersine-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oysan', 'oysan-omer-faruk-hatipoglu-eua3l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eğer sevgilim diyeceksem

alnımı,göğsümü yırta yırta

sevgilim diyeceksem

sesin iğne,tenin ipekten iplik

ellerin usta

ama ben yamanmak istemiyorum

biçilmek,dikilmek istiyorum yeniden

senin o tanrısal aşkına

eğer sevgilim diyeceksem 

iliklerimden, tabanlarımdan ağrı

dolu bulutlar kaldırıp ağustosuna

bir ceryan ırmağı gibi ağacaksam

ağzından yüreğine bir aşk

bir toprak hattında yatışmak için

...

sana annesinden süt ister gibi

sevgilim diyeceksem çağla gözlüm

sen onu memenden 

diline çevir diyedir', 'eğer sevgilim diyeceksem alnımı,göğsümü yırta yırta sevgilim diyeceksem sesin iğne,tenin ipekten iplik ellerin usta ama ben yamanmak istemiy...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Hatipoğlu']::text[], 8.5, '{"poet":"Ömer Faruk Hatipoğlu","poet_slug":"omer-faruk-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/oysan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviye Yolculuk', 'maviye-yolculuk-mustafa-sami-d85lb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalgaların iniş ve çıkışı 

____O anın ateşiyle 

_____İç içe geçerken 

_____Tuz tadı bırakıp 

_________Akıyordu tenimden

____________ve ben

Her seferinde seninle

_____Mavi denizlerde…', 'Dalgaların iniş ve çıkışı  ____O anın ateşiyle  _____İç içe geçerken  _____Tuz tadı bırakıp  _________Akıyordu tenimden ____________ve ben H...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maviye-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Kız', 'deli-kiz-sahin-yilmaz-zom0w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siyah saçlarını deli rüzgara

Bırakmışın estirirsin deli kız

Sen mi hayat verdin ulu dağlara

Ne kendini kastırırsın deli kız 

Etrafına ışık saçar gözleri

Akıllıyı deli eder sözleri

Çocukları, erkekleri, kızları 

Dalga geçer, küstürürsün deli kız

Masum bakışında bile cinlik var

Yürümende, duruşunda hinlik var

Çok tatlısın ama biraz benlik var

Konuşturmaz susturursun deli kız

Derdim, gamım biter yanıma gelsen

Bütün cihan güler bir kere gülsen

Eğer mahkemede şahidim olsan

İnan beni astırırsın deli kız

Yaramaz çocuğun ruhu var sende

Gençliğin ateşi tepinir kanda

Ne kadar masumsun toplum içinde

Duyguların bastırırsın deli kız

Yüzündeki gülücükler gitmesin

Mutluluğun ömür boyu bitmesin

İstemem hiç kimse sana çatmasın

Vallahi kan kusturursun deli kız', 'Siyah saçlarını deli rüzgara Bırakmışın estirirsin deli kız Sen mi hayat verdin ulu dağlara Ne kendini kastırırsın deli kız  Etrafına ışık s...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deli-kiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzulayınca', 'arzulayinca-metin-yalti-rnbmz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Testis tepelerine inen vadide

Çoşkun akan nehir gibi vurmakta

kendini o yamaçtan bu yamaca

helak olacak diye

donumu baraj yaptım kıyılarına

Kara bir bulut gibiydi

çevresine kurduğum orman.

ne kadar geçerse geçsin aradan

şaha kalkmış bir aygır gibi

dörtnal ezerken testis tepelerini

zor dizginledim avuçlarımla

senin gençlik tayını...

II

..........................-İlgilisine not-

Elli yıldan bu güne

çoşkun Aras gibiydi

bendini aşmak isterdi hep

Şimdi  dicle gibi küskün

Oluyor zaman zaman

Benim bir yakınmam yok

söylemedin deme

yanlış anlamlarda çıkarma bundan

Ama artık gına gelmiş olmalı

şaha kalktığı zaman

başka kısraklar geçmekte 

onun aklından...

III

beş altı yıldan beri

şakak platolarına düşen karlar

testis vadisine de düşmekte artık

Bilim adamları söylüyor

Son yıllarda

Küresel ısınma artmış.

İklimsel değişiklikler ondanmış.

O kapkaranlık çam ormanında

- bu sebepten olsa gerek-

Artık kayınlarda çıkmakta.

istersen dur, düşün biraz

o sımsıkı dayandığın sert çamlardan sonra

ne kadar mutlu eder seni

Yumuşak kayın ağaçları...

29/01/05 Sadabat', 'Testis tepelerine inen vadide Çoşkun akan nehir gibi vurmakta kendini o yamaçtan bu yamaca helak olacak diye donumu baraj yaptım kıyılarına ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/arzulayinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeyeceğim…', 'olmeyecegim-olgun-ekinci-r8sqg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '... Ay ışıksız gecelerin, yıldızsız semaların korkunç karanlığında kabus dolu intiharlardayım, 

tükenmeyen gecelerden sabahın uykusuz ilk ışıkların dek… 

Geceyi inleten sessiz çığlıklarım geri dönmekte kanayan yüreğime biçare... 

... Çocukluğumu unuttuğum, gençliğimi harcadım bu kentte boğuluyorum…karanlık düşlerimde 

uzanan hiçbir eli tutamıyorum… Uzanan ellerde bıçaklar bilenmiş… Silahlar kınından çıkarılmış… 

haydi kesin kellemi… Vurun... Ne duruyorsunuz? ... Bu yürek sevmekten vazgeçmeyecek… 

… Boğucu, sisli sabahlara sırıl sıklam uyandığımda doğrulamıyor, çamur deryası bir derede 

yüzmeye, kıyıya ulaşmaya çalışıyorum, nafile batıyorum… Battıkça daha çok seviyorum... 

... Sesimi ne zaman duyacak sınız? Size rağmen değil, sizlerle ayakta kalmalıyım-ki kan içiciler 

zafer çığlıklarını vahşi kabileler gibi tam-tamlarla kutlamasınlar… 

... Batıyor… Boğuluyorum… Uzandığım eller-ki dost türküler yazdığım eller hançerli… 

... Vuruldum… Ama ölmedim… Çocukluğum da '''' anne ben hiç ölmeyeceğim'''' derdim annem 

üzülmesin diye… Ölümüm hüzün kokan emekçi sevdaların, hüzün dolu bir çift gözün dizlerinde 

olmadıkça ölmeyeceğim… ÖLMEYECEĞİM… SEVİYORUM...

31.05.2005 - Adana', '... Ay ışıksız gecelerin, yıldızsız semaların korkunç karanlığında kabus dolu intiharlardayım,  tükenmeyen gecelerden sabahın uykusuz ilk ış...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olmeyecegim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüle Muhabbet', 'gonule-muhabbet-mustafa-sami-xcybn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Görüyorum ki

Bu bir serap değil 

Ruhumda estirdiğiniz 

Fırtınalar birer gerçek 

__O halde hak adalet yerini bulsun

______Derim ki; 

________Cezanız müebbet

________Gönüle muhabbet', 'Görüyorum ki Bu bir serap değil  Ruhumda estirdiğiniz  Fırtınalar birer gerçek  __O halde hak adalet yerini bulsun ______Derim ki;  ________...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gonule-muhabbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git.Git...', 'git-git-ayfer-yildiz-51ryi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece son bir kez göreyim seni de öyle git,

Mademki kararlısın herşeyini alda  git,

İz bırakma ardından kalbimi sökte dönüp bakmadan git

Kahrolmam desemde yalan o çok sevdiğim gözlerini benden ayırda git.

Ne desem boş anlıyorum şimdi,

Karanlık odama sensizliğin soğuk nefesi sindi,

Hani çok güçlüydü aşkımız bilmem ki neye yenildi,

Derman kalmadı bende sevgilim bana güç veren o kara gözlerindi.

Neler yaşarım ardından boşver sen mutlu olda git.

Gözyaşlarımı görme sakın bana acımadan git,

Kor saldığın gönlüme karları yağdırda git,

O karlar erirde korum alevlenir unutma da öyle git.

Biliyorum bu gece çok uzun sürecek,

Bitmez gibi ama biliyorum ki yarınlarda gelecek,

O yarınlarda bir gün duyarsan teslim almış beni ebediyet,

Mezartaşıma solmuş bir karanfil bırakta öyle git...', 'Bu gece son bir kez göreyim seni de öyle git, Mademki kararlısın herşeyini alda  git, İz bırakma ardından kalbimi sökte dönüp bakmadan git K...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Yıldız']::text[], 8.5, '{"poet":"Ayfer Yıldız","poet_slug":"ayfer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/git-git-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanım Var', 'i-syanim-var-i-lknur-cekici-9dh00', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İsyanım var herşeye

Yalan yanlış sevgine

Söylediğin son kelime

Olsam bile ne çare

İsyanım var sevgime

Yaşlar akar yüreğime

Damla damla benliğime

Sensiz doğan her güne', 'İsyanım var herşeye Yalan yanlış sevgine Söylediğin son kelime Olsam bile ne çare İsyanım var sevgime Yaşlar akar yüreğime Damla damla benli...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isyanim-var-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl Melekelerim', 'akil-melekelerim-mustafa-sami-pjxhu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzelliğini dile getirsin isterim 

Etrafında pervane kesilen sözlerim

Her bahar gönlüne ateş olup düşsün de

______Öyle geçsin ki kendinden

______Şaşırsın, çıksın yolundan

__________Akıl melekelerim...', 'Güzelliğini dile getirsin isterim  Etrafında pervane kesilen sözlerim Her bahar gönlüne ateş olup düşsün de ______Öyle geçsin ki kendinden _...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/akil-melekelerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Topal', 'kor-topal-burak-killioglu-vu1kf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat denilen gemide en arkada yerimiz,

Dalgalara bata çıka gidiyoruz kör topal...

İnsan kul olmuş insana, boşa akar terimiz,

Tüketip günümüzü yaşıyoruz kör topal...

Bilgi karşılıksız bir çek; alabildiğine şöhret,

Yıkılası putlara tapar olduk kör topal...

Küfre doğru bir meyil, güzele karşı nefret,

Ruhlarımızı şeytana satar olduk kör topal...

İnsan insanın kurdu, düşeni yerler hemen,

Leşlere sofra kurup doyuyoruz kör topal...

Gaflet nöbetlerinde kime geçermiş dümen,

Nefsin tuzaklarında yem olmuşuz kör topal...

Tarih söylemiş bize: Tekerrür aptallara! 

Kulak ardı ederek dinlemişiz kör topal...

Batmaya yakın gemi doluşup sandallara

Kurtuluruz sanmışız, 

Usul usul boğulup gider olduk kör topal...', 'Hayat denilen gemide en arkada yerimiz, Dalgalara bata çıka gidiyoruz kör topal... İnsan kul olmuş insana, boşa akar terimiz, Tüketip günümü...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kor-topal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve sevda', 'ask-ve-sevda-ali-riza-unal-ul0ax', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda denilen dert,sıtmadan betermi beter.

Gömleği yok, çul deyip,çekip çöpe atasın.

Gündüz hayalde, gece rüyada, yakarmı yakar.

Narı canına düşmüş, eldemiki,hissizce bakasın.

Düşmeyegör firâkı aşka, seni senden çekermi çeker.

Namusu ar’ı yok donsuzun,bir pula yada,hiçe satasın.

Öyle yüksekten,zalimce,sinsice,bakarmı,bakar,

Kârı ölümdür visalin,feryat ne çare,yâre senzizce varasın.', 'Sevda denilen dert,sıtmadan betermi beter. Gömleği yok, çul deyip,çekip çöpe atasın. Gündüz hayalde, gece rüyada, yakarmı yakar. Narı canına...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-ve-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Yoğunluğum', 'duygu-yogunlugum-mustafa-sami-235w1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşka dönüşecek bir tutkuydu 

____İçimden atamadığım

Ne zaman uzaklaşmak istediysem 

____Yakınlaştığım

______Bırakmadın peşimi

______Duygu yoğunluğum', 'Aşka dönüşecek bir tutkuydu  ____İçimden atamadığım Ne zaman uzaklaşmak istediysem  ____Yakınlaştığım ______Bırakmadın peşimi ______Duygu yo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/duygu-yogunlugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pes', 'pes-ali-riza-unal-68w5j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah bilirdim zati hal ile sineni pes

her hicaptan faş ettin didemi pes

Zatı haline halveti vucudum pes.

Ezelden visalim,mevtim varına pes', 'Ah bilirdim zati hal ile sineni pes her hicaptan faş ettin didemi pes Zatı haline halveti vucudum pes. Ezelden visalim,mevtim varına pes...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pes-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığı', 'ay-isigi-mustafa-sami-q3t0n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimdeki hercai çocuğun

Niye bu saatlerde gezip dolaştığını

_____Nasıl anlatabilirim ki 

Gecenin sessizliği üzerimdeyken

__Nasıl huzur bulabilirim söyle 

Neden gam ile dolu şu gönlüm

___Hadi söyle bana ay ışığı 

___Şu gönlümdeki fırtınayı

______Nasıl dindirebilirim', 'İçimdeki hercai çocuğun Niye bu saatlerde gezip dolaştığını _____Nasıl anlatabilirim ki  Gecenin sessizliği üzerimdeyken __Nasıl huzur bulab...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ay-isigi-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sene de Geçti Mevsim Sonbahar', 'bu-sene-de-gecti-mevsim-sonbahar-mustafa-sami-obbmx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya tiyatro, biz figüranlarız

Rollerimizi okumadan oynarız

Halimize bazen güler bazen ağlarız

Söyleyin, böyle daha kaç yıl yaşarız

Bu sene de geçti mevsim sonbahar

Ağaç dalında dökülen yapraklar gibi

Ömrümden bir yıldız daha kayar

Söyleyin, böyle daha kaç bahar yaşarız', 'Dünya tiyatro, biz figüranlarız Rollerimizi okumadan oynarız Halimize bazen güler bazen ağlarız Söyleyin, böyle daha kaç yıl yaşarız Bu sene...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sami']::text[], 8.5, '{"poet":"Mustafa Sami","poet_slug":"mustafa-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-sene-de-gecti-mevsim-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefâ', 'vef-ali-riza-unal-64jo8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilirdim senin ahde, vefâsızlığını.

Gördümki sen aşkada,vefasızmışşın.

Bilmemki bu senin, kaçıncı yüzün.

Bilki bir gün çekersin yalanı sefasızlığını.

Ne fark eder, hevâ sende, mübâh iken.

Bi haddi  yırtmışsın,ar’ın hayayasızlığını.

Günâhın kahrettikçe,vicdanını elem,elem.

Haydi tut avazını,sûkût et sedasızlığını.', 'Bilirdim senin ahde, vefâsızlığını. Gördümki sen aşkada,vefasızmışşın. Bilmemki bu senin, kaçıncı yüzün. Bilki bir gün çekersin yalanı sefas...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vefa-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teklif', 'teklif-ali-riza-unal-913ys', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Küfrükâr tanımaz helâlı,yutar haramı.

Şeytan azdırır sanmaki siler günahı.

Sen hayrı şerri,nefsinde ara, birde mübâhı.

Var mürşidi kâmile,bulursun secdeyi rahmanı.', 'Küfrükâr tanımaz helâlı,yutar haramı. Şeytan azdırır sanmaki siler günahı. Sen hayrı şerri,nefsinde ara, birde mübâhı. Var mürşidi kâmile,bu...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/teklif-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül, Dil ve Dudaklar…', 'gonul-dil-ve-dudaklar-muammer-celik-elyp0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Binlerce duygu ile yürür gönül dilin üstünde

dil dudaklara vurur, damak ayyuka durur

durdukca çözülür beden beden üstünde...

Terler akar

gözler bakar 

ırmaklar gibi coşar 

tutmak ne mümkün

soysuzca, hoyratca 

isyandan isyana koşarlar… 

Adım adım kapanır yollar 

yürekler avuçlarda atar… 

Dudaklar… 

Dudaklar…

Dişlerin arasında 

koparlar

Kanarlar

ve gül açarlar... 

Yanar eller ve avuçlar

tutuşur bacalar… 

RUH! 

can havliyle kurtulmaya çabalar... 

Evrensel özgürlüktür kurtulduğu an’ın adı 

orgazmdır sevgilinin bağrında özgürleşmenin tadı... 

31.05.2005

BirDeli', 'Binlerce duygu ile yürür gönül dilin üstünde dil dudaklara vurur, damak ayyuka durur durdukca çözülür beden beden üstünde... Terler akar göz...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gonul-dil-ve-dudaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leb-i Derya', 'leb-i-derya-sumru-karabas-1nczl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat böyle 

Anlamsız bir şey işte

Ne yaparsan yap

Kimsesizliğinin çaresi yoktur

Bildiğin her şey

Aslında bir yok oluştur

Acıyla için kıvranırken

Yüzün sahte tebessümlere bezenir

Ve sen

Her yüzde biraz daha eskir

Biraz daha içine ağlarsın

Biraz daha özlersin

Sana dokunacak

Bir bakışı....', 'Hayat böyle  Anlamsız bir şey işte Ne yaparsan yap Kimsesizliğinin çaresi yoktur Bildiğin her şey Aslında bir yok oluştur Acıyla için kıvran...', ARRAY['Türk Edebiyatı','Şiir','Sumru Karabaş']::text[], 8.5, '{"poet":"Sumru Karabaş","poet_slug":"sumru-karabas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/leb-i-derya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvağın Olayım Simsiyah', 'duvagin-olayim-simsiyah-ayhan-yavuz-acikgoz-tkjl8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duvağın olayım simsiyah...

Gerdanına kadar inip,

Saklayayım seni 

          herkesten...

Değmesin...

Ne bir soysuzun arsız eli,

Ne de bir hâsidin nazarı...

Değmesin...

Sakla gözlerini...

Yalnız ben dokunabileyim tülüne...

                         ve yalnız bana bak...

Kıskanırım...

Bırak,

    duvağın olayım simsiyah...

Bırak,

    tek elbisen olayım,

                kefeninden önce...

Bırak...

(istanbul-30.05.2005)', 'Duvağın olayım simsiyah... Gerdanına kadar inip, Saklayayım seni            herkesten... Değmesin... Ne bir soysuzun arsız eli, Ne de bir hâ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/duvagin-olayim-simsiyah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma, Utanıyorum', 'bakma-utaniyorum-ayhan-yavuz-acikgoz-ecoal', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne var? 

Ne bakıyorsun? 

Hiç mi ağlayan adam görmedin? 

Tamam...

Belki; 

Ağlarken ıslanan sakalı...

Kıpkırmızı olan mavi gözlerinin etrafı...

Ve bağırarak hıçkıran birini...

Ben de görmedim...

Olsun! 

Gene de bakma! 

Utanıyorum...

(istanbul-29.05.2005)', 'Ne var?  Ne bakıyorsun?  Hiç mi ağlayan adam görmedin?  Tamam... Belki;  Ağlarken ıslanan sakalı... Kıpkırmızı olan mavi gözlerinin etrafı.....', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bakma-utaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidince Anladım, Sevmiyormuşum', 'gidince-anladim-sevmiyormusum-ayhan-yavuz-acikgoz-8n2fs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sükûnet...

Sessiz ve tatlı...

Oh...

Ne güzel...

Üzgünüm...

Ben seni değil,

      sensizliği seviyormuşum...

Gidince anladım...

(istanbul-30.05.2005)', 'Sükûnet... Sessiz ve tatlı... Oh... Ne güzel... Üzgünüm... Ben seni değil,       sensizliği seviyormuşum... Gidince anladım... (istanbul-30....', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gidince-anladim-sevmiyormusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölemedim', 'olemedim-ayhan-yavuz-acikgoz-br0x5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey Dermân''ım, kelâmının yerini

Bulamadım

Avunmaktan, cennetin değerini

Bilemedim

Bezensin istedim dünya sırçaya

Aldandım, boyası yalan fırçaya

Koskoca ekmeği iki parçaya

Bölemedim

Yürürken önüme dağlar dikildi

Tarlama verimsiz tohum ekildi

Baktım ki damardan kanlar çekildi

Ölemedim

(istanbul-30.05.2005)', 'Ey Dermân''ım, kelâmının yerini Bulamadım Avunmaktan, cennetin değerini Bilemedim Bezensin istedim dünya sırçaya Aldandım, boyası yalan fırça...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olemedim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Yâr', 'gitme-y-r-ayhan-yavuz-acikgoz-d8puo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gitme yâr uzağa

Düşersin tuzağa

Bakmazlar yaşına

Orda bir başına

Feryadın'' duymazlar

Sevincin'' koymazlar

Özlersin yurdunu

Bilmezler derdini

Gurbetlik sert vurur

Olmadı, dert vurur

Ağlayıp durursun

Sararıp kurursun

Ayhan''ın gün sayar

Gitme yâr, gitme yâr

(istanbul-28.05.2005)', 'Gitme yâr uzağa Düşersin tuzağa Bakmazlar yaşına Orda bir başına Feryadın'' duymazlar Sevincin'' koymazlar Özlersin yurdunu Bilmezler derdini ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gitme-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mert Vurur Bazen', 'mert-vurur-bazen-ayhan-yavuz-acikgoz-85hjf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kader bu bilinmez, sert vurur bazen

Gözlerin nemlenir, dert vurur bazen

Sanma ki kar yağmaz, büyük dağlara

Kalleşler dinlenir, mert vurur bazen

(adana-2004)', 'Kader bu bilinmez, sert vurur bazen Gözlerin nemlenir, dert vurur bazen Sanma ki kar yağmaz, büyük dağlara Kalleşler dinlenir, mert vurur ba...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mert-vurur-bazen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar da Ağlar', 'daglar-da-aglar-ayhan-yavuz-acikgoz-nohi9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlar...

Suskun ve duygusuz,

Büyük ve kaygısız,

             sandığın dağlar

Yağmur yağınca,

Onlar da ağlar...

(istanbul-25.05.2005)', 'Dağlar... Suskun ve duygusuz, Büyük ve kaygısız,              sandığın dağlar Yağmur yağınca, Onlar da ağlar... (istanbul-25.05.2005)...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/daglar-da-aglar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin Sen', 'kimsin-sen-ayhan-yavuz-acikgoz-8l6xw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimsin sen? 

Ocak mısın, ekmek misin, nan mısın? 

Kimsin sen? 

Ömür müsün, saat misin, an mısın? 

Kimsin sen? 

Kemik misin, deri misin, kan mısın? 

Kimsin sen? 

Yürek misin, gönül müsün, can mısın? 

Kimsin sen? 

Kral mısın, sultan mısın, han mısın? 

Kimsin sen? 

Onur musun, şeref misin, şan mısın? 

Kimsin sen? 

Gece misin, şafak mısın, tan mısın? 

Yoksa aşktan kavrulan Ayhan mısın? 

(istanbul-31.05.2005)', 'Kimsin sen?  Ocak mısın, ekmek misin, nan mısın?  Kimsin sen?  Ömür müsün, saat misin, an mısın?  Kimsin sen?  Kemik misin, deri misin, kan ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimsin-sen-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zora Gidiyor', 'zora-gidiyor-ayhan-yavuz-acikgoz-bm79u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasihate cür''et edemez olduk

Ne söylense gayrı zora gidiyor

Serinliğe bedel ödemez olduk

Tüm rüzgârlar yanıp kora gidiyor

(istanbul-31.05.2004)', 'Nasihate cür''et edemez olduk Ne söylense gayrı zora gidiyor Serinliğe bedel ödemez olduk Tüm rüzgârlar yanıp kora gidiyor (istanbul-31.05.20...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zora-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Sanatı', 'aglama-sanati-ayhan-yavuz-acikgoz-f0z35', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak oğlum bu gördüğün gözyaşıdır

Korkağın utancı, merdin aşıdır

Ağlamak bir nevî def-i hâcettir

Gülmeyi unutmak yolun başıdır

Doğarken anandan ağlarsın önce

Gözünden katreler süzülür ince

Kahkaha, bahçende gül ise eğer

Ağlamak Sahra''da açılan gonca

Sorsalar ''Ne'' diye bana, son sözün

Derim ki ''Ağla ki, çağlasın gözün''

Eğer ağlayacak bir hâl bulursan

Gözünden akanla paklanır özün

Ağlayan dereler, akar denize

Başaklar yağmurla geliyor dize

Ağlamak, yanmanın çaresi olsa

Nebî''nin gözyaşı yeterdi bize

Gözyaşı üstüne bir şiir yazdım

Bak oğlum, altına imzamı kazdım

Ağlamak, karası olsaydı yüzün

Deden ağlamazdı, ben ağlamazdım

(istanbul-01.06.2005)', 'Bak oğlum bu gördüğün gözyaşıdır Korkağın utancı, merdin aşıdır Ağlamak bir nevî def-i hâcettir Gülmeyi unutmak yolun başıdır Doğarken anand...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aglama-sanati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Martı...', 'sessiz-marti-cigdem-simsek-4rc9o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessiz martı …

Yüreğime süzüldün yavaşça.

Ne getirdin bana? 

Dostluk mu? 

Sevgi mi? 

Aşk mı? 

Yoksa yine Acı mı?', 'Sessiz martı … Yüreğime süzüldün yavaşça. Ne getirdin bana?  Dostluk mu?  Sevgi mi?  Aşk mı?  Yoksa yine Acı mı?...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sessiz-marti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Sus', 'yuregim-sus-dua-ekseni-bw2dj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sus yüreğim Sus! 

Hiç düşünmeden

Tahtına oturtup

Baş köşeyi verişini

İçinde fırtınalar kopup

Deli rüzgarların esişini

Özlemle dopdolu

İç çekişini

Avaz avaz haykıran 

sevda sesini duymayan

Can…

…

Sus yüreğim sus! 

Şimdi nedir bu ahû zarın? 

Bu sevdadan acıdır payın

Sermayen gözyaşı

Hasret kârın

At yükünü omsuzdan

Ölümlüye sevdalardan arın

Yürek yangınına,çığlığına

Kulak tıkayan

Can..

Yüreğimin sesine kulak verip

Fısıltısını duyarmısın

… a  Can’ım? ! ...

(duaekseni)', 'Sus yüreğim Sus!  Hiç düşünmeden Tahtına oturtup Baş köşeyi verişini İçinde fırtınalar kopup Deli rüzgarların esişini Özlemle dopdolu İç çek...', ARRAY['Türk Edebiyatı','Şiir','Dua Ekseni']::text[], 8.5, '{"poet":"Dua Ekseni","poet_slug":"dua-ekseni","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yuregim-sus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-mehmet-nuri-gezmis-24c32', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hizmetin, himmetin, hikmetin başı,

Küçük yumurcakların ekmeği, aşı,

Yeni başlayan günün tatlı telâşı,

Hizmet kervanının lideri SEVGİ.

Gönüller dağından esen bir yeldir,

Azim obasından akan bir seldir,

Verdiği huzur bir ömre bedeldir,

Nesil şerbetinin şekeri SEVGİ.

Dünyada zaten kin, nefret yaygın,

Sevgi olmadan olunmaz saygın,

Sevgisiz yerlere çokıyor yangın,

Yangın yerlerinin suyudur SEVGİ.

Kin, garaz kötü niyetin eşi,

İyi niyet, güler yüzün güneşi,

Bu kelimenin yoktur dünyada eşi,

Buzul dağlarının ateşi SEVGİ.

O olmasaydı, biz de olmazdık,

Gönül bahçelerini onunla kazdık,

Bilgiyi ilgiyle onunla yazdık,

yaşama hakkının gayesi SEVGİ.

Geçer akçedir her zamanda, her çağda,

yarıyor her derde, yaraya fayda,

Ondan başkası değmiyor kayda,

Hayat yumağının ipliği SEVGİ.

    

  (O.Çelik / M.N.Gezmiş- Gölköy)', 'Hizmetin, himmetin, hikmetin başı, Küçük yumurcakların ekmeği, aşı, Yeni başlayan günün tatlı telâşı, Hizmet kervanının lideri SEVGİ. Gönüll...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Gezmiş']::text[], 8.5, '{"poet":"Mehmet Nuri Gezmiş","poet_slug":"mehmet-nuri-gezmis","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgi-182-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum...', 'dostum-ayfer-yildiz-qxg38', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güvenme böyle dostum kendine,

Öyle bir zaman olur ki şaşar kalırsın haline,

Ayağın takılırda bi düşersen amansız derde,

Rastlarsın inan dost bildiğin yüzlerdeki ihanete...

Büyüklenme böyle dostum sakın,

Ölüm hepimize dünden daha yakın,

Garantisini kim verebilirki bize yarının,

Kimseyi hor görmeyesin büyüsüne kapılıpta o sahte paranın...

El açma kuluna dostum gücüne gider allahın,

Kulluk etme kapısında allahsız ve imansızın

Şüphe duyupta yanılma adaletinden o yüce hakkın.

Duymazdan gelme dostum sana ulaşan feryadı,

Düşünmeden tutacak garibin her bir ahı,

Muhtaca uzanan bir eldir bazen aralayan cennet kapısını,

Sen tokken unutma açıktaki aç insanı...

Yüreğini sarmasın dostum yıpratan hain duygular,

Şu üç günlük dünyada nefrete kine ne gerek var,

Harcanıp gidiyor hesapsızca zalim yıllar,

Biçilmiş ömrümüz vakit toprağa kadar...', 'Güvenme böyle dostum kendine, Öyle bir zaman olur ki şaşar kalırsın haline, Ayağın takılırda bi düşersen amansız derde, Rastlarsın inan dost...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Yıldız']::text[], 8.5, '{"poet":"Ayfer Yıldız","poet_slug":"ayfer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dostum-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-mehmet-nuri-gezmis-r8ax0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her zaman başımızda dalgalan rahat rahat,

Uğrunda ölmek için bekliyoruz her saat.

Rengin bizim kanımız, rüzgârınsa canımız,

O tertemiz halinle aşığınız oğul, kız.

Hürriyet ve istiklâl, devrilmeyen gönderin,

Ülkem senin gölgende kendi kendinden emin.

Savaşta ve barışta naşımın üstündesin,

Gözbebeğimde ışık, ruhumda bir bestesin.

Cihanın her yerinde selâm durulsun sana,

Kahraman milletimin sevgisine baksana.

seyrederken alemi, nazlı nazlı yüksekten,

Bu milleti bağrında taşıyorsun gerçekten.

Sen! Zaten arştan inip aşık oldun kanıma,

Sen! Yine arşa yüksel, yakışır bu şanına.

Her zaman milletimin kalbiyle kucaklaştın,

Türklüksün, ülkümüzsün, bir ruhsun, bayraklaştın.', 'Her zaman başımızda dalgalan rahat rahat, Uğrunda ölmek için bekliyoruz her saat. Rengin bizim kanımız, rüzgârınsa canımız, O tertemiz halin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Gezmiş']::text[], 8.5, '{"poet":"Mehmet Nuri Gezmiş","poet_slug":"mehmet-nuri-gezmis","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bayragim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seven Yüreğimi Seviyorum', 'seni-seven-yuregimi-seviyorum-doner-ozeke-csrj5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni seven sana aşık kalbimi seviyorum 

Sana uzanan ellerimi bana bakan gözlerini

Sana karşı duyduğum ilahi askı seviyorum 

Kendime bile anlatamadığım aşkı seviyorum 

Hani ürpererek yaslanmıştın ya omuzuma 

O benliğimi saran sımsıcak nefesin varya 

Bana dünyaları veren deniz mavisi gözlerini 

Beni hayallere düşüren seni seviyorum

Nasıl desem nasıl anlatsam bilmiyorum 

Beni yalnız bırakıp giden gecelerinden 

Sensiz olduğum günlerimden nefret ediyorum 

Bana aşkla bakan gözlerini seviyorum 

Hadi aşkım cabuk ol mevsimler bitiyor 

Günler, aylar,yıllar sensiz yalnız geciyor

Sen olmayınca yanımda öfkem dinmiyor 

Seni sen olduğun için coookkk  seviyorum 

                 DÖNER TEMÜR  

                     01.06.2005 

                        ANKARA', 'Seni seven sana aşık kalbimi seviyorum  Sana uzanan ellerimi bana bakan gözlerini Sana karşı duyduğum ilahi askı seviyorum  Kendime bile anl...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-seven-yuregimi-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verme...', 'verme-veysel-alkan-sw81z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüce Tanrım hiç kimseye

Ceza diye,ibret diye

Benzemeyen hiç bir şeye

Bet suratlı hanım verme..

Yemekleri,zehir tuzlu

Üstü başı kirli,tozlu

Çok cilveli,az namuslu

Gözü yolda hanım verme...

Evladını hoş tutmayan

Dırdır eden,hiç susmayan

Geceleri uyutmayan

Boş boğazlı hanım veme...

Akrabaya sırtı dönük

Dili uzun,beyni küçük

Çok gururlu,özrü büyük

Gün görmemiş hanım verme...

Pantolonu ütülemez

Gömlekleri kolalamaz

Kıymet bilmez,laf anlamaz

Dik kafalı hanım verme...

Uveys diler; emrin bilsin

Erkeğine hürmet etsin

Öfkeliyken ağzın tutsun

Acı dilli hanım verme...', 'Yüce Tanrım hiç kimseye Ceza diye,ibret diye Benzemeyen hiç bir şeye Bet suratlı hanım verme.. Yemekleri,zehir tuzlu Üstü başı kirli,tozlu Ç...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/verme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Kibrit', 'elimde-kibrit-meral-yagcioglu-gwtub', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buram buram anı kokan 

Mutlu günlerin yansıması 

Dolu, dopdolu yaşadığımız 

Anılarımızın resimlerini 

Serdim yere teker teker. 

Elimde kibrit tam ortasına 

Bağdaş kurdum

Denize karşı bir bankta, başım göğsünde 

Martılara el salladığımız an sağımda 

Tavşan kanı çayımızı yudumlarken 

İçime doldu sokak simidinin kokusu solumdan 

İlk tartıştığımız gün ki titrek sesin arkamdan seslendi 

Doğum günümde aldığın minik ayıcık

Dizlerimin dibinde yüzüme bakıyor kederli

Canlanan anılar 

Sızlattı gönül telimi 

İğnelendi bedenim 

Yüreğim oldu kan revan 

Kibriti çakar çakmaz 

Titrek alev kızıllığında 

Başa sarıldı günler

Gözlerimin önünden 

Geçiverdi film şeridi

Verdiğin o gonca gülün dikenini 

Söküp attım göğsümden ateşin kucağına 

Sıcaklığını hala hissettiğim ellerin 

Avuçlarımdan kaydı, çıra oldu ateşi mayaladı

İçtim soğuk su kristal kadehten 

Düğümlendi yudumlarım boğazımda 

Tutuştu dilsiz resimler 

Anılarla birlikte her şeyi

Acıyı, ıstırabı,kederi 

Yokluğunu silercesine 

Sessiz büklüm büklüm kıvrandı her biri 

Alevlerin koynunda kor oldu kayboldu ben gibi 

Bir fırtına koptu 

Yangın yerinin isli külleri 

Çıkmamacasına savruldu

İz oldu yüreğime katran karası

	      2001', 'Buram buram anı kokan  Mutlu günlerin yansıması  Dolu, dopdolu yaşadığımız  Anılarımızın resimlerini  Serdim yere teker teker.  Elimde kibri...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/elimde-kibrit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-i-brahim-balci-ukciw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soruyorum kadim merafimlere

Bu gecelerin sırrı ne

Neden bu hüzün

Sebepsiz neşelenmem

Ağlamak,ağlamak istediğimde

Kahkahalarımla başbaşa iken

Neden hep gece

Ağartarak ak gözlerini

Bakıyorlar önlerine

“O geceler ki

Yaratırken Tanrı

Tüm hayvanatı ve nebatatı

İnsanoğluyla birlikte

Ve yerleri ve gökleri

Dinlenmesi için insanoğlunun

Hasıl etti geceyi

Gece uzun gece karanlık

Dinlenince insanoğlunun bedeni

Keşfe çıkar 

Diğer bedendeki kendini”

Geceler özlem

Geceler tutku

Geceler hasret

Geceler senle

Ve sensizlikle yüklü', 'Soruyorum kadim merafimlere Bu gecelerin sırrı ne Neden bu hüzün Sebepsiz neşelenmem Ağlamak,ağlamak istediğimde Kahkahalarımla başbaşa iken...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gece-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsiz Değil', 'sebepsiz-degil-melih-coskun-p3pxe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sebepsiz değil, 

Midende kramp, 

Sol kolundaki dinmeyen sancı, 

Damarlarını hırpalarcasına coşan kan

Ve tüm gördükleriniz koskoca bir yalan

Bildiğinizi sandığınız 

En büyük yanılgınızdır aslında. 

Sebepsiz değil 

Mavi rengin daha da güzelleşmesi 

Yükselen nabız 

Alevlenen ten

İçindeki bu titreme soğuktan değil 

Yorgunluktan değil tutmayışı dizlerinin. 

Tüm yaşanılan 

Koskoca bir yalan.

Aşk gerçek...', 'Sebepsiz değil,  Midende kramp,  Sol kolundaki dinmeyen sancı,  Damarlarını hırpalarcasına coşan kan Ve tüm gördükleriniz koskoca bir yalan ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sebepsiz-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Hecelemek...', 'aski-hecelemek-i-brahim-ethem-bingul-kb1n6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Parçalanmışlığın en koyusunda

Sessiz ağlamanın yokuşundayım

Dipsiz derinliğin kör kuyusunda

Hükümsüz suçlular koğuşundayım...

Beklemek... Beklemek... Alnımda yazım

Yarime dilekçe sunuşundayım

Aşkı hecelemek Hak'' tan niyazım

Sevgiliye selâm duruşundayım...

Gözlerden gönüle yol arıyorum

Nasıl olur, bunun soruşundayım

Kalpten kalbe kapı aralıyorum

Gönül pınarında aşk duşundayım...

Sermayem bitiyor ömür kabında

Çil liram tükendi, kuruşundayım

Çöl dünyamda gözüm aşk serabında

Son hamlem, varoluş vuruşundayım...

www.iebingul.com', 'Parçalanmışlığın en koyusunda Sessiz ağlamanın yokuşundayım Dipsiz derinliğin kör kuyusunda Hükümsüz suçlular koğuşundayım... Beklemek... Be...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aski-hecelemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-necmiye-sarpkaya-3m21r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiirler yazılır adına

Adaklar yapılır

Şarkılar bestelenir

Türküler söylenir

Efsunlu ela gözlerine

Gözbebeğindeki sihirli bene

Saçının her teline

İncecik beline

Gönüller bağlanır

Hayaller süslersin Leyla

Düşler var görülecek

Ömürler var  yaşanacak

Sefalar var sürülecek

Her gönülde

Her akılda

Her yaşta

Her başta

Yerin var Leyla

Zarif ellerde kır çiçekleri

Kimi gün papatya

Kimi gün gelincik

Kimi gün güller

Evaze etekleri savurarak

Kumral saçları rüzgara vererek

Alımlı çalımlı yürüyüşün var Leyla

Yollara dizilir aşıkların

Yataklara düşer tutkunların

Umursamaz eda ile

Salına salına geçip gidişin var Leyla

Reddersin bütün aşkları

Geri çevirirsin teklifleri

Kanmazsın yaldızlı sözlere

Gülüp geçişlerin var Leyla

Gamzeli gül yüzün

Hoş hallerin

Tatlı Dillerin

Sıcacık minik gülüşlerin

Seke seke yürüyüşün var Leyla

01.06.2005

(Bir Leyla Şiir de benden sevgili şair dostlarım)', 'Şiirler yazılır adına Adaklar yapılır Şarkılar bestelenir Türküler söylenir Efsunlu ela gözlerine Gözbebeğindeki sihirli bene Saçının her te...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/leyla-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale''de Bir Garip Akşam', 'canakkale-de-bir-garip-aksam-zekeriyya-bican-x4frh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çanakkale’de o gün, çarmıha gerilecekmiş şanlı bayrağımız güya,

Anadolu’m  buradan esir alınacakmış, şaşkınların rüyaları bu ya...

Ne garip bir hayal ki kurdukları, çarpıldılar o haşmetli orduya,

Alınları yere değdi o gün, sarsıldı yürekleri “Allâh” nidalarıyla! 

Kilitbahir’de kilitlendi  kapılar düşman çizmesine, sonsuza kadar,

Kahpe kurşunlar, toplar, vatan sevdalısı yüreklere çarpıp kaldılar! 

Analar evlatlarını, bilerek bu vatan için  cennete uğurladılar,

Lakin düşman sevinmesin diyerek, açıktan açığa hiç mi hiç ağlamadılar.

Eller kenetlendi, yürekler birleşti, Ardahan’dan Çanakkale’ye kadar...

Şanla şerefle dolu tarihlerine, ne güzel anılar yaşayıp bıraktılar.

Elemleri gidip de dönmemek değildi, vatanı uğrunaydı o askerlerin,

Hiç dönmeyecekmiş gibi çıkardı yola anaları, o şanlı Mehmet’lerin.

İman dolu yürekler döşenmişti, sınır taşları yerine bütün Anadolu’ya,

Tanıktır şimdi orada, tabyalarda aynı kahpe kurşunları hisseden taşlar...

Lâkin nasıl anlatmalı bilmem ki, o askerin tasviri yapılabilir mi ki?

Elem yoktu gözlerinde,  ön sırada bir bir düşerken  nazenin başlar,

Ruhları şerefiyle yükseliyordu, vurulup düşerken, ta  arş’a kadar! 

İnsan bu, üzülmemek elde değil, biz hâlâ  elemlerdeyiz.

Nar çiçeği renginde bu akşam şahittir,  şu dağ, şu tepe, bu deniz,

Ellerdeki renk kınadan değil, bu nedenle ağlarız, yaşarır gözlerimiz...

Settülbahir’de denizin karayı öptüğü yerde, ağlar bir sevgili hâlâ,

Ellerini açıp bekler,  sonra naralar gibi ünlenir bütün Anadolu’ya! 

Lâl olur bu sesten, lâl olur rüzgar, yine geçer gider öte yakaya,

‘Al tüfeğini geri gel, hani düğün yapacaktık, değil mi gelecek bahara! 

Maalesef gelmeyeceksin’ derken, boynu bükük bir taze gelin adayı...

Oyalı yazmalar,daha kaç asır çeyiz sandıklarında öylece kalacaklar,

Lisanımda kelimeler yetmese de, eminim nice dillerden seni anlatacaklar.

Sabırla bekleyeceğim, sen gelmesen de bir gün ben sana geleceğim...

Unuttuk sanma sakın, hatıranı destanlara yazıp da söyleyeceğim,

Ne kadar zaman geçerse geçsin, şehitlik rütbeni başıma taç edeceğim.

Bu büyük emanetin nöbeti bitmeyecek, yerine  ben bekleyeceğim,

İçiniz rahat olsun, huzurla yatın, bir karış toprak bile vermeyeceğim,

Cihan toplanıp yeniden üstüme varsa, düşmana sırtımı dönmeyeceğim.

Analar da bekler bu kutsal nöbetleri, analar da savaşır bu vatan için,

Nasırlı ellerde dualar da  yükselir arşa, yükselir  bu kutsal topraklar için! ..     

NOT: Akrostişt şiirdir

						

Zekeriyya BİCAN', 'Çanakkale’de o gün, çarmıha gerilecekmiş şanlı bayrağımız güya, Anadolu’m  buradan esir alınacakmış, şaşkınların rüyaları bu ya... Ne garip ...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/canakkale-de-bir-garip-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız değilim...', 'yalniz-degilim-cemal-nalci-hbj3q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yalnız değilim

gecenin karanlığıyladır

		sohbetim...

düşünürken seni burada

suskun dudaklarınla örtündüm...

gece; 

fırtına öncesi beklemede

ben; 

kısık gözlerimi

gecenin karanlık gözlerine dikip

			haykırdım! ..

vücudum bir yerde

	ruhum ise zapt edilmez bir halde

beni anlattım...

titreyen dudaklarımla

	boğum

		boğuk sesimle.. 

			yalnız değilim! ..

gecenin karanlığıyladır

		sohbetim...

beni anlattım ya! ..	

ne ben anlayabildim...

		ne de...

karanlık gözleri daldı ya gecenin

bir dokunsam

	ya da

	bir dokunsa

	kopup gelecek ya...

	her biri hasret yüklü

	her biri özlem,

		yağmur damlalarında...

…

dinlerim karanlıkta geceyi

sevgi dolu yürekleri duyarım

	fırtına öncesi gecede 

	fırtınalar kopar yüreğimde…

ben yalnız değilim

dokunamam sana

	dayanmaz yüreğim...

yalnız değilim

0209042346pb

cemalnalcı', 'yalnız değilim gecenin karanlığıyladır 		sohbetim... düşünürken seni burada suskun dudaklarınla örtündüm... gece;  fırtına öncesi beklemede ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Nalcı']::text[], 8.5, '{"poet":"Cemal Nalcı","poet_slug":"cemal-nalci","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yalniz-degilim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verdiğin Acıları Unutmak için', 'verdigin-acilari-unutmak-icin-veli-dalbudak-xqyhu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir çizgi çektim tüm geçmişe,

Verdiğin acıları unutmak için,

Umutla baktim geleceğe,

Verdiğin acıları unutmak için.

Yalanda olsa, zorda olsa güldüm,

Ne kadar yazdıysam o kadar sildim,

Gideni zarar, geleni kar bildim,

Verdiğin acıları unutmak için.

Kapılmadığım yel kalmadı,

Yalvarmadığım el kalmadı,

Baş vurmadığım yol kalmadı,

Verdiğin acıları unutmak için.

iliklerime işlemişin, sökemedim,

Denizmişin  meğer, dökemedim,

Ölmek istedim bazan, ölemedim,

Verdiğin acıları unutmak için.

.............................Yinede olmadı,

...............Acın peşimi bırakmadı.

(Stockholm 2003)', 'Bir çizgi çektim tüm geçmişe, Verdiğin acıları unutmak için, Umutla baktim geleceğe, Verdiğin acıları unutmak için. Yalanda olsa, zorda olsa...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/verdigin-acilari-unutmak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç bahar soldu? ..', 'kac-bahar-soldu-cemal-nalci-1drvv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'beklerim,

