INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-mehmet-baki-erfidan-5cb11', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda

Deli gönlün deli kanıydı akan baharda,

Çılgın sel gibi bendini çiğneyip aşınca,

Sevda demişlerdi, gün gelir geçerdi,

Bir anı gibi o da kalacaktı hatıralarda.

Anı değil, bir hayattı, hayat için gerekli bir gıda,

Hep beraberdi yalnız bırakmadı,

Ne gece, ne gündüz, ne de engin tufanlarda.

Sevdaydı amma geçenlerden değil,

Seçtiği sabit bir nokta, kaypak zemin değil,

Dumura uğramış beyinlerin leş nefesleri,

Kokuşmuş fahişe dolu caddeleri,

Kulu, kulun yaptığına kul eden o parlak fikirleri,

Farksızdı gözünde, ha onlar, ha lağım fareleri,

Yoktu payesi içinde sahte gülücüklerin,

Pusuda bekleyen aç kurtların,

Ve paraya sevdalanan aşiftelerin,

Onun için anlamı farklıydı sevdanın.

Sevmek gönlünü vermek, bağlanma belki amma,

Çok üstündeydi bunların,

Çok uzaklardaydı anlamı sevdanın.

Sevda, benliğiydi, kişiliği, hem de fikri,

Soğuk gecelerde kanı ısıtan şarap iksiri,

Sadece gülerken değil, ağlarken de yanında,

Berzahtan ebede giden sonsuz yolculukta', 'Sevda Deli gönlün deli kanıydı akan baharda, Çılgın sel gibi bendini çiğneyip aşınca, Sevda demişlerdi, gün gelir geçerdi, Bir anı gibi o da...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Baki Erfidan']::text[], 8.5, '{"poet":"Mehmet Baki Erfidan","poet_slug":"mehmet-baki-erfidan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevda-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostuma', 'dostuma-alaeddin-i-kican-k1e3i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'S anmaki ismini bilmeden,cismini görmeden arkadaş olunmaz,

        O nu düşünen kişilerin meyve ağacına dost kuşu konmaz,

        N e aradığını bilmezsen o hiçbir yerde bulunmaz,

        E minim sen de bu düşüncelerde olmasaydın eğer,

        R üzgar gibi esen dostluk kervanına katılmazdın Soner.

        S anki bir şeye kırılmışsın diyor gönlüm bana,

        A ncak hatırlayamadım nasıl bir hata ettim sana,

        Y anıldığımı sanıyorum bakışın dürüstlüğü simgeliyor,

         I şık saçan gözlerin içtenliğini gösteriyor,

        N e dersen de dostum sen benim hemşehrimsin,

        S evgi ve dostlukla başlayan ebedi kardeşimsin,

        Ö lümün dahi ayırmak için yarattığı engelleri,

        Z orlanmadan yok edecek düşünceye sahip toprağımsın.

								

       Bu şiir Şair Alaeddin İKİCAN''a ait ''SEVGİDEN ÖTESİ YOK'' isimli şiir kitabından alınmıştır.', 'S anmaki ismini bilmeden,cismini görmeden arkadaş olunmaz,         O nu düşünen kişilerin meyve ağacına dost kuşu konmaz,         N e aradığ...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dostuma-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü', 'olu-serhat-sumer-tzgzz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adamın bedeni

Cansız kalakaldı

Hastalıklı yatağında.

Karısı eyvah! dedi 

Büktü boynunu

Anlamaya çalıştı herkes

Kaderin oyununu.

Yüreklerine gam 

Yakıcı bir kor düşüverdi

Sevenleri eyvah! dedi

Işıklar sönüverdi.

Adamın çocuğu 

Yaklaştı babasına 

Koydu ellerini 

Göğsünün ortasına 

Baba dedi yaralayan bir sesle 

Hadi uyansana...

Annesinin gözünden 

Sir damla yaş aktı 

Sildi gözlerini çocuğa baktı 

Oğlum dedi

Baban, baban gitti.

Çocuk 

Ayağıyla sakladı önündeki topu 

Kalkınca dedi oynayacaktık da 

Uyandıracaktım onu', 'Adamın bedeni Cansız kalakaldı Hastalıklı yatağında. Karısı eyvah! dedi  Büktü boynunu Anlamaya çalıştı herkes Kaderin oyununu. Yüreklerine ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefs Ekspresi', 'nefs-ekspresi-burak-killioglu-0tq8b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalpten kalbe yol varmış, bana çıkmazlar düştü

Bırakıp gitmek varken, akbabalar üşüştü

Kendi çıkmazlarımı taşır dururum içimde

Ufuklar açık halbuki türlü çeşitli biçimde

''Ben''den kurtulmadan rahat olmayacak bana

Yollar yardım eder elbet çıkış yolu arayana

Şu gördüğüm ışık belki aydınlığı müjdeliyor

Belki de ''nefs ekspresi'' tam üzerime geliyor', 'Kalpten kalbe yol varmış, bana çıkmazlar düştü Bırakıp gitmek varken, akbabalar üşüştü Kendi çıkmazlarımı taşır dururum içimde Ufuklar açık ...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nefs-ekspresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-mehmet-baki-erfidan-hi885', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor yine dışarıda,

Bayram var bugün toprakta,

Gökyüzü gülüyor, yerde mutluluk,

Hüznü yaşayan insanlar bu bayramda.

Ötelerden bir haber mi var ne? 

Herkeste bir acaip kulak kesilme,

Nefesler tutulmuş, gözler çakmak çakmak,

Örümcek ağı gibi insanlar

Tek düğümle olmuş yumak.

Leyla ile Mecnun çok ibtidai,

Farketmez Kerem ve Aslı, ya da efsanesi,

Unutulmuş Mem u Zin hikayesi,

Hadi gösterin Mehlika Sultan için

Kaf dağında Zümrütü Anka’yı,

Bulmaya giden aşık yedi genci.

Bırakın yedisini vazgeçtim,

Hayalin umudu için hayalde gerçeği arayan,

Var mı gençler arasında bir nefer çıkan? 

Yada içindeki ateşin koru için,

Dağları körük yapan Kerem’i,

Zin için ağayla satranç tahtasında,

At oynatan bir Mem’i,

Aşkı için dağa çıkan Leyla’yı,

Ve dağlarda Leyla’nın aşkında kaybolup,

Leyla’yı terk eden Mecnun’u,

Hani var mı böyle aşkın medyumu? 

Bugün aşklar yıldızlarda,

Yıldızlarda burcu aramak moda,

Burcun hakimi medyum falcılar,

Falcılarda artık fora bayraklar.

Aşklar sözde yaşasın şekilcilik,

Sevgi karın doyurmaz, sadece bir tik,

Doğruluk ve sadakat.... oda ne sözlük gerek,

Bunları konuşurken moda oldu besmele çekmek.

07.11.1994', 'Yağmur yağıyor yine dışarıda, Bayram var bugün toprakta, Gökyüzü gülüyor, yerde mutluluk, Hüznü yaşayan insanlar bu bayramda. Ötelerden bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Baki Erfidan']::text[], 8.5, '{"poet":"Mehmet Baki Erfidan","poet_slug":"mehmet-baki-erfidan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yagmur-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Keyfi', 'sairin-keyfi-cemil-aygen-jqqrb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sene 365 gün

Her gün bir şiir yazsam

365 şiir yapar..İyi mahsul

Ama 65 i defolu çıktı

Daha kafadan zırt pırt tenkitle

İptal oldu 300 şiir kaldı

50 sini ben eledim

Topluma, toplum kurallarına saygı için

Kaldı 250 şiir

50 sini dinleyenlere, eleştirenlere

Burun kıvıranlara feda ettik 

200 şiir

Millet kurban arıyor ya

Mahkemelik olursun...Benzerlik var

İsim hakkı vs..Gitti 50 şiir 

Kaldı 150 net şiir diyorum,Aklı başında 

Hala inat ediyorlar

Yufka yüreğime bastırıyorlar 

50 adet darülacezeye Ayrı kitap ayrı gelir

50 adet Mehmetçik vakfını, veya eğitim için

Kitap yap bas hasılat onların 

Kalan 50 adet klas bir kapak 

Ve ben sakallı Feylazof..Entel bir resimimi bas

İyi bir kitap

Nasılsa anlaşılmayacak...Satmayacak nasılsa

OHH be..Ne zormuş şiir yazmak

Para kazanamamak....', 'Sene 365 gün Her gün bir şiir yazsam 365 şiir yapar..İyi mahsul Ama 65 i defolu çıktı Daha kafadan zırt pırt tenkitle İptal oldu 300 şiir ka...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sairin-keyfi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dönmek', 'geri-donmek-serhat-sumer-hx0yd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen ağlıyordun 

duvardaki saat geceyi vuruyordu

susuyordu takvimler 

masanın üstünde sıcaklığım kalıyordu 

gözlerimin içinde gözlerin

bir martı uçuyordu 

hani vapurdayken ekmek attığımız martılar 

bir yara kanıyordu 

hani ayrılık dediğimizde 

yüreğimizde sızlayan 

sen ağlıyordun 

yıldızlar sönüyordu 

içime bir hüsran çöküyordu.

ayaklarıma bir derman 

gitmek kolay oluyordu böyle zamanlarda 

kalmak çok zor 

sesine sesim çarptığında 

çığlık oluyordu 

ellerin ellerime değdiğinde yangın 

herşey sereserpe 

etrafa saçılıyordu 

bir kristal parçalanıyordu 

göğsümün sol yanında 

darmadağın bir ayrılığa bileniyordum 

sen 

ağlıyordun yalnızca 

gitmek kolay oluyordu böyle zamanlarda 

kalmak çok zor...

can parçam 

söyle şimdi ne haldesin

bıraktığım gibi misin? 

yoksa başka eldemisin? 

dönsem diyorum bir kıyamet zamanı 

dönmek zor..

dön desen 

demen çok zor...', 'sen ağlıyordun  duvardaki saat geceyi vuruyordu susuyordu takvimler  masanın üstünde sıcaklığım kalıyordu  gözlerimin içinde gözlerin bir ma...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/geri-donmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hasankeyf*(Akrostiş)', 'hasankeyf-akrostis-seyhmus-sevilmez-bjjaq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '‘H’er bir uygarlığa, köprüdür taşı

…Medeniyetlerin ili Hasankeyf

…Dicle’yle bir olup, akıtır yaşı

…Bilinmezliklerin dili hasankeyf

‘A’surlar kayayı tek tek kazmıştı

…Sümerler duvara yazı yazmıştı

…Babilliler ise destan çizmişti

…hükümdarlıkların eli Hasankeyf

‘S’üryanilerin tek barınağıydı

…Piskoposlukların dini ağıydı

…Eski ibadetin, merkez bağıydı

…İnanmışlıkların seli Hasankeyf

‘A’rtuklu dönemi, en parlak anı

…Eyubiler ile, yükselir şanı

…Yekpare kalesi, okur destanı

…Egemenliklerin beli Hasankeyf

‘N’ehir yolu ile, mal alıp satmış

…İpek yolundan da, kervanı kapmış

…Nice yüklü tacir, bu yola sapmış

…Zengin ticaretin kolu Hasankeyf

‘K’alesine çıksak iki kapıdan

…Kuş bakışı baksak şehre tepeden

…Gören hayran kalır, eski yapıdan

…Sanat eserinin tülü Hasankeyf

‘E’meviler’den de, izler görülür

…Sanki burda bir tek tarih örülür

…Dört bin mağarayla, keyif sürülür 

…Antik diyarların gülü Hasankeyf

‘Y’ıkayacaklarmış, barajla seni

…Bulanık su bozar, türbe deseni

…Hiç görmüyorlar mı? koca cüsseni

…Olma! vicdansızlık gölü, Hasankeyf

‘F’ıtratım el vermez seni kaybetmem

…Dostun Dicle ile seni yok etmem

…Birkaç çıkarcıya seni yar etmem

…İlgisizliklerin çölü Hasankeyf

(Not: Bu şiiri,  Güzel ilçemiz Hasankeyf''i, tarihiyle birlikte sulara gömmek isteyen zihniyete yönelik kaleme aldım..)', '‘H’er bir uygarlığa, köprüdür taşı …Medeniyetlerin ili Hasankeyf …Dicle’yle bir olup, akıtır yaşı …Bilinmezliklerin dili hasankeyf ‘A’surlar...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/hasankeyf-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-rasim-gozcu-sehpl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm ne hoşdur mümine sanki bir hicret

Saf saf sahabelere yaparlar bir bir ziyaret', 'Ölüm ne hoşdur mümine sanki bir hicret Saf saf sahabelere yaparlar bir bir ziyaret...', ARRAY['Türk Edebiyatı','Şiir','Rasim Gözcü']::text[], 8.5, '{"poet":"Rasim Gözcü","poet_slug":"rasim-gozcu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/olum-178-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Asker', 'bizim-asker-mehmet-baki-erfidan-42ssh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O, uzunca boylu biraz zayıfça,

İnce boyun üzerinde bir kafa,

Saçlar siyah anlımın üstünde durur,

Gözler mavi, bel hafif kamburca..

İsmi “Baki” Zat-i zülcelalin isminden,

Bir de Mehmet eklemişler başına edepten,

Şimdi asker ve çok uzaklarda,

Bütün hayalleri Nizamiye kapısında.

Sabahın ilk işi gözlerini açar “kalk”la

Ardından yemek ve tabiki mıntıka,

Sağ olsun acemiler, var olsunlar,

Onlar da olmazsa mıntıka can sıkar.

İctima gelir mıntıkanın ardından

Sıkı bir sayımla işi sıkı tumak gerek.

Eksiksiz bir ictima sporun habercisidir,

Tüfekli yada tüfeksiz, sıralanır komutlar,

Önce hareketler ardından ısınma,

Bazen es geçilir, bazen tam spor,

Hareketlerin altılı tekrarı epey zor.

Derken bir emir “GİYİN” “hersek elbise başına”,

Ne güzel yapışır elbiseler terli vücuda,

Kahvaltıyı unutmak olmaz,

Ondan da biraz bahs etmeli,

Kahvaltının değişmez ikizleri,

Karnımda mercimek ve tarhana izleri.

Çay, peynir, ya da yumurta,

Süperler yine bir arada,

Ah, bir de ekmek bayat olmazsa,

Acıkmış karınlar iştahla doyar.

Karargah ayrılsın, ayrılsın falan, filan,

Sırada bir iş var, haydin bakalım geriye kalan,

Yazıcılar iş başına, otur oraya,

Kalkmak yok, boş durulmaz iş olmasa da,

Öğlen yemeği, ardından ictima var ikide,

Ne olur ne olmaz sen katıl yine de.

Aksam ictimaları cok sıkıcı,

Bereket yetişiyor müsaade belgesi.

Akşama güzel bir film var ya da maç,

Ama önünde yarına yetişecek bir sürü evrak,

Bir de nöbet varsa o gece,

Doyulmaz işte o gecenin keyfine.

Ya koparılmazsa izin nöbetçi subaydan,

Gece farksız olur, zehir dolu fincandan.

Hafta sonları çok sıkar, çok olur angaryalar,

Angaryaların başında nöbetçi çavuşluk var.

İçtimada eksik yine pek çok,

Falanca nerde niye yok? 

Ha o mu? Görevdeymiş,

Ya beriki adam nerde? 

Onu da gönderdiler angarya işe,

Ötekini sorarsan istirahatli,

Bilmem kim nerde nöbetçi,

Düş falancayı da karagaha,

Ha iki de şoför var ya,

Çarşıları bir de yatı da unutma.

Düşe düşe ictimaya çıkan kalmadı,

Ellide beş-on kişiyle,

Sıyırdın bunu da, hadi iyisin yine.

İşte bizim asker böyle asker,

Şafak bitmiyor, geçmiyor geceler,

Neler verilmez ki doğan güneşe neler....', 'O, uzunca boylu biraz zayıfça, İnce boyun üzerinde bir kafa, Saçlar siyah anlımın üstünde durur, Gözler mavi, bel hafif kamburca.. İsmi “Bak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Baki Erfidan']::text[], 8.5, '{"poet":"Mehmet Baki Erfidan","poet_slug":"mehmet-baki-erfidan","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/bizim-asker-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Üstüne', 'dostluk-ustune-alaeddin-i-kican-m9l0y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'S andığımdan iyi bir arkadaş edinmişim.,

A nlamalısın senle dost olduğuma sevinmişim.,

M eğer vefakarlık,fedakarlık ne kadar kolaymış deseler de,

İ nan can dostum lafla olmuyor bunu bilmişim.,

B urçlarımızın ayni olması bir şey ifade etmez,

O rtak noktalarımızın varolması inan ki yetmez.,

Z ehir olsada meğer hayatın gerçek tadı.,

K alplerin beraberliği yeter,art niyet hiç etkilemez.,

U marım söylediklerimi,anlatmak istediğim gibi yorumlarsın.,

R esimlerindeki gerçek ciddiyeti ömür boyu yaşatırsın.,

T ürkiye’min her karış toprağı vatandır,bana ulaşırsın.

Bu şiir Şair Alaeddin İKİCAN''ın kendine ait SEVGİDEN ÖTESİ YOK'' isimli şiir kitabından alınmıştır.', 'S andığımdan iyi bir arkadaş edinmişim., A nlamalısın senle dost olduğuma sevinmişim., M eğer vefakarlık,fedakarlık ne kadar kolaymış desele...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dostluk-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür İçin', 'ozgur-i-cin-alaeddin-i-kican-079mx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ö zlemle yaşamak istediğimiz bu yıllar,

          Z alim olsa bile geride kalacaktır yarınlar,

          G önüllerde taht kuran samimi içten dostluklar,

          Ü mit ederim gelir bizimle mahşere kadar,

          R iyakar olmazsa dost görünen,candan arkadaşlar.

          S anma ki senin için söylüyorum bunları can kardeşim,

          Ü zülme bilirsin ben genel söylerim,arkadaşımsın sen benim,

          R akip olarak görme kimseyi,herkes kendinin gölgesidir,

          E ğer yenmek isterse başkasını önce kendini yenmelidir,

          R üyalarda solan gerçekleri insanlar kendileri yeşertir.

              Bu şiir Şairin kendisine ait ''SEVGİDEN ÖTESİ YOK''isimli şiir kitabından alınmıştır.', 'Ö zlemle yaşamak istediğimiz bu yıllar,           Z alim olsa bile geride kalacaktır yarınlar,           G önüllerde taht kuran samimi içten...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozgur-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlangıç Noktası', 'baslangic-noktasi-cemil-aygen-i7nbs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani bir nokta koy 

Sonra yeniden başla

Yılma,mücadele et 

Hayat bir yaşam boyudur

Devam ediyor...Unutma

Dünya kuruldu sen bir fert değilsin

Sen varlığınla bir şahsiyetsin

Ve bir insansın

Bu dünya çevrendekiler

Senin için var oldu 

Senin için yaşıyorlar

Sen varsın diye varlar

Sen onları görmüyorsan onlar yok...

Varlığınca yaşadığınca

Sen olduğunca onlar var

Sen yoksan herşey bitiyor

Tanrı emri bu 

Yanlışmı.. Hayır

Tanrım sana şükürler olsun 

Sıkıntım da üzüntüm de bitti

Sen benim için koca bir evreni

Özene bezene yarattın

Ben hayata bir nokta koyup

Hep...Yeniden başlıyacağım 

Vallahide Billahide', 'Hani bir nokta koy  Sonra yeniden başla Yılma,mücadele et  Hayat bir yaşam boyudur Devam ediyor...Unutma Dünya kuruldu sen bir fert değilsin...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/baslangic-noktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgam...', 'kavgam-mustafa-celebi-cetinkaya-qzket', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün yine hüsran nöbetçi yüreğimde 

Bugün yine gözyaşı umutların önünde,

Ve yoksun işte...

Sensiz vakitlere tahammülsüz yüreğim,

Bir özlem türküsü dudaklarımda 

Bir şarkı ki notasız;     seni özledim! . 

Karanlıkta kalıyor şafak...

Pusuda bekliyor çile sensizliği 

Öfkem ki bu vuslata, dinmedi. 

...

satırların adabı bozuluyor Gelincik! 

yoksan birbirini tutmuyor dakikalar...

bilirsin tek düşmanı sensin sensizliğimin 

ve bilirsin kan kusar yokluğuna ümidim...

Bıraksalar koşup geleceğim sana aslında 

Bir müsaadesi olsa efkarımın,

...

bugün başka bir acı sardı bedeni

bir sızı ki dinecek gibi değil

ve ben doğarken binmiş dünya sırtıma

inecek gibi değil! .

İnatla sarılır sana sevdam

Ve hayallerini akran ederim gönlüme sen yoksan! 

...

bir hal olur gene sarılırım sana ben bir tenha da

varsın hayal olsun beni saran kolların,

bir düş doğar; öperim dudaklarını 

yine hüsran tutsa da nöbetini yüreğimin,

bir buseyi katre katre alır gönül: 	kanarım...

sen ki; sevgili! 

kavgamsın.................

8 Mayıs 2005 Pazar

Dışkapı', 'Bugün yine hüsran nöbetçi yüreğimde  Bugün yine gözyaşı umutların önünde, Ve yoksun işte... Sensiz vakitlere tahammülsüz yüreğim, Bir özlem ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kavgam-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmışım Yıllardır Yanmışım Boşa', 'yanmisim-yillardir-yanmisim-bosa-murat-demir-qwuvb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derdime hiç kimse derman olmuyor

Beklerim sonumu çilem dolmuyor

Yar desem vefasız gelip sormuyor

Yanmışım yıllardır yanmışım boşa

Gözümün önünden gitmeyen hali

Tarihe karışmış sanki emsali

Hasret hazanıyla yaprak misali

Solmuşum yıllardır solmuşum boşa

Elalem yaşarken aşk ilacıyla

Benim mevsimlerim geçti sancıyla

Yüreğim yandıkça, sonsuz acıyla

Dolmuşum yıllardır dolmuşum boşa

Bitirdi ömrümü dert yiye yiye

Neye yarar akıl versen deliye

Birgün döner diye belki geriye

Sanmışım yıllardır sanmışım boşa!', 'Derdime hiç kimse derman olmuyor Beklerim sonumu çilem dolmuyor Yar desem vefasız gelip sormuyor Yanmışım yıllardır yanmışım boşa Gözümün ön...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanmisim-yillardir-yanmisim-bosa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir çocuk Buldum Göz Yaşlarımda', 'bir-cocuk-buldum-goz-yaslarimda-ahmet-atmaca-lbco6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir çocuk buldum göz yaşlarımda

ipek dokunuşlu ellere hasret, 

bir çocuk buldum yüreğinde sızı var.

zaman,varlığından habersiz mi geçiyor ne

hüzün bütün perdeleri indirmiş güpe gündüz

bir çocuk uyuttum güneşin  geceliğinde 

kanatlanmış gök kubbe 

toprak tahtından memnun 

gelen giden bahane

yeşile soğuk vurmuş

inceden çiğ iniyor

bir çocuk  büyüttüm

dikenin sinesi de. 

işte o  çocuk öldü..

kimin acı kaybı bu?', 'bir çocuk buldum göz yaşlarımda ipek dokunuşlu ellere hasret,  bir çocuk buldum yüreğinde sızı var. zaman,varlığından habersiz mi geçiyor ne...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-cocuk-buldum-goz-yaslarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Aşkın Ekmeği', 'umut-askin-ekmegi-tunahan-ermihan-6gr3m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretlerde tükenir bu kara geceler misali

Özlediğin tenimde dans eder hayallerin bir bakmışsın

Bir bakmışsın sabah gözlerimizden doğmuş güneş

Umudunu yitirme sevdiğim umuttur bu sevdayı büyüten', 'Hasretlerde tükenir bu kara geceler misali Özlediğin tenimde dans eder hayallerin bir bakmışsın Bir bakmışsın sabah gözlerimizden doğmuş gün...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/umut-askin-ekmegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asyali Armut', 'asyali-armut-ayda-yildiz-y7pyp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Basladi hazirlanmaya bir hincla

Soyledi oglana, bugun gelecek babasiyla

Yemesini istedi ekmegini yumurtasiyla

Omuz silkti oglan, acitti icini aglamasiyla

Anasi gecirirken sirtina yagmurlugu

Verdi eline, susarsin al bu sulugu

Kalem cizgisi cekik gozlu, umutlu

Bir saatligine iste olacak, Pazar  mutlu 

Kim nereden bilecek,

Anasi bugun neden ise gidecek

Bes saati yapip, o bir saati alacak

Ilk once Asyali  armut''a bakacak

Onun geldigi yerlerde tek satilmazdi 

Bir tanecik alacak, ogluydu tadina bakacak

Ancak bu  birtanecik Asyali armut getirecek 

Onun istedigi, kokuyu burnuna tutturecek

Uzaklar dan gocun bahsetmeyi unuttugu

Yemekten cikan mis gibi kokan bugu

Insan kokusuydu bahsetmeyi unuttugu

Evin, her kapi acilista yuzune calan solugu 

Bu asyali armut, butun bu kokulari

Bahcedeki, evdeki, kilerdeki 

Akla gelen arkadaslarin isimleri

Getirecekti tatli suyuyla, yaslari gozlerdeki', 'Basladi hazirlanmaya bir hincla Soyledi oglana, bugun gelecek babasiyla Yemesini istedi ekmegini yumurtasiyla Omuz silkti oglan, acitti icin...', ARRAY['Türk Edebiyatı','Şiir','Ayda Yıldız']::text[], 8.5, '{"poet":"Ayda Yıldız","poet_slug":"ayda-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asyali-armut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam Yine...', 'bu-aksam-yine-muharrem-cetinkaya-e27vp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Efkârlıyım yine bu akşam,

Sensizliğe,

Yokluğuna doluyor kadehlerim.

Yüzüstü bırakıp gittin gideli; 

Yokluğunun müebbet mahkumu gönlümü

Yağlı ilmeklerin,

İtilmek için bekletilen sehpalarına 

Çıkarıyorum………………………

Ve yine bu akşam; 

Tüm gemileri yakıp,

Sensizliğin limanında demir attım,

Bir sandalla…! 

Yine bu akşam; 

Acı-kekremsi tadına mahkumum,

Yokluğunda seni sevmenin.

Ve bir sevda masalı anlatacağım yine,

Sahildeki dalgalara………………….

………………………………………

Anılarımı yüzdüreceğim,

Bu limanda

Kâğıttan gemilere bindirip! 

Yokluğunun elinden tutup,

Bana ezberlettiğin masalları anlatacağım,

Sahilde.

İhtimal,

Yine

Gülüp geçeceksin……………………….

Yine

Bu akşam; 

Tek celsede

Kalemini kırıyorum…………………….

Yokluğunun müebbet mahkumu gönlümü

Yağlı ilmeklerin,

İtilmek için bekletilen sehpalarına 

Çıkarıyorum.

Ve 

Bu akşam; 

Yine,

Tereddütsüz vuracaksın tekmeyi

O sehpaya

Bi  li yo rum……………………..!', 'Efkârlıyım yine bu akşam, Sensizliğe, Yokluğuna doluyor kadehlerim. Yüzüstü bırakıp gittin gideli;  Yokluğunun müebbet mahkumu gönlümü Yağlı...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bu-aksam-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmısın?', 'varmisin-sahin-erturk-ijlcs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Leyla ile Mecnun gibi

Ferhat ile Şirin gibi

Tahir ile Zühre gibi

Efsane aşklar yaşadım

Şahin ile Zeycan aşkı

Tülay ile Şahin aşkı

Bir efsane,efsaneydi

Kütahyanın dilindeydi

Sevencan ile Şahin aşkı

Yurdagül ile,Şahin aşkı

İstanbulda,İzmirdeydi

Türkiyenin dilindeydi

Hiç birinde suçum yoktu

Aysun,Nilgün toprak oldu

Meral,Sibel zengin buldu

Aşk yolunda yalnız kaldım

Şimdi sen çıktın karşıma

Benimle destan yazmaya

Sevgilim,aşkım olmaya

Varmısın güzel,VARMISIN? 

Aşka çıkar katanlara

ALMAN lara,YUNAN lara

HANS lara aşk öğretmeye

Varmısın güzel,VARMISIN? 

Uzaklara,KUTUPLARA

Eskimolar,YAMYAMLARA

Riyasız aşk öğretmeye

Varmısın güzel,VARMISIN? 

Gönüllerde taht kurmaya

Benimle destan yazmaya

Dünyaya aşk öğretmeye

Varmısın güzel,VARMISIN? 

(Şiirdeki isimler SANALDIR) 

(Gerçek isimler KALPTE SAKLIDIR)

(01.06.2005-Yeni)', 'Leyla ile Mecnun gibi Ferhat ile Şirin gibi Tahir ile Zühre gibi Efsane aşklar yaşadım Şahin ile Zeycan aşkı Tülay ile Şahin aşkı Bir efsane...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/varmisin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan cı', 'yalan-ci-muharrem-cetinkaya-9gzh1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.....................................

Hani ağlamıştın bi-keresinde,

''Ben sensiz yaşayamam''diye

Dizlerimde...

Hani sımsıkı sarılarak; 

''Biz ayrılamayız''demiştin,

Kollarımda...

Hani sen benimdin,

Ben de..................? 

Hani..................................................? 

Yoksa; 

Ben mi bir hayâl gördüm,

Bunlar bir yalandı.

Yoksa sen mi

Yalan söyledin

Bunlar gerçek...!', '..................................... Hani ağlamıştın bi-keresinde, ''Ben sensiz yaşayamam''diye Dizlerimde... Hani sımsıkı sarılarak;  ''Biz a...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalan-ci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldım Tek Başıma', 'kaldim-tek-basima-kenan-sahbudak-28yo3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gezdim alemleri arşın içinde

Gönül kıblesinde feza kalmadı

Çektim acıları farşın içinde

Feleğin verdiği eza kalmadı

Dört kapı kırk makam gezdim anlarım

Cana tuzak kurdu kahpe yanlarım

Almadım kendimden verdim canlarım

Gönül sermayemden size kalmadı

Şahbudak çok çektim puşta kıyağı

Yine de onlardan yedim dayağı

Madrabazlar benden çekti ayağı

Kaldım tek başıma ceza kalmadı', 'Gezdim alemleri arşın içinde Gönül kıblesinde feza kalmadı Çektim acıları farşın içinde Feleğin verdiği eza kalmadı Dört kapı kırk makam gez...', ARRAY['Türk Edebiyatı','Şiir','Kenan Şahbudak']::text[], 8.5, '{"poet":"Kenan Şahbudak","poet_slug":"kenan-sahbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaldim-tek-basima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Dileği', 'dost-dilegi-alaeddin-i-kican-s7ni4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'H ani hatırlarmısın geldiğin günleri? 

     Ü mit ettiğini yaşıyormusun? Özlemlerini,

     S anma ki herşey gönlünce olur insanların,

     E ngeller olmasa şevk saçan şu gözlerin,

     Y aşatır dünyanın tüm güzelliklerini,

      İ nsanlar menfaat gözetmeden vermiyor inan,

     N eden senin gibi vefakar,fedakar olamıyor insan.? 

     Ö zlem duyarak aradığım memuriyet niteliklerini,

     Z orlanmadan sende gördüm güzelliklerini,

     K atılırım doğru söylediğin fikirlerine,

     A ncak bakarım Kamunun menfaatlerine,

     N erede olursan ol başarılı olmanı isterim içtenliğimle.

       Bu şiir Şaire ait ''SEVGİDEN ÖTESİ YOK''isimli şiir kitabından alınmıştır.', 'H ani hatırlarmısın geldiğin günleri?       Ü mit ettiğini yaşıyormusun? Özlemlerini,      S anma ki herşey gönlünce olur insanların,      E...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dost-dilegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Güzel', 'mechul-guzel-abbas-yurt-1e2hq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu meçhul dünyada var olduğunu,

Bana hatırlattı o meçhul güzel.

Nice insanların kör olduğunu,

Sormadan anlattı o meçhul güzel.

Kader yazısında yokmuş hiç vacdan,

Her şeye rağmen sen insansın insan! 

Avcılar elinde bir ahu ceylan,

Süzülüp gidiyor o meçhul güzel.

Bataklık içinde güle benziyor,

Çölün ortasında sele benziyor,

Konuşamıyan dile benziyor,

Bakışı harika o meçhul güzel.

Zar atmış hayata; Gelmiş şeş-ü beş,

Ruhunda aselet var tam bir düseş.

Mutsuzluk içinde doğan bir güneş,

Mutluluğa özlem o meçhul güzel.

Birden tökezlemiş koşarken son hız,

Hayat çok kahpeymiş, ne yapsın bu kız! 

Karanlık gecede parlak bir yıldız,

Uçuyor boşlukta o meçhul güzel.

Öyle bir güzel ki tam cıvıl cıvıl,

Hüzünlü gözleri hep ışıl ışıl,

Bedbaht dünya onu etmiş bir haşıl,

Kavrulup gidiyor o meçhul güzel.

                            20.03.2005', 'Şu meçhul dünyada var olduğunu, Bana hatırlattı o meçhul güzel. Nice insanların kör olduğunu, Sormadan anlattı o meçhul güzel. Kader yazısın...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mechul-guzel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden, Benden Baska', 'senden-benden-baska-ayda-yildiz-jkz35', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ne bicimdesin, ne alemdesin

Yoksa yine dertlerin depresti

Ortasindamisin ki kiyametlerin

Fikirler mi asagi dustu 

Gorusler mi,  pekisti

Belki  bundan oturu,  us sustu

Sen beni sormaz oldun

Yolun degistirdin, irak oldun

Vardi elbette aklinda 

Hakli bir suru goturu

Gormeyeli seni ben

Gamin tadi kacti, baska oldu

Kimsede bahsetmez, dertlenmez

Senden benden oturu, 

Konusmuyorlar, gorusmuyorlar demez

Varmiydi aramizda alakasizligin bu turu

Uzaktan gorunur bizim durumumuz kotu

Pek bir dertli, pek bir aci

Nehire gidiyorum, arinmaya

Gel yika beni bundan oturu

Yok canim efendim yok

Bu ise, icin icin uzulen yok

Senden benden baska 

Beni kizipta icinden seven yok

Benden baska seni

Icinden, siralayip  ta sayan yok', 'Sen ne bicimdesin, ne alemdesin Yoksa yine dertlerin depresti Ortasindamisin ki kiyametlerin Fikirler mi asagi dustu  Gorusler mi,  pekisti ...', ARRAY['Türk Edebiyatı','Şiir','Ayda Yıldız']::text[], 8.5, '{"poet":"Ayda Yıldız","poet_slug":"ayda-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/senden-benden-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyün Kızları', 'koyun-kizlari-alaeddin-i-kican-kl4qq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derdimin çaresini sende bulmuşum.,

Aşkımın kuşunu sende vurmuşum.,

Ben bir köy kızına vurulmuşum.,

Köy kızlarını candan sevmişim.

Tarlaya gidip öküz koşardı.,

Aşkı ve sevgiyi orada arardı,

Boya makyaj nedir tanımazdı.,

Köy kızlarını candan sevmişim.

 Bir baktım köy kızı,

 İki baktım köy kızı.,

 Ardından kalbimde,

 Ufak bir sızı,

       Bu şiir Şairin kendisine ait ''SEVGİDEN ÖTESİ YOK'' isimli şiir kitabından alınmıştır.', 'Derdimin çaresini sende bulmuşum., Aşkımın kuşunu sende vurmuşum., Ben bir köy kızına vurulmuşum., Köy kızlarını candan sevmişim. Tarlaya gi...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/koyun-kizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulak Ver', 'kulak-ver-i-brahim-balci-mscbg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Farkında değil misin

Işıltısı gözlerinin

Vurmakta açığa açlığını

Gel git’in dalgaları

Boğazdaki yakamoz

İnilti ve fısıltılarıyla

Pırıltısında gözlerinin

Arzu,özlem ve tutku

Yanıp sönerken böyle

Daha ne kadar yalan söyleyebilirsin ki

Kendine 

Haydi bırak artık kendini

Benliğine

Ne Assisili’nin ayak izindesin

Ne de Nirvana var hedefinde

Kimbilir kimi kınıyorsun

Perhizinle

Kimbilir kimi onurlandırıyorsun

Yetmedi mi şimdiye dek

Kendinden başka herkesin

Taleplerince yaşamak

Biraz da kendi iç sesine kulak ver

Artık

Kulak ver çağrısına 

Teninin

Arzu,istek ve ihtiras

Tantalos’un dişleriyle kol gezerken bedeninde

Vaftiz olmak,yunmak

Sularıyla Kharon’un

Ancak

Kendine eziyet etmekle mükafatlandırılmış

Bir ucube eyler seni', 'Farkında değil misin Işıltısı gözlerinin Vurmakta açığa açlığını Gel git’in dalgaları Boğazdaki yakamoz İnilti ve fısıltılarıyla Pırıltısınd...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kulak-ver-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişle Yüzleşme', 'gecmisle-yuzlesme-alaeddin-i-kican-nm6g8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklıma gelince gücüme gider,

Sarar vücudumu buz gibi terler,

Ceketim yamalı,pantalonum yırtık,

Dilim varmasa da bunları söylerim artık.

İskarpin ayakkabısı,okul çantası olanlar,

Kendini bilmem neyin malı sananlar,

Benim içimin kanadığını ne bilsin,

Onlar değil, o imkanı sunanlar düşünsün.

Kardeşlik,arkadaşlık değerini saydık,

Dostu,kardeşi böyle yaşadıkça tanıdık,

Öğretmen,arkadaş,komşu,dost hep bizim,

Ayrıcalık oldumu kabullenmez yüreğim,çaresizim.

Alın terimle zamanı yarıştırdım,

Tarlada orak biçerken hayatı yaşadım,

Okul çıkışı simit sattım kazandım,

Hem okulda,hem sokakta ben çalıştım.

Yaşamak istiyorsan kemdinle ol barışık,

Kimseyi hor görmezsin herkesle tanışık,

Unutursan çektiğin acıları derdi,

Sonunda sen kazanırsın olursun efendi.', 'Aklıma gelince gücüme gider, Sarar vücudumu buz gibi terler, Ceketim yamalı,pantalonum yırtık, Dilim varmasa da bunları söylerim artık. İska...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecmisle-yuzlesme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarsın', 'aglarsin-i-brahim-balci-yxez7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kara kurum gözlerine

Dalıp dalıp da

Yelken basamadım gizemli denizlere

Öpemedim daha

Daha ısıramadım

Gül kurusu dudakların ile

Gamzesiyle yanaklarını

Saramadım ince belinle

Avuçlayıp sıkamadım

Koklayamadım

Goncalarını

Dikemedim

Gizli vadilerine

Keşif bayrağımı

Kınıyor musun beni

İtiraf ettiğimde

Ağlamak istediğimi

Yazılarından fışkıran

Şiirlerinden

Şairane ruhun gerçekse eğer

Anlarsın beni

Anlar ve

İzin verdiği kadar hançerenin

Bağıra bağıra

Ağlarsın 

Sen de benim kadar', 'Kara kurum gözlerine Dalıp dalıp da Yelken basamadım gizemli denizlere Öpemedim daha Daha ısıramadım Gül kurusu dudakların ile Gamzesiyle ya...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aglarsin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onu,Unutamıyorum.', 'onu-unutamiyorum-ali-osman-yilmaz-sm175', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben Mİ yi,

Sarı saçlı,mavi gözlü,

Suyun öte  yakasından,

Boşnak damarlı,

O kadını çok sevdim.

Bana bakan gözlerini,

Kulağıma fısıldayan,

Tatlı dilini,

Göğsüme başını dayayıp,

Derin derin iç çekerek,

Beni koklayışını,

Koynumda cilveyle oynaşmasını,

İşte o sarı saçlı,

Mavi gözlü kadını,

Çok sevdim inanın.

Onu sevdiğime,

Bir onu,

Birde tanrıyı,

İnandıramadım.

Sabahları,

Yatağıma gelip,

Mutlu gecelerden sonra,

Ellerimle yüzünü sarıp,

Dudaklarımdan ateş gibi,

Öperek haydi sevgilim,

Sofran hazır demesini,

Unutamadım.

Her sabah,

Mavi gözlerinden,

Işıklar saçarak delicesine,

Koynuma atılmasını,

Seni  seviyorum  demesini,

Tenimde eriyip,

Ben  olmasını,

Asla  unutamıyorum.', 'Ben Mİ yi, Sarı saçlı,mavi gözlü, Suyun öte  yakasından, Boşnak damarlı, O kadını çok sevdim. Bana bakan gözlerini, Kulağıma fısıldayan, Tat...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/onu-unutamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Yeli...', 'bahar-yeli-avni-aydin-no9gp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yaziyorum...

kalemim elimde, binlecesine inat

bir tanesini yazıyorum...

boşa söylenmiş sözler değil benimkisi

binlercesinin arasına sıkışıp kalmış

yalnız bir haykırış; acıyla karışık...

koşup da yorulmadığımız düz yollarda

bir ağacın gölgesinde yazdığım...

inadına sevip, inadına özlediğim

bahar yeli benimkisi...', 'yaziyorum... kalemim elimde, binlecesine inat bir tanesini yazıyorum... boşa söylenmiş sözler değil benimkisi binlercesinin arasına sıkışıp ...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bahar-yeli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muştu', 'mustu-kamil-caglar-aksu-lofqs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hayalin kırılma noktası; 

umut yolculuklarının sefer tasında,

aynı zehir taşınır ''şüphe''

kokusunda yangın işaretleri

sarsılır kalbinde kızıl çamlar

içleri içlerine sığmaz olur

vurulmak ister çanlar..

kuşkudur,

doğan ümitleri sakat bırakan muştu,

korkudur..', 'hayalin kırılma noktası;  umut yolculuklarının sefer tasında, aynı zehir taşınır ''şüphe'' kokusunda yangın işaretleri sarsılır kalbinde kızıl...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çağlar Aksu']::text[], 8.5, '{"poet":"Kamil Çağlar Aksu","poet_slug":"kamil-caglar-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mustu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşmi Siyahım', 'cesmi-siyahim-abbas-yurt-nhmse', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir benle derdin çeşmi siyahım? 

Yüzüme bir kere gülsene nolur.

Vicdanına danış tutmasın ahım,

Sözüme bir kere gelsene nolur.

Suçlu mu buldun da çarmıha gerdin? 

Hani, baş tacımsın hep bana derdin! 

Yoluma canını feda ederdin! 

Özüme bir kere dönsene nolur.

Biçare Abbas''ı boşuna yorma,

Zaten yaralıyım bir de sen vurma! 

Bu sözüm sanadır gel beni kırma,

Sazımı bir kere çalsana nolur.

                 12.10.2002', 'Nedir benle derdin çeşmi siyahım?  Yüzüme bir kere gülsene nolur. Vicdanına danış tutmasın ahım, Sözüme bir kere gelsene nolur. Suçlu mu bul...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cesmi-siyahim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sevda masalı.', 'bir-sevda-masali-i-shak-ozlu-9wm7k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir canı parçaladın iki can yaptın,

Yıllar öncesinden sevdiğimi aldın.

Ben sana ne yaptım ey güzel İstanbul,

Gönül yazğımı senmi ayrılık yazdın? .

Şehirlerin şahı güzellikte birsin,

Sevdiğimle arama niçin girersin? .

Sevda ahı almak yakışmaz şanına,

Dilerim cananımı geri verirsin.

Baharlarımı kış yaşadım yıllarca,

Yıllar saydım güngün hasretlik dağlarca.

Bir ahım kaldı vebal sende İstanbul,

Şikayetim gayri mahşere varınca.

Senin güzelliğini görmeye gelmişti,

Kalıcı değil misafirim demişti.

Mutluluğa hazır beklerken İstanbul,

Sayende bir sevda masalı bitmişti.', 'Bir canı parçaladın iki can yaptın, Yıllar öncesinden sevdiğimi aldın. Ben sana ne yaptım ey güzel İstanbul, Gönül yazğımı senmi ayrılık yaz...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sevda-masali-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feleğim Şaştı Neyleyim', 'felegim-sasti-neyleyim-abbas-yurt-orb1w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolumu şaşırdım oldum biçare,

Bir kere feleğim şaştı neyleyim.

Onulmaz derdim var gayri ne çare,

Kaderde bize bu düştü neyleyim.

Boşunamı benim bunca emeğim,

Tanrıdan mutluluk bir tek dileğim,

Paramparça oldu yanan yüreğim,

Ateşten kavruldu pişti neyleyim.

Dedim; nedir derdin benimle ulan? 

Sanki o anda oldu koca bir yılan,

Dağlardan koparak üstüme gelen,

Kükremiş sel gibi coştu neyleyim.

Yetmez mi verdiğin eza ya Habip? 

Kurtulamıyorum boğazımda ip,

Derdimi merhemle saracak tabip,

Neşterle yaremi deşti neyleyim.

Abbas’ım halimi bilenler anlar,

Sana kalsın köşkler, saraylar, hanlar,

Kaynar kazanlarda yanınca canlar,

Taşıp ta bendini aştı neyleyim.

                                    15.08.2002', 'Yolumu şaşırdım oldum biçare, Bir kere feleğim şaştı neyleyim. Onulmaz derdim var gayri ne çare, Kaderde bize bu düştü neyleyim. Boşunamı be...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/felegim-sasti-neyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Diyeyim Ey Dünya Sana', 'ne-diyeyim-ey-dunya-sana-abbas-yurt-hse2l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seyyah gibi gezdim gurbet illeri,

Soldurdum bahçemde gonca gülleri,

Anlarmısın başımdaki halleri,

Söyle ne diyeyim ey dünya sana.

Gurbet illerinde bende gezerim,

Yaşamaktan bıkıp candan bezerim,

Bazen azraile mektup yazarım,

Böyle nediyeyim ey dünya sana.

Gürbette olmaz garibin mekanı,

Andırıyorum boş kalmış cemakani,

Anlatıyorum bunca keşmekanı,

Hayli ne diyeyim ey dünya sana.

Abbasın gurbet iller bize haram,

Hicrandan azmış sarılmıyor yaram,

Artık bu iller bize oldu viran,

Neyle ne diyeyim ey dünya sana.

                                            31.12.1982', 'Seyyah gibi gezdim gurbet illeri, Soldurdum bahçemde gonca gülleri, Anlarmısın başımdaki halleri, Söyle ne diyeyim ey dünya sana. Gurbet ill...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-diyeyim-ey-dunya-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Zaman mı İster', 'daha-zaman-mi-i-ster-abbas-yurt-gbpem', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle bir dünyadayım ki şaşırıp kalmışım,

Anlamam için bilmem daha zamanmı ister.

Hayalmi nedir? Öyle bir rüyaya dalmışım,

Uyanmam için bilmem daha zamanmı ister.

Kimi zengindir, kimi taş altında ezilir.

Kimi turist gezer, kimi kurşuna dizilir.

Kimisinin diri diri mezarı kazılır.

Ölmemem için bilmem daha zamanmı ister.

Kimine değmez nazar, kimi canından bezer,

Kimi madalya takar, kimi işitir azar,

Kimi dünyaya küser, kimi kaderin çizer,

Yaşamam için bilmem daha zamanmı ister.

Abbas der neden dünyanın kahrını çekersin,

Bazen fırtına, bazen şimşek olup çakarsın,

Hiç düşünmeden nice mazlumları yakarsın,

Düşünmem için bilmem daha zamanmı ister.

                                                                  25.01.1991', 'Öyle bir dünyadayım ki şaşırıp kalmışım, Anlamam için bilmem daha zamanmı ister. Hayalmi nedir? Öyle bir rüyaya dalmışım, Uyanmam için bilme...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/daha-zaman-mi-ister-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Kokuyorsun', 'toprak-kokuyorsun-zumrut-demirtas-hahhl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Taşı toprağı altın şehre,

Uzun yıllar önce göçmüşsün,

Kah krallar gibi yaşamış,

Kah yavan ekmeği bölmüşsün,

Bazen çok sevip de sevilmiş,

Bazen kabuğuna dönmüşsün….

Sılada bırakıp anayı,

Ekmeğin peşine düşmüşsün,

Bitince yuvanın huzuru,

Sen de; evliliğe küsmüşsün,

Yalnızlığı arkadaş sayıp,

Başını kumlara gömmüşsün….

Saçına düşen aklar gibi,

Temiz bir sayfa istiyorsun,

Huzurlu bir sona yönelen,

Sadık bir sırdaş arıyorsun,

Dilerim bulursun gönlünce,

En iyiyi hak ediyorsun….

Sıladan sana selam olsun,

Acıların artık son bulsun,

Gözlerin mutlulukla dolsun,

Yüreğin sevgiyle yorulsun,

Hayalin gerçekle buluşsun,

Bizim diyarların oğlusun,

Gizleme, TOPRAK KOKUYORSUN! .....

Bir Büyüğüme…..

(01.06.2005)', 'Taşı toprağı altın şehre, Uzun yıllar önce göçmüşsün, Kah krallar gibi yaşamış, Kah yavan ekmeği bölmüşsün, Bazen çok sevip de sevilmiş, Baz...', ARRAY['Türk Edebiyatı','Şiir','Zümrüt Demirtaş']::text[], 8.5, '{"poet":"Zümrüt Demirtaş","poet_slug":"zumrut-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/toprak-kokuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğu İlleri', 'dogu-i-lleri-abbas-yurt-v9i6q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sivas''ın önünde bir güzel kuzu,

Şarkışla''da çalındı Veysel''in sazı,

İmranlı''da kaldı bir kara mazi,

Nideyim ben artık, neyleyim artık

Erzincan yolları bağdır geçilmez,

Çayırlı suları soğuk içilmez,

Kemah''ın güzelliğinde hiç de geçilmez,

Nideyim ben artık, neyleyim artık.

Erzurum''a vardım dumanlı dağlar,

Aşkale''de güzel Karasu çağlar,

Horasan''da oturmuş bir güzel ağlar,

Nideyim ben artık, neyleyim artık.

Kars Kalesinde görünen bir güzel haldir,

Emsalsiz bir doğa gölüdür Çıldır,

Ey insanoğlu kalbindeki karayı kaldır,

Nideyim ben artık, neyleyim artık.

Karaköse''nin güzeldir peyniri yağı,

Meşhurdur dünyada yüce Ağrı dağı,

Iğdır ovasıdır bir pamuk yatağı,

Nideyim ben artık, neyleyim artık.

Van''a canlılık verir güzel van gölü,

Sabah seherde öter Başkale bülbülü,

Baharda açar Erciş''in gülü,

Nideyim ben artık, neyleyim artık.

Hakkari''nin hayat kaynağıdır Zap,

Güzelim bir ilçesidir Beytüşebap,

Sende şeytanı unut, tanrıya tap,

Nideyim ben artık, neyleyim artık.

Nihayet çıktı Siirt ilinin yolu,

Türkiye''nin geçim kaynağıdır Batman petrolu,

Toprak ağalarının çok olur davarı malı,

Nideyim ben artık, neyleyim artık.

Diyarbakır''ın kan gibidir karpuzu,

Allar yeşiller giyinir gelini kızı,

Baharda yayılır çimene kuzu,

Nideyim ben artık, neyleyim artık.

Bitlis ilinin dağlıktır alanı,

Tuğ Tatvan''ın bir limanı,

Islık çalıyor  bak engerek yılanı,

Nideyim ben artık, neyleyim artık.

Muş''ta geçer Murat nehri,

Deprem değil midir Varto''nun kahrı? 

Kötülüktür insanların sihri,

Nideyim ben artık, neyleyim artık.

Bingöl''e yakındır Karakoçan,

Kiği ilçesinde çok olur sıçan,

İnsan değilmidir dağa kaçan,

Nideyim ben artık, neyleyim artık.

Tunceli''nin merkezidir Kalan,

Pertek''te çok olur yılan,

İnsan olana yakışır mı hiç yalan,

Nideyim ben artık, neyleyim artık.

Elazığ''da çıktı Keban baraj gölü,

Harput''ta görülmez güzelim yalı,

Geride kaldı güzel Hazar Gölü,

Nideyim ben artık, neyleyim artık.

Malatya''ya vardım dağlar görülmez,

Her yanı kayısı evler görülmez,

Hekimhan''ın da gülleri derilmez,

Nideyim ben artık, neyleyim artık.

Abbas  der gezer söylerim ben bunları,

Canlandırırım hayalimde güzel anıları,

Arasam da bulamam geçen güzel günleri,

Nideyim ben artık, neyleyim artık.

30.12.1974', 'Sivas''ın önünde bir güzel kuzu, Şarkışla''da çalındı Veysel''in sazı, İmranlı''da kaldı bir kara mazi, Nideyim ben artık, neyleyim artık Erzinc...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/dogu-illeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sılam', 'silam-abbas-yurt-6zi7q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatırladım artık ben silamı,

Aldım elime dolma kalemi,

Yazdım satıra binbir kelamı,

Gönderdim köye sonsuz selamı.

Birden dalıverdim ben o anda,

Köyündeyim şimdi ben şu anda,

Hiç değişmemiş geçen zamanda,

Kendime geliverdim bir anda.

Yine çok uzağım silamda ben,

O tatlı  hayallere dalınca hemen,

Nasıl geçiyor analayamıyorum zaman,

Yine dertli dertli çalıyor bir keman.

Bende hayalimde silamda gezerim,

Abbas der şu zalim gurbette bezerim,

Elimde gelse nankörlerin kafasın ezerim,

Gurbette derin uykulara dalıp sızarım.

                                                                30.06.1977', 'Hatırladım artık ben silamı, Aldım elime dolma kalemi, Yazdım satıra binbir kelamı, Gönderdim köye sonsuz selamı. Birden dalıverdim ben o an...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/silam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkbahar', 'i-lkbahar-abbas-yurt-snswn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doyum olmaz tadına,

Senin güzel ilkbahar.

Hayran oldum adına,

Senin güzel ilkbahar.

Çocuklar bayırlarda,

Kuzular çayırlarda,

Çiçeklerin kırlarda,

Adın güzel ilkbahar.

Karları eritirsin, 

Sıcakları getirirsin,

Gülleri bitirirsin,

Ne güzelsin ilkbahar.

Yemyeşil bir halısın,

Özlemlerin gülüsün,

Kuşların bir dalısın,

Vefakarsın ilkbahar.

Bülbülü yetirirsin,

Huzuru getirirsin,

Her şeyi bitirirsin,

Sen dahisin ilkbahar.

Doğaya hayat verdin,

Umutsuzluğu yerdin,

Taptaze gülü derdin,

Bir romansın ilkbahar.

                    05.11.1980', 'Doyum olmaz tadına, Senin güzel ilkbahar. Hayran oldum adına, Senin güzel ilkbahar. Çocuklar bayırlarda, Kuzular çayırlarda, Çiçeklerin kırl...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ilkbahar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye''m', 'turkiye-m-abbas-yurt-e9l8u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim ülkem bir cennettir,

Emsali bulunmaz tektir,

Hepimize emanettir,

Bir  masalsın sen Türkiyem.

Rumeli ve Anadolu,

Kars, Edirne, Mersin, Bolu,

Her tarafı ahenk dolu,

Şerefli şanlı Türkiyem.

Dört mevsimi yaşattıran,

Ümitleri yeşerttiren,

Dünyayı hep şaşırttıran,

Çok özelsin sen Türkiyem.

Ulu yüce dağlarınla,

Sebze, meyve bağlarınla,

Zeytin, peynir, yağlarınla,

Bir nimetsin sen Türkiyem.

Berrak akar hep suları,

Yemyeşildir ovaları,

Bir milletin duaları,

Sanadır canım Türkiyem.

                       25.03.2001', 'Benim ülkem bir cennettir, Emsali bulunmaz tektir, Hepimize emanettir, Bir  masalsın sen Türkiyem. Rumeli ve Anadolu, Kars, Edirne, Mersin, ...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/turkiye-m-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alimlerin Yorumu Nedir?', 'alimlerin-yorumu-nedir-abbas-yurt-j3k72', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fakirin halini soran olmuyor,

Zenginin fakirle sorunu nedir? 

Halimizi hayra yoran olmuyor,

Bilmem ki ülkenin durumu nedir? 

Bir yandan enflasyon ile işsizlik,

Bir yandan cüzdan bomboş, cep te delik,

Vatandaş giymeye bulamaz terlik,

Alimlerin buna yorumu nedir? 

Kaynak yok diyerek hep dert yandılar,

Hortumlanan bankayı kurtardılar,

Sanmasınlar bizi hep kandırdılar,

Bütün bunlar devlet sırrı mı nedir? 

Çiftçiyi, köylüyü hepten unuttular,

Yerli malını ithale sattılar,

Bazıları da yükünü tuttular,

Koskoca ülkenin tarımı nedir? 

Çözümlenemeyenleri çözerek,

Hep olayların üstüne giderek,

Enflasyonla mücadele ederek,

Bundan kurtulmanın terimi nedir.

                                                        17.03.2001

(Zirve Gazetesinde Yayımlanmıştır.)', 'Fakirin halini soran olmuyor, Zenginin fakirle sorunu nedir?  Halimizi hayra yoran olmuyor, Bilmem ki ülkenin durumu nedir?  Bir yandan enfl...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/alimlerin-yorumu-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zam Geliyor', 'zam-geliyor-abbas-yurt-o5gjr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bulunmuyor buğday unu,

Bu gidiş milletin sonu,

Allah kabul etmez bunu,

Buğdaylara zam geliyor.

Sigara, çay karaborsa,

Hiç olmazsa zamlar dursa,

Çok yaşarız allah korsa,

Çünkü yine zam geliyor.

Yeni rakı, votka, şarap,

Ayyaşların işi harap,

Kendi şarabını kendin yap,

İçkilere zam geliyor.

Karaborsa sığır eti,

Çoğaldı etin kıymeti,

Çok satılır eşşek eti,

Hayvanlara zam geliyor.

Bulunmuyor azot gübresi,

Ne yapsın çiftçi  fukarası,

Kırıldı fabrikanın ibresi,

Gübrelere zam geliyor.

Stokçular stok yapar,

Sudan bile para kapar,

Demiri depolara atar,

Demirlere zam geliyor.

Bulunmuyor sana yağı,

Kaydı milletin ayağı,

Duysun milletin kulağı,

Her taraftan zam geliyor.

Ağalar zamdan sakınmaz,

Zam onlara hiç dokunmaz,

Ey kucağımdaki kırık saz,

Sana bile zam geliyor.

                                    20.03.1976', 'Bulunmuyor buğday unu, Bu gidiş milletin sonu, Allah kabul etmez bunu, Buğdaylara zam geliyor. Sigara, çay karaborsa, Hiç olmazsa zamlar dur...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/zam-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beter Ol', 'beter-ol-abbas-yurt-lnay9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklımı başımdan alan güzelim,

Ceryanı olmayan telden beter ol.

Aşkımı yerlere çalan güzelim,

Uyuşmuş tutmayan elden beter ol.

Dilerim olmasın  halini soran,

İçinde dinmesin tipi ve boran,

Çoşarak çağlayıp kendini yoran,

Amacı olmayan selden beter ol.

Tüm  güller kurusun kalsın elinde,

Onulmaz yaralar çıksın dilinde,

Yarısı yanmış bir kor halinde,

Çöplüğe dökülen külden beter ol.

Kararsın o güzel dünyan anında,

Eski kılıç gibi paslan kınında,

Derdini dökemeyip te utancında,

Hiç konuşamayan lal’dan beter ol.

Dehlizde kalarak küflenip kokan,

Yaşamdan ümidi kesip te  bıkan,

Umarım gelmez bir araya yakan,

Yıpranmış eskimiş çuldan beter ol.

Saçların ağarsın belin bükülsün,

Ağzında dişlerin hepsi dökülsün,

Viran olsun dünyan, ömrün sökülsün...

Kuruyup dökülen gülden beter ol.

Dilerim solasın gonca gül iken,

Yollarına dolsun çalı ve diken,

Su dahi akmasın toprakta köken,

Ağaçta kuruyan daldan beter ol.

Abbas der sarılmaz dünyanın ipi,

Gönlümde boş yere estirdin tipi!

Sahipsiz dolaşan bir mektup gibi,

Üstü mühürlenmiş puldan beter ol.', 'Aklımı başımdan alan güzelim, Ceryanı olmayan telden beter ol. Aşkımı yerlere çalan güzelim, Uyuşmuş tutmayan elden beter ol. Dilerim olması...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beter-ol-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Devrin Haline Bak!', 'su-devrin-haline-bak-abbas-yurt-crv39', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu devrin halini seyrana çıktım,

Millet bir hülyaya dalmış gidiyor.

Zamane üstüne şiirler yazdım,

Dümensiz gemiyi salmış gidiyor.

Dümensiz gemiyi yürütür kaptan,

Parasız insanlar düşüyor çaptan,

Namus paroladır satılır toptan,

Dünya nerden gelmiş, nere gidiyor.

Kirli bir şapkası vardır başında,

Pantolonu yoktur kadın peşinde,

Hayatını zehirler genç yaşında,

Sigarayla duman salmış gidiyor.

Sadaka vermeden başa kalkarlar,

Bir dal oduna bir orman yakarlar,

Yakasız gömleğe kravat takarlar,

Dünyadan habersiz gelmiş gidiyor.

Aman allahım ne günlere kaldık,

Herşeyi bırakıp hayala daldık,

İyi insana artık hasret kaldık,

İyi insanlar hep göçüp gidiyor.

Sağcı, solcu diye kavga ederler,

Birbirine karşı bir kin güderler,

Nicesini canlarından ederler,

Arkada gözyaşı akıp gidiyor.

Oturup bacak bacağa atarlar,

Karavana atıp, dolu tutarlar,

Ortalığı birbirine katarlar,

Dünya züppelerle dolmuş gidiyor.

Abbas''ım çok karışık devirdeyiz,

Kimi sevinç içinde, kimi yeis,

Bu devirde atlara bakan seyis,

Bırakmış dizgini salmış gidiyor.

                                    06.06.1978', 'Şu devrin halini seyrana çıktım, Millet bir hülyaya dalmış gidiyor. Zamane üstüne şiirler yazdım, Dümensiz gemiyi salmış gidiyor. Dümensiz g...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/su-devrin-haline-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozuk Dünya', 'bozuk-dunya-abbas-yurt-gnbkd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu dünyada bozulmayan ne kaldı ki,

Caddeler bozuk, yollar bozuk.

Zengin bir koca arayan,

Kızlar bozuk, dullar bozuk.

Pisliklerle dolu her kıyımız,

Sık sık kesilir çeşme suyumuz,

Çıkar can fakat çıkmaz huyumuz,

Kalpler bozuk, gönüller bozuk.

Obur mideler buna alışık,

Et kokmuş, yağ karışık,

Her gün  sık sık kesilir ışık,

Trafolar bozuk, piller bozuk.

Tilkilerin de sesi çıktı,

Her yüzün bir maskesi çıktı,

Her şeyin çok sahtesi çıktı,

Paralar bozuk, pullar bozuk.

Gün boyunca çalışmamız,  gayretimiz,

Anlımızda namusumuz, iffetimiz,

Kafamızın içindeki niyetimiz,

Başlar bozuk, gözler bozuk.

Erzincanlı yazar eserini,

Anlayıp ta bilen çıkmaz değerini,

Artık anlayan yok birbirini,

Kalemler bozuk, diller bozuk.

Yalan değil gerçek yazdıklarım,

Abbas der işlerimiz kalmasın yarım,

Kızma bana ey yüce ulu tanrım,

İnsan diye yarattığın kullar bozuk.', 'Şu dünyada bozulmayan ne kaldı ki, Caddeler bozuk, yollar bozuk. Zengin bir koca arayan, Kızlar bozuk, dullar bozuk. Pisliklerle dolu her kı...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bozuk-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah Bizdeymiş', 'gunah-bizdeymis-abbas-yurt-d0fbe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapısından içeri almayanlar,

Oy verme zamanı geldiler bize.

Söz hakkı veripte dinlemeyenler,

Tüm delegeleri saldılar bize.

Söylevler ile bütün nutuklardan,

Mesajlarla seçim meydanlarından,

Bütün adaylar hepsi bir ağızdan,

Baş tacımızsınız dediler bize.

Meclise girip te vekil olunca,

Unuttular bizi hepsi topluca,

Verilen sözlerden hesap sorunca,

Biz vekiliz deyip güldüler bize.

Enflasyon, işsizlik hepsi bir hile,

Gözümüze bakarak bile bile,

Fiyat ayarlamasıyla, vergiyle,

Bütün günahları buldular bize.

28.05.2001', 'Kapısından içeri almayanlar, Oy verme zamanı geldiler bize. Söz hakkı veripte dinlemeyenler, Tüm delegeleri saldılar bize. Söylevler ile büt...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gunah-bizdeymis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umurumda Değil', 'umurumda-degil-abbas-yurt-8mde3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir olmaza selam verdim almadı,

Umurumda değil almayıversin.

Bir mektup yazdım cevap salmadı,

Umurumda değil salmayıversin.

Oynak gözleri olmuş bir fal taşı,

Baldudaklıkla aldatılamaz kişi,

Verdiğim ayranla çalmıyor aşı,

Umurumda değil çalmayıversin.

Niye viran etti gönül tahtımızı,

Kara deftere yazdı bahtımızı,

Boş laflarla harcadı vaktimizi,

Umurumda değil harcayıversin.

İstemem artık olsan da melek,

Atacaksın bana belki de kelek,

Gelmedi yanıma şu kahpe felek,

Umurumda değil gelmeyiversin.

Ahd edip ikrarında geçti ise,

Bülbüller gülüne yad seçti  ise,

Abbas’tan birisi vazgeçti ise,

Umurumda değil vazgeçiversin.

                                13.12.1978', 'Bir olmaza selam verdim almadı, Umurumda değil almayıversin. Bir mektup yazdım cevap salmadı, Umurumda değil salmayıversin. Oynak gözleri ol...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/umurumda-degil-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başkasını Seversem Eğer', 'senden-baskasini-seversem-eger-abbas-yurt-sbkbn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim kör olsun, tutulsun dilim,

Senden başkasını seversem eğer.

Çürüsün kemiklerim, kırılsın elim,

Senden başkasını seversem eğer.

Cami önlerinde mendil açayım,

Aşk badesi diye zehir içeyim,

Bahçemde gül diye diken biçeyim,

Senden başkasını seversem eğer.

Doktorlar, hekimler derdim bilmesin,

Abbas der dünyada yüzüm gülmesin,

Hiç kimsecikler göz yaşım silmesin,

Senden başkasını seversem eğer.

                                           1979', 'Gözlerim kör olsun, tutulsun dilim, Senden başkasını seversem eğer. Çürüsün kemiklerim, kırılsın elim, Senden başkasını seversem eğer. Cami ...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senden-baskasini-seversem-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılsın Senin Ellerin Kahpe Felek', 'kirilsin-senin-ellerin-kahpe-felek-abbas-yurt-e40fh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir dünyayı bir garibe çokmu sandın,

Kör olsun senin gözlerin kahpe felek.

Canını almayıp ta yaralı koydun,

Kırılsın senin ellerin kahpe felek.

Uçarken havada kanadımı kırdın,

Hiç acımadan yaman yerimden vurdun,

Bu sana be adam müstehaktır dedin,

Bağlansın senin dillerin kahpe felek.

Ben sana ne yaptım ki sen bana küstün,

Fırtına gibi girdin bağıma estin,

Düz ovada bile dermanımı kestin,

Tutulsun senin yolların kahpe felek.

Gülümü koparıp ta gurbete  attın,

Sen kolumdan tutup yerden yere çaldın,

Bizi neden böyle ilden ile sattın,

Yıkılsın senin illerin kahpe felek.

Abbas''ım ey felek nedir benle derdin,

Engerek yılanını ardımdan saldın,

Ayakta duracak bir mecal mi koydun,

Kesilsin senin dizlerin kahpe felek. 15.08.1979', 'Bir dünyayı bir garibe çokmu sandın, Kör olsun senin gözlerin kahpe felek. Canını almayıp ta yaralı koydun, Kırılsın senin ellerin kahpe fel...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirilsin-senin-ellerin-kahpe-felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Dünyanın', 'boyle-dunyanin-abbas-yurt-2am63', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden çalı dikenle doldu yolum,

Bana yaptıkların yetmez mi zalim? 

Kırıldı kanadım, kırıldı kolum,

Canı cehenneme böyle dünyanın.

Kara yılan oldun ardımdan geldin,

Zehirli oklarla sinemi deldin,

Gam ve keder ile ömrümü yedin,

Canı cehenneme böyle dünyanın.

Anlımıza böyle yazılmış ahir,

Şu kahpe hayatı ettin bir zehir,

Çekmekle bitmiyor bu kadar kahır,

Canı cehenneme böyle dünyanın.

İşkence yapıp ta candan bezdirdin,

Anlımıza kara yazı yazdırdın,

Neden gurbetten gurbete gezdirdin,

Canı cehenneme böyle dünyanın.

Bilmem ki nedir şu Abbas''a kastın,

Bir kasırga olup bağımdan estin,

Yetmez mi artık dermanımı kestin,

Canı cehenneme böyle dünyanın.

                                           24.11.1979', 'Neden çalı dikenle doldu yolum, Bana yaptıkların yetmez mi zalim?  Kırıldı kanadım, kırıldı kolum, Canı cehenneme böyle dünyanın. Kara yılan...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/boyle-dunyanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Çarptı Beni', 'ask-carpti-beni-abbas-yurt-pwlh5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk kelimesinin anlamını bilmezidim,

Aşka inanana için için güleridim,

Aşkı ben boş, gereksiz bir duygu sanıridim,

Aşk çarptı beni yerden yere vurdu savurdu.

İnsan ne olduğunu dahi hiç anlamıyor,

Aç kalıyor, susuz kalıyor hiç bilemiyor,

Sarhoştan farkı yok kendine hiç gelemiyor,

Aşk çarptı beni hemen de hesabını sordu.

Aşığım ben aşık, içim alev alev yanıyor,

Aşk sarhoşuyum başım fena halde dönüyor,

Hançer yemişten beterim, yüreğim kanıyor,

Aşk çarptı beni tuttu ta canevimden vurdu.

Aşk; yemekmiş, suymuş, içmem gereken doluymuş,

Aşk; sevenlerin, sevgililerin bir yoluymuş,

Aşk; en güzel şeymiş, güzelliklerle doluymuş,

Aşk çarptı beni ağına alıp tuzak kurdu.

Abbas der aşkı aşık olunca ben anladım,

Sevdim, seviyorum hiç sevgiye ben doymadım,

İğne batırdılar acısını hiç duymadım,

Aşk çarptı beni ateş gibi yaktı kavurdu.

28.04.1979', 'Aşk kelimesinin anlamını bilmezidim, Aşka inanana için için güleridim, Aşkı ben boş, gereksiz bir duygu sanıridim, Aşk çarptı beni yerden ye...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-carpti-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oy Zalim Kader', 'oy-zalim-kader-abbas-yurt-7h2r1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Izdırap çekmekle geçiyor ömrüm,

Yıkılasın seni oy zalim kader.

Kalbimde acı, hüzün dolu gönlüm,

Yıkılasın seni oy zalim kader.

Ağlarım, inlerim budur kederim,

Acılar içinde kaldım beterim,

Şu kahpe hayata hayat mı derim,

Yıkılasın seni oy zalim kader.

Neden kırdın kanadımı, kolumu,

Çalı  diken oldun kestin yolumu,

Gurbete saldın sen nazlı gülümü,

Yıkılasın seni oy zalim kader.

Çektirdiğin acı bana yetmez mi? 

Ayrılık belası birgün bitmez mi? 

Acılar kederler benden gitmez mi? 

Yıkılasın seni oy zalim kader.

Ne zaman bitecek çileli günler,

Abbası bilenler halinden anlar,

Yeter artık bitsin çileli yollar,

Yıkılasın seni oy zalim kader.

                                             17.08.1979', 'Izdırap çekmekle geçiyor ömrüm, Yıkılasın seni oy zalim kader. Kalbimde acı, hüzün dolu gönlüm, Yıkılasın seni oy zalim kader. Ağlarım, inle...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oy-zalim-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni', 'sen-beni-abbas-yurt-do7mn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buldun sende benim gibi garibi,

İstediğin yöne dönder sen beni.

Bilmem olurmuyum derdin tabibi,

Derdine dermana gönder sen beni.

Şu benim sevdiğim bana gülüyor,

Salını salını yolda geliyor,

İçim alev alev oldu yanıyor,

Sineme su döküp söndür sen beni.

Hatasız kul olmaz böyle sev beni,

Şu hayat yoldaşan bir bakta tanı,

Yok yere insan kırarmı insanı,

Yareme el vurup güldür sen beni.

Ben sensiz bu canı neyler satarım,

Terazi elimde kantar tartarım,

Yayladan yaylaya göçüp giderim,

Konaktan konağa kondur sen beni.

Abbas''ım gülüm gücenmem ben sana,

Unutma insanlık lazım insana,

Eğerki ihanet edersem sana,

Al hançeri vur öldür sen beni.

                                 07.07.1979', 'Buldun sende benim gibi garibi, İstediğin yöne dönder sen beni. Bilmem olurmuyum derdin tabibi, Derdine dermana gönder sen beni. Şu benim se...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-beni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleğim', 'melegim-abbas-yurt-bwhzc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İyi kalpli perimisin,

Cennetteki hurimisin,

Bal yapan bir arımısın,

Benim güleryüzlü meleğim.

Cennet bağında bir gülmüsün? 

Yoksa dalımda öten bülbülmüsün? 

Gönlümde biten sünbülmüsün? 

Benim tatlı dilli meleğim.

Bahçemde açan çiçekmisin? 

Sevgiyle bekleyen kucakmısın? 

Yoksa aşımı pişirecek ocakmısın? 

Benim alçak gönüllü meleğim.

                                       26.01.1980', 'İyi kalpli perimisin, Cennetteki hurimisin, Bal yapan bir arımısın, Benim güleryüzlü meleğim. Cennet bağında bir gülmüsün?  Yoksa dalımda öt...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/melegim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-abbas-yurt-gkpc9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Severim ben engini,

Ela gözlerinin rengini,

Fısılda bana sevgini,

Sende buldun dengini.

Kaybetmem ben özümü,

Ayıramıyorum senden gözümü,

Özlüyorum güler yüzünü,

Yapma artık bana nazını.

Ellerinde geziyor yeleğim,

Asılı kaldı köydeki eleğim,

Kabul olursa dileğim,

Mesut oluruz meleğim.

                                26.01.1980', 'Severim ben engini, Ela gözlerinin rengini, Fısılda bana sevgini, Sende buldun dengini. Kaybetmem ben özümü, Ayıramıyorum senden gözümü, Özl...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgiliye-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm Cemalini', 'gordum-cemalini-abbas-yurt-ps3mc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yar yoluna canı feda eyledim,

Mağrib’ten Maşrib’e selam söyledim,

İndim aşkın deryasını boyladım.

Gördüm cemalini ben senin yarim.

Yedi derya bir olup çalkalandı,

Nice canlar gelip hep halkalandı,

Görenler şaşırıp ta dona kaldı,

Gördüm cemalini ben senin yarim.

Bu garibin arşa çıktı feryadı,

Buna veremez bir anlam kör kadı,

Dilimden düşürmem onun var adı,

Gördüm cemalini ben senin yarim.

			30.07.1980', 'Yar yoluna canı feda eyledim, Mağrib’ten Maşrib’e selam söyledim, İndim aşkın deryasını boyladım. Gördüm cemalini ben senin yarim. Yedi dery...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gordum-cemalini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gam Yeme', 'gam-yeme-abbas-yurt-y5cdl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlümde bulunmaz senin bir eşin,

Gam yeme güzelim severim seni.

Öyle mahsun durma sil gözün yaşın,

Gam yeme güzelim severim seni.

Başka çiçekleri koklasam bile,

Bülbülü kaptırmam yabani güle,

Canım feda olsun yeter ki dile,

Gam yeme güzelim severim seni.

Huysuzluk yaptıysam hor görme  beni,

Belkide görmüşüm senin hatanı,

Şu garip abbası çok iyi tanı

Gam yeme güzelim severim seni.', 'Gönlümde bulunmaz senin bir eşin, Gam yeme güzelim severim seni. Öyle mahsun durma sil gözün yaşın, Gam yeme güzelim severim seni. Başka çiç...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gam-yeme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara Beni', 'yara-beni-abbas-yurt-78doh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yara beni, yara beni,

Mahvetti bu yara beni.

Derdinden divane oldum,

Kavuşturun yara beni.

Yara beni, yara beni,

Fitlediler yara beni.

Uçurumlardan aşağı,

Uçurdular yara beni.

Yara beni, yara beni,

Kurban edin yara beni.

Sevdiğime kavuştum ben,

Öldürmez bu yara beni.', 'Yara beni, yara beni, Mahvetti bu yara beni. Derdinden divane oldum, Kavuşturun yara beni. Yara beni, yara beni, Fitlediler yara beni. Uçuru...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yara-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünür! !', 'dusunur-tuncay-akdeniz-gctpn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bülbülün umudu kalır bahara,

Konar bir çalıya gülü düşünür.

Kırdırmaz dalını,hara rüzgara,

Bağbancı bağında dalı düşünür

Gelinler beşikte,bebeği bezer,

Yetimlerin eli,koynunda gezer.

Arılar çiçeğin,sırrını çözer,

Girer kovanında balı düşünür.

Bu aşkın sevdası,büktü belimi,

İstersen bağımda soldur gülümü

Can çıkmıyor canda,bekler ölümü

Kerem yanar aslı külü düşünür

Anasız ağlaşır körpe kuzular

Yüzü gülmez yürek yara sızılar

Sevda hasretinde aşkı arzular

Bahar sevdasında yeli düşünür

Bu sevdayla aşkın,gülünü kokla,

Kurut yaprağını,hatıra sakla.

Yaralama gönlü,attığın okla,

Mecnun Leylasını çölü düşünür

İnsanlar yorulur gönül  yorulmaz

Sevgisiz gönülden sevgi alınmaz

Her suyun üstünde geçit bulunmaz

Gönülden gönül''e yolu düşünür

Sevgisi kaplamış bak asumanı

Gönüller sınırsız derin ummanı

Tuncay’a sev demiş sevdiğin canı

Dünyası bir başka kulu düşünür', 'Bülbülün umudu kalır bahara, Konar bir çalıya gülü düşünür. Kırdırmaz dalını,hara rüzgara, Bağbancı bağında dalı düşünür Gelinler beşikte,be...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dusunur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Arkadaş Tanıdım', 'bir-arkadas-tanidim-abbas-yurt-kd81j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir arkadaş tanıdım ne kadar iyi,

Sanki iyilikte yapılmış onun suyu,

Bir arkadaş tanıdım iyilik beyi,

İyilik hamuruyla yoğrulmuş huyu.

Bir arkadaş tanıdım ne kadar insanı,

Çok geniştir onun gönlündeki hanı,

Görünce insanın kaynar hemen kanı,

Kendime bir kardeş gibi tanırım onu.

Bir arkadaş tanıdım hal pazarında,

Aradığımı buldum yine o eski handa,

İnsanın gerçek kişiliği kandadır kanda,

Ne kadar sevdim bilsen gördüğüm anda.

Bir arkadaş tanıdım garip bir yolcu,

Sanki iyilik için yaratılmış bir arzuhalcı,

İyilik denizinde yüzen ey garip salcı,

Oldu bunlar benim sinemde bir ölçü.

Bir arkadaş tanıdım ne kadar cömert,

İyilikte hisse kapan mert oğlu mert,

Bazen yumuşak huylu, bazen çok sert,

Dünyada üzerini iyilik yorganı ile ört.

Bir arkadaş tanıdım meçhul bir yolda,

Abbas der  anlayan çok az olur halde,

İnsan kıymeti olmaz parada pulda,

Arılar gibi dolaş çiçekte  balda.', 'Bir arkadaş tanıdım ne kadar iyi, Sanki iyilikte yapılmış onun suyu, Bir arkadaş tanıdım iyilik beyi, İyilik hamuruyla yoğrulmuş huyu. Bir a...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-arkadas-tanidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalanlara Sesleniş', 'kalanlara-seslenis-abbas-yurt-9g1yl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ömrümün en güzel yanı,

İncitmedim hiçbir canı,

Dünya bomboş herşey fani,

Sevgidir herşeyin başı.

Kem lafları almam dile,

Kıyamadım hiçbir güle,

Ayrılık anında bile,

İstemedim hiç gözyaşı.

Kulak ver o meçhul sese,

Sanma kalır son nefese,

İbret olsun tüm herkese,

Başımdaki mezar taşı..

                                       03.05.2001', 'Ömrümün en güzel yanı, İncitmedim hiçbir canı, Dünya bomboş herşey fani, Sevgidir herşeyin başı. Kem lafları almam dile, Kıyamadım hiçbir gü...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalanlara-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostiş', 'akrostis-abbas-yurt-wt64s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlamadım şu dünyanın halinden,

Boşuna dolaştım gurbet ilinden,

Bıktım artık goncasından gülünden,

Ayrı düştüm vatanımdan, ilimden,

Sandım ki yaralar çıkmış dilimden,

Yalnız kaldım bir şey gelmez elimden,

Uzaklardan bir ses gelir derinden,

Rağbet etmem dünyaya kederimden,

Ta ki oynayınca her yer yerinden. 

                                      20.03.1978', 'Anlamadım şu dünyanın halinden, Boşuna dolaştım gurbet ilinden, Bıktım artık goncasından gülünden, Ayrı düştüm vatanımdan, ilimden, Sandım k...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/akrostis-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadutum', 'karadutum-abbas-yurt-qrukp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara duta benzersin,

Neden beni üzersin,

Hikaye, roman değil,

Sen bir destan yazarsın.

		Hadi canım sende gel,

		Aşk atına binde gel,

		Onu bunu boşverip; 

		Özümüze dönde gel.

Kara dutum ez beni,

Tam kalbine yaz beni,

Gönlünün tesbihine,

Sıra sıra diz beni.

Hadi canım sende gel,

		Hadi canım sende gel,

		Aşk atına binde gel,

		Onu bunu boşverip; 

		Özümüze dönde gel.

Kara dut ulu orta,

Elmam var turta turta,

Kalbinde sakla beni,

Yedirme kuşa, kurda.

Hadi canım sende gel,

		Hadi canım sende gel,

		Aşk atına binde gel,

		Onu bunu boşverip; 

		Özümüze dönde gel.

Kara dut şıra gibi,

İçilmez bira gibi,

Sevdandan yanıyorum,

Tutuşmuş çıra gibi.

Hadi canım sende gel,

		Hadi canım sende gel,

		Aşk atına binde gel,

		Onu bunu boşverip; 

		Özümüze dönde gel.

				28.01.2003', 'Kara duta benzersin, Neden beni üzersin, Hikaye, roman değil, Sen bir destan yazarsın. 		Hadi canım sende gel, 		Aşk atına binde gel, 		Onu ...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/karadutum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atışma', 'atisma-abbas-yurt-0bgr8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yöresel ozan dursun hazani ile 15 aralık 1978 tarihinde yapılan 

karşılıklı şiir atışması.

       Zanneder

Gerçekleri savunmayan serseri,

Kendi kendisini insan zanneder.

Erzincan diyor belki Kayseri,

Zemheri ayını nisan zanneder.

                                                                Zannetme

  			Gerçekleri savunduğunu sanan serseri,

			Sende kendini insan zannetme.

			Erzincan olamaz ki gafil Kayseri,

			Böyle bir şeyi sakın  meram zannetme.

Gündüze gece der, güneşe de ay,

Palavra atmak dile pek kolay,

Bakır madenine vurulur kalay,

Cahil bunu alamiyon zanneder.

			Gündüz gece, güneş de ay olamaz,

			Bizi palavracı sanma behey anlamaz,

			Yaptığın cahilliktir, dostluk olamaz,

			Dışarda bakıp ta bizi cahil zannetme.

Ömründe görmemiş mektep, medrese,

Mektup yazıyor gayet meçhul adrese,

Hazani gel uyma kendini bilmeze,

İstanbulu görse afyon zanneder.

                                              Dursun Hazani

			Mektep, medreseyle olunmaz insan,

			Sen kendi düşünceni kendine korsun,

			Kendini hazani diye tanıtan dursun,

			Her insanı sakın hayvan zannetme.

			Abbasiyim bizi şiirde anlamaz sanma,

			İnsanları iyi tanı, sakın aldanma,

			Önüne bak,  ateşe düşüpte yanma,

			Sende kendi kendini ozan zannetme.

        								abbas yurt', 'Yöresel ozan dursun hazani ile 15 aralık 1978 tarihinde yapılan  karşılıklı şiir atışması.        Zanneder Gerçekleri savunmayan serseri, Ke...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/atisma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-ali-baydere-ll98k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başladığım yerdeyim yine; 

Dünyayı rahatlıkla seyredebildiğim

Tek yer burası.

Odamdaki pencerenin dibine çökmüşüm.

Bir elimde sigara,

Diğerinde; 

İlk cümleyi yazdığım kalemim.

Yirmi dokuz harfi karışık şekillerde kullanıyorum yine.

Köşedeki camiden ezan sesleri yükseliyordu.

Hiçbir dine mensup olmamıştım oysa ben.

Tek inancım, tek taptığım aşktı,

Belki de aşığın dini aşktır sadece.

Odamdaki dünyadan

Farklı bir dünya görüyorum

Her seferinde dışarıda.

Bir çift sevgili konaklamış

Ağacın yanı başında,

Sevdalarını kazıyorlar; 

O narin, uzun, ve kıvrımlı ağacın gövdesine

Benim aşkımı kazıdığım ağaç

Çoktan parçalanıp,

Herhangi bir ocakta

Ateşle birleşmiştir mesela.

Benim birleşmemden önce olmasa da.

Karşı komşunun kızları,

Bir balkondan diğerine

Bağırarak konuşuyorlardı.

Halbuki benim hiç komşum olmamıştı

Ve hiçbir şekilde

Bağırarak konuşamamıştım.

Çok istemiştim bunu yapmayı aslında.

Hep kısık sesle duyurmaya çalıştım kendimi

Ve hep sesimle yıkmaya çalıştım 

Önümdeki duvarları.

Yine bir akşam üstü.

Yine yalnız yaşıyorum yalnızlığı.

Dedim ya hiç kimse olmamıştı

Yalnızlığımı benimle yaşayacak.

Benim dünyam çok küçüktü oysa.

Görebildiğim her şey

Ufuktan öncesiyle sınırlıydı.

Herkesin bir yuvası,

Bir işi gücü vardı,

Şu dünyada.

Benim gibi içinde

Çark ettirmiyor dünyayı,

Yaşamıyor kimse benim gibi

Yalnız yalnızlığıyla.', 'Başladığım yerdeyim yine;  Dünyayı rahatlıkla seyredebildiğim Tek yer burası. Odamdaki pencerenin dibine çökmüşüm. Bir elimde sigara, Diğeri...', ARRAY['Türk Edebiyatı','Şiir','Ali Baydere']::text[], 8.5, '{"poet":"Ali Baydere","poet_slug":"ali-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/bosluk-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-gorkem-kizir-9jeix', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün yalnız bir gündü,

Bugün daha yalnız bir gün.

Dün sen yoktun,

Bugün seni anlatacak kimsem.

Dün yalnız bir gündü,

Sen yoktun rüyamda.

Bugün daha yalnız bir gün,

Çünkü sen bir tek rüyamda.

Dün yalnız bir gündü,

Çünkü kendimle yalnızdım.

Bugün daha yalnız bir gün,

Çünkü kendimi sana kaptırdım..', 'Dün yalnız bir gündü, Bugün daha yalnız bir gün. Dün sen yoktun, Bugün seni anlatacak kimsem. Dün yalnız bir gündü, Sen yoktun rüyamda. Bugü...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kizir']::text[], 8.5, '{"poet":"Görkem Kizir","poet_slug":"gorkem-kizir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlik-247-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Zevki', 'olumun-zevki-gorkem-kizir-4yths', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kerem ile Aslı görselerdi bizi

Kıskanırlardı belliki

Ölümü zevkle kucaklayan bizi.

Günahın davet ederken gül kokulu bahçelerde

Gül ve diken misali birbirimize kenetlenirken.

Mutluluktan kanayan vucütlarımız

Zevkten ağlamalarımız

Beyinlerimiz ölürken

Birbirimize acımasızca saldırışlarımız.

Görselerdi, kıskanırlardı belliki...', 'Kerem ile Aslı görselerdi bizi Kıskanırlardı belliki Ölümü zevkle kucaklayan bizi. Günahın davet ederken gül kokulu bahçelerde Gül ve diken ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kizir']::text[], 8.5, '{"poet":"Görkem Kizir","poet_slug":"gorkem-kizir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olumun-zevki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-aldanma', 'a-aldanma-mikdat-bal-onjei', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aldanma! 

Bir gürültü kopar şimşekten sonra 

Gözleri kör eden nur’a aldanma! 

Yiğit insan kalkar düştükten sonra 

Kolay yolu seçip, zor’a aldanma! 

Evet bu memleket fesatla doldu 

Bir sis çöktü her şey karardı soldu 

Sanma her şey bitti, her şey yok oldu 

Kışın çiçek açan kır’a aldanma 

Vatan hainleri ezilir bir gün 

Üzüldüğün gibi üzülür bir gün 

Umutlu ol her şey düzelir bir gün 

Ağustosta yağan kara aldanma! 

Cevap yanlış olur yanlış soruya 

Kötüleri terk et yürü doğruya 

Senaryo icabı öten boruya 

Vakitsiz üflenen sura aldanma 

Boş ver, localara katılmışları 

Onlar bu milletin atılmışları 

Sakın örnek alma satılmışları 

Euro’ya, dolara, kur’a aldanma! 

Mikdadî der elbet taraf olmalı

Bu fetret bitmeli saf, saf olmalı 

Peşinden gittiğin şeffaf olmalı 

Lider bilir deyip, köre aldanma!



Şair Mikdat Bal', 'Aldanma!  Bir gürültü kopar şimşekten sonra  Gözleri kör eden nur’a aldanma!  Yiğit insan kalkar düştükten sonra  Kolay yolu seçip, zor’a al...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aldanma-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esaret', 'esaret-gorkem-kizir-nvts9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Esaretin verdiği karanlıkta

Aydınlık bir aşk bizimkisi

Mutlu ama gözü yaşlı

Güneşli havada yağmurlar misali..', 'Esaretin verdiği karanlıkta Aydınlık bir aşk bizimkisi Mutlu ama gözü yaşlı Güneşli havada yağmurlar misali.....', ARRAY['Türk Edebiyatı','Şiir','Görkem Kizir']::text[], 8.5, '{"poet":"Görkem Kizir","poet_slug":"gorkem-kizir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/esaret-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıran İllet', 'ayiran-i-llet-abdullah-turgut-jiwws', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dönüşünü bekledim yine,

Gecenin zifiri karanlığında,

Sokaklarda bir tek ben,

Bir de cızırdayan elektrik direkleri,

Bekledim sabahın ilk ışıklarına kadar,

Ama sen gelmedin,

Neden,neden gelmedi diyordum kendi kendime saatlerce,

Sonradan ögrendim neden yanımda olmadığını,

Seni suçlamıştım boşu boşuna bilmeden,

Beni sevmediğini,aşkının yalan olduğunu,

Dedim kendi kendime güneşin sabahı yaran; 

Işıkları ortaya çıkana dek,

Duygularımın onun için hiçbir anlamı olmadığını,

Bir oyuncak gibi benimle oynadığını,

Düşünmüştüm zamansız saatlerce,

Keşke o an azrail gelseydi de,

Canımı benden alsaydı,bunları düşünürken,

Ama nerden bilebilirdim ki,

Senin o amansız,zalim illetin kucağına düştüğünü,

Hiçbir şeyin bizi birbirimizden ayıramayacagına,

Yemin etmiştik aşkın kutsal mabedinde,

Bunun bu kadar kolay ve basit olacagını düşünmemiştim,

Bir an bile olsa senden ayrı olamk.sensiz olmak,

Ölümden daha beter geliyordu bana,

Acıya,kahıra herşeye dayanabilirdim,

Ama peki ya sensizliğe,', 'Dönüşünü bekledim yine, Gecenin zifiri karanlığında, Sokaklarda bir tek ben, Bir de cızırdayan elektrik direkleri, Bekledim sabahın ilk ışık...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ayiran-illet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bihaber', 'bihaber-abdullah-turgut-42ocg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün yine yanımdaydın,

Her zamanki gibi,

Seni sevdiğimden habersizce,

Belki de biliyordun sevdiğimi,

Yanımda toprağın üzerini kaplayan,

Bembeyaz bir kar örtüsü gibi saf bir şekilde,

Herşey habersiz,

Masum bir çocuk gibi', 'Bugün yine yanımdaydın, Her zamanki gibi, Seni sevdiğimden habersizce, Belki de biliyordun sevdiğimi, Yanımda toprağın üzerini kaplayan, Bem...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bihaber-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-gulseren-onay-wt8dx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensizlik 

Yoldaş oldu,

Düşmüş peşine 

Düşlerde arıyorum..

Nerdesin? 

Sırdaş oldu korkular 

Gecenin gölgesinde.. 

Kabuslarda buldum

Seni...

Yokluğunda

Tutsak olmuşum 

Hasretine... 

Uzandım,uzandım

Ulaşamadım....

GÜLSEREN ONAY

01/06/2005/ANTALYA', 'Sensizlik  Yoldaş oldu, Düşmüş peşine  Düşlerde arıyorum.. Nerdesin?  Sırdaş oldu korkular  Gecenin gölgesinde..  Kabuslarda buldum Seni... ...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasret-252-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilelim', 'bilelim-tuncay-akdeniz-yfgtk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bulutlar olmasa,rahmet var olmaz,

Toprağında göl olmayı bilelim

Çiçeği sevmese,arılar konmaz,

Kovanında bal, olmayı bilelim

Kusur kabahat çok olur kulda

Bülbülün sevgisi gül ile dalda

Hasretlik içimde gözlerim yolda

Gönüllerde hal olmayı bilelim

Her işin başına başlanır erken

Ha bugün ha yarın yapayım derken 

Güllerin içinden ayrılmaz diken

Dallarında gül olmayı bilelim

Çok gönül gezilir edeple arla

Bahçıvansız bağa neylesin tarla

Rüzgar olup esme tipiyle karla

Seherlere yel olmayı bilelim

Haramı katılmaz helal varına

Güvenme dağların beyaz karına

Hazırlığın yoksa eğer yarına

Orasına yol olmayı bilelim

Tuncay diyor insan gönlü kırılmaz

Hatır pazarına vicdan satılmaz

Doğru varken eğrilere katılmaz

Yaradan a kul olmayı bilelim', 'Bulutlar olmasa,rahmet var olmaz, Toprağında göl olmayı bilelim Çiçeği sevmese,arılar konmaz, Kovanında bal, olmayı bilelim Kusur kabahat ço...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bilelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğam', 'dogam-abdullah-turgut-hc0at', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğanın ilkbaharda yeniden doğduğu gibi,

Bende seni görünce yeniden doğuyordum.

Sen gidinceyse; 

Sonbaharda solan hazan yaprakları gibi solup,

Hayat ağacının dalından kopuyordum.

Bir bulut olmak isterdim bunun için; 

Devamlı seninle birlikte olmak,

Gittiğin her yerde seni takip etmek,

Seni yalnız bırakmamak ve sensiz olmamak için…', 'Doğanın ilkbaharda yeniden doğduğu gibi, Bende seni görünce yeniden doğuyordum. Sen gidinceyse;  Sonbaharda solan hazan yaprakları gibi solu...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fetih', 'fetih-abdullah-turgut-pv6kk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinin içine bakınca dünyalar,

Benim olurdu sanki,

Orada bin bir güzellikte bir renk cümbüşünün

İçinde kalırdım zamansızca

Sanki içinde kelebeklerden kurulu bir ordu vardı,

Sefere hazırlanıyorlar gibiydi,

Kalbimin içindeki sevgi kalesini fethetmeye,

Ama buna gerek yoktu ki; 

Bu sevgi kalesi sana teslim olmaya hazırdı,

Buna bir gülüşün,bakışın yeterdi…', 'Gözlerinin içine bakınca dünyalar, Benim olurdu sanki, Orada bin bir güzellikte bir renk cümbüşünün İçinde kalırdım zamansızca Sanki içinde ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/fetih-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-abdullah-turgut-mft12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen,sen,sen ve yine sen 

Her yerde seni arıyorum,

İçtiğim suda,soluduğum havada,yediğim ekmekte...

Ne yana baksam hep seni görüyorum,

Sanki okyanusun ortasındayım,

Ne yana baksam deniz,

Sen benim denizimsin,

Geceleri gökyüzüne baktığım zaman,

Gördüğüm her yıldız da seni arıyorum,

Ama biliyorum ki yoksun,

Sen benim kalbimdesin,

İnsan kalbi de bir gökyüzü değil midir? 

İçinde sayısız yıldızı barındıran,

Ama benim için; 

İçlerinden biri daima özel olacaktır; 

O da sensin sevgilim,

Ne zaman bir yıldız kaysa gökyüzünden

Sen olmasından korkuyorum.

İşet o zaman biliyorum ki,

Artık sen olmayacaksın,

Sensiz bir hayatı düşünemediğim içinde; 

Bende varolmayacağım...', 'Sen,sen,sen ve yine sen  Her yerde seni arıyorum, İçtiğim suda,soluduğum havada,yediğim ekmekte... Ne yana baksam hep seni görüyorum, Sanki ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-563-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-abdullah-turgut-4vx2c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum; 

Seni bana sevmeyi öğrettiğin için seviyorum,

Seni ne vücut ölçülerin için,ne de zenginliğin için; 

Seni sen olduğun için seviyorum,

Seni yüzündeki o tatlı gülüşün için seviyorum,

Seni sevgi dolu kalbin için seviyorum,

Seni sevgiyle bakan kömür karası gözlerin için seviyorum,

Seni insanları küçümsemediğin için seviyorum,

Seni baldan tatlı dilin için seviyorum,

Seni karanlık dünyalara ışık tuttuğun için seviyorum,

Seni güneşe muhtaç dünya gibi  seviyorum,

Seni suya muhtaç toprak gibi seviyorum,

Seni azad edilmiş bir köle gibi seviyorum

Anlayacağın seni deli gibi SEVİYORUM…', 'Seni seviyorum;  Seni bana sevmeyi öğrettiğin için seviyorum, Seni ne vücut ölçülerin için,ne de zenginliğin için;  Seni sen olduğun için se...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-seviyorum-257-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum Meleğim', 'seni-seviyorum-melegim-abdullah-turgut-7exyp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz olamayacagımı daha iyi anladım artık,

Evimde tek başıma seni düşünürken,

Neredesin benim canım MELEĞİM,

İnan seni o kadar çok arıyorum ki,

Sensizliğinde seni resimlerinle avunuyorum

El diyarlarında sen bensiz,ben sensiz,

Viranelerdeyim sen ğittiğinden beri,

İlk sevdiğimdin sen benim delicesine,

Yürüyorum geceleri ıssız sokaklar arasında tek başıma,

Onsuz nasıl yaparım diyerek kendime,

Resimlerinde buluyordum cevabını bilmediğim soruların,

Ulu orta her yerde seni ararken,

Mekansızdım sen buralardan ğittiğinden beri,

Meleğimdin sen benim,

Ezelden ebede kadar seveceğim tek melek,

Leyleklere soruyordum geleceğin ğünü,

Eskiden böyle değildim,bitanem ben,

Ğeleceğini düşünmeyen,meçhul birisi,

İyiliklerin,sevgin degiştirmişti beni imkansızca,

Mutluluk yolunu gösterdiğin için TEŞEKKÜRLER...', 'Sensiz olamayacagımı daha iyi anladım artık, Evimde tek başıma seni düşünürken, Neredesin benim canım MELEĞİM, İnan seni o kadar çok arıyoru...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-seviyorum-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun', 'olsun-halil-colak-kcyqa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatı ilkbahar svinci içinde olsun.

Açılsın gonca gül gibi ruhu neşeyle dolsun.

Mutluluk dostu,ayrımaz yoldaşı olsun

Her zaman, her işte Allah yardımcısı olsun.

Halil Çolak 1.6.2005', 'Hayatı ilkbahar svinci içinde olsun. Açılsın gonca gül gibi ruhu neşeyle dolsun. Mutluluk dostu,ayrımaz yoldaşı olsun Her zaman, her işte Al...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/olsun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Güzeli', 'sevda-guzeli-abdullah-turgut-349z9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinin içine bakınca bir çiçek bahçesindeydim sanki,

İçinde güllerin,karanfillerin,menekşelerin,sümbüllerin olduğu bir bahçe

Saçlarına bakınca dalganın ne olduğunu; 

İpeğin en iyi kumaş olmadığını öğrendim dokununca saçlarına,

Beni kendine çeken bir şey vardı sanki,

Ne olduğunu bir türlü bulamıyordum.

Ama etrafında öyle bir dönüyordum ki,

Dünya bile böyle dönmüyordu Güneş’in etrafında

Sana bir türlü karşı koymak gelmiyordu içimden,

Nasıl ki yerçekimine karşı koymak imkansızca,

Senin yanında bir çocuktan hiçbir farkım yoktu.

Sen gelince dünyalar benim olur,gidinceyse

Sanki elimden şekerim alınmış olurdu be sevda güzeli

Seni tanıdıkça daha çok sevmeye başladım.

Önceleri bir dostluktu,arkadaşlıktı

Dedim ya sevda güzeli,

Seni tanıdıkça daha çok seviyordum...

Sensiz geçen günlerin ne kadar anlamsız,boş ve saçma olduğunu 

Seni tanıyınca anladım be sevda güzeli,

Seninle her şey o kadar anlamlıydı ki,

Anlamsızlık bile bir başka görünüyordu insana,

Sensiz,uçsuz bucaksız bir karanlığın ortasında,

Yapayalnız,tek başıma buluyordum kendimi 

Denizin ortasında yönünü şaşıran denizcilere; 

Nasıl fenerler imdatlarına yetişiyorsa,

Sende benim fenerimdin be sevda güzeli

Aşk denizinde yönümü şaşırdığım zamanlarda

Bana yol gösteren bir fener,

Bu Mecnun’unkinden farklı değildi,

O da aşkından çöllerde kaybolmuyor muydu be sevda güzeli

Seni tanıdıkça daha çok sevmeye başladım.

Önceleri dostluktu,arkadaşlıktı.

Dedim ya sevda güzeli 

Seni tanıdıkça daha çok seviyordum...

Sesin insana o kadar dinlendirici geliyordu ki,

Bir annenin yavrusuna ninni söylemesinden farksızdı bu

Tüm dertlerini,üzüntülerini 

Bu kahpe dünyanın tüm kahrını,çilesini unutturuyordu insana 

Sana olan sevgim gün geçtikçe daha çok alevleniyordu,

Bu aynı şarabın yıllandıkça tadının artması gibiydi.

Seni bir sigaranın yanması gibi seviyordum,

Usul usul,yavaş yavaş be sevda güzeli,

Sevmenin tadını ala ala,tadına vara vara

Sevdan içimde bir nargile misali

Durmadan kaynayan,fokurdayan bir sevda 

Bende öyle bir bağımlılık yapmıştın ki be sevda güzeli

Seni sevmekten bir türlü alıkoyamıyordum kendimi 

Seni tanıdıkça daha çok seviyordum,

Önceleri bir dostluktu,arkadaşlıktı

Dedim ya be  sevda güzeli

Seni tanıdıkça daha çok seviyordum

Sen benim hayat kaynağım,güneşimsin be sevda güzeli,

Sensiz tüm kaynaklarım kuruyor,yok oluyordu,

Bir buğday tanesi nasıl güneşe,yağmura,kara muhtaçsa

Bende sana işte öyle muhtaçtım be sevda güzeli,

Senin yanında kelebekler kadar özgürdüm,

Çünkü seninle her yerde  ve zamandaydım,

Seninle birlikteyken her şeyi unutuyordum be sevda güzeli,

Varsa yoksa benim için varolan sendin,

Zihnimi öylesine talan etmiştin ki anlatmaya kelimeler yetmezdi,

Yetse bile buna cesaret edemezdi be sevda güzeli,

Seni ölesiye bir an bile olsa unutmamak için; 

Altın harflerle kalbimin ta ortasına kazımıştım,

Seni tanıdıkça daha çok seviyordum,

Önceleri bir dostluktu,arkadaşlıktı,

Dedim ya be sevda güzeli; 

Seni tanıdıkça daha çok seviyordum...

Seni sevmek bir hayal gibi görünüyordu insana,

Sen benim için uçsuz,bucaksız güzellikleri içinde barındıran; 

Onlara hayat kaynağı olan bir hayal dünyasıydı benim için,

Benim için vazgeçilmez bir arzuydun,

Ekmek gibi,su gibiydin benim için be sevda güzeli,

Sensiz kafese kapatılmış bir kuştan hiçbir farkım yoktu,

Ama seninle azad edilmiş bir kölenin duyduğu mutluluğu duyuyordum,

Aşkı gönlümde ölümsüz yapan senin sevdandı,

Aşkın,sevginin böyle olduğunu bilmezdim be sevda güzeli,

Aşk insanın ayaklarını yerden kesermiş meğer,

Bakışların aşkın ateşini bir ok gibi kalbime saplamıştı,

Sana bakınca kendimi bir aşk bahçesinin içinde buluyordum,

İçinde sevgiden başka hiçbir şeyin olmadığı bir aşk bahçesi,

Seni tanıdıkça daha çok seviyordum

Önceleri bir dostluktu,arkadaşlıktı,

Dedim ya be sevda güzeli; 

Seni tanıdıkça daha çok seviyordum...

Kısacası be sevda güzeli,

Senin yanındayken kendimi başka bir alemde buluyordum,

Her zaman olduğu gibi yine seni düşünüyorum,

Seni her düşünüşümde gül dikiyorum,

Kalbimin uçsuz,bucaksız topraklarına be sevda güzeli,

Ne kadar yazarsam yazayım seni,

Hiçbir kelime seni anlatamaz be sevda güzeli,

Yine de bu sevgi korkutuyor beni,

Sana olan tarifi imkansız duygularımı söylediğim zaman,

Seni tamamen kaybetmekten ve bir daha görememekten,

Ama aşıksan cesur olacaksın diyordu bunu yaşayanlar,

Seni tanıdıkça daha seviyordum,

Önceleri bir dostluktu,arkadaşlıktı,

Dedim ya be sevda güzeli; 

Seni tanıdıkça daha çok SEVİYORDUM...', 'Gözlerinin içine bakınca bir çiçek bahçesindeydim sanki, İçinde güllerin,karanfillerin,menekşelerin,sümbüllerin olduğu bir bahçe Saçlarına b...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/sevda-guzeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-abdullah-turgut-07o8p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başı boş dağlarda gezer benim sevdam

Alabildiğine uçsuz bucaksız

Bir o kadarda sınırlı 

Bir kar tanesi kadar saf,

Kömür kadar kara.

Bir su kadar billur,

Ve çamur yığını kadar kirli

Prenses kadar asil

Bir o kadar derbeder', 'Başı boş dağlarda gezer benim sevdam Alabildiğine uçsuz bucaksız Bir o kadarda sınırlı  Bir kar tanesi kadar saf, Kömür kadar kara. Bir su k...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdam-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleğim', 'melegim-abdullah-turgut-zyo2l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdayı aradım yıllarca gizli kalmış kalp köşelerinde,

Erişilmez denilen başı boz dumanlı dağlarda,

Nerede,nasıl ve ne zaman karşılaşacağımı bilmeden,

İsli camlara adını yazacağım meleği bekleyerek,

Sessiz gecelerimde sığınabileceğim,

Ellerini sımsıkı bırakmamacasına tutacağım,

Ve onun ardından delicesine ağlayabileceğim,

İlahi bir tutkuyla sevebileceğim,

Yaşamda,ölümde birlikte olabileceğim,

Onunla her şeyi sonuna kadar paylaşabileceğim,

Ruhsuz bedenime ruh aşılayabilecek,

Umutsuzca çırpınışlarıma çare olabilecek,

Meleği aradım durdum fani dünyada,

Mutluluğu,sevinci tekrar yaşamak isterdim,

Elemi,kederi,acıyı unutabileceğim,

Lalenin, gülün,karanfilin anlamı olmalıydı artık  benim için,

Ezelden ebede kadar birlikte olabileceğim,

Gülmeliydim onunla birlikte her kötü günde

İşte tüm bunlar onunla başladı,onunla da bitecek,

MELEĞİM SENİ SEVİYORUM...', 'Sevdayı aradım yıllarca gizli kalmış kalp köşelerinde, Erişilmez denilen başı boz dumanlı dağlarda, Nerede,nasıl ve ne zaman karşılaşacağımı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/melegim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Bulutu', 'sevgi-bulutu-abdullah-turgut-aqpqo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi bulutunun altındayım sanki; 

Her yanım sırılsıklam.

Sevgi bulutundan yağan sevgi yağmurundan

Senin sevgi suyundan içmek tek varlık amacım

Tek korkum; 

Zamansız esen bir hain rüzgarın,

Seni bilmediğim ıssız diyarlara alıp götürmesi…', 'Sevgi bulutunun altındayım sanki;  Her yanım sırılsıklam. Sevgi bulutundan yağan sevgi yağmurundan Senin sevgi suyundan içmek tek varlık ama...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevgi-bulutu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açık Adres', 'acik-adres-salim-erben-0noq6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eskimeyen bir duygu

Tutup sökesim geldi

Laleyi sümbülü bir de seni

İkide bir öpesim geldi

Kokusunu senden almış

Alıp dağlara çıkasım geldi

Şahidim olsun gök kubbe

Ankara''ya akasım geldi

Gurbet benim neyime 

Ilık ılık gezdin yüreğimde

Ezberim de tek bir kelime

Görünce söyleyesim geldi

Lav oldu kalmadı bende

Ellerle hasret giderme

Niceler göçtü dünyadan

Cennet''im senin olsun 

Elimi tut da girmezsen girme

Mutluluklar seninle geldi

Erişilmez hani derlerdi 

Şakan olsun gül eğlen ki

Esinlendim rıhtımında

Liman olayım sandalına

İnan aşkın son durağında

Sonsuzluğa uçasım geldi

Oldu ya bir dargınlık

Kınama çekilmiyor artık

Al götür gittiğin yere

Koyma dağlarda artık

Olmaz deme sakın

Neyimiz kaldı bu dünyada

Sensiz yaşanan bu aşkın

Elvan çiçeyi koynunda

Koklayıp uçasım geldi

İyi ki kokun sardı dağları

Zalım aradı bir ceylanı

Evlat gözü ile baktım sana

Bırak gururu bir kenara

Elini tutup haykırırcasına

Şahlanıp uçasım geldi', 'Eskimeyen bir duygu Tutup sökesim geldi Laleyi sümbülü bir de seni İkide bir öpesim geldi Kokusunu senden almış Alıp dağlara çıkasım geldi Ş...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/acik-adres-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı', 'sevdali-halil-colak-gan3r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İsmini bilmediğim çiçek

Elinde sigaran

Yanmaya sevdalı

Bu gördüğün insan

Kalbimi hoş eden

Yeşil gözlerine sevdalı

Bense seninle

Yolun başında

Seninle olmak için

Engelleri aşmaya sevdalı

Halil çolak 31.01.2005', 'İsmini bilmediğim çiçek Elinde sigaran Yanmaya sevdalı Bu gördüğün insan Kalbimi hoş eden Yeşil gözlerine sevdalı Bense seninle Yolun başınd...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdali-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-mehmet-hulusi-reyhan-r3cmf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırpmadan gözümü maziye daldım

Erişmeyin dostlar doluyum bugün

Zaten unutuldum, ikmale kaldım

imtihan yaklaştı zorluyum bugün

Açtım sayfa sayfa hatıralar not

Nerde o genclikten kalan dibizot

Birde siz yakmayın ben zaten yandım

Küle döneceğim, korluyum bugün

Kurumuş güllerim, dikeni kalmış

Gözümün az görür ikeni kalmış

Uykudan da zaten çok geç uyandım

Deymeyin adostlar doluyum bugün

Dumanım karışmış kül ile benim

Gümanım yarışmış kul ile benim

İniş yokuş derken yara dayandım

Urganım karışık, zorluyum bugün

Merdiven tükendi, elde son kanca

Telef oldu gitti yıllarım onca

Simsiyah saçlarla aka boyandım

Aksın gözyaşlarım, doluyum bugün

Aradım dost eli, ben bana kaldım

Takdiri, mühleti mevlaya saldım

Hakkın kapusunda hakka dayandım

Doluyum dostlarım doluyum bugün

Esmer, kumral; yeşil, sarı velhasıl

Seçer deli gönül simsiyah nasıl

Her gülün rengine daldım boyandım

Kapadım defteri, zorluyum bugün

Terledim şu hayat pişirdi beni

İçtiğim su bayat şişirdi beni

Kim aradı sordu, kime ayandım

Ölüyüm dostlarım, ölüyüm bugün

15/01/2000 (Pendik/İST)', 'Kırpmadan gözümü maziye daldım Erişmeyin dostlar doluyum bugün Zaten unutuldum, ikmale kaldım imtihan yaklaştı zorluyum bugün Açtım sayfa sa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hulusi Reyhan']::text[], 8.5, '{"poet":"Mehmet Hulusi Reyhan","poet_slug":"mehmet-hulusi-reyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bugun-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırla beni', 'hatirla-beni-tuncay-akdeniz-vjlll', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey sevdiğim ayrı kalırsam senden

Her akşam her gece hatırla beni

Gönül usanır mı sevdiği candan

Bir ömür boyunca hatırla beni

Ömür vefa etmez tükenir hayat

Ben seni sevmiştim aşkına inat

Gülistan bahçesi güzel tabiat

Her çiçek solunca hatırla beni

Ömrüme renk kattın sevgi tadıyla

Sevgini tatmışım gönül canıyla

Gül solar sevmedim gülün adıyla

Goncalar açınca hatırla beni

Kul Tuncay  sevgimiz dengi dengine

Ayrılık olmasa doymam sevgine

Bir gün kalır isen kendi kendine

Her kapı çalınca hatırla beni', 'Ey sevdiğim ayrı kalırsam senden Her akşam her gece hatırla beni Gönül usanır mı sevdiği candan Bir ömür boyunca hatırla beni Ömür vefa etme...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatirla-beni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayâllerim Can Verdi', 'hay-llerim-can-verdi-muammer-baydere-8dngy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Özlemlerim Çıldırdı”, akli dengem yerinde

Aşkım rahata erdi, ersin başım sağ olsun

“Umutlarım Komada” yeri hazır derinde

Hayallerim can verdi, versin başım sağ olsun

Ne söylenir kafamı duvarlara vurduğum

Ne bir kere görülür boynu bükük durduğum

Gece gündüz gördüğüm, her köşede kurduğum

Hayallerim can verdi, versin başım sağ olsun

Bir gün neyse bir ömür ağlayana şaşarım

“Bir yudum sevgi”yi de paylaşmaktır başarım

Anılarla avunur, gerçeklerle yaşarım

Hayallerim can verdi, versin başım sağ olsun

Yine bahar gelecek, çiçekler serilecek

Menekşe, gül, papatya koklanıp derilecek

Madem ki yaşamıyor, toprağa verilecek

Hayallerim can verdi, versin başım sağ olsun', '“Özlemlerim Çıldırdı”, akli dengem yerinde Aşkım rahata erdi, ersin başım sağ olsun “Umutlarım Komada” yeri hazır derinde Hayallerim can ver...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayallerim-can-verdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-abdullah-turgut-q3g23', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmek; 

Bembeyaz bir kar tanesinin,

Karanlığı yarıp aydınlatması gibidir.

Sevgi,insanın kapkara dünyasını,

Bir mum alevi gibi aydınlatır.

Sende bir mum alevi,kardın benim için,

Benim kapkara dünyamda,

Senden önce sanki yaşamıyordum,

Yürüyen bir naaştım sanki,

Seni tanımamla birlikte; 

Hayat daha zevkli,daha renkli gelmeye başlamıştı bana,

Senden önce hayat diye bir şey yoktu benim için,

Ama senden sonra; 

İşte ne olduysa bundan sonra oldu dünyamda,

Benim için,

Artık hayatı bütün güzellikleriyle yaşamak,

Yaşamak istiyordum çılgıncasına,

Sevmenin,sevilmenin ne demek oldugunu,

Sevginin değerini,aşkın kutsallığını; 

Öğrenmeye başlamıştım seninle birlikte,

Yaşamanın ne kadar degerli oldugunu,

Seninle birlikteyken anladım...', 'Sevmek;  Bembeyaz bir kar tanesinin, Karanlığı yarıp aydınlatması gibidir. Sevgi,insanın kapkara dünyasını, Bir mum alevi gibi aydınlatır. S...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevmek-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızma Sakın Gülmira', 'kizma-sakin-gulmira-muammer-baydere-na4uk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dinlemeyi istersen ya şimdi anlatayım

Ya buraya gelirsen dertleşiriz bir ara

Moralim fena değil fakat biraz hastayım

Sağlığımı küstürdüm, kızma sakın Gülmira

Seni öyle özledim, görmeyince ağladım

Sana kusur bulmadım, sırf kadere bağladım

Ne bir şeyle avundum, ne teselli sağladım

Kendime kan kusturdum, kızma sakın Gülmira

Bugünü unutmadım düşünürken yarını

Umutlarla dağıttım gönlümün efkarını

Senden gelsin diyerek mutluluk rüzgarını

Sana doğru estirdim, kızma sakın Gülmira

Biliyorum, aslında sen de gelmek istersin

Gözlerime bakarak sen de gülmek istersin

Ölmem dışında, en son bunu bilmek istersin

Sakalımı kestirdim, kızma sakın Gülmira', 'Dinlemeyi istersen ya şimdi anlatayım Ya buraya gelirsen dertleşiriz bir ara Moralim fena değil fakat biraz hastayım Sağlığımı küstürdüm, kı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kizma-sakin-gulmira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik', 'gelincik-muammer-baydere-lbwz6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kader değil de ne böyle bir sevda

Aklımı başımdan aldı gelincik

Sevgime eşlik et, maziye veda

Gözlerim yollarda kaldı gelincik

Mutluluk ihtiyaç bir nefes gibi

İnan ki bu şehir bir kafes gibi

Gelmeni beklerken prenses gibi

Gözlerim yollarda kaldı gelincik

Sen bana uzaksın, ruhuma yakın

Hasretin başlattı yoğun bir akın

Elini çabuk tut gecikme sakın

Gözlerim yollarda kaldı gelincik

Özledim deyip de ağlama gene

İnşallah yüzümüz güler bu sene

Haziran olmazsa temmuzu dene

Gözlerim yollarda kaldı gelincik

Aslında bir şekil aramam da pek

Mavi bir gömlek giy, siyah bir etek

İstersen çocuk de, istersen bebek

Gözlerim yollarda kaldı gelincik', 'Kader değil de ne böyle bir sevda Aklımı başımdan aldı gelincik Sevgime eşlik et, maziye veda Gözlerim yollarda kaldı gelincik Mutluluk ihti...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelincik-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı', 'sizi-abdullah-turgut-s0jxf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık gözlerinin içine bakamıyorum,

Daha doğrusu korkuyorum bakmaya,

İçine baktığımda daha çok bağlanmaktan,

Bağlanıp ta kaybetmekten,

Seni bir daha bulamamak,

Bu duygu ölümden de beterdir seven için,

Tamamen kaybetmektense uzaktan sevmek,

Tek çözüm gibi görünüyor ama,

Ama bu daha da kötü,

Bir kanser gibi içten içe yer seveni, 

Darmadağın,virane,perişan eder,

Dışardan hiç belli olmaz,

Ne durumda olduğun,nasıl göründüğün,

İçinde sürekli,bitmek tükenmek bilmeyen

Bir sızı daima seninle olur

Hiçbir zaman içinden çıkmaz,

İçin için kemirir seni,

Keşke sevdiğimi söyleseydim dersin,

Dersin demesine ama her seferine içinde kalır,

Günden güne eriyip gidersin,

Aklın yapma der,kalbin ise yap

Sonu olmayan bir uçurumun ortasında bulursun kendini,

Bir süre sonra ikisi birbirine karışır,

İşte o zaman Mecnun’dan farkın kalmaz...', 'Artık gözlerinin içine bakamıyorum, Daha doğrusu korkuyorum bakmaya, İçine baktığımda daha çok bağlanmaktan, Bağlanıp ta kaybetmekten, Seni ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sizi-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-abdullah-turgut-3r5of', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gaipten sesler duyuyorum artık

Sevdalar üzerine; 

Soruyorum handan gelip geçenlere,

Sevda hakkında; 

Hiç kimse bir şey diyemiyor

Sevda hakkında.

Söyleyenlerde kararsız,umutsuz

Kimisi çıra gibi yanmaktır,diyor

Kimisiyse kör olmaktır,der

Bir başkası kanatsız sonsuz,

Gökyüzünde alabildiğine uçmaktır,diyor

Başka birisi ise uğrunu ölünecek bir mabet gibi görür sevdayı

“Hiçbir şeydir” diyenlerde var sevda hakkında

Bence SU içmek gibidir sevda; 

Bir seferde,soluksuz içmek

Zorlamaya gelmez,

Zorlarsan bıkarsın,rahatsız eder insanı

Aşırıya kaçarsan şişirir.

En güzelidir tek seferde kana kana içmek

Çölün yakıcı sıcağının altında değeri neyse,

Bir bardak suyun.

Dünya çölünde de bir yudum SEVDA aynı şeydir…', 'Gaipten sesler duyuyorum artık Sevdalar üzerine;  Soruyorum handan gelip geçenlere, Sevda hakkında;  Hiç kimse bir şey diyemiyor Sevda hakkı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/su-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarifsiz Melek', 'tarifsiz-melek-abdullah-turgut-6v1eh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni ne sıfatlar anlatabilir,ne de diğerleri

Bu dünyada hiçbir kelimenin gücü,

Seni anlatmaya yetmez,

Sen sadece yaşanırsın,anlatılamazsın,

Seni yaşamakta imkansız ama,

Elden bir şey gelmiyor işte,

Bir hava,su neyse,

Sende o’sun benim için,

Bugüne kadar kim yapmış ki

Sevginin ve sevgilinin tarifini,

Yapanlarda yaptıklarını zannederler,

Ama nereden bilsinler; 

Tarifi olmayan bir şeyi,

Tarif ettiklerini,

Bu aynı meleği tarif etmek gibi,

Kimse melek hakkında bir şey diyemez,

Ama gel gör ki onu tarif ederler,

Bence melek neyse sevgili de o’dur 

Sevene göre,

Meleği tarif etmek onun yaratılışına; 

Saygısızlık etmek değil midir? 

Tarif etmek yerine onu yaşamak; 

En güzelidir...', 'Seni ne sıfatlar anlatabilir,ne de diğerleri Bu dünyada hiçbir kelimenin gücü, Seni anlatmaya yetmez, Sen sadece yaşanırsın,anlatılamazsın, ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tarifsiz-melek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Malum Yerden Ayrılmak', 'malum-yerden-ayrilmak-muammer-baydere-9qqpk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutlu olmak ne demek, meğer sevmek her şeymiş

Boynumun borcu artık cümle şerden ayrılmak

Uyanıkken uykuya dalmak gibi bir şeymiş

Ölümden de betermiş, malum yerden ayrılmak

Düşündükçe yolları bir sigara yakarak

Otobüse binerken dönüp dönüp bakarak

Yüreğimi, aklımı ardımda bırakarak

Ölümden de betermiş, malum yerden ayrılmak

Birkaç gün geçirdim de bir kere sarılmadım

Şansa, kadere küstüm kimseye darılmadım

Çok yaralar aldım da böylesi vurulmadım

Ölümden de betermiş, malum yerden ayrılmak

Hasretin sancısı var, çektiğim her ağrıda

Ayrılık ateş gibi yakıyor bu bağrı da

Gerçi nefes aldığım, yaşadığım doğru da

Ölümden de betermiş, malum yerden ayrılmak', 'Mutlu olmak ne demek, meğer sevmek her şeymiş Boynumun borcu artık cümle şerden ayrılmak Uyanıkken uykuya dalmak gibi bir şeymiş Ölümden de ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/malum-yerden-ayrilmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Meleğim', 'tatli-melegim-abdullah-turgut-ihaiv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her insanın mutlaka bir meleği vardır; 

Ama iyi,ama kötü

İşte sende benim meleğimsin.

İyi kalbli,şefkatli,beni koruyan bir melek

Öyle bir meleksin ki benim için

Kendimi bir türlü alamıyorum senden

Varlığını her zaman yanımda hissetmek istiyorum

Seni görmesem de,duymasam da

Beni hataya düşmekten,yanılmaktan kurtaran,

Doğruluğu,sevgiyi bulmamı sağlayan

Bir meleksin SEN…', 'Her insanın mutlaka bir meleği vardır;  Ama iyi,ama kötü İşte sende benim meleğimsin. İyi kalbli,şefkatli,beni koruyan bir melek Öyle bir me...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tatli-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-abdullah-turgut-8gwf2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamanın anlamını seninle buldum,

Gözlerin bana bir rengin insanı,

Ne kadar etkileyebileceğini gösterdi,

Artık sensiz yapamayacağımı anlamamı sağladı,

Onlar konuşmadan sevdiğini söylemenin,

Tek yolu,tek kapısıydı sanki,

Ve saçların bir ok gibi kalbime saplandı,

Tüm vücudum kanlar içinde kaldı,

Akan her zerre kanda sen vardın benim için,

Sana olan sevgim; 

Gün geçtikçe daha da kuvvetleniyor,

Varsa yoksa sendin benim için

Yediğim ekmekte,içtiğim suda,

Çektiğim sigarada ve aldığım her nefeste

Sen vardın benim için,

Rüyalarımda bile sen vardın artık,

Rakamlarda,kelimelerde bile seni görüyordum,

Düşün artık ne halde olduğumu,

Her şeyde,her yerde  sen vardın benim için,

Her yere adını yazıyor,resmini çiziyordum,

Suya,toprağa,havaya ve kalbime

Asla silinmeyecek bir şekilde,

Silindiğinde ise ben olmayacaktım...', 'Yaşamanın anlamını seninle buldum, Gözlerin bana bir rengin insanı, Ne kadar etkileyebileceğini gösterdi, Artık sensiz yapamayacağımı anlama...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turgut']::text[], 8.5, '{"poet":"Abdullah Turgut","poet_slug":"abdullah-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasamak-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Dursun Nehirler', 'selam-dursun-nehirler-muammer-baydere-iosqh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevenler de biliyor

Yalan aşkı zehirler

Göz yaşlarım geliyor

Selam dursun nehirler

Ne olursun artık gel

Seven tanımaz engel

Görülmedi böyle sel

Selam dursun nehirler

Düştü gönlüm kışına

Kaldı yalnız başına

Gözlerimin yaşına

Selam dursun nehirler

Ne gerek var ezaya

Verdiğin bu cezaya

Hepsi geçsin hizaya

Selam dursun nehirler', 'Sevenler de biliyor Yalan aşkı zehirler Göz yaşlarım geliyor Selam dursun nehirler Ne olursun artık gel Seven tanımaz engel Görülmedi böyle ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/selam-dursun-nehirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sözümüz', 'son-sozumuz-muammer-baydere-2k699', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir İstanbul sonrası bana veda ederken

İkimiz de susmuştuk gözlerimiz dolmuştu

Son defa sarılmıştık sen buradan giderken

Ve son sözümüz “Seni seviyorum” olmuştu

Firari arzuların suç ortağı tasaydı 

Ayrılmak bir ölümdü fakat sanki yasaydı

Az ama öz konuştuk zamanımız kısaydı

Ve son sözümüz “Seni seviyorum” olmuştu

Sular seller faydasız düştüğümüz ateşe

“Acaba”lar “keşke”ler sıralandı peş peşe

yolculuğa çıkmıştık gerçeklerden bir düşe

Ve son sözümüz “Seni seviyorum” olmuştu

Bağrımıza taş basıp içten içe gerildik

Ne dimdik ayaktaydık ne de yere serildik

Allak-bullak bir halde,öldük öldük dirildik

Ve son sözümüz “Seni seviyorum” olmuştu', 'Bir İstanbul sonrası bana veda ederken İkimiz de susmuştuk gözlerimiz dolmuştu Son defa sarılmıştık sen buradan giderken Ve son sözümüz “Sen...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-sozumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sumru', 'sumru-muammer-baydere-99wsg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şairin kalbini kırmak istersen

Sussan da kırılır anında Sumru

“Bu nasıl bir şiir,nasıl his” dersen

Kalemin büyüsü şanında Sumru

Yüreğin elverse beni ihmale

Bırakmam sevgiden seni ikmale

Elbette açığım her ihtimale

Her zaman sağ olsun canın da Sumru

Bendeki bu sabır dağlar kadarsa

Hoş görüm üşümez kar da yağarsa

Nerede iyilik güzellik varsa

Yer alsın hep senin yanında Sumru

Sesinden yansıyan samimiyetti

Şahsıma duyduğun iyi niyetti

Mutluluk duymama bu bile yetti

Bir dosttur namın da şanın da Sumru', 'Şairin kalbini kırmak istersen Sussan da kırılır anında Sumru “Bu nasıl bir şiir,nasıl his” dersen Kalemin büyüsü şanında Sumru Yüreğin elve...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sumru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sabah', 'bu-sabah-adulera-ayza-o7eud', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sabah erken kalkmam lazım

Her zaman ki gibi geç değil

Kravatımı yolda bağlayacağım

Her zamanki gibi evde değil

Bu sabah farklı olmam lazım

Bu sefer başka her zamanki gibi 

Sana söz verdiğim ve tutamadığım

Sözler gibi değil

Bu sabah farklı olacağım bunu bil

Bu sabah seni unutacağım 

Kendimi değil

İster bana kız ister nefret et

Ama şunu bil ki

Bu sabah farklı olacağım

Yoksa öldürecek beni bu dert

Severken iyi idi şimdi ise dert

Dediğini duyar gibiyim

Ben bu sabah sıradan biriyim

Ben değiştim

Bildiğin gibi değil.', 'Bu sabah erken kalkmam lazım Her zaman ki gibi geç değil Kravatımı yolda bağlayacağım Her zamanki gibi evde değil Bu sabah farklı olmam lazı...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-sabah-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanarım', 'yanarim-muammer-baydere-vtxb8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni bir dinlersen iki lafım var

Hep seni düşünür anarım Sevda

Hislerim hakkında itirafım var

Sırf senin uğrunda yanarım Sevda

Kimseyle işim yok yarıştan yana

Niyetim her zaman barıştan yana

Seninle vuslata barıştan yana

Sırf senin uğrunda yanarım Sevda

Nazından sıkılır bıkarım sanma

Her şeyi bırakır çıkarım sanma

Bir söze dünyayı yıkarım amma

Sırf senin uğrunda yanarım Sevda', 'Beni bir dinlersen iki lafım var Hep seni düşünür anarım Sevda Hislerim hakkında itirafım var Sırf senin uğrunda yanarım Sevda Kimseyle işim...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanarim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok mu Bir Yolu..?', 'yok-mu-bir-yolu-muammer-baydere-1s73w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yazı yazılmış bizden habersiz 

İçinde ıstırap göz yaşı dolu 

Allah''ım sevenler öyle çaresiz 

Kaderi silmenin yok mu bir yolu 

Ya benim gönlümü al ki sevmesin 

Ya benim aklımı al ki ermesin 

Ya canımı al ki acı çekmesin 

Kaderi silmenin yok mu bir yolu 

Bir yanda sevdiğim perişan ağlar

Bir yanda kalbimiz karalar bağlar

Dostlarım dedi ki ''Allah''a yalvar''

Kaderi silmenin yok mu bir yolu

Hepimiz kulunuz ayrılık niye

Yaratan tek sensin gayrılık niye

İnsanlar bölünmüş sanki ikiye

Kaderi silmenin yok mu bir yolu', 'Bir yazı yazılmış bizden habersiz  İçinde ıstırap göz yaşı dolu  Allah''ım sevenler öyle çaresiz  Kaderi silmenin yok mu bir yolu  Ya benim g...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yok-mu-bir-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Göre Değilsin', 'bana-gore-degilsin-muammer-baydere-98isz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin burnun havalı

Aşka nasıl eğilsin

Bırak artık mavalı

Bana göre değilsin

Otobüse binmezsin

Dolmuşu beğenmezsin

Taksilerden inmezsin

Bana göre değilsin

Tek bildiğin her gece

Dans müzik ve eğlence

Anladım ki böylece

Bana göre değilsin

Belamısın başıma

Ekmeğime aşıma

Çıkıp durma karşıma

Bana göre değilsin.', 'Senin burnun havalı Aşka nasıl eğilsin Bırak artık mavalı Bana göre değilsin Otobüse binmezsin Dolmuşu beğenmezsin Taksilerden inmezsin Bana...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-gore-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökler şahit', 'gokler-sahit-i-shak-ozlu-phkc0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kahırla yaşarken baharı buldum,

Hayal etmezdim kollarıma aldım.

Deniz şahit saçlarında ellerim,

Kavuştum derken yüzün görmez oldum.

Pamuk ellerine yüzümü sürdüm,

Kömür gözlerini yakından gördüm.

Gökler şahit kokladım saçlarını,

Buldum derken bir ömür ayrı düştüm.

Kayboldu evren gülen gözlerinde,

Şifa buldu yüreğim sözlerinde,

Saçların yorğan başım dizlerinde,

Biz ayrılmayız derken hasret kaldım.

Deli Poyraz yeli zamansız çıktı,

Esip başıma hayalimi yıktı.

Yetiştim derken mutluluk anına,

Küllenmiş gönlümde volkanlar yaktı.

Bilmedim,ayrılığın kavuşma olduğunu,

Anlamadım,Rüyanın zamansız dolduğunu.

Yanarken kavuşma busesinin ateşinde,

Yoramadım,veda busesinin konduğunu.', 'Kahırla yaşarken baharı buldum, Hayal etmezdim kollarıma aldım. Deniz şahit saçlarında ellerim, Kavuştum derken yüzün görmez oldum. Pamuk el...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gokler-sahit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aphroherm', 'aphroherm-akin-akca-r25zl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O açtı, çiçek soldu, arada el fal baktı. 

O roman’a yenilmemiş, yazarlığına serilmiş; 

zamanın doğasını, doğasını onun andı! 

Genişliyor küre hacimsel, kütle; 

öz, korunmaz denemez! 

Işık burada değil, o çok güçlü, ışık uzakta; 

varmak için yola çıkmış, belli … 

Işık içimizde, içimiz üzüntüde, ışık ötelerde; 

oradan yakıp, üzüntülerin her zerresine … 

İlerleyen duvarlar perçemi’ni sayıyor adın, 

mayın mı döşeliydi, ama parlamıyor! 

Dinlenince ruh mantık en güzel yalancı 1 

İniyor kadın, inerken çıkıyor kadın; 

ovaları, yaylaları, dağı ve ulaşıyor tepelere! ... 

Erkek tırnanışta, bir sürü şey baş ucunda; 

bir sürü hata, sürüyle uğraşı, düzeltme. 

Ama artık bir noktada buluşacaktır, buluşuyor 

bunlardan ikisi de, her iki cins de. 

Ve çünkü doldurt boşalt kadın, 

yüklenmiş cefa, mahmur gözleri, sıvanmış 

duvara, sanki çıkarken iniyor o da. 

Ama zaten öyle değil miydi, 

çıkarken inen erkek değil miydi? 

Doğdu kadın sarsmak için derinden; 

bir kere vur ve bitir, böylesi güzeldir. 

Ölümün barındığı hayatta yalandır gerisi, 

ama çaba da alır, kendisini yalanlar.. 

bir ölçüde, ve gelir erkek derken 

..düzeltmek için, doğumu yol alışlarda: 

tutar, kavrar onu, doğmak için, defalarca! 

Buraya baktığında, doğan değildir o; 

Kadın’ı doğmak amaçlı doğuran 

bir mecaz-ı devriksi’den yapısal cümle; 

düren tabakalar’ı, anlamlı çıkaran tektonik; 

sürebilen karartıda, mutlak biten ışıltıda. 2 

Karanlığın içinde ışığı düzmeye çalışıyor 

Hermafrodit, belki beyaz kirpikli. 

harmanlıyor kromozomu çekirdeğindeki 

içindeki hücrenin, ki olası mı değiştirmek? 

Ameliyatla olabilir kadın, üreyen karanlık; 

ama doğar ikiz, çift ölür, geleceğe sorumludur. 

çift’teki bir tek’i fakat, erkek görüyor; 

yine de “gören” o, “bilen” başkası sanki: 

uğraştıkça bata çıka, duymayan bilendir, hakiki. 

İşte yine o hermafrodit, Bodrum’un su kaynağı; 

çok hassas bir denge, küresel ama varsağı. 

Bak Aphrodite, zeki çıktı, çevik, bu erkek de; 

tabiatın yeşil kanatları onun elindeki 

yedi zümrütte, kendini atması için 

kesilen uzvuyla Uranos’un dalgalara, 

ki cinssiz’den çıkacak o köpükler oluşturur 

seni tekrar ve tekrar, ve eşeysiz’in kendini de! 

Cinssiz ki, aslında Kronos olmalıydı kendisi, 

ölmüştü o ama zaman devam ediyor; 

Uranüs ve Neptun, uzaklardan hesap soruyor 

Merkür’e ve hatta Güneş’e, neydi bu 

(bir rüzgar Pegasus’u sırtlanmış gidiyor! 

Orpheus sallandırılıyor kadın türküsü ezgisinde; 

göndere çektiler aşkı göndere, darağacında! 

Ah, idare eden ışın topu gündüzü! !)

ötelerdeki, Hermafrodit diyorsa bunu 

ki o yaşıyor ışın der top’a yakın, o halde 

Neptün nasıl hesap soruyor: değil ötede? 

(Kron, evet, “os” ilaveten “Uran” gibi; 

bu sihirden belki de barbar Crom ünlenebildi!)

Ölmüştü Kron, ama zaman devam ediyor! 

Cinssiz ki aslında Kronos olmalıydı kendisi, 

Herma kendiyle tutuşuyor, tek’ten gelen iki’si. 

Ölmüştü zaman, o devam ediyor … 

Akıyor kar(e)  anlık, şüphesiz kendini görmeden; 

ışıldatarak her tarafı, daha yoracak zamanı … 

Beyazıyla, siyahıyla hatta şeytani kızıllığında – 

kaya duvarlarında gürül, yaşanası su sesi … 

Soykırımsal şekil verme; anca yağa, enzime, 

şekere, iyi huycul bakteri ve şenlik besinine … 

Aldın seni sende, aldın seni ancak iletildiğinde! 

Değer mi yaş dökmeye, hayat kısa diye değil; 

biz isterken bunu, aldın süphesiz seni sende! 

Mutlu etmek için yaşanan anı, yoksa 

ölüm olduğundan değil, değil bulunmayandan. 

Makbule geçti, ölmemiş bazı doğmayanlar’dan; 

ithaf edilmeye, ağrısız ama gayret doluluğa. 

- Hayat bu Hermafrodit, çiftsi, sensin frijit. 

Yaban kütledeki göze tanıdık selülit. 

- 

İnen kadın, çıkan erkek benzetmesi faithless’in “why go” adlı şarkı klibinden ilham 

kısaca: 

Hermes: efsaneye göre 7 zümrüt levhası olduğu bazı gizli bilgilerinde bu levhalar üzerine yazıldığı rivayet edilir, 

musa peygamberin ünlü yasalar levhasının gerçekte bu efsaneden araklandığıda konuşulur durur. mitolojide tanrıların habercisi olan seyahat ve ilim tanrısıdır.çok zıpır,aynı zamanda çok hindir.oldukça zeki ve çevik olduğu anlaşılır mitlerden. 

Aphrodite: yaradılışı ilyadaya göre şöyledir 

zeusun babası kronosa ait denize düşen kopmuş erkeklik organının saçtığı köpüklerden doğmuştur. 

Herma: mutant gibi bişi. hem erkek, hem dişi. genellikle hormon desteklemesi veya plastik cerrahi ile bir tür''e yakın olmayı seçmek zorunda bırakılır kişi, hatta genellikle kadın olmayı seçerler, lakin hücre çekirdeğindeki kromozomu değiştirmek mümkün değildir. hermafrodit doğup, hermafrodit ölür. 

hermes ile afrodit''in ogullaridir mitolojide. yanilmiyosam bi kiz buna a$ik olur ama o ilgilenmez kizda tanrilardan birine yalvarir sonra gider onu o kadar fazla slklp kucaklarki sonunca vucudlari ayrilmayacak $ekilde birle$ir. süngerler gibi bi çok omurgasız canlıda doğal olarak bulunan kendin pişir kendin ye tarzı çoğu zaman kendi kendine üreme yeteneğine sahip çift eşeyli bireylere verilen ad. mitolojide bahsi gecen yer Bodrum da bir su kaynagidir ayni zamanda. Zeki Müren’in yakınlarında konuşlandığı … 

eksisozluk 

1 haz ‘05', 'O açtı, çiçek soldu, arada el fal baktı.  O roman’a yenilmemiş, yazarlığına serilmiş;  zamanın doğasını, doğasını onun andı!  Genişliyor kür...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/aphroherm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlar Yağıyor Sevdamın Üzerine', 'yagmurlar-yagiyor-sevdamin-uzerine-hasan-can-4uw1b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni hiç unutamadım,

Kalbimden söküp atamadım.

İçimde hep kalacağını bilmeliydin,

Yalnızlığına ağlarken düşünmeliydin.

Ah yağmurlar yağıyor sevadmın üzerine,

Ah Yalnızlık uçuşuyor kanat kanat penceremde.

Sende biraz yürek olsaydı,

Gözlerin gözlerimden anlasaydı,

Kolların bir kez beni sarsaydı,

İçinde biraz duygu olsaydı,

Sende beni severdin.', 'Seni hiç unutamadım, Kalbimden söküp atamadım. İçimde hep kalacağını bilmeliydin, Yalnızlığına ağlarken düşünmeliydin. Ah yağmurlar yağıyor ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yagmurlar-yagiyor-sevdamin-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlilik', 'gizlilik-suna-aras-287yn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir resmimiz olsun isterdim seninle

Yasaklara oynuyoruz mümkün değil

Gel

Ellerimizin resmini çektirelim biz de

Koyalım en güzel köşeye evimizde

Herkesin gözleri önünde

Sevişip dursunlar çerçevede.', 'Bir resmimiz olsun isterdim seninle Yasaklara oynuyoruz mümkün değil Gel Ellerimizin resmini çektirelim biz de Koyalım en güzel köşeye evimi...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gizlilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sular Basmadan', 'sular-basmadan-funda-soylemez-1dji8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzünler akbaba, dolanıyor başımda

Bir çölde, bir damla su arar gibiyim

Çömeldim kaldım bir serap başına

Umutlarımı olmazlarda arar gibiyim

Gövdemde bir ağırlık ki kantar tanımaz

Bu bedene nasıl sığmış bilinmez

İçim karanlık baksan görünmez

Hayatı geceden izler gibiyim.

Açamadım içimi havasız kaldı

Bir pencerem gözlerim vardı

Onu da yağmurlar esir aldı

Ben “ben”den çoktan geçmiş gibiyim

Ne bu halim, tutmaz mı kolum kanadım

Efkarları elimle besler gibiyim

Madem bu yollarda bir çukura rastladım,

Sular basmadan yükseklere erişmeliyim.', 'Hüzünler akbaba, dolanıyor başımda Bir çölde, bir damla su arar gibiyim Çömeldim kaldım bir serap başına Umutlarımı olmazlarda arar gibiyim ...', ARRAY['Türk Edebiyatı','Şiir','Funda Söylemez']::text[], 8.5, '{"poet":"Funda Söylemez","poet_slug":"funda-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sular-basmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-gulseren-onay-65vn5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Davetim var bu gece tek kisilik

Vivaldi’nin dört mevsimi eşliğinde,

Sabaha kadar sürsün istiyorum....

Ayak parmaklarımdan,

Saçımın teline kadar

Soguk ama arzulu 

Seni hissetmek istiyorum...

Agır agır çık yukarılara bedenimde 

Her santimetre karesinde 

Yeni bir arzu yarat 

Hiç tatmadığım,

Yeni yepyeni duyguları yaşat bana,

Koca gözlü soguk ölüm...

Yüreğime geldiginde acele etmelisin,

Yaşanmamış ne aşklar vardır orda..

Durma yürü...

Sen sadece seni tattır....

Dudaklarım nemlensin soguk dokunuşlarla...

Sevgi dolu sıcak bakışlarla

Bırak gözlerimi

Seviyormuş yaşamı,desin görenler...

Oyalanma beyin  kıvrımlarımda, 

Tüm anılari sil yok et

Hiç var olmamışcasına...

Bir tanesi kalsın 

Bir ilk bahar sabahı boğazda..

Hadi artık sabah oldu son tangonu tamamla,

Vivaldide sustu daha ne bekliyorsun....

Çalacak baska kapılarında olmalı

Hadi git git bakma ardına,

Çok genç değilim acımasın  yüregin 

Koca gözlü soguk ölüm.......

GÜLSEREN ONAY', 'Davetim var bu gece tek kisilik Vivaldi’nin dört mevsimi eşliğinde, Sabaha kadar sürsün istiyorum.... Ayak parmaklarımdan, Saçımın teline ka...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/davet-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyamasın Sen Bana', 'doyamasin-sen-bana-yusuf-ter-vt4v8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aç gözlerin bir cihana

Doyamazsın sevsen insana

Ben kurban olayım sana

Şu hayata gülerek bak

Kul olmadan şu yollara

gel sarıl  seven kollara

yüzün dönsün o güllere

Şu hayata gülerek bak

Gülmek ister benim yüzüm

Beni yakar senin közün

Her  şiirde dizin dizin

Şu hayata gülerek bak

Gerçek bu hayal yaşama

Benliğinden uzaklaşma

Benlik zaafına düşme

Şu hayata gülerek bak

Gözleri sel akışlımsın

İnce zarif  nakışlımsın

Benim ahu bakışlımsın

Şu hayata gülerek bak

Yusuf Ter 31.05.05

Saat 22:25 İsviçre', 'Aç gözlerin bir cihana Doyamazsın sevsen insana Ben kurban olayım sana Şu hayata gülerek bak Kul olmadan şu yollara gel sarıl  seven kollara...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/doyamasin-sen-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı şarkı...', 'ayni-sarki-sila-nur-koken-bd1x8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben hep aynı şarkıda yazdım

tüm şiirleri

hep o kadının sesi vardı

kulaklarımda

içim acığında

ya da

içim acıdığında

hep aynı sesi duydum ben

kendi içimde

çınladı

kendi sesim

bir şarkı gibi

bir çığlık gibi

yükselerek zaman zaman

zaman zaman

mırıltı

zaman zaman

es...

sussss

geçecek

sussss

güleceksin

sussss

ağlamak yok

sussss

susss

zaman....

(2 Haziran 2005)', 'Ben hep aynı şarkıda yazdım tüm şiirleri hep o kadının sesi vardı kulaklarımda içim acığında ya da içim acıdığında hep aynı sesi duydum ben ...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ayni-sarki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemiksiz dil.', 'kemiksiz-dil-i-shak-ozlu-o3l7l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatın anlamı,sevdim sevildim,

Sevdasına öldüm,meşke dirildim.

Dosta buyur dedim,yedim bitirdim,

Dostum bildiklerim,bakıyor şimdi.

Gençlik başımızda,deli esiyor,

Gönül ferman bilmez,güller geziyor.

Manevi duyğular,çökmüş eziyor,

Durmaz gözyaşlarım,akıyor şimdi.

Akıl verdim bolca,duydum uymadım.

Erenlerden alıp,yedek koymadım.

Manalı söz duydum,anlam yormadım,

Susmaz kemiksiz dil,satıyor şimdi.

Not:Şiir Perisi Grubunun Şimdi isimli çalışması için hazırlanmıştır.', 'Hayatın anlamı,sevdim sevildim, Sevdasına öldüm,meşke dirildim. Dosta buyur dedim,yedim bitirdim, Dostum bildiklerim,bakıyor şimdi. Gençlik ...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kemiksiz-dil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ye Aşı Kıl Beşi, İsa''nın Fransız''ı Akıllı mı Efendiden', 'ye-asi-kil-besi-i-sa-nin-fransiz-i-akilli-mi-efendiden-galip-kemali-gunay-htf9h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ye aşı kıl beşİ

İki sene askerlik 

Bahane de hazır vardı da okumadık mı, vardı...

Milletin efendisi,  durumun yakışmıyor sana

Kurtuluş yıllarında deden, baban, oğlun, 

Kul iken kula  yer di aşı, kılacakken her daim beşi,

Bir Allah Allah  süngü  oldun millet efendisi.

Efendim,,,,Çarığın taç oldu başına...

Millet    efendisi: toprağı senden kuşu, kurdu senden sorarım

Yani, ye aşını kıl beşini de aklını al başına

Kul mu olacan efendi mi', 'Ye aşı kıl beşİ İki sene askerlik  Bahane de hazır vardı da okumadık mı, vardı... Milletin efendisi,  durumun yakışmıyor sana Kurtuluş yılla...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ye-asi-kil-besi-isa-nin-fransiz-i-akilli-mi-efendiden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denge', 'denge-gokhan-oflazoglu-nzn6w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya kapılırız ilişkilerimizde

sanki tapınır gibi.

Ya kapanırız kendimize

bir çeşit kalemizdi.

Beğendiğimiz kendimiz,

kapıldığımız sizdiniz.

Ne güvenli, rahat; 

mesele çözüldüyse,

nedir bu mutsuzluk

teranesi.

Bütün hüner denge de,

iki uca dokunarak

insan olur kişi.

Bilmenizde yetmez,

derinleriniz de izin vermeli.

02/06/2005', 'Ya kapılırız ilişkilerimizde sanki tapınır gibi. Ya kapanırız kendimize bir çeşit kalemizdi. Beğendiğimiz kendimiz, kapıldığımız sizdiniz. N...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/denge-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bisiklet ....................hüseyin  ve mümtaza ucundan', 'bisiklet-huseyin-ve-mumtaza-ucundan-galip-kemali-gunay-wlrw6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayna, zil, pompa hazır

Çay matarada, ılık ılık bir sabah, dost güneş, sırt sıvazlamakta

Cırcır....  bir geri,üç ileri pedal 

Sevda çöreği aldım o fırıncıdan

Köşeden mahmur aşkım, katıldı bana......

Bir çarpı bir bisiklet, kim şöför kim yolcu belli değil 

Sımsıkı sarılmış iken bu yağmur hiç dert değil 

Ilık ılık bir sabah, aşk sırtımda, güneş dost, gülüyor bana', 'Ayna, zil, pompa hazır Çay matarada, ılık ılık bir sabah, dost güneş, sırt sıvazlamakta Cırcır....  bir geri,üç ileri pedal  Sevda çöreği al...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bisiklet-huseyin-ve-mumtaza-ucundan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoktu', 'yoktu-yasar-dogan-eprbe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hiç bir şey yoktu

bütün boşluklara tuz serptim

boşluklar susadı

su oldum kandım

adın bile yoktu

önce sana bir gül attım

büyülendin rengine ve parfümüne

bütün bülbüllerin akın akın

yanık sesini verdi içine

sesinde yoktu

bir iki paragraf uzandım

saçlarının lülesince

canın titredi heveslerime

o gün ilk heyecanlar içinde

öpülesi dudaklarında yoktu

günden sonra

geceyi armağan ettim sana

yıldızlar ve ay ile

süsledim bu dünyayı sana

yüzüne yüzümü

eline elimi

diline dilimi 

ayaklarının dibine

bu mavi gezegeni verdim

gelip girdim yüreğine

seni uyandırdım

ama sen nefesimi alırken

hiç bir şeyden haberin de yoktu

yanakların kızarıp

dudakların gülümseyince

gözlerinden seyrettim

kıvılcımlarını hayatın

yüzün kararıp

dudakların hıçkırınca

içimde hissettim 

büyük uçurumlarını

beni aradığın yerde değil

çünkü hep içindeydim

kendini dinlemeyip hep başkalarını dinledin

aslında seni yakacak kadar günahın da yoktu

şimdi

alev alev yanan bir hafızan

bir de canın var

neyi af edip

neyi kahredeceksin

eğil de fısılda kulaklarıma

Lolan	02/06/05', 'hiç bir şey yoktu bütün boşluklara tuz serptim boşluklar susadı su oldum kandım adın bile yoktu önce sana bir gül attım büyülendin rengine v...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Doğan']::text[], 8.5, '{"poet":"Yaşar Doğan","poet_slug":"yasar-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/yoktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğim', 'gelecegim-gokhan-oflazoglu-4obos', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çağdan çağa ilettiğim bilgilerim,

güvencem, geleceğim.

Aklım şaşar, gönlüm coşar,

neler işlerim. Toparlanmam

acıyla, bunlar benim günlük işlerim.

Öyle bir yere gelirim, önüm, arkam

uçurum.

Şimdi ben neylerim.

Burdan başlar insan kendine,

her acıyla daha iyiye.

Gene şaşmak üzere.

02/06/2005', 'Çağdan çağa ilettiğim bilgilerim, güvencem, geleceğim. Aklım şaşar, gönlüm coşar, neler işlerim. Toparlanmam acıyla, bunlar benim günlük işl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelecegim-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece Seni Rüyamda Gördüm', 'dun-gece-seni-ruyamda-gordum-ahmet-agdere-ja50s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç hesapta yokken, birdenbire,

Düştün düşüme bir gecede.

Kalbim kelepçe, kaldım öylece; 

Dün gece seni rüyamda gördüm.

Hayır mı, şer mi, anlayamadım.

Sessizliği sana soramadım.

Yüzüne bakmaya doyamadım.

Dün gece seni rüyamda gördüm.

Bilsen, ne çok özlemişim seni…

Yine her tarafında albeni.

Nihayetinde buldun seveni! 

Dün gece seni rüyamda gördüm.

Sayfalara söyledim, silinsin! 

Beyaz üstüne güller ekilsin! 

Seni hala sevdiğim bilinsin! 

Dün gece seni rüyamda gördüm.', 'Hiç hesapta yokken, birdenbire, Düştün düşüme bir gecede. Kalbim kelepçe, kaldım öylece;  Dün gece seni rüyamda gördüm. Hayır mı, şer mi, an...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dun-gece-seni-ruyamda-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkese, sevimli yâr olursun sen', 'herkese-sevimli-y-r-olursun-sen-mikdat-bal-lc93m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir olmak, gür olmak, hür olmak demek

Er olmak, yâr olmak, var olmak demek

Zor olmak, şer olmak, kör olmak demek

Zor olma, şer olma, var olursun sen

Herkese, sevimli yâr olursun sen

Yer varsa varsın sen, yer yoksa, yoksun

Kâr varsa varsın sen, kâr yoksa, yoksun

Var varsa varsın sen, yok varsa, yoksun

İşi bul, aşı bul, var olursun sen

O zaman sevimli yâr olursun sen

Fert isen, mert isen severler seni

Dert isen, sert isen, söverler seni

Kurt isen, lord isen överler seni

Lord ol, mert ol, kurt ol, var olursun sen

Herkese sevimli yâr olursun sen', 'Bir olmak, gür olmak, hür olmak demek Er olmak, yâr olmak, var olmak demek Zor olmak, şer olmak, kör olmak demek Zor olma, şer olma, var olu...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/herkese-sevimli-yar-olursun-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Bu?', 'nedir-bu-canan-motorcu-h2u8e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara kapkara ceylan gözler

O sımsıcak hayran bakışlar

Heyecanlı kalp atışları

O tanıdık ürpertiler

Sakin sessiz hayata veda

Ve yeni bir kapı açılır dünyaya

El sıkarkan ki sıcaklık

Parmaklardan kola

Ve tüm bedene yayılan ısı

Heran patlamaya hazır bir volkan ağzı

Ve birden alev topuna dönüşür

İnsanın bütün yaşantısı

Önce derin göz süzmeler

Şirin ve utangaç gülüşler

Zaman zaman dalmalar

Heyecanla bakışmalar

Sonra arzuyla kıvrılan dudaklar

Ufak tefek dokunmalar

El ele göz göze öpüşler

Yürek atışları titremeler

Acabalar tereddütler

Her şeye boş vermeler

Huşuyla birleşen bedenler

Anlamlı bu med cezirler

Nedir bu hoşlanma mı, aşk mı? 

Yoksa sadece bir an mı? 

Acaba ebediyen sürer mi? 

Yoksa bir kerede biter mi? 

Peki ya denemeye değer mi? 

An''ı yakalamak önemli mi? 

22.05.2005  (12:40)', 'Kara kapkara ceylan gözler O sımsıcak hayran bakışlar Heyecanlı kalp atışları O tanıdık ürpertiler Sakin sessiz hayata veda Ve yeni bir kapı...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/nedir-bu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Boyut', 'yeni-bir-boyut-canan-motorcu-26o0r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ve birgün uzaklardan

Çıkıp geliverdi biri

Çenesinde çukuru

Dudaklarında gülüşü

Ve gözlerinde neşesiyle...

Güvenilmezdi, tıpkı bir serap gibiydi

Gerçek miydi yoksa değil miydi? 

Belkide iflah olmaz düşlerimin 

Ortaya çıkardığı bir hayaldi

Birgün ansızın önüme çıkıverdi.

Artık aramaktan vazgeçmişken

Hayatımı düzene koymuşken

Aşktan ve duygu arayışından yorulmuşken

Sanki yeni bir boyut açıldı

Ve ruhum tam bu karmaşanın ortasına daldı

26.05.2005    (02:10)', 'Ve birgün uzaklardan Çıkıp geliverdi biri Çenesinde çukuru Dudaklarında gülüşü Ve gözlerinde neşesiyle... Güvenilmezdi, tıpkı bir serap gibi...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeni-bir-boyut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MSN Hata Verdi Gene', 'msn-hata-verdi-gene-canan-motorcu-qgjqb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pencere her kapandığında

Yüreğime bir üzüntü

Derin bir acı çöküyor...

Sana ulaşamamak

Güzel yüzünü görememek

İçimi daraltıyor...

İşte yine kapandı

Aramızdaki tek bağlantı

Sanki tüm dünya bize karşı...

Onca kilometre yetmezmiş gibi

Başka engellerde ortaya çıktı...

Sana yazamamak seni görememek

Seni hissedememek değil ama

Keşke yanımda olsan

Ve keşke dokunabilsem sana...

Gülüşüne hasret kaldım

Güzel ve anlamlı gözlerine

Çenendeki şirin gamzeye

En çokta şevkatine sevgine...

Bilgisayarı kırasım geliyor

Veya bir yolunu bulup

Işınlanarak yada uçarak

Yanıbaşına varasım geliyor

29.05.2005   (15:20)', 'Pencere her kapandığında Yüreğime bir üzüntü Derin bir acı çöküyor... Sana ulaşamamak Güzel yüzünü görememek İçimi daraltıyor... İşte yine k...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/msn-hata-verdi-gene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Bu Sevgi', 'i-ste-bu-sevgi-canan-motorcu-1rr34', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Evet... Seviyorum galiba seni

O çocuksu şirin hallerini

Hoş ve minik buselerini

Daima şevkatle bakan gözlerini

Sen gidince boynum hep bükük kalıyor

Beynimde duruşların dansediyor

Aklıma giderken ki hüznün takılıyor

Yaşam sensiz anlamsızlaşıyor

Gözlerim hasretle arıyor seni

Yerine koyamıyor kimseleri

Hadi gel sevdiceğim dön geri

Neden diyemiyorum ki bu sözcükleri

Gözlerini cama dikip dalışın

Benim yüzümden uykusuz kalışın

Param parça ediyor yüreğimi

Çünkü ben seviyorum seni

Bence işte bu olmalı sevgi

İnsan hep karşıyı hissetmeli

Ayrılığa bile göğüs gerip

Sadece sevgilisini düşünmeli

02.06.2005   (05:30)', 'Evet... Seviyorum galiba seni O çocuksu şirin hallerini Hoş ve minik buselerini Daima şevkatle bakan gözlerini Sen gidince boynum hep bükük ...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iste-bu-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencerenin Onundeki Cicekler', 'pencerenin-onundeki-cicekler-ayda-yildiz-n47x3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kac gundur oturdum, dusundum

Yazsam mi diye, kalemi agzima goturdum

Yazmayayim bu beyaz sayfaya diye

Gittim suyu aldim getirdim

Yine de bu benim is iste, dayanamadim

Suya yazmaktansa

Kaleme kuvvet dayandim

Kalem zorluyor, su degil

Kagit islaniyor, suyun umrunda degil

Kalem parmagimi bukuyor

Sudaki parmak buzuluyor

En iyisi dedim Kapiyi tiklatip

Soyleyecegini soyle bir nefes alip

''Sizin pencerenin onundeki cicekler

icindeki tozlar, pek de guzel kokarlar''

Soyledim, nefes nefese kalip soyledim

Yoksa hasta edecekti beni

Bu guzel seyler icimde kalip dedim', 'Kac gundur oturdum, dusundum Yazsam mi diye, kalemi agzima goturdum Yazmayayim bu beyaz sayfaya diye Gittim suyu aldim getirdim Yine de bu b...', ARRAY['Türk Edebiyatı','Şiir','Ayda Yıldız']::text[], 8.5, '{"poet":"Ayda Yıldız","poet_slug":"ayda-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/pencerenin-onundeki-cicekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdigim', 'sevdigim-muzaffer-erdogan-gd6re', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aradım seni çok uzaklardasın

Bazen içtigim suda,bazen aklımdasın

Bak işte göz yaşı oldun yanagımdasın

Sen gözdesin,gönüldesin

Yazarken satırlarda

Uyurken hayallerdesin

Kısaca gülüm sen her yerdesin

Ve benimlesin....! 

Çünki sen benim unutamadıgım 

Tek sevdigimsin,ve bir tanesin.....!', 'Aradım seni çok uzaklardasın Bazen içtigim suda,bazen aklımdasın Bak işte göz yaşı oldun yanagımdasın Sen gözdesin,gönüldesin Yazarken satır...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Erdoğan']::text[], 8.5, '{"poet":"Muzaffer Erdoğan","poet_slug":"muzaffer-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdigim-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim', 'neyleyim-ahmet-durmus-ax0r0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeni bir gün niyetine,

sabah ezanlarında sana başlardım

titrerken ellerim,buz kesen ayazlarda

dua''larımada hep sen vardın

Odam soğuk,yastığımı hayalinle ısıttım.

Yastık soğuk,yaktım sigaramı seni ısıttım.

Neyleyim.. Yüreğin soğukmuş.

Ben kül oldum.Sen ısınmadın.

Neyleyim.. Kaderim buymuş.

Tezenem vurmuyor vuslatı

Sensiz ezgiler çalmakta varmış

Neyleyim... Hani dilimde olmasa Allah kelamı 

Sana lanetler okumak varmış.', 'Yeni bir gün niyetine, sabah ezanlarında sana başlardım titrerken ellerim,buz kesen ayazlarda dua''larımada hep sen vardın Odam soğuk,yastığı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Durmuş']::text[], 8.5, '{"poet":"Ahmet Durmuş","poet_slug":"ahmet-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neyleyim-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Putlar - Heykeller', 'putlar-heykeller-ekrem-sama-si5a4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Putlar hiç bir fayda veremeyen varlıklar.

Helak edilenlerle dolu mezarlıklar.

Düşünmek için çalıştırılsın her beyin

Putları heykelden ibaret zannetmeyin...

(İstanbul:01.06.2005)', 'Putlar hiç bir fayda veremeyen varlıklar. Helak edilenlerle dolu mezarlıklar. Düşünmek için çalıştırılsın her beyin Putları heykelden ibaret...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/putlar-heykeller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-abdullah-atay-44ld4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O gözler yeşil gözler 

Nice sevdayı gizler. 

Ne kadar gizlese de 

O gözde kalır izler. 

Sevdaya vurgun gözler 

Uykuyla dargın gözler 

Sevdiği elin olmuş 

Dalıyor yorgun gözler. 

O gözler gamlı gözler 

Sevdayla demli gözler 

Nazlı yari gidince 

Kederde nemli gözler... 

O gözler süzgün gözler 

Kendine özgün gözler 

Yarini görmeyince 

Kederli,üzgün gözler. 

Sürmeli kaşlı gözler 

Sevdalar aşlı gözler 

Sevip de sevilmemiş 

Ağlıyor yaşlı gözler... 

O gözler ela gözler 

Aşka müptela gözler 

Gurbet elde yarini 

Bekliyor hala gözler...', 'O gözler yeşil gözler  Nice sevdayı gizler.  Ne kadar gizlese de  O gözde kalır izler.  Sevdaya vurgun gözler  Uykuyla dargın gözler  Sevdiğ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozler-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-gulseren-onay-gkiro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalan söylüyor aynalar

Eksilmemiş 

Hiç bir şey gençliğinden...

Hüzün çizgileri değil

Yüzündeki derin izler

Belli ki gülüşünden,

Ruhundaki yara da sağalmış artık...

Eser yok gözlerinde

O eşsiz sevgiden 

Oysa bende

Hala ilk günkü kadar

Güzel,

İlk günkü kadar

Taze.....

Unutamadım seni 

Söküp atamadım içimden...

GÜLSEREN ONAY

02/06/2005/ANTALYA', 'Yalan söylüyor aynalar Eksilmemiş  Hiç bir şey gençliğinden... Hüzün çizgileri değil Yüzündeki derin izler Belli ki gülüşünden, Ruhundaki ya...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sitem-142-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarda', 'mezarda-yusuf-koc-fmubb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Orada yatan belki de en büyük aşkı idi...babası...! ! 

-------------------

Gördüm o güzeli mezar başında,

Elleri duaya kalktı ağladı,

Bir isim yazılı mezar taşında,

Kara yazılara baktı ağladı.

Sordum o güzele kimdir bu yatan,

Dedi kara toprak oluyor atam,

Oysa ki yaşıyor şerefi satan,

Mutsuzluk gözünü yaktı ağladı.

Topladı mezardan çalı çırpıyı,

Anladım yücedir onun her huyu,

Adaletli tartar gönlü tartıyı,

Zalimden gaddardan bıktı ağladı.

Dedim gözlerinde neden yaşlar var,

Dedi o gitti ya dünya bana dar,

Dedim ki insanlar nasibi yaşar,

Çaresiz yaşları aktı ağladı.

Orda bu güzelin yüreği vardı,

Ele geniş dünya ona pek dardı,

Koç Ozan bu büyük aşkı kıskandı,

Aşkı kolye yaptı taktı ağladı.', 'Orada yatan belki de en büyük aşkı idi...babası...! !  ------------------- Gördüm o güzeli mezar başında, Elleri duaya kalktı ağladı, Bir is...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mezarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Şiir Yarışması', 'i-stanbul-siir-yarismasi-erol-dal-9nwas', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsafsız insanların yatağı olmuşsun

Sürtük sürtüşmelerin kaynağı da

Tenlerin yüzsüz 

Analardan üryan bakireler, 

Nesilsiz kollarında satılık her şey.

Burçların yıkılmış, yırtılmış da mazin.

Uzak kıtalar artık; asıl sahibin.

Liva Yıkıldı. Ne hazin…

….

(Sende yıkıl karşımdan.

Boynuzlu Rezil.)', 'İnsafsız insanların yatağı olmuşsun Sürtük sürtüşmelerin kaynağı da Tenlerin yüzsüz  Analardan üryan bakireler,  Nesilsiz kollarında satılık...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/istanbul-siir-yarismasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezardaki ziyaretçi', 'mezardaki-ziyaretci-yusuf-koc-6qlyu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Orada yatan belki de en büyük aşkı idi...babası...! ! 

