INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cuş oldu kalem', 'cus-oldu-kalem-ali-riza-unal-nu97p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Attın içime, o hülyaları.

Dem ettin uykuma rüyâları.

Sırra kadem bastı sûkûtun.

Cuş oldu kalem yazar Leylâları.', 'Attın içime, o hülyaları. Dem ettin uykuma rüyâları. Sırra kadem bastı sûkûtun. Cuş oldu kalem yazar Leylâları....', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cus-oldu-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-gulseren-onay-akltz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anılarla buluştum 

Sararmış bir kaç resimde

Bu gece...

Boğazda çekilmişti biri.

Arkada mavi deniz

Sağımda sen,

Ellerim ellerinde,

Gözlerimizde 

Mutlu bir gülümseme...

O gün,

''Bir senden

Birde denizden 

Ayrılamam'' demiştin.

Oysa, 

Onu bizden daha çok sevmişsin

Cağırınca ecelin

Takılıp peşine

Umarsız çekip gittin.... 

GÜLSEREN ONAY

05/06/2005/ANTALYA', 'Anılarla buluştum  Sararmış bir kaç resimde Bu gece... Boğazda çekilmişti biri. Arkada mavi deniz Sağımda sen, Ellerim ellerinde, Gözlerimiz...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ardindan-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olma', 'olma-i-brahim-kilinc-2yyic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dinler isen benden sana nasihat

Ne olursan ol da, muhannet olma

Bir insan insana elbette muhtaç

Kalp kırma, dikkat et, lafazan olma

İmkânların varsa kullan insana

Zulüm atme muhtaç olan insana

Ne güzel rehberdir Kuran insana

Öksüzden yetimden ah alan olma

Yorma insanları gereksiz yere

Kırma insanları sebepsiz yere

Tökezleyip düşse bir insan yere

Koru o nu, sakın sen vuran olma

Engin ol, tepeden bakma insana

Her suçu, günahı yıkma insana

Hayır et, kötülük yapma insana

Hayat ver, sakın ha can alan olma

İbrahim, olur mu burada rahat 

Bir insan var ise bir yerde bedbaht

Ne gönlünde saray ne de var bir taht

Gül ol gönüllerde, sen diken olma', 'Dinler isen benden sana nasihat Ne olursan ol da, muhannet olma Bir insan insana elbette muhtaç Kalp kırma, dikkat et, lafazan olma İmkânlar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığın sonu', 'asigin-sonu-halil-colak-d65w3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kerem aslı için otuz iki dişinden olur

Mecnun Leyla için kendini çölde de bulur

Ferhat şirin için dağları delerde durur.

Yine sevdiğine kavuşamaz ayrılık sonu

Halil Çolak6.6.2005', 'Kerem aslı için otuz iki dişinden olur Mecnun Leyla için kendini çölde de bulur Ferhat şirin için dağları delerde durur. Yine sevdiğine kavu...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asigin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-i-brahim-kilinc-do4se', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söylenmesi gerekenlerle

söylemek istediklerim 

Hep çatıştılar

Söylenmesi gerekenleri duydun

Söylemek istediklerim

Benimle mezara gidecek

Sırlarımın arasına karıştılar

Belki gözlerimden hissediyorsun

Söylediklerimin arasındaki gizlerden

Birşeyler çözüyorsun

Fakat ne emin olabiliyorsun

Ne büsbütün ilgisiz

Belki sende duymaktan korkuyorsun

Ve kendi kendine sorguluyorsun

En iyisi bırak olduğu gibi dursun', 'Söylenmesi gerekenlerle söylemek istediklerim  Hep çatıştılar Söylenmesi gerekenleri duydun Söylemek istediklerim Benimle mezara gidecek Sır...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birak-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sipariş Kelimeler', 'siparis-kelimeler-halil-kesken-v9us2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni canımdan çok sevdiğimi; nasıl söyleyeceğim sana? 

Bir gün bir yerlerde çay içerken söylemeyi düşünüyorum,

Yarısında bırakıp gittiğin bardak geliyor gözümün önüne

Bir gün telefon açıp söylemeyi düşünüyorum,

Telefonun kapanış sesi geliyor kulaklarıma

Bir sokakta yolunu kesip söyleyeceğim,

Yediğim tokadın acısı geliyor yanaklarıma

Elimde çiçeklerle kapına dayanayım diyorum,

Yüzüme vurulan buketin yaprakları düşüyor ayaklarıma

Karşına çıkacak kadar cesaretim yok

Seni canımdan çok sevdiğimi nasıl; söyleyeceğim sana? 

Keşke tamamen kaybetmeyeceğimi bilebilseydim

Ya da seni neyin daha çok mutlu edeceğini

O zaman ya hiç birşey söylemeden çeker gider,

Ya da sevdiğin başka biri varsa mutluluklar dilerdim

Kendime sorup durduğum soru o kadar zor ki

Kral arı vaz geçermiydi kraliçesinden? 

Kelebek sadece bir gün yaşayacağını bilse

Yine de çıkarmıydı kozasından? 

Her gece sana olan sevgimi anlatabileceğim; 

Kelimeler sipariş ediyorum yıldızlara

Seni canımdan çok sevdiğimi nasıl; söyleyeceğim sana? 

Şiirlerim kanatsız birer haber güvercini gibi

Henüz hiç biri konamadı ellerine

Hiç biri mesajımı iletemedi yüreğine

Kelime sipariş ettiğim yıldızlar gibi,

Şiirlerimde kayıp gidiyor ellerimden

Yine cevapsız sorularımla kalıyorum başbaşa

Seni canımdan çok sevdiğimi; nasıl söyleyeceğim sana? 

Halil KESKEN                                05.06.2005    02:25', 'Seni canımdan çok sevdiğimi; nasıl söyleyeceğim sana?  Bir gün bir yerlerde çay içerken söylemeyi düşünüyorum, Yarısında bırakıp gittiğin ba...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/siparis-kelimeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sorma / (düzyazı)', 'bana-sorma-duzyazi-orhun-basat-bvprd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tugay, sıkıntının, sıcakla birlikte sinsice çöreklendiği kuytuda, gözlerini bir kenarı kopuk tokyosunun içindeki kirli parmaklarından ayırmadan yineledi. 

- Gözünü sevdiğim,sorma bana,sana elli kere söyledim! .Ne yapayım? , ne dersin diye sorma bana.Sorma güzel abicim! ! .İçinden ne geliyorsa öyle yap.İster kal, ister git, ister kalk,ister yat, ister ye, ister sıç.. Ne yaparsan yap,bana böyle şeyler sorma. Ben hiç kimsenin, her hangi bir davranışına karışmak, özellikle yönlendirmek istemiyorum, bunu senelerdir istemiyorum. İstemiyoruuuuum, istemiyoruuuuum..! ! .. 

-Tamam baboş, tamam. Dedi, Sırat. 

-Tamam. Kendi öz kararımla memlekete gitmemeye karar verdim, baboş.Sen beni kovana kadar burada seninleyim.Yeter ki sen kızma, baboş.Yak şurdan bi’tane. 

Tugay, ciğerlerindeki havayı, sıkıntısını belirten bir üflemeyle boşaltırken, Sırat’ın uzattığı paketten bir sigara çekti. Sırat’ın yüzündeki temiz ve dostluk dolu gülümsemeyi görünce, o da, gülümsemekten kendini alamadı. 

-Ulan, dedi. Şu şirinliğin olmasa çoktan dehlediydim ya seni, neyse! . Sen de şu saksıyı çalıştır biraz. Kızdığım bir iki şey var işte, öğren artık bunları ve o konularda üstüme gelme. Göreceksin ki, daha iyi geçineceğiz o zaman.. 

******* 

Tugay, Sırat’ı, Anamur rampalarında bulmuştu. Daha doğrusu rastgele yolculuklarının birinde, şakır şakır yağmurlu bir günde, sırılsıklam rampa yukarı yürürken görmüş, yollarda kimseyi arabasına almamaya kararlı olmasına rağmen, dayanamayıp durup almıştı. İlk iki saat içinde de, bütün hayat hikayesini anlatıp tüketmişti, Sırat. 

Basit, klasik bir Anadolu hikayesiydi zaten. Sevmişti, sevgisinden başka verecek fazla bir şeyi yoktu ve askerdeyken kızı başkasına vermişlerdi. Kaderine küsüp, alıp başını düşmüştü yollara.Yirmi üç yaşında, parasız, pulsuz, küskün, umutsuz. İş bulduğu inşaatlarda, bunalana kadar, üçer beşer gün çalışa çalışa, daha uzağa, daha uzağa deyip rastlaştıkları yere kadar gelmişti. 

Tugay, o gece, bir çeşit karavana benzettiği döküntü minibüsü sessiz, sakin bir kıyıya çekip durduğunda, güneş batalı epeyce olmuştu. Sırat mahcup ve memnun,elini Tugay’a uzatıp: 

- Sağ ol, baboş. Bana müsaade, çok zahmet verdim, hakkını helal et, dedi. 

- Gidiyor musun? . 

- He ya. Müsaden olursa. 

- İyi de nereye? 

- Öylesine işte, bildiğin gibi! .. 

Tugay’ın aklından sıkça geçen son iki yıl, bir kez daha geçiverdi çabucak....Küskünlüğü, yalnızlığı, konuşmazlığı. Bankadaki üç beş kuruşun ve emekli maaşının ve döküntü minübüsün elverdiği ölçüde orası senin, burası benim amaçsız gezinmeler.. Kendine bile itiraf etmekten kaçındığı, ama çok iyi bildiği bir yok olmak arzusu. Asla unutamadığı, unutamayacağı o anlatılmaz gece. Yüreğini bir mengene gibi bıkmadan usanmadan sıkan o gece. 

Sırat, bir can yoldaşı olabilir miydi? . Yaşananlar değişik olsa da, kaybedişin nedenleri ve şekli değişik olsa da, geriye kalanlar birbirine benzemiyor muydu? . Yani geriye bir şey kalmamış olması.! ! 

-Dinle beni Sırat, dedi Tugay; saklamaya çalıştığı bir kararsızlıkla. Vakit hayli geç. İstersen benle kal. Pek rahat edemesen de, bir şeyler uydururuz, yatarsın arabada. 

-Sağ olasın, baboş. Yeterince zahmet verdim sana, sıkıntılı adamın biriyim ben, bırak yoluma gideyim. Yeter yaptığın iyilik, daha fazla ezme beni. 

-Saçmalama, hem nasıl olsa yarın yolda gene önüme düşmeyecek misin? .Görüp de almazlık edemem artık seni. 

- Baboş, bak.. Gazipaşa çok yakın. Bir yer bulup... 

-Uzatma, en azından deneyelim, ne kaybederiz ki.. 

Daha fazla direnemedi, Sırat. O da, bu orta yaşlı, dost gözüken adama ısınmıştı. Mutfak teşkilatı arabadan çıkarılmış, yakındaki tarlalardan koparılan domates ve biberlerin bir kısmıyla salata, bir kısmıyla kızartmamsı bir şeyler yapılmış, açılan bir şişe ucuz şarap birlikte tüketilmişti. Bir birilerini daha fazla tanımaya yönelik, soran, araştıran, ama fazla ısrarcı olmayan konuşmalar eşliğinde. İkisi de hoşnut, gidip yatmışlardı, gizlediklerinin ve anlatmadıklarının soluğan koynunda. 

Tugay, Sırat’ın her sağa sola dönüşünde, arabanın sallantısından uyandı. Sallantının nedenini anlayana kadar, yüreği gümbür gümbür sağa sola bakındı, sonra eski acılarıyla birlikte, gene uyudu. Bu uyanışlarında, Sırat’a kal dediğine pişman oldu, bin kere.. 

Sabah geç saatlerde uyandı. Senelerdir yalnız uyandığı için, Sırat’ın yokluğunu fark etmedi bile. Arabadan indi. Kıyıya yürüyüp, denizde yüzünü yıkadı, arabanın gölgesine çöktü. Öğlenin rutubetli sıcağı da gelip sıkıntılarının üstüne...Aniden yerinden kalkıp kendini denize attı. Epeyce yüzdü, keşke gözlüğü taksaydım balık var mı, yok mu bakardım diye geçirdi aklından. Akdeniz’in sıcak suları, aradığı ferahlığı vermeyince sahile döndü. Gene arabanın gölgesine sığındı. 

Sırat, o zaman geldi aklına.” Gitmiş..” dedi kendi kendine. Sonra,”Giderse gitsin..” dedi. 

Arabayı gölge bir yere çekti. O günü, orada geçirmeye karar verip, bir battaniye çıkardı, arabanın yanına serip uyudu. Çıplak omzuna konan bir çekirge uyandırdı uykusundan. Çekirgeyi incitmeden tutup havaya doğru fırlattı. Yapacak bir şeyleri varmış gibi birden bire yerinden kalktı. Düşündü bir süre, yapacak bir şey bulamadı.. Daha yorgun çöktü gölgeye. 

Güneş, batıma bir mızrak boyu yakınlaşınca babası geldi aklına. Sağ olsaydı,“ Ben rakı makyajımı yapayım artık, yavaş yavaş “ der, annesinin hazırladığı sade bir sofraya oturur, ilk kadehini doldururdu şimdi.Onların ve ötekilerin özlemi, bütün acılarıyla bir kez daha çöreklendi yüreğine, yakınlardan geçen bir yılan gibi. 

Şimdi ne yapacağını biliyordu işte. Kalktı, dışarıdaki ıvır zıvırı arabaya attı. Gazi Paşa’ya gidip, başta rakı olmak üzere bir şeyler alıp gelecek ve geberene kadar içecekti. Tam kapıyı kaparken, uzakta, elinde torbalarla gelen Sırat’ı gördü, durdu. Sırat, geldi ve hiçbir şey söylemeden torbaları yavaşça yere bıraktı, çalıştığı inşaattan üzerine bulaşmış tozları, çabuk hareketlerle bir kez daha çırptı. Yüzünü ağır ağır kaldırıp Tugay’a baktı. 

- Gittim mi sandın, baboş? dedi. Sonra gene başını önüne eğdi. 

Olanı biteni hemen anlamıştı, Tugay. İçi sıcacık oldu. Başını salladı yalnızca.. 

********* 

Sonraki günler, aylar, çoğunlukla deniz kıyılarında, çoğunlukla Sırat’ın iş bulup çalışabileceği yazlık inşaatlara yakın kıyılarda geçti. Sırat iş bulabildikçe çalışıyor, giderlere ortak oluyor, buna yürekten gayret ediyordu. Tugay, gündüzleri kıyı müsaitse dalıyor, birkaç balık vuruyor, ya da oltayla şansını deniyordu. Sebze, meyve işi de genelde yakınlardaki bahçelerden sağlanıyor, geçinilip gidiliyordu. Aralarında günbegün gelişen güven, sevgi ve dostluk ikisini de mutlu ediyor, bu mutluluk ikisinin de yüzüne, uykularına yansıyordu. 

Bir tek sorun vardı sıkça yaşanan. Sırat, sevdiği, saydığı, kendisinden çok bilgili, deneyimli olduğuna inandığı “Baboş”u Tugay’a, her konuda akıl danışmak istiyor, her seferinde de “ nasıl istiyorsan öyle yap “, “ İçinden ne geliyorsa onu yap “, “Beni, seni yönlendirmeye zorlama “, “Bana sorma “ gibi cevaplar alıyor ve buna bir türlü bir anlam veremiyordu. Hatta zaman zaman, içten içe kızıyor, ama kendisini bir çeşit sahiplenen, yalnızlığını bölüşen bu adama, “Ulan, kendini amma da ağıra satıyon, ha..” diyemiyordu bir türlü. 

******** 

İşte, o gün de, konu nereden açıldıysa açılmış, gene aynı noktaya gelip takılmış, Sırat gene zılgıtı yemiş ve susmuştu. Tugay, her seferinde önce sinirleniyor, bağırıp çağırıyor, siniri geçince de, “Niye sinirleniyorum ki çocuğa, adam gibi bir şeyler soruyor işte. Ya cevapla, ya da anlat.” diyordu içinden. O güne kadar bu duyguları onlarca kez yaşamış ama anlatmayı hiç denememişti. Ne geçmişti eline.Yaşadığı hayat tarzının nedenini başkalarıyla paylaşırsa, bu tarzın da önemi kalmaz, daha büyük bir boşluğa mı düşerdi. Ya da “şöyle yap, böyle yap.” derse o gece olduğu gibi, birilerini daha ölüme mi gönderirdi.? ! 

Sırat’ın sorduğu, sadece, memlekete gidip sevdiği kızı bir kez daha görmesinin doğru olup olmayacağıydı. Akıllı bir adam ne önerirdi. “Bence gitme “ derdi, “Evlenmiş, barklanmış artık, sana hayır getirmez, unutursun, yarın önüne başka biri çıkar, biraz sabır göster.” demez miydi? . Ya da tersine inanıyorsa, tersini söylemez miydi? . Birden bire bir şeyin farkına vardı, Tugay.Madem ki başkalarının kaderinde bir payı olmasın diye, özellikle yönlendirici hiçbir soruyu cevaplamıyor, kimsenin ne yaptığına karışmıyordu, Öyleyse Sırat’ın yanında ne işi vardı. Çocuğu yanına almış, aylardır yanında gezdirmiyor muydu? . Bu nasıl bir ikilem, nasıl bir açmazdı? .Birden ellerinin titrediğinin farkına vardı.Bardağa uzandı, içinde ne varsa sonuna kadar içti. Sırat’a döndü. Sırat, bir şeyler sezmişti, huzursuzlandı, kalkar gibi oldu, kararsız yeniden oturdu. Gece sustu. 

- Dinle.! Dedi, Tugay...Sırat, yerinde iyice huzursuz kıpırdadı gene. 

- Bir daha anlatmayacağım. İyi dinle. Depremi biliyorsun değil mi? . ağustos’taki büyük depremi. Bilmemen mümkün değil, sordum işte! . O gece, her zaman ki gibi sade, yalın bir gece gibi başlamıştı. Eşim ve ben yemeğimizi yemiştik, ben yemekten sonra haberlere takılmıştım. Eşim, üç kat altımızda oturan baldızlara gitti. Ben yorgunluktan uyuyup kalmışım televizyonun karşısında.. 

Tugay, Sırat’ın sessizce doldurduğu bardaktaki rakıyı ellerinin titremesini engelleyemeden, gene bir solukta bitirdi. Sırat, 

- İstersen anlatma, baboş. diyebildi. 

- Başladık bir kere.. Dedi, Tugay. Devam etti. 

- Sarsıntıya uyandım. Korktum, kımıldayamadım. Önce sadece korktum, sadece korktum.! Anlatılmaz bir şeydi, bir uğultu, bir gürültü! ! . Sen depremde neredeydin, ne kadar yaşadın bilmiyorum? . Ben cehennemin içindeydim. Sonra kendimi unuttum, karımı hatırladım. Kapıya, dışarıya koştum.Zorla açabildim kapıyı, bütün çığlıklar ve binanın çatırtıları kapının önündeydi sanki. Merdivenlerden aşağıya koşmaya başladım, birkaç basamak inmiştim ki, iki belki de üç kat aşağıda – tam hatırlamıyorum - yukarıya doğru, ve mutlaka bana doğru koşan karımı gördüm. Dışarıya doğru koşacağına, bana doğru koşuyordu, yukarı doğru.. 

Sesi iyice titremeye başladı Tugay’ın..Dolan gözlerini, elinin tersiyle sildi, sonra koyuverdi kendini, ağlamağa başladı.Ağladı, ağladı. Sırat; şaşkın, ürkek, kederli. Aklına sadece, Tugay’ın boşalan bardağına rakı doldurmak geldi. 

- Sonra... Dedi, Tugay. 

- Sonra, bağırdım. Avazım çıktığı kadar bağırdım. Aşağıya koş, dışarıya koş diye çılgın gibi bağırdım. Karım, bir an gözlerimin içine şaşkın bakıp geri döndü, aşağıya, dışarıya doğru merdivenlerden inmeye başladı.Sanıyorum, birinci kata kadar inmeyi de başarmıştı. İşte en büyük gürültü o zaman koptu, bina çöktü. Benim bulunduğum kata kadar çöktü, alt katların üzerine oturdu kaldı. Uzatmayayım, Sırat.Toz, duman ve ölümcül karanlık üzerime çöktüğü zaman ben hala yaşıyordum.Yaralıydım ama yaşıyordum..Karım ölmüştü..Ve karımı ben öldürmüştüm, anlıyor musun, Sırat? ..Ben, Onu geri döndürmeseydim, O bana doğru koşup benim bulunduğum kata ulaşabilir ve kurtulabilirdi.Anlıyorsun değil mi.? İşin özü, Sırat, işin özü bu işte. O gün, bu gün, hiç kimsenin işine karışmıyorum, karışmak istemiyorum.. Anladın mı şimdi, Sırat? ... 

Sırat usulca kalktı, Tugay’a sıkıca sarıldı. 

Bir süre birlikte ağladılar. Sonra, Sırat: 

- Kendi öz kararımla, memlekete gitmiyorum, baboş.. Dedi.', 'Tugay, sıkıntının, sıcakla birlikte sinsice çöreklendiği kuytuda, gözlerini bir kenarı kopuk tokyosunun içindeki kirli parmaklarından ayırma...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bana-sorma-duzyazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümüne Yaşayacaklara', 'olumune-yasayacaklara-yavuz-bayram-caliskan-j38yd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yaz sabahı, sonsuz mavi, yeşillerin dansı,

Otlu yamaçlarla rüzgarlar karışmakta biri birlerine

Yakası yana yatmış gün, alacasından yeni kurtulmuş,

Bir ayrılığın ince gözyaşları yaprakların üzerinde,

Çiğleri alma çabasında süzülen güneş ışıkları

Kaygı damlaları değil toprağa dökülen,

Can veren, yeşili yazan ve tuale döndüren damlalar

Küçük bir el uzanır eline, 

Körpecik dudaklarıyla yanağından özlemleri öper

Baba, kız içten, hayatın akıp geldiği sularda yürürler

Yavrucağız saf ve sade, gülüşleriyle babanın gözlerinde.

Baba ser verir sır vermez.

“Gelecek yavrum bir gün mutlaka, ama gelemez bekleme yarına”

Ruhunu cennet bahçelerine uğurladığı yarini anlatamaz.

“Annemi çok göreceğim geldi, annemi çok özlüyorum baba”

Zihinlerindeki düşünceleri zincirli, doğanın çözülmezlerine bakar baba,

Çözülemeyen bilmeceleri hep o doldurmaktadır sanki,

Yaşamak ve ölmek, ağırlıklarla ezilir baba.

Kırmızı gül yanaklı güzel bir çocuk,

Bütün özlemleriyle sorar

“Ya gelmezse baba ya gelmezse? ”

“Niçin gelmesin yavrum”

“Annem öldü mü baba? ”

“ Bunu da nereden çıkardın yavrum? ”

Çöküverdi aba, yavrunun güneşini bulutlar kapadı,

Gülücükler kayboldu,ufuklar acı verdi.

Çocukça anlamaya çalıştı,

Ufacık yüreği yasları mı tutacaktı? 

O annesini istiyordu,

Yas neyine, ne bilirdi yavrucak.

Ayrılık sızılarını bırakmıştı yari.

Dalgın dalgın baktılar birbirlerine,

Kayaların üzerine oturdular.

Baba “ Yavrum” diye bildi.

Gözlerini sildi, çaresizliğini gülücüklerine gizledi.

Ne kadar ağladığını mı söyleseydi.

Yari olmadan yataklarda kıvrandığını,

Dese miydi “ “ Anneni hiç göremeyeceksin”.

Yanağına kondurduğu öpücüğün gölgense gizlendi.

Sabırsızdı hıçkırıklar, sabırsızdı ruh,

Kelebekler süzüldü, pırlanta gözlü kızına son kez baktı,

Göklerden bir melek indi,

Acıklı bir susuşla elele tutuştular,

Yalnızlıklarla bırakıp küçük yavruyu.

Ölümüne  yaşayacaklara emanet ettiler..', 'Bir yaz sabahı, sonsuz mavi, yeşillerin dansı, Otlu yamaçlarla rüzgarlar karışmakta biri birlerine Yakası yana yatmış gün, alacasından yeni ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/olumune-yasayacaklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül', 'bulbul-hasan-gorgu-a8nfl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bülbül öter bir kafeste dinlerim ben aheste

Neşeden mi kederden mi yankılanır bu beste

Savurur silkeler beni yakıcı rüzgarlarda

Bedenim kavruluyorken engin hatıralarda

                                                   

Kafes mi senin kaderin benim garip bülbülüm

Bahçeler bağlar dururken çekilirmi bu zulüm

Alsam o kafesten seni uçursam bir nefeste

Özgürlük en güzel beste benim ruhum kafeste

Kısacık geçen bu ömür biter günün birinde

Bülbül yatar ulu çınar ağacının dibinde

Sorgu sual edilmeyen yerden gelse de emir

Yürek ağlar isyan eder neden çok kısa ömür', 'Bülbül öter bir kafeste dinlerim ben aheste Neşeden mi kederden mi yankılanır bu beste Savurur silkeler beni yakıcı rüzgarlarda Bedenim kavr...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulbul-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtiyarlık', 'bahtiyarlik-adem-yaldiz-2ymgm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben,

Ne çorak topraklarda 

Ne filizler yeşerttim.

Miraç oldum gökyüzüne,

Sondaj vurdum yeryüzüne

Ne beldeler keşfettim.

Ben,

Varlıkta yokluk oldum,

Yoklukta gerçek varlık.....

Benim işim,

Çıraklık,kalfalık ve ustalık.

Dahası,

Teknisyenlik, mühendislik, mimarlık,

Hatiplik, ozanlık, sanatkarlık....

Gölgede güneş oldum

Güneşte gölge.

Deva oldum, nerede

Gördümse bir hastalık...

Siz şimdi dediniz ki

Bu sima pek tanıdık

İşte bu benim için

En büyük bahtiyarlık....', 'Ben, Ne çorak topraklarda  Ne filizler yeşerttim. Miraç oldum gökyüzüne, Sondaj vurdum yeryüzüne Ne beldeler keşfettim. Ben, Varlıkta yokluk...', ARRAY['Türk Edebiyatı','Şiir','Adem Yaldız']::text[], 8.5, '{"poet":"Adem Yaldız","poet_slug":"adem-yaldiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bahtiyarlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu akşamın adı umut', 'bu-aksamin-adi-umut-halit-alhan-icxfo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bu akşamın adını umut koydum, 

Sermayesi gülümseyişin, 

Heyecanı suskunluğun oldu, 

Ne gülümseyişin bitsin istiyorum, ne heyecanım

Gülümseyişin heyecanım olsun, 

Heyecanım

Gülümseyişin', 'Ben bu akşamın adını umut koydum,  Sermayesi gülümseyişin,  Heyecanı suskunluğun oldu,  Ne gülümseyişin bitsin istiyorum, ne heyecanım Gülüm...', ARRAY['Türk Edebiyatı','Şiir','Halit Alhan']::text[], 8.5, '{"poet":"Halit Alhan","poet_slug":"halit-alhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-aksamin-adi-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şile', 'sile-cemil-aygen-38ke3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seneler seneler önce

Bir defa gitmiştim şileye 

O zamanlar

Çocuklardan biri yoktu 

Biride küçüktü

Demekki 10 yaşlarında 

Hırçın bir deniz vardı

Hatırladığım

Deniz kenarında kamp kurmuştuk

Bir gündüzün büyüklüğünceydi

Oturup eğlenmelerimiz

Ayrılıp dönerken 

Birde şile bezinden elbise almıştık 

Karıma..

Hiçbirşeyimiz yoktu ozaman

Ne evimiz...Ne yazlığımız

Ne de yanlızlığımız

Nasılda sevinçli..Nasıl da mutluyduk

Büyük kızımın

Dalgalar içinde koşuştuğunu

Kalbi çırpınan bir kuş gibi çırpındığını

Hala hatırlıyorum

Ne o güzelim Şile 

Ne de hala hatırladığım Şile bezinden 

Elbise kaldı 

Şimdi büyük kızımın dalgalarla

Boğuşan ellerine uzanan küçük kızım var

Seneler sonra şilenin ardından..', 'Seneler seneler önce Bir defa gitmiştim şileye  O zamanlar Çocuklardan biri yoktu  Biride küçüktü Demekki 10 yaşlarında  Hırçın bir deniz va...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karagölde (Ankarada) Sonbahar', 'karagolde-ankarada-sonbahar-halay-sadi-liynz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yamaçta sonbahar ağaçları

Kimi kırmızı, kimi sarı, kimiyse yeşil

Kimi göl suyuna bırakmış dallarını

Dipte acılar içinde ağlaşır

Kimi zirvede bulutlarla şakalaşır

Bazı yapraklarsa zamansız düşmüş yerlere

Toprak olmaya hazır

Tıpkı yaşam gibi, tıpkı insanlar gibi

13.10.2002', 'Yamaçta sonbahar ağaçları Kimi kırmızı, kimi sarı, kimiyse yeşil Kimi göl suyuna bırakmış dallarını Dipte acılar içinde ağlaşır Kimi zirvede...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karagolde-ankarada-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman ve İnsan', 'zaman-ve-i-nsan-tuncay-akdeniz-7bq8u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her akşam olunca güneş batıyor

Sabahı ekiyor zaman  insanın

Gecenin koynunda hüzün yatıyor

Boynunu büküyor zaman insanın

Geride bıraktık geçen hayatı

Ne tahtları kalmış ne saltanatı

Ölümü bekliyor güz kasım patı

Yaprağı döküyor zaman insanın

Her sabah bakınca aynı gök yüzü

Akşam törpülüyor bu ömrümüzü

Farkında değiliz satıyor bizi

Ömrünü söküyor zaman insanın

Tersine dönüyor yel değirmeni

Çarkında eziyor yer seni beni

Bunun belli değil uzunu eni

İpini çekiyor zaman insanın

Rüzgarı esiyor bilinmez yere

Ocağında kaynar susuz tencere

Sonsuza açılmış camsız pencere

Hayale bakıyor zaman  insanın

Ne havaya sığdık nede karaya

Çiçeği çok gördük kırda arıya

Hayalı boyadık siyah halıya

Bilmeden dokuyor zaman  insanın

Tuncay’ın önünde bitmez engeller

Ateşin içinden uzar alevler

Gerçeği bilinmez gizli belgeler

Görmeden okuyor zaman insanın', 'Her akşam olunca güneş batıyor Sabahı ekiyor zaman  insanın Gecenin koynunda hüzün yatıyor Boynunu büküyor zaman insanın Geride bıraktık geç...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/zaman-ve-insan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün...', 'her-gun-i-brahim-ethem-bingul-m2e7t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşka dilekçe verdim

Sevgiliye deste gül

Gönlümü sere serpe

Açtım yerlere serdim

Toprak oldum yoluna

Ey Sevgili gel de gül...

Ellerin var

Pamuk gibi yumuşak 

Yüzünde tebessümün

Bana doğru gül dalı...

Kuş olup gönlüm birden

Uçup sana gelecek

Konacak gülüşüne

Yanacak, yakılacak

Figan edecek bir gün...

O gün vuslât ânıdır

Kollar yâri saracak

O günü sen bilirsin

Zannedersem yakındır...

Bekle beni, Sevgili

Bekle beni sen her gün...

www.iebingul.com', 'Aşka dilekçe verdim Sevgiliye deste gül Gönlümü sere serpe Açtım yerlere serdim Toprak oldum yoluna Ey Sevgili gel de gül... Ellerin var Pam...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/her-gun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımsızım', 'tanimsizim-melih-coskun-hot7m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanımsızım

Doğumun ve ölümün

En temiz çıplaklığında

İki bilinmez arası

Hayal kırıklığı

Üzerimde yalan dünyanın

Parıltılı kumaşından giysiler

Yapay sevişmeler arasında 

Hakiki bir yürek 

Ama aykırı, 

Ama asi, 

Tanımını yapmak için değil üzüntünün ve sevincin

Yaşamak sadece

Yaşamak bugünü bugün gibi

Ve yarını yarın...

Utanıyorum 

Çıplaklığımdan değil ama

Zorla giydirdikleri bu kirli elbiseleri atmak istiyorum üzerimden

Utanıyorum 

Yaşamak için kendimden utanmaya mecbur bırakıldığım için 

Kirli zincirlerin halkası olmaktan

Ve bu zulüm denizinde isyansız yaşayan bir balık olmaktan

Ayak bastığımdan beri bilincimin sınırsız topraklarına

Sürgünüyüm kendi yurdumun

Özlüyorum unutmayı 

Unutmayı ve bir daha asla hatırlamamayı

Giyinmek o çıplaklığı

Ve soyunmak bütün acıları ve ayrılıkları...', 'Tanımsızım Doğumun ve ölümün En temiz çıplaklığında İki bilinmez arası Hayal kırıklığı Üzerimde yalan dünyanın Parıltılı kumaşından giysiler...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tanimsizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevremizi Koruyalım', 'cevremizi-koruyalim-tuncay-akdeniz-ces47', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğa kirleniyor bence

Çevreleri koruyalım

Gülü çiçeği sevince

Çimenleri koruyalım

Çöpleri yere atmayın

Toprağa zehir katmayın

Suda nimet unutmayın

Denizleri koruyalım

Atık ırmağa akıyor

Yatağı pislik kokuyor

İçinde balık yaşıyor

Nehirleri koruyalım

Kırmasan dalını yeter

Gönüllere sevgi katar

Gülleri kokusuz biter

Çiçekleri koruyalım

Kıymetini bilmediğin

Bebeğe beşik dediğin

Meyvelerini yediğin

Ağaçları koruyalım

Bazısını çok sevdiğin

İnsana yarar bildiğin

Sadıktır ona dediğin

Hayvanları koruyalım0

Katlar binalar yapıldı

Her tarafı beton doldu

Sokak yolları daraldı

Şehirleri koruyalım

Motor duman gaz boğuyor

Bacalar zehir salıyor

Hasta zor nefes alıyor

İnsanları koruyalım

Tuncay bak diyorum sana

Neme lazım deme bana

Varlığı hayat her cana

Yuvaları koruyalım', 'Doğa kirleniyor bence Çevreleri koruyalım Gülü çiçeği sevince Çimenleri koruyalım Çöpleri yere atmayın Toprağa zehir katmayın Suda nimet unu...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/cevremizi-koruyalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklemek Var''ya', 'seni-beklemek-var-ya-nilgun-yuce-9xfrj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni beklemek var''ya,! 

Özlemeyi''de,yolunu gözlemeyi''de severim.

Gidişin hüznüm''e, dönüşün  neşem''e 

Bak..! 

Tuttuğum ellerinin  izi var hala ellerim''de

Bilmemki; 

Herkez seni soruyor.! Neden''se

Sitemim var benim''de sensizliğime...

Bilesin..! 

İçimdesin  hep özlemim''de.. 

Solukların  var an be an nefesim''de.

Gecelerim''de bir  gündüzlerim''de,

Seni benle süslediğim''de

Yolları çeker; Uzağı''da  yakın ederim. 

Seni Beklemek var ''ya..! 

Güzelim! 

Hadi dön  gel; 

Yüreğim''de hasretimsin; BEBEĞİM :)))))) 

6.6.2005', 'Seni beklemek var''ya,!  Özlemeyi''de,yolunu gözlemeyi''de severim. Gidişin hüznüm''e, dönüşün  neşem''e  Bak..!  Tuttuğum ellerinin  izi var hal...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Yüce']::text[], 8.5, '{"poet":"Nilgün Yüce","poet_slug":"nilgun-yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-beklemek-var-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar', 'mezar-cemil-aygen-4iq9p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük bir çocuk

Arkadaşıyla birlikte

Bir karıncaya

Deniz kıyısında

Bir çam ağacının dibinde

Bir mezar yapıyorlar

Karıncaya basan çocuk ağlamaklı

Ama diyor.. Ama görmedim

Öteki..

Canım görmediğini bende biliyorum

Yoksa böyle mezar kazar

Merasim yaparmıydık

Hadi gel..

Ağzında lokmasıyla gömelim

Dirildiğinde aç kalmasın

Koca bir mezar 

Karpuz büyüklüğünde

Koca bir kum kümesi

Ve de kaybolmasın diye 

Bir kozalak başına

Ve de küçük eller havada.Dualarla

Öbür dünya uğurlaması

Tıpkı koca koca insanlar gibi

Koca koca insanları yalnız kalmasınlar diye

Öbür dünyaya Dualarla 

Tabutlarla mezara koyar gibi

Çocuklar farkında değiller

Aslında kumlukta

Binlerce şişmanca karpuz büyüklüğünde mezar

Ve yerlerde binlerce kozalak var...', 'Küçük bir çocuk Arkadaşıyla birlikte Bir karıncaya Deniz kıyısında Bir çam ağacının dibinde Bir mezar yapıyorlar Karıncaya basan çocuk ağlam...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mezar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 4', 'guncel-beyitler-4-huseyin-avdic-bmzra', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Amerikanya fethetti dünyayi hayallerle.

Ben de fethedecegim insanligi gerceklerle.

******

Haksiz kazanca el attigin an,  olursun bir mafya.

Mafyaciliga son verelim, erelim insanliga.

******

Ey insanlar! Allah sizi yaratti, oyun olsun diye degil.

Sizden kulluk ve iyilik ister, kötülük ve eglence degil.

******

Sanatkârlar en büyük ödülü Allah''tan alacaktir.

O''na inanclica i$leri, buna kâfi olacaktir.

******

Sevilmedigini iddia etme.

Sevgiyi hakettin mi onu söyle.

******

Hergün ''Halil Ibrahim sofrasi''na degil, ''Allah''in sofrasi''na oturursun.

Bu sofranin zikrini, $ükrünü, fikrini yapmazsan; sen nasil insan olursun? 

Berlin, Mayis-Haziran 2005.', 'Amerikanya fethetti dünyayi hayallerle. Ben de fethedecegim insanligi gerceklerle. ****** Haksiz kazanca el attigin an,  olursun bir mafya. ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guncel-beyitler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Bil Beni Kendin Gibi', 'dost-bil-beni-kendin-gibi-emin-eren-ua9ge', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İsyan edip kötü kadere şansa

Beddualar ederim şu kara bahta

Anlamasalarda cektiğim ahta

Asıl isyanım o sahte dostlara

Yüzüme gülüpte yanımda duran

Arkamı dönünce sırtımdan vuran

Herşeyi çıkarı üstüne kuran

Dostlardan isen uzak dur aman

Herşeyin bedeli var diyor isen

Kendince dünyada birtek sen isen

Kendini kendinken sen sevmez isen

Sana dost bil beni kendin gibi sen', 'İsyan edip kötü kadere şansa Beddualar ederim şu kara bahta Anlamasalarda cektiğim ahta Asıl isyanım o sahte dostlara Yüzüme gülüpte yanımda...', ARRAY['Türk Edebiyatı','Şiir','Emin Eren']::text[], 8.5, '{"poet":"Emin Eren","poet_slug":"emin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dost-bil-beni-kendin-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adıma', 'adima-yasin-temo-6xwnu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeşermişim parlak ışıklarıyla güneşin

Aydınlık mı bu dünya? 

Sanki ben karanlıklar içinden gelmişim

İçimdeki o kımızı gonca; nerdesin? 

Terkedilmiş bir yerde misin? 

Efsunlanmış bir çölde misin? 

Madem ki içimdesin

Olurum sensin, ölümüm sensin? 

Dilimdeki vazgeçilmez bestemsin.

Yüzümdeki busem,kalbimdeki çisem,sırrımdaki gizemsin.', 'Yeşermişim parlak ışıklarıyla güneşin Aydınlık mı bu dünya?  Sanki ben karanlıklar içinden gelmişim İçimdeki o kımızı gonca; nerdesin?  Terk...', ARRAY['Türk Edebiyatı','Şiir','Yasin Temo']::text[], 8.5, '{"poet":"Yasin Temo","poet_slug":"yasin-temo","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/adima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Aşık Oldun Mu?', 'sen-hic-asik-oldun-mu-arda-sila-dl6gj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklın ve mantığının çözemediği sebepsiz derin duygulara daldın mı hiç? 

Kalbin atarken şiddetiyle tüm vücudunun sallandığı anlar oldumu hiç? 

İlk gördüğünde tüm kanın siyahlaşarak kutuplardaymış gibi dondu mu hiç? 

Sesini duyduğunda her yerin titreyip sallanarak parça parça eridin mi hiç? 

Yatarken rüyanda onu görebilmek için yüce Allah’a dualar ettin mi hiç? 

Uyandığında onu yanında görmeyince göz pınarların yaşla doldu mu hiç? 

Bir gece sarsılarak uyanıp birkaç saat sadece onu düşündün mü hiç? 

Beynini ve tüm hafızanı yok edip sadece kalbinle onu yaşadın mı hiç? 

Gözlerini kör edip sadece hayalindeki aşk ışığıyla onu görebildin mi hiç? 

Kulaklarını kapatarak sadece kalbinin atışlarında onun sesini aradın mı hiç? 

Burnunu kapatıp sadece hayal ederek onun kokusunu hissettin mi hiç? 

Onun adı geçince damarlarındaki kanların ters yönde aktığı oldu mu hiç? 

Ona ilk dokunduğunda çıplak elle elektrik teline dokunmuşçasına çarpılmadıysan,

Onu tadıdıktan sonra etrafındakiler bir defa bile sana “aklın başında mı” demediyse,

Onu  beklediğin beş dakika beş yıldan, hatta beş asırdan daha uzun gibi geçmediyse,

Onu tanıdıktan sonra, onsuz  geçen  bir saniyede bile  yaşadığını düşünebiliyorsan,

Yanında değilken  kalbinin çalıştığının ve etrafındakilerin  farkında olabiliyorsan,

En iyisi mi sen hiç aşık oldum deme, yaşadığı aşk değil belki başka birşey.', 'Aklın ve mantığının çözemediği sebepsiz derin duygulara daldın mı hiç?  Kalbin atarken şiddetiyle tüm vücudunun sallandığı anlar oldumu hiç?...', ARRAY['Türk Edebiyatı','Şiir','Arda Sıla']::text[], 8.5, '{"poet":"Arda Sıla","poet_slug":"arda-sila","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-hic-asik-oldun-mu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz', 'caresiz-kemal-cakir-fhn8d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sakin ol, dizginleri vur hırsına

Gün doğacak düşündüklerine

Nasıl olsa.

Hem, kendini ne diye zorlayacaksın

Bir garibin getirmek için sırtını yere.

İşin çok kolay, okşamaya devam et 

Garip! sevildiğini sanır, olsa olsa.

Bir zulüm işareti var

Sebepsiz okşayan ellerinde

Boşuna durgun değil 

Düşüncelerindeki telaş.

Yaklaşıyor mu dersin acaba! 

Hırs denizindeki gemi

Yavaş yavaş.

Sakin ol, dizginleri vur hırsına

Gün doğacak düşündüklerine

Nasıl olsa.

Hem, kendini ne diye zorlayacaksın

Bir garibin getirmek için sırtını yere.

İşin çok kolay, okşamaya devam et 

Garip! sevildiğini sanır, olsa olsa.', 'Sakin ol, dizginleri vur hırsına Gün doğacak düşündüklerine Nasıl olsa. Hem, kendini ne diye zorlayacaksın Bir garibin getirmek için sırtını...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/caresiz-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Övünme Gül', 'ovunme-gul-ayhan-yavuz-acikgoz-hzj3s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey gül bir ömre bedel, yaprağının deseni

Fakat övünme çünkü, biz yetiştirdik seni

(istanbul-05.06.2005)', 'Ey gül bir ömre bedel, yaprağının deseni Fakat övünme çünkü, biz yetiştirdik seni (istanbul-05.06.2005)...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ovunme-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bire Üç', 'bire-uc-ayhan-yavuz-acikgoz-sz7t9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey oğlum ağlama, ağlatma beni

Bilirsin, bu düzen değildir yeni

Topraktır nihâyet varacağın yer

Üç karış boyudur, bir karış eni

(istanbul-04.06.2005)', 'Ey oğlum ağlama, ağlatma beni Bilirsin, bu düzen değildir yeni Topraktır nihâyet varacağın yer Üç karış boyudur, bir karış eni (istanbul-04....', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bire-uc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşegül', 'aysegul-guven-tahtakiran-0jdkg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölenle ölünmez bunu böyle bil 

Baba sevgin candan içten Ayşegül 

Kederi ve gamı yüreğinden sil 

Hayatın tadını yaşa Ayşegül

Kalbin neşelensin yüzün hep gülsün 

Babanın hasreti içinde kalsın

Bütün mutluluklar seninle olsun

Yüreğin dönmesin taşa Ayşegül

Her gece babana Fatiha oku

Sadaka ver olmaz azı ve çoku 

Ona layık kız ol oku ha oku

Neşe dağıt dağa taşa Ayşegül

Sevgiye râm ol da hüzünü unut

Nefrete karşı ol neşeye anıt

Eksilmesin bir an içinden umut 

Gitmesin umutlar boşa Ayşegül

07.11.1994 / OLUKÖZÜ', 'Ölenle ölünmez bunu böyle bil  Baba sevgin candan içten Ayşegül  Kederi ve gamı yüreğinden sil  Hayatın tadını yaşa Ayşegül Kalbin neşelensi...', ARRAY['Türk Edebiyatı','Şiir','Güven Tahtakıran']::text[], 8.5, '{"poet":"Güven Tahtakıran","poet_slug":"guven-tahtakiran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aysegul-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Bir Hafta', 'i-stanbul-bir-hafta-halay-sadi-lxsy5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim için İstanbul,

Senede bir hafta…

İlk gün Modada çay ve manzara

İstiklal caddesinde avara volta

öğlen Şampiyonda kokoreç-ayran

 İncide profiterol

Bir günüm Büyükadada

İşte o gün koparım hayattan

Faytonla büyük tur, deniz seyirli çay

Kumkapı da felekten bir gece

Herkes işine gidince

Vapura binip iyot kokusuyla

Ve martı çığlıklarıyla bir gezi

Birkaç dost ziyareti

Koşan insanlar trafiğine takılmadan

Yani İstanbullu olmadan

En eski ve en yeni dokuları

En fakir ve en zenginleri

Yan yana görüp öylece bırakarak

Gözbebeklerime sadece ve sadece

Büyükada manzaraları alarak

Bir hafta İstanbulu

Tenhalarda sevip

Buluşmak üzere terk etmektir. Nisan-2005', 'Benim için İstanbul, Senede bir hafta… İlk gün Modada çay ve manzara İstiklal caddesinde avara volta öğlen Şampiyonda kokoreç-ayran  İncide ...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istanbul-bir-hafta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz Dağı', 'buz-dagi-ahmet-agdere-fhw59', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buz dağı devrildi, arkası görüldü

Ağlamayan pek çok, buna gönül üzüldü

Derbeder kalmak, mutluluktan paye imiş

Eski havalar yine odama süzüldü', 'Buz dağı devrildi, arkası görüldü Ağlamayan pek çok, buna gönül üzüldü Derbeder kalmak, mutluluktan paye imiş Eski havalar yine odama süzüld...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/buz-dagi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilik Denen Işık', 'i-yilik-denen-isik-i-lknur-cekici-l5ky3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden saf kalamıyoruz? 

Akıp giden zaman da

Neden çocuk olamıyoruz? 

Yüreğin kuytusun da

Neden karanlık kuyuya atıp da

Üzerini örteriz

Yok etmek için onu

Kötülüğe yem ederiz

Neden döneriz sırtımızı? 

İyilik denen ışığa

Gideriz hep karanlığa

Mecbur değiliz ki anlasana', 'Neden saf kalamıyoruz?  Akıp giden zaman da Neden çocuk olamıyoruz?  Yüreğin kuytusun da Neden karanlık kuyuya atıp da Üzerini örteriz Yok e...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iyilik-denen-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlu gecede mektup', 'yagmurlu-gecede-mektup-salih-erdem-95szt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yüzüm sana dönük

vurdukça resmediyor pencereyi

neler aklına gelmiyor ki insanın

……..yaşayıp yaşayacağı

türlü şekiller yuvarlanıp siliniyor camdan

sürüklenirken damlaların peşinde

kıyamet davulları gibi

gök gürültüsünün sırası mı şimdi

tam yakalamışken

……..şimşekli ıslak ezgiyi

özlemek faydasız 

bu uzaklara

bir bulut da ben olsaydım

milyonlarca damlayla yüklü uç uca

dokunurdum yüzüne belki

açmışsan pencereni

……..birkaç soğuk damlayla

hayaller pervasız

gece yarısı

tanımadığın bir bulut pencereni tıklatıyor

ısrarlı iri damlalarla

dışarı çıkıyorsun merakla

birden tanıdık bir soğukluk

gözlerini kapayıp düşünüyorsun

……………………………….yüzünü okşadığımı

titriyorsun

………zevkten mutluluktan

hiç farkında değilsin oysa 

üşüyorsun

düşünsene

………..her yağmurlu havada

………………….gökte bulut olduğumu

ben deli değilim de neyim

sırası mı şimdi

……………bulutlara ortak olmanın

fırtınayla yol alıp

………..kapına yığılmanın

belki korkuturum seni

hoş zaten sevmezsin

benimki de hayal işte

………..hoş gör canım

hayalde olmasa

………..çekilir mi kahrı

……………..bu uzakların

yarın iş güç yok gibi

neler düşünüyorum

uyku sırada bekliyor

………..saat gecenin ikisi

güzelim

şimdi tam uyku havası

………..deyim yerindeyse eskilerin

aklımda sen varken

ne günahı var şimdi

………..uyku tutmayan gözlerimin

15-16.01.1995 safranbolu', 'yüzüm sana dönük vurdukça resmediyor pencereyi neler aklına gelmiyor ki insanın ……..yaşayıp yaşayacağı türlü şekiller yuvarlanıp siliniyor c...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/yagmurlu-gecede-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılıksız sevgi', 'karsiliksiz-sevgi-ali-riza-unal-axnvq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi denen servet, bedelsiz paha.

Aşk denen devlet, kefensiz çuha.

Gördüm ki gönüle akçenin takâti yok.

Kâfidir bir dür-u kelâm en güzel baha.

Beş yüz kelam yazdık, beş ehil çıkmadı.

Ey Rıza bir değil bin daha söyle,bin daha.

Anlayana sivri sinek saz, gerisi angut ile kaz,

Sözümüz meclisten öte,daha ne diyeyim daha.', 'Sevgi denen servet, bedelsiz paha. Aşk denen devlet, kefensiz çuha. Gördüm ki gönüle akçenin takâti yok. Kâfidir bir dür-u kelâm en güzel ba...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karsiliksiz-sevgi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biten Bir Dostluğun Ardından', 'biten-bir-dostlugun-ardindan-i-lknur-er-yyvbb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbimdeki son hatıralarıda koydum kapıya

Son resmimizi de sildim zihnimden

Kalmadı bir şey sana dair

Sensizliği, senden daha çok sevdim

Hissediyorum mutluluk daha yakın böyle

Bilinmezler denizinde sürüklenmektense

Adı konmuş bir yokluğu yeğlerim

Son derim bitti derim

Varlığına yazamadığım şiiri 

Ne kolay yazdım yokluğuna

Fark ettim cümlelerim çok çabuk bitti

Onlar bile istemedi seni ifade etmeyi', 'Kalbimdeki son hatıralarıda koydum kapıya Son resmimizi de sildim zihnimden Kalmadı bir şey sana dair Sensizliği, senden daha çok sevdim His...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biten-bir-dostlugun-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-dilba-selen-efidj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kim kirleti bu sevgiyi, isinlari göz kamastirirken

Kim haykirdi özgürce, sevgi yürekte gizli yanarken

Ah sana, sana ne desem 

Yalan degilde gercek oldugunu his etsem

Bu dünyaya ait degilmiyim? 

Yasanmis zamanlardan mi geliyorum 

Yoksa yasanmamis zamanlardanmi

Tek bildigim bu zamana ait olmadigim

Degilim cani, zamanin

Ben ona ask dolu bir gelecek vaat etmistim

Oysa o sirt cevirdi bende onu yasanmamis sayiyorum

Kendime olsada isyanin, aslinda isyanim sana', 'kim kirleti bu sevgiyi, isinlari göz kamastirirken Kim haykirdi özgürce, sevgi yürekte gizli yanarken Ah sana, sana ne desem  Yalan degilde ...', ARRAY['Türk Edebiyatı','Şiir','Dilba Selen']::text[], 8.5, '{"poet":"Dilba Selen","poet_slug":"dilba-selen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğin/Geldiğin Gün', 'gittigin-geldigin-gun-halil-kesken-ffd5d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geldiğin gün güneş doğdu bu şehirde

Geldiğin gün ağaçlar çiçek açtı

Geldiğin gün güldü yüzüm

Geldiğin gün bitti hüzün

Geldiğin gün terkettim kederleri

Geldiğin gün bu şehirden gittim

Geldiğin gün doğdum,

Geldiğin gün öldüm

Geldiğin günü sevdim en çok

En çok geldiğin günden nefret ettim

Gittiğin günün yıldönümüydü

Geldiğin gün sabun gibi erimemin bittiği gündü

Geldiğin gün, bittiğim gündü

Artık farketmiyor gelmiş olman

Çünkü ben artık tükendim,

Ben artık bittim

Geldiğin gün ben bu şehirden gittim

Geldiğin gün toplamıştım hüzünlü şiirlerimi

Geldiğin gün hasretini ve aşkını bırakmıştım evde

Geldiğin gün bir otobüs garından

Sadece gidiş için bilet almıştım

Geldiğin gün doğmuş, geldiğin gün ölmüştüm

Yeni adresimi vermiyorum bir daha gelme diye

Numaramı bırakmıyorum arama, sorma diye

Gözümde çalıntı bir şiir gibi bitmiştin

Hatırlarsan; geldiğin gün gitmiştin...

Halil KESKEN                  06.06.05   00:35', 'Geldiğin gün güneş doğdu bu şehirde Geldiğin gün ağaçlar çiçek açtı Geldiğin gün güldü yüzüm Geldiğin gün bitti hüzün Geldiğin gün terkettim...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gittigin-geldigin-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürümek..', 'yurumek-ersin-sercek-m3tts', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürümek istiyorum yürümek,

Karlı yağmurlu havalarda yürümek.

Bazen sevmesemde yürümeyi,

Gideceğim yerde düşünmek seni.

Sevdiriyor bana saatlerce yürümeyi..', 'Yürümek istiyorum yürümek, Karlı yağmurlu havalarda yürümek. Bazen sevmesemde yürümeyi, Gideceğim yerde düşünmek seni. Sevdiriyor bana saatl...', ARRAY['Türk Edebiyatı','Şiir','Ersin Serçek']::text[], 8.5, '{"poet":"Ersin Serçek","poet_slug":"ersin-sercek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yurumek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-nihal-gungor-2z1qn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hızla,bir tünelden kayıyorum

yada yüzüyorum.

Tünelin sonunda iki gölge...

Yaklaştıkça tanıyorum,

seviniyorum.

Biri dört bebesini bırakıp giden teyzem.

Diğeri kurbanda kestikleri

kıvırcık Eminem.

Bakışlarıyla ısınıyorum.

Sonsuz bir beyazlığın içindeyim.

Daha önce hiç duymadığım bir musiki....

Daha önce hiç olmadığım kadar neşeli,

saydam bir aradan sana bakıyorum.

Üzülme bebeğim,

canım acımıyor ki

Yolculuğa çıkar gibi

biraz merak...biraz heyecan....

Ağlama bebeğim

ölmek yok olmak değil ki

Kapının arkasında,

pencerenin dışında,

eve giren kelebeğin

kanatlarında....

Hep yanında olacakmışım,

yanıbaşında.

                   (4.6.2005)', 'Hızla,bir tünelden kayıyorum yada yüzüyorum. Tünelin sonunda iki gölge... Yaklaştıkça tanıyorum, seviniyorum. Biri dört bebesini bırakıp gid...', ARRAY['Türk Edebiyatı','Şiir','Nihal Güngör']::text[], 8.5, '{"poet":"Nihal Güngör","poet_slug":"nihal-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ruya-174-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Bir Hasretse', 'sevda-bir-hasretse-herdem-ankara-9t9u5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda Bir Hasretse

Sen yaşanılmamışsın gizemli bebek

Hayatımda kimseye söylemediğimi

Sana haykırıyorum

Seninle gurur duyuyorum

Bir nefes yaşamaksa kollarında 

Seninle olmaksa özlemek

Seni hissetmekse hasret

Gözlerinin içinde yaşamaksa sevmek

Ben gözlerinin içinde hapis olmak istiyorum

Sevda bir hasretse  HASRETİM

Hissetmek özlemekse ÖZLÜYORUM

Sevmek gözde yaşamaksa YAŞIYORUM

SENİNLE GURUR DUYUYORUM

SENİ ÇOK SEVİYORUM MELEĞİM

Herdem

06/06/2005

17:20', 'Sevda Bir Hasretse Sen yaşanılmamışsın gizemli bebek Hayatımda kimseye söylemediğimi Sana haykırıyorum Seninle gurur duyuyorum Bir nefes yaş...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevda-bir-hasretse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Film Gibi', 'film-gibi-sahin-yenilmez-8opbr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu zamana kadar hatırlanmamışsa 

Yaşamak için gerekli olan duygular

Yada hatırlatılmamışsa 

Neye yarar ki yaşamak bundan sonra.

Gözlerime söz geçirsem de kalbime hep yenik düşmüşümdür 

Alır başını gider o bazen

Kaptırır kendini uzak deniz kızlarına

Sonra gel de pirincin taşını ayıkla..

O orada ben burada olmuyor

En iyisi unut diyorum kendi kendime.

Unutmak! 

Hayatımızın en kilit kelimesi

Bazıları ben unuttum diyor

Yalan! 

Hiç bir şey aslında akıldan çıkmıyor...

Çoğu zamanımızı

Hatta hemen hemen ömrümüzün tamamını

-Yalan..deyip

-Yalan dünya..deyip

-Sahte,-hayal,-düş..deyip geçirdik...

Gerçekleri yitirdiğimiz şeylerin ardından aramaya başladık sonra

Avuttuk bunca yıl kendimizi.

Sonra bir bakmışız ki epey olmuş güneş batalı...

Benimde canım geçti tüm karanlıklardan 

Ama hiç korkmadan...

Şu an tüm hayatım

Gözlerimin önünden bir film gibi geçiyor

Ben ise hiç yaşamamış gibi seyrediyorum..', 'Bu zamana kadar hatırlanmamışsa  Yaşamak için gerekli olan duygular Yada hatırlatılmamışsa  Neye yarar ki yaşamak bundan sonra. Gözlerime sö...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/film-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karabağ', 'karabag-muhammet-faruk-koca-5f8v9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözümde vatanımı düşlüyorum her gün, 

Özlemle kokusunu çekiyorum içime derin derin, 

Karabağım sevdam, 

Sula toprağını al canımdan, 

Oy yaralım karabağım, 

Senden ayrıyım ya, 

Yüreğimi koparmışsın ya, 

Al beni vur taşlara, 

Ey toprağımın kızıl gülü, 

Özledim senin o loş kokulu sümbülünü,, 

Karabağım yaralım, 

Ayrıyım senden ezelden, 

İçimde bir parçaydın aldılar benden, 

Seni düşlerim her ezan sesinde, 

Karabağım yaralım, 

Sula toprağını al canımdan. 

(05.06.2005)', 'Gözümde vatanımı düşlüyorum her gün,  Özlemle kokusunu çekiyorum içime derin derin,  Karabağım sevdam,  Sula toprağını al canımdan,  Oy yara...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karabag-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hasan’ a Mektup / 10 (Susmalı mıyım?)', 'hasan-a-mektup-10-susmali-miyim-ahmet-turan-altunsu-ugc53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sıkıntılar had safhada / bedbînim, bezginim Hasan! .. / yıkılırım her defada / üzgünüm, üzgünüm Hasan! .. / mecnun gibi pür cefada / biçare, gezginim Hasan! ..

susmalıyım... 

bir ferahlık dolmalı içime tuhaf da olsa... 

zihnimde fingirdeşmemeli 

kara sevdalı figürler. 

hasret çelebi ile yüzleşmemeli, 

yanaşsa da 

-göl yeşili gözlerime 

-altın su damlaları, 

hıçkırıklarım saf saf da olsa, 

düğümlense de boğazımda 

asla dilleşmemeli... 

bu sıkıntıyı aşmalı be Hasan! ..

dağıtmalı efkârı, 

yeni sevdalara kucak açmalı. 

bir gurup vakti olmalı...

meselâ Turgut Reis’ te: 

-bir, yalı akşamüstü’ nde; 

-adaların gerdanlarında kaybolmak üzere olan 

- altın sarısı güneşle gözlerim buluşmalı... 

bu sıkıntıyı aşmalı be Hasan! ..

dağıtmalı efkârı. 

yeni sevdalara kucak açmalı. 

bir gece vakti olmalı... 

yamaçlara otağ kurup, 

-ayın şavkına dalmalı. 

kırılgan yansımaların; 

yakamozların

parlak, göz alıcı ışıltılarına sevdalanmalı...

huzura kavuşmalı be Hasan! ..

arada bir Halikarnas’ a uzanmalı 

-hani “vur patlasın, çal oynasın” babından- 

bu, dört dörtlük et kombinasında, 

canlı kalmanın 

“bilâ kayd-ı şart”larını öğrenmeli 

-erbabından...

susmalı mıyım? .. 

yasak bir “kutlu aşk”tan uzakta, 

başka sevdalarla buluşmalı mıyım? ..

................

...............

ah be Hasan; 

olacak şey mi bu? 

yakışır mı sevdalısına saklanmak? ..

o “kutlu emanet” e inat,

eğreti yalanlarca yasaklanmak? 

çaresizim yine Hasan! 

bakamıyorum yüzüne kimsenin,

çıkamıyorum el içine Hasan! ..

-06.06.2005 / Ankara

-Ahmet Turan Altunsu', 'sıkıntılar had safhada / bedbînim, bezginim Hasan! .. / yıkılırım her defada / üzgünüm, üzgünüm Hasan! .. / mecnun gibi pür cefada / biçare,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/hasan-a-mektup-10-susmali-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berceste Mısralar-3', 'berceste-misralar-3-nihat-malkoc-sh18y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SON NEFES

Ağzımı bağlasalar Hak''tan dem vurur sesim

Allah Allah diyerek tükensin son nefesim

SONSUZLUĞUN SULTANI

Hakikati bulmada akıl gönüle muhtaç

Sonsuzluğun sultanı bize aguşunu aç

BEŞER

Gönlümün bozkırları gül suyuyla yeşersin

Büyük görme kendini neticede beşersin

SEN

Sensiz hayat nasıldı?...Hiç düşünemiyorum

Hissiyat alev ateş, yoruma muhtaç yorum

LÂĞIM FARELERİ

Onca lâğım faresi kemiriyor ruhumu

Süsleyip sunduğunuz ideal hayat bu mu?

KELİMELERİN DARASI

Şiir, kelimelerin darasını düşmektir

Hissiyat kazanında yana yana pişmektir

GÖNÜL DİLİ

Şiir gönül dilidir, eylemi içindedir

Damıtılmış saf sözdür, söylemi içindedir

KALBİ MÜHÜRLENENLER

Kalbi mühürlenenler, göremez tuzakları 

Marifet kalp gözüyle görmektir uzakları', 'SON NEFES Ağzımı bağlasalar Hak''tan dem vurur sesim Allah Allah diyerek tükensin son nefesim SONSUZLUĞUN SULTANI Hakikati bulmada akıl gönül...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/berceste-misralar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit Yaşar Yaz Demeseydi', 'umit-yasar-yaz-demeseydi-sahin-erturk-599yi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onun gibi

Acılar denizine düşmeseydim

Benden ŞAİR olmazdı

Ne zaman ki

Aşk ateşine düştüm

İşte o  zaman

Aldım kalemi elime

Ve,

ÜMİT YAŞAR OĞUZCAN

Çıkıverdi karşıma

Şiirlerimi okudu

Duygulu yazıyorsun

Yaz oğlum yaz dedi

Bana güç verdi

Gaz verdi

Ümit verdi

İşte o gün,bugün

Tam otuz yıldır

Bıkmadan yazıyorum ben

Kimler geldi,kimler geçti

Kimleri,

Neleri yazmadı bu kalem

Merhum,büyük üstat

ÜMİT YAŞAR YAZ DEMESEYDİ

3500 ŞİİR yazamazdım

Beş şiir kitabı çıkaramazdım

YÜREĞİ YANMIŞ ŞAİRLERDEN

ŞİİR MAKİNESİ

NÖBETÇİ ŞAİR 

Olmazdım,olamazdım

ŞAHİN ERTÜRK olarak kalır

Unutulur giderdim

ÜMİT YAŞAR YAZ DEMESEYDİ', 'Onun gibi Acılar denizine düşmeseydim Benden ŞAİR olmazdı Ne zaman ki Aşk ateşine düştüm İşte o  zaman Aldım kalemi elime Ve, ÜMİT YAŞAR OĞU...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/umit-yasar-yaz-demeseydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönül', 'deli-gonul-muhammet-faruk-koca-4noya', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aldırma deli gönül aldırma, 

Nasıl olsa geçer, 

Bilirim acı çektiğini, 

Beslediğin derin hislerin ardından, 

Gitti bilirsin geri dönmez, 

Dökme gözyaşlarını sil, 

Bir anlıkta olsa yeterde, 

bırak şişeyi, 

Son bulsun bu hüsran, 

Deli gönül ey deli gönül, 

Düşleme artık bekleme düşündüklerini, 

Bir seldi aldı gitti, 

Bilirim yanarsın boşu boşuna, 

Aldırma derdim, 

Kabarmış denizin belli, 

Vuruyorsun kendini loş ışıklara, 

Elinde ki resme baka kala, 

Aldırma deli gönül aldırma, 

Dünya hali hep böyle, 

Giden geri dönmüyor, 

Ufka açılan gemiler gibi. 

(05.06.2005)', 'Aldırma deli gönül aldırma,  Nasıl olsa geçer,  Bilirim acı çektiğini,  Beslediğin derin hislerin ardından,  Gitti bilirsin geri dönmez,  Dö...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/deli-gonul-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluğun Sultanı', 'sonsuzlugun-sultani-nihat-malkoc-2sxok', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hakikati bulmada akıl gönüle muhtaç

Sonsuzluğun sultanı bize aguşunu aç', 'Hakikati bulmada akıl gönüle muhtaç Sonsuzluğun sultanı bize aguşunu aç...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sonsuzlugun-sultani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Düşü', 'yalnizligin-dusu-muhammet-faruk-koca-19pp2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine uzaklardasın bilirim, 

Uzanıp ta tutamadığım bir elimsin, 

Her karanlık çökünce, 

Başlar oysa benim yalnızlığım, 

Bir mum yakarım resmine bakan yana, 

Sisli bir mum ışığı, 

Sarar sarmalar içimde ki tüm sensizliği, 

Alır getirir düşlerde seni 

Ve başlar gece, 

Eğilip de yaslarım başımı dizlerine, 

Bir çocuk gibi sevilmek ister bu yürek 

Ve ansızın çekip gidersin, 

Hayra yorulmaz bu gidiş, 

Yalnızlığım başlar senin her gidişinde, 

Bilirim bir daha geri gelmeyeceksin, 

Odamı aydınlatan sessizlik gelmeyeceksin. 

(05.06.2005)', 'Yine uzaklardasın bilirim,  Uzanıp ta tutamadığım bir elimsin,  Her karanlık çökünce,  Başlar oysa benim yalnızlığım,  Bir mum yakarım resmi...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizligin-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-muhammet-faruk-koca-evetb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şarkı var kulaklarımı tırmalayan, 

Beni diyar diyar gezdiren, 

Sonra bir bilmecenin içine bırakan, 

Bir bilmecenin içindeyim şimdi yalnızım. 

Bir çığ gibi büyüyor içimde ki yalnızlık, 

Bir başkası için dökemedim şiirleri sayfalara, 

Bir yaprakmış meğer deli gönüm, 

Deli divane diyar diyar uçan 

Ve bir daha geri dönmeyen. 

(05.06.2005)', 'Bir şarkı var kulaklarımı tırmalayan,  Beni diyar diyar gezdiren,  Sonra bir bilmecenin içine bırakan,  Bir bilmecenin içindeyim şimdi yalnı...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizim-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bu', 'ask-bu-ali-baydere-np0zn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde bir his var,

Nedendir bilinmez.

Sana olan sevgimi

Anlatmaya kelimeler yetmez.

Acımasız kalbin aşka gelmez.

Sana olan sevgim

Bir ömür bitmez.

Çaresiz yüreğim

Kapıldı bir kez.

Sana olan duygularımı

Hiç bir şey dindirmez.

Yüreğime laf geçmez.

Aşk bu, gelir ama

Asla gitmez.', 'İçimde bir his var, Nedendir bilinmez. Sana olan sevgimi Anlatmaya kelimeler yetmez. Acımasız kalbin aşka gelmez. Sana olan sevgim Bir ömür ...', ARRAY['Türk Edebiyatı','Şiir','Ali Baydere']::text[], 8.5, '{"poet":"Ali Baydere","poet_slug":"ali-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-bu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berceste Mısralar-19', 'berceste-misralar-19-nihat-malkoc-4bf14', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÇAĞRI

Hasret ruhu kemirir, dünya yabancı diyar

Elinde kırmızı gül vuslata çağırır yâr

DİLEK

Semâ ruhuma çadır, dolunay gölgem olsun

Üstümde dalgalanan bayrağım, ülkem olsun

CAM KIRIKLARI

Gönül yıkık, perişan, yâr can evinden attı

Kalbin cam kırıkları yüreğimi kanattı

OYUNCAK

Kazandıkça hırslandın, dolaştın kucak kucak

Mal mülk nefse teselli, çoluk çocuk oyuncak

TOPRAK

Çağırınca Azrail sarılırım boynuna

Toprak ruha sığınak, alır bizi koynuna

KÖR AKIL

Kör akıl kalbe değil, kalp aklına hükmetsin

Kalp kılavuzluğunda aklı olmayan netsin

İMTİH/ÂN

Her ân sınanıyorsun, ıskalama bu ân''ı

Başına gelen her şey Rabbinin imtihanı

YAŞ DEDİĞİN NEDİR Kİ

Sonuçta bir kaç rakam, yaş dediğin nedir ki

Şayet eğilecekse baş dediğin nedir ki', 'ÇAĞRI Hasret ruhu kemirir, dünya yabancı diyar Elinde kırmızı gül vuslata çağırır yâr DİLEK Semâ ruhuma çadır, dolunay gölgem olsun Üstümde ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/berceste-misralar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaçlar ve Ben', 'agaclar-ve-ben-ali-baydere-1xtfy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağaçlara benzetiyorum kendimi

Göz yaşlarının yanaklarımdan süzülerek

İntihar edercesine

Boşluğa atlaması

Ağaçların solduğunda yapraklarının

O sonsuz boşluğa bırakması gibi.

Dışarıda bakıldığında dimdiktir aslında

Ağaçlarda benim gibi.

Belli etmek istemeyiz duygularımızı ikimizde

O topraklar altında saklar 

Bütün duygularını

Ben ise kalbimin derinliklerinde.

O kurtlardan kalan boşlukları kapatmaya

Çalışır gövdesinde

Bende aşklardan kalan yaraları

Onarmaya çalışırım

O sonbahar günlerinde.', 'Ağaçlara benzetiyorum kendimi Göz yaşlarının yanaklarımdan süzülerek İntihar edercesine Boşluğa atlaması Ağaçların solduğunda yapraklarının ...', ARRAY['Türk Edebiyatı','Şiir','Ali Baydere']::text[], 8.5, '{"poet":"Ali Baydere","poet_slug":"ali-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/agaclar-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-nihat-malkoc-ly583', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz hayat nasıldı? ...Hiç düşünemiyorum

Hissiyat alev ateş,yoruma muhtaç yorum', 'Sensiz hayat nasıldı? ...Hiç düşünemiyorum Hissiyat alev ateş,yoruma muhtaç yorum...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sen-564-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ben', 'bir-ben-muhammet-faruk-koca-c1ehg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çamlıca dayım içimde derin bir düş, 

Her yer loş bir karanlık, 

İstanbul’un o görkemli yapıtlarında, 

Derin çizgiler çizilmiş sahil burnuna, 

Yalnızlığımın yankısını izliyorum, 

Çamlıca dayım içimde derin bir duş 

Ve elimde yüreğim, 

Aydınlanmayan güne inat. 

(05.06.2005)', 'Çamlıca dayım içimde derin bir düş,  Her yer loş bir karanlık,  İstanbul’un o görkemli yapıtlarında,  Derin çizgiler çizilmiş sahil burnuna,...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-ben-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buda Ne ki', 'buda-ne-ki-ali-baydere-dct8q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbinin parolası yok ki bende

Kapını çalamam kolum kalkmaz ki

Sesim çıkmaz ki

Kapının arkasından sana seslenemem ki

Bedenim hapsetmiş yüreğimi

Sana ilişemez ki

Hep adını sayıklarım

Her düşüncem senle son bulur

Sonların yeni bir ilk olur bende

Seni düşüncelerime sığdıramam ki

Elimde oynatamam ki seni

Beni aşkımla 

Bir başıma bırakıp gittiğin gibi

Seni terkedip, yokedip

Hayatını bir damara bağlayıp

Gidemem ki

Gözlerim yörüngene giremez ki

Yanar, kavrulur, kül olur

Doya doya seni seyredemez ki

Küllerim uçuşup

Saçlarına konduğunda

Anlar mısın? hisseder misin?  ki beni

Yangınlarıma yetişemedin

Şimdi çıka gelsen

Neye yarar ki

Buda ne ki

İçimi sana dökmeye

Kelimeler yetmez ki', 'Kalbinin parolası yok ki bende Kapını çalamam kolum kalkmaz ki Sesim çıkmaz ki Kapının arkasından sana seslenemem ki Bedenim hapsetmiş yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Ali Baydere']::text[], 8.5, '{"poet":"Ali Baydere","poet_slug":"ali-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/buda-ne-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırımlar', 'kaldirimlar-ali-baydere-buyik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaldırımlar,

O karanlık sokaklarda yürürken

Bana eşlik eden kaldırımlar.

Sanki yalnızlığımı hissetmiş gibi

Hep yanımda,uzanıp giden kaldırımlar.

O sokak lambasının ışığıyla,

Gölgemin birleştiği kaldırımlar.

Nereye gitsem,hangi sokağa sapsam

Hep karşıma çıkan kaldırımlar.

Parçalanmış kalbimin etrafa saçılan

Kırıntılarıyla izimi bulan kaldırımlar.', 'Kaldırımlar, O karanlık sokaklarda yürürken Bana eşlik eden kaldırımlar. Sanki yalnızlığımı hissetmiş gibi Hep yanımda,uzanıp giden kaldırım...', ARRAY['Türk Edebiyatı','Şiir','Ali Baydere']::text[], 8.5, '{"poet":"Ali Baydere","poet_slug":"ali-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kaldirimlar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden hala?', 'neden-hala-lokman-ali-yavuz-sqwa3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep sana sığındığımı zannediyorum

Sesini duyduğumda neden hala.............? 

Ağlamak istediğimde, 

Sevinçlerimde neden hala......? 

Burukluğumda neden? 

Her sevgi sözcüğünde neden hala? 

Her özlem sözcüğünde neden? 

Neden adının ilk harfiyle başlayan

Sözcüklere bakıyorum hala? 

Gitsem de uzaklara, 

Neden, gönlüm kapından geçiyor hala? 

Bütün ‘en’ lerimde sen çıkıyorsun.

Sana ait bir özel ‘dil’im var hala? 

Söylemek istemesem de hala,

Biliyorum, kendimi kandırıyorum işte.', 'Hep sana sığındığımı zannediyorum Sesini duyduğumda neden hala.............?  Ağlamak istediğimde,  Sevinçlerimde neden hala......?  Buruklu...', ARRAY['Türk Edebiyatı','Şiir','Lokman Ali Yavuz']::text[], 8.5, '{"poet":"Lokman Ali Yavuz","poet_slug":"lokman-ali-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/neden-hala-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğmeler', 'dugmeler-lokman-ali-yavuz-1i03g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sana  kapatırlar.

Beni bana kapatırlar.

Bu düğmeleri yapanlar hiç aşık olmadılar mı? 

Neden sevgilileri birbirine kapatan düğme yapmazlar?', 'Seni sana  kapatırlar. Beni bana kapatırlar. Bu düğmeleri yapanlar hiç aşık olmadılar mı?  Neden sevgilileri birbirine kapatan düğme yapmazl...', ARRAY['Türk Edebiyatı','Şiir','Lokman Ali Yavuz']::text[], 8.5, '{"poet":"Lokman Ali Yavuz","poet_slug":"lokman-ali-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dugmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaklar Aşktır, Aşklar Yasak', 'yasaklar-asktir-asklar-yasak-sair-dijraber-di0zy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YASAKLAR AŞKTIR, AŞKLAR YASAK

Yasaklar ortasında duyulan habersiz aşk

Mayın tarlasında gözü bağlı yürümektir

Fark yoktur arada

Bakmak yasaktır sevgiliye

Dokunmak yasak

Yanında olmak

Ve tutamamak ellerini

Aynı kadehten, aynı anda

Zehri ve şarabı yudumlamak kadar sarsıcı

Ve yaşamla ölüm arasında

Mekik dokumak kadar ölümcülüdür

Yaşamak birlikte

Arada Berlin duvarlarıyla

Aynı dünyada

Farklı galaksileri solumak

Sınır komşusu

İki düşman

Aslında dost devleti oynamak gibi tehditvari! 

Yasaklar ortasında ümitsiz aşk

Çöle tek bir damlanın düşmesini

Sabır ve sabırsızlıkla asırlarca beklemektir.

Oysa bir gülüş

Tenine ufak bir dokunuş

Belki soluğunu yakından hissederiz

Fazlasıyla yetecektir

O çölü kasırgaya boğmaya.

Yeter de artar bile

Bu şehirde çıldırmış bir tanrı var dedirtmeye….

İşin en mayınsı tadı ise 

Damarlarını depremler döverken

Bütün hücrelerin enkaz altındayken

Bütün sevinçlerini,

Acılar okyanusundan saldıran

Keder dalgaları yutarken

Senin bunları kimseye anlatamaman

Bu aşk baştan yasaktır,

Yasaklanır mı hayat? 

Ama yasaktır işte aşkın

Duyguların sahipsizdir,

Hiç kimse arkasında duramaz tehlikeli hislerinin

Yıkımı kimse paylaşamaz

Sen severken yuvasında mutlu bir kuşu

Kimse göze alamaz sırrını saklamayı,

Sen ve içindeki canavar

Kimsesiz iki sokak çocuğusunuzdur.

Aşkın öcü gibidir, en büyük günah tanrılarına karşı

Anlatmaya kalksan, tufan olur iki nehir arası

Oysa ne sen suçlusundur severken

Ne de o aşk günahkar bir çocuk

Bunu sen yaşar

Sen anlarsın.

Ve inadına taşırsın onu

Büyütür, okşar, sever

Acısını çekersin.

Yasaklı dinamitlenmiş aşklar

Katman katman koparır ruhundan ömrünü

Ve sen

Hiçbir zaman

Bir parçasını bile

O yarin avuçlarına bırakamazsın

SUÇTUR! 

YASAKTIR BU AŞK! 

Kalemi asırlar öncesinden kırılmıştır.

				28.12.2004/dijraber', 'YASAKLAR AŞKTIR, AŞKLAR YASAK Yasaklar ortasında duyulan habersiz aşk Mayın tarlasında gözü bağlı yürümektir Fark yoktur arada Bakmak yasakt...', ARRAY['Türk Edebiyatı','Şiir','Şair Dijraber']::text[], 8.5, '{"poet":"Şair Dijraber","poet_slug":"sair-dijraber","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/yasaklar-asktir-asklar-yasak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lâğım Fareleri', 'l-gim-fareleri-nihat-malkoc-huuz3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Onca lâğım faresi kemiriyor ruhumu

Süsleyip sunduğunuz ideal hayat bu mu?', 'Onca lâğım faresi kemiriyor ruhumu Süsleyip sunduğunuz ideal hayat bu mu?...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/lagim-fareleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-ziya-nizam-zr0xg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçük bir çocukken

Masalları çok severdim.

Gözlerime uyku girmezdi

Masal dinlemediğimde.

Sonra kitaplarımı çok sevdim

Okumaktan hiç bıkmadım onları.

Şimdi de seni çok seviyorum.

Aynı masal prensesleri gibi

Sen de benim prensesimsin.

Hayallerimde yaşatıyorum seni.

Güneşten evler yapıyorum,

Yağmur camlı evler.

Denizler konduruyorum gözlerine.

Sonsuz kırlar seriyorum ayaklarına.

Rüyalar ülkesinde yaşıyorum seninle.

Bir derdim var yalnızca,

O da tüm bunları sensiz yaşamam.

			29.11.1997-Cumartesi

			20:26 Genç GM Çerkezköy', 'Küçük bir çocukken Masalları çok severdim. Gözlerime uyku girmezdi Masal dinlemediğimde. Sonra kitaplarımı çok sevdim Okumaktan hiç bıkmadım...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ruya-175-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak', 'yaprak-ziya-nizam-kgi0d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yaprak koptu

Sonbaharla dalından.

Gözyaşlarıyla uğurladı

Ağaç o can parçasını.

Yaprağa sorsan

Özgürlüktü nihayet yaşadığı.

Ağaç; öyle hafiflemiş,

Öyle boşluk hissetmişti ki

Yaprağın ayrıldığı anda.

Yapma diyemedi ona

Gitme diyemedi.

Sanki söylese hislerini anlar mıydı

O dik kafalı yaprak.

Yanlışlıklar bürümüştü gözünü

Ayrılınca dalından

Öleceği, biteceği hiç aklına gelmiyordu.

Gelse ne olurdu ki

Ağaç büyüktü, güçlüydü.

O dayanırdı yalnızlığa.

Kendisi ölse ne olurdu ki.

Bir zaman sonra anladı

Ağaç olmadan yaşayamayacağını

Anladı ama ne çare.

Dönemiyordu ki dalına.

Hem doğası böyleydi

Hem de dal kabul etmiyordu artık onu.

Ölecekti işte o da.

Her yalnız yaprak gibi.

			15.11.1997-Cumartesi

			20:59 Genç FM Çerkezköy', 'Bir yaprak koptu Sonbaharla dalından. Gözyaşlarıyla uğurladı Ağaç o can parçasını. Yaprağa sorsan Özgürlüktü nihayet yaşadığı. Ağaç; öyle ha...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yaprak-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ülke', 'bu-ulke-sair-dijraber-u68mx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BU ÜLKE

	Bu, ülkede yabancı,

Bu ülkede,

Ölüm yetişir bin yıllardır ekin niyetine

Harmanlarda toplanır canlar

Demir ökçelerle, bir bir ezilir başaklar.

	En üstte, yularları ellerinde tutan tanrılar

	Yabancı tanrılar var

	Ve başakları ezmekle görevli

	Tarla sahibi görünen

	İşbirlikçi (ihanetçi)  yerli tanrılar.

	En altta da; 

	Tanrılarına sonsuz minnetle bağlı

	Durmadan patoslanıp,

	Kanı, canından ayrılan

	Her şeyden habersiz başaklar

Bu ülkeye güneş doğmaz yabancı 

Başaklar harmanlananda

Oluşan pusulu hava seyrelir sadece

Görüş mesafesi artar.

Kıyımlardan artakalan 

Verimli mahsulün,

Sere serpe,

Ayrı gayrı

Yenilik manzarasından.

	

	Bu ülkede güneş,

	Ya tanrıların şişman vücutlarını 

	Bronzlaştırmak için vardır

	Onlar yudumlarken gasp ettikleri,

	Kumsallarda pahalı viskilerini

Ya da ham başakları

Yeni moda patosların

Damak tadlarına uydurmak üzere

Kıvamında sarartıp

Olgunlaştırmak için.

Bu ülkede,

Harmanlanmaktan bıkan başaklar var,

Sabah kıran, patosları dağıtan,

Ezildikçe sertleşen

Tanrıların mezelerine lokma olmamaya

Yeminli,

İnançlı başaklar

Yabanıl, zehirli otlar bellenmişti onlar,

Ne ilaçlar köklerini kurutabildi

Ne yolunmalar

Ne koparılmalar

Her başağında binlerce yeni muhalifler

Barındırırlar, temizlendikçe çoğalırlar.

	Tanrılar sevmez onları

	Mahsulün tacirleri de.

	Pürüzdürler çünkü onlar.

	Yüksek verimli

	Son model

	Makinalı sistematik tarım işleyişine

Bu ülkede Anneler var! 

Azrailin Vampirlerle avlanmaya çıktığı

Çığlıklarını duyuramayan

Öksüz gecelerden

Yeni güne ağıtlarla,

Evlatsız doğan.

	Ve, bu ülkede ÇOCUKLAR VAR YABANCI! 

	Bu dünyaya yetim düşen

	Küçücük yüreklerinde

	Koca dağlar büyüten çocuklar

	Zirvelerinde bütün tanrılara

	DİRENEN ÇOCUKLAR! 

Bütün yıpratmalara rağmen

Ruhlarında isyan kartallarını

Bilinçlerinde özgürlük bülbüllerini

Ve kalplerinde sevgi çınarlarını

Büyüten ÇOCUKLAR! ...

	21.11.2001/dijraber', 'BU ÜLKE 	Bu, ülkede yabancı, Bu ülkede, Ölüm yetişir bin yıllardır ekin niyetine Harmanlarda toplanır canlar Demir ökçelerle, bir bir ezilir...', ARRAY['Türk Edebiyatı','Şiir','Şair Dijraber']::text[], 8.5, '{"poet":"Şair Dijraber","poet_slug":"sair-dijraber","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/bu-ulke-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelince', 'sen-gelince-ziya-nizam-ockgh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gelince,

Değişiyor dünya

En sert kışlar bahar oluyor.

Yağmur susuyor, güneş şakıyor.

Doğa canlanıyor, bir hareket başlıyor yaşamda.

Sen gelince hayat geliyor.

Sen gelince,

Değişiyor zaman

Yıllar ay, aylar gün oluyor.

Saatler neşeyle ilerliyor.

Her dakikanın, her anın

Ayrı ayrı tadı çıkıyor.

Sen gelince hayat geliyor.

Sen gelince,

Değişiyor denizler

En azgın dalgalar

Sakinleşiyor,uysallaşıyor

Gözlerinden bir yeşil yayılıyor

En karanlık sulara.

Sen gelince hayat geliyor.

Sen gelince

Yüzüm gülüyor

Tüm dertlerim siliniyor sanki aklımdan.

En büyük acılarımı unutuyorum bir anda.

Kalbim bir değişik atıyor.

Sen gelince bana hayat geliyor.

Bu yüzden hep gel.

Hep gel ki ben yaşayabileyim.

			18.10.1998-Pazar

			20:11 Lapizza Çerkezköy', 'Sen gelince, Değişiyor dünya En sert kışlar bahar oluyor. Yağmur susuyor, güneş şakıyor. Doğa canlanıyor, bir hareket başlıyor yaşamda. Sen ...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-gelince-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizden Aldın,Kime Verdin?', 'bizden-aldin-kime-verdin-veysel-alkan-9yefj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüce Mevlam ne haldeyiz! 

Kayıp ettik doğru yolu.

Son sahnede en baş rolü,

Bizden aldın kime verdin? 

Ordunduk biz,savaşmıştık,

Haçlılarla boğuşmuştuk,

Nereleri feth etmiştik! 

Bizden aldın kime verdin? 

Ümmetimiz dört bir yanda,

Mazlum hepsi kaldı darda,

Önderliği,bu cihanda,

Bizden aldın kime verdin? 

Kalbimizden imanını,

Dilimizden tekbirini,

Güzelliğin cümlesini,

Bizden aldın kime verdin? 

Uveys der ki; elden gitti.

İsyan değil'' tövbe'' haddi,

Bu vatanı, memleketi,

Bizden aldın kime verdin?', 'Yüce Mevlam ne haldeyiz!  Kayıp ettik doğru yolu. Son sahnede en baş rolü, Bizden aldın kime verdin?  Ordunduk biz,savaşmıştık, Haçlılarla b...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bizden-aldin-kime-verdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ülkede', 'bu-ulkede-sair-dijraber-qebwl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BU ÜLKE

	Bu, ülkede yabancı,

Bu ülkede,

Ölüm yetişir bin yıllardır ekin niyetine

Harmanlarda toplanır canlar

Demir ökçelerle, bir bir ezilir başaklar.

	En üstte, yularları ellerinde tutan tanrılar

	Yabancı tanrılar var

	Ve başakları ezmekle görevli

	Tarla sahibi görünen

	İşbirlikçi (ihanetçi)  yerli tanrılar.

	En altta da; 

	Tanrılarına sonsuz minnetle bağlı

	Durmadan patoslanıp,

	Kanı, canından ayrılan

	Her şeyden habersiz başaklar

Bu ülkeye güneş doğmaz yabancı 

Başaklar harmanlananda

Oluşan pusulu hava seyrelir sadece

Görüş mesafesi artar.

Kıyımlardan artakalan 

Verimli mahsulün,

Sere serpe,

Ayrı gayrı

Yenilik manzarasından.

	

	Bu ülkede güneş,

	Ya tanrıların şişman vücutlarını 

	Bronzlaştırmak için vardır

	Onlar yudumlarken gasp ettikleri,

	Kumsallarda pahalı viskilerini

Ya da ham başakları

Yeni moda patosların

Damak tadlarına uydurmak üzere

Kıvamında sarartıp

Olgunlaştırmak için.

Bu ülkede,

Harmanlanmaktan bıkan başaklar var,

Sabah kıran, patosları dağıtan,

Ezildikçe sertleşen

Tanrıların mezelerine lokma olmamaya

Yeminli,

İnançlı başaklar

Yabanıl, zehirli otlar bellenmişti onlar,

Ne ilaçlar köklerini kurutabildi

Ne yolunmalar

Ne koparılmalar

Her başağında binlerce yeni muhalifler

Barındırırlar, temizlendikçe çoğalırlar.

	Tanrılar sevmez onları

	Mahsulün tacirleri de.

	Pürüzdürler çünkü onlar.

	Yüksek verimli

	Son model

	Makinalı sistematik tarım işleyişine

Bu ülkede Anneler var! 

Azrailin Vampirlerle avlanmaya çıktığı

Çığlıklarını duyuramayan

Öksüz gecelerden

Yeni güne ağıtlarla,

Evlatsız doğan.

	Ve, bu ülkede ÇOCUKLAR VAR YABANCI! 

	Bu dünyaya yetim düşen

	Küçücük yüreklerinde

	Koca dağlar büyüten çocuklar

	Zirvelerinde bütün tanrılara

	DİRENEN ÇOCUKLAR! 

Bütün yıpratmalara rağmen

Ruhlarında isyan kartallarını

Bilinçlerinde özgürlük bülbüllerini

Ve kalplerinde sevgi çınarlarını

Büyüten ÇOCUKLAR! ...

	21.11.2001/dijraber', 'BU ÜLKE 	Bu, ülkede yabancı, Bu ülkede, Ölüm yetişir bin yıllardır ekin niyetine Harmanlarda toplanır canlar Demir ökçelerle, bir bir ezilir...', ARRAY['Türk Edebiyatı','Şiir','Şair Dijraber']::text[], 8.5, '{"poet":"Şair Dijraber","poet_slug":"sair-dijraber","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/bu-ulkede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne belaymis su kellik', 'ne-belaymis-su-kellik-husamettin-guven-80oa4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayna gibi parliyor

Safki gozler aliyor

Kompleksede sokuyor

Ne belaymis su kellik

Eski hava olmuyor

Kafamda sac kalmiyor

Bayanlarmi bakmiyor

Ne belaymis su kellik

Kuafore giderim

Sabit tarife oderim

Basa geldi cekerim

Ne belaymis su kellik', 'Ayna gibi parliyor Safki gozler aliyor Kompleksede sokuyor Ne belaymis su kellik Eski hava olmuyor Kafamda sac kalmiyor Bayanlarmi bakmiyor ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-belaymis-su-kellik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
