INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasan’ dan Rubailer / 3 (Sabır)', 'hasan-dan-rubailer-3-sabir-ahmet-turan-altunsu-f8ci5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat zorlu bir sınavdır; dayan karındaşım dayan,

