INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Vur Öldür', 'vur-vur-oldur-hadi-onal-r4vkl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tükendi göz yaşlarım tek damla kalmadı gel gör

Elinde sevda hançeri vur bari vur vur öldür

