INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak İstiyorum', 'yasamak-i-stiyorum-hadi-onal-1my7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamak istiyorum,yaşamak yeniden

Uçurtmamla yükselip gökyüzüne

İzin alarak ay dededen

Çuvallar dolusu yıldız toplamak

Sonra bir bir keserek yıldızları

Yollara serpiştirmek

Yaşamak istiyorum,yaşamak yeniden

Körebe oynamak, top koşturmak

Gülmek katıla katıla salıncaklarda

Ve sevmek riyasız, masum

Çirkinliklere kapalı

Güle kucak, yalansız,derinden

Yaşamak istiyorum,yaşamak yeniden

Aşık olmak sırılsıklam

Tutmak ellerini sevgilimin

Tüm saatleri durdurup

Bulutlarda ıslanmak

Yaşamak istiyorum,yaşamak yeniden

Olacaklardan haberli

Hatalardan ders alarak

Şansa yer vermeden

Yaşamak istiyorum,yaşamak yeniden.', 'Yaşamak istiyorum,yaşamak yeniden Uçurtmamla yükselip gökyüzüne İzin alarak ay dededen Çuvallar dolusu yıldız toplamak Sonra bir bir keserek...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yasamak-istiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kofik', 'kofik-hadi-onal-vtq56', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İplere düzülürsün 

Ne güzel süzülürsün 

Gün vurur büzülürsün 

Evümün aşı kofik 

Sofranın başı kofik 

Oy kofik canım kofik 

Rüzgar ile hop hop fik 

Yazın son dönümünde 

Balkonun süsü kofik 

Balcanın acı çalar 

İsotunda lezzet var 

Herkes bülsün aşikar 

Evümün aşı kofik 

Orcik gardaşı kofik 

Oy kofik canım kofik 

Açtın midemde gedik 

Ele bi öskedim ki 

Sana gurban bin gidik 

Ocağ başında kürsün 

Gış geldi mi üşürsün 

Fidoş seni bişürsün 

Evümün aşı kofik 

Sarmanın eşi kofik 

Oy kofik canım kofik 

Gohusu sanki kekik 

Guşhanada duruşu 

Hemi magrur hemi dik 

Gadan alam gel hele 

Kendini yağa bele 

Midemiz sahan köle 

Evümün aşı kofik 

Ezbet sırdaşı kofik 

Oy kofik canım kofik 

Bulgur sende gıllorik 

Sen aşların veziri 

Çekemez seni lobik 

İri köfte lengerde 

Sırın galsın kilerde 

Ano kofiğim nerde 

Evümün aşı kofik 

Ustalık işi kofik 

Oy kofik canım kofik 

Seni almaz her kodik 

Guddeler çatlasınlar 

Çıhında açan bubik 

Gakko göze gelmesin 

Kimse hımiklenmesin 

Onda her türlü besin 

Evümün aşı kofik 

Sininin düşü kofik 

Oy kofik canım kofik 

Sana bu mıllapotik 

Gohusuna bayılur 

Süyünkte gezen pisik 

Selin ağzı tutulur 

Elin ağzı tutulmaz 

Kofiksiz dügün olmaz 

Evümün aşı kofik 

Fetir yoldaşı kofik 

Oy kofik canım kofik 

Ardından oldum hışik 

İçli köfteden sonra 

Sen göynümde gıngılik 

Erişte, eşbabiye 

Haber salın bibiye 

Toplanın Mezire’ye 

Evümün aşı kofik 

Sofranın başı kofik 

Oy kofik canım kofik 

Kimse çekmesin yerik 

Ververan etmeyin ha 

Size düşer bi kırtik.', 'İplere düzülürsün  Ne güzel süzülürsün  Gün vurur büzülürsün  Evümün aşı kofik  Sofranın başı kofik  Oy kofik canım kofik  Rüzgar ile hop ho...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/kofik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yağmur Yağıyor Üstümden Üstünüze', 'bir-yagmur-yagiyor-ustumden-ustunuze-arif-emrah-toyoglu-6ybmh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'be ne dedim. 

birşeyler mi fısıldadımda koca dünya beni duydu. 

birşeyler mi ters gidiyor yoksa. 

yaşamım mı bu? 

beynim neden ağrıyor. 

sizler kimsiniz. 

beni bilirsiniz herhangi birisiyim. 

neden herkez her söylediğime bir anlam katıyor. 

onlar benim sözlerim. 

sadece bana ait. 

burada hiçbir işim yok. 

tek yaptığım uğramak. 

arasıra uğramak. 

güneş neden hergün doğuyorsa bende öyleyim işte. 

birini sevmek mi. 

aşık mı olmak. 

kime.. neye.. 

belki aradığınız budur. 

evet çok zayıfım. 

evet silah beni öldürebilir. 

ben hiçbirşey istemiyorum. 

hiç bir şey.............

deli gibi  bir çift göz evet. 

memnun oldunuzmu.

evet adres belli.....

kadın.

bir heykel bir ütopya

ne bileyim işte bir şeyyyyy

heykeltraşın yaptığı

bir taş parçası sadece,

neden anlamıyorsunuz....

yontuldukça güzel....

artık bu denli saldırıyorsunuz

hayallerle

belki.....

hayır, kalbiniz değil elinizdeki...

ilkel bir atom parçası

bir kurşun.

buraya kadar mı deme mi bekliyorsunuz.

''şimdi şiir mi bu''

neden şair mi yazdıda böyle düşünüyorsunuz

sen neden erken kalkıyorsun? 

sen kiminle konuşuyorsun? 

sen ne yapmaya çalışıyorsun? 

hangi ordu karşımda? 

kaç kişisiniz? 

bitmedi şu muhabbetler

bir isyan öylemi.

çok mu mutlu oldunuz...

öyleya

ölesiye bir salgın hastalığa saplandım

ortanızdayım diye

size benziyorum diye.....

daha yaşımı hesaplamadan karşınızdayım işte

ben.....

ben işte o binlercesinin aklına bile gelmeyen.

ben ölüyorum........

geberircesine...

aslında ölüyordum

şimdi

bir ölüyüm sadece...

hey! ! ! ! 

beni diriltemezsiniz....', 'be ne dedim.  birşeyler mi fısıldadımda koca dünya beni duydu.  birşeyler mi ters gidiyor yoksa.  yaşamım mı bu?  beynim neden ağrıyor.  siz...', ARRAY['Türk Edebiyatı','Şiir','Arif Emrah Toyoğlu']::text[], 8.5, '{"poet":"Arif Emrah Toyoğlu","poet_slug":"arif-emrah-toyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/bir-yagmur-yagiyor-ustumden-ustunuze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemiler', 'gemiler-sair-pirinc-zu0uh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'birer yalnız gemiyiz maviliklerde yüzen 

şaşırıp rotamızı kayboluruz 

hep çok erken buluruz yolumuzu 

fırtınadan sonra dinginleşir duruluruz 

zakkum rengı bır ruzgar 

hızla geçip giden zaman 

her maceraya acılırken bir liman ararız 

bulunca orada arınırız yeni yolculuklar için 

İnsan düşünür 

At, köpek düşünür 

Balık düşünmez 

cünkü bilir.', 'birer yalnız gemiyiz maviliklerde yüzen  şaşırıp rotamızı kayboluruz  hep çok erken buluruz yolumuzu  fırtınadan sonra dinginleşir duruluruz...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gemiler-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun', 'yorgun-sair-pirinc-zm7no', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kestirme yollardan yorgun 

serseri oklarla delik deşik mormaviliğim 

sağa sola sapmadan 

sonuna kadar dümdüz 

Şehriyarın binbir gece aşklarından 

ne bir yüz ne de bir iz.', 'kestirme yollardan yorgun  serseri oklarla delik deşik mormaviliğim  sağa sola sapmadan  sonuna kadar dümdüz  Şehriyarın binbir gece aşkları...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yorgun-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Alışkanlık', 'yeni-aliskanlik-sair-pirinc-hlpp7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1

.... sanki hep vardın 

hep yanımdaydın 

sanki her şeyi biliyorsun ve susyorsun 

bu yeni...... 

buna da alışırım 

nelere alışmadım...........', '1 .... sanki hep vardın  hep yanımdaydın  sanki her şeyi biliyorsun ve susyorsun  bu yeni......  buna da alışırım  nelere alışmadım............', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yeni-aliskanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya', 'papatya-sair-pirinc-g5iw0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '2

……teninde taze beyaz papatyalar 

dalında dişlediğim yaban çilekleri 

soyunup uzanıverdin mi yanıma 

durdururum tüm saatleri... 

.................', '2 ……teninde taze beyaz papatyalar  dalında dişlediğim yaban çilekleri  soyunup uzanıverdin mi yanıma  durdururum tüm saatleri...  .............', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/papatya-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahane', 'bahane-sair-pirinc-bx758', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'başbaşa kaldıgımız sayılı vakitlerde 

konuşmaktan yorulup sevişmekten bitkin düştüğümüzde 

kapanıyorsa gözlerim 

- ki biliyorum bana kızıyorsun 

sevgilim, uyumak değil, inan 

-o anı gözkapaklarıma çizmek içindir', 'başbaşa kaldıgımız sayılı vakitlerde  konuşmaktan yorulup sevişmekten bitkin düştüğümüzde  kapanıyorsa gözlerim  - ki biliyorum bana kızıyor...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bahane-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalan....', 'kalan-arif-emrah-toyoglu-hhf6b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seyir defterimde inceldiği yerden kopan

ve yerde birsin gökte kim? 

adını ezberledim, ezberim batsın...

gemiler, kalmadı efkar

hayalini üstüme çekip uykuya dalınca

sahil denize vuruyor

ve ilk defa

ilk defa bir mezar senle anılıyor

bu aşk epey battı...

ve fazlaca sabıkalandı be sevda..

diller kaince

civar ve saçların aciz bir kırbaç

yerim yurdum sen..

parmaklarım sen...

kaburgam sen...

ve melodimsin

tırnaklarımı bir işkence faslında

ciğerlerimden söküp 

sözlerimden bütün harfleri silen

girdabım

sana artık kim gelecek

içindeyim...

damarlarında dolaşan kan değil

benim çürümüş etlerim

elini kesince acıyan

asıl benim kesikliğim...

artık rüya bile değilim

korkunç ve sabahı tazeleyen

su değil içtiğin benim 

ağladığında kim olacak yanağında çırpınan

aynaya baktığında kimi göreceksin

yalvardığında kim seslenecek sana

sustuğunda herşey neden senden konuşacak

seni Tanrı''ya benzettim

şimdi kim seni sorgulayacak

sen nerde yaşıyacaksın

dünya çeperlerinde parçalandı

ya evrende kim oluyormuş

varlık senden başkası değil

sen artık bu söylediklerimin hiçbirini haketmiyorsun

belki ben tutturmuşum

sende kaybettiğim

beni seviyormuşum

sen de kalmadın geride

bu aşk kaldı.........................................

geride...................................................

mavi gözlerinin içinde.........................', 'seyir defterimde inceldiği yerden kopan ve yerde birsin gökte kim?  adını ezberledim, ezberim batsın... gemiler, kalmadı efkar hayalini üstü...', ARRAY['Türk Edebiyatı','Şiir','Arif Emrah Toyoğlu']::text[], 8.5, '{"poet":"Arif Emrah Toyoğlu","poet_slug":"arif-emrah-toyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kalan-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delirmiş Sevinçlerim', 'delirmis-sevinclerim-hatice-bediroglu-qgw3l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oturmuşum sahilde kumlara.

Yosunların okşayışlarına,

Terk etmişim ayaklarımı.

Dur durak tanımayan, 

Beynimin içinde sen.

Dalgaların köpüklerinde,

Muzip gülüşlerin….

Martılar suskun,

Uzaklara demir atmış motorlar,

Haydi rastgele,

Taşsın ağlardan balıklar.

Ziyafete koşuşsun,

Çığlık çığlığa martılar.

Bu sabah…

Gördüğüm hiçbir olumsuzluk,

Azaltmıyor içimdeki yaşam sevincini,

Çünkü kaynağı sensin.

İçimde çoğalıp,

Dev dalgalara dönüşüyorsun.

Öyle keyifliyim ki…

kıpır kıpır delirmiş sevinçlerim.

Sevmek özlemek ve istemek,

Tüm bunlara sahibim ne güzel.

Bir çay söylüyorum,

Buram buram dumanları tüten.

Lezzetlice yudumluyorum.

Boğazımdan aşağıya akışını dinliyorum.

Sessizce…

Ürpertimi alıp götürüyor sıcaklığın.

Uçarı ruhumu alıp,

Atlıyorum son moda bisikletime.

Dalıyorum yüzleri asık insanların içine.

Önüme gelene selam veriyorum.

Gününüz aydın olsun, gününüz aydın olsun.

Gözlerimde gözlerin….

Dudaklarımda akşamdan kalma tadın.

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Oturmuşum sahilde kumlara. Yosunların okşayışlarına, Terk etmişim ayaklarımı. Dur durak tanımayan,  Beynimin içinde sen. Dalgaların köpükler...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/delirmis-sevinclerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Soldu...', 'hersey-soldu-osman-ergun-zirs2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinden okuduğum şiiri,

Hiçbir şair yazmadı.

Yüreğimin arzusunu,

Akıl mantık almadı.

Bir sevda ki yaşadığım,

Bilen duyan olmadı.

Geçti gitti bir ömür,

Her şey soldu.

Acı hatıralardan ve

Sana olan aşkımdan,

Başka bir şey kalmadı.

Y.Tar:2005/Ankara', 'Gözlerinden okuduğum şiiri, Hiçbir şair yazmadı. Yüreğimin arzusunu, Akıl mantık almadı. Bir sevda ki yaşadığım, Bilen duyan olmadı. Geçti g...', ARRAY['Türk Edebiyatı','Şiir','Osman Ergün']::text[], 8.5, '{"poet":"Osman Ergün","poet_slug":"osman-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hersey-soldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyi?', 'neyi-osman-ergun-wrpr3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman bileceksin? 

İçindeki seni sıkanı, ne zaman

Her gece düşünüyorsun

Neyi? 

Bir diyebilsen düşündüklerini

İçin o zaman boşalacak belki.

Bir ağlayabilsen doyasıya...

İşte senin derdinin çaresi./2004

Y.Tar:2005/Ankara', 'Ne zaman bileceksin?  İçindeki seni sıkanı, ne zaman Her gece düşünüyorsun Neyi?  Bir diyebilsen düşündüklerini İçin o zaman boşalacak belki...', ARRAY['Türk Edebiyatı','Şiir','Osman Ergün']::text[], 8.5, '{"poet":"Osman Ergün","poet_slug":"osman-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nehir', 'nehir-gulsen-gonenc-nez73', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaynağını bilmediğim mutsuzluklar nehrinde,

Zamana tutsak anılarımı yıkıyorum.

Kirler akıyor, izler bir türlü çıkmıyor.

Neyin karşılığı ödendiği belirsiz bedellerden mandallarla,

Tutku ağaçlarına asıyorum.

Etken anlamsızlıklar dolduruyor, edilgen ruhların boşluklarını artık.

Böyle daha iyiyim.', 'Kaynağını bilmediğim mutsuzluklar nehrinde, Zamana tutsak anılarımı yıkıyorum. Kirler akıyor, izler bir türlü çıkmıyor. Neyin karşılığı öden...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nehir-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret', 'nefret-gulsen-gonenc-80104', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazı zamanlarda kendinden nefret edebilmelisin,

Bir caniymiş gibi

Acımasız; tiksinti verici,

Gizemli; neden katlettiğini anlamaya çalışır gibi.

Nedenlerini aramalısın kendini bulmak için.

İnsan kendinden neden kolay nefret edemez, bilir misin? 

Çünkü sevgi, nefretin büyük kardeşidir.', 'Bazı zamanlarda kendinden nefret edebilmelisin, Bir caniymiş gibi Acımasız; tiksinti verici, Gizemli; neden katlettiğini anlamaya çalışır gi...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nefret-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın Kokar', 'kadin-kokar-erbil-kutlu-ao4dg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadın kokar dostum,

Yaşı kaç olursa olsun kokar.

İster kapkara çarşafa sarmalansın,

İster sereserpe uzanmış olsun bir yere.

Salar kokusunu istediği erkeğe veya erkeklere; 

Hatta anlamazsın, kadınlara bile.

Ondan kadın kıskanır, kıskanılıyorsa da

Kızsa da, için için bundan çok büyük zevk alır.

Kıskanılmaktır, kadını tahrik eden, yoldan eden,

İstenildikçe asla dinmez heyecanı, hep çocuk gibidir.

Bir bakışı, elinin, ayağının kıpırdaması

Geçtim baldırını, bacağını; kokusunu yayar etrafa...

Kadın ne güzel bir varlıktır, can verir dünyaya,

Senin hücrelerinden, kendi hücrelerinden bir meyve...

İşte onun sana verebileceği en yüce zevk budur bence,

Çünkü o çok mutlu olur, oda onunla çocuk olur.

Sen sadık ol ona, onu yegane dünyan kıl yeter,

Görbak o koku nasılda yalnız sana gelecek.

Kadın kokar dostum engelleyemezsin.

Hep hayatı boyunca çıtır olur o, sakın aldanma,

Yalnız gözlerine bak yeter; 

O her bakışında, seni kendine, kendini sana daima aşık eder.

Kadın gül kokar, papatya kokar...

Kadın aşk, sevgi... özellikle şehvet kokar...

02/06/2005/prş – 19.30', 'Kadın kokar dostum, Yaşı kaç olursa olsun kokar. İster kapkara çarşafa sarmalansın, İster sereserpe uzanmış olsun bir yere. Salar kokusunu i...', ARRAY['Türk Edebiyatı','Şiir','Erbil Kutlu']::text[], 8.5, '{"poet":"Erbil Kutlu","poet_slug":"erbil-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kadin-kokar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba! Bu Ben miyim?', 'acaba-bu-ben-miyim-huseyin-erdogan-5f4eo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu gün hava soğudu birdenbire

yüreğime de karakış girdi sanki

tir tir titriyorum inan gittiğinden beri

artık benim için mevsimler bire indi

zaten benim tek korkum da sensizliğimdi

beni ayazlarda bırakıp da neden gittin? 

hani benim solmayacak baharım sendin

bir günde niye beni böyle uçurumlara ittin? 

gönlümdeki çiçekleri kuruttun bir gecede

beni sabaha dek korkuttun durdun düşlerimde

söyler misin ben nasıl dayanırım buna ömrümce? 

beni böyle darmadağın edersen gündüz gece

kendimde değilim sevdiğim takatsizim halsizim

gittin gideli soruyorum kendime acaba! bu ben miyim? 

                                              14.06.2005', 'bu gün hava soğudu birdenbire yüreğime de karakış girdi sanki tir tir titriyorum inan gittiğinden beri artık benim için mevsimler bire indi ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/acaba-bu-ben-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-erbil-kutlu-95e2b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimsiniz Sizler,

Ne işiniz var benim hayatımda? 

Ne zaman girseniz hayatıma alt üst ediyorsunuz,

İki dirhem huzurum var,

Onu da baltalamaya doymuyorsunuz...

Ne zaman gülse şu yüzüm,

Hep bir hüznü yaşattınız.

Nasıl yaptınız, nasıl ettiniz anlayamıyorum,

Gülerek ağlamayı öğrettiniz.

Ki sizler, ağlar iken gülenlersiniz bana.

Ağlamayı bilmemiş, hep gülmüşsünüz işte.

Bir yudum su bile istemedim ki sizlerden,

Sadece siz beni, bende sizi bilmeyeyim dedim,

Hiç erinmediniz; 

Kendi mutluluğunuz için hayatımı piç ettiniz...

Kimsiniz lan siz,

Ne işiniz var hayatımda? 

Anladım, haklısınız; 

Benim acımda, kederimde

Sizlerin mutluluğu var...

Oysa ki, benim mutluluğum,

Siz mutluysanız mutluluktu...

13/06/05/pzt – 23.00', 'Kimsiniz Sizler, Ne işiniz var benim hayatımda?  Ne zaman girseniz hayatıma alt üst ediyorsunuz, İki dirhem huzurum var, Onu da baltalamaya ...', ARRAY['Türk Edebiyatı','Şiir','Erbil Kutlu']::text[], 8.5, '{"poet":"Erbil Kutlu","poet_slug":"erbil-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mutluluk-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinaslı Dörtlükler', 'cinasli-dortlukler-guven-tahtakiran-ev0gu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yatan karı yatan karı

Yer yutar yatan karı 

Karı güneş eritir 

Yiğidi yatan karı 

Yer beni yer beni 

Hatalıysam yer beni 

Özüm toprak ne deyim

Hem besler hem yer beni 

Bir gülde bak bir gülde bak

Bülbül öter bir gülde bak 

Dünya gülistana döner 

Hak der ise bir gülde bak

19 KASIM 2002 / SİVAS', 'Yatan karı yatan karı Yer yutar yatan karı  Karı güneş eritir  Yiğidi yatan karı  Yer beni yer beni  Hatalıysam yer beni  Özüm toprak ne dey...', ARRAY['Türk Edebiyatı','Şiir','Güven Tahtakıran']::text[], 8.5, '{"poet":"Güven Tahtakıran","poet_slug":"guven-tahtakiran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cinasli-dortlukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haleti Ruhiyem', 'haleti-ruhiyem-guven-tahtakiran-p78sn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cehennem ateşi dudaklarında

Güzel gözlerinde cenneti gördüm

Zülfünün teline bağlandı gönlüm 

Ateşi aşkını kalbime gömdüm

1980 / AKDAĞMADENİ', 'Cehennem ateşi dudaklarında Güzel gözlerinde cenneti gördüm Zülfünün teline bağlandı gönlüm  Ateşi aşkını kalbime gömdüm 1980 / AKDAĞMADENİ...', ARRAY['Türk Edebiyatı','Şiir','Güven Tahtakıran']::text[], 8.5, '{"poet":"Güven Tahtakıran","poet_slug":"guven-tahtakiran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/haleti-ruhiyem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine bana gel', 'yine-bana-gel-yasin-temo-ojtoe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yar; 

Yine bana gel.

Akşam üstü güneş gruba meylederken,

Yine bana gel

Sessizlik etrafı büyülerken

Ay ışığı gözleride yansısın,

Yüreğim içime akıp giderken

Yine bene gel

Hasretim renklerine ayrılsın

Malıçta akşam oluyorken yar yine bana gel', 'Yar;  Yine bana gel. Akşam üstü güneş gruba meylederken, Yine bana gel Sessizlik etrafı büyülerken Ay ışığı gözleride yansısın, Yüreğim içim...', ARRAY['Türk Edebiyatı','Şiir','Yasin Temo']::text[], 8.5, '{"poet":"Yasin Temo","poet_slug":"yasin-temo","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yine-bana-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-gokten-aydogdu-lu51f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve ben...

Hala sensiz

Hala üşüyorum 

Bırakmıyor yakamı sevdan 

Bu şehrin sokakları ıssız 

Buz tutuyor yüreğim 

Bilmelisin sevdiğim 

Karabasanım oldu kışların 

Donduran bakışların... 

Gelir misin! 

Vakit çok geçmeden 

Ve hala...

Yangınlarda

Üşüyor yüreğim! .', 'Ve ben... Hala sensiz Hala üşüyorum  Bırakmıyor yakamı sevdan  Bu şehrin sokakları ıssız  Buz tutuyor yüreğim  Bilmelisin sevdiğim  Karabasa...', ARRAY['Türk Edebiyatı','Şiir','Gökten Aydoğdu']::text[], 8.5, '{"poet":"Gökten Aydoğdu","poet_slug":"gokten-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/usuyorum-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kur’an-ın Sinyalleri (Düz yazı)', 'kur-an-in-sinyalleri-duz-yazi-ali-kilic-kakiz-fygxr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İslam ilim,irfan ve medeniyet dinidir. Çünkü İslam asırlar ötesinin dinidir.Yerlere ve gölere sığmayan ulvi tek dindir. İslam şablon dini değildir. Yer yüzünde yaşayacak son insana kadar, bu din baki olacak. Allah bu dini sigortalıyor. Allah’ın takdirini bozabilecek kimdir? Bizim gibi fanilere ne oluyor? Allah şöyle buyuruyor:

‘Hiç şüphesiz Kur’an-ı biz indirdik. O’nu tahrif ve tağyirden biz koruyacağız’.

Hicr sûresi,ayet: 9

Maneviyat önderleri bulunmayan toplumlarda, Allah’dan korkanlara rastlanamaz.

Resûlullah s.a.v. asırların güneşiydi. Peygamberimiz varken başka kandilleri aramaya ihtiyaç yoktu. O güneş batıktan dan sonra, dava arkadaşları Onun nuruyla meseleri çözdüler. Hatemül enbiyanın nurunu gören gözler bu alemden göçtükten sonra,ortalığa karanlıklar çökmeye başladı. akabinde içtihat ve kıyas gündemi geldi.

İslam asırların diniyse, geleceğe de sözünü geçirecekse yarınlara dönük dört başı mamur ehliyetli ve liyakatli insanların kollarını sıvaması gerekmektedir.

Günümüzde ki meseleri körün el yardımıyla düğüm çözdüğü gibi çözmeye başlıyoruz.Bizde ki bir kısım his ûleması Kur’an-ı Kerim den bir ayet cımbızlarlar ondan sonra,bir tek ayetle ahkam keserler. Vebalini kendilerinden öncekilerin sırtına sarmışlar fakat,kitaplara kendi adlarını yazmışlar.

Kendi kusurlarımızla bu dinimizi gölgeledik. Tarifleri büyüttük,insanları küçültük. İnsan oğlu gerçekten tuhaf bir varlıktır.

Denizi bahçesinde ki bostanının göleği zanneden zihniyet, bir gecede denizi boşaltmaya kalkar. Su adına evinde ki testiden başka bir şey görmemiş kişiye denizi nasıl anlatırsınız. Yer ile gök arasını bir adamın boyu kadar gören zihniyete miraç’ı anlatabilirmisiniz.

Bu muhteşem kainat her zaman her an ilâhi emre ve iradeye muhataptır.

Akıllara durgunluk veren ilmi ve tekniği aciz bırakan semaları ve fizik ötesini tanımadıkça insanoğlu, Kur’an anlayışı daima eksik olacaktır.

Bakınız, Ruh ve Cebrail Cenab-ı Hakkın huzuruna 50 000 senede çıkarlar. Dönüşleri de bir o kadar sürer.Vahiy meleğinin yer yüzünden Allah’ın huzuruna bir defa çıkıp dönmesi için tam 100 000 yıla ihtiyaç vardır.

Bütün bu tanımlardan sonra hayat kitabı olan Kur’an-ı Kerim bize neler getirmiştir. Kur’an, başka alemlere sinyaller saçarak insanların dikkatini büyük yaratıcıya çekmektedir. Gaybın bir dili ve sırlarını anlatan Kur’an, İnsana,gayb perdesi altındaki eceline hazırlıklı ol mesajınıda vermektedir.

Ömür içinde ecelin,dünyanın içinde kıyametin gizli zikredilmesi de, aklın ve hikmetin bir gereğidir. Biz bunları umursamazsak,ellerimizi ovuşturmaktan başka bir şey yapamayız.

Kur’an-ı Kerimin genel atmosferini anlamak zorundayız. İnsan ilimle büyür rakamla değil. Bak baka bildiğin kadar semalara.O zaman anlarsın,zerre ile kürre arasında ki farkı.Ama gözler yorgun argın sahibine döner.

Mearicsuresi,Ayet: 4

`Melekler ve Cebrail miktarı ellibin yıl olan o derecelere bir günde yükselirler`.

Ayette ki manayı ancak düşünmekten beyni çatlayanlar,semaya bakmaktan gözleri aşınanlar anlar. Atlas döşekler de tatlı rüyalara dalanlar anlamazlar. Rabbimiz semayı temaşa etmeye çağırmaktadır. Çünkü, semaların ihtişamı fezanın derinlikleri ve fizik ötesi öyle üç beş bakmakla kavranacak cinsten değildir.

Hayat ancak dünya hayatıdır, yaşarız ve ölürüz,bizi ancak zaman helak eder, diyen o zihniyet, Peygamberimizin bahsettiği metafizik alemini inatlarından dolayı bir türlü kabul etmiyorlardı. Peygamberimiz buyuruyor ki:

‘Ben sizin görmediğinizi görür,duymadığınızı duyarım’. Sün. Tirmizi

Bütün beşeri ifadenin sınır ve imkanlarını aşan Kur’an-nın gücü hususunda bir kanaata varamayan Mekke müşrikleri terettütler içerisinde bocalıyorlardı.

Bu kitap baştan sona,Allah’ın birliğini vurguluyor,şirki kovuyor,tüm insanlara evrensel bir rahmet çağrısı yapıyor.

Teğabün suresi: Ayet,8

‘Allah’a Resulüne ve indirdiğimiz Nur’a iman edin’. Kıyamete kadar bütün insanlar bu ilahi sofranın davetçileridir. Allah bu dini ve kitabını koruma altına almıştır.En zayıf bir evde en büyük peygamberini,en şiddetlidüşmanlarından korumuştur.

Nahl suresi:Ayet,......

‘Biz Kur’an –ı sana her şeyin apaçık bir beyanı olarak indirdik’. Kur’an-ın üzerinde semavilik ve ilâhilik damgası mevcuttur. Bu güne kadar hiç bir beşer bunu taklide muvaffak olamamıştır. Fizik ötesi alem,kıyamet ve ahiret aklın tek başına işin içinden çıkabileceği türden bir mesele değildir. Allah her şeyi düzen ve ahenk içinde halk etmiştir. İnsanın eline,bir kitap önüne uyarıcı bir peygamber koymuştur. Kur’an-ın temel davası olan tevhid,insanlığı kesretten vahdete çıkarır. İnsan gayba açılmış duygularla doludur. Kur’an insana yaratılışın ve gaybın sırlarını anlatmıştır. Kur’an-ı cinler dinlediler iman ettiler. Dağlar Kur’an-ı işittiler inlediler......

Haşır suresi:Ayet, 21

‘Eğer Biz bu Kur’an-ı bir dağın üzerine indirseydik muhakkak ki o dağ Allah korkusundan baş eğmiş parçalanmış görürdün’.

Kur’an varlık alemini aydınlatan bir güneştir. Resûlün dava arkadaşları,Kur’an-ı itina ile okurlardı,her beş ayet okudukça,Allah ilim ve amel olarak ne buyurdu ona bakarlardı. Allah Onlarla dinini yücelti ve düşmanlarını onlarla susturdu.Siz onları görmüş olsaydınız onlara çılgın mecnun derdiniz. Fakat onlar sizi görmüş olsalardı size Müslüman demezlerdi.

Kaynaklar...........

                 Kuran-ı Kerim.. Muteber Hadis Kaynakları

                 İçki Uyuşturucu Sigara..Nuri Yazar.

Lessines / 2000', 'İslam ilim,irfan ve medeniyet dinidir. Çünkü İslam asırlar ötesinin dinidir.Yerlere ve gölere sığmayan ulvi tek dindir. İslam şablon dini de...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kur-an-in-sinyalleri-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesadüflerin Şiiri…', 'tesaduflerin-siiri-muammer-celik-6uch9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I.

**''Tesadüfmüş gibi karşılaşıversek bir caddenin en işlek yerinde”… 

**************** 

ve tanımıyormuşuz gibi 

geçiversek birbirimizin yanından 

sabaha kalksak en ıslak yerimizden 

başlasak güne  yaralı sol yanımızdan... 

II.

hep tesadüflerle karşılaştık

hep tesadüfleri yaşadık

ve yine bir tesadüf sonucu

geçip gidiyoruz bu dünyadan 

aşk ve sevdayı yaşamadan 

III. 

tesadüfen görmüştüm seni bir yerde 

tesadüfen okumuştum bir şiirini 

tesadüfen yazmıştım sana tüm şiirlerimi 

tesadüfen sevmiştim seni 

tesadüfen itiraf etmiştim sevgimi 

zorlanarak da olsa kendime... 

IV.

Hani diyorum ki, 

bir de tesadüfen 

 koyuverseler sen’le beni

...aynı mezara! ... 

Aman Allahım! ... 

Bu, tüm kainatin en güzel 

ve en büyük buluşması olurdu tesadüfen... 

Ve inan bana, 

yemin ederim ki,

tesadüfen de olsa 

bırakmazdım seni, 

bir daha ve asla o mezardan.... 

BirDeli

14.06.2005

(**  Nurten Altınok dostumun izni ile “Ben Mavi Sevdim Seni” isimli şiirinden ödünç alınmış bir dizedir.)', 'I. **''Tesadüfmüş gibi karşılaşıversek bir caddenin en işlek yerinde”…  ****************  ve tanımıyormuşuz gibi  geçiversek birbirimizin yan...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tesaduflerin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DALGALI ve SOĞUK RÜYAM', 'dalgali-ve-soguk-ruyam-mehmet-emin-yesilmen-cmi9s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecelerimin rüyasında görüyorum seni

Tohumunu istiyordum kalbime ekmek için.

Rüyam dalgalı ve soluk renkteydi, ve de soğuk...

Bana kurumuş dallar uzatıyordun

Yakıp ısınmam içinmiydi acaba.

Hayır, ben ateşle ısınmam

Yalnızlığın soğuğuna dayanamaz alevler...

Soluk renkteki rüyamda elini istiyordum

Elimi uzattıkça, uzaklaşıyordu görüntüler

Ellerim üşüyordu,

Ben üşüyordum....

Seni çağırıyordum soğukta,

Titriyordum,

Aç kalmıştım sana,

Sesime ses gelmiyordu,,,,

Bırakıyordum kendimi yerin dalgasına

Umursamıyordum

Ne kendimi,

Nede hiç bir şeyi.

Haricim bir sendin kalbimdeki....

Soğuk rüzgarlar esiyordu ayak izlerini silen,

Kumlar yüzümü kesiyordu önde.

Düz gidip azarlıyordum kalan diğrer yönleri.

Umudum pes edip yetiştirmendi kendine beni....

Dumanlı bulutta uçuyordu kanatlı yılanlar.

Sanki okuyordu biri fermanımı.

Dalgalı görüş ve soğuktur kalan ömür.

Öyle soğuk ki,

Yalnızlığın verdiği soğuktu...

____________________? 

Tanrım! 

Hep üşüyecekmiyim gecelerimin rüyasında?', 'Gecelerimin rüyasında görüyorum seni Tohumunu istiyordum kalbime ekmek için. Rüyam dalgalı ve soluk renkteydi, ve de soğuk... Bana kurumuş d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dalgali-ve-soguk-ruyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıkta', 'ayrilikta-firuze-keles-zgwbz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlık sensizliktir dostum

Yalnızlık sensizlik.

Ayrılık; yolcu etmek seni,

Özlemek ve beklemek…

Döneceksin

Ve güzel günler

Geri dönecek.

İlk defa, bir veda

Bu kadar huzurlu.

İlk defa, ayrılık

Böyle umutlu.

Bekliyorum

Ve biliyorum geleceksin.

Ve güzel günler gelecek…

İlk defa, hayalimde

Umutlu ve güzel bir gelecek…

		10.07.2003', 'Yalnızlık sensizliktir dostum Yalnızlık sensizlik. Ayrılık; yolcu etmek seni, Özlemek ve beklemek… Döneceksin Ve güzel günler Geri dönecek. ...', ARRAY['Türk Edebiyatı','Şiir','Firuze Keleş']::text[], 8.5, '{"poet":"Firuze Keleş","poet_slug":"firuze-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayrilikta-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Isyan Ertesi(Dersim''e)', 'bir-isyan-ertesi-dersim-e-diyar-serdar-yildiz-6089z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir isyan ertesiydi; 

Sevdalanmistik yasama 

Yüreklerimiz bir ceylanin ürkekliginde, 

Titrek, 

Ve bir o kadar deli, 

Namluya sürülen fisek gibiydi hani 

Tarihi desiyordum tirnaklarimla, 

Ciksin diye kiri pasi. 

Dagliyordum dermansiz yaralari, 

Eskiyaya cikarmislar adimizi,asi''ye. 

Ben bilirim nedendir asiligimiz, 

Bilirim bilmesine de yetmez ki gücüm 

Zalimin tankina,pervanelisine,tüfengine 

Düsünürüm Osmanlidan bu yana 

Ne verdiniz bana,ne istersiniz benden 

Hani verilen o sözler ve o sözleri veren 

Yüce efendiler nerdedirler,neylerler... 

O yüce efendiler Ankara''nin göbeginde 

Önlerinde rakilar mezelere gelince, 

Yakilacak yikilacak diyarlar ve asilacak canlar 

Zorlarim bellegimi,ne söz verdiler bize 

Daha dün kurtarabilme adina yardim dilenirken benden 

Ne olduda bugün düsmana kesiliverdim birden? 

Kürdistan''dayim diyen yüce türk degilmiydi? 

O degilmiydi iki halki carpistiran haindir diyen? 

Gidilirken bir yerlere imzalara, Kürt ve Türk icin diyen 

Kürt Ismet degil miydi? 

Sorarim ne tez unutuldu bunlar, 

Ne cabuk silindi belleklerinizde yakilan insanlar 

Kursuna dizilenler, 

Zorlayin derim hafizalarinizi, 

Yüzlesin derim o karanlik günlerle 

Ben hergün düsünürüm; 

Bellegimde seyidim ve alti yoldasi 

Samanpazari sessiz, 

Samanpazari utancini yasiyor tarihin 

Görüyor o görmez gözleriyle olani biteni 

Bak üc adim ötesi talan,vurgun ve 

Sürgün... 

Dumanlar yükseliyor köylerden 

Yanik et kokusu yakiyor genizleri 

Insanlar yakiliyor gözünün icine baka baka dünyanin 

Yakilacak elbet, 

Temizlenecek demis Ismet Pasa,daha 26 da 

Onay vermis yüce türk,temizleyin yakin yikin 

Adim basilmadik bir karis topragi kalmayana dek. 

Ol tarih böyle yasanmis iste; 

Ondandir adimiz eskiya, 

Ondandir adimiz asi... 

Halden anlamaz nerden bilsin derdimizi 

Görmüsmüdür acaba gözleri? 

Diri diri yakilan, 

Ve yakilirken dünyaya bos gözlerle bakan bir bebeyi 

Yada sahit olmusmudur acep? 

Kursuna dizilmesin diye yetiskinler, 

Babasi tarafinda bogulan, kirkindaki bebenin acisina? 

Budandir adimiz eskiya, 

Bundandir adimiz asi.. 

Bir isyanin ertesiydi 

Yinede sevdaliydik yasama 

Bellegimde Seyidim ve alti yoldasi 

Samanpazarinin tam ortasi, 

Kürt Ismet ve yüce türk pasasi. 

Genzimi yakiyor yakilan insanlardan yükselen et kokusu, 

Gözlerimde canlaniyor kirkindaki bebegin bogulusu,', 'Bir isyan ertesiydi;  Sevdalanmistik yasama  Yüreklerimiz bir ceylanin ürkekliginde,  Titrek,  Ve bir o kadar deli,  Namluya sürülen fisek g...', ARRAY['Türk Edebiyatı','Şiir','Diyar Serdar Yıldız']::text[], 8.5, '{"poet":"Diyar Serdar Yıldız","poet_slug":"diyar-serdar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/bir-isyan-ertesi-dersim-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Nerede', 'yunus-nerede-kadir-kaya-ohhcd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevipte sevilmek ne güzel duygu,

Tertemiz sevgide var olur Yunus.

Bütün insanlara duyalım saygı,

Sevenin gönlünde  yar olur Yunus.

Sabırla, tevazu yürüsün bizle,

İmanla, hoşgörü buluşsun özle,

Kalpler ısınmalı ilahi sözle,

Gerçek dostluklarla bir olur  Yunus.

Karanlık geceye bir ışık yakmak,

Saçını okşayıp öksüze bakmak,

Bir dost yüreğine isterim akmak,

Bu günden yarını gör olur Yunus.

Varlıkta benliğe olmasın heves,

Alıpta verdiğin sayılı nefes,

Bir gün can kuşunu zapdetmez kafes,

Manevi Alemde sır olur Yunus.

Haline şükredip zorluğa dayan,

Küçüğü gözetip büyüyü sayan,

Ömür çiçeğimiz solmadan uyan,

Özleme,hasrete yer olur Yunus.

Tatlı konuş, aksın ağzından ballar,

Çokça meyva versin,büyüsün dallar,

Kadir güler yüzlü , her zaman haller,

Hoş sohbet.nasihat ser olur Yunus.', 'Sevipte sevilmek ne güzel duygu, Tertemiz sevgide var olur Yunus. Bütün insanlara duyalım saygı, Sevenin gönlünde  yar olur Yunus. Sabırla, ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yunus-nerede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-mehmet-sakir-karatas-1bmtj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğacak güneşten fayda yok sana

Ne diye bu günü harap edersin

Tutup muradını günden alsana

Ki sana kendini bir daha  versin

İçinde bir hasret amansız sancı

Gördüğün herşeye oldun yabancı

Yitirdin kendine bile inancı

Bilmem ki nereye niye gidersin

                                          1992', 'Doğacak güneşten fayda yok sana Ne diye bu günü harap edersin Tutup muradını günden alsana Ki sana kendini bir daha  versin İçinde bir hasre...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakir Karataş']::text[], 8.5, '{"poet":"Mehmet Şakir Karataş","poet_slug":"mehmet-sakir-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yabanci-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçların', 'saclarin-i-brahim-balci-it77i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saçların ışık saçar,inkar eder rengini

Parıldar ki parıldar,çeker pervaneleri

Pervane gözü kara,atılır ölümüne

Ölüm siyah saçında,ham sevdayla birlikte

Sevda saçın içinde,bir gizler ki kendini

Aramadan bulamam,tek tek her bir telini

Kuğu boynu beline kadar uzanan saçın

Çeker beni içine,kokusuyla ham aşkın

Ece’min tacı sanki,topuz olur başında

Zafir,zümrüt ve yakut,toka olmuş sonunda

Zaptedilmez perçemin isyan eder bu taca

Salt sevgi değil ki bu,vurulmuşum Sertac’a

Bazen örgülü saçın hülyaya sarar beni

Çıkmak için kuleye,o ham hayalimdeki

O hayasız şehvet,esaret altındaki

Tutsak eder kendine,mermer merdivenleri

Bazen o uzun saçlar,dalgalanır rüzgarda

Çıvgın’ın kokusu var,akıp giden havada

Sen ki aşk mabudesi,kırbaçla haydi beni

Usturadan da keskin o zalim saçlarınla

Ellerim saçlarında,arzu gök kuşağında

Kurşuni bir gökyüzü,minarenin ucunda

Ulaşılmaz oldun ki,kuşkuyla doldum yine

Örgülü kuyruğunu kılıcımla kesip de

Ak kaftanım giyinip,cenge dalasım gelir', 'Saçların ışık saçar,inkar eder rengini Parıldar ki parıldar,çeker pervaneleri Pervane gözü kara,atılır ölümüne Ölüm siyah saçında,ham sevday...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/saclarin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-kadir-kaya-wce74', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana ben bakamam, nazar değmesin,

Göz olayım kalem kaşına gülüm.

Mevlam güzel başını hiç eğmesin,

Beklerim değsen yüz yaşına gülüm.

Hasretin bütün benliğimi sardı,

Gündüzde, gecemde hayalin vardı,

Seninle olmanın her anı kardı,

Sana gülmem gider hoşuna gülüm.

Uzadı ayrılık çekerim çile,

Sevginle hayat ver, çevirme çöle,

Gel bana aşkımız düşmesin dile,

Senin benden kaçman boşuna gülüm.

Yanan yüreğimden özlemdir sızan,

Bitmesin baharın gelmesin hazan,

Yazımızı beraber yazsın Yazan,

Ben koşarım senin peşine gülüm.

Deli gönlüm hiç dinlemiyor ferman,

Kadirim, bir gülsen olursun derman,

Tek olduğunu bilmesinler aman,

Dünyada raslamam eşine gülüm.', 'Sana ben bakamam, nazar değmesin, Göz olayım kalem kaşına gülüm. Mevlam güzel başını hiç eğmesin, Beklerim değsen yüz yaşına gülüm. Hasretin...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gulum-137-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sen Oldun', 'hep-sen-oldun-osman-i-nci-xb2zu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne gözlerin aklımdan çıkar, ne de saçların,

Hiç silinmedi beynimden, mahzun bakışların,

Tenimde dolaşıyor sanki, narin parmakların,

Fallarda baktırdığım, inan hep sen oldun…

Hep seni duyuyorum, dinlediğim sözlerde,

Yalnız seni görüyorum, baktığım gözlerde,

Yalnızlıktan sıkıldığım, karanlık gecelerde,

Rüyalarda gördüğüm, inan hep sen oldun…

Seni düşünüyorum, yağmurlarda yürürken,

İçim kan ağlıyor, el ele gezenlere bakarken,

Bu yataktan kalktığımda, yüzümü yıkarken,

Aynalarda baktığım, inan hep sen oldun…

Benim hayatımdın sen, nefes diye çektiğim,

En değerli varlığımdın, kalbime gizlediğim,

Eski günlerimi anarken, hüzünle dinlediğim,

Şarkılarda duyduğum, inan hep sen oldun…', 'Ne gözlerin aklımdan çıkar, ne de saçların, Hiç silinmedi beynimden, mahzun bakışların, Tenimde dolaşıyor sanki, narin parmakların, Fallarda...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hep-sen-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmaklarının Arasında Yaşam', 'parmaklarinin-arasinda-yasam-muhsin-aktas-u0cpy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Parmaklarının arasında yaşam

Bana ne kadar yakınsa

Sana o kadar uzak olan.....

Sigara ve dumanı gibi

Ah.Bir bilsen? 

Bizi bekleyen yaşam.', 'Parmaklarının arasında yaşam Bana ne kadar yakınsa Sana o kadar uzak olan..... Sigara ve dumanı gibi Ah.Bir bilsen?  Bizi bekleyen yaşam....', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/parmaklarinin-arasinda-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayende', 'sayende-osman-i-nci-uym1n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne gün gösterdin bana, ne de güldürdün,

Yaşadığım her günde, defalarca öldürdün,

Kalbimde yanan koru, bakışınla söndürdün,

Tozpembe rüyalarım, kâbus oldu sayende…

Sevdamızı kıskananlar, bak sonunda güldü,

Delicesine seven bu kalbim, yaşarken öldü,

Birlikte gezdiğimiz bahçeler, hazana döndü,

Mor salkımlı bağlarım, viran oldu sayende...

Bütün günler dertlerle doldu, perişan oldum,

Susuz kalmış güle döndüm, sararıp soldum, 

Mücadeleyle geçti bu ömrüm, çok yoruldum,

Güzel gençlik yıllarım, ziyan oldu sayende…

Yaşamaya mecalim yok, darmadağınım artık,

Tüm mektuplar yakılmış, resimlerin de yırtık,

Ne hayâllerim vardı oysa, böyle mi olacaktık, 

İşte bütün umutlarım, hayâl oldu sayende…', 'Ne gün gösterdin bana, ne de güldürdün, Yaşadığım her günde, defalarca öldürdün, Kalbimde yanan koru, bakışınla söndürdün, Tozpembe rüyaları...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sayende-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fallarda Çıkıyorsun', 'fallarda-cikiyorsun-murat-nail-guney-7ujdn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En güzel çağlarımı kurban ettim yıllara,

Sevgi uğruna düştüm, tükenmeyen yollara,

Gurbet kuşları gibi düştüm daldan dallara,

Sevgililer vefasız, dostlar kendi halinde...

Ne acılar saklıyor alnımdaki çizgiler,

İçimde kor alevler, yüzüm çaresiz güler,

Dilerim mevladan ki, biter bütün çileler,

Kaderim acımasız, kaldım gurbet elinde...

Herşeyimi paylaştım, ne varsa elde dostum,

Kırdılar gönlümüzü, dosta, düşmana küstüm,

Yüzüme söyle bana, eğer var ise kastın,

Bu sitemler anlamsız, sözler diken dilinde...

Biz seninle Leyla ve Mecnun gibiydik gülüm,

Ayrılığın kadar çok canımı yakmaz ölüm,

Gülüm dalında soldu,  perişan şimdi halim,

Gündüzlerim anlamsız, gece resmin elimde...

Senle paylaşmadığım daha ne anılar var,

Boş yere ak dökmedi bu saçlarıma yıllar,

Mevla ne derse olur, boşa çırpınır kullar,

Sen bilmesen de olur, adın her an dilimde...

Pişman olur maziye dönüp te bakamazsın,

Ben doğuştan yanmışım, sen beni yakamazsın,

Yüreğim sende iken, gönlümden çıkamazsın,

Karşıma çıkıyorsun, baktığım her falımda...

12/05/2005   akçay kışlası - İskenderun', 'En güzel çağlarımı kurban ettim yıllara, Sevgi uğruna düştüm, tükenmeyen yollara, Gurbet kuşları gibi düştüm daldan dallara, Sevgililer vefa...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/fallarda-cikiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-hasan-gorgu-ktjwj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geziyorum akşamüstü 

Beyoğlunda

Bir kalabalık varki 

Sorma gitsin

İğne atsan yere düşmez

İcabında

Kalabalığın ortasında bir ben

Yalnızım

Tek başına

Üşüyorum yalnızlıktan

Yaz sıcağında

Yetmiyor kalabalıklar

Çare değil yalnızlığıma

Çünkü yanımda yoksun sen

Eğer olsaydın yanımda

Tutuşsaydık  elele

Bir kalabalık olacaktım ki

Sorma gitsin

Beyoğlundan da fazla

Unut gitsin

Ne sen benim yanımda

Ne ben senin yanında

Olamadık bir türlü

Alıştım yalnızlığıma

Şimdi bir tepenin başında

Ya da bir derenin içinde

Yalnızlığım

O kadar kalabalık ki

Alıştım kalabalığa

Yalnızlıklar içinde', 'Geziyorum akşamüstü  Beyoğlunda Bir kalabalık varki  Sorma gitsin İğne atsan yere düşmez İcabında Kalabalığın ortasında bir ben Yalnızım Tek...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yalnizlik-250-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Buyum İşte', 'ben-buyum-i-ste-osman-i-nci-wjgc7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne yalanı severim, ne de söyleyen birini,

Kırmak istemem asla, bir insanın kalbini,

Paylaşırım bir yabancı, insanın da derdini,

Hava atmaya gerek yok, ben buyum işte…

Kendi sorunlarımı, hiç paylaşmak istemem,

Öyle anılar yaşadım ki, ben onları silemem,

Samimi olan bir isteğe de, hayır diyemem,

Hava atmaya gerek yok, ben buyum işte…

Kalbim buruk, gözlerim nemlidir benim,

Duygularım kırık, gönlüm yaslıdır benim,

En değer verdiğim şey, dostluktur benim,

Hava atmaya gerek yok, ben buyum işte…

Ne sahte dostluk yıkar, ne de ihanet beni,

Hiçbir olaya takmam, anlamak güçtür beni,

Mermi işlemez de, acı bir söz öldürür beni

Hava atmaya gerek yok, ben buyum işte…', 'Ne yalanı severim, ne de söyleyen birini, Kırmak istemem asla, bir insanın kalbini, Paylaşırım bir yabancı, insanın da derdini, Hava atmaya ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-buyum-iste-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Geçemedim', 'senden-gecemedim-osman-i-nci-3wnjv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu hasretin yükünü yıllarca, omzumda taşıdım,

Rest çektim bütün evrene, yalnızlıklar yaşadım,

Yokluğuna dayanamadım, hıçkırıklarla ağladım,

Nelerden vazgeçtim ama, senden geçemedim…

Hiçbir şey umurumda değil,sadece sen ol yeter,

Böyle sensiz olmak bence, inan ölümden beter,

Hasretinle yanar gönlüm, kokun burnumda tüter,

Nelerden vazgeçtim ama, senden geçemedim…

Birlikte gülerdik biz seninle, birlikte dolaşırdık,

Bu yorulan yüreğim, acılara dayanamıyor artık,

Mektupların sararmış, elimde tek resmin yırtık,

Nelerden vazgeçtim ama, senden geçemedim…

Okyanusta tek başına dolaşan, sala dönmüşüm,

Yanan bir volkandı bu gönlüm, küle dönmüşüm,

Fırtınalar gibi eserken eskiden, yele dönmüşüm,

Nelerden vazgeçtim ama, senden geçemedim…', 'Bu hasretin yükünü yıllarca, omzumda taşıdım, Rest çektim bütün evrene, yalnızlıklar yaşadım, Yokluğuna dayanamadım, hıçkırıklarla ağladım, ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-gecemedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım Seni', 'unutamadim-seni-osman-i-nci-wsj31', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yaşayabilsen de, böyle bensiz,

Senin yokluğunda, her taraf sessiz,

Zaman durdu sanki, geçmez sensiz,

Çok uğraştım da, unutamadım seni …

Bu gönlüm, öyle düşmüş ki bu aşka,

Kuşların ötüşü, gülün kokusu başka,

Duygular dağılmış, dostluklar laçka,

Çok uğraştım da, unutamadım seni …

Mevsimlerim değişti, baharlar olmaz,

Bende bıraktığın yara, asla kapanmaz,

Çok iyi anladım, bendeki yerin dolmaz,

Çok uğraştım da, unutamadım seni …

Günden güne eritir, bitirir özlemin beni,

Kış ortasında bile, yakar hasretin beni,

Yaz gününde dondurur, o gözlerin beni,

Çok uğraştım ama, unutamadım seni …', 'Sen yaşayabilsen de, böyle bensiz, Senin yokluğunda, her taraf sessiz, Zaman durdu sanki, geçmez sensiz, Çok uğraştım da, unutamadım seni … ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutamadim-seni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Utanıyorum..', 'utaniyorum-osman-kilic-sprc4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlığın ışıkla buluşacağı yere

O kadar çok yaklaşmışken

Ve saadetten sarhoş günlere

Belki bir adım belki bir nefes

Belki bir tebessüm kalmışken

Erken erken

Bırakıp giden bir sevgili tanıyorum

Yahu utanır mı insan başkasının yaptığından? 

Utanıyorum...

Daha söylenecek çok şeyler varken

Kendini hiç yormadan

Hep aynı dalgaboyunda

Yükselip alçalmadan

''Eyvallah'' diyen bir ses tanıyorum

Yahu utanır mı insan kendi sesinden? 

Utanıyorum...

Ne onun için birşeyler yapan

Ne de bu sevdanın yakasını bırakan

Bir deli rüzgarla çalkalanıp duran

Hazanda dala vedaya hazırlanan

Sapsarı yaprak gibi bir ben tanıyorum

Yahu utanır mı insan hiç kendinden? 

Utanıyorum...

08.11.2004', 'Karanlığın ışıkla buluşacağı yere O kadar çok yaklaşmışken Ve saadetten sarhoş günlere Belki bir adım belki bir nefes Belki bir tebessüm kal...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/utaniyorum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım', 'asigim-meryem-i-sler-jilnj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözüm sende gönlüm sende

Saklayamam seni hiç bir yerde

Kalbim dilime vurmuş bir kere

Şarkılar söyler aşkın uğruna her telde

Varsın eller yalan desin

İster gülsün ister alay etsin

Sen benimsin bende senin

Aşkın bende ya gerisi gelip geçsin

Rüyalarımda bile aşkını yaşıyorum

Ben yaşamaya senin için geldim biliyorum

Candan sevdim seviliyorum

Seninle cenneti dünyada yaşıyorum', 'Gözüm sende gönlüm sende Saklayamam seni hiç bir yerde Kalbim dilime vurmuş bir kere Şarkılar söyler aşkın uğruna her telde Varsın eller yal...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asigim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamam Sana', 'kiyamam-sana-ali-goncu-n7pyk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kıyamam sana, senden uzakta

İstemem  sensiz mutluluğu.

Sen ulaşıldıkça 

Ulaşılmaz hasretim olacaksın

galiba.

Haykırsam duyar mısın sesimi

Ya da soluğumu hisseder misin

tutuşunca.', 'Kıyamam sana, senden uzakta İstemem  sensiz mutluluğu. Sen ulaşıldıkça  Ulaşılmaz hasretim olacaksın galiba. Haykırsam duyar mısın sesimi Ya...', ARRAY['Türk Edebiyatı','Şiir','Ali Göncü']::text[], 8.5, '{"poet":"Ali Göncü","poet_slug":"ali-goncu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kiyamam-sana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmez Gözlerim', 'gormez-gozlerim-osman-i-nci-wklkd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlüme diktiğin fidan, asla solmaz,

Bir gün gidersen eğer, yerin dolmaz,

Dünya yıkılsa bile, umurumda olmaz,

Senden başkasını, görmez gözlerim…

Hayatın anlamı oldun, felsefem sensin,

Damarımdaki kansın, ruhumda bensin,

Sözlerimde hep sen, rüyamda gezensin,

Senden başkasını, görmez gözlerim…

Sen yaşamımda farksın, köşe taşısın,

Sen hayatın önemisin, ağız tadımsın,

Sen benim sevdamın, en güzel yanısın,

Senden başkasını, görmez gözlerim…

Vazomdaki çiçek, bahçemde gülümsün,

Kalbimdeki her atış, ömrüme ömürsün,

Parmağımı oynatmam, seninle mümkün,

Senden başkasını, görmez gözlerim…', 'Gönlüme diktiğin fidan, asla solmaz, Bir gün gidersen eğer, yerin dolmaz, Dünya yıkılsa bile, umurumda olmaz, Senden başkasını, görmez gözle...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gormez-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Gideceksin', 'bir-gun-gideceksin-osman-i-nci-ym7yd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özünde mertlik, sözünde doğruluk olsun,

Olsun ki bunlar, kalkan olup seni korusun,

Bil ki herkes gibi, sende bir Adem oğlusun,

Bir gün gideceksin, dört omuz üstünde…

Ne ekmişsen dünyada, onu biçeceksin,

İki metrelik bu kefeni, sende giyeceksin,

Şahadet şerbetini, ellerinle alıp içeceksin,

Bir gün gideceksin, dört omuz üstünde…

Babandan bile hayır yok, tek başınasın,

Sanma ki orada da böyle hayal kurarsın,

Unutma bu sözlerimi, şimdi rüyadasın,

Bir gün gideceksin, dört omuz üstünde…

En değerli şeylerden, zorla ayrılacaksın,

Toprağın altında, yeni bir ev kuracaksın,

Girmek istemiyorum diye, yalvaracaksın,

Bir gün gideceksin, dört omuz üstünde…', 'Özünde mertlik, sözünde doğruluk olsun, Olsun ki bunlar, kalkan olup seni korusun, Bil ki herkes gibi, sende bir Adem oğlusun, Bir gün gidec...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-gideceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kışa mı Döndü', 'kisa-mi-dondu-osman-i-nci-ynfu7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çerçeveler hep kırılmış, resimler yerde,

Huzur dolu günler yerini, bıraktı derde,

Hani mutluluk vardı, verilen sözler nerde,

Aşkın bahar mevsimi, kışa mı döndü? ..

Vazoda çiçeklerim, solmuş dökülür,

Vücudumdan sanki, kalbim sökülür,

Kara listedeyim, sonum kötü görünür,

Aşkın bahar mevsimi, kışa mı döndü? ..

Her gelen yeni günlerim, aratıyor dünü,

Kimilerinin umurunda mı, gün eder günü,

Şimdi oldum işte, tam bir sevda sürgünü,

Aşkın bahar mevsimi, kışa mı döndü? ..

En parlak yıldızdık biz, gökte görülen,

Bir krallığımız vardı, hüküm sürülen,

İşte bizim defterimiz, bak bu dürülen,

Aşkın bahar mevsimi, kışa mı döndü? ..', 'Çerçeveler hep kırılmış, resimler yerde, Huzur dolu günler yerini, bıraktı derde, Hani mutluluk vardı, verilen sözler nerde, Aşkın bahar mev...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kisa-mi-dondu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamam Sana Senden Uzakta', 'kiyamam-sana-senden-uzakta-ali-goncu-fjigq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıyamam sana, senden uzakta

İstemem  sensiz mutluluğu.

Sen ulaşıldıkça 

Ulaşılmaz hasretim olacaksın

galiba.

Haykırsam duyar mısın sesimi

Ya da soluğumu hisseder misin

tutuşunca.', 'Kıyamam sana, senden uzakta İstemem  sensiz mutluluğu. Sen ulaşıldıkça  Ulaşılmaz hasretim olacaksın galiba. Haykırsam duyar mısın sesimi Ya...', ARRAY['Türk Edebiyatı','Şiir','Ali Göncü']::text[], 8.5, '{"poet":"Ali Göncü","poet_slug":"ali-goncu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kiyamam-sana-senden-uzakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Gibi Zor Bana', 'olum-gibi-zor-bana-osman-i-nci-cax3s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün ömrümü vermiştim, bu sevdama,

Dayanırdı  gönlüm, bütün çileye-gama,

Neler yaşadım bilsen, korkmadım ama,

Senin bu yokluğun, ölüm gibi zor bana…

Hayalin takılı kaldı, benim gözlerimde,

Adını sayıklar oldum, tüm sözlerimde,

O kadar sorun yaşadım, üzülmedim de,

Senin bu yokluğun, ölüm gibi zor bana...

Sen olurdun geceleri, bütün rüyalarımda,

Sen çıkardın hep, baktırdığım fallarımda,

Bıraktığın güller bile, yeniden açılıyor da,

Senin bu yokluğun, ölüm gibi zor bana…

Mutlu çiftlere bakıp, her gece ağlıyorum,

Bilsen bu hasretinle, ben neler çekiyorum,

Yaşadığım günlerde, azaplarla ölüyorum,

Senin bu yokluğun, ölüm gibi zor bana…', 'Bütün ömrümü vermiştim, bu sevdama, Dayanırdı  gönlüm, bütün çileye-gama, Neler yaşadım bilsen, korkmadım ama, Senin bu yokluğun, ölüm gibi ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-gibi-zor-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gelir', 'gun-gelir-firuze-keles-yuj8c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün olur dağılıp herbir köşeye,

Toz olur, duman olur

Savruluruz.

Gün olur karışıp yağan yağmura,

Gül olur, çimen olur

Kavruluruz.

Gün olur anlatırım

Dost bir geceye,

Söz olur, aşk olur

Duyuluruz.

Gün olur çekilirim

Issız köşeye,

Bir mezar taşında dua oluruz.

Ve

Gün gelir son nefes verildiğinde

Zamansız bir mekanda

Buluşuruz...

07.03.2003', 'Gün olur dağılıp herbir köşeye, Toz olur, duman olur Savruluruz. Gün olur karışıp yağan yağmura, Gül olur, çimen olur Kavruluruz. Gün olur a...', ARRAY['Türk Edebiyatı','Şiir','Firuze Keleş']::text[], 8.5, '{"poet":"Firuze Keleş","poet_slug":"firuze-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gun-gelir-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Çarpacak', 'senin-i-cin-carpacak-osman-i-nci-ljli5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni dost değil, düşman bilsen de,

Hatıralarını bir bir, yakıp silsen de,

Yıksan beni, verem, kanser etsen de,

Deli yüreğim, senin için çarpacak…

Kâinat durdukça, aşkım sürecek,

Her zerrem özünde, seni sevecek,

Bütün dünya bunu, böyle bilecek,

Deli yüreğim, senin için çarpacak…

Kapına geldiğimde, hep kovsan da,

Silahı çıkarıp, alnımdan vursan da,

Soluğumu kessen, ecelim olsan da,

 Deli yüreğim, senin için çarpacak…

Baktırdığım fallar, bir gün çıkacak,

Yaptığın o kötülükler, sana kalacak,

Öldüğümde bil ki, bir mucize olacak,

Deli yüreğim, senin için çarpacak…', 'Beni dost değil, düşman bilsen de, Hatıralarını bir bir, yakıp silsen de, Yıksan beni, verem, kanser etsen de, Deli yüreğim, senin için çarp...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-icin-carpacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dair', 'sana-dair-ali-goncu-y6hnk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kıyamam sana, senden uzakta

İstemem sensiz mutluluğu.

Sen ulaşıldıkça 

Ulaşılmaz hasretim olacaksın galiba.

Haykırsam duyar mısın sesimi,

Ya da soluğumu hisseder misin

Tutuşunca.', 'Kıyamam sana, senden uzakta İstemem sensiz mutluluğu. Sen ulaşıldıkça  Ulaşılmaz hasretim olacaksın galiba. Haykırsam duyar mısın sesimi, Ya...', ARRAY['Türk Edebiyatı','Şiir','Ali Göncü']::text[], 8.5, '{"poet":"Ali Göncü","poet_slug":"ali-goncu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sana-dair-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah DeliceKız', 'siyah-delicekiz-sule-aydemir-ps9e8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'siyaha bakmak

beyazı bilmekten gelir

biri olmazsa 

diğerini kim bilir

yoksan kimse yok

özümse deneyimleri

al kendini git

umutlar 

tersine çevirdiğin anlar

arkanda  bıraktığın

otuz beş  basamak 

gerisi düşünebildiğin 

kadardır yaşamak

__yararsız acıyı veren ne varsa

_________________çek çizgini

____________________al kendini git



**** Diğer Yarım-a (Ebru Delice''ye)                 ithaf edilmiştir..

****Nice yılları düşünce asiliğiyle devir DeliKız...Doğum günün kutlu olsun...', 'siyaha bakmak beyazı bilmekten gelir biri olmazsa  diğerini kim bilir yoksan kimse yok özümse deneyimleri al kendini git umutlar  tersine çe...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/siyah-delicekiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecelin Sesi', 'ecelin-sesi-murat-demir-uix28', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açık denizlerde 

Demirlemek istemiştim

Yalnızlığımı

Ve beni

Sığınacak liman bulamayınca,

Sensiz geçmişimin kara tahtasını

Ak sayfaya çeviririm sanmıştım

Tebeşir tozuyla,

Bir martı kanadının çıkaracağı

Rüzgara teslim ederek

Geleceğimi.

İçtikçe sarhoş oluyor

Sarhoş oldukça içiyordum

Yapayalnız,

Okyanusun ortasında.

Ve gözlerim döktükçe

Sağanağını sulara,

Ayaklarımın altında yunuslar

Mutluluklarını sergiliyordular

Mutsuzluğumun inadına.

Yine yalnız değildim

Yine birleri vardı

Seni bana hatırlatan,

Yine köpürmüştü yüreğim

Okyanusun dalgalarına

Meydan okurcasına

Ve bana isyan edercesine,

Anla artık,onsuz olmuyor

Anla artık diye,

Ve ben,

Boyun eğmiştim ki

Yüreğimin fermanına,

Olmadı,

Çünkü; 

Ecelin sesiydi dayanan kapıma

Demir almak için.', 'Açık denizlerde  Demirlemek istemiştim Yalnızlığımı Ve beni Sığınacak liman bulamayınca, Sensiz geçmişimin kara tahtasını Ak sayfaya çevirir...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ecelin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-soner-polat-hppcd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tırtıl kozasında 

bir kelebek

bir gün için uçması gerek

kanat çirpması

ölmesi demek

tırtıl kozasında

bir kelebek

ölüme 

uçarak gidecek...', 'tırtıl kozasında  bir kelebek bir gün için uçması gerek kanat çirpması ölmesi demek tırtıl kozasında bir kelebek ölüme  uçarak gidecek......', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kelebek-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cüzzi irade', 'cuzzi-irade-ali-riza-unal-imym6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel put etme, külde cüzünü.

İyi tanı o cüzde, gerçek külünü.

Tanrı, hesaba çekmesin kulunu.

Ver Muhammede, beşer yolunu.

Kokla,kana kana, hakikât gülünü.', 'Gel put etme, külde cüzünü. İyi tanı o cüzde, gerçek külünü. Tanrı, hesaba çekmesin kulunu. Ver Muhammede, beşer yolunu. Kokla,kana kana, ha...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cuzzi-irade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aboneyim Ben İçkiye', 'aboneyim-ben-i-ckiye-suleyman-saylan-2bg7y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ABONEYİM  BEN  İÇKİYE

Sığmıyorsun kadehlere,

Boşaldın bak yüreğime.

Unuturum seni diye

Aboneyim ben içkiye.

Kadeh kadeh boşalırsın,

Dumanlanır dertli başım.

Yalnızlığa alışığım...

Aboneyim ben içkiye.

Her gün başka bir içkisin,

Kadehimde, içimdesin,

Uyurken de düşümdesin...

Aboneyim ben içkiye.

Meyhaneler seni tanır,

Sevdalıyım diye acır,

Hepsi üstüme kapanır.

Aboneyim ben içkiye.

Bir teselli bulmak için,

Hayalini görmek için,

Kaderime sövmek için,

Aboneyim ben içkiye.

Ölsem bile seveceğim,

Uğruna can vereceğim,

Mahşere dek içeceğim,

Aboneyim ben içkiye.

   Süleyman  SAYLAN 

Ankara, 22.07.1999 saat: 01.45   Şarkı sözü olarak yazılmıştır.', 'ABONEYİM  BEN  İÇKİYE Sığmıyorsun kadehlere, Boşaldın bak yüreğime. Unuturum seni diye Aboneyim ben içkiye. Kadeh kadeh boşalırsın, Dumanlan...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aboneyim-ben-ickiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Uzak', 'senden-uzak-ali-goncu-4rqsz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamı düşündüm.

Denizden uzak, bizansa yakın.

Vişne çürügü, küş ölüsü

Senle küskün, benle barışık.

Küfürler dönüyor sokaklarda

Senden uzak, bana yakın.', 'Yaşamı düşündüm. Denizden uzak, bizansa yakın. Vişne çürügü, küş ölüsü Senle küskün, benle barışık. Küfürler dönüyor sokaklarda Senden uzak,...', ARRAY['Türk Edebiyatı','Şiir','Ali Göncü']::text[], 8.5, '{"poet":"Ali Göncü","poet_slug":"ali-goncu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/senden-uzak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Çıktı Serseriye', 'adim-cikti-serseriye-suleyman-saylan-la0lf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ADIM  ÇIKTI  SERSERİYE

Unuturum seni diye,

Sabah, akşam, gündüz, gece,

Kadeh kadeh içe içe

Adım çıktı serseriye.

Serseriyim ben serseri,

Aşkının elinde deli...

Bilemedim sevmesini,

Adım çıktı serseriye.

Sevdam gibi bembeyazdı,

Doldurdum hep kadehlere.

İçti gönlüm, şiir yazdı...

Adım çıktı serseriye.

Serseriyim ben serseri,

Aşkının elinde deli...

Bilemedim sevmesini,

Serseriyim ben serseri.

Her bir damla gözyaşımdı,

Koyduğum su bakışındı,

Yakıp geçen öpüşündü,

Adım çıktı serseriye.

Serseriyim ben serseri,

Aşkının elinde deli...

Bilemedim sevmesini,

Serseriyim ben serseri.

     Süleyman  SAYLAN

(Sandıklı-Afyon yolu (şehirlerarası otobüste)  

22.10.1995 saat: 02.30       Şarkı sözü olarak yazılmıştır.', 'ADIM  ÇIKTI  SERSERİYE Unuturum seni diye, Sabah, akşam, gündüz, gece, Kadeh kadeh içe içe Adım çıktı serseriye. Serseriyim ben serseri, Aşk...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/adim-cikti-serseriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlmi hayali hal eyle', 'i-lmi-hayali-hal-eyle-ali-riza-unal-6faj7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey Rıza, sayfalar dolusu, söze ne hacet.

Söyler isen az söyle, öz ile dür söyle.

Gafile,bir deyil bin kerâmet, bilki necaset.

Sen o meçhul ilmi hayali,ehline  hal eyle', 'Ey Rıza, sayfalar dolusu, söze ne hacet. Söyler isen az söyle, öz ile dür söyle. Gafile,bir deyil bin kerâmet, bilki necaset. Sen o meçhul i...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilmi-hayali-hal-eyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunluk', 'yorgunluk-devrim-gulecyuz-8y7sw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koskocaman bir yarayla başa çıkmak mı

Yoksa yenilerine karşı sürekli tetikte olmak mı

Karşına çıkanları bir bir sınamak mı

Yoran duyguları mı? 

Gerçek bir sıcaklığa hasret kalmak mı

Güzel sözlere, güneş gibi bir gülümsemeye

Kana kana susamak mı

Kapatıp gözlerini sadece teninle konuşmayı özlemek mi

Yoran duyguları mı? 

Kelimelerin dile gelmesini değil de

Bakışlardan süzülmesini beklemek mi

Gözyaşlarını kalbine akıtmayı bırakıp da

Gözlerimin özgürlüğüne sevinebilmek mi

Dokunmasam da varlığıyla yanımda olduğunu 

En derinden hissettirecek birini aramak mı

Yoran duyguları mı? 

Yoksa mantığımla sürekli kavgaları mı? 

Bunca şeye rağmen! ! !', 'Koskocaman bir yarayla başa çıkmak mı Yoksa yenilerine karşı sürekli tetikte olmak mı Karşına çıkanları bir bir sınamak mı Yoran duyguları m...', ARRAY['Türk Edebiyatı','Şiir','Devrim Güleçyüz']::text[], 8.5, '{"poet":"Devrim Güleçyüz","poet_slug":"devrim-gulecyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yorgunluk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Gözlüm', 'huzun-gozlum-suleyman-saylan-9fyoz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'HÜZÜN  GÖZLÜM

Çağla badem gözlerini

Hüzün sarmış, içli hüzün.

Düş boyamış evrenini,

Menekşeye dönmüş yüzün.

Boyun posun, endamınla

Yaktın beni sevdalarda.

Yüreğim bir bakışınla

Kördüğümdür, bir kördüğüm.

Gözün yeşil, kaşın kara,

Hüzün yüklü bakma bana.

Doysun sana kana, kana

Haz telleri bu gönlümün.

Sevdan seldir, kalbim çakıl; 

Sürükleyip, al da, götür...

İster yüzdür, ister batır; 

(ister çağdaş, ister batıl ;) 

Son sevdası ol ömrümün.

Anlatmaya sözler yetmez,

Sevmeyen bu dilden bilmez.

Özgürlüğe ömrüm yetmez,

Gözlerinde bir sürgünüm...

                            Süleyman SAYLAN

                            Ankara, 21.07.1997 saat: 17.05  Şarkı sözü olabilir.', 'HÜZÜN  GÖZLÜM Çağla badem gözlerini Hüzün sarmış, içli hüzün. Düş boyamış evrenini, Menekşeye dönmüş yüzün. Boyun posun, endamınla Yaktın be...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/huzun-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem Ne Seni, Ne de Sevgini...', 'i-stemem-ne-seni-ne-de-sevgini-suleyman-saylan-fbm3q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İSTEMEM  NE  SENİ,  NE  DE  SEVGİNİ...

İstemem ne seni, ne de sevgini; 

Sen sevgiyi bilmez, aşkı bilmezsin.

Yıllarca sevdamla sulasam seni,

(yıllarca sevdamla beslesem seni,) 

Çorak toprak gibi, çiçek vermezsin.

Başka bir dünyada gezinir gönlün,

Gerçeği görmeden bitecek ömrün...

Bırak bu nazı da, kalbin aşk görsün.

Çiçek açsan bile, koku vermezsin.

Ağaç olsan sana kuş bile konmaz,

Mihrapsan önünde namaz kılınmaz,

Dünyan yansa senin, kibriti yakmaz,

Yanıp kül olsan da, duman vermezsin.

Dünyaya bir daha gelme sakın sen,

Sevmeyi bilmezsin, sevme sakın sen,

Düş olup düşüme girme sakın sen; 

(düşüme düş gibi girme sakın sen ;) 

Azrail olsan da, korku vermezsin.

İstemem ne seni, ne de sevgini; 

Sen sevgiyi bilmez, aşkı bilmezsin.

Yıllarca sevdamla sulasam seni,

(yıllarca sevdamla beslesem seni,) 

Çorak toprak gibi, çiçek vermezsin.

        Süleyman  SAYLAN

Ankara, 08.01.1995 saat: 00.15  (Şarkı sözü olabilir.)', 'İSTEMEM  NE  SENİ,  NE  DE  SEVGİNİ... İstemem ne seni, ne de sevgini;  Sen sevgiyi bilmez, aşkı bilmezsin. Yıllarca sevdamla sulasam seni, ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istemem-ne-seni-ne-de-sevgini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanım Kaynadı', 'kanim-kaynadi-suleyman-saylan-s61ou', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KANIM  KAYNADI

Göçmen kuşlar gibi gezgin yüreğim

(göçmen kuşlar gibi özgür yüreğim) 

Çılgınca çarpıyor, kökten oynadı.

Bu son demlerimde artık güleyim; 

(bu son demlerimde sensin tüneğim ;) 

Isındım sana ben, kanım kaynadı.

Sahipsiz geçen o yitik yıllarım

Boşa akıp gitmiş, ona yanarım.

(boşa uçup gitmiş, ona yanarım.) 

Bir tatlı hatıra kalsa, anarım...

Isındım sana ben, kanım kaynadı.

Çıplak düşlerimde gördüğüm rüya,

(senli düşlerimde gördüğüm rüya,) 

Renklendi seninle, bambaşka dünya.

(can buldu seninle, bambaşka dünya.) 

Eskitip atmıştım aşkları güya...

(eskiciye sattım aşkları güya...) 

Isındım sana ben, kanım kaynadı.

Vazgeçmek zor artık, yangınım sana,

(vazgeçmem zor artık, ben yandım sana,) 

Gönül rızasıyla aldandım sana,

Yorgun yüreğimle uzandım sana...

Isındım sana ben, kanım kaynadı.

   Süleyman  SAYLAN

   Ankara, 12.05.1993 saat: 22.30  (Şarkı sözü olabilir.)', 'KANIM  KAYNADI Göçmen kuşlar gibi gezgin yüreğim (göçmen kuşlar gibi özgür yüreğim)  Çılgınca çarpıyor, kökten oynadı. Bu son demlerimde art...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kanim-kaynadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edirne Kahramanı Şükrü Paşa', 'edirne-kahramani-sukru-pasa-ekrem-sama-afnoh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Edirne''yi kuşattı Bulgar,

Emretti, çekildi kılıçlar,

İstanbul''da tatlı rüya var,

Ama uykusuz, Şükrü Paşa.

Edirne, mabetler mahalli,

Açlığa mahkumdur ahali,

Yendi; ot, fare, kabuk, çalı...

Hem aç hem susuz, Şükrü Paşa.

Paşa sanki düşmana esir,

Politik görüş çok da kısır,

Neden evde hapis, hala sır? 

Yattı sorgusuz, Şükrü Paşa.

Milletinin asker evladı,

Edirne''nin dilinde yadı,

Çantasında kefen taşırdı,

Merhum korkusuz, Şükrü Paşa.

Aylarca namusu savundu,

Millet sevgisiyle avundu,

Tarihe kahramanlık sundu; 

Budur kuşkusuz, Şükrü Paşa...

(İstanbul:14.06.2005)', 'Edirne''yi kuşattı Bulgar, Emretti, çekildi kılıçlar, İstanbul''da tatlı rüya var, Ama uykusuz, Şükrü Paşa. Edirne, mabetler mahalli, Açlığa m...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/edirne-kahramani-sukru-pasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlikti Adı Seni Sevmenin...', 'sensizlikti-adi-seni-sevmenin-ugur-deniz-ulkegul-975om', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadavra olmuşum yine

Sözünde şairin

Belli ki yorulmuş düşünürken

Zordur altından kalkmak

Duygusal bir otopsinin...

Ne kadar geç kalmış sabah

Erkenci gitmelerin ardından

Çayımın acımtırak tadı

Sigaramın puslu dumanı...

Yokluğun...

İçimde aynı burukluğun

Sokakta gülüşüp duran çocuklar

Yine bulut olmuş elleri...

Gökyüzünde

Sanki yedi renginden gökkuşağının..

Uçurtmalar...

Cebimde aşkın anatomisi

Dilsiz, sağır

Elleri soğuk, gözleri kör

Bir yandan ayrılık kor

Sustukça ağır ağır...

Mektupsuz akşamlardan doğarım

Yazgım acı, büyürüm sancılı

Nazenin bir gül boşlukta duran

Ertelenmiş saatlere dokunmalarım

Yanlış yer, yanlış zaman..Sustum..

Bu kaçıncı? 

Sensizlikti adı..Seni Sevmenin..

Kahvede adım geçer

Tavla masasında, laf arasında

''İşte şu ev mavi boyalı

İçinde oturan yalnız bir adam...''

Bir de susmayan telsizler

''Otuz yaşlarında adresi meçhul

Sakıncalı dolaşır yol ortasında...''

II- Sevmek koydum adını...Sensizliğin..

Baş ucumda gözlerin

Gözlerim yok...

Sözlerin bıçak yarası, yaram derin

Sözlerim yok...

Sıcaktı ellerin kar yangını düşlerde

Gelmedin (-gitmedim)    görüşlerde

İzlerim yok...

Seviyorum bahar kokusunu

Çocuk seslerini

Bir de yağmur sonrası

Girdiğim ağaç kuytusunu...

Alın terini toprağa düşen

İnsanı..Hani erdemli düşünen..

Seviyorum inadına yürümeyi

Yürürken sakıncalı görünmeyi...

Seviyorum hayatı

Adam gibi sonunda ölebilmeyi..

Ve yoksun...

Sevmek koydum adını...Sensizliğin...

Otopsim hep yarım kaldı...Biliyorsun...', 'Kadavra olmuşum yine Sözünde şairin Belli ki yorulmuş düşünürken Zordur altından kalkmak Duygusal bir otopsinin... Ne kadar geç kalmış sabah...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sensizlikti-adi-seni-sevmenin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum', 'ariyorum-cemil-aygen-dug8h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırık bir vazo 

Parçasını arıyor

Bir şarkı..Notasını

Bir tablo Renklerini

Gül bülbülünü arıyor

Ağaç yapraklarını

Ve Bir Adam

Her gece yollara düşüp

Yana yakıla seni arıyor...

İlk değil gözleri böylesine ıslak

Gel diye yalvarıyor Tanrıya da

Gözyaşlarını saklıyor utanarak...', 'Kırık bir vazo  Parçasını arıyor Bir şarkı..Notasını Bir tablo Renklerini Gül bülbülünü arıyor Ağaç yapraklarını Ve Bir Adam Her gece yollar...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ariyorum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Charles Bukowski İçin...', 'sair-charles-bukowski-i-cin-ali-kuruuzum-796us', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bukowski şiirlerim için ne diyor duydun mu? 

İşe yaramazmış yazdıklarım.

Ayrıca benim miras yedi,tembel,osuruktan bir adam olduğumu söyledi.

Yaşasaydı seksen dört yaşında olacaktı.

O na; ne düşündüğünün önemli olmadığını,yazmayı sevdiğim için yazdığımı söyledim.

Bir daha dünyaya gelirse daha iyi bir suratla gelmesini de önerdim.

Gülümseyerek bunun iyi bir fikir olduğunu söyledi..

''-Bilmiyorum Hank,bilmiyorum...''

Saçları az uzamış ve kirli sakallıydı.

Söyleyeceği cümle dudaklarında dondu...

Elleri cebinde, bir ıslıkla uzaklaştı

Gözden kaybolana kadar izledim onu.

Aralık-2003', 'Bukowski şiirlerim için ne diyor duydun mu?  İşe yaramazmış yazdıklarım. Ayrıca benim miras yedi,tembel,osuruktan bir adam olduğumu söyledi....', ARRAY['Türk Edebiyatı','Şiir','Ali Kuruüzüm']::text[], 8.5, '{"poet":"Ali Kuruüzüm","poet_slug":"ali-kuruuzum","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sair-charles-bukowski-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Kırılma Noktası...', 've-kirilma-noktasi-cigdem-demircan-spqc5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 've ben oturduğumda 

