INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zillisin (Aşıftesin)', 'zillisin-asiftesin-halay-sadi-b5oyg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evdeki bebeğini, evdeki meleğini

Bilerek sarılıyorsan

Sofrasında solan güllerini

Kanayan hasret gönüllerini

Bilerek sarılıyorsan

Zillisin sen zilli

Kullandığın zamanın çalıntı olduğunu

Bilerek sarılıyorsan

Oynadığın duyguların sahibini

Bu oyunun bitim tarihini

Bilerek sarılıyorsan

Zillisin sen zilli

2002', 'Evdeki bebeğini, evdeki meleğini Bilerek sarılıyorsan Sofrasında solan güllerini Kanayan hasret gönüllerini Bilerek sarılıyorsan Zillisin se...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zillisin-asiftesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '280 Nolu Rubai', '280-nolu-rubai-omer-hayyam-tnw5a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '280

Sünneti, farzı fazla kafana takma,

Ekmeğinden yoksula verdin bir lokma.

Dostu ve gönlü hoş tut, kötülüğü kov; 

Şarap ver; cennetliksin mutlaka, korkma!', '280 Sünneti, farzı fazla kafana takma, Ekmeğinden yoksula verdin bir lokma. Dostu ve gönlü hoş tut, kötülüğü kov;  Şarap ver; cennetliksin m...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/280-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Frank mektubun var', 'hey-frank-mektubun-var-nejat-karagoz-zwv3h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben Basra''dan Ömer...

Belki haberin yoktur diye yazıyorum Frankn; 

Önce demakrosi yağdı göklerden

Sonra özgürlük geçti üstümüzden palet palet...

Ve insan hakları namlularından

Yüzü maskeli adamların

Saniyede bilmem kaç bin adet.

Demokrasi bizim eve de isabet etti

Bir gün sonra anladım ayaklarımın koptuğunu

Babamın vücudunda

Tam on sekiz adet

İnsan hakları saymışlar

Annem zaten yoktu

Ben doğarken

İlaç yokluğundanr ölmüş

Ambargo filan dediler ya

Anlamadım,çocuk aklı işte

Sen daha iyi bilirsin.

Sizde de barış böyle midir  Frank? 

İnsan hakları çocukları yetim

ve ayaksız bırakır mı orada da? 

Ya demokrasi? 

Güpegündüz pazar yerine düşer mi? 

Ve zenginlik...

İnsanları korkudan uykusuz bırakır mı? 

Ve kuşlar gökyüzünü terkeder mi orada da? 

Babama söylediğim son dua dilimde,

Ayaklarım hastanede,

Ve giymeye kıyamadığıım ayakkabılar

Elimde kaldı...

Çocuğun var mı Frank? 

Al... Çocuğuna götür onları

Bir işe yarasın.

Kim bilir baktıkça

Belki meni hatırlarsın

Bu nasıl demokrasi Frank? 

Düştüğü yeri yaktı

Merhamet hür dünyaya

Bu kadar mı Irak''tı? 

Basra''lı Ömer.', 'Ben Basra''dan Ömer... Belki haberin yoktur diye yazıyorum Frankn;  Önce demakrosi yağdı göklerden Sonra özgürlük geçti üstümüzden palet pale...', ARRAY['Türk Edebiyatı','Şiir','Nejat Karagöz']::text[], 8.5, '{"poet":"Nejat Karagöz","poet_slug":"nejat-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hey-frank-mektubun-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyorum', 'yuruyorum-bisar-ulutas-vxsig', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Büyüdü gerginlikler içimde, yol alma vakti şimdi.

Kötü insanların, güzel şehrinden uzaklaşıyorum. 

Ey sessizlikler, bekleyin beni. 

Size geliyorum, koklanmamış çiçekler

Ezilmeden binlerce sürünün içinde.

Yaklaşmadan enseme, kötü nefesler. 

Start verdim, huzura hazırlıyorum adımlarımı. 

Yolculuk var, umutların mavisine, 

hakiki aşkların sesine. 

Gözüm yerde, boynum bükük, 

kalabalığı yarıyorum. 

Yalancı, sahtekâr kullara dargın yürüyorum. 

Parçalanmış yüreğime hatıraları aldım. 

Gizlerimi bilmez hiç kimse. 

Kısık bir fon okşuyor kulaklarımı. 

Usulca uzaklaşıyorum, 

uyuyan denizin yanından. 

Kükremeden köpüksüz su, 

kavrulmadan arsız güneş. 

Karanlığa gömülüyorum, gün doğmadan. 

Huzur alıyor bedenim, 

doğanın sessizliğinden. 

Kalpleri pislik, temizliği haykıranlardan uzağım şimdi. 

Amaçsız bulut, hedefsiz gök, aydınlığa kırgın yürüyorum. 

Kırdılar gururumu, dost bildiklerim. 

Hayatıma kıydı, ‘hayat’ verdiklerim. 

İşte bu yüzdendir isyanım benim. 

Ama her şeye rağmen, lâl, susuyorum. 

Şehirler geçiyorum, dumanlı, paslı. 

Gün doğmak üzere, hava soğuk, üşüyorum. 

Ayaklarım yorgun düşüyor, bir cigara yakıyorum. 

Gözleri patlak, sakalları kirli puştlara kızgın yürüyorum. 

Bir düş istiyorum, değişik bir düş. 

Kirlenmemiş, saf ve çiçeklerden örülmüş. 

Dizginsiz bir istekle yürüyorum, düşlerime doğru. 

Varıyorum, Torosların eteğine. 

Yakıyor güneş, yeşilliğe uzanıyorum. 

Kirli sarı bir rüya görüyorum. 

Soluk soluğa uyanıyorum. 

Çekiliyor güneş, kükrüyor su, uyanıyor deniz. 

Köpürüp çıldırıyor, hırçın Akdeniz. 

Sonsuz sulara kusuyorum, yüzyıllık öfkemi. 

Kalkıyor, düşünüyorum. 

Kötü insanların, güzel memleketini özlüyorum. 

Kararsız, isteksiz, yüreğim yangın yürüyorum.', 'Büyüdü gerginlikler içimde, yol alma vakti şimdi. Kötü insanların, güzel şehrinden uzaklaşıyorum.  Ey sessizlikler, bekleyin beni.  Size gel...', ARRAY['Türk Edebiyatı','Şiir','Bişar Ulutaş']::text[], 8.5, '{"poet":"Bişar Ulutaş","poet_slug":"bisar-ulutas","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yuruyorum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanetin Gözyaşı', 'i-hanetin-gozyasi-halay-sadi-vsumn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İhanet acısıydı

Gönül cenazesiydi

Sarılıp birbirimize

Ağladık o gece

O, verdiği acıya

Ben, incinen onuruma

Sarılıp birbirimize

Ağladık o gece

Yıkan kim, yıkılan kim

Neden ellerimde ellerin

Sarılıp birbirimize

Ağladık o gece

Yere bakan alnımızı

Çöpe düşen gönlümüzü

Sorgulayıp halimizi

Sarılıp birbirimize

Ağladık o gece

2002', 'İhanet acısıydı Gönül cenazesiydi Sarılıp birbirimize Ağladık o gece O, verdiği acıya Ben, incinen onuruma Sarılıp birbirimize Ağladık o gec...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ihanetin-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '273 Nolu Rubai', '273-nolu-rubai-omer-hayyam-tnz2g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '273

Her gün her gece içmek, bitmeli; tövbe! 

Dolu kadehi artık itmeli; tövbe! 

Tam şimdi gül zamanı, her yer gül olmuş; 

Tanrım; artık tövbeye etmeli, tövbe!', '273 Her gün her gece içmek, bitmeli; tövbe!  Dolu kadehi artık itmeli; tövbe!  Tam şimdi gül zamanı, her yer gül olmuş;  Tanrım; artık tövbe...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/273-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '272 Nolu Rubai', '272-nolu-rubai-omer-hayyam-dseeo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '272

O gün Felek atına eğer vurdular.

Göklere de süs diye yıldız kurdular.

Orda verdi payımız'' kader divanı; 

Düşen günahı burda, bizden sordular.', '272 O gün Felek atına eğer vurdular. Göklere de süs diye yıldız kurdular. Orda verdi payımız'' kader divanı;  Düşen günahı burda, bizden sord...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/272-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '270 Nolu Rubai', '270-nolu-rubai-omer-hayyam-l1wzw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '270

Avcı yemi koydu ve bekledi sonra,

Avına Adem adı ekledi sonra,

Dünyada iyi, kötü her şeyi yapıp; 

Suçu hep başkasına yükledi sonra!', '270 Avcı yemi koydu ve bekledi sonra, Avına Adem adı ekledi sonra, Dünyada iyi, kötü her şeyi yapıp;  Suçu hep başkasına yükledi sonra!...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/270-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Rolünü Belirleyen Nedir?', 'hayat-rolunu-belirleyen-nedir-halay-sadi-am8wa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat bir oyun

Nasıl bir rol seçtin kendin için? 

Temkini elden bırakmayan mı? 

Sürprizlere yelken açan mı? 

Yoksa, karma bir yol

Katlanabileceği bir marj bırakan mı? 

Rolünün belirleyicisi kim? 

Sahip olduğun burcun mu? 

Ailen mi, çevren mi, toplum mu? 

Çekmecendeki, duvarındaki diploman mı? 

Sahip olduğun yaftan mı? 

2003', 'Hayat bir oyun Nasıl bir rol seçtin kendin için?  Temkini elden bırakmayan mı?  Sürprizlere yelken açan mı?  Yoksa, karma bir yol Katlanabil...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-rolunu-belirleyen-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '268 Nolu Rubai', '268-nolu-rubai-omer-hayyam-vl9w8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '268

Beni, toprak ve sudan kazdı; benim suçum ne? 

Dokuduğu ipek, çul, sazdı; benim suçum ne? 

İyi, kötü yaptığım her şeyi ve her sözü

Bu alnıma kendisi yazdı; benim suçum ne?', '268 Beni, toprak ve sudan kazdı; benim suçum ne?  Dokuduğu ipek, çul, sazdı; benim suçum ne?  İyi, kötü yaptığım her şeyi ve her sözü Bu aln...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/268-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '263 Nolu Rubai', '263-nolu-rubai-omer-hayyam-o1e5d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '263

Gönlün temiz mi hocam, kanıtın var mı? 

Gösterişten başka bir anıtın var mı? 

Hırkan, seccaden tamam; yarın sorunca; 

Tanrı''ya vermek için yanıtın var mı?', '263 Gönlün temiz mi hocam, kanıtın var mı?  Gösterişten başka bir anıtın var mı?  Hırkan, seccaden tamam; yarın sorunca;  Tanrı''ya vermek iç...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/263-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğidime', 'yigidime-halay-sadi-jpztz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerin ellerimdeyse, gözlerin gözlerimdeyse

Bir hataydı diyorsan tüm kalbinle

Gözyaşlarınla yıkanmışsa geçmiş

Geleceğimde sana yer verdiğimde

Sevinçle doluyorsa gönlüm

Daha ne düşüneceğim

Anlarım ki bebeğimsin

Eskileri koyalım bir torbaya

Beyaz saçlardan başka hatırası kalmasın

Torbayı atalım aşrı aşrı akan ırmağa

Kıyıya vurmasın, geriye dönüşü olmasın

Bebeğimsin, kuzgunumsun, yiğidimsin

Yüreğinle geldinse yine yeniden benimsin

Sarılırım sana, koklarım tenini

Bırak, bırak eller ne derse desin

2003', 'Ellerin ellerimdeyse, gözlerin gözlerimdeyse Bir hataydı diyorsan tüm kalbinle Gözyaşlarınla yıkanmışsa geçmiş Geleceğimde sana yer verdiğim...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yigidime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '260 Nolu Rubai', '260-nolu-rubai-omer-hayyam-it3kn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '260

Erenlere hizmet et, ermişlikten ayrılma.

Namaz kıl ve oruç tut, delilikten ayrılma.

Sözün en doğrusunu, dinle Ömer Hayyam''dan:

Şarap iç, yol kes ama; iyilikten ayrılma!', '260 Erenlere hizmet et, ermişlikten ayrılma. Namaz kıl ve oruç tut, delilikten ayrılma. Sözün en doğrusunu, dinle Ömer Hayyam''dan: Şarap iç,...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/260-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesaplaşma Zamanı', 'hesaplasma-zamani-cemil-aygen-0mt5r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oturun düşüncelerim

Sizinle hesaplaşmam var 

Beni iteklediğiniz bu çaresiz hayat için

Sorgularım var 

Neden aklımda hep yanlışa düştün

Neden hep çılgınlıklardaydınız 

Pişmanlıkları yarattınız bana

Düşüncelerim,düşündüklerim 

Geride kalmış yanlışlarım benim

Kendime ihanetlerim

Siz nasıl bilemezdiniz

Neden beni aldattınız

Çıkın aklımdan çıkın

Başka yüreklere girin birazda

Bana mutlu düşüncelerimi verin

Bu bir hesaplaşma zamanıdır

Artık yaşamak

Ama güzel yaşamak istiyorum 

Ne olur artık düzelin

Geçmişlerde kalmış üzüntülerim

Terkedilmişliklerim...Yaşanmışlıklarım 

Hepinizi kovuyorum 

Bugün benim hesaplaşma günüm

Oturun...Oturun...ve dinleyin

Yemin ettim..Bir daha

Kötü anılar bırakmayacağım geriye 

Benim istediğimce güzel olacak

Bunu bilin 

Ve toplantı bitti...

Kalbimi de odayı da terk edin.....', 'Oturun düşüncelerim Sizinle hesaplaşmam var  Beni iteklediğiniz bu çaresiz hayat için Sorgularım var  Neden aklımda hep yanlışa düştün Neden...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hesaplasma-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '252 Nolu Rubai', '252-nolu-rubai-omer-hayyam-mxrbv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '252

Kalıbımı şu topraktan söktüler,

Kötülükler toprağıma çöktüler,

Bundan daha iyi olamam, çünkü; 

O potadan beni böyle döktüler!', '252 Kalıbımı şu topraktan söktüler, Kötülükler toprağıma çöktüler, Bundan daha iyi olamam, çünkü;  O potadan beni böyle döktüler!...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/252-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '250 Nolu Rubai', '250-nolu-rubai-omer-hayyam-5rjtw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '250

Kimse emin değil ki şafaktan tekrar.

İste; gelsin, gül renkli şaraptan tekrar.

Sen altın değilsin ki, hey aptal herif; 

Gömüp de çıkarsınlar topraktan tekrar!', '250 Kimse emin değil ki şafaktan tekrar. İste; gelsin, gül renkli şaraptan tekrar. Sen altın değilsin ki, hey aptal herif;  Gömüp de çıkarsı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/250-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardım...', 'vardim-vatan-avanoglu-xwewl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vardım,varmısın diye sorduğunda oysa

Sıcak beyaz akşamda bize

Yıldızlar göz kırparken sinsice

Ve yakamoz ve ılık rüzgar...

Vardım,varmısın diye sorduğunda oysa

Yıldızlar alkış tuttu bu ''o'' diye

Ve martılar ve dalgalar...

Vardım,varmısın diye sorduğunda oysa

Güzeldim sende,dalındaki gülden

Martı kanadındaki özgürlükten çok

Ve güneşten ve günden...

Vardım,varmısın diye sorduğunda oysa

Güvenim ve şefkatim sende

Güvenin ve şefkatin bende

Ve dünler ve yarınlar...

Vardım,varolmalıydım,bilemeden

Sevdim çokça ve umarsızca,sevilmeden

Şimdiler de yokum oysa,yoktayım

Ve küskünüm ve zordayım...', 'Vardım,varmısın diye sorduğunda oysa Sıcak beyaz akşamda bize Yıldızlar göz kırparken sinsice Ve yakamoz ve ılık rüzgar... Vardım,varmısın d...', ARRAY['Türk Edebiyatı','Şiir','Vatan Avanoğlu']::text[], 8.5, '{"poet":"Vatan Avanoğlu","poet_slug":"vatan-avanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/vardim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '241 Nolu Rubai', '241-nolu-rubai-omer-hayyam-ddss5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '241

Ne kazandım dünyadan? Sorulunca: Hiç.

Şu kısacık yaşama sarılınca? : Hiç.

Yanan neşe mumuyum, üzme boşuna; 

Cem elinde kadehim, kırılınca: Hiç.', '241 Ne kazandım dünyadan? Sorulunca: Hiç. Şu kısacık yaşama sarılınca? : Hiç. Yanan neşe mumuyum, üzme boşuna;  Cem elinde kadehim, kırılınc...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/241-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Newal''ime', 'newal-ime-ahmet-mese-t7zll', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşündüm yine,

beni düşünürken

bir anda çiçekler açtı 

yüreğimin kurumaya yüz tutmuş ağaçlarında,

ansızın bir düş kurdum,

kaybolmasın diye acıtan anılarımın kalabalığında

katlayıp yüreğimin iç cabine koydum', 'Seni düşündüm yine, beni düşünürken bir anda çiçekler açtı  yüreğimin kurumaya yüz tutmuş ağaçlarında, ansızın bir düş kurdum, kaybolmasın d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meşe']::text[], 8.5, '{"poet":"Ahmet Meşe","poet_slug":"ahmet-mese","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/newal-ime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ünye', 'unye-vatan-avanoglu-grbra', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni içimde yaşattığım yerdi Ünye

Yeşiliyle,doğasıyla ve sahiliyle

Aşkımızı haykırıyordum bir kalemde

Sensiz gecelere...

Bu şehirde kavuştuk birbirimize

Bu sahilde kavuştuk,yağmurda elele

Şehir bizi alkışlıyordu,şevkle

Sen yanımdayken bir başka bu Ünye...', 'Seni içimde yaşattığım yerdi Ünye Yeşiliyle,doğasıyla ve sahiliyle Aşkımızı haykırıyordum bir kalemde Sensiz gecelere... Bu şehirde kavuştuk...', ARRAY['Türk Edebiyatı','Şiir','Vatan Avanoğlu']::text[], 8.5, '{"poet":"Vatan Avanoğlu","poet_slug":"vatan-avanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '"Bir Tek Gül"', 'bir-tek-gul-firat-yilmaz-d7a84', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uğrak yerinden gönlümün

Kervanın geldi geçti

Bağımdan bir tek gül

Üç beş diken ziyan

Hepsi buydu ilk sızının

Sonrası feryat figan', 'Uğrak yerinden gönlümün Kervanın geldi geçti Bağımdan bir tek gül Üç beş diken ziyan Hepsi buydu ilk sızının Sonrası feryat figan...', ARRAY['Türk Edebiyatı','Şiir','Fırat Yılmaz']::text[], 8.5, '{"poet":"Fırat Yılmaz","poet_slug":"firat-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-tek-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Fazla Düş(men) e Gerek Yok', 'daha-fazla-dus-men-e-gerek-yok-humeyra-yilmaz-jjqp7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Giden memnun gittiği yerden. Kalanlar ölüm şehrinde yaşamaya mahkum. Üzerlerinde yalandan bir kefen, gözlerinden akan acı gerçekler

Ve biri bir dokunsa ÖLECEKLER...

Benim de kapımda gözü yaşlı bir bahar,

Yüreğimde, 

Aslında hiç yaşanmamış bir aşkın 

Mentol kokan parçaları var...

İki dirhem bir çekirdek olmuş aşkın yeni adı 

Madem her şey bu kadar ucuz

Neden dilenir ki insan? 

Sadece sustum ve

Beni sakladığın yerde duruyorum 

Kan çanağı gözlerimde iki damla yaş

Biri gerekli diğeri gereksiz  / yanıyorum

Hangi geceyi vursam bir sevdaya 

Dökülüyor yıldızları 

Bomboş kalıyor gökyüzü

İsyan satıyor ay, karanlığın koyu rengine

Soğuk bir sevda şahit oluyor bu alış verişe

İnandığın kadar yalan oluyor aşk

Ve aşık olduğun kadar yalan oluyorsun

Perde perde iniyor yüzüne hüzün

Sessizlik uyuyor

Dört köşeli bir mendilin içinde 

Eğer senin de 

Söyleyecek yalanların bittiyse

Terk et bu şehri 

Yoksa her şiirim bir kurşun olacak

Ve sen ölünceye kadar yazacağım...!', 'Giden memnun gittiği yerden. Kalanlar ölüm şehrinde yaşamaya mahkum. Üzerlerinde yalandan bir kefen, gözlerinden akan acı gerçekler Ve biri ...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/daha-fazla-dus-men-e-gerek-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Dünya...', 'yalan-dunya-ayfer-yildiz-rxo7m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üç günlük yalan dünya,

Belli değil yarınlar kim öle kim kala,

Söylesenize dostlar görülmüşmü dünya malı gidenin yanına kala...

Her şey boş,

Bitmez gibi bu yol koş babam koş,

Nefesin tıkanırda içersen bir tas su adın olur sarhoş,

Hele tükenirse dizinde derman adın konur yaralı topal kuş,,,

Bu yolun yolcuları hepten farklı,kimi yayan kimi arabalı,

Kimi koşuyor kimi emekliyor,

Kimi binmiş birinin sırtına bulmuş ki öyle bir rahatı,

Kimi de sürünmekten yorulmuş zavallı kara bahtlı...

Akıl ermez feleğin işine,

Söz dinletemezsin yazılmış bir kez kaderine,

Ya tuz basar ya bal çalar bir lokma ekmeğine,

Aman be dostum boşver üzülme,yalan dünyanın yalan gidişi böyle...', 'Üç günlük yalan dünya, Belli değil yarınlar kim öle kim kala, Söylesenize dostlar görülmüşmü dünya malı gidenin yanına kala... Her şey boş, ...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Yıldız']::text[], 8.5, '{"poet":"Ayfer Yıldız","poet_slug":"ayfer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalan-dunya-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin Uzun Bir Geceydi', 'ellerin-uzun-bir-geceydi-selahattin-yetgin-hbeo3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerin uzun bir geceydi

Ezik ve karanlıktı yalnızlık

Konuşsak dağılacaktı belki

Bir çöküntüydü sis ve ayrılık.

	İçimizdeki sıcacık odalarda mutluluğu paylaşmak uğruna gözyaşlarımıza acılarımızı sarıp sarmaladık yıllarca. Bulutların altında durmaksızın giden bir trenin aynı yolcularıydık. Uzak o istasyonun çivileri sökülmüştü raylarından. Ve o trenin arkasından durmaksızın koşan çocuklar gibi geçirdik hayatımızı.

	Sabahın olmasını hiç istemediğimiz uykularda, ellerin uzun bir geceydi. Soğuk ve karanlık geceler gibiydi yalnızlık. Konuşsak, dağılacaktı dertlerimiz. Sisler gibi çöktü üzerimize ayrılık. Suskun  bir üzüntüye sarılmıştı yüreğimiz. 

	Renklerin suskun olduğu  anlarda gelişinle sevinç  duyardım. Kimi zaman  sevişirdik titrek odalarda. Ellerin ellerime değince öfkelerim zindanlara kapanırdı. Gözlerini gözlerime değince  umudumun zulasına gizlenen tüm sözlerim dizilirdi sofralara.

	Yakamoz ışıltılı gözlerin çekilince denizden, suskun misali uzanırdım yüzüne. Anlamsızlığımı sözcüklerle üretmeye çalışırdım. Geçersiz bahanelerle yurduna ulaşmayı, ellerini, gözlerini ve yüreğini yeniden kazanmayı düşlerdim.

	Yokluğunu falcı çingenelerle paylaşırdım. Ayrılık kulpunu takıp koluma sokaklarda bir başıma yürürdüm. Gökyüzündeki kuşları çağırıp oturduğum banklara dökerdim derdimi.  Anlaşılmaz bir boşlukta sallanırken, yağmurlar yağardı üstüme. Yıldızlara tutunan gözlerin içime bir ateş yüklerdi. Daralırdı yüreğim. Gül yaprağı dudakların diken olurdu dilimde.

	Benim adım sevdadır ve omzuma her sabah bir güvercin konar. Boyun bükerek bakarım sevgisizlere. Künyeme aşk, göğsüme sevda, yüreğime acı nakşederim. Neleri giydim de bugüne dek, neleri çıkardım üzerimden henüz kirlenmeden. Mavi düşler boyamıştı usumu. Yeşil yapraklarla donatmıştım sevgi bahçemi. Şiirler diktim, imgelerle bezedim yüreğimin topraklarını.

	Bir bezirgânım ben, kimi zaman aşk satarım. Takastadır sevgilerim. Sızım sızım sızlar   içim. Rüzgârım kimi zaman, yelimden korkarım. Limanda el sallarım dostlarıma. Kimi zaman haziran olur, eylül''de aşkı yaşarım.

	Hain olacaksa bugünüm sevinci yarında yaşarım. Örse tutarım sevdamı. Sızlar ara sıra içim, vefasızlıklara söverim. Kimi zaman yağmurum ben, dolu dolu yağarım, kimi zaman ele avuca sığmaz, mevsimlere nispet edercesine vakitsiz yağarım. 

	Biliyorum, sınırsızlığın bir sınırı vardır. Özleyişlerimin hiç biri beş para etmez. Allar sürülü bir dünyanın yankısı durur halâ içimde. Yanılgılarıma aldırmaz, gözbebeklerimi ağrıtan gecelerde, denizin yüreğine inmeyi düşleyen bir sevda yolcusuyum ben. Yankımın sıfır noktasında kaybettim silüetimi. Hesapsız duruşlarla tükettim gençliğimi. Rüzgara savurdum,   kaybettim acımasız  geri dönüş biletimi.

	Tufanlara gebe şu ömrümün ütopyasında sevgiler uçurumundan geri dönüyorum işte. Yalnız senin için yaşamalarım bitti. Bir fırtına kuşu beslemişim yıllarca yüreğimde. Baharlarım elbet geri dönecek ve bitecek bu yanılgılı duruşlarım. Seni sevmelerin eskiyen biletlerini topladım uçurumlardan.

	Evet bebeğim. Ellerin çok uzun bir geceydi ve şimdi gündüzlere döndüm yüzümü. Karanlıkların tortusuna, geçen yılların yankısına kapattım kapımı. Gürül gürül yüreğimle sevgi dolu yüreklere  veriyorum ellerimi. Üşümüş, kanatları sarkmış fırtına kuşlarını alıyorum odamdan içeri ve ellerimle seviyorum sevgiye aç, sevginin değerini bilen kutsal yürekleri.', 'Ellerin uzun bir geceydi Ezik ve karanlıktı yalnızlık Konuşsak dağılacaktı belki Bir çöküntüydü sis ve ayrılık. 	İçimizdeki sıcacık odalarda...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ellerin-uzun-bir-geceydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi Yüreklim', 'asi-yureklim-selahattin-yetgin-8sy4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Lirik yüreğinin hıçkırık boğumlarında

Efsaneler dile gelir, dillenir acıların

Yüzyıllardır Mecnun''un çöllerde aradığı

Leyla''sın sen, bu yaşama alışamayan

Ağlayışlarını bile kimselere göstermeyen..

	Anlatmazsan, dertlerini söylemezsen, içindeki fırtınalara yön vermezsen, kim bilecek dertlerini? . Ağlamazsan, yüreğinin sel kapaklarını açmazsan, isyanlarını bir kütüğe yatırıp indirmezsen baltanı, kim bilecek baş kaldırışlarını? .Uçarı bir alev topu gibi dönen, günleri bir kurt gibi kemiren bu zaman makinesi nasıl çalışacak, gözyaşlarını ve hıncını gizlersen.

	Yaşadıklarının akrep uçlarında dönek insanlar bir pervane böceği gibi dönerler çevrende. Yüreğine girmeyi beceremeden, pembe düşler kurarlar uslarında. Yalnızlık yansıtan kolalı gömleklerinin ütüsüz kıvrımlarında aldanışları taşırlar, bedevi zalimliğiyle sürek avına çıkarlar bu garip yaşamın ormanlarında.

	Oysa, avcı da kendileridir, av da. Bir bardak su dileyemedikleri, susuz dolaştıkları bu yerkürede kurumuş dilleriyle yağmur yağmasını dilerler, hiç inanmadıkları tanrıdan. Menfaatlerinin ağılındaki kuzuları her gece kurtlara meze yaparlar, her gece çizgili pijamalarıyla bir eşikte mırıltılı ve korkulu bakışlarla uykulara dalarlar.

	Susma! . Suskunluklarını içine gömme bir daha. Lirik yüreğinin hıçkırık boğumlarında efsaneler dile gelsin, dillensin acıların. Yüzyıllardır Mecnun''un çöllerde aradığı Leyla''sın sen, bu yaşama alışamayan, ağlayışlarını bile kimselere göstermeyen. 

	İki kere ikinin dört ettiğini parmakla hesaplayabilen bu kalabalık insan duraklarında maskesiz dolaşamayan, gecenin karanlığından korkan insanlar kaybolurlar güneş batınca. ''Zaman, acıya en iyi merhemdir'', unutma bunu. Silemediğin gözyaşlarının kutsal kriterlerinden güneşe yansımalar gönder her yalnız kaldığında. İçindeki fırtına hasatlarında ve bu çarpık düzenin biyografisinden güzel karelerle doldur ömrünü.

	Kopar ömrünü törpüleyen öfke budaklarını yaşam ağacından. Öfke yeni kızgınlıkları doğurur unutma. Bu şehirde, sevginin yağmurları nice siyahları, acıları götürür masmavi denizlere. O denizlerden bu günah dünyasına yolalan bir gemi, pusulası sadece aşka çevrili bir yelkenli olursun, bir efsaneye gider gibi.

	Ve o efsanenin huzurlu kollarında dilindeki şarkılarla yürürsün bu kentin kaldırımlarında. Söversin tüm olumsuzluklara dobra dobra. Unutursun yaşadığın tüm acıları. Ellerindeki çiçekler, gözlerindeki şefkâtle sihirli bir dünyaya dökersin yüreğinin tüm güzelliklerini.

	Evet Asi Yüreklim, yüreğinin silahlarıyla çıktığın bu savaşta yolun açık olsun. Çirkefliklerin hiç uyumadığı bir dünyanın kilometrelerinde uğradığın haksızlıklar her devirde aynı olsa da, aynı kelimelerin tuzaklarına düşsen de, yıkılmamayı koymuşsan kafana başaracağından emin ol. Bugün yeni bir güne merhaba diyerek yürü bu uzun yollarda. Onurunla ve karakterinle nice zorlu hendekleri koşarak aş. Sevgilerin bahçesine uzanınca öfkelerin bitecek, tüm yaşadıkların küflenmiş bir film şeridinde geçmişin mahzenlerine inecek.', 'Lirik yüreğinin hıçkırık boğumlarında Efsaneler dile gelir, dillenir acıların Yüzyıllardır Mecnun''un çöllerde aradığı Leyla''sın sen, bu yaşa...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asi-yureklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Of Off..', 'of-off-nejat-karagoz-pg7wn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Demir gece

Kapkaranlık gök yüzü

Dünyada tek başınayım sanki

Kesif bir sessizlik içinde evren.

Ellerim buz kesilmiş

Yüreğimde kan sıcaklığı

Nefesim alev alev 

Sıtma ateşinden.

...

Arada bir bozuluyor sessizlik

Uzakta,çok uzakta bir türkü sesi; 

Memleket hasreti.

...

Yamandı korkuyla yaşamak

Yamandı tedirgin bekleyişler

Korkunçtu kendi vatanında,yaşamak

İliklerine dek esareti...

Of ki of

Şimdi seninle olmak vardı

Küçük bir ateş,

Sıcacık bir çay

Ve yürekleri ısıtan dost sohbeti..

Hafiften fısıldayacaktın gene o şarkıyı

Gülüşecektik gene 

Anacaktık eski güzel günleri

Memleketi...', 'Demir gece Kapkaranlık gök yüzü Dünyada tek başınayım sanki Kesif bir sessizlik içinde evren. Ellerim buz kesilmiş Yüreğimde kan sıcaklığı N...', ARRAY['Türk Edebiyatı','Şiir','Nejat Karagöz']::text[], 8.5, '{"poet":"Nejat Karagöz","poet_slug":"nejat-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/of-off-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Gece', 'islak-gece-vatan-avanoglu-gvq1b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Islak gece sarıldı karanlığa

Tek başınalığa razı gelmiş kendim ve sigaramla

Işıktan ve sesten medet umarken gecede

Karıştım karanlığa...

Perdesiz penceremde ben,

Sarı tütsümün aydınlığa ve çisil çarparken cama

Beterinden kaçmak ya hep savaşın

Sarıldım sarıya ve yağmura

Küçük sarı aydınlık,sigaram ve bir de ben,,,', 'Islak gece sarıldı karanlığa Tek başınalığa razı gelmiş kendim ve sigaramla Işıktan ve sesten medet umarken gecede Karıştım karanlığa... Per...', ARRAY['Türk Edebiyatı','Şiir','Vatan Avanoğlu']::text[], 8.5, '{"poet":"Vatan Avanoğlu","poet_slug":"vatan-avanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/islak-gece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen', 'gidersen-ahmet-naci-cogaltay-avfi9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu şehirden gidersen 

gökyüzü benim kadar yaş dökemiycek. 

hiçkimsede benim kadar 

sana sıkı sıkı sarılmak isteyemiyecek. 

neolur öpmeden gitme 

neolur bakmadan gitme.... 

sana bakmak 

okyanusta yolculuk gibi 

seni sevmek 

vangölünü bi uçtan diğer uca yüzerek geçmek gibi 

seni öpmek 

sana ulaşmak demek 

nolur bakmadan gitme 

nolur öpmeden gitme', 'bu şehirden gidersen  gökyüzü benim kadar yaş dökemiycek.  hiçkimsede benim kadar  sana sıkı sıkı sarılmak isteyemiyecek.  neolur öpmeden gi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Naci Çoğaltay']::text[], 8.5, '{"poet":"Ahmet Naci Çoğaltay","poet_slug":"ahmet-naci-cogaltay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gidersen-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Sana Ayan', 'her-sey-sana-ayan-zulfikar-yapar-kaleli-rya9p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tereddütsüz başı senin yoluna

Koyanlar bu yurdun sevdalıları

Hilâlle yıldızı kendi salına

Oyanlar bu yurdun sevdalıları

Unutmadı, şeref saydı dününü

İki cihan duydu onun ününü

On bir yıldır zindanlarda gününü

Sayanlar bu yurdun sevdalıları

İnsanlar var, kesir küsür bayağı

Gelinler var, bayraktandır duvağı

Şu malum düzende iki ayağı

Kayanlar bu yurdun sevdalıları

Kaleli, fikrimiz ayan sır değil

Yüzler var cefâda, yüzler, bir değil

Başkasına yaltaklanan er değil

Cayanlar bu yurdun sevdalıları', 'Tereddütsüz başı senin yoluna Koyanlar bu yurdun sevdalıları Hilâlle yıldızı kendi salına Oyanlar bu yurdun sevdalıları Unutmadı, şeref sayd...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-sey-sana-ayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimez Beyitler 16', 'eskimez-beyitler-16-huseyin-avdic-6qxk1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Edebiyat arıyorum edebiyat.

Karşımdan geliyor sefiliyat! 

******

Ümid, ak toprak ak.

Yeis,  kara toprak! 

******

Kıral köle olur, yüce cüce.

Bir kaç yavru dünyaya gelince.

******

Şiir, insandan sızan bir kir.

Bu kir, Kur''ana giden fakir.

******

Rüyada yaşarım yaşamadan.

Her olacağı yazmış Yaradan.

******

Bizi biz edemez, dışımızdaki parti.

İçimizde kurarsak, kurtuluruz belki.

Batı Berlin, 1980-85.', 'Edebiyat arıyorum edebiyat. Karşımdan geliyor sefiliyat!  ****** Ümid, ak toprak ak. Yeis,  kara toprak!  ****** Kıral köle olur, yüce cüce....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eskimez-beyitler-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Üşümesin...', 'ozgurluk-usumesin-zulfikar-yapar-kaleli-0edr7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayal kadar özgürlüğü

Koy gönülde üşümesin

Sırttandır sesin gürlüğü

Duy gönülde üşümesin

Avantaya üslenen o

Her pislikten beslenen o

Kuzgun gibi seslenen o

Huy gönülde üşümesin

Her çeneye damak olur

Her işleve yumak olur

Bir namerde yamak olur

Boy gönülde üşümesin

Vurgun vuranı görünce

Tam yetişir ondan önce

Araştırır ince ince

Vay gönülde üşümesin

Sanma sakın pişmandır o

Kene gibi şişmandır o

İnsanlığa düşmandır o

Soy gönülde üşümesin', 'Hayal kadar özgürlüğü Koy gönülde üşümesin Sırttandır sesin gürlüğü Duy gönülde üşümesin Avantaya üslenen o Her pislikten beslenen o Kuzgun ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozgurluk-usumesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pay...', 'pay-zulfikar-yapar-kaleli-vum1s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyada ne bulduk bugüne kadar? 

Gam, kasavet, keder payımız olur.

Yücelmek ülkümüz, azmimiz de var,

Ne abi ne emmi dayımız olur.

Çoğu abad oldu, ahdinden döndü,

Bazıları döner koltuğa sindi,

İşsizler, güçsüzler vallahi yandı,

Artık dere suyu çayımız olur.

Toplumda ne düzen ne de var ahenk,

Deliye gün bayram taşırız çelenk,

Hayasız, arsız, yüssüz, pezevenk,

Saniye haftamız, ayımız oldu.

Kaleli her söze inanmam, kanmam,

Gül deyip, gül sanıp, her dala konmam,

Özler yaradana doğruysa tamam,

Elbet düğün, dernek, toyumuz olur.', 'Dünyada ne bulduk bugüne kadar?  Gam, kasavet, keder payımız olur. Yücelmek ülkümüz, azmimiz de var, Ne abi ne emmi dayımız olur. Çoğu abad ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pay-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıntı Baba...', 'kirinti-baba-zulfikar-yapar-kaleli-rowwu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökte kervan yürür onu izlerim

Uğraşım bu, ister isen zır bil sen

Çocuk günlerimi nasıl özlerim

Bir bilsen ah, yağmur gözlüm bir bil sen

Soğanlı somunu tuzladığım gün

Ayaktan ıslanıp sızladığım gün

Arifler yolunu izlediğim gün

O efendim, ben köleyim hür bil sen

İstemem er ile cenge girmeyi

Anlamsız söz ile çam devirmeyi

Şu taşlı yamacı, şu çevirmeyi

Ne anlamsız ve ne hoyrat yer bil sen

Çare boğum boğum, çile düğümsüz

Bağlamış bülbülü güle düğümsüz

Beni aşık etmiş dile düğümsüz

Aşikare şu meydanı sır bil sen', 'Gökte kervan yürür onu izlerim Uğraşım bu, ister isen zır bil sen Çocuk günlerimi nasıl özlerim Bir bilsen ah, yağmur gözlüm bir bil sen Soğ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirinti-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbret...', 'i-bret-zulfikar-yapar-kaleli-shn26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Yücel Şahin''e -

Şu vatan dediğim kabristan yerde,

Yavaş yavaş eriyorum, ibret al.

O muhteşem, eski günlerim nerde? 

Emaneti sürüyorum, ibret al.

Hep Hakk dedim, Hakk bağırdım, ha bire,

Yer vermedim asla gönlümde kire,

Ayağımla yavaş yavaş kabire,

Saat saat yürüyorum, ibret al.

Eski günlerime bir göz atınca,

O günle bugünü tartı tutunca,

Düzen uyduruğu sözü yutunca,

Nefsime ders veriyorum, ibret al.

Ne güleç yüzüm var, ne mutlu günüm,

Arkamda uçurum önümde ölüm,

Sevabı, günahı saymışım dünüm,

Yarınlara giriyorum, ibret al.

Girdiğim yarını sizler verip,

Yarının şevkini dünlerde görüp,

Görün ibret alın, bu güne erip,

Benliğimi koruyorum, ibret al.

Neşemiz, kaygımız, tasamız birdi,

Yaş geldi zevale, bir gün mü gördü? 

Kaleli yarını sizlere verdi,

Dünlerimi arıyorum, ibret al.', '-Yücel Şahin''e - Şu vatan dediğim kabristan yerde, Yavaş yavaş eriyorum, ibret al. O muhteşem, eski günlerim nerde?  Emaneti sürüyorum, ibre...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ibret-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim Ama...', 'hasretim-ama-zulfikar-yapar-kaleli-1fjec', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşmüşüm kör kütük dipsiz çukura

Barışamam, ömür kısa, yol uzun

Umutlarım gece gibi, kapkara

Karışamam, ömür kısa, yol uzun

Vefâsızlık beni dile düşürdü

Oyaladı, bile bile düşürdü

Derdimi denkleyen ile düşürdü

Görüşemem, ömür kısa, yol uzun

Düşman oldum, her yönümle, her yanla

Bir derim,  arif ol, binini anla

Artık bundan sonra, falan filanla

Vuruşamam, ömür kısa, yol uzun

Hani âhde vefa vardı ya işte

Aranır olmuştur, hayalde, düşte

Hayır aransa da her türlü gidişte

Girişemem, ömür kısa, yol uzun

Dağın ardı duman, görünmez emen

Kalpazan her şeye uydurur dümen

Her türlü cilveye, her şeye rağmen

Yarışamam, ömür kısa, yol uzun', 'Düşmüşüm kör kütük dipsiz çukura Barışamam, ömür kısa, yol uzun Umutlarım gece gibi, kapkara Karışamam, ömür kısa, yol uzun Vefâsızlık beni ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasretim-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müdahale...', 'mudahale-zulfikar-yapar-kaleli-83bxp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle dağınık ki dakikam, günüm

Gezmek istiyorum, gezdirmiyorlar.

Şanlı geleceğim, şerefli dünüm

Sezmek istiyorum, sezdirmiyorlar

Geçim yükü her gün kırar belini

Beş yıldır nişanlı durur gelini

Can çekişen çoklarının halini 

Yazmak istiyorum, yazdırmıyorlar.

Sevdam yaşar zamanın her anında

Sade yüzüm olsun Resul yanında

Her şeyi bir yana koyup sonunda

Tozmak istiyorum, tozdurmuyorlar.

Bırakırsan derdin azar da azar

Kimi yalan söyler, gerçeği yazar 

Taht’ı kabir yapıp,üstüne mezar

Kazmak istiyorum, kazdırmıyorlar.', 'Öyle dağınık ki dakikam, günüm Gezmek istiyorum, gezdirmiyorlar. Şanlı geleceğim, şerefli dünüm Sezmek istiyorum, sezdirmiyorlar Geçim yükü ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mudahale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaktırmadan Seviyorum', 'caktirmadan-seviyorum-sahin-erturk-u44o2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söylemeye korkuyorum

Seni candan seviyorum

Hasretinle yanıyorum

Çaktırmadan sevdim seni

Haberin yok sevdiğimden

Haberin yok yandığımdan

Haberin yok çektiğimden

Çaktırmadan seviyorum

Ürkütmeden sevdim seni

Kızdırmadan sevdim seni

Beklentisiz sevdim seni

Çaktırmadan sevdim seni

Hayalinle konuşanım

Yazdığını okuyanım

Mesajını bekleyenim

Çaktırmadan seviyorum

Resmin bile yok elimde

Kız kıtlığı varmış gibi

Görmediğim güzel seni

Çaktırmadan seviyorum

Senin için kafa yordum

Pembe,yeşil düşler kurdum

Bu ŞİİRİ sana yazdım

Çaktırmadan seviyorum

(17.06.2005-Yeni)', 'Söylemeye korkuyorum Seni candan seviyorum Hasretinle yanıyorum Çaktırmadan sevdim seni Haberin yok sevdiğimden Haberin yok yandığımdan Habe...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/caktirmadan-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekil(ler)', 'tekil-ler-bekir-mutlu-gokcesu-l4qbo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her gece bu geceydi aslında

İzafi zamanlarda katlandı yalnızlıklar

Ki en kalabalık haliydi bir tekilin

Yalnızlık da yoktu aslında...

Geceyi ve zamanı yutan

Dipsiz kuyudan aynalarımızda

Çoğaltanıydık birbir(ler) imizin

İçimizden biri/leri hep yoktu aslında...

Her gece böyle bir geceydi 

Ya yağmur yağar ya ben ağlardım

Ya bir şiir düşerdi tutardım ellerinden

Ya bir düş vurulurdu öperdim gözlerinden...

Bir yıldız mutlaka kayardı her seferinde

Ben uyumadan önce...

İzafi zamanların aldatılanı, azalanlarıydık sözde

Oysa biliyor, hissediyordum çığ gibi çoğaldığımızı

Tanış yüreklerce...', 'Her gece bu geceydi aslında İzafi zamanlarda katlandı yalnızlıklar Ki en kalabalık haliydi bir tekilin Yalnızlık da yoktu aslında... Geceyi ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tekil-ler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yesil deniz', 'yesil-deniz-tamer-avci-h2zns', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yesil bir deniz

Guzel bir gece

Ben bir liman

Sen bir yaz

Once sana sariliyorum

sonra ayaz

o bir gemi

sen bir yaz

gemi gelmedi

gelmeyecek

surecek   ayaz….

17-06-2005 tashkent', 'Yesil bir deniz Guzel bir gece Ben bir liman Sen bir yaz Once sana sariliyorum sonra ayaz o bir gemi sen bir yaz gemi gelmedi gelmeyecek sur...', ARRAY['Türk Edebiyatı','Şiir','Tamer Avcı']::text[], 8.5, '{"poet":"Tamer Avcı","poet_slug":"tamer-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yesil-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar', 'yillar-sinan-karakas-er2kl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şikayetim var yıllara

Neler çizdi anılara 

Evvel siyah olan saçlar

Şimdi dönmüştür kışlara

Yıllar sizden çektiklerim

Boşa gitti emeklerim

Selvi gibi uzamışken 

Neden eğik kemiklerim

Yıllar yıllar zalım yıllar

Beynimde acı sızılar 

Bir ikisi ağlıyorsa

Şimdi gülüyor bazılar', 'Şikayetim var yıllara Neler çizdi anılara  Evvel siyah olan saçlar Şimdi dönmüştür kışlara Yıllar sizden çektiklerim Boşa gitti emeklerim Se...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yillar-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba/Sızım', 'baba-sizim-orkun-isik-ydsfw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanağımda Kuruyan Bir Damlasın... 

Geceden bir damla düşer gökyüzünden 

Ve takılı kalır kirpiklerimde, 

İki kişi sedanın derinliğinde, terennümde…

Sen CAN bense kanayan SIZIYIM 

Yani; Aynama vuran Terazinin CANSIZIYIM! ! ! .

Birler BİR’i bilebilirler mi? .. 

Şimdilerde zaman uğultu renginde 

eriyip gidiyor tuval denen hüzünlerden. 

Ellerim yok ki tutayım! 

Gözyaşlarını döküyorlar pınar pınar

Zamana, zamanın peşinden geri gelsin diye.. 

Ya da bilmem niye. 

Onlar Onumu görebilirler mi? .. 

İç profilimin saman renkli duvarlarında? 

özlemlerimin elinde bir fırça 

boyadıkça boyuyor, çizdikçe çiziyor, 

Ardında ne var ne yok demeden 

Çizdiği yere göçüp gidiyor 

Çizgi ötesindeki sonu görmeden 

Neyin ne olduğunu bilmeden. 

Orada O var ya! 

Yüzler Yüzüme çarpılıyor

 “Şahadet parmağımı” kaldırıyorum 

-Ben yalnızım ben yalnızım, 

üşüyor parmağım sonsuzluga deyerken. 

Kimseler duymuyor Ondan ve senden başka, 

Yalnızlık sabırsızken, vakit değil miydi çok erken? 

Ah çok erken çok erken! .. 

Avuçlarımda zaman boğulurken. 

yollardaki kalabalıkların omuzundasın

başbaşayım sensizlikteki sende

yine ben çok yalnızım kalabalıklar içinde … 

Bilirsin senin gibiydim bende 

Yani sen öyle derdin… 

En Çok z/amansız ayrılıklardan nefret ederdik 

Sadece ikimiz, ne kızın ne karın 

Ne çocuğun, ne de oğlun! 

Hep şuna kızdık ikimiz; 

Ardına dönmeden, gidiyorum bile demeden, 

çekip gitmelere, ah senin gibi gitmelere! ! ! 

Suçluymuşum gibi neden bakıyorsunki, 

Bırakıp giden ben miydim sanki? ! .. 

Hani,bırakıp giderken tutamamıştık ya ellerimizi

Ama giderken bıraktığın gözlerin,

halâ gözlerimde saklı şimdi…

Ey CAN/SIZIM! ! !', 'Yanağımda Kuruyan Bir Damlasın...  Geceden bir damla düşer gökyüzünden  Ve takılı kalır kirpiklerimde,  İki kişi sedanın derinliğinde, teren...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/baba-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Desem...', 'gel-desem-taner-nisanci-pqolz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gül yüzünden divane oldu gönlüm

Merhem olup sür desem sürer misin? 

Ah ile vah ile geçti bu ömrüm

Gel desem, çağrıma cevap verir misin? 

Aslı’ya vurgun Kerem misali ben

Üç beş nöbetinde,uzaklar da sen

Adını sayıklarım inleyip, her an

Gel desem, çağrıma cevap verir misin? 

Gece en derin uykudan uyanıp

Yokluğunda hayaline dayanıp

Seni çok özledim diye bağırıp

Gel desem, çağrıma cevap verir misin? 

Hasret dağını yakıp da eritsem

Senden gayrı kalptekini arıtsam

Zamanı değirmenlerde öğütsem

 Gel desem, çağrıma cevap verir misin? 

Yaralı ceylanım aklım hep sende

Hasrete dayanacak güç yok tende

Son bir ümitle,Son sesleniş bende

Gel desem, çağrıma cevap verir misin? 



                                                        06/12/2003', 'Gül yüzünden divane oldu gönlüm Merhem olup sür desem sürer misin?  Ah ile vah ile geçti bu ömrüm Gel desem, çağrıma cevap verir misin?  Asl...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gel-desem-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yarası', 'sevda-yarasi-vatan-avanoglu-rt7pl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Paylaşmanın,sevmenin,sevilmenin

Dışa vurması,yürekten seslenerek haykırmanın

Ve şiirlere tek tek dökülmenin

Acılarını,çığlıklarını,kaleme dökmenin

Ötesi yok! 

Ağlamanın,gözyaşlarının silinmesinin

Islak kağıt mendillerinin bile saklanması

Hatıra olarak görülmesi,yaşanması

Duyguların yoğunlaşması,yazılması

Bunun adının''sevda yarası'' olması

Unutamamak olması...', 'Paylaşmanın,sevmenin,sevilmenin Dışa vurması,yürekten seslenerek haykırmanın Ve şiirlere tek tek dökülmenin Acılarını,çığlıklarını,kaleme dö...', ARRAY['Türk Edebiyatı','Şiir','Vatan Avanoğlu']::text[], 8.5, '{"poet":"Vatan Avanoğlu","poet_slug":"vatan-avanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevda-yarasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Karanlığı Sevmek**', 'karanligi-sevmek-seyhmus-sevilmez-mj9b7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlığı çok severim bilir misin? 

Ne güneş ışığında gördüm tenini, 

Ne de kulaklarım anlıyordu dilini. 

Yüzünün rengi, ha esmer olmuş, ha sarışın. 

Ne fark eder ki? 

Karşılıklı uzlaşmak için, 

Konuştuğun lisanı anlamak kafi değil mi? 

Her şeyden önce, insan olduğun için 

Ve karanlıkta insanların rengi bir olduğu için, 

Karanlığı çok severim. Bilir misin? 

İnsanları çok sevişim belki o yüzden. 

Ve o yüzden karanlıklarda sarılırım canlara. 

Sıcacık yüreğime basarım sıcak yürekleri. 

Karanlıkta; 

''''Seni seviyorum'''' diyen dillerin bütün anlamları bir. 

Dost ve kardeşçesine bütün sarılışlar sıcak. 

Karanlığı çok severim çok... 

Çünkü, 

Karanlıkta 

Sınıflamalar, ayırımlar ve ırkçılıklar yok. 

Sahte yüzleri görmemek için, 

Karanlığı benimsedim ozümde… 

Karanlıklarda her kes insan göründüğü için 

Ve insanların rengi bir olduğu için, 

Karanlığı çok seviyorum çok……… 

Karanlıklar ne için sevilir, anlar mısın?', 'Karanlığı çok severim bilir misin?  Ne güneş ışığında gördüm tenini,  Ne de kulaklarım anlıyordu dilini.  Yüzünün rengi, ha esmer olmuş, ha ...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/karanligi-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Gözüm', 'kor-gozum-yusuf-ter-x1jeh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I

Kör gözüm 

Geceye

Yârimdir 

Kem dırdırına

Işıl ışıl

Ağlar kucağında

Ak göğsünde

Emer emer

Uçundadır

Hadi be

Git güle güle

Şiirler söyle

Kara sevdalara

Çay ırmaklarına

Yusuf  Yusuf’um

Beyaz şahin

Bu gece 

Uhu kuşu öter

Selamsız 

Sabah eder 

II

Rüzgar boyun eğmez

Serce dirense 

Erciyes dağına gelse

Güneşi 

Benle görse 

Görse

   Görse

      Görse

        Görse

          Görse 

             Gör

                  Se 

Feryat etse

Yusuf  Yusuf’um 



III

Kızılırmak aşıldı

Suyu ile coşuldu

Seylan’a karıştı

Toprak yıkıldı 

Doru atın kişnemesi

Tayın yıktı

Şafak doğdu 

Kör gözüm

Sabah oldu….

Yusuf Ter 16.06.05

Saat 22:23 İsviçre', 'I Kör gözüm  Geceye Yârimdir  Kem dırdırına Işıl ışıl Ağlar kucağında Ak göğsünde Emer emer Uçundadır Hadi be Git güle güle Şiirler söyle Ka...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kor-gozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanç Mevsimler', 'kiskanc-mevsimler-nazli-gizem-caglayan-cu8oa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden evvel dört mevsim vardı

Sonra sen çıktın karşıma

Yaz eritti karlarımı

Yeşertti ağaçlarımı

Aştı baharlarımı

Üç mevsim kıskandı,

Bir tek yaz kaldı.

Leylakların kokusu sardı

Sevgisizlik mazide kaldı

(13.05.2002/ Trabzon- Şair tarafından bestelenmiştir.)', 'Senden evvel dört mevsim vardı Sonra sen çıktın karşıma Yaz eritti karlarımı Yeşertti ağaçlarımı Aştı baharlarımı Üç mevsim kıskandı, Bir te...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kiskanc-mevsimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk olsun!', 'ask-olsun-asima-azra-wn4tz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '………………………………..Hayata! 

Ağlıyor musun

Şimdi bandırıp zamanları şahdamarına,

Kanıyor musun? 

O zamanlar ki bıçak sırtıdır

Lekeleri söndürülmemiş dil uçlarında,

Sayıyor musun? 

Un ufak edilmiş çeperlerin ellerinde

Ne bekliyorsun hayattan bundan fazla,

………………………...ne duruyorsun?', '………………………………..Hayata!  Ağlıyor musun Şimdi bandırıp zamanları şahdamarına, Kanıyor musun?  O zamanlar ki bıçak sırtıdır Lekeleri söndürülmem...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-olsun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Hüzünlü Şarkıda', 'her-huzunlu-sarkida-nazli-gizem-caglayan-zmii5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her hüzünlü şarkıda

Sonbahar vardı

Sen sonbahardın

Bulut olduğunda ağlardın

Tutamazdım seni (Tutamazdım ellerini) 

Sen sonbahardın

Esip geçerdin benden

Sen giderdin

Ama geri gelirdin

Beni bırakıp gittin

Bu mevsim hiç gelmedin.

(02.09.2002/ Ankara- Şair tarafından bestelenmiştir.)', 'Her hüzünlü şarkıda Sonbahar vardı Sen sonbahardın Bulut olduğunda ağlardın Tutamazdım seni (Tutamazdım ellerini)  Sen sonbahardın Esip geçe...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-huzunlu-sarkida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-i-brahim-kilinc-wox2q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül mızrabımla şu bağlamama

Vuruşumu babam, ağıt sanmazlar

Başbaşa verip te onun teliyle

Yanışımı babam, ağıt sanmazlar

Son buyruğun imiş, çıktık huzura

Oğul, kız, torunun, geçtik hazıra

Bu mutlu tabloyla geldik nazara

Söyleşimi babam, ağıt sanmazlar

Boşa mıydı Ankara ya geldiğin

Boşa mıydı bakıp bakıp güldüğün

Boşa mıydı bize ümit verdiğin

Gülüşümü babam, ağıt sanmazlar

El uzatmadığın bir garip yoktu

Şüphesiz ki senin sevenin çoktu

Felek İbrahim''in boynunu büktü

Akmayan yaşımı, ağıt sanmazlar', 'Gönül mızrabımla şu bağlamama Vuruşumu babam, ağıt sanmazlar Başbaşa verip te onun teliyle Yanışımı babam, ağıt sanmazlar Son buyruğun imiş,...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/babam-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım...', 'yalnizim-i-brahim-ethem-bingul-6fbpz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sazın teli gibi

İnceden ince sızım

Her nazın sözü gibi

Unutuldum, yalnızım...

Yalnızım ah...yalnızım...

Bu benim alın yazım...

Bahar gelmiş, yaz gelmiş

Dalda kızıl kirazım

Geceme ayaz gelmiş

Bir şefkatli el lazım...

Yalnızım ah...yalnızım...

Bu benim alın yazım...

Ağaç benim, dal benim

El süremem meyveye

Su benim, sandal benim

Sözüm geçmez dalgaya...

Yalnızım ah... yalnızım...

Bu benim alın yazım...

İnsanda hayat roman

Uzun bir hikâyedir

Çocuktur soru soran

Cevapsa kinayedir...

Yalnızım ah... yalnızım...

Bu benim alın yazım...

Sözüm o ki endişem

Giyindiğim elbisem

Yâr gelecek mi bilsem

Gönlüm beklemededir...

Yalnızım ah...yalnızım...

Yalnızlık alın yazım...

www.iebingul.com', 'Bir sazın teli gibi İnceden ince sızım Her nazın sözü gibi Unutuldum, yalnızım... Yalnızım ah...yalnızım... Bu benim alın yazım... Bahar gel...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yalnizim-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsim Arasında', 'dort-mevsim-arasinda-nazli-gizem-caglayan-tvikb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben yazla-kışı

Sen güzle-baharı 

Severdin 

Bir değişik bu mevsim

Sanki yaz-kış arasındayım

Güz ile bahar yok ki yanımda

Kalmışım tam ortasında

Mevsimler ayrılmış yarıya

Biz ayrıldık mı, senle yoksa? 

(04.09.2002/ Ankara- Şair tarafından bestelenmiştir.)', 'Ben yazla-kışı Sen güzle-baharı  Severdin  Bir değişik bu mevsim Sanki yaz-kış arasındayım Güz ile bahar yok ki yanımda Kalmışım tam ortasın...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dort-mevsim-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kefen İnsanın Cebinde', 'kefen-i-nsanin-cebinde-yusuf-ter-7xiah', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'günaha sevaba aymaz

bu dünya kefene konmaz

neden diye soran olmaz

kefen insanın cebinde

doğayı kirleten odur

ozonu delen o bodur

belki ali belki hıdır

kefen insanın cebinde 

ana ağlar kuzusuna

doyum olmaz nazlısına

büyüsünde öyle sına

kefen insanın cebinde

Yusuf’um gül bahçesinde

Sizi söyler lehçesinde

Ateşi suyu al sen de 

kefen insanın cebinde 

 14.06.05

Saat 16:24 İsviçre', 'günaha sevaba aymaz bu dünya kefene konmaz neden diye soran olmaz kefen insanın cebinde doğayı kirleten odur ozonu delen o bodur belki ali b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kefen-insanin-cebinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylak Rengi ve Mavi', 'leylak-rengi-ve-mavi-nazli-gizem-caglayan-30ehg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şarkılarda herşey mümkündür

Aşkta bir şarkıdır

Her aşkın ve şarkının

Bir rengi vardır.

Bizim aşkımız

Leylak rengi ve Mavi

Özlemimiz deli

Sevgimizin seli

Yıkar geçer herşeyi

Hayatta herşey mümkündür

Aşkta hayatın parçası

(04.09.2002/ Ankara- Şair tarafında bestelenmiştir.)', 'Şarkılarda herşey mümkündür Aşkta bir şarkıdır Her aşkın ve şarkının Bir rengi vardır. Bizim aşkımız Leylak rengi ve Mavi Özlemimiz deli Sev...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/leylak-rengi-ve-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dengeler', 'dengeler-mehmet-halil-hhzfb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kumda sırt üstü yatıyorum…

Gözlerim ne tam kapalı,

Ne de tam açık.

Güneşe bakıyorum.

Öyle bir an ki…

Kirpiklerim arasından,

binbir rengi yakalıyorum.

Cennet ile cehennem arasındaki

Kıldan ince kılıçtan keskin köprü gibi..

Kritik bir noktadayım

Bu güzelliği bırakmak istemiyorum.

Hassas dengeler üstünde titriyorum.

Hem çok kolay…

Hem çok zor

Parçalanmaz denilen ışığı parçalıyorum.

Pirizmaya ihtiyaç yok…

Sessiz ve Sakin! 

Ne bir adım ileri

Ne bir adım geri

Kıldan ince 

Kılıçtan keskin köprüyü yürüyorum.

Niyetim köprüyü geçmek

Dengelerim, 

Bozulmasın istiyorum.', 'Kumda sırt üstü yatıyorum… Gözlerim ne tam kapalı, Ne de tam açık. Güneşe bakıyorum. Öyle bir an ki… Kirpiklerim arasından, binbir rengi yak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dengeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylemiyorlar', 'soylemiyorlar-sahin-erturk-gcog4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Örümcek kafalılar

Takmışlar başörtüsüne

ÖCÜ sanki,korkuyorlar

Bir bez parcasından

Başörtüsüyle yatıyorlar

Başörtüsüyle kalkıyorlar

Sözde AYDIN onlar

Sözde DEMOKRAT onlar

Sözde PROFESÖR onlar

Cumhuriyeti koruyorlarmış

Demokrasiye sahip çıkıyorlarmış

ATATÜRK cü aydınlarmış

MIŞ,MIŞ bir sürü MIŞ

ZAVALLI,örümcek kafalılar

Büyük önder ATATÜRK ün

Annesinin,Karısının

BAŞÖRTÜLÜ olduğunu

Biliyorlar,söylemiyorlar

Bu nasıl DEMOKRASİ ise

Bu nasıl AYDIN lık ise

Biliyorlar,söylemiyorlar

(17.06.2005-Yeni)', 'Örümcek kafalılar Takmışlar başörtüsüne ÖCÜ sanki,korkuyorlar Bir bez parcasından Başörtüsüyle yatıyorlar Başörtüsüyle kalkıyorlar Sözde AYD...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/soylemiyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selamım Olsun Sevdalılara', 'selamim-olsun-sevdalilara-nazli-gizem-caglayan-xwuw5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yakamozlara sordum seni

Durgunluğun ışığında

Döndüm birtanem sana

Olmadı yapamadım.

Tanımsız yaşama

Bilinmeyen yalnızlığa

Tükenmiş birkaç satıra

Gözümdeki yaşlara

Yasak kurallara

Ebedi tüm şarkılara

Selam olsun sevdalılara

(13.10.2002/ Trabzon - Şair tarafından bestelenmiştir.)', 'Yakamozlara sordum seni Durgunluğun ışığında Döndüm birtanem sana Olmadı yapamadım. Tanımsız yaşama Bilinmeyen yalnızlığa Tükenmiş birkaç sa...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/selamim-olsun-sevdalilara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Bir Nehir Akmıyor İçimde', 'artik-bir-nehir-akmiyor-i-cimde-gokhan-tan-anp4m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendi tenhalığında yaşıyorum hayatı,ulu orta

Kaygıdan ve teselliden uzak.

Herhangi bir zaman dilimi dışında,yaşamın bir köşesine iliştirilmiş olarak

Bencil her duygum törpülendi

Mümkünmüdür artık susmak,dönüşü olmayan bir çığlıktan sonra

Dönmek mümkünmüdür,dönmek yolun sonundan aynı başa

Hercaim,Manolyam,serzenişim

Ayası tütün kokan,saçları bal mumum,gözleri şehlam

Avuntum,umudum,öteki yarım

Artık,bir nehir akmıyor içimde

Oturup hatıraları ayıklıyor yürek,dingin bir su kenarında

Dilimde,çok sevdiğim pek hatırlayamadığım bir şarkı dolanıyor.

Yitik,yitikten ziyade eksik,gedik bir halde.

Mümkünmüdür artık susmak,dönüşü olmayan bir çığlıktan sonra...', 'Kendi tenhalığında yaşıyorum hayatı,ulu orta Kaygıdan ve teselliden uzak. Herhangi bir zaman dilimi dışında,yaşamın bir köşesine iliştirilmi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Tan']::text[], 8.5, '{"poet":"Gökhan Tan","poet_slug":"gokhan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/artik-bir-nehir-akmiyor-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''da', 'i-stanbul-da-nazli-gizem-caglayan-nevx3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şiir ağlıyor

İstanbul''da,

Önce sevdanın türküsü

Sonra göz yaşları

İstanbul''un.

Dökülüyor yüreğime 

O uçsuz bucaksız derinliğe

Sonra bir gül açıyor bak,

İstanbul''da.

Göz yaşları içinde

İstanbul ağlıyor.

İkimize önce sevdanın türküsü

Sonra göz yaşları

İstanbul''un.

(18.04.2003/ Trabzon-Şair tarafında bestelenmiştir.)', 'Bir şiir ağlıyor İstanbul''da, Önce sevdanın türküsü Sonra göz yaşları İstanbul''un. Dökülüyor yüreğime  O uçsuz bucaksız derinliğe Sonra bir ...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istanbul-da-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Elinde Güneş Diğerinde Balçık Var', 'bir-elinde-gunes-digerinde-balcik-var-gokhan-tan-gmm1x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kızıla çalan rengi ile Grubdaki yerini aldı

Güneş,giderek solan siması ve küle dönüşen rengi ile

Birden etrafı karanlık suratlı insanlar sardı

Az zamanları,eşkiyadan beter düşleri vardı

Ellerindeki cılız meşaleler yüzlerini aydınlatmaya yetmiyordu

Aydınlığı boğmak istiyorlardı karanlıkla

Nasıl boğulurdu ki aydınlık karanlıkta

Az zamanları,eşkiyadan beter düşleri vardı

Çoğu aydınlık nedir bilmiyordu,karanlığı da hiç görmemişti

Feri sönmüş,cılız meşalelerin peşine takıldılar

Çeyrek saat içinde bir o kadar daha olmuştular

Oysa güneşe yaklaştıkça,yani aydınlığa

Yüzleri kızaracak,göreceksin

Eller kollar balçık içinde,tüm bedenler kesilecek lal

İşte o an! 

Bir avucunda güneş,diğerinde balçık var.', 'Kızıla çalan rengi ile Grubdaki yerini aldı Güneş,giderek solan siması ve küle dönüşen rengi ile Birden etrafı karanlık suratlı insanlar sar...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Tan']::text[], 8.5, '{"poet":"Gökhan Tan","poet_slug":"gokhan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-elinde-gunes-digerinde-balcik-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemim', 'ozlemim-nazli-gizem-caglayan-uwttg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Etrafında kör düğüm

O sır dolu gülüşün

Saf kalbimde taht yerin

Gel de bitsin özlemim

Yanan benim demezsin

Bu sevgiyi görmezsin

Hiçte sevdim demezsin

Nazın bitsin özlemim

Geldim, sana mecburum

Seninle var soluğum

Ellerinden bir yudum

Sevgi içsem özlemim.

(Ayfer Çağlayan- Nazlı için/ 01.03.1988-Bestelenmiştir.)', 'Etrafında kör düğüm O sır dolu gülüşün Saf kalbimde taht yerin Gel de bitsin özlemim Yanan benim demezsin Bu sevgiyi görmezsin Hiçte sevdim ...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlemim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslatına feda', 'vuslatina-feda-halil-i-brahim-ozdemir-lyoal', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir şiir ağlıyor 

Sevdanın türküsü...

Garip şehrin gözyaşı

Bak Dicle''de Fırat''ta

Varlığına veda

Vuslatına feda,', 'Şiir şiir ağlıyor  Sevdanın türküsü... Garip şehrin gözyaşı Bak Dicle''de Fırat''ta Varlığına veda Vuslatına feda,...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/vuslatina-feda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz ve Akşam', 'biz-ve-aksam-zeki-altas-1d674', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu akşam,senle ben,yalnız ikimiz,

şarkılarda buluşup,hasret soluyacağız.

Rüyalar uyurken uykularda,

yürekten yüreğe buluşacağız

Özleme dair her ne var ise,

içip içip sarhoş olacağız.

Yıldızlarla köprü kurup,

deryalara dalacağız.

Bu akşam, senle ben,yalnız ikimiz,

sessizce kavuşup sarılacağız.

Gönülden gönüle bir bağ kurup,

yalnızlığa ağlayacağız.

Geceye dair her ne var ise,

yudum yudum arayacağız.

Ve karanlığın gizemli kollarında,

geçmişe hesap soracağız.

Bu akşam,senle ben,yalnız ikimiz,

sel olup çağlayacağız.

Hırçın dalgalarla bir olup,

fırtınalarla savaşacağız.

Vuslata dair her ne var ise,

vurup vurup avlayacağız.

Ve közlenmiş sevdaları,

yakıp yıkıp kavuracağız.

Bu akşam, senle ben,yalnız ikimiz,

sabaha dek kavuşup,sonra ayrılacağız..!', 'Bu akşam,senle ben,yalnız ikimiz, şarkılarda buluşup,hasret soluyacağız. Rüyalar uyurken uykularda, yürekten yüreğe buluşacağız Özleme dair ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Altaş']::text[], 8.5, '{"poet":"Zeki Altaş","poet_slug":"zeki-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/biz-ve-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.Gül Ateşe Düştü', 'a-gul-atese-dustu-nail-yavuz-g1ldg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geceler aleni yalnızlığımın mor suretidir 

biten bir umudun sürüklendiği sığınakta 

belki de buz ve ateşe yolculuktur 

hangi acı bıraktığımız yerde kaldı 

benim tanığı / ömrümün 

keskin bir ayaz kış artığında 

kardelenin künyesi zemheriye düştü 

odun ateşi ısıtmadı / sözcükler suskun 

elimdeki elsizliğin / göğsümdeki kurşundan beter 

________ gül kızıl ateşe düştü 

içimin yurtsuz gezgini düşlerim 

gelecek / bir rüyanın anısıdır sadece 

hep bir dost eli, varla yok arası 

ıslak bir bulutun altında 

seninle dopdolu yalnızlığım 

kimsesiz elim / sessiz çığlığım 

beni yetim bırakan gülüşün 

_____gelmedin dost 

-gelmedin ya 

sulara gömüldü kirpiklerim 

dalgaların sesine bırakıp kendimi 

adını suya yazdım 

çiçeğin çiçeğe bakışı gibi ılık 

aşkın en sıcak mevsiminde 

ben seninle şiirlerimde seviştim 

Nail Yavuz İzmir, Mayıs 2005', 'geceler aleni yalnızlığımın mor suretidir  biten bir umudun sürüklendiği sığınakta  belki de buz ve ateşe yolculuktur  hangi acı bıraktığımı...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/a-gul-atese-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkaldırıyorum!', 'baskaldiriyorum-muharrem-cetinkaya-mb40i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara kara bulutlar gibi çöktüler,

_bu sevdanın üstüne...', 'Kara kara bulutlar gibi çöktüler, _bu sevdanın üstüne......', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/baskaldiriyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yağmuru Yağdı', 'son-yagmuru-yagdi-nazli-gizem-caglayan-1asak', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son yağmuru yağdı

Mevsimimizin

Yaş topraklar kurudu

Gök maviye kavuştu

Ben hala yalnız,

Sensiz ve çaresiz (Mevsimsiz)

Çiçekler açar mı yokluğun da burada

Yıldızlar parlar mı,

Sensiz bu boşlukta? 

Tenin de bensiz oynaşırken kışlar, hazanlar

Mutluluğun göklerde

Özgürce dolaşır mı? 

Bir martı misali.', 'Son yağmuru yağdı Mevsimimizin Yaş topraklar kurudu Gök maviye kavuştu Ben hala yalnız, Sensiz ve çaresiz (Mevsimsiz) Çiçekler açar mı yoklu...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-yagmuru-yagdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimlerin Gözyaşları', 'mevsimlerin-gozyaslari-selahattin-yetgin-c7lfi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nasıl da unutmuştum seni sevmeyi. Fırtınalarımın sükûta kavuştuğu, acımın fırdöndü ilmeklerinden kurtulduğu bir anda yeniden dikildin karşıma. Gözlerini unutmayı her istediğimde, kör bıçaklarla taa kornea tabakama kadar işlediğinde divane bir sarsılışla yeniden sokuldun içerime.

Yılların hesabını görmeye niyet ettiğimizde bir Kasım yangınıydı içimizde durmadan yanan. Bedenin bir Nisan goncası gibi titriyor, yüreğin Ağustos yediverenleri gibi deşiliyor, kapıda dikilen zalim şubat iliklerimizi donduruyordu. Eylül bizden izin isteyerek ayrılmış, ekim''in sarı yaprakları üzerinde yürüyüşlerimiz puslu bir odada bizi terk etmişti. Şiirlerimizi altımıza serip, söylenmemiş tüm sözlerimizi birbirimize söyleyip karanlıkta birbirimizi bulmuştuk.

Dudaklarımız yıllardan öç alırcasına acımasız mevsimlere kızgın, nisan goncaları gibi patlıyordu. Ellerimiz kenetlenmiş, mart''ın çözümsüz çığlıklarında direncimizi yitirmiştik. Aynı odada, aynı karanlıkta menekşeler, çiğdemler, nergisler, yaseminler demet demet çiçeklerle girdiler içeri ve mayısın rengârenk izdüşümünde usulca bırakıp gittiler kucaklarındakileri.

Açılmıştı göğsün, entarin yavaşça sıyrılmıştı ayaklarından. Dağlar sallanıyor, ırmaklar tersine akıyor, mevsimler gözyaşı döküyordu sessiz iniltilerle. Sevdamızın istasyonundan kalkan tren gıcırdayarak ilerliyordu dünyanın öbür ucuna. Dumanlar dağılmış, içimizin fırtınaları yıllardır sığındığımız limandan ayrılmış, gönlümüzün sarı ovaları yemyeşil oluvermişti.	

Beklediğimiz yağmurlar da yağmakta geç kalmadı. Az sonra bardaktan boşanırcasına yağan yağmur kahır yıllarımıza damlalarını döktü uzun uzun. Saçlarını toplayıp yavaşça kalktın şiirlerimin üzerinden. Giyinmen ve yeniden eski kalıbına dönmen çok sürmedi. Gözlerin yine kapıya ilişti ve bir sigara dumanı gibi kıvrılarak uzaklaştın benden.

Oysa bir nisan goncası gibiydin titrerken. Yüreğimdeki şelâlelere atmıştın bedenini. Düşüncelerin o karanlıkta şafağa durmuş, Meryem''in bakışları donuk kalmıştı gözlerinde. Öpüşlerinle, sarılışlarınla ve kokunla bedevi yalnızlığımı bitirecektin. Bir teselli olmak isterken sana, aynı teselliyi kendimde hissedecektim. 

İşlenmiş bir günahsa boz kanatlı bir atın yelelerine yapışmamız, ninnilerimizi kimselere söyleyememişsek, yatağımızdaki güller hiç solmamışsa, cüzzamlı şiirlerim bir daha gün ışığına çıkmasın sakın. Dudağımızdaki bayat kelimeler kahve telvelerinde yorumlanmasın. Sana buncadır pembe bulutlardan bir rota çizmedim. Bir yangınım vardı içimde bir beni yakan, saçlarının yelinden medet uman bir sevdalıydım kendi dairemin içerisinde yaralı bir aslan gibi kükreyen.

Bir sabah uyanıp bakacağım yeniden şu masmavi gökyüzüne. Denizin maviliğini çözeceğim. Bir saman çöpünü salıp nehirlere peşinden koşacağım. Kana kana içeceğim gerçek aşk''ın sularını. Mevsimlerin değişken görüntüsüne inat çığlık çığlığa soğukta, sıcakta, bulutla, güneşle sohbete duracağım. Beni böyle kavruk, çelimsiz bırakan mevsimlere meydan okuyup sensizliğin şiirlerini yazacağım inatla.

İşte böyle küçüğüm. Mazinin koordinatlarında küçücüktür albümler. Nasırlı bir ayaktır uğruna yürümeye çalıştığın. Ve hüzünler sürünüp gözlerine, serpilirsin yollara, sevişmeye gidersin korkusuz, kurtlar sofrasına. İçindeki serkeş fırtınalar sensizliğe yakalandığında, adımı unutmaya başladığında, dokunmaya korktuğun bedenimi de sensizlik ormanlarında yitireceksin. Sevdaya soluksuz duruşların, ihtiraslarına yön veremeyişlerin ve söylemeyi unuttuğum ne varsa, o asla beni bulamadığın zaman labirentinde kaybedeceksin.', 'Nasıl da unutmuştum seni sevmeyi. Fırtınalarımın sükûta kavuştuğu, acımın fırdöndü ilmeklerinden kurtulduğu bir anda yeniden dikildin karşım...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mevsimlerin-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-nazli-gizem-caglayan-vwyq7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz ne gece, ne gündüz

Sensiz ne kışlar, ne yazlar

Sensiz ne aşklar,

Ne yaşlar tükettim

Çaresiz

Sonbahar kokusu sardı

Bırakta solmasın çiçekler

Solmasın güller

Gülsün yine güneş

Geri gel

Özledim seni

(07.10.2003/ Akçay- Şair tarafından bestelenmiştir.)', 'Sensiz ne gece, ne gündüz Sensiz ne kışlar, ne yazlar Sensiz ne aşklar, Ne yaşlar tükettim Çaresiz Sonbahar kokusu sardı Bırakta solmasın çi...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviye Boyadım Yüreğimi', 'maviye-boyadim-yuregimi-selahattin-yetgin-8wn1z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessiz çığlıklar atarsın yankım ülkene ulaştığında. 

Efsane güzelliğinin üzüm bağlarında gülücükler saçarsın. 

Anılarını koynuna alıp, dalarsın savaş meydanlarına

Bir liman meyhanesinde zaferine kadeh kaldırır, 

yüreğindeki çözümsüz aşkla hayat oyununu oynarsın.

	Binlerce sözcüğün yıldıza dönüştüğü bir gizem gezegeninde, kırık dökük anılara kadeh kaldırmaktır yokluğun. Günler serseri bir mayın gibi dolanır masmavi denizlerinde. Bir yakamoz ışığı yansır arada bir çözümsüz yüreğinden ve yalnızlığının ayak sesleri duyulur derinden. Sesin, gözlerin, saçların ve ellerin tırmalar bedenimi binbir yerinden.

 	Muammalar gibi sakladığın yüreğini günlerdir aramaktayım. Sözcüklerinden sevgi kuleleri yaparak adını yazdım kapısına. Bir yangın mavisine boyadım yüreğimi ve duvarlarına da gizemli gülüşlerini astım. Hasret gülleri diktim surlarına renk renk. Günler hasreti emzirirken sürmeli gözlü geceler böldü umarsız düşlerimi. Yitirdim sevgiye belediğim tüm çocuksu gülüşlerimi.

	Sessiz çığlıklar atarsın yankım ülkene ulaştığında. Efsane güzelliğinin üzüm bağlarında hayata gülücükler saçarsın. Anılarını koynuna alıp, dalarsın savaş meydanlarına. Bir liman meyhanesinde zaferine kadeh kaldırır, yüreğindeki çözümsüz aşkla hayat oyununu oynarsın.

	Oysa, geceleri gökyüzüne sözcük serpmeyi, halka halka anıları fırlatmayı ben de çok seviyorum. İçimdeki kızıl gezegende, en uç zirvelere tırmanmayı bekleyen bir çocuk yanım var benim de. Ben masalların bilgesi, gecenin atardamarında yontu arayan bir derviş, fukara ve gönlü yakutlarla donatılı bir ressam, kimi de gülüşü dudaklarında sönen bir bezirgânım ben.

	Şakaklarımda zonklar arada bir yaşamamışlığım. Sarı kanatlı kuşlar geçer üzerimden, sevdaya tutulduğumda. Bir elimde orak, bir elimde aşkın testisi ve terli alnımla dolanırım ekin tarlalarında. Kimi unuturum ağzımdaki lokmayı çiğremeyi, kimi de bir ağaç gölgesinde aşkı yazarım sarı topraklara. Bir anka kuşunun peşine takılır, kanatlarından yeşil sular dökülen metruk bir değirmende soluklanırım. 

 	Kimi zaman yürüdüğü yolların taşlarını sayamaz insan. Hayallerine uzanmak için yürümelidir ve bu zorlu yolda mola verir zaman zaman. İdealler, hayattan beklentiler bazen kısır bir döngünün içinde kaybolur, bazen de bir yıldız gibi yansır gökyüzünde. Uzansan tutacak gibi olursun ve yarınların çile yumakları sardıkça büyüyen bir topaç olur.

	 Bir terazinin kefesine koyduğun ve tartmayı asla beceremediğin kırmızı domatesler gibidir aslında hayat. Her iki kefede de umut vardır ve sen ikisinin de aynı hizada olmasına dikkat edersin. Sıcacık yüreğine rüzgâr değince umutsuzluğu yaşamak senin işin değil anlayacağın. Bir elinde valiz, bir elinde yaşamak için gereksinim duyduklarını barındıran bir çanta ile yürürsün bu zorlu yolları.

	İşte bu zorlu yollarda farzet ki bir mola verdin ve yaşamı solukluyorsun şimdi. Kendinle bir başına kaldığın anlarda gökteki yıldızları seyret, güneş şehrin üzerinden ayrılınca avuçladığın taşları mavi denizlere fırlat. Kolların ve bedenin yorulunca koy yastığa başını ve sürekli güzellikleri düşle. Her sabah yüreğin gibi tertemiz umutlarla tut yaşamın elinden, çünkü yarın mutlaka güzel bir günü hazırlayacaktır sana. Hayatın öte yüzünü hiç düşünme ve sakın ağlama. Gözyaşı zayıfların kullandığı, yaşamasını bilmeyenlerin ilk tercihidir. 

	Yorgun gecelerin imbik imbik bakışlarında bir şivan türküdür sevdaya küskün bakışın. Sürgün gözlerinde bulutlara bakar ve güneşi özler çocuklar. Aşk gökkuşağına sarılır arada bir ve dolanır başında vakitsiz. Kelebekler gibi özgür uçuşlar yaparsın ve dönersin eylül gelince kabuğuna. Ve ben seni özlediğimde gözlerine şehirler yürür. Ellerin gül açar ve ışıklar yansır saçlarından. Denizler ağlar sessiz ve nazlı bir nilüfer suya düşer kaygısız.', 'Sessiz çığlıklar atarsın yankım ülkene ulaştığında.  Efsane güzelliğinin üzüm bağlarında gülücükler saçarsın.  Anılarını koynuna alıp, dalar...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/maviye-boyadim-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben insanım', 'ben-insanim-i-lhami-arslantas-kon6b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Varlık yokluk arasında, 

Bir çizgiyim. 

Öyle ki, 

Bazen varlığım, 

Bazen yokluğum dava olur. 

Tüm zamanı ben işgal eder, 

Ben yorarım tarihi. 

Giderken kalır ardımda, 

Uç uca ulanarak. 

Ben insan, 

Ben bir, 

Eylemim aslında, 

Gerçeğin özünde 

Ben sosyal bir varlığım 

Hayatta olması gereken 

Telâşım, 

Uğraşım, 

Kavgayım, 

Barışım, 

Çünkü 

Ben insanım. 

Dünyanın varlığında da, 

Yokluğunda da 

Bir nedeninim. 

Çözümde, 

Çözümsüzlükte, 

Benim ellerimde. 

Dünyayı o kısacık sürede, 

İstediğim renge boyarım. 

Tüm renklerin boyası, 

Benim fırçamın ucunda. 

Ben başka bir eylemim. 

Fizik ötesi değil ama. 

Gözüm bir olay, 

Elim bir olay, 

Aklım bir olay, 

Hele dilim, 

Bambaşka bir olay. 

Eylemle hasıl olmuş, 

Eylemle bu güne gelmişim. 

Kısacası 

ben insanım.', 'Varlık yokluk arasında,  Bir çizgiyim.  Öyle ki,  Bazen varlığım,  Bazen yokluğum dava olur.  Tüm zamanı ben işgal eder,  Ben yorarım tarihi...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ben-insanim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Meleğim', 'sevda-melegim-selahattin-yetgin-al492', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgun bir akşamüstü kaldırımına düşürdüğün

Gözlerini bulup, yine sana vermektir yaşamak.

Seni yazmak, kimseyi yerine koyamamaktır

Ve satır arası bırakmamaktır bir yazıtta.

 	Bir dere akar düşlerimde. Güçsüz, düşmüş çiçekleri taşır denizlere sarı sular. Yüzün yansır sulardan gönlüme ve tuzlanır kirpiklerim. Yürürsün içime, görmek için sessizce ölüşümü. Bir yıldızın izdüşümü sarılır geceye, ağustosların sesleri duyulur uzaktan ve bir çobanın sürüsü geçer o dereden.

	Karışıp ılık yellere düşlerime giriverirsin ansızın. Alıp gidersin ömrümü seller gibi. Sevda dansı derlermiş denizler üzerinde yürümeye. Bu denizleri aşıp karlı dağların eteklerini her düşlediğimde böylesi bir sevdada mutluluk var mıdır? diye sorarım kendime. Yalnızlığın nefesi üşütür ellerimi, gurbette yazılmış bir şiirin sözleri gibi seni solurum.

	Mor salkımlı sokaklarda buzullar ağar gönlünün sarkıtlarından. Sarsan bitmez, yazsam dinmez, sevsem silinmez, sebebi bilinmez  bir yazgı gibi durursun günlerdir içimde. Yağmurların ıslattığı saçların, gri öpücüğüne konan kelebeklerin, ülkem gibi bakan gözlerin ve durmadan kemirdiğim tırnaklarım gibisin sen.

	Sen ki; delişmen ve yüreğinde binlerce gülücükle saklarsın duygularını. Her sabah uyanıp yüzüne baktığım bir ayna, bayrak gibi göğsüme sardığım vefa, kimseye nasip olmayan bir sevdasın. Yüreğinin lâbirentlerinde dolaşarak bulmak istiyorum seni. Kan ter içinde kalsam da seni arayışım bitmeyecek gül yüzlüm.

	Ben sana vurgun, yalnız sana sevdalı paslı bir zincirim güvertende bekleyen. Bir resimsin tuvalime yansıyan, sarnıçlardan sularına inmeyi dileyen bir bakraç, akar suyunda bir nilüfer, çamurlu dizleriyle senden af dileyen bir çocuk, kimi de iç çekişleriyle üç günlük ömrünün sona ermesini bekleyen bir kelebek.

	Ne çok sevmişim seni. Katran karası gözlerindeki mavi okyanusca, hayat zincirinin ucundaki tanımlanamayan bir bakla gibi durursun canevimde. Senin kokun yüreğime binlerce çiçek saplar mevsim tanımaksızın. Mutluluğu arayıp bulamayanların ve bu koca şehirde hayat iksiri arayanların gözlerindeki umutsuzluğu silersin sevginle. 

	Belki de ilkel bir ses benimkisi. Acılarını haça germiş bir romantiğim. Çivilendiğim yerlerde güvercinler tüner omzuma ve yüreğimi atarım önlerine. Varsın bitimsiz düşler olsun gördüğüm. Güneşe yürümelerim bitmesin. Yaşlı bir şairin omuzlarına yaslanıp ağlayan bir kız düşsün her sabah fırçamın ucuna.  Sevginin litaratürlerindeki ismine yürüyüşüm hiç bitmesin. Sızlasın yüreğim her seni andığımda.

	Aynı yüreği, aynı beyni, aynı duyguları yaşıyoruz seninle. Ne çok sözüm var oysa sana söylenecek. Her sabah şiir damlacıklarıyla uyandırıp seni, gecenin kollarına da aynı şiirlerle belemek tek isteğim. Engeller varken güzeldir sevmek. Oynar durursun içimde ve içirirsin gençlik ağularını her seni arzuladığımda.

	Ben kendimi ele vermekten vazgeçmedikçe, aynı müziği, aynı şarkıları dinlemekten bıkmadıkça, dilimde duaya dönüşen yakarışlarımı dinlemekten ve bu sevdayı yangınlara dönüştüren gözlerin var oldukça, sana ölümsüz ritimlerle koşacağım gül dudaklım. Varsın kalkmasın yaz kış yüreğimden keder, varsın içimdeki  geceler sabahlara tutsak olsun. Ayrılıkları bir peçe gibi ört yüzüne istersen.

	Günlerdir ruhumun müziklerinden oluşan bir konserdi sana sunduğum. Tek kişilik bu gösteride yalan da olsa bir alkıştı umduğum. Ama galiba sen sıkıldın ve salonu terk ediyorsun. Bu oyun benim için çok kutsal küçüğüm. Sahnede senin için yürekten ağlayabilirim. Ama kaçmayı seçersen onu da ben alkışlayabilirim.', 'Yorgun bir akşamüstü kaldırımına düşürdüğün Gözlerini bulup, yine sana vermektir yaşamak. Seni yazmak, kimseyi yerine koyamamaktır Ve satır ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevda-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Bitmezdi?', 'hani-bitmezdi-nazli-gizem-caglayan-vybt4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gece yürüdüm

Sokaklar boyunca

Amaçsız,

Çaresiz,

Bizi düşündüm.

Aşkımızı,

Sevdamızı,

Alev alev,

Buram buram yanan,

Hani bitmezdi? 

Ben biliyordum

günü gelecek

Sönecek (bitecek) 

Yıldızlar(bu sevda) 

Işığı kalacak ardından

Yaşlı ve sönük

Yıpranmış biraz

Solmuş.

Bütün gece düşündüm, durmadan

Anlayamadım neydi bitiren,

Bu büyük sevdayı

(27.09.2003/ Akçay- Şair tarafından bestelenmiştir.)', 'Dün gece yürüdüm Sokaklar boyunca Amaçsız, Çaresiz, Bizi düşündüm. Aşkımızı, Sevdamızı, Alev alev, Buram buram yanan, Hani bitmezdi?  Ben bi...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hani-bitmezdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepimizin Ayrı Dünyası Var...', 'hepimizin-ayri-dunyasi-var-muharrem-cetinkaya-10bs8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hepimizin gizi var,

Ve

Sınırlarına kenar süsü yaptığı

Kendi dünyası.

Neler var orada,

_neler....

Hepimiz ayrı dünyalarda yaşarız,

_çoğu zaman....

Ve neler getiririz,

_ta dünyanın öbür ucundan,

Neler götürürüz geri.....

Kimsenin ruhu duymaz; 

Delik-deşik olur kimi,

_kan-revan! 

Kimi paramparça,

_tuz-buz! 

Birilerinin yolu birleşir

_biryerlerde

Kimse duymaz feryatları,

Duymaz kimse,

Görmez,

_sağır-kör! 

Hepimizin bir gizi var,

_ayrı bir dünyası,

Hepimiz aynı dünyada

Ayrı dünyalarda yaşarız,

_kimi zaman...!', 'Hepimizin gizi var, Ve Sınırlarına kenar süsü yaptığı Kendi dünyası. Neler var orada, _neler.... Hepimiz ayrı dünyalarda yaşarız, _çoğu zama...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hepimizin-ayri-dunyasi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-nazli-gizem-caglayan-3r36n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahtan kalktım,

Yeni güne başladım,

Yaz farklı mevsim

Mutlulukla oynadım

Dans etmeye başladım

Son rüzgarla

Işıksız sabahlardan

Çiçeksiz baharlardan

Kurtuldum (Yalnızlıklardan)

Kim düşünürdü ki birgün bitecek

Anlamsız savaşmalar

Sonuçsuz kavgalar

Ve yalnızlıklar.

Tükendi artık, tükendi artık

Gözyaşları, zamanla kurudu

Ve bitti.... yalanlar zamanında

Acıttı ve bitti

(24.09.2003/ Akçay- Şair tarafından bestelenmiştir.)', 'Sabahtan kalktım, Yeni güne başladım, Yaz farklı mevsim Mutlulukla oynadım Dans etmeye başladım Son rüzgarla Işıksız sabahlardan Çiçeksiz ba...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yeniden-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonca', 'gonca-emin-eren-m5kjx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dar dik güzelim dar mor gömleğini

Sallandır hoplat zıplat memelerini

Kısa kes gömleğini göster göbeği

Tak aynalı kemeri kıvırt belini

Çok yakışmış sana mini eteğin

Allah vermiş bir cift sütun bebeğim

Hadi gel seninle bize gidelim

Vallahi yok hiç bir kötü niyetim

Ne olaçak sanki tutsam elini

Koklasam goncadan taze tenini

Dokunayım sana mest eyle beni

Öptürt artık cıldırtma nazınla beni', 'Dar dik güzelim dar mor gömleğini Sallandır hoplat zıplat memelerini Kısa kes gömleğini göster göbeği Tak aynalı kemeri kıvırt belini Çok ya...', ARRAY['Türk Edebiyatı','Şiir','Emin Eren']::text[], 8.5, '{"poet":"Emin Eren","poet_slug":"emin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonca-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zarardır dostum', 'zarardir-dostum-i-lhami-arslantas-6nz43', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beyhude gezersin yolun yokuştur 

İş, uğraş insana yakut nakıştır 

Öyle bir şey yap ki yap da yakıştır 

Beyhude geçen gün zarardır dostum

muhanetse  usta çırak ne lazım

bulduğun yer içer eder de hazım

iş gören insana boldur  levazım

beyhude geçen gün zarardır dostum



Etmiyorsun hiçbir şeyi bir tasa 

Seni korumaya bulunmaz yasa 

Mutlu olmak için hayat çok kısa 

Beyhude geçen gün zarardır dostum 

Dünya kasnağına sen olma deri 

Şeytan sakalının olma berberi 

Hurafeden el çek geri dur geri 

Beyhude geçen gün zarardır dostum 

Keşfet bir kendini aklında dolaş 

Çelişme canınla hoş değil dalaş 

Gayret eyle etme sakın ha telaş 

Beyhude geçen gün zarardır dostum 

İlhami yim kurşun yemiş muharip 

Düzenden,cahilinden hayli mustarip 

Gel gidelim çağdan öteyi yarıp 

Beyhude geçen gün zarardır dostum', 'Beyhude gezersin yolun yokuştur  İş, uğraş insana yakut nakıştır  Öyle bir şey yap ki yap da yakıştır  Beyhude geçen gün zarardır dostum muh...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zarardir-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölesim var ölesim', 'olesim-var-olesim-muhammed-murad-uzun-w2cq7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne haldeyim görmezsin

Şu  halimi bilmezsin

Belki de hiç  sevmezsin

Nerdesin yar Nerdesin

Ölesim var ölesim

Ayrı düştüm ya senden

Hayır yok artık  benden

Bir şey gelmiyor elden

Nerdesin yar Nerdesin

Ölesim var ölesim 

Dengesiz bir haldeyim

Çıldırmak üzereyim

Bilmem nere gideyim

Nerdesin yar Nerdesin

Ölesim var ölesim

Kurtulamam derdimden

Yanarım hasretinden

Geçiyorum kendimden

Nerdesin yar Nerdesin

Ölesim var ölesim

Hayır yok benden bana

Hayrım olmaz ki  dosta

Tak ediyor yar cana 

Nerdesin yar Nerdesin

Ölesim var ölesim

Yataklara düseyim

Hasta olup öleyim

Bu diyardan göceyim

Nerdesin yar Nerdesin

Ölesim var ölesim', 'Ne haldeyim görmezsin Şu  halimi bilmezsin Belki de hiç  sevmezsin Nerdesin yar Nerdesin Ölesim var ölesim Ayrı düştüm ya senden Hayır yok a...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Murad Uzun']::text[], 8.5, '{"poet":"Muhammed Murad Uzun","poet_slug":"muhammed-murad-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/olesim-var-olesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk çiçeğim olur musun?', 'ask-cicegim-olur-musun-muhammed-murad-uzun-ci6hk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel Bahçıvanın olayım

Hiç seni soldurur muyum

Her  gün sevgiyle sulayım

Aşk çiçeğim olur musun? 

Zahmet gerek emek gerek 

Sevmesini bilmek gerek 

En derinlerden bir dilek 

Aşk çiçeğim olur musun? 

Kıramam bir saç telini

Kıramam asla kalbini

Dilerim hep keyfini

Aşk çiçeğim olur musun? 

Gel gezelim hep el ele 

Gel olalım hep kal kalbe

Çare bulunur her derde 

Aşk çiçeğim olur musun? 

Yaşansın baharlar artık 

Yinemi dikene çattık 

Hadi tebessüm et artık

Aşk çiçeğim olur musun?', 'Gel Bahçıvanın olayım Hiç seni soldurur muyum Her  gün sevgiyle sulayım Aşk çiçeğim olur musun?  Zahmet gerek emek gerek  Sevmesini bilmek g...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Murad Uzun']::text[], 8.5, '{"poet":"Muhammed Murad Uzun","poet_slug":"muhammed-murad-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-cicegim-olur-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki şehri gir seyran eyle', 'i-cimdeki-sehri-gir-seyran-eyle-i-lhami-arslantas-kiklm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimdeki şehri gir seyran eyle 

Herkese açılan kapısı vardır 

Gezip gördüğünü türküyle söyle 

Şefkatten çatılmış çatısı vardır 

Al gönül gülümden sar demet demet 

Ahtım  var dostlarım sözüm de senet 

Yalancı dünyada olmam muhannet 

 insanın  gönlünün  yatısı vardır

Azat et başından at yalan varsa 

Durma bu mekânda şer olan varsa 

Tüm dünyaya yeter yer alan varsa 

Vicdan mahkemesi yapısı vardır 

Doğrulukta bol sermaye yok diye 

Özümsemem kötülüğü hak diye 

Övünmesin dilim dostum çok diye 

Her canlının zarif, katısı vardır 

Der İlhami nefsim azar eyledim 

Yüreğimi açtım pazar eyledim 

Sevgi denen güle nazar eyledim 

Zümrütten nadide takısı vardır', 'İçimdeki şehri gir seyran eyle  Herkese açılan kapısı vardır  Gezip gördüğünü türküyle söyle  Şefkatten çatılmış çatısı vardır  Al gönül gül...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/icimdeki-sehri-gir-seyran-eyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecikmiş Gül', 'gecikmis-gul-alptekin-biber-6zw1s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecikmiş güldür yüreğim

goncasında baharın

gonca sır doludur

umududur yarının...

1997', 'Gecikmiş güldür yüreğim goncasında baharın gonca sır doludur umududur yarının... 1997...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gecikmis-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülya Tüneli-1', 'hulya-tuneli-1-oguz-duzgun-wqyws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bahara doğma aşkıyla yürürdüm gözlerinin maviliğine

Bulut bulut karşılardı müphemiyetin bıçak bıçak yaralardı

Süzüldüğümde ben lahuti bir akşamda ruhunun enginliğine

Umutlarımdan sarkardım sana, ürkek melal, gülmemi yargılardı

Bırakışın göğe izlerini söküp de gamzelerini atışın

Bir buğday tanesinde ağyarın pusularına düşmenin korkusu

Gecelerden el ayak çekince rindler, sessiz izbelerden bakışın

Başak başak, pusulara saldırırdı tebessümlerinin ordusu

Biraz daha ılgıtlaşma telaşında eserken dil-i mecruhuma

Gece uykulara soyunup rüyalarla yatışım seni görmek için

Doğardın ansızın kabusların en karanlık derin uçurumuna

Hülya tünelinde kilitlenirdi yollarım sensizdim için için', 'Bir bahara doğma aşkıyla yürürdüm gözlerinin maviliğine Bulut bulut karşılardı müphemiyetin bıçak bıçak yaralardı Süzüldüğümde ben lahuti bi...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hulya-tuneli-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak', 'uzak-alptekin-biber-o2pms', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaksın uzak

Sıcak,

Kendime yapışkanlığımdan

Uzaksın  çook uzak

Yüreğimde ki kora ulaşmıyor nefesin

Derin sessizliğime erişmiyor sesin

Benim olmadığım biryerlerdesin

Düşündüğün de oluyordur belki beni

Düşünüp duygulandığın da

Ama artık

.....düşlerimde bile görmüyorum seni

Bazen göz göze gelsek de

G e r ç e k t e

Aramızdaki hava duvar

Başındaki mavi umut duvar

Yüreğinde ki sevda duvar...

Mutluyum; 

...benim hiç olmazsa  gökyüzüm

hiç olmazsa 

ak mı ak

özgür mü özgür

sevdalı yüreğim var...

31 Temmuz 1996', 'Uzaksın uzak Sıcak, Kendime yapışkanlığımdan Uzaksın  çook uzak Yüreğimde ki kora ulaşmıyor nefesin Derin sessizliğime erişmiyor sesin Benim...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/uzak-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Yaşarım', 'seninle-yasarim-ali-kilic-kakiz-i5ia0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hem ağladım, hem yürüdüm sırdaşım.

Baharım kış oldu, dinmiyor göz yaşım.

Hayat dert, kan ağlıyor cihan.

Efkar sardı, üzülüyorum durmadan.

Göz yummak zor, susmak ar.

Ayak tepiyor, ta içimden yıkıyor.

Yıkık duvarların hemen ardından.

Bize hucum eden, üç başlı bir yılan.

Neye mahkumum ben, artık yeter.

Dinsin bu gözyaşı bitsin bu keder.

Cihana sığmaz büyüktür davamız.

Biz tarihe şan veren kahramanlarız.

Şerefli bir tarihsin seninle varım.

Gönlümde hayalin seninle yaşarım.

Asla yılmayız, biz adımı attık ezelden.

Allahım inmesin bayrağımız göklerden.

Alemleri örten nuruna olsun yemin.

İşte malum halimiz, ya Rabbel âlemin.

.........................

İstanbul / 2002', 'Hem ağladım, hem yürüdüm sırdaşım. Baharım kış oldu, dinmiyor göz yaşım. Hayat dert, kan ağlıyor cihan. Efkar sardı, üzülüyorum durmadan. Gö...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seninle-yasarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taksim Maydanı', 'taksim-maydani-ufuk-nazim-v6rw6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Taksim meydanı; 

Gri bir günün altında

Sonsuz bir hasret.

İmgesini arayan şair 

Dalmış dışarıya; 

Pencereden.

Geçen tramvaya takmış

Bir yanını

Bir yanı 

Akıp giden trafikte.

Sonra uzaklar düşmüş

Aklının taa içine.

Dönmüş gözleri 

Geri geri

Dalmış içine 

Gölgeleri derin 

Umutları yeni

Sevda kuşuna 

Konmuş...

Resmi bir binadan

Evraklara takmış 

Yıllarıda 

Öyle çıkmış.

Kasvetinden günün

Yağmur çiseliyor.

Taksim içinde

Bir şair

Düşleri derin

Gülüşleri

Yemyeşil.

Mutlu,

Umutlu

Dalmış içine 

Yaşamın...', 'Taksim meydanı;  Gri bir günün altında Sonsuz bir hasret. İmgesini arayan şair  Dalmış dışarıya;  Pencereden. Geçen tramvaya takmış Bir yanı...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/taksim-maydani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslım', 'aslim-volkan-yoruc-3bd6j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün başkaydı bugünde bir başka yarın ise bambaşka

Aslımdan suret isteme

Ben buyum değişemem

Doğmuşum büyümüşüm yürümüşte konuşmuşum

Anlatmışım derdimide rahatlamışım

Düşmüşüm yere kendim kalkıp ağlamışım

Dünü bir başka bugünü bambaşka yarını daha bir başka yaşamışım

Aslımdan suret isteme, veremem

Ben buyum işte, değişemem

Zorla gülüpte ağlayamam

Kendim giderim kendim gelirim

Ne bir kukla nede oyuncak olamam

Zoraki sevemem ben seni

Gözlerine dik bakıpta yanına varamam

Masallardan çıkmadım ben

Elimde kılıcımla heybetimle savaşamam 

Bende insanoğluyum hep kazanamam

Aslımdan surete dair sebebim var

Dalında kopmamış nice düşüm var

Bir cesaret ki bunu sana nasıl anlatsam

Gülü kanım aksada okşarım

Yağmurda ıslansamda dolaşırım

Anılar yüreğimi yaksada hatırlarım

Lakin yüzün hürmetine olsada şayet

Ben seni senliğinden sebep artık sevemem', 'Dün başkaydı bugünde bir başka yarın ise bambaşka Aslımdan suret isteme Ben buyum değişemem Doğmuşum büyümüşüm yürümüşte konuşmuşum Anlatmış...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aslim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-ufuk-nazim-ownbr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gemi kalkar

Halatların hışırtısında

Bir ömür of çeker

Ama umuttur

Dalgaların ışıltısı.

Bir martı sesidir

Uzayan zaman 

Denizin örtüsü boyunca

Yığınla hüzündür.

Artık ayrılığı

Yalnız iskele babası

Yalnız hüzün.

Yorgun deniz

Pervanelere dolanmaktan

İnsanların tenine

Dokunamamaktan.

Uzak artık

Geceyi aydınlatan

Aysız yakamozları.

Hele o balık bekleyen

Lüks lambaları; 

Nasılda dargın şimdi

Köhnemiş 

Kahvehane köşelerinde.

Dalgakıran boyunca

Dizilmiş karabataklar

Yosunlu kayaların yüzü

Dönük Haydarpaşa İskelesine

Boylu boyunca 

Uzun bir; 

Sedire uzanır gibi

Uzanmışlar ufkun sonsuzluğuna.

Ardlarında 

İki tarih çığlığı

Sultanahmet ve Ayasofya.', 'Bir gemi kalkar Halatların hışırtısında Bir ömür of çeker Ama umuttur Dalgaların ışıltısı. Bir martı sesidir Uzayan zaman  Denizin örtüsü bo...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/deniz-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Gör Bana', 'bak-gor-bana-i-rfan-demirel-lsb6p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi soguk duvarlara

İcimdeki yalnızlıkla 

Penceremdeki rüzgarlarla

Aglıyorum aglıyorum

Duyuyormusun sesimi 

Uzaklardan uzaklara

Sensiz ne haldeyim

Bak bak gör bana

Dudaklarımda sarkısın

Gecmısınımde anısın

Alnımda kara yazısın 

Bak bak gor bana', 'Şimdi soguk duvarlara İcimdeki yalnızlıkla  Penceremdeki rüzgarlarla Aglıyorum aglıyorum Duyuyormusun sesimi  Uzaklardan uzaklara Sensiz ne ...', ARRAY['Türk Edebiyatı','Şiir','İrfan Demirel']::text[], 8.5, '{"poet":"İrfan Demirel","poet_slug":"i-rfan-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bak-gor-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çabuk Gel', 'cabuk-gel-gulsen-gonenc-a42gu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '- Canım Babam''a -

Nefesini duyacak,

Şiir dolu yüzünü görecek,

Huzurunu koklayacak,

Eline dokunacak,

Doya doya öpecek

Kadar yakınım...

Bitmeyen gecenin karanlığında,

Kapını aşındırdı; 

Gözyaşlarım,

Sessiz çığlıklarım,

Dualarım...

Bu can sensiz olamaz derdin.

Buradayım.

Çabuk gelirsin değil mi?', '- Canım Babam''a - Nefesini duyacak, Şiir dolu yüzünü görecek, Huzurunu koklayacak, Eline dokunacak, Doya doya öpecek Kadar yakınım... Bitmey...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cabuk-gel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Özlü Sözler 8', 'ozlu-sozler-8-fatih-cinar-495g7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kahpe dünya budurki

filler karıncanın lokmasına göz koyduğunda

söz olmaz

lakin karıncalar

fillerin sofralarına el uzattıklarında

elleri kesilir!', 'kahpe dünya budurki filler karıncanın lokmasına göz koyduğunda söz olmaz lakin karıncalar fillerin sofralarına el uzattıklarında elleri kesi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozlu-sozler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
