INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Aylık', '14-aylik-volkan-yoruc-nc201', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siyahla beyaz bakar bu gözler

Ve içinden sessizce geçer bu düşler

Bir resimki benden yana eski

Maziden hatıra kalmış bu günler

Yaş belki 14 aylık

Gözler belki aynı ama yürek hiç yaşamamış ayrılık

Saf bir melek gibi

Dili çözülmemiş hayalleri büyümemiş

Yaşadığı günleri hiçte düşünmemiş

14 aylık ömründe en fazla 2 semt görmüş

Misal ki bir bahçede tomurcuk gülmüş', 'Siyahla beyaz bakar bu gözler Ve içinden sessizce geçer bu düşler Bir resimki benden yana eski Maziden hatıra kalmış bu günler Yaş belki 14 ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/14-aylik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Bir Solcunun Birkaç Dakikası!', 'bir-solcunun-birkac-dakikasi-fatih-cinar-0itsc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüreğimde darbe korkusu

kulağımda tank uğultusu

sokaklara çıkmak yasak

ben sokaklarda çırılçıplak

bir siyah cop ağrısı şakaklarımda

sabahlar uzak geceler tuzak

ve hala bir tank uğultusu kulaklarımda...', 'yüreğimde darbe korkusu kulağımda tank uğultusu sokaklara çıkmak yasak ben sokaklarda çırılçıplak bir siyah cop ağrısı şakaklarımda sabahlar...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-solcunun-birkac-dakikasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Müebbet', 'son-muebbet-nurol-banabak-pz74m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-e.m.cioran’a-

Gün bitti,

Gün bitti

Gün …

Hadi, iyi geceler! 

Gece bitti,

Gece bitti

Gece…

Hadi, günaydın! 

Ömür bitti,

Ömür bitti

Ömür…

Hadi, gözünaydın!', '-e.m.cioran’a- Gün bitti, Gün bitti Gün … Hadi, iyi geceler!  Gece bitti, Gece bitti Gece… Hadi, günaydın!  Ömür bitti, Ömür bitti Ömür… Had...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-muebbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni seviyorum', 'ben-seni-seviyorum-fahri-maden-9wb5m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben Seni Seviyorum

Şiir yazma değildi

Niyetim

Seni övmekti

Yere göğe sığdıramadığım

Sana olan aşkımı

Ölümsüzleştirmekti.

Adıma şair diyorlar ya

İnan kahroluyorum

Bak bir daha

Bir daha söylüyorumn

Ben seni seviyorum.. 11Haziran 2005 Samsun/Havza', 'Ben Seni Seviyorum Şiir yazma değildi Niyetim Seni övmekti Yere göğe sığdıramadığım Sana olan aşkımı Ölümsüzleştirmekti. Adıma şair diyorlar...', ARRAY['Türk Edebiyatı','Şiir','Fahri Maden']::text[], 8.5, '{"poet":"Fahri Maden","poet_slug":"fahri-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-seni-seviyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma', 'sorma-hayriye-kisla-k3vs7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum heran

Seni özlüyorum hiç durmadan

İçimdeki boşluğu dolduramıyorum

Sorma sakın ne haldeyim

Dilim kilitlendi, yalnız kaldım

Koca dünyada, kimsesiz yüreğim

Ölüp ölüp dirilirim her gün

Sorma sakın ne haldeyim

Çizgi çektim duygularııma

Çaresizlik sardı düşüncelerimi

Elbet birgün güler masum gözlerim

Sorma sakin ne haldeyim', 'Seni düşünüyorum heran Seni özlüyorum hiç durmadan İçimdeki boşluğu dolduramıyorum Sorma sakın ne haldeyim Dilim kilitlendi, yalnız kaldım K...', ARRAY['Türk Edebiyatı','Şiir','Hayriye Kışla']::text[], 8.5, '{"poet":"Hayriye Kışla","poet_slug":"hayriye-kisla","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sorma-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Uğradım, Ayaküstü', 'anneme-ugradim-ayakustu-suna-doganay-eyzql', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anneme uğradım, sonbahardı. Anılarla sürüklendi ayaklarım. Taşlı, topraklı, hüzünlü yollara. Bir ziyaretçisi vardı, benden önce gelmiş. Mezar taşında küçük,minicik bir kuş.Onu bekliyordu, belki de hiç gitmemiş.

Belki de bekleyecek, sonsuza kadar. O, kuşları çok severdi, kuşlar da onu.Vefalıydı dostları, apaçık. Son dostu soğuk taşlar üzerinde.

     Yağmur başladı, inceden inceden.Hiç korkmadı, küçük kuş. Keyiflendi beni görünce. Şarkı söyledi, kendi dilince.  Anlamıştı, tanımıştı beni. Ben de onu..''Merak etme'', diyordu sanki bana.Annemi bekliyordu. Bekleyecekti, sonsuza kadar.

      Seni seviyorum, küçük kuş.Şarkı söylemeni de seviyorum. Yağmurda şarkı söylemeyi de. Dua ettim ardından, şarkı söyledim. Duydu mu, bilemem mevsimsiz ötüşümü.Gördü mü, yağmurun saçlarıma dokunuşunu....

       Anneme uğradım ayaküstü. Yalnızlığını paylaşmaya. İçim buruktu giderken. Gönlüm yaslı. Onunla birlikte göçüp gitmişti, pek çok şey. Yalnız bulacağımı sanmıştım onu, yapayalnız. Oysa bir ziyaretçisi vardı. Benden önce gelmiş. Belki de hep oradaydı. Son dostuydu, annemin..

         Yüreğim hoştu ayrılırken. Mutluydum, şendim çocuklar gibi.'' Sevgi'' koydum, minik kuşun adını. Can dostu annemin, sevgi kuşum.Yalnız değildi anneciğim.

          Sözde ayaküstü uğramıştım. Zaman su gibi aktı, geçip gitti zaman... Gölgem kadar kısaydı saatler. Yağmurda şarkı söyledik Sevgi kuşumla. Şarkılar yağmurla karıştı. ''Git'' dedi, Sevgi kuşum... Gözün arkada kalmasın...Döndüm, tekrar baktım giderken.... O, halâ bekliyordu.. Halinden memnun..', 'Anneme uğradım, sonbahardı. Anılarla sürüklendi ayaklarım. Taşlı, topraklı, hüzünlü yollara. Bir ziyaretçisi vardı, benden önce gelmiş. Meza...', ARRAY['Türk Edebiyatı','Şiir','Suna Doğanay']::text[], 8.5, '{"poet":"Suna Doğanay","poet_slug":"suna-doganay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anneme-ugradim-ayakustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanç 1', 'kiskanc-1-sedat-akguden-u75jy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sema BABAYİĞİT. e ithafen

Sensizliğin çılgınlığı

Sararken tüm bedenimi

Duygularım kaygılara 

Yüklenmiş

Sana doğru yol almakta

Bilmiyorum 

Olacakmısın yanımda

Bu en hırçın baharımda

POSTA Gazetesi [füsün ÖZBİLGEN}', 'sema BABAYİĞİT. e ithafen Sensizliğin çılgınlığı Sararken tüm bedenimi Duygularım kaygılara  Yüklenmiş Sana doğru yol almakta Bilmiyorum  Ol...', ARRAY['Türk Edebiyatı','Şiir','Sedat Akgüden']::text[], 8.5, '{"poet":"Sedat Akgüden","poet_slug":"sedat-akguden","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kiskanc-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşündün mü', 'dusundun-mu-sule-aydemir-3jowk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hiç düşündün mü/tam yaklaşmışken uzaklaşmayı

hiç fark ettin mi/koşuyorum derken yürümeyi bilmediğini

hiç anladın mı/dolu yaşıyorum derken hiçlere kurban verdiğini

hiç gördün mü/duyguların paslandığını ya da yer değiştirdiğini

hiç yaşadın mı/her şeyin çok şey olduğunu ve hiçbir şey olmadığını

hiç düşündün mü/ değişirken dün söylediklerinin yalan kaldığını

söylesene sen bildin mi/aslında sen olmadan sen diye yaşadığını

ona buna yaşamını bağışladığını

başkalarının hayatlarını yaşayacak kadar zengin

bir tek kendini bilmeyen/ey  cahil', 'hiç düşündün mü/tam yaklaşmışken uzaklaşmayı hiç fark ettin mi/koşuyorum derken yürümeyi bilmediğini hiç anladın mı/dolu yaşıyorum derken hi...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dusundun-mu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran', 'hicran-nermin-altindag-rfbh2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vur kadehi, aksın yine bir nefes mey, şiirin en dibine

Savur kelimeleri, yansın yine dilin, sarhoş ol bu gece

Savrul git kelimelerin en gizemli seyrinde

Yak ateşi, savur külleri, kızıl bir nehrin gölgesinde

Şiir ol, şair ol, aşık ol tut elini suzanın

Bu bir matemdir, şarkısıdır hicranın', 'Vur kadehi, aksın yine bir nefes mey, şiirin en dibine Savur kelimeleri, yansın yine dilin, sarhoş ol bu gece Savrul git kelimelerin en gize...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hicran-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SIĞINAK 2. SAYI/İhanet', 'siginak-2-sayi-i-hanet-nermin-altindag-qc6o4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İHANET

I)   

İhanet

Saçlarının akı

Kırışıklığı yüzünün

Suskunluğunla şehrin surlarına kazınmış suretin

Yalnızsın ve yalnız kalmalısın

II)   

Taş yontusu sözler dağdağasında hayallerin

Hayallerin vişne çürüğü sabahlara yelken açmış

Mor üzüm, göz sancısı ve hayal sanrıları

Bedelsiz yıllar, yıllar kayıp ve şehir suskun

İhanet çöreklenmiş yuvasına tarla farelerinin

İbrahim’in ateşine bir odun da ben taşımışım

Ateş köz, köz avuçlarımda, avuçlarım kangren

İhanetin bedeli bir ömür, ömür talan

Sinsi gülüşlerde aynalar, diz boyu yalan

Çırpınışlar beyhude, cehennem çukuru gözlerin tutsun yasını zindanların

Ben çocuksu gülüşleri annemin dizlerinde bıraktım

Pişmandım büyüdüğüme, arabesk aldanışlarda kandırdım zamanı

Aşımız aşktı, ekmeğimiz, suyumuz

Soluk alışlarımızda ciğerimize yığılan tortusu tütünün

Verdiğimiz soluklarımızda 

sevdamızı da aldı götürdü 

kaburga kemiklerimizin 

arasından

Haberimiz bile olmadı

Cevaplarını bulamadığım soruların arasında yitiyorum nice zamandır

İçim neden bu kadar karanlık ve aşk neden bu kadar uzak

Hoyratlığımıza buladığımız sevda sözcükleri bu kadar mı ucuz

Aşk, hangi şehrin surlarından sızdı karanlık sulara

Hangi balığın karnında dinledin dilini bilmediğin türküleri

İhanetin bedelidir taşlaşmış yürekler, atışları tutsak

Zaman patlamaya hazır saatli bomba

Şimdi bir ateş daha yakmalı ve bütün kağıtları kalemleri ve şiirleri kurban vermeli

Serinlesin diye İbrahim’in yüreği...

İhanetin bedelini suskunluğuyla ödemeli şair

Korkak doğmuş cennetin bütün şairleri

III)   

Ciğerlerin bu kadar zayıf olmasaydı

Olmasaydı ellerin bu kadar narin

Ve ayaklarına derman olsaydı annenin ninnileri

Bilirim, söndürmezdin ateşini cehennemin

Şimdi konuş, ay konuşsun, konuşsun serçeler

Bir şarkı da sen tuttur kurtulur belki dünya

Çağı yeniden yazacak kahramanlar listesinde varsın geçmesin adımız

Sesimiz evrenin bir yerlerinde hep dolanıp duracak

Kıyamet sarhoşluğu saracak bedenimizi

Rahimliğine sığındığımız yaradan, bilirim, büyüktür

Büyüktür ve kuşatır sonsuz rahmetiyle ihanetlerimizi

***Sığınak Dergisi 2. sayısında yayınlanmıştır***', 'İHANET I)    İhanet Saçlarının akı Kırışıklığı yüzünün Suskunluğunla şehrin surlarına kazınmış suretin Yalnızsın ve yalnız kalmalısın II)   ...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/siginak-2-sayi-ihanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefes Alamam Sensiz', 'nefes-alamam-sensiz-kadir-kaya-0shnq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Candan gülüşünle mutlu gözlerim,

Cansın,cananımsın olamam sensiz.

Yokluğunda kışa döner yazlarım,

Boğulurum nefes alamam sensiz.

Kederli günlerde odur sırdaşım,

Derdime dermanım anam kardaşım,

Gecemde gündüzde can arkadaşım,

Dağılırım yolu bulamam sensiz.

Kadirim,  geçirdik kırk iki yılı,

Ömür bahçemizin evlatlar dalı,

Torunla tadarken armağan balı,

Mutluluğa haber salamam sensiz.', 'Candan gülüşünle mutlu gözlerim, Cansın,cananımsın olamam sensiz. Yokluğunda kışa döner yazlarım, Boğulurum nefes alamam sensiz. Kederli gün...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nefes-alamam-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilim Türkçe Konuşur', 'dilim-turkce-konusur-nihat-yucel-isisq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İlk sözü anamdam öğrendim

Anam öğretti karayı-akı

Anam öğretti bana

Yurdumu-budunumu sevmeyi

Bayrağımı belletti

Anam al-al

Anamın ak sütü gibi helal

Ana dilim

               DİLİM TÜRKÇE KONUŞUR

Geçmişim ordularımla

Bir fırtına gibi

Demir kapıdan- Horasandan

Bir sel gibi

Akmışım Anadolu''ya

Dağ-taş çadır olmuş

Dağ-taş at

Dağ-taş çeri

Bütün zorluklara göğüs germişim

Dönmemişim geri

Otağlar kurulmuş

Konar-göçer çadırlar kurulmuş

Adımı vermişim

                          kanımı vermişim

                          canımı vermişim

Yurt edinmişim

Bastığm toprağı

Demişim yeni yurduma

Türkelim

                       TÜRKELİM TÜRKÇE KONUŞUR

Adımı vermişim çiçeklere

Kardelenim demişim

Yedi verenim demişim

Dağlara-taşlara-ağaçlara

Çiçeklere-otllara

Nehirlere-çaylara

Adımı vermişim

Sevdiğime-yavukluma

Demişim gülüm

                   GÜL''ÜM TÜRKÇE KONUŞUR

Ben bir Dede Korkutum

Yunus''um-Karacaoğlanım

Gün olmuş

Ocaklarda yanmışım

Gün olmuş

Buz tutmuş her yanım

Ben saz demişim

Bağlama demişim

O demiş kopuz

Ozanların her vuruşunda

İnlemiş telim

                      TEL''İM TÜRKÇE KONUŞUR

Bir Abdalanı Rum olmuşum

Yarı belime kadar çıplak

En önde ben çarpışmışım

Azap Çerileri demişler adıma

Saçlarımı kazıtmışım

Elimde tahtadan kılıç

Hacı Bektaşi Veliden

El almışım-yol almışım

Dolaşmışım

Baştan başa Türkelini

Bu yurdu ben yurt yapmışım

Ben bir dervişim-bir deliyim

                             DEL''İM TÜRKÇE KONUŞUR

Ben kağanlar yetiştirmişim

Acuna düzeni ben vermişim

Bir uçarsu olmuşum

Dağlardanovalara

Akmış bir selim

                                SEL''İM TÜRKÇE KONUŞUR

                                                           kASIM/2004

Şelalenin türkçesi: Uçarsu', 'İlk sözü anamdam öğrendim Anam öğretti karayı-akı Anam öğretti bana Yurdumu-budunumu sevmeyi Bayrağımı belletti Anam al-al Anamın ak sütü gi...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/dilim-turkce-konusur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günü gününe uymuyor', 'gunu-gunune-uymuyor-mikdat-bal-f2bf3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şair şiirini yazar

Bölüm bölüm azar azar

Bu gün yazar yarın bozar

Günü gününe uymuyor

Her gün bir şiire gebe

Her sözü kulağa küpe

Kâh umuma, kâh habibe

Günü gününe uymuyor

Yazar vaktini anını

Çevresini her yanını

Geçmişini, yarınını

Günü gününe uymuyor

Hayatı neyle meşgülse

Kolaysa, ya da müşkülse

Yazar iken ne şekilse

Günü gününe uymuyor

Genç yaşında sevdasını

Yaşlanınca vedasını

Vasiyeti, mevtasını

Günü gününe uymuyor

Kulağı halktan yanadır

Daha çok ağlayanadır

Dinleyene, duyanadır

Günü gününe uymuyor

Her şairin var bir yâri

Yazar doğduğu diyarı

Yazar gayri-ihtiyari

Günü gününe uymuyor

Birleşince ilham, sezgi

Meydana çıkar bir ezgi

Hayat grafikli bir çizgi

Günü gününe uymuyor

Mikdat der ki ben öyleyim

Gurbette iken köyleyim

Dün öyle bu gün böyleyim

Günü gününe uymuyor', 'Şair şiirini yazar Bölüm bölüm azar azar Bu gün yazar yarın bozar Günü gününe uymuyor Her gün bir şiire gebe Her sözü kulağa küpe Kâh umuma,...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gunu-gunune-uymuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Uçmağ Bağı', 'rubai-ucmag-bagi-nihat-yucel-juq2e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şair kişi bil ki tutkunun tutsağıdır

Gençlik çağı sevmek ve sevilmek çağıdır

Sen kendin olursan iyi herkes iyidir

Dünya o zaman inan ki uçmağ bağıdır

                                                  Şubat/72

Cennet:: Türkçesi Uçmağ', 'Şair kişi bil ki tutkunun tutsağıdır Gençlik çağı sevmek ve sevilmek çağıdır Sen kendin olursan iyi herkes iyidir Dünya o zaman inan ki uçma...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/rubai-ucmag-bagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Geçer', 'rubai-gecer-nihat-yucel-icc6p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevda çekenin günleri hicranla geçer

Geçmez sanılan çağları efganla geçer

Bir gün olur aşık kavuşur sevdiğine

Günler geceler gül gibi cananla geçer

                                              1968', 'Sevda çekenin günleri hicranla geçer Geçmez sanılan çağları efganla geçer Bir gün olur aşık kavuşur sevdiğine Günler geceler gül gibi cananl...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-gecer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Bu mudur', 'rubai-bu-mudur-nihat-yucel-qfp2n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Candan seni andığım dediğin şey bu mudur

Sevdan ile kandım dediğin şey bu mudur

Sorsam bana söyler misin ey sevgili yar

Aşkınlada yandım dediğin şey bu mudur

                                                  Mayıs/68', 'Candan seni andığım dediğin şey bu mudur Sevdan ile kandım dediğin şey bu mudur Sorsam bana söyler misin ey sevgili yar Aşkınlada yandım ded...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-bu-mudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Gibisin', 'rubai-gibisin-nihat-yucel-vvgkn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey kız yine başlardaki taçlar gibisin

Düşman değiliz sen bizi taşlar gibisin

Gelsen yine bak şenlenecek dünyamız

Sensiz ölürüz gövdede başlar gibisin

                                                   1969', 'Ey kız yine başlardaki taçlar gibisin Düşman değiliz sen bizi taşlar gibisin Gelsen yine bak şenlenecek dünyamız Sensiz ölürüz gövdede başla...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Bir Gün', 'rubai-bir-gun-nihat-yucel-a3jx8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güller açılır sen de kokarsın bir gün

Gönlündeki sevgiyle dolarsın bir gün

Aldanma güzel mutlu geçen günlerine

Tüller sararır sen de solarsın bir gün

                                             Mayıs/69', 'Güller açılır sen de kokarsın bir gün Gönlündeki sevgiyle dolarsın bir gün Aldanma güzel mutlu geçen günlerine Tüller sararır sen de solarsı...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok yok', 'yok-yok-tuncay-akdeniz-ja3rf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu bahçenin bağlarına girilmez

Ağacı yok dalları yok gülü yok

Bu meydanın pazarından alınmaz

Pazarı yok malları yok pulu yok

Sabahın güneşi akşam batıyor

Her doğan canlıyı toprak yutuyor

Bu toprakta nice canlar yatıyor

Mezarı yok canları yok éli yok

Bu hekimde derde derman sürülmez

Her gönül e zevki sefa verilmez

Elbisesi yoktur libas giyilmez

Kumaşı yok pulları yok alı yok

Aklı olan dünya zevkine dalmaz

Çalışan dersini  ikmal a kalmaz

Her mevsim içinde çiçekler olmaz 

Arısı yok balları yok dalı yok

O kutlu makamdan dünyaya geldim

Tuncay dertsiz idim dertleri buldum

Alemi varlığa bir insan oldum

Vatanı yok kulları yok ili yok', 'Bu bahçenin bağlarına girilmez Ağacı yok dalları yok gülü yok Bu meydanın pazarından alınmaz Pazarı yok malları yok pulu yok Sabahın güneşi ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yok-yok-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Eylül Vurdu Yüzüme...', 'eylul-vurdu-yuzume-i-mdat-ozcan-4cczi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düş gördüm

Yarının vuslatında gülen çocuklar

Tomurcukları yuvalanmış filiz

Masum

Kurtulmuşum şom ağız nazarından

Gülmekte gözler

Gülmekte sokakları memleketimin

Şimdi iç çeker bir yanım

Bugün esrik hayat

Bugün yangın

Bugün ölüm üzre kelamlar

Patlamayan bombalar

Düşmeyen tetikler 

Vurulmayan çocuklar gördüm 

Şafak aklığında

Oysa kızıl bugün 

Sevmeler tutuklu 

Zindan

Urgan 

Volta

Taşları kırık bir tesbih

İşlemeli / gümüş

Eylül vurdu yüzüme

Yüzüm kan revan

Uykum tedirgin

Gece

Vurgun

Bugün kanar şehir

Bugün çığlık çığlığa

Düş gördüm 

Ellerimde yuvalandı gökkuşağı

Üç ucu yanık mektubun

Görüş günü gelmez gayrı

Gün görüşmez benimle

Iraklardan buyruk verilir

Aşk yarına

Sevda yürekte işlenir 

Sevdam köz

Sevdam rüzgar beklemekte

Düş görmüştüm

Uyandım

Ellerimden kaydı gökkuşağı…', 'Düş gördüm Yarının vuslatında gülen çocuklar Tomurcukları yuvalanmış filiz Masum Kurtulmuşum şom ağız nazarından Gülmekte gözler Gülmekte so...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/eylul-vurdu-yuzume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Vardın', 'sen-vardin-ufuk-nazim-a8dn1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahçedeydin; 

İçi dolu ağaç

Rüzgarlarla soluklanan

Günün taa içinde; 

Sen vardın.

Tanıdık bir ezgi,

Rüzgarın kolunda

Ve Nazım ın resimleri

Asılı duvarların üstünde.

Burası evin seninde

Buğulanan bir camı sildin

Bak içine

Bu seninde için

Ruhunun aynasıdır 

Mısralardan seken.

Ve ustan Nazım

Yeniden yeniden dirilen

Milyonların içinde

Küçücük bir mum olana 

Ve yurttaşların içinde

Anadoluda

Olana dek

Dirilecek

Duvarların içinden.', 'Bir bahçedeydin;  İçi dolu ağaç Rüzgarlarla soluklanan Günün taa içinde;  Sen vardın. Tanıdık bir ezgi, Rüzgarın kolunda Ve Nazım ın resimle...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-vardin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğri Odun', 'egri-odun-himmet-karatas-y6itf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaz uykusuna küsmüş 

Bir uçurum çağırıyor beni

Hiç beklemeden

Orta şekerli kahvemi

Ormanın rahatlığına çekiyor

Yakamdan 

Rehavetim çamlara yapışıp kalınca

Annem

Çıkarıyor sarı günler arasından

İlk resmimi

Olmadı diyor

Eğri odunun bile yok senin

Büzülüyorum

İlk resmime sığacak kadar', 'Yaz uykusuna küsmüş  Bir uçurum çağırıyor beni Hiç beklemeden Orta şekerli kahvemi Ormanın rahatlığına çekiyor Yakamdan  Rehavetim çamlara y...', ARRAY['Türk Edebiyatı','Şiir','Himmet Karataş']::text[], 8.5, '{"poet":"Himmet Karataş","poet_slug":"himmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/egri-odun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Flash Haber', 'flash-haber-himmet-karatas-pytpg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin güzelliğinden 

Bir gökyüzü yaptım çocuklara

Bu yüzden onlar 

Hiçbir masala sığmadılar', 'Senin güzelliğinden  Bir gökyüzü yaptım çocuklara Bu yüzden onlar  Hiçbir masala sığmadılar...', ARRAY['Türk Edebiyatı','Şiir','Himmet Karataş']::text[], 8.5, '{"poet":"Himmet Karataş","poet_slug":"himmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/flash-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden...', 'yeniden-avni-aydin-2xrra', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'garip oluyor,

geçmişte hissettiklerini

yeniden hissedebilmesi insanın...

sabah yasanan dinginliğin

aksam yasanan tatlı yorgunlugun...

bir aralık girince hayatlara

kopuyor insan hayat koşuşturmacasından...

yanılsamaların ilk sonlarıyla...

seyrederken kayan hayatı bile camından otobüsün,

sarhoş oluyor yorgun yurekler hayata inat...', 'garip oluyor, geçmişte hissettiklerini yeniden hissedebilmesi insanın... sabah yasanan dinginliğin aksam yasanan tatlı yorgunlugun... bir ar...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yeniden-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yankısı Yok Yine Sesimin', 'yankisi-yok-yine-sesimin-melih-coskun-z4s4u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yankısı yok yine sesimin 

Ve mevsim

Yine paramparça bir sonbahar

Ölüm ve doğumun en büyük randevusu yitik avlularda 

En kırılgan çağı ömrümün 

Adı yok doğan günün 

Sen pişmanlık desen de

Her cümle eksik derken

Ve ömrüm boyunca haykırabilecekken 

Yüreğimde çağlayan sesi 

Seviyorum diyecekken 

Kapanmaz yaralarına ve 

Ayrılıklarına inat

Yahut hiç kavuşamamalarına

Susmaktır yine payıma düşen. 

Ve kahreden budur ki 

Kimse zorlamamıştır buna seni 

Yenik düşersin 

Sesinin yankısızlığına...', 'Yankısı yok yine sesimin  Ve mevsim Yine paramparça bir sonbahar Ölüm ve doğumun en büyük randevusu yitik avlularda  En kırılgan çağı ömrümü...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yankisi-yok-yine-sesimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni yalnızlığım paklar', 'beni-yalnizligim-paklar-aysun-elagoz-9epfu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'uzaktır mutluluk kaf dağı kadar

geleceğe dair 

tükenen umutlar

kitlenirken boğazıma

kulağımı takayıp

kapatıp gözlerimi

zil zurna sarhoş bahara

son çare

kapandım kendime 

uzaktır benden huzurlu şafaklar

anladım ki 

beni ancak yalnızlığım paklar....', 'uzaktır mutluluk kaf dağı kadar geleceğe dair  tükenen umutlar kitlenirken boğazıma kulağımı takayıp kapatıp gözlerimi zil zurna sarhoş baha...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beni-yalnizligim-paklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkmadım', 'korkmadim-aysun-elagoz-6ssd4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ölümden korkmadım 

ölürken bile

beni vuran kurşun 

çıkmasaydı dudaklarından

bu denli acıtmazdı

şu yalnız yüreğimi

ölüm  bile....', 'ölümden korkmadım  ölürken bile beni vuran kurşun  çıkmasaydı dudaklarından bu denli acıtmazdı şu yalnız yüreğimi ölüm  bile.......', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korkmadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğlence', 'eglence-kadir-polat-ddh30', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ödünç 

sevinçlerle 

geldim 

akşamına

hadi gülelim', 'Ödünç  sevinçlerle  geldim  akşamına hadi gülelim...', ARRAY['Türk Edebiyatı','Şiir','Kadir Polat']::text[], 8.5, '{"poet":"Kadir Polat","poet_slug":"kadir-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/eglence-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Sorma!', 'hic-sorma-siyah-gri-v83hn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öylesine sıkılıyordu ki; içim

kıyısına gittim dün sahilin.

Tepemde ılık bahar güneşi

bir çarptı ki; beni 

hiç sorma! …

Tıpkı mavi bir mürekkep gibiydi 

Marmara…

içine karıştırdım duygularımı

hepsi sır oldu.

Öylesine rahatladım ki; 

hiç sorma! …', 'Öylesine sıkılıyordu ki; içim kıyısına gittim dün sahilin. Tepemde ılık bahar güneşi bir çarptı ki; beni  hiç sorma! … Tıpkı mavi bir mürekk...', ARRAY['Türk Edebiyatı','Şiir','Siyah Gri']::text[], 8.5, '{"poet":"Siyah Gri","poet_slug":"siyah-gri","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hic-sorma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinde Kanar Yarın', 'i-cinde-kanar-yarin-kamil-aydemir-gmcfe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'keder bende gülüm

             bende gam

yanık kokar yatak odam

gecelerde savrulur külüm

daha berbatlarını tanıdım senden

korkutamasın beni ölüm

geceleri sevmediği adamın koynunda yatan

sen benim karanlığa batan sol yanımsın

yıldızları bile ağlatan sevdiğim kadınsın

dallardaki kuşlar hüzünün dem yerindeyken

ve güller ağlarken geçtim kapından

cama bile çıkmadın

ben kanarken hiç mi acımadın

kıyarsan sevdamıza

yakamozlar küser denize

önce kırlangıçlar göçer

seni de terk eder güzellikler

yangın yeri yüreğinde hüzünler

ve solmuş güller

elinde kalır yitik yıllar

hasretinle içtim

üçyüz promil aşkın çıktı kanımda

tamda yaslanacak anımda sen yoksun yanımda

sevinçlerim perişan 

zemherim olma da

varoşlardaki isyan gibi

içimde sevgin büyüsün

sen de kurtul mutsuzluğun pençesinden 

ve kurtlar sofrasından

gamzelerinde yeryüzünün çocukları gülsün

ve günlerin aynası mutlu bir kadın görsün

değilsin ki taştan kaçamasın aşktan

sevgime kaparsan kapısını gönlün

felç olur zaman

hayat komada

akordu bozulur çalgıların

dili tutulur şarkıların

içinde kanar yarın

ah sol yanım 

bu sevda senin baharın', 'keder bende gülüm              bende gam yanık kokar yatak odam gecelerde savrulur külüm daha berbatlarını tanıdım senden korkutamasın beni ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/icinde-kanar-yarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namus', 'namus-suheyl-turkoglu-eaqq6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lastik gibi sünüyor,

Bukalemun namus.

Sonsuzluğu perdeleyen,

Ahlaksızlığı örten,

Kişiye göre

Kılık değiştiren,

Etek içinde

Hayat bulan,

Beyinlerde

İhanete uğrayan,

Manyaklaştırıp

Cinayetler işleten,

Romantik,

Masum,

Sarhoş,

Biraz da manyak,

Çılgın namus.', 'Lastik gibi sünüyor, Bukalemun namus. Sonsuzluğu perdeleyen, Ahlaksızlığı örten, Kişiye göre Kılık değiştiren, Etek içinde Hayat bulan, Beyi...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/namus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sehit annesi', 'sehit-annesi-hanife-ayaz-4xcm2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyanma annem dertleselim seninle

uykunun arasinda

aglama artik ne olursun

gözyaslarin kurudu göz pinalarlarinda

Bir sehit düsen ben degilim

bu vatan ugruna

nice gencler katti kanini topragina suyuna

makberimdeki gül  düsmana silahim 

Mermim ise yapraklari

korkar anne düsman

gülümün rengi onlarin yüreginin kani

hic kimse vermez anne

canini versede bu vatani

Aglama annem kurusun gözlerindeki pinar

yagmur olsa kuru topraklar kanar

birgün hesap verecek annem

bizi yakan kör kursunlar

Inmeyecek bayragim gökyüzünden

dalgalanacak dalga dalga

oksayacak rüzgar ilik ilik bayragimi

annecigim senin oksadigin gibi

nasil oksardin saclarimi

Agit yakma annem agit yakma pesimden

ruhum ter olur bosanir gökyüzünden

üzülme annem aglama

ben uykularinda gelecegim ziyarete sana

buse konduracagim o islak yanaklarina

sarilacagim boynuna

sen Türk milletinin basinin tacisin

övün sehit oglunla

en güzel varligini verdin

sen bu vatana

Bayram geliyor anne

arife gecesi gelecegim

öpüp ellerini koyacagim anlima

hakkini helal et diyecegim annem

biliyorum helal kuzum diyeceksin ak sütüm sana

aglama annem aglama

rüyalarindada olsa gelecegim sana

ruhum dolasacak baba ocaginda

yavrunun teninin kokularini duyacaksin

uykularinin arasinda

uyaninca anlat oglunun geldigini

ak sacli babama

ahiretten selam söyledi de

sehit oglun sana

Birdaha aglama annem dayanamam

inci gibi akan gözyaslarina

mürvetimi görmek isterdin

dizlerinde dururdu basim

annem mürvetim SEHIT yazisiyla

yazilmis mezar tasim

22/7/97', 'Uyanma annem dertleselim seninle uykunun arasinda aglama artik ne olursun gözyaslarin kurudu göz pinalarlarinda Bir sehit düsen ben degilim ...', ARRAY['Türk Edebiyatı','Şiir','Hanife Ayaz']::text[], 8.5, '{"poet":"Hanife Ayaz","poet_slug":"hanife-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/sehit-annesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karameleğime', 'karamelegime-golge-gezgini-pfkzb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne dinmeyen gözyaşım

Ne hayasızca bir alkış

Dön karameleğim

Bu sana son haykırış', 'Ne dinmeyen gözyaşım Ne hayasızca bir alkış Dön karameleğim Bu sana son haykırış...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/karamelegime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle neyleyim', 'soyle-neyleyim-hanife-ayaz-91fj2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hazana   dönmüs  kurak bahcede

Ter  oldum  sarildim  narin  bedene

Kaldirmadin  takilip düstügüm yerde

Yollarimda dikken idin yoldum neyleyim

Kurulmustun gönlümün bos tahtina

Can adamistim yar senin yoluna

Kiymet bilmeyenler düser sonunda

Gönül sarayimda sultan idin yiktin neyleyim

Duydumki agliyor  sevdigim  gözler

Dert cibani bitirdi o  yalan  sözler

Kiymetini  bilmedi mi  yabanci eller

Bir zamanlar goncam  idin soldun neyleyim

Yagmur oldum suladim soldurmamak icin

Firtinaya gögüs gerdim yoldurmamak icin

Sakindim  tenimden aglatmamak icin

Candin bedenimde yar öldün neyleyim

21/8/98', 'Hazana   dönmüs  kurak bahcede Ter  oldum  sarildim  narin  bedene Kaldirmadin  takilip düstügüm yerde Yollarimda dikken idin yoldum neyleyi...', ARRAY['Türk Edebiyatı','Şiir','Hanife Ayaz']::text[], 8.5, '{"poet":"Hanife Ayaz","poet_slug":"hanife-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soyle-neyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nilüfer', 'nilufer-yelda-karatas-z0p70', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu ikinci şiirim sana 

Kaç bin yıl sonra yeniden

Ak kağıt üste

Kor 

Sen daha küçüktün  bense kayıp çapraz  bilmeceler

Kara tahta, üzgün tebeşir

hayat o güzel ırmak işte 

İçinde nilüfer gezen çocuklar

Her gece yitirip annesini  arar

 

Koşarken hayata  takılan gözyaşlarımız mı ne

Güneş altında şapkası  da yok ki

Çocukken bizi taştan başka kim anlar

 Ah! kaç entarin vardı  senin  hiç bilmem

Üstü kırmızı kiraz 

muhtemel

daha küçükken acıttılar

gözlerin

“tren gelir hoş gelir”

Belki bundan benim durup dururken bir yerlere  gitme isteğim

Sor  unutulmuş  çocukluğunu arayan  kızım

O bahçenin ortasında 

Aşk ölüme başkaldırır değil mi

Susar dalında  son gül

haykırarak gözleriyle her şeyi

O  bir örnek iki siyah gömlek 

Bende unuttun

Ya yitirirsem diye 

armağan almışım sana

bilmeden 

Öyle çok şey var ki bende bıraktığın 

bilmeden

Durgun suya hasret kızım 

Ateşin çocuğu

Ak kağıt üstüne  açan Nilüfer...', 'Bu ikinci şiirim sana  Kaç bin yıl sonra yeniden Ak kağıt üste Kor  Sen daha küçüktün  bense kayıp çapraz  bilmeceler Kara tahta, üzgün tebe...', ARRAY['Türk Edebiyatı','Şiir','Yelda Karataş']::text[], 8.5, '{"poet":"Yelda Karataş","poet_slug":"yelda-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/nilufer-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maden İşçiliği Şehitleri', 'maden-i-sciligi-sehitleri-akin-akca-cqjsg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yerin dibinden verilen körüklü yaşam, 

Karanlıklardan, ışık ürettiğin madenden. 

Bilmez çok kimse neler çektin sen. 

Ama bilir kaleminin şairin önsezisi … 

Yazarın cümleleri fark eder ve dillendirir … 

Spatulasınca oynak fırça darbeleri 

Onun, ressamın, paletten tuvale … 

Müzisyenin notaları ve şan sesken … 

Bilen kendini veya herkes, senin adınca … 

Evet, yine de çok kişi arkanda 

Maden işçiliği yeraltı şehitliğinde; 

Ya entrika, işte ya o cahil körkütük, 

Sökük, domino taşlarından, Politika. 

Ebedi, körpe, taylar ve kısraklar 

Bu mevkide şahlanır terminolojide; 

Yükseltmek uğruna tüm o medeniyeti, 

Verdiğin tarafsız bir mücadelede:

Eh sanki hatalı mağara adamı mı; 

bilmek bunları, büyük şeydir yontmak

karanlığın, şafağın hür alacakaranlığını - 

Sen “biraz karnımı doyurdum” sanırken 

Belki; ya da bir gidişte, şuurlu tüm. 

Mehmetçik, sessiz sedasız, göğsünü 

Siper ederek cepheye, gıkı çıkmadı. 

Cesaretli, zoraki edilen-oynaklar asla

Bıkmadı, insan ya cesur şaşmadı

Yoldan, Sen Bernar geliyor dağdan! 

Işık karanlıktan kapan babalar günü, 

Ama aile bakmak göçük altı olmamalı! 

Altı şehit verdik diri Zonguldak’ta, 

Yerin altından sorgulamışlardı - 

Medeniyeti yüceltirkendi ve, ah ellerde 

Yükseldi, zaman muğlak, pamuk 

Tesadüfi ipliği, taşınanlar ölü beşik; 

Çektiğinizi yaşamayan bilemez, nelerdi 

- Belli belirsiz bir yaşam hakkı adına. 

- 

Zonguldak’ta ölenler anısına 

ayrıca mucizenin ışık işçilerine ithafen 

ki aynı 

18 06 ‘05', 'Yerin dibinden verilen körüklü yaşam,  Karanlıklardan, ışık ürettiğin madenden.  Bilmez çok kimse neler çektin sen.  Ama bilir kaleminin şai...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/maden-isciligi-sehitleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamdan başka...', 'gamdan-baska-i-lhami-arslantas-m0pir', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hey cevri cefasın çektiğim düzen

Demden başka ne verdin ki nem ola

Yastık altı hesabı mı sorarsın

Zamdan başka ne verdin ki nem ola

Doktor  ilaç ekmeğe el erdi mi

Gözün çıksın niçin aldın vergimi

Yataktayım bilmez misin derdimi

Ramdan başka ne verdin ki nem ola

Gidiyorum  çok kalmadı menzilim

Gün sayıyor  ağzım alevde  dilim

Sende kalsın göz yaşıyla mendilim

Gamdan başka ne verdin ki nem ola

Der ilhami ger çarmıhın as beni

Korkun varsa bir baltayla kes beni

Zaten sağken öldürecek sus beni

Gemden  başka ne verdin ki nem ola', 'Hey cevri cefasın çektiğim düzen Demden başka ne verdin ki nem ola Yastık altı hesabı mı sorarsın Zamdan başka ne verdin ki nem ola Doktor  ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gamdan-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Buseleyen Dudaklar', 'olumu-buseleyen-dudaklar-necmi-unsal-gec7u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kervan yorgun, yollar yorgun; yorgunluk sevdalara yıkılır.

Kim bilir kaç mecnun yuttu çöllerde, acımasız bu kumlar! 

Okyanusta saman çöpü hep titrer, yalnızlıktan sıkılır.

Vuslat yalan! Bu yalanla yatsıya kadar yanar  bu mumlar.

Elbet bir gün filizlenir hayata atılan tüm tohumlar.

Yeşerir de ağaç olur, dal sürer; yapraklanır  budaklar.

Dertler çöker, aşk göverir; gebedir gülmelere doğumlar.

Seherlere selam söyler ölümü buseleyen dudaklar.

29 Nisan 2004 Perşembe, Danimarka-Køge 23.51

4+4+3+4+3', 'Kervan yorgun, yollar yorgun; yorgunluk sevdalara yıkılır. Kim bilir kaç mecnun yuttu çöllerde, acımasız bu kumlar!  Okyanusta saman çöpü he...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olumu-buseleyen-dudaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alpaslan', 'alpaslan-hadi-onal-dlhcl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Alpaslan

Çatal yürek,öncü komutan

Elde Kur''an

Bismillah

Başladı kutsal akın

Ovası toprak

Dağları gül kokan Anadolu’ya

İşte Ani, işte Şavşat

Az ötede Van

Buyur dedi ufkun usu

Susan sayılara

Susayan gönüllere su

Zalimlerin zulmüne

Kine,nefrete, kire

Kılıçlar çıktılar 

Bir bir kınlarından

Alpaslan

Çatal yürek,öncü komutan

Elde Kur''an

Bismillah

Gökte ay yarım

Benim diyordu

Benim kararım

Yurt yapmak Anadolu’yu Türk’e

Yedi iklim yetmiş renk

Her boğumu bin ahenk

Kucak kucak

Çelenk çelenk

Güneşi getirdim diyordu güneşi

Güneşin doğusundan

Alpaslan

Çatal yürek,öncü komutan

Elde Kur''an

Bismillah

Omuzlarda ter

Heybesinde lor

Atının üstünde dimdik

Öylesine emin

Ölümüne vakur

Damarlarında atası Bilge Kağan:

“Üste Gök Tanrı basmazsa

Altta yağız yer delinmezse”

Dünün aynası temiz

Yarın avuçlarının içinde

Alpaslan

Çatal yürek,öncü komutan

Elde Kur''an

Bismillah

Dağ doruklarında,vadilerde

Yeniydi

Yepyeniydi

Özü hukuk

Sözü buyruk

Her komutanı bir ülke

Her ülkesi Alpaslan

Alpaslan

Çatal yürek,öncü komutan

Elde Kur''an

Bismillah

Muştular getirin diyordu

Oğullarına:

Melikşah’a,Togan’a, Gümüş Tekin’e

İlyas’a, Aslanşah’a

Muştular getirin diyordu bana

Komutanları:

Artuk Bey’e, Afşin’e Süleyman Şah’a

Muştular

İsfehan’dan,Merv’den,

Herat’tan, Horosan’dan

Güneyden Adıyaman’dan

Antakya’dan

Batıdan Muş’tan,Oltu’dan

Harput’tan

Alpaslan

Çatal yürek,öncü komutan

Elde Kur''an

Bismillah

Nice benim diyene kök söktüren

Rahla ovasında

Romen Diyojen’e diz çöktüren

Kutsal akınla 

Anadolu’ma doğan

Asırlara inşa

Sözü haktan

Alpaslan

Çatal yürek,öncü komutan

Ne ilkti ne son kahraman.', 'Alpaslan Çatal yürek,öncü komutan Elde Kur''an Bismillah Başladı kutsal akın Ovası toprak Dağları gül kokan Anadolu’ya İşte Ani, işte Şavşat ...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/alpaslan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Çocuk Kal', 'hep-cocuk-kal-hadi-onal-mwudf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sena’ma

Gül desem yolar zaman

Takıp da dikenlere

İncitir yüreğini

Kıyamam sana çocuk

Ay desem gölgelenir

Saçlarında bulutun

Ses desem uzaklaşır

Duyamam sonra çocuk

Kar desem ulu dağda

Hep buz gelir aklıma

Su desem buharlaşır

Doyamam sana çocuk

Can desem yüreğime

Sevdalar çöreklenir

Yıldız olur göklerde

Sayamam sonra çocuk

Renk desem küser bana

Şekillerin ahengi

Senin çizdiğin resmi

Boyamam sensiz çocuk

Melek desem korkarım

Uçuverirsin diye

Uçsuz maviliklere

Koyamam seni çocuk

Umut desem gölgesiz

Sevgi desem riyasız

Ne olursun sen çocuk

Hep çocuk kal hep çocuk', 'Sena’ma Gül desem yolar zaman Takıp da dikenlere İncitir yüreğini Kıyamam sana çocuk Ay desem gölgelenir Saçlarında bulutun Ses desem uzakla...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hep-cocuk-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah derse tek bir lisan', 'allah-derse-tek-bir-lisan-i-brahim-sahinoglu-ar7wi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allah derse tek bir lisan

Sözü eyimiş, eyimiş

Aşığım bağrımda yanar

Közü eyimiş eyimiş

Kar görünür cebel dağa

Bülbül feryat imiş bağa

Bahar gelir bak nevrağa

Yazı eyimiş eyimiş

Tefekkür babında kalmak

İlmi ledunnuya dalmak

Batin yardan name almak

Bazı eyimiş eyimiş

Yanmakla gün olmaz tamam

Ah vah ile geçer zaman

ŞAMDA canan sana kurban

Tozu eyimiş eyimiş

Fikrimde ettim gümanı

Aradım yok bu cananı

Benim derdimin dermanı

Yozu eyimiş eyimiş

Neyim var fani dünyada

Elimden çıktı irade

Eyvallah bana müsaade 

Azı eyimiş eyimiş

Hulusiden akar yaşlar

Hayal oldu bütün düşler

Eş yaren kavim kardeşler

Hızı eyimiş eyimiş

		Nuri ŞAHİNOĞLU

		      Aşık Hulusi

                                NARMAN / ERZURUM', 'Allah derse tek bir lisan Sözü eyimiş, eyimiş Aşığım bağrımda yanar Közü eyimiş eyimiş Kar görünür cebel dağa Bülbül feryat imiş bağa Bahar ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şahinoğlu']::text[], 8.5, '{"poet":"İbrahim Şahinoğlu","poet_slug":"i-brahim-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/allah-derse-tek-bir-lisan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Dünya İçin D-8', 'yeni-bir-dunya-i-cin-d-8-ekrem-sama-nu5gn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Yarışma için yazıldı...)

Hep merak edilir, nedir acep sekizler? 

Kısa yazıyorum, ama anlayın sizler...

Ben hayran olmaktan kendimi alamadım,

''Yeni bir dünya'' ya doğru atılmış adım.

Böyle bir birliğin getirisi çok büyük,

Bu büyük birliğe bizler ettik öncülük.

Kural tanımayan sanayileşmiş güçler,

Potansiyel gücü anladılar bu sefer.

İlişkiler gözden geçirilecekti yeniden,

Gelişmiş yediler, irkildiler aniden.

Türkiye''miz önder, İran, Mısır, Malezya,

Pakistan, Bangladeş, Nijerya, Endonezya.

Kalkınmakta olan, sekizyüzmilyon nüfus,

Büyük potansiyel, tam dostça bir konsensus.

Birliğin mimarı tanırlar Erbakan''ı,

Güçlü Hükumet''in Muhterem Başbakan''ı.

Hiçbir ülke değil, sömürüye müstehak,

Birliğin temeli kabul edilmişti: Hak...

Bu birliğin altı esası var hak için,

Hakları güçlere karşı korumak için.

Esas gaye barış olmalı kavga değil,

Barışa ermeli her millet mütekamil.

Diyalogla çözüm, her sorun için tek tek,

Menfaatlere de çok dikkat edilerek...

Sömürü emeli her devirde demode,

İş birliği esas olmalı ilişkide.

Kabul edilemez hiçbir ezme gayesi,

Adalet olacak birliğin sermayesi.

Kim kimden üstünmüş, olabilir mi böyle? 

Her karar alınır, eşitlik ilkesiyle.

Zulme uğrayamaz, fertlerden hiç birisi,

Hakim kılınmalı her yerde demokrasi.

Artık kuvvet değil, hak tutulmalı üstün,

Kuvvetli yıkmadan, dünyamızı büsbütün.

Diğer ülkelerle, ticaret gelişmeli,

İç ticaretimiz, olacak çok verimli.

Temel sanayide, iş bölümü olacak,

Yerli yapılacak, araba, gemi, uçak...

Sınırlanmayacak böyle güzel bir birlik,

Genişleyebilir, ama sekiz şimdilik...

Dünya örgütleri ve İslam ülkeleri,

İlişkiye açık birliğin ilkeleri.

Doğal kaynakları, petrolü, hammaddesi,

Sekizlerde boldur, zenginliklerin hepsi.

Barış hakim olup, unutulacak savaş,

Kaynaklar servete dönüşür yavaş yavaş...

Sekiz ülke ile oluştu bu omurga,

Dünyaya vuruldu hilal şeklinde damga.

Altyapı hazırdır, artık yürütmek ister,

Şimdi lazım olan dirayetli bir lider.

(İstanbul:17.06.2005)', '(Yarışma için yazıldı...) Hep merak edilir, nedir acep sekizler?  Kısa yazıyorum, ama anlayın sizler... Ben hayran olmaktan kendimi alamadım...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yeni-bir-dunya-icin-d-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirde Kaybolduk', 'siirde-kaybolduk-ozan-ozel-nq6hn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çürük mısralarda

anlam kavgasına tutuştuk

var olduğumuzu anlatmak isterken

yok olduk

şiirde kaybolduk

yazık olduk...', 'çürük mısralarda anlam kavgasına tutuştuk var olduğumuzu anlatmak isterken yok olduk şiirde kaybolduk yazık olduk......', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/siirde-kaybolduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam Sevecek Seni', 'sevdam-sevecek-seni-gulay-yildiz-lpuhr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sesini fısıldadı meltemi sabahın

Ve sonra uzaklaştı 

Ardımdan gel der gibi

Sen; 

Sesini aleme sunup da benden sakınan yar! 

Bir dön, bir bak yüzüme! 

Haykırışlarımı duymaz mısın? 

Mayışsın sevdam, ruhuna dolaşsın.

Dolaşsın da damarlarında kana bulaşsın.

Varlığını ben kılmaksa sevgi; 

Sen, sadece orda kal...

Sevdam sevecek  seni.

Seni ve damar damar benliğini! 

Sesini uğuldadı rüzgarı efkarın

Ve sonra uzaklaştı 

Seni de talan etsinler ben gibi', 'Sesini fısıldadı meltemi sabahın Ve sonra uzaklaştı  Ardımdan gel der gibi Sen;  Sesini aleme sunup da benden sakınan yar!  Bir dön, bir bak...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdam-sevecek-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B01 - Gel', 'b01-gel-tahir-gungor-a3cz8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdalanıp süzülmeden,

Sandık sepet düzülmeden,

Örgü saçın çözülmeden,

...........................................G e l.

Yanakların güllenmeden,

Güzelliğin bellenmeden,

Sözolup dillenmeden,

...........................................G e l.

Baharın yaza ermeden,

Baban ellere vermeden,

Kimsecikler görmeden,

...........................................G e l.

Dal verip kök salmadan,

Çiçeğe meyveye varmadan,

Acıya, derde karmadan,

...........................................G e l.

Doğru ol doğru yolunda,

Kendi aşın kendi suyunda,

Gurur kibirden soyun da,

...........................................G e l.

Binbir kulp takılmadan,

O bu başa kakılmadan,

Hor gözle bakılmadan,

...........................................G e l.

Bir ileri bir geri bak da,

Köprüleri yık, gemileri yak da,

Geçmişi geride bırak da,

...........................................G e l.

Örf-adete dalmadan,

Gözün arkada kalmadan,

İnce iğne almadan,

...........................................G e l.

Bugünü kıskanmadan,

Geçmişe yaslanmadan,

Yanakların ıslanmadan,

...........................................G e l.

Belim boynum bükülmeden,

Saçım başım dökülmeden,

Yıllar yüzüme dikilmeden,

...........................................G e l.

Akşam olmadan, gün inmeden,

Yaşam yolunda dinmeden,

Bedene ağrılar sinmeden,

...........................................G e l.

Kan demden geçmeden,

Ben benden geçmeden,

Can tenden geçmeden,

...........................................G e l.', 'Sevdalanıp süzülmeden, Sandık sepet düzülmeden, Örgü saçın çözülmeden, ...........................................G e l. Yanakların güllenme...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/b01-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Var mı?', 'haberin-var-mi-mehmet-dag-csiwv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deli rüzgârlar uçuşuyor dışarıda

Ormanların çamları devriliyor bir bir

Kulağa ışık gelmiyor, göze ses 

Cam duvarları paran parça evimin

Yatacak yeri yok uykularımın

Sele kapılmış yüreğim 

Haberin var mı? 

Haberin var mı? 

Lapa lapa kar yağıyor sevdama

Cellat indirdi indirecek  kılıcını enseme

Bu acının yemeğini görmedi hiçbir ana

Durmadan çiviler çakılıyor beynime

Yılanlarla birlikte yatıyorum

Haberin var mı? 

Dişe diş dövüşüyorum taşlarla 

Silaha, bombaya, füzeye karşı 

Bir elim cevizlerimde

Ha dondum ha dona cam

Can siper. Canım siperde.

Haberin var mı? 

Yaşamak sevdasıdır bizimkisi, gök tanrısıyla

Gömülmek isteniyoruz toprağa 

Gece ilerledikçe yoğunlaşıyor karanlık

Yutacak diri diri besbelli

Bir lokma ciğer gibi …

Yer tanrısı…

Haberin var mı? 

Sevdamın hülyalarına bıraktım kendimi

Hedefine kilitlendim şafağın

Onurun, inancın yumağı oldum

Terk etmedim yolunu aydınlığın

Öldüm öldüm, dirildim

Haberin var mı? 

17/6/2005', 'Deli rüzgârlar uçuşuyor dışarıda Ormanların çamları devriliyor bir bir Kulağa ışık gelmiyor, göze ses  Cam duvarları paran parça evimin Yata...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/haberin-var-mi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-l-tif-karagoz-5raq9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ailemizin direği

Sırtındadır onun hayat.

Huzur saçar yüreği

Güçlükleri aşar kat kat! 

Teriyle sular toprağı

Asla incitmez yaprağı

Saçında titrer kırağı

Güçlükleri aşar kat kat! 

Ne mutluyuz ocağında

Sevgi dolu kucağında

Şevkat yüklü bucağında

Güçlükleri aşar kat kat! 

Özveriyle parlar gözü

Güneş gibi güler yüzü

Ne kutsaldır baba sözü

Güçlükleri aşar kat kat! 

Haziran – 2005

                       Lâtif KARAGÖZ

                                ÇORLU', 'Ailemizin direği Sırtındadır onun hayat. Huzur saçar yüreği Güçlükleri aşar kat kat!  Teriyle sular toprağı Asla incitmez yaprağı Saçında ti...', ARRAY['Türk Edebiyatı','Şiir','Lâtif Karagöz']::text[], 8.5, '{"poet":"Lâtif Karagöz","poet_slug":"l-tif-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/babam-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-volkan-yurt-hjwc9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek Sevgilim

Köpek Öldürüren ile

Güneşden Önce Gelmek

Kabataş Parkı''na

Saatlerce Yürümek

Yağmura Aldırmaksızın

Ve Konuşmak

Döru Duvar Arasında

Ağını Örmeye Çalışan

Örümcek İle

Sevmek Beklemek Sevgilim

İşçilerin Elleri Arasında

Gelecek Özgürlüğü', 'Sevmek Sevgilim Köpek Öldürüren ile Güneşden Önce Gelmek Kabataş Parkı''na Saatlerce Yürümek Yağmura Aldırmaksızın Ve Konuşmak Döru Duvar Ara...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yurt']::text[], 8.5, '{"poet":"Volkan Yurt","poet_slug":"volkan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmek-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Kız', 'kara-kiz-volkan-yurt-nfufg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara Kız

Sanma; 

Bahçemin içindeki

Gülümün Üstüne Konan

Kelebek Kadar Güzelsin

Ve Sanma 

Yağan Kar Altında

Soğuğu Kendine Elbise Yapmış

Sokak Çocuğu Kadar Dürüst

Bu Yüzden

Ada Vapurundan Denize Düşen

Teybime

Üzüldüğüm Kadar

Üzülmedim Gidişine', 'Kara Kız Sanma;  Bahçemin içindeki Gülümün Üstüne Konan Kelebek Kadar Güzelsin Ve Sanma  Yağan Kar Altında Soğuğu Kendine Elbise Yapmış Soka...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yurt']::text[], 8.5, '{"poet":"Volkan Yurt","poet_slug":"volkan-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kara-kiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensinya', 'sensinya-doner-ozeke-64bvu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömerin kalbinde sevgiler açan 

Ömrünün deminde mutluluk saçan 

Sevginle aşkınla kalbine akan

Seni seviyorum aşkım sensinya 



Yılmadım aradım her dem ben seni 

Bu can sana feda sende sev beni 

Ömrüm var oldukça severim seni 

Seni seviyorum aşkım sensinya 

Sensiz nefes almak haramdır bana 

Bütün goncaları getirsem sana 

Dünyanın tadına sensiz ben asla 

Seni seviyorum aşkım sensinya

Ömer adım Yılmaz benim soyadım 

Kalbime işledim doyulmaz tadın 

Seninle ben doğdum senle yaşadım 

Seni seviyorum aşkım sensinya 



                    DÖNER TEMÜR 

                        18.05.2005

                           ANKARA', 'Ömerin kalbinde sevgiler açan  Ömrünün deminde mutluluk saçan  Sevginle aşkınla kalbine akan Seni seviyorum aşkım sensinya  Yılmadım aradım ...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensinya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde O Eski Evler', 'nerde-o-eski-evler-ozkan-gonlum-qxsn7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'NERDE  O  ESKİ  EVLER

			Apartmanlar yapıldı komşuluk bozuldu

			Mahalleler site – site dizildi

			Silindi insanlık, dostluk adına her şey

Yalnızlığın en karası

			Alnımıza yazıldı.

			Nerde o eski evler

			Eski komşular nerde

			Bir gariplik sarmış her yanı 

			Mahallelerde.

			Körü körüne bir koşturmaca

			Sürüp gidiyor yaşamda

			Aynı apartmanda olanlar tanımıyor 

			Birbirlerini bile.

			Unutuldu merhabalar, günaydınlar

Hal hatır sormak nafile

Ancak bayramdan bayrama bazen

Hoş geldin deniyor ve de güle – güle.

İlgisiz, komşular birbiriyle

			Ne gelen belli ne giden.

			Herkes bürünmüş bir sırra

Habersizler doğandan, ölenden

İyi günde kötü günde de olsa

Hastalıkta, sağlıkta da olsa

Komşu komşuya muhtaç ama

Yaşam kaygısı perdelemiş gözlerini

Kimse değil birbirinin farkında

Dönüyor herkes kaderince 

Feleğin bir çarkında.', 'NERDE  O  ESKİ  EVLER 			Apartmanlar yapıldı komşuluk bozuldu 			Mahalleler site – site dizildi 			Silindi insanlık, dostluk adına her şey Y...', ARRAY['Türk Edebiyatı','Şiir','Özkan Gönlüm']::text[], 8.5, '{"poet":"Özkan Gönlüm","poet_slug":"ozkan-gonlum","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/nerde-o-eski-evler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbulda Sabah', 'i-stanbulda-sabah-i-smail-avci-981e4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabahı kucaklıyor İstanbul...

Vapur seslerini martı cıvıltılarıyla notalaştırıyor,

Boğazla diz dize çayını yudumluyor...

İstanbul, canım İstanbul! 

Bunu hep yapıyor.

Üsküdar sahilinin kapılarını çalıyor,

Marmaranın delikanlı sularıyla...

Ve bir simitçi,

Simitinin taze ve çıtır olduğunu iddia ediyor,

İstanbul adı altında...

Akaretler durağı,saat 7:40

Bir hukuk öğrencisi,

110 Taksim-Kadıköy otobüsünü bekliyor,

İstanbulun kaplumbağa trafiğine inat...

İstanbul kucaklıyor sabahı...

İş başı yapıyor bir boyacıyla,

Ve bir dükkanın darabası oluyor

Gürültüyle açılan...

Sonra yoruluyor,

Beşiktaş iskelesinde ayaklarını suyla boyuyor

Elinde mis kokulu simitiyle...

İstanbul sabahı kucaklıyor...

Çamlıcanın geçmesine izin verdiği

Güneş ışığıyla...

Ürküyor önce Eminönüne toplanan,

Vapurların kustuğu insanlardan.

Sonra rahatlıyor 15 dakikalık,

Sonra yine...

Sabah İstanbulu kucaklıyor sevgiyle...', 'Sabahı kucaklıyor İstanbul... Vapur seslerini martı cıvıltılarıyla notalaştırıyor, Boğazla diz dize çayını yudumluyor... İstanbul, canım İst...', ARRAY['Türk Edebiyatı','Şiir','İsmail Avcı']::text[], 8.5, '{"poet":"İsmail Avcı","poet_slug":"i-smail-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istanbulda-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöz Avuçlarımdaki Büyüyü', 'coz-avuclarimdaki-buyuyu-selahattin-yetgin-q5yxr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her gece, göğsümün duvarlarına efsane gülüşlerinle oturur, sallarsın aşk salıncağında 

Her gece, mavi denizlerimden sular taşırsın sen, yakamoz öpüşlerinle gönül yapıma 

Her gece, rüzgarlara direnen mum ışığıma bir gölge,bir bilge olursun perde yüreğinle 

Bakışlarınla hüzün bir söğüt gölgesine serer çarşafını ve sen sokulursun ruhuma, koynuma 

Ben seni düşündükçe kuyulardan tohumlar çıkarır, ekerim aşk çiçeklerini gökyüzü tarlalarına.

Adına söylenmiş, ruhuna bestelenmiş bütün şarkılardan bir sevgi kulesi kurarak seni gözlemeye başladım sevda kalemizde. Kımız acıların kadehleri şerefine kalkıyor, yaman yalnızlığıma kılıç sallıyorum seni düşündükçe. Elveda dediğim tüm sevdaları tıkarak zindanlarına gözyaşı mendilimi yıkıyorum  pınar gözlerinde.

Ne zaman dilinden bir sözcük düşse seninle tamlanıyorum. Rüzgarın getirdiği bir çiçek tohumu oluyorsun bende. Ne zaman dilinden düşen bir harf olsan yüreğini yazıyor kalemim, buzlar çözülüyor sarkıtlarımdan. Ne zaman incecik dallarına tutunsam kanıyor zaman kapsülleri ve ıslanıyorum şiirlerinden. Yüzümü mavi gülüşlerin yalıyor, seneler asırlar ekleniyor ömrüme, sen ne zaman dudaklarıma eğilsen.

Bakışlarının ödüllerini kaybettiğim anlarda içimde yüzlerce çocuk ağlar ve eksik kalmış bir roman gibi köşelere atılırım. Sesinin kristal zerreciklerini hissetmediğim an, ele avuca sığmaz bir pervane böceği olur, yoksul evlerin karanlıklarında saklanırım. Sevinçlerim eskirse yüreğinde, karartma gecelerine döner odam, sarmaşıklar ağar yorgun penceremden, menekşelerin rengi silinir yüreğimden.

Sınırlarımın seni çevreleyen yaklaşımlarında duruşlarımın ve susuşlarımın kapsülleri patlamakta günlerdir. Bu deniz ülkesinde dalgaları çağırarak  çarpamazsın şiirlerime. Beni vuracaksa gözlerin vursun. Ben senin için karanlık bir gök altında çiçeklerle bezeli bir dünyayı yaşıyorum. Bir yaz akşamıdır kadehimizden dökülen sözcük damlalarımız ve ıslatır ellerimizi tutkumuz. Pembe yüzünde öfken yeşerirken bulutlarını kovarım göz yaşlarımla tapılası yüreğinden. Göğüm senin, gülüşlerin benim olur birden öpmelere doyamam ateş topu dudaklarından.

Her gece, göğsümün duvarlarına efsane gülüşlerinle oturur, sallarsın aşk salıncağında. Her gece, mavi denizlerimden sular taşırsın sen, yakamoz öpüşlerinle gönül yapıma. Her gece, rüzgarlara direnen mum ışığıma bir gölge,bir bilge olursun perde yüreğinle. Bakışlarınla hüzün bir söğüt gölgesine serer çarşafını ve sen sokulursun ruhuma, koynuma. Ben seni düşündükçe kuyulardan tohumlar çıkarır, ekerim aşk çiçeklerini gökyüzü tarlalarına.

Yüreğimizdeki renk cümbüşlerine binlerce çocuk salarak denizleri ve kuşları çiziyoruz parklarımızın duvarlarına. Yaşamıyoruz diye bizi yok sayanlar, sevişmiyoruz diye yüzümüze kapanan kapıları direnç yumruklarımızla dövmedik mi,  kilitlerini sevgi gürzümüzle, öpüşlerimizle kırmadık mı? . Biz sarıldıkça menekşeler büyür kuytularda ve her gece bir çiçeğin tohumu oluruz. Gözlerimizdeki kör kuyular ve yüreğimizdeki sularla göl olur, ırmaklara dökülür, denizlere dolarız bu aşk atlasında.

Unutulmaz sevinçlerin coşkularında yeryüzünün tüm mavilerini kucağına taşırdım senin. Seni sevdikçe dalgalarına koyardı başını ayrılıklar. Seni soluklamak için yeniden körükledim şu yorgun yüreğimi ve göğsündeki koruk üzümlerle yürüyorum sevgi bağlarına. Al beni kuytu derelerine, çiğne bedenimi yeni sevinçlerle.Uyansın yeryüzünün tüm böcekleri, gözlerindeki yağmur göllerinde birlikte çekelim bu aşkın küreklerini

Sensiz susuşlarımın akrep duruşlarında yelkovan dönüşler yaparım gecelerimin hasret saatlerinde. Omzundaki yüklere bir sırt verebilsem, terini silebilsem diyorum dinginliği aradığın anlarda. Öpüp öpüp dudaklarıma sürüyorum pamuk ellerini, koklamalara doyamadığım saçlarını, sarmalara sevdalandığım bedenini kucaklamak ister gibi.

Koparılmış nice takvim yapraklarına bir daha bakmak istemez insan. Yarınların tespihleri çekilirken ömür koltuğunda bir daha gelmez dünkü nisan. Avuçlarımızdaki büyü, yüreğimizdeki kor alev ve düşlerimizdeki mevsimlere koşuyorum seni her özlediğimde. Ömrümün takvimleri seninle tamlanıyor, ruhumun ateşleri aşkınla harlanıyor çünkü bir tanem.', 'Her gece, göğsümün duvarlarına efsane gülüşlerinle oturur, sallarsın aşk salıncağında  Her gece, mavi denizlerimden sular taşırsın sen, yaka...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/coz-avuclarimdaki-buyuyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülüm Olmalı', 'bir-gulum-olmali-i-smail-avci-yzfvk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gülüm olmalı benim,

Sadece ben koklamalıyım.

Bir gülüm olmalı,

Bülbülle dilleşmemiş seher vakitlerinde.

Bir gülüm olmalı,

Rengi farketmez adı gül olmalı.

Benim bahçemde açmalı,

Dört mevsime inat

Hiç solmamalı yüreğimde...

Bir gülüm olmalı,

Ben sulamalıyım onu her sabah.

Bir gül,sadece bir gül,

Benim olmalı ah be ah! 

Tüm dertlerimi eriten,

Bir gülüm olmalı,

Baktıkça ferahlatan,gülümseten beni...

Bir gülüm olmalı,

Ben olmalıyım sadece dikeni,

Uzanan ellere inat...', 'Bir gülüm olmalı benim, Sadece ben koklamalıyım. Bir gülüm olmalı, Bülbülle dilleşmemiş seher vakitlerinde. Bir gülüm olmalı, Rengi farketme...', ARRAY['Türk Edebiyatı','Şiir','İsmail Avcı']::text[], 8.5, '{"poet":"İsmail Avcı","poet_slug":"i-smail-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-gulum-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan', 'kan-mehmet-dag-78hjn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimden

Kan damlar damla damla 

Uyuduğum yatağa

Bir sese bağırarak uyanırım uykumdan

Sesime kanlar damlar

Açarım gözlerimi 

Kan çanağı gözlerim

Hangi yanıma baksam 

Her yanımdan kan akar

Gece düğüm düğüm, sırlarla saklı

Elleri kanlı “ Şafağın! 

Gören var devrilen, fidanları

Kan serpildi güneşe

Hava ağlamaklı.

Derelerden kan aktı denizlere 

Dağlara kırmızı karlar yağdı.

Kara bağladı analar

Bütün ağıtlardan kan buharlanır.

Ter, kan içinde halkım

Kan yutar, kan solur, kanla uyur

Kaleminden kan damlar yargıçların

Kırmızıya boyanır tüm şiirler.

Beyaz kâğıtlar üzerinde 

Kanlı desenler olur.

Hala bunca akan kanı 

İnkârdan, görmemezlikten gelir KANSIZLAR 

Yinede güllük, gülistanlık 

Bir ülkeden söz eder bu YOBAZLAR 

 18-6/2005', 'Yüreğimden Kan damlar damla damla  Uyuduğum yatağa Bir sese bağırarak uyanırım uykumdan Sesime kanlar damlar Açarım gözlerimi  Kan çanağı gö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk aşkım', 'i-lk-askim-ramazan-kayak-fvwrb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk aşkım

Dağlara yağan kar gibiydi

Büyük ve ulaşılmaz

Nisanda yağmur gibi

Coşkun sellere kapıldı

Çiy gibi düşmüştü

Gül yaprağına

Ulaşamadım

Güneş doğarken eridi

İlk aşkım

Uzayıp giden yollar gibiydi

Hiç tükenmeyen

Bazen bahardı gönlümde

Çiçek çiçek açan

Bazen sinsi bir yara

Kanardı yüreğimde ara sıra

İlk aşkım

Aldırmadan geçen yıllara

Hala dolanır yüreğimde

Zamansız zamana inat

Zaman zaman.', 'İlk aşkım Dağlara yağan kar gibiydi Büyük ve ulaşılmaz Nisanda yağmur gibi Coşkun sellere kapıldı Çiy gibi düşmüştü Gül yaprağına Ulaşamadım...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ilk-askim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elde Var, Elde Olmayanlar...', 'elde-var-elde-olmayanlar-tulay-sustam-p9t8o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mangalsız yürekler de...

kükürt kokardı_______ aldırma (z)  dım...

aşk teğet geçerdi...

sol yanımdan________ aldırma (z)  dım...

gündüzleri güneşi çalarlardı...

gönül penceremden___ aldırma (z)  dım...

ne zaman ki; 

hayat can özümü aldı benden

o zaman -kafa tutmayı- da öğrendim

ipini çektim hayatın

olduğu yerde dönerken, birden bire durdu...

şimdiler de hayatımda...

elde var, elde olmayanlar! ...', 'mangalsız yürekler de... kükürt kokardı_______ aldırma (z)  dım... aşk teğet geçerdi... sol yanımdan________ aldırma (z)  dım... gündüzleri ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/elde-var-elde-olmayanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuklunum', 'tutuklunum-nilufer-aslantas-ov9fx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnız olan senmisin sadece? 

Ya, seninleyken yaşanan yalnızlık...? 

Çok yakınsın bana,

İçimdeki nefesimsin...

Bir o kadarda uzak,

Gökyüzündeki erişilmez yıldız...

Peki.... bu adilmi? 

Seni bilmem ama,

Tutuldum sana,

Tutkum oldun...

Tutuklunum....', 'Yalnız olan senmisin sadece?  Ya, seninleyken yaşanan yalnızlık...?  Çok yakınsın bana, İçimdeki nefesimsin... Bir o kadarda uzak, Gökyüzünd...', ARRAY['Türk Edebiyatı','Şiir','Nilüfer Aslantaş']::text[], 8.5, '{"poet":"Nilüfer Aslantaş","poet_slug":"nilufer-aslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tutuklunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOLLAR şematik', 'yollar-sematik-hayri-arikan-serdaroglu-j6n41', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel.................muhabbetin................çağı................başkadır.

Muhabbetin........demi..........................yolu................meşkedir.

Çağı...................yolu.........................devranıda...........aşkadır.         .

Başkadır............meşkedir..................aşkadır.............yollar

 Hayri Arıkan (Serdaroğlu)', 'Güzel.................muhabbetin................çağı................başkadır. Muhabbetin........demi..........................yolu.............', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yollar-sematik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affetmem', 'affetmem-gulseren-onay-25mhw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne çingenenin 

Falı,

Ne büyüsü

Hacının,hocanın

Yetmez affetmeme seni...

Kaç kez 

Eyüpsultana gitsen

Adaklar adasan,

Ne kadar çok

Mum da yaksan

Ayazmada...

Sevmeyi bilmiyorsan

Asla affetmem...

GÜLSEREN ONAY

10/06/2005/ANTALYA', 'Ne çingenenin  Falı, Ne büyüsü Hacının,hocanın Yetmez affetmeme seni... Kaç kez  Eyüpsultana gitsen Adaklar adasan, Ne kadar çok Mum da yaks...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/affetmem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okkalı,Çift Şerefeli,Şekerli,Soğuk Türk Kahvesi''nin Öyküsü', 'okkali-cift-serefeli-sekerli-soguk-turk-kahvesi-nin-oykusu-ali-osman-yilmaz-bng4a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'OKKALI,ÇİFT ŞEREFELİ,ŞEKERLİ,SOĞUK TÜRK KAHVESİ

2.dünya savaşı sona ermiş,Avrupa yeniden şekillenmektedir.Bir tarafta ABD ve  müttefikleri,diğer yanda Sovyetler Avrupayı parsellemektedirler.Osmanlı imparatorluğunun çökmesinden sonra,Atatürk tarafından temelleri atılan Türkiye cumhuriyeti,dünya savaşının sıkıntılarını üzerinden atmaya çalışmaktadır.Bu dönemde çok partili demokrasiye geçen Türkiye’nin,terk ettiği topraklardaki Türk soydaşları,yabancı ülkelerin dinsel,ekonomik ve siyasal baskılarından kaçmakta,göç ederek Ana yurtlarına gelmeye çalışmaktadırlar.

Üç dört kuşaktır akrabaları ana yurda göçmekte olan Hüseyin ağanında artık ana yurda göç etmek vakti gelmiş,Komünist blok’a dahil olan Bulgaristan’dan Ana yurda doğru hareket etmiştir.Köyünde tüm kardeşleri ve akrabaları  komünist sistemin izin verdiği birkaç yorgan ve giysisini bohçaladığı gibi pasaportlarını alıp 1950 yılının güz aylarında yola koyulmuşlardır.

Yıllar öncesinden anayurda göç eden akrabalarını bulacaklar,onların yanına yerleşerek yeni bir yaşama başlamayı düşlemektedir.Hüseyin Ağanın 30 lu yıllarda bir ablası,40 lı yıllarda en büyük ağabeyi ana yurda göçmüştür.Şimdi umutla küçük ağabeyi ile birlikte bir çocuğunu da katırının üstüne koyup  sınıra doğru yol almaktadır.Ne var ki onu  uğurlayanların,Hüseyin ağanın ana yurda ulaşabileceğine inançları yoktur.Çünkü Hüseyin ağa çok hasta durumdadır.

Yalnız üst baş ve birkaç küçük eşyayla birlikte Edirne’den ana yurda girmiş ve gümrükte küçük ağabeyi de ondan önce geçtiği için hangi soyadını aldığını bilmemekte,ancak gelen haberlerden kulağında kaldığı kadarı ile büyük ağabeyi Cafer’in Yılmaz soyadını  isteyecektir.

Gümrükten geçerken kendilerini Konya taraflarında iskan edileceği ve kendilerine toprak verileceği söylenmiş, ancak karısı Şevkiye,hasta kocasıyla yapayalnız bir şekilde o kadar uzaklara gidemeyeceklerini düşündüğü için iskan edilmeyi kabul etmezler ve doğruca İzmit iline doğru yola koyulurlar.Kendilerine verilen yiyeceklerle birlikte iki gün içinde İzmit’e varırlar ve ağabeyleri Cafer ‘in yanına,İzmit’in Yuvacık köyüne doğru yol alırlar.

Neden bu köye gelirler oda garip bir tesadüftür.En büyük ablaları,30 lu yıllarda kocası ile birlikte ana yurda göçmüş ve daha önce işledikleri bir cinayet nedeniyle kaçarak anayurda gelen akrabalarının yanına gelmişlerdir.O nedenle büyük ağabeyleri 40 lı yıllarda ablasının ve eniştesinin bulunduğu bu köye gelmiş ve kardeşlerine arkasından bu köye gelmelerini tembihlemiş dir.Ne de olsa memlekette tütün işlemede usta oldukları ve bu köyde de çok iyi tütün yetiştirildiği için iş bulmaları,tütün ekip yeni bir yaşama başlamaları daha kolay olacaktır.Tütünün yanında dağ eteğinde olan bu köyde orman ürünü ve hayvancılıkta yapabileceklerdir.

Yuvacık köyüne gelen Hüseyin ağa,Murat dayının eski bir ahırdan bozma penceresi bile olmayan evine yerleşir. Hasta olduğundan tütün ekemeyecek olan Hüseyin ağaya yaklaşan ramazan ayında köyün davul çalma işini verirler. Geldiği önceki vatanında varlıklı bir kimse olan Hüseyin ağa ramazan gecelerinde bu davulu nasıl çalacağını Murat dayıya sorar.Çünkü utanmaktadır,bir dilenci gibi davul çalarak geçimini temin etmek ona ağır gelmektedir.Murat dayı köy  kahvesinde durumu köylülere anlatır ve köy gençlerinin davulu çalmasını ve toplanan paraların Hüseyin ağaya verilmesini kararlaştırırlar.Ramazan da biter ve karnı burnunda karısı ile nasıl geçineceğini düşünmektedir.O sırada köylülerden birisi köyde bulunan iki kahveden biri olan kendi kahvesini işletmesini teklif eder.Başka  çaresi olmayan Hüseyin Ağa bu teklifi hemen kabul eder.Karısı karnı burnunda tütüne çapaya gider,pastal zamanı pastalda yapacaklardır.Kahveden de biraz gelir gelirse yaşamlarını rahatça sürdürebileceklerdir.

Bu şartlarda kahveyi çalıştırmaya başlar.Karısı bir süre sonra doğum yapar,ancak penceresiz evde,yeterli beslenme olanağı bulamayan Dayıları Deli Bilal’ın adını koydukları çocuklarını on beş günlükken kaybederler.

Bu arada kahvenin sahibi dağdan odun getirmekte ve kahveye  odun bırakmaktadır.Odunları kahveye bıraktıktan sonra köyün diğer kahvesine gider ve kahvesini çayını orada içer.Bu  durum Hüseyin ağanın zoruna gider.Günlerden birgün kahvenin sahibi yine odun getirmiş,odunları beraber kahvenin arka tarafına sıraladıktan sonra,kahve sahibi tam diğer kahveye gidecekken Hüseyin Ağa sorar.İsmail efendi,neden benim çayımı,kahvemi içmezde öteki kahveye gidersin diye.İsmail efendi  hiç tereddüt etmeden peki,bu kez  senin kahveni içeyim bari der ve  içeri girerler.

Hüseyin ağa sevinçle ocağa koşturur ve ateşi canlandırmak için birkaç kömür çubuğunu ateşe  atar.Yeterli  hazırlığı yaptıktan sonra İsmail efendinin yanına gelerek sorar.İsmail efendi çay mı? kahve mi içersiniz diye? 

İsmail efendi; ben kahve içerim ama bilmem sen yapabilir misin diye istihza ile sorar.Hüseyin ağa; yaparım İsmail efendi der.İsmail efendi; eğer istediğim kahveyi yapamazsan bir daha senin kahvene gelmem der.Hele bir söyleyiver; kahveni nasıl içersin? Diye sorar.

İsmail Efendi ben kahveyi Okkalı,Şekerli  Çift şerefeli ve  soğuk içerim diyerek cevap verir.Hemen ocağa doğru yönelir ve koştururcasına kahveyi yapmaya koyulur.Biraz sonra elinde okkalı fincanda yaptığı kahvenin dumanı tüte tüte İsmail efendinin yanına gelir.Buyrun İsmail efendi kahveniz der.İsmail efendi önce kahve fincanına şöyle  bakar,bıyık altından gülümseyerek,ilk elde  güzel görünüyor diyerek kahveden  bir yudum alır,ağzına aldığı bir yudum kahveyi ağız içinde şöyle bir dolandırarak yutar ve eh Hüseyin ağa der.Sen benim gibi köyün en tiryaki adamının kahvesini  bile böyle mükemmel yaptıktan sonra tüm köylü senin kahvene gelecektir diye kahvesini keyifle içmeye devam eder.

Hüseyin ağa şöyle bir omuzlarını kaldırır ve dik bir şekilde gururla  ocağına doğru  gider.O günden sonra köyün en tiryakileri Hüseyin ağanın müşterisi olmuşlardır.

Köyün bir başka tiryakisi de Hüseyin ağaya dadanmıştır.Rüstem ağa köyün kaçakçılığı ile ünlü bir kişisidir.Köyün çay kahve ihtiyacı ile sarma tütün kağıdını ve başkaca ihtiyaçlarını kaçak olarak köye getirmektedir.İşte bu Rüstem ağa kahvenin üstüne su içtiği için tiryakiliği makbul tutulmaz kendisiyle köyün diğer insanları alay edermiş.Rüstem ağada onlara,kahveden anlamasam,kahvenin en iyisini size nasıl getiririm,ben olmasam nohut kahvesine talim edeceksiniz diye  karşılık verirmiş.İşte bu Rüstem ağanın kahve sonrasında içtiği su nedeniyle bir gün Hüseyin ağa Rüstem ağanın kahvesine bir iki adet arpa tanesi  atarak pişirmiş,okkalı,çift şerefeli,şekerli ve soğuk kahvesini yapmış ve Rüstem Ağaya götürmüş.Ama oda ne? kahvesini içtikten sonra Rüstem Ağa ha bire su istemektedir.Bu durum göçmen Hüseyin ağanın dikkatini çekmiş ve sormuş.Bre Rüstem ağa,kahvenin üstüne su içmeni anlıyorduk ama bu da ne? ha bire su istersin,neden diye sorunca,Oğlum göçmen Hüseyin,Kahveyi çok güzel yaparsında içine arpayı fazla kaçırmışsın,o nedenle arpa çok susattı beni,deyince  Rüstem ağanın gerçekten has bir kahve tiryakisi olduğu  böylece tescil edilmiş.

Bu olaydan sonra yeniden göç etmek zorunda kalırlar.Beş  altı ay sonra 1951 yazında Bursa’ya göç ederler. Bursa’da tütün işleme fabrikaları çoktur ve tütün ustası göçmenler aranmaktadır.Kendilerinden  önce Bursa’ya giden akrabalarının iş çağrısı üzerine kalan yaşamlarını Bursa’da devam ettirmek üzere İzmit’in Yuvacık köyünden Bursa’ya yeniden göç ederler.

Hüseyin ağanın,Köyün en tiryakisi İsmail efendiye yaptığı o kahve ile,Köyün kaçakçısı Rüstem Ağanın arpa hikayesi,Yuvacık köyünde hala anlatılmaktadır.

O zamanlar kahve Ülkemize Brezilya’dan değil yemen civarından gelmektedir.Bilmem şimdiki kahve tiryakilerinde böyle  özel damak zevkleri varmıdır? 

Rahmetli Babamın Anısına saygılarımla.', 'OKKALI,ÇİFT ŞEREFELİ,ŞEKERLİ,SOĞUK TÜRK KAHVESİ 2.dünya savaşı sona ermiş,Avrupa yeniden şekillenmektedir.Bir tarafta ABD ve  müttefikleri,d...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/okkali-cift-serefeli-sekerli-soguk-turk-kahvesi-nin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sirkeci Garında', 'sirkeci-garinda-gokhan-tan-2iysf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Katarlar durdu, pistonlar sustu sirkeci garında

Hava soğuk, peron dolu, gün batmak üzere

Anlaşılan vakti geldi ayrılığın ve bir çok münasebetin

Giden ve dönme ihtimali olan başka hiçbir şey, öyle yalnız hissettirmez insana kendini

Endişe ve yoldaşı tedirginlik şimdilik duruma hakim

Az ileride Bosfor ekspres belirdi, çelik yığın halinde

Ki,  ben ilk kez çeliğin bu kadar soğuk ve sert olduğunu hissettim

Üç beş dakika durdu garda Bosfor eksres

Ardından rayları bileyen çeliğin gıcırtısıyla çıktı yola

İlk durak Kapıkule, Sofya ardından Belgrat, Kişinev

Tam üç günü ağırlıyacak kompartımanlarında Bosfor ekspres

Yani bir kıtada batan gün bir diğerine yol almakta

Sirkecinin denize bakan kapısından şehre karışıyorum

Hava soğuk, peron dolu, gün batmak üzere...', 'Katarlar durdu, pistonlar sustu sirkeci garında Hava soğuk, peron dolu, gün batmak üzere Anlaşılan vakti geldi ayrılığın ve bir çok münasebe...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Tan']::text[], 8.5, '{"poet":"Gökhan Tan","poet_slug":"gokhan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sirkeci-garinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-yusuf-tahir-akkose-wg5wv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'beni kucağına al

dizlerinde salla

ayak uçlarına kuş tüyü yastık koy

aman başım acımasın

uyut beni anne

usulca beşiğime götür

üstümü örtmeyi unutma

emzir beni kaynayan memelerinden

sütünü esirgeme

çok acıktım anne

parmak uçlarınla dudaklarıma vur

gülücükler atayım meleklere ve sana

gözlerin ışıldasın

güller açsın gamzelerinde

sev beni anne

sar sarmala

tedirgin ol hastalığımdan

dualar oku

hatta nazar boncuğu tak yakama

koru beni anne

agucuklar söyle

maniler söyle

ninniler söyle

hayaller kur geleceğime dair

benim oğlum beni bakar de

umut ver kendine anne

beni kucağına al

hastayım

çaresizim

ölüm geliyor aklıma

neredesin nerelerdesin

kurtarsana beni anne

(ALEVDEN OYUNCAKLAR) 

MART 2003', 'beni kucağına al dizlerinde salla ayak uçlarına kuş tüyü yastık koy aman başım acımasın uyut beni anne usulca beşiğime götür üstümü örtmeyi ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Tahir Akköse']::text[], 8.5, '{"poet":"Yusuf Tahir Akköse","poet_slug":"yusuf-tahir-akkose","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/anneme-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ak''tan Kara''ya', 'ak-tan-kara-ya-kemal-guzel-z0ew7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varmı ki? 

 düşlerinde bütün renleri böylesine

barındıran bir başkası daha? 

Varmı ki? 

acıyı böylesine mutlu olma hevesiyle

yaşıyan bir başkası daha? 

Varmı ki? 

saldırmamak için ağzına böylesine 

gem vuran bir başkası daha? 

Varmı ki? 

içindeki isyan ateşini kimse yanmasın diye

dışa vurmayan bir başkası haha? 

Varmı ki? 

bütün renkleri böylesine seven

bir başkası daha? 

          AK''TAN TUN VARANA DEK KARA''YA

varmı ki?', 'Varmı ki?   düşlerinde bütün renleri böylesine barındıran bir başkası daha?  Varmı ki?  acıyı böylesine mutlu olma hevesiyle yaşıyan bir baş...', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ak-tan-kara-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman?', 'ne-zaman-kemal-guzel-gsp3d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'memleketimizde aşağı yukarı var

70 milyon insan.

evet; bunlardan kaçı insan? 

ama İNSAN.

halen analar ağlıyorsa

halen hastalar ilaç bulamıyorsa

halen işsiz had safhadaysa

halen potansiyel suçluluk varsa

halen sebepsiz tutuklama varsa

halen fukara ekmekten yoksunsa

halen mutsuz insan yüzde yüzse

halen baba çocuğuna oyuncak alamıyorsa

halen dur durak bilmeyen kapkaç,

soygun,dolandırıcılık,sahtekarlık,

yalan-dolan ve hala sağlıksız gıda diz boyuysa

bunun üstüne bunların hepsini göremiyorsak,

bunlardan kaçı İNSAN...? 

   ne zaman olacaz insan.

ne zaman?', 'memleketimizde aşağı yukarı var 70 milyon insan. evet; bunlardan kaçı insan?  ama İNSAN. halen analar ağlıyorsa halen hastalar ilaç bulamıyo...', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ne-zaman-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızdırıp Durma', 'kizdirip-durma-caner-kuru-xrypb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hakim olmam çok zor sinirlerime

Bak çeker giderim kızdırıp durma.

Biraz renk, hayat ver şiirlerime,

Bana hep hasreti yazdırıp durma.

İçime işledin nakışlarını,

Kalbime ok ettin bakışlarını

Başka yöne kaydır akışlarını

Yok yere gönlümü azdırıp durma.

Sensizliği tatmak, senle kaplıyken

Gözlerin kalbime böyle saplıyken

Zaten her gittiği yol girdaplıyken

Gönlüme labirent çizdirip durma.

Ben yılmam kaderin engellerinden

Vazgeçmez bu kalbim  emellerinden

Bir deniz oluştu hayallerinden

Hep aynı denizde yüzdürüp durma.', 'Hakim olmam çok zor sinirlerime Bak çeker giderim kızdırıp durma. Biraz renk, hayat ver şiirlerime, Bana hep hasreti yazdırıp durma. İçime i...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kizdirip-durma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuzüçüncü Günün Şiiri', 'otuzucuncu-gunun-siiri-hatem-kardesler-07tvc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bekliyorum sevdiğim…Bekliyorum.

Hergün batımı seni bana biraz daha yaklaştırıyor,

Hergün güneş doğarken ışıklarıyla,

Hasret zincirinden bir halka koparıyor…

Artık eskisi gibi değilim…

Hasret şarkıları beni etkilemiyor artık…

Dudaklarıma da bir oynak hava koydum ki sorma

Kalemime de söz verdim; 

“Hasret” sözcüğüne yer yok artık dizelerimde… 

İnan sevdiceğim inan,

Rakılı kadehlerle sensizliğe isyan etmeyeceğim artık,

Sular gibi akacak,çocuklar gibi koşacağım…

Çünkü otuzüç günün bitiminde,

Sana kavuşacağım…

		         (Hasret İçimde Bir Dağ)  Kitabından', 'Bekliyorum sevdiğim…Bekliyorum. Hergün batımı seni bana biraz daha yaklaştırıyor, Hergün güneş doğarken ışıklarıyla, Hasret zincirinden bir ...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/otuzucuncu-gunun-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz', 'olmaz-hatem-kardesler-vevk2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İbrahim BORUKLU''ya

Olmaz…

Olmaz ve buğday sarısı saçlarına,

Kurban olduğum…

Bitmez ya,

Bu hasretin bittiğini düşün bir,

Mutluluk kolay mı? ...

Kolay mı iki odalı küçük bir ev yapmak? ...

Olmaz…

Olmaz be çimen yeşili gözlerine 

Kurban olduğum…

Bitmez ya,

Bu gurbetin bittiğini düşün bir,

Çalışır kazanırsın diyeceksin,

Nerede iş,nerede iş verecek adam? ...

Yok gülüm yok…

Lafla peynir gemisi yürümüyor…

Olmaz…

Olmaz be sevgisine,inancına,

Allah’ına kurban olduğum…

her şeye sıfırdan başlamak kolay mı? ...

Kolay mı iki odalı küçük bir ev yapmak…

		         (Hasret İçimde Bir Dağ)   Kitabından', 'İbrahim BORUKLU''ya Olmaz… Olmaz ve buğday sarısı saçlarına, Kurban olduğum… Bitmez ya, Bu hasretin bittiğini düşün bir, Mutluluk kolay mı? ....', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olmaz-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilemiz Bizim...', 'cilemiz-bizim-zulfikar-yapar-kaleli-p66qo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Anlatmak imkansız getirip dile

Ebu Cehilerden gördüğümüzü

Görmedik ehli salipten bile

Ebu Cehilerden gördüğümüzü

Bin dört yüz yıl önce ne ise cehil

Bugün de öyledir değildir ehil

Görmedi  Bilal''in çektiği dahil

Ebu Cehilerden gördüğümüzü

Ömrün baharında çıkmadan yaza

Onlar ize düşkün bunlarsa söze

Allah''ın aşkına bir sorun bize

Ebu Cehilerden gördüğümüzü

Bilal''in gençliği zulümle öçtü

En son Nebi bile Yesrib''e göçtü

Sorun zindanlara gençliğim geçti

Ebu Cehilerden gördüğümüzü

                          

Çile verdi suçun şudur demedi! 

Devranını Karun bile sürmedi

İnan cahiliye devri görmedi

Ebu Cehilerden gördüğümüzü

Bir önceki Karun doymaz haramdan

Şimdiki Firavun alt kalmaz ondan

Kaleli duyulsun anlat sıradan

Ebu Cehilerden gördüğümüzü

                                                     1987', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Anlatmak imkansız getirip dile Ebu Cehilerden gördüğümüzü Görmedik ehli salipten bile Ebu...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cilemiz-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimez Beyitler 17', 'eskimez-beyitler-17-huseyin-avdic-prwl4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün sporlar yarışta

Seyrediyorum stadyumda

İlân ediyorlar birdenbire:

Bütün sporlar Namaz''da! 

******

Namaz, ruh ve beden sporum.

Onunla Mirac''a çıkıyorum.

******

Ukbâdaki yaz,

Dünyadaki Namaz.

******

Midem, ''acıktım! '' der, feryad eder.

Ruhum, beş öğün günde Namaz yer.

******

Ruh ve beden banyom Namaz,

Miraç''tan inen bir niyaz.

******

Müslümanlar astronot, minareler füze, Miraç ise Ay''dır.

Müslüman olanlara bir abdest ile beş vakit Namaz farzdır.

Batı Berlin, 1980-85.', 'Bütün sporlar yarışta Seyrediyorum stadyumda İlân ediyorlar birdenbire: Bütün sporlar Namaz''da!  ****** Namaz, ruh ve beden sporum. Onunla M...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eskimez-beyitler-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyulmayan Feryat...', 'duyulmayan-feryat-zulfikar-yapar-kaleli-eurvd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göklere yekseldi feryadım kat kat

Duyanların yüreğini dağladı

Öpmeye kalktığım el idi fakat

Tuttu benim kollarım bağladı

Sevdim vatanımı, bugün dardayım

Suçum kimse bilmez, zindanlardayım

Arayanım da yok, yok oldu adım

Anam geldi garip garip ağladı

Tıkıldık zindana, boş geçti yıllar

Ne garip, kargalar kartal kovalar

Allah var be zalim, yıkılmaz dağlar

Eteğinde coşkun sular çağladı

Sönmedi bu ocak, tütecek elbet

Biraz sabır lazım, biraz da gayret

Esirgeme, Rabb’im bize yardım et

Çatlak bekçi bir düzendir sağladı

Namusunu yiyen kadın piyasa

Bu mudur töre be, bu mudur yasa? 

Bekçi makamında kurarsa masa

Kaleli’nin elbet yok olur adı', 'Göklere yekseldi feryadım kat kat Duyanların yüreğini dağladı Öpmeye kalktığım el idi fakat Tuttu benim kollarım bağladı Sevdim vatanımı, bu...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duyulmayan-feryat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıyoruz.! !', 'yaniyoruz-zulfikar-yapar-kaleli-e6yqu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül sırça saraydır yıkılırsa yapılmaz

Girmeye muktedirler nerdeler yanıyoruz.

Orta yerde bir hak var, haksızlığa tapılmaz

Ermeye muktedirler nerdeler yanıyoruz.

Konaklama bilmiyor, biçare akıl ezgin

Musibetler peş peşe, belâlar doludizgin

Ne kadar mustaribim, gönül ne kadar üzgün

Görmeye muktedirler nerdeler  yanıyoruz.

Gönlümüz ölü damı, yürekte yüz yakılır

Boğazı geçti geçen, hâlâ üsten bakılır. 

Adam biraz utanır, adam biraz sıkılır

Sormaya muktedirler nerdeler yanıyoruz.

Karanlık kafalılar besler garezi, kini

Mutmain gönül anlar yaşamanın zevkini

Cana akıl ziyası, dile gönül şevkini

Vermeye muktedirler nerdeler  yanıyoruz.

Hakikat silikleşti aynaların camında

Sultanlık arar olduk, harabenin damında

Gönüller gül arıyor yücelik makamında

Örmeye muktedirler nerdeler  yanıyoruz.', 'Gönül sırça saraydır yıkılırsa yapılmaz Girmeye muktedirler nerdeler yanıyoruz. Orta yerde bir hak var, haksızlığa tapılmaz Ermeye muktedirl...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yaniyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menfaat Dünyası...', 'menfaat-dunyasi-zulfikar-yapar-kaleli-7pckm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sefil bedende yük ise canlar

Dildeki gönülden okur, menfaat

Ferasetli insan bakınca anlar

Mideden seslenen şükür, menfaat

Dil söyler ya, nefsi diline uymaz

İşine gelmeyen  sözü de duymaz

Sünnet hep dilinde, gönlüne koymaz

Ali, Ömer, Osman, Bekir, menfaat

Olmalı gönül nur, alınlarsa ak

Kendini Allah’a teslim et, bırak

Dilde Allah fakat Resulden uzak

Cebe kiralanmış zikir, menfaat', 'Bu sefil bedende yük ise canlar Dildeki gönülden okur, menfaat Ferasetli insan bakınca anlar Mideden seslenen şükür, menfaat Dil söyler ya, ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/menfaat-dunyasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçiyor Zaman', 'geciyor-zaman-gozde-hatiboglu-iykis', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklımdan geçenlerin anlamsızlığına yeni bir yolda durmanın ve senden kalanlarla çarpışmanın verdiği yorgunluk eklenince zorluyor beni. 

    Karışıyorum. 

    Kırgınlıklar ve düşler birbirine girdiğinde fark ediyorum ki varlığını özlüyorum. 

    Bunca zaman yer kaplayanlar bir anda dağıldılar ve boşluklarıyla bıraktılar.

    Alışıyorum. 

    Boşluk hislerle yeniden var oluyor. 

    Zaman zaman ayağıma takılsalar da cam kırıkları misali eskimiş duygular yine de kanayan tabanlarıma inat aşka yürüyorum. 

    Sevmeyi senden sonra farklı açılardan algılıyorum çünkü yerin yüreğimin sol yanı olur  derken yanıldığımı görüyorum. 

    An oluyor yüreğimden düşüşüne nasıl seyirci kaldığıma şaşıyorum. 

    Sonra kızıyorum kendime, tutunmaya çalıştığım her yer parça parçayken, savunmadıkların ve korkak tavrınla nasıl hırçınlaştığımı hatırlıyorum. 

  

    Geçiyor zaman.

    Görüyorum ki geride kalıyor her duygu sağlam olmayan. 

    Bir kez daha anlıyorum aşkın sadece aşık olan göre olduğunu ve bendekilerle kalıyorum. 

    Pişmanlık yok. 

    Dingin yüreğim bundan öte, senden yansıyan belirsizlik çıkınca hayatımdan kendime dönüyorum. 

    Eskiden olsa mutlu ol derdim sana ama olma. 

    Kaybedilenler geçip giderken yanından ve var edilemeyecek bir aşk batarken günbatımıyla yüreğinden; ağla. 

     Nasıl kıymıştın bana..

    Şimdi yeni nesnelerim ve dolu dolu duygularla daha cesur bir aşığım.    

    Sevdalanmaya yakın ve gerçekten yüreğime dokunanlarlayım..

    Şaşkınlığım sadece yazgıya ve hayatın karşıma çıkardıklarına. 

    Sana hoşça kal demek imkansız sanmıştım, gördüm ki; zaten hayatıma almamışım..

(12.mayıs.2005)', 'Aklımdan geçenlerin anlamsızlığına yeni bir yolda durmanın ve senden kalanlarla çarpışmanın verdiği yorgunluk eklenince zorluyor beni.      ...', ARRAY['Türk Edebiyatı','Şiir','Gözde Hatiboğlu']::text[], 8.5, '{"poet":"Gözde Hatiboğlu","poet_slug":"gozde-hatiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/geciyor-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A n n e (ler Duyun Bizi)', 'a-n-n-e-ler-duyun-bizi-zulfikar-yapar-kaleli-mf6eb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sevdadan geri dönersek eğer

Gözümüze çivi çakın anneler

Başları yoluna koyduksa değer

İzimize çıra yakın anneler

Kanlar oluk oluk içine aksa

Vazgeçme dostundan düşmanın çoksa

Haksızlığa karşı lal olacaksa

Sözümüze kusur takın anneler

Şafaklar sökmede doğmamış ayız

Seher bülbülüyle aynı daldayız

Suçlu sevdalarla yarı yoldayız

Özümüze kurşun sıkın anneler

Boş başaklar gibi kavrulacaksak

Yanmasın anneler boşluğa aksak

Sop olup rüzgarda savrulacaksak

Yüzümüze bakman sakın anneler

Bir başka aşk bizi eğlemiyorsa

Gönül her sevdayı yaylamıyorsa

Hakkı hakikati söylemiyorsa

Yazımıza karşı çıkın anneler', 'Bu sevdadan geri dönersek eğer Gözümüze çivi çakın anneler Başları yoluna koyduksa değer İzimize çıra yakın anneler Kanlar oluk oluk içine a...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/a-n-n-e-ler-duyun-bizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlanma', 'umutlanma-cel-lettin-cevik-lke3d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlün bendeyse

Hüzün yolcudur

Kayıtsız kal yanılgılara

Şaşkınlıkların olacak sıkça 

Bu sevdâ mıdır, bu rûya mıdır

Gönlün bendeyse

Kapında güller görmeye alış

En sevdiğin şarkıyı söylerken

Gözlerimi üzerinde hissedip

Nakarata takılıp kalacak dilin

Gönlün bendeyse

Sevgi kokulu çiçekler sık açacak, 

Sensiz yalnızlık çekecek yıldızlar

Karanlık köşeleri aşk fısıltıları dönerken

Sevincin çok, taşkınlıkların bol olacak

Gönlün bendeyse

Gül yatağında, kuş ninnisiyle uyursun

Her sabah aşk mevsimine açılır gözlerin

Ne göz ne ten uzağındadır sevda

Bülbüle yuvadır artık gül bahçesi

Gönlün bendeyse

Senin soruların, benim cevaplarım yok

Sen bir kelebeksin, ben bir deli çocuğum

Peşinde koşmaktan her şeyi unutmuşum

Seviyor muyum… mutlu muyum…', 'Gönlün bendeyse Hüzün yolcudur Kayıtsız kal yanılgılara Şaşkınlıkların olacak sıkça  Bu sevdâ mıdır, bu rûya mıdır Gönlün bendeyse Kapında g...', ARRAY['Türk Edebiyatı','Şiir','Celâlettin Çevik']::text[], 8.5, '{"poet":"Celâlettin Çevik","poet_slug":"cel-lettin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/umutlanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Oldum Şiir İçinde', 'kus-oldum-siir-i-cinde-erdogan-ergin-ynpgz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazılmaya değer ne varsa,

Şiire dair; 

Unuttum

Aklımdan uçuverdi her şey

Yerine ne kondu bilmiyorum

Bazen kelimeler geliyor aklıma

Çarpıyor aklımın duvarlarına

Ağarıyor saçlarım,

Her asi dalganın,

Gözlerimde yer bulduğunda

Aşkı düşünüyorum, bazen

Kızlar geçiyor aklımdan

İsmini hatırlayamadığım 

Bir sürü kadın

Ne oldu diye düşünüyorum, onlara

Bilmem

Evlendiler her hal

Benim gibi olmayan adamlarla

Sonra hatalarım….

Ne hatalar yapmışım aşk adına

Kim yapmaz ki, hata

Doğruyu bulmak için

Karalamaz bir sürü boş kağıdı

Demek ki boşmuş

Aş hayatımda,

Onca kadın

Bak kuş oldum, yine şiir içinde

Kondum daldan dala

Bağla şimdi dalları kolaysa

Ah! Aşk, ne hale sokuyorsun adamı', 'Yazılmaya değer ne varsa, Şiire dair;  Unuttum Aklımdan uçuverdi her şey Yerine ne kondu bilmiyorum Bazen kelimeler geliyor aklıma Çarpıyor ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kus-oldum-siir-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttur Kendini', 'unuttur-kendini-cel-lettin-cevik-pqgo7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yar desem, gel desem olmaz

Zor olsa, zoru aşmak kolay 

Her gün aynı acı, aynı keder

Ben imkansızda ölüyorum

Kayıp gidiyor ellerimden hayat ipi

Yaşamanın bedeli belli ölüm kere ölüm

Sesini duysam, resmine baksam olur

Çekip gidiyorsun,  karanlıkta gölgelerin

Hangi terazide tartsam yüreğim eksik

Boş yere yeminler ediyorum sevdâya 

Umut tutunduğum dal değil

Kan çiçekleri örter üzerimi sen değil

Her güzel düşü çirkin sırlarla kaplıyorum

Sızlanacak acıları zoraki gülüşler gizliyor

Anlatmıyor, anlatmıyor hâlimi kelimeler 

Çoğalıyor yalnızlığı tetikleyen parmaklarım

Yar desem, gel desem olmaz

Olmazlar peşimdeyken, beni aklına al

Yüreğine sığmaz yüreğimin acıları

Ya bana unuttur kendini, ya gitme kal', 'Yar desem, gel desem olmaz Zor olsa, zoru aşmak kolay  Her gün aynı acı, aynı keder Ben imkansızda ölüyorum Kayıp gidiyor ellerimden hayat i...', ARRAY['Türk Edebiyatı','Şiir','Celâlettin Çevik']::text[], 8.5, '{"poet":"Celâlettin Çevik","poet_slug":"cel-lettin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unuttur-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez Mi? ? ?', 'yetmez-mi-zulfikar-yapar-kaleli-t81mi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne yaptınız diye sormayın bize

Zafere duacı olduk yetmez mi? 

Allah''ın izniyle güvenip size

Canları pazara sürdük yetmez mi? 

Sahibimiz Allah vekilimiz size

Bizde buruk yürek sizde cevher öz

Milleti top yekun kucaklarız biz

Sizleri meclise saldık yetmez mi? 

Sermayem kazancım güvencim artı

Dil susar konuşmaz olmazsa sırtı

Dün ile bugünü tartar mı tartı

Sizinle ağladık güldük yetmez mi? 

Yetmez mi gül diye can sunduk işte

Tesellimiz sizler avunduk işte

Ta candan yürekten savunduk işte

Sizi vekilimiz bildik yetmez  mi? 

Hepiniz mücevher hepiniz değer

Değerli olanı Peygamber över

Kaleli''nin sözü hiç ise eğer

Dört bin yiğit ile öldük yetmez mi? 

                                                05 11 1991', 'Ne yaptınız diye sormayın bize Zafere duacı olduk yetmez mi?  Allah''ın izniyle güvenip size Canları pazara sürdük yetmez mi?  Sahibimiz Alla...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yetmez-mi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hücredeki Adam', 'hucredeki-adam-hatem-kardesler-tl2br', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suat YAĞIZ’A

Kapanmış karanlığına gecelerin

Bir türkü tutturmuş uzaktan uzağa…

Ana demiş,

Baba demiş,

Yar demiş,

Sıla demiş ağlamış…

Gün olmuş hasreti; 

Koğuş duvarlarında çınlamış…

Gün olmuş gurbeti; 

Yalnızlık diye tanımlamış…

Gün olmuş bir güz ekimini düşlemiş,

Karanlık gecelerde…

3-5 nöbetçilerinin gölgesinde…

Yaşadığım dünya “Hücre”dir demiş,

Ki düşüncelerimizi prangaya vururlar,

Düşünce fırsatı vermezler adama…

Zaman gelmiş “Hücrem” dediği dünyası

Küçülmüş,küçülmüş…

Kağıthane sırtlarında bir cisim oluvermiş…

İşte kendi kabında,

Kendi hücresinde bu adam; 

Yine bir güz ekimini düşlemektedir,

Yine anasını,babasını yarini,

Memleketini özlemektedir…



		         (Hasret İçimde Bir Dağ)  Kitabından', 'Suat YAĞIZ’A Kapanmış karanlığına gecelerin Bir türkü tutturmuş uzaktan uzağa… Ana demiş, Baba demiş, Yar demiş, Sıla demiş ağlamış… Gün olm...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hucredeki-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen..Ben..Hüzün', 'sen-ben-huzun-gozde-hatiboglu-ezmph', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamansız ve eski bir ilkbahar akşam üstünden kalma yarı bulanık hava,

 Yağan yağmurla gökkuşağının renkleri altında bir düşün uykusundayım. 

 Kendimden geçtim, bunu fark ettiğimde senden de çoktan geçmişim. 

 Şimdi yalın ve yalnızlıktayım. 

 İçimdeki dalgalar durulmuş, fırtınadan sonraki toprak kokusundayım.

 Sen.. kimdin de bunca zaman yüreğimi gözü yaşlı bıraktın.

 Hırçınlığın boşuna, tutunamazsın artık duygularıma.

 Ben.. nerden başladım ve nasıl bir son umdumsa, ordayım. 

 Hüzün.. bir var bir yok..

 Yaralarımı hüzünle sarmadayım..

 Şimdi yanımda duran ve huzurlu aşklardayım..

(7.Mayıs.2005)', 'Zamansız ve eski bir ilkbahar akşam üstünden kalma yarı bulanık hava,  Yağan yağmurla gökkuşağının renkleri altında bir düşün uykusundayım. ...', ARRAY['Türk Edebiyatı','Şiir','Gözde Hatiboğlu']::text[], 8.5, '{"poet":"Gözde Hatiboğlu","poet_slug":"gozde-hatiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-ben-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıksız hasret.', 'basliksiz-hasret-hasan-akin-5akp3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorgun sardı gözlerim

susamış çapaklarda...

sevdiğim,

ben

bana verdiğin vekaletin adıyım

ve örümcekler ağlarında...

Bırak sönsün lambalar

Nasılsa kırıldı saçlarımın seyisleri

köpük saçların avuçlarda....

Bütün izinlerin işgale kalsın

kuru şafak yazgısında

bütün koğuş kalksın....

Urfa/Birecik....18.06.05', 'Yorgun sardı gözlerim susamış çapaklarda... sevdiğim, ben bana verdiğin vekaletin adıyım ve örümcekler ağlarında... Bırak sönsün lambalar Na...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akın']::text[], 8.5, '{"poet":"Hasan Akın","poet_slug":"hasan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/basliksiz-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mümkün Mü?', 'mumkun-mu-ayse-yucel-5uklo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hava kararıp da akşam çökünce şehre

Şöyle uzanıp boylu boyu yıldızlara bakıp da

Seni hatırlamamak mümkün mü? 

Gece bakışlarını görmemek sislerin arasından

Özlememek mümkün mü sonum olan ellerini? 

Duyarsın belki diye o şarkıyı fısıldamamak

Tenim tenine değmiş gibi ürpermemek 

Mümkün mü sanıyorsun sana birikmemek, sana dolmamak

Bir kucak dolusu sana uzanmamak

Sana akmak isteyip dalgalanmamak

Yaz yağmurları gibi sevinçlerini

Aramamak çocuk gülüşlerini

Ve kimin soluğuyla uyandığını düşünüp dağılmamak

Paramparça olmamak

Seni özlememek

Ve dilememek yeniden...

Mümkün mü?', 'Hava kararıp da akşam çökünce şehre Şöyle uzanıp boylu boyu yıldızlara bakıp da Seni hatırlamamak mümkün mü?  Gece bakışlarını görmemek sisl...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mumkun-mu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemediğim', 'soyleyemedigim-hatem-kardesler-lx3td', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana söylemek istediğim,

Bir şey var…

Gecenin sıfırikileri kadar ürkek,

Gecenin sıfırikileri kadar ağlamaklı,

Gecenin sıfırikileri kadar sessiz…

Sana söylemek istediğim,

Bir şey var…

Ölüm gibi acı

Ecel gibi ürkek,

Can gibi tatlı…

Sana söylemek istediğim,

Bir şey var…

Ağlamak kadar doğal,

Gülmek kadar komik,

Gelmek kadar zor…

Sana söylemek istediğim,

Bir şey var…

Anlamak kadar anlamlı,

Anlamamak kadar anlamsız…

Sana söylemek istediğim,

Şeyler var…

Dünyalar kadar…

Dünyalar kadar…

Dünyalar kadar…

									

									                                           

		         (Hasret İçimde Bir Dağ)  Kitabından', 'Sana söylemek istediğim, Bir şey var… Gecenin sıfırikileri kadar ürkek, Gecenin sıfırikileri kadar ağlamaklı, Gecenin sıfırikileri kadar ses...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/soyleyemedigim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mangal Keyfi (Babaanneme)', 'mangal-keyfi-babaanneme-ali-osman-yilmaz-xe4mu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'MANGAL KEYFİ

	

	Bilenler bilir.Eski Türk evlerinin sofa denen orta salonlarında yada oturma odalarının ortasında çoğu zaman oval şekilde mangal bulunurdu.Ev halkı sabah evden  işe gitmek için ayrılınca,akşamdan sobada kalan ateş bu mangala yerleştirilir,eğer ateş yeterli değilse üstüne odun kömürü atılarak ateşin gün boyu sürmesi sağlanırdı.Böylece evde kalan kadınlar ve çocukların üşümesi engellenir,fazladan sobada odun yakılarak para israfının önüne geçilmeye çalışılırdı.

	Daha zenginlerin evlerinde şimdilerde adına şömine denen ocaklar  bulunur ve buralarda yanan ateş sayesinde evde kalan kadın ve çocuklar,ocak önü  sohbetleri yapar ve çocuklar oyunlarını oynar,derslerini yapardı.

	Babaanneme bizim yörede Kıvırcık Ayşe derlerdi.Saçları kıvır kıvır,yazmasının altından taşardı.Her banyodan sonra onları özenle tarar,kimi zamanda yanlardan örerek belik yapardı.

 Çok cevval kadındı babaannem.Mahalle gençlerinden evlenme vakti gelen gençlere hamamda kız beğenir,genç kızlara da koca bulurdu.Nerdeyse bizim semtin en ünlü çöp çatanıydı denebilir.

Ama sözünü esirgemez,dobra dobra ne söyleyecekse korkmadan çekinmeden söylerdi.O yüzden herkes babaannemle dalaşmaktan korkardı.

Çocukken en  sevdiğimiz şey eve misafir gelmesiydi.Nasıl sevinmezsin? her misafir geldiğinde,o mangala hemen patatesler gömülür,bir kenarına toprak çaydanlık oturtulur,hemen mutfaktan süt ve un gelir,cıvık hamur hazırlanır,mangalın üstüne de kaygana oturtuldu mu sabırsızlıktan çatlardık.İşte en çok o zamanlar  babaannemden tokat,çimdik yerdik.Mangalda patatesler pişmeden ateşi karıştırır,kaygananın üstene konan cıvık hamuru,yani akıtmayı yemeye çalışırdık.Birde yan masada zeytin,peynir,reçel olurdu ki parmaklarımızla yemeye çalışırdık.Eh deymeyin keyfimize.O nedenle babaannem,arsızlık etmeyin diye bağırır,yetişirse de şaplağı indirirdi.Tüm çocuklar  odalara,etrafa kaçışırdık.Yalnız biz mi? Komşu çocukları da anneleri ne kadar bağırsalar,uslu olun diye azarlasalar da bu şaplaklardan nasibini alırdı.

Biraz irice büyümüştüm.Ye kalmasın tabakta bir şey,günahtır oğlum derler,tabağı tertemiz ettirirlerdi.O nedenle tabağa konan fazlaca da olsa yiyecekleri bitirmek,günaha girmemek adına,iyi bir kul olma adına bira irice olmamı sağlamıştı.Yani kısacası ergenleşiyor gibiydim.

Günlerden bir gün eve komşular geldi.Mahallemizin en güzel kızı,annesi ve başka büyükleri,babaannemden akıl soracaklar.Hem de kızlarına evlenmeden önce gerdek ve diğer bilgileri alacaklar.Eh nede olsa mahallemizin en bilgili kadını babaannemdi.Tecrübeli,sözünü esirgemeyen,her taşın altından kalkan bir kadın 4 erkek,3 kız olmak üzere 7 çocuk doğurmuş 20 yıldır da dul birisiydi. 

Eh kadın kadına yapılan toplantılarda,kadınlar fütursuz davranır,eteklerini falan toplamaya özen göstermezlerdi.İşte bu anlarda ergenliğe adım  atmakta olan çocuklar ağızları açık kadınların  bacaklarına bakakalır,çözülen düğmelerin ardından görünebilecek göğüslere bakılırdı.Babaannem çıkın dışarı sizi hınzırlar,pis  röntgenciler diye bizi kovalardı.Kadınlara da dönüp,ayol bunlar kazık kadar adam oldu artık, toplanın,kendinize çeki düzen verin diye söylenirdi.Bizler dışarı kaçıp cam kenarına toplanır,içeride kadınları dikizlerdik.Babaannem bizi gördükçe  her seferinde bağırır perdeleri çekerdi.

O mahallenin en güzel kızının bize geldiği gün,içeride bir şeyler olacağını düşünüp,dışarı çıkıyorum diyerek odaya gitmiştim.Kapıdan sessizce içeride olan biteni duymaya çalışıyordum.Kıvırcık Ayşe,kadınları mangalın etrafına toplamış,toprak  çaydanlığı  içine oturtmuş,mahallenin güzel kızını da mutfağa süt,un almaya göndermişti.O anda kızın annesi,güzel kızın ilk gece korkusunu,.gelin kıza ahretlik(sağdıçlık)   yapacak biri olmadığını,ne olur diyerek yardım  etmesini babaannemden istedi.Babaannem korkma,her bi şeyciği öğretirim  ben ona.Sen korkma.İlk gece damadın aklını başından aldırtmazsam nah bana diyerek  elinin parmaklarını boylu boyunca açarak elini ileri götürdü.Sen onu  benimle   bir iki kez hamama salıver,ben ona ne cilveler öğretirim,hazinelerini nasıl kullanacağını anlatırım dedi.Gözlerim birazdan bayram yapacaktı.Daha öncede görmüştüm.Böyle bir genç kızı sofanın ortasında nerdeyse çıplacık hale getirmiş,memelerini,kalçalarını,vücudunu nasıl kullanacağını anlatmıştı.Gerçi ben o zaman ergenlik falan çağından uzak olduğum,hatta hala kadınlar hamamına babaannemle gittiğim için,her şeyin benim yanımda olmasına ses çıkarmamışlardı.Şimdi öylemi? Ya.Kazık kadar adam oldu diyordu babaannem benim için.Eh haksızda sayılmazdı hani.

Mahallenin güzel kızı süt ve unla içeri geldi,Bir kap içinde babaannem unu süt ve suyla karıştırırken,kıza patates getirmesini söyledi.Kız tekrar mutfağa yönelmişti.Babaannem kadına,kız sende ne hont kadınsın.Kızını da kendin gibi hont yetiştirmişsin.Sende genç kızlığında kıvırtmayı,kalçalarını işveyle sallamayı beceremezdin.Kızına da ne bir işve öğretmiş,nede dişiliğini sergilemesini anlatmamışsın. 

Kadın,bende sana o yüzden geldim ya Ayşe abla dedi.Babaannem tamam.Kızını bir haftada fettan bir dişi yapmazsam yuh bana,Yuh kıvırcık Ayşe’ye dedi.

Güzel gelin adayı  patatesleri getirmiş,çay demlenmiş,hep beraber sofraya geçmişlerdi.Bir ara  babaannemin kıza; kaldır kız şu eteklerini,sıyır azıcık bakıyım demesiyle kalbim küt küt atmaya  başladı.Kız eteklerini alı al bir yüzle kaldırınca küçük dilimi yuta yazdım.Aman tanrım o ne muhteşem bir görüntüydü,o bacaklar,o kalçalar aklımı başımdan almaya yetmişti.Hele entarisinin üst kısmını çıkarıp evde dikilmiş sütyenin içindekileri gösterip,bunlar ne kadın,bu kıza çarşıdan güzel sütyen almalı dedi.Aman tanrım aklımı  kaçıracaktım sanki.Gözlerim yuvalarından fırlayacakmış gibi açılmıştı.Babaannem kızın kıçına hızlıca bir şaplak indirdi,kız ah diyerek kenara çekildi.Belliki canı yanmıştı.Hınzır kız,Kocana bu  bacaklarını, kalçalarını,memelerini gösterince aklını  başından alacaksın.Birde benim derslerimi iyi öğrenirsen vah kocanın haline.

Ter içinde kalmıştım.Aman tanrım,erkeklik ne biçim  bir şey böyle,halbuki hamamda ne kadar çok çıplak kadın görmüştüm,kimi güzel,kimi karnına sarkmış  memeler,sütun gibi bacaklar,yusyuvarlak kalçalar,çoğu da portakal kabuğu gibi kıvrım kıvrım şeylerdi.Hiç bir şey anlamazdım.Önümdeki şeye hayretle bakıp,kadın denen yaratıkları anlamaya çalışırdım.Aklım yinede ermezdi.Her şeyin bir zamanı var elbet.İşte şimdi kanımı kaynatan,beni ter içinde bırakan,önümdeki şeyin kazık gibi olmasına neden olan ergenlik  başlamıştı.İçimi bir korku sardı.Ya babaannem beni bu halde görürse,işte yandığım gündü. Sessizce kalktım,kapının ardından yatağa kıvrıldım,yorganı başıma kadar çekip sanki uyuyacakmışım gibi gözlerimi kapadım.Ama gözümün  önünden o görüntüler hiç gitmiyor,o küçük sandığım şey kocaman olmuş kazık gibi ellerimin arasındaydı.Ne olduğunu anlamadım ama,donumun ıslandığını,işemenin dışında bir şeyin donumu ıslatmakta olduğunu  fark ettim.Eyvah şimdi ne olacaktı.Bana neler olmuştu.Bu durumu kime anlatabilirdim.İçime bir korku girdiki,yorganın altını iyice saklandım.Annemin sesiyle uyandım. Ellerimle bacaklarımın arasını kapatıyordum farkında olmadan.Annem ne oldu diye sormaz mı? Eh o anda ter boşaldı sırtımdan,hızla dışarı çıktı,babam içeri geldi gülümseyen bir yüzle.Kaşlarını sözüm ona çatmış kaldır bakayım ellerini dedi.İstersen kaldırma.Ellerimi utanç içinde çektim.Donuma işedi diyecekler diye ödüm patlıyordu.Vallahi işemedim baba dedim.Tamam oğlum.Git banyoya gir,duş al  yıkan,bitincede gusül apdesti al.Ha biliyormusun nasıl alacağını diye sordu.Biliyorum anlamında başımı salladım.İşte o an başıma gelenin ne olduğunu anlamıştım.Ben artık erkek olmuştum.Ve ilk gusül apdesimi alacaktım. 

Neyzenden Bir Dörtlük (ilgilisine) 

Öyle hürriyete aşık ki kadınlar,hatta,

Hiç bir erkek olmaz onlara yol arkadaşı,

Çıkar at çarşafı  teklifine karşı,netekim,

Donu fırlattı..........tünden,açacak yerde başı.', 'MANGAL KEYFİ 	 	Bilenler bilir.Eski Türk evlerinin sofa denen orta salonlarında yada oturma odalarının ortasında çoğu zaman oval şekilde man...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mangal-keyfi-babaanneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç''lik', 'hic-lik-omer-golge-ovrbw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül yarasına söz çare olmaz

Devayı melhemi dost elindendir

Mütemadi kanar bir lahza onmaz

Bülbülün figanı gül tenindendir

Arif hayran olmuş sırr-ı hilkate

Hayreti her lahza tecllidendir

Nazarı garkolmuş kevn-i vahdete

Şarhoşluğu bu ilahi meydendir

Puthane,meyhane,salhanede de

Bilirimki bana gelen sendendir

Bu sen,ben deyişin tek illeti de

Çaresizim! kifayetsiz dildendir

Yoksa sen variken benmi olurmuş

Bu söz olsa,olsa cehalettendir

Bütün kainatı aşkın doldurmuş

Bu aşkın idraki bil hiçliktendir.', 'Gönül yarasına söz çare olmaz Devayı melhemi dost elindendir Mütemadi kanar bir lahza onmaz Bülbülün figanı gül tenindendir Arif hayran olmu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hic-lik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayrılığın Yansıması', 'bir-ayriligin-yansimasi-ayse-yucel-85ax7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidiyordun

Yağmurlar yağdırarak ardından

Gidiyordun

Yüreğim ellerinde

Çocuklar gibi

Ağlıyordum

İçimdeki fırtınaya inat

Sen çığlık çığlık

Susuyordun...

Yüreğin gideli çok olmuştu

Senin ayazında 

Üşüyordum

Ellerim ellerindeydi

Gidiyordun', 'Gidiyordun Yağmurlar yağdırarak ardından Gidiyordun Yüreğim ellerinde Çocuklar gibi Ağlıyordum İçimdeki fırtınaya inat Sen çığlık çığlık Sus...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-ayriligin-yansimasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötelerin Adamı', 'otelerin-adami-hatem-kardesler-4wd94', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben ötelerin adamıyım birtanem,

Sizce lanetlenmiş bir şehirde doğmuşum…

Ama ben sevmişim doğduğum şehri,

Hemde yürekten sevmişim…

Yaylanın yeşiline,

Çiftelerin karına aşık olmuşum…

Birde seni sevmişim; 

Yürek bu,

Sevda bu,

Aşk bu…

Günlerce hayalinle avunup durmuşum…

Olmayacak duaya amin demişim günlerce…

Ve birgün yüzüstü bırakmış gitmişsin uzaklara…

Sevda demiş,

Aşk demiş,

Sen demiş,

Ben demiş düşünmüşüm sonra…

Ve birden 

İsyan bayrakları göndere çekilmiş beynimde,

Olamaz demişim…

Olmaz demişim…

								

									                                           

		         (Hasret İçimde Bir Dağ)  Kitabından', 'Ben ötelerin adamıyım birtanem, Sizce lanetlenmiş bir şehirde doğmuşum… Ama ben sevmişim doğduğum şehri, Hemde yürekten sevmişim… Yaylanın y...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/otelerin-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-celal-isildak-n6hnc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel

Bir güzel metedem dostlarım size

Kara kaşlar göze ne kadar uymus

Niyazlar ettirir getirtir dize

Kara kaşlar göze ne kadar uymus

Bakışları afet duruşu melek

Görmek gerekiyor söze ne gerek

Alttan alttan bakar gözün süzerek

O kaşlar o göze ne kadar uymuş

Bir bakışta iiçin ediyor harab

Ne güzel yaratmış özenmiş yarab

Altın gibi sakla olmasın harab

O kaşlar o göze ne kadar uymuş

Nerelisin dedim birazcık güldü

Sanki bu garibi yürekten vurdu

Sordum söylemedi o güzel yurdu

O kaşlar o göze ne güzel uymuş

Saçın dökmüş gerdenınden dödüne

Ben gercegi gördüm gerek yok düşe

Celal Gurbaniyi getirir  dize

O güzele o boy ne güzel uymuş

2002 Amerirka', 'Güzel Bir güzel metedem dostlarım size Kara kaşlar göze ne kadar uymus Niyazlar ettirir getirtir dize Kara kaşlar göze ne kadar uymus Bakışl...', ARRAY['Türk Edebiyatı','Şiir','Celal Işıldak']::text[], 8.5, '{"poet":"Celal Işıldak","poet_slug":"celal-isildak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guzel-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delirdim', 'delirdim-yurdagul-kurnaz-efjl0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yonca''ya gul dedim

gul''e guldum

Biri dogdugunda agladim

olene guldum

Vefasizlarin kirli carsaflarini

ortaya doktum

Acimayin bana...! 

sizki aglanacak halinize gulen

Dut duru dunya

herkes degisik bir turkuden

Giden yolculara, merhaba

Gelene, elveda

Kanlar akmasin,

analar yanmasin

Sokakta el ele deliler dolassin

Yolu sevgiden gecen yolcuya

Delicesine Merhaba...

20.04.2005', 'Yonca''ya gul dedim gul''e guldum Biri dogdugunda agladim olene guldum Vefasizlarin kirli carsaflarini ortaya doktum Acimayin bana...!  sizki ...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/delirdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Selam', 'dosta-selam-celal-isildak-oph92', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dosta Selam 

Aldım selamını güzel dost senin 

Bir gün olur dosta gelir Gurbani 

Yüreginden gelen hoş muhabbetin 

Bir gün olur dinler seni Gurbani 

Emlek yöresinin dertli bülbülü 

Kablan deresinde açardı gülü 

Kurumuş ırmagı deresi gölü 

Seninle sel gibi coşsa Gurbani 

Pircanın başına seninle çıksam 

Oradan hasretle etrafa baksam 

Seninle oturup şiirler yazsam 

O zaman coşarsın dostla Gurbani 

Ak pınara gelip orda otursak 

Rakımızı soğuk suya yatırsak 

Kalan şiirimiz orda bitirsek 

İşte o zamanlar mestdir Gurbani 

Özledimde yazdım ben bu sözleri 

Kısmet ise gelir görür gözleri 

Orta köyle Hüyüklünün sözleri 

Her gün kulagında çınlar Gurbani 

Ali İzzetle Aziz Üstün ustadım 

Aşık Aziyetle kaynaşır kanım 

Gurbani yadelde çıkmadan canım 

Dostlarala buluşmak ister Gurbani 

17 Haziran 2005', 'Dosta Selam  Aldım selamını güzel dost senin  Bir gün olur dosta gelir Gurbani  Yüreginden gelen hoş muhabbetin  Bir gün olur dinler seni Gu...', ARRAY['Türk Edebiyatı','Şiir','Celal Işıldak']::text[], 8.5, '{"poet":"Celal Işıldak","poet_slug":"celal-isildak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dosta-selam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost 4/4', 'dost-4-4-yurdagul-kurnaz-anhpv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siiri anlatan sair ebedi

Yasa sen dost yüreklerde

Özü öz, sözü söz

Korusun seni Mevlam kem gözlerden', 'Siiri anlatan sair ebedi Yasa sen dost yüreklerde Özü öz, sözü söz Korusun seni Mevlam kem gözlerden...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dost-4-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diren...! ! !', 'diren-yurdagul-kurnaz-3h67k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceler kanatir kalbin yarasini

Ailem dedigim tutunagim

Yillar boyu savurdu beni

Catlayan dudaklarim

Dilimin altinda yatanlar

Aci biber gibi yakar

Birak sen sende kal

Övün yalnizliginla Yurdagül

Hep gül

Ne dikenine dokunsunlar

Ne de gülünü incitsinler

Diren...! ! ! 

06.01.2005', 'Geceler kanatir kalbin yarasini Ailem dedigim tutunagim Yillar boyu savurdu beni Catlayan dudaklarim Dilimin altinda yatanlar Aci biber gibi...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/diren-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne fark eder', 'ne-fark-eder-mehmet-bolus-63gnh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz yaşamak ölümden beter,

Ha yoksun ha ölmüşüm ne fark eder.

Senin olmadığın hayatı bu gönül neyler,

Ha yoksun ha ölmüşüm ne fark eder...

Sensiz yaşamanın bir anlamı olmaz,

Solar gider yüreğim bir daha açmaz,

Ağlarım sele döner gözyaşım durmaz,

Ha yoksun ha ölmüşüm ne fark eder..

Çiçeğe verilen su damlası gibisin,

Bu gönül sensiz açmış neylesin,

Gittiğin gün ben ölürüm bunu iyi bilesin,

Ha yoksun ha ölmüşüm ne fark eder...

                                              15/10/1996', 'Sensiz yaşamak ölümden beter, Ha yoksun ha ölmüşüm ne fark eder. Senin olmadığın hayatı bu gönül neyler, Ha yoksun ha ölmüşüm ne fark eder.....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bölüş']::text[], 8.5, '{"poet":"Mehmet Bölüş","poet_slug":"mehmet-bolus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-fark-eder-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Farz Et', 'masal-farz-et-gozde-hatiboglu-vbucz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırak sensiz kalsın mevsimler bir süre...

Bırak ilk bahar tanımasın seni...

Bilmesin yüreğindeki o derin sevgiyi...

İzin ver yüreğine ağlasın...

Zaman ver kendine, bırak bir süre yalnız kalsın...

Bildiğin her şeyi unut ayrılığa dair, bu ayrılık bildiklerin gibi değil...

Hani şiirler vardır, yetişir çoğu zaman imdadına..

O kırık dökük cümleler sevdiğin şairlerden, aklına gelir bu zamanlarda..

Hepsinde kendine ait bir şeyler var..

İsyan var ayrılığa o satırlarda, 

Sitem var sevgiliye söyleyemediğin,

Belki de,

Üstü kapalı dörtlüklerde anlamak istemediğin bitiş var..

Sevgili...

Üzgünüm olanlar için...

Üzgünüm yarı yolda bıraktığım için...

Üzgünüm kırgınlıkların için...

Farz et ki masaldı yaşananlar..

Bizde bu masal ülkesinin aşka dair kahramanları..

Okuduk heyecanla ve sevgiyle birbirimizi..

Elbet bir son var sevgili..

Her masal gibi bu da bitti! ! ! 

(mayıs 2002)', 'Bırak sensiz kalsın mevsimler bir süre... Bırak ilk bahar tanımasın seni... Bilmesin yüreğindeki o derin sevgiyi... İzin ver yüreğine ağlası...', ARRAY['Türk Edebiyatı','Şiir','Gözde Hatiboğlu']::text[], 8.5, '{"poet":"Gözde Hatiboğlu","poet_slug":"gozde-hatiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/masal-farz-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi', 'gibi-seckin-tok-a4l8o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bazen dudaklarım bükülüyor kendiliğinden

saçlarımın karıştığını fark ediyorum

parmaklarım sımsıkı

bir gelinciği düşürmenin ayıbı var

gevşetmeden sıkıyorum parmaklarımı

çalımlarla yürüyorum sana gidiyormuş gibi

ve elbette bileceksin elimde şiirlerim

gözlerimde su içmemiş hayaller

aç karnına yollarda

sana gidiyorum

gibi…

(29.11.2004 / 02.10)', 'bazen dudaklarım bükülüyor kendiliğinden saçlarımın karıştığını fark ediyorum parmaklarım sımsıkı bir gelinciği düşürmenin ayıbı var gevşetm...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Tok']::text[], 8.5, '{"poet":"Seçkin Tok","poet_slug":"seckin-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gibi-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah', 'gunah-seckin-tok-r8z2z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'günah kalbe işleyen tüm hançerlere.

sevdayı deniz olarak hayal etmek kadar serin ve kutsal

kaybolmanın geceliğini sattığı eskicilerle

iki üç muhabbet etmek kadar günah.

gün çekerse düşen pantolonunu tekrar üstüne

olur da bulutlar üşümez bir daha.

(03.03.2005 / 20.29)', 'günah kalbe işleyen tüm hançerlere. sevdayı deniz olarak hayal etmek kadar serin ve kutsal kaybolmanın geceliğini sattığı eskicilerle iki üç...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Tok']::text[], 8.5, '{"poet":"Seçkin Tok","poet_slug":"seckin-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gunah-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerelerdesin', 'nerelerdesin-mehmet-bolus-gb5mg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün gece ansızın uykudan uyandım,

O mahmur gözlerimle etrafıma bakındım,

Yarım açık gözlerleyine seni aradım,

Yine yoktun yanımda vefasız nerelerdesin..

Kapatmadım kapıyı,camları açık tuttum,

Belki bir rüzgar olup esip gelirsin diye.

Kırpmadım gözümü yoluna nöbet tuttum,

Yine yoktun vefasız nerelerdesin....

                                15/10/2000', 'Dün gece ansızın uykudan uyandım, O mahmur gözlerimle etrafıma bakındım, Yarım açık gözlerleyine seni aradım, Yine yoktun yanımda vefasız ne...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bölüş']::text[], 8.5, '{"poet":"Mehmet Bölüş","poet_slug":"mehmet-bolus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nerelerdesin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutkulu', 'tutkulu-seckin-tok-hd0zd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gün sarardı ayaklar altında

suskun güler yüzlü kız

içine akıtmış tüm dertlerini

kaçışırken gökyüzü sıcaklığında

sam yeline takılmış parmakları

kim bilir, belki de üşüyor saçları

dünya gecelerinden herhangi birinde

gökten aniden yağsa

bir parça gelincik yaprağı

yağmurda toprak kokusu sinecek üzerine

gülümse

ve unutma ki

bu sabah da gökyüzü sana muhtaç...

(16.01.2005 / 13.28)', 'gün sarardı ayaklar altında suskun güler yüzlü kız içine akıtmış tüm dertlerini kaçışırken gökyüzü sıcaklığında sam yeline takılmış parmakla...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Tok']::text[], 8.5, '{"poet":"Seçkin Tok","poet_slug":"seckin-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tutkulu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmalısın Beni', 'unutmalisin-beni-mehmet-bolus-9th5j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün yine evime telefon açıp,

Seni aramam için haber salmışsın.

Seninle yolumuz çoktan ayrıldı,

Artık gerçeği görüp anlamalısın..

Dönüşü olmayan  bir yoldayız biz,

Ayrı dünyalarda yabancıyız ikimiz.

Mazide bir anı oldu sevgimiz

Artık bunları görüp anlamalısın..

Tükendi sevdamız,bitti aşkımız,

Artık başka insanların kollarındayız.

Dağlar gibi uçurum seninle aramız,

Artık sende bunu anlamalısın,

Zorlada olsa beni unutmalısın...', 'Dün yine evime telefon açıp, Seni aramam için haber salmışsın. Seninle yolumuz çoktan ayrıldı, Artık gerçeği görüp anlamalısın.. Dönüşü olma...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bölüş']::text[], 8.5, '{"poet":"Mehmet Bölüş","poet_slug":"mehmet-bolus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutmalisin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıklar', 'baliklar-seckin-tok-ri2p0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Balıklar akşamları dua eder

Düşte sevgiliyi görmek için,

Sonra kamer seslenir yukarıdan

Bu gece ilan-ı aşk edin,

Ama hiçbiri göze alamaz

Karşına çıkmaya sevgilinin,

O bir damla gelincik yaprağı gibi

Alev alev yanan gözlerin.', 'Balıklar akşamları dua eder Düşte sevgiliyi görmek için, Sonra kamer seslenir yukarıdan Bu gece ilan-ı aşk edin, Ama hiçbiri göze alamaz Kar...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Tok']::text[], 8.5, '{"poet":"Seçkin Tok","poet_slug":"seckin-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/baliklar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran', 'hicran-cemal-gokmen-4kl54', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık ne hiçbir şey eskisi gibi olacak

ne de bizleri hatırlatan bir şarkı

sonundayız bu hikayenin

kabuslarımı sensiz gecelere gizleyeceğim

kanayan yüreğimdeki izlerini

sileceğim sessizce

ümitlerimi,renksiz umutsuzluklarla boyayıp

karanlıklarda,kaybedeceğim kendimi

bir geçmişin bittiği yerde

bu şehirde

hazana dönen baharın

yasını tutacağım bağ bozumlarında

uçurumlardan düşerken yüreğim

kırılgan umutlara vurgun yiyecek

gökten kayarken yıldızlar

tutulan dileklerde olmayacağım

aşk defterimin son nirengi noktasını

savuracağım bu rüzgarların ıslığında

o kahvesi güzel,kahverengi gözlerinin

kifayetsiz özlemimde soldurup

hüzne boğulmuş yorgun ruhumu

hapsedeceğim en karanlık zindanlarda

sevdalı yağan yağmurların hüzzamlı sesi

bu çaresizlik

bu umman

sonsuza dek sürecek bu hicran', 'Artık ne hiçbir şey eskisi gibi olacak ne de bizleri hatırlatan bir şarkı sonundayız bu hikayenin kabuslarımı sensiz gecelere gizleyeceğim k...', ARRAY['Türk Edebiyatı','Şiir','Cemal Gökmen']::text[], 8.5, '{"poet":"Cemal Gökmen","poet_slug":"cemal-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hicran-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susarsa Gelincikler', 'susarsa-gelincikler-seckin-tok-ljnpa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya gelincikler bir gün susarsa

Kim sular onları? 

Yan yan geçen bir ihtiyar var,

Yağmur görmeden hâlimce yaşar; 

Belki çıkarsa köşkünden,

Bakarsa yamaçlara kızıl kızıl; 

Ağlayan bir uğur böceği görür,

Hisseder gelinciğimi.

Önce okşar mariz bir halde,

Sonra su verir herhalde.

Ya susarsa gelincikler

Kim söyler hasret şarkılarını; 

Kim ağlar yârenlerin gidişine? 

Dayanamam bu hale,

Susturmayın gönlümün sesini

Ölsem bile…', 'Ya gelincikler bir gün susarsa Kim sular onları?  Yan yan geçen bir ihtiyar var, Yağmur görmeden hâlimce yaşar;  Belki çıkarsa köşkünden, Ba...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Tok']::text[], 8.5, '{"poet":"Seçkin Tok","poet_slug":"seckin-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/susarsa-gelincikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Veda Umudu', 'bir-veda-umudu-seckin-tok-eassg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bel çantama resmini hapsettim

yüreğime seni

belkilere güneş ne zaman vurursa

görkemin gölgeler yüreğimi

sevinç adlı bulutum düşecek sabahına

oltama takılan bir akça karanlık

nasıl sürer bu sancı bu kadar

kim bilir sıradanca

biz istersek gurbet vazgeçer gitmekten

yarına kürek çekmek de neymiş

tek dileğim tutuklu kalmak sana

barış kokan bir ses geliyor

sen fısılda

ayrılmayalım diye

şimdi oturuyorum köşemde

kendi halimde

karışık saçlar arasında sana hasret

tütsü kokan bir güvercin ile

baş başa bir gece bekliyorum

dalıvereceğim bir anda gözlerine

tek umudum bu

kusursuz güzel bir sima canlanacak

bu gece matinemde

bizim aşkımız gökkuşağı eteğinde

geyiklerin çektiği bir araba

balık tutmak serpilmiş yüreklerimize

yaşanmayan yılların anısına

sağırım bilirim

duyamam hiçbir şeyi istesem de

yalnızlık korkusu ve dostluğu ile

büyüyüverdim birden

akışı gözlerinin sorgularıma

uyumayı unutturur oldu

zafer esintisi ile kayıp bir ruhun dansı

melekler şarkıları çaldıkça

notaları kaybeden bestekar benim

seviyorum dedikçe taş yağdı kalbime

renksiz düşsüz bir yaşamdı aslında

tüm yaşadıklarım

özlem korkusu sardıkça içimizi

yaklaşıyoruz birbirimize

anlamsız gelen sevgiler bırakışması

ayrılık neden

dalıvereceğim sahilimden gece yarısı

gençliğimin kıyısındaki

zanlılar gölüne

ve eyvallah eden bir sevda masalı

titreterek üşütecek içimizi

bilirim ben

bilirim

sahil banklarındaki sevgilileri

aşk destanlarını

unutulmaz bir veda öpücüğü tek hediyen

sılaya dönüş yolu nerde diye

soracağım bekçilere bir gece

bu gece

sen gelmeyeceksin diye

sazlıklarda öteceğim ben

adın dudağımdan sarkmazsa

bu gece

(...önce başladı ama güz 2004’te bitti.)', 'bel çantama resmini hapsettim yüreğime seni belkilere güneş ne zaman vurursa görkemin gölgeler yüreğimi sevinç adlı bulutum düşecek sabahına...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Tok']::text[], 8.5, '{"poet":"Seçkin Tok","poet_slug":"seckin-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/bir-veda-umudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Olsun', 'gecmis-olsun-seckin-tok-9b9y1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geçmiş olsun! 

vedalarımız, iç çekmelerimiz, gece nöbetlerimiz; 

hayallerimiz, tutkularımız, anılarımız; 

unuttuklarımız, vazgeçtiklerimiz; 

hedeflerimiz, inançlarımız, iç dünyalarımız; 

karanlıklarımız, soluşlarımız, sorularımız; 

cevaplarımız, cevapsızlarımız; 

aç karnımız, paramız; 

aşka dair her noktamız

ve elbette ki

insanlığımız

geride kaldı tamamen

hiç dönülmeyecek geriye bundan böyle! 

öyle olmalı zaten

bitti…

bitmeliydi

bitmiş…

bitmiş mi? 

geçmiş olsun! 

ömrümüz şafaklarla harcanmasın bir daha

çok geçmişler olsun! 

(10.12.2004 / 12.40)', 'geçmiş olsun!  vedalarımız, iç çekmelerimiz, gece nöbetlerimiz;  hayallerimiz, tutkularımız, anılarımız;  unuttuklarımız, vazgeçtiklerimiz; ...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Tok']::text[], 8.5, '{"poet":"Seçkin Tok","poet_slug":"seckin-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gecmis-olsun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pembe Gece', 'pembe-gece-oguz-duzgun-jn1k1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akıyor ikliminden tenlerce ihtilal gecelere muhal

Bir yangına gebedir hayır değil şerdir, nardır, yardir bu hal

Şu yürekte senin için bir şeyda bülbül uyanık figanda

Gel bu gece gülüm güldür yüreğimi, güldür gece, bende kal

Irmaklar coşar, setler yıkılır, bir sel koşar, tutar yakalar

Bir lahza çırpınır, buselerinden akan yağmurda dudaklar

Sonsuzluk akın eder, binlerce atlı kılıçlar ellerinde

Ruhaniler feryat figan çarpışır, kaçar aşktan hep korkaklar

Şimdi ihtilal zamanı yüreklerce, cehennemlere inat

Güller şahına sunulmalı bu feryat, bu hayat, bu nakarat

Bir pembe gecedir çeşm-i siyahınla buluşma zamanı yar

Akıştır yüreğimden bir arzudur ötelere  bu serenat', 'Akıyor ikliminden tenlerce ihtilal gecelere muhal Bir yangına gebedir hayır değil şerdir, nardır, yardir bu hal Şu yürekte senin için bir şe...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pembe-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-ozgur-kokturk-fj3zs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni derken duymak mutluluğu

Ve hissetmek yüreğindeki sevinci

Anlamak...

Ağlamak kolay değil

Kolay değil seni yazmak dizelere

Adını harf harf, hece hece

İşlemek, örmek kelimelere

Ne dilemek seni senden

Ne de dilenmek umutsuzca

Seni sen olduğun için sevmek

Seviyorum diyebilmek...', 'Seviyorum seni derken duymak mutluluğu Ve hissetmek yüreğindeki sevinci Anlamak... Ağlamak kolay değil Kolay değil seni yazmak dizelere Adın...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seviyorum-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-durmus-karakus-f31oa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sakın ha aldırma çileye derde,

Bunları çok çabuk aşarsın Baba

Ağzından kötüsöz çıkmaz biryerde

Sen hep şerefinle yaşarsın Baba.

Şefkatle kol kanat açarken bize,

Ciğerde hastalığa almışsın vize

Yer yoktur kalbinde karabir ize

Sen hep şerefinle yaşarsın Baba.

Bizim üstümüzde çoktur emeğin 

Herkesede yeter aşın yemeğin

Söze hakkıyoktur birkaç ineğin 

Sen hep şerefinle yaşarsın Baba.

Duygularım katkat kabardı yine,

Sanki Dev sokmuşlar küçük bir ine

Çoğu değişirken parayı Dine,

Sen hep şerefinle yaşarsın Baba.

Şu anda birdöksem gönül bendimi,

İnanki dolupta taşarsın Baba.

Şerefsizler bir b... sansın kendini, 

Sen hep şerefinle yaşarsın BABA.', 'Sakın ha aldırma çileye derde, Bunları çok çabuk aşarsın Baba Ağzından kötüsöz çıkmaz biryerde Sen hep şerefinle yaşarsın Baba. Şefkatle kol...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baba-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkına Sus/a/rım', 'askina-sus-a-rim-omer-bolat-m2849', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yandım...

Yandıkça,

Aşkına susa/rım...

Yetmez! 

Kül et beni,

Saçının teline

Kâkül et...

Söylemeye dilim aciz,

Yazmaya kelimeler yarım...

Aşkına sus/arım...

18 Haziran 2005

ALACA', 'Yandım... Yandıkça, Aşkına susa/rım... Yetmez!  Kül et beni, Saçının teline Kâkül et... Söylemeye dilim aciz, Yazmaya kelimeler yarım... Aşk...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askina-sus-a-rim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir ve Gül (Şiir Balığı)', 'siir-ve-gul-siir-baligi-nurol-banabak-cthxp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bugün de gidiciyim dün de gidici

Bu sabah güne şiir okuyarak başladım

Softanın her işten önce besmele çekmesi gibi

Günden önce çektim şiiri yüreğime

Siz aç karnına şiir sever misiniz

Ben bugün de gidiciyim dün de gidici

Ama gitmedim

Bir şiire apuskalım* vardı, bırakıp gitmedim

Öksüz kalmasın diye

Doğmadan önce

Bir şiire dokun göreceksin

Hele seherle dokun göreceksin

Okumak yetmez dokun göreceksin

Özleminin özlediğini ve hüznünü sevdiğinin

Ben bugün de gidiciyim dün de gidici

Ben bugün de gidiciyim dün de gidici

Hepiniz hepimiz gibi gidici

Hepiniz hepimiz değin

İki sap gül kesip koyarsam vazoma bugün

Ki koyacağım

İki dize çiziktirirsem defterime

And olsun

Hele bi de akvaryumumu donatayım bugün

Su balıklar

Sular balıklar

Melek lepistes envaitürlüsü

Bir de şiir balığı

…

Gidici gitmez olur

Bu şiir bitmez olur

*)  apuskal: başlanılmış iş, sıra, düzen 

(bir yerel dil, olasılıkla Rumca’dan)', 'Ben bugün de gidiciyim dün de gidici Bu sabah güne şiir okuyarak başladım Softanın her işten önce besmele çekmesi gibi Günden önce çektim şi...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/siir-ve-gul-siir-baligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Senden Sonra-', 'senden-sonra-dursun-elmas-f95f1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gittikten sonra hayatımdan; 

Hiç bir şeyin artık tadı kalmadı

Ne gezdiğim şu şehrin 

Ne solukladığım nefesin... 

Ne şiirde hecelerin 

Ne ay ışığı gecelerin... 

Ne şarkıdaki nakaratın 

Ne de sensiz yaşadığım hayatın... 

Ve sen gittin diye, 

Çiçekler suya küstü, 

Yapraklar büktü boynunu... 

Bülbüller ağlamıyor gül için

 Leylekler yuvasına dönmüyor, 

Bölük bölük uçmaz oldu turnalar...

Sen gittikten sonra hayatımdan; 

Yaşamın da bir anlamı kalmadı

Kırağı düştü ballıbabaya 

Bal vermez oldu arıya... 

Olmuyor artık pervane 

Kelebekler ışığa... 

Geçmez oldu kapımızın önünden ''sevda yüklü kervanlar'' 

Seni anlatmıyor

Daha seni hatırlatmıyor 

Artık beni ağlatmıyor; o eski içli şarkılar…

Sen gittikten sonra hayatımdan; 

Gündüz karaya büründü 

Denizin sonu göründü... 

Rahmet akmıyor göklerden 

Umut uçtu yüreklerden...

embed src=''http://www.antoloji.com/siir/media/36/www_antoloji_com_272236_855.MP3''', 'Sen gittikten sonra hayatımdan;  Hiç bir şeyin artık tadı kalmadı Ne gezdiğim şu şehrin  Ne solukladığım nefesin...  Ne şiirde hecelerin  Ne...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/senden-sonra-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felsefe', 'felsefe-omer-bolat-b3qal', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beşerin aşkı,

Beşeri bağlamaz! 

Beşerin haline, 

Beşer ağlamaz! 

Beşer için maşuk yoktur,

Rahman''dan başka...

Beşer; beşer için,

Düşmezmiş aşka! ... 

16 Haziran 2005

ANKARA', 'Beşerin aşkı, Beşeri bağlamaz!  Beşerin haline,  Beşer ağlamaz!  Beşer için maşuk yoktur, Rahman''dan başka... Beşer; beşer için, Düşmezmiş a...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/felsefe-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-mikdat-bal-s4ta1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya ya gözlerimi, açınca yanımdaydı

Rızkım olan ilk sütü, içince yanımdaydı

Ağlarken yanımdaydı, gülünce yanımdaydı

Hasta olup rahatsız, olunca yanımdaydı

Annem beni koynuna, alınca yanımdaydı

Bazen gurbete gidip, gelince yanımdaydı

Annem hediyeleri, bölünce yanımdaydı

İlkokula ilk kayıt, olunca yanımdaydı

Derslerime çalışıp, bilince yanımdaydı

Kaytarıp oyunlara, dalınca yanımdaydı

En ufak bir hatamı, bulunca yanımdaydı

Öğretecek bir şeyi, olunca yanımdaydı

Sorduklarıma cevap, bulunca yanımdaydı

Hele onu çok iyi, bilince yanımdaydı

Ruhunca yanımdaydı, gönlünce yanımdaydı

Camide yanımdaydı, kılınca yanımdaydı

Gücünce yanımdaydı, malınca yanımdaydı

Okuyup diplomamı, alınca yanımdaydı

Yaşım gelip askere, salınca yanımdaydı

Teskere alıp günüm, dolunca yanımdaydı

Babam her an aklıma, gelince yanımdaydı

Asla geri kalmazdı, halince yanımdaydı

Yoklukta yanımdaydı, olunca yanımdaydı

Başımda ki saçların, telince yanımdaydı

Babamın kıymetini, baba olunca bildim

Babam ne kadar haklı, o zaman diyebildim', 'Dünya ya gözlerimi, açınca yanımdaydı Rızkım olan ilk sütü, içince yanımdaydı Ağlarken yanımdaydı, gülünce yanımdaydı Hasta olup rahatsız, o...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/babam-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkün Farkı', 'turkun-farki-tuncay-akdeniz-tm542', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evrensel dünyaya açık kapımız

Dostluk olan yerde ırkına bakma

Her kıtaya gider bizim yolumuz	

Doğu batı güney şarkına bakma

İnsanlığı bilir insan severiz

Bize taş atana ekmek vereniz

İkicilik yapma demiş atamız

Fitne fesat düzen şirkine bakma

Din dil ırk ayrımı yapmaz azında

İsayım Musayim İslam özümde

Yürürüz Muhammed kuran izinde

Üstüne giydiği kürküne bakma

Aramıza girip düzen bozanlar

Dost görünüp kuyumuzu kazanlar

Ajan gibi aramızda gezenler

Düzen bazın dönek çarkına bakma

Tuncay in vatanı güzel yurdumuz

Atamın izinde gider yolumuz

Dünyaya bedeldir bizim ordumuz

Sahtekarın fazla farkına bakma', 'Evrensel dünyaya açık kapımız Dostluk olan yerde ırkına bakma Her kıtaya gider bizim yolumuz	 Doğu batı güney şarkına bakma İnsanlığı bilir ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/turkun-farki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seçti', 'seni-secti-sait-muharrem-say-qehlh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Giderken avuçlarında götürdün

Koskoca şehrin

Bakire inciten ıssızlığını

Kırık aynalardan yaşama akan

Kırık umutların

Hiçbir yola ulaşmayan çaresizliğini

Gözlerinde götürdün

Mağlup bir savaş gemisinin

Ardına takılı

Küçük bir filikanın boşluğa bakan gözleri

Saçlarında terketti şehri

Hafif meşrep notalarla

Aynı masada asla sarhoş olmayan

Ağıtları yüreğinde götürdün.

Her gece saklanacak bir yeri olan

İstasyon tenhalığı seninle gitti

Ve iyiliği anlatan kötülük

Daha fazla iyiliğe açılan

Sevgi ardına bakmadan seni seçti

(04.09.2001)', 'Giderken avuçlarında götürdün Koskoca şehrin Bakire inciten ıssızlığını Kırık aynalardan yaşama akan Kırık umutların Hiçbir yola ulaşmayan ç...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-secti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz ayrılamayız', 'biz-ayrilamayiz-meryem-i-sler-kpjh6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İkimizde sustuk konuşamadık

Duygularımızı anlatamadık

Düşündük  inceden derinden 

Neydi bizi bu hale getiren

Sevgimizmiydi yoksa eksilen

Aşkımızmıydı kalbimizden eriyip giden

Yoksa zamanmıydı acele kararlar verdiren

Elbette bir sebebi vardı bizi bu kadar üzen

Yan yana oturuyorduk iki yabancı gibi 

Kaçırıyorduk gözlerimizden gözlerimizi

Yutuyorduk  öfkeyle birbirimizi kıracak sözlerimizi

Oysa biz böylemiydik kavuşmak için neler feda etmiştik

İlk defa tanışıyor gibi birbirimize bakıp gülümsedik

Susmamıza darılmamıza hiç bir sebep yok dedik

Bir kez daha anladıkki  birbirimizden kopamayız

Biz bir elmanın iki yarısı yız  ayrılamayız', 'İkimizde sustuk konuşamadık Duygularımızı anlatamadık Düşündük  inceden derinden  Neydi bizi bu hale getiren Sevgimizmiydi yoksa eksilen Aşk...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biz-ayrilamayiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceden Sabaha', 'geceden-sabaha-taner-nisanci-qjgn5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hele çıkış bitsin de gör inişi

Yokuştan düzlüğe elbet çıkar yol

Hele şafak söksün de gör güneşi

Geceden sabaha elbet gider yol

Kapılar kapansa bir bir yüzüne

Kanlı yaşlar dolsa tek tek gözüne

Sitemler düşmesin ap ak sözüne

Geceden sabaha elbet gider yol

Dost kalmamış olabilir yanında

Gonca güller solabilir canında

Çıkmaz yolda kalabilir anında

Geceden sabaha elbet gider yol

Yorsa seni sahte bakış gülüşler

Yalan olsa sözde alış verişler

Hak’tan Hakka özde gidiş gelişler 

Geceden sabaha elbet gider yol

Bir Garip benim; Ümidin solmasın

Hiç mi hiç,boynun bükülü kalmasın

Mevlam elemli kedere salmasın

Geceden sabaha elbet gider yol

18/06/2005', 'Hele çıkış bitsin de gör inişi Yokuştan düzlüğe elbet çıkar yol Hele şafak söksün de gör güneşi Geceden sabaha elbet gider yol Kapılar kapan...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/geceden-sabaha-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasam Gözlüm', 'yasam-gozlum-sair-gaddar-16-3lwu4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yasam Gözlüm

Hayatıma girdin sen,

Canımı aldın bedenimden,

Cansız kaldı bu beden,

Nerdesin be yaşam gözlüm.

...

Hayalin var şuan karşımda,

Düşünüyorum seni sensiz akşamlarda,

Adını okuyorum dağlarda taşlarda,

Nerdesin be yaşam gözlüm.

...

Şimdi ellerim bomboş ve çıplak,

Sen gittin saçıma düştü ak,

Gençliğim bitti seni beklemekle,

Nerdesin be yaşam gözlüm.

...

Sen özlendin özlemedin,

Sen sevildin sevmedin,

Sen unuttun unutulmadın,

Nerdesin be yaşam gözlüm.

...

Sadece sende hayat var,

Sadece sende huzur var,

Bu can seni taşıdığı sürece yaşar,

Nerdesin be yaşam gözlüm.

...

Artık ben sensizim,

Sevgi doluydu yüreğim,

Sayende tükendim bittim,

Nerdesin be yaşam gözlüm.

£zgim seni seviyorum...

Unutulamayacak vazgeçilemeyecek kadar güzel

Ve özelsin (Izdırap Gözlüm) £zgiiiiiiiiiiiiiiiiiiiiiiiiiii

İdris £zgi', 'Yasam Gözlüm Hayatıma girdin sen, Canımı aldın bedenimden, Cansız kaldı bu beden, Nerdesin be yaşam gözlüm. ... Hayalin var şuan karşımda, D...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yasam-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gözlü Çocuk', 'mavi-gozlu-cocuk-sadik-dogan-c1yzx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'acıların gölgesinde bir hayat sürersin. 

kendi sahipsizliğinde kendinle boğuşur, 

feleğin çarkına tükürür geçersin. 

Sen, 

       Mavi Gözlü Çocuk! 

sustukça anlatırsın derdini 

her seferinde bir başka yanında 

her yanının bir başka tarafında korursun gizemini. 

sus, sakın konuşma! 

Sen, 

      Mavi Gözlü Çocuk! 

konuşursan ele verirsin kendini. 

kandırırlar, gök mavi 

deniz mavidir diye. 

inanma! .. 

inanma sen, 

                 Mavi Gözlü Çocuk! 

her şey karanlık, her yer puslu. 

bir tek, 

bir tek senin gözlerin mavi. 

kıvırcık saçlarına ak düşerse bir gün 

gözlerinin feri sönerde 

bu şiir anlamını yitirirse bir gün.

Sen, 

       Mavi Gözlü Çocuk! 

işte o zaman 

yeniden doğar, 

kalbime yeniden girersin. 

belki o zaman 

sen de beni seversin. 

sen, 

Mavi Gözlü Çocuk! .. 

18.07.2005/Osmancık', 'acıların gölgesinde bir hayat sürersin.  kendi sahipsizliğinde kendinle boğuşur,  feleğin çarkına tükürür geçersin.  Sen,         Mavi Gözlü...', ARRAY['Türk Edebiyatı','Şiir','Sadık Doğan']::text[], 8.5, '{"poet":"Sadık Doğan","poet_slug":"sadik-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mavi-gozlu-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kor Bakışların III', 'kor-bakislarin-iii-fatih-taskin-sa94w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cama vuran yüzün yarısındaydı

Beni aşık eden yar bakışların

Hüzün girdabına düştüğüm andı

Umarsız tavırlı yan bakışların

Güneşte yağmurdun içime akan

Bakışın koruydu yağmurda yakan

Islağın nemiydi gözde buğlanan 

Senden bana yağan yaş bakışların

Dalında kurumuş çukur gamzeydi

Kokusu  yitilmiş   kırık  buseydi

Ben ona baktıkça  beni  eritdi

Alevlenip vuran  har bakışların 

siyahbereli

haziran-05', 'Cama vuran yüzün yarısındaydı Beni aşık eden yar bakışların Hüzün girdabına düştüğüm andı Umarsız tavırlı yan bakışların Güneşte yağmurdun i...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kor-bakislarin-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Arkadaş’a', 'sair-arkadas-a-nurol-banabak-afxzw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Olmaz ki, kimse kimseyi sevemez

Ama hiç kimse.”

telgrafındı teller eskiden

şimdi beyinler telde

taşır vurur bizi birbirimize

ben seni hoş bulurum

hoş bulurum dizelerini hüzünlerini

korkularını kavgalarını hoş bulurum

öfkelerini kıskançlıklarını falan

öykün benzer öyküme hoş bulurum

yıl böyle iki bin beş sayarken

bir sanalda sallanmakmış ikimizin kaderi

Hoca Nasrettin’e “keçiboynuzu ikram etmişler; 

-bir gram bal için, bir çeki odunu çiğneyemem! , demiş”

biz çiğner dururuz ikimiz

ben seni hoş bulurum

kimi “popüler şair”dir kerametinden

ne nasıl hikmetse

şiirin ilmine varmıştır belki de

veya vahiy almaktadır

şerbetlidir veya

veya hükümette adamı vardır

ben seni

en çok “antoloji almıştır” öbürü

tümünü almıştır da sana bana kalmamıştır bi’şey

“günün şairi”dir

“top yüz”dür ya da ne bileyim

topluk uymaz ki sana

ben seni hoş bulurum

yani sen ağzınla kuş tutsan

hoş bulanın kırk fırın ekmek yese

olsa olsa ikimizde göbekleniriz

hadi yine iyisin iyisin

sana av eti bana kuru ekmek

ben seni hoş bulurum

köyde hasret yolda hasret gurbette

işte tatilde hasret

yare hasret söze hasret 

sana şiir dize hasret şairim

gam yeme

“Varsın seni ömrünce azabın kolu sarsın,

Şair sen üzüldükçe ve öldükçe yaşarsın! ”', '“Olmaz ki, kimse kimseyi sevemez Ama hiç kimse.” telgrafındı teller eskiden şimdi beyinler telde taşır vurur bizi birbirimize ben seni hoş b...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sair-arkadas-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Oğlum', 'can-oglum-suheyla-kurnaz-0b3uq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resmini bağrıma bastım oğlum

Dağlardaki karlara seni sordum. 

Denizlerdeki  tüm balıklara,

Yollardaki minik karıncalara,

Havada uçan kuşlara seni sordum.

Duvarlardaki afişlere,

Tren istasyonlarına, 

Otobüs duraklarına,

Seni sordum oğlum.

Yüreğim yanıyor, gözlerimden kan damlıyor.

Aç mısın açıkta mısın, 

Hangi köşe bucaktasın,

Hangi yaban ellerdesin oğlum? ...

Güneşe sordum  seni,  gördü mü  diye

Ay’a yalvardım, sana ışık olsun diye

Rüzgarlara göğsümü gerdim kokunu getirsin diye

Dağlara haykırdım, karşılık versin sesin duyayım diye

Tanrıya yalvardım kol kanat gersin diye 

Adaklar adadım gelirsin diye...

Buram buram kokun gelir uzaklardan, 

İçim kan ağlar, yüreğim sızlar.

Bu acıya hangi yürek dayanır

Hangi dost teselli olur.

Gözüm yollarda kulağım kapıda

Gel artık dön yuvana

Neredesin can oğlum

Yeter artık dön yuvana

Dön can oğlum dön...

SuheylaKurnaz.com - Kişisel Web Sitem

SuheylaKurnaz.com - Kişisel blog Sayfam', 'Resmini bağrıma bastım oğlum Dağlardaki karlara seni sordum.  Denizlerdeki  tüm balıklara, Yollardaki minik karıncalara, Havada uçan kuşlara...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Kurnaz']::text[], 8.5, '{"poet":"Süheyla Kurnaz","poet_slug":"suheyla-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/can-oglum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanadı Yüreğim', 'kanadi-yuregim-sair-gaddar-16-spmos', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kanadı Yüreğim..

Zaman gece yarısı

Ve yine seni düşünüyorum

Resmine bakıyorum göz yaşlarımı tutamıyorum

Ah be bi tanem yinede kanadı yüreğim

...

Seni düşünmekten yatamıyorum

Uykusuz kalıyor günlerimi harap ediyorum

Seni çok seviyorum be bitanem

Ve yinede kanadı yüreğim.

...

Ah! be bitanem keşke  yanımda olsaydın

Ellerini tutup boynuna sarılsaydım

Neler çektiğimi,aklımdan

Çıkmadığını bir bir anlatabilseydim

Ah! be bitanem yüreğim kanıyor.

...

Aşkımın adını ölümsüzlük koydum

Ve artık bende ölümsüz biriyim

ßen kod adı garip şairim

senden başkasını sevebilirmiyim

...

Gözlerim ıslak ve yorgun

Güneş batıyor,gece başlıyor,ve hala deniz durgun

Etrafıma bakıyorum ve sen hala yoksun

Ah! ah! ve yinede kanadı yüreğim.

...

Oysa ne hayallerim vardı geleceğe dair

ßen kod adı garip şair

ßu şair senden başka kimi sevebilir

Ah! ah! ve yinede kanadı yüreğim.

...

Gözlerin cennet bahçesi

Dişlerin inci tanesi

unutabilirmi bu kalp seni

Ah Ah! ve yinede kanadı yüreğim.

...

ßaktığım her yerde seni görüyorum

Yediğim ekmekte,içtiğim suda ismini okuyorum

Ve vakit gece yarısı seni düşünüyorum

Ah! be bitanem kanıyor yüreğim

...

Sana yaklaşıyor konuşamıyorum

Uzaklaşmak istiyorum seni bırakamıyorum

Sevgilim ben sensiz yapamıyorum

Ah! be bitanem tekrar kanadı yüreğim.

...

Unutma sevgilim senden vazgeçemem

İstersen canımı canına eklerim

Sevmiyorsan söyle buralardan giderim

Sevgim rahatsız ettiyse özür dilerim

Hayatımı uğruna feda ederim

Sonra bu diyardan çeker giderim

Ah! be bi tanem yinede kanadı yüreğim.

Ezgim yüreğim kanıyor

idris Ezgi (ızdırap gözlüm)', 'Kanadı Yüreğim.. Zaman gece yarısı Ve yine seni düşünüyorum Resmine bakıyorum göz yaşlarımı tutamıyorum Ah be bi tanem yinede kanadı yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/kanadi-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Aşkı Yenemez', 'sair-aski-yenemez-mustafa-oz-dh2dc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen

Her gece ağlarsın

Ben

Her gece yanarım

Leyla

Alışamadım acıya

Ölüm

Ümitsiz bir aşktan iyimidir

Şair 

Ölümü yenemez

Bu yüzden

Aşkı hiç sevmez', 'Sen Her gece ağlarsın Ben Her gece yanarım Leyla Alışamadım acıya Ölüm Ümitsiz bir aşktan iyimidir Şair  Ölümü yenemez Bu yüzden Aşkı hiç se...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Öz']::text[], 8.5, '{"poet":"Mustafa Öz","poet_slug":"mustafa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sair-aski-yenemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'd. Quantum (Quatriem ''Comment'')', 'd-quantum-quatriem-comment-dogan-ozcan-vf7i6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Avant le matin, onze heures...

Ceux qui se trouverent dans''''Il était une fois''''

se trouvaient cette fois-ci en Chine,

moi

j''éffaçais les particules de la lumiere hors de la chambre

     le doigt sur le bouton,

''''toi'''', l''une d''elles cria,

''''t''es seulement comme ''une'' entre elles,'''' continua,

''''en moi'''', ajouta,

''''il y en a des millions comme toi...''''

Je pense a ça depuis ce jour-la,

et j''ai plus de dix-neuf ans maintenant! 

je n''ai pas compris ''comment''

et ''comment'', sais pas encore ça

                  mais, comment, encore une fois,

tout le monde clairement me voit

   puisque je suis million fois

       plus petit qu''un doigt? ...

Doğan Özcan', 'Avant le matin, onze heures... Ceux qui se trouverent dans''''Il était une fois'''' se trouvaient cette fois-ci en Chine, moi j''éffaçais les par...', ARRAY['Türk Edebiyatı','Şiir','Doğan Özcan']::text[], 8.5, '{"poet":"Doğan Özcan","poet_slug":"dogan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/d-quantum-quatriem-comment-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'd. Title (I am sorry)', 'd-title-i-am-sorry-dogan-ozcan-6len5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Now,it''s my time to explain the truth; 

That sun is not as big as you thought,look,

and if there is something as world; 

                  he is not round,

the moon has never been lier,

she has never take the light from the sun,

the moon was perhaps a kind of fish

                                  lived in cold seas.,

it was the lorry who crushed the idealists,

after that day they were afraid of all the roads

nobody has died for four hundreds thousands years,

cos'' there was nothing to be man,

and because your hands weren''t enough realist,

so your past wasn''t so long,

and so

I can say

that you have almost never lived...

Now,

What can I do for you? ...

Doğan Özcan', 'Now,it''s my time to explain the truth;  That sun is not as big as you thought,look, and if there is something as world;                    h...', ARRAY['Türk Edebiyatı','Şiir','Doğan Özcan']::text[], 8.5, '{"poet":"Doğan Özcan","poet_slug":"dogan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/d-title-i-am-sorry-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gizli yar a lar', 'gizli-yar-a-lar-turgut-gundogmus-pleqw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözünde,

sevda birikir

peşinden,

bir bulut yükselir

göklere

hüznün aşka gelir

çarparsın kayalara

deniz kokusu

toprağa karışır

bulutlardan emanet

gizli bir yara

yavaşca içine taşınır

ayaklar altına

düşmenle

vuran vurana

ezen ezenedir.

birde üstüne

eşkıya misali

yalnızlık  çöker

boynun bükülür,

çığlıkları gölgede bırakan

bir ses böler

geceyi

bulutlar çarpışmakta

her nefeste

ahlar! zirveye çıkmıştır 

oysa,

gizli bir yaradır

içinde taşıdığın

gözlerin, inadından vazgeçmez

habersizdir

süzülen yaşlardan

bağrına,

ateş konmuştur

bu seferde kırılmamıştır

gururun zincirleri

genzinde

hıçkırık kalır

oysa,

gizli bir yaradır

içinde taşıdığın

artık,

dallarına tünemiştir

baykuş iniltileri

tapusu üzerine geçirilmiş 

virane bağların sahibisin

bülbül yastatır

kendisine

gül, dikenlerini hesaba katmamış

acıyı bilmemesi doğaldır.

oysa,

gizli bir yaradır

içinde taşıdığın

oklar gerilir, 

hedeftesin

heceler,kelimeler,cümleler

ardı sıra

yerlerinden firlarlar

durdurma imkani güçleşir

kemiksiz bir eserin

isabet alanındasın

oysa,

gizli bir yaradır

içinde taşıdığın

yaralı bir gönülden kalan

son yapraklar

rüzgar bütün cesaretiyle eser

siyahın hükmü 

çaresizdir,

boyun eğer kaderine

üşür güçsüzlüğün

oysa,

gizli bir yaradır

içinde taşıdığın

beyazın gölgesi

çevreler seni

ağlayanlar,kalanlardır

dönmeyeceksin! 

çaresizliğin,

omuzlar üstünde

oysa,

yaşam aralığına girenler

habersizdiler

gizli bir yaradan

güvenmek,güvenilmek

zor bir zanaattir

şimdi güvendesin,toprağın koynunda

herşeyinle bağrına bastı 

sadakatı ondandır.', 'gözünde, sevda birikir peşinden, bir bulut yükselir göklere hüznün aşka gelir çarparsın kayalara deniz kokusu toprağa karışır bulutlardan em...', ARRAY['Türk Edebiyatı','Şiir','Turgut Gündoğmuş']::text[], 8.5, '{"poet":"Turgut Gündoğmuş","poet_slug":"turgut-gundogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/gizli-yar-a-lar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurbanım', 'kurbanim-hatem-kardesler-d3o8e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir pınar başında testi doldurur,

Mahsun mahsun duruşuna kurbanım…

Bir hasret türküsü rengin soldurur,

Nazlı nazlı yürüyüşüne kurbanım…

Ak elleri saban tutar,bel tutar,

Saçı buram buram ak toprak kokar,

Yüreğinde yalnız bir aslan yatar,

Gizli gizli gülüşüne kurbanım…

         (Hasret İçimde Bir Dağ)   Kitabından', 'Bir pınar başında testi doldurur, Mahsun mahsun duruşuna kurbanım… Bir hasret türküsü rengin soldurur, Nazlı nazlı yürüyüşüne kurbanım… Ak e...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kurbanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'He Desen', 'he-desen-hatem-kardesler-wz2fr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir he desen,

Bir he desen doğunun esmer yüzlü çiçeği

Koşar gelirdim sana…

Gözlerim böyle kan çanağı olmazdı hep,

Hergün ağlamazdım böyle,yalnızlığıma,çaresizliğime.

Bir he desen,

Bir he desen geceler böyle zifiri karanlık olmazdı…

Kalemim hasret şiirlerine talim yapmazdı her gece,

Aşk deyince hasreti,seni hatırlamazdım hiç…

Bir he desen,

Bir he desen birtanem

Gönlüm böyle acıları içine gömmezdi,

Güller açardı konuştuğun yerde…

Bir he desen,

Bir he desen yaban gülüm,

Şu dinine yandığımın kentinde,

Gurbet geceleri bu kadar koymazdı bana…

         (Hasret İçimde Bir Dağ)  Kitabından', 'Bir he desen, Bir he desen doğunun esmer yüzlü çiçeği Koşar gelirdim sana… Gözlerim böyle kan çanağı olmazdı hep, Hergün ağlamazdım böyle,ya...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/he-desen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin et baba şiirine ithamımdır', 'gelin-et-baba-siirine-ithamimdir-tuncay-akdeniz-wzjhj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bülbülüm gül için çekiyor hasret 

Ansızın karşına çıkarım gülüm 

Oğlumdan cesaret senden de gayret 

Sizi bir kafese tıkarım gülüm 

İnsani gönül e bülbülü güle 

Bir mecnunum vardır salmışım çöle 

Ferhat ı görmüşler hep şirin ile 

Keremi ateşe yakarım gülüm 

Misafir et anlatayım gerçeği 

Bizim evde vardır uğur böceği 

Boş vazo sevilmez yoksa çiçeği 

Van''nın kalesini yıkarım gülüm 

Geceleri baksan yıldıza aya

Onlarda tutulmuş kara sevdaya

Çağırsan gelirim vallahı yaya

Elbet çaresine bakarım gülüm

Tuncay dalgın,dalgın sizi izlerim 

Gerçeği ne zaman görür gözlerim 

Şaka yolu ile sivri sözlerim 

Gelinlik nişanı takarım gülüm', 'Bülbülüm gül için çekiyor hasret  Ansızın karşına çıkarım gülüm  Oğlumdan cesaret senden de gayret  Sizi bir kafese tıkarım gülüm  İnsani gö...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelin-et-baba-siirine-ithamimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Tutkusu', 'deniz-tutkusu-bulent-kiroglu-44mjv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sene bir yaş daha bitiyor birkaç hafta içinde,

İçimde hala bir ümit, hala bir öfke,

Ne kadar acı çekiyorum bilmiyor ki kimse,

Görmüyor ki beni gerçek kimliğimle,

Olsun şimdi sen varsın ya, yanliz girmeyeceğim yeni yaşıma,

Belki gözümde bir damla yaş, belki sen olacaksın karşımda,

Zor tutacağım kendimi gördüğümde seni yanımda,

Sarılacağım sana, fısıldayacağım sevgimi kulağına,

Anlamayacaksın belki duyduğum bu sevgiyi sana,

Daha yeni bir hafta olmuşken, kafanı karıştıracağım aşkımla,

Adı ne ne olursa olsun, sevgi olsun hissettiğim her neyse sana,

İzin ver benimle olsun bu sevgin sen yokken yanımda,

Üzdüm seni farkında olmadan, çok mu geç af dilesem,

Değil on dokuz, yüz dokuz kere arasam,

Yine de sevsem seni senin sevgini bilmeden,

Aşkımı anlatsam sana sen beni bilmezken.

Damla damla Deniz olsun gözyaşlarım,

Denizle birlikte kaybolsun tüm yaslarım,

Götürsün beni dalgasıyla, sevincimden ağlarım.

Seni düşünürüm sensiz olduğum her an,

Aramak isterim seni, seni sevdiğimi hissettiğim an,

Karşılıksız olsa da bu aşk, bilirim yetinmesini her zaman.

Elim başında, başım göğsünde,

Bir melodi var sanki o kadife sesinde,

Şaşırma sakın sana olan sevgimde,

Samimiyim sana hiç olmadığım kadar kendime.

Belki de,

Belki de hayaldir bu uyanmam gereken,

Belki de şiirdir bu yazmam gereken,

Belki de sensin sevmem gereken,

Kimbilir belki de hayattır bu yaşamam gereken.

İsterim seninle olmak her zaman,

Aşkım demek sana, seni duyduğum her an,

Denizdir adın, bilemem seni her zaman.

Dalgalarınla al götür beni unuttuğun zaman.', 'Bir sene bir yaş daha bitiyor birkaç hafta içinde, İçimde hala bir ümit, hala bir öfke, Ne kadar acı çekiyorum bilmiyor ki kimse, Görmüyor k...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/deniz-tutkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Diyarlar', 'uzak-diyarlar-bulent-kiroglu-ojr82', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok tuttum kendimi ama olmadı hapsedemedim gözyaşlarımı içime,

Çok özledim seni ama dayanamadım hasretine baktım doyasıya resmine,

Değdi ellerim yanaklarına, dudaklarım dudaklarına, gözlerim gözlerine,

Sen birtanesin, sen benim sevdiğim yegane insansın dedim yüzüne.

Unutmak istedim çoğu zaman seni, alışmak için yokluğuna,

Kızdım çoğu zaman kendime, sen başkasını severken seni sevdiğime,

Benimsin diyorsun, beni bırakıp gidiyorsun uzak diyarlara sevdiğinle,

Acıdan hissetmez oldu artık yüreğim, seni düşündükçe sevgilinle.

Bakma artık bana öyle mahzun, ne söyleyeceksen söyle nasıl olsa adım olgun,

Bekletme artık beni böyle mahzun, bitireceksen bitir etme artık beni yorgun,

Suçlusu benim bu aşkın, tutamadım kendimi sen öyle dururken durgun,

Daha fazla veremezsen olsun, verdiğinle de yetinirim yeter ki senden olsun.

İşte yine karşımdasın bakıyorsun bana ama duyamıyorsun beni,

Gizliyor su sesleri, oysa haykırıyorum her sabah seviyorum diye seni,

Geç yatıyorum bekliyorum seni, arayacaksın diye beni,

Günler geçtikçe anlıyorum seni, sevdiğinle olunca unutuyorsun beni.

Geçmiyor artık boğazımdan lokmalar, yenmeden kalıyor curry ve safranlar,

Siliyor kumlarda bıraktığımız ayak izlerimizi uzaktan gelen hırçın dalgalar,

Götürüyor sevdiğinle seni uzak diyarlara içimizde kopan fırtınalar,

Anlatıyor tekrar bana beni sevenin bir tek onlar olduğunu aynalar.

Soğuk bir rüzgar esti odamdan, üşüttü beni taa uzak diyarlardan,

Sesin de çıkmadı bu akşam, aradın da duyamadım mı ud ve kanundan,

Başka sesler ninni oldu bu akşam, rüzgarın soğuk nefesi sardı omzumdan,

Seni düşündüm durmadan, hiç olmazsa gelir uyandırır diye rüyamdan.

Belki de sendin beni uyutan, sendin beni varlığınla rüyamda avutan,

Gerçek oldu hayallerim, rüyamda da olsa sendin beni yaşatan,

Yaşadım seninle en güzel anlarımı bu dünyada sen hayal de olsan,

Unuttum gerçekleri sen yokken ey hayalim gel de uyandır beni bu rüyadan.

Bekliyor mutlu günler seni, sen mutlu oldukça mutlu edecek günler beni,

Çoktan hakettin bu günleri, mutlu edecek bu günler seni ve beni,

Ders olsun geçmiş ikimize, mutlu olalım mutsuz etseler de bizleri, 

Isıtalım birbirimizi, buhar yapalım hatırlamak istemediğimiz geçmişimizi.

İki ay önce girdim ben yeni bir yıla, gecenin bir vakti sevdiğimi bulunca,

Yeni bir yıl sanki her günüm onunla, yaşarım binbir gece o benim olunca,

Olsun, olmasın yanımda bu gece, nasıl olsa benim için sıradan bir gece,

Yeter ki ayırmasın tanrım bizi, ben onun, o benim olunca.

Bitsin artık mutsuzluklar bugün, biten sensiz bir yıl gibi,

Gelsin artık sevdiğim, özlemle beklediğim aşkım gibi, 

Olsun artık her günümüz, birlikte yaşanan bir rüya gibi,

Bırakmasın melekler bizi, benim sevdiğim gibi.', 'Çok tuttum kendimi ama olmadı hapsedemedim gözyaşlarımı içime, Çok özledim seni ama dayanamadım hasretine baktım doyasıya resmine, Değdi ell...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/uzak-diyarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Pazar', 'bugun-pazar-bulent-kiroglu-db6jt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En son korkuyorum dedin beni de korku içinde bıraktın giderken,

Ne saklıyorsun benden, ne zaman anlatacaksın zaman akıp giderken,

Bak hava bile kapalı bugün ayrılığımıza dayanamadı açarken,

Gök gürültüsü ile uyandım sanki senin haykırışlarındı güneş doğarken.

Uzun uzun yürüdüm ıslandım yağmurda bugün, seni düşündüm,

Sahile vuran dalgalar sanki sendin, geliyorum diye haber gönderdin,

Gözyaşlarımı tutamadım, ağladım bugün, seni düşündüm,

Ara sıra bulutlar arasında göz kırpan güneş sendin, bana göründün.

Bir ara nefes alamadım, tuttum nefesimi, seni aradım,

Sen yoktun, ama anlattım sana bugünü, seni yaşadım.

Yürüdüm yosun kokan sahilde bugün, seni kokladım.

Sen yoktun, ama oturdum çimlere bugün, saçını okşadım.

Rüzgar esmeye başladı birden, kollarımı açtım, seni kucakladım.

Sorma nasıl geçti günün diye, seni bekledim durdum geleceksin diye,

Ama yine haber gönderdin sen vapur sirenleriyle az kaldı geliyorum diye,

Hava karardı yine bu akşam, ışıkları yandı yine koca şehrin ama nafile,

Sevdiğim yanımda olmayınca, hatırladım geçmişi, özledim seni yine.

Heyecanlandım bugün bir çocuk gibi, seni kucaklayacağım yarın gibi,

Seni düşündüm her gün, her güne bir şiir yazdım, bunun gibi,

Sana sarılmak, sana dokunmak istiyorum artık bir insan gibi,

Ne olur bırakma tut beni.', 'En son korkuyorum dedin beni de korku içinde bıraktın giderken, Ne saklıyorsun benden, ne zaman anlatacaksın zaman akıp giderken, Bak hava b...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bugun-pazar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüngür Hüngür Ağladım', 'hungur-hungur-agladim-muammer-baydere-xkmcw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soldu yine gönlümde çiçekler büktü boyun

Coşkun seller gibiydim gözyaşıyla çağladım

Kapımdayken mutluluk kaderin bana oyun

Ettiğini anladım hüngür hüngür ağladım

Sen ümitsiz bir anda geliverdin yanıma

Sana kızıp ah etmek yakışmazdı şanıma

Çok kısa bir sürede ayrılığın canıma

Yettiğini anladım hüngür hüngür ağladım

Son günlerde nedense aşkım düştü tuzağa

Ben sana sarılırken sen sarıldın kazağa

“Yanındayım” diyorsun oysa ruhen uzağa

Gittiğini anladım hüngür hüngür ağladım

Sanki vurgun yemiştim kalakaldım öylece

Kör olmayı istedim başkasıyla görünce

Dünyalara sığmayan aşkımızın böylece

Bittiğini anladım hüngür hüngür ağladım', 'Soldu yine gönlümde çiçekler büktü boyun Coşkun seller gibiydim gözyaşıyla çağladım Kapımdayken mutluluk kaderin bana oyun Ettiğini anladım ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hungur-hungur-agladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-bulent-kiroglu-gk728', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir korku kapladı içimi, sanki son görüşümdü seni,

Hata mı ettim alışmakla, çaresiz bekledim gelişini,

Anlamadım ne oldu bana, gerçek sevgiyi mi öğrettin bana? 

Haber gelmeyince senden, merak ettim düşündüm kara kara,

3 gün geçti, kaldi 2 gün gelişine, aradım seni özlemimle,

Sıcaklığını özledim, sarılmak istedim seni karşımda görünce,

Saatler geçmek bilmiyor sen yokken yanımda,

Gün sayıyorum sana kavuşmak için tüm zamanımda,

Bir ses, bir mesaj da yeter bana, ne olur anlasana,

Bona Fide yokmuş gibi davranmasana,

Kalbim atmaz oldu, sesim çıkmaz oldu,

Sensiz bir hayat bana zehir oldu.

İstesen de istemesen de söylemeliyim sana,

Sanırım aşık oluyorum sana, ne olduğunu anlamasam da,

Beklentilerim fazla değil senden, 

Yeter ki yanlız bırakma beni yeniden,

Keşke izin versen de sokulsam aniden,

Sevebilsem seni suçluluk hissetmeden.

Keşke uyusam sen gitmeden, öpsen beni giderken,

Uyanmasam uykudan özlemesem sen yokken,

Girsen rüyama, benimle olsan ben ağlarken,

Öperek uyandırsan beni geldiğinde birden.

Sana hasretimi dile getirir bu satırlar,

Söyleyemediğim ama hissetiklerimi açıklar,

Bunlar da olmasa beni ancak dört duvar paklar,

Beni ancak senin gibi dostlar anlar.', 'Bir korku kapladı içimi, sanki son görüşümdü seni, Hata mı ettim alışmakla, çaresiz bekledim gelişini, Anlamadım ne oldu bana, gerçek sevgiy...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/korkuyorum-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yararım...', 'neye-yararim-muammer-baydere-rxftr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söylediğin sözlerde yazdığın her şiirde

Haddim olmasa bile hep kendimi ararım

Kalabalık içinde yalnızım bu şehirde

Sensiz ne iş yaparım söyle neye yararım

Her satırda bir ima üstü kapalı sözler

Fakat nerden bileyim kime ağlar o gözler

Hep sonuçsuz kalıyor sürdüğüm bütün izler

Sensiz ne iş yaparım söyle neye yararım

Korkum hata yapmaktır sorun değil gururum

Bu yüzden itirafı senden bekler dururum

Seni kırmış olursam bil ki beni vururum

Sensiz ne iş yaparım söyle neye yararım

Benim için kolay mı ben nasıl diyeceğim

Ne olursun çekinme seni mi yiyeceğim

Ateş denen gömleği bende mi giyeceğim

Sensiz ne iş yaparım söyle neye yararım

Son defa söylüyorum benden cevap bekleme

Gururuna yenilip derdine dert ekleme

Aşk dururken gönlüme ayrılığı yükleme

Sensiz ne iş yaparım söyle neye yararım', 'Söylediğin sözlerde yazdığın her şiirde Haddim olmasa bile hep kendimi ararım Kalabalık içinde yalnızım bu şehirde Sensiz ne iş yaparım söyl...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neye-yararim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmin Kaldı Elimde', 'resmin-kaldi-elimde-muammer-baydere-sfk7l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düne kadar mutluyduk ne oldu aşkımıza

Bu dünyada tek senin ismin vardı dilimde

Söyle bir tanem nedir bu gelen başımıza

Kala kala sadece resmin kaldı elimde

Hakkı var mı gülmeye beni mutsuz edenin

Nerden çıktı bu veda geçerli mi nedenin

Önce ruhun ayrıldı daha sonra bedenin

Kala kala sadece resmin kaldı elimde

Ben mutluluk vermiştim sen ıstırap getirdin

Günden güne gözümde değerini yitirdin

Başardın en sonunda sabrımı da bitirdin

Kala kala sadece resmin kaldı elimde

Ordu girse emrime sarayını kuşatmam

Nefretime değmezsin yolda görsem taş atmam

Son kez bakıp yakarım anıları yaşatmam

Kala kala sadece resmin kaldı elimde', 'Düne kadar mutluyduk ne oldu aşkımıza Bu dünyada tek senin ismin vardı dilimde Söyle bir tanem nedir bu gelen başımıza Kala kala sadece resm...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/resmin-kaldi-elimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizim Yok Oldu', 'denizim-yok-oldu-bulent-kiroglu-1c06b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin yokluğunda özlemi öğrendim ben,

Duymak istedim sesini, görmek istedim gözlerini yeniden.

Sakladım giydiklerini hiç gitmesin kokun diye tenimden

Uzandım uzandığın yere düşledim seni belki gelirsin diye.

İstemedim bilerek üşüdüğünde beni giydiğini,

Belki sen getirirsin dedim bir kez daha görmek için beni,

Belki getirmezsin hiç unutmamak için sevdiğini,

Belki de unuttun hem sevdiğini hem sevildiğini.

Ağlattın beni yine bu akşam, 

Mutlu bir insan sesiydi benimle konuşan

Seninle anlaşan başkası var anlaşılan,

Hatırla isterim herşeyi seninle yaşanan.

Kaçmak kolay gelse de kovalar gerçekler bizi,

Mutluluk uzak değil aslında, sevebilsek birbirimizi,

Deli de aşık de ne dersen de

Çok iyi bir insansın yine de.

Seninle girdim yeni bir yaşa,

Seninle girdim yeni bir yaşama,

Sevmeyi öğrettin bana duygularımı vurdum kıyılarına.

Yardımcı olmak isterdim sana biraz daha güvenebilseydin bana.

Zor yaşamlar, karışık insanlar, hızlı giden arabalar,

Akıp giden bir zaman, yetişemeyen insanlar,

Batan bir güneş, doğmaya hazırlanan yeni günler,

Soğuk bir hava, aklı karışmış bir deniz.

Isındıkça hava buharlaşıverdi koskoca denizim yok oldu galiba,

Oysa ne de güzel dalgaların vardı, acıtsa da kıyıları,

Köpüren sendin, duyguların vardı, incitse de insanları,

Alıp götürdün beni uzaklara getirecek denizim yok oldu galiba.

Bir resmini çok gördün bana, belki de korku verdim sana.

Hata yapmak da yaradı bana bir insan daha tanıdım

Bir yıldız daha kaydı, masumlar bir başka aşka kaldı.

Denizim yok olsa da gönlümün denizi okyanus oldu.

Hatırladın mı?', 'Senin yokluğunda özlemi öğrendim ben, Duymak istedim sesini, görmek istedim gözlerini yeniden. Sakladım giydiklerini hiç gitmesin kokun diye...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/denizim-yok-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Bacı Diyemem', 'sana-baci-diyemem-muammer-baydere-dk02g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana oyun oynandı sana nikah kıyıldı

Yüzünü görmesem de bir yabancı diyemem

Aşkın bana haramsa ruhun helal sayıldı

Karım değilsin ama sana bacı diyemem

Gözlerimden dökülen yaşlar sel olabilir

Hayal suya düşünce ümit yel olabilir

Düne kadar sevenler bugün el olabilir

Karım değilsin ama sana bacı diyemem

Hayatıma anlamı yine sen veriyorsun

Söyle gönül bağından kime gül deriyorsun

Her gece düşlerimde koynuma giriyorsun

Karım değilsin ama sana bacı diyemem

Keder hüzün nedir ki kahır düştü hisseme

Kırılıp küsme sakın bu ufacık siteme

Yalvarırım ne olur bunu benden isteme

Karım değilsin ama sana bacı diyemem', 'Bana oyun oynandı sana nikah kıyıldı Yüzünü görmesem de bir yabancı diyemem Aşkın bana haramsa ruhun helal sayıldı Karım değilsin ama sana b...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-baci-diyemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akçay''da...', 'akcay-da-muammer-baydere-fduik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Altından kalkılmaz o gururunun

Ne bir şans veriyor ne de bir fayda

Bulutu sevgimdi aşk yağmurunun

Ne diye dindirdin beni Akçay’da

Keyfini bekledim boynumu eğip

Gönlümü doyurdum ayvayı yeyip

“Öpersen bırakır giderim” deyip

Köşeye sindirdin beni Akçay’da

Her kimi istersen sen onu çağır

Her kime kızarsan gel bana bağır

Şu gönül tartında el daha ağır

Sıfıra indirdin beni Akçay’da

Gözlerim bir ajan gönlün kaçaktı

İçimde arzular salkım saçaktı

Vuslata kalkacak hani uçaktı

Dolmuşa bindirdin beni Akçay’da', 'Altından kalkılmaz o gururunun Ne bir şans veriyor ne de bir fayda Bulutu sevgimdi aşk yağmurunun Ne diye dindirdin beni Akçay’da Keyfini be...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/akcay-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Is this a dream?', 'is-this-a-dream-bulent-kiroglu-9bru9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'It was a rainy winter night, it was cold and wet.

I was walking and crying but trying not to be sad.

I was thinking and dreaming hoping to be right,

May be waiting for the sun or for the someone.

I have a great passion for the unknown,

I am hiding the truth for the well known,

And ready to sacrifice what I really own.

It was just the same, same as the past.

I know it will be the same, same as the present.

I know it is not easy to find you but,

I promise not to leave you when I find you.

Am I searching for the impossible? Is impossible possible? 

Is this a test I have to pass to reach you? 

With all my heart, I want to keep you when I reach you.

Who are you? What am I doing? Am I crazy? 

Or am I falling in love? I really do not know.

Intense sorrow just filled my body! 

I can not breathe, I can not talk anymore,

Do you hear me? Do you feel me? 

I am here waiting for you to see me! 

I know you, but I couldn’t come and see you.

I don’t know you, but I could talk to you.

Oh god, I am confused, I am totally confused.

Will you help me? 

Like every night has a morning,

This time I wake up with your smile,

I wash my face with your hands

While my hands keeping my heart.

And this is a dream I see everynight!', 'It was a rainy winter night, it was cold and wet. I was walking and crying but trying not to be sad. I was thinking and dreaming hoping to b...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/is-this-a-dream-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tik Tak Tik Tak', 'tik-tak-tik-tak-bulent-kiroglu-0trpc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıradan başladı herşey, sanki eski bir dosta kavuşacaktık.

Dile kolay tam 20 yıl, oysa karşımızda yeni birini bulacaktık.

Çocukluk geride kalmış, yetişkin olmanın acıları ise yaşanmış.

Birbirimizi üzmemek ve kırmamak içinse sözler baştan verilmiş! 

Son akşama kadar sıradandın sen de benim için,

Sanırım ben de sıradandım senin için.

Dayanamadım aradım son bir kez sesini duyabilmek için! 

Sevindim hem de çok sevindim, tekrar sesini duyduğum için.

Tik tak tik tak…

Senden gelen bir haberle yine gerildim ve korktum.

Az kalmıştı sıradan büyük buluşmaya…

Gerçi daha önce de buluşmuştum ama.

O an gerçekten çok farklıydı benim için,

Sıradan başlamıştı, ama sıradan olmamalıydı bizim için.

Daha ilk bakışta, güneşin ısıtmıştı içimizi,

Bir kadeh içki rahatlatmıştı ikimizi.

Seninle zaman çok çabuk geçti, nasıl geçecek derken,

Gözlerin içindeki güneşin ışıklarını yansıttı sana bakarken,

Çoğu zaman utandım bakamadım gözlerine sen bana bakarken,

Keyiflendim ben de seni gördüğümde keyifle müziği dinlerken.

Söz vermiştim kendime aşık olmayacağım sana diye,

Sakın aşık sanma beni sana şiir yazdım diye.

Belki de sadece güneşinin sıcaklığını özledim yine,

Belki de karın ağrıma ilaç olur sandım bu şiir böyle.

Tik tak tik tak…

Devam ediyor bu heyecan, bu korku ve bu gerilim.

Devam etmesi mi iyi? Etmemesi mi? Ne bileyim? 

Ne hissettim onca yıldan sonra dersen? 

Sıradan bir paylaşımı özel hissettim derdim.

Doğal akışında yazılan bir şiirle sana merhaba demek istedim.

Karşılık beklemeden paylaşmayı da senden öğrendimi bil istedim.

Sen özlesen de özlemesen de benim seni özlediğimi bil istedim.

Birinci olmak için hırslarım yoktur benim, 

İkinciliğe de razı olduğumu hatırlatmak istedim.', 'Sıradan başladı herşey, sanki eski bir dosta kavuşacaktık. Dile kolay tam 20 yıl, oysa karşımızda yeni birini bulacaktık. Çocukluk geride ka...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/tik-tak-tik-tak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın', 'yangin-bulent-kiroglu-ir906', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşin doğuşu ile attım kendimi sahile,

Sakin ve huzurluydum köpüren dalgaların aksine,

Sen de vardın yanımda birlikte taş attık denize,

Kabarttı deniz yüreğimizi aşık etti bizi birbirimize,

Gözlerim karardı birden, karlar kapladı her yeri aniden,

Bulutlar aldı dalgaların yerini güneş doğarken, 

Sen ve ben, karlar ülkesine giderken,

Düşüverdik birden, bir çığ olduk güçlendik yeniden.

İçin için yanıyor yüreğim bir kor gibi,

Eriyorum yavaş yavaş sanki bir buz gibi,

Sevemiyorum onu seni sevdiğim gibi,

Daha ne kadar çekeceksin onun sorduğu gibi.

Sevdiğimi paylaşmak zor geliyor bana,

Kıskanıyorum seni başkaları ile paylaştıkça,

Koparıp almak istiyorum, o seni kullandıkça,

Saklıyorum sana olan aşkımı sen ona aşık oldukça.

Olgun oldu adım, gördüklerimi görmez olunca,

Sabırlı oldu adım, sana olan hislerime ket vurunca,

Daha ne kadar sabrederim sen onunla olunca,

Dayanamam ölürüm seni ona aşık bulunca.

Seviyor mu seni senin onu sevdiğin kadar? 

Çekiyor mu aynı acıyı senin çektiğin kadar? 

Olgun oluyor artık senin de adın, sabırlı olana kadar.

Vazgeçmek zor geliyor sana, onu da seviyorsun o kadar.

Ne haddime bunları söylemek sana,

Sadece kızıyorum seni üzdüğü için ona,

Gözlerini açmak istiyorum senin bana baktığında,

Benim olmanı istiyorum yanlızca.

Bilmek istiyorum yerimi senin kalbinde,

Üzmek istemiyorum seni onun kalbinde,

Daha fazla olgunlaşıp yere düşmek yerine,

Gelip koparmanı istiyorum beni elinle.', 'Güneşin doğuşu ile attım kendimi sahile, Sakin ve huzurluydum köpüren dalgaların aksine, Sen de vardın yanımda birlikte taş attık denize, Ka...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yangin-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Sesleri', 'kus-sesleri-bulent-kiroglu-5pu37', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyordum, seni özlüyordum,

Benden uzaklaşmana dayanamıyor, 

Sana yaklaşmanın yollarını arıyordum,

Sana sarılmak, seni hissetmek istiyordum.

Derken titrek bir sesle irkildim o gece,

Anlamaya çalıştım seni üzen her neyse,

Gerçi hep bir burukluk vardı üzerinde,

Ama zorlamak istemedim seni üzülsem de.

Görmesem de, duymasam da hissediyordum seni içimde,

Tanrı şahittir ki arıyorsun beni her seni düşündüğümde,

Zorlandın,

Sen de söylemek istedin olmadı beceremedin o gece,

Ben zorlamasam seni uzaklaşıp gidecektin benden o gece.

Korktun, neden korktun ki…

Sen de biliyorsun dedin, ama bir de senden duymak istemiştim,

Sonra dedin.

Beni uykusuz bir gece ile başbaşa bırakmak istedin.

Tatlı bir rüzgar yaladı yüzümü penceremi açtığımda,

Kuşlar ötmeye başladı onlara baktığımda,

Keman sesleri ile karışık bir hüzün çöktü yatağıma,

Kitabım elimden düştü, sen yardıma çağırdığında.

Korktuğum olmuştu, ben de korkmuştum,

Bir damla gözyaşı bir buz gibi kaymıştı yanağımdan,

Sarılıp sana güç verememek,

Yeni bir yıla sensiz girmek gibi gelmişti bana.

Kanatlanıp saatlerce uçtum o gece,

Alnına bir öpücük kondurup, sana sarıldım o gece,

Kıyamadım seni uyandırıp öpmeye o gece,

Sabah olduğunda sen ve ben vardık ne olduysa o gece.

Sevmek istiyorum seni delice, sen hazır hissettiğinde,

Geçmiş yılda uyumak istemiyorum artık, 

Seninle girmek istiyorum her güne.', 'Seni düşünüyordum, seni özlüyordum, Benden uzaklaşmana dayanamıyor,  Sana yaklaşmanın yollarını arıyordum, Sana sarılmak, seni hissetmek ist...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kus-sesleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşabilmek Sana', 'kavusabilmek-sana-bulent-kiroglu-2zfve', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Az kaldı kavuşmamıza, ya da senin kızgınlığına,

Gelecek misin bana? Yanlız mı doyuracağım karnımı yoksa,

Heyecandan dilim kurudu desem, düşünür müsün beni yolda? 

Geçmek bilmedi Pazar, sabahtan başladım desem hazırlığa,

Dayanamadım öptüm o sabah seni,

Aklımda yoktu dokunmak sana, asana kadar ceketini,

Kapı çalıyor sanki, görüyorum hala karşımda seni,

Sense belki yolda düşünmüyorsun bile beni,

Ne diyeceksin bilmiyorum ki bu yazdıklarıma,

Belki kızacak belki sevineceksin okuduğumda sana,

Neler vermezdim ki bir kez daha dokunmak için sana,

Başımı göğsüne yaslayıp uyanmak isterdim sabaha.

Zaman mı geçen seninle, yoksa sevgim mi artan bizimle,

Biz demeye başladım senden habersiz inan değil elimde,

Yanıyor içim sensiz, seni düşünüyorum senin yattığın yerde,

Saatler geçmek bilmiyor artık, seni gözlüyorum penceremde,

Korkuyorum aslında gelmeyeceksin diye,

Bir kez daha aramak istiyorum seni sesini duyarım diye,

Yaklaştın mı bana, yoksa gelip geçtin mi ikiden yine? 

Arasam kızar mısın bana, yetti be der misin indiğinde? 

Hadi ne olur gel artık, bitsin sana karşı bu özlemim,

Söyleyeceksen söyle sevmediğini, seni derinlere gömeyim.

Olsun sen yine varsın, nasıl da geçti bir hafta meleğim,

Battın ya sen denizimde, izin ver meleğim olsun benim.', 'Az kaldı kavuşmamıza, ya da senin kızgınlığına, Gelecek misin bana? Yanlız mı doyuracağım karnımı yoksa, Heyecandan dilim kurudu desem, düşü...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kavusabilmek-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz de olur', 'sensiz-de-olur-bulent-kiroglu-xdbfy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine ben.

Anlam veremesen de evet yine ben.

Neden mi sen? Sevmek suç mu? Sevdim bir kere seni ben,

Ben de çok çalışırım ama yine de severim seni ben.

Düşünürüm çoğu zaman kendim için ne yaptım bu hayatta,

Ya da ne yaptı başkaları benim için bu hayatta,

Başkaları için yaptığımı ben yaptım mı kendime acaba? 

Yetti be dedim artık seni görünce karşımda.

Ağlamaya başladım gerçekten, yine kendim oldum yeniden,

Seni sevmeyi senin beni sevmeni istedim aniden,

Seni beklemek, seni özlemek, seni hissetmek istedim,

Sesini duymak beni unutmadığını bilmek istedim sadece.

Çok mu fazla gördün bunu kendine? 

Değer misin acaba bu kadar çok ilgiye? 

Sussam mı artık fazla mı geldim senin ilgine? 

Yoksa ben de sıradan birimiyim senin sevgine? 

Kendim oldum açtım kendimi sonuna kadar sana,

Unutmak istedim seni olmadı düşündükçe verdiklerini bana,

İlgini verdin, sevgini verdin, kendini verdin bana,

Vermek istemezsen söyle, almam ben de bundan böyle.

Heyecanlandım seni görünce karşımda,

Dilim tutuldu sesini duyunca,

Seni sevdim bir kere ama sensiz de olur hayatta,

Sen istemezsen beni kendi hayatında.

Her zaman olmaz bu aşk, her zaman aşık olmaz insan,

Her zaman kendi olmaz, dürüst olmaz bu yaşanan,

İstiyor musun sevgimi; sevdikçe seni, sevecek misin beni? 

Yoksa gülüp geçecek, itecek misin başka denize beni? 

Korkarsın bazen duraksarsın aniden,

Belki de sevilmedin gerçekten, sevemedin yürekten.

Seven çıkınca karşına, sana şiirler yazınca,

Korktun haklı olarak alışılmadık bu sırdaşa.

Keşke hep seninle olsa, sensiz hiç olmasa,

Sensiz de olur bu hayatta keşkeler bir başka hayata.', 'Yine ben. Anlam veremesen de evet yine ben. Neden mi sen? Sevmek suç mu? Sevdim bir kere seni ben, Ben de çok çalışırım ama yine de severim ...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sensiz-de-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Yağmuru', 'nisan-yagmuru-bulent-kiroglu-dce5c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok beklemiştim seni, senin sen olduğunu bilmeden,

Çok gözyaşı dökmüştüm, hayali sen beni terkettiğinden

Çok şiir yazmıştım yanlızlığımı düşündüğümden

Şimdi yine yazıyorum ama bu sefer seni düşündüğümden.

Bir yaşıma daha giriyorum bugün,

Yine gözlerim doluyor ağlıyorum bugün.

Anlayabilecek misin içimdeki sevgimi bugün? 

Yılların gizli kalmış sevgisini sana verdiğimi bugün.

Hediyelerin en güzelini aldım senden, 

Yılların sevgisini paylaşacak bir dost buldum nerden,

Seni sevdim, seveceğim de sen kaçsan da benden.

Bu satırları okudukça hatırlarsın beni yeniden.

Bir ay oldu seninle tanışalı,

Bir ömür oldu seninle yaşayalı,

Yanımda olmasan da özledim seninle uyanmayı,

Sesini duydukça sana sarılıp uyumayı.

Şaşırma sakın bu satırları okurken tek başına,

İnancımı kaybetmedim hiç kalsam da tek başıma.

Hatırlarım seni daima sen beni hatırlamasan da,

Kaybetmek istemem seni sen beni umursamasan da.

Dünyalar benim olur aradığında beni,

Görmek isterim duysam da sesini,

Gözlerine bakmak isterim, tutmak ellerini,

Seninle olmak isterim, paylaşmak günlerini.

Bilinmeze bir yolculuk seninle zorluyor ikimizi de,

Daha tam tanımadan birbirimizi biniyoruz aynı gemiye.

Açıldıkça engin denize, daha sıkı sarılıyoruz birbirimize,

Az da olsa var bizim gibiler, dürüst oldukça birbirlerine.', 'Çok beklemiştim seni, senin sen olduğunu bilmeden, Çok gözyaşı dökmüştüm, hayali sen beni terkettiğinden Çok şiir yazmıştım yanlızlığımı düş...', ARRAY['Türk Edebiyatı','Şiir','Bulent Kiroglu']::text[], 8.5, '{"poet":"Bulent Kiroglu","poet_slug":"bulent-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nisan-yagmuru-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülü ağlattın', 'gulu-aglattin-tuncay-akdeniz-vfd6f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acı hoyrat gibi estin bağıma

Kırdırdın dalları gülü ağlattın

Bahar mı getirdin gönül dağıma

Döktürdün yaprağı dalı ağlattın

Sen batırdın benim yüzen gemimi

Limana varmadan kestin önümü

Arıyla gönderdim sana  sevgimi

Küstürdün çiçeği balı ağlattın 

Bu sevda yürümez yaptığın nazla

Senin yaptıkların kaderden fazla

Senin için dövdüm bağrımı sazla

Susturdun mızrabı teli ağlattın

Sinemi attığın oklar deldiler

Arzu kamber kavuşmadan öldüler

Leyla’nın aşığı mecnun dediler

Yandırdın keremi külü ağlattın

Tuncay diyor sönmez aşkın közleri 

Gönülden silinmez sevgi izleri

Anladım ki aşkın körmüş gözleri

Kandırdın sevdayı çölü ağlattın', 'Acı hoyrat gibi estin bağıma Kırdırdın dalları gülü ağlattın Bahar mı getirdin gönül dağıma Döktürdün yaprağı dalı ağlattın Sen batırdın ben...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gulu-aglattin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C05 - Ayak', 'c05-ayak-tahir-gungor-f55ln', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürür hep yıllar yılın,

Hem giyimli hem yalın,

Yaya yolcusu yolun,

................................Ayak.

Vardan sayma tekini,

Gider uzak yakını,

Çeker dünya yükünü,

................................Ayak.

Ayrı gider ikisi,

Fena kokar akısı,

Aklı yok ki okusa,

................................Ayak.

Ne anlar kurt çakaldan,

Korkusu taştan çakıldan,

Çekisi hep akıldan,

................................Ayak.

Ayak uyak değilse,

Baş da duyak değilse,

Doyum doyak değilse,

................................Ayak,

................................Hep ayak,

................................Hep ayak.', 'Yürür hep yıllar yılın, Hem giyimli hem yalın, Yaya yolcusu yolun, ................................Ayak. Vardan sayma tekini, Gider uzak yak...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/c05-ayak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaranlar(4)', 'sahmaranlar-4-i-smet-barlioglu-wrl2i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoldan geçen bir adam durup bir süre ilgiyle baktı. Delikanlı bir geniş konferans salonunda bir baştan bir başa gidip geliyordu. Boru haline spkmuş olduğu formaları kavrayan elini kaldırarak sorular soruyor, sonra bu sorulara, kibrit kutusunu sıkan elini yukarıdan aşağı indirerek, çeşitli yaylar çizerek karşılıklar veriyor, kendi kendine bir şeyler anlata anlata ilerliyordu.

Ta aşağılarda Vatan Caddesi ‘ne döndü. Caddeye bastığı ilk adımla ayrı, apayrı bir dünyanın eşiğinden içeri girdiğini sandı. Yüksek, modern, pırıl pırıl metal direklerdeki yeşil flıoresanslı çubuk lambaların ışığında çoraplarına baktı. Ayakkabılarının boğazlarıyla paçalarının bitimleri arasında kalan bölümler yemyeşil Çin İpeği gibi parlıyordu. Kendi çorapları bu renk değildi. Bir süre ucuz, eski çoraplarının bu tatlı renklerini merakla ve övgüyle seyretti. Sonra başını kaldırıp direklere baktı. Direkler, asfaltın ortasından disiplinli bir dizi halinde ta ilerilere kadar uzanıyordu. Uzakta Aksaray ışıklar içerisindeydi. Derinlerdeki, kenarları damalı, kaportası çağla yeşili araba, yaklaştıkça kızardı ve tam yanından küflenmiş kırmızı olarak geçti.

‘Plakası 216527.’

Surların az ilerisinde yaşlı bir çingene taşlar üzerine oturmuş sigara içiyordu. Yanından geçerken selam verdi. Çingene duymadı.Delikanlı, yaya kaldırımındaki akasya fidanından bir dalcık kopardı, saydı: Sekiz yaprak vardı. Dalı sapından tutup yapraklarla yüzünü yelpazeledi. Sonra yaprakları teker teker koparıp uçurdu. İnce dalı katlamak istedi. Dal tekrar açıldı. Katlanırsa kırılır sanıyordu.  Birkaç kere denedi, kıramadı. Attı. Bu kere, akasyadan tek bir yaprak kopardı. Yaprağı geniş kenarından yuvarlayarak sigara sarar gibi tamamen dürdü. Ortadan katladı. Yaprağın en üst tabakası, katlandığı yerden pek hafif yırtıldı. Eğilip çorabının boğazından ince bir lastik iplik çekti. Lastiğin iki ucunu düğümledi. İncecik bir sapan yaparak parmaklarına geçirdi. Bükülü yaprağı ok yerine sapanına taktı. Sapanı çeke çeke gerdi. Ansızın bıraktı. Yaprak uçarak gidip bir taşa vurdu.

- Eyüp ‘e nereden gidilüptür aya? 

Yapraktan okun vurduğu taşa bakmakta olan delikanlı döndü. Onaltı yaşlarında kadar görünen bir gençti. Bıyıkları terlememişti. Sırtında kabaca ütülenmiş, bit pazarı yenisi bir elbise vardı. Lacivert elbisenin içinde, gömlek yerine bir işlik göze çarpıyordu. ‘Belki de laciver değil.’ Di. Mendil cebinden desenli iri bir mendil fışkırıyordu. Bu cepte kolları katlanmış bir güneç gözlüğü göze çarpmaktaydı. Saçlarının dipleri terlemişti. Alnında iyice belirginleşen bu damlalar, gözlerinin yanlarından yanaklara ilerlemekteydi.

- Eyüp ‘e nişanlı görmeye mi gideceksin? 

- Yoh aya. Men te Gars ‘dan gelirem. Eyüp ‘de halam var benim. Ola ki tanıyorsun, ergişisi Gumgapı ‘da motor tepikliyen Gara Haydar. ‘Gara Haydar’ dedinmi tanımıyan bir tek nefer yohtur.

Delikanlı hiç düşünmedi bile:

- Kara Haydar mı? Tanırım. Demek Kara Haydar senin halanın kocası.

- Ehe.

- İstanbul ‘a bugün mü geldin? 

- Yoh. Beş, on, onbeş, girmi gün gadar oldu. Bugün dolanmaya çıhöışamdır şeyle bir. Geçdiğim yerleri men hep ezberlemişemdi. Hammısını ezmerlemişemdi. Garanlıh ki basdı, yolları, cedahları çıhardamamışamdı. Hammısı hammısına benzeyüptü köpoğlunun gedesinin. Tee ilerlerden sora sora buraya varmışam.

- Buradan da Eyüp ‘e gideceksin? 

- Beli.

- Yolun karşısında otobüs durağı var. Bak, işte şu teneke tabelanın asılı olduğu direğin dibi.

- Aya gardaş, sen yolu tarif eyliyemeyüpsen mene? 

- Elbette ederim ya, yaya gidemezsin; çok uzak.

- Olsun, men giderem.

- Otobüsle neden gitmek istemiyorsun? Paran mı yok? 

- Menim pulum da var lakin zor işdi bu iş.

- Niçin? 

- Aya gardaş, men her nerde ki ‘Ay gişi men burada düşecem’ diyiremse, köpoğlunun gedeleri mene diskur geçiğler ‘Gorhma balam, gappılar sağlamdı, heçbi nefer buralardan düşemeyüptü.’ Diye.

- Sen de ‘Düşeceğim’ yerine ‘İneceğim’ dersin olup biter.

- Ne diyerem? 

- ‘Düşeceğim burada’ demezsin, ‘İneceğim burada’ dersin.

- ‘İneceğim burada’ derem.

- Öyle dersin.

- Ola ki diyebülemem de gene otommusda galıram. Biz uzah yerin balasıyıh. Sen yolu tarif eyleyesen mene, o daha yahşıdı.

- Surları görüyorsun. Şunlar. Oraya kadar git. Sağa dön. Sağını biliyor musun? Bak, şu yan sağ yandır. Önüne bir yokuş çıkacak. Yokuşu başa kadar yürü. Orada gene sor. Tümünü ben anlatırsam karıştırırsın.

- Heyli teşekkür ederem aya.

- Güle güle.

Gencin arkasından uzun uzun, çok uzun uzun baktı. Düşünceleri Tarlabaşı ile Taksim arasında gidip gidip geliyordu. İstanbul ‘a ilk geldiği günlere döndü. Kime ait olduğunu çıkaramadığı kuvvetli bir el, vücudunu Vatan Caddesi ‘nin serin gecesinden çekip almış, kızgın bir öğle sıcağının Tarlabaşı ‘sına koymuştu. Tüm varlığı yirmi liraydı. Sekiz belgelik fotoğraf istemişlerdi. Birilerinden akıllar danışmıştı. ‘Taksim ‘de çektirebilirsin.’ Di. Taksim nerededir bildiği yoktu. ‘Otobüs buralardan geçmez. Taksiler saat açarlar. Ne tutacak? Tutacağı ya iki lira, ya da üç.’ Tü. ‘Taksim’ deyince şoför çok bir garip bakmıştı kendisine. Git babam, git, yol bitmez, Taksim bir türlü görünmezdi. Dönerken yaya dönebilmek için arabanın her geçtiği yeri aklına yazıyordu. Tarlabaşı ‘nı yukarı çıkınca sağa dönmüşlerdi. Sonrası; İstiklal Caddesi, Şişhane, Unkapanı Köprüsü, Saraçhane, Aksaray, Laleli, Beyazıd, Divanyolu, Cağaloğlu, Eminönü, Galata Köprüsü, Karaköy, Dolmabahçe ve bir dik yokuştan sonra Taksim Alanı ‘ydı. ‘Vay babam, Taksim ne uzak.’ Tı. ‘Şoför abi, borcumuz ne kadar? ’ dı. ‘Yirmi lira, hemşerim.’ Di. ‘Belgeye yapışacak fotoğraflara artık gerek kalmadı, zira; biz bugün boyumuzun ölçüsünü aldık.’ Dı. ‘Akılsız başın cezasını ayak çeker.’ Di. ‘Ama ona bu cezayı çektiren de gene akılsız baş.’ Tı. Belleği kuvvetliydi ama arabayla iki saatte gittiği Taksim ‘den Tarlabaşı ‘na gelebilmek için ayakları yeteri kadar kuvvetli değildi. Tarlabaşı ‘na ulaştığında, akşamı, geceyi atlamış, sabahı bulmuş olduğunu gördü. Yıllar sonra, aldatılmışlığını anladı: Tarlabaşı Taksim ‘le burun burunaydı.. Taksim Anıtı ‘nın dibinde, aldatılmışlığına hüngür hüngür ağladığı günlerden Vatan Caddesi ‘ndeki serin gecenin koynuna zorlukla geldi.

Hala parmağına dolanmış duran ince lastiği ceketinin mendil cebine attı. Kitap formalarından yapmış olduğu boruyu, ceketinin altından, pantalonunun arka ceplerinden birine diklemesine soktu. Paketten bir sigara çıkarıp yaktı. Eyüb ‘e giden genç, surların ilerisinde sağa dönüp kaybolmuştu. Kibrit kutusundan fetişini sol avucuna sıkıştırdı, yürüdü.

‘Dünya çakal dolu, it dolu. Hergele dolu. Hergele Meydanı Ankara ‘da. Samanpazarı da orada Hergele değil, her gelen meydanı. Aslı bu bunun. Sonra sonra, hergelen hergele olmuş. Her gelen hergele olmuş. Her gelen hergele olmuş.’

Delikanlı, yaya geçidi ayrılmış olup olmadığına bakmaksızın asfalt caddeyi enlemesine geçti. Sağ kaldırımda yürümesine devam etti. Yaklaştıkça, ne olduğu kesinlikle anlaşılamayan gürültülerden, sevinçli bağırmalardan, seslenmelerden, kırık-kopuk türkü ve şarkı sözlerinden, mekanik gıcırtılardan oluşmuş bir gümbürtünün içine düşüyordu. Kendini alıştıra alıştıra yaklaşan gümbürtü, uzak karanlıklarda zayıflayan yankılarla kayboluyordu. Asfalttan aşılmaz demir parmaklıklarla ayrılmış olan Luna Park ‘ın Binbir renkli ışıkları, asfaltın bu bölümünü büyülü fırçalarla nakış nakış boyamıştı. Giriş kapılarının önünde duran tek-tük insanlar, karlarda bırakılan çamurlu ayak izleri gibi, asfaltı cetvel gibi bölen yaya geçitlerini aşıp Akdeniz Caddesi ‘ne doğru uzanıyordu. Parmaklıkların Aksaray yönünde kalan dış bölümleri, arabalı satıcılarla doluydu. Küçük bir kız çocuk bir eliyle haminnesinin elinden tutmuş, gözbebeklerinde renkli ışıklar oynaşırken öbür elindeki gül pembe keten helvası bulutuna küçücük ağzını, yeşilli, sarılı, morlu yanaklarına kadar daldırıyordu. Üç havacı subay, vücutlarına şık oturmuş üniformaları içinde, ayakta tartışıyorlardı. Uzaktaki taksilerden birine, biri yaşlı olan dört yolcu bindi. Araba geri geri giderek birden ilerleyip şiddetle sağa viraj aldı ve homurtular çıkarıp demir parmaklıkların ötesinde kayboldu.

Bilet satış gişelerinden birindeki genç adam kulübenin kapısını açtı. Yanına yaklaşan delikanlıyla tıkalaştı:

- Merhaba Kubi.

- Merhaba.

- Bu gece ner ‘den? 

Delikanlı, ta yükseklerde çevreye çığlıklar savurarak vırıldayan, ışıklara boğulmuş dönme dolaba bakıyordu:

- Her zamanki gibi. Biraz sürteyim dedim.

- Nerelerde? 

- Şur ‘da, bur ‘da.

- Yenganım yine Tophane ‘de mi? 

- Or ‘da.

- Almadılar mı Sirkeci ‘ye hala? 

- Almadılar.

- İçine tüküreyim böyle dünyanın.

Bir süre sustular. Gişeci genç sordu:

- Gene sabah dörde kadar mı çalışıyor? 

- Bu hafta öyle.

- Sen götürüp getiriyorsun tabi’? 

- Ben.

- Ta buradan Tophane ‘ye? 

- Tophane ‘ye.

- Ta Tophane ‘den buraya? 

- Buraya.

- İçine tüküreyim böyle dünyanın.

Bir süre daha sustular. Gişeci genç, iki bayanla bir baya kabin dışından içeri uzanıp alarak bilet verdi:

- Sınavlar nasıl gidiyor? 

- Gidiyor.

- Yarınki son mu? 

- Son.

- Bankanınkiydi bu? 

- Bankanınkiydi.

- Kaç müfettiş yardımcısı alacaklar? 

- Üç.

- Sınava giren çok mu? 

- Çok.

- Kubi, kazanacaksın.

Delikanlı parktan çıkanlara baktı. Cevap vermedi.

- Kazanacaksın, eminim. Çalışkansın. Hepimizden önce bitirdin fakülteyi. Biz hala bir ‘in, iki ‘nin derslerini temizlemeye çalışıyoruz.

Delikanlı sol avucundaki kibrit kutusundan fetişini sıkıp sıkıp gevşetiyordu.

- Hacı Hanife Hanım Teyze ‘nle aran nasıl? 

- İyi.

- Zam istemiyor ya kiraya? 

- İstemiyor.

- ‘Kızımla damadım gelecek, çık evden.’ Demişti? 

- Gelmediler.

Gişeci genç kabin penceresinden kolunu içeri soktu. Tekrar çıkararak üzeri jelatinli bir kutu yabancı sigarasını delikanlıya uzattı.

- Sigaram var.

- Bunu da al, Kubi. Dört kutuydu, sağa-sola verdim.

Delikanlı, hızlandıkça zincirli koltukları geniş çemberler halinde havada açılan atlı karıncaya baktı.

‘İnsanların saçları hep bir yöne uçuşuyor.’

- Pederden mektup alıyor musun Kubi? 

- Almıyorum.

- Gene or ‘da mı, Anadolu ‘da? 

- Anadolu ‘da.

- Gene şef vekili mi? 

- Şef vekili.

- Dünya da çok pahalı.

- Pahalı.

- Beş çocuk, bir kadın. Kendiyle yedi nüfus. Zor geçiniyor adam.

- Zor geçiniyor.

- Para falan yollayamıyor tabi’? 

- Yollayamıyor.

- İçine tüküreyim bu dünyanın.

Gene sustular. Gişeci genç, kalabalık bir kızlı, erkekli gruba bilet verdi. Gençler kontrolör sanıp biletlerini kendisine uzatınca, delikanlı hiçbir şey söylemeden aldı. Biletleri ortalarına kadar yırtıp kenarları madeni parmaklıklı çöp sepetine attı. Grup onunla hiç ilgilenmeden konuşa-gülüşe kapıdan geçti.

- Yengenin paydos saatine kadar yatamazsın.

- Yatamam.

- Kaç dakikaya gidebiliyorsun bueadan Tophane ‘ye? 

- İki saate yakın.

- Yaya mı? 

- Yaya.

- Her gün? 

- Her gün.

- Sen delisin.

- Deliyim.

İçeriden bir milli piyango satıcısı çıktı.

- Sabahın dördüne daha bir ton yol var, Kubi.

- Bir ton yol var.

- İöçeri girmek istersen, gir. Vakit geçirirsin.

- Vakit geçiririm.

Delikanlı çöp sepetini geçti. İçeriye doğru yürürken gişeci genç yeniden yanına geldi. Kapalı avucunu uzatarak çok yavaş bir sesle:

- On lira, Kubi. Al, borcun olsun.

Dedi.

- Param var.

- Beş paran yok. Günde kırk kuruş, o da sigara parası. Birincileri beleş vermiyorlar. Senin için değil. Yenge için. Tophane ‘den ta Malta ‘ya kadar kadıncağızı yaya yürütmeye hakkın yok. Al Kubi. Yalvarırın. Borcun olsun. Verirsin. Tanrı ‘nın izniyle bu aybaşı aydınlığa çıkacaksın. Eminim. Arkadaşlar da emin. Darda kaldık mı, koşarız Müfettiş Kubilay Bey ‘in aylık bordrolarına, sürekli yol paralarına, gündeliklerine. Niye yüzünü buruşturdun? 

- Kulağım ağrıyor.

- Benim de ağrımıştı bir kere, bir on lira soktum geçti. Şimdi ağrıdımı; beşer-onar sokuyorum. Al da bir dene. Kanın parası değil. Benim. Aybaşında verirsin. Namus borcun olsun.

Gişeci genç, elini delikanlının ceketinin yan cebine sokup çıkardı. Sonra gişe önünden kendisine bakan atlet yapılı iki adama doğru yürüdü.

(Devam edecek…)', 'Yoldan geçen bir adam durup bir süre ilgiyle baktı. Delikanlı bir geniş konferans salonunda bir baştan bir başa gidip geliyordu. Boru haline...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":123,"source_url":"https://www.antoloji.com/sahmaranlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudaktan Kalbe Akis', 'dudaktan-kalbe-akis-mehmet-sait-akkus-0sbch', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dudaktan Kalbe Akis

O gülüsün o bakisin

Dudaktan kalbe akisin

Beni candan yakisin

Yetmezmi be güzelim

Tatli dilin güler yüzün

Soldurmasin seni hüzün

Bana söyledigin o son sözün

Unutmamki be güzelim

Saçlarinin sarisini

Gözlerinin pariltisini

Sanki ayin yarisini

Almissin be güzelim', 'Dudaktan Kalbe Akis O gülüsün o bakisin Dudaktan kalbe akisin Beni candan yakisin Yetmezmi be güzelim Tatli dilin güler yüzün Soldurmasin se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkus']::text[], 8.5, '{"poet":"Mehmet Sait Akkus","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dudaktan-kalbe-akis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gönül Yarasi', 'bu-gonul-yarasi-mehmet-sait-akkus-z22j7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu Gönül Yarasi

Bu yara

Gönül yarasi

Sevdigiyle arasi

Bir hostur bu gün

Bu sevda

Gönül sevdasi

Kalbimin pasi 

Silindi bu gün

Bu melek

Gönül melegi

Soframin ekmegi

Gelmis bu gün

Bu kafiye 

Baska kafiye

Sevdigine hediye

ALLAH tan bu gün', 'Bu Gönül Yarasi Bu yara Gönül yarasi Sevdigiyle arasi Bir hostur bu gün Bu sevda Gönül sevdasi Kalbimin pasi  Silindi bu gün Bu melek Gönül ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkus']::text[], 8.5, '{"poet":"Mehmet Sait Akkus","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-gonul-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni bana bırak! ..', 'beni-bana-birak-sibel-uygun-w8g29', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Giderken herşeyinle çık bu kapıdan

Bedenim ellerinin sıcaklığını unutmalı! ..

Göz bebeklerimde siman kalmamalı! ..

Sevgi dolu bakışını,

Gülüşünü de unutmak istiyorum...

Sana ait ne varsa, al ve git.

Giderken, 

Beni bana bırak yeter...', 'Giderken herşeyinle çık bu kapıdan Bedenim ellerinin sıcaklığını unutmalı! .. Göz bebeklerimde siman kalmamalı! .. Sevgi dolu bakışını, Gülü...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beni-bana-birak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayan Ülkeme Mektuplar-1', 'kanayan-ulkeme-mektuplar-1-melih-coskun-f74x1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kanayan Ülkeme Mektuplar-1

Güzel annem, 

Burada geçirdiğim ilk günüm. “İnsanoğlu kuş misali” dedikleri ne kadar doğruymuş. Oysa daha dün dizlerinin dibinde otururken zamanın hiç geçmemesini böylece durmasını diliyordum tanrıdan. 

Kuş deyince aklıma geldi. Dünyanın en güzel duygusu olsa gerek  kuş misali uçabilmek. Belki kanatlarım yok benim ama dün uçağa ilk defa bindiğimde bu duyguyu tattım birkaç saatliğine de olsa. Haylaz bir çocuğun duvara çizdiği resim gibi görünüyordu yeryüzü binlerce metre yukarıdan. 

Yolumuza otobüsle devam ettik uçaktan sonra. Otobüs yolculukları hep öğrencilik yıllarımı hatırlatır bana. En sevdiğim şiirler hep o otobüs yolculukları üzerine yazılmıştır. Ama keder verir insana daha önce hiç gitmediğin ve hiç kimsenin gitmek istemediği bir yere gidiyorsan. Yollar her zaman kavuşmalara uzanmıyor ne yazık ki anne.

Buradaki yollar bizim oradakilere hiç benzemiyor. Yol kenarlarında görmeye alıştığım onca şey bile o kadar farklı ki. Sanki gökten taş yağmış bütün tarlalarına uçsuz bucaksız Mezopotamya’nın. Dalıp gitmişim bakarken o düzlüğün sonsuzluğa uzanışına. 

Uyandığımda o düzlük yerini dağların sonsuzluğa uzanışına bırakmıştı. Sonsuzluk kavramı gerçekten ne kadar değişken anne. Bazen sürüp gideceğini sanıyor insan bazı şeylerin. Oysa her şeyin bir sonu var. Acılarımızın da, mutluluklarımızın da...

Sanırım senin içinde en az benim için olduğu kadar zor olacak bu ayrılık. Malum, geldiğim yer adını bile duymak tedirgin etmeye yetiyor insanı. Ama senin için çok daha farklı olmalı. Nasıl bir duygudur ki etinden yüreğinden bir parçanın çok uzaklarda soğuk bir namlunun yalnızlığında sabahlaması. Büyük fedakarlıklarla büyüttüğün, hastalandığında sabahlara kadar başından ayrılamadığın oğlunu ölesiye merak etmek, sesini duyabilmek için bütün gün telefonun başında yüreği avucunda çırpınarak beklemesi nasıl bir duygu acaba anne...     

Sana ne kadar ben iyiyim, beni merak etme desem de biliyorum ki sen yine yüreğin avucunda bekleyeceksin bütün gün telefonun başında. Endişe etme gün gelecek baharda gelmiş olacak memleketime.Ve bu dağlara da bir gün mutlaka bahar gelecek anne. O zaman dönmüş olacağım belki yorgun dizlerinin dibine...

Oğlun', 'Kanayan Ülkeme Mektuplar-1 Güzel annem,  Burada geçirdiğim ilk günüm. “İnsanoğlu kuş misali” dedikleri ne kadar doğruymuş. Oysa daha dün diz...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kanayan-ulkeme-mektuplar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anaya Hasret', 'anaya-hasret-selahattin-olmez-4bjfh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ANAYA HASRET  

Güneş doğmadı bu gün,

Biçare göz kapaklarıma,

Dünyayı görmesi için.

Sabah olmadı ki kurtlaydım,

Korku dolu rüyaların içinden..

Emeline kavuşamıyordu bir türlü,

Mürüvveti kısıtlanmış kirpiklerim.

Değemiyordu birbirine dudaklarım,

Anlatsın birer,birer dostlara,

Bilinsin çektiğim ızdıraplarım

Bir illet oluşmuştu çaresi yoktu,

Bir teselli verecek insanlar bitti,

Ana gitti,baba gitti,Dost bitti.

“Köpekler olmasın” derler

Ana gibi dost bulunmaz mı meğer,

Gurbetlerden sılaya kadar

Her sözü bin hayat,görünüşü gülizar,

Ey ana sensiz yaşam ne kadarda zor,

Kirli çarşaf,yırtık şilte gel de gör.

Nihayet son buluştu,bu korkulu rüya

Masmavi bir havada,güneş doğarken…

06,02,1974 - Silvan 

Selahattin Ölmez', 'ANAYA HASRET   Güneş doğmadı bu gün, Biçare göz kapaklarıma, Dünyayı görmesi için. Sabah olmadı ki kurtlaydım, Korku dolu rüyaların içinden....', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anaya-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Geldim Anne', 'ben-geldim-anne-selahattin-olmez-artuc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BEN GELDİM ANNE  

Ben geldim anne,

Aç gözlerini bak gözlerimin içine,

Dayanamam senin göz yaşlarının bir tanesine.

Dinle; dinle, dinle beni anne ve kendine geldiğinde,

Al ellerimi ellerinin içine,

Ve

Bir şeyler söyle bana,

Hasret kaldı kulaklarım,senin sözlerine,

Ben geldim,sana geldim,ben geldim anne..

Gök yüzünün mavilikleri arasından geldim,

Beni gözlerinin maviliklerinde kaybetme anne.

Gözlerim hasret kaldı zira,senin gözlerinin rengine,

Yumuşacık dudaklarınla,yanaklarımdan öpüşüne,

Bana hayat veren sımsıcak nefesine,

Aç gözlerini,aç; bak gözlerimin içine

Ben geldim sana,ben geldim anne…

Ben hayırsız,ben vefasız,ben biçare evladın,

On gün oldu hiç yanına uğrayamadım,

Ellerini öpemedim,feyzini alamadım,

Göz bebeklerinin içinde anne,Kendimi göremedim

Göremedim anne göremedim.

Ne olur aç gözlerini de,gözlerinde kedim bulayım,

Canıma can katan annemi,doya,doya öpeyim,

Ellerini öperken yaşama nedenimi göreyim.

Aç gözlerini aç; Bak gözlerimin içine,

Ben geldim sana,ben geldim anne…

Nefesin gelmez olunca oralara kadar anne,

İçimden bir ses:Koş dedi koş dedi annene,

Belki geç olur yarınlar durma,hemen gitsene,

Yüzlerini,gözlerini,ellerini öpsene,

O ne emekler verdi sana tam elli sene

Ben de duramadım,duramadım koştum sana geldim anne

Aç gözlerini aç da bak,gözlerimin içine,

Ben sana geldim,ben sana geldim anne,

Belki şifa olmaya gelmedim,

Şifa bulman için duaya geldim.

Duydum nefesinde zorluklar çekmektesin,

Zorluğun sebebini bilmeğe geldim,

Derdine dermanlar bulmaya geldim.Canımdan can vermeye,

Emrine amade olmaya geldim,İlacın bulmaya geldim.

On gündür hasretinle yandım tutuştum,

Her gece rüyamda ben seni gördüm,

Ve,,

Koştum,ben sana geldim

Aç gözlerini aç ta, bak,gözlerimin içine,

Ben sana geldim,ben sana geldim anne….

Yüreğimin çırpıntısı durmadı,senden uzakta,

Sen burada hasta,yatar iken yatakta.

Yırtarım bendimi,benliğimi:gelirim ben sana ana,

Yeter ki kavuşasın sen eski sağlığına.

Çaren olurum,derman olurum,yalvarırım yaratanıma,

Canım lazım ise, canım fedadır sana

Aç gözlerini aç ta bak,gözlerimin içine,

Ben geldim sana,ben geldim anne,ben geldim anne..

14,12,2004



Selahattin Ölmez', 'BEN GELDİM ANNE   Ben geldim anne, Aç gözlerini bak gözlerimin içine, Dayanamam senin göz yaşlarının bir tanesine. Dinle; dinle, dinle beni ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/ben-geldim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdeniz Mavisi', 'akdeniz-mavisi-selahattin-olmez-pbwtc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'AK DENİZ MAVİSİ  

Kıyısında oturup seyran ederken,

İnsanı kendisinden geçiren bu nasıl mavi.

Ufuktan süzülerek,sızıp ta gelirken,

Işıklar oluyor havai mavi.

Ellerimi kaşlarımın üzerine koyunca,

Ak Denizin suları oluyor atlastan mavi.

Gözlerin kamaşmaya başlar,dalga vurunca

Dalgalar olur lacivert Ak,Deniz koyu bir mavi.

Gönüllerde aşk yelleri eserken,

Gözler dalar Ak Denizin ufuklarına.

Dönüşür Ak Deniz o zaman mavi bir saraya.

Hülyalar,mutluluklar,umutlar doluşur o mavi yuvaya,

Ve; Eller açılır mevlaya dua yapmaya.

Sabahleyin mavinin tonu biraz koyudur,

Tekneler dönmektedir,kasaları balık doludur,

Ak Deniz sevdalıya aşıklara,esin yoludur

İnsanlar için kıyıları umut doludur,

Maviler açılır yavaş,yavaş Beyaza doğru dönüşür,

Aşıkların üzerinden nazar bozdurur.

Gün ilerleyip ufka girerken,

İmbat yeli yavaş,yavaş eserken,

Ak Denizde maviler türlü haller alırken,

Sen de ki; Pembeleşmiş mavidir,

Kimine göre; Lacivert

Bana sorarsan bu,mutluluğun tablosu,

Morcivert,

Yani kızıla dönmüş lacivert.

Yedi rengi bünyesine almışta,güneş

Sevenlere Ak Denizin kıyısında diyecek evet

Açık mavi,koyu mavi,lacivert,Morcivert

Beyazlaşmış mavi,atlas mavisi,ediyor düet,

Bu günü ne kadar güzelse Ak Denizin; Olacak ilelebet,

Öylesine temizdir ve güzeldir mazisi de elbet.

Başkadır sularında yakamozlar,

Başkadır ak denizin dalgaları,aşk ile coşar,

Bir başkadır ak denizin mavileri,sanki dans eder

Sevdalılar.sevdalarını kıyısında yaşarlar,

Mavinin her tonunu taşıyan sularını,

Ayna gibi görerek,gönüllerince hem yaşar,hem coşarlar.

Hayat o kadar yaşanır kılar,Ak deniz Mavileri…..

25,12,2004

Selahattin Ölmez', 'AK DENİZ MAVİSİ   Kıyısında oturup seyran ederken, İnsanı kendisinden geçiren bu nasıl mavi. Ufuktan süzülerek,sızıp ta gelirken, Işıklar ol...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/akdeniz-mavisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Sevdamız', 'bizim-sevdamiz-selahattin-olmez-lyhwr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİZİM SEVDAMIZ  

Biz al çiçek derdik başkaları, lale,diyormuş,

Açıldığında şekli,sevdamıza benzemiş,

Kendi gizemi saklı kalırken bahçelerde

Geçince mevsim,soldu gitti nedense,

Rengi kaldı,aşkımızı saklayan yüreciğimizde

Bahçelere özendi yüreğimiz galiba

Doldurdu yüreğimizin bahçelerini,lalelerle süslü manzara.

Ne hüzün bıraktı,ne sitem ne dilde yara.

Zaman en güzel ilaç oldu,dertlere deva,

Söyleşti dudaklar,bakıştı gözler,

Yaşandı aramızda bu ulvi sevda.

Dar geliyor sevdamıza artık bu dünya,

Aşkımız ulvileşti büyüdü,taştı semaya,

Zaman hala duruyor olmalı zira,

Biz bakarken,kendimizden geçmiş; aynalara,

Aynalar yansıtıyor sevdamızı dünyaya…

Gözler şahit oldunuz beklide sizler,

Gördünüz belki siz kim bilir,kaç tane

Aşkların tükenip bittiğini,

Ak Deniz kıyılarında kaybolup gittiğini.

Yazın sarı sıcaklarında kavrulup yandığını,

Mum misali eriyip tükendiğini..

Oysa; 

Sevdamız şiirlerle sabitleşmiş değil ki bizim,

Nasıl var olduysa,öyle devam edecektir bilirim.

Lalelerin açılıp,solmasıyla bitmez bu sevgim.

Yazların sevdası gibi kısa değil,

Güzlerin gazalı gibi kırılgan değil,

Baharın sevdası gibi rengarenk,tatlı ve mutlu sevgim,

Sevdamız çok,çok,çok uzun ömürlü bizim.

10,02,2005



Selahattin Ölmez', 'BİZİM SEVDAMIZ   Biz al çiçek derdik başkaları, lale,diyormuş, Açıldığında şekli,sevdamıza benzemiş, Kendi gizemi saklı kalırken bahçelerde ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bizim-sevdamiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akkaya Öğretmenin Ardından', 'akkaya-ogretmenin-ardindan-selahattin-olmez-71e5t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'AKKAYA ÖĞRETMENİN ARDINDAN  

Adını bilmiyordum,şahsını hiç görmedim,

Has bel kader cenazende bulundum.

Saf tutum,namazını kıldım,defneyledim,

Öğretmendi öldü dediler,mezarında dua eyledim.

İnmedin; cıvıl,cıvıl,öğrencilerin omzundan,

Ayrılmak istemiyorlardı senden,belliydi hallerinden.

Fakat gördüm ki iki dünya arasındaki kapıdan,

Ahrete göç eyledin,gittin bu fani dünyadan…

Kim dedi ki sana öldün diye,sevgili öğretmenim,

Ne büyük fazilettir bu,kalplere girebilmişsin,

Nasılda hıçkırıyorlardı,boğazı düğümlenmiş öğrencilerin,

Belki çok şey di senin,öğrencilerine verdiklerin.

Karanfillerle doldurdular mezarının üstünü,

Böyle sini görmedim öğrencilerde,öğretmen düşkününü.

Mısralara sığdıramam ki,cenazende gördüğümü,

Dedim ki; Bir cenaze değil,sanki öğretmenin düğünü.

Sevgili öğretmenim sana Allah rahmet eylesin,

Beli ki dünyadan dolu gittin,mekanın cennet olsun,

Ektiğin tohumlar,fidan olsun boy,boy,büyüsün,

İrfanın çizdiğin yol,bizlere ibret,kılavuz olsun.

27,05,1997



Selahattin Ölmez', 'AKKAYA ÖĞRETMENİN ARDINDAN   Adını bilmiyordum,şahsını hiç görmedim, Has bel kader cenazende bulundum. Saf tutum,namazını kıldım,defneyledim...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/akkaya-ogretmenin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğaziçi', 'bogazici-celal-sahin-rm633', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her geçişimde, güzelliğini dökmek isterim mısralara

İlk görüyormuş gibi  büyüne kapılır dalarım hayallere

Bir yanda selimiye,biryanda salacak üsküdar,kız kulesi

Karşıdan sarıyor,ihtişamlı geçmişin büyüsü

Tek satır yazamadan,rüya gibi biter deniz sefası

Yazılmaz,anlatılmazsın farkına vardım, yaşanansın', 'Her geçişimde, güzelliğini dökmek isterim mısralara İlk görüyormuş gibi  büyüne kapılır dalarım hayallere Bir yanda selimiye,biryanda salaca...', ARRAY['Türk Edebiyatı','Şiir','Celal Şahin']::text[], 8.5, '{"poet":"Celal Şahin","poet_slug":"celal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bogazici-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-gulseren-onay-a0zn0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıkıp geleceksen 

Bir gün 

Bana eğer,

Nereye bıraktığını 

Bilmediğin

Yüreğini de 

Al gel....

GÜLSEREN ONAY

19/06/2005/ANTALYA', 'Çıkıp geleceksen  Bir gün  Bana eğer, Nereye bıraktığını  Bilmediğin Yüreğini de  Al gel.... GÜLSEREN ONAY 19/06/2005/ANTALYA...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eger-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedduan Tuttu', 'bedduan-tuttu-ali-dilki-akxkr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç bir şey olmadı diye ağlama

Ettiğin beddua tuttu sonunda

Dilek ağacına mendil bağlama

Ettiğin beddua tuttu sonunda

Gurur dağlarını aştımda geldim

Perişan halime şaştmda geldim

Şimdi ayağna düştümde geldim

Ettiğin beddua tuttu sonunda

Birgün söylemişti dersin demiştin

Başın belalara girsin demiştın 

Alşlah bin cezanı versin demiştin

Ettiğin beddua tutrtu sonunda

İstersen bayram et istersen düğün

Yaptığın şeylerle gurur duy ögün

Karşında biçare benim gördüğün

Ettiğin beddua tuttu sonunda

Bilemedim gönlümdeki cevheri

Baharı yaşarken geldin zemheri

Sen kazandın bu savaşta zaferi

Ettiğin beddua tuttu sonunda.', 'Hiç bir şey olmadı diye ağlama Ettiğin beddua tuttu sonunda Dilek ağacına mendil bağlama Ettiğin beddua tuttu sonunda Gurur dağlarını aştımd...', ARRAY['Türk Edebiyatı','Şiir','Ali Dilki']::text[], 8.5, '{"poet":"Ali Dilki","poet_slug":"ali-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bedduan-tuttu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ne Kadar Seviyorum?', 'seni-ne-kadar-seviyorum-suheyl-turkoglu-llqj5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben seni,

Ne kadar seviyorum,

Biliyor musun? 

Aşk kadar,

Doğa kadar,

Dünyalar kadar,

Çölün yağmuru,

Sevdiği kadar,

Anne babanın,

Evladına Düşkünlüğü,

Ve daha ötesi.

Sığmıyor,

Sığdıramıyorum,

Anlatamıyorum,

Tarif edemiyorum,

Öyle büyük ki sevdam,

Ben seni, 

Benim kadar seviyorum.', 'Ben seni, Ne kadar seviyorum, Biliyor musun?  Aşk kadar, Doğa kadar, Dünyalar kadar, Çölün yağmuru, Sevdiği kadar, Anne babanın, Evladına Dü...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-ne-kadar-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan, uyan, kalk uyan', 'uyan-uyan-kalk-uyan-mikdat-bal-8h4ge', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Memleket baştan başa, istilâ olmaktadır

Yabancı ne var ise, yurduma dolmaktadır

Din, ahlak, namus kültür, her şey kaybolmaktadır

Uyan, uyan, kalk uyan, gaflet sona ermeli

Yetmedi mi yattığın,  gaflete son vermeli

Ey gencim bu memleket, omuzunda emanet

Şu anda ki susuşun, değil sabır, metanet! 

Neler katıldı bize, işleniyor hiyanet

Uyan, sözümü duyan, hainleri sürmeli

Yetmedi mi kattığın, daha ne getirmeli

Sanal gündemler ile uyutmasınlar seni

Artık yakanı kurtar, kaptırmadan enseni

Kurtar vakit geçmeden, ipotekten hisseni

Uyan Allaha dayan, zulmü yere sermeli

Yetmedi mi çattığın, bu zulmü bitirmeli

Senin ilk gafletinden ikdidara gelmişler

Türkiye düzelecek, büyük bir lâf demişler

Türkiye diye diye, memleketi yemişler

Uyan artık yok doyan, ne bulup yetirmeli

Yetmedi mi sattığın, artık ipi germeli

Patronlar hep yabancı, ısrarla dayatıyor

Sahiller elden çıktı, satabilen satıyor

Borçlandık boğaza dek, bu memleket batıyor

Uyan Hakkı et beyan, hakikatı görmeli

Yetmedi mi battığın, mezara mı girmeli? 

Mikdat der uyanalım, uyaralım milleti

Türk’ün şanı yücedir,  kabul etmez zilleti

Canımıza tak etti, ayrılığın illeti

Uyan alkana boyan,Hakka ilerlemeli

Yetmedi mi tattığın,artık biberlemeli', 'Memleket baştan başa, istilâ olmaktadır Yabancı ne var ise, yurduma dolmaktadır Din, ahlak, namus kültür, her şey kaybolmaktadır Uyan, uyan,...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/uyan-uyan-kalk-uyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak', 'ciplak-yucel-gursac-ciqd8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Soyun'' dedi bana o..

dur dedim

senin adın ne

çıplağım zaten.

''soyun'' dedi yine

''işim acele..''

giyinsem nasıl olur

dedim kendime.

''soyun'' diye

bağırdı..

tenim acıdı.', '''Soyun'' dedi bana o.. dur dedim senin adın ne çıplağım zaten. ''soyun'' dedi yine ''işim acele..'' giyinsem nasıl olur dedim kendime. ''soyun'' di...', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ciplak-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Exi`s Çevarsı', 'exi-s-cevarsi-akin-akca-7pxy5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1.

ii.

Çıkarken Atlas, düz sırtlanan; 

Kaldırdığı ağırlıklar baskı yaptı

Kürek kemiklerine ve kanatlar,

Oldukça beyaz, baskıyla çıkarttı - 

Yüksekte, en yukarıda, direkte

i.

Binalardan kurtulmak için

Gökteki tek direğe tırmandı,

Zirve noktası delen bulutları

Ve geçen bile onların üzerlerini.

Adam direği çıktı, bir kez seven

Alışmayı, bisiklet hızlandırmak gibi -

Ve hümanizmanın ilerlemesi

Vatan sevgisiyle, iki seksen …

- Orta kısmını isin bürüdüğü eksen,

Göğü cüssesiyle yaran ekside.

Ama dışarı çevreydi burası,

Artı sonuçta elde edilen.

2.

Orgazmda gibi, orada, tepede; 

Nedense gençken bunun sözü

Geçmemişti ama anlatılıyor şimdi -

Yaşlılıkta çıktığın o direkte

- Her anlatı, anlatı amaçlı sadece.

Çıkmıştı çarçabuk basamakları

Ama işin doğası belli değil mi? 

:Yaşamak, bir dışarı açılmak; 

Bundan ve inmeye yine başladı –

Çıktığı’nın öncesi’nde yaptığı.', '1. ii. Çıkarken Atlas, düz sırtlanan;  Kaldırdığı ağırlıklar baskı yaptı Kürek kemiklerine ve kanatlar, Oldukça beyaz, baskıyla çıkarttı -  ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/exi-s-cevarsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sehir', 'sehir-ulya-erkman-pbbt3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakiyorum balkonumdan bir sehre

Isiklarla ortulmus sanki

Binlerce insani gizlercesine

Atiyor sessizce sehrin kalbi

Kimi olusune aglamakta

Kimi dogan bebege guluyor

Kimi yasiyor kahkahalarla

Kimi hastaya teselli veriyor

Piril piril bir sehirsin amma

Bagrinda ne karanliklar yatiyor

Insan oglu nerede olsada

Her cesit derdi yasiyor

Aydinlat karanliklari ama

Karanlik ruhlari ne yaparsin

Piril piril bir sehirsin ama

Kadere birsey yapamazsin

Yinede baktikca sana guzel sehir

Umitlenirim bende kendimce

Aydinlanacak karanlik gunlerim derim

Ruhuma isiklar serpilince

Ilham oldun bana isiklar sehri

Karanliklar gitti boylece icimden

Giriyorum simdi balkonumdan iceri

Umitlerle ortulu memnun kendimden

                    {Toronto  18 Haziran 2005 }', 'Bakiyorum balkonumdan bir sehre Isiklarla ortulmus sanki Binlerce insani gizlercesine Atiyor sessizce sehrin kalbi Kimi olusune aglamakta Ki...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sehir-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çigdem', 'cigdem-munevver-duver-sm6ji', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çiğdem dediler süslettiler çayırların arasını

Açtırdılar çiçeğimi, bahar mevsimleri benim

Başlattılar dağlardan, bayırlardan süslettiler ovayı

Evlerine götürerek şenlendirdiler yuvayı

Bende çiğdem olarak doğdum yuvamda 

Mutluluk verdim, üçüncü kardeş olarak evimde

Çınar, pınar derken, uydurdular sıraya

Açtım çiçeklerimi, kokuttum etrafıma

Kokular saçarak büyüdüm, serpildim

Okullara gittim, sonunda fakülteli oldum

Bittikten sonra da ne yapacağım diye kaygılandım durdum

Kaygılarda boş değil, şu ülkemin durumunda

Sevenlerim çoktu, bende sevildim de

İçlerinden biri de cananım oldu sonunda

O da canımı yaktı, uzaklaştı sonunda

Hep kafama takıp durdum onu da

Onu sevdiğim için, rahatça adından bahsettim

Adının geçtiği yerde de efkarlandım durdum

Her şeyin bitmesine rağmen, haber bekler oldum

Onun adının geçtiği yerde içim bir hoş oldu

Sevgili Çiğdem’ciğime en içten dileklerimle

Her şey gönlünce olsun

11.03.2004

DERNEK

PERŞEMBE 10:22

Münevver DÜVER', 'Çiğdem dediler süslettiler çayırların arasını Açtırdılar çiçeğimi, bahar mevsimleri benim Başlattılar dağlardan, bayırlardan süslettiler ova...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cigdem-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bölünemez mi yalnızlık', 'bolunemez-mi-yalnizlik-gulseren-onay-v4w05', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık

Paylaşılmazmış..

Bölünemez mi? 

İki yalnız 

Bir araya gelseler,

Yalnızlıklarını

Parçalara bölseler

Bölseler,

Bölseler,

Yok edip bitirseler...

GÜLSEREN ONAY

19/06/2005/ANTALYA', 'Yalnızlık Paylaşılmazmış.. Bölünemez mi?  İki yalnız  Bir araya gelseler, Yalnızlıklarını Parçalara bölseler Bölseler, Bölseler, Yok edip bi...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bolunemez-mi-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Sarı Lekeler', 'mutluluk-sari-lekeler-cetin-hacifettahoglu-l267j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluluk Sarı Lekeler

Mutluyum Limon Ekşiliğinde

Kimini Kamaştırır

Kimini Sarhoş Eder

Mutluyum Limon Ekşiliğinde', 'Mutluluk Sarı Lekeler Mutluyum Limon Ekşiliğinde Kimini Kamaştırır Kimini Sarhoş Eder Mutluyum Limon Ekşiliğinde...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mutluluk-sari-lekeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keklik pınarı', 'keklik-pinari-munevver-duver-8pw2b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baktım kavak ağaçları sallanıyor,

Sanki aşktan sarhoş olmuş biri gibi

Bir o yana bir bu yana gidip geliyor

Kafasın da bir plan yapar gibi

Keklik pınarının ötesinde yemyeşil ağaçlar

Yanlarında gökdelen apartman duruyor

Alt kısmında oynayan zeybek heykelleri

Kim bilir tepede kaç sevdalılar var.

Bakınca manzara bir başka güzel 

Sanki Ankara’yı tepeden süzüyor 

Karşıda yemyeşil ormanlar, uzakta dağlar

Evet kim bilir uzakta kaç sevdalılar var

Havası güzel oksijeni bol mu bol

Hanımları çok bakımlı, güler yüzlü

İçlerine girdiğin zaman hepten hüzünlü

Tertemiz bir semt çiçek kokulu.

.

15.05.2004.

Keklikpınarı / Ankara

Cumartesi Saat:11:43

Münevver Düver', 'Baktım kavak ağaçları sallanıyor, Sanki aşktan sarhoş olmuş biri gibi Bir o yana bir bu yana gidip geliyor Kafasın da bir plan yapar gibi Ke...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/keklik-pinari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Kuşlar', 'guzel-kuslar-munevver-duver-1m7nt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuşlar ah, güzel kuşlar var

Balkonuma konan gri kuşlar var

Beni hüzünlendiren eskiye götüren kuşlar var

Size baktıkça da kalbimin derinliklerine inen var

Ah kuşlar, minicik kuşlar

Bahar da göçmen kuşlar sizi havada seyretmek 

Sonbaharda yerde seyretmek güzel oluyor

Size bakarak ruhumda ilham buluyorum

Beynimin derinliklerine alıp götürüyor beni

Ah kuşlar,uzun gagalı,uzun ayaklı kuşlar

Kuşlar var, kocaman deve kuşları var

Çok sevimli, irili ufaklı, renkli, gagalı iri gözlü

Baykuşlar, kınalı keklikler,turaçlar var.

Eskinin postacısı,güzellerin sevdalısı kuşlar.

Ah kuşlar, sevdalı kuşlar.

27.02.2004

Huzur kent-Kadirli

Cuma Saat:08:06

Münevver Düver', 'Kuşlar ah, güzel kuşlar var Balkonuma konan gri kuşlar var Beni hüzünlendiren eskiye götüren kuşlar var Size baktıkça da kalbimin derinlikle...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/guzel-kuslar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamane Bade', 'zamane-bade-munevver-duver-f6z27', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamane’ye bakınca, ruhum açılıyor 

Senin baktığın yerlerde neşe saçıyor

Sanki bastığın yerlerde güller açıyor 

Zaten sende bir koklanmamış gül gibisin

Gül dedim ya sen gonca gülümsün benim

O kadar tatlısın ki nurludur yüzün senin

Seni çok seviyorum benim canım gibisin

Sen sevdiğinin de canı cananısın

Sen gönüllere taht kuracak kadar karakterlisin

Sen çalışıyorsun ama istediğin karaktere ulaşamıyorsun

Çok beceriklisin, çokta dürüstsün tatlımsın

Benim yanımda en yüksen yerlerdesin

Zamane zamanlar sana uğurlar getirsin

İstediğin yerlere giderek, istediğine kavuşasın

Sonunda da mutluluktan  uçar gibi olasın

Mutlu yuvalar kurarak mutlu olasın

Zamane zaman su gibi aksın önünde 

Güzellikler açılıp su gibi aksın önünde 

Sonunda okuyarak istediğin okullarda

Sende muradına eresin günün birinde

09.03.2004			

Özel İdare/Adana

Salı  Saat.09:39

Münevver Düver', 'Zamane’ye bakınca, ruhum açılıyor  Senin baktığın yerlerde neşe saçıyor Sanki bastığın yerlerde güller açıyor  Zaten sende bir koklanmamış g...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zamane-bade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emre Can', 'emre-can-munevver-duver-abrmn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Emre Can sen daha  on iki yaşındasın

İlkokul beşinci sınıfı okuyorsun

Aynı zamanda da matematiği de hiç sevmiyorsun

Annen Yüksel hatunu da çok üzüyorsun

Emre Can sen çok cadı ve sevimlisin

Çok zeki ama çokta hareketlisin 

Annenin de tek oğlusun sen

İlk adım apartmanın da oturuyorsun sen

Babandan uzak canın acıyor 

Ruhuna hüzün dolup taşıyor

Huzuru ararken  huzursuz oluyorsun 

Anneni de çok ama çok üzüyorsun 

Emre Can dilerim ufkun güneş gibi açılsın

Etrafına neşe verip neşeler saçıyorsun

Yüksek okullu olup paşa olasın

Annenin dilekleri de yerini  bulsun.

	                      				

   	

  17.05.2004

Keklik Pınarı / Ankara

Pazartesi   Saat:20:09

  Münevver DÜVER', 'Emre Can sen daha  on iki yaşındasın İlkokul beşinci sınıfı okuyorsun Aynı zamanda da matematiği de hiç sevmiyorsun Annen Yüksel hatunu da ç...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/emre-can-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cansın''ıma', 'cansin-ima-nilgun-akcay-1xqdy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözümün feri..

Yüreğimin sesi..

Hayatımın yörüngesi..

Birtaneciğim..

Nefretimi sevgiye

Karanlığımı güneşe

Hüznümü sevince

Döndüren sensin.

Hani derler ya…

Bir Ömre Bedelsin.

Seni anlatmak için

Kelimeler yetersiz

Duygular kifayetsiz…

Yıllar geçtikçe yüreğimde

Adsız bir duygu  büyümekte

Korku mu desem

İsyan mı desem

Ne desem…

Yıllar..Hain Yıllar…

O kadar çabuk geçtiler ki..

Bebekliğin,çocukluğun,

Genç kız oluşun

Bir film misali..

Su gibi geçti zaman..

Doya doya yaşayamadan.

Hani o duygu var ya..

İçimde dağ gibi kabaran…

Yuvadan uçacağın güne isyan..

Gün gelecek … 

Uzaklarda olacaksın…

Gün gelecek sadece..

Evin ayrı köyün ayrı

Ama yüreğin hep ben de kalacak..

Anılarımı..

Yıllar öncesini hatırlıyorum da..

O ilk bakışın..ilk kelimelerin..

İlk adımın..

Okumaya geçişin…

İlk diploma alışın…

İlk, orta,lise derken..

Tadına doyamadığım günlermiş meğer..

Abin sen ve ben…

Şimdi düşünüyorum da Yavrum..

Anne olarak sizlere ne verdim ki…

Hüzün,,gözyaşının yanında belki

Gururu,güveni anlatırken

Haykıramadım sevgimi

Ama eminim utandırmadım sizleri.

Hep derdin ki…

“Anne önce biz mi işin mi…”

Ben de ya susar ya da kızardım sana

Canım kızım.. 

Kaygılarımı,korkularımı..

Hayata isyanımı..

Haykıramadım sana..

O küçücük yüreğine..

Anlatamadım…

Sizsiz bir Yaşam bana Ölüm diye..

İşte böyle…

On sekiz yılı sığdırdım birkaç dizeye..

Canım yavrum..

Gözlerindeki Azminle..

Yüreğindeki kocaman sevginle

Aşılmaz,yenilmez cesaretinle..

Kaygıların ve korkularınla..

Kadere isyanınla..

Tüm duygularınla …her şeyinle..

SENİ ÇOK SEVİYORUM…

Canım Kızım.. CANSIN’IM..', 'Gözümün feri.. Yüreğimin sesi.. Hayatımın yörüngesi.. Birtaneciğim.. Nefretimi sevgiye Karanlığımı güneşe Hüznümü sevince Döndüren sensin. H...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/cansin-ima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Jale', 'jale-munevver-duver-85z37', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Telaşlı bir şekilde uğramıştım bankaya,

Baktım ki karşımda duruyordu bir güzel.

Bakmaktan kendimi alamaz oldum,

İsmin nedir diye soramadım kahroldum.

Güzelliğini Tanrı neşeli gününde ayarlamış,

Resim tablosu gibi çizmiş yaratmış.

Hayalimdeki kişi çıktı şans bana uğramış

Benim kalbimin güzelliğini de zaten kendi yaratmıştı

Sonradan adının Jale olduğunu öğrendim

Çevresindeki herkes ona Jale deyip duruyordu

Gittim sordum memura kim bu güzel diye

Anladı derdimi, konuştu sonunda o kişi.

Dış güzelliği çok hoştu içini bilemem! 

İçin güzelse sana yazacak çok şiirlerim var.

Kafama taktım seni, yolumdan dönemem.

Kitabımım bir bölümünde de sen olabilirsin bilemem..! 

14.09.2004	

BASINKÖY İSTANBUL

SALI SAAT.18:06

MÜNEVVER DÜVER', 'Telaşlı bir şekilde uğramıştım bankaya, Baktım ki karşımda duruyordu bir güzel. Bakmaktan kendimi alamaz oldum, İsmin nedir diye soramadım k...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/jale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '22 Eylülde Sen Funda', '22-eylulde-sen-funda-munevver-duver-1dyk2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok tatlı bir yüzün vardı funda

Gülerken gözlerinde gülüyordu funda

Tebessümlerin ruhları okşuyordu funda

Sanki seni yıllardır tanıyordum funda

Ruhun yüzüne yansıyıp duruyordu funda

Sana baktıkça kalbime neşe doluyordu funda

Sanki yıllardır aradım durdum bulamıyordum funda

Buldum sonunda kader bana yolladı, seni funda

22 Eylül 2004 benim için anlamlı oldu funda

Sanki ruhuma neşeler doldu funda

Seni bana kimler yolladı funda

Yollayan tanrı bana güzellikler verdi funda

Eylülde mucizeler olacak dediler funda

Fallarım da hep eylülü uğurlu buldular funda

Karşıma çıktın sonunda oldu doğru funda

Bende eylülde oldum mutlu funda

Fundaya sevgilerimle her şey gönlünce     olsun

22/09/2004 – 22:43

Çarşamba

Güzelyalı / ADANA

Münevver DÜVER', 'Çok tatlı bir yüzün vardı funda Gülerken gözlerinde gülüyordu funda Tebessümlerin ruhları okşuyordu funda Sanki seni yıllardır tanıyordum fu...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/22-eylulde-sen-funda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Betül', 'betul-munevver-duver-76gsl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen yeni bastın on beşi yaşına

Saçlarını döktün hilal kaşına

Yeni değdin bir sonraki yaşına

7 Şubat doğum günün kutlu olsun.

Sen açıldın,tomurcuktun gül oldun

Sen bir çiçektin,değişerek gül oldun

Sen bir ırmaktın, büyüyerek göl oldun

Sen bir çekirdektin,şimdi bir dal oldun

7 Şubat’ta doğdun doğum günün kutlu olsun.

Betül sen, 7 Şubat 1989’ da doğdun

Gözünü açtığında,etrafında halalarını buldun

Babanı da; bir başka severdin,sen bir tanem

Babaannene de; çok ama çok bağlandın

7 Şubat doğum günün kutlu olsun.

     

Sen şimdi bir karabiberimsin 

Çok tatlısın benim yeğenimsin

Aynı zamanda da; bir liselisin

Okulunda da; çok, çok başarılısın

7 Şubat doğum günün kutlu olsun.

	

06.02.2004

Güzelyalı / Adana

Cuma  Saat.19:20

Münevver DÜVER', 'Sen yeni bastın on beşi yaşına Saçlarını döktün hilal kaşına Yeni değdin bir sonraki yaşına 7 Şubat doğum günün kutlu olsun. Sen açıldın,tom...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/betul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tufan Tedbiri', 'tufan-tedbiri-adem-yaldiz-g12jz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benden sonra tufan diyenler

Gitmiş? 

Demek ki 

Tufan var günümüzde

Biz böyle demezisek

Selamet var önümüzde', 'Benden sonra tufan diyenler Gitmiş?  Demek ki  Tufan var günümüzde Biz böyle demezisek Selamet var önümüzde...', ARRAY['Türk Edebiyatı','Şiir','Adem Yaldız']::text[], 8.5, '{"poet":"Adem Yaldız","poet_slug":"adem-yaldiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tufan-tedbiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokum-casına!', 'yokum-casina-nurol-banabak-rp57g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Ben ordan geçerken biri

Amca dese, gir içeri…”

Aklıma bir zeval gelse de,

Yaşadığımı unutsam, ne olur? ! 

Doğmamış gibi olur muyum? 

Ama, ölmemiş de gibi! 

Kadın (veya aşk)  gereksinimim olsa, bilmesem.

Erkek (veya aşk)  gereksinimim…

Para pul gereksinimim…

Yaşasam, yaşamıyormuşum gibi! 

Ziftten bir yalnızlığım.

İçimin en içinde derince…

Gözlerini görsem O’nun bilmesem; 

Bilmediğimi de bilmiyorum gibi

İnsan’a en uzakta olsam,

Yokçasına, yokumcasına! 

Tanrıya en uzakta ve şeytana…

Şimdi, geçmiş ve gelecek yok gibi.

Ellerim tutsak, tutmasam.

Omurgam taşısa beni, taşınmasam.

Size gelip kapı eşiğine otursam, oturmasam.

Ama, kalkıp gitmesem de bir daha…

(-Sen, beni bilirdin, değil mi? 

-Huyumu suyumu, şuyumu buyumu…

-Şimdi, bildiğin şeylerde yeller eser.

-O vahalar çöl gibi.)', '“Ben ordan geçerken biri Amca dese, gir içeri…” Aklıma bir zeval gelse de, Yaşadığımı unutsam, ne olur? !  Doğmamış gibi olur muyum?  Ama, ö...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yokum-casina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Hayat', 'bizim-hayat-adem-yaldiz-fikx9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizim hayat

Ha yat 

Ha kalk

Farketmez', 'Bizim hayat Ha yat  Ha kalk Farketmez...', ARRAY['Türk Edebiyatı','Şiir','Adem Yaldız']::text[], 8.5, '{"poet":"Adem Yaldız","poet_slug":"adem-yaldiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bizim-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halimiz', 'halimiz-adem-yaldiz-5lsx3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yanı iğreti deve misali

Doğrusuz birikmiş sorunlar bizde

İlim teknik diye yapıp meali

Maymuna ata der torunlar bizde

Ne cevher insanlar sinmiş bir yerde

Sahnede oyun var kapalı perde

Gizlenecek ne var bilmem sansürde

Susun, konuşmayın, durun''lar bizde

Fakirden çocuğa fakirlik miras

Fakirlikle kalsa hakirlik miras

Bir yandan göklere yükselir teras

Karun''u çatlatır Karunlar bizde

Birileri bir yol bulmuş hep kapar

Dostuna der''Birazcık da sen apar''

Birisi yer biri bakar ne kopar? 

Korkarım karanlık yarınlar bizde', 'Her yanı iğreti deve misali Doğrusuz birikmiş sorunlar bizde İlim teknik diye yapıp meali Maymuna ata der torunlar bizde Ne cevher insanlar ...', ARRAY['Türk Edebiyatı','Şiir','Adem Yaldız']::text[], 8.5, '{"poet":"Adem Yaldız","poet_slug":"adem-yaldiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/halimiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü', 'cunku-cetin-hacifettahoglu-1w2p5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sakin Yürü

Ama Gürültülü Olsun Bakışların

Her Adımında Ezilen Milyonlarca Acı Olsun

Sen Yürü Acılar Un Ufak Olsun

Ve Yorulunca Bakışların Dur

Ayakların İster Bilirim Yolun Sonunu

Ama Sen Yinede Dur

Çünkü Bir Adım Önündedir Kocaman Pencere

Arkanda Kalan Kum Taneleriyle

Havada Uçuşan Toz Bulutudur Senin Dünyan

Derin Bir Nefeste

Ciğerlerine Yapışan Acıları Öksür Gökyüzüne

Toz Dinince 

Yağmur Yağıp Kum Taneleri Dökülünce Denize

İşte O Zaman Tekrar Ardına Dön

Çünkü Bir Adım Arkandadır O Kocaman Pencere', 'Sakin Yürü Ama Gürültülü Olsun Bakışların Her Adımında Ezilen Milyonlarca Acı Olsun Sen Yürü Acılar Un Ufak Olsun Ve Yorulunca Bakışların Du...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cunku-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertliler Meyhanesi', 'dertliler-meyhanesi-hatem-kardesler-4r4gc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yılmaz ŞAFAK''a

Hiç sormayın halimi içim dışım dert oldu,

Dertliler meyhanesi benim durağım oldu…

Benimle yaşayacak son çiçeğimde soldu,

Dertliler meyhanesi benim durağım oldu…

İçerim ve gezerim ne yaptığım bilmeden,

Ağlarım,inilerim göz yaşımı silmeden,

Ayrılığın,hasretin birgün sonu gelmeden,

Dertliler meyhanesi benim durağım oldu…

Erirken kadehlerde gecenin karanlığı,

Bir türlü tükenmedi gönlümün mahsunluğu,

İçerimde duyunca o zalim ayrılığı,

Dertliler meyhanesi benim durağım oldu…

         (Hasret İçimde Bir Dağ)  Kitabından', 'Yılmaz ŞAFAK''a Hiç sormayın halimi içim dışım dert oldu, Dertliler meyhanesi benim durağım oldu… Benimle yaşayacak son çiçeğimde soldu, Dert...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dertliler-meyhanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olumsuz...', 'olumsuz-hatem-kardesler-oobre', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmek; 

Bir ışık.bir kaynak,ki ilmin en yücesi

Ama,

Ha deyince bilinmez ki…

Gülmek; 

Güzel beklide en tatlı şey dünyada

Ama,

Ha deyince gülünmez ki…

Gelmek; 

Yalan olan tek gerçek

(Uzatsam elimi kavuşuruz) 

Ama,

Ha deyince gelinmez ki…

Sevnmek; 

İçten,gönülden,yürekten sevinmek

Ama,

Gel görki deli gönül

Ha deyince sevinmez ki…

Ölmek; 

Bir düş,bir umut bir can simidi

Ama,

Ha deyince ölünmez ki…

		         (Hasret İçimde Bir Dağ)  Kitabından', 'Bilmek;  Bir ışık.bir kaynak,ki ilmin en yücesi Ama, Ha deyince bilinmez ki… Gülmek;  Güzel beklide en tatlı şey dünyada Ama, Ha deyince gül...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olumsuz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-bahri-orhan-6qvt5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur damla damla düşerken gönüle

Alır beni bir sevinç çisil çisil ıslanırken

Dallarda sevgi tomurcukları filizlenirken,

Bahçelere ekildi güldesteler.

Mevsim bahara dönerken kardelenler

Bir ikindi güneşi gibi batmakta,

Nice güzellikler dönmek için bahara...

(8 Mart 2005  Hozat)', 'Yağmur damla damla düşerken gönüle Alır beni bir sevinç çisil çisil ıslanırken Dallarda sevgi tomurcukları filizlenirken, Bahçelere ekildi g...', ARRAY['Türk Edebiyatı','Şiir','Bahri Orhan']::text[], 8.5, '{"poet":"Bahri Orhan","poet_slug":"bahri-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kardelen-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyhan', 'beyhan-munevver-duver-tcr0q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni görünce baharı anımsattı bana

Güller açmıştı tüm çehrende

Gözlerin gökyüzünü, kaşların kemanı andırıyordu.

Yanağına elma oturtturulmuştu sanki.

Sen baharlar kadar güzeldin Beyhan.



Boyun selvi ağacı sanki serpilmiştin

Ruhun hurilere benzeyip, ilham vermiştin

Nürünberk sokaklarında bende seni bulmuştum.

Fürth’teki akasyalara benzetmiştim.

Sen baharlar kadar güzeldin Beyhan.



Kalbin yüzün aynası olmuştu sanki.

Melekler kadar güzeldi ruhun

Resimlerine bakarak avunuyorum ben.

Rüyalarımı süslüyordun hepten sen

Sen baharlar kadar güzeldin Beyhan.



Doğmuşsun Almanya’da almışsın kültürünü

Türkiye’yi çok seviyorsun, hep onunlasın.

Hep memleket aşkıyla yanıp tutuşuyorsun.

Varsa yoksa Türkiye’m diyorsun.

Sen baharlar kadar güzeldin Beyhan.



07.08.2004

GÜZELYALI- ADANA

Cumartesi – 22:00

Münevver Düver', 'Seni görünce baharı anımsattı bana Güller açmıştı tüm çehrende Gözlerin gökyüzünü, kaşların kemanı andırıyordu. Yanağına elma oturtturulmuşt...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beyhan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Çilesi-4+', 'ask-cilesi-4-bayram-tunca-67z6y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllarca, hülyalarımda misafir ettim

Kavuşmak için divane gibi seğirttim

Aşk koruyla yanan, ne ilk ne tektim

Ah bir bilsen, aşktan ne çok çektim

Bazen gecemden gündüzüme kattım

Bazen gündüzümden geceme kattım 

Aşkı doymak için durmadan çalıştım

Ah aşktan yana da karaymış bahtım

06.04.2003-16:04

''Aşk Ateşten Gömlek''', 'Yıllarca, hülyalarımda misafir ettim Kavuşmak için divane gibi seğirttim Aşk koruyla yanan, ne ilk ne tektim Ah bir bilsen, aşktan ne çok çe...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-cilesi-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CANIM Anam''a', 'canim-anam-a-nilgun-akcay-bmxu4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu mektup sanadır,ANAM..

Hasretin tüter burnumda.

Nerden başlasam anlatmaya..

Bilmem ki.

Bir günümü anlatayım sana

Yalnızca bir günümü.. ANAM.

Geçen akşam üstüydü.

Şirin  küçük bir köydü.

Biz ise on iki asker,ölmeye gönüllü…

Yürüyorduk köye doğru.

Alacakaranlığın sessizliğinde

Buram buram sıla hasretiyle.

Dalmıştık gurbet türküleriyle

Yanık,içli hasret kokan

Memleket sohbetlerine

Gururluyduk.

Çünkü Vatan Bekçileriydik.

Vadinin derin sessizliğini

Bozdu birden silah sesleri

Onlarca belki de Yüzlerce namlu

Üzerimize doğrulmuştu..

İlk Kurşunla vurulmuştu arkadaşım

Sırada ben vardım..ANAM

Ben…

Ağaçlar… Kayalar..

Bize Kucak açmıştı..

Düşmana karşı.

Saklıyordu bizi hain kurşunlardan.

On İki askerden 

Bendim en şanslı olan..

Sadece vurulmuştum Omzumdan.

O gün de ölmemiştim ANAM.

Ne mutlu bana 

Kanım akmıştı Vatanım için..

Ve Ne mutlu sana ki ANAM

Sen Artık  Gazi ANASISIN..

Dua senden ANAM dua senden.

Eksik etme üzerimizden.

Bir evladın olarak geldim..

Bin evladınla döneceğim..ANAM.

Yarın ölsem de ANAM..

Sakın üzülme..

Senin gibi binlerce Anamızın duasına

Güç yeter mi ANAM:..

Sözüm sanadır ANAM…

Daha hangisini anlatsam..

Haber geldi ilçeden..

Dediler ki şenlik varmış.

Analar günüymüş bugün..

ANALAR GÜNÜ..anam..

İçim buruldu birden.

Gözümde sen..Gönlümde sen..

Canım ANAM..Bir bilsen..

Ne çok üzgünüm.. ANAM 

Seni Şehit Anası edemedim …ANAM..

Bu sana armağanım olacaktı..

Olmadı… ANAM..Olmadı..

Vatan sağ olsun..

Canım Anam, Günün kutlu olsun..

br> width=''100'' height=''16'' autostart=''true'' loop=''true''>', 'Bu mektup sanadır,ANAM.. Hasretin tüter burnumda. Nerden başlasam anlatmaya.. Bilmem ki. Bir günümü anlatayım sana Yalnızca bir günümü.. ANA...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/canim-anam-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyzene 21.yüz yıldan selam olsun 1', 'neyzene-21-yuz-yildan-selam-olsun-1-ali-osman-yilmaz-yoemj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buş’un palyaçosu,şu kasımpaşalının halini gör,

Yurdun Sinesine ne ihanetler ekiyor,

Yuları küffarın elinde,türban da dilinde,

Bu amerikan eşeğini,360 arap atı  zor çekiyor.', 'Buş’un palyaçosu,şu kasımpaşalının halini gör, Yurdun Sinesine ne ihanetler ekiyor, Yuları küffarın elinde,türban da dilinde, Bu amerikan eş...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/neyzene-21-yuz-yildan-selam-olsun-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk-1', 'cocuk-1-hatem-kardesler-y0gyb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocuk...Dünyanın en saf,en masum,en dürüst,en içten,en güzel yaratığı...O küçücük gönlünde okyanusları barındıran bir çağlayansın sen...Sen yatağına sığmayan nehirsin çocuk...

		Yalanı biz öğrettik sana. Biz öğrettik sana güvensizliği... Kaleme aldığımız güzel şeyleri kağıtlarda bıraktık. Yaşama geçiremedik. Bir azgın nehir örneği vurmayı,kırmayı,yıkmayı savaşı öğrettik. Tepemizde barış güvercinlerinin uçuştuğu bir ortamda oyuncak silahlar verdik eline...Taramalı verdik,toplu verdik,barabellum verdik...Bilim kurgularla seni barıştan soğuttuk,savaşa özendirdik...

		Okula başlattık sonra seni,hiç hazırlıksız...Ne için okuman gerektiğini bile anlatamadık...O körpe beynine akıl almaz şeyleri yerleştirdik. Resime yetenekliysen müzikci yaptık...Müziğe yetenekliysen ziraatçı... Lisede de hiç kimse seni düşünmedi çocuk...Başarıyı hep notta aradık. Hep birileriyle mukayese ettik seni...Hep birilerinin önünde ol istedik... Ama sen farklıydın. Biz bunun farkına varamadık...Üniversite sınavına gönderdik sonra seni...Hukuk istedin,filoloji çıktı karşına. Güzel sanatları istedin,veteriner hekimliği...Bütün büyüklerin birlik olduk; okumadan yazmadan diploma alabilmen için,okuma dan yazma dan nefret etmen için elimizden gelen her türlü gayreti gösterdik...Şimdi de senden şikayet ediyoruz çocuk...Kitap okumuyor.,gazete okumuyor,dergi okumuyor diyoruz...

		Bu çarpık düzende hala okuyabilen,yazabilen,araştırabilen kardeşlerin varsa inan ki gözümüzden kaçmıştır. Yoksa bu tezatlar içerisinde biz onlarında yuvasını yapardık...

		Dileğim düşünce ikliminin esrarlı atmosferinde seferlerine devam etmen...Temiz,saf,ikiyüzlülükten uzak o çocuk gönlünü hiç yitirme çocuk... Ama ilmi Çin''de de olsa ara. Şunu da unutma; önce kendini tanı, insani duygularla donan. İlim biraz gayretle öğrenilir. Yunus''un dörtlüğü rehberin olsun...

		'' İlim ilim bilmektir.

		İlim kendin bilmektir.

		Sen kendini bilmezsin,

		Bu nice okumaktır...''', 'Çocuk...Dünyanın en saf,en masum,en dürüst,en içten,en güzel yaratığı...O küçücük gönlünde okyanusları barındıran bir çağlayansın sen...Sen ...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cocuk-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyzen''e 21 yüzyıldan selam 2', 'neyzen-e-21-yuzyildan-selam-2-ali-osman-yilmaz-eqjbl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Makam ve mevkii,çok oldu gözümden düşeli,

Hiç kıymeti olmadığını,yaşayarak öğrendim,

Şimdi de kalmadı liranın bende kıymeti,

Uncu’nun elinde görünce,paradan da iğrendim.', 'Makam ve mevkii,çok oldu gözümden düşeli, Hiç kıymeti olmadığını,yaşayarak öğrendim, Şimdi de kalmadı liranın bende kıymeti, Uncu’nun elinde...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/neyzen-e-21-yuzyildan-selam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyzen''e 21. yüzyıldan selam 3', 'neyzen-e-21-yuzyildan-selam-3-ali-osman-yilmaz-1s4nu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nayloncunun başı her yerde göründü,hem de,

Yüzünde sahte bir gülücük,hala sırıtıp duruyor,

Kedinin yavrusuna verdiği lağım faresi gibi,

Medyacılarla el ele,halkı soyup,boğduruyor.', 'Nayloncunun başı her yerde göründü,hem de, Yüzünde sahte bir gülücük,hala sırıtıp duruyor, Kedinin yavrusuna verdiği lağım faresi gibi, Medy...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/neyzen-e-21-yuzyildan-selam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyzen''e 21. yüzyıldan selam 4', 'neyzen-e-21-yuzyildan-selam-4-ali-osman-yilmaz-sczkj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl olsa binecek üstüme avrupalı,

Semerimle,nalımı enseledi  kasımpaşalı,

Hoşbakanım,yularım bari başımda kalsın,

Beni at zannederek,gem takacak amerikalı.', 'Nasıl olsa binecek üstüme avrupalı, Semerimle,nalımı enseledi  kasımpaşalı, Hoşbakanım,yularım bari başımda kalsın, Beni at zannederek,gem t...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/neyzen-e-21-yuzyildan-selam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şu Aşk ki+', 'ah-su-ask-ki-bayram-tunca-p9gkv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk kimleri veli etmedi ki

Aşk kimleri deli etmedi ki

Aşk kimleri kör etmedi ki

Aşk kimleri esir etmedi ki

Aşk kimleri arattırmadı ki

Aşk kimleri yalvartmadı ki

Aşk kimleri ağlattırmadı ki

Aşktan kim memnundu ki

Aşk kimleri mecnun etmedi ki

Aşk kimleri pişman ettirmedi ki

Aşk uğruna nelere katlanılmadı ki

Aşk uğruna neler feda edilmedi ki

Aşk olmasaydı, âşık olur muydum sana ki

Aşk olmasaydı, âşık olmazdın sen bana ki

Aşk olmasaydı, âşık/maşuk olur muydu ki

Aşk olmasaydı, yaşamın tadı mı olurdu ki

Aşk uğruna nice acı şiirler yazılmadı mı ki

Aşk uğruna nice destanlar yazılmadı mı ki

Aşkı anlatan nice türküler söylenmedi mi ki

Aşkı dillendiren nice şarkı söylenmedi mi ki

Şu aşk Kerem ile Aslı’ya bile yâr olmadı ki

Şu aşk yâr mı olur sanıyorsun sen bana ki

Şu aşk yâr mı olur sanıyorsun hem sana ki

Şu aşktan memnun olup giden var mıdır ki

Şu aşk Veysel’lere çölleri arşınlatmadı mı ki

Şu aşk Ferhat’lara dağları deldirtmedi mi ki

Şu aşk Leylâ’ya parmağını kestirtmedi mi ki

Şu aşk nice kulu, çöllerde gezdirtmedi mi ki

Aşkı kim tam anlatabilmiş ki, ben anlatabileyim

Aşk uğruna ben de çok çile çektim itiraf edeyim

Aşk uğruna çile çekenlerden ne ilk/ne de tektim

Aşkı öğrenip/yaşayım derken, ömrümü tükettim

Hem, aşkı da bir hikmete binaen, Allah yaratmadı mı ki

Kulunun istek ve arzusunu ebede kadar uzatmadı mı ki

Baharı istettiği gibi cennet-i cemalini de istetmedi mi ki

Hem her şeyi  bir hikmete binaen, Rab yaratmadı mı ki

12.12.2000-14:00

''Aşk Ateşten Gömlek''', 'Aşk kimleri veli etmedi ki Aşk kimleri deli etmedi ki Aşk kimleri kör etmedi ki Aşk kimleri esir etmedi ki Aşk kimleri arattırmadı ki Aşk ki...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ah-su-ask-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitap', 'kitap-rifki-kaymaz-jtuy9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ruhumun en güzel gıdası kitap

Odur benim candan dostum, yoldaşım.

İlme el, mutluluk,en güzel hitap,

Tükenmez hazine ve arkadaşım.', 'Ruhumun en güzel gıdası kitap Odur benim candan dostum, yoldaşım. İlme el, mutluluk,en güzel hitap, Tükenmez hazine ve arkadaşım....', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kitap-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Mektubu', 'dost-mektubu-rifki-kaymaz-wy6d1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ruhumun en güzel gıdası kitap

Odur benim candan dostum, yoldaşım.

İlme el, mutluluk,en güzel hitap,

Tükenmez hazine ve arkadaşım.', 'Ruhumun en güzel gıdası kitap Odur benim candan dostum, yoldaşım. İlme el, mutluluk,en güzel hitap, Tükenmez hazine ve arkadaşım....', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dost-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem Canim Annem', 'annem-canim-annem-munevver-duver-swnqa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canim annem, dalgin yatiyorsun..

Gözlerini kapatiyorsun

Alev alev yaniyorsun

Hiç kalkmayacak gibi duruyorsun.

beni can evimden vuruyorsun.

Canim annem rengin sapsari duruyorsun

Gözlerime bakarak agliyorsun

Sanki kendi halini biliyorsun.

Sagindan soluna dönemiyorsun

Beni can evimden vuruyorsun.

Atesler içinde sayikliyorsun

Durmadan çocuklarini soruyorsun

Her dalisinda Tahiri''im Haci''m diyorsun

Durumun çok kötü sende biliyomusun? 

Beni can evimden vuruyorsun.

Balcali hastanesi yogunbakimda yatiyorsun

Beni basucunda hep istiyorsun

Dayanamiyor kalbin içten içe eriyorsun

Durmadan gözlerini akitiyorsun.

Beni can evimden vuruyorsun.

Canim annemi 23 nisan 2005 te yogunbakima yatirdik.

Canim annemi 25 mayista yogunbakimda  kaybettik 

canim annemdi, çok sevdigimdi,yasam kaynagimdi

Onsuz ne yaparim bilemiyorum...

.

24/04/2005

balcali hastanesi yogunbakim

Pazar saat 18.50

www.munevverduver.com', 'Canim annem, dalgin yatiyorsun.. Gözlerini kapatiyorsun Alev alev yaniyorsun Hiç kalkmayacak gibi duruyorsun. beni can evimden vuruyorsun. C...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/annem-canim-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kizil Saçli Nurten'' im', 'kizil-sacli-nurten-im-munevver-duver-tblsl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kizil saçlim Antoloji'' de tanistik

Mesajlasip, yazisip sonunda bulustuk.

Candan kucaklasip göz göze öpüstük

Sanki ayrilmista, yeni kavusanlar gibi koklastik

Dogum günün kutlu olsun NURTEN'' iM.

Birbirimize baglandik kardes gibi olduk

Sözlesip tas mekanda bulustuk

Ayrilamaz olduk, bu ne hal diye konustuk

Çok sevdik birbirimizi,mutluluktan sarhostuk.

Dogum günün kutlu olsun NURTEN'' iM.

kizil saçli  güzel ruhlu arkadasim Nurten Turan Yüksel

20  haziran 2005 dogum gününü kutlar mutluluklar

diliyorum.hayatin tüm güzellikleri onunla olsun......

17/06/2005 çarsamba

güzelyali/Adana

çarsamba saat 09.07

Münevver düver', 'Kizil saçlim Antoloji'' de tanistik Mesajlasip, yazisip sonunda bulustuk. Candan kucaklasip göz göze öpüstük Sanki ayrilmista, yeni kavusanla...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kizil-sacli-nurten-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 6', 'guncel-beyitler-6-huseyin-avdic-vmz2v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölüp de toprakta cürümekten korkma, tohum gibi ol.

Korkusuz tohum agac olur, dirili$e bulur yol.

******

(Bana ''cahillik'' isnad edenlere! ..) 

Sizin ilim dediginiz $ey, benim dilimde bir noktadir.

''Bilim'' diye yaptiginiz ise, o noktayi cogaltmaktir.

******

Evren varsa, Allah da vardir.

Allah yoksa, hic bir$ey yoktur! 

******

Iki ce$it insan vardir dünyada; biri yapicidir, biri yikici.

Yapici olmalidir insan her an, yapicilar insanligin sertaci.

******

$iir; Hakk''i, iyiligi, dogruyu söylemenin edebî araci.

Bu araci suistimal edenler, olur $erre $eytanî araci.

******

Be$ vakit Namaz, senin icin en iyi meditasyondur.

Namazsiz meditasyon, kabul edilemez bir kulluktur.

Berlin, Haziran 2005.', 'Ölüp de toprakta cürümekten korkma, tohum gibi ol. Korkusuz tohum agac olur, dirili$e bulur yol. ****** (Bana ''cahillik'' isnad edenlere! ..)...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/guncel-beyitler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^^^^Gider^^^^', 'gider-mehmet-hulusi-reyhan-29dmp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Değmeyin seherde yaslı gönlüme,

Çatlar baraj gibi sel olur gider.

İcranı hasred''den paslı gönlüme,

Kırılır toplanmaz el olur gider.

Saçarım gizlenir gözümden yaşı,

Çalmadık taş mı var bu garip başı,

Vermeyince meğbub eşide eşi,

Tutarsın tutmaya yel olur gider.

Bir kere kadere mağlupsa mevkiin

Savrulmaya mahkum sevincin, şevkin,

Dolarda izinin çıkarda sevkin

Zevat-i hayalin sel olur gider.

Sabır et isteme payından fazla,

Mertten umutlan da namertten asla,

Namert verir damla alırda tasla

Başında saç kalmaz kel olur gider.

Bir rüya gemisi bindiğin gemi,

Hep riya gemisi bindiğin hemi,

Vicdansız hayasız tutmuş dümeni,

Sen ağladıkça da kıl olur gider.

Sakın düşme gama gümen et güven,

Puştun elinden de alınır dümen,

Taş öğütür bir gün gelir değirmen,

O lanet günaha pul olur gider.', 'Değmeyin seherde yaslı gönlüme, Çatlar baraj gibi sel olur gider. İcranı hasred''den paslı gönlüme, Kırılır toplanmaz el olur gider. Saçarım ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hulusi Reyhan']::text[], 8.5, '{"poet":"Mehmet Hulusi Reyhan","poet_slug":"mehmet-hulusi-reyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gider-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manevi Kızım''a', 'manevi-kizim-a-nilgun-akcay-04nvy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Candan içeri CANSIN 

Ana yüreğinde harsın 

Nerde olursan ol yanımızdasın 

Sevgimiz canına can katsın 

Işığın duamız,yardımcın Yaradan olsun 

Niyetimiz,duamız Sağlığın için; kabul olsun..', 'Candan içeri CANSIN  Ana yüreğinde harsın  Nerde olursan ol yanımızdasın  Sevgimiz canına can katsın  Işığın duamız,yardımcın Yaradan olsun ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/manevi-kizim-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaranlar(5)', 'sahmaranlar-5-i-smet-barlioglu-k19y8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '‘İçeriye girince hangi seslerin hangi pavyonlara ait olduğu daha iyi anlaşılıyor.’ Du.

Tele-Gide pavyonunda, ondört yaşlarında, spor gömlekli, sarışın bir oğlan, direksiyona kablolarla bağlı bir minyatür otoyu uzaktan falsosuz yöneterek trafik engellerini aşırıp masa üzerindeki garaja sokmaya çalışıyordu.Oto garaja giremeden, falsoyu duyuran ziller çaldı. Direksiyon kitlendi.

Kelimeleri tek tek okuyan ciddi tonlu bir ses görünmeyen bir hoparlörden sesleniyordu:

- Paris ‘te, Londra ‘da, Berlin ‘de, Lizbon ‘da ve Roma ‘da, adları dillerde destanlaşan korkusuz Bahadır Kardeşler ‘in Motosiklet Ölüm Silindiri… Ölüm numaralarını seyredeceksiniz… Ölüm silindirinde.

Galvanizli sacdan yapılma buğday silolarına benzeyen ve tahtadan yapılıp dikine oturtulmuş olan silindirin dibinde bir kapı vardı. Kapının yanından, bir kenarı parmaklıklı bir merdivenden, karışık bir seyirci kalabalığı yukarı çıkıyordu. Kulenin üzerinde çepeçevre insan başları göze çarpmaktaydı. Dipteki kapı açıldı. Motosiklet sürücüsü giyinişli bir gençle bir genç kız gülüşüp şakalaşarak, çıkıp kapı önünde konuşmaya daldılar.

‘ Korkusuz Bahadır Kardeş, şimdilik kız tavlamakla meşgul.’

Kulenin yakınlarından bir yerden sürekli bir zil sesi duyuldu. Arkasından, harıltılı-gürültülü motor çalışmaları başladı. Dış kenarlarındaki parmaklık çevrili taraçalarına bir seyirci kalabalığının yığıldığı pistte altları çember lastikli, iki kişilik, renk renk mini otolar koşuşuyordu. Pistin üzeri kare delikli bir tel kafesle örtülmüştü. Otoların arkalarında dikine dikine metal çubuklar vardı. Bunların tırpan gibi kıvrak uçları tel kafese sürtünüyor, otolarla birlikte kayarak ilerliyor, her geçtiği yerden mavimtrak, tatlı bir elektrik şeraresi çıkarıyordu. Otolar fazla, pist ise çok küçüktü. Bu yüzden, arabalar, sürücülerinin kaçınmalarına aldırmadan çarpışıyor, her çarpışmada alttaki çember lastik kalkanlardan kof sesler çıkıyordu.

Delikanlı büyük bir ilgiyle piste bakıyordu. Özellikle, çarpışmamak için başkalarından kaçan ve otosunu hep pistin boş yerlerinde sürmek isteyem sürücüleri seyretmekteydi. Onlar trafik kargaşalığının kurbanı oldukça yüzünün biryerlerinde bir şeyler seğiriyordu.

‘Doğa kararlıdır. Bilinçlidir. Ters gidilmez doğayla. Yönü tektir. Her yol o yöne çıkar. Çabalama, Faraday ‘ın kafesindeki kuş. Çirkin akıllı kuş. Baykuş. Faraday ‘ın kafesi kafes. Faraday ‘ın kafesi gerçek. Faraday ‘ın kafesi mızrak gibi gerçek. Çarpışmak kaderin senin. Çünkü fiziğin ona göre. Kağıdın kaderi yırtılmaktır. Fiziği öyle. Ve camın kaderi kırılmaksa ve insanın kaderi şuysa, buysa. Çabalama Faraday ‘ın kafesindeki çirkin akıllı kuş. Fiziğe ters düşemezsin. Say ki; kaderine. Suda boğulan balık gördün mü sen hiç? ’

Sürekli bir zil sesi duyuldu. Otoların hepsi durdu. Sürücülerin tamamı gülümsemeli indiler otolarından ve piste dağıldılar. Sonra, ayrılanlar gelenlerle karıştılar.

Delikanlı başını gökyüzüne kaldırdı. Koluna birileri çarpıp geçtiler. Yukarda, uzak derinliklerde, gökyüzü sarı sarı deliklerle doluydu.

‘İki elektrikli alan. Biri yukarıda, biri aşağıda. Bur ‘da. Ayaklarımın altında. Beni tutan. Çivilemeyen. Ne yukarı, ne aşağı. Hiç olmasa; yukarı düşerim. Altı-üstü yok bunun. Aşağısı-yukarısı yok. Orada, o deliklerin bulunduğu biryerlerde aşağıyla yukarı bir. Pis iş. Ve bunlar robot. Ve bunlar, otoyu kısa süre yönetenler. Şartelin indiği yerde, yetenek sustu. Şartele saygı duruşu. Üç dakika. En az üç dakika. Üç saat. Üç yüzyıl. Üçyüz ve üçyüz mültimilyar yüzyıl.’

Birkaç kişi daha merakla başlarını gökyüzüne kaldırdılar, baktılar.,Birileri:

- Hava ne güzel. Şahane yaz havası.

Dediler.

Kukla pavyonunun açık kapısından bakılınca; mini sahnedeki kuklalar uzaktan görünen gerçek adamlara benziyorlardı.

‘Tuzsuz Bekir kapıya dayanmış.’

Biryerlerde kuvvetini deneyen bir adam bir yumrukta 180 kilo vurdu.

‘Acaba Arşimed kaç gram vuruyordu? ’

Dört köşe bir çadırın üzerine asılmış olan bez resim, ta yukarılardan çadırın açık kapısına kadar iniyordu.Resimde, gövdeleri cetvelden çıkma, koyu yeşil ağaçlar vardı. Bunlar arasında, sadece edep yerleri kapalı, kendileri çok kalın dudaklı beş-on zenci göze çarpmaktaydı. Zenciler soba borusu kalınlığındaki bir yılanı karga tulumba kaldırmışlardı. Yılan insan başlıydı. Ayni resimli bezin üzerinde ilgi çekecek ve çok kolay okunacak irilikte yazılar vardı: Afrika ‘nın balta girmemiş ormanlarında dört yerliyi yedikten sonra on zenci tarafından yakalanan, başı insan, vücudu yılan Şahmaran ‘ın resmi.

Bir-iki meraklı gişeciyi arıyorlardı. Gişe boştu. Bunlardan birisi:

- Hamama gitmiş.

Dedi. Obirisi:

- Guslünü, tahretini alsın, gelsin.

Diye güldü. Sonra ayni adamlar biletsiz olarak içeriye girdiler. Delikanlı da onlarla birlikte çadıra girdi ve kalabalığa karıştı.

Çadırın ortasında boydan boya kalın bir ip gerilmişti. Bel hizasına gelen bu ip seyircilerin daha ileriye geçmesini engelliyordu. İpin bu yanından başlayan bir meraklı kalabalığı, sandalyesiz çadırın giriş yerine kadar yayılıyordu. İpin öte yanında, çiçekli mavi basmadan büyük bir perde vardı. Perdenin yanında bir adam, ayakta sigara içiyordu. Arapların giydiği cinsten uzun ve beyaz bir ipek entari giymişti. Beli ipekli bir kuşakla bağlıydı. Entari üstünde sırmaları parıldayan bol işlemeli bir yelek vardı. Başını Hintlilerin sardığı biçimde bir sarıkla sarmış, ön ortasına yeşil renkte, yontma, iri bir değerli taş koymuş, bu taşın dibinden renkli tüylü genişçe ve yüksekçe bir sorguç takmıştı. Kulaklarında kadınların kullandıkları geniş halka biçimli, sarı metal küpeler sallanıyordu. Çeneden sakallıydı ve bıyıkları uzanarak sakalına birleşmişti. Sırtında, kendisi siyah, astarı kırmızı, pahalı bir ipek pelerin vardı.

Çadırı dolduran ve dakikalar geçtikçe çoğalan kalabalık, sanki para ödenerek seyredilecek oymuş gibi, ipek pelerinli, başı sorguçlu, sigara içen adama bakıyordu. Adam ise, biletiyle seyre gelen onlar değil de, kendisiymiş pozundaydı. Törene katılacak öğrencilerini sayan bir öğretmen gibi, kalabalığa göz gezdiriyor, arada bir sigarasından bir nefes çekiyor, dumanı her iki burun deliğinden çenesindeki sakalına doğru fişek gibi püskürtüyordu.

Çadırın giriş yerinde, kulaklara zor veren bir hoparlör sesi yükseldi:

- Canaballah ‘ın kereminden suval olunmaz. Dünyanın yedinci harikası Şahmaran bu çadırda… Başlıyor… Afrika ‘nın balta girmemiş ormanlarında, dört kişiyi yedikten sonra, on zenci tarafından yakalanan Şahmaran bu çadırda… Baş insan, vücut ilan…Canaballah ‘ın mucizesi… Bir gören bir daha görmek istiyor… Biletler elli kuruştur… Girmekte, görmekte acele ediniz…

Çadırın içinden birileri gülüştü:

- Hamamdan gelmiş.

- Guslünü, taharetini almış, gelmiş.

Kalabalığın en gerisinde ayakta duran delikanlı, ipin ötesinde burun deliklerinden duman çıkaran adama bakıyordu.

‘Adam rahat değil. Bizim rahat olamadığımız gibi. Olmak istediğini olamamış. Bu doğru. Rahat değil. Olduğu bu değil. Olmak istediğini olmaya çalışıyor. Köylü. Yüzünün çizgileri kaba. İlkel. İşlenmemiş. Taslak nasılsa yapıt öyle kalmış. Gözlerinde parıltı yok. Biryerlere ilgiyle baktığı zaman ağzı düşüyor, kapatmasını bilemiyor. İlkel. Zeki değil. Ama kendini zeki sananları aldattığından emin. Gerçekte, zekayı değil, merakı aldatıyor. Bilinçsizlik bilinci aldatamaz. Bu çelişmedir. Bilinçsizlik merakı belki aldatabilir. Bu doğru.’

Hoparlördeki ses son anonsu yaptı:

- Program başlamıştır… Bundan sonraki gösteri için acele ediniz…

Hoparlörden konuşmuş olan dışarıdaki adam, çadırın yukarıya tutturulmuş olan bez kapısını çözüp aşağı bıraktı.

İpin ötesindeki, sigarasını yere atıp ayağıyla ezdi. Bir yerlere uzanıp bir eline tahta saplı, metal çanlı bir okul çıngırağı, diğerine ince, uzun bir çubuk aldı. Konuşmaya selamsız, sabahsız girdi. Sesi kalın, oturaklı ve etkiliydi:

- Kıymatlı vatandaşlar… Analar, bacılar… Kardaşlar, babalar… Cenaballah 2ın lütfü keremiynen sizlere dünyanın yedinci harikasını göstereceğiz… Yalanız, içinizde eğer ki hamile kadınlar var ise, lütven bu çadırdan çıksınlar. Nabalda kalmayalım. Mucize gösterirken fenalık etmeyelim. Yaniya kaş yaparken göz çıkarmayalım. Eğer ki kalp hastaları var ise, haşa huzurdan, güçcük abdestini veya ki iri abdestini tutamıyan var ise bunlar da çıksınlar. Bu dediklerim ki bu çadırdan çıkmadan ben bu işe başlamam.

Çadırdaki herkes birilerinin çıkmasını bekliyor, tanısın tanımasın birbirlerine ‘Çıksana, sen küçük abdestini tutamazsın, ben biliri.’ gibilerden bakıyorlardı. Sonunda o kalabalıktan hiç kimse bu noksanlık suçlamalarını kabul edip dışarı çıkmadı.

- Suç benden gitti. Artık mesuliyet kabıl edilmez. Deseniz de edilmez. Gıymatlı hemşeriler, cenaballah neler yaratmıştır, neler. Destannarını ağızdan ağza dinnediğiniz, namını şöhretini duyduğunuz menşur Şahmaran ‘ı şimdi sizlere göstereceğiz. Birzat gözleriniznen görüp ve sesini gulahlarınıznan duyacaksınız. Verdiğiniz paraları kat be kat helal edeceksiniz. Türklüğünüzle kat be kat övüneceksiniz. Zira ki, bu menşur Şahmaran ‘ı yakalattıran birzat bizim Türk alimleri olmuştur. Kıymatlı vatandaşlar… Bu şahmaran, hepimiz biliriz ki; ilanların şahıdır. ‘İlan’ da demek doğru değildir.Zira ki ilan adını ağzına alannarın ilan kadar zehirli düşmanları çok olur. Onun için ‘İlan’ demeyip ‘Yerde Gezen’ demek şarttır. Kıymetli müşterilerimiz, bu yerde gezen Şahmaran, Afrika ‘nın balta girmemiş ormanlarında dört kişiyi yedikten sonra, on zenci tarafından zorluknan yakalanmıştır, zincirlere vurulmuştur. Cenaballah ‘ın mucizelerinden biri de Şahmaran ‘dır. Neden? Çünkü; Şahmaran ‘ın başı insan, vücudu ise yerde gezendir. Yaniya; başı, ayni bir teviri bizim başlarımız gibidir. İnsan yemeye alışık olduğundan kolay kolay doymamaktadır. Bu sebepten ve hergün birzat 72 toyuk, 29 davuşan yemekte ve 14 varil süt içmektedir. Başı insan, vücudu yerde gezen olduğundan ayni metoloji raporu gibi adamın falını ayniyne ve ayniynen bilmektedir. Ve de bildiği falların hiçbir teki bugüna kadar yanış ve ergi çıkmamıştır. Şimdi sizlere Şahmaran ‘ı gözlerinizle göstereceğiz.

Çadırda çıt yoktu. Herkesin gözleri kapalı duran perdeye dikilmiş, soluklar kesilmiş, kıpırdanmalar durmuştu.

İpin ötesindeki başı sorguçlu adam, sol elindeki çıngırağı şiddetle sallamaya başladı. Çıngırak sesleri çadırın içinde yankılanırken, adam gözlerini yukarı kaldırdı. Anlaşılmaz sözlerle, kendinden başkasının göremediği birilerine seslenmeye koyuldu:

- Hamar… Mesnud… Vantar… Bismillahi birsin ve billahi nursun, yetmişbin ayetelkürsü etrafımızda dönsün dursun…. Mucizelerine ve insan başlı mahlukatına inanmayan kafirdir, ye Resulallah.

Adam çıngırağı yeniden salladı. Sonra çubuğu tutan obir eliyle perdeyi bir çekişte sonuna kadar sıyırdı.

Küçük bir çocuk öızıldadı, annesinin eteğine sarıldı. Kadınlar erkeklerine sokuldular. Hiç kimse tek kelime konuşmadı. Arkadakiler başlarını öne doğru uzatmışlardı. En önde, karınlarını ipe yaslamış duranlar bir-iki karış gerilediler.

Delikanlı kalabalığın gene en arkasındaydı. Açılan sahnedeki Şahmaran ‘a baktı. Sonra yere eğildi. Yere atılmış bir Bafra sigarasının dış gömleğini alıp doğruldu. Kağıtla oyalanmaya başladı. Elleriyle gözleri ayrılmışlardı. Bakışları Şahmaran ‘da dolaşırken, parmakları kağıdı bir kenarından kıvırıyor, sigara sarar gibi dürüyordu.

Şahmaran bir masa üzerine uzatılmıştı. Henüz uyuyordu. Başı aynen bir insan başıydı. Etiyle, kemiğiyle, kanıyla, rengiyşe, bir-iki günlük uzamış sert sakalıyla, kavisli burnuyla, dudaklarının kenarlarını izleyerek çeneye inen gür, siyah bıyıklarıyla, memeleri kılanmış kulaklarıyla, alnına aşağı dökülen, limonla taranmış, kirli, yağlı, düz siyah saçlarıyla, altında kıpırtılar olan gözkapaklarıyla gerçek bir insan başıydı. Gövdesi soba borusu kalınlıkta ve beş-altı metre kadardı. Gövde bu dar yere sığdırılamadığından kavis kavis büktürülmüş ve kıvırılmıştı. Çevresinde kalın, yeşil ipekten çok büyük bir örtü seriliydi. Bu örtü Şahmaran ‘ı her yandan kuşatıyor fakat vücudunun ve başının hiçbir yanını gizlemiyordu.

İpin ötesindeki adam:

- Kıymatlı vatandaşlar, canaballah ‘ını seven lütven ‘Maşallah’ desin.

Diye uyardı. Çadırı dolduran kalabalık ş ‘leri ikileyip üçleterek koro halinde:

- Maşşşallah… Maşşşallah…

Dedi. Sarığı sorguçlu adam, sol elindeki çıngırağı birkaç kere kuvvetle çalkaladı. Şahmaran ‘da herhangi bir depreniş görülmedi.

Delikanlı Şahmaran ‘ın yüzüne dalmıştı:

‘Kulakları da var ama Şahmaran çıngırağı iplemedi. Uykunun en derin yerinde. Gözbebekleri gözkapaklarının altında sağa-sola gidip geliyor. Pis iş. Çok pis iş. Kumpanya üç kişi: Biri sarıklı, biri hoparlörlü, biri Şahmaran. Zayıf kumpanya. Kazancı kolay kolay üçe bölemezler işin berbadı. Düz hesap gelmez. Zira; elli kuruşu üçe tam bölmek olanaksız. Pis iş. Şahmaran cahil, ilkel. Kulakları kıllı. Kafatası kaba, büyük. Sığırınkine yakın beyni var. Nöronlarının çoğu kapalı. Kavranış hızı otuz saniyeden az değil. Yolda klakson çalsalar, en az otuz saniye bakar ve sonra kavrar çekilmesi gerektiğini. Pis iş. Çok pis iş. Bilinçsizlik bilinci aldatamaz. Bilinçsizlik belki merakı aldatabilir. Bu doğru. Bilinçsizlik bilinçaltını aldatır. Bu da doğru.’

Siyah ipek pelerinli adam çıngırağı bıraktı. Sağ elindeki uzun çubukla yılanın yattığı masaya birkaç kere kuvvetle vurdu:

- Şahmaran… Ya Şahmaran… Uyan ya mübarek…

Yılan gözkapaklarını araladı. Başı sorguçlu adam çubukla masaya yeniden vurdu:

- Uyan ya mübarek…

Yılan gözlerini tüm açtı. Akları yer yer kanlı, bebekleri iri gözleri vardı.Üzerindeki uyku mahmurluğunu hala atamamıştı. Pelerininin astarı kırmızı ipekli adam, yeniden masaya vurunca Şahmaran ağzını açtı, geniş geniş esnedi. Dili gerçek insan diline benziyordu. Dişleri yer yer paslıydı. Mevcud olmayan köpek dişlerinden birinin yerinde kara bir boşluk görünüyordu.

- Beni uykudan niye uyandırdın, ey insanoğlu? ..

Sesi aynen insan sesiydi.

Başı sorguçlu adam sağ elini önce kalbine, sonra dudaklarına ve daha sonra başına doğru götürdü:

- Selamünaleyküm, ya Şahmaran. Selam Cenaballah ‘ın adıdır.

- Kötü yerde belim kırdın, ey insanoğul. Cenaballah ‘a canım kurban. Kötü yerde belimi kırdın. Ve aleykümüsselam. Dile benden. Ne dilersin? 

Delikanlının yüzünde biryerler seğiriyor, yanaklarının kulaklarına yakın biryerlerinde kaslar sürekli hareket eiyordu. Başı sorguçlu adamın yanındaki perdesi açık sahnede Taksim Anıtı durmaktaydı. Tarlabaşı ‘ndan çıkan bir taksi, anıtı bütük bir hızla geçerek sağa viraj alıp İstiklal Caddesi ‘ne sapmaktaydı. Anıttaki taştan heykeller kara kara bakıyorlardı. Anıtın dibindeki çimenler içinde, yeşil, yemyeşil, enyeşil çimenler içinde bir yılan çöreklenmiş, o gün yediği 72 tavuğu, 29 tavşanı, o gün içtiği 14 varil sütü sindirmeye çalışıyordu. Başı gerçek insanlara benzeyen, kapalı gözkapaklarının altında gözbebekleri sağa sola seğiren bir yılan. Bir ejderha. Gerçek insanlarınkine benzeyen diliyle, paslı, küflü dişleriyle, geniş geniş esnemesiyle, bozuk kötü Türkçe ‘siyle bir ejderha. Bir Şahmaran.

Delikanlının alnında boncuk boncuk ter damlaları vardı. Parmakları kasılıyor, bu kasıntı, giderek yumruğuna, bileğine, pazusuna çıkıyor, kuvvetlendikçe; aşağılara, karnının kaslarına iniyor ve orada öylece kalakalıyordu.

Başı sorguçlu adam sordu:

- Seni buraya nereden getirdiler, ya Şahmaran? 

- Afrika ‘nın balta girmemiş ormanlarından.

- Ya Şahmaran, ne yersin, ne içersin? 

- Et yerim, süt içerim.

Delikanlı, parmakları arasında sarıp yuvarlayarak ince bir çubuk haline getirdiği kağıt parçasını ikiye katladı.

‘Gövdesini bezden yapmış, boyamışlar. Çok belli. Masanın ortası delik. Şahmaran masanın altında. Oturmuş, başını delikten çıkarmış. Baş, yılan gövdesinin tam önünde duruyor. Şahmaran ‘ın başı. Kafatası çok büyük ve ilkel. Beyni büyük ve tembel. Kavrama hızı otuz saniye. Bilinçsizlik bilinci aldatamaz. Bu doğru.’

Delikanlı sol elini ceketinin mendil cebine sokup oradaki ince çorap lastiğini çıkardı. Sapanı parmaklarına geçirdi. Sağ elindeki, deminden beri hazırladığı kağıttan oku lastiğe taktı. Kalabalığın en arkasında ellerini yukarıya kaldırdı. Şahmaran ‘ın yüzüne nişan aldı. İnce lastik yayını var kuvvetiyle gerdirdi. Hareketsiz duran kalabalık arasından havaya kalkan ellerin bu hareketi Şahmaran ‘ın ilgisini o yana çekmişti. Bunun ne olduğunu anlayamadan bir süre baktı.

‘Kavrama hızı otuz saniye.’

Şahmaran bir şeyler anlamıştı, çok şey anlamıştı, her şeyi anlamıştı. Şahmaran bir şey bilmiyordu, çok şey bilmiyordu, hiçbir şey bilmiyordu. Neye karar vereceğini bilemiyordu. İçgüdüleri bunun iyi olmayacağını, hiç iyi olmayacağını haber veriyordu. Bir yer geldi ki, Şahmaran ‘ı çadırın gerçeğine bağlamaya sarığı sorguçlu adamın soruları, çubuk darbeleri ve çıngırağının sesleri yetmemeye başladı. Sorulan sorulara karşılık vermiyor, kalın gövdesini dürten çubuğa tepki göstermiyordu. Tüm varlığı bakışlarında toplanmış ve kalabalığın en arkasında kağıttan ok atmak için lastikten bir yay geren parmaklara bağlanmıştı. Lastik henüz kıvamını almamış gibi, parmaklarda gevşeyip gerildikçe, yeniden yeniden gevşeyip daha daha çok gerildikçe, Şahmaran ‘ın yüzünün biryerlerinde bir şeyler kasılıyor, korunmak istercesine gözleri dar çizgiler halinde kısılıyor, göz kuyruklarında merkezden çembere sağlı sollu kırışıklıklar, büzülmeler beliriyor, bunlar derinleştikçe, yanaklarının burna yakın bölümleri irileşip tümseklenerek gözlerine kavuşuyor, bürün yüze çok korkulu, çok acıklı bir ifade geliyordu.

‘’Eli yok, kolu yok. Şahmaranlar… Elsiz, kolsuz Şahmaranlar… Ejderhalar… Günde 72 tavuk, 29 tavşan yiyen, 14 varil süt içen, kuyruğu başından habersiz ejderhalar… Şahmaranlar… Şahmaranlar… Şahmaranlar…’

Delikanlı kağıttan okunu olanca gücüyle fırlattı. Ok havada şiddetle uçup Şahmaran ‘ın sol gözünün üstüne vurdu. Kulakları sağır etmeye yetecek güçte bir nağra koptu. Yılanın çevresini saran kalın, yeşil ipek örtü hortuma kapılmış gibi savruldu. Örtünün altından, başı ortadaki deliğe geçik bir adam masayla birlikte fırladı. Yana çekili duran perde, masanın bacağına takılıp yırtıldı. Perdeyi tutan korniş, çadırı ortadan bölen gergin ipe düşüp kopardı. Kavuğunu yerden almaya eğilen başı sorguçsuz adam, niçin olduğunu bilemeden, elindeki tahta saplı metal çanı var gücüyle sallıyordu. Çıngırağın metal çanı bir kadının başına çarpıp sarı ipek eşarbını kana boyadı. Kadının yanından bir erkek fırlayıp çanı kopardı, aldı ve başı sorguçsuz adamın yüzüne-gözüne çalmaya başladı. Çelik bilyeden yapılı tokmağın çana her vuruşunda çıkan düzensiz çınlamalar, çadırdan kaçmaya çalışan, birbirlerini ezen kalabalığın korkulu, şaşkın, öfkeli seslerine karışıyordu.

Dışarılarda biryerlerde birileri soruyordu:

- Burada ne olmuş? Çadır neden yıkılıyor? 

- Bir ejderha kaçmış, bir Şahmaran. Nah içte o çadırdan.

- Öldürebilmişler mi? 

- Besbelli hayır.

- Halkın, toplumun arasına bir karışırsa fena.

(Devam edecek…)', '‘İçeriye girince hangi seslerin hangi pavyonlara ait olduğu daha iyi anlaşılıyor.’ Du. Tele-Gide pavyonunda, ondört yaşlarında, spor gömlekl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/sahmaranlar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın', 'yangin-soner-polat-39423', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'göğsümde alevler

göğsümde yangın

güçsüz nehir

bulutlar yağmur

ellerim kül

gözlerim kül', 'göğsümde alevler göğsümde yangın güçsüz nehir bulutlar yağmur ellerim kül gözlerim kül...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yangin-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pisiklet', 'pisiklet-soner-polat-k28sx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gökten bi pisiklet düşse

binsem üzerine

gitsem bilmediğim şehirlere

aşık olsam

delirsem

divane olsam

sarhoş olsam

durulsam

özgür olsam

dönsem kendi şehrime', 'gökten bi pisiklet düşse binsem üzerine gitsem bilmediğim şehirlere aşık olsam delirsem divane olsam sarhoş olsam durulsam özgür olsam dönse...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/pisiklet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '‘’* Bîsmîllahî Rahman ve Rahîm', 'b-sm-llah-rahman-ve-rah-m-ali-riza-unal-03i71', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Igraa bîsmî Rabbikêllezi khalag Rabbuke.

Ey insan oğlu,Rabbının adıyla oku! .

O kerem sahibini, okumaktan mana.

Sanmaki,sureyi ayet ezberi,alfabe talimi.

Senki,Rahmana halifesin, sırrını oku! .

Hak hirada,habibi Ahmede ne,için ne dedi.

Namaz kıl oruç tut,kâbeyi tavafmı eyle dedi.

Hayır! bu gafillerin zannından başka bir deyil.

Önce hakkani amel tahkiki iman için oku.

Haaa! Sakın namazı orucu inkâr eyleme.

Nefsi cehline zebun olup, küfrü îkrâr eyleme.

O şah-ı Resul okudumu tecvit ile alfabeyi bakın.

O arza inen, nice nice,açık seçik ayetlere bakın.

O alak-ın halık,o cemâli nigâr hudâya, ol yakın.

Bir damla kan pıhtısından yaratan, Rabbının adı ile oku.

Oku aklı selim, ehli basir ol, oku ki aslına rûcû olasın.

Oku ve çalış,kalemle yazı yazmayı öğretene arif ol.

Oku-ki sende  nurunu,kemâle tamam eylesin.

Oku-ki Kur-anı beyyinatı, sende beyan eylesin.

Oku-ki ölmeden önce öl sırrına mashar eylesin

Oku-ki ef-al öte,sende zati sırrını ayan eylesin.', 'Igraa bîsmî Rabbikêllezi khalag Rabbuke. Ey insan oğlu,Rabbının adıyla oku! . O kerem sahibini, okumaktan mana. Sanmaki,sureyi ayet ezberi,a...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bismillahi-rahman-ve-rahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babaanne', 'babaanne-soner-polat-ky0u7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'serçeler

kirazları sever

yemesin diye

babaanneler

hergün

serçeleri

kışeler', 'serçeler kirazları sever yemesin diye babaanneler hergün serçeleri kışeler...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/babaanne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-i-brahim-yavuz-7k45a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni anlatmaya söz mü yetişir

Ne güzel kışların yazların vardır

Aşkın yüreğimde yanar tutuşur

Tadına doyulmaz hazların vardır

Sayende düzeldi bozuk ayarım 

Bu yüzden kendimi şanslı sayarım

Nedimden Bakiden sesler duyarım

Ruhumu şâdeden sazların vardır

Geçim derdi için geldim buraya

Değer vermez oldum artık paraya

Bir boğaza baktım bir de karaya

Bir yeşil bir mavi gözlerin vardır

Sana kimler verdi bu güzel adı

Sensiz çıkar mı hiç hayatın tadı

Hangi şair sana şiir yazmadı

Kitaplara sığmaz sözlerin vardır

Adalar uzaktan sahile bakar 

Gecene semadan yıldızlar akar

Rengarenk ışıklar geceyi yakar

Daha nice cilve nazların vardır 

Güzeller gül yüzlü vede soyludur

Çoğu gamzelidir uzun boyludur

Benim sevdiceğim Ortaköyludur

Menendi bulunmaz kızların vardır

Üsküdar, Beyoğlu, Bebek, Kumkapı''n

Dillere destandır tarihi yapın

Ebedi Türklüğe yazıldı tapun

Meşhur tepelerin düzlerin vardır

Fatihi kendine yar diye seçtin

Şanlı bir tarihi süreçten geçtin

Bir çağı kapatıp bir çağı açtın

Tarihte silinmez izlerin vardır', 'Seni anlatmaya söz mü yetişir Ne güzel kışların yazların vardır Aşkın yüreğimde yanar tutuşur Tadına doyulmaz hazların vardır Sayende düzeld...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/istanbul-316-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babacığım...', 'babacigim-muammer-baydere-piw36', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanların kaderi bu ebedi ayrılık 

Bak sonunda bizi de buldu be babacığım 

Senden ayrı kalalı bütün dünyam karanlık 

İşte yine gözlerim doldu be babacığım 

Yokluğunun acısı yüreğimi kararttı 

Günden güne özlemin saçlarımı ağarttı 

Kederlerim büyüdü gül benzimi sararttı 

Kuru yaprak misali soldu be babacığım 

Hep mutluluk bulurdum senin tatlı sözünde 

Sanki nurlar parlardı melek gibi yüzünde 

Koca adamdım ama hep çocuktum gözünde 

Şimdi oğlun bir yetim kaldı be babacığım 

Allah ödül vermiştir her kulun zahmetine 

Fakat erken kavuştun Ya Hakk''ın rahmetine 

O tertemiz ruhunu yaratan ahretine 

Belki aziz diyerek aldı be babacığım. 

* * * * * 

''Sen öldün öleli her şey zahmetli 

İnan ki yaşamak zul oldu baba 

Ben bir garip yetim sense rahmetli 

Anamsa haliyle dul oldu baba 

Çoğaldı ''keşke''miz ''eğer''lerimiz 

Koz versek satılır ciğerlerimiz 

Yerle bir edildi değerlerimiz 

Korkarım harcandı pul oldu baba...'' 

MB 

Tüm babaların babalar gününü kutluyor,rahmetli olanları dualarla anıyorum,nur içinde yatsınlar...', 'İnsanların kaderi bu ebedi ayrılık  Bak sonunda bizi de buldu be babacığım  Senden ayrı kalalı bütün dünyam karanlık  İşte yine gözlerim dol...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/babacigim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetimin Babalar Günü', 'yetimin-babalar-gunu-ozan-ozel-p5767', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tarıyor ellerim mezar taşını

tel tel ağarmış ak saçlarını

öpüyor gözyaşlarım

dudaklarım ağlıyor

dökülüyor damla damla

ağıtlarım...

her yetim gibi

ben de

babalar gününü

mezarlıkta kutlarım', 'tarıyor ellerim mezar taşını tel tel ağarmış ak saçlarını öpüyor gözyaşlarım dudaklarım ağlıyor dökülüyor damla damla ağıtlarım... her yetim...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yetimin-babalar-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misafir Bekliydruz', 'misafir-bekliydruz-mehmet-sait-akkus-848lt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Misafir Bekliyoruz

Ha variz ha yokuz

Simdi saat tam dokuz

Yas yetmis dokuz

Misafir gelecek bekliyoruz

Kimimiz aký illi kimimiz deli

Saat tam yedi elli

Gidecegimiz zaten belli

Misafir gelecek bekliyoruz

Su fani dünyada

Saat tam yede altida

Ecel yani basimizda

Alacak cani bekliyoruz

ALLAH akil fikir vere

Simdi gidecegimiz yere

Yalvarirsak yüzbin kere

Gidecegiz ne bekliyoruz', 'Misafir Bekliyoruz Ha variz ha yokuz Simdi saat tam dokuz Yas yetmis dokuz Misafir gelecek bekliyoruz Kimimiz aký illi kimimiz deli Saat tam...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkus']::text[], 8.5, '{"poet":"Mehmet Sait Akkus","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/misafir-bekliydruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rübailer-4', 'rubailer-4-nihat-malkoc-256oi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ŞÜKÜR

Ecel arabasını ufkun ötesine sür

Yaşıyoruz cihanda alabildiğine hür(!)

Gidenlerin ardından kapanırım secdeye

Kalbim atıyor hâlâ,ölmediğime şükür.', 'ŞÜKÜR Ecel arabasını ufkun ötesine sür Yaşıyoruz cihanda alabildiğine hür(!) Gidenlerin ardından kapanırım secdeye Kalbim atıyor hâlâ,ölmedi...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubailer-4-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılganlık', 'kirilganlik-mustafa-sureyya-sezgin-sop04', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırılgan bir dönemdeyim.

Ruhumun eski diklenişleri yok artık.

Zaten zaman da yok direnmeye.

Yitip giden gençliğim gibi,

Tüm kalelerim düşüyor tek tek.

Ve sen beni hala anlamadın

Anlayamadın  yirmi beş yıl boyunca

Zaten ne zaman anladın ki

Şimdi anlamanı bekleyeyim? 

Kucağındaki renkli boncuklar gibi

Yarattığın eften püften nedenlerle

Gölgeliyorsun 

Öz veriyle  yarattığımız bu evreni.

Kırıyor ve kırılıyorsun

Anlamıyorum bir türlü

Bütün bunlardan 

Ne kazanıyorsun? 

İstanbul, 14.06.2005', 'Kırılgan bir dönemdeyim. Ruhumun eski diklenişleri yok artık. Zaten zaman da yok direnmeye. Yitip giden gençliğim gibi, Tüm kalelerim düşüyo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kirilganlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berceste Mısralar-4', 'berceste-misralar-4-nihat-malkoc-1a5d7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'PERDE

Son nefes tükenince kapanıverir perde 

Dualar sağnak sağnak kabre iner seherde…

DAVET

Maveradan duyulur sılaya davet sesi

Söndürür ateşimi servilerin gölgesi

RUHUN MATEMİ

İçime akıtırım gözlerimin nemini

Sonsuzluğa bıraktım ruhumun matemini

SERMAYE

Asıl sermaye sevgi, sözleri banın aşka

Ömrü nurla yoğurun, hayat olsun bambaşka

VAHA               

 Dünya mümine çöldür, ahiret kutlu vaha

 Bayram eder ruhumuz  kavuşunca  Allah’a!...

DİN

Din, fuhşiyattan kaçıp hakikati bulmaktır

Kalb-i selim sahibi, din samimi olmaktır

TEFERRUAT

Memlekettir aslolan, can dediğin füruat

Söz konusu vatansa gerisi teferruat

TAKLACININ MEZARI

Cumartesinden görür menfaatçi pazarı

Genişçe kazılmalı taklacının mezarı', 'PERDE Son nefes tükenince kapanıverir perde  Dualar sağnak sağnak kabre iner seherde… DAVET Maveradan duyulur sılaya davet sesi Söndürür ate...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/berceste-misralar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berceste Mısralar-20', 'berceste-misralar-20-nihat-malkoc-rul44', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'RAHMET

Rahmandır yüce Allah, gece gün rahmet saçar

Bir kapıyı kapatır, öbür kapıyı açar

SÖZ HANÇERİ

Her bahtı karalının gözyaşını silerim

Söz denilen hançeri hoşgörüyle bilerim

KIYAS

Elin Avrupa’sında yükselir kâşâneler

Ülkemde gözlerimi yaşartır virâneler

KİR

Suyu bulandırdılar, oluklardan akar kir

Âlemin özü insan, nasıl görürsün hâkir?

KEFEN BİÇENLER

Baş tacı ediliyor, Türk’e kefen biçenler

Dünyayı yönetiyor iştahla kan içenler

VEFA VE DEVA

Kalmadı ne yazık ki kulun ahde vefası

Deva beklediğinin yok derdine devası

ZAMANSIZ AYRILIKLAR

Ömrümün arklarından seneler akıp gitti 

(Z)amansız ayrılıklar gönlümü yakıp gitti

ALLAH''A DAYANDIM BEN

Karanlık gecelerden umuda uyandım ben

Hayatın çıkmazında Allah''a dayandım ben', 'RAHMET Rahmandır yüce Allah, gece gün rahmet saçar Bir kapıyı kapatır, öbür kapıyı açar SÖZ HANÇERİ Her bahtı karalının gözyaşını silerim Sö...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/berceste-misralar-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SESSiZLiĞi DiNLE', 'sessizligi-dinle-mehmet-emin-yesilmen-vncs9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessizliği dinle! 

Suskunluğumu duyacaksın,

Herşeyin anlamını içinde saklayan

İnatçı ruhlu suskunluğum.

Sessizliği dinle! 

Ki anlayasın suskunluğumun söylediklerini.

Karanlık geceler bile sabrediyorsa meşaleleri yakmam için...

An gelir,

Anlayacaksın suskunluğumun anlamını...

Fedakarlığı ben bilirim en çok sana.

Anlamanı isterdim kelimelerle konuşmadan.

Ve ilgiyi

Ve sevgiyi

Gerekli anlarda susarak sunduğum

Hep severek sunduğum...

Sessizliği dinle! 

Dinle ki suskunluğumun içini duyasın.

Duyarsan şayet telepati uygula

Cevabı kalbine yollarım, salisede.

Kalbimden düşünceye....', 'Sessizliği dinle!  Suskunluğumu duyacaksın, Herşeyin anlamını içinde saklayan İnatçı ruhlu suskunluğum. Sessizliği dinle!  Ki anlayasın susk...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sessizligi-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-mustafa-sureyya-sezgin-ba52y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anam; “Ağlarsa analar ağlar”

Diyordu,

Babam bakıp susuyordu.

“Yarına çıkmam ölürüm”

Diyordu anam.

Babam dayanıklı, sağlam 

Yarınki ekmeği düşünüyordu.

Sonra aniden

Onurlu ve sessizce

Ve hiç şikayet etmeden

Sonsuzluğa göçtü babam

Şaşırmış ve yorulmuş

Ardından baka kaldı anam.

İstanbul, 19.06.2005', 'Anam; “Ağlarsa analar ağlar” Diyordu, Babam bakıp susuyordu. “Yarına çıkmam ölürüm” Diyordu anam. Babam dayanıklı, sağlam  Yarınki ekmeği dü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/babam-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEŞKE, AŞK HERKES iÇiN KOLAY GELSE', 'keske-ask-herkes-icin-kolay-gelse-mehmet-emin-yesilmen-vnvkn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Parlak bir orman,

Kıvrımlı ağaçlar ve süslenmiş dallar yeşille.

Gündüzün ortasında kalp görüntüsünde yıldızlar,

Üstelik alçak mesafede...

İki kişilik hikaye başlıyor.

Erkek önce dişinin kızıl saçlarına dalıyor,

Yavaştan kahverengi gözlerine kayıp,

Bakışların yürüyüşünü durduruyor.

Gözlere takılıyor heyecanla.

Ne bir hareket nede ses

Sadece kahverengi gözleri düşünüyor seyredip.

Kızıl saçlı dişi, çok yavaş hareketlerle erkeğe yaklaşıyor.

Dişi, erkeğin pembeleşen yanağına bir öpüzcük konduruyor.

Zamanda sessizlik devam ediyor,

Erkekte hareketler kesilmiş, dona kalmış.

Sanki, o öpme anı seneler sürmüş.

Masum bir öpücük,

Asırlık bir aşk doğurmuş erkekte.

Ve erkek dua etmiş.

''Keşke, aşk herkes için kolay gelse''', 'Parlak bir orman, Kıvrımlı ağaçlar ve süslenmiş dallar yeşille. Gündüzün ortasında kalp görüntüsünde yıldızlar, Üstelik alçak mesafede... İk...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/keske-ask-herkes-icin-kolay-gelse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Kankırmızı', 'kankirmizi-nurten-altinok-rw3h0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül, rengini taşısa da ellerinde 

Kırmızı damlar battığı her yerde 

Seviyorsan bir çiçeği dikeniyle 

Elbette bulaşacaktır kan şiire 

Dikensiz bir gül müdür aradığın 

Hani nerde 

Engelsiz bir yarın mı? 

Buldunsa söyle 

Obamızı oraya kuralım... 

Hangi bahçıvanın elleri kanamaz 

Yarıyorken toprağı umut diye ikiye... 

.', 'Gül, rengini taşısa da ellerinde  Kırmızı damlar battığı her yerde  Seviyorsan bir çiçeği dikeniyle  Elbette bulaşacaktır kan şiire  Dikensi...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kankirmizi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim (aruz)', 'sevdigim-aruz-i-brahim-yavuz-aap05', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bahçe üzgün gonca mahkum solmaya 

Koy da güller sende gülsün sevdiğim

Sevgi bekler boş gönüller dolmaya

Suçlu kimdir kim ne bilsin sevdiğim 

Zühre gözlüm sabrı sensin zorlayan

Mutlu olmaz bence insan horlayan

Sorma kimdir böyle yetkin parlayan

Gökte mehtap yer de sensin sevdiğim

Can verirdim gelse bir gün kabrime

Asla sığmaz karşı gelmek haddime

Diz çökerdim yalvarırdım rabbime

Her ne derdin varsa silsin sevdiğim 

Fâilâtün  /  Fâilâtün  / Fâilün', 'Bahçe üzgün gonca mahkum solmaya  Koy da güller sende gülsün sevdiğim Sevgi bekler boş gönüller dolmaya Suçlu kimdir kim ne bilsin sevdiğim ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdigim-aruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Senin Soluşu', 'bu-senin-solusu-ahmet-atmaca-r80h6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elbet dönecek bu devran

Geçer bu çölden de kervan

Kalırsın  bir gün yayan

Düşmez, kalkmaz bir Allah var

Ne idim ne oldum dersin

Yaşanmışı boş geçersin

Rüzgar iken yel esersin

Düşmez kalkmaz bir Allah var', 'Elbet dönecek bu devran Geçer bu çölden de kervan Kalırsın  bir gün yayan Düşmez, kalkmaz bir Allah var Ne idim ne oldum dersin Yaşanmışı bo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-senin-solusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhun Matemi', 'ruhun-matemi-nihat-malkoc-4apso', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçime akıtırım gözlerimin nemini

Sonsuzluğa bıraktım ruhumun matemini', 'İçime akıtırım gözlerimin nemini Sonsuzluğa bıraktım ruhumun matemini...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ruhun-matemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Ey gencim', 'a-ey-gencim-mikdat-bal-qh36m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey gencim dinlersen, bir kaç sözüm var 

Dünya kalleş olsa, sen namert olma! 

Yapıcı ol, buna çok ta lüzum var! 

Dertlerimiz çoktur, sen de dert olma! 

Bazı genç var merttir, çoktur saygısı 

Bazı genç var serttir, yoktur kaygısı 

Bazı genç var derttir, ölmüş duygusu 

Yumuşak ol, sakın ola sert olma! 

Tarihini, geçmişini dünü bil 

Etrafa bak, çevreye bak, günü bil 

Sen davanı anlatırken şunu bil 

Adamlıktan ödün verip tart olma1

Biliyoruz canınızı sıkan var 

Her manevi şeye karşı çıkan var 

Ahlakını, kültürünü yıkan var 

Sen onlara yardım eden fert olma! 

Ah bir bilsen neler, neler oluyor 

Göz dikenler, gözcüsünü yolluyor 

Dikkatli ol düşman fırsat kolluyor 

Gafletinden yere değen sırt olma! 

Mikdadî der, akıllı ol saldırma 

Sana gelmek isteyeni yıldırma 

Sen olduğun gibi görün aldırma 

Tavrın açık, seçik olsun art olma! 

Ozan Mikdadî', 'Ey gencim dinlersen, bir kaç sözüm var  Dünya kalleş olsa, sen namert olma!  Yapıcı ol, buna çok ta lüzum var!  Dertlerimiz çoktur, sen de d...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/a-ey-gencim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen istedin...', 'sen-istedin-sibel-uygun-lz8v1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir tuvaldin sen gönlümde

Bir tarafı gündüz, diğeri gece...

Seninleyim her nefesimde...

Uzaklarda olsan da yanımdasın işte...

Ben seni böyle severken ıraklıklar vız gelir diyorum...

Sonra, senin yolladığın yağmurlar yağıyor gizliden,

Damlalar çoğaldıkça, 

Renkler karışıyor birbirine...

Gündüz, geceye, 

Ay,  güneşe...

Yıldızlar yavaş yavaş sönüyor.

Gökkuşağımın renkleri, al alaca olmuş akıyor.

Tutamıyorum gidenleri.

Ben istemesem de, süzülüyor gündüz ve gece.

Sıcacık sevgim bir anda ortada kalıyor.

Sonra üzerine güneşler doğuyor.

Tuvalin ıslaklığıyla, sevgim de, 

Güneş eşliğinde buhar olup uçuyor, göklerin derinliklerine...

Sevdam mavi, gökyüzü mavi, 

Karışıyor birbirine.

Ne gündüz, ne de gece...

Sen istedin diye...

Şimdi, beyaz bir tuval var elimde.

Yeni bir resmin çizilmesini beklercesine...

Beyaz,

Bembeyaz...', 'Bir tuvaldin sen gönlümde Bir tarafı gündüz, diğeri gece... Seninleyim her nefesimde... Uzaklarda olsan da yanımdasın işte... Ben seni böyle...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-istedin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sermaye', 'sermaye-nihat-malkoc-xjxru', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Asıl sermaye sevgi,sözleri banın aşka

Ömrü nurla yoğurun,hayat olsun bambaşka', 'Asıl sermaye sevgi,sözleri banın aşka Ömrü nurla yoğurun,hayat olsun bambaşka...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sermaye-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuldum Aşkına', 'tutuldum-askina-i-brahim-yavuz-z54qz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutuldum aşkına döndüm deliye 

Felek önden vurdu gittim geriye 

Şimdi benziyorum bir serseriye 

Ne huzurum kaldı ne mutluluğum 

Sayende sararmış solmuş gibiyim 

Saçımı başımı yolmuş gibiyim 

Seninle belamı bulmuş gibiyim 

Ne huzurum kaldı ne mutluluğum 

Sensin bütün derdim bütün kederim

Başımım alıp ta nere giderim 

Seninle başladı kara günlerim 

Ne huzurum kaldı ne mutluluğum 

Bana saygın da yok sevginde bitti 

Çektiğim çileler canıma yetti

Gecem gündüzüme karıştı gitti 

Ne huzurum kaldı ne mutluluğum', 'Tutuldum aşkına döndüm deliye  Felek önden vurdu gittim geriye  Şimdi benziyorum bir serseriye  Ne huzurum kaldı ne mutluluğum  Sayende sara...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tutuldum-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-i-brahim-yavuz-nz35q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine kırdın beni durup dururken

Sen bana nazınla çok ettin sevdam

Her gece rüyamda seni görürken

Şimdi düşlerimi yok ettin sevdam

Mehtaptan mı aldın o nurlu yüzü

Aşkının kalbimde derindir izi

Seni insafsızın zalimin kızı

Sen bu sitemleri hak ettin sevdam

Aşığım başımdan duman tütüyor

Sabrım sona geldi bitti bitiyor

Şeytan tut kolundan al götür diyor

Vallahi canıma tak ettin sevdam

Ne su istiyorum ne aş ne ekmek

Nede ardın sıra gözyaşı dökmek

Kolay değil senin derdini çekmek

Bütün saçlarımı ak ettin sevdam

Gözümün farkı, yok akan ırmaktan

Bıkmadın mı beni her gün kırmaktan

Yoruldum ardından koşup durmaktan

Sen bana hayatı yük ettin sevdam', 'Yine kırdın beni durup dururken Sen bana nazınla çok ettin sevdam Her gece rüyamda seni görürken Şimdi düşlerimi yok ettin sevdam Mehtaptan ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdam-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanı canân', 'sultani-can-n-ali-riza-unal-k38iy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eşref vakti sordum,hal ile yare.

Ne var ne yok, nerdesin  canân.

Canân,ne gam var keder dedi.

Sende ne var ne yok ya sultan.

Dedim yare bende ne var ne yok.

Dedi her şeyin var,hiçbir şeyin yok.

Şaştım nerden duyulur bu hallerim.

Meğer o canan,bende sultan imiş.

Pinhan halimi, lisan edersin dilde canân.

Ben cehlimden bi haber, cahilim canân.

Meğer o bende,ben onda canân imiş.

Dilde beyân,sırda perdesiz, ayan imiş.

Not: okuyucularımın dikkâtine burada söz konusu,

Sultan ve canân hep (HU) (O)  yani Hz ALLAH:', 'Eşref vakti sordum,hal ile yare. Ne var ne yok, nerdesin  canân. Canân,ne gam var keder dedi. Sende ne var ne yok ya sultan. Dedim yare bend...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sultani-canan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Ötesi', 'daha-otesi-i-brahim-yavuz-4pg4o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sevda ki alev alev yakıyor.

Boynumu vursalar değil bitesi.

Bir ırmak ki gürül gürül akıyor.

Seviyorum var mı daha ötesi.

Tanrım beni sevsin diye yarattı.

Bin bir çeşit duygu ile donattı.

Hamuruma sevgi kattı aşk kattı.

Seviyorum var mı daha ötesi.

Sevmediğin toprak sana yurt değil.

Sevdiğini söylemeyen mert değil.

Dokuz köyden kovsalar da dert değil.

Seviyorum, var mı daha ötesi.

Hem zerreyi hem zerrenin özünü.

Seven insan hiç yutar mı sözünü.

Şu gördüğün karıncanın gözünü.

Seviyorum var mı daha ötesi.

İnsan vazgeçemez aşkı tattıysa.

Kalbini bir başka kalbe kattıysa.

Yaratan evrende ne yarattıysa.

Seviyorum var mı daha ötesi.

İbrahim der kimi sevsem söz gelir.

Yokuş biter ardı sıra düz gelir.

Sevenlere ölüm bile vız gelir.

Seviyorum var mı daha ötesi.', 'Bir sevda ki alev alev yakıyor. Boynumu vursalar değil bitesi. Bir ırmak ki gürül gürül akıyor. Seviyorum var mı daha ötesi. Tanrım beni sev...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/daha-otesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Sevdigim', 'bir-gun-sevdigim-mehmet-sait-akkus-kukyz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir Gün Sevdigim

Ben sana asik

Sen bana asik

Bu askimiz yakisik

Olmus sevdigim

Ben sana deli

Sen bana deli

Bu askimiz ezeli

Olsun sevdigim

Ben sana sevdali

Sen bana sevdali

Ikimizin gönlü yarali

Olmus sevdigim

Ben sana vurgun

Sen bana vurgun

Kavusursak bir gün

Ne yapalim sevdigim', 'Bir Gün Sevdigim Ben sana asik Sen bana asik Bu askimiz yakisik Olmus sevdigim Ben sana deli Sen bana deli Bu askimiz ezeli Olsun sevdigim B...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-gun-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğu Bulurdum', 'mutlulugu-bulurdum-i-brahim-yavuz-7mpo2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir anda kanatlanır mutluluktan uçardım

Bir kez olsun gönlüne girebilseydim eğer

Cennet bahçelerinin kapısını açardım

Gözlerinde kendimi görebilseydim eğer

Dünyanın bir ucuna git deseydin giderdim

Bin yıllık ömrüm olsa sana feda ederdim

Aşkı yarattı diye Tanrıya şükrederdim

Sonsuz aşkın sırrına erebilseydim eğer

Sensiz uyku uyumaz sensin yemek yemezdim

Senden başka birine asla aşkım demezdim

Sevgiden başka hiç bir karşılık beklemezdim

Her şeyimi yoluna serebilseydim eğer

Yıllara boş verirdim mevsimleri saymazdım

Zindanlara atsalar yine senden caymazdım

İnan bir ömür boyu koklamaya doymazdım

İncitmeden gülünü derebilseydim eğer

Sanma ki pes ederdim sanma ki yorulurdum

Uzaklarda olsan da arar seni bulurdum 

Ne kendimi suçlardım ne de pişman olurdum

Sana bütün ömrümü verebilseydim eğer

Ruhumu teslim alsan birkaç manalı sözle

Ah çekmezdim yüreğim yansa aşk denen közle

Bu dünyaya kahredip gitmezdim acık gözle

Bu aşkın sefasını sürebilseydim eğer', 'Bir anda kanatlanır mutluluktan uçardım Bir kez olsun gönlüne girebilseydim eğer Cennet bahçelerinin kapısını açardım Gözlerinde kendimi gör...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mutlulugu-bulurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yıl Başıma Gelenler', 'bu-yil-basima-gelenler-i-brahim-yavuz-hv7ws', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilerim besbeter olsun 

Benim halime gülenler 

şe dosta ibret olsun 

Bu yıl başıma gelenler

Tuttuğum dallar kurudu 

Tarlamda ekin çürüdü 

İtler üstüme yürüdü

Bu yıl başıma gelenler

Bir bir çürüdü dişlerim 

Hep terse gitti işlerim 

Kabusa döndü düşlerim 

Bu yıl başıma gelenler

Kaç çifte yedim atlardan 

Kalkamadım yataklardan 

Çıkamadım bataklardan 

Bu yıl başıma gelenler

İneğim süt vermez oldu

Sağ gözüm hiç görmez oldu 

Artık aklım ermez oldu

Bu yıl başıma gelenler

Evin çatısı tutuştu 

Görenler yardıma koştu 

Kafama kiremit düştü 

Bu yıl başıma gelenler

Bu çevrede zengin bendim 

Kapı kapı borç dilendim 

Süt içerken zehirlendim

Bu yıl başıma gelenler

Horozu vurdum uçurdum 

Karıyı evden kaçırdım 

Çok kötü günler geçirdim 

Bu yıl başıma gelenler

Allah’ım bu nasıl iştir 

Benim yazımı değiştir 

Kimin başına gelmiştir 

Bu yıl başıma gelenler', 'Dilerim besbeter olsun  Benim halime gülenler  şe dosta ibret olsun  Bu yıl başıma gelenler Tuttuğum dallar kurudu  Tarlamda ekin çürüdü  İt...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bu-yil-basima-gelenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım..', 'canim-nilgun-akcay-o24jf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oğlum…

Canım..

İlkbaharımın ilk ışığı

Yüreğimin kalkanı

Muradım Canım..

Seninle gençliğimi

Uğurladım acı ve gözyaşıyla..

Kâh güldük kâh ağladık..

Beraber gözyaşımızı katık yaptık

Birlikte büyüdük oğlum seninle..

Gözyaşı dolu gecelerimin sevinci

Karanlık gündüzümüzün de feneri.

Oldun Oğlum..

Çok üzdün çok da üzüldün belki..

Ama bir gün haykırmadın

“ Geleceğim  ne olacak” diye

Kendi çabalarının içinde

Hep sustun…sadece..

İsyandaydın sen de

Belli etmesen de 

Kırgındı ela gözlerin..

Yıllar yılları kovaladı..

Günler günleri..

İki iken üç olduk..

Sen ve  kardeşin.. bir de  ben..

Hayat sofrasını taşıyan 

Üç bacaklı masaydık artık..

Yıkılmamak için savaştık..

Hatırlar mısın Oğulcum..

1999 Ağustosunu..

O kara geceyi..

Deprem oluyor diye 

Haykırarak uyandığımızda

Kardeşinle bana

Kalkan olmuştun kollarınla..

Anlamıştım O an..

Büyümüştü Dünkü küçük Can 

Gurur duymuştum..

Buruk bir gururdu..

Gözümü kapadım açtım

Büyümüştün Oğlum..

Bir daha kapadım açtığım da..

Artık yoktun oğlum..

Uçmuştun yuvadan..

Dön diyemem..

Seni Özlüyorum oğlum..

Sessiz isyanını..

Sevgini göstermesen de..

Sevgini hissetmeyi özlüyorum..

Seni seviyorum Oğlum…

br>', 'Oğlum… Canım.. İlkbaharımın ilk ışığı Yüreğimin kalkanı Muradım Canım.. Seninle gençliğimi Uğurladım acı ve gözyaşıyla.. Kâh güldük kâh ağla...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/canim-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşe', 'ayse-i-brahim-yavuz-5z5e3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömrünün baharında fırtınaya tutuldun

Genç yaşta saçlarına yağan kar mıdır Ayşe? 

Daha yolun başında ne çabuk unutuldun

Bu yükü taşıyacak gücün var mıdır Ayşe? 

Hiç yüreğim yanmazdı biçseydin ektiğini 

Dağlar taşlar çekemez bu senin çektiğini 

Güzelliğin söylüyor gülmen gerektiğini 

Ağlayarak yaşamak söyle kâr mıdır Ayşe? 

Sırtında ağır bir yük altında çöküyorsun 

Suçun neydi ki senin göz yaşı döküyorsun 

Konuşurken ne diye boynunu büküyorsun 

Kadere yenik düşmek sanki ar mıdır Ayşe? 

Şimdi ne fark eder ki olmuş olsan da haklı 

Herkesin bir derdi var ama seninki farklı 

Yüzünde acıların derin izleri saklı

Şu felek dedikleri sana yar mıdır Ayşe? 

Ne hayaller kurmuştun yarım kaldı muradın 

Neden hicran değil de Ayşe verildi adın

Bir zalimin yüzünden zehir oldu hayatın 

Dünya geniş diyorlar sence dar mıdır Ayşe?', 'Ömrünün baharında fırtınaya tutuldun Genç yaşta saçlarına yağan kar mıdır Ayşe?  Daha yolun başında ne çabuk unutuldun Bu yükü taşıyacak güc...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayse-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Olur', 'bayram-olur-i-brahim-yavuz-k8177', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yar sevdası can özüme 

Aksa bana bayram olur 

Yüzünü dönüp yüzüme 

Baksa bana bayram olur

Küstürdüm gonca gülümü 

Gelip de sormaz halimi 

Usulca tutup elimi

Sıksa bana bayram olur

Sürmeler çekmiş gözüne 

Sanki ay doğmuş yüzüne 

Siyah saçların omzuna 

Yıksa bana bayram olur

Servi boylar ince beller 

Görüp kıskanmasın eller 

Saçlarına gonca güller 

Taksa bana bayram olur

Göllerde yüzer sunalar 

Neler doğurmuş analar 

Ak ellere al kınalar 

Yaksa bana bayram olur

İbrahim’im bak halime 

Kuş konmaz oldu dalıma 

Ayda yılda bir yoluma 

Çıksa bana bayram olur', 'Yar sevdası can özüme  Aksa bana bayram olur  Yüzünü dönüp yüzüme  Baksa bana bayram olur Küstürdüm gonca gülümü  Gelip de sormaz halimi  Us...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bayram-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akçay Geceleri', 'akcay-geceleri-murat-nail-guney-379ct', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mevziye yatmış da pusuda bekler,

Felek alnımızdan devirmek ister.

Dostlar kabus etti tüm yaşantımı,

Şimdi küllerimi savurmak ister...

Ne boyun eğerim, ne diz çökerim,

Ne eyvallah eder, ne de bakarım,

Bizi yakanları ben de yakarım,

Gönlüm kaleleri devirmek ister...

Halimi sormazsın yine, haklısın,

Farzet ki sen her insandan farklısın,

Üstelik bir de içimde saklısın,

Beni cehennemde kavurmak ister...

Kışlada hüzünle batıyor güneş,

Sensiz çok üşüyor, kalbime yanaş,

Hasretler bitiyor bak yavaş yavaş,

Dostlarım yolumdan çevirmek ister...

Akçay''da tükettim günü, geceyi,

Kıskanırdım kelebeği, böceği,

Tez zamanda kurtaralım paçayı,

Gönül hasret kaldı, sevilmek ister...

Gülüm sabret, seni çok sevdim inan,

Bir isli çırayım aşkınla yanan,

Sen oldun sevdalım, can içinde can,

Canım sıkı sıkı sarılmak ister...

Murat Nail Güney

14/06/2005   Akçay Kışlası- İskenderun

sevgili eşim, duygu ve sevgi dolu insan Esma''ya...', 'Mevziye yatmış da pusuda bekler, Felek alnımızdan devirmek ister. Dostlar kabus etti tüm yaşantımı, Şimdi küllerimi savurmak ister... Ne boy...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/akcay-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnam Kanadı Kırık', 'turnam-kanadi-kirik-murat-nail-guney-bictf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretlere tutunup geldim bunca yollardan,

Bir tek meyve yemedim, güvendiğim dallardan,

Can deyip, dostum deyip, güvendiğim ellerden,

Şimdi, boynuma yağlı kementler takılıyor...

Gönül sevgide Yunus kadar engin olsa boş,

Dünyanın tüm serveti sana miras kalsa boş,

İnsanlar seni kral kadar güçlü bilse boş,

İnsanlığa rağbet yok, şekile bakılıyor...

Hep ayakta kalırsan, dağ başı yorgan döşek,

Helal, haram bilmezsen, sarmaz belini kuşak,

Dostum, biz olamayız bu yaşantıya uşak,

Kadın, erkek kılıktan kılığa sokuluyor...

Köroğlu, Karacoğlan, pirimiz, üstadımız,

mutluluk verir bize o günleri yadımız,

Osmanlı soyundandır dedemiz, ecdadımız,

Şimdi Millet Batı''lı ve entel takılıyor...

Muradım, bilen mi var; büyük, küçük, bilgili,

Herkes etrafındaysa, servetinle ilgili,

Parfüm icat olalı, koklayan mı var gülü,

Turnam kanadı kırık, uçmadan çakılıyor...

murat nail güney   15/06/2005

Anamur - Mersin', 'Hasretlere tutunup geldim bunca yollardan, Bir tek meyve yemedim, güvendiğim dallardan, Can deyip, dostum deyip, güvendiğim ellerden, Şimdi,...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/turnam-kanadi-kirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın Gizli', 'adin-gizli-murat-nail-guney-k9hiv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Engin ufuklarda solarken güneş,

Sular hüzne çalar, akar sevdiğim.

Mazide kalan o sensiz yıllarım,

Ateşler söndürür, yakar sevdiğim...

Gizlemez ardına, ne sis ne gece,

Üzüntü, kederler biter böylece,

Nasıl sabah olur sensiz bir gece,

Elimden tut, burdan  çıkar sevdiğim,

Yoksa can yurdundan bıkar sevdiğim...

Murat Nail Güney

05/05/2005   Akçay kışlası-İskenderun', 'Engin ufuklarda solarken güneş, Sular hüzne çalar, akar sevdiğim. Mazide kalan o sensiz yıllarım, Ateşler söndürür, yakar sevdiğim... Gizlem...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adin-gizli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerim', 'siirlerim-murat-nail-guney-ckl4v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimi döktüm beyaz kağıda,

Allı, morlu çiçek oldu şiirler.

Dünyayı gezdiler gündüz ve gece,

Gönülden gönüle doldu şiirler...

Bazen acı oldu yürekler yakan,

Bazen şimşek oldu peş peşe çakan,

Bazen Kardelen''di, kışımda çıkan,

Kırk sekiz baharım buldu şiirler...

Dostluğa köprüdür, sevgiye konak,

Sanki öpülmeye hasret bir yanak,

Asla haksızlığa tutmadı çanak,

Özlem mektubuma, puldu şiirler...

Ne yaşadım ise, söyler an be an,

Yare kavuşturan beyaz küheylan,

İçim rahatlıyor yazdığım zaman,

Benimle ağlayıp, güldü şiirler...

Bizle yaşadılar dünü, bu günü,

Ne güzel anlatır, bayram, düğünü,

Kimi de gizlerler nefreti, kini,

Dostluğa köleydi, kuldu şiirler...

Yüzyıllar boyunca yaşarlar her an,

Onda huzur bulur seven her insan,

Yerinde duramaz can içinde can,

Ruhumda tomurcuk güldü şiirler...

Kimi zaman tarih olur, belgedir,

Okyanusta, denizlerde dalgadır,

Anlayana sarı altın halkadır,

Beni hülyalara saldı şiirler...

Aşığın dilinde, deya gibidir,

Kimi şarkı, kimi arya gibidir,

Anlamayana angarya gibidir.

İnsanlığa miras kaldı şiirler...

Muradım, sabrına rehber oldular,

Bizle yeşerdiler, bizle soldular,

Kaç gece sabahı benle buldular,

Sevgisiz kalınca, öldü şiirler...

Murat Nail Güney

15/06/2005  saat: 22:45', 'Yüreğimi döktüm beyaz kağıda, Allı, morlu çiçek oldu şiirler. Dünyayı gezdiler gündüz ve gece, Gönülden gönüle doldu şiirler... Bazen acı ol...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/siirlerim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğine Sor Beni', 'yuregine-sor-beni-murat-nail-guney-k78b2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denizi görünce beni anarsan,

Ufuktaki Turnalardan sor beni,

Sevda dolu kıvılcımlar çakıyor,

Bakışların ne hallere kor beni...

Vadideki Zambak, kırdaki çiçek,

Açmışlar sevdiğim, bak biz bekler,

Boşuna gitmesin bunca emekler,

Sevgi dolu kollar ile sar beni...

Senle her nefesim ömre bedel, can,

Seven gönüllerde bitmez heyecan,

Seninle el ele olduğumuz an,

Sanki Melekler Cennete kor beni...

Rüya değil gerçeğimsin, canımsın,

Havam, suyum, damarımda kanımsın,

Onulmaz yareme tek dermanımsın,

İnanmazsan yüreğine sor beni...

Doğan şafağıma müjdeler getir,

Sanki bunu bana Mevlam söyletir,

Sana yar olmazsam, işimi bitir,

Alnımın tam ortasından vur beni...

Muradım, sevgidir hep baki kalan,

Dünya denilen yer ezelden yalan,

Bir hoş seda ise ardından kalan,

Sevgisiz yaşamak, korkutur beni...

Murat Nail Güney

08/06/2005   Anamur', 'Denizi görünce beni anarsan, Ufuktaki Turnalardan sor beni, Sevda dolu kıvılcımlar çakıyor, Bakışların ne hallere kor beni... Vadideki Zamba...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yuregine-sor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hassul havas dua.', 'hassul-havas-dua-ali-riza-unal-g9r8q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Firâkın isyana düçâr eder, bende varımı.

Bana sen ile sensizlik çektirme canân.

Hayayı hicabım,cümle mahlûkat, kula ar-ımı.

Beni umman içinde,katreye çektirme canân.

Aşkın ile terk ettim günâhı sevabı birde tövbeyi.

Bu lisanı dil senindir,srrını faş eyleme canân.

Not: Kitabı divanı suphaniyemizden.

aşıkı arifana ledünni mana sofrasıdır.', 'Firâkın isyana düçâr eder, bende varımı. Bana sen ile sensizlik çektirme canân. Hayayı hicabım,cümle mahlûkat, kula ar-ımı. Beni umman içind...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hassul-havas-dua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben...', 'ben-sadik-dursun-3hkqq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben,

Belirsizliklerde savrulan,

Bir fersiz beden.

Yüreğiyle aciz,

Yüreğiyle,

Çaresiz.

Ben,

Gizlenmiş derinliklerde,

Kaybolup giden.

Bir deryada sensiz,

Tükenmiş haykırışlarım,

Tükenmiş,

Sessiz.

Ben,

Seni arıyorum,

Gözlerimde ağlarken.

Sana adayamadığım 

Hayatımla,

Ben kaybolmuş bir iz,

Kaybolmuş,

Kimsesiz.', 'Ben, Belirsizliklerde savrulan, Bir fersiz beden. Yüreğiyle aciz, Yüreğiyle, Çaresiz. Ben, Gizlenmiş derinliklerde, Kaybolup giden. Bir dery...', ARRAY['Türk Edebiyatı','Şiir','Sadık Dursun']::text[], 8.5, '{"poet":"Sadık Dursun","poet_slug":"sadik-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-175-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharı Yaşamaktayım', 'bahari-yasamaktayim-halil-i-brahim-kecebas-u1m9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşüncelerimin şimdi başucundayım.

Tüyden hafif olurum böyle zamanlar; 

Bir kış günü baharı yaşamaktayım.

Gönlümde çiçekler açar böyle zamanlar.

Aslında sevmek kolay değil,

Unutmak ise daha zor; 

Kavuşmak çok defa mümkün değil,

Bir de bunu sevip de ayrılanlara sor.

Ben karamsar şairler gibi değilim.

Karanlığın içinde bir ışık bulurum; 

Olamasa bile yürekten sevenim.

Bahar şarkıları söyleyerek avunurum.

17.01.2003', 'Düşüncelerimin şimdi başucundayım. Tüyden hafif olurum böyle zamanlar;  Bir kış günü baharı yaşamaktayım. Gönlümde çiçekler açar böyle zaman...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Keçebaş']::text[], 8.5, '{"poet":"Halil İbrahim Keçebaş","poet_slug":"halil-i-brahim-kecebas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bahari-yasamaktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antoloji cemde kâtibim demde', 'antoloji-cemde-k-tibim-demde-ali-riza-unal-c7gk3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gayrı sözler nadide,yazılmaz antoloji kütübü cemde.

Hal kırklardan öte,anılmaz.anlaşılmaz kâtibim demde :))', 'Gayrı sözler nadide,yazılmaz antoloji kütübü cemde. Hal kırklardan öte,anılmaz.anlaşılmaz kâtibim demde :))...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/antoloji-cemde-katibim-demde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-ali-galip-sari-ouokf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm dediğine katlanırım da,

Senden vazgeçmekten korkuyorum ben.

Nedir ki, nedir ki zehir dediğin,

Sensizken içmekten korkuyorum ben.

Adını anmadan geçerse bir an,

Farzet ki durmuştur ülkemde zaman,

Azrail kapımda belirdiği an,

Sensiz can vermekten korkuyorum ben...

                                                     16.06.2005 //Ankara', 'Ölüm dediğine katlanırım da, Senden vazgeçmekten korkuyorum ben. Nedir ki, nedir ki zehir dediğin, Sensizken içmekten korkuyorum ben. Adını ...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/korku-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekkeler', 'tekkeler-yusuf-ter-6yq1g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'takiyeyle kendi halkın kandıran

ondan sona imf ye bandıran

boğa olmuş ona buna saldıran

soğuk duşla taraftarı  donduran

ak  içinde  kara çıktı duydun mu

sandığına  evet oyu koydun mu

sen böyle bir kaydırakta kaydın mı

soğuk duşla taraftarı  donduran

yusufum marifet olmuş tekeller

başımıza  sardı tontonlar keller

vatanı soydular namussuz döller

soğuk duşla taraftarı  donduran

Yusuf Ter 19.06.05

Saat 01:03 İsviçre', 'takiyeyle kendi halkın kandıran ondan sona imf ye bandıran boğa olmuş ona buna saldıran soğuk duşla taraftarı  donduran ak  içinde  kara çık...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tekkeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyüm Benim', 'koyum-benim-yusuf-ter-k76ac', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Teki diyar etmiş gurbet ellere 

Yıkılmış virane olmuş kozaklım

Üç beş yaşlı dulu yetimi kalmış

Yıkılmış virane olmuş kozaklım

 Hasretim yıllardır soğuk suyuna

 Suyundan yapılan berrak çayına

 Bu gideceğim temmuz ayına

 Hasretin içimde gülmüş  kozaklım

Kıraç köyüm yolu yazı yabanda

Gelişti mi acep o  kasabam da

Hasretlik zor imiş çıkmıyor canda

Yüreğimde izin kalmış kozaklım

Yusuf’um yaz Ankara’ya dilekçe 

Okurlar mı  bilmem posta gidince

Kalem kırarlarmış hak isteyince

Memleket zalimle dolmuş kozaklım

Yusuf Ter 19.06.05

Saat 01:43 İsviçre', 'Teki diyar etmiş gurbet ellere  Yıkılmış virane olmuş kozaklım Üç beş yaşlı dulu yetimi kalmış Yıkılmış virane olmuş kozaklım  Hasretim yıll...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/koyum-benim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalın Ucunda', 'dalin-ucunda-vasfi-ayaz-z2tvd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalın Ucunda

İnce bir iplik orta yerde,

koptu,kopacak..

Ökseye yakalanmış kanat

beyaz bir kelebek uçtu,uçacak.

Beyaz gömleklinin biri

''Günleri sayılı''

Beyaz eteklinin biri

''Alnına yazılı'' dedi.

Ufaldı,ufaldı evren,

nefes alışlara sığdı.

Titredi öksenin dalları birden.

Beyaz kelebek kanat çırptı.

Döküldü kum saatının son taneleri.

Görünmez emanetci,

kalanlara göz kırptı.

Kovaladı feryatlar,hıçkırıkları

beyaz koridorlarda.

Bilinmeze bir göç daha yansıdı,

sevenlerinin göz pınarlarına.

Beyaz gömlekliler''''günleri sayılıydı''

Beyaz etekliler''alnına yazılıydı’’

Diyebildiler,sadece,

teselli niyetine.

                                             Vasfi AYAZ', 'Dalın Ucunda İnce bir iplik orta yerde, koptu,kopacak.. Ökseye yakalanmış kanat beyaz bir kelebek uçtu,uçacak. Beyaz gömleklinin biri ''Günle...', ARRAY['Türk Edebiyatı','Şiir','Vasfi Ayaz']::text[], 8.5, '{"poet":"Vasfi Ayaz","poet_slug":"vasfi-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dalin-ucunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Geleceksin', 'bana-geleceksin-vasfi-ayaz-y62hq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana geleceksin! ! 

Saklanma arasına mor bulutların,

Ben başlarım bittiği yerde umutların.

Ben toprağım,bana geleceksin, 

İplik,iplik yağmurlarla.

Kaçma derinine okyanusların,

Kırılınca bedeni fanusların,

Ben sahilim,bana geleceksin,

Gürül,gürül dalgalarla.

Gizlenme içine,bal rengi gözlerin. 

Kavuşmada geregi yok,sözlerin.

Ben ağlama duvarı bana geleceksin,

 Damla,damla yaşlarla.. 

                  

                                                              Vasfi AYAZ', 'Bana geleceksin! !  Saklanma arasına mor bulutların, Ben başlarım bittiği yerde umutların. Ben toprağım,bana geleceksin,  İplik,iplik yağmur...', ARRAY['Türk Edebiyatı','Şiir','Vasfi Ayaz']::text[], 8.5, '{"poet":"Vasfi Ayaz","poet_slug":"vasfi-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bana-geleceksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Romantika', 'romantika-vasfi-ayaz-rxg9g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Romantika

yaşanmış güzellikler,düne kelepçeli,

çaresizlik,ümitsizlik müebbet gibi.

gururlardan set,çaresizlik bin heceli,

halimiz,yönü bulunmaz mabet gibi.

bir adım geleceğini bilsem, bin adım koşarım.

bilirmisin, her anımı bu ümitle yaşarım.

kirpiklerinden süzülen,hasret damlacıkları,

ardıç dikeninde, sabah çiği gibi.

yitirilmiş mutluluğun sancılırı,

her nefeste, yüreğime batan çivi gibi.

bir adım geleceğini bilsem, bin adım koşarım.

Bilirmisin, her anımı bu ümitle yaşarım.

                           

                                           vasfi ayaz', 'Romantika yaşanmış güzellikler,düne kelepçeli, çaresizlik,ümitsizlik müebbet gibi. gururlardan set,çaresizlik bin heceli, halimiz,yönü bulun...', ARRAY['Türk Edebiyatı','Şiir','Vasfi Ayaz']::text[], 8.5, '{"poet":"Vasfi Ayaz","poet_slug":"vasfi-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/romantika-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fantazi', 'fantazi-vasfi-ayaz-tmf87', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fantazi

kollarım belini

sarmak,

yüzüm nefesini 

duymak,

dudağım dudağına 

değmek istiyor.

bir cevabın olsun,ya öyle ya böyle.

şaşkın kız,bırak nazı,sen yüreğini söyle.

arzularım tam olunca,

kalbim seninle dolunca,

gönül, bir ömür boyunca

seninle kalmak istiyor.

bir cevabın olsun.ya öyle ya böyle

şaşkın kız,bırak nazı,sen yüreğini söyle.

   

                                     vasfi ayaz', 'Fantazi kollarım belini sarmak, yüzüm nefesini  duymak, dudağım dudağına  değmek istiyor. bir cevabın olsun,ya öyle ya böyle. şaşkın kız,bır...', ARRAY['Türk Edebiyatı','Şiir','Vasfi Ayaz']::text[], 8.5, '{"poet":"Vasfi Ayaz","poet_slug":"vasfi-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fantazi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim köy', 'bizim-koy-mikdat-bal-mcipp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu bizim köyümüzden biraz haber vereyim

Ahvali manzarayı göz önüne sereyim

Eski ismi gorgoras yenisi Eğridere

Çaykaradan yaylaya cennet gibi bir yöre

Su elektrik yok idi bir tek çeşmemiz vardı

Yollar çamur, patika, iki kişiye dardı

İnsanlar birbirini kardeş gibi severdi

Her kes arkadaşını gıyabında överdi

Çoğu fakirdi lakin gönüller zengin idi

Hürmet,saygı,muhabbet hoş görü engin idi

Birinde dert olunca herkes ortak olurdu

Komşuları mutlaka çaresini bulurdu

Dul,yetıim,fukaralar beyden iyi yaşardı

Yediden yetmişine yardımına koşardı

Biri evi yansaydı hiç üzülmezdi buna

Köylüsü daha güzel bir ev yapardı ona

Ne oldu bu millete bilen varsa söylesin

İnsanlık öldü ise Allah rahmet eylesin

Her şeyde el birliği, büyükler dinlenirdi

En basit örnek, yayla aynı gün şenlenirdi

Her şeyde ahenk vardı, saygı, sevgi olunca

Köy yaşanmaz yer oldu, hoşgörü azalınca

Omuz omuza iken, insanlar sırt çevirdi

Hiç kusura kalmayın haset bizi devirdi

Geçen yıl izin yaptım, sıla-ı rahim ettim

Arkadaşın birine, falancı nerde dedim

Dedi sen onu boş ver, itin teki, yaramaz

Dedi bu köyde kimse, birbirini aramaz

Vardım camiye gittim, baktım cemaatı çok

Namazı kıldık çıktım, bir de baktım kimse yok

Meğerse hiç bir kimse birbiriyle konuşmaz

Onun için kaçarlar aynı yerde buluşmaz

Ne oldu bu millete, nerede eski neşe? 

Dönelim kendimize dur diyelim bu işe

“mu''minler yek vucuttur” diyen pegamberimiz

Ümmeti olduğunu söylüyor her birimiz

Buyurur ki: “ giremez cennete inanmayan

İman etmiş olamaz birbirini sevmeyen”

Birbirine küs olan kavuşamaz rahmete

Rivayetler sarihtir çok zor girer cennete

Hayat cehennem oldu ahiret tehlikede

Bu işe son veriniz yazıktır memlekete.

Mikdat der sürci-lisan eylediysem affola

Umarım bu dargınlık hemen bertaraf ola', 'Şu bizim köyümüzden biraz haber vereyim Ahvali manzarayı göz önüne sereyim Eski ismi gorgoras yenisi Eğridere Çaykaradan yaylaya cennet gibi...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bizim-koy-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-meltem-adiguzel-3mqpz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden dertli oldum hiç bilmem ki,

Kalbim neşe dolsa ben gülmem ki,

Sen bekleyip dursan da ben gelemem ki,

Çünkü yollar uzak ayrıyız şimdi....

Düşünüp dertleri hep içime attım,

Hayatta zehrin tadına baktım,

Kesin sözü verip seni aldattım,

Fakat kader buymuş ayrıyız şimdi...

Ne mektup ne selam bir haber gelmez,

Derler ki sevenler mesut olmaz,

Bülbül harı bulsa gülü aramaz,

Hep dolaşıp durur bağları şimdi....

Zalim kader deyip isyan etsemde,

Eşime dostuma derdim döksemde,

Başım alıp bu diyardan gitsemde,

yollar izin vermez olmuştur şimdi...', 'Neden dertli oldum hiç bilmem ki, Kalbim neşe dolsa ben gülmem ki, Sen bekleyip dursan da ben gelemem ki, Çünkü yollar uzak ayrıyız şimdi......', ARRAY['Türk Edebiyatı','Şiir','Meltem Adıgüzel']::text[], 8.5, '{"poet":"Meltem Adıgüzel","poet_slug":"meltem-adiguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilik-256-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzüm düşüyor başımdan', 'yuzum-dusuyor-basimdan-suna-aras-bh0hh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah saat altı otuz yağmur yağıyor

İş başında bir cerrahın ciddiyeti içinde

Almışım beni önüme

Nemi üstünde etin sabun kokusu

Masada kâğıt kalem sigara kül tablası

Buğusu üstünde bir fincan kahve

Bu günkü şiir dizimi insan anatomisi

Acı aşkla donduruldu

Her harfi bir dilime batırıp diziyorum

Gözlerimi gökyüzünün umudundan kopardım

Bu yalanı üfleyip içini siliyorum.

İkinci kadın direniyor içimde

Kıpraşıp titreşiyor sözün acıttığı iz

Çıplaklığı bedenin uçuşan bir çocukluk

Altını üstüne aktaran bilinç

Tırnak içlerinde kuruyan kan ölüyor

Çırpınışı adının iki söz arasında

Yüzüm

Tutunup tırmanıyor düşüyor sonra

Ve sadece inliyor.

Bir boşluğa doğruyum

Çekiyor fitilini içine dünya

Tırtıldım o kıyıda kuruyan kendine çekilen tırtıl

Dedim

Aşktır aklı yarılayan ey nebi derya

Özlemdir

Bir ucu uykuda bir ucu derin ve gürbüz

Kime soru sorduysam hayattı bağışlanan

Gözlerimin dibi diken tarlası, neden

En çok onu yine onu sevdim, aşk

Gel de konuştur beni bütünümü ver bana dilimi çöz

Tarihin

Yarısından fazlası kızarsın hicabından.

Ne zaman bir gülle göz göze gelsem

Bülbüle bağışlarım aşk sıçratır üstüme.

Yüzüm düşer başımdan.', 'Sabah saat altı otuz yağmur yağıyor İş başında bir cerrahın ciddiyeti içinde Almışım beni önüme Nemi üstünde etin sabun kokusu Masada kâğıt ...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yuzum-dusuyor-basimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babacığım Seninle', 'babacigim-seninle-rifki-kaymaz-krmes', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Babacığım seninle,

	Evimize can gelir.

	Yürek dolusu sevgi,

	Bize heyecan gelir.

	Babacığım seninle,

	Güven dolar evimiz.

	Mutlulukla yıkanır,

	Sevgiyle yüreğimiz.

	Babacığım seninle,

	Umutlar kucak kucak.

	Doldurur evimizi,

	Bizi sarar sımsıcak.

	Babacığım seninle,

	Apaydınlık yüzümüz.

	Huzur bulur seninle,

	Gecemiz, gündüzümüz.

	Babacığım seninle,

	Yarına umutluyuz.

	Annemle kardeşlerim,

	Seninle çok mutluyuz.', 'Babacığım seninle, 	Evimize can gelir. 	Yürek dolusu sevgi, 	Bize heyecan gelir. 	Babacığım seninle, 	Güven dolar evimiz. 	Mutlulukla yıkanı...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/babacigim-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örümcek ağı', 'orumcek-agi-durmus-karakus-oefhp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani ben hep derdimya birazcık sende sevde,

Erisin şu gönlümün güngörmemiş buzdağı.

Sana olan aşkımı anlattığım o evde,

Hertarafı kaplamış inan Örümcek ağı.

Ne kapısından bakan nede bir giren olmuş,

Oda yalnız geçirmiş yıllaryılı bir çağı.

Duvarda senden kalan resim sararmış solmuş,

Hertarafı kaplamış inan Örümcek ağı.

Tabanları küf tutmuş tavan ise çürümüş

Dondum kaldım bir anda kesilmişti kanbağı.

Sanırsın torosları boz bir duman bürümüş,

Hertarafı kaplamış inan Örümcek ağı.', 'Hani ben hep derdimya birazcık sende sevde, Erisin şu gönlümün güngörmemiş buzdağı. Sana olan aşkımı anlattığım o evde, Hertarafı kaplamış i...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/orumcek-agi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boncuk', 'boncuk-rifki-kaymaz-93qhy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kahverengi benekli,

Tüyleri yumuşacık,

Mırıl mırıl mırıldar,

Ne sevimli sıcacık,

Her yemeği beğenmez,

Binbir oyun binbir naz,

Ben nerede, o orda,

Peşimden hiç ayrılmaz.

Oynatır kuyruğunu,

Sevildiğini anlar,

Kurulur pencereye,

Sokağı seyre dalar.

Ben içeri girince,

Gözlerim onu arar,

Otururum o gelir,

Beni sımsıcacık sarar.

Gözleri ışıl ışıl,

Mırlıyor, miyav diyor,

Ses veriyor sevgime,

Beni mutlu ediyor.', 'Kahverengi benekli, Tüyleri yumuşacık, Mırıl mırıl mırıldar, Ne sevimli sıcacık, Her yemeği beğenmez, Binbir oyun binbir naz, Ben nerede, o ...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/boncuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapma Vitiligo.', 'yapma-vitiligo-kadir-kaya-4a9e9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kader kısmetimden benimi seçtin,

Sana darılırım Bay Vitiligo.

Elimi bırakıp yüzüme geçtin,

Gezmeyi edindin Huy Vitiligo.

Mutlulukta buldum derken dengimi,

Al,al yanağımdan alma rengimi,

Gezdin yüzümde,bozdun ahengimi,

Her yerde gösterdin Boy Vitiligo.

Senin için içtim hamam suyunu,

Öğrenemedim,sen söyle huyunu,

Bir söylesem,torun kazar kuyunu,

Sana kızıyorum  Duy Vitiligo.

Isırgan otuyla Ebe gümeci,

Çörek otu versin sana demeci,

Nar gülü karışmış balın amacı,

Başka çare varmı Say Vitiligo.

Işın tedavisi sakın olmayın,

Kansorejen hapı,kremi almayın,

Gölgede durun,Güneşte kalmayın,

Gençlere el attın Doy Vitiligo.

Kafaya hiç takmayın,gerisi  boş,

Onunla yaşayıp,sev,sevgiye koş,

Mevla’mın lütfuda hoş,kahrıda hoş,

Sebebi hayıra Yoy Vitiligo.

Bilirim malzemen çilem,kederim,

Çaresiz boşuna sitem ederim,

Yaşadığım bir bir benim kaderim,

Sabırla,şükürü Koy Vitiligo.

Not: Vitiligo Cildin beyazlama hastalığı', 'Kader kısmetimden benimi seçtin, Sana darılırım Bay Vitiligo. Elimi bırakıp yüzüme geçtin, Gezmeyi edindin Huy Vitiligo. Mutlulukta buldum d...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yapma-vitiligo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir de suna can ağlar.', 'bir-de-suna-can-aglar-suna-aras-6hw7s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Al kalbimin yasını kur bırak başucuna

İstanbul şehrinde Üsküdar ağlar

Kırılan her aşkta bir gönül susar

Kirpik yol göstermez gözde yaş ağlar.

Bu gece dursun gece

İlk dokunuş ten ağlar

Bu gece dursun gece

Bir de Suna can ağlar.

Hangi an anlamını yitirdi gidişinle

Dumanı yok eder köz olan aşklar

Her anı kendini besler büyütür

Boy verir ardında kalanlar ağlar.

Bu gece dursun gece

İlk öpüş o an ağlar

Bu gece dursun gece

Bir de Suna can ağlar.', 'Al kalbimin yasını kur bırak başucuna İstanbul şehrinde Üsküdar ağlar Kırılan her aşkta bir gönül susar Kirpik yol göstermez gözde yaş ağlar...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-de-suna-can-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden...', 'neden-avni-aydin-b8zzw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'neden? 

ya da nedendir? 

olmaz denilenlerin olduğu...

tutmaz denilenlerin tuttuğu...

mutlu olamamaksa neden tum guzelliklerin arasında,

ya da bulamamaksa bir damla hasretin getirdiği o garip mutluluğu...

konuşupta düşünmeden ve sonra pişman olmaksa neden,

tadı bile başkaysa salaş bir lokantada bulunmanın artık...

neden hissetmeye başlamışsan bişeylerin hep tekdüzeliğini

ve her nedense bulamadıysan yanıtını? 

kaçmak daha kolay geliyorsa yüreğine hayattan? 

ya da daha kolaysa koşmamak, akıp giden hayatın ardından...

sonu gelen yol mu var yalnız yüreklere...

bunu tekrarlayıp yollara düşüyorsan her gece,

ve her gece tek dostun seni oradan oraya

ve amaçsızca götüren arabansa? 

bırakmaya çalıştığın sigarana yeniden başlayabiliyorsan nedensiz,

çektiğinde zehri ciğerlerine,

bişeyleri tekrar eskisi gibi hissedebiliyorsan...

cevabını daha fazla aramak istemiyorsan nedenlerine,

her yorgun yürek gibi takılıp gideceksin,

gönül sofrasındaki yaralı aslanlara...', 'neden?  ya da nedendir?  olmaz denilenlerin olduğu... tutmaz denilenlerin tuttuğu... mutlu olamamaksa neden tum guzelliklerin arasında, ya d...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neden-156-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen miydin? O', 'sen-miydin-o-hasan-bilgin-7j8lq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen miydin? 

beni ağlatan sabahlara kadar 

yıllarca...

sen miydin? 

uyutmayan beni gecelerce

sen miydin? 

düşündüren beni yıllarca

sen miydin? 

öldüren beni 

her gün...', 'sen miydin?  beni ağlatan sabahlara kadar  yıllarca... sen miydin?  uyutmayan beni gecelerce sen miydin?  düşündüren beni yıllarca sen miydi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Bilgin']::text[], 8.5, '{"poet":"Hasan Bilgin","poet_slug":"hasan-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-miydin-o-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlıktan...', 'i-nsanliktan-sadik-dogan-cnlpz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne para var gözümde ne mal mülk,

Dağıtıyorsam bol kesede, 

Bonkörlükten değil

İnsanlıktan... İnsanlıktan... 

Vurulmuşsam saçlarına, 

Almışsam seni gönlüme, 

Seviyorsam delicesine, 

Güzellikten değil 

İnsanlıktan... İnsanlıktan... 

Yaşıyorsam sere serpe, 

Dağıtıyorsam geceleri, 

Türkülerle süslüyorsam duygularımı, 

Yalnızlıktan değil

İnsanlıktan... İnsanlıktan... 

Herkesi seviyorsam, 

Düşmanımı da koruyorsam, 

Dostumun değil de doğrunun yanında oluyorsam, 

Nankörlükten değil

İnsanlıktan... İnsanlıktan... 

Sen bu millettensin, ben şu soydan,

Demeden kucaklayabiliyorsam herkesi, 

Haklının yanında cephe alabiliyorsam, 

Kansızlıktan değil 

İnsanlıktan... İnsanlıktan... 

''''Savaşa Hayır'''' sloganını taşıyorsam yüreğimde, 

Başımı hep dik tutabiliyorsam, 

Açabiliyorsam savaşanlara karşı savaş, 

Kahramanlıktan değil

İnsanlıktan... İnsanlıktan... 

Kalemim çalışıyorsa sürekli, 

Yazıyorsa bir bir kederimi 

Ve şiirimi besleyebiliyorsam gözlerimle, 

Bencillikten değil

İnsanlıktan... İnsanlıktan... 

Mezhep farkı yoksa özümde, 

Bütün inançlara saygı duyabiliyorsam 

Ve sonra laik olmayı öneriyorsam, 

Dinsizlikten değil

İnsanlıktan... İnsanlıktan... 

Özgürlük çorbasını içebiliyorsam hep bir ağızdan, 

Yaratılanları seviyorsam yaratandan ötürü, 

Dünya düzdür diyorsam, 

Cahillikten değil

İnsanlıktan... İnsanlıktan... 

İnsanlık adına yazıyorsam bunları, 

Düşüncelerimi özgürce paylaşabiliyorsam sizlerle 

Ve insanlık namına koyuyorsam yüreğimi ortaya, 

Bu şiir artık benden değil

İnsanlıktan... İnsanlıktan... 

18.07.2005/Osmancık', 'Ne para var gözümde ne mal mülk, Dağıtıyorsam bol kesede,  Bonkörlükten değil İnsanlıktan... İnsanlıktan...  Vurulmuşsam saçlarına,  Almışsa...', ARRAY['Türk Edebiyatı','Şiir','Sadık Doğan']::text[], 8.5, '{"poet":"Sadık Doğan","poet_slug":"sadik-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/insanliktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Sonsuzluk', 'rubai-sonsuzluk-nihat-yucel-typ4b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanrım ben o sonsuzluğa ermek dilerim

Sonsuzdaki her gizliyi görmek dilerim

Rüya gibi hülya gibi dünya ben de

Rüyamı güzellerle geçirmek dilerim

                                     Haziran/69', 'Tanrım ben o sonsuzluğa ermek dilerim Sonsuzdaki her gizliyi görmek dilerim Rüya gibi hülya gibi dünya ben de Rüyamı güzellerle geçirmek dil...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-sonsuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Gönül', 'rubai-gonul-nihat-yucel-0prk6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben çektiğin ahzanı derim yare gönül

Bir yar için etme mihnet ağyare gönül

Feryadını yar anlamak ister miki hiç

Öyleyse senin derdine yok çare gönül

                                      Temmuz/69', 'Ben çektiğin ahzanı derim yare gönül Bir yar için etme mihnet ağyare gönül Feryadını yar anlamak ister miki hiç Öyleyse senin derdine yok ça...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şifre', 'sifre-kemal-guzel-qxfmj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çözmek  ne mümkün

ne mümkün aşkı çözmek

ne münkün aşkı yaşamak 

dost başına yaşamak

yaşamak aşkı dost başına

ol olki aşık gör hayat ne güzel

gör çiçekler ne renkli

başlı başlına hayattır aşk

mutluluğun ötesidir aşk

bir buluşmanın ilk heyecanı

bir başarının son anıdır

bir kaybın ta ortasıdır

gariptir.

manidir dilden dile

ayindir dinden dine

yavrudur anadan anaya

sudur susadıkça içmek istemektir o suyu

yabanidir mahzundur yalnızdır 

kimsesizdir herkesle yaşadıkça 

yaşadıkça aşkı tanımaktır geleceği

^^ YAĞMURUN ALTINDA ISLANDIKÇA-ISLANMAKTAN MUTLU OLMAKTIR AŞK ^^

şifresidir aşkın düşünmek

aşık olanada hep bu düşer

     (DÜŞÜNMEK-DÜŞÜNMEK-DÜŞÜNMEK)', 'çözmek  ne mümkün ne mümkün aşkı çözmek ne münkün aşkı yaşamak  dost başına yaşamak yaşamak aşkı dost başına ol olki aşık gör hayat ne güzel...', ARRAY['Türk Edebiyatı','Şiir','Kemal Güzel']::text[], 8.5, '{"poet":"Kemal Güzel","poet_slug":"kemal-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sifre-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Doludur', 'rubai-doludur-nihat-yucel-uys5j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '- Namık ve Sevilay''a                           

Her sevgilinin gözleri mana doludur

Manasız sözler bile mana doludur

Gerçekten uzak halleri vardır bilirim

Dünya gelecek onlara rüya doludur

                                             Mart/70', '- Namık ve Sevilay''a                            Her sevgilinin gözleri mana doludur Manasız sözler bile mana doludur Gerçekten uzak halleri ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/rubai-doludur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai İster', 'rubai-i-ster-nihat-yucel-iz54j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her sevgili yar derdine derman ister

Sen istemesen sevmeni canan ister

Her bir adımında bastığın yer bizden

Her an yeni bir aşığı kurban ister

                                    Mayıs/71', 'Her sevgili yar derdine derman ister Sen istemesen sevmeni canan ister Her bir adımında bastığın yer bizden Her an yeni bir aşığı kurban ist...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-ister-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaşam Düşle', 'bir-yasam-dusle-nurcan-ugurlu-de17t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yaşam düşle

Tüm mevsimlerin üstünde

İster asırlar kadar uzun

İster en küçük zaman birimi kadar

 Kısa olsun

Öyle bir yer rezerve etki

Sevgiye

Öyle bir yer rezerve etki

 İyiye, doğruya, güzele

Yaşamın boyunca

Umutlar filizlensin yüreğinde', 'Bir yaşam düşle Tüm mevsimlerin üstünde İster asırlar kadar uzun İster en küçük zaman birimi kadar  Kısa olsun Öyle bir yer rezerve etki Sev...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Uğurlu']::text[], 8.5, '{"poet":"Nurcan Uğurlu","poet_slug":"nurcan-ugurlu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-yasam-dusle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-erdal-ustunbas-5jlvr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmurun bu kadar ıslak olduğunu keşfetmemiştim

Düşünmemiştim senden önce düşünmeyi

Özlem in ne olduğu o kadar umurumda değildi

Yaşamak için yeterdi nefes almak senden önce..

Ama..

Sen varsın artık her şeyden önce..

Nefes alırken oksijen diye senin isminin harfleri

Nefes borumdan içeriye giriyor sanki..

Artık özlemin ne olduğu değil

Özlemimin sebebini umursuyorum..

Yaşamak içinse nefes almak bile yetmez olur...

Sen artık damarımın kanı,çayımın şekeri..

Bendeki aşk beterin beteri..Artık hayalinde yetmez olur..

Sen

Sen her şeye yetersin biliyorum..

Ah be kara gözlüm

Seni çooookk seviyorum..', 'Yağmurun bu kadar ıslak olduğunu keşfetmemiştim Düşünmemiştim senden önce düşünmeyi Özlem in ne olduğu o kadar umurumda değildi Yaşamak için...', ARRAY['Türk Edebiyatı','Şiir','Erdal Üstünbaş']::text[], 8.5, '{"poet":"Erdal Üstünbaş","poet_slug":"erdal-ustunbas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yagmur-188-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-i-shak-ozlu-30m6n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün elim kalem tutuyorsa,

Oglum,kızım sevgiyle arıyorsa,

Gözlerim dünyaya umutla bakıyorsa,

Elbet sebebi sensin Babam.

Oniki çocuk,ikide kadın,

Belkide yoktu hiç tadın,

Derdini gizleyip içine attın,

Dermanla yanımda oldun Babam.

Kucağına alıp doyasıya sevmedin,

Bilerek haram lokma yedirmedin,

Tokat,küfür nedir hiç bilmedin,

Yüreğinle,bakışınla sevdin Babam.

Bugün babalar günü diyorlar,

Unutanlar telefonla hatır soruyorlar,

Yabancı adetlerini bizim sanıyorlar,

365 gün yüreğimdesin Babam.

Mezar taşını yosunlar bağladı,

Gözlerim yaş dökmeden ağladı,

Sevgin yüregimi acıyla dağladı,

Dualarım seninle bilesin Babam.

Tüm Babaları sevgiyle selamlıyorum.', 'Bugün elim kalem tutuyorsa, Oglum,kızım sevgiyle arıyorsa, Gözlerim dünyaya umutla bakıyorsa, Elbet sebebi sensin Babam. Oniki çocuk,ikide k...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/babam-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Deli Sürgün', 'deli-surgun-emine-deniz-zvula', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey hayatıma  yabani öfkeler taşıyan gece

Kırdığım kibrit çöpleri,kazdığım siperler her yenilgi sonrası

İçemediğim ağız

Doğurgan anamın sebepsiz ağrısı dökülen göğüslerinden

Ve içtiğim şarap

Andolsun

Andolsun bu gece ay kızıllığından utanacak...

Ve bütün yıldızlar, soyunup vahşiliğinden  dolunayın şaha kalkacak.

Deniz ‘dir göğsüm

İn dik yamaçlardan ve yerleş içime ölüm...

Kısa çizgiler çiz yüzüme,

Ve kesikler at boğazımdan sırtıma uzanan

 derin kesikler ki içleri irin 

panzehiri var mıdır  bu kadar kinin

anne söyle

bana senden mi miras bu deli sürgün? 

Yatmış pusuya bekler sefil yangınlar

Dudaklarımda körüklenen ihtiraslı   sevdalara inat.

Ha sen varsın parmaklarımın arasında dolanan yuvarlak,derin

Ha ölüm gözlü  çocuklar,gelincik yüzlü bahçeler kadar serin...

Nedir bu karmaşa,nedir bu yaşanmışlığın içinde ölüm peltesi

Bu kahkaha,bu acı

Bu delice raks

... hevesi 

... neşesi

 hüznü dize getiren bu kösnü sesi

Ya Rab

Beni bu gece İbrahim’in atıldığı ateşlere at....', 'Ey hayatıma  yabani öfkeler taşıyan gece Kırdığım kibrit çöpleri,kazdığım siperler her yenilgi sonrası İçemediğim ağız Doğurgan anamın sebep...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/deli-surgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlamalarım-(Hicivlerim', 'taslamalarim-hicivlerim-vasfi-ayaz-uk4vx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'TAŞLAMALARIM   (Hicivlerim) 

                                       

                   EV İŞİ

DEMOKRASİYE Avrupadan ev işi getirir,

EKONOMİYE Amerikadan Dervişi getirir,

Baldan parmağını çekmedikce siyasiler,

Ne fayda,vatandaş hep ayni gevişi getirir. 

                                                                                 Vasfi AYAZ

   

11/mart/2001 tarihli Hürriyet gazetesinde Yalçın Bayerin köşesinde EV İŞİ başlığı yayınlanmıştır.                                                                   

K.DERVİŞ’ in dünya bankasından,gelip Ekonomiden sorumlu devlet bakanı olması, AB.nin,demokrasiye tam dönüş için,hükümetimize önerilerde bulunması sebebiyle,Dervişin lehine,aleyhine çok yazıldığı günlerde.

                                              ************

GÜNÜN SÖZÜ

Çağdaş zengin ülkelerin,bizden yarı bakanı var

Bizde katmerli,hepsinin eteğinde de yakını var.

Onlarınki gören olmalı,bizdekiler hep bakıyor,

Kral giyinik,ülkemim; çok seyircili talanı var. 

                                                   

04/EKİM/2001 tarihinde Hürriyet yazarı Y.Bayer GÜNÜN SÖZÜ başlığı atarak yayınlamıştır. 

.Amerikanın 17,Almanyanın 14 Japonya gibi kalkınmış ülkelerin 16 bakanı varken bizim gibi 

fakir ülkenin 37 bakanı olması sebebiyle yazılmıştır.Vasfi AYAZ

                                                  ***********



              Böyle gelmiş....

Salkım,salkım hediye paketleri yakışır bizim bakana,

Kim ne derki,vatandaş kesesinden hovardalık yapana.

Kimi içmemişde,dökmüş kenefe,,ayık olsanız ne azar,

Kim seyirci kaldı; vatandaş biliyor,girerken bu kapana.

                                                                                                                                    

 Hürriyet gazetesi Y.Bayerin köşesinde 02/ocak/2202 tarihinde ‘Böyle gelmiş... ‘’başlığı ile yayınlamıştır.

‘’Salkım hanımın taneleri’’ yazarı Tekelden sorumlu devlet bakanı Yılmaz Karakoyunlu,içinde tekel içki çeşitleri ile dolu yılbaşı hediye sepetlerini 550 milletvekiline yollamış,AK ve SP partili vekillerde şişeleri meclisin tuvaletlerine döküp tuvaletlere alkol kokusundan girilemez hale gelmiş ve bakanımızda vatandaşın vergileri ile hovardalık yapması üzerine yazılmıştır Vasfi Ayaz 

                                                                                 

                                     

                                                                      **************

Kimler layık görür kendini bunca kıyağa

Milletin vekilliği düşmelimi böyle ayağa? 

SEÇKİN olamadılar,nedense seçilmişlerimiz,

Alırlar oyumuzu,çıkınca balık kavağa..

09/10/2001 tarihli SABAH gazetesinde Erdal Bilalların köşesinde çıkmııştır..

Vekillerin kıyak emeklilikleri için anayasada yaptıkları kanun değişikliği sebebiyle yazılmış bir dörtlük..Vasfi AYAZ

                                                            

                                                                   ***************

                                        KAZIK’istan

Ey! yüce devletlüler,kaç post çıkacak bir koyundan.

Makamlar, niye geri adım atmaz bu k^arlı oyundan,

Üşüyen bebelere,kirlenen gökyüzüne; yazık ki yazık.

KAZIK’istan mı bu ülke,nereye el atsan orda kazık.

u hiciv 08/01/2002 tarihli Hürriyette Y.Bayerin köşesinde KAZIK ‘istan başlığı ile yayınlanmıştır.

                                                                                                                  

Maliye bakanlığı,Botaş,İğdaş Genel Müdürlükleri Belediye başkanları kendi kafalarına göre zam yaparak vatandaşı doğalgazdan kaçırmaya başladılar,En pahalı şehir olan Londrada bizden yarı ucuza satılmakta imiş.Bu makamlara gönderilmiştir....  Vasfi Ayaz 

                                                           ****************

Değiştim demekle olmuyor,huy canda ise,

Çok naneler! ! icad olur,delilik kanda ise

Tayyip boş ekim alanı buldumu savurur durur.

Tasa değil, akıllı çoğunluk beri yanda ise.

     07/03/2002 tarihinde Sabaha mektuplar köşesinde

                                             ‘’Değiştim diyenlere’’ başlığı ile çıkmıştır.                                                            

Tayyip Erdoğanın Değiştim deyip,kamu yerlerinde alkol için referandum yapılması,çok çocuk doğurun ‘Allah ne verdiyse’’ gibi lafları üzerine yazılmıştır.

Vasfi Ayaz

                                              

                                                        *******************

                       

                                       Değişenler

‘Değişenlerin’ çıktı sarımsak gibi beklenen kokusu.

Değişmeyen ‘arka bahçe’nin kara zambak korkusu.

Önbahçenin özgür beyaz papatyalarının suçu ne? 

Yeşerse oralarda da yaradılanı bir görmenin tutkusu.

                                                                                       Vasfi AYAZ            

 06/05/2004 tarihli HÜRRİYET de Y.Bayer köşesinde çıkmıştır..

                                                                 

T.Erdoğan başbakan olduktan sonra pek değişmediğini belli eden olaylar sebebiyle yazılmışr.

                                  ****************

                          AB KAPISI

Ne çok bilinmezli hale getirdik, şu AB.kapısını, 

Partisine,kurumuna göre,değişik algıladık yapısını

Çok bilen; ey yetkili makamlar kurumlar, öze gelin,

Aklın yolunu bulun,rahatlatın vatandaşımın kafasını.

10/mart/2002 de Yalçın Bayeri köşesinde AB KAPISI başlığı ile çıkmıştır

                                                                                        

Avrupa birliği konusunda partilerin söylemleri oya dönük üçgün evvel de MGK.sekreteri  orgeneralde Rusya ve İrana dostluk gösterip AB ye arkamızı dönelim gibi laflar etmesi üzerine yazılmıştır Vasfi AYAZ

                                      *******************

Af Kargaşası (karmaşası) 

Hukuk döndü lastiğe herkez bir yanından çekiştirir

Bilinirki devletin saygınlığını adalet pekiştirir,

Sindirmeyen midelere alkış karbonatı yetmez

Umut yok; onlar zamanı kargaşa ile geçiştirir.

                                                                                       Vasfi Ayaz

07 –05-2002  Hürriyetde Yalçın Bayerin köşesinde yayınlanmıştır

İki sene evvel çıkarılan af sebebiyle 36 bin hırsız katil salıverilmişti,içerde kalanlar eşitlik ilkesine aykırı diye ana yasa mahkemesine müracaat ettiler kazandılar beşbin katil daha tahliye olacaktı,reisicumhur,veto etti fakat veto geç kalınca savcılar tahliyeye başladılar,şartlı tahliye,yok af gibi kavramlarla hukukcular iktidar ve reisicumhur ki hukucu herkez başka yorum yaparak memleketi bir hukuk karmaşasın içine soktular sanki milletin derdi az gibi 

.

                                                       ****************************

Af Kargaşası = Hukuk karmaşası

Hukuk döndü lastiğe herkez bir yanından çekiştirir

Biineki devletin saygınlığını adalet pekiştirir,

Sindirmeyen midelere alkış karbonatı yetmez

Umut yok; onlar zamanı kargaşa ile geçiştirir

                                                                                                         

Af  kargaşası = Hukuk  07/05/2002 tarihli SABAH Gazetesinde Hayrullah Mahmudun  VİZYON  köşesinde çıkmıştır       Vasfi Ayaz

                            

                                                   **************

                 SEDYE ile taşınacak hale geldi bu tezkere,

Anlaşılmaz çıkarlar yüklenir bizim askere.

Dipsiz kuyuları oluştu, Pentagon''un oralarda,

Kuyulara olta atan siyasetçilerimize rastgele .

                                                                                    Vasfi AYAZ-

               IRAK’a asker gönderilmesi hakkındaki teskerelerin karmaşa yarattığı gönlerde.  Mesaj başlığı ile HÜRRİYET -Yalçın Bayerin köşesinde 24.07.2003 tarihinde yayınlanmıştır

                                            *******************************

                        Nalıncı Keserleri

                        

‘’Hepbana’cılar Çankaya ile düşünce açmaza

‘’Nalıncı keserleri’de girdiler hukiki çıkmaza,

Kırk akıllı kuyu başında şimdi kös dinler,

Ne yapılsa meheldir,bunca şerbetli tınmaza.

                                                                                                       V.Ayaz

Vekillerin kendi çıkarları için çıkarılan kanunun Çankaya tarafından veto edilmesi sebebiyle..

                                            ********************

                       Yeni Sultanlar

‘Gömülmüştü saltanat tarihe’’ diyemez olduk,

Elimizle,oyumuzla yeni tip padişahlar yarattık.

Kimki sultaya; kıldan incedir bilemez olduk,

Yarınlarımız ümidsiz,dünlerimizi de kararttık.

                                                             V.Ayaz

Liderler sultası karşısında m.vekillerinin emirle parmak kaldırma ve indirmeden başka fonksiyonlarını olmayışı sebebiyle yazılmiştır 31/03/2002

Olmayasın bu günlerde iktidara keskin muhalif,

Tut dilini,gösterme dişini,görünme ortalarda muhalif

Asarlar bir çan boynuna Ergenokon nağmeleri üreten

Demokrasi kalsa da lafta,dursada rafta,sen kal  pasif.

Bir Ergenokon davası karmaşasının sürdüğü,emekli ordu komutanlarının bile neden suçlandıklarını bilmeden hapislerde yattığı günlerde yazılmıştır..

30-01-2009 tarihinde Hürriyet gazetesi Yalçın Bayerin köşesinde yayınlanmıştır.', 'TAŞLAMALARIM   (Hicivlerim)                                                             EV İŞİ DEMOKRASİYE Avrupadan ev işi getirir, EKONOMİ...', ARRAY['Türk Edebiyatı','Şiir','Vasfi Ayaz']::text[], 8.5, '{"poet":"Vasfi Ayaz","poet_slug":"vasfi-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":113,"source_url":"https://www.antoloji.com/taslamalarim-hicivlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-rifki-kaymaz-53qcd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm, ötelere açılan kapı,

Uhrevî âlemden derin bir izdir.

Bir ömrün sonunda, bir toprak yapı,

Mezar, acılarımız ve sevincimizdir.', 'Ölüm, ötelere açılan kapı, Uhrevî âlemden derin bir izdir. Bir ömrün sonunda, bir toprak yapı, Mezar, acılarımız ve sevincimizdir....', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olum-181-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derler', 'derler-rifki-kaymaz-6u0fk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bülbülün yanında gül olur derler

