INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Sessizliği', 'olum-sessizligi-hasan-can-5pbn8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O gün çok soğuktu,

Kar soğuğunu iyice hissettirmişti.

Ölüm kokan bir sessizlik vardı,

Soğuktan sokaklar bile titriyordu.

Odam da dolan satırların dışında çıt çıkmıyordu,

Öylesine sessizdi soğuğun derin kuytusun da odam.

Hava kararmaya başlamışken henüz,

Birden yağmur sesleriyle inledi sokaklar,

Kiremit uçlarındaki buzlar erimeye başlamıştı damla damla.

Satırlara eklenen yağmur sesi daha da üşütüyordu beni.

Sobamda köz kokusu var ışıltısı yok, sobamda üşüyordu.

Sağlam bir şiir dolmuştu satırlar yağmurun seside eklenince,

Uyuklar gibi oldum bi an, birden bir çığlık koptu, köpek inletisiydi,

Perdeyi araladım, göz gücü yetmeyen bir karanlık vardı,

Pencereyi açtım ses soluk kesilmişti, sessizce kara gömülmüştü köpek yavrusu.

Birden doldu gözlerim keder eklendi yüzüme.

Ölüm sessizliğinde bir akşam vaktiydi,

Kısa sürdü yağmurun sokakları inletmesi,

Olmayacak kadar azaldı satır sesleri.

O gün çok soğuktu, kar acı veriyordu kasabaya,

Bir oyun yolu bile kalmamıştı çocuklara,

Kasaba derin bir uykuya bürünmüştü sanki,

Çocuklar çoktan dalıp uyumuştu anlatılan masallara.

Ölüm sessizliğinde bir kar fırtınası,

Kanayan yüreğimin ağrısı,

Olmadı güzel bir gün,

Bitmeti kasabanın sızısı.', 'O gün çok soğuktu, Kar soğuğunu iyice hissettirmişti. Ölüm kokan bir sessizlik vardı, Soğuktan sokaklar bile titriyordu. Odam da dolan satır...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/olum-sessizligi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-para, para, para, para', 'a-para-para-para-para-mikdat-bal-b0fyl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Para, para, para.

İnsanları paralıyor terk ettirir yurdunu

Hasta edip yaralıyor unutturur derdini

Başkasına kiralıyor sefilini, merdini

Para, para, para, para onsuz bir şey alınmaz

Uğrunda insanlık ara, hiçbir yerde bulunmaz

Sahip olan zengin olur kalmaz hiçbir kusuru

Ona her şey mümkün olur satın alır Mısırı

Sevgi, saygı engin olur herkes onun esiri

Para, para, para, para onsuz bir şey alınmaz

Olmayanın yüzü kara, ona rahmet olunmaz 

Yerden eder, yârden eder hasret gönlünü yakar

Ülkeden diyardan eder herkes yoluna bakar

Utanmaktan, ardan eder her türlü role sokar

Para, para, para, para onsuz bir şey alınmaz

Bulamayan düşer zora kapısı hiç çalınmaz

Bu dünyayı zindan eder herkes alır alaya

Hem sıhhat hem candan eder başın girer belaya

Neyin varsa ondan eder, hasret kılar sılaya

Para, para, para, para onsuz bir şey alınmaz

Bulamayan bir fukara izine de salınmaz

Para denen bu mereti herkes sever sırayla

Putlaştıranlar türedi onu yazı turayla 

İnsanın şanı, şöhreti ölçülüyor parayla

Para, para, para, para onsuz bir şey alınmaz

Düşünürken kara kara, uykuya da dalınmaz

Mikdadi der yandı sinem beni gelip bulmuyor

Paraya hiç vermem önem ancak onsuz olmuyor

Hem cennet hem de cehennem  hiç nedensiz dolmuyor

Para, para, para, para onsuz bir şey alınmaz

Buna kafa yora yora akıllı da kalınmaz! 

Şair Mikdat Bal', 'Para, para, para. İnsanları paralıyor terk ettirir yurdunu Hasta edip yaralıyor unutturur derdini Başkasına kiralıyor sefilini, merdini Para...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/para-para-para-para-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamahın yok devası', 'tamahin-yok-devasi-mikdat-bal-qotm8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tamahın yok devası

Mal sevgisi,hevesi

Nefsin arzu, hevası

Seni yakar kül eder

Zenginlerin övgüsü

Nüfuzu ya mevkisi

Seni dünya sevgisi

Başkasına kul eder

Örnek alma zengini

Aşamazsın engini

Bulmaz isen dengini

Sen tül isen çul eder

Zengin herşey yaptırır

El eteği öptürür

Doğru yoldan saptırır

Kompleksin kabul eder

Seni yanında tutar

Ona gereğin kadar

İşin bitince atar

Seni geçmez pul eder

Tayin eder keseni

Eksik verir hisseni

Bir nokta çıkar,seni

Cümlede virgül eder

İçer senin kanını

Gevretir imanını

Alır senin canını

Hanımını dul eder

Gayem değil eğlenmek

Sizlere bir şey vermek

Kim isterse öğrenmek

Herşeyi okul eder

Hoş görünüz Mikdat''ı

Şiir onun muradı

Kim varsa kanaatı

Her bitkiyi gül eder', 'Tamahın yok devası Mal sevgisi,hevesi Nefsin arzu, hevası Seni yakar kül eder Zenginlerin övgüsü Nüfuzu ya mevkisi Seni dünya sevgisi Başkas...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tamahin-yok-devasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Yok Mu', 'kimse-yok-mu-selahattin-olmez-0bdx8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KİMSE  YOK  MU

İsmin senin olsun,Anlamı tüm insanlara uğrasın,

Kimse yok mu diye yollara çıktın,kapıları açtırdın,

Birlikten kuvvet doğar,tüm gönüller sende bileşsin,

Açtığın kapılara,bahtı zengin insanlarla,sevgini verdin,

Lafların  değil,garibanları güldürdü,ağlarken bile gülen gözlerin.

Güneş gibi doğuyorsun,bazen Manisa’da,bazen Çorumda,

Üstünde şemsiye oluyorsun,hasta,fakir çaresiz insanlara,

Renklendiriyorsun dünyalarını,kalpleri kararmış insanların adeta,

Pınar oluyorsun doğadan akıyorsun,sanki kimsesiz yuvalara,

Ilgın,ılgın akıtıyorsun,göz yaşlarını kalbine,bakarken kimsesiz çocuklara.

Nice yüzler güldürmek için koşarsın,Kah Adana’ya,kah,Kastamonu’ya

Artık yeter demedin,hep koşturdun yanını aldığın kardeş insanlarla,

Rayihalar kattın,sefalet içinde yaşayanların çorbalarına…

Kimse yok mu dedin düştün yola,

Lokomotif oldun,taktın tüm yoldaşları ardına, 

Yardım yapmak için yarıştı insanlar,senin programınla,

Ağladılar,güldüler,başladılar hayatın ağırlığını anlamaya.

Minicik öğrenciler bile harçlıklarını verdiler ya

Başladı göz yaşlarım görünmeden, kalbime kan olarak akmaya,,

Gördüğüm çileli tüm insanların hali,gelebilirdi benimde başıma

Her şey insanlar içindir yaşandıkça varolan bu dünyada,

Ne mutlu acıları mutluluğa dönüştüren,Sevgili İkbal GÜRPINARA.

	06,06,2004

                                                                             Selahattin   ÖLMEZ

	CEYHAN', 'KİMSE  YOK  MU İsmin senin olsun,Anlamı tüm insanlara uğrasın, Kimse yok mu diye yollara çıktın,kapıları açtırdın, Birlikten kuvvet doğar,tü...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kimse-yok-mu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorsun Demektir', 'seviyorsun-demektir-selahattin-olmez-mdirv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEVİYORSUN  DEMEKTİR

Omzuna başını yasladığında

Bir huzur buluyorsan o anda,yaşamında,

Avuçların avuçlarıyla buluştuğunda,

Bir sıcaklık hissediyorsan,damarlarındaki,

Dolaşan kanda.

Ve yıldırımlar çakıyorsa başında,

Seviyorsun demektir onu,

Göz bebeklerine baksanda, bakmasanda.

Ayrı kaldığında zaman çok uzun geliyorsa sana,

Dizlerinde bir titreme oluyorsa yöneldiğinde ona,

Kalbin pır,pır ediyorsa bir anda,

Bir başka heyecan oluyorsa göz kapaklarında,

Kendisine veya resmine baktığında,

Seviyorsun demektir onu,

Göz bebeklerine baksanda bakmasanda.

 İçinde bir özlem duygusu kabarıyorsa bir anda,

Gitmek istiyorsa ayakların ona  doğru koşa,koşa,

İsimler takıyorsan havaya baktığında aya ve yıldızlara,

Haber getirsin diye türküler yakıyorsan dalgalara,

Ve,

Haykırıyorsan adını kırlara,bayırlara.

Seviyorsun demektir onu,

Başını omzuna yaslasanda yaslamasanda…..

                                                 01,MAYIS:2004

				Nikah yıldönümümüz. 25.Yıl', 'SEVİYORSUN  DEMEKTİR Omzuna başını yasladığında Bir huzur buluyorsan o anda,yaşamında, Avuçların avuçlarıyla buluştuğunda, Bir sıcaklık hiss...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seviyorsun-demektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuhaf Şey', 'tuhaf-sey-mikdat-bal-mqt2b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nefsine kul olup yoldan sapanlar

Başkasına nasıhatı tuhaf şey

Akıl almaz kötülükler yapanlar

Başkasına nasıhatı tuhaf şey

Namaz kılmaz kalbim temiz der durur

Oruç tutmaz her yıl oruç yer durur

Tepeden tırnağa kadar şer durur

Kalbim temiz söylemesi tuhaf şey

Konuşunca herkes sözünü dinler

O haline güler şeytanlar,cinler

Bir iyilik görse mutlaka önler

Cömertlikten bahsetmesi tuhaf şey

İçki içer gider karıyı döver

Kötülüğü yapar şeytanı söver

Mu’mine yobaz der, tağutu över

Müslümanım söylemesi tuhaf şey

Her hayırda mazereti var onun

İyiliğe her an kalbi dar onun

Bir gün gelir ayağı kayar onun

Doğru yoldayım demesi tuhaf şey

Mikdat der ki onun haline şaştım

Bir gün tövbe eder diye uğraştım

Sabrım bitti yanından uzaklaştım

Bana kızmış, gönül koymuş tuhaf şey', 'Nefsine kul olup yoldan sapanlar Başkasına nasıhatı tuhaf şey Akıl almaz kötülükler yapanlar Başkasına nasıhatı tuhaf şey Namaz kılmaz kalbi...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tuhaf-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Şiir Şair*', 'siir-sair-adulera-ayza-53em3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir şair yazamaz ama

Şair şiir yazar

Şair adamı bir tek şey bozar

Karşılıksız sevdalar

Şiir içki içmez şiir gezmez 

Şiir ezberlemez

Şair içer şair gezer

Şair ezberler

Şiiri değil

Seni ezberler seni içer seni gezer

Şiir okumaz

Şair okur

Şair okunmaz

Şiir okunur

Şiir görmez

Şair görür

Şiir de

Şair de ölmez', 'Şiir şair yazamaz ama Şair şiir yazar Şair adamı bir tek şey bozar Karşılıksız sevdalar Şiir içki içmez şiir gezmez  Şiir ezberlemez Şair iç...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/siir-sair-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gilindirede Akşam', 'gilindirede-aksam-selahattin-olmez-dhjxp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GİLİNDİREDE AKŞAM 

Bir cumartesi akşamı,oturuyorum Gilindirede

Sırtımı yaslamışım bir harnup ağacının gövdesine,

Balıkçı iskelesinin biraz ötesindeki tepede.

 Ruhum Akdeniz de

Hayallerim ufukların ötesindeki çizgide.

Mavi atlas serilmiş sanki engin denize,

Yeşilin tonları düşüyor izdüşümü,tam tersine,

Akdenizin serin sularının derinliklerine,

Sevişiyor yeşiller ve mavi delicesine,

Yakamozlar şahit oluyor onların sevişmelerine,

Balıklar düğün yapıyorlar,

Sevdalanmış aşıklarla birlikte,

Sarı,siyah,yeşil,mavi, ebruli pembe,

Gül kurusu renkli giysilerle; Akdeniz de

Güneş altından tepsi gibi olmuş,dalıyor Akdenize,

Yer ve gök birleşiyor adeta,Bakırlaşmış rengiyle.

İnsan nasıl özlerse sevdiğini,bir süre görmeyince,

Sanki güneşte sevdalanmıştı,buluştuğu Akdenize.







Gökte ay beliriyor,Keçi boynuzu gibi,hilal şeklinde,

Keçi boynuzları ise kıskanarak benziyor ayın haline,

Bal katıyorlar adeta aşıkların sevgilerine

Sevdalarını ölümsüzleştiriyor,mitolojik lezzetiyle,

Mavi atlas üstünde,Ufukların Bakırımsı döşeğinde.

Bir cumartesi akşamı oturuyorum Gilindirede,

Gözlerim Akdenizde,Akdeniz gecelerinde,

Mavi atlas pembe döşek oluyor artık,

Gecenin ilerleyen saatlerinde.

Sevdalanmıştım bir kere ben Akdenize,

Serin sularıyla geceler boyunca

Akdenizle sevişsem de,sevişmesem de.

Gözlerim ufuk çizgilerinin ötesinde,

Ruhum ve hayallerim akdenizde

,Ömrüm bitecektir benim Akdeniz sevgisiyle,

Bu günün bittiği gibi Gilindirede ki İskelede..

,                                                        15,mayıs.2004', 'GİLİNDİREDE AKŞAM  Bir cumartesi akşamı,oturuyorum Gilindirede Sırtımı yaslamışım bir harnup ağacının gövdesine, Balıkçı iskelesinin biraz ö...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gilindirede-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin Yüreğime', 'hosgeldin-yuregime-nurten-altinok-f9c17', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben düne bakmamayı öğrettim kendime 

yarınlarıma acı maya olmasın diye 

süzdüm de tüm anıları dağarcığımda 

gül kokulularını taktım göğsüme broş diye 

bu kan_yangını nereden geliyor sanıyorsun 

dikenlerini unutmuşum da  koparmaya gülüm

sımsıkı kapatmışım avuçlarımı / kaçma diye

yüreğime vuruyor sancısı şimdi

yüreğime mavisi

ben düne bakmamayı bu yüzden 

ezberlettim kendime 

-ki miladımdın 

senden önce… 

.....hoş geldin can 

..........hoş geldin kan_çiçeğim 

...............hoş geldin yüreğime 

gitmeyeceksin 

/değil mi..!', 'ben düne bakmamayı öğrettim kendime  yarınlarıma acı maya olmasın diye  süzdüm de tüm anıları dağarcığımda  gül kokulularını taktım göğsüme ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hosgeldin-yuregime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gölge Oyunu**', 'golge-oyunu-hulya-simsek-x6yp3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi musluğu açsam can akar tenden içeri

Mumu söndürür efsunlu bir nefes de

Ölgün yüzlü bir dervişçesine doğrulur düş.

Ölüm sonsuz uykusunda Sen uyan

Bak! 

Çıkageldi! 

Her zamankinden daha mağrur aydınlık

Tinsiz bir sokuluşu var

Anlak aralığından 

Değdiği her nesne utandı çıplaklığından

Özüne mahpus bir ordu oldu etrafım

Hangi musluğu açsam akarsın tenden içeri

Çakmak gözlerindeki yalaz tutuşturur da geceyi

Saklanmış çocukluğum sobelenir

Sen yine efsunlu nefesinle yanımda…

Bilirsin 

Camlardan süzülen rüzgârın sesini

Çocuk çığlığı sanırdım ben

Herkes kadar yalnızken 

Herkesten çok korkardım

Sen leylili kadın! 

Sarıldığım günden beri

Kollarımda uyursun

Sahipsiz bir sözcüktür adın

Uyan ve bak! 

Büyüttüğün çocuğa

Eskisi gibi değil artık gölge oyunum

Zafer naralarımın süsüydü

İki parmağım

Şimdi bir tavşanın kulakları…

20.o6.2oo5 /o1:47/İst.', 'Hangi musluğu açsam can akar tenden içeri Mumu söndürür efsunlu bir nefes de Ölgün yüzlü bir dervişçesine doğrulur düş. Ölüm sonsuz uykusund...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/golge-oyunu-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara Dumani', 'sigara-dumani-ulya-erkman-k4hel', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gorseler 

Ufukta bir duman

Derler 

Gelen bir gemi var

Baksalar 

yamaclara kivrilan dimanlara

Derler 

Giden bir tren var

Aman derler 

Sezince uzaklarda

Bir duman

Ormanda yangin var

Sormazlar

Ya nedir su tuten elinde

Sanirlar

Sigaramdir yanan

Sorsalar

Derdim onlara

Dostlar bagrimindir bu duman', 'Gorseler  Ufukta bir duman Derler  Gelen bir gemi var Baksalar  yamaclara kivrilan dimanlara Derler  Giden bir tren var Aman derler  Sezince...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sigara-dumani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silahşörler', 'silahsorler-suheyl-turkoglu-s97rt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Savaş meydanı,

Gibi beynim,

Kavramlar,

Baş köşeye,

Oturmanın,

Savaşını veriyor.

''Ben çarparım,

İçleri ısıtıp,

Kalbe akarım,

Mantığı rafa koyarım,

Bir bakışa,

Hayat yakarım.''

Diyor aşk.

Sevgi,

''Her yerde,

Yeşeririm,

Çığ gibi büyür,

Gönülleri fethederim,

Her çağıranın,

Ayağına giderim.''

Kılıcını sallıyor.

Arzu,

Manyak,

Bencil,

Biraz da sapık,

Gerçekleri görmüyor,

Her isteğine,

Normalmiş gibi,

Hayal kuruyor.

Koca sevda,

Döğüşe katılmıyor,

Saman alevi aşk,

Pamuk ipliği sevgi,

Değişken arzu,

Hepsi,

Tutkunun evlatları.

Birbirine girmiş,

Silahşörler.

İçimde fırtınalar,

Ne yapacağımı,

Bilmiyorum.

Evlat kavgası gibi.', 'Savaş meydanı, Gibi beynim, Kavramlar, Baş köşeye, Oturmanın, Savaşını veriyor. ''Ben çarparım, İçleri ısıtıp, Kalbe akarım, Mantığı rafa koy...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/silahsorler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleğim', 'melegim-suheyl-turkoglu-rkz7d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yoksun ya,

Hayallerim,

Arkandan ağlıyor.

Yerlerde sürünüyor,

Fantazilerim.

Ya bir eksik,

Ya da fazla,

Oturmuyor düşünceler,

Doğrular kırılıyor,

Eğriler düzeliyor,

Zayıf kaldım,

Savaşamıyorum,

Ordulaşmış,

Hata karıncaları,

Beynimi kemiriyor.

Unut söylediklerimi,

Yaşlılığıma ver,

Yeniden oku,

Aşk mektuplarımı,

Bak onlar ne diyor.', 'Yoksun ya, Hayallerim, Arkandan ağlıyor. Yerlerde sürünüyor, Fantazilerim. Ya bir eksik, Ya da fazla, Oturmuyor düşünceler, Doğrular kırılıy...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/melegim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıl Dönümü', 'yil-donumu-selahattin-olmez-2lej5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YILDÖNÜMÜ

     

Yirmi sekiz yıl önce bu gün,

Açık havada yapılıyor bir düğün,

Dünyanın en güzel kızı oluyor gelin,

Benim oluyor gelin,altında yıldızların..

Beyazlar içinde olmuşsun sanki bir melek,

Mümkün mü sana hayranlığımı gizleyebilmek,, 

Olur mu hiç  olur mu,seni özlememek,

Ellerin ellerimde ömüre,ömür eklememek

Sarayımın sultanı oldun her zaman,

Hiçbir sıkıntıda demedin aman,

El salladın evden her çıkışta ardımdan,

Duacıyım bende,bizi, ayırmasın mevlamdan..

Yirmi sekiz yıl nasıl geçti bilinmezki aradan,

Çocuklarımız doğdu,büyüdü,uçtu yuvadan,

Mutluluğum daim olsun,dileğimiz yaradandan,

Bir zerrecik eksilmesin,benim sana olan sevdamdan.

Ve hala o günkü şarkıyı dinliyor kulaklarım,

Hala aynı sevgiyle seni ve sevgini kucaklarım,

Saçlarımda bu kadar çoğalsa da aklarım,

Sevgini kalbimin an derininde sakalarım.

					06.Haziran.2004', 'YILDÖNÜMÜ       Yirmi sekiz yıl önce bu gün, Açık havada yapılıyor bir düğün, Dünyanın en güzel kızı oluyor gelin, Benim oluyor gelin,altınd...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yil-donumu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimi Koydum Orta Yere', 'kalbimi-koydum-orta-yere-selahattin-olmez-2bd2l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KALBİMİ KOYDUM ORTA YERE

Ben kalbimi koydum orta yere,

Bir yanımda sen,bir yanımda senin sevgin.

Arkamda dostlarım,önümde AKDENİZ’im

Ömrümü uzatır benim,

Akdeniz’in dalgaları ve senin sevgin.

Ben kalbimi koydum orta yere,

Sol yanımda eşim,sağımda çocuklarım,

Arkamda sevdiklerim,önümde Akdeniz’in,

Ömrüme ömür katıyor benim,

Eşim,çocuklarım,sevdiklerim,

Engin görünüşüyle Akdeniz’im

Ben kalbimi koydum orta yere,

Sağımda İskenderun,Sol yanımda Ceyhan’ım,

Arkamda AMANOS dağları,

Önümde Akdeniz’im.

İncisidir gerdanında sevdiğim varlıklarım

Doyar koynunda barınan,aç,yoksul,sefil insanlarım.

Ben başka diyarlarda mutluluk mu ararım,

Her derdimi sana anlatır senden medet umarım,

Seninle ağlasam da,yine senin ile gülerim.,

Senin kıyılarında hayatıma devam ederim,

Bir seni,bir de senin dalgalarını severim,

En sana sevdalanmışım bir kere,

Başka ne söyleyeyim,neler diyeyim…

					06,06,2004', 'KALBİMİ KOYDUM ORTA YERE Ben kalbimi koydum orta yere, Bir yanımda sen,bir yanımda senin sevgin. Arkamda dostlarım,önümde AKDENİZ’im Ömrümü ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kalbimi-koydum-orta-yere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Ve Sevgi', 'gul-ve-sevgi-selahattin-olmez-kciug', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÜL  VE SEVGİ

Sevgini zamanında vermelisin güle,

Bekleyemez gül sevgiyi,ağlasan bile

Hissetmez ise sevgini, dalına dokunduğunda,

Solar gider  o, hayatın boşluğunda.

Gül sevgiyi hissetmeli dalında,

Yoksa solar gider,bülbüllere yalvara  yakara,

Gülde kırmızılık olamaz ki, mısralar için

Gül sevgisiz kalırsa,kokusun vermez,

Bana sana ve uzaklardaki insanlara.

Sevgi bir damla gibi,

Gonca güle damlarsa,

Bülbül gül dalında,ne kadar çok ağlarsa,

Analar yavrusuna doya,doya sarılsa,

Sevgi o zaman anlaşılır,

Sevgiyi karşılıklı bilenler varsa….

                                                        01,05,2004', 'GÜL  VE SEVGİ Sevgini zamanında vermelisin güle, Bekleyemez gül sevgiyi,ağlasan bile Hissetmez ise sevgini, dalına dokunduğunda, Solar gider...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gul-ve-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdenizi Yaşamak', 'akdenizi-yasamak-selahattin-olmez-th4vj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AKDENİZİ  YAŞAMAK

     

Gök yüzü açık mavi,sanki şemsiyedir Akdeniz’e,

Akdeniz; gök yüzü mazisiyle bir başka güler yüzlere,

Aynasıdır Akdeniz arz-ı alemin  görüntülerle,

İyiyi,kötüyü,güzeli,güzellikleri yansıtırken bizlere.

Toroslar yeşile bürünmüş,zümrüt gibi çamlarla,

Bazı yerler geline dönmüş,açılmış zambaklarıyla,

Gelincikler açmış,dönmüş sanki gelinin belindeki kuşağa,

Akdeniz kıyısında bir çizgi gibi,uzayıp uzadıkça.

Sanki vurmuş torosların şavk-ı,rengarenk Akdeniz’e,

Mavinin dansı başlamış,doğadaki renklerin cümlesiyle,

Bunu görürde nasıl yaşamaz insan,doğanın büyüsüyle,

Gözler Akdeniz’e dönmez mi,mutluluk duygularının özlemiyle..

Akdeniz’i tepeden seyretmek bir başka hoştur,

O bir aynadır,görüntüsü gerçek,hayali boştur,

Yeşil,mavi,ebruli,kızıl,sarı bütün renkler sarhoştur,

Akdeniz’i akşam vakti,gün batımında yaşamak hoştur…

							15,07,2004', 'AKDENİZİ  YAŞAMAK       Gök yüzü açık mavi,sanki şemsiyedir Akdeniz’e, Akdeniz; gök yüzü mazisiyle bir başka güler yüzlere, Aynasıdır Akdeni...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/akdenizi-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suların Merkezi Akdeniz', 'sularin-merkezi-akdeniz-selahattin-olmez-lahny', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SULARIN MERKEZİ AKDENİZ

          

Sen merkezsin, tüm sular sana  koşar

Dalgaların kollarını açmış,tüm suları kucaklar.

Tuzlu suyla,tatlısının buluşması bin hasret kokar,

Sanki ikisi, yıllardır çok özlem çekmiş,çok eski dostlar….

Sen sadece suları çekmezsin kıyılarına Akdeniz’im,

İnsanlığı kucaklarsın,yaşatırsın onları dört mevsim.

Yazın yananları serinletirsin,serin suların olur nevresim,

Kışın donanları kucaklarsın,ısıtırsın,dersin hemşerim.

Kıyılarının; anasıdır,yuvasıdır,sanki tüm güzelliklerin,

Yeşili,çayırı,pamuğu,inciri,çok türlüdür meyvelerin.

Mutluluğa ilk adım attığı yerdir kıyıların,bir çok sevgililerin.

Gururu olmuşsun sen uğruna savaş veren tüm medeniyetlerin…

Kıyılarında ilerlerken,yılan kavi yollarda,çok mutlu,

Sanma ki bu insanlar,sevgililer,tarihçiler seni unuttu.

El ele verdi insanlık,seninle yaşamanın yolunu tuttu,

Gerçekleri gördü,sende yaşadı,hayalleri unuttu…

Yılan kavi yollar tespih ipliği gibi gider kıyılarında,

Taneleri olmuş beldeler üzerinde,şirin mi şirin diyarlarında,

Sanki şehirler açılmış güle dönmüşler,gonca gibi kenarlarında,

Yeni yeşeren goncaların da çok,yeşeren gül gibi dallarında.

						16,08,2004', 'SULARIN MERKEZİ AKDENİZ            Sen merkezsin, tüm sular sana  koşar Dalgaların kollarını açmış,tüm suları kucaklar. Tuzlu suyla,tatlısın...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sularin-merkezi-akdeniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdenizi Tespihat', 'akdenizi-tespihat-selahattin-olmez-ijyh4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'AKDENİZİ TESPİHAT

         

Samandağ,Arsuz,İskenderun,Payas ile başlar körfezler

Bu yerlere insanlar geçinmeye gelirler.

Yumurtalık,Karataş,Mersin birbirini izlerler,

Pamuk eker,portakal yetiştirir,sebze meyve verirler.

Alata,Erdemli, Kız kalesi,Silifke sırasıyla giderler,

Buralardan geçmiş yıllar önce ne medeniyetler.

Cennet,Cehennem,Kum kuyu görülmeye değecek yerler,

Akdeniz için bulunmaz pahadadır bir çok değerler.

Taş ucu,Aydıncık,Boz yazı,Anamur muazzam yerler,

Güneşiyle deniziyle insanları mutlu ederler.

Bu bölgede insanlar muz ve çilek yetiştirirler,

Lezzetiyle tüm dünyaya namın  sürerler.

Gazi Paşa,Alanya,Manavgat yaşanan yerler,

Dünyanın dört bir yanından turist çekerler.

Denizine sanki her mevsim adam ekerler,

Deniz kum,tarih iç içe,medeniyet döşerler.

Side,Antalya,Bel dibi bin ömre bedel,

Yerli yabancı turiste hizmet ederler.

Denizin dibinde sanki gül bitirirler,

Memlekete kucaklarla sevgi ve döviz getirirler.

Kemer,Finike,derme,Kaş güzellik bahşederler,

Noel babasıyla dünyada hüküm sürerler.

Yat limanlarına bin bir ülkeden bayrak çekerler,

Gülleri güzellikleri, gül yüzleri güldürürler,









Kalkan,Fethiye,Ölü Denizinde insanlar yeniden doğar,

Muğla,Marmaris,Dalaman Şifa verirler.

Çam balları,gün ışığı,kuru hava,sanki nefesler,

İnsanlar bu beldelerde, kalmak isterler.

Datça,Milas, bodrum isanlığa hayat verirler,

Allah’ın bir lütfü’dür,Akdenize bu yerler

Hayat için ekmek gibi,su gibi,yüce değerler,

Daha nice küçük,küçük yerler,koylar beldeler.

Dedim ya, Akdeniz’im.kıyılarında uzanan yollar,

Tespih ipliği gibidirler,Kopmazlar kırılmazlar.

Tane olmuş ona,saydığımız bu şehirler,beldeler,

Tespihat çeker insanlar,yıllar boyunca AKDENİZ derler,

						01,07,2004', 'AKDENİZİ TESPİHAT           Samandağ,Arsuz,İskenderun,Payas ile başlar körfezler Bu yerlere insanlar geçinmeye gelirler. Yumurtalık,Karataş,...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/akdenizi-tespihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Diye', 'sen-diye-selahattin-olmez-953i4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEN DİYE

Gök yüzüne çıkmak,

Güneşi kucaklamak istiyorum.

Isınmak istiyorum sımsıcak,

Bulutların üzerine uzanarak,

Güneşe sen diye sarılarak.

Gök yüzüne çıkmak istiyorum,

Güneşle arkadaş olmak,

İliklerime kadar ısınmak istiyorum.,

BBulutlardan oluşmuuş bir yatak,   

Ve oyatakta güneşi,sen diye kucaklayarak.

Yükseklere çıkmak istiyorum,

Gezegenler arasında seni bularak,

Sonsuzluğa yürümek istiyorum.

Gök yüzüyle dost,yıldızlarla arkadaş olmak,

Ellerin ellerimde,mutluluğu bularak 

Yaşamak istiyorum,

Tüm kainatla dost kalarak...

                     30,08,2004', 'SEN DİYE Gök yüzüne çıkmak, Güneşi kucaklamak istiyorum. Isınmak istiyorum sımsıcak, Bulutların üzerine uzanarak, Güneşe sen diye sarılarak....', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-diye-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarıma', 'dostlarima-selahattin-olmez-gv7tb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DOSTLARIMA

Farz edin ki,bir rüzgardım,

Esip geçtim hayatınızdan.

Ya da bir yağmur oldum yağdım,

Sel oldum,akıp gittim sokaklarınızdan.

Buluştum ırmaklarla,ummanlara eriştim,

Toprak emdi beni,alıverdi aranızdan,

Kaybolup gittim..

Belkide bir rüya oldum,kimileriniz için,

Uyuduk hep beraber,

Uyandığınızda,baktınız ki ben yoktum,

Hatırlayın o zaman beni,güzel olsun anılarım,

Çünkü bunlar size yazdığın son satırlarım..

Ve sizler beni güzelliklerimle anımsayın,

Gülen yüzümü hala odanızda varsayın,

Ben hep mutlu olduğunuz zamanlar geleyim aklınıza,

Beraberce paylaştığımız sevinçler ve neşeler ile.

Elemli anılar,acılar ve kederler gelmesin yadınıza.

Belki kapınızı çalarak,geleceğimizi düşüneceksiniz,

Şakayı,süprizler yapmayı sevdiğimizbilirsiniz,

O nedenle bekleyebilirsiniz.

Ama hayır,hayır,hayır,

Bu size son süprizim olacak,

Acılar,elemler,hazlar,mutluluklar son bulacak.

ve,

Sizlere elveda diyorum,

Hakkınızı helal etmenizi diliyorum,

İşte gidiyorum

Beni hep güzel anılarımla hatırlayın,

Diyorum,Sizleri çok seviyorum......

                                         31,08,2001', 'DOSTLARIMA Farz edin ki,bir rüzgardım, Esip geçtim hayatınızdan. Ya da bir yağmur oldum yağdım, Sel oldum,akıp gittim sokaklarınızdan. Buluş...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dostlarima-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kültür Sarayı', 'kultur-sarayi-selahattin-olmez-1pk6m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KÜLTÜR SARAYI

İnsanlara hizmet için,yarışı ön planda tutmayı,

Gelecek çocuklarındır diye,onları şefkatle kucaklamayı,

Sunarak teknolojiyi,ilimi,irfanı,bilgiyi,bilgisayarı

Hazine oldun sitemize,İsdemire sen,KÜLTÜR SARAYI.

Çocuklar coşarak dolduruyor,dört bir yandan masayı,

Unutuyorlar çalışırken,İnternette,derdi,tasayı.

Bin bir çeşitten oluşmuş kitaplar okumayı

Bilgi birikimiyle güçleniyor,tüm gençler sende KÜLTÜR SARAYI…

Türlü etkinlikler düzenlenecek güzide salonlarında,

Herkes ortaya dökecek eserlerini,kendi alanlarında,

Ufukları daha da genişleyecek insanların,öz dünyalarında,

Buluşacak her türlü insan,ilim,irfan yuvası KÜLTÜR SARAYINDA..

Sanatlar harman olacak,sanatkarlar kendin bulacak,

Serilecek dizi,dizi eserler herkesçe okunacak,

Tanışacak insanlar,bir birileriyle dostluklar kurulacak,

Kültür Sarayı İsdemirin haklı gururu,onuru olacak.

Sarayları saray yapan,içindeki hazinedir,gizemdir,

İnsanları bir araya toplayan,özündeki özlemdir,

Sarayı ortaya koyan,varlığını keşfedecek gözlemdir,

Kültür sarayını İsdemire kazandıran:Ne büyük bir insandır.

Şiir,Roman ,Makale,Tiyatro ve ,Sinema,

Daha ne sanatlar var,Müzik, Resim,Bale gibi sırada.

Buluşacak isdemirli,Birlik için,bekli her gün burada,

Geleceğin parlak temelleri atılacak,Bu KÜLTÜR SARAYINDA…

                                                  SELAHATTİN ÖLMEZ

                                                     03,11,2004-11-04', 'KÜLTÜR SARAYI İnsanlara hizmet için,yarışı ön planda tutmayı, Gelecek çocuklarındır diye,onları şefkatle kucaklamayı, Sunarak teknolojiyi,il...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kultur-sarayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Bülbül', 'asik-bulbul-suheyl-turkoglu-46c8u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güle aşık,

Olan bülbül,

Ötüşünle,

Aşkı yazdın.

Hep katlandın,

Dikenlere,

Seranatla,

Destan yazdın.

Karanfilin,

Sitemine,

Aldırmadın,

Aşk yaşadın.

Kokusuna,

Mest olduğun, 

Yasemini,

Kovaladın.

Fala bakan,

Papatyaya,

Gelinciğe,

Aşkı yazdın.', 'Güle aşık, Olan bülbül, Ötüşünle, Aşkı yazdın. Hep katlandın, Dikenlere, Seranatla, Destan yazdın. Karanfilin, Sitemine, Aldırmadın, Aşk yaş...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asik-bulbul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirle konuşurum', 'siirle-konusurum-mikdat-bal-3non3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiirle konuşurum 

Bu bende meziyettir 

Bilmeyenler yazarsa 

Boşuna eziyettir 

Şairlik kolay değil 

Ciddi bir vaziyettir 

Mesela bir kelime 

Desek ki ''Çaykaralı'' 

Kelimeler bitince 

Uydururum kör Ali 

Öyle devam ederim 

Kolay olur, zor Ali 

Ondan sonra eklerim 

Mesela ne der Ali 

O biter arkasından 

Söylerim ne yer Ali 

Bu böyle devam eder 

Başka olur her Ali 

Şiirim uzun olur 

Hep altalta sıralı 

İşte bu ustalıktır 

Şairlikte sır Ali 

Bu arada sorarım 

Kaç lira mısır Ali 

Bu sadece bir örnek 

Daha neler var Ali 

Eğer benden sorarsan 

Benim sinem yaralı 

Çok şükür sen iyisin 

Dünya sana yâr Ali 

Anladınız mi şimdi 

Her şeyin var kuralı 

Buna eklenebilir 

Saatini kur Ali 

Bu böyle devam eder 

Ne istersen sor Ali 

Yazmam şundan dolayı 

Gerçekleri gör Ali', 'Şiirle konuşurum  Bu bende meziyettir  Bilmeyenler yazarsa  Boşuna eziyettir  Şairlik kolay değil  Ciddi bir vaziyettir  Mesela bir kelime  ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/siirle-konusurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenine Sevgi Gönder', 'ogretmenine-sevgi-gonder-selahattin-olmez-75y1h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖĞRETMENİNE SEVGİ GÖNDER

Bu gün bir deste çiçek,veya bir tek gül al eline,

Kırmızı olun,sarı olsun, pembe,beyaz ebruli olun,

Rengi fark etmez,yeter ki içinde sevgin bulunsun,

Sevgini göster öğretmenine,bu gün çok mutlu olsun…

Bu gün bir deste pembe karanfille git göster sevgini,

Çünkü yıllar önce aldın sen ondan,hayat çizgini,

Yaşam boyu sana elzem olan  sevgiyi ve bilgiyi,

Bu gün ne olur git,mutlu et eski öğretmenlerini.

Öğretmenin karşılık beklemeden verdi sana her şeyi,

Bu vatan bizim dedi,dolaştı dört bir köşeyi,

Yaşayamadı beklide doyasıya mutluluğu,neşeyi,

Yine de biliyorum ki òldu onun öğrencisi,her şeyi.

Bir gül al eline bugün,ara bul öğretmeninin evini,

En samimi duygularınla öp,bir kez daha öğretmeninin elini,

Sana verdiği emeklerin,sen değil o bilir kıymetini,

Öperken elini, bakarsan gözlerine,anlarsın onun öğretmenliğini.

Öğretmen nefer gibidir,memleketi bütün vatandır,

Bolu’da,Seben’de,Marmaris’te,Edirne’de Ağrıda da koşandır,

Yaşadıkları,gördükleri,tükettiği ömrü,sevgileri destandır,

Bir değil,binlerce gülü karanfili,hak eden,en kutsal insandır.

Öretmen Bolu’da Seben’de kara denizde ormancı gibi,

Akdeniz’de,Ege’de,Güney Doğuda sanki bir çiftçi,

İç ana doluda,Doğuda,Kars’ta Erzurum’da besici,

En önemli görevi bu vatanın her şeyinde öncü ve eğitici.

Benliğini kor orta yere,çırpınır yetişsin diye öğrencisi,

Bir gün karşısına çıkınca eski bir,doktoru,mühendisi,bestecisi,

Avukatı,Hakimi,Savcısı,hele öğretmen olan eski bir öğrencisi,

Kalmaz öğretmenin hayattan başka bir isteği,başka bir beklentisi.

Kendi çocuğu yoktur,çocukları vardır daima,

Öğrenci eker o her zaman gönlündekini tarlasına

Yetiştirir onları tıpkı buğday taneleri gibi,başaklarında,

Hasattaki çiftçi gibi sevinir,görünce onları bir işlerinin başında.

Hepinizin günü kutlu olsun,sevgili öğretmenlerim,

Yaşayanların tamamı,uzatın elinizden öpeyim,

Hakkın rahmetine kavuşanlar,sizlere hatim edeyim

Gönlünüz dopdolu,,Kabrinizin cennet olduğunu bileyim..

Bu gün bir deste gül,karanfiller alalım elimize,

Yaşlı genç,erkek kadın,büyük küçük hep birlikte,

Rengi fark etmez,kırmızı sarı,kadife pembe 

Gidelim en yakınımızdaki öğretmenlerimizin evine.

    24,Kasım,2004-

					Selahattin  ÖLMEZ', 'ÖĞRETMENİNE SEVGİ GÖNDER Bu gün bir deste çiçek,veya bir tek gül al eline, Kırmızı olun,sarı olsun, pembe,beyaz ebruli olun, Rengi fark etme...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ogretmenine-sevgi-gonder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadir Gecesi', 'kadir-gecesi-selahattin-olmez-rfe4a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KADİR GECESİ

Ey bu dünyada biçare dolaşan,divane beşer,

Gözlerin kapanmadan ömürler su gibi geçer

Düşün bir kere,var mı dünyada yaşayan hünkar,

Zira Azrail kapına geldiğinde iş işten geçer.

Ey günden güne ömrünün sonuna yaklaşan beşer,

Nefsine dost olup ta yaşayan insan,sonunda şaşar,

Çevrene bakarsan,anlarsın,eskilerden kaç kişi yaşar,

Zira Azrail kapına geldiğinde iş işten geçer.

Uyan ey beşer,gafletten uyan,ömürler geçer,

Uyanır da şaşırmış insanlar,belki kendine döner,

Bu çağrıya kulak verirde hakkın yolunu seçer,

Zira Azrail kapını çaldığında iş işten geçer.

Hakka niyaz edelim,haktan ancak yardım beklenir,

Bu gece çok ulvidir,bu gece insanlar affedilir,

İnsanı insan yapan,hem rabbini,hem resulü sevmektir,

Sevgi dolu kalplerde,Azrail,olsa,olsa melektir.

Bu sözlerim tavsiyedir insanlara,belki dinlenir,

Bizler beşeriz,tövbe edelim,hakça kabul edilir,

Pişmanlık duyup nedim olanlar,cennetle müjdelenir,

Böyle olunca Azrail kapıya gelse de bir gelmese de bir.

                                                         KADİR GECESİ

						2004', 'KADİR GECESİ Ey bu dünyada biçare dolaşan,divane beşer, Gözlerin kapanmadan ömürler su gibi geçer Düşün bir kere,var mı dünyada yaşayan hünk...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kadir-gecesi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-i-shak-ozlu-n69yj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fersah fersah denizin dibinde,

İnci mercan gördüğüm sen.

Gülün kokusunda,bülbülün sesinde,

Yaşattıgım suna boylu sen.

Uğruna dağları delip geçtiğim,

Bir kelamına ağular içtiğim,

Anadan geçip yar diye seçtiğim,

Sen mi bendesin,ben mi sende.

Sen varsın diye mi bende varım.

Yoksa ben mi seni yarattım.

Sen aşkın büyüsünü sundun,

Bense bir efsane yarattım.', 'Fersah fersah denizin dibinde, İnci mercan gördüğüm sen. Gülün kokusunda,bülbülün sesinde, Yaşattıgım suna boylu sen. Uğruna dağları delip g...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/efsane-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babalar', 'babalar-i-shak-ozlu-dbjmt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrım bilmez sevgileri eşittir.

Dogru söyler yaşamları keşiftir.

Yol gösterir hayatları çeşittir,

İleriyi GÖRENLERDİR babalar.

Not:Şiir Perisi grubunun Babalar adlı çalışması için yazılmıştır.', 'Ayrım bilmez sevgileri eşittir. Dogru söyler yaşamları keşiftir. Yol gösterir hayatları çeşittir, İleriyi GÖRENLERDİR babalar. Not:Şiir Peri...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/babalar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Bazı ihtiyarlar!', 'a-bazi-ihtiyarlar-mikdat-bal-wo1sv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalmayınca başka yiyecek nane 

Kılık değiştirir sakal şahane 

Elinden gelmiyor tövbe bahane 

Caminin yolunu tutan ihtiyar 

Camiye girip de geçer ön safa 

Alaylı gözlerle bakar etrafa 

Hiç de değişmedi hala o kafa 

Halkı birbirine katan ihtiyar 

Kim tövbe ederse başımın tacı 

Ancak bu ihtiyar başka bir hacı 

Toplumda oturur konuşur acı 

Ona buna çamur atan ihtiyar 

Eski alışkanlık sivri sözleri 

Neler çevirirdi tutsa dizleri 

Devirir insanı hain gözleri 

Her hayır yoluna yatan ihtiyar 

Bal der büyüklere saygım pek çoktur 

Bunun davranışı görene şoktur 

Yanımda bir zere kıymeti yoktur 

Dinini dünya ya satan ihtiyar

Ozan Mikdadî', 'Kalmayınca başka yiyecek nane  Kılık değiştirir sakal şahane  Elinden gelmiyor tövbe bahane  Caminin yolunu tutan ihtiyar  Camiye girip de g...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/a-bazi-ihtiyarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtar Beni', 'kurtar-beni-huseyin-sigirtmac-hgf44', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yar yüreğim aşkından kül,

Olmadan gel kurtar beni.

Son demimde açan bu gül,

Solmadan gel kurtar beni.

Gönül sensiz tutmaz ayar.

Yerine kimleri koyar.

Yüreğime gamla efkar,

Dolmadan gel kurtar beni.

Hayalin tutkudur yaşar.

Yüreğim aklımı aşar.

Baharımı gelip kışlar,

Almadan gel kurtar beni.

Gel ver elini elime.

Bak perişan son halime.

Hasretin beni ölüme,

Salmadan gel kurtar beni.

Yaş ilerler ağarır saç.

Sanma sevmek günah ve suç.

Sensiz belayı Sığırtmaç,

Bulmadan gel kurtar beni.', 'Yar yüreğim aşkından kül, Olmadan gel kurtar beni. Son demimde açan bu gül, Solmadan gel kurtar beni. Gönül sensiz tutmaz ayar. Yerine kimle...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kurtar-beni-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İnsanız Dedik', 'biz-i-nsaniz-dedik-ozan-ozel-6bwb9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ıslak sokaklarda

kuru adımlarla yürüdük

biz hep tek başına

başımıza ne geleceğini bilmeden

gülmeden büyüdük

ay yanarken

kuytulara sığındık

yüreğimiz üşüdü 

yaz gecelerinde

yıldızlara uzattık ellerimizi

yanmayı göze alarak

ısınmak istedik...

soran olunca da

biz insanız dedik

afedersiniz, hata ettik...', 'ıslak sokaklarda kuru adımlarla yürüdük biz hep tek başına başımıza ne geleceğini bilmeden gülmeden büyüdük ay yanarken kuytulara sığındık y...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biz-insaniz-dedik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnatla Seveceğim', 'i-natla-sevecegim-sahin-erturk-be57p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ne dersen de

Ben,bildiğimi yapacağım

İnatla seveceğim seni

Delice seveceğim seni

Çılgınca seveceğim seni

Adına şölenler düzenleyeceğim

Klipler çekeceğim

Kitaplar çıkaracağım

Dağa,taşa...Köye,kente

Adını yazacağım

Seni tanıyan,tanımayan

Tüm insanlara zorla

İsmini ezberleteceğim

Radyolar,Televizyonlar

Senden bahsedecekler

Medyakolik olup çıkacaksın

Sen ne dersen de

Ben,bildiğimi yapacağım

Bıkmadan,usanmadan

İNATLA SEVECEĞİM SENİ

İNATLA SEVECEĞİM SENİ

(20.06.2005-Yeni)', 'Sen ne dersen de Ben,bildiğimi yapacağım İnatla seveceğim seni Delice seveceğim seni Çılgınca seveceğim seni Adına şölenler düzenleyeceğim K...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/inatla-sevecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Ey Dost', 'neredesin-ey-dost-caglar-asik-zacyf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neredesin ey dost neredesin? 

Gönül bahçemde öten bülbülsün.

Sen ne içten sözlü bir yolcusun.

Gelipte uğrayanlara selam olsun.

Vaktin varsa sende biraz uğra.

Bu gönüldeki, yanan kor bir yara.

Hiç sönmeden yanar durur hep orada.

Dönüpte, hatır soranlara selam olsun.

Kime bu sözüm diye pek düşünürsün.

O kişi sensin ne vefalı, içten bir kimsesin.

Gelipte halimi görenler, kendinede baksın.

Durupta, özüyle dinleyebilenlere selam olsun.

Coşkun akan bir nehir gibidir bu yürekler.

Gürleyip coşkuyla ağlatır bizi hep o sözler.

Ne sendeki nede başkasındaki yürekteki izler.

Dinleyenler bizde hep muradını bulmak ister.

Geldin madem, dur biraz, bırakıp gitme hemen.

Bırak alsın, dilediğince tadına varmak isteyen.

Coştukça coşar, hep çağlar, dost olan gönüller.

Muradını arayan ziyaretçilere gönülden selam olsun.

İstanbul - 17.06.2005', 'Neredesin ey dost neredesin?  Gönül bahçemde öten bülbülsün. Sen ne içten sözlü bir yolcusun. Gelipte uğrayanlara selam olsun. Vaktin varsa ...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neredesin-ey-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Başka Bir Şey', 'bu-baska-bir-sey-hatice-bediroglu-wjxxb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatıma girdiğin andan öncesi yok 

Ne olduğunu anlayamadan 

Birden doluşuverdin her yerime 

Bir hortum gibi çekip aldın beni 

Sanki her şeyi 

Yeniden görüyormuş gibi gözlerim

Ne yapacağımı bilemez bir haldeyim

Birbirine karışmakta elim ayağım 

Sanki hep seninle yaşarmışım 

Sanki ben hep seni sevmişim gibi 

Gözlerim öylesine sevinçle bakıyor ki yaşama

Beş altı yaş gençleşmişim gibi 

Uçarcasına yürüyorum yollarda 

Ama korkuda hiç bırakmıyor peşimi 

Kapanmayan gözlerle sabahlanan gecelerde 

Olumsuz düşünceler oyuyor içimi.

Ya her şey ansızın yarım kalırsa… 

Boğazıma takılan bir lokma gibi 

Çağlayanların arasında susuz kalmak gibi 

Günlerce aç kalıp da önüne konulan 

Çeşit çeşit tatlıları yiyememek gibi 

Rüyanın en güzel yerinde uyanmak 

Uyanıp da hiçbir şeyi görememek gibi 

Kalp krizi geçirirken 

Ellerin ilaca uzanamaması gibi

Öyle bir yara alacak ki kanatlarım 

Gidersen ve ben yalnız kalırsam

Her şey yabancı gelecek bana

Bir çıkmaz sokakta kalakalacağım öylece

Bir daha kanatlarım kalkmayaca 

Ve hep yaşla dolacak yüreğimin gözleri

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Hayatıma girdiğin andan öncesi yok  Ne olduğunu anlayamadan  Birden doluşuverdin her yerime  Bir hortum gibi çekip aldın beni  Sanki her şey...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bu-baska-bir-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut Düşer Yüreğime', 'bir-umut-duser-yuregime-huseyin-erdogan-n90bt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sabah olunca

bir umut düşer yüreğime

belki sesini duyarım diye

gün batınca

hava kararınca

bir hüzün çöker gönlüme

sensizlik kabusum olur

her gece

korkarım düşlerimde

bir gün bu şehrin

sokaklarında caddelerinde

beni göremezsen eğer

sakın hiç üzülme

sevda çeke çeke

ıssız bir köşede

yığılıp kalmıştır de

kendi kendine

inan ki aşkın 

ölüme bile değer

zaten yokluğun

ölümden de beter

           20.05.2005', 'sabah olunca bir umut düşer yüreğime belki sesini duyarım diye gün batınca hava kararınca bir hüzün çöker gönlüme sensizlik kabusum olur her...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-umut-duser-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar-"siz hiç ay aşığında ağladınız mı" Kitabından', 'mezar-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-6s167', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duygularım sarsıyor yaşam yitik sancılı

Baktım baktım terk etti dostları kaldı mezar

Musalla ıssız mahzun ağır hüznü ürkütür

Vedalaşma yok serde ayrılık güden mezar

Ruhumda burkuntular derbeder beden mezar

Doymaz mısın meyyitten bu açlık neden mezar

Nice koç yiğitleri yurdundan eden mezar

Anladım ki her şey boş gelmiyor giden mezar

Kime cennet bahçesi ibrete meydan mezar

Cehenneme çukur kim, cürümler soydun mezar

Gassal c/anı almadan kalbe havf koydun mezar

Açtım bağrım reca''ya  kaç beden kefen mezar

 Pierloti-11.06. 2005', 'Duygularım sarsıyor yaşam yitik sancılı Baktım baktım terk etti dostları kaldı mezar Musalla ıssız mahzun ağır hüznü ürkütür Vedalaşma yok s...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mezar-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Bu Gündür', 'gun-bu-gundur-hadi-onal-bgt8r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kelimelerin güdük

Cümlelerin sırnaşık, kaypak

Olduğu zamanda

Tükürük fayda etmez oğul

Dinsin sızısı ahın

Tut elinden eyvahın

Su fayda etmez oğul

Ateşi kanla söndür

Çare yürek

Gün bu gündür

Ah yerde kalmaz oğul

İnanır buna şeksiz

İnanan her kul

İşte o kul sen

Senin gibi düşünen

Yüzler binler

Tut hakkı

Kaldır yerden

Haydi aslanım 

Uğrun açık ola

Geçmezsen anadan

Geçmezsen yardan

Geçmezsen serden

Kalır yerde 

Gözyaşının ahı

Feryadın  eyvahın

Dinsin sızısı ahın

Tut elinden eyvahın

Su fayda etmez oğul

Ateşi kanla söndür

Çare yürek

Gün bu gündü', 'Kelimelerin güdük Cümlelerin sırnaşık, kaypak Olduğu zamanda Tükürük fayda etmez oğul Dinsin sızısı ahın Tut elinden eyvahın Su fayda etmez ...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gun-bu-gundur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna imiş Meğer', 'bosuna-imis-meger-murat-demir-w1j8g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben ne karakışlar gördüm

Sen yokken

Ne sefaletler yaşadım

Sen tokken

Ben ne çiseler altında kaldım

Dağlara duman çökerken

Boşuna imiş meğer

Gezdiğim kaldırımlar

Boşuna imiş meğer

Senin için

Attığım o adımlar

Keşke, seni görmeden önce,

Beni

Çarpsaymış yıldırımlar', 'Ben ne karakışlar gördüm Sen yokken Ne sefaletler yaşadım Sen tokken Ben ne çiseler altında kaldım Dağlara duman çökerken Boşuna imiş meğer ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bosuna-imis-meger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dev Aşkımızı', 'dev-askimizi-huseyin-pelit-80vmk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cana yakın sesi bedenden yakın

Parlayan dudaklar alev kırmızı

Hesapsız aşkına gel akın akın

Yarınlara götür dev aşkımızı

Dinmeyen sadadır dudaklardadır

Gülmeyen yaradır yanaklardadır

Bir yudum hayattır sokaklardadır

Yarınlara sevdir sev şarkımızı

Bugün olsun yarın çok geç olmadan

Hasretin verdiği süre dolmadan

Sen orda ben burda gönül kırmadan

Sabahlara kadar döv sazımızı

Canım iste senin yoluna herdem

Canım iste kölen olurdum ben

Uzakları yakın edelim herdem

Günaha batalım sev aşkımızı

HÜSEYİN PELİT 

20.06. 2005

 Bestelenmiş şiirlerimi you tube kanalımda dinleyebilirsiniz ...', 'Cana yakın sesi bedenden yakın Parlayan dudaklar alev kırmızı Hesapsız aşkına gel akın akın Yarınlara götür dev aşkımızı Dinmeyen sadadır du...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Pelit']::text[], 8.5, '{"poet":"Hüseyin Pelit","poet_slug":"huseyin-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dev-askimizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün Aydın Vefasız', 'gozun-aydin-vefasiz-murat-demir-119c1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılmam derken asla

Çekip gittin kıyasla

Sana artık yar demem

Bu hırs ile bu yasla

Bir yandan karanlık net

Bir yandan kış kıyamet

Aklım isyan ederken

Kalbim diyordu sabret

Bir yanımda zindanlar

Bir yanımda dağlar var

Ben yandıkça yerime

Hep dağlar ağladılar

Sen bittin artık bende

Çizildin bir kalemde

Bu gönül benim ise

Yerin yok bu alemde

Bir yandan dedim kısmet

Bir yandan çırpındım hep

Ölsem demeyeceğim

Ya medet yar ya medet

Bir yanımda dert bekler

Bir yanımda kalp tekler

Gözün aydın vefasız

Beni öldürecekler', 'Ayrılmam derken asla Çekip gittin kıyasla Sana artık yar demem Bu hırs ile bu yasla Bir yandan karanlık net Bir yandan kış kıyamet Aklım isy...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozun-aydin-vefasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpsiz', 'kalpsiz-ali-hamdi-eray-kwx23', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim sevgim kalbim kadar

Ben güzelleri severim

Gerçek güzelleri.

Ama onlar..

Vefasızlar.

Kalbimide onlar aldılar.', 'Benim sevgim kalbim kadar Ben güzelleri severim Gerçek güzelleri. Ama onlar.. Vefasızlar. Kalbimide onlar aldılar....', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kalpsiz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem Kapısında Aşk', 'cehennem-kapisinda-ask-cenk-aksal-uu0u0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geceleri 

el ayak çekilince

perdelerin arkasından

hayalin çıkar da:

yüzünün:

aydınlık gölgesi düşer,

kaldırımlara...

hüznün yedi rengi,

mavi:

ışıklarla dolaşır,

salına salına...

bir senden yana,

yangınıma..

bir de sensiz 

yalnızlıklarımda...

meçhule gitmiş:

geleceğimin,

sensiz 

tüm yazgıların da,

cehennem kapısıdır

aşk....

......................................

ey umarsız sevdiğim:

güzel aşkımızdan

kalan tek hatıra...

mavi hüzünlerimiz....

.......................................

gider aheste

sevdamız,

salına salına,

cehennem kapısına...

''bütün şiirler aynı başlar benim kitabımda''

''duygularımda aynıdır yaşadığım sevda da''', 'geceleri  el ayak çekilince perdelerin arkasından hayalin çıkar da: yüzünün: aydınlık gölgesi düşer, kaldırımlara... hüznün yedi rengi, mavi...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cehennem-kapisinda-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-ali-hamdi-eray-q2zax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şey vardı,

Sonsuzlukta yaşardı.

Büyüktü doğarken,ölürken küçük,

Anladıda her şey olduğunu,

Yaşadıkça yaşadı.', 'Bir şey vardı, Sonsuzlukta yaşardı. Büyüktü doğarken,ölürken küçük, Anladıda her şey olduğunu, Yaşadıkça yaşadı....', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/umut-179-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Günler', 'ne-gunler-huseyin-pelit-rfgep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamı yok sözlerimin

Bakışı yok gözlerimin

Fermanı yok ki bilimin

Yanıbaşımdan gidişinin

Aklımı baştan alışın

Beni deliye çevirişin

Sonu yok ki bu bitişin

Canımı candan alışın

Ne günler yaşandı

Ne günler gördük yar

En güzel bahardı

Yaşandı bitti yar

Kulağımda yankıları

Gönlümde hatırası

Yüreğimde yaraları

Gönlümde sevdası var', 'Anlamı yok sözlerimin Bakışı yok gözlerimin Fermanı yok ki bilimin Yanıbaşımdan gidişinin Aklımı baştan alışın Beni deliye çevirişin Sonu yo...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Pelit']::text[], 8.5, '{"poet":"Hüseyin Pelit","poet_slug":"huseyin-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-gunler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anı', 'ani-ali-hamdi-eray-93vqi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğimdeki sızı,

Yıllar ötesinde kalan o sevginin.

Gözlerimdeki bakış,

Düşlerden kalan hüzün.', 'Yüreğimdeki sızı, Yıllar ötesinde kalan o sevginin. Gözlerimdeki bakış, Düşlerden kalan hüzün....', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ani-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giyotin', 'giyotin-naime-erlacin-gkul8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'iyi huylu bir yaratığım

bildiğin gibi

hiç kızmam mı sanıyorsun

elbette 

ben de insanım

öfkelenir

kışkırtırım

karışır dip dalgalarım

hele ki kan tutmasın deli yanımı

yeni bir çağ başlatmak

beyin ihtilali ister önce

bilirsin

giyotinler ne için! 

(20 Haziran 2005)', 'iyi huylu bir yaratığım bildiğin gibi hiç kızmam mı sanıyorsun elbette  ben de insanım öfkelenir kışkırtırım karışır dip dalgalarım hele ki ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/giyotin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Mavim', 'benim-mavim-sait-muharrem-say-nc11l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her balık kendi mavisinde yaşar,

Her kabus kendi batağında

Her yırtılışında gökyüzü

Tek bir maviye

Tek bir düşe vurur

Ve kendi mavisinde balık

Kendi batağında kabus

Pişman olur.

(15.02.2001)', 'Her balık kendi mavisinde yaşar, Her kabus kendi batağında Her yırtılışında gökyüzü Tek bir maviye Tek bir düşe vurur Ve kendi mavisinde bal...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benim-mavim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-naime-erlacin-zs35u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayat sürekli bir oyun... 

vazgeçeriz bazen

düşer dekorlar

ışık söner 

kostümler kayıp

bir sessizlik ki ah! 

bir de 

aynası kalır içimizin

ayrılık ve hüzne dairdir her şey

aynaya düşen yalnızlık görüntüsü 

uslanmaz hiç

usanmaz içimizdeki fener

acıyı aydınlatır durmaksızın

yeniden başlayana dek oyun 

(20 Haziran 2005)', 'hayat sürekli bir oyun...  vazgeçeriz bazen düşer dekorlar ışık söner  kostümler kayıp bir sessizlik ki ah!  bir de  aynası kalır içimizin a...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oyun-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-mehmet-sait-simdi-xw1p8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pencereden geçti bugün,

Mutluluklar saçtı bugün,

Enginlere uçtu bugün,

Benim güzel kelebeğim.

Bahçelerde geziyorsun,

Çiçeklere konuyorsun,

Niçin benden kaçıyorsun,

Benim güzel kelebeğim.

Kelebeğim mor kanatlı,

Kanadında neş''e saklı,

Var mı senden daha tatlı? 

Benim güzel kelebeğim...', 'Pencereden geçti bugün, Mutluluklar saçtı bugün, Enginlere uçtu bugün, Benim güzel kelebeğim. Bahçelerde geziyorsun, Çiçeklere konuyorsun, N...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Şimdi']::text[], 8.5, '{"poet":"Mehmet Sait Şimdi","poet_slug":"mehmet-sait-simdi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kelebek-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ayaz...', 'ayaz-naime-erlacin-8gkv9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerinde alevlenir gözlerim

tecellim olursun böyle anlarda

tek tesellim

ucundan tutmasan 

bilmem nasıl kalkardı bu yük

gidersen öleceğimi söyledim mi hiç

hiç yaşanmasın 

dedim mi senden sonra

açık tut hatlarını yüreğinin

ruhumu sıvazlasın elin 

ister sevgili 

ister bir hayal gibi dokun bana

yarı ölüm sayılır çünkü uykular yattığımda

donmaktan beter! 

çek bu zalim ayazı üstümden

en iyi sen bilirsin

(20 Haziran 2005)', 'gözlerinde alevlenir gözlerim tecellim olursun böyle anlarda tek tesellim ucundan tutmasan  bilmem nasıl kalkardı bu yük gidersen öleceğimi ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayaz-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Yaşanan Bir İki Mevsim.', 'seninle-yasanan-bir-i-ki-mevsim-mehmet-sait-simdi-zwbyo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne hasret duyarım ne ağlarım,

Terkedip gidersen eğer sevgilim.

Seninle yaşanan bir iki mevsim,

Yılların hepsine değer sevgilim.

Bu tatlı sevdayı kim ne bilecek,

Gönülde sımsıcak yaşanan gerçek,

Ne bahar isterim ne de bir çiçek,

Güllerin hepsine değer sevgilim.

Ümitle sevgiyle bakan yüzlerin,

Bir ateş misali yakan gözlerin,

Aşk için dilinden akan sözlerin,

Balların hepsine değer sevgilim...', 'Ne hasret duyarım ne ağlarım, Terkedip gidersen eğer sevgilim. Seninle yaşanan bir iki mevsim, Yılların hepsine değer sevgilim. Bu tatlı sev...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Şimdi']::text[], 8.5, '{"poet":"Mehmet Sait Şimdi","poet_slug":"mehmet-sait-simdi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seninle-yasanan-bir-iki-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Öyle ki! ...', 'oyle-ki-naime-erlacin-gwv1c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'alış kendine

sev yüreğindeki ejderi 

adına ''hasret'' dedikleri

her zaman kudurmaz acı

sinsi bir kurt kimi gün 

ağudan beter

okşa başını

bakarsın hükmü geçer

bilirsin

“en çok kalbinden korkar insan” *

ve ayrılık:

“sen burada 

ben orada” 

der durursun 

bir turnusol kağıdıdır acı

alış kedere

alıştır kendini 

dahası

bilmiyorum can 

bir özlem kalır geride 

öyle vahşi

öyle ki! 

…..

(*)    Murathan Mungan

(22 Şubat – 20 Haziran 2005)', 'alış kendine sev yüreğindeki ejderi  adına ''hasret'' dedikleri her zaman kudurmaz acı sinsi bir kurt kimi gün  ağudan beter okşa başını bakar...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/oyle-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemediğin!', 'diyemedigin-caglar-asik-1wckt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sözün var, kimselere diyemediğin.

Bir derdin var, kimselere anlatamadığın.

Bir kalbin var, çıkarıp ona sunamadığın.

Bir aşkın var, koşupta hiç ulaşamadığın.

Bir gönlün var, aşkıyla kavrulup yandığın.

Bir ömrün var, uğruna durmayıp harcadığın.

Bir dileğin var, tüm dostlarla paylaştığın.

Bir ruhun var, yanlızca Ona ulaştırdığın. 

İstanbul - 20.06.2005', 'Bir sözün var, kimselere diyemediğin. Bir derdin var, kimselere anlatamadığın. Bir kalbin var, çıkarıp ona sunamadığın. Bir aşkın var, koşup...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/diyemedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-galip-sinecikli-cktv5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'söyle

hangi çıkmaz sokaktan ekspres bir tren geçer 

hangi gül dikenlerini kendine batırır 

leyleğin yuvasında yapabilir mi bir kırlangıç,

hangi midye

bir kum tanesinden başlayıp

acılar içinde

nakış nakış işlediği inciyi

bir parça yosuna feda eder

hangi göz ağlarken

pınarlarından kahkaha düşer yere 

hangi durak var ki

yolcusu olmaz 

hatta ve hatta

hangi fotoğraf karesi

geleceği gösterir adama 

ve

hangi gidişin sessiz harfleri

kalanlara ses verir

söyle

www.radyoerguvan.com

www.turkhaber.eu', 'söyle hangi çıkmaz sokaktan ekspres bir tren geçer  hangi gül dikenlerini kendine batırır  leyleğin yuvasında yapabilir mi bir kırlangıç, ha...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/soyle-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Gitti', 've-gitti-seyfettin-yazar-aevsl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.... Ve gittin işte.! 

Yüreğime bıraktığın aşkınla,

....Ve gittin işte.! 

Bana geride bıraktığın hasretinle.! 

Yolun ve bahtın açık olsun,

Seni seviyorum..

Sarı, Kızıl, Beyaz saçlım. 

Hoşça kal...

.............................!', '.... Ve gittin işte.!  Yüreğime bıraktığın aşkınla, ....Ve gittin işte.!  Bana geride bıraktığın hasretinle.!  Yolun ve bahtın açık olsun, S...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Yazar']::text[], 8.5, '{"poet":"Seyfettin Yazar","poet_slug":"seyfettin-yazar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ve-gitti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlık bitmez.', 'yanlizlik-bitmez-halil-colak-t2g7z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık  bitmez tükenmez hayat gerçeği

Her tarafın kalabalık olsada yalnızlık bitmez.

Yüreklerde sevgi yok olur uçar giderse

İnan kardeşim yalnızlık bitmez.

Ne oldu bizlere kardeşim anlamadım ben

Bir kerecik kardeşini özlemedin sen

Yalnız şarkısı dinlemedin mi hiç sen.

Sevgiler  ölmüş  dünyada yalnızlık bitmez.

Ufukta güneşle birlikte hayat sona ererse bir gün.

Gül bahçesinde güllerin yerini dikenler almışsa bütün

Son konak olan kardeş mezara koyarlar bir gün

Kardeşim mezarda bile yanlızlık bitmez.

Horasan ereni  beni sana nasıl anlatsın

Bitmeyen yanlızlıklara nasıl katlansın.

Bülbül bilir yalnızlığı söyle sana dinletsin.

Konan göçer,ömür biter yanlık bitmez.

Halil Çolak20.6.2005', 'Yalnızlık  bitmez tükenmez hayat gerçeği Her tarafın kalabalık olsada yalnızlık bitmez. Yüreklerde sevgi yok olur uçar giderse İnan kardeşim...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yanlizlik-bitmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ennui! ..', 'ennui-naime-erlacin-44bjq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şimdi canın sıkılıyor ya bu amiplere

en yalın 

en yalan fotoğrafına bakıyoruz hayatın

en vurucu

en deli(ci)  

fazladan bir joker gibi konuyorlar hileli ellere 

arsızca sırıtarak 

şehevi bir doygunlukla illet gibi

çalıyorlar masada ne var ne yok

gözünü dikme virane koyaklarıma

yatıştırmaya kalkışma istim üstündeyim

topla şu zincirleri

yalnızca yokluktur büyüyen 

yoklar âleminde

amipler bilmez boşluğun anlamını

doğuştan öğrenirler parçalanmayı

çoğalırlar

deliliğin onurlu yüzü düşer bize

ne kalır geride 

hangi mecburiyet 

kafalarımızda yuvalanan 

uru kırbaçlamaktan başka

şaşırtmasın kanserojen bu gelişme

hangi hayalperest demiş şiirin kalesidir diye 

istilâ edilir ve hiçe dönüşürken onurlu yalnızlık

şiir mi kaldı böyle! 

hepsi bitmiş bizden evvel 

her yer kangren, her yer çürümüş

başlama sakın sözcük ekonomisinden! 

bu şarkı benim 

devasa bir sözlük doldururum içine 

eğer istersem

sus ve dinle 

koşuyor uğursuz saranın oyuncak bebeleri

amipleri yakala benim için

sıkıca tut, kalmasın hatırım

kurtulalım önce ezici ennui’den 

sonra karar veririz ne halt edeceğimize

sevdim bu yalın fotoğraf anarşisini

çok daha güzeldir bir şarjörü okşamak

bininci kez soyunmaktan bir aptal gibi 

cesetlerin önünde 

ayna nerede 

vuruşacağım! 

şimdi kızıyorsun ya saralı amiplere

ben toplu katliama hazırlanıyorum 

bil ey! 

ayrılık 

acı 

aşk

ve ne varsa daha 

ilerde yine yazılır

önce mühimmatını kuşan gel

tam teçhizat

dedik ya deliyiz diye 

izle beni 

düş peşime! 

(20 Haziran 2005)', 'şimdi canın sıkılıyor ya bu amiplere en yalın  en yalan fotoğrafına bakıyoruz hayatın en vurucu en deli(ci)   fazladan bir joker gibi konuyo...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/ennui-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-halil-colak-0ydx8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece

 Sokakta...

Bir şamata...

Anı bir ıslık

Birde ben

Kalbimde 

Ruhumda

Hayalde bir hüzün

Bir keder

Bir hasret

Birde sen.

Halil Çolak 1.7.1978', 'Gece  Sokakta... Bir şamata... Anı bir ıslık Birde ben Kalbimde  Ruhumda Hayalde bir hüzün Bir keder Bir hasret Birde sen. Halil Çolak 1.7.1...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gece-157-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Akıntı!', 'derin-akinti-naime-erlacin-0hyv3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kovuğundan baktı her biri

biri diğerinden yaralı

bilmezdi hiçbiri içimizin ne dediğini

her gördüğü tepeyi dağ sandı kimi! 

düşperest ürkek ya da cesur

muttasıl tedirgin

sakıncalı çeşnisine kondu sözün

alan aldı 

uğramayan 

aç mı tok mu bilinmiyor

hepsi bu işte! 

öyle saklanmışlardı kendilerinden 

ulaşılmazdı geçitleri

kapandılar içlerine

kapılarsa aralanmadı

kaç cinayetin tanığı var sanırsınız

silahı kaç kişi gördü...kaçı bildi kalibreyi

söylesin ayna! 

sürün şimdi mermiyi boşluğa 

kaç arşınsınız 

kaç bukağınız var

kaça gidersiniz

ak bir yiğit misiniz yoksa! 

gittiğiniz yoldan 

gittiğiniz gibi mi dönersiniz

mukayyet olun kendinize

derindeki çılgın su yutmasın sizi! 

(20 Haziran 2005)', 'kovuğundan baktı her biri biri diğerinden yaralı bilmezdi hiçbiri içimizin ne dediğini her gördüğü tepeyi dağ sandı kimi!  düşperest ürkek y...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/derin-akinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam Zamanı', 'tam-zamani-bahri-yildirim-gm6th', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ay ışığı akşamında

Bir çığlık bölmüş geceyi

Görenler anlatmış görmeyenlere

Kurtlar,kuşlar cıvıldaşmış sevinçle

Bir can geldi Dünya''ya

Muştunun tam zamanı

Geceyi böldü çığlıkları

Anne bir başka mutlu,

Baba bir başka umutlu

Bakıp bakıp birbirlerinin gözlerine

Bu bizim geleceğimizdir dediler

Umudun tam zamanı

Dinle beni bebek, İyi dinle hemi de

Henüz tertemizken yüreğin

Bilmezken,anlamazken hiç bir kötülüğü

İyi dinle! 

Ağlayacaksan şimdi ağla özgürce

Şimdiden çıkar uyumanın tadını

Büyüyünce utanırsın

Şimdi özgürce ağlayabilmenin tam zamanı

Kimseler kalmayacak büyüdüğün zaman

Kucağına özgürce atılabileceğin

Bir anneciğin,bir sıcak kucağın olmayacak

Varken atıl hadi

Bir ana kucağı en sıcak yuva insana

Sığınmanın tam zamanı

Kızım  olursun ya da oğlum

Gelecek yakın zamanda

En yakın zamanda büyürsün

Çiçekler takarsın saçlarına

Vazgeçilmez olursun

Sevdalara tutunmanın tam zamanı

Cihan olursun yaşlı akşamlarıma

Yalnızlıklarımı paylaşırsın çocuk kalbinle

Yaşama ait neyin varsa 

Hep göz diker birileri bunalırsın 

Direnmenin tam zamanı

Göğsünü gerersin zulme ve ihanete

İnce bir sızı kaplar içini

Tam kalbindae vurulursun bir sevda kurşununa

Dayanırsın dişinle tırnağınla

Yavaş yavaş öğrenirsin kötülüklere direnmeyi

Anlarsın yani,Dünya''nın sadece İyilerle  dolmadığını

Siper ettiğin göğsünden 

Binlerce isyan fışkırır kötülüğe

Çaresiz kalırsın bazen

Bazen umutsuz

Bazen yılgın

Ama teslim olmazsın biliyorum

Çünkü sen....

Çünkü sen.....

Aşkımın ilkbaharısın

Benden bir parçasın

Canımsın! 

Seni bu yüzden daha çok seviyorum', 'Bir ay ışığı akşamında Bir çığlık bölmüş geceyi Görenler anlatmış görmeyenlere Kurtlar,kuşlar cıvıldaşmış sevinçle Bir can geldi Dünya''ya Mu...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/tam-zamani-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zikreyler', 'zikreyler-halil-colak-zrp4z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalda çiçekler

Yerde böcekler

Kalp deki gözler

Daim zikreyler.

Gökteki  yıldız

Yerdeki toprak

Ağaçta yaprak 

Daim zikreyler.

Göz ile sebat

Hayvanla nebat

Müminde cihat

Daim zikreyler.

Halil Çolak 12.7.974 Erzurum', 'Dalda çiçekler Yerde böcekler Kalp deki gözler Daim zikreyler. Gökteki  yıldız Yerdeki toprak Ağaçta yaprak  Daim zikreyler. Göz ile sebat H...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zikreyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece de Sevilir İnsan', 'gece-de-sevilir-i-nsan-bahri-yildirim-nszh3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece çok başka olacak

Kulaklarımda çınlayan sesinle

sensiz uzanacağım yatağıma

Hangi sürprizlere gebe kimbilir? 

Hangi yokluklarla dolacak yüreğim? 

Nasıl bir karanlık ki bu gece

Ay ışığı gözlerini bile saklamış.

 Ne bir ışık ne bir umut

 Nasıl bir gece ki bu? 

Her tarafa sensizlik yağıyor.

Ah bir görsem sabahın aydınlık yüzünü

sana neler söyleceğim bir bilsen...

Birazcıkta senin yüreğin titrese

Bilsen ne kadar özlendiğini

Ne kadar sevildiğini bilsen keşke

Sende seversin bitimsiz

Vız gelir gece

Ah bir bilsen

Uykularımın en güzellerinin

Senle başlayıp bittiğini

Nokta olmasan en güzel yerlerine rüyamın

Bir bilsen sensizliğin acısını

Gecede seversin 

Gündüzde...', 'Bu gece çok başka olacak Kulaklarımda çınlayan sesinle sensiz uzanacağım yatağıma Hangi sürprizlere gebe kimbilir?  Hangi yokluklarla dolaca...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gece-de-sevilir-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Kaldırımda', 'islak-kaldirimda-burak-cicek-frctr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Islak kaldırımda ıslık çalarak sürünüyorum

Solucanları anlamak için yaptığım saçma

Biliyorum

Soluksuz kaldım, sağanak yağış altında nefes nefeseyim

Islak tüylerim kaldırım taşlarına dökülüyor

Canım acıyor hayat can yakıyor ve ten acıtıyor.

Ölmek görmek mi demek devri alemi? 

Yoksa gömmek mi hatırları toprak altına

Bilebilsem, öle bilsem gidebilsem 

Ben hani şu kaldırımda sürünerek gezen, 

sırılsıklam ve artık kel

Sürünerek karşıdan karşıya geçiyorum 

Bağdat caddesinden 

Elveda………..

Ölüm mutlu son, intihar kaçınılmaz.', 'Islak kaldırımda ıslık çalarak sürünüyorum Solucanları anlamak için yaptığım saçma Biliyorum Soluksuz kaldım, sağanak yağış altında nefes ne...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/islak-kaldirimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nurum mu vardır', 'nurum-mu-vardir-i-brahim-kilinc-2kkg2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne diye seveyim böyle baharı? 

Gülşende açılan gülüm mü vardır? 

Gül yüze hasretim, bitmiyor çile

Güzeller içinde yârim mi vardır? 

Baharı beklerken, geçmiş çoktan yaz

Şakaklara düşmüş kar beyaz beyaz

Tanrı''dan dileğim bir olmaz niyaz

Hasretsiz geçmeyen günüm mü vardır? 

Sarı saçlarında güneşi gördüm

Mavi gözlerinde ummanı buldum

Mah cemâlin ayın ondördü bildim

Bana açmadığın sırrın mı vardır? 

İbrahim dil bilmez, anlatsa aşkı

Atamaz, satamaz bu kara bahtı

Senin hasretinle geçiyor vakti

Karanlık dünyada nurum mu vardır?', 'Ne diye seveyim böyle baharı?  Gülşende açılan gülüm mü vardır?  Gül yüze hasretim, bitmiyor çile Güzeller içinde yârim mi vardır?  Baharı b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nurum-mu-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarzan', 'tarzan-burak-cicek-kd2xj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Böbreklerim ağrıyor

Tarzan olmanın da bir bedeli var

Koluma mı ne oldu? 

Aslan kaptı, timsah attı 

Hayvanların espri anlayışı kadınlarınkine çok benziyor değil mi? 

Bağırsak kurtlarıyla da başım dertte şu sıralar

Kendini tenya sanan bir anakonda kaçtı kıçıma 

Şempanzemle olan ilişkim tatsız, anlaşamıyoruz

Adeti de gecikti aşiftenin 

Zannederim bir gorille aldatıyor beni 

Ama olsun bir insanla aldatmasında daha az onur kırıcı bu 

Ağğğaağaağ…….

Yapmaz anakonda.', 'Böbreklerim ağrıyor Tarzan olmanın da bir bedeli var Koluma mı ne oldu?  Aslan kaptı, timsah attı  Hayvanların espri anlayışı kadınlarınkine...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tarzan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selim', 'selim-burak-cicek-n095p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalk gidelim selim Azrail geldi ortamın havası bozuldu.

Ceset kokuyorsun dostum selim

Bak ya, 

neden ağlıyor nişanlın selin

Nereye gidiyorsun

Daha erkendi yaş yirmi dört

Karesi bile değil 5’in

Çok tez bu gidiş kalsaydın, 

Kalamadın. 

Ceset olmuşsun dostum selim 

Ne diye çapraz ateşe tuttun kendini?', 'Kalk gidelim selim Azrail geldi ortamın havası bozuldu. Ceset kokuyorsun dostum selim Bak ya,  neden ağlıyor nişanlın selin Nereye gidiyorsu...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/selim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz günler', 'sensiz-gunler-i-brahim-kilinc-ssydy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstemeden bazen seni üzdüysem

Deli gönlün sevdasına say gülüm

Ne olur ki, üç beş satır yazdıysam

Sensiz günler oluyorken ay gülüm

Gönül bir serçedir, hasret mengene

Ölmez sağ kalırsam yazarım yine

Ha kırk yıl yaşadım, ha doksan sene

Sensiz günler oluyorken zay gülüm', 'İstemeden bazen seni üzdüysem Deli gönlün sevdasına say gülüm Ne olur ki, üç beş satır yazdıysam Sensiz günler oluyorken ay gülüm Gönül bir ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensiz-gunler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arife', 'arife-burak-cicek-cvyft', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir metrekarelik garsoniyerimde bir fahişe olan sözde metresimle her anı sıcak her anı nefes nefese.

Bu gece.

Bu gece arife…', 'Bir metrekarelik garsoniyerimde bir fahişe olan sözde metresimle her anı sıcak her anı nefes nefese. Bu gece. Bu gece arife…...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/arife-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Holigan', 'holigan-burak-cicek-d1izv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pembe forma giyen bir futbol takımının

Kramponlarını temizleyen mini etekli kız

Kendi duasını kendi yazan

Ekonomik kaygı taşımayan kız

Küme düştün, küme düşürüldün

Sen yedek kaleciye aşıktın

Öyle gizli saklı da değil 

İlanı aşıktan korkmazdın

Maalesef defansa takıldın.

Sana faul yaptılar Gül! 

Sana faul yaptılar, sakatlandın.

Sert oynadılar, fizik kondisyonları yüksekti

Oysa masumca pembe forma giyerlerdi ve sen temizlerdin kirlilerini…

Kıymet bilmediler.

Pembe forma giyen bir futbol takımının

Geri dörtlüsünün ırzına geçtiği mini etekli kız

Eteğin yırtık, eteğin kanıyor.

Gerisi mühim değil desem de bilirim ki nafile

Söyle üzülmesinler haline.

Kendi kendine delirmedin ya, 

anlat ailene

Önce çıkart şu pembe formayı üzerinden

Yazdığın duaları oku peşi sıra

Kübist resimler yap ardından.

Bırak şu futbol merakını artık Gül

Renklerin büyüsüne kanma

Kapat gözlerinin kepenklerini dünyaya

Ve veda et aşka.', 'Pembe forma giyen bir futbol takımının Kramponlarını temizleyen mini etekli kız Kendi duasını kendi yazan Ekonomik kaygı taşımayan kız Küme ...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/holigan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Şarkısı', 'ozgurluk-sarkisi-bahri-yildirim-72s4g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman sevda zamanıdır 

Öyle salma kendini

Öyle yıkma! 

Öylesine boş verme Dünya''ya

Yüreğine düşmesin ayrılık acıları

Gözlerine dolmasın nem

İhanetleri söylemesin  dilin

Öylesine yaşama Dünya''da

Ellerin barış yazsın hep

Gözlerin mutluluğun resmini  çizsin 

Kulaklarında hep o şarkı çalsın

Bizim şarkımız varya hani

Hani o şarkı canım! 

Yüreğime seni sonsuz kazıtan o şarkı

Hiç eksik olmasın dilinden

Ben ancak o dilden anlarım bilirsin

Sen  de hep o şarkıyı  söyle', 'Zaman sevda zamanıdır  Öyle salma kendini Öyle yıkma!  Öylesine boş verme Dünya''ya Yüreğine düşmesin ayrılık acıları Gözlerine dolmasın nem ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozgurluk-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini Gözlerime Tak', 'gozlerini-gozlerime-tak-hasan-ejderha-10jmp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Keklik  yakalamış

Kartal pençesince

Gözlerini gözlerime tak

Hep orada yaşa

Oraya bak

Çoban ateşini

Oraya yak.

Nişanlı ziyaretinden

Dönercesine kalk

Sevgi mi istiyorsun

Bebeklerce kucak-kucak

Düşüncem hep sevgi olacak

Hayatta anlamını bulacak

Bir yürek ki…

Dokunsan ezilecek

Büyük rüya bitecek.', 'Keklik  yakalamış Kartal pençesince Gözlerini gözlerime tak Hep orada yaşa Oraya bak Çoban ateşini Oraya yak. Nişanlı ziyaretinden Dönercesi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerini-gozlerime-tak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-hasan-ejderha-xvq52', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklımı zorluyorken aşkın

Söyle

Maşukun ne yapsın

Bana aşkın gerek

Sen

Ha varsın ha yoksun

İstersen

Gel aşkımız bitsin

Ya da uzak kal

Aşkımız devam etsin

1988', 'Aklımı zorluyorken aşkın Söyle Maşukun ne yapsın Bana aşkın gerek Sen Ha varsın ha yoksun İstersen Gel aşkımız bitsin Ya da uzak kal Aşkımız...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgiliye-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sen Ve Yaşadıklarımız', 'ben-sen-ve-yasadiklarimiz-hasan-ejderha-h8ezs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BEN- Yüreğimi avucuma alıp

Çivi çakarken buzlara…

SEN- Balyozla iz açmaya çalıştın

Kendi halinde akan sulara…

Sular sessiz

Rüzgar nefessiz

Ağlıyor babam.

Yürekler penceresiz

Kulaklar duyarsız

Gür çıkmıyor naram.

Babam ağlıyor

Zaman ağlıyor

Sen istersen gül.

Duyma nine

Görme onları babanne

Sen seccadende süzül.

Bin aşka bin şahit gerekmez

Benim yüreğime bin aşk yetmez

Sorma aşkı sorma zamanı bana

Onu ancak ben yaşarım

Nefessiz esiyor rüzgar baksana

Ben ise önünde koşarım.

1990', 'BEN- Yüreğimi avucuma alıp Çivi çakarken buzlara… SEN- Balyozla iz açmaya çalıştın Kendi halinde akan sulara… Sular sessiz Rüzgar nefessiz A...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ben-sen-ve-yasadiklarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran Külleri miydi...', 'haziran-kulleri-miydi-i-brahim-ethem-bingul-3chkf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Savrulan haziran külleri miydi? 

Her zerremin aşkın peşinden koşması mı? 

Yaşayan ölüye döndüm tam bir senedir

Her saniyesi aylara bedel

Yok mu bir haber ya da sefer

Seni bana ulaştıran...

Kayboldum yine aşkının kızıl alevinde

Resminin solgun renklerinde

Korkuyorum

Kim bilir bir gün unutursun beni diye...

Gecelerin karasında

Gözlerin ışıldıyor rüyalarımda

Aşkım, özledim

Neredesin! ? .

www.iebingul.com', 'Savrulan haziran külleri miydi?  Her zerremin aşkın peşinden koşması mı?  Yaşayan ölüye döndüm tam bir senedir Her saniyesi aylara bedel Yok...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/haziran-kulleri-miydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keman Sesi', 'keman-sesi-hatice-ozdes-1luyu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir keman sesi çalınır

Kulaklarımda çınlar o nağmeler

Seni hatırlatır

Yaşananlar anımsanır

Güzeldi hoştu her şey

Güzeldi hoştu her şey

Yüreğimi yakan

Seni benden çalan

O keman nağmelerinin ardından

Hatırlatır seni bana

Güzeldi hoştu her şey

Güzeldi hoştu her şey', 'Bir keman sesi çalınır Kulaklarımda çınlar o nağmeler Seni hatırlatır Yaşananlar anımsanır Güzeldi hoştu her şey Güzeldi hoştu her şey Yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/keman-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-hatice-ozdes-xqajy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boş olan yarım kalan

Hayatımı anlamsız kılan

Yarım kalan nağmeler

Dökülür dudaklarımdan

Tamamlanmak isteyen

Sonunu baştan belli eden

Hayatıma renk katan

Yüreğimi yerden yere vuran

Aklıma bile gelmezdi

Hayat sensiz geçmezdi

Bu rüya böyle bitmezdi', 'Boş olan yarım kalan Hayatımı anlamsız kılan Yarım kalan nağmeler Dökülür dudaklarımdan Tamamlanmak isteyen Sonunu baştan belli eden Hayatım...', ARRAY['Türk Edebiyatı','Şiir','Hatice Özdeş']::text[], 8.5, '{"poet":"Hatice Özdeş","poet_slug":"hatice-ozdes","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ruya-177-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüseyni Bir Çizgi Bırakıp Gittin', 'huseyni-bir-cizgi-birakip-gittin-hasan-ejderha-fqm1q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüseyni bir çizgidir gidişin bende

Alnımda senden iz olarak durur

Geceye makamlar vurur sensizlik

Ne ilk, ne de son gidensin oysa sen

Hüseyni bir deniz içimde kudurur.

“açın çantasını nesi var

bir çift potini bir de fesi var”

Ne dağlar dayanır bu gidişe

Ne de makamlar

Hüseyni en uygun gidiştir

Bir de hüzzam

Benim yüreğim ve cümle azam

Hasrete uyarlı şimdi

Sen gibi bulut olmaz havada bir daha

Çocukluğum dayanır kapıma

Anne cenazeleri geçer sokaktan

Korkarım çocukluğumda kalmaktan.

Bir daha gazi ortaokulu olacak mı

Ya duvar üstündeki ekmek

Çün hala kahrı var alamamanın

Lezzeti damağımda yemişcesine.

Ya harmancık ilkokulu

Gübre torbasından muşamba çantam

İlk çözüşüm çantamda yazılı “TZDK”’yi

Daha güzel değil mi “nike” yazan çantadan

Ya da “emre”’nin “adidas” çantasından

Arkasından tüm bunların arkasından

Hicaz bir şarkı çalsa ne çıkar

Ya da kürdili hicazkar.

Hüseyni bir köyden

Hüseyni bir şehre aktı hayatım

Hiç mahur besteler yaşamadım ben

Sonra türkülerin hüznünde buldum kendimi

Bendimi yıkarım edasıyla yürüdüm üstüne şehrin

Derin kuyulara yusuf ben oldum kentlerde

Sirenlerin çaldığı saatlerde ansızın

Ben fırladım hışımla sokaklara

Yara sunacak tek güle bile

Dağlar yıkarım şimdi.

Hüseyni köyün delikanlısını ben büyüttüm bu caddelerde

Sokaklar feryatta şimdi, içemediler onun derin gönlünü

Yönünü şaşırmış pusulalar aciz ve şaşkın karşısında

Bin ahına dayanamayan, dağlara baskın yapılar

Yükselir etrafında, bin inatla dağlara

Ağlara takılan sazanlar gibi

Yutacakken şehir

O şimdi

Hür.

Bahar

Ancak dağlara

Yaraşır sanırdım

Oysa çiçekler açtı şimdi

Hüseyni köyün delikanlısında

Faslında medeniyetler haykıran

İcra-i sanat hilalinde ne makamlar var şimdi

Delirecek gibi bir hazla meşke doyan yürek o yürek

Kırmızı bir semerde mavi boncuğu hayranlıkla seyretmek

Hüseyni bir çizginin, hüseyni manalarla dolu hayatına denk

Beklemek gerek. 

Hüseyni bir hayatın hüseyni nesli elbet gelecek.', 'Hüseyni bir çizgidir gidişin bende Alnımda senden iz olarak durur Geceye makamlar vurur sensizlik Ne ilk, ne de son gidensin oysa sen Hüseyn...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/huseyni-bir-cizgi-birakip-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın suçu ne?', 'sevdanin-sucu-ne-ali-riza-unal-yvgu8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şaşkın gönül arısı,kendini sinek sanıp, leşe konarsa. 

Çiçekte has balın,o  pak, yalın sevdanın suçu ne? .

 Noot şiirin tamamı deyildir.

Gerisi geride. sevdaya suç isnad ednlere hediyedir.', 'Şaşkın gönül arısı,kendini sinek sanıp, leşe konarsa.  Çiçekte has balın,o  pak, yalın sevdanın suçu ne? .  Noot şiirin tamamı deyildir. Ger...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevdanin-sucu-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma', 'ogluma-herdem-ankara-1y805', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalem dedi kendim yazarım

Göz yaşlarımı damla damla akıtırım

Ayrılığı ben içimde yaşarım

OĞLUM seni çok özledim...

Bir umut oldun doğduğun günde

Nefes oldun bu bedene

Bir hasretsin belleğime

OĞLUM seni çok özledim....

Böyle bir hayat istemedin

Gözlerinde sevgiyi göremedim

Dostluğunu bilemedim

OĞLUM seni çok özledim...

Bir ben vardı ki bende

Sensizliği yaşadım oldum divane

Hasretin içimi yaktı ÖZLEDİM

OĞLUM seni çok özledim.....

Canım yavrum TOLGA EGE

16/06/2005

23:05', 'Kalem dedi kendim yazarım Göz yaşlarımı damla damla akıtırım Ayrılığı ben içimde yaşarım OĞLUM seni çok özledim... Bir umut oldun doğduğun g...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ogluma-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen Eğer', 'gidersen-eger-atilla-guler-zof09', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kumdan kaleler gibi hayat 

bir uğur böceğine bağlanmış umut 

tekdüze bir gidiş geliş 

laleler lekelenmiş kaldırım köşelerinde 

canımı acıtan bir hikayenin sonu aşk 

gece yorganı çeker üstüne 

ay kızıla bürünür 

kan damlar saatlerden 

bulutlarda dans eder yıldızlar 

yanarım...sessiz 

vurur aşk suskunluğumu 

dinle____ 

şu havlayan it...ağlayan bebek...kıyıya vuran dalgalar...çığlık çığlığa martılar 

benim...sesim____ 

sana...her gece şarkılar söylerim 

sana açarım otağımı...kurşunlar yağar saatlere...ölür zaman! 

öyle koyar ki sevdan 

öyle koyar ki____ 

...billur yaşlar kurur 

yüreğe vurur hançer...kanar sevda 

___acıyla... 

gidersen bir gün 

-olur ya- 

kal demem 

kelebekler özgürdür ya hani 

kısacık özgürlüğünü senden alamam 

ama...ağlarım...sessiz 

isyanlara çağlar haykırışlar...kusarım 

terkedişlerin zalimliğine...lanetim öfkemde 

hüzün dolaşır gözlerimin ucunda 

kirpiklerimde yaş olur ayrılık 

git__ 

me! 

susmuyorum sana/susturamazsın 

kelimeleri ben zapt ettim 

durduramazsın! ! ! 

gidersen gelmeyi unutma... 

sen...gidersen eğer 

göremem...istemem/kapanır gözlerim yollara 

git...ama 

gelirken sıcak getir ellerime...sıcak getir 

üşüyorum... 

bırakma bana beni 

biliyorum 

gidersen olmam 

ben___bende kalmam 

al beni de öyle git 

şarkımı koy koynuna 

ama 

gel...şiir ol öyle gel 

gel___beni....sıcacık...sımsıcak 

şiirle...vur!', 'kumdan kaleler gibi hayat  bir uğur böceğine bağlanmış umut  tekdüze bir gidiş geliş  laleler lekelenmiş kaldırım köşelerinde  canımı acıtan...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/gidersen-eger-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti', 'bitti-serkan-yildirimoglu-t5z4m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlık ve soğuk odamın duvarları ile

Sen biliyor musun ben geceleri ne yaparım

Başıma çekince ağır ve kötülü yorgan mı

Gözlerimi kapatınca neler görür, duyarım

Ben her gece kurt gibi ulur, at gibi kişnerim

Duvarları yıkmak için tırnaklarımla

Rüyalarımda ellerimi kırmızıya boyarım,

Akan kanlar görülmesin, göremeyesin diye

Kapıya son attığım kafadan sonra

Herkes girip çıkabilsin diye kilit yok

Ama sen giremeyesin, kapıda kalasın diye

Anahtarımı bildiğin yerden aldım

Sen gittikten sonra neler neler oldu

Her gece karanlıkta gözlerimi bağlayıp

Kör ebe oynuyorum kendi kendimle

Hep kaçıyorum hep kovalıyorum kendimi

Senin için terk ettiğim dostlarımdan sonra

Yalnızlığın acısını yaşamanın verdiği yük

Sensizliğin getirdiği acıların yükünü

Cılız bedenimle kaldırmaya çalışıyorum 

Gece uyumak için yorganımın altında iken

Aklıma düşüyorsun hiç olmadık bir anda

Nerede ne yaptığına dair uyuz hayaller

Geçmişe dair güzel günlerin gitmişliği

Artık ay tutuldu, ışımayacak bir daha

Boğuyor güneşi sarmaşıklar, ısıtmayacak

Ufuklara gömüldü tüm yıldızlar

Bir daha kaymayacak, tüm dilekler bitti', 'Karanlık ve soğuk odamın duvarları ile Sen biliyor musun ben geceleri ne yaparım Başıma çekince ağır ve kötülü yorgan mı Gözlerimi kapatınca...', ARRAY['Türk Edebiyatı','Şiir','Serkan Yıldırımoğlu']::text[], 8.5, '{"poet":"Serkan Yıldırımoğlu","poet_slug":"serkan-yildirimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bitti-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatta en çok Rabbımı sevdim', 'hayatta-en-cok-rabbimi-sevdim-ali-riza-unal-1v6uv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatta ben en çok,Rabbımı sevdim.

Ana koynundan alıp bilmemki nereydi,

O gezdirdiği tarifsiz güzel yerler.

Ben şimdi oraları çok ama çok özledim.

Üç beş yaş arası, safi sübyan bir çocuktum.

Gerçi şimdide halâ öyleyim,o Rabbım katında.

Köyümüze yakın bir tarlada,hasat zamanı idi.

Annem ile babam hasatla uğraşırken kan ter içinde.

Ben dere kenârından geçip, ormanda oyuna dalmıştım.

Ömrümce hiç unutmam,sanırım bir meşe ağacı idi.

O ağaç haydi gel,ben senin Rabbınım diye seslendi.

Çocukluk olsa gerek, çok ama çok korkmuştum o hitaptan.

Çünkü o ağaç o anda, insan suretine bürünmüştü.

Yarım nefes,yarım adım,sürdümü bilmem,o nasıl kaçış.

Gözümü annem ile  rahmetli olan babamın yanında açtım.

Aradan geçen yıllardan sonra yaş kırk oluvermişti.

Yine aynı zuhurat ve tecelli,her yerden her yönden oluyordu.

Elhamdulillâh korkmak şöyle dursun,bir garip hıçkırık,

Bir garip göz yaşı içinde,yoğrulup yok oluyorum.

O hal ne feryat,ne ne bir sükût hali, haz içinde haz.

Gerisi sırrı ifşa, ihanet olur,duy ve yaz dostum yaz.

İşte hayatta ben en çok Rabbımı sevdim.

Çünkü beni yaratan,yaşatan,büyütüp eğiten hep o idi.

Bulamadım başkasını hayatta ben en çok Rabbımı sevdim.

  Not  burada muradımız asla kendimizde varlık büyüklük anlatmak deyildir.neye büyükleneyimki aczime şahit olmuşum.

Bu asırdada Hz ALLAHIN şen-inin rahmetinin kesilmediği

Ve kıyamete dek devam etmekte olduğunu hatılatmak ve,

Ehli talip aşığa, vuslat için bir umut veslesi olmaktır.

Yoksa ne haddimize varlıktan dem vurmak,

Güç kudret ve ihsanı lütûf yalnız ve yalnız ille ALLAHA ait ve mahsusdur bizler,onun iki çıplak bir hamama yakışan, misali abut,Aciz kullarıyız Elhamdulillaaaah! .işte bu acizlik benim tek amaTek övüncümdür. Kurtuluşumdur.inşaALLAH.

 okuyucuların dikkatine.

tefekkür tembeline bu eserden zarar hasıl olur.', 'Hayatta ben en çok,Rabbımı sevdim. Ana koynundan alıp bilmemki nereydi, O gezdirdiği tarifsiz güzel yerler. Ben şimdi oraları çok ama çok öz...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hayatta-en-cok-rabbimi-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salak Be....', 'salak-be-zulfikar-yapar-kaleli-t41qr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neler, neler gördük şu meydanlarda

Yüzmeyi bilmeyen, ördek geçinir

Yaptığı şeytanca işi anlarda

Kalkar bu toplumda melek geçinir.

Saçma inancını yayar aleme

Yüz çevirir, karşı durur ilime

Ne istiyorsa sor, bilmez kelime

Çamura batar da kürek geçinir.

İlimle, irfanla yoktur ilgisi

Düşük çenesinin olmuş delisi

Zevzeklik ininin eski tilkisi

Kuyruğunu kısar, leylek geçinir

Nasıl tarif etsem, o bir tuhaftır

Yüzüne bakınca sanırsın saftır

Onun işi gücü fitne, fesattır

Sırtında her türlü felek geçinir.

Tutmayan beyninden akarken beyni

Bunlar çok eskidir, değildir yeni

Haşâ, adları da çıkmış medeni

Her gelene vurur, değnek geçinir.', 'Neler, neler gördük şu meydanlarda Yüzmeyi bilmeyen, ördek geçinir Yaptığı şeytanca işi anlarda Kalkar bu toplumda melek geçinir. Saçma inan...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/salak-be-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dürüstlüğün Bu Mu Senin....', 'durustlugun-bu-mu-senin-zulfikar-yapar-kaleli-a0qn0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Madem ki yüzüm ak temizim dersin

Ardına döktüğün bu pasa nedir? 

İnsan geçinirsin insanı yersin

Zehir zukkum dolu bu masa nedir? 

Hiçbir zaman yüz olmadın astarsın

Amelin ne ise Rabbim göstersin

Hani haram yemez hell istersin

Çalma çırpma dolan bu kasa nedir? 

Hani hak yolunda yarışçı idin

Hani hakla halkı karışçı idin

Hani dövüş bilmez  barışçı idin

Elinde tuttuğun bu asa nedir? 

İtecektin ayağınla illeti

Kovacaktın kovamadın zilleti

Seviyorsan memleketi milleti

Dilinden düşmeyen bu U S A  nedir? 

Hak gözetip haksızlığa vurmazsın

Bir an bile mazlumları sormazsın

Hak-hukuk dersinden geri durmazsın

Hep ihlal ettiğin bu yasa nedir? 

                                                       1978', 'Madem ki yüzüm ak temizim dersin Ardına döktüğün bu pasa nedir?  İnsan geçinirsin insanı yersin Zehir zukkum dolu bu masa nedir?  Hiçbir zam...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/durustlugun-bu-mu-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendeyim', 'sendeyim-ayhan-akdogan-00ntv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sonuna gelmiş her bir damla gözyaşım

ellerim zor tutmakta ellerim arasındaki gülü

yüzümden bin parça düşen sevdanın sendanın izleri

hasreti iplikle çekip seni sende yaşamak en güzeli

gülün kokusuna benzetirdim sesini

duyduğumda hoş olur coşardım sonu gelmeyen yollara

bir çocuk edasında ayakalarım beni sana götürürdü

bedenim burda kalırdı oysa ben hep sendeydim

ürkek ve çekingen bakışlardan aldım ben sevgiyi

bazen bir umut bazen güven oldu ama yine...

seni sensiz yaşamak en kötü kaderim oldu benim

artık herşey bitti buraya kadar olsada ben hep sendeyim...', 'sonuna gelmiş her bir damla gözyaşım ellerim zor tutmakta ellerim arasındaki gülü yüzümden bin parça düşen sevdanın sendanın izleri hasreti ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Akdogan']::text[], 8.5, '{"poet":"Ayhan Akdogan","poet_slug":"ayhan-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sendeyim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Haber...', 'ne-haber-zulfikar-yapar-kaleli-ge0za', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gömüldün içine ye kana kana

Seni borçlu koyan maldan ne haber? 

Para mal mülk şöhret hepsi bir yana

Edepten erkandan yoldan ne haber? 

Fukaraya herkes öl mü diyecek? 

Mazlum mu her zaman boyun eğecek? 

Ziynet Bacı hep kara mı giyecek? 

Maviden yeşilden aldan ne haber? 

Helal ne haram ne doldur kasaya

Birgün sevap günah konur masaya

Değişsin  değişsin denen yasaya

Sığınıp zulmeden kıldan ne haber? 

Kaleli ki Yaradan''ın muhtacı

Ne idükler evet şimdi baş tacı

Yedikçe gıdıklar acı mı acı

Arının yaptığı baldan ne haber? 

                                                 1984', 'Gömüldün içine ye kana kana Seni borçlu koyan maldan ne haber?  Para mal mülk şöhret hepsi bir yana Edepten erkandan yoldan ne haber?  Fukar...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-haber-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Cambaz', 'seni-cambaz-zulfikar-yapar-kaleli-ixw7c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu şeytan fikrinle alim geçinme

Hakikat sırrına erenleri gör! 

Her şey bana mahsus  hep benim deme

Vatana canını verenleri gör 

Nasılsa her zaman öter düdüğün

Düdüğün öttükçe olur dediğin

Vurgunu vurunca eylersin düğün

Biraz da ah u zar derenleri gör 

Haksız isem söyle  hadi ne dersin

Babanın cesedi olsa da yersin

Salıverdin aynı hızla gidersin

Postu yol başına serenleri gör

                                                1987', 'Şu şeytan fikrinle alim geçinme Hakikat sırrına erenleri gör!  Her şey bana mahsus  hep benim deme Vatana canını verenleri gör  Nasılsa her ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-cambaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Bestesi', 'zamanin-bestesi-hasan-ejderha-6icsq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırılır mı kovuklara sarkan dal bilmem

Bana düşmez bestesi zamanın

Ansızın şiire kayabilir sızım, lakin baltam kör

Ver elini İstanbul deyip gitmek hangi şarkıya çıkar

Aşikar bir hayata makam tutmaz, karanlıkta paslı kilit.

Zahit ölmedi daha ahmaklar. Yar var gazel var hazan var

Hangi var yakın değil ki yokluğa, pas tutmaz güneş

İki at az bozkıra ve bir evlek tarla, İstanbul’a çok var daha.', 'Kırılır mı kovuklara sarkan dal bilmem Bana düşmez bestesi zamanın Ansızın şiire kayabilir sızım, lakin baltam kör Ver elini İstanbul deyip ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zamanin-bestesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimden yol alıyorum', 'kendimden-yol-aliyorum-nalan-kazazoglu-ucay5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O koyu iz yüreğimde,

Dalgalı denizlerdeyim yaşamın içinde...

Zirvemde hiç gitmez duman,

Başım karlı her mevsimde...

İçimdeki sesi boğup

Başımı denizlere sokup

Son bulmaz masalları dinlerim

Elimi toprağın eline koyup....

Bırak yosunlar başımdan açsın..

Balıklar göğsümde zıplayan yüreğimden kaçsın..

Güneşi kucağında taşıyan sular,

Köpüklerini başıma saçsın....

Hayallerime düşmez bir ufak ışık,

Daha çok kendimden yol alıp

Değiştirsem şu yüreğimi koparıp

Kocaman yüreğimin her yanı yırtık,  kırık.....', 'O koyu iz yüreğimde, Dalgalı denizlerdeyim yaşamın içinde... Zirvemde hiç gitmez duman, Başım karlı her mevsimde... İçimdeki sesi boğup Başı...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kendimden-yol-aliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş ve Çocuk Masalı', 'tas-ve-cocuk-masali-hasan-ejderha-cpqet', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dereler ak taşları yumuş

Taşlar

Ak olmuş

Çocuk oturmuş

Üstüne taşın

Hayal kurmuş

Su taşları yur

Taşlar da suyu

Şimdi güzel dereler

Kışın niye değişir huyu

İçerlemiş 

Hayaline çocuğun

Orman ve yağmur

Orman ağacı sulamış

Ağaç dallarını

Göğe yollamış

Sel olmamış 

O yıl

“oturma taşa

takkeni al başa”

Demiş ya atalar

Kışın karlar

Taşları kaplamışlar

Çocuk oturmamış taşa

Takkesini de almış başa

Çocuk 

Dereyle arkadaş olmuş

Çünkü dere

Muhtaçmış arkadaşa

Ah güzel çocuk

Sen çok yaşa.', 'Dereler ak taşları yumuş Taşlar Ak olmuş Çocuk oturmuş Üstüne taşın Hayal kurmuş Su taşları yur Taşlar da suyu Şimdi güzel dereler Kışın niy...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/tas-ve-cocuk-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayırlısı', 'hayirlisi-zafer-mutlu-9tpjs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sana değil bir kez,bin kez

evet derim inan..

dudaklarım alışkın

evet-e

kulaklarımda hep duymak ister; 

ortalaması olmayan,

kolay tüketim hayallerinin

sihirli kelimesi,  evet leri...

gel bu alışkanlıktan vazgeçelim,

pembe görüntüleri şimdi den silelim

gözlerimizden..

gerçeklere toslayalım,

kafamız hala ayıkken..

hayır-lara alıştıralım 

birbirimizi,

hayır-lısı diyerek-den...', 'sana değil bir kez,bin kez evet derim inan.. dudaklarım alışkın evet-e kulaklarımda hep duymak ister;  ortalaması olmayan, kolay tüketim hay...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayirlisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halkçılık', 'halkcilik-halil-colak-mplqv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Halkçılık

Konuş be şaşkın

Hanibe Hakçılığın

Yıllarca sömürdüğün

Fakır fukaranın 

Hayatı ile oynadın kumar

İçki masalarında

Bütün değerlerini

Yok ettin acımadan,

Bumu be halkçılığın

Halil Çolak 17.1.1977 İstanbul', 'Halkçılık Konuş be şaşkın Hanibe Hakçılığın Yıllarca sömürdüğün Fakır fukaranın  Hayatı ile oynadın kumar İçki masalarında Bütün değerlerini...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/halkcilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hokkabaz', 'hokkabaz-halil-colak-yk94r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hokkabaz

 Şu hırsız

Şu hilekar

Şu madrabaz 

Toptancılıkta ne denir.

Her ipte

Her dalda,

Oynayan cambaz

Halil Çolak 17.1.2005 İstanbul

.', 'Hokkabaz  Şu hırsız Şu hilekar Şu madrabaz  Toptancılıkta ne denir. Her ipte Her dalda, Oynayan cambaz Halil Çolak 17.1.2005 İstanbul ....', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hokkabaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz', 'karadeniz-arif-buk-cli6b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Topraktan gelenleri seyreder göz

Göğün her yanında yağmurdur zaman,

Yeşil...Dalgalarını keser denizin

Yeşil...Sahillerde en derin iz

Saçlarından akar dağların Karadeniz...

Düşler ıslak ıslak kederler mavi

Su içten kucaklayan biri içimizde,

Mavi ve yeşil; gözlerde doğan ikiz

Toprağa abanan cennettir Karadeniz...

Menekşe en güzel burada açar

En güzel duyulandır martı çığlığı,

Tek mevsim bahar ve giz

Dünyanın ellerinde

Yeşil bir eldivendir Karadeniz...

Yağmurdan merdivendir burada zaman

Sarışın bakışlara hasrettir deniz

Irmakların dolandığı,

Yeşil bir gözün içinde rüyadır Karadeniz...', 'Topraktan gelenleri seyreder göz Göğün her yanında yağmurdur zaman, Yeşil...Dalgalarını keser denizin Yeşil...Sahillerde en derin iz Saçları...', ARRAY['Türk Edebiyatı','Şiir','Arif Bük']::text[], 8.5, '{"poet":"Arif Bük","poet_slug":"arif-buk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karadeniz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C08 - Ta Kendisi', 'c08-ta-kendisi-tahir-gungor-52jbq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Görsen sıradan birisi,

Gönül gözüyle erisi,

Coşkusu tanrı verisi,

.............Çağlayanın, ta kendisi.

Kara toprağın humusu,

Olmadan çıkar umusu,

Gönülden halka sunusu,

.............Sevgilerin, ta kendisi.

Sırt kamburu tek eğrisi,

Yolu doğruların doğrusu,

Aşrı, sivrinin yumrusu,

.............Hoşgörünün, ta kendisi.

,

Dost, bir dost diyen arzusu,

Gülüp de geçmiş bazısı,

Dinmeyen gönül sızısı,

.............Yalnızlığın, ta kendisi.

Bir demiş iki dinlemiş,

Ne hak, ne de hukuk yemiş,

Saza sarılıp inlemiş,

.............Feryatların, ta kendisi.

Kakk ın zindana attığı,

Dostun kenara ittiği,

Eşin terkiyle tattığı,

.............İhanetin, ta kendisi.

Çok kara imiş yazgısı,

İnce bir yolmuş çizgisi,

Olağanüstü sezgisi,

.............Ermişliğin, ta kendisi. 

Sözün meclise katkısı,

Kurakta rahmet etkisi,

Kara toprağa tutkusu,

.............Sevdaların, ta kendisi.

Çorak toprağın kurusu,

Duru suların durusu,

Ama gözlerle görüsü,

.............Hakikatin, ta kendisi.

Çok da tüketmiş nefesi,

Durup durup bir esesi,

Bu torağın yanık sesi,

.............Koca Veysel, ta kendisi.', 'Görsen sıradan birisi, Gönül gözüyle erisi, Coşkusu tanrı verisi, .............Çağlayanın, ta kendisi. Kara toprağın humusu, Olmadan çıkar u...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/c08-ta-kendisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmini', 'i-smini-halil-colak-abcmn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ahdettim ben kendi kendime

Asla hatırlamayacağım ismini

Söyle sende, bana gül sende

Yemin ettim anmayacağım ismini

Gül gibi dalım dada solsam da

Aşkından yanıp tutuşsam da

 Aşkımdan da öl sende vefasızım

Yemin ettim anmayacağım ismini

Tatlı gülüşlerin,gözlerimin önünde

Bir hayal gibi hayatımda kal sanda

Kalbim kırık,yüreğim parça, parça

Yemin ettim anmayacağım ismini.

Halil Çolak 20.6.2005', 'Ahdettim ben kendi kendime Asla hatırlamayacağım ismini Söyle sende, bana gül sende Yemin ettim anmayacağım ismini Gül gibi dalım dada solsa...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ismini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Latifeyi deva', 'latifeyi-deva-ali-riza-unal-2scql', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne sırdırki, bir damla suda, hikmeti İlâhi.

Gâh firavun halk edersin gâh halifeyi.

   Not: eserin tamamı değildir', 'Ne sırdırki, bir damla suda, hikmeti İlâhi. Gâh firavun halk edersin gâh halifeyi.    Not: eserin tamamı değildir...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/latifeyi-deva-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştü', 'dustu-halil-colak-ksgz0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düştü

Aşkımın baharında

Bir fırtınalı kış günü.

Dondurduk çilesini

Bizde aşkımızın

Yeşil dağlara

Zamansız kârlar yağmış gibi

Mutluluk kapısını

Fırtına kapattı ansızın.

Dağıttı tarumar etti

Gönlümün gül bahçesini

Bir çırpıda kader.

Kimine güller düştü

Bana da zehirli dikenler

Düştü

Mutluluklar sunarken

Sevenler sevdiğine

Benim bu öksüz gönlüme

Acı ve ızdıraplar düştü.

Halil Çolak haziran 1980

Erzurum', 'Düştü Aşkımın baharında Bir fırtınalı kış günü. Dondurduk çilesini Bizde aşkımızın Yeşil dağlara Zamansız kârlar yağmış gibi Mutluluk kapısı...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dustu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimez Beyitler 18', 'eskimez-beyitler-18-huseyin-avdic-aticx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Otomobil oldu at, at otomobil.

İstiyorum tezek dökmeyen at/om-obil.

******

Göz, görür mü ki gözünü.

Görsün, gözünün gözünü? 

******

Doktor ve öğretmenim oruç.

Süper sıhhat-eğitim sonuç.

******

Yumurtayı herkes kırar, çok kolay.

İçerden kırar civciv, yapar olay! 

******

Avrupa ikidir: Biri kitaplı, öteki kitapsız.

Hesapsızlıktan hoşlanır nedense bizim aydınımız...

******

''Yarım doktar candan, yarım hoca imandan''

Yarım aydın eder, insanı insanlıktan...

Batı Berlin, 1980-85.', 'Otomobil oldu at, at otomobil. İstiyorum tezek dökmeyen at/om-obil. ****** Göz, görür mü ki gözünü. Görsün, gözünün gözünü?  ****** Doktor v...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eskimez-beyitler-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Nedir?', 'siir-nedir-selman-cesur-vx5u7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir nedir? bilirmisin! ! 

şiir yaşamaktır hiç düşünmeden

şiir sanattır yıpranmadan

şiir kancadır kalbine takmadan

şiir aşktır duygu deliliğidir

şiir nefretide anlatır mutluluğuda

şiir kalp ilacıdır umutsuz olunca çekers içersin

şiir su gibidir saftır temizdir yalanı barındırmaz

şiir şehir gibidir bazen dumanlı bacalarda

şiir yaşam biçimidir ne sensizdir ne de sessiz

şiir nehirdir akar durur sonunu bilmeden

şiir beyin travmasıdır anlamsızları anlar anlatır

şiir duygusuz yürekte acı çeker

şiir yol gibidir bir yerde aynı yere yine gider

şiir ölüm gibidir bir yerde doğar bir yerde biter', 'Şiir nedir? bilirmisin! !  şiir yaşamaktır hiç düşünmeden şiir sanattır yıpranmadan şiir kancadır kalbine takmadan şiir aşktır duygu deliliğ...', ARRAY['Türk Edebiyatı','Şiir','Selman Cesur']::text[], 8.5, '{"poet":"Selman Cesur","poet_slug":"selman-cesur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siir-nedir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın Anatomisi', 'ayriligin-anatomisi-selman-cesur-fir5a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'umudun içinde yaşayıp giden anıların altında ezik büzük bir mor menekşe 

sevginin bulutunda yaşanılıpta gidilen yolun en ağır damgasıdır ayrılık

tek çare var sevgide bulunup kolayların içinde zoru yaşamak muhtaçlığın 

neresindedir bilinmez bu sevginin anatomisinde olan ayrılığın hançerini.', 'umudun içinde yaşayıp giden anıların altında ezik büzük bir mor menekşe  sevginin bulutunda yaşanılıpta gidilen yolun en ağır damgasıdır ayr...', ARRAY['Türk Edebiyatı','Şiir','Selman Cesur']::text[], 8.5, '{"poet":"Selman Cesur","poet_slug":"selman-cesur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayriligin-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-selman-cesur-c0n76', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'biraz ihtiras,

biraz acı,

sevgimin gönül ilacı

başımın tacı

ömrümün tek meyve veren ağacı

kurumadan ıslattın tüm bedenimi

seninle yükseldi aşk tirajı', 'biraz ihtiras, biraz acı, sevgimin gönül ilacı başımın tacı ömrümün tek meyve veren ağacı kurumadan ıslattın tüm bedenimi seninle yükseldi a...', ARRAY['Türk Edebiyatı','Şiir','Selman Cesur']::text[], 8.5, '{"poet":"Selman Cesur","poet_slug":"selman-cesur","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/agac-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafam Dumanlı', 'kafam-dumanli-selman-cesur-kojv2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaktım bir sigara dumanına kanmışım

kana kana doya doya çekiyorum

içim içimden çıkacakmış gibi üflüyorum

galiba hayatın son demlerini yaşıyorum

sonumu bilmeden yüreğimi hasata sürüyorum

bazen korkmuyor değilim

bazende ölümle dalga geçiyorum

bir pazar sabahında ismini anıyorum

soruyorum soruşturuyorum

nerededir kiminledir hiç bilmiyorum

ellerim titriyor sigarayı atıyorum

uzaktan hayal meyal seni görüyorum

en sonunda kavuşuyoruz 

artık ölsemde gam yemem

sönsün tüm sigaralar ben senin için

tekrar yaşamak istiyorum.', 'yaktım bir sigara dumanına kanmışım kana kana doya doya çekiyorum içim içimden çıkacakmış gibi üflüyorum galiba hayatın son demlerini yaşıyo...', ARRAY['Türk Edebiyatı','Şiir','Selman Cesur']::text[], 8.5, '{"poet":"Selman Cesur","poet_slug":"selman-cesur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kafam-dumanli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sunam-"siz hiç ay aşığında ağladınız mı" Kitabından', 'sunam-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-e6eee', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülistanda seni gördüm 

Hayellerim bezer sunam 

Turnalardan haber sordum 

Ceylan gibi gezer sunam 

Soğanlı''dan haber saldı 

Sinemi kor ateş aldı 

Sunam benden ayrı kaldı 

Sessiz mektup yazar sunam 

Ben gurbette sunam orda 

Kavuşmamız sanki zorda 

Az ötede vallah darda 

Sensiz yaşam üzer sunam 

Yok, olasın kara sevda 

Ben ellerde sunam evde 

Rüya gibi kuşat sev de

Bala şerbet ezer sunam 

Sunam oldu nurlu ana 

Üç kuzucuk verdi bana 

Şükür ettim Yaratana 

Dua ile bezer sunam

Derken canım Sultan yazar 

Ruhu yüreğimde gezer

Ya kavuşmak ya da mezar 

Belki ağıt dizer sunam', 'Gülistanda seni gördüm  Hayellerim bezer sunam  Turnalardan haber sordum  Ceylan gibi gezer sunam  Soğanlı''dan haber saldı  Sinemi kor ateş ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sunam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
